210a514b-2348-40e4-8f73-b718ca586423	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\n// 国旗计划\n// 给定点的数量m，点的编号1~m，所有点围成一个环\n// i号点一定顺时针到达i+1号点，最终m号点顺指针回到1号点\n// 给定n条线段，每条线段(a, b)，表示线段从点a顺时针到点b\n// 输入数据保证所有线段可以把整个环覆盖\n// 输入数据保证每条线段不会完全在另一条线段的内部\n// 也就是线段之间可能有重合但一定互不包含\n// 返回一个长度为n的结果数组ans，ans[x]表示一定选x号线段的情况下\n// 至少选几条线段能覆盖整个环\n// 测试链接 : https://www.luogu.com.cn/problem/P4155\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_FlagPlan {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int LIMIT = 18;\n\n\tpublic static int power;\n\n\t// 每条线段3个信息 : 线段编号、线段左边界、线段右边界\n\tpublic static int[][] line = new int[MAXN << 1][3];\n\n\t// stjump[i][p] : 从i号线段出发，跳的次数是2的p次方，能到达的最右线段的编号\n\tpublic static int[][] stjump = new int[MAXN << 1][LIMIT];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tline[i][0] = i;\n\t\t\tin.nextToken();\n\t\t\tline[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tline[i][2] = (int) in.nval;\n\t\t}\n\t\tcompute();\n\t\tout.print(ans[1]);\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tout.print(" " + ans[i]);\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static void compute() {\n\t\tpower = log2(n);\n\t\tbuild();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans[line[i][0]] = jump(i);\n\t\t}\n\t}\n\n\t// <=n最接近的2的幂，是2的几次方\n\tpublic static int log2(int n) {\n\t\tint ans = 0;\n\t\twhile ((1 << ans) <= (n >> 1)) {\n\t\t\tans++;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void build() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (line[i][1] > line[i][2]) {\n\t\t\t\tline[i][2] += m;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(line, 1, n + 1, (a, b) -> a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tline[i + n][0] = line[i][0];\n\t\t\tline[i + n][1] = line[i][1] + m;\n\t\t\tline[i + n][2] = line[i][2] + m;\n\t\t}\n\t\tint e = n << 1;\n\t\tfor (int i = 1, arrive = 1; i <= e; i++) {\n\t\t\twhile (arrive + 1 <= e && line[arrive + 1][1] <= line[i][2]) {\n\t\t\t\tarrive++;\n\t\t\t}\n\t\t\tstjump[i][0] = arrive;\n\t\t}\n\t\tfor (int p = 1; p <= power; p++) {\n\t\t\tfor (int i = 1; i <= e; i++) {\n\t\t\t\tstjump[i][p] = stjump[stjump[i][p - 1]][p - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int jump(int i) {\n\t\tint aim = line[i][1] + m, cur = i, next, ans = 0;\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tnext = stjump[cur][p];\n\t\t\tif (next != 0 && line[next][2] < aim) {\n\t\t\t\tans += 1 << p;\n\t\t\t\tcur = next;\n\t\t\t}\n\t\t}\n\t\treturn ans + 1 + 1;\n\t}\n\n}\n	模板：Code01_FlagPlan.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c3009d64-4e46-42b9-9312-597c747debe6	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\n// ST表查询最大值和最小值\n// 给定一个长度为n的数组arr，一共有m次查询\n// 每次查询arr[l~r]上的最大值和最小值\n// 每次查询只需要打印最大值-最小值的结果\n// 测试链接 : https://www.luogu.com.cn/problem/P2880\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_SparseTableMaximumMinimum {\n\n\tpublic static int MAXN = 50001;\n\n\t// 2的15次方是<=50001且最接近的\n\t// 所以次方可能是0~15\n\t// 于是准备16长度够用了\n\tpublic static int LIMIT = 16;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// log2[i] : 查询<=i情况下，最大的2的幂，是2的几次方\n\tpublic static int[] log2 = new int[MAXN];\n\n\tpublic static int[][] stmax = new int[MAXN][LIMIT];\n\n\tpublic static int[][] stmin = new int[MAXN][LIMIT];\n\n\tpublic static void build(int n) {\n\t\tlog2[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlog2[i] = log2[i >> 1] + 1;\n\t\t\tstmax[i][0] = arr[i];\n\t\t\tstmin[i][0] = arr[i];\n\t\t}\n\t\tfor (int p = 1; p <= log2[n]; p++) {\n\t\t\tfor (int i = 1; i + (1 << p) - 1 <= n; i++) {\n\t\t\t\tstmax[i][p] = Math.max(stmax[i][p - 1], stmax[i + (1 << (p - 1))][p - 1]);\n\t\t\t\tstmin[i][p] = Math.min(stmin[i][p - 1], stmin[i + (1 << (p - 1))][p - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint p = log2[r - l + 1];\n\t\tint a = Math.max(stmax[l][p], stmax[r - (1 << p) + 1][p]);\n\t\tint b = Math.min(stmin[l][p], stmin[r - (1 << p) + 1][p]);\n\t\treturn a - b;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tbuild(n);\n\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tr = (int) in.nval;\n\t\t\tout.println(query(l, r));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_SparseTableMaximumMinimum.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
edccd56e-56e3-4baf-bed0-00e758aff8ed	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\n// ST表查询最大公约数\n// 给定一个长度为n的数组arr，一共有m次查询\n// 每次查询arr[l~r]上所有数的最大公约数\n// 测试链接 : https://www.luogu.com.cn/problem/P1890\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_SparseTableGCD {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int LIMIT = 10;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] log2 = new int[MAXN];\n\n\tpublic static int[][] stgcd = new int[MAXN][LIMIT];\n\n\tpublic static void build(int n) {\n\t\tlog2[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlog2[i] = log2[i >> 1] + 1;\n\t\t\tstgcd[i][0] = arr[i];\n\t\t}\n\t\tfor (int p = 1; p <= log2[n]; p++) {\n\t\t\tfor (int i = 1; i + (1 << p) - 1 <= n; i++) {\n\t\t\t\tstgcd[i][p] = gcd(stgcd[i][p - 1], stgcd[i + (1 << (p - 1))][p - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 算法讲解041 - 辗转相除法求最大公约数\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint p = log2[r - l + 1];\n\t\treturn gcd(stgcd[l][p], stgcd[r - (1 << p) + 1][p]);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tbuild(n);\n\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tr = (int) in.nval;\n\t\t\tout.println(query(l, r));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_SparseTableGCD.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c9a6cf52-8653-47b3-82b0-d5c6f5b4601a	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\n// 出现次数最多的数有几个\n// 给定一个长度为n的数组arr，该数组一定是有序的\n// 一共有m次查询，每次查询arr[l~r]上出现次数最多的数有几个\n// 对数器验证\n\nimport java.util.Arrays;\nimport java.util.HashMap;\n\npublic class Code04_FrequentValues1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int LIMIT = 17;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] log2 = new int[MAXN];\n\n\tpublic static int[] bucket = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[][] stmax = new int[MAXN][LIMIT];\n\n\tpublic static void build(int n) {\n\t\t// 题目给定的数值范围-100000 ~ +100000\n\t\t// 把arr[0]设置成不会到达的数字即可\n\t\tarr[0] = -23333333;\n\t\tint cnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (arr[i - 1] != arr[i]) {\n\t\t\t\tright[cnt] = i - 1;\n\t\t\t\tleft[++cnt] = i;\n\t\t\t}\n\t\t\tbucket[i] = cnt;\n\t\t}\n\t\tright[cnt] = n;\n\t\tlog2[0] = -1;\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tlog2[i] = log2[i >> 1] + 1;\n\t\t\tstmax[i][0] = right[i] - left[i] + 1;\n\t\t}\n\t\tfor (int p = 1; p <= log2[cnt]; p++) {\n\t\t\tfor (int i = 1; i + (1 << p) - 1 <= cnt; i++) {\n\t\t\t\tstmax[i][p] = Math.max(stmax[i][p - 1], stmax[i + (1 << (p - 1))][p - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tif (l > r) {\n\t\t\tint tmp = l;\n\t\t\tl = r;\n\t\t\tr = tmp;\n\t\t}\n\t\tint lbucket = bucket[l];\n\t\tint rbucket = bucket[r];\n\t\tif (lbucket == rbucket) {\n\t\t\treturn r - l + 1;\n\t\t}\n\t\t// a : 最左侧桶在此时l~r范围上的数字有几个\n\t\t// b : 最右侧桶在此时l~r范围上的数字有几个\n\t\tint a = right[lbucket] - l + 1, b = r - left[rbucket] + 1, c = 0;\n\t\tif (lbucket + 1 < rbucket) {\n\t\t\tint from = lbucket + 1, to = rbucket - 1, p = log2[to - from + 1];\n\t\t\tc = Math.max(stmax[from][p], stmax[to - (1 << p) + 1][p]);\n\t\t}\n\t\treturn Math.max(Math.max(a, b), c);\n\t}\n\n\t// 对数器\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("测试开始");\n\t\tint n = 10000;\n\t\tint v = 100;\n\t\tint m = 5000;\n\t\trandomArray(n, v);\n\t\tbuild(n);\n\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\tl = (int) (Math.random() * n) + 1;\n\t\t\tr = (int) (Math.random() * n) + 1;\n\t\t\tif (query(l, r) != checkQuery(l, r)) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 得到随机数组\n\t// 为了验证\n\tpublic static void randomArray(int n, int v) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = (int) (Math.random() * 2 * v) - v;\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1);\n\t}\n\n\t// 暴力方法\n\t// 直接遍历统计词频\n\t// 为了验证\n\tpublic static int checkQuery(int l, int r) {\n\t\tif (l > r) {\n\t\t\tint tmp = l;\n\t\t\tl = r;\n\t\t\tr = tmp;\n\t\t}\n\t\tHashMap<Integer, Integer> map = new HashMap<>();\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tmap.put(arr[i], map.getOrDefault(arr[i], 0) + 1);\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int v : map.values()) {\n\t\t\tans = Math.max(ans, v);\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_FrequentValues1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
db42f26e-8159-44db-82d9-6dd448c0e841	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\n// 出现次数最多的数有几个\n// 给定一个长度为n的数组arr，该数组一定是有序的\n// 一共有m次查询，每次查询arr[l~r]上出现次数最多的数有几个\n// 题目查看 : https://www.luogu.com.cn/problem/UVA11235\n// 题目提交 : https://vjudge.net/problem/UVA-11235\n// 洛谷上提交会发生远程连接错误，需要绑定一个UVA账号再提交\n// 也可以注册一个vjudge账号来提交，不过如果UVA链接不上就需要等\n// 其实用对数器验证即可，我肯定是提交通过测试了的\n// 提交以下的code，提交时请把类名改成"Main"\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_FrequentValues2 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int LIMIT = 17;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] log2 = new int[MAXN];\n\n\tpublic static int[] bucket = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[][] stmax = new int[MAXN][LIMIT];\n\n\tpublic static void build(int n) {\n\t\t// 题目给定的数值范围-100000 ~ +100000\n\t\t// 把arr[0]设置成不会到达的数字即可\n\t\tarr[0] = -23333333;\n\t\tint cnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (arr[i - 1] != arr[i]) {\n\t\t\t\tright[cnt] = i - 1;\n\t\t\t\tleft[++cnt] = i;\n\t\t\t}\n\t\t\tbucket[i] = cnt;\n\t\t}\n\t\tright[cnt] = n;\n\t\tlog2[0] = -1;\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tlog2[i] = log2[i >> 1] + 1;\n\t\t\tstmax[i][0] = right[i] - left[i] + 1;\n\t\t}\n\t\tfor (int p = 1; p <= log2[cnt]; p++) {\n\t\t\tfor (int i = 1; i + (1 << p) - 1 <= cnt; i++) {\n\t\t\t\tstmax[i][p] = Math.max(stmax[i][p - 1], stmax[i + (1 << (p - 1))][p - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tif (l > r) {\n\t\t\tint tmp = l;\n\t\t\tl = r;\n\t\t\tr = tmp;\n\t\t}\n\t\tint lbucket = bucket[l];\n\t\tint rbucket = bucket[r];\n\t\tif (lbucket == rbucket) {\n\t\t\treturn r - l + 1;\n\t\t}\n\t\tint a = right[lbucket] - l + 1, b = r - left[rbucket] + 1, c = 0;\n\t\tif (lbucket + 1 < rbucket) {\n\t\t\tint from = lbucket + 1, to = rbucket - 1, p = log2[to - from + 1];\n\t\t\tc = Math.max(stmax[from][p], stmax[to - (1 << p) + 1][p]);\n\t\t}\n\t\treturn Math.max(Math.max(a, b), c);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tint n = (int) in.nval;\n\t\t\tif (n == 0) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tin.nextToken();\n\t\t\tint m = (int) in.nval;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i] = (int) in.nval;\n\t\t\t}\n\t\t\tbuild(n);\n\t\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tr = (int) in.nval;\n\t\t\t\tout.println(query(l, r));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_FrequentValues2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8a83cf85-364d-42ef-ad9c-ff9748e6eb5e	bc87b76e-fe80-4524-b258-5d608ebab8d4	java	package class117;\n\npublic class TwoSmallQuestions {\n\n\t// 给定一个正数x\n\t// 已知用m个二进制位一定能表示x\n\t// 从高位到低位打印x每一位的状态\n\tpublic static void show1(int x, int m) {\n\t\tfor (int p = m - 1, t = x; p >= 0; p--) {\n\t\t\tif (1 << p <= t) {\n\t\t\t\tt -= 1 << p;\n\t\t\t\tSystem.out.println(x + "的第" + p + "位是1");\n\t\t\t} else {\n\t\t\t\tSystem.out.println(x + "的第" + p + "位是0");\n\t\t\t}\n\t\t}\n\t}\n\n\t// 给定一个正数x\n\t// 打印<=x最大的2的幂\n\t// 到底是2的几次方\n\tpublic static void show2(int x) {\n\t\tint power = 0;\n\t\t// 以下注释掉的写法不对，没有考虑溢出\n//\t\twhile ((1 << power) <= x) {\n//\t\t\tpower++;\n//\t\t}\n//\t\tpower--;\n\t\t// 防止溢出的写法\n\t\twhile ((1 << power) <= (x >> 1)) {\n\t\t\tpower++;\n\t\t}\n\t\tSystem.out.println("<=" + x + "最大的2的幂，是2的" + power + "次方");\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 需要保证用m个二进制位一定能表示x\n\t\tint x = 101;\n\t\tint m = 10;\n\t\tshow1(x, m);\n\n\t\tx = 13;\n\t\tshow2(x);\n\t\tx = 16;\n\t\tshow2(x);\n\t\tx = 2000000000;\n\t\tshow2(x);\n\t}\n\n}\n	模板：TwoSmallQuestions.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
