6146ec27-37bf-448e-bff5-d5ab4096b8f3	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class168;\n\n// 矩阵内第k小，第一种写法，java版\n// 给定一个n * n的矩阵，接下来有q条查询，格式如下\n// 查询 a b c d k : 左上角(a, b)，右下角(c, d)，打印该区域中第k小的数\n// 1 <= n <= 500\n// 1 <= q <= 6 * 10^4\n// 0 <= 矩阵中的数字 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1527\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_MatrixKth1 {\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXQ = 1000001;\n\tpublic static int n, q;\n\n\t// 矩阵中的每个数字，所在行x、所在列y、数值v\n\tpublic static int[][] xyv = new int[MAXN * MAXN][3];\n\t// 矩阵中一共有多少个数字，cntv就是矩阵的规模\n\tpublic static int cntv = 0;\n\n\t// 查询任务的编号\n\tpublic static int[] qid = new int[MAXQ];\n\t// 查询范围的左上角坐标\n\tpublic static int[] a = new int[MAXQ];\n\tpublic static int[] b = new int[MAXQ];\n\t// 查询范围的右下角坐标\n\tpublic static int[] c = new int[MAXQ];\n\tpublic static int[] d = new int[MAXQ];\n\t// 查询矩阵内第k小\n\tpublic static int[] k = new int[MAXQ];\n\n\t// 二维树状数组\n\tpublic static int[][] tree = new int[MAXN][MAXN];\n\n\t// 整体二分\n\tpublic static int[] lset = new int[MAXQ];\n\tpublic static int[] rset = new int[MAXQ];\n\n\t// 每条查询的答案\n\tpublic static int[] ans = new int[MAXQ];\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\t// 二维空间中，(x,y)位置的词频加v\n\tpublic static void add(int x, int y, int v) {\n\t\tfor (int i = x; i <= n; i += lowbit(i)) {\n\t\t\tfor (int j = y; j <= n; j += lowbit(j)) {\n\t\t\t\ttree[i][j] += v;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 二维空间中，左上角(1,1)到右下角(x,y)范围上的词频累加和\n\tpublic static int sum(int x, int y) {\n\t\tint ret = 0;\n\t\tfor (int i = x; i > 0; i -= lowbit(i)) {\n\t\t\tfor (int j = y; j > 0; j -= lowbit(j)) {\n\t\t\t\tret += tree[i][j];\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\t// 二维空间中，左上角(a,b)到右下角(c,d)范围上的词频累加和\n\tpublic static int query(int a, int b, int c, int d) {\n\t\treturn sum(c, d) - sum(a - 1, d) - sum(c, b - 1) + sum(a - 1, b - 1);\n\t}\n\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tans[qid[i]] = xyv[vl][2];\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tfor (int i = vl; i <= mid; i++) {\n\t\t\t\tadd(xyv[i][0], xyv[i][1], 1);\n\t\t\t}\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tint id = qid[i];\n\t\t\t\tint satisfy = query(a[id], b[id], c[id], d[id]);\n\t\t\t\tif (satisfy >= k[id]) {\n\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t} else {\n\t\t\t\t\tk[id] -= satisfy;\n\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tqid[ql + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tqid[ql + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tfor (int i = vl; i <= mid; i++) {\n\t\t\t\tadd(xyv[i][0], xyv[i][1], -1);\n\t\t\t}\n\t\t\tcompute(ql, ql + lsiz - 1, vl, mid);\n\t\t\tcompute(ql + lsiz, qr, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\txyv[++cntv][0] = i;\n\t\t\t\txyv[cntv][1] = j;\n\t\t\t\txyv[cntv][2] = in.nextInt();\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tqid[i] = i;\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\tc[i] = in.nextInt();\n\t\t\td[i] = in.nextInt();\n\t\t\tk[i] = in.nextInt();\n\t\t}\n\t\tArrays.sort(xyv, 1, cntv + 1, (a, b) -> a[2] - b[2]);\n\t\tcompute(1, q, 1, cntv);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_MatrixKth1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
81c2012a-9ec6-45c6-9b5b-8b1defd2e3e4	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class168;\n\n// 矩阵内第k小，第二种写法，java版\n// 给定一个n * n的矩阵，接下来有q条查询，格式如下\n// 查询 a b c d k : 左上角(a, b)，右下角(c, d)，打印该区域中第k小的数\n// 1 <= n <= 500\n// 1 <= q <= 6 * 10^4\n// 0 <= 矩阵中的数字 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1527\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_MatrixKth2 {\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXQ = 1000001;\n\tpublic static int n, q;\n\n\tpublic static int[][] xyv = new int[MAXN * MAXN][3];\n\tpublic static int cntv = 0;\n\n\tpublic static int[] qid = new int[MAXQ];\n\tpublic static int[] a = new int[MAXQ];\n\tpublic static int[] b = new int[MAXQ];\n\tpublic static int[] c = new int[MAXQ];\n\tpublic static int[] d = new int[MAXQ];\n\tpublic static int[] k = new int[MAXQ];\n\n\tpublic static int[][] tree = new int[MAXN][MAXN];\n\t// 数据的使用数量\n\tpublic static int used = 0;\n\n\tpublic static int[] lset = new int[MAXQ];\n\tpublic static int[] rset = new int[MAXQ];\n\n\tpublic static int[] ans = new int[MAXQ];\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int x, int y, int v) {\n\t\tfor (int i = x; i <= n; i += lowbit(i)) {\n\t\t\tfor (int j = y; j <= n; j += lowbit(j)) {\n\t\t\t\ttree[i][j] += v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int sum(int x, int y) {\n\t\tint ret = 0;\n\t\tfor (int i = x; i > 0; i -= lowbit(i)) {\n\t\t\tfor (int j = y; j > 0; j -= lowbit(j)) {\n\t\t\t\tret += tree[i][j];\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static int query(int a, int b, int c, int d) {\n\t\treturn sum(c, d) - sum(a - 1, d) - sum(c, b - 1) + sum(a - 1, b - 1);\n\t}\n\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tans[qid[i]] = xyv[vl][2];\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\twhile (used < mid) {\n\t\t\t\tused++;\n\t\t\t\tadd(xyv[used][0], xyv[used][1], 1);\n\t\t\t}\n\t\t\twhile (used > mid) {\n\t\t\t\tadd(xyv[used][0], xyv[used][1], -1);\n\t\t\t\tused--;\n\t\t\t}\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tint id = qid[i];\n\t\t\t\tint satisfy = query(a[id], b[id], c[id], d[id]);\n\t\t\t\tif (satisfy >= k[id]) {\n\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t} else {\n\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tqid[ql + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tqid[ql + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tcompute(ql, ql + lsiz - 1, vl, mid);\n\t\t\tcompute(ql + lsiz, qr, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\txyv[++cntv][0] = i;\n\t\t\t\txyv[cntv][1] = j;\n\t\t\t\txyv[cntv][2] = in.nextInt();\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tqid[i] = i;\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\tc[i] = in.nextInt();\n\t\t\td[i] = in.nextInt();\n\t\t\tk[i] = in.nextInt();\n\t\t}\n\t\tArrays.sort(xyv, 1, cntv + 1, (a, b) -> a[2] - b[2]);\n\t\tcompute(1, q, 1, cntv);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_MatrixKth2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
890312a3-91cb-4675-98b4-29af8749428f	b760a5f2-9131-489d-8973-39a768258ab0	java	package class036;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.LinkedList;\nimport java.util.List;\nimport java.util.Queue;\n\n// 二叉树的层序遍历\n// 测试链接 : https://leetcode.cn/problems/binary-tree-level-order-traversal/\npublic class Code01_LevelOrderTraversal {\n\n\t// 不提交这个类\n\tpublic static class TreeNode {\n\t\tpublic int val;\n\t\tpublic TreeNode left;\n\t\tpublic TreeNode right;\n\t}\n\n\t// 提交时把方法名改为levelOrder，此方法为普通bfs，此题不推荐\n\tpublic static List<List<Integer>> levelOrder1(TreeNode root) {\n\t\tList<List<Integer>> ans = new ArrayList<>();\n\t\tif (root != null) {\n\t\t\tQueue<TreeNode> queue = new LinkedList<>();\n\t\t\tHashMap<TreeNode, Integer> levels = new HashMap<>();\n\t\t\tqueue.add(root);\n\t\t\tlevels.put(root, 0);\n\t\t\twhile (!queue.isEmpty()) {\n\t\t\t\tTreeNode cur = queue.poll();\n\t\t\t\tint level = levels.get(cur);\n\t\t\t\tif (ans.size() == level) {\n\t\t\t\t\tans.add(new ArrayList<>());\n\t\t\t\t}\n\t\t\t\tans.get(level).add(cur.val);\n\t\t\t\tif (cur.left != null) {\n\t\t\t\t\tqueue.add(cur.left);\n\t\t\t\t\tlevels.put(cur.left, level + 1);\n\t\t\t\t}\n\t\t\t\tif (cur.right != null) {\n\t\t\t\t\tqueue.add(cur.right);\n\t\t\t\t\tlevels.put(cur.right, level + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 如果测试数据量变大了就修改这个值\n\tpublic static int MAXN = 2001;\n\n\tpublic static TreeNode[] queue = new TreeNode[MAXN];\n\n\tpublic static int l, r;\n\n\t// 提交时把方法名改为levelOrder，此方法为每次处理一层的优化bfs，此题推荐\n\tpublic static List<List<Integer>> levelOrder2(TreeNode root) {\n\t\tList<List<Integer>> ans = new ArrayList<>();\n\t\tif (root != null) {\n\t\t\tl = r = 0;\n\t\t\tqueue[r++] = root;\n\t\t\twhile (l < r) { // 队列里还有东西\n\t\t\t\tint size = r - l;\n\t\t\t\tArrayList<Integer> list = new ArrayList<Integer>();\n\t\t\t\tfor (int i = 0; i < size; i++) {\n\t\t\t\t\tTreeNode cur = queue[l++];\n\t\t\t\t\tlist.add(cur.val);\n\t\t\t\t\tif (cur.left != null) {\n\t\t\t\t\t\tqueue[r++] = cur.left;\n\t\t\t\t\t}\n\t\t\t\t\tif (cur.right != null) {\n\t\t\t\t\t\tqueue[r++] = cur.right;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans.add(list);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_LevelOrderTraversal.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
