23789e67-a1f7-45b8-8a30-6cf59dfc25bd	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class169;\n\n// 带修改的区间第k小，java版\n// 给定一个长度为n的数组arr，接下来是m条操作，每种操作是如下两种类型的一种\n// 操作 C x y   : 把x位置的值修改成y\n// 操作 Q x y v : 查询arr[x..y]范围上第v小的值\n// 1 <= n、m <= 10^5\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2617\n// 本题是讲解160，树套树模版题，现在作为带修改的整体二分模版题\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_DynamicRankings1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXE = MAXN << 2;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 事件编号组成的数组\n\tpublic static int[] eid = new int[MAXE];\n\t// op == 1，代表修改事件，x处，值y，效果v\n\t// op == 2，代表查询事件，[x..y]范围上查询第v小，q表示问题的编号\n\tpublic static int[] op = new int[MAXE];\n\tpublic static int[] x = new int[MAXE];\n\tpublic static int[] y = new int[MAXE];\n\tpublic static int[] v = new int[MAXE];\n\tpublic static int[] q = new int[MAXE];\n\tpublic static int cnte = 0;\n\tpublic static int cntq = 0;\n\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXN];\n\n\t// 整体二分\n\tpublic static int[] lset = new int[MAXE];\n\tpublic static int[] rset = new int[MAXE];\n\n\t// 查询的答案\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int sum(int i) {\n\t\tint ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\treturn sum(r) - sum(l - 1);\n\t}\n\n\tpublic static void compute(int el, int er, int vl, int vr) {\n\t\tif (el > er) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (op[id] == 2) {\n\t\t\t\t\tans[q[id]] = vl;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (op[id] == 1) {\n\t\t\t\t\tif (y[id] <= mid) {\n\t\t\t\t\t\tadd(x[id], v[id]);\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tint satisfy = query(x[id], y[id]);\n\t\t\t\t\tif (v[id] <= satisfy) {\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tv[id] -= satisfy;\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\teid[el + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\teid[el + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tint id = lset[i];\n\t\t\t\tif (op[id] == 1 && y[id] <= mid) {\n\t\t\t\t\tadd(x[id], -v[id]);\n\t\t\t\t}\n\t\t\t}\n\t\t\tcompute(el, el + lsiz - 1, vl, mid);\n\t\t\tcompute(el + lsiz, er, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t\top[++cnte] = 1;\n\t\t\tx[cnte] = i;\n\t\t\ty[cnte] = arr[i];\n\t\t\tv[cnte] = 1;\n\t\t}\n\t\tchar type;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ttype = in.nextChar();\n\t\t\tif (type == 'C') {\n\t\t\t\tint a = in.nextInt();\n\t\t\t\tint b = in.nextInt();\n\t\t\t\top[++cnte] = 1;\n\t\t\t\tx[cnte] = a;\n\t\t\t\ty[cnte] = arr[a];\n\t\t\t\tv[cnte] = -1;\n\t\t\t\top[++cnte] = 1;\n\t\t\t\tx[cnte] = a;\n\t\t\t\ty[cnte] = b;\n\t\t\t\tv[cnte] = 1;\n\t\t\t\tarr[a] = b;\n\t\t\t} else {\n\t\t\t\top[++cnte] = 2;\n\t\t\t\tx[cnte] = in.nextInt();\n\t\t\t\ty[cnte] = in.nextInt();\n\t\t\t\tv[cnte] = in.nextInt();\n\t\t\t\tq[cnte] = ++cntq;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\teid[i] = i;\n\t\t}\n\t\tcompute(1, cnte, 0, INF);\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code02_DynamicRankings1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
