7678cc3e-c21e-4b30-8091-04d8bb65f041	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class169;\n\n// 网络，java版\n// 一共有n个服务器，给定n-1条边，所有服务器连成一棵树\n// 某两个服务器之间的路径上，可能接受一条请求，路径上的所有服务器都需要保存该请求的重要度\n// 一共有m条操作，每条操作是如下3种类型中的一种，操作依次发生，第i条操作发生的时间为i\n// 操作 0 x y v : x号服务器到y号服务器的路径上，增加了一个重要度为v的请求\n// 操作 1 t     : 当初时间为t的操作，一定是增加请求的操作，现在这个请求结束了\n// 操作 2 x     : 当前时间下，和x号服务器无关的所有请求中，打印最大的重要度\n// 关于操作2，如果当前时间下，没有任何请求、或者所有请求都和x号服务器有关，打印-1\n// 2 <= n <= 10^5    1 <= m <= 2 * 10^5    1 <= 重要度 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3250\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Network1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXP = 20;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\t// 树上点差分 + 树上倍增\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXN];\n\n\t// 事件编号组成的数组\n\tpublic static int[] eid = new int[MAXM];\n\t// 如果op == 0，添加点x到点y，重要度为v的路径\n\t// 如果op == 1，删除点x到点y，重要度为v的路径\n\t// 如果op == 2，查询和x相关的答案，y表示问题的编号\n\tpublic static int[] op = new int[MAXM];\n\tpublic static int[] x = new int[MAXM];\n\tpublic static int[] y = new int[MAXM];\n\tpublic static int[] v = new int[MAXM];\n\tpublic static int cntq = 0;\n\n\t// 整体二分\n\tpublic static int[] lset = new int[MAXM];\n\tpublic static int[] rset = new int[MAXM];\n\n\tpublic static int[] ans = new int[MAXM];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tdfn[u] = ++cntd;\n\t\tstjump[u][0] = f;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs1(to[e], u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tsiz[u] += siz[to[e]];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\t\t\tif (to[e] != f) {\n\t\t\t\t\t\tsiz[u] += siz[to[e]];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int query(int i) {\n\t\tint ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\t// 点x到点y的路径上，每个点增加v个请求数量\n\tpublic static void pathAdd(int x, int y, int v) {\n\t\tint xylca = lca(x, y);\n\t\tint lcafa = fa[xylca];\n\t\tadd(dfn[x], v);\n\t\tadd(dfn[y], v);\n\t\tadd(dfn[xylca], -v);\n\t\tif (lcafa != 0) {\n\t\t\tadd(dfn[lcafa], -v);\n\t\t}\n\t}\n\n\t// 查询和x点相关的请求数量\n\tpublic static int pointQuery(int x) {\n\t\treturn query(dfn[x] + siz[x] - 1) - query(dfn[x] - 1);\n\t}\n\n\tpublic static void compute(int el, int er, int vl, int vr) {\n\t\tif (el > er) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (op[id] == 2) {\n\t\t\t\t\tans[y[id]] = vl;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) / 2;\n\t\t\tint lsiz = 0, rsiz = 0, request = 0;\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (op[id] == 0) {\n\t\t\t\t\tif (v[id] <= mid) {\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tpathAdd(x[id], y[id], 1);\n\t\t\t\t\t\trequest++;\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t} else if (op[id] == 1) {\n\t\t\t\t\tif (v[id] <= mid) {\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tpathAdd(x[id], y[id], -1);\n\t\t\t\t\t\trequest--;\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (pointQuery(x[id]) == request) {\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\teid[el + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\teid[el + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tint id = rset[i];\n\t\t\t\tif (op[id] == 0 && v[id] > mid) {\n\t\t\t\t\tpathAdd(x[id], y[id], -1);\n\t\t\t\t}\n\t\t\t\tif (op[id] == 1 && v[id] > mid) {\n\t\t\t\t\tpathAdd(x[id], y[id], 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\tcompute(el, el + lsiz - 1, vl, mid);\n\t\t\tcompute(el + lsiz, er, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (op[i] == 1) {\n\t\t\t\tint pre = x[i];\n\t\t\t\tx[i] = x[pre];\n\t\t\t\ty[i] = y[pre];\n\t\t\t\tv[i] = v[pre];\n\t\t\t}\n\t\t\tif (op[i] == 2) {\n\t\t\t\ty[i] = ++cntq;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\teid[i] = i;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top[i] = in.nextInt();\n\t\t\tx[i] = in.nextInt();\n\t\t\tif (op[i] == 0) {\n\t\t\t\ty[i] = in.nextInt();\n\t\t\t\tv[i] = in.nextInt();\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute(1, m, 0, INF);\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tif (ans[i] == 0) {\n\t\t\t\tout.println(-1);\n\t\t\t} else {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_Network1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
