d], -1);\n//                    request--;\n//                    rset[++rsiz] = id;\n//                }\n//            } else {\n//                if (pointQuery(x[id]) == request) {\n//                    lset[++lsiz] = id;\n//                } else {\n//                    rset[++rsiz] = id;\n//                }\n//            }\n//        }\n//        for (int i = 1; i <= lsiz; i++) {\n//            eid[el + i - 1] = lset[i];\n//        }\n//        for (int i = 1; i <= rsiz; i++) {\n//            eid[el + lsiz + i - 1] = rset[i];\n//        }\n//        for (int i = 1; i <= rsiz; i++) {\n//            int id = rset[i];\n//            if (op[id] == 0 && v[id] > mid) {\n//                pathAdd(x[id], y[id], -1);\n//            }\n//            if (op[id] == 1 && v[id] > mid) {\n//                pathAdd(x[id], y[id], 1);\n//            }\n//        }\n//        compute(el, el + lsiz - 1, vl, mid);\n//        compute(el + lsiz, er, mid + 1, vr);\n//    }\n//}\n//\n//void prepare() {\n//    dfs(1, 0);\n//    for (int i = 1; i <= m; i++) {\n//        if (op[i] == 1) {\n//            int pre = x[i];\n//            x[i] = x[pre];\n//            y[i] = y[pre];\n//            v[i] = v[pre];\n//        }\n//        if (op[i] == 2) {\n//            y[i] = ++cntq;\n//        }\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        eid[i] = i;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op[i] >> x[i];\n//        if (op[i] == 0) {\n//            cin >> y[i] >> v[i];\n//        }\n//    }\n//    prepare();\n//    compute(1, m, 0, INF);\n//    for (int i = 1; i <= cntq; i++) {\n//        if (ans[i] == 0) {\n//            cout << -1 << '\\n';\n//        } else {\n//            cout << ans[i] << '\\n';\n//        }\n//