1addbab0-a1ed-4ea0-8cad-c97da8a352b3	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class169;\n\n// 接水果，java版\n// 一共有n个点，给定n-1条无向边，所有点连成一棵树\n// 一共有p个盘子，每个盘子格式 a b c : 盘子是点a到点b的路径，盘子权值为c\n// 一共有q个水果，每个水果格式 u v k : 水果是点u到点v的路径，k含义如下\n// 如果一个盘子路径完全在一个水果路径的内部，那么该盘子可以接住该水果\n// 那么对于每个水果，可能有很多盘子都可以将其接住，打印其中第k小的权值\n// 1 <= n、p、q <= 4 * 10^4\n// 0 <= 盘子权值 <= 10^9\n// 内存可用空间500MB\n// 测试链接 : https://www.luogu.com.cn/problem/P3242\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code04_Fruit1 {\n\n\tpublic static int MAXN = 40001;\n\tpublic static int MAXP = 16;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, p, q;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\t// 树上倍增 + 每棵子树上的ldfn和rdfn\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] ldfn = new int[MAXN];\n\tpublic static int[] rdfn = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int cntd = 0;\n\n\t// 只有y维度的树状数组\n\tpublic static int[] tree = new int[MAXN];\n\n\t// 所有事件排完序之后，依次把下标放入eid数组\n\tpublic static int[] eid = new int[MAXN << 3];\n\t// 每个事件有8个属性值\n\t// op==1加盘子，x处加、yl、yr，盘子权值v、空缺、空缺、空缺\n\t// op==2删盘子，x处删、yl、yr，盘子权值v、空缺、空缺、空缺\n\t// op==3为水果，x、空缺、空缺、空缺、y、要求k、问题编号i\n\tpublic static int[][] event = new int[MAXN << 3][8];\n\t// 事件的总数\n\tpublic static int cnte = 0;\n\n\t// 整体二分\n\tpublic static int[] lset = new int[MAXN << 3];\n\tpublic static int[] rset = new int[MAXN << 3];\n\n\t// 每个水果的答案\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tldfn[u] = ++cntd;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u);\n\t\t\t}\n\t\t}\n\t\trdfn[u] = cntd;\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tldfn[u] = ++cntd;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\trdfn[u] = cntd;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\t// 已知a和b的最低公共祖先一定是a或b\n\t// 假设祖先为x，后代为y，返回x的哪个儿子的子树里有y\n\tpublic static int lcaSon(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] > dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\treturn a;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\t// 树状数组中[l..r]范围上的每个数增加v\n\tpublic static void add(int l, int r, int v) {\n\t\tadd(l, v);\n\t\tadd(r + 1, -v);\n\t}\n\n\t// 树状数组中查询单点的值\n\tpublic static int query(int i) {\n\t\tint ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void addPlate(int x, int yl, int yr, int v) {\n\t\tevent[++cnte][0] = 1;\n\t\tevent[cnte][1] = x;\n\t\tevent[cnte][2] = yl;\n\t\tevent[cnte][3] = yr;\n\t\tevent[cnte][4] = v;\n\t}\n\n\tpublic static void delPlate(int x, int yl, int yr, int v) {\n\t\tevent[++cnte][0] = 2;\n\t\tevent[cnte][1] = x;\n\t\tevent[cnte][2] = yl;\n\t\tevent[cnte][3] = yr;\n\t\tevent[cnte][4] = v;\n\t}\n\n\tpublic static void addFruit(int x, int y, int k, int i) {\n\t\tevent[++cnte][0] = 3;\n\t\tevent[cnte][1] = x;\n\t\t// 2、3、4位空缺\n\t\tevent[cnte][5] = y;\n\t\tevent[cnte][6] = k;\n\t\tevent[cnte][7] = i;\n\t}\n\n\tpublic static void compute(int el, int er, int vl, int vr) {\n\t\tif (el > er) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (event[id][0] == 3) {\n\t\t\t\t\tans[event[id][7]] = vl;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tint id = eid[i];\n\t\t\t\tif (event[id][0] == 1) {\n\t\t\t\t\tif (event[id][4] <= mid) {\n\t\t\t\t\t\tadd(event[id][2], event[id][3], 1);\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t} else if (event[id][0] == 2) {\n\t\t\t\t\tif (event[id][4] <= mid) {\n\t\t\t\t\t\tadd(event[id][2], event[id][3], -1);\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tint satisfy = query(event[id][5]);\n\t\t\t\t\tif (satisfy >= event[id][6]) {\n\t\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tevent[id][6] -= satisfy;\n\t\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 这里为什么不用做撤销？\n\t\t\t// 因为任何一个盘子，一定有两条扫描线\n\t\t\t// 一条扫描线会增加yl..yr的计数\n\t\t\t// 一条扫描线会减少yl..yr的计数\n\t\t\t// 同一个盘子的两条扫描线，一定会在一起，是不可能分开的\n\t\t\t// 所以此时树状数组就是清空的，不需要再做撤销操作\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\teid[el + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\teid[el + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tcompute(el, el + lsiz - 1, vl, mid);\n\t\t\tcompute(el + lsiz, er, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tp = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs2();\n\t\tfor (int i = 1; i <= p; i++) {\n\t\t\tint a = in.nextInt();\n\t\t\tint b = in.nextInt();\n\t\t\tint c = in.nextInt();\n\t\t\tif (ldfn[a] > ldfn[b]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = b;\n\t\t\t\tb = tmp;\n\t\t\t}\n\t\t\tint ablca = lca(a, b);\n\t\t\t// 类型1，a和b的lca是a或b，2个区域，4个事件产生\n\t\t\t// 类型2，a和b的lca不是a或b，1个区域，2个事件产生\n\t\t\tif (ablca == a || ablca == b) {\n\t\t\t\tint son = lcaSon(a, b);\n\t\t\t\t// (1 ~ dfn[son]-1) (b子树上的dfn范围)\n\t\t\t\taddPlate(1, ldfn[b], rdfn[b], c);\n\t\t\t\tdelPlate(ldfn[son], ldfn[b], rdfn[b], c);\n\t\t\t\t// (b子树上的dfn范围) (son子树上最大的dfn序号+1 ~ n)\n\t\t\t\taddPlate(ldfn[b], rdfn[son] + 1, n, c);\n\t\t\t\tdelPlate(rdfn[b] + 1, rdfn[son] + 1, n, c);\n\t\t\t} else {\n\t\t\t\t// (a子树上的dfn范围) (b子树上的dfn范围)\n\t\t\t\taddPlate(ldfn[a], ldfn[b], rdfn[b], c);\n\t\t\t\tdelPlate(rdfn[a] + 1, ldfn[b], rdfn[b], c);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tint u = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tint k = in.nextInt();\n\t\t\taddFruit(Math.min(ldfn[u], ldfn[v]), Math.max(ldfn[u], ldfn[v]), k, i);\n\t\t}\n\t\t// 根据x排序，如果x一样，加盘子排最前、删盘子其次、水果最后\n\t\tArrays.sort(event, 1, cnte + 1, (a, b) -> a[1] != b[1] ? a[1] - b[1] : a[0] - b[0]);\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\teid[i] = i;\n\t\t}\n\t\tcompute(1, cnte, 0, INF);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code04_Fruit1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
