95a9220a-48cb-468e-8534-1fe2abf51bb7	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class169;\n\n// 点的度都是奇数的最小瓶颈，java版\n// 一共有n个点，初始没有边，依次加入m条无向边，每条边有边权\n// 每次加入后，询问是否存在一个边集，满足每个点连接的边的数量都是奇数\n// 如果存在，希望边集的最大边权，尽可能小，如果不存在打印-1\n// 2 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 1 <= 边权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF603E\n// 测试链接 : https://codeforces.com/problemset/problem/603/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_PastoralOddities1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 300001;\n\tpublic static int n, m;\n\n\t// edge代表所有边依次出现\n\t// wsort代表所有边按边权排序\n\t// 每条边有：端点x、端点y、边权w、时序tim、边权排名rak\n\tpublic static int[][] edge = new int[MAXM][5];\n\tpublic static int[][] wsort = new int[MAXM][5];\n\n\t// 可撤销并查集 + 节点数为奇数的连通区数量为oddnum\n\tpublic static int oddnum;\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] ans = new int[MAXM];\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static boolean union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx == fy) {\n\t\t\treturn false;\n\t\t}\n\t\tif ((siz[fx] & 1) == 1 && (siz[fy] & 1) == 1) {\n\t\t\toddnum -= 2;\n\t\t}\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t\treturn true;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t\tif ((siz[fx] & 1) == 1 && (siz[fy] & 1) == 1) {\n\t\t\toddnum += 2;\n\t\t}\n\t}\n\n\t// 依次出现的边在edge里，当前来到[el..er]范围\n\t// 权值排序后的边在wsort里，答案范围[vl..vr]，同时也是排名范围\n\t// 调用递归的前提 : el之前，边权排名<vl的边，已经加到图里了\n\t// 利用整体二分得到所有边的答案\n\tpublic static void compute(int el, int er, int vl, int vr) {\n\t\tif (el > er) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tans[i] = vl;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\t// 1) el之前，边权排名在[vl..mid]之间的边，加到图里，通过遍历wsort[vl..mid]来加速\n\t\t\tint unionCnt1 = 0;\n\t\t\tfor (int i = vl; i <= mid; i++) {\n\t\t\t\tif (wsort[i][3] < el) {\n\t\t\t\t\tif (union(wsort[i][0], wsort[i][1])) {\n\t\t\t\t\t\tunionCnt1++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 2) 从el开始遍历，边权排名<=mid的边，加到图里，找到第一个达标的边split\n\t\t\tint unionCnt2 = 0;\n\t\t\tint split = er + 1;\n\t\t\tfor (int i = el; i <= er; i++) {\n\t\t\t\tif (edge[i][4] <= mid) {\n\t\t\t\t\tif (union(edge[i][0], edge[i][1])) {\n\t\t\t\t\t\tunionCnt2++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (oddnum == 0) {\n\t\t\t\t\tsplit = i;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 3) 撤销2)的效果，el之前，边权排名<=mid的边，都在图中\n\t\t\tfor (int i = 1; i <= unionCnt2; i++) {\n\t\t\t\tundo();\n\t\t\t}\n\t\t\t// 4) 执行 compute(el, split - 1, mid + 1, vr)，此时满足子递归的前提\n\t\t\tcompute(el, split - 1, mid + 1, vr);\n\t\t\t// 5) 撤销1)的效果，此时只剩下前提了，el之前，边权排名<vl的边，都在图中\n\t\t\tfor (int i = 1; i <= unionCnt1; i++) {\n\t\t\t\tundo();\n\t\t\t}\n\t\t\t// 6) 从el开始到split之前，边权排名<vl的边，加到图里\n\t\t\tint unionCnt3 = 0;\n\t\t\tfor (int i = el; i <= split - 1; i++) {\n\t\t\t\tif (edge[i][4] < vl) {\n\t\t\t\t\tif (union(edge[i][0], edge[i][1])) {\n\t\t\t\t\t\tunionCnt3++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 7) 执行 compute(split, er, vl, mid)，此时满足子递归的前提\n\t\t\tcompute(split, er, vl, mid);\n\t\t\t// 8) 撤销6)的效果，回到了前提\n\t\t\tfor (int i = 1; i <= unionCnt3; i++) {\n\t\t\t\tundo();\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\toddnum = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\twsort[i][0] = edge[i][0];\n\t\t\twsort[i][1] = edge[i][1];\n\t\t\twsort[i][2] = edge[i][2];\n\t\t\twsort[i][3] = edge[i][3];\n\t\t}\n\t\tArrays.sort(wsort, 1, m + 1, (a, b) -> a[2] - b[2]);\n\t\t// edge数组、wsort数组，每条边设置排名信息\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\twsort[i][4] = i;\n\t\t\tedge[wsort[i][3]][4] = i;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tedge[i][0] = in.nextInt();\n\t\t\tedge[i][1] = in.nextInt();\n\t\t\tedge[i][2] = in.nextInt();\n\t\t\tedge[i][3] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute(1, m, 1, m + 1);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (ans[i] == m + 1) {\n\t\t\t\tout.println(-1);\n\t\t\t} else {\n\t\t\t\tout.println(wsort[ans[i]][2]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_PastoralOddities1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
