a7c11481-67bb-4f61-9091-88e46ddecc9c	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class028;\n\nimport java.util.Arrays;\n\n// 基数排序\n// 测试链接 : https://leetcode.cn/problems/sort-an-array/\npublic class Code02_RadixSort {\n\n\t// 可以设置进制，不一定10进制，随你设置\n\tpublic static int BASE = 10;\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int[] help = new int[MAXN];\n\n\tpublic static int[] cnts = new int[BASE];\n\n\tpublic static int[] sortArray(int[] arr) {\n\t\tif (arr.length > 1) {\n\t\t\t// 如果会溢出，那么要改用long类型数组来排序\n\t\t\tint n = arr.length;\n\t\t\t// 找到数组中的最小值\n\t\t\tint min = arr[0];\n\t\t\tfor (int i = 1; i < n; i++) {\n\t\t\t\tmin = Math.min(min, arr[i]);\n\t\t\t}\n\t\t\tint max = 0;\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\t// 数组中的每个数字，减去数组中的最小值，就把arr转成了非负数组\n\t\t\t\tarr[i] -= min;\n\t\t\t\t// 记录数组中的最大值\n\t\t\t\tmax = Math.max(max, arr[i]);\n\t\t\t}\n\t\t\t// 根据最大值在BASE进制下的位数，决定基数排序做多少轮\n\t\t\tradixSort(arr, n, bits(max));\n\t\t\t// 数组中所有数都减去了最小值，所以最后不要忘了还原\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tarr[i] += min;\n\t\t\t}\n\t\t}\n\t\treturn arr;\n\t}\n\n\t// 返回number在BASE进制下有几位\n\tpublic static int bits(int number) {\n\t\tint ans = 0;\n\t\twhile (number > 0) {\n\t\t\tans++;\n\t\t\tnumber /= BASE;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 基数排序核心代码\n\t// arr内要保证没有负数\n\t// n是arr的长度\n\t// bits是arr中最大值在BASE进制下有几位\n\tpublic static void radixSort(int[] arr, int n, int bits) {\n\t\t// 理解的时候可以假设BASE = 10\n\t\tfor (int offset = 1; bits > 0; offset *= BASE, bits--) {\n\t\t\tArrays.fill(cnts, 0);\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\t// 数字提取某一位的技巧\n\t\t\t\tcnts[(arr[i] / offset) % BASE]++;\n\t\t\t}\n\t\t\t// 处理成前缀次数累加的形式\n\t\t\tfor (int i = 1; i < BASE; i++) {\n\t\t\t\tcnts[i] = cnts[i] + cnts[i - 1];\n\t\t\t}\n\t\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\t\t// 前缀数量分区的技巧\n\t\t\t\t// 数字提取某一位的技巧\n\t\t\t\thelp[--cnts[(arr[i] / offset) % BASE]] = arr[i];\n\t\t\t}\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tarr[i] = help[i];\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code02_RadixSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
7f7543aa-aa8c-475d-b755-d159488fd8f3	696832b0-38df-469e-a0c0-801aa9578cbf	java	package class169;\n\n// 范围最大异或和，java版\n// 给定一个长度为n的数组arr，下标1~n，接下来有q条查询，格式如下\n// 查询 l r : arr[l..r]中选若干个数，打印最大的异或和\n// 1 <= n、q <= 5 * 10^5\n// 0 <= arr[i] <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/CF1100F\n// 测试链接 : https://codeforces.com/problemset/problem/1100/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_IvanAndBurgers1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int BIT = 21;\n\tpublic static int n, q;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] qid = new int[MAXN];\n\tpublic static int[] l = new int[MAXN];\n\tpublic static int[] r = new int[MAXN];\n\n\tpublic static int[][] baset = new int[MAXN][BIT + 1];\n\tpublic static int[] tmp = new int[BIT + 1];\n\n\tpublic static int[] lset = new int[MAXN];\n\tpublic static int[] rset = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void insert(int[] basis, int num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void clear(int[] basis) {\n\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\tbasis[i] = 0;\n\t\t}\n\t}\n\n\tpublic static int maxEor(int[] basis) {\n\t\tint ret = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tret = Math.max(ret, ret ^ basis[i]);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void clone(int[] b1, int[] b2) {\n\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\tb1[i] = b2[i];\n\t\t}\n\t}\n\n\tpublic static void merge(int[] b1, int[] b2) {\n\t\tclone(tmp, b1);\n\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\tinsert(tmp, b2[i]);\n\t\t}\n\t}\n\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tans[qid[i]] = arr[vl];\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tclear(baset[mid]);\n\t\t\tinsert(baset[mid], arr[mid]);\n\t\t\tfor (int i = mid - 1; i >= vl; i--) {\n\t\t\t\tclone(baset[i], baset[i + 1]);\n\t\t\t\tinsert(baset[i], arr[i]);\n\t\t\t}\n\t\t\tfor (int i = mid + 1; i <= vr; i++) {\n\t\t\t\tclone(baset[i], baset[i - 1]);\n\t\t\t\tinsert(baset[i], arr[i]);\n\t\t\t}\n\t\t\tint lsiz = 0, rsiz = 0, id;\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tid = qid[i];\n\t\t\t\tif (r[id] < mid) {\n\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t} else if (l[id] > mid) {\n\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t} else {\n\t\t\t\t\tmerge(baset[l[id]], baset[r[id]]);\n\t\t\t\t\tans[id] = maxEor(tmp);\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tqid[ql + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tqid[ql + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tcompute(ql, ql + lsiz - 1, vl, mid);\n\t\t\tcompute(ql + lsiz, ql + lsiz + rsiz - 1, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tqid[i] = i;\n\t\t\tl[i] = in.nextInt();\n\t\t\tr[i] = in.nextInt();\n\t\t}\n\t\tcompute(1, q, 1, n);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_IvanAndBurgers1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
