e3dc95e4-3387-4dc0-803c-0fc0c7adedab	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class004;\n\npublic class SelectBubbleInsert {\n\n\t// 数组中交换i和j位置的数\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\t// 选择排序\n\tpublic static void selectionSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int minIndex, i = 0; i < arr.length - 1; i++) {\n\t\t\tminIndex = i;\n\t\t\tfor (int j = i + 1; j < arr.length; j++) {\n\t\t\t\tif (arr[j] < arr[minIndex]) {\n\t\t\t\t\tminIndex = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tswap(arr, i, minIndex);\n\t\t}\n\t}\n\n\t// 冒泡排序\n\tpublic static void bubbleSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int end = arr.length - 1; end > 0; end--) {\n\t\t\tfor (int i = 0; i < end; i++) {\n\t\t\t\tif (arr[i] > arr[i + 1]) {\n\t\t\t\t\tswap(arr, i, i + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 插入排序\n\tpublic static void insertionSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int i = 1; i < arr.length; i++) {\n\t\t\tfor (int j = i - 1; j >= 0 && arr[j] > arr[j + 1]; j--) {\n\t\t\t\tswap(arr, j, j + 1);\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：SelectBubbleInsert.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
aff72c43-2c10-4b56-b97c-113f6e5e80a2	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class021;\n\n// 归并排序，acm练习风格\n// 测试链接 : https://www.luogu.com.cn/problem/P1177\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_MergeSort {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] help = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\t// mergeSort1(0, n - 1);\n\t\tmergeSort2();\n\t\tfor (int i = 0; i < n - 1; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.println(arr[n - 1]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// 归并排序递归版\n\t// 假设l...r一共n个数\n\t// T(n) = 2 * T(n/2) + O(n)\n\t// a = 2, b = 2, c = 1\n\t// 根据master公式，时间复杂度O(n * logn)\n\t// 空间复杂度O(n)\n\tpublic static void mergeSort1(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\tmergeSort1(l, m);\n\t\tmergeSort1(m + 1, r);\n\t\tmerge(l, m, r);\n\t}\n\n\t// 归并排序非递归版\n\t// 时间复杂度O(n * logn)\n\t// 空间复杂度O(n)\n\tpublic static void mergeSort2() {\n\t\t// 一共发生O(logn)次\n\t\tfor (int l, m, r, step = 1; step < n; step <<= 1) {\n\t\t\t// 内部分组merge，时间复杂度O(n)\n\t\t\tl = 0;\n\t\t\twhile (l < n) {\n\t\t\t\tm = l + step - 1;\n\t\t\t\tif (m + 1 >= n) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tr = Math.min(l + (step << 1) - 1, n - 1);\n\t\t\t\tmerge(l, m, r);\n\t\t\t\tl = r + 1;\n\t\t\t}\n\t\t}\n\t}\n\n\t// l....r 一共有n个数\n\t// O(n)\n\tpublic static void merge(int l, int m, int r) {\n\t\tint i = l;\n\t\tint a = l;\n\t\tint b = m + 1;\n\t\twhile (a <= m && b <= r) {\n\t\t\thelp[i++] = arr[a] <= arr[b] ? arr[a++] : arr[b++];\n\t\t}\n\t\t// 左侧指针、右侧指针，必有一个越界、另一个不越界\n\t\twhile (a <= m) {\n\t\t\thelp[i++] = arr[a++];\n\t\t}\n\t\twhile (b <= r) {\n\t\t\thelp[i++] = arr[b++];\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tarr[i] = help[i];\n\t\t}\n\t}\n\n}	模板：Code01_MergeSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8c40db27-7c15-424a-9f7a-1f83f6808102	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class021;\n\n// 归并排序，填函数练习风格\n// 测试链接 : https://leetcode.cn/problems/sort-an-array/\n\npublic class Code02_MergeSort {\n\n\tpublic static int[] sortArray(int[] nums) {\n\t\tif (nums.length > 1) {\n\t\t\t// mergeSort1为递归方法\n\t\t\t// mergeSort2为非递归方法\n\t\t\t// 用哪个都可以\n\t\t\t// mergeSort1(nums);\n\t\t\tmergeSort2(nums);\n\t\t}\n\t\treturn nums;\n\t}\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int[] help = new int[MAXN];\n\n\t// 归并排序递归版\n\tpublic static void mergeSort1(int[] arr) {\n\t\tsort(arr, 0, arr.length - 1);\n\t}\n\n\tpublic static void sort(int[] arr, int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\tsort(arr, l, m);\n\t\tsort(arr, m + 1, r);\n\t\tmerge(arr, l, m, r);\n\t}\n\n\t// 归并排序非递归版\n\tpublic static void mergeSort2(int[] arr) {\n\t\tint n = arr.length;\n\t\tfor (int l, m, r, step = 1; step < n; step <<= 1) {\n\t\t\tl = 0;\n\t\t\twhile (l < n) {\n\t\t\t\tm = l + step - 1;\n\t\t\t\tif (m + 1 >= n) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tr = Math.min(l + (step << 1) - 1, n - 1);\n\t\t\t\tmerge(arr, l, m, r);\n\t\t\t\tl = r + 1;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void merge(int[] arr, int l, int m, int r) {\n\t\tint i = l;\n\t\tint a = l;\n\t\tint b = m + 1;\n\t\twhile (a <= m && b <= r) {\n\t\t\thelp[i++] = arr[a] <= arr[b] ? arr[a++] : arr[b++];\n\t\t}\n\t\twhile (a <= m) {\n\t\t\thelp[i++] = arr[a++];\n\t\t}\n\t\twhile (b <= r) {\n\t\t\thelp[i++] = arr[b++];\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tarr[i] = help[i];\n\t\t}\n\t}\n\n}	模板：Code02_MergeSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3f7fad56-3991-414b-b2ae-0e96fafe8812	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class023;\n\n// 随机快速排序，acm练习风格\n// 测试链接 : https://www.luogu.com.cn/problem/P1177\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_QuickSort {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tquickSort2(0, n - 1);\n\t\tfor (int i = 0; i < n - 1; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.println(arr[n - 1]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// 随机快速排序经典版(不推荐)\n\t// 甚至在洛谷上测试因为递归开太多层会爆栈导致出错\n\tpublic static void quickSort1(int l, int r) {\n\t\t// l == r，只有一个数\n\t\t// l > r，范围不存在，不用管\n\t\tif (l >= r) {\n\t\t\treturn;\n\t\t}\n\t\t// 随机这一下，常数时间比较大\n\t\t// 但只有这一下随机，才能在概率上把快速排序的时间复杂度收敛到O(n * logn)\n\t\t// l......r 随机选一个位置，x这个值，做划分\n\t\tint x = arr[l + (int) (Math.random() * (r - l + 1))];\n\t\tint mid = partition1(l, r, x);\n\t\tquickSort1(l, mid - 1);\n\t\tquickSort1(mid + 1, r);\n\t}\n\n\t// 已知arr[l....r]范围上一定有x这个值\n\t// 划分数组 <=x放左边，>x放右边\n\t// 并且确保划分完成后<=x区域的最后一个数字是x\n\tpublic static int partition1(int l, int r, int x) {\n\t\t// a : arr[l....a-1]范围是<=x的区域\n\t\t// xi : 记录在<=x的区域上任何一个x的位置，哪一个都可以\n\t\tint a = l, xi = 0;\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tif (arr[i] <= x) {\n\t\t\t\tswap(a, i);\n\t\t\t\tif (arr[a] == x) {\n\t\t\t\t\txi = a;\n\t\t\t\t}\n\t\t\t\ta++;\n\t\t\t}\n\t\t}\n\t\tswap(xi, a - 1);\n\t\treturn a - 1;\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\t// 随机快速排序改进版(推荐)\n\t// 可以通过所有测试用例\n\tpublic static void quickSort2(int l, int r) {\n\t\tif (l >= r) {\n\t\t\treturn;\n\t\t}\n\t\t// 随机这一下，常数时间比较大\n\t\t// 但只有这一下随机，才能在概率上把快速排序的时间复杂度收敛到O(n * logn)\n\t\tint x = arr[l + (int) (Math.random() * (r - l + 1))];\n\t\tpartition2(l, r, x);\n\t\t// 为了防止底层的递归过程覆盖全局变量\n\t\t// 这里用临时变量记录first、last\n\t\tint left = first;\n\t\tint right = last;\n\t\tquickSort2(l, left - 1);\n\t\tquickSort2(right + 1, r);\n\t}\n\n\t// 荷兰国旗问题\n\tpublic static int first, last;\n\n\t// 已知arr[l....r]范围上一定有x这个值\n\t// 划分数组 <x放左边，==x放中间，>x放右边\n\t// 把全局变量first, last，更新成==x区域的左右边界\n\tpublic static void partition2(int l, int r, int x) {\n\t\tfirst = l;\n\t\tlast = r;\n\t\tint i = l;\n\t\twhile (i <= last) {\n\t\t\tif (arr[i] == x) {\n\t\t\t\ti++;\n\t\t\t} else if (arr[i] < x) {\n\t\t\t\tswap(first++, i++);\n\t\t\t} else {\n\t\t\t\tswap(i, last--);\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：Code01_QuickSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
