\t\tfirst = l;\n\t\tlast = r;\n\t\tint i = l;\n\t\twhile (i <= last) {\n\t\t\tif (arr[i] == x) {\n\t\t\t\ti++;\n\t\t\t} else if (arr[i] < x) {\n\t\t\t\tswap(arr, first++, i++);\n\t\t\t} else {\n\t\t\t\tswap(arr, i, last--);\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：Code02_QuickSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
78f5d0b0-34b6-4c7a-84dc-3e39b57f88b4	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class025;\n\n// 堆结构和堆排序，acm练习风格\n// 测试链接 : https://www.luogu.com.cn/problem/P1177\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_HeapSort {\n\t\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\t// heapSort1();\n\t\theapSort2();\n\t\tfor (int i = 0; i < n - 1; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.println(arr[n - 1]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// i位置的数，向上调整大根堆\n\tpublic static void heapInsert(int i) {\n\t\twhile (arr[i] > arr[(i - 1) / 2]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\t// i位置的数，向下调整大根堆\n\t// 当前堆的大小为size\n\tpublic static void heapify(int i, int size) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < size) {\n\t\t\tint best = l + 1 < size && arr[l + 1] > arr[l] ? l + 1 : l;\n\t\t\tbest = arr[best] > arr[i] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\t// 从顶到底建立大根堆，O(n * logn)\n\t// 依次弹出堆内最大值并排好序，O(n * logn)\n\t// 整体时间复杂度O(n * logn)\n\tpublic static void heapSort1() {\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\theapInsert(i);\n\t\t}\n\t\tint size = n;\n\t\twhile (size > 1) {\n\t\t\tswap(0, --size);\n\t\t\theapify(0, size);\n\t\t}\n\t}\n\n\t// 从底到顶建立大根堆，O(n)\n\t// 依次弹出堆内最大值并排好序，O(n * logn)\n\t// 整体时间复杂度O(n * logn)\n\tpublic static void heapSort2() {\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\theapify(i, n);\n\t\t}\n\t\tint size = n;\n\t\twhile (size > 1) {\n\t\t\tswap(0, --size);\n\t\t\theapify(0, size);\n\t\t}\n\t}\n\n}\n	模板：Code01_HeapSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ddac8b88-3c5a-4a7e-a5b6-c6bf0cd26ad8	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class025;\n\n// 堆结构和堆排序，填函数练习风格\n// 测试链接 : https://leetcode.cn/problems/sort-an-array/\npublic class Code02_HeapSort {\n\n\tpublic static int[] sortArray(int[] nums) {\n\t\tif (nums.length > 1) {\n\t\t\t// heapSort1为从顶到底建堆然后排序\n\t\t\t// heapSort2为从底到顶建堆然后排序\n\t\t\t// 用哪个都可以\n\t\t\t// heapSort1(nums);\n\t\t\theapSort2(nums);\n\t\t}\n\t\treturn nums;\n\t}\n\n\t// i位置的数，向上调整大根堆\n\t// arr[i] = x，x是新来的！往上看，直到不比父亲大，或者来到0位置(顶)\n\tpublic static void heapInsert(int[] arr, int i) {\n\t\twhile (arr[i] > arr[(i - 1) / 2]) {\n\t\t\tswap(arr, i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\t// i位置的数，变小了，又想维持大根堆结构\n\t// 向下调整大根堆\n\t// 当前堆的大小为size\n\tpublic static void heapify(int[] arr, int i, int size) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < size) {\n\t\t\t// 有左孩子，l\n\t\t\t// 右孩子，l+1\n\t\t\t// 评选，最强的孩子，是哪个下标的孩子\n\t\t\tint best = l + 1 < size && arr[l + 1] > arr[l] ? l + 1 : l;\n\t\t\t// 上面已经评选了最强的孩子，接下来，当前的数和最强的孩子之前，最强下标是谁\n\t\t\tbest = arr[best] > arr[i] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(arr, best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\t// 从顶到底建立大根堆，O(n * logn)\n\t// 依次弹出堆内最大值并排好序，O(n * logn)\n\t// 整体时间复杂度O(n * logn)\n\tpublic static void heapSort1(int[] arr) {\n\t\tint n = arr.length;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\theapInsert(arr, i);\n\t\t}\n\t\tint size = n;\n\t\twhile (size > 1) {\n\t\t\tswap(arr, 0, --size);\n\t\t\theapify(arr, 0, size);\n\t\t}\n\t}\n\n\t// 从底到顶建立大根堆，O(n)\n\t// 依次弹出堆内最大值并排好序，O(n * logn)\n\t// 整体时间复杂度O(n * logn)\n\tpublic static void heapSort2(int[] arr) {\n\t\tint n = arr.length;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\theapify(arr, i, n);\n\t\t}\n\t\tint size = n;\n\t\twhile (size > 1) {\n\t\t\tswap(arr, 0, --size);\n\t\t\theapify(arr, 0, size);\n\t\t}\n\t}\n\n}	