cbc4621a-e1f0-45b0-a45d-5a3f29aca333	a8e20b47-6b6f-447d-a405-8272557f21eb	java	package class028;\n\n// 基数排序，acm练习风格\n// 测试链接 : https://www.luogu.com.cn/problem/P1177\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_RadixSort {\n\n\t// 可以设置进制，不一定10进制，随你设置\n\tpublic static int BASE = 10;\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] help = new int[MAXN];\n\n\tpublic static int[] cnts = new int[BASE];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tsort();\n\t\tfor (int i = 0; i < n - 1; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.println(arr[n - 1]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static void sort() {\n\t\t// 如果会溢出，那么要改用long类型数组来排序\n\t\t// 找到数组中的最小值\n\t\tint min = arr[0];\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tmin = Math.min(min, arr[i]);\n\t\t}\n\t\tint max = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// 数组中的每个数字，减去数组中的最小值，就把arr转成了非负数组\n\t\t\tarr[i] -= min;\n\t\t\t// 记录数组中的最大值\n\t\t\tmax = Math.max(max, arr[i]);\n\t\t}\n\t\t// 根据最大值在BASE进制下的位数，决定基数排序做多少轮\n\t\tradixSort(bits(max));\n\t\t// 数组中所有数都减去了最小值，所以最后不要忘了还原\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] += min;\n\t\t}\n\t}\n\n\t// 返回number在BASE进制下有几位\n\tpublic static int bits(int number) {\n\t\tint ans = 0;\n\t\twhile (number > 0) {\n\t\t\tans++;\n\t\t\tnumber /= BASE;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 基数排序核心代码\n\t// arr内要保证没有负数\n\t// m是arr中最大值在BASE进制下有几位\n\tpublic static void radixSort(int bits) {\n\t\t// 理解的时候可以假设BASE = 10\n\t\tfor (int offset = 1; bits > 0; offset *= BASE, bits--) {\n\t\t\tArrays.fill(cnts, 0);\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\t// 数字提取某一位的技巧\n\t\t\t\tcnts[(arr[i] / offset) % BASE]++;\n\t\t\t}\n\t\t\tfor (int i = 1; i < BASE; i++) {\n\t\t\t\tcnts[i] = cnts[i] + cnts[i - 1];\n\t\t\t}\n\t\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\t\t// 前缀数量分区的技巧\n\t\t\t\t// 数字提取某一位的技巧\n\t\t\t\thelp[--cnts[(arr[i] / offset) % BASE]] = arr[i];\n\t\t\t}\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tarr[i] = help[i];\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：Code01_RadixSort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c2d1a50a-628a-4a10-b39f-78b54a5bed53	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\n\n// 最大数\n// 给定一组非负整数nums\n// 重新排列每个数的顺序（每个数不可拆分）使之组成一个最大的整数\n// 测试链接 : https://leetcode.cn/problems/largest-number/\npublic class Code01_LargestNumber {\n\n\t// strs中全是非空字符串，要把所有字符串拼接起来，形成字典序最小的结果\n\t// 暴力方法\n\t// 为了验证\n\t// 生成所有可能的排列\n\t// 其中选出字典序最小的结果\n\tpublic static String way1(String[] strs) {\n\t\tArrayList<String> ans = new ArrayList<>();\n\t\tf(strs, 0, ans);\n\t\tans.sort((a, b) -> a.compareTo(b));\n\t\treturn ans.get(0);\n\t}\n\n\t// 全排列代码，讲解038，常见经典递归过程解析\n\tpublic static void f(String[] strs, int i, ArrayList<String> ans) {\n\t\tif (i == strs.length) {\n\t\t\tStringBuilder path = new StringBuilder();\n\t\t\tfor (String s : strs) {\n\t\t\t\tpath.append(s);\n\t\t\t}\n\t\t\tans.add(path.toString());\n\t\t} else {\n\t\t\tfor (int j = i; j < strs.length; j++) {\n\t\t\t\tswap(strs, i, j);\n\t\t\t\tf(strs, i + 1, ans);\n\t\t\t\tswap(strs, i, j);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(String[] strs, int i, int j) {\n\t\tString tmp = strs[i];\n\t\tstrs[i] = strs[j];\n\t\tstrs[j] = tmp;\n\t}\n\n\t// strs中全是非空字符串，要把所有字符串拼接起来，形成字典序最小的结果\n\t// 正式方法\n\t// 时间复杂度O(n*logn)\n\tpublic static String way2(String[] strs) {\n\t\tArrays.sort(strs, (a, b) -> (a + b).compareTo(b + a));\n\t\tStringBuilder path = new StringBuilder();\n\t\tfor (int i = 0; i < strs.length; i++) {\n\t\t\tpath.append(strs[i]);\n\t\t}\n\t\treturn path.toString();\n\t}\n\n\t// 为了验证\n\t// 生成长度1~n的随机字符串数组\n\tpublic static String[] randomStringArray(int n, int m, int v) {\n\t\tString[] ans = new String[(int) (Math.random() * n) + 1];\n\t\tfor (int i = 0; i < ans.length; i++) {\n\t\t\tans[i] = randomString(m, v);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\t// 生成长度1~m，字符种类有v种，随机字符串\n\tpublic static String randomString(int m, int v) {\n\t\tint len = (int) (Math.random() * m) + 1;\n\t\tchar[] ans = new char[len];\n\t\tfor (int i = 0; i < len; i++) {\n\t\t\tans[i] = (char) ('a' + (int) (Math.random() * v));\n\t\t}\n\t\treturn String.valueOf(ans);\n\t}\n\n\t// 为了验证\n\t// 对数器\n\tpublic static void main(String[] args) {\n\t\tint n = 8; // 数组中最多几个字符串\n\t\tint m = 5; // 字符串长度最大多长\n\t\tint v = 4; // 字符的种类有几种\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tString[] strs = randomStringArray(n, m, v);\n\t\t\tString ans1 = way1(strs);\n\t\t\tString ans2 = way2(strs);\n\t\t\tif (!ans1.equals(ans2)) {\n\t\t\t\t// 如果出错了\n\t\t\t\t// 可以增加打印行为找到一组出错的例子\n\t\t\t\t// 然后去debug\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 测试链接 : https://leetcode.cn/problems/largest-number/\n\tpublic static String largestNumber(int[] nums) {\n\t\tint n = nums.length;\n\t\tString[] strs = new String[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tstrs[i] = String.valueOf(nums[i]);\n\t\t}\n\t\tArrays.sort(strs, (a, b) -> (b + a).compareTo(a + b));\n\t\tif (strs[0].equals("0")) {\n\t\t\treturn "0";\n\t\t}\n\t\tStringBuilder path = new StringBuilder();\n\t\tfor (String s : strs) {\n\t\t\tpath.append(s);\n\t\t}\n\t\treturn path.toString();\n\t}\n\n}\n	模板：Code01_LargestNumber.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e6709204-0d83-4839-9b8f-ab714af48532	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.Arrays;\n\n// 两地调度\n// 公司计划面试2n个人，给定一个数组 costs\n// 其中costs[i]=[aCosti, bCosti]\n// 表示第i人飞往a市的费用为aCosti，飞往b市的费用为bCosti\n// 返回将每个人都飞到a、b中某座城市的最低费用\n// 要求每个城市都有n人抵达\n// 测试链接 : https://leetcode.cn/problems/two-city-scheduling/\npublic class Code02_TwoCityScheduling {\n\n\tpublic static int twoCitySchedCost(int[][] costs) {\n\t\tint n = costs.length;\n\t\tint[] arr = new int[n];\n\t\tint sum = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = costs[i][1] - costs[i][0];\n\t\t\tsum += costs[i][0];\n\t\t}\n\t\tArrays.sort(arr);\n\t\tint m = n / 2;\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tsum += arr[i];\n\t\t}\n\t\treturn sum;\n\t}\n\n}\n	模板：Code02_TwoCityScheduling.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9ab33621-abff-4279-b6a2-bc3f015d031c	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.HashMap;\n\n// 吃掉N个橘子的最少天数\n// 厨房里总共有 n 个橘子，你决定每一天选择如下方式之一吃这些橘子\n// 1）吃掉一个橘子\n// 2) 如果剩余橘子数 n 能被 2 整除，那么你可以吃掉 n/2 个橘子\n// 3) 如果剩余橘子数 n 能被 3 整除，那么你可以吃掉 2*(n/3) 个橘子\n// 每天你只能从以上 3 种方案中选择一种方案\n// 请你返回吃掉所有 n 个橘子的最少天数\n// 测试链接 : https://leetcode.cn/problems/minimum-number-of-days-to-eat-n-oranges/\npublic class Code03_MinimumNumberEatOranges {\n\n\t// 所有的答案都填在这个表里\n\t// 这个表对所有的过程共用\n\tpublic static HashMap<Integer, Integer> dp = new HashMap<>();\n\n\tpublic static int minDays(int n) {\n\t\tif (n <= 1) {\n\t\t\treturn n;\n\t\t}\n\t\tif (dp.containsKey(n)) {\n\t\t\treturn dp.get(n);\n\t\t}\n\t\t// 1) 吃掉一个橘子\n\t\t// 2) 如果n能被2整除，吃掉一半的橘子，剩下一半\n\t\t// 3) 如果n能被3正数，吃掉三分之二的橘子，剩下三分之一\n\t\t// 因为方法2）和3），是按比例吃橘子，所以必然会非常快\n\t\t// 所以，决策如下：\n\t\t// 可能性1：为了使用2）方法，先把橘子吃成2的整数倍，然后直接干掉一半，剩下的n/2调用递归\n\t\t// 即，n % 2 + 1 + minDays(n/2)\n\t\t// 可能性2：为了使用3）方法，先把橘子吃成3的整数倍，然后直接干掉三分之二，剩下的n/3调用递归\n\t\t// 即，n % 3 + 1 + minDays(n/3)\n\t\t// 至于方法1)，完全是为了这两种可能性服务的，因为能按比例吃，肯定比一个一个吃快(显而易见的贪心)\n\t\tint ans = Math.min(n % 2 + 1 + minDays(n / 2), n % 3 + 1 + minDays(n / 3));\n\t\tdp.put(n, ans);\n\t\treturn ans;\n\t}\n\n}\n	模板：Code03_MinimumNumberEatOranges.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
57216edf-282c-4daf-8003-f8ad3aad81c0	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\n// 会议室II\n// 给你一个会议时间安排的数组 intervals\n// 每个会议时间都会包括开始和结束的时间intervals[i]=[starti, endi]\n// 返回所需会议室的最小数量\n// 测试链接 : https://leetcode.cn/problems/meeting-rooms-ii/\npublic class Code04_MeetingRoomsII {\n\n\tpublic static int minMeetingRooms(int[][] meeting) {\n\t\tint n = meeting.length;\n\t\tArrays.sort(meeting, (a, b) -> a[0] - b[0]);\n\t\tPriorityQueue<Integer> heap = new PriorityQueue<>();\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\twhile (!heap.isEmpty() && heap.peek() <= meeting[i][0]) {\n\t\t\t\theap.poll();\n\t\t\t}\n\t\t\theap.add(meeting[i][1]);\n\t\t\tans = Math.max(ans, heap.size());\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_MeetingRoomsII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fd281b85-326d-4068-a4be-14c57178b580	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\n// 课程表III\n// 这里有n门不同的在线课程，按从1到n编号\n// 给你一个数组courses\n// 其中courses[i]=[durationi, lastDayi]表示第i门课将会持续上durationi天课\n// 并且必须在不晚于lastDayi的时候完成\n// 你的学期从第 1 天开始\n// 且不能同时修读两门及两门以上的课程\n// 返回你最多可以修读的课程数目\n// 测试链接 : https://leetcode.cn/problems/course-schedule-iii/\npublic class Code05_CourseScheduleIII {\n\n\tpublic static int scheduleCourse(int[][] courses) {\n\t\t// 0 : 代价\n\t\t// 1 : 截止\n\t\tArrays.sort(courses, (a, b) -> a[1] - b[1]);\n\t\t// 大根堆\n\t\tPriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> b - a);\n\t\tint time = 0;\n\t\tfor (int[] c : courses) {\n\t\t\tif (time + c[0] <= c[1]) {\n\t\t\t\theap.add(c[0]);\n\t\t\t\ttime += c[0];\n\t\t\t} else {\n\t\t\t\t// time + c[0] > c[1]\n\t\t\t\tif (!heap.isEmpty() && heap.peek() > c[0]) {\n\t\t\t\t\ttime += c[0] - heap.poll();\n\t\t\t\t\theap.add(c[0]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn heap.size();\n\t}\n\n}\n	模板：Code05_CourseScheduleIII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f427fdb7-7989-44c4-a129-a0667617a9f7	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\nimport java.util.PriorityQueue;\n\n// 连接棒材的最低费用(leetcode测试)\n// 你有一些长度为正整数的棍子\n// 这些长度以数组sticks的形式给出\n// sticks[i]是第i个木棍的长度\n// 你可以通过支付x+y的成本将任意两个长度为x和y的棍子连接成一个棍子\n// 你必须连接所有的棍子，直到剩下一个棍子\n// 返回以这种方式将所有给定的棍子连接成一个棍子的最小成本\n// 测试链接 : https://leetcode.cn/problems/minimum-cost-to-connect-sticks/\npublic class Code06_MinimumCostToConnectSticks1 {\n\n\tpublic static int connectSticks(int[] arr) {\n\t\t// 小根堆\n\t\tPriorityQueue<Integer> heap = new PriorityQueue<>();\n\t\tfor (int i = 0; i < arr.length; i++) {\n\t\t\theap.add(arr[i]);\n\t\t}\n\t\tint sum = 0;\n\t\tint cur = 0;\n\t\twhile (heap.size() > 1) {\n\t\t\tcur = heap.poll() + heap.poll();\n\t\t\tsum += cur;\n\t\t\theap.add(cur);\n\t\t}\n\t\treturn sum;\n\t}\n\n}\n	模板：Code06_MinimumCostToConnectSticks1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
50f27d16-f153-474d-b1fa-688068d55c02	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class089;\n\n// 连接棒材的最低费用(洛谷测试)\n// 你有一些长度为正整数的棍子\n// 这些长度以数组sticks的形式给出\n// sticks[i]是第i个木棍的长度\n// 你可以通过支付x+y的成本将任意两个长度为x和y的棍子连接成一个棍子\n// 你必须连接所有的棍子，直到剩下一个棍子\n// 返回以这种方式将所有给定的棍子连接成一个棍子的最小成本\n// 测试链接 : https://www.luogu.com.cn/problem/P1090\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_MinimumCostToConnectSticks2 {\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int[] nums = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tnums[i] = (int) in.nval;\n\t\t\t}\n\t\t\tout.println(minCost());\n\t\t\tout.flush();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int minCost() {\n\t\tsize = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tadd(nums[i]);\n\t\t}\n\t\tint sum = 0;\n\t\tint cur = 0;\n\t\twhile (size > 1) {\n\t\t\tcur = pop() + pop();\n\t\t\tsum += cur;\n\t\t\tadd(cur);\n\t\t}\n\t\treturn sum;\n\t}\n\n\t// 手写小根堆\n\tpublic static int[] heap = new int[MAXN];\n\n\t// 堆的大小\n\tpublic static int size;\n\n\tpublic static void add(int x) {\n\t\theap[size] = x;\n\t\tint i = size++;\n\t\twhile (heap[i] < heap[(i - 1) / 2]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\tpublic static int pop() {\n\t\tint ans = heap[0];\n\t\tswap(0, --size);\n\t\tint i = 0, l = 1, best;\n\t\twhile (l < size) {\n\t\t\tbest = l + 1 < size && heap[l + 1] < heap[l] ? l + 1 : l;\n\t\t\tbest = heap[best] < heap[i] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(i, best);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint tmp = heap[i];\n\t\theap[i] = heap[j];\n\t\theap[j] = tmp;\n\t}\n\n}\n	模板：Code06_MinimumCostToConnectSticks2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0adfcbb4-5394-4b6e-8a1b-544136cb1921	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\n// 砍竹子II\n// 现需要将一根长为正整数bamboo_len的竹子砍为若干段\n// 每段长度均为正整数\n// 请返回每段竹子长度的最大乘积是多少\n// 答案需要对 1000000007 取模\n// 测试链接 : https://leetcode.cn/problems/jian-sheng-zi-ii-lcof/\npublic class Code01_CuttingBamboo {\n\n\t// 快速幂，求余数\n\t// 求x的n次方，最终得到的结果 % mod\n\tpublic static long power(long x, int n, int mod) {\n\t\tlong ans = 1;\n\t\twhile (n > 0) {\n\t\t\tif ((n & 1) == 1) {\n\t\t\t\tans = (ans * x) % mod;\n\t\t\t}\n\t\t\tx = (x * x) % mod;\n\t\t\tn >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int cuttingBamboo(int n) {\n\t\tif (n == 2) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (n == 3) {\n\t\t\treturn 2;\n\t\t}\n\t\tint mod = 1000000007;\n\t\t// n = 4  -> 2 * 2\n\t\t// n = 5  -> 3 * 2\n\t\t// n = 6  -> 3 * 3\n\t\t// n = 7  -> 3 * 2 * 2\n\t\t// n = 8  -> 3 * 3 * 2\n\t\t// n = 9  -> 3 * 3 * 3\n\t\t// n = 10 -> 3 * 3 * 2 * 2\n\t\t// n = 11 -> 3 * 3 * 3 * 2\n\t\t// n = 12 -> 3 * 3 * 3 * 3\n\t\tint tail = n % 3 == 0 ? 1 : (n % 3 == 1 ? 4 : 2);\n\t\tint power = (tail == 1 ? n : (n - tail)) / 3;\n\t\treturn (int) (power(3, power, mod) * tail % mod);\n\t}\n\n}\n	模板：Code01_CuttingBamboo.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
93fc5425-cecd-4aea-9e03-90ce0a5d6f30	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\n// 分成k份的最大乘积\n// 一个数字n一定要分成k份，得到的乘积尽量大是多少\n// 数字n和k，可能非常大，到达10^12规模\n// 结果可能更大，所以返回结果对 1000000007 取模\n// 来自真实大厂笔试，没有在线测试，对数器验证\npublic class Code02_MaximumProduct {\n\n\t// 暴力递归\n\t// 为了验证\n\tpublic static int maxValue1(int n, int k) {\n\t\treturn f1(n, k);\n\t}\n\n\t// 剩余的数字rest拆成k份\n\t// 返回最大乘积\n\t// 暴力尝试一定能得到最优解\n\tpublic static int f1(int rest, int k) {\n\t\tif (k == 1) {\n\t\t\treturn rest;\n\t\t}\n\t\tint ans = Integer.MIN_VALUE;\n\t\tfor (int cur = 1; cur <= rest && (rest - cur) >= (k - 1); cur++) {\n\t\t\tint curAns = cur * f1(rest - cur, k - 1);\n\t\t\tans = Math.max(ans, curAns);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 贪心的解\n\t// 这是最优解\n\t// 如果结果很大，那么求余数\n\tpublic static int maxValue2(int n, int k) {\n\t\tint mod = 1000000007;\n\t\tlong a = n / k;\n\t\tint b = n % k;\n\t\tlong part1 = power(a + 1, b, mod);\n\t\tlong part2 = power(a, k - b, mod);\n\t\treturn (int) (part1 * part2) % mod;\n\t}\n\n\tpublic static long power(long x, int n, int mod) {\n\t\tlong ans = 1;\n\t\twhile (n > 0) {\n\t\t\tif ((n & 1) == 1) {\n\t\t\t\tans = (ans * x) % mod;\n\t\t\t}\n\t\t\tx = (x * x) % mod;\n\t\t\tn >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 对数器\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tint N = 30;\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint k = (int) (Math.random() * n) + 1;\n\t\t\tint ans1 = maxValue1(n, k);\n\t\t\tint ans2 = maxValue2(n, k);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\t// 如果出错了\n\t\t\t\t// 可以增加打印行为找到一组出错的例子\n\t\t\t\t// 然后去debug\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code02_MaximumProduct.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3f02669f-0fe4-4ff9-b69f-f221e3551d09	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\nimport java.util.Arrays;\n\n// 会议必须独占时间段的最大会议数量\n// 给定若干会议的开始、结束时间\n// 你参加某个会议的期间，不能参加其他会议\n// 返回你能参加的最大会议数量\n// 同学找到了Leetcode的在线测试，题意类似\n// 测试链接 :https://leetcode.cn/problems/non-overlapping-intervals/\npublic class Code03_MeetingMonopoly1 {\n\n\t// 测试链接 :https://leetcode.cn/problems/non-overlapping-intervals/\n\t// 测试链接中，问至少删除多少会议，可以让剩下的会议都不重合\n\t// 那么求出，最多能不重合的参加多少会议，然后 n - 这个数量，就是答案\n\t// 同时注意，测试链接中，会议的时间点范围[- 5 * 10 ^ 4 ~ + 5 * 10 ^ 4]\n\t// 其实就是课上讲的方法，稍微改动一下即可，改动的地方已经加上注释\n\tpublic static int eraseOverlapIntervals(int[][] meeting) {\n\t\tArrays.sort(meeting, (a, b) -> a[1] - b[1]);\n\t\tint n = meeting.length;\n\t\tint ans = 0;\n\t\t// cur初始设置为-50001，因为题目数据状况如此\n\t\tfor (int i = 0, cur = -50001; i < n; i++) {\n\t\t\tif (cur <= meeting[i][0]) {\n\t\t\t\tans++;\n\t\t\t\tcur = meeting[i][1];\n\t\t\t}\n\t\t}\n\t\t// 会议总数 - 参加的最大会议数量\n\t\treturn n - ans;\n\t}\n\n\t// 暴力方法\n\t// 为了验证\n\t// 时间复杂度O(n!)\n\tpublic static int maxMeeting1(int[][] meeting) {\n\t\treturn f(meeting, meeting.length, 0);\n\t}\n\n\t// 把所有会议全排列\n\t// 其中一定有安排会议次数最多的排列\n\tpublic static int f(int[][] meeting, int n, int i) {\n\t\tint ans = 0;\n\t\tif (i == n) {\n\t\t\tfor (int j = 0, cur = -1; j < n; j++) {\n\t\t\t\tif (cur <= meeting[j][0]) {\n\t\t\t\t\tans++;\n\t\t\t\t\tcur = meeting[j][1];\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int j = i; j < n; j++) {\n\t\t\t\tswap(meeting, i, j);\n\t\t\t\tans = Math.max(ans, f(meeting, n, i + 1));\n\t\t\t\tswap(meeting, i, j);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void swap(int[][] meeting, int i, int j) {\n\t\tint[] tmp = meeting[i];\n\t\tmeeting[i] = meeting[j];\n\t\tmeeting[j] = tmp;\n\t}\n\n\t// 正式方法\n\t// 时间复杂度O(n*logn)\n\tpublic static int maxMeeting2(int[][] meeting) {\n\t\t// meeting[i][0] : i号会议开始时间\n\t\t// meeting[i][1] : i号会议结束时间\n\t\tArrays.sort(meeting, (a, b) -> a[1] - b[1]);\n\t\tint n = meeting.length;\n\t\tint ans = 0;\n\t\tfor (int i = 0, cur = -1; i < n; i++) {\n\t\t\tif (cur <= meeting[i][0]) {\n\t\t\t\tans++;\n\t\t\t\tcur = meeting[i][1];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\t// 生成随机会议\n\tpublic static int[][] randomMeeting(int n, int m) {\n\t\tint[][] ans = new int[n][2];\n\t\tfor (int i = 0, a, b; i < n; i++) {\n\t\t\ta = (int) (Math.random() * m);\n\t\t\tb = (int) (Math.random() * m);\n\t\t\tif (a == b) {\n\t\t\t\tans[i][0] = a;\n\t\t\t\tans[i][1] = a + 1;\n\t\t\t} else {\n\t\t\t\tans[i][0] = Math.min(a, b);\n\t\t\t\tans[i][1] = Math.max(a, b);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 对数器\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tint N = 10;\n\t\tint M = 12;\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[][] meeting = randomMeeting(n, M);\n\t\t\tint ans1 = maxMeeting1(meeting);\n\t\t\tint ans2 = maxMeeting2(meeting);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\t// 如果出错了\n\t\t\t\t// 可以增加打印行为找到一组出错的例子\n\t\t\t\t// 然后去debug\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code03_MeetingMonopoly1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
61fff507-de84-489c-8cc5-e6c3f821150f	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\n// 同学找到了洛谷的在线测试，看似是题目3，其实不是\n// 区别在于数据量，如下测试链接中的题目\n// 会议的数量10^6，会议的开始、结束时间也是10^6\n// 排序会超时，C++的同学可能不会，但是java的同学会\n// 而且根据这个数据量，最优解一定不是排序！\n// 会议开始、结束时间也是10^6规模，所以不排序也可以做，具体看如下代码和注释\n// 并不是课上讲错了，而是这个数据状况太特殊\n// 测试链接 : https://www.luogu.com.cn/problem/P1803\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_MeetingMonopoly2 {\n\n\t// 既是会议的规模，也是开始、结束时间的规模\n\tpublic static int MAXN = 1000001;\n\n\t// latest[60] == 40\n\t// 表示 : 结束时间是60的所有会议中，最晚开始的会议是40的时候开始\n\t// 比如会议[1, 60]、[30, 60]、[40, 60]\n\t// 这些会议都在60结束，但是最晚开始的会议是40开始\n\t// 如果latest[60] == -1\n\t// 表示没有任何会议在60结束\n\tpublic static int[] latest = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tfor (int i = 0; i < MAXN; i++) {\n\t\t\t\tlatest[i] = -1;\n\t\t\t}\n\t\t\tfor (int i = 0, start, end; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tstart = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tend = (int) in.nval;\n\t\t\t\tif (latest[end] == -1) {\n\t\t\t\t\t// 如果结束时间在end的会议之前没发现过\n\t\t\t\t\t// 现在发现了\n\t\t\t\t\tlatest[end] = start;\n\t\t\t\t} else {\n\t\t\t\t\t// 如果结束时间在end的会议之前发现过\n\t\t\t\t\t// 记录最晚的开始时间\n\t\t\t\t\tlatest[end] = Math.max(latest[end], start);\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(compute());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute() {\n\t\tint ans = 0;\n\t\t// 不排序\n\t\t// 根据时间遍历\n\t\tfor (int cur = 0, end = 0; end < MAXN; end++) {\n\t\t\t// cur : cur之前不能再安排会议，因为安排会议的人来到了cur时刻\n\t\t\t// end是当前的结束时间\n\t\t\t// 所有以end结束的会议，最晚的开始时间是latest[end]\n\t\t\t// 如果cur <= latest[end]，那么说明可以安排当前以end结束的会议\n\t\t\tif (cur <= latest[end]) {\n\t\t\t\tans++;\n\t\t\t\tcur = end; // 安排之后，目前安排会议的人来到end时刻\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code03_MeetingMonopoly2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
be30bd40-ba80-4311-ab7b-f00d14050aa1	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\nimport java.util.PriorityQueue;\n\n// IPO\n// 给你n个项目，对于每个项目i\n// 它都有一个纯利润profits[i]\n// 和启动该项目需要的最小资本capital[i]\n// 最初你的资本为w，当你完成一个项目时，你将获得纯利润，添加到你的总资本中\n// 总而言之，从给定项目中选择最多k个不同项目的列表\n// 以最大化最终资本，并输出最终可获得的最多资本\n// 测试链接 : https://leetcode.cn/problems/ipo/\npublic class Code05_IPO {\n\n\tpublic static class Project {\n\t\tpublic int p; // 纯利润\n\t\tpublic int c; // 需要的启动金\n\n\t\tpublic Project(int profit, int cost) {\n\t\t\tp = profit;\n\t\t\tc = cost;\n\t\t}\n\t}\n\n\tpublic static int findMaximizedCapital(int k, int w, int[] profit, int[] cost) {\n\t\tint n = profit.length;\n\t\t// 需要的启动金小根堆\n\t\t// 代表被锁住的项目\n\t\tPriorityQueue<Project> heap1 = new PriorityQueue<>((a, b) -> a.c - b.c);\n\t\t// 利润大根堆\n\t\t// 代表被解锁的项目\n\t\tPriorityQueue<Project> heap2 = new PriorityQueue<>((a, b) -> b.p - a.p);\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\theap1.add(new Project(profit[i], cost[i]));\n\t\t}\n\t\twhile (k > 0) {\n\t\t\twhile (!heap1.isEmpty() && heap1.peek().c <= w) {\n\t\t\t\theap2.add(heap1.poll());\n\t\t\t}\n\t\t\tif (heap2.isEmpty()) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tw += heap2.poll().p;\n\t\t\tk--;\n\t\t}\n\t\treturn w;\n\t}\n\n}\n	模板：Code05_IPO.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b5156763-295a-4b73-a278-e41be5c1b959	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class090;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.HashSet;\n\n// 加入差值绝对值直到长度固定\n// 给定一个非负数组arr，计算任何两个数差值的绝对值\n// 如果arr中没有，都要加入到arr里，但是只加一份\n// 然后新的arr继续计算任何两个数差值的绝对值，\n// 如果arr中没有，都要加入到arr里，但是只加一份\n// 一直到arr大小固定，返回arr最终的长度\n// 来自真实大厂笔试，没有在线测试，对数器验证\npublic class Code06_AbsoluteValueAddToArray {\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int len1(int[] arr) {\n\t\tArrayList<Integer> list = new ArrayList<>();\n\t\tHashSet<Integer> set = new HashSet<>();\n\t\tfor (int num : arr) {\n\t\t\tlist.add(num);\n\t\t\tset.add(num);\n\t\t}\n\t\twhile (!finish(list, set))\n\t\t\t;\n\t\treturn list.size();\n\t}\n\n\tpublic static boolean finish(ArrayList<Integer> list, HashSet<Integer> set) {\n\t\tint len = list.size();\n\t\tfor (int i = 0; i < len; i++) {\n\t\t\tfor (int j = i + 1; j < len; j++) {\n\t\t\t\tint abs = Math.abs(list.get(i) - list.get(j));\n\t\t\t\tif (!set.contains(abs)) {\n\t\t\t\t\tlist.add(abs);\n\t\t\t\t\tset.add(abs);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn len == list.size();\n\t}\n\n\t// 正式方法\n\t// 时间复杂度O(n)\n\tpublic static int len2(int[] arr) {\n\t\tint max = 0;\n\t\t// 找到任意一个非0的值\n\t\tint gcd = 0;\n\t\tfor (int num : arr) {\n\t\t\tmax = Math.max(max, num);\n\t\t\tif (num != 0) {\n\t\t\t\tgcd = num;\n\t\t\t}\n\t\t}\n\t\tif (gcd == 0) { // 数组中都是0\n\t\t\treturn arr.length;\n\t\t}\n\t\t// 不都是0\n\t\t// 0 7次\n\t\t// 5 5次\n\t\tHashMap<Integer, Integer> cnts = new HashMap<>();\n\t\tfor (int num : arr) {\n\t\t\tif (num != 0) {\n\t\t\t\tgcd = gcd(gcd, num);\n\t\t\t}\n\t\t\tcnts.put(num, cnts.getOrDefault(num, 0) + 1);\n\t\t}\n\t\tint ans = max / gcd;\n\t\tint maxCnt = 0;\n\t\tfor (int key : cnts.keySet()) {\n\t\t\tif (key != 0) {\n\t\t\t\tans += cnts.get(key) - 1;\n\t\t\t}\n\t\t\tmaxCnt = Math.max(maxCnt, cnts.get(key));\n\t\t}\n\t\tans += cnts.getOrDefault(0, maxCnt > 1 ? 1 : 0);\n\t\treturn ans;\n\t}\n\n\tpublic static int gcd(int m, int n) {\n\t\treturn n == 0 ? m : gcd(n, m % n);\n\t}\n\n\t// 为了测试\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = (int) (Math.random() * v);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static void main(String[] args) {\n\t\tint N = 50;\n\t\tint V = 100;\n\t\tint testTimes = 20000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 0; i < testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[] nums = randomArray(n, V);\n\t\t\tint ans1 = len1(nums);\n\t\t\tint ans2 = len2(nums);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code06_AbsoluteValueAddToArray.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
44467b95-c4ab-4211-a63e-beacccc5e0a6	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\n// 最短无序连续子数组\n// 给你一个整数数组nums，你需要找出一个 连续子数组\n// 如果对这个子数组进行升序排序，那么整个数组都会变为升序排序\n// 请你找出符合题意的最短子数组，并输出它的长度\n// 测试链接 : https://leetcode.cn/problems/shortest-unsorted-continuous-subarray/\npublic class Code01_ShortestUnsortedContinuousSubarray {\n\n\tpublic static int findUnsortedSubarray(int[] nums) {\n\t\tint n = nums.length;\n\t\t// max > 当前数，认为不达标\n\t\t// 从左往右遍历，记录最右不达标的位置\n\t\tint right = -1;\n\t\tint max = Integer.MIN_VALUE;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tif (max > nums[i]) {\n\t\t\t\tright = i;\n\t\t\t}\n\t\t\tmax = Math.max(max, nums[i]);\n\t\t}\n\t\tint min = Integer.MAX_VALUE;\n\t\t// min < 当前数，认为不达标\n\t\t// 从右往左遍历，记录最左不达标的位置\n\t\tint left = n;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\tif (min < nums[i]) {\n\t\t\t\tleft = i;\n\t\t\t}\n\t\t\tmin = Math.min(min, nums[i]);\n\t\t}\n\t\treturn Math.max(0, right - left + 1);\n\t}\n\n}\n	模板：Code01_ShortestUnsortedContinuousSubarray.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c915770b-cbc0-4ee2-8dbb-ebc01f3d3a03	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\nimport java.util.List;\nimport java.util.TreeSet;\n\n// 最小区间\n// 你有k个非递减排列的整数列表\n// 找到一个最小区间，使得k个列表中的每个列表至少有一个数包含在其中\n// 测试链接 : https://leetcode.cn/problems/smallest-range-covering-elements-from-k-lists/\npublic class Code02_SmallestRange {\n\n\tpublic static class Node {\n\t\tpublic int v; // 值\n\t\tpublic int i; // 当前值来自哪个数组\n\t\tpublic int j; // 当前值来自i号数组的什么位置\n\n\t\tpublic Node(int a, int b, int c) {\n\t\t\tv = a;\n\t\t\ti = b;\n\t\t\tj = c;\n\t\t}\n\t}\n\n\t// 时间复杂度O(n*logk)\n\t// n是数字总数，k是数组数量\n\tpublic static int[] smallestRange(List<List<Integer>> nums) {\n\t\tint k = nums.size();\n\t\t// 根据值排序\n\t\t// 为什么排序的时候i要参与\n\t\t// 因为有序表中比较相等的样本只会保留一个\n\t\t// 为了值一样的元素都保留，于是i要参与排序\n\t\t// 在有序表中的所有元素i必然都不同\n\t\tTreeSet<Node> set = new TreeSet<>((a, b) -> a.v != b.v ? (a.v - b.v) : (a.i - b.i));\n\t\tfor (int i = 0; i < k; i++) {\n\t\t\tset.add(new Node(nums.get(i).get(0), i, 0));\n\t\t}\n\t\tint r = Integer.MAX_VALUE; // 记录最窄区间的宽度\n\t\tint a = 0; // 记录最窄区间的开头\n\t\tint b = 0; // 记录最窄区间的结尾\n\t\tNode max, min;\n\t\twhile (set.size() == k) {\n\t\t\tmax = set.last(); // 在有序表中，值最大的记录\n\t\t\tmin = set.pollFirst(); // 在有序表中，值最小的记录，并弹出\n\t\t\tif (max.v - min.v < r) {\n\t\t\t\tr = max.v - min.v;\n\t\t\t\ta = min.v;\n\t\t\t\tb = max.v;\n\t\t\t}\n\t\t\tif (min.j + 1 < nums.get(min.i).size()) {\n\t\t\t\tset.add(new Node(nums.get(min.i).get(min.j + 1), min.i, min.j + 1));\n\t\t\t}\n\t\t}\n\t\treturn new int[] { a, b };\n\t}\n\n}\n	模板：Code02_SmallestRange.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0d9f4032-7536-4ef9-9de4-fee6e48b758e	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\nimport java.util.PriorityQueue;\n\n// 组团买票\n// 景区里一共有m个项目，景区的第i个项目有如下两个参数：\n// game[i] = { Ki, Bi }，Ki、Bi一定是正数\n// Ki代表折扣系数，Bi代表票价\n// 举个例子 : Ki = 2, Bi = 10\n// 如果只有1个人买票，单张门票的价格为 : Bi - Ki * 1 = 8\n// 所以这1个人游玩该项目要花8元\n// 如果有2个人买票，单张门票的价格为 : Bi - Ki * 2 = 6\n// 所以这2个人游玩该项目要花6 * 2 = 12元\n// 如果有5个人买票，单张门票的价格为 : Bi - Ki * 5 = 0\n// 所以这5个人游玩该项目要花5 * 0 = 0元\n// 如果有更多人买票，都认为花0元(因为让项目倒贴钱实在是太操蛋了)\n// 于是可以认为，如果有x个人买票，单张门票的价格为 : Bi - Ki * x\n// x个人游玩这个项目的总花费是 : max { x * (Bi - Ki * x), 0 }\n// 单位一共有n个人，每个人最多可以选1个项目来游玩，也可以不选任何项目\n// 所有员工将在明晚提交选择，然后由你去按照上面的规则，统一花钱购票\n// 你想知道自己需要准备多少钱，就可以应付所有可能的情况，返回这个最保险的钱数\n// 数据量描述 : \n// 1 <= M、N、Ki、Bi <= 10^5\n// 来自真实大厂笔试，没有在线测试，对数器验证\npublic class Code03_GroupBuyTickets1 {\n\n\t// 暴力方法\n\t// 为了验证\n\t// 每个人做出所有可能的选择\n\t// 时间复杂度O((m+1)的n次方)\n\tpublic static int enough1(int n, int[][] games) {\n\t\tint m = games.length;\n\t\tint[] cnts = new int[m];\n\t\treturn f(0, n, m, games, cnts);\n\t}\n\n\tpublic static int f(int i, int n, int m, int[][] games, int[] cnts) {\n\t\tif (i == n) {\n\t\t\tint ans = 0;\n\t\t\tfor (int j = 0, k, b, x; j < m; j++) {\n\t\t\t\tk = games[j][0];\n\t\t\t\tb = games[j][1];\n\t\t\t\tx = cnts[j];\n\t\t\t\tans += Math.max((b - k * x) * x, 0);\n\t\t\t}\n\t\t\treturn ans;\n\t\t} else {\n\t\t\tint ans = f(i + 1, n, m, games, cnts);\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tcnts[j]++;\n\t\t\t\tans = Math.max(ans, f(i + 1, n, m, games, cnts));\n\t\t\t\tcnts[j]--;\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\t// 正式方法\n\t// 时间复杂度O(n * logm)\n\tpublic static int enough2(int n, int[][] games) {\n\t\t// 哪个项目，再来一人挣得最多\n\t\t// 大根堆\n\t\tPriorityQueue<Game> heap = new PriorityQueue<>((a, b) -> b.earn() - a.earn());\n\t\tfor (int[] g : games) {\n\t\t\theap.add(new Game(g[0], g[1]));\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// 一个个的人，依次送到当前最挣钱的项目里去\n\t\t\tif (heap.peek().earn() <= 0) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tGame cur = heap.poll();\n\t\t\tans += cur.earn();\n\t\t\tcur.people++;\n\t\t\theap.add(cur);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static class Game {\n\t\tpublic int ki; // 折扣系数\n\t\tpublic int bi; // 门票原价\n\t\tpublic int people; // 之前的人数\n\n\t\tpublic Game(int k, int b) {\n\t\t\tki = k;\n\t\t\tbi = b;\n\t\t\tpeople = 0;\n\t\t}\n\n\t\t// 如果再来一人，这个项目得到多少钱\n\t\tpublic int earn() {\n\t\t\t// bi - (people + 1) * ki : 当前的人，门票原价减少了，当前的门票价格\n\t\t\t// people * ki : 当前人的到来，之前的所有人，门票价格都再减去ki\n\t\t\treturn bi - (people + 1) * ki - people * ki;\n\t\t}\n\n\t}\n\n\t// 为了验证\n\tpublic static int[][] randomGames(int m, int v) {\n\t\tint[][] ans = new int[m][2];\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tans[i][0] = (int) (Math.random() * v) + 1;\n\t\t\tans[i][1] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tint N = 8;\n\t\tint M = 8;\n\t\tint V = 20;\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint m = (int) (Math.random() * M) + 1;\n\t\t\tint[][] games = randomGames(m, V);\n\t\t\tint ans1 = enough1(n, games);\n\t\t\tint ans2 = enough2(n, games);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code03_GroupBuyTickets1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0b8af00a-c27c-4243-acd4-101e96fbd923	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\n// 组团买票找到了在线测试\n// 逻辑和课上讲的一样，但是测试中设定的ki为负数\n// 实现做了一些小优化，具体可以看注释\n// 测试链接 : https://www.luogu.com.cn/problem/P12331\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.util.PriorityQueue;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_GroupBuyTickets2 {\n\n\tpublic static class Game {\n\t\tpublic long ki;\n\t\tpublic long bi;\n\t\tpublic int people;\n\n\t\tpublic Game(long k, long b) {\n\t\t\tki = k;\n\t\t\tbi = b;\n\t\t}\n\n\t\tpublic long earn() {\n\t\t\treturn cost(people + 1) - cost(people);\n\t\t}\n\n\t\tpublic long cost(long p) {\n\t\t\tlong price = ki * p + bi;\n\t\t\tif (price < 0) {\n\t\t\t\tprice = 0;\n\t\t\t}\n\t\t\treturn p * price;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tint n = in.nextInt();\n\t\tint m = in.nextInt();\n\t\tPriorityQueue<Game> heap = new PriorityQueue<>((a, b) -> Long.compare(b.earn(), a.earn()));\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tGame cur = new Game(in.nextLong(), in.nextLong());\n\t\t\t// 初始增费<=0的项目直接忽略\n\t\t\tif (cur.earn() > 0) {\n\t\t\t\theap.add(cur);\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i < n && !heap.isEmpty(); i++) {\n\t\t\tGame cur = heap.poll();\n\t\t\tlong money = cur.earn();\n\t\t\tif (money <= 0) {\n\t\t\t\t// 没有正向增费，那么可以结束了\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tans += money;\n\t\t\tcur.people++;\n\t\t\tif (cur.earn() > 0) {\n\t\t\t\theap.add(cur);\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0L;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code03_GroupBuyTickets2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
927457cc-0919-48b2-8712-5d3ad27112af	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\nimport java.util.Arrays;\n\n// 平均值最小累加和\n// 给定一个数组arr，长度为n\n// 再给定一个数字k，表示一定要将arr划分成k个集合\n// 每个数字只能进一个集合\n// 返回每个集合的平均值都累加起来的最小值\n// 平均值向下取整\n// 1 <= n <= 10^5\n// 0 <= arr[i] <= 10^5\n// 1 <= k <= n\n// 来自真实大厂笔试，没有在线测试，对数器验证\npublic class Code04_SplitMinimumAverageSum {\n\n\t// 暴力方法\n\t// 为了验证\n\t// 每个数字做出所有可能的选择\n\t// 时间复杂度O(k的n次方)\n\tpublic static int minAverageSum1(int[] arr, int k) {\n\t\tint[] sum = new int[k];\n\t\tint[] cnt = new int[k];\n\t\treturn f(arr, 0, sum, cnt);\n\t}\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int f(int[] arr, int i, int[] sum, int[] cnt) {\n\t\tif (i == arr.length) {\n\t\t\tint ans = 0;\n\t\t\tfor (int j = 0; j < sum.length; j++) {\n\t\t\t\tif (cnt[j] == 0) {\n\t\t\t\t\treturn Integer.MAX_VALUE;\n\t\t\t\t}\n\t\t\t\tans += sum[j] / cnt[j];\n\t\t\t}\n\t\t\treturn ans;\n\t\t} else {\n\t\t\tint ans = Integer.MAX_VALUE;\n\t\t\tfor (int j = 0; j < sum.length; j++) {\n\t\t\t\tsum[j] += arr[i];\n\t\t\t\tcnt[j]++;\n\t\t\t\tans = Math.min(ans, f(arr, i + 1, sum, cnt));\n\t\t\t\tsum[j] -= arr[i];\n\t\t\t\tcnt[j]--;\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\t// 正式方法\n\t// 时间复杂度O(n * logn)\n\tpublic static int minAverageSum2(int[] arr, int k) {\n\t\tArrays.sort(arr);\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < k - 1; i++) {\n\t\t\t// 最小的k-1个数，每个数独自成一个集合\n\t\t\tans += arr[i];\n\t\t}\n\t\tint sum = 0;\n\t\tfor (int i = k - 1; i < arr.length; i++) {\n\t\t\tsum += arr[i];\n\t\t}\n\t\tans += sum / (arr.length - k + 1);\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = (int) (Math.random() * v);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static void main(String[] args) {\n\t\tint N = 8;\n\t\tint V = 10000;\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[] arr = randomArray(n, V);\n\t\t\tint k = (int) (Math.random() * n) + 1;\n\t\t\tint ans1 = minAverageSum1(arr, k);\n\t\t\tint ans2 = minAverageSum2(arr, k);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code04_SplitMinimumAverageSum.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
15456224-b915-456a-a7f5-208f068f70aa	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class091;\n\nimport java.util.Arrays;\n\n// 执行所有任务的最少初始电量\n// 每一个任务有两个参数，需要耗费的电量、至少多少电量才能开始这个任务\n// 返回手机至少需要多少的初始电量，才能执行完所有的任务\n// 测试链接 : https://leetcode.cn/problems/minimum-initial-energy-to-finish-tasks/\npublic class Code05_MinimalBatteryPower {\n\n\t// 同学找到了本题的在线测试，把如下minimumEffort方法提交，可以直接通过\n\t// 测试链接 : https://leetcode.cn/problems/minimum-initial-energy-to-finish-tasks/\n\tpublic static int minimumEffort(int[][] tasks) {\n\t\tArrays.sort(tasks, (a, b) -> (b[0] - b[1]) - (a[0] - a[1]));\n\t\tint ans = 0;\n\t\tfor (int[] job : tasks) {\n\t\t\tans = Math.max(ans + job[0], job[1]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 暴力递归\n\t// 为了验证\n\t// 时间复杂度O(n!)\n\t// 得到所有排列\n\t// 其中一定有返还电量最小的排列\n\tpublic static int atLeast1(int[][] jobs) {\n\t\treturn f1(jobs, jobs.length, 0);\n\t}\n\n\tpublic static int f1(int[][] jobs, int n, int i) {\n\t\tif (i == n) {\n\t\t\tint ans = 0;\n\t\t\tfor (int[] job : jobs) {\n\t\t\t\tans = Math.max(job[1], ans + job[0]);\n\t\t\t}\n\t\t\treturn ans;\n\t\t} else {\n\t\t\tint ans = Integer.MAX_VALUE;\n\t\t\tfor (int j = i; j < n; j++) {\n\t\t\t\tswap(jobs, i, j);\n\t\t\t\tans = Math.min(ans, f1(jobs, n, i + 1));\n\t\t\t\tswap(jobs, i, j);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void swap(int[][] jobs, int i, int j) {\n\t\tint[] tmp = jobs[i];\n\t\tjobs[i] = jobs[j];\n\t\tjobs[j] = tmp;\n\t}\n\n\t// 正式方法\n\t// 贪心\n\t// 时间复杂度O(n * logn)\n\tpublic static int atLeast2(int[][] jobs) {\n\t\t// jobs[i][0] : 耗费\n\t\t// jobs[i][1] : 至少电量\n\t\t// 消耗电量 - 至少电量，越大的任务，越先倒推\n\t\tArrays.sort(jobs, (a, b) -> (b[0] - b[1]) - (a[0] - a[1]));\n\t\tint ans = 0;\n\t\tfor (int[] job : jobs) {\n\t\t\tans = Math.max(ans + job[0], job[1]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\tpublic static int[][] randomJobs(int n, int v) {\n\t\tint[][] jobs = new int[n][2];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tjobs[i][0] = (int) (Math.random() * v) + 1;\n\t\t\tjobs[i][1] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\treturn jobs;\n\t}\n\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tint N = 10;\n\t\tint V = 20;\n\t\tint testTimes = 2000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1; i <= testTimes; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[][] jobs = randomJobs(n, V);\n\t\t\tint ans1 = atLeast1(jobs);\n\t\t\tint ans2 = atLeast2(jobs);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t\tif (i % 100 == 0) {\n\t\t\t\tSystem.out.println("测试到第" + i + "组");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code05_MinimalBatteryPower.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
