7cbc4fd7-486d-437c-9b7c-c176b053b4a2	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class093;\n\n// 灌溉花园的最少水龙头数目\n// 在x轴上有一个一维的花园，花园长度为n，从点0开始，到点n结束\n// 花园里总共有 n + 1 个水龙头，分别位于[0, 1, ... n]\n// 给你一个整数n和一个长度为n+1的整数数组ranges\n// 其中ranges[i]表示\n// 如果打开点i处的水龙头，可以灌溉的区域为[i-ranges[i], i+ranges[i]]\n// 请你返回可以灌溉整个花园的最少水龙头数目\n// 如果花园始终存在无法灌溉到的地方请你返回-1\n// 测试链接 : https://leetcode.cn/problems/minimum-number-of-taps-to-open-to-water-a-garden/\npublic class Code02_MinimumTaps {\n\n\tpublic static int minTaps(int n, int[] ranges) {\n\t\t// right[i] = j\n\t\t// 所有左边界在i的水龙头里，影响到的最右右边界是j\n\t\tint[] right = new int[n + 1];\n\t\tfor (int i = 0, start; i <= n; i++) {\n\t\t\tstart = Math.max(0, i - ranges[i]);\n\t\t\tright[start] = Math.max(right[start], i + ranges[i]);\n\t\t}\n\t\t// 当前ans数量的水龙头打开，影响到的最右右边界\n\t\tint cur = 0;\n\t\t// 如果再多打开一个水龙头，影响到的最右边界\n\t\tint next = 0;\n\t\t// 打开水龙头的数量\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// 来到i位置\n\t\t\t// 先更新下一步的next\n\t\t\tnext = Math.max(next, right[i]);\n\t\t\tif (i == cur) {\n\t\t\t\tif (next > i) {\n\t\t\t\t\tcur = next;\n\t\t\t\t\tans++;\n\t\t\t\t} else {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code02_MinimumTaps.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0a12f5cb-10dc-4e82-85c6-6ce9d85a7362	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class093;\n\nimport java.util.Arrays;\n\n// 字符串转化\n// 给出两个长度相同的字符串str1和str2\n// 请你帮忙判断字符串str1能不能在 零次 或 多次 转化后变成字符串str2\n// 每一次转化时，你可以将str1中出现的所有相同字母变成其他任何小写英文字母\n// 只有在字符串str1能够通过上述方式顺利转化为字符串str2时才能返回true\n// 测试链接 : https://leetcode.cn/problems/string-transforms-into-another-string/\n// 测试链接 : https://www.lintcode.com/problem/3869\npublic class Code03_StringTransforms {\n\n\tpublic static boolean canConvert(String str1, String str2) {\n\t\tif (str1.equals(str2)) {\n\t\t\treturn true;\n\t\t}\n\t\t// map[x] : str2中字符x的词频\n\t\tint[] map = new int[26];\n\t\t// kinds : str2中字符的种类数\n\t\tint kinds = 0;\n\t\tfor (int i = 0; i < str2.length(); i++) {\n\t\t\tif (map[str2.charAt(i) - 'a']++ == 0) {\n\t\t\t\tkinds++;\n\t\t\t}\n\t\t}\n\t\tif (kinds == 26) {\n\t\t\treturn false;\n\t\t}\n\t\tArrays.fill(map, -1);\n\t\t// map[x] = y : str1中的字符x上次出现在str1中的y位置\n\t\tfor (int i = 0, cur; i < str1.length(); i++) {\n\t\t\tcur = str1.charAt(i) - 'a';\n\t\t\tif (map[cur] != -1 && str2.charAt(map[cur]) != str2.charAt(i)) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tmap[cur] = i;\n\t\t}\n\t\treturn true;\n\t}\n\n}\n	模板：Code03_StringTransforms.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
7b035e0c-64b7-4d77-b0e1-28a7a7b2bf73	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class093;\n\n// 过河问题\n// 一共n人出游，他们走到一条河的西岸，想要过河到东岸\n// 每个人都有一个渡河时间ti，西岸有一条船，一次最多乘坐两人\n// 如果船上有一个人，划到对岸的时间，等于这个人的渡河时间\n// 如果船上有两个人，划到对岸的时间，等于两个人的渡河时间的最大值\n// 返回最少要花费多少时间，才能使所有人都过河\n// 测试链接 : https://www.luogu.com.cn/problem/P1809\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_CrossRiver {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] nums = new int[MAXN];\n\n\tpublic static int[] dp = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tnums[i] = (int) in.nval;\n\t\t\t}\n\t\t\tout.println(minCost());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int minCost() {\n\t\tArrays.sort(nums, 0, n);\n\t\tif (n >= 1) {\n\t\t\tdp[0] = nums[0];\n\t\t}\n\t\tif (n >= 2) {\n\t\t\tdp[1] = nums[1];\n\t\t}\n\t\tif (n >= 3) {\n\t\t\tdp[2] = nums[0] + nums[1] + nums[2];\n\t\t}\n\t\tfor (int i = 3; i < n; i++) {\n\t\t\tdp[i] = Math.min(dp[i - 1] + nums[i] + nums[0], dp[i - 2] + nums[1] + nums[1] + nums[i] + nums[0]);\n\t\t}\n\t\treturn dp[n - 1];\n\t}\n\n}	模板：Code04_CrossRiver.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dca699a6-788f-4415-9030-f70eadb55f3c	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class093;\n\n// 超级洗衣机\n// 假设有n台超级洗衣机放在同一排上\n// 开始的时候，每台洗衣机内可能有一定量的衣服，也可能是空的\n// 在每一步操作中，你可以选择任意 m (1 <= m <= n) 台洗衣机\n// 与此同时将每台洗衣机的一件衣服送到相邻的一台洗衣机\n// 给定一个整数数组machines代表从左至右每台洗衣机中的衣物数量\n// 请给出能让所有洗衣机中剩下的衣物的数量相等的最少的操作步数\n// 如果不能使每台洗衣机中衣物的数量相等则返回-1\n// 测试链接 : https://leetcode.cn/problems/super-washing-machines/\npublic class Code05_SuperWashingMachines {\n\n\tpublic static int findMinMoves(int[] arr) {\n\t\tint n = arr.length;\n\t\tint sum = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tsum += arr[i];\n\t\t}\n\t\tif (sum % n != 0) {\n\t\t\treturn -1;\n\t\t}\n\t\tint avg = sum / n; // 每台洗衣机最终要求的衣服数量一定是平均值\n\t\tint leftSum = 0; // 左侧累加和\n\t\tint leftNeed = 0; // 左边还需要多少件衣服\n\t\tint rightNeed = 0;// 右边还需要多少件衣服\n\t\tint bottleNeck = 0;// 每一步的瓶颈\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < n; leftSum += arr[i], i++) {\n\t\t\tleftNeed = i * avg - leftSum;\n\t\t\trightNeed = (n - i - 1) * avg - (sum - leftSum - arr[i]);\n\t\t\tif (leftNeed > 0 && rightNeed > 0) {\n\t\t\t\tbottleNeck = leftNeed + rightNeed;\n\t\t\t} else {\n\t\t\t\tbottleNeck = Math.max(Math.abs(leftNeed), Math.abs(rightNeed));\n\t\t\t}\n\t\t\tans = Math.max(ans, bottleNeck);\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code05_SuperWashingMachines.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d01cbe81-cc78-41e7-b4b7-12cdbf90d15b	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\nimport java.util.Arrays;\n\n// 消灭怪物的最大数量\n// 你正在玩一款电子游戏，在游戏中你需要保护城市免受怪物侵袭\n// 给定两个大小为n的整数数组dist、speed\n// 其中dist[i]是第i个怪物与城市的初始距离\n// 其中speed[i]是第i个怪物的速度\n// 你有一种武器，一旦充满电，就可以消灭一个怪物，但是，武器需要1的时间才能充电完成\n// 武器在游戏开始时是充满电的状态，怪物从0时刻开始移动，一旦任何怪物到达城市，就输掉了这场游戏\n// 如果某个怪物恰好在某一分钟开始时到达城市，这也会被视为输掉游戏\n// 返回在你输掉游戏前可以消灭的怪物的最大数量，如果消灭所有怪兽了返回n\n// 测试链接 : https://leetcode.cn/problems/eliminate-maximum-number-of-monsters/\npublic class Code01_EliminateMaximumMonsters {\n\n\tpublic static int eliminateMaximum(int[] dist, int[] speed) {\n\t\tint n = dist.length;\n\t\tint[] time = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// a / b 向上取整 -> (a + b - 1) / b\n\t\t\ttime[i] = (dist[i] + speed[i] - 1) / speed[i];\n\t\t}\n\t\tArrays.sort(time);\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// 当前来到i的时刻\n\t\t\tif (time[i] <= i) {\n\t\t\t\treturn i;\n\t\t\t}\n\t\t}\n\t\treturn n;\n\t}\n\n}\n	模板：Code01_EliminateMaximumMonsters.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
37bbc30e-1808-478c-a8d9-f1062cd40b80	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\n// 最大回文数字\n// 给你一个仅由数字（0 - 9）组成的字符串num\n// 请你找出能够使用num中数字形成的最大回文整数\n// 并以字符串形式返回，该整数不含前导零\n// 你无需使用num中的所有数字，但你必须使用至少一个数字，数字可以重新排列\n// 测试链接 : https://leetcode.cn/problems/largest-palindromic-number/\npublic class Code02_LargestPalindromicNumber {\n\n\tpublic static String largestPalindromic(String num) {\n\t\tint n = num.length();\n\t\t// '0' ~ '9'字符对应整数为48 ~ 57\n\t\tint[] cnts = new int[58];\n\t\tfor (char a : num.toCharArray()) {\n\t\t\tcnts[a]++;\n\t\t}\n\t\tchar[] ans = new char[n];\n\t\tint leftSize = 0;\n\t\tchar mid = 0;\n\t\tfor (char i = '9'; i >= '1'; i--) {\n\t\t\tif ((cnts[i] & 1) == 1 && mid == 0) {\n\t\t\t\tmid = i;\n\t\t\t}\n\t\t\tfor (int j = cnts[i] / 2; j > 0; j--) {\n\t\t\t\tans[leftSize++] = i;\n\t\t\t}\n\t\t}\n\t\tif (leftSize == 0) { // '1'~'9'每一种字符出现次数 <= 1\n\t\t\tif (mid == 0) { // '1'~'9'每一种字符出现次数 == 0\n\t\t\t\treturn "0";\n\t\t\t} else { // '1'~'9'有若干字符出现次数 == 1，其中最大的字符是mid\n\t\t\t\treturn String.valueOf(mid);\n\t\t\t}\n\t\t}\n\t\t// '1'~'9'有若干字符出现次数 >= 2，左部分已经建立，再考虑把'0'字符填进来\n\t\tfor (int j = cnts['0'] / 2; j > 0; j--) {\n\t\t\tans[leftSize++] = '0';\n\t\t}\n\t\tint len = leftSize;\n\t\t// 把中点安插进去\n\t\tif (mid == 0 && (cnts['0'] & 1) == 1) {\n\t\t\tmid = '0';\n\t\t}\n\t\tif (mid != 0) {\n\t\t\tans[len++] = mid;\n\t\t}\n\t\t// 左部分逆序拷贝给右部分\n\t\tfor (int i = leftSize - 1; i >= 0; i--) {\n\t\t\tans[len++] = ans[i];\n\t\t}\n\t\treturn new String(ans, 0, len);\n\t}\n\n}\n	模板：Code02_LargestPalindromicNumber.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
27e55197-7ad1-4aaf-bdc0-abdcde4f5740	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\nimport java.util.PriorityQueue;\n\n// 最大平均通过率\n// 一所学校里有一些班级，每个班级里有一些学生，现在每个班都会进行一场期末考试\n// 给你一个二维数组classes，其中classes[i]=[passi, totali]\n// 表示你提前知道了第i个班级总共有totali个学生\n// 其中只有 passi 个学生可以通过考试\n// 给你一个整数extraStudents，表示额外有extraStudents个聪明的学生，一定能通过期末考\n// 你需要给这extraStudents个学生每人都安排一个班级，使得所有班级的平均通过率最大\n// 一个班级的 通过率 等于这个班级通过考试的学生人数除以这个班级的总人数\n// 平均通过率 是所有班级的通过率之和除以班级数目\n// 请你返回在安排这extraStudents个学生去对应班级后的最大平均通过率\n// 测试链接 : https://leetcode.cn/problems/maximum-average-pass-ratio/\npublic class Code03_MaximumAveragePassRatio {\n\n\tpublic static double maxAverageRatio(int[][] classes, int m) {\n\t\tint n = classes.length;\n\t\t// double[] c1 : {a, b, c}\n\t\t// a : c1班级有多少人通过\n\t\t// b : c1班级总人数\n\t\t// c : 如果再来一人，c1班级通过率提升多少，(a+1)/(b+1) - a/b\n\t\t// 通过率提升的大根堆\n\t\tPriorityQueue<double[]> heap = new PriorityQueue<>((c1, c2) -> c1[2] >= c2[2] ? -1 : 1);\n\t\t// n * logn\n\t\tfor (int[] c : classes) {\n\t\t\tdouble a = c[0];\n\t\t\tdouble b = c[1];\n\t\t\theap.add(new double[] { a, b, (a + 1) / (b + 1) - a / b });\n\t\t}\n\t\t// 天才一个一个分配\n\t\t// m * logn\n\t\twhile (m-- > 0) {\n\t\t\tdouble[] cur = heap.poll();\n\t\t\tdouble a = cur[0] + 1;\n\t\t\tdouble b = cur[1] + 1;\n\t\t\theap.add(new double[] { a, b, (a + 1) / (b + 1) - a / b });\n\t\t}\n\t\t// 计算通过率累加和\n\t\tdouble ans = 0;\n\t\twhile (!heap.isEmpty()) {\n\t\t\tdouble[] cur = heap.poll();\n\t\t\tans += cur[0] / cur[1];\n\t\t}\n\t\t// 返回最大平均通过率\n\t\treturn ans / n;\n\t}\n\n}\n	模板：Code03_MaximumAveragePassRatio.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
daf398a3-86e7-45f0-a5a8-448cadf28481	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\n// 雇佣K名工人的最低成本\n// 有n名工人，给定两个数组quality和wage\n// 其中quality[i]表示第i名工人的工作质量，其最低期望工资为wage[i]\n// 现在我们想雇佣k名工人组成一个工资组\n// 在雇佣一组k名工人时，我们必须按照下述规则向他们支付工资：\n// 对工资组中的每名工人，应当按其工作质量与同组其他工人的工作质量的比例来支付工资\n// 工资组中的每名工人至少应当得到他们的最低期望工资\n// 给定整数k，返回组成满足上述条件的付费群体所需的最小金额\n// 测试链接 : https://leetcode.cn/problems/minimum-cost-to-hire-k-workers/\npublic class Code04_MinimumCostToHireWorkers {\n\n\tpublic static class Employee {\n\t\tpublic double ratio; // 薪水 / 质量的比例\n\t\tpublic int quality;\n\n\t\tpublic Employee(double r, int q) {\n\t\t\tratio = r;\n\t\t\tquality = q;\n\t\t}\n\t}\n\n\tpublic static double mincostToHireWorkers(int[] quality, int[] wage, int k) {\n\t\tint n = quality.length;\n\t\tEmployee[] employees = new Employee[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\temployees[i] = new Employee((double) wage[i] / quality[i], quality[i]);\n\t\t}\n\t\t// 根据比例排序，比例小的在前，比例大的在后\n\t\tArrays.sort(employees, (a, b) -> a.ratio <= b.ratio ? -1 : 1);\n\t\t// 大根堆，用来收集最小的前k个质量数值\n\t\tPriorityQueue<Integer> heap = new PriorityQueue<Integer>((a, b) -> b - a);\n\t\t// 堆里，最小的前k个质量数值，总和是多少\n\t\tint qualitySum = 0;\n\t\tdouble ans = Double.MAX_VALUE;\n\t\tfor (int i = 0, curQuality; i < n; i++) {\n\t\t\tcurQuality = employees[i].quality;\n\t\t\tif (heap.size() < k) { // 堆没满\n\t\t\t\tqualitySum += curQuality;\n\t\t\t\theap.add(curQuality);\n\t\t\t\tif (heap.size() == k) {\n\t\t\t\t\tans = Math.min(ans, qualitySum * employees[i].ratio);\n\t\t\t\t}\n\t\t\t} else { // 堆满了\n\t\t\t\tif (heap.peek() > curQuality) {\n\t\t\t\t\tqualitySum += curQuality - heap.poll();\n\t\t\t\t\theap.add(curQuality);\n\t\t\t\t\tans = Math.min(ans, qualitySum * employees[i].ratio);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_MinimumCostToHireWorkers.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a47d82fb-c56a-4e9d-86ae-fe04e0a949cd	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\n// 砍树\n// 一共有n棵树，每棵树都有两个信息：\n// 第一天这棵树的初始重量、这棵树每天的增长重量\n// 你每天最多能砍1棵树，砍下这棵树的收益为：\n// 这棵树的初始重量 + 这棵树增长到这一天的总增重\n// 从第1天开始，你一共有m天可以砍树，返回m天内你获得的最大收益\n// 测试链接 : https://pintia.cn/problem-sets/91827364500/exam/problems/type/7?problemSetProblemId=91827367873\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n// 不过现在这个题收费了，验证很困难了，于是我找到了一个平替的题目\n// 本节课Code06_CookingPlan文件就是平替题目，贪心的思路是非常类似的\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_CuttingTree {\n\n\t// 树的个数、天数最大值，不超过的量\n\tpublic static int MAXN = 251;\n\n\t// 树的编号为1 ~ n\n\t// tree[i][0] : 第i棵树第一天的初始重量\n\t// tree[i][1] : 第i棵树每天的增长重量\n\tpublic static int[][] tree = new int[MAXN][2];\n\n\t// dp[i][j] : 在j天内，从前i棵树中选若干棵树进行砍伐，最大收益是多少\n\tpublic static int[][] dp = new int[MAXN][MAXN];\n\n\tpublic static int t, n, m;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tt = (int) in.nval;\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\ttree[j][0] = (int) in.nval;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\ttree[j][1] = (int) in.nval;\n\t\t\t}\n\t\t\tout.println(compute());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// 讲解073 - 01背包\n\tpublic static int compute() {\n\t\t// 树的初始重量不决定树的顺序，因为任何树砍了，就获得固定的初始量，和砍伐的顺序无关\n\t\t// 根据增长速度排序，增长量小的在前，增长量大的在后\n\t\t// 认为越靠后的树，越要尽量晚的砍伐，课上的重点内容\n\t\tArrays.sort(tree, 1, n + 1, (o1, o2) -> o1[1] - o2[1]);\n\t\t// dp[0][...] = 0 : 表示如果没有树，不管过去多少天，收益都是0\n\t\t// dp[...][0] = 0 : 表示不管有几棵树，没有时间砍树，收益都是0\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + tree[i][0] + tree[i][1] * (j - 1));\n\t\t\t}\n\t\t}\n\t\treturn dp[n][m];\n\t}\n\n}	模板：Code05_CuttingTree.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5a15b514-3e4d-40b2-98cc-8cd1d22d2ce3	d252426a-9418-4bd7-a1c9-7a591594b99e	java	package class094;\n\n// 烹调方案\n// 课上没有讲这个题，本节课的题目5，砍树问题，现在验证已经很困难了\n// 所以找到这个题作为平替，因为贪心的思路是非常类似的\n//\n// 一共有n个食材，一共有m秒可以加工食材，你只能串行加工食材\n// 每个食材的初始美味度为a[i]，美味衰减速度b[i]，加工花费c[i]秒\n// 第i个食材美味度 = a[i] - t * b[i]，t是加工食材的时刻\n// 计算m秒内，你能获得的最大美味度总和\n// 1 <= n <= 50\n// 其他数据 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1417\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n//\n// 本题的分析过程\n// 假设当前来到s时刻，食材x和食材y，必须选择一个先加工\n// 选择1，先加工x，后加工y，获得食材x的美味时刻是s，y的时刻是s + c[x]\n// 选择1的美味度 = a[x] - s * b[x] + a[y] - (s + c[x]) * b[y]\n//             = a[x] - s * b[x] + a[y] - s * b[y] - c[x] * b[y]\n//\n// 选择2，先加工y，后加工x，获得食材y的美味时刻是s，x的时刻是s + c[y]\n// 选择2的美味度 = a[y] - s * b[y] + a[x] - (s + c[y]) * b[x]\n//             = a[y] - s * b[y] + a[x] - s * b[x] - c[y] * b[x]\n//\n// 选择1和选择2的公共部分 = a[x] + a[y] - s * b[x] - s * b[y]，记为common\n// 选择1 = common - c[x] * b[y]\n// 选择2 = common - c[y] * b[x]\n// 也就是说，如果c[x] * b[y] <= c[y] * b[x]，先选食材x，否则先选食材y\n// 于是排序策略搞定了，剩下就和题目5一样了，01背包的解法，并且可以空间压缩\n// 代码如下\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code06_CookingPlan {\n\n\tstatic class Food {\n\t\tint a, b, c;\n\n\t\tpublic Food(int x, int y, int z) {\n\t\t\ta = x;\n\t\t\tb = y;\n\t\t\tc = z;\n\t\t}\n\t}\n\n\tstatic class FoodCmp implements Comparator<Food> {\n\t\t@Override\n\t\tpublic int compare(Food x, Food y) {\n\t\t\tif ((long) x.c * (long) y.b <= (long) y.c * (long) x.b) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn 1;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int MAXN = 51;\n\tpublic static int MAXM = 100001;\n\tpublic static int n, m;\n\tpublic static Food[] food = new Food[MAXN];\n\tpublic static long[] dp = new long[MAXM];\n\n\tpublic static long compute() {\n\t\tArrays.sort(food, 1, n + 1, new FoodCmp());\n\t\tdp[0] = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tdp[i] = -1;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = m, p = j - food[i].c; p >= 0; j--, p--) {\n\t\t\t\tif (dp[p] != -1) {\n\t\t\t\t\tdp[j] = Math.max(dp[j], dp[p] + food[i].a - (long) j * food[i].b);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tans = Math.max(ans, dp[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tm = in.nextInt();\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfood[i] = new Food(0, 0, 0);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfood[i].a = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfood[i].b = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfood[i].c = in.nextInt();\n\t\t}\n\t\tlong ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code06_CookingPlan.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b586b05e-0fee-470a-805b-798b3c694daf	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\n// 利用二维前缀和信息迅速得到二维区域和\n// 测试链接 : https://leetcode.cn/problems/range-sum-query-2d-immutable/\npublic class Code01_PrefixSumMatrix {\n\n\tclass NumMatrix {\n\n\t\tpublic int[][] sum;\n\n\t\tpublic NumMatrix(int[][] matrix) {\n\t\t\tint n = matrix.length;\n\t\t\tint m = matrix[0].length;\n\t\t\tsum = new int[n + 1][m + 1];\n\t\t\tfor (int a = 1, c = 0; c < n; a++, c++) {\n\t\t\t\tfor (int b = 1, d = 0; d < m; b++, d++) {\n\t\t\t\t\tsum[a][b] = matrix[c][d];\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\t\tsum[i][j] += sum[i][j - 1] + sum[i - 1][j] - sum[i - 1][j - 1];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic int sumRegion(int a, int b, int c, int d) {\n\t\t\tc++;\n\t\t\td++;\n\t\t\treturn sum[c][d] - sum[c][b] - sum[a][d] + sum[a][b];\n\t\t}\n\n\t}\n\n}\n	模板：Code01_PrefixSumMatrix.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bd744c01-9b7f-48a2-840a-f561fcc3050f	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\n// 边框为1的最大正方形\n// 给你一个由若干 0 和 1 组成的二维网格 grid\n// 请你找出边界全部由 1 组成的最大 正方形 子网格\n// 并返回该子网格中的元素数量。如果不存在，则返回 0。\n// 测试链接 : https://leetcode.cn/problems/largest-1-bordered-square/\npublic class Code02_LargestOneBorderedSquare {\n\n\t// 打败比例不高，但完全是常数时间的问题\n\t// 时间复杂度O(n * m * min(n,m))，额外空间复杂度O(1)\n\t// 复杂度指标上绝对是最优解\n\tpublic static int largest1BorderedSquare(int[][] g) {\n\t\tint n = g.length;\n\t\tint m = g[0].length;\n\t\tbuild(n, m, g);\n\t\tif (sum(g, 0, 0, n - 1, m - 1) == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\t// 找到的最大合法正方形的边长\n\t\tint ans = 1;\n\t\tfor (int a = 0; a < n; a++) {\n\t\t\tfor (int b = 0; b < m; b++) {\n\t\t\t\t// (a,b)所有左上角点\n\t\t\t\t//     (c,d)更大边长的右下角点，k是当前尝试的边长\n\t\t\t\tfor (int c = a + ans, d = b + ans, k = ans + 1; c < n && d < m; c++, d++, k++) {\n\t\t\t\t\tif (sum(g, a, b, c, d) - sum(g, a + 1, b + 1, c - 1, d - 1) == (k - 1) << 2) {\n\t\t\t\t\t\tans = k;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans * ans;\n\t}\n\n\t// g : 原始二维数组\n\t// 把g变成原始二维数组的前缀和数组sum，复用自己\n\t// 不能补0行，0列，都是0\n\tpublic static void build(int n, int m, int[][] g) {\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tg[i][j] += get(g, i, j - 1) + get(g, i - 1, j) - get(g, i - 1, j - 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int sum(int[][] g, int a, int b, int c, int d) {\n\t\treturn a > c ? 0 : (g[c][d] - get(g, c, b - 1) - get(g, a - 1, d) + get(g, a - 1, b - 1));\n\t}\n\n\tpublic static int get(int[][] g, int i, int j) {\n\t\treturn (i < 0 || j < 0) ? 0 : g[i][j];\n\t}\n\n}\n	模板：Code02_LargestOneBorderedSquare.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f5ce5738-4762-4414-9ac3-19ec9d27e126	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\n// 二维差分模版(洛谷)\n// 测试链接 : https://www.luogu.com.cn/problem/P3397\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_DiffMatrixLuogu {\n\n\tpublic static int MAXN = 1002;\n\n\tpublic static int[][] diff = new int[MAXN][MAXN];\n\n\tpublic static int n, q;\n\n\tpublic static void add(int a, int b, int c, int d, int k) {\n\t\tdiff[a][b] += k;\n\t\tdiff[c + 1][b] -= k;\n\t\tdiff[a][d + 1] -= k;\n\t\tdiff[c + 1][d + 1] += k;\n\t}\n\n\tpublic static void build() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tdiff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= n + 1; i++) {\n\t\t\tfor (int j = 1; j <= n + 1; j++) {\n\t\t\t\tdiff[i][j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tq = (int) in.nval;\n\t\t\tfor (int i = 1, a, b, c, d; i <= q; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\ta = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tb = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tc = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\td = (int) in.nval;\n\t\t\t\tadd(a, b, c, d, 1);\n\t\t\t}\n\t\t\tbuild();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(diff[i][1]);\n\t\t\t\tfor (int j = 2; j <= n; j++) {\n\t\t\t\t\tout.print(" " + diff[i][j]);\n\t\t\t\t}\n\t\t\t\tout.println();\n\t\t\t}\n\t\t\tclear();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_DiffMatrixLuogu.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
751f60ad-cf5b-44c9-bf7d-c64d984517f7	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\n// 二维差分模版(牛客)\n// 测试链接 : https://www.nowcoder.com/practice/50e1a93989df42efb0b1dec386fb4ccc\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_DiffMatrixNowcoder {\n\n\tpublic static int MAXN = 1005;\n\n\tpublic static int MAXM = 1005;\n\n\tpublic static long[][] diff = new long[MAXN][MAXM];\n\n\tpublic static int n, m, q;\n\n\tpublic static void add(int a, int b, int c, int d, int k) {\n\t\tdiff[a][b] += k;\n\t\tdiff[c + 1][b] -= k;\n\t\tdiff[a][d + 1] -= k;\n\t\tdiff[c + 1][d + 1] += k;\n\t}\n\n\tpublic static void build() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tdiff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= n + 1; i++) {\n\t\t\tfor (int j = 1; j <= m + 1; j++) {\n\t\t\t\tdiff[i][j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tq = (int) in.nval;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tadd(i, j, i, j, (int) in.nval);\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1, a, b, c, d, k; i <= q; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\ta = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tb = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tc = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\td = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tk = (int) in.nval;\n\t\t\t\tadd(a, b, c, d, k);\n\t\t\t}\n\t\t\tbuild();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(diff[i][1]);\n\t\t\t\tfor (int j = 2; j <= m; j++) {\n\t\t\t\t\tout.print(" " + diff[i][j]);\n\t\t\t\t}\n\t\t\t\tout.println();\n\t\t\t}\n\t\t\tclear();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_DiffMatrixNowcoder.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0b03ba22-68f0-466a-8320-78626f9b3b59	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\n// 用邮票贴满网格图\n// 给你一个 m * n 的二进制矩阵 grid\n// 每个格子要么为 0 （空）要么为 1 （被占据）\n// 给你邮票的尺寸为 stampHeight * stampWidth\n// 我们想将邮票贴进二进制矩阵中，且满足以下 限制 和 要求 ：\n// 覆盖所有空格子，不覆盖任何被占据的格子\n// 可以放入任意数目的邮票，邮票可以相互有重叠部分\n// 邮票不允许旋转，邮票必须完全在矩阵内\n// 如果在满足上述要求的前提下，可以放入邮票，请返回 true ，否则返回 false\n// 测试链接 : https://leetcode.cn/problems/stamping-the-grid/\npublic class Code04_StampingTheGrid {\n\n\t// 时间复杂度O(n*m)，额外空间复杂度O(n*m)\n\tpublic static boolean possibleToStamp(int[][] grid, int h, int w) {\n\t\tint n = grid.length;\n\t\tint m = grid[0].length;\n\t\t// sum是前缀和数组\n\t\t// 查询原始矩阵中的某个范围的累加和很快速\n\t\tint[][] sum = new int[n + 1][m + 1];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tsum[i + 1][j + 1] = grid[i][j];\n\t\t\t}\n\t\t}\n\t\tbuild(sum);\n\t\t// 差分矩阵\n\t\t// 当贴邮票的时候，不再原始矩阵里贴，在差分矩阵里贴\n\t\t// 原始矩阵就用来判断能不能贴邮票，不进行修改\n\t\t// 每贴一张邮票都在差分矩阵里修改\n\t\tint[][] diff = new int[n + 2][m + 2];\n\t\tfor (int a = 1, c = a + h - 1; c <= n; a++, c++) {\n\t\t\tfor (int b = 1, d = b + w - 1; d <= m; b++, d++) {\n\t\t\t\t// 原始矩阵中 (a,b)左上角点\n\t\t\t\t// 根据邮票规格，h、w，算出右下角点(c,d)\n\t\t\t\t// 这个区域彻底都是0，那么: \n\t\t\t\t// sumRegion(sum, a, b, c, d) == 0\n\t\t\t\t// 那么此时这个区域可以贴邮票\n\t\t\t\tif (sumRegion(sum, a, b, c, d) == 0) {\n\t\t\t\t\tadd(diff, a, b, c, d);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tbuild(diff);\n\t\t// 检查所有的格子！\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\t// 原始矩阵里：grid[i][j] == 0，说明是个洞\n\t\t\t\t// 差分矩阵里：diff[i + 1][j + 1] == 0，说明洞上并没有邮票\n\t\t\t\t// 此时返回false\n\t\t\t\tif (grid[i][j] == 0 && diff[i + 1][j + 1] == 0) {\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static void build(int[][] m) {\n\t\tfor (int i = 1; i < m.length; i++) {\n\t\t\tfor (int j = 1; j < m[0].length; j++) {\n\t\t\t\tm[i][j] += m[i - 1][j] + m[i][j - 1] - m[i - 1][j - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int sumRegion(int[][] sum, int a, int b, int c, int d) {\n\t\treturn sum[c][d] - sum[c][b - 1] - sum[a - 1][d] + sum[a - 1][b - 1];\n\t}\n\n\tpublic static void add(int[][] diff, int a, int b, int c, int d) {\n\t\tdiff[a][b] += 1;\n\t\tdiff[c + 1][d + 1] += 1;\n\t\tdiff[c + 1][b] -= 1;\n\t\tdiff[a][d + 1] -= 1;\n\t}\n\n}	模板：Code04_StampingTheGrid.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4acc4ee5-f60d-46e2-9668-7b12f9776f21	da19cc5d-c52d-472a-8985-a67cd270d859	java	package class048;\n\nimport java.util.Arrays;\n\n// 最强祝福力场\n// 小扣在探索丛林的过程中，无意间发现了传说中"落寞的黄金之都"\n// 而在这片建筑废墟的地带中，小扣使用探测仪监测到了存在某种带有「祝福」效果的力场\n// 经过不断的勘测记录，小扣将所有力场的分布都记录了下来\n// forceField[i] = [x,y,side] \n// 表示第 i 片力场将覆盖以坐标 (x,y) 为中心，边长为 side 的正方形区域。\n// 若任意一点的 力场强度 等于覆盖该点的力场数量\n// 请求出在这片地带中 力场强度 最强处的 力场强度\n// 注意：力场范围的边缘同样被力场覆盖。\n// 测试链接 : https://leetcode.cn/problems/xepqZ5/\npublic class Code05_StrongestForceField {\n\n\t// 时间复杂度O(n^2)，额外空间复杂度O(n^2)，n是力场的个数\n\tpublic static int fieldOfGreatestBlessing(int[][] fields) {\n\t\tint n = fields.length;\n\t\t// n : 矩形的个数，x 2*n个坐标\n\t\tlong[] xs = new long[n << 1];\n\t\tlong[] ys = new long[n << 1];\n\t\tfor (int i = 0, k = 0, p = 0; i < n; i++) {\n\t\t\tlong x = fields[i][0];\n\t\t\tlong y = fields[i][1];\n\t\t\tlong r = fields[i][2];\n\t\t\txs[k++] = (x << 1) - r;\n\t\t\txs[k++] = (x << 1) + r;\n\t\t\tys[p++] = (y << 1) - r;\n\t\t\tys[p++] = (y << 1) + r;\n\t\t}\n\t\t// xs数组中，排序了且相同值只留一份，返回有效长度\n\t\tint sizex = sort(xs);\n\t\t// ys数组中，排序了且相同值只留一份，返回有效长度\n\t\tint sizey = sort(ys);\n\t\t// n个力场，sizex : 2 * n, sizey : 2 * n\n\t\tint[][] diff = new int[sizex + 2][sizey + 2];\n\t\tfor (int i = 0, a, b, c, d; i < n; i++) {\n\t\t\tlong x = fields[i][0];\n\t\t\tlong y = fields[i][1];\n\t\t\tlong r = fields[i][2];\n\t\t\ta = rank(xs, (x << 1) - r, sizex);\n\t\t\tb = rank(ys, (y << 1) - r, sizey);\n\t\t\tc = rank(xs, (x << 1) + r, sizex);\n\t\t\td = rank(ys, (y << 1) + r, sizey);\n\t\t\tadd(diff, a, b, c, d);\n\t\t}\n\t\tint ans = 0;\n\t\t// O(n^2)\n\t\tfor (int i = 1; i < diff.length; i++) {\n\t\t\tfor (int j = 1; j < diff[0].length; j++) {\n\t\t\t\tdiff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];\n\t\t\t\tans = Math.max(ans, diff[i][j]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// [50,70,30,70,30,60] 长度6\n\t// [30,30,50,60,70,70]\n\t// [30,50,60,70] 60 -> 3\n\t//  1  2  3  4\n\t// 长度4，\n \tpublic static int sort(long[] nums) {\n\t\tArrays.sort(nums);\n\t\tint size = 1;\n\t\tfor (int i = 1; i < nums.length; i++) {\n\t\t\tif (nums[i] != nums[size - 1]) {\n\t\t\t\tnums[size++] = nums[i];\n\t\t\t}\n\t\t}\n\t\treturn size;\n\t}\n\n \t// nums 有序数组，有效长度是size，0~size-1范围上无重复值\n \t// 已知v一定在nums[0~size-1]，返回v所对应的编号\n\tpublic static int rank(long[] nums, long v, int size) {\n\t\tint l = 0;\n\t\tint r = size - 1;\n\t\tint m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) / 2;\n\t\t\tif (nums[m] >= v) {\n\t\t\t\tans = m;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans + 1;\n\t}\n\n\t// 二维差分\n\tpublic static void add(int[][] diff, int a, int b, int c, int d) {\n\t\tdiff[a][b] += 1;\n\t\tdiff[c + 1][d + 1] += 1;\n\t\tdiff[c + 1][b] -= 1;\n\t\tdiff[a][d + 1] -= 1;\n\t}\n\n}\n	模板：Code05_StrongestForceField.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
271cf4d4-0c0a-4aff-93d5-4bfb0778da06	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class066;\n\nimport java.util.Arrays;\n\n// 斐波那契数\n// 斐波那契数 （通常用 F(n) 表示）形成的序列称为 斐波那契数列\n// 该数列由 0 和 1 开始，后面的每一项数字都是前面两项数字的和。\n// 也就是：F(0) = 0，F(1) = 1\n// F(n) = F(n - 1) + F(n - 2)，其中 n > 1\n// 给定 n ，请计算 F(n)\n// 测试链接 : https://leetcode.cn/problems/fibonacci-number/\n// 注意：最优解来自矩阵快速幂，时间复杂度可以做到O(log n)\n// 后续课程一定会讲述！本节课不涉及！\npublic class Code01_FibonacciNumber {\n\n\tpublic static int fib1(int n) {\n\t\treturn f1(n);\n\t}\n\n\tpublic static int f1(int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (i == 1) {\n\t\t\treturn 1;\n\t\t}\n\t\treturn f1(i - 1) + f1(i - 2);\n\t}\n\n\tpublic static int fib2(int n) {\n\t\tint[] dp = new int[n + 1];\n\t\tArrays.fill(dp, -1);\n\t\treturn f2(n, dp);\n\t}\n\n\tpublic static int f2(int i, int[] dp) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (i == 1) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (dp[i] != -1) {\n\t\t\treturn dp[i];\n\t\t}\n\t\tint ans = f2(i - 1, dp) + f2(i - 2, dp);\n\t\tdp[i] = ans;\n\t\treturn ans;\n\t}\n\n\tpublic static int fib3(int n) {\n\t\tif (n == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (n == 1) {\n\t\t\treturn 1;\n\t\t}\n\t\tint[] dp = new int[n + 1];\n\t\tdp[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tdp[i] = dp[i - 1] + dp[i - 2];\n\t\t}\n\t\treturn dp[n];\n\t}\n\n\tpublic static int fib4(int n) {\n\t\tif (n == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (n == 1) {\n\t\t\treturn 1;\n\t\t}\n\t\tint lastLast = 0, last = 1;\n\t\tfor (int i = 2, cur; i <= n; i++) {\n\t\t\tcur = lastLast + last;\n\t\t\tlastLast = last;\n\t\t\tlast = cur;\n\t\t}\n\t\treturn last;\n\t}\n\n}\n	模板：Code01_FibonacciNumber.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cc15fef1-6b1e-4c3a-88c3-8ad656294ea5	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class066;\n\nimport java.util.Arrays;\n\n// 最低票价\n// 在一个火车旅行很受欢迎的国度，你提前一年计划了一些火车旅行\n// 在接下来的一年里，你要旅行的日子将以一个名为 days 的数组给出\n// 每一项是一个从 1 到 365 的整数\n// 火车票有 三种不同的销售方式\n// 一张 为期1天 的通行证售价为 costs[0] 美元\n// 一张 为期7天 的通行证售价为 costs[1] 美元\n// 一张 为期30天 的通行证售价为 costs[2] 美元\n// 通行证允许数天无限制的旅行\n// 例如，如果我们在第 2 天获得一张 为期 7 天 的通行证\n// 那么我们可以连着旅行 7 天(第2~8天)\n// 返回 你想要完成在给定的列表 days 中列出的每一天的旅行所需要的最低消费\n// 测试链接 : https://leetcode.cn/problems/minimum-cost-for-tickets/\npublic class Code02_MinimumCostForTickets {\n\n\t// 无论提交什么方法都带着这个数组      0  1  2\n\tpublic static int[] durations = { 1, 7, 30 };\n\n\t// 暴力尝试\n\tpublic static int mincostTickets1(int[] days, int[] costs) {\n\t\treturn f1(days, costs, 0);\n\t}\n\n\t// days[i..... 最少花费是多少 \n\tpublic static int f1(int[] days, int[] costs, int i) {\n\t\tif (i == days.length) {\n\t\t\t// 后续已经无旅行了\n\t\t\treturn 0;\n\t\t}\n\t\t// i下标 : 第days[i]天，有一场旅行\n\t\t// i.... 最少花费是多少 \n\t\tint ans = Integer.MAX_VALUE;\n\t\tfor (int k = 0, j = i; k < 3; k++) {\n\t\t\t// k是方案编号 : 0 1 2\n\t\t\twhile (j < days.length && days[i] + durations[k] > days[j]) {\n\t\t\t\t// 因为方案2持续的天数最多，30天\n\t\t\t\t// 所以while循环最多执行30次\n\t\t\t\t// 枚举行为可以认为是O(1)\n\t\t\t\tj++;\n\t\t\t}\n\t\t\tans = Math.min(ans, costs[k] + f1(days, costs, j));\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 暴力尝试改记忆化搜索\n\t// 从顶到底的动态规划\n\tpublic static int mincostTickets2(int[] days, int[] costs) {\n\t\tint[] dp = new int[days.length];\n\t\tfor (int i = 0; i < days.length; i++) {\n\t\t\tdp[i] = Integer.MAX_VALUE;\n\t\t}\n\t\treturn f2(days, costs, 0, dp);\n\t}\n\n\tpublic static int f2(int[] days, int[] costs, int i, int[] dp) {\n\t\tif (i == days.length) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (dp[i] != Integer.MAX_VALUE) {\n\t\t\treturn dp[i];\n\t\t}\n\t\tint ans = Integer.MAX_VALUE;\n\t\tfor (int k = 0, j = i; k < 3; k++) {\n\t\t\twhile (j < days.length && days[i] + durations[k] > days[j]) {\n\t\t\t\tj++;\n\t\t\t}\n\t\t\tans = Math.min(ans, costs[k] + f2(days, costs, j, dp));\n\t\t}\n\t\tdp[i] = ans;\n\t\treturn ans;\n\t}\n\n\t// 严格位置依赖的动态规划\n\t// 从底到顶的动态规划\n\tpublic static int MAXN = 366;\n\n\tpublic static int[] dp = new int[MAXN];\n\n\tpublic static int mincostTickets3(int[] days, int[] costs) {\n\t\tint n = days.length;\n\t\tArrays.fill(dp, 0, n + 1, Integer.MAX_VALUE);\n\t\tdp[n] = 0;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\tfor (int k = 0, j = i; k < 3; k++) {\n\t\t\t\twhile (j < days.length && days[i] + durations[k] > days[j]) {\n\t\t\t\t\tj++;\n\t\t\t\t}\n\t\t\t\tdp[i] = Math.min(dp[i], costs[k] + dp[j]);\n\t\t\t}\n\t\t}\n\t\treturn dp[0];\n\t}\n\n}\n	模板：Code02_MinimumCostForTickets.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4e4b1237-bccf-417e-a2a6-bdaf17f99e89	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class066;\n\nimport java.util.Arrays;\n\n// 解码方法\n// 一条包含字母 A-Z 的消息通过以下映射进行了 编码 ：\n// 'A' -> "1"\n// 'B' -> "2"\n// ...\n// 'Z' -> "26"\n// 要 解码 已编码的消息，所有数字必须基于上述映射的方法，反向映射回字母（可能有多种方法）\n// 例如，"11106" 可以映射为："AAJF"、"KJF"\n// 注意，消息不能分组为(1 11 06)，因为 "06" 不能映射为 "F"\n// 这是由于 "6" 和 "06" 在映射中并不等价\n// 给你一个只含数字的 非空 字符串 s ，请计算并返回 解码 方法的 总数\n// 题目数据保证答案肯定是一个 32位 的整数\n// 测试链接 : https://leetcode.cn/problems/decode-ways/\npublic class Code03_DecodeWays {\n\n\t// 暴力尝试\n\tpublic static int numDecodings1(String s) {\n\t\treturn f1(s.toCharArray(), 0);\n\t}\n\n\t// s : 数字字符串 \n\t// s[i....]有多少种有效的转化方案\n\tpublic static int f1(char[] s, int i) {\n\t\tif (i == s.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tint ans;\n\t\tif (s[i] == '0') {\n\t\t\tans = 0;\n\t\t} else {\n\t\t\tans = f1(s, i + 1);\n\t\t\tif (i + 1 < s.length && ((s[i] - '0') * 10 + s[i + 1] - '0') <= 26) {\n\t\t\t\tans += f1(s, i + 2);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 暴力尝试改记忆化搜索\n\tpublic static int numDecodings2(String s) {\n\t\tint[] dp = new int[s.length()];\n\t\tArrays.fill(dp, -1);\n\t\treturn f2(s.toCharArray(), 0, dp);\n\t}\n\n\tpublic static int f2(char[] s, int i, int[] dp) {\n\t\tif (i == s.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (dp[i] != -1) {\n\t\t\treturn dp[i];\n\t\t}\n\t\tint ans;\n\t\tif (s[i] == '0') {\n\t\t\tans = 0;\n\t\t} else {\n\t\t\tans = f2(s, i + 1, dp);\n\t\t\tif (i + 1 < s.length && ((s[i] - '0') * 10 + s[i + 1] - '0') <= 26) {\n\t\t\t\tans += f2(s, i + 2, dp);\n\t\t\t}\n\t\t}\n\t\tdp[i] = ans;\n\t\treturn ans;\n\t}\n\n\t// 严格位置依赖的动态规划\n\tpublic static int numDecodings3(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tint n = s.length;\n\t\tint[] dp = new int[n + 1];\n\t\tdp[n] = 1;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\tif (s[i] == '0') {\n\t\t\t\tdp[i] = 0;\n\t\t\t} else {\n\t\t\t\tdp[i] = dp[i + 1];\n\t\t\t\tif (i + 1 < s.length && ((s[i] - '0') * 10 + s[i + 1] - '0') <= 26) {\n\t\t\t\t\tdp[i] += dp[i + 2];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[0];\n\t}\n\n\t// 严格位置依赖的动态规划 + 空间压缩\n\tpublic static int numDecodings4(String s) {\n\t\t// dp[i+1]\n\t\tint next = 1;\n\t\t// dp[i+2]\n\t\tint nextNext = 0;\n\t\tfor (int i = s.length() - 1, cur; i >= 0; i--) {\n\t\t\tif (s.charAt(i) == '0') {\n\t\t\t\tcur = 0;\n\t\t\t} else {\n\t\t\t\tcur = next;\n\t\t\t\tif (i + 1 < s.length() && ((s.charAt(i) - '0') * 10 + s.charAt(i + 1) - '0') <= 26) {\n\t\t\t\t\tcur += nextNext;\n\t\t\t\t}\n\t\t\t}\n\t\t\tnextNext = next;\n\t\t\tnext = cur;\n\t\t}\n\t\treturn next;\n\t}\n\n}\n	模板：Code03_DecodeWays.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5fdb4baa-70f2-4f40-ae8d-bf5e72dfcf14	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class066;\n\nimport java.util.Arrays;\n\n// 解码方法 II\n// 一条包含字母 A-Z 的消息通过以下的方式进行了 编码 ：\n// 'A' -> "1"\n// 'B' -> "2"\n// ...\n// 'Z' -> "26"\n// 要 解码 一条已编码的消息，所有的数字都必须分组\n// 然后按原来的编码方案反向映射回字母（可能存在多种方式）\n// 例如，"11106" 可以映射为："AAJF"、"KJF"\n// 注意，像 (1 11 06) 这样的分组是无效的，"06"不可以映射为'F'\n// 除了上面描述的数字字母映射方案，编码消息中可能包含 '*' 字符\n// 可以表示从 '1' 到 '9' 的任一数字（不包括 '0'）\n// 例如，"1*" 可以表示 "11"、"12"、"13"、"14"、"15"、"16"、"17"、"18" 或 "19"\n// 对 "1*" 进行解码，相当于解码该字符串可以表示的任何编码消息\n// 给你一个字符串 s ，由数字和 '*' 字符组成，返回 解码 该字符串的方法 数目\n// 由于答案数目可能非常大，答案对 1000000007 取模\n// 测试链接 : https://leetcode.cn/problems/decode-ways-ii/\npublic class Code04_DecodeWaysII {\n\n\t// 没有取模逻辑\n\t// 最自然的暴力尝试\n\tpublic static int numDecodings1(String str) {\n\t\treturn f1(str.toCharArray(), 0);\n\t}\n\n\t// s[i....] 有多少种有效转化\n\tpublic static int f1(char[] s, int i) {\n\t\tif (i == s.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (s[i] == '0') {\n\t\t\treturn 0;\n\t\t}\n\t\t// s[i] != '0'\n\t\t// 2) i想单独转\n\t\tint ans = f1(s, i + 1) * (s[i] == '*' ? 9 : 1);\n\t\t// 3) i i+1 一起转化 <= 26\n\t\tif (i + 1 < s.length) {\n\t\t\t// 有i+1位置\n\t\t\tif (s[i] != '*') {\n\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t// num num\n\t\t\t\t\t//  i  i+1\n\t\t\t\t\tif ((s[i] - '0') * 10 + s[i + 1] - '0' <= 26) {\n\t\t\t\t\t\tans += f1(s, i + 2);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\t// num  *\n\t\t\t\t\t//  i  i+1\n\t\t\t\t\tif (s[i] == '1') {\n\t\t\t\t\t\tans += f1(s, i + 2) * 9;\n\t\t\t\t\t}\n\t\t\t\t\tif (s[i] == '2') {\n\t\t\t\t\t\tans += f1(s, i + 2) * 6;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t// *  num\n\t\t\t\t\t// i  i+1\n\t\t\t\t\tif (s[i + 1] <= '6') {\n\t\t\t\t\t\tans += f1(s, i + 2) * 2;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tans += f1(s, i + 2);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\t// *  *\n\t\t\t\t\t// i  i+1\n\t\t\t\t\t// 11 12 ... 19 21 22 ... 26 -> 一共15种可能\n\t\t\t\t\t// 没有10、20，因为*只能变1~9，并不包括0\n\t\t\t\t\tans += f1(s, i + 2) * 15;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long mod = 1000000007;\n\n\tpublic static int numDecodings2(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tlong[] dp = new long[s.length];\n\t\tArrays.fill(dp, -1);\n\t\treturn (int) f2(s, 0, dp);\n\t}\n\n\tpublic static long f2(char[] s, int i, long[] dp) {\n\t\tif (i == s.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (s[i] == '0') {\n\t\t\treturn 0;\n\t\t}\n\t\tif (dp[i] != -1) {\n\t\t\treturn dp[i];\n\t\t}\n\t\tlong ans = f2(s, i + 1, dp) * (s[i] == '*' ? 9 : 1);\n\t\tif (i + 1 < s.length) {\n\t\t\tif (s[i] != '*') {\n\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\tif ((s[i] - '0') * 10 + s[i + 1] - '0' <= 26) {\n\t\t\t\t\t\tans += f2(s, i + 2, dp);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (s[i] == '1') {\n\t\t\t\t\t\tans += f2(s, i + 2, dp) * 9;\n\t\t\t\t\t}\n\t\t\t\t\tif (s[i] == '2') {\n\t\t\t\t\t\tans += f2(s, i + 2, dp) * 6;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\tif (s[i + 1] <= '6') {\n\t\t\t\t\t\tans += f2(s, i + 2, dp) * 2;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tans += f2(s, i + 2, dp);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tans += f2(s, i + 2, dp) * 15;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tans %= mod;\n\t\tdp[i] = ans;\n\t\treturn ans;\n\t}\n\n\tpublic static int numDecodings3(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tint n = s.length;\n\t\tlong[] dp = new long[n + 1];\n\t\tdp[n] = 1;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\tif (s[i] != '0') {\n\t\t\t\tdp[i] = (s[i] == '*' ? 9 : 1) * dp[i + 1];\n\t\t\t\tif (i + 1 < n) {\n\t\t\t\t\tif (s[i] != '*') {\n\t\t\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t\t\tif ((s[i] - '0') * 10 + s[i + 1] - '0' <= 26) {\n\t\t\t\t\t\t\t\tdp[i] += dp[i + 2];\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tif (s[i] == '1') {\n\t\t\t\t\t\t\t\tdp[i] += dp[i + 2] * 9;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tif (s[i] == '2') {\n\t\t\t\t\t\t\t\tdp[i] += dp[i + 2] * 6;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t} else {\n\t\t\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t\t\tif (s[i + 1] <= '6') {\n\t\t\t\t\t\t\t\tdp[i] += dp[i + 2] * 2;\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tdp[i] += dp[i + 2];\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tdp[i] += dp[i + 2] * 15;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tdp[i] %= mod;\n\t\t\t}\n\t\t}\n\t\treturn (int) dp[0];\n\t}\n\n\tpublic static int numDecodings4(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tint n = s.length;\n\t\tlong cur = 0, next = 1, nextNext = 0;\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\tif (s[i] != '0') {\n\t\t\t\tcur = (s[i] == '*' ? 9 : 1) * next;\n\t\t\t\tif (i + 1 < n) {\n\t\t\t\t\tif (s[i] != '*') {\n\t\t\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t\t\tif ((s[i] - '0') * 10 + s[i + 1] - '0' <= 26) {\n\t\t\t\t\t\t\t\tcur += nextNext;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tif (s[i] == '1') {\n\t\t\t\t\t\t\t\tcur += nextNext * 9;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tif (s[i] == '2') {\n\t\t\t\t\t\t\t\tcur += nextNext * 6;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t} else {\n\t\t\t\t\t\tif (s[i + 1] != '*') {\n\t\t\t\t\t\t\tif (s[i + 1] <= '6') {\n\t\t\t\t\t\t\t\tcur += nextNext * 2;\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tcur += nextNext;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tcur += nextNext * 15;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tcur %= mod;\n\t\t\t}\n\t\t\tnextNext = next;\n\t\t\tnext = cur;\n\t\t\tcur = 0;\n\t\t}\n\t\treturn (int) next;\n\t}\n\n}\n	模板：Code04_DecodeWaysII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2cb55a19-6185-426a-a906-544e979b9f56	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class066;\n\n// 丑数 II\n// 给你一个整数 n ，请你找出并返回第 n 个 丑数\n// 丑数 就是只包含质因数 2、3 或 5 的正整数\n// 测试链接 : https://leetcode.cn/problems/ugly-number-ii/\npublic class Code05_UglyNumberII {\n\n\t// 时间复杂度O(n)，n代表第n个丑数\n\tpublic static int nthUglyNumber(int n) {\n\t\t// dp 0 1 2 ...  n\n\t\t//      1 2 ...  ?\n\t\tint[] dp = new int[n + 1];\n\t\tdp[1] = 1;\n\t\tfor (int i = 2, i2 = 1, i3 = 1, i5 = 1, a, b, c, cur; i <= n; i++) {\n\t\t\ta = dp[i2] * 2;\n\t\t\tb = dp[i3] * 3;\n\t\t\tc = dp[i5] * 5;\n\t\t\tcur = Math.min(Math.min(a, b), c);\n\t\t\tif (cur == a) {\n\t\t\t\ti2++;\n\t\t\t}\n\t\t\tif (cur == b) {\n\t\t\t\ti3++;\n\t\t\t}\n\t\t\tif (cur == c) {\n\t\t\t\ti5++;\n\t\t\t}\n\t\t\tdp[i] = cur;\n\t\t}\n\t\treturn dp[n];\n\t}\n\n}\n	模板：Code05_UglyNumberII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
