287a03bd-2fc5-4c9b-b401-7797eb08870d	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class067;\n\n// 最小路径和\n// 给定一个包含非负整数的 m x n 网格 grid\n// 请找出一条从左上角到右下角的路径，使得路径上的数字总和为最小。\n// 说明：每次只能向下或者向右移动一步。\n// 测试链接 : https://leetcode.cn/problems/minimum-path-sum/\npublic class Code01_MinimumPathSum {\n\n\t// 暴力递归\n\tpublic static int minPathSum1(int[][] grid) {\n\t\treturn f1(grid, grid.length - 1, grid[0].length - 1);\n\t}\n\n\t// 从(0,0)到(i,j)最小路径和\n\t// 一定每次只能向右或者向下\n\tpublic static int f1(int[][] grid, int i, int j) {\n\t\tif (i == 0 && j == 0) {\n\t\t\treturn grid[0][0];\n\t\t}\n\t\tint up = Integer.MAX_VALUE;\n\t\tint left = Integer.MAX_VALUE;\n\t\tif (i - 1 >= 0) {\n\t\t\tup = f1(grid, i - 1, j);\n\t\t}\n\t\tif (j - 1 >= 0) {\n\t\t\tleft = f1(grid, i, j - 1);\n\t\t}\n\t\treturn grid[i][j] + Math.min(up, left);\n\t}\n\n\t// 记忆化搜索\n\tpublic static int minPathSum2(int[][] grid) {\n\t\tint n = grid.length;\n\t\tint m = grid[0].length;\n\t\tint[][] dp = new int[n][m];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tdp[i][j] = -1;\n\t\t\t}\n\t\t}\n\t\treturn f2(grid, grid.length - 1, grid[0].length - 1, dp);\n\t}\n\n\tpublic static int f2(int[][] grid, int i, int j, int[][] dp) {\n\t\tif (dp[i][j] != -1) {\n\t\t\treturn dp[i][j];\n\t\t}\n\t\tint ans;\n\t\tif (i == 0 && j == 0) {\n\t\t\tans = grid[0][0];\n\t\t} else {\n\t\t\tint up = Integer.MAX_VALUE;\n\t\t\tint left = Integer.MAX_VALUE;\n\t\t\tif (i - 1 >= 0) {\n\t\t\t\tup = f2(grid, i - 1, j, dp);\n\t\t\t}\n\t\t\tif (j - 1 >= 0) {\n\t\t\t\tleft = f2(grid, i, j - 1, dp);\n\t\t\t}\n\t\t\tans = grid[i][j] + Math.min(up, left);\n\t\t}\n\t\tdp[i][j] = ans;\n\t\treturn ans;\n\t}\n\n\t// 严格位置依赖的动态规划\n\tpublic static int minPathSum3(int[][] grid) {\n\t\tint n = grid.length;\n\t\tint m = grid[0].length;\n\t\tint[][] dp = new int[n][m];\n\t\tdp[0][0] = grid[0][0];\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tdp[i][0] = dp[i - 1][0] + grid[i][0];\n\t\t}\n\t\tfor (int j = 1; j < m; j++) {\n\t\t\tdp[0][j] = dp[0][j - 1] + grid[0][j];\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tfor (int j = 1; j < m; j++) {\n\t\t\t\tdp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];\n\t\t\t}\n\t\t}\n\t\treturn dp[n - 1][m - 1];\n\t}\n\n\t// 严格位置依赖的动态规划 + 空间压缩技巧\n\tpublic static int minPathSum4(int[][] grid) {\n\t\tint n = grid.length;\n\t\tint m = grid[0].length;\n\t\t// 先让dp表，变成想象中的表的第0行的数据\n\t\tint[] dp = new int[m];\n\t\tdp[0] = grid[0][0];\n\t\tfor (int j = 1; j < m; j++) {\n\t\t\tdp[j] = dp[j - 1] + grid[0][j];\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\t// i = 1，dp表变成想象中二维表的第1行的数据\n\t\t\t// i = 2，dp表变成想象中二维表的第2行的数据\n\t\t\t// i = 3，dp表变成想象中二维表的第3行的数据\n\t\t\t// ...\n\t\t\t// i = n-1，dp表变成想象中二维表的第n-1行的数据\n\t\t\tdp[0] += grid[i][0];\n\t\t\tfor (int j = 1; j < m; j++) {\n\t\t\t\tdp[j] = Math.min(dp[j - 1], dp[j]) + grid[i][j];\n\t\t\t}\n\t\t}\n\t\treturn dp[m - 1];\n\t}\n\n}\n	模板：Code01_MinimumPathSum.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
54f9ddba-fb87-4361-9d34-b01d10192ca7	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class067;\n\n// 单词搜索（无法改成动态规划）\n// 给定一个 m x n 二维字符网格 board 和一个字符串单词 word\n// 如果 word 存在于网格中，返回 true ；否则，返回 false 。\n// 单词必须按照字母顺序，通过相邻的单元格内的字母构成\n// 其中"相邻"单元格是那些水平相邻或垂直相邻的单元格\n// 同一个单元格内的字母不允许被重复使用\n// 测试链接 : https://leetcode.cn/problems/word-search/\npublic class Code02_WordSearch {\n\n\tpublic static boolean exist(char[][] board, String word) {\n\t\tchar[] w = word.toCharArray();\n\t\tfor (int i = 0; i < board.length; i++) {\n\t\t\tfor (int j = 0; j < board[0].length; j++) {\n\t\t\t\tif (f(board, i, j, w, 0)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\t// 因为board会改其中的字符\n\t// 用来标记哪些字符无法再用\n\t// 带路径的递归无法改成动态规划或者说没必要\n\t// 从(i,j)出发，来到w[k]，请问后续能不能把word走出来w[k...]\n\tpublic static boolean f(char[][] b, int i, int j, char[] w, int k) {\n\t\tif (k == w.length) {\n\t\t\treturn true;\n\t\t}\n\t\tif (i < 0 || i == b.length || j < 0 || j == b[0].length || b[i][j] != w[k]) {\n\t\t\treturn false;\n\t\t}\n\t\t// 不越界，b[i][j] == w[k]\n\t\tchar tmp = b[i][j];\n\t\tb[i][j] = 0;\n\t\tboolean ans = f(b, i - 1, j, w, k + 1) \n\t\t\t\t|| f(b, i + 1, j, w, k + 1) \n\t\t\t\t|| f(b, i, j - 1, w, k + 1)\n\t\t\t\t|| f(b, i, j + 1, w, k + 1);\n\t\tb[i][j] = tmp;\n\t\treturn ans;\n\t}\n\n}\n	模板：Code02_WordSearch.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e1a4a592-feb8-40bd-8fa3-9a65dcefdc58	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class067;\n\n// 最长公共子序列\n// 给定两个字符串text1和text2\n// 返回这两个字符串的最长 公共子序列 的长度\n// 如果不存在公共子序列，返回0\n// 两个字符串的 公共子序列 是这两个字符串所共同拥有的子序列\n// 测试链接 : https://leetcode.cn/problems/longest-common-subsequence/\npublic class Code03_LongestCommonSubsequence {\n\n\tpublic static int longestCommonSubsequence1(String str1, String str2) {\n\t\tchar[] s1 = str1.toCharArray();\n\t\tchar[] s2 = str2.toCharArray();\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\treturn f1(s1, s2, n - 1, m - 1);\n\t}\n\n\t// s1[0....i1]与s2[0....i2]最长公共子序列长度\n\tpublic static int f1(char[] s1, char[] s2, int i1, int i2) {\n\t\tif (i1 < 0 || i2 < 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tint p1 = f1(s1, s2, i1 - 1, i2 - 1);\n\t\tint p2 = f1(s1, s2, i1 - 1, i2);\n\t\tint p3 = f1(s1, s2, i1, i2 - 1);\n\t\tint p4 = s1[i1] == s2[i2] ? (p1 + 1) : 0;\n\t\treturn Math.max(Math.max(p1, p2), Math.max(p3, p4));\n\t}\n\n\t// 为了避免很多边界讨论\n\t// 很多时候往往不用下标来定义尝试，而是用长度来定义尝试\n\t// 因为长度最短是0，而下标越界的话讨论起来就比较麻烦\n\tpublic static int longestCommonSubsequence2(String str1, String str2) {\n\t\tchar[] s1 = str1.toCharArray();\n\t\tchar[] s2 = str2.toCharArray();\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\treturn f2(s1, s2, n, m);\n\t}\n\n\t// s1[前缀长度为len1]对应s2[前缀长度为len2]\n\t// 最长公共子序列长度\n\tpublic static int f2(char[] s1, char[] s2, int len1, int len2) {\n\t\tif (len1 == 0 || len2 == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tint ans;\n\t\tif (s1[len1 - 1] == s2[len2 - 1]) {\n\t\t\tans = f2(s1, s2, len1 - 1, len2 - 1) + 1;\n\t\t} else {\n\t\t\tans = Math.max(f2(s1, s2, len1 - 1, len2), f2(s1, s2, len1, len2 - 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 记忆化搜索\n\tpublic static int longestCommonSubsequence3(String str1, String str2) {\n\t\tchar[] s1 = str1.toCharArray();\n\t\tchar[] s2 = str2.toCharArray();\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\tint[][] dp = new int[n + 1][m + 1];\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tfor (int j = 0; j <= m; j++) {\n\t\t\t\tdp[i][j] = -1;\n\t\t\t}\n\t\t}\n\t\treturn f3(s1, s2, n, m, dp);\n\t}\n\n\tpublic static int f3(char[] s1, char[] s2, int len1, int len2, int[][] dp) {\n\t\tif (len1 == 0 || len2 == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (dp[len1][len2] != -1) {\n\t\t\treturn dp[len1][len2];\n\t\t}\n\t\tint ans;\n\t\tif (s1[len1 - 1] == s2[len2 - 1]) {\n\t\t\tans = f3(s1, s2, len1 - 1, len2 - 1, dp) + 1;\n\t\t} else {\n\t\t\tans = Math.max(f3(s1, s2, len1 - 1, len2, dp), f3(s1, s2, len1, len2 - 1, dp));\n\t\t}\n\t\tdp[len1][len2] = ans;\n\t\treturn ans;\n\t}\n\n\t// 严格位置依赖的动态规划\n\tpublic static int longestCommonSubsequence4(String str1, String str2) {\n\t\tchar[] s1 = str1.toCharArray();\n\t\tchar[] s2 = str2.toCharArray();\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\tint[][] dp = new int[n + 1][m + 1];\n\t\tfor (int len1 = 1; len1 <= n; len1++) {\n\t\t\tfor (int len2 = 1; len2 <= m; len2++) {\n\t\t\t\tif (s1[len1 - 1] == s2[len2 - 1]) {\n\t\t\t\t\tdp[len1][len2] = 1 + dp[len1 - 1][len2 - 1];\n\t\t\t\t} else {\n\t\t\t\t\tdp[len1][len2] = Math.max(dp[len1 - 1][len2], dp[len1][len2 - 1]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[n][m];\n\t}\n\n\t// 严格位置依赖的动态规划 + 空间压缩\n\tpublic static int longestCommonSubsequence5(String str1, String str2) {\n\t\tchar[] s1, s2;\n\t\tif (str1.length() >= str2.length()) {\n\t\t\ts1 = str1.toCharArray();\n\t\t\ts2 = str2.toCharArray();\n\t\t} else {\n\t\t\ts1 = str2.toCharArray();\n\t\t\ts2 = str1.toCharArray();\n\t\t}\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\tint[] dp = new int[m + 1];\n\t\tfor (int len1 = 1; len1 <= n; len1++) {\n\t\t\tint leftUp = 0, backup;\n\t\t\tfor (int len2 = 1; len2 <= m; len2++) {\n\t\t\t\tbackup = dp[len2];\n\t\t\t\tif (s1[len1 - 1] == s2[len2 - 1]) {\n\t\t\t\t\tdp[len2] = 1 + leftUp;\n\t\t\t\t} else {\n\t\t\t\t\tdp[len2] = Math.max(dp[len2], dp[len2 - 1]);\n\t\t\t\t}\n\t\t\t\tleftUp = backup;\n\t\t\t}\n\t\t}\n\t\treturn dp[m];\n\t}\n\n}\n	模板：Code03_LongestCommonSubsequence.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
