tdp[i][0] = i * b;\n\t\t}\n\t\tfor (int j = 1; j <= m; j++) {\n\t\t\tdp[0][j] = j * a;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tif (s1[i - 1] == s2[j - 1]) {\n\t\t\t\t\tdp[i][j] = dp[i - 1][j - 1];\n\t\t\t\t} else {\n\t\t\t\t\tdp[i][j] = Math.min(Math.min(dp[i - 1][j] + b, dp[i][j - 1] + a), dp[i - 1][j - 1] + c);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[n][m];\n\t}\n\n\t// 空间压缩\n\tpublic static int editDistance3(String str1, String str2, int a, int b, int c) {\n\t\tchar[] s1 = str1.toCharArray();\n\t\tchar[] s2 = str2.toCharArray();\n\t\tint n = s1.length;\n\t\tint m = s2.length;\n\t\tint[] dp = new int[m + 1];\n\t\tfor (int j = 1; j <= m; j++) {\n\t\t\tdp[j] = j * a;\n\t\t}\n\t\tfor (int i = 1, leftUp, backUp; i <= n; i++) {\n\t\t\tleftUp = (i - 1) * b;\n\t\t\tdp[0] = i * b;\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tbackUp = dp[j];\n\t\t\t\tif (s1[i - 1] == s2[j - 1]) {\n\t\t\t\t\tdp[j] = leftUp;\n\t\t\t\t} else {\n\t\t\t\t\tdp[j] = Math.min(Math.min(dp[j] + b, dp[j - 1] + a), leftUp + c);\n\t\t\t\t}\n\t\t\t\tleftUp = backUp;\n\t\t\t}\n\t\t}\n\t\treturn dp[m];\n\t}\n\n}\n	模板：Code02_EditDistance.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
