d290745f-6566-4a39-af48-c5ba17c96407	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class127;\n\n// 感谢热心的同学，找到了题目3的在线测试\n// 测试链接 : https://codeforces.com/problemset/problem/1215/B\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_MultiplyPositiveNegative2 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 结果可能很大，所以用long类型\n\tpublic static long ans1, ans2;\n\n\tpublic static void compute() {\n\t\tint[] cnt = new int[2];\n\t\tcnt[0] = 1;\n\t\tcnt[1] = 0;\n\t\tans1 = ans2 = 0;\n\t\tfor (int i = 1, cur = 0; i <= n; i++) {\n\t\t\tcur ^= arr[i] > 0 ? 0 : 1;\n\t\t\tans1 += cnt[cur];\n\t\t\tans2 += cnt[cur ^ 1];\n\t\t\tcnt[cur]++;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tcompute();\n\t\tout.println(ans2 + " " + ans1);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_MultiplyPositiveNegative2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0d4f1e01-e389-4507-93d5-9095384b523d	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class127;\n\n// 相邻与结果不为0的最长子序列\n// 给定一个长度为n的数组arr，你可以随意选择数字组成子序列\n// 但是要求任意相邻的两个数&的结果不能是0，这样的子序列才是合法的\n// 返回最长合法子序列的长度\n// 1 <= n <= 10^5\n// 0 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4310\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_LongestAddNotZero {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] pre = new int[32];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute() {\n\t\tArrays.fill(pre, 0);\n\t\tfor (int i = 0, num, cur; i < n; i++) {\n\t\t\tnum = arr[i];\n\t\t\tcur = 1;\n\t\t\tfor (int j = 0; j < 31; j++) {\n\t\t\t\tif (((num >> j) & 1) == 1) {\n\t\t\t\t\tcur = Math.max(cur, pre[j] + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int j = 0; j < 31; j++) {\n\t\t\t\tif (((num >> j) & 1) == 1) {\n\t\t\t\t\tpre[j] = Math.max(pre[j], cur);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int j = 0; j < 31; j++) {\n\t\t\tans = Math.max(ans, pre[j]);\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_LongestAddNotZero.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8460d9e8-d883-4991-8576-489584832e0c	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class127;\n\n// 摆盘子的方法\n// 一共有n个盘子k种菜，所有盘子排成一排，每个盘子只能放一种菜\n// 要求最多连续两个盘子菜品一样，更长的重复出现是不允许的\n// 返回摆盘的方法数，答案对 1000000007 取模\n// 1 <= n <= 1000\n// 1 <= k <= 1000\n// 来自真实大厂笔试，对数器验证\npublic class Code05_WaysOfArrangePlates {\n\n\tpublic static int MOD = 1000000007;\n\n\t// 正式方法的尝试思路\n\tpublic static int dp1(int n, int k) {\n\t\tif (n == 1) {\n\t\t\treturn k;\n\t\t}\n\t\treturn (int) ((((long) f1(n - 1, k) + f1(n - 2, k)) * k) % MOD);\n\t}\n\n\tpublic static int f1(int i, int k) {\n\t\tif (i == 0) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (i == 1) {\n\t\t\treturn k - 1;\n\t\t}\n\t\tlong p1 = f1(i - 1, k);\n\t\tlong p2 = f1(i - 2, k);\n\t\treturn (int) (((p1 + p2) * (k - 1)) % MOD);\n\t}\n\n\t// 正式方法的普通动态规划版本\n\t// 时间复杂度O(n)\n\tpublic static int dp2(int n, int k) {\n\t\tif (n == 1) {\n\t\t\treturn k;\n\t\t}\n\t\tint[] dp = new int[n];\n\t\tdp[0] = 1;\n\t\tdp[1] = k - 1;\n\t\tfor (int i = 2; i < n; i++) {\n\t\t\tlong p1 = dp[i - 1];\n\t\t\tlong p2 = dp[i - 2];\n\t\t\tdp[i] = (int) (((p1 + p2) * (k - 1)) % MOD);\n\t\t}\n\t\treturn (int) ((((long) dp[n - 1] + dp[n - 2]) * k) % MOD);\n\t}\n\n\t// 最优解的版本，动态规划 + 矩阵快速幂优化\n\t// 时间复杂度O(log n)\n\t// 不会的同学看讲解098\n\tpublic static int dp3(int n, int k) {\n\t\tif (n == 1) {\n\t\t\treturn k;\n\t\t}\n\t\tint s = k - 1;\n\t\tint[][] start = { { 1, s } };\n\t\tint[][] base = { { 0, s }, { 1, s } };\n\t\tint[][] ans = multiply(start, power(base, n - 2));\n\t\treturn (int) ((((long) ans[0][0] + ans[0][1]) * k) % MOD);\n\t}\n\n\tpublic static int[][] multiply(int[][] a, int[][] b) {\n\t\tint n = a.length;\n\t\tint m = b[0].length;\n\t\tint k = a[0].length;\n\t\tint[][] ans = new int[n][m];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tfor (int c = 0; c < k; c++) {\n\t\t\t\t\tans[i][j] = (int) (((long) ans[i][j] + (long) a[i][c] * b[c][j]) % MOD);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int[][] power(int[][] m, int p) {\n\t\tint n = m.length;\n\t\tint[][] ans = new int[n][n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i][i] = 1;\n\t\t}\n\t\tfor (; p != 0; p >>= 1) {\n\t\t\tif ((p & 1) != 0) {\n\t\t\t\tans = multiply(ans, m);\n\t\t\t}\n\t\t\tm = multiply(m, m);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int right(int n, int k) {\n\t\tint[] path = new int[n];\n\t\treturn dfs(path, 0, k);\n\t}\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int dfs(int[] path, int i, int k) {\n\t\tif (i == path.length) {\n\t\t\tint len = 1;\n\t\t\tfor (int j = 1; j < path.length; j++) {\n\t\t\t\tif (path[j - 1] == path[j]) {\n\t\t\t\t\tlen++;\n\t\t\t\t} else {\n\t\t\t\t\tlen = 1;\n\t\t\t\t}\n\t\t\t\tif (len > 2) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn len > 2 ? 0 : 1;\n\t\t} else {\n\t\t\tint ans = 0;\n\t\t\tfor (int j = 0; j < k; j++) {\n\t\t\t\tpath[i] = j;\n\t\t\t\tans += dfs(path, i + 1, k);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\t// 对数器\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("功能测试开始");\n\t\tfor (int n = 1; n <= 8; n++) {\n\t\t\tfor (int k = 1; k <= 8; k++) {\n\t\t\t\tint ans1 = dp1(n, k);\n\t\t\t\tint ans2 = dp2(n, k);\n\t\t\t\tint ans3 = dp3(n, k);\n\t\t\t\tint ans4 = right(n, k);\n\t\t\t\tif (ans1 != ans2 || ans1 != ans3 || ans1 != ans4) {\n\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("功能测试结束");\n\t\tSystem.out.println();\n\n\t\tSystem.out.println("性能测试开始");\n\t\tint n = 505060123;\n\t\tint k = 303060123;\n\t\tSystem.out.println("数据量 : n = " + n + ", k = " + k);\n\n\t\tlong start, end;\n\t\tstart = System.currentTimeMillis();\n\t\tSystem.out.println("dp2方法结果(已经取模) : " + dp2(n, k));\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("dp2方法用时(毫秒) : " + (end - start));\n\n\t\tstart = System.currentTimeMillis();\n\t\tSystem.out.println("dp3方法结果(已经取模) : " + dp3(n, k));\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("dp3方法用时(毫秒) : " + (end - start));\n\t\tSystem.out.println("性能测试结束");\n\t}\n\n}\n	模板：Code05_WaysOfArrangePlates.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dc42b11d-ddcb-4868-9c92-8df7dafd1bf2	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class127;\n\n// 过河踩过的最少石子数\n// 在河上有一座独木桥，一只青蛙想沿着独木桥从河的一侧跳到另一侧\n// 在桥上有一些石子，青蛙很讨厌踩在这些石子上\n// 我们可以把独木桥上青蛙可能到达的点看成数轴上的一串整点0...n\n// 其中n是桥的长度，坐标为0的点表示桥的起点，坐标为n的点表示桥的终点\n// 青蛙从桥的起点开始，不停的向终点方向跳跃，一次跳跃的距离是[s,t]之间的任意正整数\n// 当青蛙跳到或跳过坐标为n的点时，就算青蛙已经跳出了独木桥\n// 题目给出独木桥的长度n，青蛙跳跃的距离范围s、t，题目还给定m个桥上石子的位置\n// 你的任务是确定青蛙要想过河，最少需要踩到的石子数\n// 1 <= n <= 10^7\n// 1 <= s <= t <= 10\n// 1 <= m <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P1052\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code06_FrogCrossRiver {\n\n\tpublic static int MAXN = 101;\n\n\tpublic static int MAXL = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] where = new int[MAXN];\n\n\tpublic static int[] dp = new int[MAXL];\n\n\tpublic static boolean[] stone = new boolean[MAXL];\n\n\tpublic static int n, s, t, m, safe;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\ts = (int) in.nval;\n\t\tin.nextToken();\n\t\tt = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute() {\n\t\tArrays.sort(arr, 1, m + 1);\n\t\tif (s == t) {\n\t\t\tint ans = 0;\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tif (arr[i] % s == 0) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn ans;\n\t\t} else { // s < t\n\t\t\t// 可以直接给一个足够安全的距离，不需要算\n\t\t\t// 因为s和t不大，都<= 10\n\t\t\t// safe = 201;\n\t\t\tsafe = reduce(s, t);\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\twhere[i] = where[i - 1] + Math.min(arr[i] - arr[i - 1], safe);\n\t\t\t\tstone[where[i]] = true;\n\t\t\t}\n\t\t\t// where[m] + safe : 最后一颗石子 + 安全距离\n\t\t\t// 过了这个安全距离之后，dp值不会再有变化，也不会再遇到石子\n\t\t\tn = where[m] + safe;\n\t\t\tArrays.fill(dp, 1, n + 1, MAXN);\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = Math.max(i - t, 0); j <= i - s; j++) {\n\t\t\t\t\tdp[i] = Math.min(dp[i], dp[j] + (stone[i] ? 1 : 0));\n\t\t\t\t}\n\t\t\t}\n\t\t\tint ans = MAXN;\n\t\t\tfor (int i = where[m] + 1; i <= n; i++) {\n\t\t\t\tans = Math.min(ans, dp[i]);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static int MAXK = 201;\n\n\tpublic static boolean[] reach = new boolean[MAXK];\n\n\t// 一旦s和t定了，那么距离多远就可以缩减呢？\n\t// 做实验！\n\tpublic static int reduce(int s, int t) {\n\t\tArrays.fill(reach, false);\n\t\tint cnt = 0;\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < MAXK; i++) {\n\t\t\tfor (int j = i + s; j < Math.min(i + t + 1, MAXK); j++) {\n\t\t\t\treach[j] = true;\n\t\t\t}\n\t\t\tif (!reach[i]) {\n\t\t\t\tcnt = 0;\n\t\t\t} else {\n\t\t\t\tcnt++;\n\t\t\t}\n\t\t\tif (cnt == t) {\n\t\t\t\tans = i;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code06_FrogCrossRiver.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
07a6e08b-02de-499b-81a7-b5b3a3d907e6	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class128;\n\n// 苹果和盘子\n// 有m个苹果，认为苹果之间无差别，有n个盘子，认为盘子之间无差别\n// 比如5个苹果如果放进3个盘子，那么(1, 3, 1) (1, 1, 3) (3, 1, 1)认为是同一种方法\n// 允许有些盘子是空的，返回有多少种放置方法\n// 测试链接 : https://www.nowcoder.com/practice/bfd8234bb5e84be0b493656e390bdebf\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_ApplesPlates {\n\n\tpublic static int MAXM = 11;\n\n\tpublic static int MAXN = 11;\n\n\tpublic static int[][] dp = new int[MAXM][MAXN];\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tout.println(compute(m, n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute(int m, int n) {\n\t\tfor (int i = 0; i <= m; i++) {\n\t\t\tfor (int j = 0; j <= n; j++) {\n\t\t\t\tdp[i][j] = -1;\n\t\t\t}\n\t\t}\n\t\treturn f(m, n);\n\t}\n\n\tpublic static int f(int m, int n) {\n\t\tif (m == 0) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (n == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (dp[m][n] != -1) {\n\t\t\treturn dp[m][n];\n\t\t}\n\t\tint ans;\n\t\tif (n > m) {\n\t\t\tans = f(m, m);\n\t\t} else {\n\t\t\tans = f(m, n - 1) + f(m - n, n);\n\t\t}\n\t\tdp[m][n] = ans;\n\t\treturn ans;\n\t}\n\n}	模板：Code01_ApplesPlates.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f62f468f-4828-4a38-ba6d-910e525bd7e7	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class161;\n\n// 路径最大值与累加和，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定权值\n// 一共有m条操作，每种操作是如下3种类型中的一种\n// 操作 CHANGE x y : x的权值修改为y\n// 操作 QMAX x y   : x到y的路径上，打印节点值的最大值\n// 操作 QSUM x y   : x到y的路径上，打印节点值的累加和\n// 1 <= n <= 3 * 10^4\n// 0 <= m <= 2 * 10^5\n// -30000 <= 节点权值 <= +30000\n// 测试链接 : https://www.luogu.com.cn/problem/P2590\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code03_PathMaxAndSum1 {\n\n\tpublic static int MAXN = 30001;\n\tpublic static int INF = 10000001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static int[] max = new int[MAXN << 2];\n\tpublic static int[] sum = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tseg[cntd] = first;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = arr[seg[l]];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = -INF;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void pointUpdate(int u, int v) {\n\t\tupdate(dfn[u], v, 1, n, 1);\n\t}\n\n\tpublic static int pathMax(int x, int y) {\n\t\tint ans = -INF;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans = Math.max(ans, queryMax(dfn[top[y]], dfn[y], 1, n, 1));\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans = Math.max(ans, queryMax(dfn[top[x]], dfn[x], 1, n, 1));\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans = Math.max(ans, queryMax(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1));\n\t\treturn ans;\n\t}\n\n\tpublic static int pathSum(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans += querySum(dfn[top[y]], dfn[y], 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += querySum(dfn[top[x]], dfn[x], 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans += querySum(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextInt();\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(1, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(1, 1)，调用迭代版防止爆栈\n\t\tbuild(1, n, 1);\n\t\tm = io.nextInt();\n\t\tString op;\n\t\tint x, y;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tif (op.equals("CHANGE")) {\n\t\t\t\tpointUpdate(x, y);\n\t\t\t} else if (op.equals("QMAX")) {\n\t\t\t\tio.println(pathMax(x, y));\n\t\t\t} else {\n\t\t\t\tio.println(pathSum(x, y));\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_PathMaxAndSum1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
