9afb9bc9-3d56-4792-90ae-66ea5b986957	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class128;\n\n// 数的划分方法\n// 将整数m分成n份，且每份不能为空，任意两个方案不相同(不考虑顺序)\n// 比如，m=7、n=3，那么(1, 1, 5) (1, 5, 1) (5, 1, 1)认为是同一种方法\n// 返回有多少种不同的划分方法\n// 测试链接 : https://www.luogu.com.cn/problem/P1025\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_SplitNumber {\n\n\tpublic static int MAXN = 201;\n\n\tpublic static int MAXK = 7;\n\n\tpublic static int[][] dp = new int[MAXN][MAXK];\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tout.println(compute(m, n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute(int m, int n) {\n\t\tif (m < n) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (m == n) {\n\t\t\treturn 1;\n\t\t}\n\t\tm -= n;\n\t\tfor (int i = 0; i <= m; i++) {\n\t\t\tfor (int j = 0; j <= n; j++) {\n\t\t\t\tdp[i][j] = -1;\n\t\t\t}\n\t\t}\n\t\treturn f(m, n);\n\t}\n\n\tpublic static int f(int m, int n) {\n\t\tif (m == 0) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (n == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (dp[m][n] != -1) {\n\t\t\treturn dp[m][n];\n\t\t}\n\t\tint ans;\n\t\tif (n > m) {\n\t\t\tans = f(m, m);\n\t\t} else {\n\t\t\tans = f(m, n - 1) + f(m - n, n);\n\t\t}\n\t\tdp[m][n] = ans;\n\t\treturn ans;\n\t}\n\n}	模板：Code01_SplitNumber.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2598b220-a0af-4e22-873d-585909fcff40	47ae35d9-059f-489d-9980-e7dc34786e7e	java	package class128;\n\n// 注意查看Code02_BestDeploy2文件，找到了题目2的在线测试\n// 最好的部署\n// 一共有n台机器，编号1 ~ n，所有机器排成一排\n// 你只能一台一台的部署机器，你可以决定部署的顺序，最终所有机器都要部署\n// 给定三个数组no[]、one[]、both[]\n// no[i] : 如果i号机器部署时，相邻没有机器部署，此时能获得的收益\n// one[i] : 如果i号机器部署时，相邻有一台机器部署，此时能获得的收益\n// both[i] : 如果i号机器部署时，相邻有两台机器部署，此时能获得的收益\n// 第1号机器、第n号机器当然不会有两台相邻的机器\n// 返回部署的最大收益\n// 1 <= n <= 10^5\n// 0 <= no[i]、one[i]、both[i]\n// 来自真实大厂笔试，对数器验证\n\npublic class Code02_BestDeploy1 {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int[] no = new int[MAXN];\n\n\tpublic static int[] one = new int[MAXN];\n\n\tpublic static int[] both = new int[MAXN];\n\n\tpublic static int n;\n\n\t// 区间dp的尝试\n\t// 时间复杂度O(n^3)\n\t// 正确但是并不推荐\n\tpublic static int best1() {\n\t\tint[][] dp = new int[n + 1][n + 1];\n\t\tfor (int l = 1; l <= n; l++) {\n\t\t\tfor (int r = l; r <= n; r++) {\n\t\t\t\tdp[l][r] = -1;\n\t\t\t}\n\t\t}\n\t\treturn f(1, n, dp);\n\t}\n\n\t// 部署l...r范围上的机器\n\t// 并且l-1和r+1的机器一定都没有部署\n\t// 返回部署的最大收益\n\tpublic static int f(int l, int r, int[][] dp) {\n\t\tif (l == r) {\n\t\t\treturn no[l];\n\t\t}\n\t\tif (dp[l][r] != -1) {\n\t\t\treturn dp[l][r];\n\t\t}\n\t\tint ans = f(l + 1, r, dp) + one[l];\n\t\tans = Math.max(ans, f(l, r - 1, dp) + one[r]);\n\t\tfor (int i = l + 1; i < r; i++) {\n\t\t\tans = Math.max(ans, f(l, i - 1, dp) + f(i + 1, r, dp) + both[i]);\n\t\t}\n\t\tdp[l][r] = ans;\n\t\treturn ans;\n\t}\n\n\t// 线性dp的尝试\n\t// 时间复杂度O(n)\n\t// 推荐\n\tpublic static int best2() {\n\t\t// dp[i][0] : i号机器的前一台机器没有部署的情况下，部署i...的机器获得的最大收益\n\t\t// dp[i][1] : i号机器的前一台机器已经部署的情况下，部署i...的机器获得的最大收益\n\t\tint[][] dp = new int[n + 1][2];\n\t\tdp[n][0] = no[n];\n\t\tdp[n][1] = one[n];\n\t\tfor (int i = n - 1; i >= 1; i--) {\n\t\t\tdp[i][0] = Math.max(no[i] + dp[i + 1][1], one[i] + dp[i + 1][0]);\n\t\t\tdp[i][1] = Math.max(one[i] + dp[i + 1][1], both[i] + dp[i + 1][0]);\n\t\t}\n\t\treturn dp[1][0];\n\t}\n\n\t// 为了测试\n\tpublic static void random(int size, int v) {\n\t\tn = size;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tno[i] = (int) (Math.random() * v);\n\t\t\tone[i] = (int) (Math.random() * v);\n\t\t\tboth[i] = (int) (Math.random() * v);\n\t\t}\n\t}\n\n\t// 为了测试\n\tpublic static void main(String[] args) {\n\t\tint maxn = 100;\n\t\tint maxv = 100;\n\t\tint testTime = 10000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 0; i < testTime; i++) {\n\t\t\tint size = (int) (Math.random() * maxn) + 1;\n\t\t\trandom(size, maxv);\n\t\t\tint ans1 = best1();\n\t\t\tint ans2 = best2();\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code02_BestDeploy1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
