930aa495-52e0-48b6-a9cd-a7ebac773da6	bd7c262d-7df8-45bf-9a13-0685288d6d4c	java	package class099;\n\n// 单个除数求逆元\n// 对数器验证\npublic class Code01_InverseSingle {\n\n\tpublic static void main(String[] args) {\n\t\t// 1) 必须保证a/b可以整除\n\t\t// 2) 必须保证mod是质数\n\t\t// 3) 必须保证b和mod的最大公约数为1\n\t\tint mod = 41;\n\t\tlong b = 3671613L;\n\t\tlong a = 67312L * b;\n\t\tSystem.out.println(compute1(a, b, mod));\n\t\tSystem.out.println(compute2(a, b, mod));\n\t}\n\n\tpublic static int compute1(long a, long b, int mod) {\n\t\treturn (int) ((a / b) % mod);\n\t}\n\n\tpublic static int compute2(long a, long b, int mod) {\n\t\tlong inv = power(b, mod - 2, mod);\n\t\treturn (int) (((a % mod) * inv) % mod);\n\t}\n\n\t// 乘法快速幂\n\t// 计算b的n次方的结果%mod\n\tpublic static long power(long b, int n, int mod) {\n\t\tlong ans = 1;\n\t\twhile (n > 0) {\n\t\t\tif ((n & 1) == 1) {\n\t\t\t\tans = (ans * b) % mod;\n\t\t\t}\n\t\t\tb = (b * b) % mod;\n\t\t\tn >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_InverseSingle.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dbb4540b-59f1-466f-90dc-7da4d2e3a718	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class110;\n\n// 线段树同时支持范围重置、范围增加、范围查询\n// 维护最大值\n// 测试链接 : https://www.luogu.com.cn/problem/P1253\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_SegmentTreeUpdateAddQueryMax {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static long[] max = new long[MAXN << 2];\n\n\tpublic static long[] add = new long[MAXN << 2];\n\n\tpublic static long[] change = new long[MAXN << 2];\n\n\tpublic static boolean[] update = new boolean[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (update[i]) {\n\t\t\tupdateLazy(i << 1, change[i]);\n\t\t\tupdateLazy(i << 1 | 1, change[i]);\n\t\t\tupdate[i] = false;\n\t\t}\n\t\tif (add[i] != 0) {\n\t\t\taddLazy(i << 1, add[i]);\n\t\t\taddLazy(i << 1 | 1, add[i]);\n\t\t\tadd[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void updateLazy(int i, long v) {\n\t\tmax[i] = v;\n\t\tadd[i] = 0;\n\t\tchange[i] = v;\n\t\tupdate[i] = true;\n\t}\n\n\tpublic static void addLazy(int i, long v) {\n\t\tmax[i] += v;\n\t\tadd[i] += v;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tmax[i] = arr[l];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\tadd[i] = 0;\n\t\tchange[i] = 0;\n\t\tupdate[i] = false;\n\t}\n\n\tpublic static void update(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tupdateLazy(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void add(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddLazy(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i);\n\t\tlong ans = Long.MIN_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken(); int n = (int) in.nval;\n\t\tin.nextToken(); int m = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (long) in.nval;\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tlong jobv;\n\t\tfor (int i = 1, op, jobl, jobr; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken(); jobl = (int) in.nval;\n\t\t\t\tin.nextToken(); jobr = (int) in.nval;\n\t\t\t\tin.nextToken(); jobv = (long) in.nval;\n\t\t\t\tupdate(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else if (op == 2) {\n\t\t\t\tin.nextToken(); jobl = (int) in.nval;\n\t\t\t\tin.nextToken(); jobr = (int) in.nval;\n\t\t\t\tin.nextToken(); jobv = (long) in.nval;\n\t\t\t\tadd(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tin.nextToken(); jobl = (int) in.nval;\n\t\t\t\tin.nextToken(); jobr = (int) in.nval;\n\t\t\t\tout.println(query(jobl, jobr, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code06_SegmentTreeUpdateAddQueryMax.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9066f43f-aef0-437f-9256-a1c4453b0e67	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class110;\n\n// 线段树范围为1 ~ n时，需要几倍空间才够用？\npublic class HowManySpace {\n\n\t// 范围l~r，信息存在独立数组的i位置\n\t// 返回递归展开的过程中出现的最大编号\n\tpublic static int maxi(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn i;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\treturn Math.max(maxi(l, mid, i << 1), maxi(mid + 1, r, i << 1 | 1));\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tint n = 10000;\n\t\tint a = 0;\n\t\tint b = 0;\n\t\tdouble t = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tint space = maxi(1, i, 1);\n\t\t\tdouble times = (double) space / (double) i;\n\t\t\tSystem.out.println("范围[1~" + i + "]，" + "需要空间" + space + "，倍数=" + times);\n\t\t\tif (times > t) {\n\t\t\t\ta = i;\n\t\t\t\tb = space;\n\t\t\t\tt = times;\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("其中的最大倍数，范围[1~" + a + "]，" + "需要空间" + b + "，倍数=" + t);\n\t}\n\n}\n	模板：HowManySpace.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
57e4c3fb-91e7-4c6e-9b1e-06ccf5f89c36	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n// 掉落的方块\n// 有一个二维平面，x轴是最底的边界\n// 给定二维整数数组pos，pos[i] = [ lefti, leni ]\n// 表示第i个方块边长为leni，左侧边缘在x = lefti位置，所在高度非常高\n// 所有方块都是正方形，依次从高处垂直掉落，也就是左边界顺着x = lefti往下\n// 如果掉落的方块碰到已经掉落正方形的顶边或者x轴就停止掉落\n// 如果方块掉落时仅仅是擦过已经掉落正方形的左侧边或右侧边，并不会停止掉落\n// 一旦停止，它就会固定在那里，无法再移动，俄罗斯方块游戏和本题意思一样\n// 返回一个整数数组ans ，其中ans[i]表示在第i块方块掉落后整体的最大高度\n// 1 <= pos数组长度 <= 1000，1 <= lefti <= 10^8，1 <= leni <= 10^6\n// 测试链接 : https://leetcode.cn/problems/falling-squares\npublic class Code01_FallingSquares {\n\n\tpublic static int MAXN = 2001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] max = new int[MAXN << 2];\n\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static boolean[] update = new boolean[MAXN << 2];\n\n\tpublic static int collect(int[][] poss) {\n\t\tint size = 1;\n\t\tfor (int[] pos : poss) {\n\t\t\tarr[size++] = pos[0];\n\t\t\tarr[size++] = pos[0] + pos[1] - 1;\n\t\t}\n\t\tArrays.sort(arr, 1, size);\n\t\tint n = 1;\n\t\tfor (int i = 2; i < size; i++) {\n\t\t\tif (arr[n] != arr[i]) {\n\t\t\t\tarr[++n] = arr[i];\n\t\t\t}\n\t\t}\n\t\treturn n;\n\t}\n\n\tpublic static int rank(int n, int v) {\n\t\tint ans = 0;\n\t\tint l = 1, r = n, m;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (arr[m] >= v) {\n\t\t\t\tans = m;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void up(int i) {\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (update[i]) {\n\t\t\tlazy(i << 1, change[i]);\n\t\t\tlazy(i << 1 | 1, change[i]);\n\t\t\tupdate[i] = false;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, int v) {\n\t\tupdate[i] = true;\n\t\tchange[i] = v;\n\t\tmax[i] = v;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tmax[i] = 0;\n\t\tchange[i] = 0;\n\t\tupdate[i] = false;\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i);\n\t\tint ans = Integer.MIN_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static List<Integer> fallingSquares(int[][] pos) {\n\t\tint n = collect(pos);\n\t\tbuild(1, n, 1);\n\t\tList<Integer> ans = new ArrayList<>();\n\t\tint max = 0, l, r, h;\n\t\tfor (int[] square : pos) {\n\t\t\tl = rank(n, square[0]);\n\t\t\tr = rank(n, square[0] + square[1] - 1);\n\t\t\th = query(l, r, 1, n, 1) + square[1];\n\t\t\tmax = Math.max(max, h);\n\t\t\tans.add(max);\n\t\t\tupdate(l, r, h, 1, n, 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_FallingSquares.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c22cacbe-8167-4867-abd7-ade67d6dd650	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\n// 瓶子里的花朵\n// 给定n个瓶子，编号从0~n-1，一开始所有瓶子都是空的\n// 每个瓶子最多插入一朵花，实现以下两种类型的操作\n// 操作 1 from flower : 一共有flower朵花，从from位置开始依次插入花朵，已经有花的瓶子跳过\n//                     如果一直到最后的瓶子，花也没有用完，就丢弃剩下的花朵\n//                     返回这次操作插入的首个空瓶的位置 和 最后空瓶的位置\n//                     如果从from开始所有瓶子都有花，打印"Can not put any one."\n// 操作 2 left right  : 从left位置开始到right位置的瓶子，变回空瓶，返回清理花朵的数量\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=4614\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_VasesAndFlowers {\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int[] sum = new int[MAXN << 2];\n\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static boolean[] update = new boolean[MAXN << 2];\n\n\tpublic static int n;\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (update[i]) {\n\t\t\tlazy(i << 1, change[i], ln);\n\t\t\tlazy(i << 1 | 1, change[i], rn);\n\t\t\tupdate[i] = false;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, int v, int n) {\n\t\tsum[i] = v * n;\n\t\tchange[i] = v;\n\t\tupdate[i] = true;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tsum[i] = 0;\n\t\tupdate[i] = false;\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int[] insert(int from, int flowers) {\n\t\t// 题目给的位置从0开始\n\t\t// 线段树下标从1开始\n\t\tfrom++;\n\t\tint start, end;\n\t\tint zeros = n - from + 1 - query(from, n, 1, n, 1);\n\t\tif (zeros == 0) {\n\t\t\tstart = 0;\n\t\t\tend = 0;\n\t\t} else {\n\t\t\tstart = findZero(from, 1);\n\t\t\tend = findZero(from, Math.min(zeros, flowers));\n\t\t\tupdate(start, end, 1, 1, n, 1);\n\t\t}\n\t\t// 题目需要从0开始的下标\n\t\tstart--;\n\t\tend--;\n\t\treturn new int[] { start, end };\n\t}\n\n\t// s~n范围上\n\t// 返回第k个0的位置\n\tpublic static int findZero(int s, int k) {\n\t\tint l = s, r = n, mid;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (mid - s + 1 - query(s, mid, 1, n, 1) >= k) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 注意题目给的下标从0开始\n\t// 线段树下标从1开始\n\tpublic static int clear(int left, int right) {\n\t\tleft++;\n\t\tright++;\n\t\tint ans = query(left, right, 1, n, 1);\n\t\tupdate(left, right, 0, 1, n, 1);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint t = (int) in.nval;\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint m = (int) in.nval;\n\t\t\tbuild(1, n, 1);\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tint op = (int) in.nval;\n\t\t\t\tif (op == 1) {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tint from = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tint flowers = (int) in.nval;\n\t\t\t\t\tint[] ans = insert(from, flowers);\n\t\t\t\t\tif (ans[0] == -1) {\n\t\t\t\t\t\tout.println("Can not put any one.");\n\t\t\t\t\t} else {\n\t\t\t\t\t\tout.println(ans[0] + " " + ans[1]);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tint left = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tint right = (int) in.nval;\n\t\t\t\t\tout.println(clear(left, right));\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_VasesAndFlowers.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f6f379cb-bfed-48c8-b023-76f443a4a8d8	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\n// 范围上开平方并求累加和\n// 给定一个长度为n的数组arr，实现以下两种类型的操作\n// 操作 0 l r : 把arr[l..r]范围上的每个数开平方，结果向下取整\n// 操作 1 l r : 查询arr[l..r]范围上所有数字的累加和\n// 两种操作一共发生m次，数据中有可能l>r，遇到这种情况请交换l和r\n// 1 <= n, m <= 10^5，1 <= arr[i] <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P4145\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_SquareRoot {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\tpublic static long[] max = new long[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = arr[l];\n\t\t\tmax[i] = arr[l];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\t// sqrt方法是最核心的\n\t// 注意和常规线段树不一样，这里没有懒更新，也就不需要有down方法\n\t// 只有根据范围最大值信息的剪枝\n\t// 时间复杂度的分析就是课上讲的势能分析\n\t// 不用纠结单次调用的复杂度\n\t// 哪怕调用再多次sqrt方法，总的时间复杂度也就是O(n * 6 * logn)\n\tpublic static void sqrt(int jobl, int jobr, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tlong sqrt = (long) Math.sqrt(max[i]);\n\t\t\tsum[i] = sqrt;\n\t\t\tmax[i] = sqrt;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid && max[i << 1] > 1) {\n\t\t\t\tsqrt(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid && max[i << 1 | 1] > 1) {\n\t\t\t\tsqrt(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\t// 没有懒更新\n\t// 不需要调用down方法\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (long) in.nval;\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, op, jobl, jobr, tmp; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobr = (int) in.nval;\n\t\t\tif (jobl > jobr) {\n\t\t\t\ttmp = jobl;\n\t\t\t\tjobl = jobr;\n\t\t\t\tjobr = tmp;\n\t\t\t}\n\t\t\tif (op == 0) {\n\t\t\t\tsqrt(jobl, jobr, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tout.println(query(jobl, jobr, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_SquareRoot.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
77cd2bca-9f72-4e48-a6c9-01c6cd2911b6	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class115;\n\n// 矩形周长并(poj测试)\n// 测试链接 : http://poj.org/problem?id=1177\n// poj上的java版本较老，不支持lamda表达式定义比较器\n// 所以需要自己定义比较器，除此之外没有区别\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code04_PerimeterSum2 {\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int[][] rec = new int[MAXN][4];\n\n\tpublic static int[][] line = new int[MAXN][4];\n\n\tpublic static int[] vsort = new int[MAXN];\n\n\tpublic static int[] length = new int[MAXN << 2];\n\n\tpublic static int[] cover = new int[MAXN << 2];\n\n\tpublic static int[] times = new int[MAXN << 2];\n\n\tpublic static int prepare(int n) {\n\t\tArrays.sort(vsort, 1, n + 1);\n\t\tint m = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (vsort[m] != vsort[i]) {\n\t\t\t\tvsort[++m] = vsort[i];\n\t\t\t}\n\t\t}\n\t\tvsort[m + 1] = vsort[m];\n\t\treturn m;\n\t}\n\n\tpublic static int rank(int n, int num) {\n\t\tint ans = 0;\n\t\tint l = 1, r = n, mid;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (vsort[mid] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tprivate static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tlength[i] = vsort[r + 1] - vsort[l];\n\t\ttimes[i] = 0;\n\t\tcover[i] = 0;\n\t}\n\n\tpublic static void up(int l, int r, int i) {\n\t\tif (times[i] > 0) {\n\t\t\tcover[i] = length[i];\n\t\t} else if (l == r) {\n\t\t\t// 叶节点直接设置cover不需要下层信息\n\t\t\tcover[i] = 0;\n\t\t} else {\n\t\t\tcover[i] = cover[i << 1] + cover[i << 1 | 1];\n\t\t}\n\t}\n\n\tprivate static void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\ttimes[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t\tup(l, r, i);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken(); rec[i][0] = (int) in.nval;\n\t\t\tin.nextToken(); rec[i][1] = (int) in.nval;\n\t\t\tin.nextToken(); rec[i][2] = (int) in.nval;\n\t\t\tin.nextToken(); rec[i][3] = (int) in.nval;\n\t\t}\n\t\tout.println(compute(n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute(int n) {\n\t\treturn scanY(n) + scanX(n);\n\t}\n\n\tpublic static long scanY(int n) {\n\t\tfor (int i = 1, j = 1 + n, x1, y1, x2, y2; i <= n; i++, j++) {\n\t\t\tx1 = rec[i][0]; y1 = rec[i][1]; x2 = rec[i][2]; y2 = rec[i][3];\n\t\t\tvsort[i] = y1; vsort[j] = y2;\n\t\t\tline[i][0] = x1; line[i][1] = y1; line[i][2] = y2; line[i][3] = 1;\n\t\t\tline[j][0] = x2; line[j][1] = y1; line[j][2] = y2; line[j][3] = -1;\n\t\t}\n\t\treturn scan(n << 1);\n\t}\n\n\tpublic static long scanX(int n) {\n\t\tfor (int i = 1, j = 1 + n, x1, y1, x2, y2; i <= n; i++, j++) {\n\t\t\tx1 = rec[i][0]; y1 = rec[i][1]; x2 = rec[i][2]; y2 = rec[i][3];\n\t\t\tvsort[i] = x1; vsort[j] = x2;\n\t\t\tline[i][0] = y1; line[i][1] = x1; line[i][2] = x2; line[i][3] = 1;\n\t\t\tline[j][0] = y2; line[j][1] = x1; line[j][2] = x2; line[j][3] = -1;\n\t\t}\n\t\treturn scan(n << 1);\n\t}\n\n\tpublic static long scan(int n) {\n\t\tint m = prepare(n);\n\t\tbuild(1, m, 1);\n\t\tArrays.sort(line, 1, n + 1, new LineComparator());\n\t\tlong ans = 0;\n\t\tfor (int i = 1, pre; i <= n; i++) {\n\t\t\tpre = cover[1];\n\t\t\tadd(rank(m, line[i][1]), rank(m, line[i][2]) - 1, line[i][3], 1, m, 1);\n\t\t\tans += Math.abs(cover[1] - pre);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 这里有个坑\n\t// 在排序时，如果同一个位置的扫描线有多条，也就是a[0] == b[0]时\n\t// 应该先处理区间覆盖+1的扫描线，然后再处理区间覆盖-1的扫描线\n\t// 不然投影长度会频繁变化，导致答案错误\n\t// 不过测试数据并没有安排这方面的测试\n\t// poj上的java版本较老，不支持lamda表达式定义比较器\n\t// 需要自己定义比较器，除此之外没有区别\n\tpublic static class LineComparator implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\treturn a[0] != b[0] ? (a[0] - b[0]) : (b[3] - a[3]);\n\t\t}\n\n\t}\n\n}	模板：Code04_PerimeterSum2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b33982c5-29de-4a11-9cbf-1ad57613ddca	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class116;\n\n// 出现次数大于n/2的数\n// 给定一个大小为n的数组nums\n// 水王数是指在数组中出现次数大于n/2的数\n// 返回其中的水王数，如果数组不存在水王数返回-1\n// 测试链接 : https://leetcode.cn/problems/majority-element/\npublic class Code01_WaterKing {\n\n\tpublic static int majorityElement(int[] nums) {\n\t\tint cand = 0;\n\t\tint hp = 0;\n\t\tfor (int num : nums) {\n\t\t\tif (hp == 0) {\n\t\t\t\tcand = num;\n\t\t\t\thp = 1;\n\t\t\t} else if (num != cand) {\n\t\t\t\thp--;\n\t\t\t} else {\n\t\t\t\thp++;\n\t\t\t}\n\t\t}\n\t\tif (hp == 0) {\n\t\t\treturn -1;\n\t\t}\n\t\t// 复用hp，统计真实出现的次数\n\t\thp = 0;\n\t\tfor (int num : nums) {\n\t\t\tif (num == cand) {\n\t\t\t\thp++;\n\t\t\t}\n\t\t}\n\t\treturn hp > nums.length / 2 ? cand : -1;\n\t}\n\n}\n	模板：Code01_WaterKing.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f65b58a8-87e3-4172-8c32-0c52514d86d9	bd7c262d-7df8-45bf-9a13-0685288d6d4c	java	package class099;\n\n// 连续数字逆元的线性递推\n// 给定n、p，求1∼n中所有整数在模p意义下的乘法逆元\n// 1 <= n <= 3 * 10^6\n// n < p < 20000528\n// 输入保证p为质数\n// 测试链接 : https://www.luogu.com.cn/problem/P3811\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.InputStream;\nimport java.io.IOException;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\n// 如下代码可以通过全部测试用例\n// 但是这个题卡常数比较严重\n// 一般情况下不会如此卡常数\n// 需要使用快读、快写增加IO效率\npublic class Code02_InverseSerial {\n\n\tpublic static int MAXN = 3000001;\n\n\tpublic static int[] inv = new int[MAXN];\n\n\tpublic static int n, p;\n\n\tpublic static void build(int n) {\n\t\tinv[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tinv[i] = (int) (p - (long) inv[p % i] * (p / i) % p);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tn = in.readInt();\n\t\tp = in.readInt();\n\t\tbuild(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(inv[i]);\n\t\t}\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}	模板：Code02_InverseSerial.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
70b4ebf4-8fa2-4891-84d3-8f17d4b4b642	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\n// 包含取模操作的线段树\n// 给定一个长度为n的数组arr，实现如下三种操作，一共调用m次\n// 操作 1 l r : 查询arr[l..r]的累加和\n// 操作 2 l r x : 把arr[l..r]上每个数字对x取模\n// 操作 3 k x : 把arr[k]上的数字设置为x\n// 1 <= n, m <= 10^5，操作1得到的结果，有可能超过int范围\n// 测试链接 : https://www.luogu.com.cn/problem/CF438D\n// 测试链接 : https://codeforces.com/problemset/problem/438/D\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_QueryModUpdate {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\tpublic static int[] max = new int[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = arr[l];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void mod(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobv > max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] %= jobv;\n\t\t\tmax[i] %= jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tmod(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tmod(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobr = (int) in.nval;\n\t\t\t\tout.println(query(jobl, jobr, 1, n, 1));\n\t\t\t} else if (op == 2) {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobr = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobv = (int) in.nval;\n\t\t\t\tmod(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobi = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobv = (int) in.nval;\n\t\t\t\tupdate(jobi, jobv, 1, n, 1);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code04_QueryModUpdate.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2a08a89a-740e-4cc4-91d3-55bd8cfa6c7d	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\n// 贴海报\n// 有一面墙，有固定高度，长度为n，有m张海报，所有海报的高度都和墙的高度相同\n// 从第1张海报开始，一张一张往墙上贴，直到n张海报贴完\n// 每张海报都给出张贴位置(xi, yi)，表示第i张海报从墙的左边界xi一直延伸到右边界yi\n// 有可能发生后面的海报把前面的海报完全覆盖，导致看不到的情况\n// 当所有海报贴完，返回能看到海报的数量，哪怕只漏出一点的海报都算\n// 1 <= n、xi、yi <= 10^7，1 <= m <= 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P3740\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_Posters1 {\n\n\tpublic static int MAXM = 1001;\n\n\tpublic static int[] pl = new int[MAXM];\n\n\tpublic static int[] pr = new int[MAXM];\n\n\tpublic static int[] num = new int[MAXM << 2];\n\n\t// 线段树的某个范围上是否被设置成了统一的海报\n\t// 如果poster[i] != 0，poster[i]表示统一海报的编号\n\t// 如果poster[i] == 0，表示该范围上没有海报或者海报编号没统一\n\tpublic static int[] poster = new int[MAXM << 4];\n\n\t// 某种海报编号是否已经被统计过了\n\t// 只在最后一次查询，最后统计海报数量的阶段时候使用\n\tpublic static boolean[] visited = new boolean[MAXM];\n\n\tpublic static int collect(int m) {\n\t\tArrays.sort(num, 1, m + 1);\n\t\tint size = 1;\n\t\tfor (int i = 2; i <= m; i++) {\n\t\t\tif (num[size] != num[i]) {\n\t\t\t\tnum[++size] = num[i];\n\t\t\t}\n\t\t}\n\t\tint cnt = size;\n\t\tfor (int i = 2; i <= size; i++) {\n\t\t\tif (num[i - 1] + 1 < num[i]) {\n\t\t\t\tnum[++cnt] = num[i - 1] + 1;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(num, 1, cnt + 1);\n\t\treturn cnt;\n\t}\n\n\tpublic static int rank(int l, int r, int v) {\n\t\tint m;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (num[m] >= v) {\n\t\t\t\tans = m;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (poster[i] != 0) {\n\t\t\tposter[i << 1] = poster[i];\n\t\t\tposter[i << 1 | 1] = poster[i];\n\t\t\tposter[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tposter[i] = 0;\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tposter[i] = jobv;\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (poster[i] != 0 && !visited[poster[i]]) {\n\t\t\t\tvisited[poster[i]] = true;\n\t\t\t\treturn 1;\n\t\t\t} else {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tint ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tint size = 0;\n\t\tnum[++size] = n;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tpl[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tpr[i] = (int) in.nval;\n\t\t\tnum[++size] = pl[i];\n\t\t\tnum[++size] = pr[i];\n\t\t}\n\t\tsize = collect(size);\n\t\tbuild(1, size, 1);\n\t\tfor (int i = 1, jobl, jobr; i <= m; i++) {\n\t\t\tjobl = rank(1, size, pl[i]);\n\t\t\tjobr = rank(1, size, pr[i]);\n\t\t\tupdate(jobl, jobr, i, 1, size, 1);\n\t\t}\n\t\tout.println(query(1, rank(1, size, n), 1, size, 1));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_Posters1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
66e2d8e4-c576-4fca-8fdd-503f77136fd0	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class111;\n\n// 贴海报(数据加强版)\n// 有一面墙，有固定高度，无限的宽度，有n张海报，所有海报的高度都和墙的高度相同\n// 从第1张海报开始，一张一张往墙上贴，直到n张海报贴完\n// 每张海报都给出张贴位置(xi, yi)，表示第i张海报从墙的左边界xi一直延伸到右边界yi\n// 有可能发生后面的海报把前面的海报完全覆盖，导致看不到的情况\n// 当所有海报贴完，返回能看到海报的数量，哪怕只漏出一点的海报都算\n// 1 <= n <= 10^5，1 <= xi、yi <= 10^7\n// 测试链接 : http://poj.org/problem?id=2528\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_Posters2 {\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int[] pl = new int[MAXN];\n\n\tpublic static int[] pr = new int[MAXN];\n\n\tpublic static int[] num = new int[MAXN << 2];\n\n\t// 线段树的某个范围上是否被设置成了统一的海报\n\t// 如果poster[i] != 0，poster[i]表示统一海报的编号\n\t// 如果poster[i] == 0，表示该范围上没有海报或者海报编号没统一\n\tpublic static int[] poster = new int[MAXN << 4];\n\n\t// 某种海报编号是否已经被统计过了\n\t// 只在最后一次查询，最后统计海报数量的阶段时候使用\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\tpublic static int collect(int m) {\n\t\tArrays.sort(num, 1, m + 1);\n\t\tint size = 1;\n\t\tfor (int i = 2; i <= m; i++) {\n\t\t\tif (num[size] != num[i]) {\n\t\t\t\tnum[++size] = num[i];\n\t\t\t}\n\t\t}\n\t\tint cnt = size;\n\t\tfor (int i = 2; i <= size; i++) {\n\t\t\tif (num[i - 1] + 1 < num[i]) {\n\t\t\t\tnum[++cnt] = num[i - 1] + 1;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(num, 1, cnt + 1);\n\t\treturn cnt;\n\t}\n\n\tpublic static int rank(int l, int r, int v) {\n\t\tint m;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (num[m] >= v) {\n\t\t\t\tans = m;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (poster[i] != 0) {\n\t\t\tposter[i << 1] = poster[i];\n\t\t\tposter[i << 1 | 1] = poster[i];\n\t\t\tposter[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tposter[i] = 0;\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tposter[i] = jobv;\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (poster[i] != 0 && !visited[poster[i]]) {\n\t\t\t\tvisited[poster[i]] = true;\n\t\t\t\treturn 1;\n\t\t\t} else {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tint ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint cases = (int) in.nval;\n\t\tfor (int t = 1; t <= cases; t++) {\n\t\t\tin.nextToken();\n\t\t\tint n = (int) in.nval;\n\t\t\tint m = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tpl[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tpr[i] = (int) in.nval;\n\t\t\t\tnum[++m] = pl[i];\n\t\t\t\tnum[++m] = pr[i];\n\t\t\t}\n\t\t\tm = collect(m);\n\t\t\tbuild(1, m, 1);\n\t\t\tfor (int i = 1, jobl, jobr; i <= n; i++) {\n\t\t\t\tjobl = rank(1, m, pl[i]);\n\t\t\t\tjobr = rank(1, m, pr[i]);\n\t\t\t\tupdate(jobl, jobr, i, 1, m, 1);\n\t\t\t}\n\t\t\tout.println(query(1, m, 1, m, 1));\n\t\t\tArrays.fill(visited, 1, n + 1, false);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code05_Posters2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
88f8525b-27fc-4bd3-9417-40d4aea35c0f	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class112;\n\n// 开关\n// 现有n盏灯排成一排，从左到右依次编号为1~n，一开始所有的灯都是关着的\n// 操作分两种\n// 操作 0 l r : 改变l~r范围上所有灯的状态，开着的灯关上、关着的灯打开\n// 操作 1 l r : 查询l~r范围上有多少灯是打开的\n// 测试链接 : https://www.luogu.com.cn/problem/P3870\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_Switch {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] light = new int[MAXN << 2];\n\n\tpublic static boolean[] reverse = new boolean[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tlight[i] = light[i << 1] + light[i << 1 | 1];\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (reverse[i]) {\n\t\t\tlazy(i << 1, ln);\n\t\t\tlazy(i << 1 | 1, rn);\n\t\t\treverse[i] = false;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, int n) {\n\t\tlight[i] = n - light[i];\n\t\treverse[i] = !reverse[i];\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tlight[i] = 0;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\treverse[i] = false;\n\t}\n\n\tpublic static void reverse(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\treverse(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\treverse(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn light[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op, jobl, jobr; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobr = (int) in.nval;\n\t\t\tif (op == 0) {\n\t\t\t\treverse(jobl, jobr, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tout.println(query(jobl, jobr, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Switch.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
719b2f5e-c8e0-4ecc-b2c1-2419977ac7e3	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class112;\n\n// 贪婪大陆\n// 一共有n个格子，编号1~n，开始时格子上没有地雷，实现两种操作，一共调用m次\n// 操作 1 l r : 在l~r范围的格子上放置一种新型地雷，每次地雷都是新款\n// 操作 2 l r : 查询l~r范围的格子上一共放置过多少款不同的地雷\n// 操作1并不是范围上替换地雷，而是范围上新增新型地雷，注意如下的例子\n// 执行 1 3 6，表示3~6范围上新加一种地雷，假设地雷类型是A\n// 执行 1 3 4，表示3~4范围上又新加一种地雷，和上次的地雷不同，假设地雷类型是B\n// 格子3有两种地雷(A、B)、格子4有两种地雷(A、B)、格子5有一种地雷(A)、格子6有一种地雷(A)\n// 执行 2 4 5，返回2；执行 2 5 6，会返回1\n// 测试链接 : https://www.luogu.com.cn/problem/P2184\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_Bombs {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] bombStarts = new int[MAXN << 2];\n\n\tpublic static int[] bombEnds = new int[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tbombStarts[i] = bombStarts[i << 1] + bombStarts[i << 1 | 1];\n\t\tbombEnds[i] = bombEnds[i << 1] + bombEnds[i << 1 | 1];\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tbombStarts[i] = 0;\n\t\tbombEnds[i] = 0;\n\t}\n\n\t// jobt==0表示在添加地雷范围的开头，jobi就是地雷范围的开头位置\n\t// jobt==1表示在添加地雷范围的结尾，jobi就是地雷范围的结尾位置\n\tpublic static void add(int jobt, int jobi, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (jobt == 0) {\n\t\t\t\tbombStarts[i]++;\n\t\t\t} else {\n\t\t\t\tbombEnds[i]++;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tadd(jobt, jobi, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tadd(jobt, jobi, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\t// jobt==0表示在查询[jobl ~ jobr]范围上有多少地雷范围的开头\n\t// jobt==1表示在查询[jobl ~ jobr]范围上有多少地雷范围的结尾\n\tpublic static int query(int jobt, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn jobt == 0 ? bombStarts[i] : bombEnds[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tint ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += query(jobt, jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += query(jobt, jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op, jobl, jobr; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tjobr = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(0, jobl, 1, n, 1);\n\t\t\t\tadd(1, jobr, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tint s = query(0, 1, jobr, 1, n, 1);\n\t\t\t\t// 如果jobl==1，说明没有更左的区域\n\t\t\t\t// 如果jobl>1，说明有更左的区域\n\t\t\t\tint e = jobl == 1 ? 0 : query(1, 1, jobl - 1, 1, n, 1);\n\t\t\t\tout.println(s - e);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_Bombs.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c7e95e5c-fdaa-4597-87fb-7ec8d73d0568	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class112;\n\n// 无聊的数列\n// 给定一个长度为n的数组arr，实现如下两种操作\n// 操作 1 l r k d : arr[l..r]范围上的数依次加上等差数列，首项k，公差d\n// 操作 2 p       : 查询arr[p]的值\n// 测试链接 : https://www.luogu.com.cn/problem/P1438\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_BoringSequence {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[] diff = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\tpublic static long[] add = new long[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (add[i] != 0) {\n\t\t\tlazy(i << 1, add[i], ln);\n\t\t\tlazy(i << 1 | 1, add[i], rn);\n\t\t\tadd[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, long v, int n) {\n\t\tadd[i] += v;\n\t\tsum[i] += v * n;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = diff[l];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\tadd[i] = 0;\n\t}\n\n\tpublic static void add(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, pre = 0, cur; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcur = (int) in.nval;\n\t\t\tdiff[i] = cur - pre;\n\t\t\tpre = cur;\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobr = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tlong k = (long) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tlong d = (long) in.nval;\n\t\t\t\tlong e = k + d * (jobr - jobl);\n\t\t\t\tadd(jobl, jobl, k, 1, n, 1);\n\t\t\t\tif (jobl + 1 <= jobr) {\n\t\t\t\t\tadd(jobl + 1, jobr, d, 1, n, 1);\n\t\t\t\t}\n\t\t\t\tif (jobr < n) {\n\t\t\t\t\tadd(jobr + 1, jobr + 1, -e, 1, n, 1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tint p = (int) in.nval;\n\t\t\t\tout.println(query(1, p, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_BoringSequence.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
69a07949-c328-497d-9ae7-e6f80d721cdc	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class113;\n\n// 最长LR交替子串\n// 给定一个长度为n的字符串，一开始字符串中全是'L'字符\n// 有q次修改，每次指定一个位置i\n// 如果i位置是'L'字符那么改成'R'字符\n// 如果i位置是'R'字符那么改成'L'字符\n// 如果一个子串是两种字符不停交替出现的样子，也就是LRLR... 或者RLRL...\n// 那么说这个子串是有效子串\n// 每次修改后，都打印当前整个字符串中最长交替子串的长度\n// 测试链接 : https://www.luogu.com.cn/problem/P6492\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_LongestAlternateSubstring {\n\n\tpublic static int MAXN = 200001;\n\n\t// 原始数组\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 交替最长子串长度\n\tpublic static int[] len = new int[MAXN << 2];\n\n\t// 交替最长前缀长度\n\tpublic static int[] pre = new int[MAXN << 2];\n\n\t// 交替最长后缀长度\n\tpublic static int[] suf = new int[MAXN << 2];\n\n\tpublic static void up(int l, int r, int i) {\n\t\tlen[i] = Math.max(len[i << 1], len[i << 1 | 1]);\n\t\tpre[i] = pre[i << 1];\n\t\tsuf[i] = suf[i << 1 | 1];\n\t\tint mid = (l + r) >> 1;\n\t\tint ln = mid - l + 1;\n\t\tint rn = r - mid;\n\t\tif (arr[mid] != arr[mid + 1]) {\n\t\t\tlen[i] = Math.max(len[i], suf[i << 1] + pre[i << 1 | 1]);\n\t\t\tif (len[i << 1] == ln) {\n\t\t\t\tpre[i] = ln + pre[i << 1 | 1];\n\t\t\t}\n\t\t\tif (len[i << 1 | 1] == rn) {\n\t\t\t\tsuf[i] = rn + suf[i << 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tlen[i] = 1;\n\t\t\tpre[i] = 1;\n\t\t\tsuf[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(l, r, i);\n\t\t}\n\t}\n\n\tpublic static void reverse(int jobi, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tarr[jobi] ^= 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\treverse(jobi, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\treverse(jobi, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(l, r, i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint q = (int) in.nval;\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, index; i <= q; i++) {\n\t\t\tin.nextToken();\n\t\t\tindex = (int) in.nval;\n\t\t\treverse(index, 1, n, 1);\n\t\t\tout.println(len[1]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_LongestAlternateSubstring.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2af42eda-a01a-434c-95f2-562ae3572fe9	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class113;\n\n// 地道相连的房子\n// 有n个房子排成一排，编号1~n，一开始每相邻的两个房子之间都有地道\n// 实现如下三个操作\n// 操作 D x : 把x号房子摧毁，该房子附近的地道也一并摧毁\n// 操作 R   : 恢复上次摧毁的房子，该房子附近的地道一并恢复\n// 操作 Q x : 查询x号房子能到达的房子数量，包括x号房子自身\n// 测试链接 : https://www.luogu.com.cn/problem/P1503\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_TunnelWarfare {\n\n\tpublic static int MAXN = 50001;\n\n\t// 连续1的最长前缀长度\n\tpublic static int[] pre = new int[MAXN << 2];\n\n\t// 连续1的最长后缀长度\n\tpublic static int[] suf = new int[MAXN << 2];\n\n\t// 摧毁的房屋编号入栈，以便执行恢复操作\n\tpublic static int[] stack = new int[MAXN];\n\n\tpublic static void up(int l, int r, int i) {\n\t\tpre[i] = pre[i << 1];\n\t\tsuf[i] = suf[i << 1 | 1];\n\t\tint mid = (l + r) >> 1;\n\t\tif (pre[i << 1] == mid - l + 1) {\n\t\t\tpre[i] += pre[i << 1 | 1];\n\t\t}\n\t\tif (suf[i << 1 | 1] == r - mid) {\n\t\t\tsuf[i] += suf[i << 1];\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tpre[i] = suf[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(l, r, i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tpre[i] = suf[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(l, r, i);\n\t\t}\n\t}\n\n\t// 已知jobi在l...r范围上\n\t// 返回jobi往两侧扩展出的最大长度\n\t// 递归需要遵循的潜台词 : 从jobi往两侧扩展，一定无法扩展到l...r范围之外！\n\tpublic static int query(int jobi, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn pre[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tif (jobi > mid - suf[i << 1]) {\n\t\t\t\t\treturn suf[i << 1] + pre[i << 1 | 1];\n\t\t\t\t} else {\n\t\t\t\t\treturn query(jobi, l, mid, i << 1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (mid + pre[i << 1 | 1] >= jobi) {\n\t\t\t\t\treturn suf[i << 1] + pre[i << 1 | 1];\n\t\t\t\t} else {\n\t\t\t\t\treturn query(jobi, mid + 1, r, i << 1 | 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tint n = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint m = (int) in.nval;\n\t\t\tbuild(1, n, 1);\n\t\t\tString op;\n\t\t\tint stackSize = 0;\n\t\t\tfor (int i = 1, x; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\top = in.sval;\n\t\t\t\tif (op.equals("D")) {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tx = (int) in.nval;\n\t\t\t\t\tupdate(x, 0, 1, n, 1);\n\t\t\t\t\tstack[stackSize++] = x;\n\t\t\t\t} else if (op.equals("R")) {\n\t\t\t\t\tupdate(stack[--stackSize], 1, 1, n, 1);\n\t\t\t\t} else {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tx = (int) in.nval;\n\t\t\t\t\tout.println(query(x, 1, n, 1));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_TunnelWarfare.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
95c56bf4-cc0b-4866-a65f-cb24cc3353c8	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class113;\n\n// 旅馆\n// 一共有n个房间，编号1~n，一开始都是空房\n// 实现如下两种操作，会一共调用m次\n// 操作 1 x   : 找到至少有连续x个空房间的区域，返回最左编号\n//              如果有多个满足条件的区域，返回其中最左区域的最左编号\n//              如果找不到打印0，并且不办理入住\n//              如果找到了打印最左编号，并且从最左编号开始办理x个人的入住\n// 操作 2 x y : 从x号房间开始往下数y个房间，一律清空\n// 操作1有打印操作，操作2没有\n// 1 <= n 、m <= 50000\n// 测试链接 : https://www.luogu.com.cn/problem/P2894\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_Hotel {\n\n\tpublic static int MAXN = 50001;\n\n\t// 连续空房最长子串长度\n\tpublic static int[] len = new int[MAXN << 2];\n\n\t// 连续空房最长前缀长度\n\tpublic static int[] pre = new int[MAXN << 2];\n\n\t// 连续空房最长后缀长度\n\tpublic static int[] suf = new int[MAXN << 2];\n\n\t// 懒更新信息，范围上所有数字被重置成了什么\n\tpublic static int[] change = new int[MAXN << 2];\n\n\t// 懒更新信息，范围上有没有重置任务\n\tpublic static boolean[] update = new boolean[MAXN << 2];\n\n\tpublic static void up(int i, int ln, int rn) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tlen[i] = Math.max(Math.max(len[l], len[r]), suf[l] + pre[r]);\n\t\tpre[i] = len[l] < ln ? pre[l] : (pre[l] + pre[r]);\n\t\tsuf[i] = len[r] < rn ? suf[r] : (suf[l] + suf[r]);\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (update[i]) {\n\t\t\tlazy(i << 1, change[i], ln);\n\t\t\tlazy(i << 1 | 1, change[i], rn);\n\t\t\tupdate[i] = false;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, int v, int n) {\n\t\tlen[i] = pre[i] = suf[i] = v == 0 ? n : 0;\n\t\tchange[i] = v;\n\t\tupdate[i] = true;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tlen[i] = pre[i] = suf[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i, mid - l + 1, r - mid);\n\t\t}\n\t\tupdate[i] = false;\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i, mid - l + 1, r - mid);\n\t\t}\n\t}\n\n\t// 在l..r范围上，在满足空房长度>=x的情况下，返回尽量靠左的开头位置\n\t// 递归需要遵循的潜台词 : l..r范围上一定存在连续空房长度>=x的区域\n\tpublic static int queryLeft(int x, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\t// 最先查左边\n\t\t\tif (len[i << 1] >= x) {\n\t\t\t\treturn queryLeft(x, l, mid, i << 1);\n\t\t\t}\n\t\t\t// 然后查中间向两边扩展的可能区域\n\t\t\tif (suf[i << 1] + pre[i << 1 | 1] >= x) {\n\t\t\t\treturn mid - suf[i << 1] + 1;\n\t\t\t}\n\t\t\t// 前面都没有再最后查右边\n\t\t\treturn queryLeft(x, mid + 1, r, i << 1 | 1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tbuild(1, n, 1);\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, op, x, y, left; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tif (len[1] < x) {\n\t\t\t\t\tleft = 0;\n\t\t\t\t} else {\n\t\t\t\t\tleft = queryLeft(x, 1, n, 1);\n\t\t\t\t\tupdate(left, left + x - 1, 1, 1, n, 1);\n\t\t\t\t}\n\t\t\t\tout.println(left);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tupdate(x, Math.min(x + y - 1, n), 0, 1, n, 1);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_Hotel.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b484fc82-aef3-4df0-b064-f7d151a963f4	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 动态开点线段树\n// 一共有n个位置，编号从1~n，一开始所有位置的值为0\n// 实现如下两个操作，一共会调用m次\n// 操作 1 l r v : 把l~r范围的每个数增加v\n// 操作 2 l r   : 返回l~r范围的累加和\n// 1 <= n <= 10^9\n// 1 <= m <= 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P2781\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_DynamicSegmentTree {\n\n\t// 范围1 ~ 10^9，线段树高度差不多30\n\t// 查询次数1000，每次查询都有左右两条边线\n\t// 所以空间占用差不多1000 * 30 * 2 = 60000\n\t// 适当调大即可\n\tpublic static int LIMIT = 80001;\n\n\tpublic static int cnt;\n\n\tpublic static int[] left = new int[LIMIT];\n\n\tpublic static int[] right = new int[LIMIT];\n\n\tpublic static long[] sum = new long[LIMIT];\n\n\tpublic static long[] add = new long[LIMIT];\n\n\tpublic static void up(int h, int l, int r) {\n\t\tsum[h] = sum[l] + sum[r];\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (add[i] != 0) {\n\t\t\t// 懒更新任务下发\n\t\t\t// 那左右两侧的空间需要准备好\n\t\t\tif (left[i] == 0) {\n\t\t\t\tleft[i] = ++cnt;\n\t\t\t}\n\t\t\tif (right[i] == 0) {\n\t\t\t\tright[i] = ++cnt;\n\t\t\t}\n\t\t\tlazy(left[i], add[i], ln);\n\t\t\tlazy(right[i], add[i], rn);\n\t\t\tadd[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, long v, int n) {\n\t\tsum[i] += v * n;\n\t\tadd[i] += v;\n\t}\n\n\tpublic static void add(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\t// 不得不去左侧才会申请\n\t\t\t\tif (left[i] == 0) {\n\t\t\t\t\tleft[i] = ++cnt;\n\t\t\t\t}\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, left[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\t// 不得不去右侧才会申请\n\t\t\t\tif (right[i] == 0) {\n\t\t\t\t\tright[i] = ++cnt;\n\t\t\t\t}\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, right[i]);\n\t\t\t}\n\t\t\tup(i, left[i], right[i]);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\t// 发现左侧申请过空间才有必要去查询\n\t\t\t// 如果左侧从来没有申请过空间那查询结果就是0\n\t\t\tif (left[i] != 0) {\n\t\t\t\tans += query(jobl, jobr, l, mid, left[i]);\n\t\t\t}\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\t// 发现右侧申请过空间才有必要去查询\n\t\t\t// 如果右侧从来没有申请过空间那查询结果就是0\n\t\t\tif (right[i] != 0) {\n\t\t\t\tans += query(jobl, jobr, mid + 1, r, right[i]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 如果一次会执行多组测试数组\n\t// 那么每组测试完成后要clear空间\n\tpublic static void clear() {\n\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\tArrays.fill(sum, 1, cnt + 1, 0);\n\t\tArrays.fill(add, 1, cnt + 1, 0);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tcnt = 1;\n\t\tlong jobv;\n\t\tfor (int i = 1, op, jobl, jobr; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tjobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tjobr = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tjobv = (long) in.nval;\n\t\t\t\tadd(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tjobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tjobr = (int) in.nval;\n\t\t\t\tout.println(query(jobl, jobr, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\t// 本题每组测试数据都单独运行\n\t\t// 可以不写clear方法\n\t\t// 但是如果多组测试数据串行调用\n\t\t// 就需要加上清空逻辑\n\t\tclear();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_DynamicSegmentTree.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
79463526-2e06-4b0e-b732-c0e3ba496999	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\nimport java.util.Arrays;\n\n// 统计区间中的整数数目\n// 实现CountIntervals类的如下三个方法\n// 1) CountIntervals() : 初始化\n// 2) void add(int l, int r) : 把[l, r]范围上的数字都设置成1\n// 3) int count() : 返回整个区间有多少个1\n// CountIntervals类需要支持1 ~ 10^9范围\n// 调用add和count方法总共10^5次\n// 测试链接 : https://leetcode.cn/problems/count-integers-in-intervals/\npublic class Code02_CountIntervals {\n\n\t// 开点线段树的实现\n\t// 为了所有语言的同学都容易改出来\n\t// 选择用静态空间的方式实现\n\t// 该方法的打败比例不高但是非常好想\n\t// 有兴趣的同学可以研究其他做法\n\tclass CountIntervals {\n\n\t\t// 支持的最大范围\n\t\tpublic static int n = 1000000000;\n\n\t\t// 空间大小定成这个值是实验的结果\n\t\tpublic static int LIMIT = 700001;\n\n\t\tpublic static int[] left = new int[LIMIT];\n\n\t\tpublic static int[] right = new int[LIMIT];\n\n\t\tpublic static int[] sum = new int[LIMIT];\n\n\t\tpublic static int cnt = 1;\n\n\t\tpublic CountIntervals() {\n\t\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\t\tArrays.fill(sum, 1, cnt + 1, 0);\n\t\t\tcnt = 1;\n\t\t}\n\n\t\tpublic static void up(int h, int l, int r) {\n\t\t\tsum[h] = sum[l] + sum[r];\n\t\t}\n\n\t\t// 这个题的特殊性在于，只有改1的操作，没有改0的操作\n\t\t// 理解这个就可以分析出不需要懒更新机制，原因有两个\n\t\t// 1) 查询操作永远查的是整个范围1的数量，不会有小范围的查询，每次都返回sum[1]\n\t\t//    这意味着只要能把sum[1]更新正确即可，up函数可以保证这一点\n\t\t// 2) 一个范围已经全是1，那以后都会是1，没有必要把全是1的懒更新信息向下传递\n\t\t// 这个函数的功能比线段树能做到的范围修改功能简单很多\n\t\t// 功能有阉割就意味着存在优化的点\n\t\tpublic static void setOne(int jobl, int jobr, int l, int r, int i) {\n\t\t\tif (sum[i] == r - l + 1) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif (jobl <= l && r <= jobr) {\n\t\t\t\tsum[i] = r - l + 1;\n\t\t\t} else {\n\t\t\t\tint mid = (l + r) >> 1;\n\t\t\t\tif (jobl <= mid) {\n\t\t\t\t\tif (left[i] == 0) {\n\t\t\t\t\t\tleft[i] = ++cnt;\n\t\t\t\t\t}\n\t\t\t\t\tsetOne(jobl, jobr, l, mid, left[i]);\n\t\t\t\t}\n\t\t\t\tif (jobr > mid) {\n\t\t\t\t\tif (right[i] == 0) {\n\t\t\t\t\t\tright[i] = ++cnt;\n\t\t\t\t\t}\n\t\t\t\t\tsetOne(jobl, jobr, mid + 1, r, right[i]);\n\t\t\t\t}\n\t\t\t\tup(i, left[i], right[i]);\n\t\t\t}\n\t\t}\n\n\t\tpublic void add(int left, int right) {\n\t\t\tsetOne(left, right, 1, n, 1);\n\t\t}\n\n\t\tpublic int count() {\n\t\t\treturn sum[1];\n\t\t}\n\t}\n\n}\n	模板：Code02_CountIntervals.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2ec9b8de-3064-4360-a95b-f70fb8a75c75	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 线段树的区间最值操作\n// 给定一个长度为n的数组arr，实现支持以下三种操作的结构\n// 操作 0 l r x : 把arr[l..r]范围的每个数v，更新成min(v, x)\n// 操作 1 l r   : 查询arr[l..r]范围上的最大值\n// 操作 2 l r   : 查询arr[l..r]范围上的累加和\n// 三种操作一共调用m次，做到时间复杂度O(n * log n + m * log n)\n// 对数器验证\npublic class Code03_SegmentTreeSetminQueryMaxSum1 {\n\n\tpublic static int MAXN = 100001;\n\n\t// 假设初始数组中的值不会出现比LOWEST还小的值\n\t// 假设更新操作时jobv的数值也不会出现比LOWEST还小的值\n\tpublic static int LOWEST = -100001;\n\n\t// 原始数组\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 累加和\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\t// 最大值(既是查询信息也是懒更新信息，课上已经讲解了)\n\tpublic static int[] max = new int[MAXN << 2];\n\n\t// 最大值个数\n\tpublic static int[] cnt = new int[MAXN << 2];\n\n\t// 严格次大值(second max)\n\tpublic static int[] sem = new int[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tsum[i] = sum[l] + sum[r];\n\t\tmax[i] = Math.max(max[l], max[r]);\n\t\tif (max[l] > max[r]) {\n\t\t\tcnt[i] = cnt[l];\n\t\t\tsem[i] = Math.max(sem[l], max[r]);\n\t\t} else if (max[l] < max[r]) {\n\t\t\tcnt[i] = cnt[r];\n\t\t\tsem[i] = Math.max(max[l], sem[r]);\n\t\t} else {\n\t\t\tcnt[i] = cnt[l] + cnt[r];\n\t\t\tsem[i] = Math.max(sem[l], sem[r]);\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tlazy(i << 1, max[i]);\n\t\tlazy(i << 1 | 1, max[i]);\n\t}\n\n\t// 一定是没有颠覆掉次大值的懒更新信息下发，也就是说：\n\t// 最大值被压成v，并且v > 严格次大值的情况下\n\t// sum和max怎么调整\n\tpublic static void lazy(int i, int v) {\n\t\tif (v < max[i]) {\n\t\t\tsum[i] -= ((long) max[i] - v) * cnt[i];\n\t\t\tmax[i] = v;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = arr[l];\n\t\t\tcnt[i] = 1;\n\t\t\tsem[i] = LOWEST;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMin(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobv >= max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && sem[i] < jobv) {\n\t\t\tlazy(i, jobv);\n\t\t} else {\n\t\t\t// 1) 任务没有全包\n\t\t\t// 2) jobv <= sem[i]\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = Integer.MIN_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("测试开始");\n\t\tint n = 2000;\n\t\tint v = 5000;\n\t\tint t = 1000000;\n\t\trandomArray(n, v);\n\t\tint[] check = new int[n + 1];\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcheck[i] = arr[i];\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op, a, b, jobl, jobr, jobv; i <= t; i++) {\n\t\t\top = (int) (Math.random() * 3);\n\t\t\ta = (int) (Math.random() * n) + 1;\n\t\t\tb = (int) (Math.random() * n) + 1;\n\t\t\tjobl = Math.min(a, b);\n\t\t\tjobr = Math.max(a, b);\n\t\t\tif (op == 0) {\n\t\t\t\tjobv = (int) (Math.random() * v * 2) - v;\n\t\t\t\tsetMin(jobl, jobr, jobv, 1, n, 1);\n\t\t\t\tcheckSetMin(check, jobl, jobr, jobv);\n\t\t\t} else if (op == 1) {\n\t\t\t\tint ans1 = queryMax(jobl, jobr, 1, n, 1);\n\t\t\t\tint ans2 = checkQueryMax(check, jobl, jobr);\n\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlong ans1 = querySum(jobl, jobr, 1, n, 1);\n\t\t\t\tlong ans2 = checkQuerySum(check, jobl, jobr);\n\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 为了验证\n\tpublic static void randomArray(int n, int v) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = (int) (Math.random() * v * 2) - v;\n\t\t}\n\t}\n\n\t// 为了验证\n\tpublic static void checkSetMin(int[] check, int jobl, int jobr, int jobv) {\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tcheck[i] = Math.min(check[i], jobv);\n\t\t}\n\t}\n\n\t// 为了验证\n\tpublic static int checkQueryMax(int[] check, int jobl, int jobr) {\n\t\tint ans = Integer.MIN_VALUE;\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tans = Math.max(ans, check[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\tpublic static long checkQuerySum(int[] check, int jobl, int jobr) {\n\t\tlong ans = 0;\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tans += check[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}	模板：Code03_SegmentTreeSetminQueryMaxSum1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d787c734-8e04-4f19-9ed2-8597ed039e92	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 线段树的区间最值操作(hdu测试)\n// 给定一个长度为n的数组arr，实现支持以下三种操作的结构\n// 操作 0 l r x : 把arr[l..r]范围的每个数v，更新成min(v, x)\n// 操作 1 l r   : 查询arr[l..r]范围上的最大值\n// 操作 2 l r   : 查询arr[l..r]范围上的累加和\n// 三种操作一共调用m次，做到时间复杂度O(n * log n + m * log n)\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5306\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_SegmentTreeSetminQueryMaxSum2 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int LOWEST = -1;\n\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\tpublic static int[] max = new int[MAXN << 2];\n\n\tpublic static int[] cnt = new int[MAXN << 2];\n\n\tpublic static int[] sem = new int[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tsum[i] = sum[l] + sum[r];\n\t\tmax[i] = Math.max(max[l], max[r]);\n\t\tif (max[l] > max[r]) {\n\t\t\tcnt[i] = cnt[l];\n\t\t\tsem[i] = Math.max(sem[l], max[r]);\n\t\t} else if (max[l] < max[r]) {\n\t\t\tcnt[i] = cnt[r];\n\t\t\tsem[i] = Math.max(max[l], sem[r]);\n\t\t} else {\n\t\t\tcnt[i] = cnt[l] + cnt[r];\n\t\t\tsem[i] = Math.max(sem[l], sem[r]);\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tlazy(i << 1, max[i]);\n\t\tlazy(i << 1 | 1, max[i]);\n\t}\n\n\t// 一定是没有颠覆掉次大值的懒更新信息下发，也就是说：\n\t// 最大值被压成v，并且v > 严格次大值的情况下\n\t// sum和max怎么调整\n\tpublic static void lazy(int i, int v) {\n\t\tif (v < max[i]) {\n\t\t\tsum[i] -= ((long) max[i] - v) * cnt[i];\n\t\t\tmax[i] = v;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) throws IOException {\n\t\tif (l == r) {\n\t\t\t// 不能生成原始数组然后build\n\t\t\t// 因为这道题空间非常极限\n\t\t\t// 生成原始数组然后build\n\t\t\t// 空间就是会超过限制\n\t\t\t// 所以build的过程直接从输入流读入\n\t\t\t// 一般情况下不会这么极限的\n\t\t\tin.nextToken();\n\t\t\tsum[i] = max[i] = (int) in.nval;\n\t\t\tcnt[i] = 1;\n\t\t\tsem[i] = LOWEST;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMin(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobv >= max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && sem[i] < jobv) {\n\t\t\tlazy(i, jobv);\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = Integer.MIN_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了不生成原始数组\n\t// 让build函数可以直接从输入流拿数据\n\t// 所以把输入输出流定义成全局静态变量\n\tpublic static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\n\tpublic static StreamTokenizer in = new StreamTokenizer(br);\n\n\tpublic static PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tin.nextToken();\n\t\tint testCases = (int) in.nval;\n\t\tfor (int t = 1; t <= testCases; t++) {\n\t\t\tin.nextToken();\n\t\t\tint n = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint m = (int) in.nval;\n\t\t\tbuild(1, n, 1);\n\t\t\tfor (int i = 1, op, jobl, jobr, jobv; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\top = (int) in.nval;\n\t\t\t\tif (op == 0) {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobl = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobr = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobv = (int) in.nval;\n\t\t\t\t\tsetMin(jobl, jobr, jobv, 1, n, 1);\n\t\t\t\t} else if (op == 1) {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobl = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobr = (int) in.nval;\n\t\t\t\t\tout.println(queryMax(jobl, jobr, 1, n, 1));\n\t\t\t\t} else {\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobl = (int) in.nval;\n\t\t\t\t\tin.nextToken();\n\t\t\t\t\tjobr = (int) in.nval;\n\t\t\t\t\tout.println(querySum(jobl, jobr, 1, n, 1));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code03_SegmentTreeSetminQueryMaxSum2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
58908cf5-5e68-414b-920b-359a8c8e3770	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 线段树范围增加操作 + 区间最值操作\n// 给定一个长度为n的数组arr，实现支持以下四种操作的结构\n// 操作 0 l r x : 把arr[l..r]范围的每个数v，增加x\n// 操作 1 l r x : 把arr[l..r]范围的每个数v，更新成min(v, x)\n// 操作 2 l r   : 查询arr[l..r]范围上的最大值\n// 操作 3 l r   : 查询arr[l..r]范围上的累加和\n// 对数器验证\n\npublic class Code04_SegmentTreeAddSetminQueryMaxSum {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static long LOWEST = Long.MIN_VALUE;\n\n\t// 原始数组\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 累加和信息(查询信息)\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\t// 最大值信息(只是查询信息，不再是懒更新信息，懒更新功能被maxAdd数组替代了)\n\tpublic static long[] max = new long[MAXN << 2];\n\n\t// 最大值个数(查询信息)\n\tpublic static int[] cnt = new int[MAXN << 2];\n\n\t// 严格次大值(查询信息)\n\tpublic static long[] sem = new long[MAXN << 2];\n\n\t// 最大值的增加幅度(懒更新信息)\n\tpublic static long[] maxAdd = new long[MAXN << 2];\n\n\t// 除最大值以外其他数字的增加幅度(懒更新信息)\n\tpublic static long[] otherAdd = new long[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tsum[i] = sum[l] + sum[r];\n\t\tmax[i] = Math.max(max[l], max[r]);\n\t\tif (max[l] > max[r]) {\n\t\t\tcnt[i] = cnt[l];\n\t\t\tsem[i] = Math.max(sem[l], max[r]);\n\t\t} else if (max[l] < max[r]) {\n\t\t\tcnt[i] = cnt[r];\n\t\t\tsem[i] = Math.max(max[l], sem[r]);\n\t\t} else {\n\t\t\tcnt[i] = cnt[l] + cnt[r];\n\t\t\tsem[i] = Math.max(sem[l], sem[r]);\n\t\t}\n\t}\n\n\tpublic static void lazy(int i, int n, long maxAddv, long otherAddv) {\n\t\tsum[i] += maxAddv * cnt[i] + otherAddv * (n - cnt[i]);\n\t\tmax[i] += maxAddv;\n\t\tsem[i] += sem[i] == LOWEST ? 0 : otherAddv;\n\t\tmaxAdd[i] += maxAddv;\n\t\totherAdd[i] += otherAddv;\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\t// 为什么拿全局最大值不写成 : tmp = max[i]\n\t\t// 因为父亲范围的最大值可能已经被懒更新任务修改过了\n\t\t// 现在希望拿的是懒更新之前的最大值\n\t\t// 子范围的max值没有修改过，所以写成 : tmp = Math.max(max[l], max[r])\n\t\tlong tmp = Math.max(max[l], max[r]);\n\t\tif (max[l] == tmp) {\n\t\t\tlazy(l, ln, maxAdd[i], otherAdd[i]);\n\t\t} else {\n\t\t\tlazy(l, ln, otherAdd[i], otherAdd[i]);\n\t\t}\n\t\tif (max[r] == tmp) {\n\t\t\tlazy(r, rn, maxAdd[i], otherAdd[i]);\n\t\t} else {\n\t\t\tlazy(r, rn, otherAdd[i], otherAdd[i]);\n\t\t}\n\t\tmaxAdd[i] = otherAdd[i] = 0;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = arr[l];\n\t\t\tsem[i] = LOWEST;\n\t\t\tcnt[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\tmaxAdd[i] = otherAdd[i] = 0;\n\t}\n\n\tpublic static void add(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, r - l + 1, jobv, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMin(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobv >= max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && sem[i] < jobv) {\n\t\t\tlazy(i, r - l + 1, jobv - max[i], 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tlong ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static long queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tLong ans = Long.MIN_VALUE;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("测试开始");\n\t\tint n = 2000;\n\t\tint v = 5000;\n\t\tint t = 1000000;\n\t\trandomArray(n, v);\n\t\tlong[] check = new long[n + 1];\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcheck[i] = arr[i];\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op, a, b, jobl, jobr, jobv; i <= t; i++) {\n\t\t\top = (int) (Math.random() * 4);\n\t\t\ta = (int) (Math.random() * n) + 1;\n\t\t\tb = (int) (Math.random() * n) + 1;\n\t\t\tjobl = Math.min(a, b);\n\t\t\tjobr = Math.max(a, b);\n\t\t\tif (op == 0) {\n\t\t\t\tjobv = (int) (Math.random() * v * 2) - v;\n\t\t\t\tadd(jobl, jobr, jobv, 1, n, 1);\n\t\t\t\tcheckAdd(check, jobl, jobr, jobv);\n\t\t\t} else if (op == 1) {\n\t\t\t\tjobv = (int) (Math.random() * v * 2) - v;\n\t\t\t\tsetMin(jobl, jobr, jobv, 1, n, 1);\n\t\t\t\tcheckSetMin(check, jobl, jobr, jobv);\n\t\t\t} else if (op == 2) {\n\t\t\t\tlong ans1 = queryMax(jobl, jobr, 1, n, 1);\n\t\t\t\tlong ans2 = checkQueryMax(check, jobl, jobr);\n\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlong ans1 = querySum(jobl, jobr, 1, n, 1);\n\t\t\t\tlong ans2 = checkQuerySum(check, jobl, jobr);\n\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 为了验证\n\tpublic static void randomArray(int n, int v) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = (int) (Math.random() * v * 2) - v;\n\t\t}\n\t}\n\n\t// 为了验证\n\tpublic static void checkAdd(long[] check, int jobl, int jobr, long jobv) {\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tcheck[i] += jobv;\n\t\t}\n\t}\n\n\t// 为了验证\n\tpublic static void checkSetMin(long[] check, int jobl, int jobr, long jobv) {\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tcheck[i] = Math.min(check[i], jobv);\n\t\t}\n\t}\n\n\t// 为了验证\n\tpublic static long checkQueryMax(long[] check, int jobl, int jobr) {\n\t\tlong ans = Long.MIN_VALUE;\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tans = Math.max(ans, check[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\tpublic static long checkQuerySum(long[] check, int jobl, int jobr) {\n\t\tlong ans = 0;\n\t\tfor (int i = jobl; i <= jobr; i++) {\n\t\t\tans += check[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_SegmentTreeAddSetminQueryMaxSum.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
82839953-a00d-4d18-aa3b-33ce8f3bb579	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 区间最值和历史最值，java版\n// 给定两个长度都为n的数组A和B，一开始两个数组完全一样\n// 任何操作做完，都更新B数组，B[i] = max(B[i],A[i])\n// 实现以下五种操作，一共会调用m次\n// 操作 1 l r v : A[l..r]范围上每个数加上v\n// 操作 2 l r v : A[l..r]范围上每个数A[i]变成min(A[i],v)\n// 操作 3 l r   : 返回A[l..r]范围上的累加和\n// 操作 4 l r   : 返回A[l..r]范围上的最大值\n// 操作 5 l r   : 返回B[l..r]范围上的最大值\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6242\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_MaximumMinimumHistory1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static long LOWEST = Long.MIN_VALUE;\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static long[] sum = new long[MAXN << 2];\n\tpublic static long[] max = new long[MAXN << 2];\n\tpublic static int[] cnt = new int[MAXN << 2];\n\tpublic static long[] sem = new long[MAXN << 2];\n\tpublic static long[] maxAdd = new long[MAXN << 2];\n\tpublic static long[] otherAdd = new long[MAXN << 2];\n\n\t// 历史最大值\n\tpublic static long[] maxHistory = new long[MAXN << 2];\n\n\t// 最大值达到过的最大提升幅度(懒更新信息)\n\tpublic static long[] maxAddTop = new long[MAXN << 2];\n\n\t// 除最大值以外的其他数字，达到过的最大提升幅度(懒更新信息)\n\tpublic static long[] otherAddTop = new long[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tmaxHistory[i] = Math.max(maxHistory[l], maxHistory[r]);\n\t\tsum[i] = sum[l] + sum[r];\n\t\tmax[i] = Math.max(max[l], max[r]);\n\t\tif (max[l] > max[r]) {\n\t\t\tcnt[i] = cnt[l];\n\t\t\tsem[i] = Math.max(sem[l], max[r]);\n\t\t} else if (max[l] < max[r]) {\n\t\t\tcnt[i] = cnt[r];\n\t\t\tsem[i] = Math.max(max[l], sem[r]);\n\t\t} else {\n\t\t\tcnt[i] = cnt[l] + cnt[r];\n\t\t\tsem[i] = Math.max(sem[l], sem[r]);\n\t\t}\n\t}\n\n\t// maxAddv   : 最大值增加多少\n\t// otherAddv : 其他数增加多少\n\t// maxUpv    : 最大值达到过的最大提升幅度\n\t// otherUpv  : 其他数达到过的最大提升幅度\n\tpublic static void lazy(int i, int n, long maxAddv, long otherAddv, long maxUpv, long otherUpv) {\n\t\tmaxHistory[i] = Math.max(maxHistory[i], max[i] + maxUpv);\n\t\tmaxAddTop[i] = Math.max(maxAddTop[i], maxAdd[i] + maxUpv);\n\t\totherAddTop[i] = Math.max(otherAddTop[i], otherAdd[i] + otherUpv);\n\t\tsum[i] += maxAddv * cnt[i] + otherAddv * (n - cnt[i]);\n\t\tmax[i] += maxAddv;\n\t\tsem[i] += sem[i] == LOWEST ? 0 : otherAddv;\n\t\tmaxAdd[i] += maxAddv;\n\t\totherAdd[i] += otherAddv;\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tlong tmp = Math.max(max[l], max[r]);\n\t\tif (max[l] == tmp) {\n\t\t\tlazy(l, ln, maxAdd[i], otherAdd[i], maxAddTop[i], otherAddTop[i]);\n\t\t} else {\n\t\t\tlazy(l, ln, otherAdd[i], otherAdd[i], otherAddTop[i], otherAddTop[i]);\n\t\t}\n\t\tif (max[r] == tmp) {\n\t\t\tlazy(r, rn, maxAdd[i], otherAdd[i], maxAddTop[i], otherAddTop[i]);\n\t\t} else {\n\t\t\tlazy(r, rn, otherAdd[i], otherAdd[i], otherAddTop[i], otherAddTop[i]);\n\t\t}\n\t\tmaxAdd[i] = otherAdd[i] = maxAddTop[i] = otherAddTop[i] = 0;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = maxHistory[i] = arr[l];\n\t\t\tsem[i] = LOWEST;\n\t\t\tcnt[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\tmaxAdd[i] = otherAdd[i] = maxAddTop[i] = otherAddTop[i] = 0;\n\t}\n\n\tpublic static void add(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, r - l + 1, jobv, jobv, jobv, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMin(int jobl, int jobr, long jobv, int l, int r, int i) {\n\t\tif (jobv >= max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && sem[i] < jobv) {\n\t\t\tlazy(i, r - l + 1, jobv - max[i], 0, jobv - max[i], 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tlong ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static long queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tLong ans = LOWEST;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static long queryHistoryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn maxHistory[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tLong ans = LOWEST;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans = Math.max(ans, queryHistoryMax(jobl, jobr, l, mid, i << 1));\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans = Math.max(ans, queryHistoryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tint op, jobl, jobr;\n\t\tlong jobv;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tjobl = in.nextInt();\n\t\t\tjobr = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tjobv = in.nextInt();\n\t\t\t\tadd(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else if (op == 2) {\n\t\t\t\tjobv = in.nextInt();\n\t\t\t\tsetMin(jobl, jobr, jobv, 1, n, 1);\n\t\t\t} else if (op == 3) {\n\t\t\t\tout.println(querySum(jobl, jobr, 1, n, 1));\n\t\t\t} else if (op == 4) {\n\t\t\t\tout.println(queryMax(jobl, jobr, 1, n, 1));\n\t\t\t} else {\n\t\t\t\tout.println(queryHistoryMax(jobl, jobr, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code05_MaximumMinimumHistory1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
