e99adbec-e52d-41f7-810d-c277061a7001	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class114;\n\n// 最假女选手，java版\n// 这道题课上没讲，也是吉司机线段树的经典模版题\n// 这道题不涉及历史最值，所以比题目5简单\n// 如果理解了题目5，完全可以看懂如下的代码，重点的地方我加了注释\n// 给定一个长度为n的数组arr，然后是m条操作，类型如下\n// 操作 1 l r x : arr[l..r]范围内，每个数都加上x\n// 操作 2 l r x : arr[l..r]范围内，小于x的数都变成x\n// 操作 3 l r x : arr[l..r]范围内，大于x的数都变成x\n// 操作 4 l r   : 查询arr[l..r]累加和\n// 操作 5 l r   : 查询arr[l..r]最大值\n// 操作 6 l r   : 查询arr[l..r]最小值\n// 1 <= n、m <= 5 * 10^5    累加和需要long类型\n// 测试链接 : https://loj.ac/p/6565\n// 测试链接 : https://www.luogu.com.cn/problem/P10639\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_FakestPlayer1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static long[] sum = new long[MAXN << 2];\n\n\tpublic static int[] max = new int[MAXN << 2];\n\tpublic static int[] cntMax = new int[MAXN << 2];\n\tpublic static int[] sem = new int[MAXN << 2];\n\n\t// 区间最小值\n\tpublic static int[] min = new int[MAXN << 2];\n\t// 区间最小值的个数\n\tpublic static int[] cntMin = new int[MAXN << 2];\n\t// 区间严格次小值\n\tpublic static int[] sim = new int[MAXN << 2];\n\n\t// 整个区间统一增加的懒信息\n\tpublic static int[] addTag = new int[MAXN << 2];\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tsum[i] = sum[l] + sum[r];\n\t\tif (max[l] > max[r]) {\n\t\t\tmax[i] = max[l];\n\t\t\tcntMax[i] = cntMax[l];\n\t\t\tsem[i] = Math.max(sem[l], max[r]);\n\t\t} else if (max[l] < max[r]) {\n\t\t\tmax[i] = max[r];\n\t\t\tcntMax[i] = cntMax[r];\n\t\t\tsem[i] = Math.max(max[l], sem[r]);\n\t\t} else {\n\t\t\tmax[i] = max[l];\n\t\t\tcntMax[i] = cntMax[l] + cntMax[r];\n\t\t\tsem[i] = Math.max(sem[l], sem[r]);\n\t\t}\n\t\tif (min[l] < min[r]) {\n\t\t\tmin[i] = min[l];\n\t\t\tcntMin[i] = cntMin[l];\n\t\t\tsim[i] = Math.min(sim[l], min[r]);\n\t\t} else if (min[l] > min[r]) {\n\t\t\tmin[i] = min[r];\n\t\t\tcntMin[i] = cntMin[r];\n\t\t\tsim[i] = Math.min(min[l], sim[r]);\n\t\t} else {\n\t\t\tmin[i] = min[l];\n\t\t\tcntMin[i] = cntMin[l] + cntMin[r];\n\t\t\tsim[i] = Math.min(sim[l], sim[r]);\n\t\t}\n\t}\n\n\tpublic static void lazyAdd(int i, int n, int v) {\n\t\tsum[i] += 1L * v * n;\n\t\tmax[i] += v;\n\t\tsem[i] += sem[i] == -INF ? 0 : v;\n\t\tmin[i] += v;\n\t\tsim[i] += sim[i] == INF ? 0 : v;\n\t\taddTag[i] += v;\n\t}\n\n\t// 只把当前区间中的最大值压到v，要求sem[i] < v < max[i]\n\tpublic static void lazySetMin(int i, int v) {\n\t\tsum[i] += 1L * (v - max[i]) * cntMax[i];\n\t\tif (min[i] == max[i]) {\n\t\t\tmin[i] = v;\n\t\t} else if (sim[i] == max[i]) {\n\t\t\tsim[i] = v;\n\t\t}\n\t\tmax[i] = v;\n\t}\n\n\t// 只把当前区间中的最小值抬到v，要求min[i] < v < sim[i]\n\tpublic static void lazySetMax(int i, int v) {\n\t\tsum[i] += 1L * (v - min[i]) * cntMin[i];\n\t\tif (max[i] == min[i]) {\n\t\t\tmax[i] = v;\n\t\t} else if (sem[i] == min[i]) {\n\t\t\tsem[i] = v;\n\t\t}\n\t\tmin[i] = v;\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tif (addTag[i] != 0) {\n\t\t\tlazyAdd(l, ln, addTag[i]);\n\t\t\tlazyAdd(r, rn, addTag[i]);\n\t\t\taddTag[i] = 0;\n\t\t}\n\t\tif (max[l] > max[i]) {\n\t\t\tlazySetMin(l, max[i]);\n\t\t}\n\t\tif (min[l] < min[i]) {\n\t\t\tlazySetMax(l, min[i]);\n\t\t}\n\t\tif (max[r] > max[i]) {\n\t\t\tlazySetMin(r, max[i]);\n\t\t}\n\t\tif (min[r] < min[i]) {\n\t\t\tlazySetMax(r, min[i]);\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = min[i] = arr[l];\n\t\t\tsem[i] = -INF;\n\t\t\tsim[i] = INF;\n\t\t\tcntMax[i] = cntMin[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t\taddTag[i] = 0;\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazyAdd(i, r - l + 1, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMax(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobv <= min[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && jobv < sim[i]) {\n\t\t\tlazySetMax(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMax(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMax(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void setMin(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobv >= max[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr && sem[i] < jobv) {\n\t\t\tlazySetMin(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tsetMin(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tlong ans = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static int queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tint ans = -INF;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static int queryMin(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn min[i];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tint ans = INF;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tans = Math.min(ans, queryMin(jobl, jobr, l, mid, i << 1));\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tans = Math.min(ans, queryMin(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, op, l, r, x; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tadd(l, r, x, 1, n, 1);\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tsetMax(l, r, x, 1, n, 1);\n\t\t\t} else if (op == 3) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tsetMin(l, r, x, 1, n, 1);\n\t\t\t} else if (op == 4) {\n\t\t\t\tout.println(querySum(l, r, 1, n, 1));\n\t\t\t} else if (op == 5) {\n\t\t\t\tout.println(queryMax(l, r, 1, n, 1));\n\t\t\t} else {\n\t\t\t\tout.println(queryMin(l, r, 1, n, 1));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code06_FakestPlayer1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bd81da93-7dce-4d7a-b829-781bf28c651a	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class115;\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\n// 包含每个查询的最小区间\n// 给你一个二维整数数组intervals，其中intervals[i] = [l, r]\n// 表示第i个区间开始于l，结束于r，区间的长度是r-l+1\n// 给你一个整数数组queries，queries[i]表示要查询的位置\n// 答案是所有包含queries[i]的区间中，最小长度的区间是多长\n// 返回数组对应查询的所有答案，如果不存在这样的区间那么答案是-1\n// 测试链接 : https://leetcode.cn/problems/minimum-interval-to-include-each-query/\npublic class Code01_MinimumIntervalQuery1 {\n\n\t// 堆结构是现成结构\n\tpublic static int[] minInterval(int[][] intervals, int[] queries) {\n\t\tint n = intervals.length;\n\t\tint m = queries.length;\n\t\tArrays.sort(intervals, (a, b) -> a[0] - b[0]);\n\t\tint[][] ques = new int[m][2];\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tques[i][0] = queries[i];\n\t\t\tques[i][1] = i;\n\t\t}\n\t\tArrays.sort(ques, (a, b) -> a[0] - b[0]);\n\t\t// 0 : 长度\n\t\t// 1 : 影响到的位置\n\t\tPriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\t\tint[] ans = new int[m];\n\t\tfor (int i = 0, j = 0; i < m; i++) {\n\t\t\tfor (; j < n && intervals[j][0] <= ques[i][0]; j++) {\n\t\t\t\theap.add(new int[] { intervals[j][1] - intervals[j][0] + 1, intervals[j][1] });\n\t\t\t}\n\t\t\twhile (!heap.isEmpty() && heap.peek()[1] < ques[i][0]) {\n\t\t\t\theap.poll();\n\t\t\t}\n\t\t\tif (!heap.isEmpty()) {\n\t\t\t\tans[ques[i][1]] = heap.peek()[0];\n\t\t\t} else {\n\t\t\t\tans[ques[i][1]] = -1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_MinimumIntervalQuery1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
