ong ans = 0;\n//    if (jobl <= mid) {\n//        ans += query(jobl, jobr, addHistory + addTag[i], l, mid, ls[i]);\n//    }\n//    if (jobr > mid) {\n//        ans += query(jobl, jobr, addHistory + addTag[i], mid + 1, r, rs[i]);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    root[0] = build(1, n);\n//    char op;\n//    int x, y;\n//    long long z;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op;\n//        if (op == 'C') {\n//            cin >> x >> y >> z;\n//            root[t + 1] = add(x, y, z, 1, n, root[t]);\n//            t++;\n//        } else if (op == 'Q') {\n//            cin >> x >> y;\n//            cout << query(x, y, 0, 1, n, root[t]) << "\\n";\n//        } else if (op == 'H') {\n//            cin >> x >> y >> z;\n//            cout << query(x, y, 0, 1, n, root[z]) << "\\n";\n//        } else {\n//            cin >> x;\n//            t = x;\n//        }\n//    }\n//    return 0;\n//}	模板：Code05_RangePersistentLessSpace2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ab8a7493-b204-4973-a0bf-5bf1fa1b3f85	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 第一次出现位置的序列，java版\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询，每条查询格式如下\n// l r : arr[l..r]范围上，每个数第一次出现的位置，把这些位置组成一个序列\n//       假设该范围有s种不同的数，那么序列长度为s\n//       打印该序列第s/2个位置(向上取整)，对应arr的什么位置\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定的l和r，按照如下方式得到真实的l和r，查询完成后更新lastAns\n// a = (给定l + lastAns) % n + 1\n// b = (给定r + lastAns) % n + 1\n// 真实l = min(a, b)\n// 真实r = max(a, b)\n// 1 <= n、m <= 2 * 10^5    0 <= arr[i] <= 2 * 10^5\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5919\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.util.Arrays;\n\npublic class Code01_FirstTimeSequence1 {\n\n\tpublic static int MAXN = 200002;\n\n\tpublic static int MAXT = MAXN * 37;\n\n\tpublic static int cases, n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// pos[v] : v这个数字上次出现的位置\n\tpublic static int[] pos = new int[MAXN];\n\n\t// 可持久化线段树需要\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\t// 数组范围上只记录每种数第一次出现的位置，这样的位置有多少个\n\tpublic static int[] firstSize = new int[MAXT];\n\n\tpublic static int cnt;\n\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cnt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tleft[rt] = build(l, mid);\n\t\t\tright[rt] = build(mid + 1, r);\n\t\t}\n\t\tfirstSize[rt] = 0;\n\t\treturn rt;\n\t}\n\n\t// 数组范围l~r，信息在i号节点\n\t// 如果jobv = -1，意味着jobi位置减少一个计数\n\t// 如果jobv = +1，意味着jobi位置增加一个计数\n\t// 返回新的头节点编号\n\tpublic static int update(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = ++cnt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tfirstSize[rt] = firstSize[i] + jobv;\n\t\tif (l == r) {\n\t\t\treturn rt;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tif (jobi <= mid) {\n\t\t\tleft[rt] = update(jobi, jobv, l, mid, left[rt]);\n\t\t} else {\n\t\t\tright[rt] = update(jobi, jobv, mid + 1, r, right[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 数组范围l~r，信息在i号节点\n\t// jobl ~ jobr范围上，一共有几种不同的数字，也就是这个范围上，有多少个位置有1\n\tpublic static int querySize(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn firstSize[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += querySize(jobl, jobr, l, mid, left[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += querySize(jobl, jobr, mid + 1, r, right[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 数组范围l~r，信息在i号节点\n\t// 查询这个范围上，第jobk个1在哪\n\tpublic static int queryKth(int jobk, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint lsize = firstSize[left[i]];\n\t\tif (lsize >= jobk) {\n\t\t\treturn queryKth(jobk, l, mid, left[i]);\n\t\t} else {\n\t\t\treturn queryKth(jobk - lsize, mid + 1, r, right[i]);\n\t\t}\n\t}\n\n\t// 从右往左建立各个版本的线段树\n\tpublic static void prepare() {\n\t\tcnt = 0;\n\t\tArrays.fill(pos, 0);\n\t\troot[n + 1] = build(1, n);\n\t\tfor (int i = n; i >= 1; i--) {\n\t\t\tif (pos[arr[i]] == 0) {\n\t\t\t\troot[i] = update(i, 1, 1, n, root[i + 1]);\n\t\t\t} else {\n\t\t\t\troot[i] = update(pos[arr[i]], -1, 1, n, root[i + 1]);\n\t\t\t\troot[i] = update(i, 1, 1, n, root[i]);\n\t\t\t}\n\t\t\tpos[arr[i]] = i;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tReaderWriter io = new ReaderWriter();\n\t\tcases = io.nextInt();\n\t\tfor (int t = 1; t <= cases; t++) {\n\t\t\tn = io.nextInt();\n\t\t\tm = io.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tarr[i] = io.nextInt();\n\t\t\t}\n\t\t\tprepare();\n\t\t\tio.write("Case #");\n\t\t\tio.writeInt(t);\n\t\t\tio.write(":");\n\t\t\tfor (int i = 1, a, b, l, r, k, lastAns = 0; i <= m; i++) {\n\t\t\t\ta = (io.nextInt() + lastAns) % n + 1;\n\t\t\t\tb = (io.nextInt() + lastAns) % n + 1;\n\t\t\t\tl = Math.min(a, b);\n\t\t\t\tr = Math.max(a, b);\n\t\t\t\tk = (querySize(l, r, 1, n, root[l]) + 1) / 2;\n\t\t\t\tlastAns = queryKth(k, 1, n, root[l]);\n\t\t\t\tio.write(" ");\n\t\t\t\tio.writeInt(lastAns);\n\t\t\t}\n\t\t\tio.write("\\n");\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class ReaderWriter {\n\t\tprivate static final int BUFFER_SIZE = 1 << 9;\n\t\tprivate byte[] inBuf = new byte[BUFFER_SIZE];\n\t\tprivate int bId, bSize;\n\t\tprivate final java.io.InputStream in;\n\n\t\tprivate byte[] outBuf = new byte[BUFFER_SIZE];\n\t\tprivate int oId;\n\t\tprivate final java.io.OutputStream out;\n\n\t\tReaderWriter() {\n\t\t\tin = System.in;\n\t\t\tout = System.out;\n\t\t}\n\n\t\tprivate byte read() throws IOException {\n\t\t\tif (bId == bSize) {\n\t\t\t\tbSize = in.read(inBuf);\n\t\t\t\tbId = 0;\n\t\t\t\tif (bSize == -1)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn inBuf[bId++];\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint s = 0;\n\t\t\tbyte c = read();\n\t\t\twhile (c <= ' ') {\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn -1;\n\t\t\t\tc = read();\n\t\t\t}\n\t\t\tboolean neg = (c == '-');\n\t\t\tif (neg)\n\t\t\t\tc = read();\n\t\t\twhile (c >= '0' && c <= '9') {\n\t\t\t\ts = s * 10 + (c - '0');\n\t\t\t\tc = read();\n\t\t\t}\n\t\t\treturn neg ? -s : s;\n\t\t}\n\n\t\tpublic void write(String s) throws IOException {\n\t\t\tfor (int i = 0; i < s.length(); i++) {\n\t\t\t\twriteByte((byte) s.charAt(i));\n\t\t\t}\n\t\t}\n\n\t\tpublic void writeInt(int x) throws IOException {\n\t\t\tif (x == 0) {\n\t\t\t\twriteByte((byte) '0');\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twriteByte((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint len = 0;\n\t\t\tbyte[] tmp = new byte[12];\n\t\t\twhile (x > 0) {\n\t\t\t\ttmp[len++] = (byte) ((x % 10) + '0');\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\twhile (len-- > 0) {\n\t\t\t\twriteByte(tmp[len]);\n\t\t\t}\n\t\t}\n\n\t\tprivate void writeByte(byte b) throws IOException {\n\t\t\tif (oId == BUFFER_SIZE) {\n\t\t\t\tflush();\n\t\t\t}\n\t\t\toutBuf[oId++] = b;\n\t\t}\n\n\t\tpublic void flush() throws IOException {\n\t\t\tif (oId > 0) {\n\t\t\t\tout.write(outBuf, 0, oId);\n\t\t\t\toId = 0;\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：Code01_FirstTimeSequence1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
68b254dd-061b-4bb8-a977-3e337e97bd4b	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 第一次出现位置的序列，C++版\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询，每条查询格式如下\n// l r : arr[l..r]范围上，每个数第一次出现的位置，把这些位置组成一个序列\n//       假设该范围有s种不同的数，那么序列长度为s\n//       打印该序列第s/2个位置(向上取整)，对应arr的什么位置\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定的l和r，按照如下方式得到真实的l和r，查询完成后更新lastAns\n// a = (给定l + lastAns) % n + 1\n// b = (给定r + lastAns) % n + 1\n// 真实l = min(a, b)\n// 真实r = max(a, b)\n// 1 <= n、m <= 2 * 10^5    0 <= arr[i] <= 2 * 10^5\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5919\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200002;\n//const int MAXT = MAXN * 37;\n//int cases, n, m;\n//int arr[MAXN];\n//int pos[MAXN];\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int firstSize[MAXT];\n//int cnt;\n//\n//int build(int l, int r) {\n//    int rt = ++cnt;\n//    if (l < r) {\n//        int mid = (l + r) / 2;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//    }\n//    firstSize[rt] = 0;\n//    return rt;\n//}\n//\n//int update(int jobi, int jobv, int l, int r, int i) {\n//    int rt = ++cnt;\n//    ls[rt] = ls[i];\n//    rs[rt] = rs[i];\n//    firstSize[rt] = firstSize[i] + jobv;\n//    if (l == r) {\n//        return rt;\n//    }\n//    int mid = (l + r) / 2;\n//    if (jobi <= mid) {\n//        ls[rt] = update(jobi, jobv, l, mid, ls[rt]);\n//    } else {\n//        rs[rt] = update(jobi, jobv, mid + 1, r, rs[rt]);\n//    }\n//    return rt;\n//}\n//\n//int querySize(int jobl, int jobr, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        return firstSize[i];\n//    }\n//    int mid = (l + r) / 2;\n//    int ans = 0;\n//    if (jobl <= mid) {\n//        ans += querySize(jobl, jobr, l, mid, ls[i]);\n//    }\n//    if (jobr > mid) {\n//        ans += querySize(jobl, jobr, mid + 1, r, rs[i]);\n//    }\n//    return ans;\n//}\n//