7e26f29a-a18e-4e92-a763-951bcff5f614	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 区间内没有出现的最小自然数，java版\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询\n// 每条查询 l r : 打印arr[l..r]内没有出现过的最小自然数，注意0是自然数\n// 请用在线算法解决该问题，因为可以设计强制在线的要求，让离线算法失效\n// 1 <= n、m <= 2 * 10^5\n// 0 <= arr[i] <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4137\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_MissingSmallest1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int MAXT = MAXN * 22;\n\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\t// 数字范围中，每个数字出现的最晚位置中，最左的位置在哪\n\tpublic static int[] lateLeft = new int[MAXT];\n\n\tpublic static int cnt;\n\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cnt;\n\t\tlateLeft[rt] = 0;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tleft[rt] = build(l, mid);\n\t\t\tright[rt] = build(mid + 1, r);\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 数字范围l~r，信息在i号节点\n\t// 数字范围上，jobi这个数字，最晚出现的位置更新为jobv\n\t// 返回新的头节点编号\n\tpublic static int update(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = ++cnt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tlateLeft[rt] = lateLeft[i];\n\t\tif (l == r) {\n\t\t\tlateLeft[rt] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[rt] = update(jobi, jobv, l, mid, left[rt]);\n\t\t\t} else {\n\t\t\t\tright[rt] = update(jobi, jobv, mid + 1, r, right[rt]);\n\t\t\t}\n\t\t\tlateLeft[rt] = Math.min(lateLeft[left[rt]], lateLeft[right[rt]]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 数字在l~r范围上，没有出现的最小自然数，课上重点图解\n\tpublic static int query(int pos, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tif (lateLeft[left[i]] < pos) {\n\t\t\t// l...mid范围上，每个数字最晚出现的位置中\n\t\t\t// 最左的位置如果在pos以左，说明l...mid范围上，一定有缺失的数字\n\t\t\treturn query(pos, l, mid, left[i]);\n\t\t} else {\n\t\t\t// 缺失的数字一定在mid+1....r范围\n\t\t\t// 因为l...r一定有缺失的数字才会来到这个范围的\n\t\t\t// 如果左侧不缺失，那缺失的数字一定在右侧范围上\n\t\t\treturn query(pos, mid + 1, r, right[i]);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tcnt = 0;\n\t\troot[0] = build(0, n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (arr[i] > n || arr[i] < 0) {\n\t\t\t\troot[i] = root[i - 1];\n\t\t\t} else {\n\t\t\t\troot[i] = update(arr[i], i, 0, n, root[i - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tr = (int) in.nval;\n\t\t\tout.println(query(l, 0, n, root[r]));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_MissingSmallest1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
91c2d9e0-6e70-4029-88da-0ea789ef8a13	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 区间内没有出现的最小自然数，C++版\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询\n// 每条查询 l r : 打印arr[l..r]内没有出现过的最小自然数，注意0是自然数\n// 请用在线算法解决该问题，因为可以设计强制在线的要求，让离线算法失效\n// 1 <= n、m <= 2 * 10^5\n// 0 <= arr[i] <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4137\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = MAXN * 22;\n//int n, m;\n//int arr[MAXN];\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int lateLeft[MAXT];\n//int cnt;\n//\n//int build(int l, int r) {\n//    int rt = ++cnt;\n//    lateLeft[rt] = 0;\n//    if (l < r) {\n//        int mid = (l + r) / 2;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//    }\n//    return rt;\n//}\n//\n//int update(int jobi, int jobv, int l, int r, int i) {\n//    int rt = ++cnt;\n//    ls[rt] = ls[i];\n//    rs[rt] = rs[i];\n//    lateLeft[rt] = lateLeft[i];\n//    if (l == r) {\n//        lateLeft[rt] = jobv;\n//    } else {\n//        int mid = (l + r) / 2;\n//        if (jobi <= mid) {\n//            ls[rt] = update(jobi, jobv, l, mid, ls[rt]);\n//        } else {\n//            rs[rt] = update(jobi, jobv, mid + 1, r, rs[rt]);\n//        }\n//        lateLeft[rt] = min(lateLeft[ls[rt]], lateLeft[rs[rt]]);\n//    }\n//    return rt;\n//}\n//\n//int query(int pos, int l, int r, int i) {\n//    if (l == r) {\n//        return l;\n//    }\n//    int mid = (l + r) / 2;\n//    if (lateLeft[ls[i]] < pos) {\n//        return query(pos, l, mid, ls[i]);\n//    } else {\n//        return query(pos, mid + 1, r, rs[i]);\n//    }\n//}\n//\n//void prepare() {\n//    cnt = 0;\n//    root[0] = build(0, n);\n//    for (int i = 1; i <= n; i++) {\n//        if (arr[i] > n || arr[i] < 0) {\n//            root[i] = root[i - 1];\n//        } else {\n//            root[i] = update(arr[i], i, 0, n, root[i - 1]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    prepare();\n//    for (int i = 1, l, r; i <= m; i++) {\n//        cin >> l >> r;\n//        cout << query(l, 0, n, root[r]) << "\\n";\n//    }\n//    return 0;\n//}	模板：Code02_MissingSmallest2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fbe857ff-8650-45f3-8eb4-d459525cbded	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 浮动区间的最大上中位数，java版\n// 为了方便理解，我改写了题意，但是改写的题意和原始题意等效\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询\n// 每条查询 a b c d : 左端点在[a,b]之间、右端点在[c,d]之间，保证a<b<c<d\n//                   哪个区间有最大的上中位数，打印最大的上中位数\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定四个参数，按照如下方式得到a、b、c、d，查询完成后更新lastAns\n// (给定的每个参数 + lastAns) % n + 1，得到四个值，从小到大对应a、b、c、d\n// 1 <= n <= 20000\n// 1 <= m <= 25000\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2839\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_LargestUpMedian1 {\n\n\tpublic static int MAXN = 20001;\n\n\tpublic static int MAXT = MAXN * 20;\n\n\tpublic static int INF = 10000001;\n\n\tpublic static int n, m;\n\n\t// 原始位置、数值\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\t// 可持久化线段树需要\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\t// 区间内最大前缀和，前缀不能为空\n\tpublic static int[] pre = new int[MAXT];\n\n\t// 区间内最大后缀和，后缀不能为空\n\tpublic static int[] suf = new int[MAXT];\n\n\t// 区间内累加和\n\tpublic static int[] sum = new int[MAXT];\n\n\tpublic static int cnt;\n\n\t// 查询的问题，a、b、c、d\n\tpublic static int[] ques = new int[4];\n\n\t// 收集区间信息，pre、suf、sum\n\tpublic static int[] info = new int[3];\n\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cnt;\n\t\tpre[rt] = suf[rt] = sum[rt] = r - l + 1;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tleft[rt] = build(l, mid);\n\t\t\tright[rt] = build(mid + 1, r);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tpre[i] = Math.max(pre[left[i]], sum[left[i]] + pre[right[i]]);\n\t\tsuf[i] = Math.max(suf[right[i]], suf[left[i]] + sum[right[i]]);\n\t\tsum[i] = sum[left[i]] + sum[right[i]];\n\t}\n\n\t// jobi位置，原来是1，现在改为-1\n\tpublic static int update(int jobi, int l, int r, int i) {\n\t\tint rt = ++cnt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tpre[rt] = pre[i];\n\t\tsuf[rt] = suf[i];\n\t\tsum[rt] = sum[i];\n\t\tif (l == r) {\n\t\t\tpre[rt] = suf[rt] = sum[rt] = -1;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[rt] = update(jobi, l, mid, left[rt]);\n\t\t\t} else {\n\t\t\t\tright[rt] = update(jobi, mid + 1, r, right[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void initInfo() {\n\t\tinfo[0] = info[1] = -INF;\n\t\tinfo[2] = 0;\n\t}\n\n\tpublic static void mergeRight(int r) {\n\t\tinfo[0] = Math.max(info[0], info[2] + pre[r]);\n\t\tinfo[1] = Math.max(suf[r], info[1] + sum[r]);\n\t\tinfo[2] += sum[r];\n\t}\n\n\tpublic static void query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tmergeRight(i);\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tquery(jobl, jobr, l, mid, left[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tquery(jobl, jobr, mid + 1, r, right[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tArrays.sort(arr, 1, n + 1, (a, b) -> a[1] - b[1]);\n\t\tcnt = 0;\n\t\troot[1] = build(1, n);\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\troot[i] = update(arr[i - 1][0], 1, n, root[i - 1]);\n\t\t}\n\t}\n\n\tpublic static boolean check(int a, int b, int c, int d, int v) {\n\t\tinitInfo();\n\t\tquery(a, b, 1, n, root[v]);\n\t\tint best = info[1];\n\t\tinitInfo();\n\t\tquery(c, d, 1, n, root[v]);\n\t\tbest += info[0];\n\t\tif (b + 1 <= c - 1) {\n\t\t\tinitInfo();\n\t\t\tquery(b + 1, c - 1, 1, n, root[v]);\n\t\t\tbest += info[2];\n\t\t}\n\t\treturn best >= 0;\n\t}\n\n\tpublic static int compute(int a, int b, int c, int d) {\n\t\tint left = 1, right = n, mid, ans = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (check(a, b, c, d, mid)) {\n\t\t\t\tans = arr[mid][1];\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = i;\n\t\t\tin.nextToken();\n\t\t\tarr[i][1] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, lastAns = 0; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tques[0] = ((int) in.nval + lastAns) % n + 1;\n\t\t\tin.nextToken();\n\t\t\tques[1] = ((int) in.nval + lastAns) % n + 1;\n\t\t\tin.nextToken();\n\t\t\tques[2] = ((int) in.nval + lastAns) % n + 1;\n\t\t\tin.nextToken();\n\t\t\tques[3] = ((int) in.nval + lastAns) % n + 1;\n\t\t\tArrays.sort(ques);\n\t\t\tlastAns = compute(ques[0], ques[1], ques[2], ques[3]);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_LargestUpMedian1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
009b785d-5dea-40e7-8926-e415dcf3acc6	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class158;\n\n// 浮动区间的最大上中位数，C++版\n// 为了方便理解，我改写了题意，但是改写的题意和原始题意等效\n// 给定一个长度为n的数组arr，下标1~n，一共有m条查询\n// 每条查询 a b c d : 左端点在[a,b]之间、右端点在[c,d]之间，保证a<b<c<d\n//                   哪个区间有最大的上中位数，打印最大的上中位数\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定四个参数，按照如下方式得到a、b、c、d，查询完成后更新lastAns\n// (给定的每个参数 + lastAns) % n + 1，得到四个值，从小到大对应a、b、c、d\n// 1 <= n <= 20000\n// 1 <= m <= 25000\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2839\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 20001;\n//const int MAXT = MAXN * 20;\n//const int INF = 10000001;\n//int n, m;\n//vector<pair<int, int>> arr;\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int pre[MAXT];\n//int suf[MAXT];\n//int sum[MAXT];\n//int cnt;\n//int ques[4], info[3];\n//\n//int build(int l, int r) {\n//    int rt = ++cnt;\n//    pre[rt] = suf[rt] = sum[rt] = r - l + 1;\n//    if (l < r) {\n//        int mid = (l + r) / 2;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//    }\n//    return rt;\n//}\n//\n//void up(int i) {\n//    pre[i] = max(pre[ls[i]], sum[ls[i]] + pre[rs[i]]);\n//    suf[i] = max(suf[rs[i]], suf[ls[i]] + sum[rs[i]]);\n//    sum[i] = sum[ls[i]] + sum[rs[i]];\n//}\n//\n//int update(int jobi, int l, int r, int i) {\n//    int rt = ++cnt;\n//    ls[rt] = ls[i];\n//    rs[rt] = rs[i];\n//    pre[rt] = pre[i];\n//    suf[rt] = suf[i];\n//    sum[rt] = sum[i];\n//    if (l == r) {\n//        pre[rt] = suf[rt] = sum[rt] = -1;\n//    } else {\n//        int mid = (l + r) / 2;\n//        if (jobi <= mid) {\n//            ls[rt] = update(jobi, l, mid, ls[rt]);\n//        } else {\n//            rs[rt] = update(jobi, mid + 1, r, rs[rt]);\n//        }\n//        up(rt);\n//    }\n//    return rt;\n//}\n//\n//void initInfo() {\n//    info[0] = info[1] = -INF;\n//    info[2] = 0;\