  in_bag_2[i] = false;\n//        head_2[i] = 0;\n//    }\n//    bag_siz = 0;\n//    cnt_2 = 0;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand((unsigned)time(nullptr));\n//    cout << "主席树优化建图" << endl;\n//    cout << "============" << endl;\n//    n = 100;\n//    v = 200;\n//    int weightMax = 1000;\n//    int round = 20;\n//    for (int t = 1; t <= round; t++) {\n//        cout << "第" << t << "轮" << endl;\n//        cout << "测试开始" << endl;\n//        cntt = n;\n//        rootOut[0] = buildOut(1, v);\n//        rootIn[0] = buildIn(1, v);\n//        int opCnt = 200;\n//        for (int i = 1; i <= opCnt; i++) {\n//            int op = random(4);\n//            if (op == 1) {\n//                int x = random(n);\n//                int xv = random(v);\n//                add(x, xv);\n//                add_2(x, xv);\n//            } else {\n//                int a = random(v);\n//                int b = random(v);\n//                int l = min(a, b);\n//                int r = max(a, b);\n//                a = random(v);\n//                b = random(v);\n//                int l2 = min(a, b);\n//                int r2 = max(a, b);\n//                int x = random(n);\n//                int w = random(weightMax);\n//                if (op == 2) {\n//                    rangeToX(l, r, x, w);\n//                    rangeToX_2(l, r, x, w);\n//                } else if (op == 3) {\n//                    xToRange(x, l, r, w);\n//                    xToRange_2(x, l, r, w);\n//                } else {\n//                    rangeToRange(l, r, l2, r2, w);\n//                    rangeToRange_2(l, r, l2, r2, w);\n//                }\n//            }\n//        }\n//        for (int x = 1; x <= n; x++) {\n//            for (int y = 1; y <= n; y++) {\n//                int ans1 = dijkstra(x, y);\n//                int ans2 = dijkstra2(x, y);\n//                if (ans1 != ans2) {\n//                    cout << "出错了!" << endl;\n