51ff6e76-637d-465c-a71e-deca7f26ba27	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class166;\n\n// 线段树分治模版题，java版\n// 一共有n个节点，一共有m条操作，每条操作是如下三种类型中的一种\n// 操作 0 x y : 点x和点y之间一定没有边，现在增加一条边\n// 操作 1 x y : 点x和点y之间一定存在边，现在删除这条边\n// 操作 2 x y : 查询点x和点y是否联通\n// 1 <= n <= 5000\n// 1 <= m <= 500000\n// 不强制在线，可以离线处理\n// 测试链接 : https://loj.ac/p/121\n// 提交以下的code，提交时类名改成"Main"，多提交几次，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\n\npublic class Code01_SegmentTreeDivideConquer1 {\n\n\t// 点的数量最大值\n\tpublic static int MAXN = 5001;\n\t// 操作数量最大值\n\tpublic static int MAXM = 500001;\n\t// 任务数量最大值\n\tpublic static int MAXT = 5000001;\n\n\tpublic static int n, m;\n\n\t// 操作类型op、端点u、端点v\n\tpublic static int[] op = new int[MAXM];\n\tpublic static int[] u = new int[MAXM];\n\tpublic static int[] v = new int[MAXM];\n\n\t// last[x][y] : 点x和点y的边，上次出现的时间点\n\tpublic static int[][] last = new int[MAXN][MAXN];\n\n\t// 可撤销并查集\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\t// 线段树每个区间拥有哪些任务的列表，链式前向星表示\n\tpublic static int[] head = new int[MAXM << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] tox = new int[MAXT];\n\tpublic static int[] toy = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\t// ans[i]为第i条操作的答案，只有查询操作才有答案\n\tpublic static boolean[] ans = new boolean[MAXM];\n\n\tpublic static void addEdge(int i, int x, int y) {\n\t\tnext[++cnt] = head[i];\n\t\ttox[cnt] = x;\n\t\ttoy[cnt] = y;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, joby);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tint unionCnt = 0;\n\t\tfor (int ei = head[i], x, y, fx, fy; ei > 0; ei = next[ei]) {\n\t\t\tx = tox[ei];\n\t\t\ty = toy[ei];\n\t\t\tfx = find(x);\n\t\t\tfy = find(y);\n\t\t\tif (fx != fy) {\n\t\t\t\tunion(fx, fy);\n\t\t\t\tunionCnt++;\n\t\t\t}\n\t\t}\n\t\tif (l == r) {\n\t\t\tif (op[l] == 2) {\n\t\t\t\tans[l] = find(u[l]) == find(v[l]);\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tdfs(l, mid, i << 1);\n\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tfor (int j = 1; j <= unionCnt; j++) {\n\t\t\tundo();\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tfor (int i = 1, t, x, y; i <= m; i++) {\n\t\t\tt = op[i];\n\t\t\tx = u[i];\n\t\t\ty = v[i];\n\t\t\tif (t == 0) {\n\t\t\t\tlast[x][y] = i;\n\t\t\t} else if (t == 1) {\n\t\t\t\tadd(last[x][y], i - 1, x, y, 1, m, 1);\n\t\t\t\tlast[x][y] = 0;\n\t\t\t}\n\t\t}\n\t\tfor (int x = 1; x <= n; x++) {\n\t\t\tfor (int y = x + 1; y <= n; y++) {\n\t\t\t\tif (last[x][y] != 0) {\n\t\t\t\t\tadd(last[x][y], m, x, y, 1, m, 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tfor (int i = 1, t, x, y; i <= m; i++) {\n\t\t\tt = io.nextInt();\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\top[i] = t;\n\t\t\tu[i] = Math.min(x, y);\n\t\t\tv[i] = Math.max(x, y);\n\t\t}\n\t\tprepare();\n\t\tdfs(1, m, 1);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (op[i] == 2) {\n\t\t\t\tif (ans[i]) {\n\t\t\t\t\tio.write("Y\\n");\n\t\t\t\t} else {\n\t\t\t\t\tio.write("N\\n");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code01_SegmentTreeDivideConquer1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
