d82c524e-d18e-4170-aa71-dbcfba3fa9f2	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class166;\n\n// 判断二分图，java版\n// 一共有n个节点，时刻的范围0~k，一共有m条操作，每条操作含义如下\n// 操作 x y l r : 点x到点y之间连一条边，该边在l时刻出现，在r时刻消失\n// 分别打印1时刻以内、2时刻以内..k时刻以内，图是不是二分图\n// 注意i时刻以内是0~i-1时间段的意思\n// 1 <= n、k <= 10^5    1 <= m <= 2 * 10^5\n// 1 <= x、y <= n       0 <= l、r <= k\n// 测试链接 : https://www.luogu.com.cn/problem/P5787\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\n\npublic class Code02_CheckBipartiteGraph1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = 3000001;\n\tpublic static int n, m, k;\n\n\tpublic static int[] father = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[][] rollback = new int[MAXN << 1][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] head = new int[MAXN << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] tox = new int[MAXT];\n\tpublic static int[] toy = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\tpublic static boolean[] ans = new boolean[MAXN];\n\n\tpublic static void addEdge(int i, int x, int y) {\n\t\tnext[++cnt] = head[i];\n\t\ttox[cnt] = x;\n\t\ttoy[cnt] = y;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, joby);\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tboolean check = true;\n\t\tint unionCnt = 0;\n\t\tfor (int ei = head[i]; ei > 0; ei = next[ei]) {\n\t\t\tint x = tox[ei], y = toy[ei], fx = find(x), fy = find(y);\n\t\t\tif (fx == fy) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t} else {\n\t\t\t\tunion(x, y + n);\n\t\t\t\tunion(y, x + n);\n\t\t\t\tunionCnt += 2;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tif (l == r) {\n\t\t\t\tans[l] = true;\n\t\t\t} else {\n\t\t\t\tint mid = (l + r) / 2;\n\t\t\t\tdfs(l, mid, i << 1);\n\t\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int k = l; k <= r; k++) {\n\t\t\t\tans[k] = false;\n\t\t\t}\n\t\t}\n\t\tfor (int k = 1; k <= unionCnt; k++) {\n\t\t\tundo();\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tk = io.nextInt();\n\t\tfor (int i = 1; i <= n * 2; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tfor (int i = 1, x, y, l, r; i <= m; i++) {\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tl = io.nextInt();\n\t\t\tr = io.nextInt();\n\t\t\tadd(l + 1, r, x, y, 1, k, 1);\n\t\t}\n\t\tdfs(1, k, 1);\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tif (ans[i]) {\n\t\t\t\tio.write("Yes\\n");\n\t\t\t} else {\n\t\t\t\tio.write("No\\n");\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code02_CheckBipartiteGraph1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
