d524abb6-c597-4712-a015-4c212d8e6660	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class166;\n\n// 独特事件，java版\n// 一共有n个节点，n-1条无向边，边给定颜色值，所有节点连成一棵树\n// 定义f(u, v) : 点u到点v的简单路径上恰好出现一次的颜色的数量\n// 打印 ∑(u = 1..n) ∑(v = u + 1..n) f(u, v) 的结果\n// 1 <= 颜色值 <= n <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1681F\n// 测试链接 : https://codeforces.com/problemset/problem/1681/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\n\npublic class Code04_UniqueOccurrences1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXT = 10000001;\n\tpublic static int n, v;\n\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\t// 每种颜色拥有哪些边的列表\n\tpublic static int[] headc = new int[MAXN];\n\tpublic static int[] nextc = new int[MAXN];\n\tpublic static int[] xc = new int[MAXN];\n\tpublic static int[] yc = new int[MAXN];\n\tpublic static int cntc = 0;\n\n\t// 颜色轴线段树的区间任务列表\n\tpublic static int[] headt = new int[MAXN << 2];\n\tpublic static int[] nextt = new int[MAXT];\n\tpublic static int[] xt = new int[MAXT];\n\tpublic static int[] yt = new int[MAXT];\n\tpublic static int cntt = 0;\n\n\tpublic static long ans = 0;\n\n\tpublic static void addEdgeC(int i, int x, int y) {\n\t\tnextc[++cntc] = headc[i];\n\t\txc[cntc] = x;\n\t\tyc[cntc] = y;\n\t\theadc[i] = cntc;\n\t}\n\n\tpublic static void addEdgeS(int i, int x, int y) {\n\t\tnextt[++cntt] = headt[i];\n\t\txt[cntt] = x;\n\t\tyt[cntt] = y;\n\t\theadt[i] = cntt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdgeS(i, jobx, joby);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tint unionCnt = 0;\n\t\tfor (int ei = headt[i]; ei > 0; ei = nextt[ei]) {\n\t\t\tunion(xt[ei], yt[ei]);\n\t\t\tunionCnt++;\n\t\t}\n\t\tif (l == r) {\n\t\t\tfor (int ei = headc[l], fx, fy; ei > 0; ei = nextc[ei]) {\n\t\t\t\tfx = find(xc[ei]);\n\t\t\t\tfy = find(yc[ei]);\n\t\t\t\tans += (long) siz[fx] * siz[fy];\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdfs(l, mid, i << 1);\n\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tfor (int k = 1; k <= unionCnt; k++) {\n\t\t\tundo();\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tv = n;\n\t\tfor (int i = 1, x, y, c; i < n; i++) {\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tc = io.nextInt();\n\t\t\taddEdgeC(c, x, y);\n\t\t\tif (c > 1) {\n\t\t\t\tadd(1, c - 1, x, y, 1, v, 1);\n\t\t\t}\n\t\t\tif (c < v) {\n\t\t\t\tadd(c + 1, v, x, y, 1, v, 1);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tdfs(1, v, 1);\n\t\tio.writelnLong(ans);\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void writelnLong(long x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code04_UniqueOccurrences1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
