d66f29ef-0000-48e4-81fa-90cc0821a2fd	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class166;\n\n// 大融合，java版\n// 一共有n个点，一共有q条操作，每条操作是如下两种类型中的一种\n// 操作 A x y : 点x和点y之间连一条边，保证之前x和y是不联通的\n// 操作 Q x y : 打印点x和点y之间这条边的负载，保证x和y之间有一条边\n// 边负载定义为，这条边两侧端点各自连通区大小的乘积\n// 1 <= n、q <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4219\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_GreatIntegration1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = 3000001;\n\tpublic static int n, q;\n\n\tpublic static int[] op = new int[MAXN];\n\tpublic static int[] u = new int[MAXN];\n\tpublic static int[] v = new int[MAXN];\n\n\t// 端点x、端点y、操作序号t\n\tpublic static int[][] event = new int[MAXN][3];\n\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] head = new int[MAXN << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] tox = new int[MAXT];\n\tpublic static int[] toy = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void addEdge(int i, int x, int y) {\n\t\tnext[++cnt] = head[i];\n\t\ttox[cnt] = x;\n\t\ttoy[cnt] = y;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, joby);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tint unionCnt = 0;\n\t\tfor (int ei = head[i]; ei > 0; ei = next[ei]) {\n\t\t\tunion(tox[ei], toy[ei]);\n\t\t\tunionCnt++;\n\t\t}\n\t\tif (l == r) {\n\t\t\tif (op[l] == 2) {\n\t\t\t\tans[l] = (long) siz[find(u[l])] * siz[find(v[l])];\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdfs(l, mid, i << 1);\n\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tfor (int k = 1; k <= unionCnt; k++) {\n\t\t\tundo();\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tevent[i][0] = u[i];\n\t\t\tevent[i][1] = v[i];\n\t\t\tevent[i][2] = i;\n\t\t}\n\t\tArrays.sort(event, 1, q + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);\n\t\tfor (int l = 1, r = 1; l <= q; l = ++r) {\n\t\t\tint x = event[l][0], y = event[l][1], t = event[l][2];\n\t\t\twhile (r + 1 <= q && event[r + 1][0] == x && event[r + 1][1] == y) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tfor (int i = l + 1; i <= r; i++) {\n\t\t\t\tadd(t, event[i][2] - 1, x, y, 1, q, 1);\n\t\t\t\tt = event[i][2] + 1;\n\t\t\t}\n\t\t\tif (t <= q) {\n\t\t\t\tadd(t, q, x, y, 1, q, 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tchar t;\n\t\tint x, y;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tt = in.nextChar();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\top[i] = t == 'A' ? 1 : 2;\n\t\t\tu[i] = Math.min(x, y);\n\t\t\tv[i] = Math.max(x, y);\n\t\t}\n\t\tprepare();\n\t\tdfs(1, q, 1);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tif (op[i] == 2) {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code05_GreatIntegration1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
