32ac2639-1807-4fcd-a32a-d320a2a655c3	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class166;\n\n// 连通图，java版\n// 一共有n个点，给定m条边，所有点一开始就连通在一起了\n// 一共有k条操作，每条操作格式如下\n// 操作 c ... : 操作涉及c条边，这些边的编号 ... 一共c个\n//              假设删掉这些边，打印整张图是否联通\n// 每条操作都是独立的，相互之间没有任何关系\n// 1 <= n、k <= 10^5\n// 1 <= m <= 2 * 10^5\n// 1 <= c <= 4\n// 测试链接 : https://www.luogu.com.cn/problem/P5227\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.util.Arrays;\n\npublic class Code06_ConnectedGraph1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXE = 400001;\n\tpublic static int MAXT = 10000001;\n\tpublic static int n, m, k;\n\n\tpublic static int[] u = new int[MAXM];\n\tpublic static int[] v = new int[MAXM];\n\n\tpublic static int[][] event = new int[MAXE][2];\n\tpublic static int ecnt = 0;\n\tpublic static boolean[] visit = new boolean[MAXM];\n\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] head = new int[MAXN << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] tox = new int[MAXT];\n\tpublic static int[] toy = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\tpublic static boolean[] ans = new boolean[MAXN];\n\n\tpublic static void addEdge(int i, int x, int y) {\n\t\tnext[++cnt] = head[i];\n\t\ttox[cnt] = x;\n\t\ttoy[cnt] = y;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, joby);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tboolean check = false;\n\t\tint unionCnt = 0;\n\t\tfor (int ei = head[i]; ei > 0; ei = next[ei]) {\n\t\t\tint x = tox[ei], y = toy[ei], fx = find(x), fy = find(y);\n\t\t\tif (fx != fy) {\n\t\t\t\tunion(fx, fy);\n\t\t\t\tunionCnt++;\n\t\t\t}\n\t\t\tif (siz[find(fx)] == n) {\n\t\t\t\tcheck = true;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int j = l; j <= r; j++) {\n\t\t\t\tans[j] = true;\n\t\t\t}\n\t\t} else {\n\t\t\tif (l == r) {\n\t\t\t\tans[l] = false;\n\t\t\t} else {\n\t\t\t\tint mid = (l + r) >> 1;\n\t\t\t\tdfs(l, mid, i << 1);\n\t\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t\tfor (int j = 1; j <= unionCnt; j++) {\n\t\t\tundo();\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tArrays.sort(event, 1, ecnt + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tint eid, t;\n\t\tfor (int l = 1, r = 1; l <= ecnt; l = ++r) {\n\t\t\teid = event[l][0];\n\t\t\tvisit[eid] = true;\n\t\t\twhile (r + 1 <= ecnt && event[r + 1][0] == eid) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tt = 1;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (t <= event[i][1] - 1) {\n\t\t\t\t\tadd(t, event[i][1] - 1, u[eid], v[eid], 1, k, 1);\n\t\t\t\t}\n\t\t\t\tt = event[i][1] + 1;\n\t\t\t}\n\t\t\tif (t <= k) {\n\t\t\t\tadd(t, k, u[eid], v[eid], 1, k, 1);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (!visit[i]) {\n\t\t\t\tadd(1, k, u[i], v[i], 1, k, 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tu[i] = io.nextInt();\n\t\t\tv[i] = io.nextInt();\n\t\t}\n\t\tk = io.nextInt();\n\t\tfor (int i = 1, c; i <= k; i++) {\n\t\t\tc = io.nextInt();\n\t\t\tfor (int j = 1; j <= c; j++) {\n\t\t\t\tevent[++ecnt][0] = io.nextInt();\n\t\t\t\tevent[ecnt][1] = i;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tdfs(1, k, 1);\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tif (ans[i]) {\n\t\t\t\tio.write("Connected\\n");\n\t\t\t} else {\n\t\t\t\tio.write("Disconnected\\n");\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code06_ConnectedGraph1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
