1fdac837-f16c-4cf1-9b3d-ececd1c5024a	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class167;\n\n// 打印所有合法数，java版\n// 一个长度为n的序列，一开始所有值都是0\n// 一共有q条操作，每条操作为 l r k : 序列[l..r]范围上，每个数字加k\n// 你可以随意选择操作来执行，但是每条操作只能执行一次\n// 如果你能让序列中的最大值正好为v，那么v就算一个合法数\n// 打印1~n范围内有多少合法数，并且从小到大打印所有的合法数\n// 1 <= k <= n、q <= 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/CF981E\n// 测试链接 : https://codeforces.com/problemset/problem/981/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_AdditionOnSegments1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXT = 500001;\n\tpublic static int BIT = 10000;\n\tpublic static int DEEP = 20;\n\tpublic static int INT_BIT = 32;\n\tpublic static int LEN = BIT / INT_BIT + 1;\n\tpublic static int n, q;\n\n\tpublic static int[] head = new int[MAXN << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] to = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\tpublic static int[] tmp = new int[LEN];\n\tpublic static int[] dp = new int[LEN];\n\tpublic static int[][] backup = new int[DEEP][LEN];\n\tpublic static int[] ans = new int[LEN];\n\n\t// 清空\n\tpublic static void clear(int[] bitset) {\n\t\tfor (int i = 0; i < LEN; i++) {\n\t\t\tbitset[i] = 0;\n\t\t}\n\t}\n\n\t// 位图set1 拷贝 位图set2\n\tpublic static void clone(int[] set1, int[] set2) {\n\t\tfor (int i = 0; i < LEN; i++) {\n\t\t\tset1[i] = set2[i];\n\t\t}\n\t}\n\n\t// 返回位图第i位的状态\n\tpublic static int getBit(int[] bitset, int i) {\n\t\treturn (bitset[i / INT_BIT] >> (i % INT_BIT)) & 1;\n\t}\n\n\t// 第i位的状态设置成v\n\tpublic static void setBit(int[] bitset, int i, int v) {\n\t\tif (v == 0) {\n\t\t\tbitset[i / INT_BIT] &= ~(1 << (i % INT_BIT));\n\t\t} else {\n\t\t\tbitset[i / INT_BIT] |= 1 << (i % INT_BIT);\n\t\t}\n\t}\n\n\t// 位图set1 或 位图set2\n\tpublic static void bitOr(int[] set1, int[] set2) {\n\t\tfor (int i = 0; i < LEN; i++) {\n\t\t\tset1[i] |= set2[i];\n\t\t}\n\t}\n\n\t// 位图ret 变成 位图bitset左移move位的状态\n\t// 不使用一位一位拷贝的方式，因为太慢了\n\t// 采用整块左移的方式，这样比较快\n\tpublic static void bitLeft(int[] ret, int[] bitset, int move) {\n\t\tclear(ret);\n\t\tif (move > BIT) {\n\t\t\treturn;\n\t\t}\n\t\tif (move <= 0) {\n\t\t\tclone(ret, bitset);\n\t\t\treturn;\n\t\t}\n\t\tint shift = move / INT_BIT;\n\t\tint offset = move % INT_BIT;\n\t\tif (offset == 0) {\n\t\t\tfor (int i = LEN - 1, j = i - shift; j >= 0; i--, j--) {\n\t\t\t\tret[i] = bitset[j];\n\t\t\t}\n\t\t} else {\n\t\t\tint carry = INT_BIT - offset, high, low;\n\t\t\tfor (int i = LEN - 1; i > shift; i--) {\n\t\t\t\thigh = bitset[i - shift] << offset;\n\t\t\t\tlow = bitset[i - shift - 1] >>> carry;\n\t\t\t\tret[i] = high | low;\n\t\t\t}\n\t\t\tret[shift] = bitset[0] << offset;\n\t\t}\n\t\t// 最高位BIT到最低位0，一共BIT+1个有效位\n\t\t// 其他更高位信息需要清空，rest就是有多少无效的更高位\n\t\tint rest = LEN * INT_BIT - (BIT + 1);\n\t\tif (rest > 0) {\n\t\t\tret[LEN - 1] &= (1 << (INT_BIT - rest)) - 1;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int i, int v) {\n\t\tnext[++cnt] = head[i];\n\t\tto[cnt] = v;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i, int dep) {\n\t\tclone(backup[dep], dp);\n\t\tfor (int e = head[i]; e > 0; e = next[e]) {\n\t\t\tbitLeft(tmp, dp, to[e]);\n\t\t\tbitOr(dp, tmp);\n\t\t}\n\t\tif (l == r) {\n\t\t\tbitOr(ans, dp);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdfs(l, mid, i << 1, dep + 1);\n\t\t\tdfs(mid + 1, r, i << 1 | 1, dep + 1);\n\t\t}\n\t\tclone(dp, backup[dep]);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, l, r, k; i <= q; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tk = in.nextInt();\n\t\t\tadd(l, r, k, 1, n, 1);\n\t\t}\n\t\tsetBit(dp, 0, 1);\n\t\tdfs(1, n, 1, 1);\n\t\tint ansCnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (getBit(ans, i) == 1) {\n\t\t\t\tansCnt++;\n\t\t\t}\n\t\t}\n\t\tout.println(ansCnt);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (getBit(ans, i) == 1) {\n\t\t\t\tout.print(i + " ");\n\t\t\t}\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_AdditionOnSegments1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8edb394c-ccc2-4aa3-961a-0ab34ecd6c47	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class167;\n\n// 打印所有合法数，C++版\n// 一个长度为n的序列，一开始所有值都是0\n// 一共有q条操作，每条操作为 l r k : 序列[l..r]范围上，每个数字加k\n// 你可以随意选择操作来执行，但是每条操作只能执行一次\n// 如果你能让序列中的最大值正好为v，那么v就算一个合法数\n// 打印1~n范围内有多少合法数，并且从小到大打印所有的合法数\n// 1 <= k <= n、q <= 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/CF981E\n// 测试链接 : https://codeforces.com/problemset/problem/981/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 10001;\n//const int MAXT = 500001;\n//const int BIT = 10000;\n//const int DEEP = 20;\n//\n//typedef bitset<BIT + 1> bs;\n//\n//int n, q;\n//int head[MAXN << 2];\n//int nxt[MAXT];\n//int to[MAXT];\n//int cnt = 0;\n//\n//bs dp;\n//bs backup[DEEP];\n//bs ans;\n//\n//void addEdge(int i, int v) {\n//    nxt[++cnt] = head[i];\n//    to[cnt] = v;\n//    head[i] = cnt;\n//}\n//\n//void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(i, jobv);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            add(jobl, jobr, jobv, l, mid, i << 1);\n//        }\n//        if (jobr > mid) {\n//            add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n//        }\n//    }\n//}\n//\n//void dfs(int l, int r, int i, int dep) {\n//    backup[dep] = dp;\n//    for (int e = head[i]; e > 0; e = nxt[e]) {\n//        dp |= dp << to[e];\n//    }\n//    if (l == r) {\n//        ans |= dp;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        dfs(l, mid, i << 1, dep + 1);\n//        dfs(mid + 1, r, i << 1 | 1, dep + 1);\n//    }\n//    dp = backup[dep];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> q;\n//    for (int i = 1, l, r, k; i <= q; i++) {\n//        cin >> l >> r >> k;\n//        add(l, r, k, 1, n, 1);\n//    }\n//    dp[0] = 1;\n//    dfs(1, n, 1, 1);\n//    int ansCnt = 0;\