af6d4abe-990c-452d-8c8b-a38600bc350e	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class167;\n\n// 八纵八横，java版\n// 一共有n个点，给定m条边，每条边的边权，用01字符串表达，初始时就保证图连通\n// 初始的m条边永不删除，接下来有q条操作，每种操作是如下三种类型中的一种\n// 操作 Add x y z  : 加入点x到点y的边，边权是z，z为01字符串，第k条添加操作，边的编号为k\n// 操作 Cancel k   : 删除编号为k的边\n// 操作 Change k z : 编号为k的边，边权修改成z，z为01字符串\n// 从1号点出发，最后回到1号点，边随便走，沿途所有边的边权异或起来\n// 打印只有初始m条边的情况下，异或最大值为多少，每一条操作结束后，都打印异或最大值为多少\n// 1 <= n、m <= 500    0 <= q <= 1000    1 <= 边权字符串长度 <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3733\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_EightVerticalHorizontal1 {\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXQ = 1001;\n\tpublic static int MAXT = 10001;\n\tpublic static int BIT = 999;\n\tpublic static int INT_BIT = 32;\n\n\t// 位图\n\tstatic class BitSet {\n\n\t\tpublic int len;\n\n\t\tpublic int[] arr;\n\n\t\tpublic BitSet() {\n\t\t\tlen = BIT / INT_BIT + 1;\n\t\t\tarr = new int[len];\n\t\t}\n\n\t\tpublic BitSet(String s) {\n\t\t\tlen = BIT / INT_BIT + 1;\n\t\t\tarr = new int[len];\n\t\t\tfor (int i = 0, j = s.length() - 1; i < s.length(); i++, j--) {\n\t\t\t\tset(i, s.charAt(j) - '0');\n\t\t\t}\n\t\t}\n\n\t\t// 返回第i位的状态\n\t\tpublic int get(int i) {\n\t\t\treturn (arr[i / INT_BIT] >> (i % INT_BIT)) & 1;\n\t\t}\n\n\t\t// 设置第i位的状态\n\t\tpublic void set(int i, int v) {\n\t\t\tif (v == 0) {\n\t\t\t\tarr[i / INT_BIT] &= ~(1 << (i % INT_BIT));\n\t\t\t} else {\n\t\t\t\tarr[i / INT_BIT] |= 1 << (i % INT_BIT);\n\t\t\t}\n\t\t}\n\n\t\t// 异或other每一位\n\t\tpublic void eor(BitSet other) {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tarr[i] ^= other.arr[i];\n\t\t\t}\n\t\t}\n\n\t\t// 清空每一位\n\t\tpublic void clear() {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tarr[i] = 0;\n\t\t\t}\n\t\t}\n\n\t}\n\n\tpublic static int n, m, q;\n\tpublic static int[] x = new int[MAXQ];\n\tpublic static int[] y = new int[MAXQ];\n\tpublic static BitSet[] w = new BitSet[MAXQ];\n\tpublic static int edgeCnt = 0;\n\tpublic static int[] last = new int[MAXQ];\n\n\t// 可撤销线性基\n\tpublic static BitSet[] basis = new BitSet[BIT + 1];\n\tpublic static int[] inspos = new int[BIT + 1];\n\tpublic static int basiz = 0;\n\n\t// 经典带权并查集，只做扁平化，不做小挂大\n\tpublic static int[] father = new int[MAXN];\n\tpublic static BitSet[] eor = new BitSet[MAXN];\n\n\t// 时间轴线段树上的区间任务列表\n\tpublic static int[] head = new int[MAXQ << 2];\n\tpublic static int[] next = new int[MAXT];\n\tpublic static int[] tox = new int[MAXT];\n\tpublic static int[] toy = new int[MAXT];\n\tpublic static BitSet[] tow = new BitSet[MAXT];\n\tpublic static int cnt = 0;\n\n\t// 每一步的最大异或值\n\tpublic static BitSet[] ans = new BitSet[MAXQ];\n\n\t// num插入线性基\n\tpublic static void insert(BitSet num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num.get(i) == 1) {\n\t\t\t\tif (basis[i].get(i) == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\tinspos[basiz++] = i;\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tnum.eor(basis[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 0这个数字结合线性基，得到的最大异或值返回\n\tpublic static BitSet maxEor() {\n\t\tBitSet ans = new BitSet();\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (ans.get(i) == 0 && basis[i].get(i) == 1) {\n\t\t\t\tans.eor(basis[i]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 线性基的撤销\n\tpublic static void cancel(int oldsiz) {\n\t\twhile (basiz > oldsiz) {\n\t\t\tbasis[inspos[--basiz]].clear();\n\t\t}\n\t}\n\n\t// 扁平化优化，find的同时修改eor，就是经典的带权并查集\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tint tmp = father[i];\n\t\t\tfather[i] = find(tmp);\n\t\t\teor[i].eor(eor[tmp]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static BitSet getEor(int i) {\n\t\tfind(i);\n\t\treturn eor[i];\n\t}\n\n\tpublic static void union(int u, int v, BitSet w) {\n\t\tint fu = find(u);\n\t\tint fv = find(v);\n\t\tBitSet weight = new BitSet();\n\t\tweight.eor(getEor(u));\n\t\tweight.eor(getEor(v));\n\t\tweight.eor(w);\n\t\tif (fu == fv) {\n\t\t\tinsert(weight);\n\t\t} else {\n\t\t\tfather[fv] = fu;\n\t\t\teor[fv] = weight;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int i, int x, int y, BitSet w) {\n\t\tnext[++cnt] = head[i];\n\t\ttox[cnt] = x;\n\t\ttoy[cnt] = y;\n\t\ttow[cnt] = w;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobx, int joby, BitSet jobw, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, joby, jobw);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, jobw, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobx, joby, jobw, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int l, int r, int i) {\n\t\tint oldsiz = basiz;\n\t\tfor (int e = head[i]; e > 0; e = next[e]) {\n\t\t\tunion(tox[e], toy[e], tow[e]);\n\t\t}\n\t\tif (l == r) {\n\t\t\tans[l] = maxEor();\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tdfs(l, mid, i << 1);\n\t\t\tdfs(mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tcancel(oldsiz);\n\t}\n\n\tpublic static void print(BitSet bs, PrintWriter out) {\n\t\tboolean flag = false;\n\t\tfor (int i = BIT, s; i >= 0; i--) {\n\t\t\ts = bs.get(i);\n\t\t\tif (s == 1) {\n\t\t\t\tflag = true;\n\t\t\t}\n\t\t\tif (flag) {\n\t\t\t\tout.print(s);\n\t\t\t}\n\t\t}\n\t\tif (!flag) {\n\t\t\tout.print(0);\n\t\t}\n\t\tout.println();\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\tbasis[i] = new BitSet();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\teor[i] = new BitSet();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint u = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tBitSet w = new BitSet(in.nextString());\n\t\t\tunion(u, v, w);\n\t\t}\n\t\tans[0] = maxEor();\n\t\tString op;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = in.nextString();\n\t\t\tif (op.equals("Add")) {\n\t\t\t\tedgeCnt++;\n\t\t\t\tx[edgeCnt] = in.nextInt();\n\t\t\t\ty[edgeCnt] = in.nextInt();\n\t\t\t\tw[edgeCnt] = new BitSet(in.nextString());\n\t\t\t\tlast[edgeCnt] = i;\n\t\t\t} else if (op.equals("Cancel")) {\n\t\t\t\tint k = in.nextInt();\n\t\t\t\tadd(last[k], i - 1, x[k], y[k], w[k], 1, q, 1);\n\t\t\t\tlast[k] = 0;\n\t\t\t} else {\n\t\t\t\tint k = in.nextInt();\n\t\t\t\tadd(last[k], i - 1, x[k], y[k], w[k], 1, q, 1);\n\t\t\t\tw[k] = new BitSet(in.nextString());\n\t\t\t\tlast[k] = i;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= edgeCnt; i++) {\n\t\t\tif (last[i] != 0) {\n\t\t\t\tadd(last[i], q, x[i], y[i], w[i], 1, q, 1);\n\t\t\t}\n\t\t}\n\t\tif (q > 0) {\n\t\t\tdfs(1, q, 1);\n\t\t}\n\t\tfor (int i = 0; i <= q; i++) {\n\t\t\tprint(ans[i], out);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate static final int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len) {\n\t\t\t\treturn true;\n\t\t\t}\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte()) {\n\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b)) {\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic String nextString() throws IOException {\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b)) {\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tStringBuilder sb = new StringBuilder(1000);\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tsb.append((char) b);\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}	模板：Code05_EightVerticalHorizontal1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
