main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    int q;\n//    cin >> q;\n//    for (int i = 1, op, x; i <= q; i++) {\n//        cin >> op;\n//        if (op == 3) {\n//            cout << mineor[1] << '\\n';\n//        } else {\n//            cin >> x;\n//            if (op == 1) {\n//                compute(x, 1);\n//            } else {\n//                compute(x, -1);\n//            }\n//        }\n//    }\n//    return 0;\n//}	模板：Code07_MinimumXor2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d34fe099-b905-4db3-bf84-5d4fffa079e4	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class181;\n\n// 晋升者计数，java版\n// 一共有n个人，给定每个人的能力值arr[i]，所有人组成一棵树，代表公司的组织\n// 1号人是整个公司的老板，从2号人开始，给定每个人的上司编号fa[i]\n// 打印第i号人为头的子树中，有多少个人的能力值 > 第i号人的能力值，一共n条打印\n// 1 <= n <= 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3605\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_PromotionCounting1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] siz = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsiz[i] = siz[ls[i]] + siz[rs[i]];\n\t}\n\n\tpublic static int add(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[rt]++;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[t1] += siz[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl > jobr || i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn siz[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tint ret = 0;\n\t\tif (jobl <= mid) {\n\t\t\tret += query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tret += query(jobl, jobr, mid + 1, r, rs[i]);\n\t\t}\n\t\treturn ret;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void calc1(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcalc1(v, u);\n\t\t\t\troot[u] = merge(1, cntv, root[u], root[v]);\n\t\t\t}\n\t\t}\n\t\tans[u] = query(arr[u] + 1, cntv, 1, cntv, root[u]);\n\t}\n\n\t// 递归函数改迭代需要的栈，不会改去看讲解118\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\t// calc1改迭代\n\tpublic static void calc2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\troot[u] = merge(1, cntv, root[u], root[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans[u] = query(arr[u] + 1, cntv, 1, cntv, root[u]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\tcntv = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[cntv] != sorted[i]) {\n\t\t\t\tsorted[++cntv] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\troot[i] = add(arr[i], 1, cntv, root[i]);\n\t\t}\n\t\t// calc1(1, 0);\n\t\tcalc2();\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 2, fa; i <= n; i++) {\n\t\t\tfa = in.nextInt();\n\t\t\taddEdge(fa, i);\n\t\t\taddEdge(i, fa);\n\t\t}\n\t\tcompute();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_PromotionCounting1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
