e82e8a78-3d80-48d3-a284-78bd15dbd1ec	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class181;\n\n// 永无乡，java版\n// 一共有n个岛，每个岛分配到一个不同的数字，数字范围1~n\n// 给定初始的m座桥梁，若干点会连通起来，接下来有q条操作，格式如下\n// 操作 B x y : x号岛和y号岛之间新修建了一座桥\n// 操作 Q x k : x号岛所在的连通区里，打印第k小的数字来自几号岛，不存在打印-1\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3224\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_NeverLand1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static int n, m, q;\n\n\t// pos[v] = i，表示数字v属于第i号岛\n\tpublic static int[] pos = new int[MAXN];\n\t// 并查集\n\tpublic static int[] father = new int[MAXN];\n\n\t// 权值线段树\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] siz = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static void up(int i) {\n\t\tsiz[i] = siz[ls[i]] + siz[rs[i]];\n\t}\n\n\tpublic static int add(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[rt]++;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[t1] += siz[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int jobk, int l, int r, int i) {\n\t\tif (i == 0 || jobk > siz[i]) {\n\t\t\treturn -1;\n\t\t}\n\t\tif (l == r) {\n\t\t\treturn pos[l];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (siz[ls[i]] >= jobk) {\n\t\t\treturn query(jobk, l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(jobk - siz[ls[i]], mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint xfa = find(x);\n\t\tint yfa = find(y);\n\t\tif (xfa != yfa) {\n\t\t\tfather[xfa] = yfa;\n\t\t\troot[yfa] = merge(1, n, root[yfa], root[xfa]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tint num;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum = in.nextInt();\n\t\t\tpos[num] = i;\n\t\t\tfather[i] = i;\n\t\t\troot[i] = add(num, 1, n, root[i]);\n\t\t}\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tunion(x, y);\n\t\t}\n\t\tq = in.nextInt();\n\t\tchar op;\n\t\tint x, y, k;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'B') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tunion(x, y);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tk = in.nextInt();\n\t\t\t\tout.println(query(k, 1, n, root[find(x)]));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code02_NeverLand1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
