6916fe77-b884-4c5d-bcd6-1f58ef912d78	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class181;\n\n// 雨天的尾巴，java版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树\n// 给定m条路径，格式 x y v，表示x到y路径上的每个点都收到一个数字v\n// 打印第i号点上，收到次数最多的数字，如果不止一种，打印值最小的数字\n// 如果某节点没有收到过数字，打印0\n// 一共n条打印\n// 1 <= n、m、v <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4556\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_RainyDayTail1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXV = 100000;\n\tpublic static int MAXT = MAXN * 50;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] maxCnt = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 递归改迭代需要\n\tpublic static int[][] ufe = new int[MAXN][3];\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改迭代\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void up(int i) {\n\t\tmaxCnt[i] = Math.max(maxCnt[ls[i]], maxCnt[rs[i]]);\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxCnt[rt] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxCnt[t1] += maxCnt[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (maxCnt[ls[i]] >= maxCnt[rs[i]]) {\n\t\t\treturn query(l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void calc1(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcalc1(v, u);\n\t\t\t\troot[u] = merge(1, MAXV, root[u], root[v]);\n\t\t\t}\n\t\t}\n\t\tif (maxCnt[root[u]] == 0) {\n\t\t\tans[u] = 0;\n\t\t} else {\n\t\t\tans[u] = query(1, MAXV, root[u]);\n\t\t}\n\t}\n\n\t// calc1改迭代\n\tpublic static void calc2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\troot[u] = merge(1, MAXV, root[u], root[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (maxCnt[root[u]] == 0) {\n\t\t\t\t\tans[u] = 0;\n\t\t\t\t} else {\n\t\t\t\t\tans[u] = query(1, MAXV, root[u]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tint lca = getLca(x, y);\n\t\t\tint lcafa = stjump[lca][0];\n\t\t\troot[x] = add(v, 1, 1, MAXV, root[x]);\n\t\t\troot[y] = add(v, 1, 1, MAXV, root[y]);\n\t\t\troot[lca] = add(v, -1, 1, MAXV, root[lca]);\n\t\t\troot[lcafa] = add(v, -1, 1, MAXV, root[lcafa]);\n\t\t}\n\t\t// calc1(1, 0);\n\t\tcalc2();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_RainyDayTail1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
