a3dd60aa-ca65-485f-a9d8-dddb2662f867	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class181;\n\n// 天天爱跑步，java版\n// 一共有n个点，给定n-1条边，所有节点组成一棵树\n// 每个点上都有一个观察员，给出每个观察员的观测时刻w[i]\n// 给出m个跑步者的路线，格式 x y : 该跑步者出发时刻为0，从x跑到y\n// 任何跑步者通过任何一条边，耗时都是1秒\n// 某个跑步者到达i号点的时刻 == w[i]，那么该跑步者才会被i号点的观察员观测到\n// 打印i号点的观察员，能观测到多少人，一共n条打印\n// 1 <= n、m、w[i] <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1600\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_LoveRunning1 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int MAXT = MAXN * 50;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\tpublic static int[] w = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int[] rtUp = new int[MAXN];\n\tpublic static int[] rtDown = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] sum = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 递归改迭代需要\n\tpublic static int[][] ufe = new int[MAXN][3];\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改迭代\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[ls[i]] + sum[rs[i]];\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[rt] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[t1] += sum[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int jobi, int l, int r, int i) {\n\t\tif (jobi < l || jobi > r || i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (l == r) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (jobi <= mid) {\n\t\t\treturn query(jobi, l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(jobi, mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void calc1(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcalc1(v, u);\n\t\t\t\trtUp[u] = merge(1, n, rtUp[u], rtUp[v]);\n\t\t\t\trtDown[u] = merge(-n, n, rtDown[u], rtDown[v]);\n\t\t\t}\n\t\t}\n\t\tans[u] = query(dep[u] + w[u], 1, n, rtUp[u]) + query(dep[u] - w[u], -n, n, rtDown[u]);\n\t}\n\n\t// calc1改迭代\n\tpublic static void calc2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\trtUp[u] = merge(1, n, rtUp[u], rtUp[v]);\n\t\t\t\t\t\trtDown[u] = merge(-n, n, rtDown[u], rtDown[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans[u] = query(dep[u] + w[u], 1, n, rtUp[u]) + query(dep[u] - w[u], -n, n, rtDown[u]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tw[i] = in.nextInt();\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tint lca = getLca(x, y);\n\t\t\tint lcafa = stjump[lca][0];\n\t\t\trtUp[x] = add(dep[x], 1, 1, n, rtUp[x]);\n\t\t\trtUp[lcafa] = add(dep[x], -1, 1, n, rtUp[lcafa]);\n\t\t\trtDown[y] = add(2 * dep[lca] - dep[x], 1, -n, n, rtDown[y]);\n\t\t\trtDown[lca] = add(2 * dep[lca] - dep[x], -1, -n, n, rtDown[lca]);\n\t\t}\n\t\t// calc1(1, 0);\n\t\tcalc2();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_LoveRunning1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
