\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    dfs();\n//    cout << ans << '\\n';\n//    return 0;\n//}	模板：Code05_MinimizeInversion2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
50769fea-4d66-40a8-8b5c-d8ef00d19cbb	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class182;\n\n// 领导集团问题，java版\n// 一共有n个节点，给定每个点的点权，所有节点组成一棵树\n// 已知1号节点是整棵树的头，其他节点的父亲节点都会给出\n// 如果你在树上选择了u、v两个节点，并且u是v的祖先节点的话\n// 那么需要保证 u的点权 <= v的点权，除此之外就没有别的限制了\n// 打印你最多能在树上选择几个点\n// 1 <= n <= 2 * 10^5\n// 1 <= 点权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4577\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_LeadersGroup1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = MAXN * 20;\n\tpublic static int n;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int cntg;\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] maxv = new int[MAXT];\n\tpublic static int[] addLazy = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void up(int i) {\n\t\tmaxv[i] = Math.max(maxv[ls[i]], maxv[rs[i]]);\n\t}\n\n\tpublic static void lazy(int i, int v) {\n\t\tif (i != 0) {\n\t\t\tmaxv[i] += v;\n\t\t\taddLazy[i] += v;\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (addLazy[i] > 0) {\n\t\t\tlazy(ls[i], addLazy[i]);\n\t\t\tlazy(rs[i], addLazy[i]);\n\t\t\taddLazy[i] = 0;\n\t\t}\n\t}\n\n\t// jobi来了个新值jobv，如果比之前获得的值更大就更新，否则不更新\n\tpublic static int update(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxv[rt] = Math.max(maxv[rt], jobv);\n\t\t} else {\n\t\t\tdown(rt);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = update(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = update(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 查询[jobl..jobr]范围上的最大值\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn maxv[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, l, mid, ls[i]));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, mid + 1, r, rs[i]));\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 线段树合并\n\t// max1代表dp[u][r+1...]的最大值，max2代表dp[v][r+1...]的最大值\n\tpublic static int merge(int l, int r, int t1, int t2, int max1, int max2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\tif (t1 != 0) {\n\t\t\t\tlazy(t1, max2);\n\t\t\t}\n\t\t\tif (t2 != 0) {\n\t\t\t\tlazy(t2, max1);\n\t\t\t}\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxv[t1] += Math.max(maxv[t2], max2);\n\t\t} else {\n\t\t\tdown(t1);\n\t\t\tdown(t2);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2], Math.max(max1, maxv[rs[t1]]), Math.max(max2, maxv[rs[t2]]));\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2], max1, max2);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static void dp(int u) {\n\t\tint sum = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tdp(v);\n\t\t\tsum += query(arr[u], cntv, 1, cntv, root[v]);\n\t\t\t// 不选u的情况，每棵子树合并一遍\n\t\t\troot[u] = merge(1, cntv, root[u], root[v], 0, 0);\n\t\t}\n\t\t// 选u的情况，最后sum需要加1\n\t\troot[u] = update(arr[u], sum + 1, 1, cntv, root[u]);\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++cntv] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, cntv + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= cntv; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tcntv = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 2, fa; i <= n; i++) {\n\t\t\tfa = in.nextInt();\n\t\t\taddEdge(fa, i);\n\t\t}\n\t\tprepare();\n\t\tdp(1);\n\t\tout.println(query(1, cntv, 1, cntv, root[1]));\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_LeadersGroup1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
