06c928ff-b76b-48a4-8478-10eb3a680f74	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class198;\n\n// 喵了个喵 II，树状数组优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_1 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 5000001;\n\tpublic static int MAXE = 20000001;\n\tpublic static int v, n, cntt;\n\n\t// 值v、位置i\n\tpublic static int[][] vi = new int[MAXN][2];\n\t// 左l、右r、决定编号x\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 树状数组\n\tpublic static int[] inTree = new int[MAXN];\n\tpublic static int[] outTree = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void addOut(int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint preo = outTree[i];\n\t\t\tint curo = ++cntt;\n\t\t\tif (preo > 0) {\n\t\t\t\taddEdge(preo, curo);\n\t\t\t}\n\t\t\taddEdge(x, curo);\n\t\t\toutTree[i] = curo;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void addIn(int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint prei = inTree[i];\n\t\t\tint curi = ++cntt;\n\t\t\tif (prei > 0) {\n\t\t\t\taddEdge(curi, prei);\n\t\t\t}\n\t\t\taddEdge(curi, x);\n\t\t\tinTree[i] = curi;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int i, int x) {\n\t\twhile (i > 0) {\n\t\t\tif (outTree[i] > 0) {\n\t\t\t\taddEdge(outTree[i], x);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void xToRange(int x, int i) {\n\t\twhile (i > 0) {\n\t\t\tif (inTree[i] > 0) {\n\t\t\t\taddEdge(x, inTree[i]);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(group, 1, cntp + 1, (a, b) -> a[1] - b[1]);\n\t\tcntt = v << 1;\n\t\tfor (int i = 1; i <= cntp; i++) {\n\t\t\tint l = group[i][0];\n\t\t\t// 后缀查询转化成前缀查询\n\t\t\tint p = n - l + 1;\n\t\t\tint x = group[i][2];\n\t\t\txToRange(x, p);\n\t\t\trangeToX(p, other(x));\n\t\t\taddIn(p, other(x));\n\t\t\taddOut(p, x);\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tArrays.sort(vi, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\tint x = vi[i][0];\n\t\t\tint a = vi[i][1];\n\t\t\tint b = vi[i + 1][1];\n\t\t\tint c = vi[i + 2][1];\n\t\t\tint d = vi[i + 3][1];\n\t\t\taddGroup(a, c, x);\n\t\t\taddGroup(b, d, x);\n\t\t\taddGroup(a, b, x + v);\n\t\t\taddGroup(c, d, x + v);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= v << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tif (belong[i] == belong[i + v]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Meow_II_java_1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
