850a156d-b601-4e4f-b3f7-8e40fa7cae71	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class182;\n\n// 根节点的取值，java版\n// 一共有n个节点，1号节点是整棵树的头，所有节点组成一棵树\n// 给定一个长度为n的数组arr，如果节点x是叶，那么arr[x]表示点权，所有叶节点的点权都不同\n// 如果节点x不是叶，那么它最多有两个孩子，此时arr[x]代表概率，节点x按照以下规则取得点权\n// 以arr[x]的概率是所有儿子的点权最大值，以1 - arr[x]的概率是所有儿子的点权最小值\n// 表示概率时，arr[x]的范围是[1, 9999]，表示概率 0.0001 ~ 0.9999\n// 假设1号结点的权值有m种可能性，第i小的权值是Vi，取得概率为Di\n// 计算 i = 1..m 时，每一项 (i * Vi * Di * Di) 的累加和，答案对 998244353 取模\n// 1 <= n <= 3 * 10^5    1 <= 叶节点权值 <= 10^9    1 <= 概率 <= 9999\n// 测试链接 : https://www.luogu.com.cn/problem/P5298\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_Minimax1 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static final int MOD = 998244353;\n\tpublic static int n;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int[] sonCnt = new int[MAXN];\n\tpublic static int[][] son = new int[MAXN][2];\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static long[] sum = new long[MAXT];\n\tpublic static long[] mulLazy = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static long[] D = new long[MAXN];\n\n\tpublic static long power(long x, int p) {\n\t\tlong ans = 1;\n\t\twhile (p != 0) {\n\t\t\tif ((p & 1) != 0) {\n\t\t\t\tans = ans * x % MOD;\n\t\t\t}\n\t\t\tp >>= 1;\n\t\t\tx = x * x % MOD;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = (sum[ls[i]] + sum[rs[i]]) % MOD;\n\t}\n\n\tpublic static void lazy(int i, long v) {\n\t\tif (i != 0) {\n\t\t\tsum[i] = sum[i] * v % MOD;\n\t\t\tmulLazy[i] = mulLazy[i] * v % MOD;\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (mulLazy[i] != 1) {\n\t\t\tlazy(ls[i], mulLazy[i]);\n\t\t\tlazy(rs[i], mulLazy[i]);\n\t\t\tmulLazy[i] = 1;\n\t\t}\n\t}\n\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t\tmulLazy[rt] = 1;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[rt] = 1;\n\t\t} else {\n\t\t\tdown(rt);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = insert(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = insert(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2, int p, long sum1, long sum2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\tif (t1 != 0) {\n\t\t\t\tlazy(t1, sum2);\n\t\t\t}\n\t\t\tif (t2 != 0) {\n\t\t\t\tlazy(t2, sum1);\n\t\t\t}\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[t1] = (sum[t1] * sum2 % MOD + sum[t2] * sum1 % MOD) % MOD;\n\t\t} else {\n\t\t\tdown(t1);\n\t\t\tdown(t2);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tlong lsum1 = (sum1 + sum[rs[t1]] * (1 - p + MOD)) % MOD;\n\t\t\tlong lsum2 = (sum2 + sum[rs[t2]] * (1 - p + MOD)) % MOD;\n\t\t\tlong rsum1 = (sum1 + sum[ls[t1]] * p) % MOD;\n\t\t\tlong rsum2 = (sum2 + sum[ls[t2]] * p) % MOD;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2], p, lsum1, lsum2);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2], p, rsum1, rsum2);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\t// 迭代版，java会爆栈，C++可以通过\n\tpublic static void dp1(int u) {\n\t\tif (sonCnt[u] == 0) {\n\t\t\troot[u] = insert(arr[u], 1, cntv, root[u]);\n\t\t} else if (sonCnt[u] == 1) {\n\t\t\tdp1(son[u][0]);\n\t\t\troot[u] = root[son[u][0]];\n\t\t} else {\n\t\t\tdp1(son[u][0]);\n\t\t\tdp1(son[u][1]);\n\t\t\troot[u] = merge(1, cntv, root[son[u][0]], root[son[u][1]], arr[u], 0, 0);\n\t\t}\n\t}\n\n\t// dp1改成迭代版\n\tpublic static void dp2() {\n\t\tint[][] stack = new int[n + 1][2];\n\t\tint siz = 0;\n\t\tstack[++siz][0] = 1;\n\t\tstack[siz][1] = 0;\n\t\twhile (siz > 0) {\n\t\t\tint u = stack[siz][0];\n\t\t\tint s = stack[siz--][1];\n\t\t\tif (sonCnt[u] == 0) {\n\t\t\t\troot[u] = insert(arr[u], 1, cntv, root[u]);\n\t\t\t} else if (sonCnt[u] == 1) {\n\t\t\t\tif (s == 0) {\n\t\t\t\t\tstack[++siz][0] = u;\n\t\t\t\t\tstack[siz][1] = 1;\n\t\t\t\t\tstack[++siz][0] = son[u][0];\n\t\t\t\t\tstack[siz][1] = 0;\n\t\t\t\t} else {\n\t\t\t\t\troot[u] = root[son[u][0]];\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (s == 0) {\n\t\t\t\t\tstack[++siz][0] = u;\n\t\t\t\t\tstack[siz][1] = 1;\n\t\t\t\t\tstack[++siz][0] = son[u][1];\n\t\t\t\t\tstack[siz][1] = 0;\n\t\t\t\t\tstack[++siz][0] = son[u][0];\n\t\t\t\t\tstack[siz][1] = 0;\n\t\t\t\t} else {\n\t\t\t\t\troot[u] = merge(1, cntv, root[son[u][0]], root[son[u][1]], arr[u], 0, 0);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getd(int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn;\n\t\t}\n\t\tif (l == r) {\n\t\t\tD[l] = sum[i] % MOD;\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tgetd(l, mid, ls[i]);\n\t\t\tgetd(mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (fa[i] != 0) {\n\t\t\t\tson[fa[i]][sonCnt[fa[i]]++] = i;\n\t\t\t}\n\t\t}\n\t\tlong inv = power(10000, MOD - 2);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (sonCnt[i] == 0) {\n\t\t\t\tsorted[++cntv] = arr[i];\n\t\t\t} else {\n\t\t\t\tarr[i] = (int) (inv * arr[i] % MOD);\n\t\t\t}\n\t\t}\n\t\tArrays.sort(sorted, 1, cntv + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= cntv; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tcntv = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (sonCnt[i] == 0) {\n\t\t\t\tarr[i] = kth(arr[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfa[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\t// dp1(1);\n\t\tdp2();\n\t\tgetd(1, cntv, root[1]);\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= cntv; i++) {\n\t\t\tans = (ans + 1L * i * sorted[i] % MOD * D[i] % MOD * D[i]) % MOD;\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_Minimax1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
