b2e93df4-e7fb-43d1-b035-c9818e7bad9b	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class182;\n\n// 命运，java版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树，规定1号节点是树头\n// 给定m个点对，每个点对(x, y)，x是y的祖先节点，路径由从上到下的边组成\n// 树上的每条边都要涂上白色或者黑色，完全由你决定\n// 但是请保证每个点对的路径中，至少有一条黑色的边存在\n// 打印给树涂色的方法数，答案对 998244353 取模\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6773\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Fate1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static final int MOD = 998244353;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static long[] sum = new long[MAXT];\n\tpublic static long[] mulLazy = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] maxdep = new int[MAXN];\n\n\t// 讲解118，递归改迭代需要的栈\n\tpublic static int[][] ufe = new int[MAXN][3];\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = (sum[ls[i]] + sum[rs[i]]) % MOD;\n\t}\n\n\tpublic static void lazy(int i, long v) {\n\t\tif (i != 0) {\n\t\t\tsum[i] = sum[i] * v % MOD;\n\t\t\tmulLazy[i] = mulLazy[i] * v % MOD;\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (mulLazy[i] != 1) {\n\t\t\tlazy(ls[i], mulLazy[i]);\n\t\t\tlazy(rs[i], mulLazy[i]);\n\t\t\tmulLazy[i] = 1;\n\t\t}\n\t}\n\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t\tmulLazy[rt] = 1;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[rt] = 1;\n\t\t} else {\n\t\t\tdown(rt);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = insert(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = insert(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i] % MOD;\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans = query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = (ans + query(jobl, jobr, mid + 1, r, rs[i])) % MOD;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2, long sum1, long sum2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\tif (t1 != 0) {\n\t\t\t\tlazy(t1, sum2);\n\t\t\t}\n\t\t\tif (t2 != 0) {\n\t\t\t\tlazy(t2, sum1);\n\t\t\t}\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[t1] = ((sum[t1] * (sum2 + sum[t2])) % MOD + (sum[t2] * sum1) % MOD) % MOD;\n\t\t} else {\n\t\t\tdown(t1);\n\t\t\tdown(t2);\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tlong tmp1 = sum[ls[t1]];\n\t\t\tlong tmp2 = sum[ls[t2]];\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2], sum1, sum2);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2], sum1 + tmp1, sum2 + tmp2);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dp1(int u, int fa) {\n\t\troot[u] = insert(maxdep[u], 0, n, root[u]);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdp1(v, u);\n\t\t\t\troot[u] = merge(0, n, root[u], root[v], 0, query(0, dep[u], 0, n, root[v]));\n\t\t\t}\n\t\t}\n\t}\n\n\t// dp1的迭代版\n\tpublic static void dp2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\troot[u] = insert(maxdep[u], 0, n, root[u]);\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\troot[u] = merge(0, n, root[u], root[v], 0, query(0, dep[u], 0, n, root[v]));\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tmaxdep[y] = Math.max(maxdep[y], dep[x]);\n\t\t}\n\t\t// dp1(1, 0);\n\t\tdp2();\n\t\tlong ans = query(0, 0, 0, n, root[1]) % MOD;\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code03_Fate1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
