8a7e4b82-5328-4195-9d76-a89cbb03352b	7befaf8c-4299-43a7-a01e-e66c7e395b6a	java	package class182;\n\n// 值全改的操作，java版\n// 给定一个长度为n的数组arr，接下来有q条操作，格式如下\n// 操作 l r x y : arr[l..r]范围上，所有数字x改成数字y\n// 所有操作做完之后，从左到右打印arr中的值\n// 1 <= n、q <= 2 * 10^5\n// 1 <= arr[i]、x、y <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/CF911G\n// 测试链接 : https://codeforces.com/problemset/problem/911/G\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_MassChangeQueries1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int MAXV = 100;\n\tpublic static int n, q;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] root = new int[MAXV + 1];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static boolean[] status = new boolean[MAXT];\n\n\tpublic static int[] pool = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static void prepare() {\n\t\ttop = 0;\n\t\tfor (int i = 1; i < MAXT; i++) {\n\t\t\tpool[++top] = i;\n\t\t}\n\t}\n\n\tpublic static int newNode() {\n\t\treturn pool[top--];\n\t}\n\n\tpublic static void del(int i) {\n\t\tpool[++top] = i;\n\t\tls[i] = 0;\n\t\trs[i] = 0;\n\t\tstatus[i] = false;\n\t}\n\n\tpublic static void up(int i) {\n\t\tstatus[i] = status[ls[i]] | status[rs[i]];\n\t}\n\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = newNode();\n\t\t}\n\t\tif (l == r) {\n\t\t\tstatus[rt] = true;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = insert(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = insert(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tstatus[t1] |= status[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\tdel(t2);\n\t\treturn t1;\n\t}\n\n\tpublic static int tree1, tree2;\n\n\tpublic static void split(int jobl, int jobr, int l, int r, int t1) {\n\t\tif (t1 == 0) {\n\t\t\ttree1 = t1;\n\t\t\ttree2 = 0;\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\ttree1 = 0;\n\t\t\ttree2 = t1;\n\t\t\treturn;\n\t\t}\n\t\tint t2 = newNode();\n\t\tint mid = (l + r) >> 1;\n\t\tif (jobl <= mid) {\n\t\t\tsplit(jobl, jobr, l, mid, ls[t1]);\n\t\t\tls[t1] = tree1;\n\t\t\tls[t2] = tree2;\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tsplit(jobl, jobr, mid + 1, r, rs[t1]);\n\t\t\trs[t1] = tree1;\n\t\t\trs[t2] = tree2;\n\t\t}\n\t\tup(t1);\n\t\tup(t2);\n\t\ttree1 = t1;\n\t\ttree2 = t2;\n\t}\n\n\tpublic static void dfs(int val, int l, int r, int i) {\n\t\tif (i == 0 || !status[i]) {\n\t\t\treturn;\n\t\t}\n\t\tif (l == r) {\n\t\t\tarr[l] = val;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdfs(val, l, mid, ls[i]);\n\t\t\tdfs(val, mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tprepare();\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\troot[arr[i]] = insert(i, 1, n, root[arr[i]]);\n\t\t}\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, l, r, x, y; i <= q; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tsplit(l, r, 1, n, root[x]);\n\t\t\troot[x] = tree1;\n\t\t\troot[y] = merge(1, n, root[y], tree2);\n\t\t}\n\t\tfor (int v = 1; v <= MAXV; v++) {\n\t\t\tdfs(v, 1, n, root[v]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_MassChangeQueries1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
15bac0e8-90e3-4f56-8dac-eb5639db738c	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class198;\n\n// 喵了个喵 II，主席树优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_2 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 10000001;\n\tpublic static int MAXE = 50000001;\n\tpublic static int v, n, cntt;\n\n\tpublic static int[][] vi = new int[MAXN][2];\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 主席树\n\tpublic static int[] rootOut = new int[MAXN];\n\tpublic static int[] rootIn = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt);\n\t\t\taddEdge(rs[rt], rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt]);\n\t\t\taddEdge(rt, rs[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addOut(int jobi, int jobx, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(i, rt);\n\t\tif (l == r) {\n\t\t\taddEdge(jobx, rt);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = addOut(jobi, jobx, l, mid, ls[rt]);\n\t\t\t\taddEdge(ls[rt], rt);\n\t\t\t} else {\n\t\t\t\trs[rt] = addOut(jobi, jobx, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rs[rt], rt);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addIn(int jobi, int jobx, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(rt, i);\n\t\tif (l == r) {\n\t\t\taddEdge(rt, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = addIn(jobi, jobx, l, mid, ls[rt]);\n\t\t\t\taddEdge(rt, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = addIn(jobi, jobx, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rt, rs[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(group, 1, cntp + 1, (a, b) -> a[1] - b[1]);\n\t\tcntt = v << 1;\n\t\trootOut[0] = buildOut(1, n);\n\t\trootIn[0] = buildIn(1, n);\n\t\tfor (int i = 1; i <= cntp; i++) {\n\t\t\tint l = group[i][0];\n\t\t\tint r = group[i][1];\n\t\t\tint x = group[i][2];\n\t\t\txToRange(x, l, r, 1, n, rootIn[i - 1]);\n\t\t\trangeToX(l, r, other(x), 1, n, rootOut[i - 1]);\n\t\t\trootIn[i] = addIn(l, other(x), 1, n, rootIn[i - 1]);\n\t\t\trootOut[i] = addOut(l, x, 1, n, rootOut[i - 1]);\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tArrays.sort(vi, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\tint x = vi[i][0];\n\t\t\tint a = vi[i][1];\n\t\t\tint b = vi[i + 1][1];\n\t\t\tint c = vi[i + 2][1];\n\t\t\tint d = vi[i + 3][1];\n\t\t\taddGroup(a, c, x);\n\t\t\taddGroup(b, d, x);\n\t\t\taddGroup(a, b, x + v);\n\t\t\taddGroup(c, d, x + v);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= v << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tif (belong[i] == belong[i + v]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Meow_II_java_2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6021bd8b-8519-4cf4-bdb3-492398caee82	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class198;\n\n// 喵了个喵 II，cdq优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_3 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 5000001;\n\tpublic static int MAXE = 20000001;\n\tpublic static int v, n, cntt;\n\n\tpublic static int[][] vi = new int[MAXN][2];\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// cdq\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] tmp = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void merge(int l, int mid, int r) {\n\t\tint preOut = 0, curOut = 0, preIn = 0, curIn = 0;\n\t\tfor (int p1 = mid + 1, p2 = r; p2 >= mid + 1; p2--) {\n\t\t\tcurOut = ++cntt;\n\t\t\