}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Meow_II_java_3.java	2026-07-25 03:11:34.779768+00	2026-07-25