8dde8b16-6308-47ab-b1dd-2c28b0ecf244	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class108;\n\n// 树状数组单点增加、范围查询模版\n// 测试链接 : https://www.luogu.com.cn/problem/P3374\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_IndexTreeSingleAddIntervalQuery {\n\n\tpublic static int MAXN = 500001;\n\n\t// 原始数组的信息，根据课上说的关系，维护在树状数组中\n\t// 注意下标一定从1开始，不从0开始\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static int n, m;\n\n\t// 得到i最右侧的1的状态\n\t// 其他位都是0\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\t// 返回1~i范围累加和\n\tpublic static int sum(int i) {\n\t\tint ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int range(int l, int r) {\n\t\treturn sum(r) - sum(l - 1);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, v; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tadd(i, v);\n\t\t}\n\t\tfor (int i = 1, a, b, c; i <= m; i++) {\n\t\t\tin.nextToken(); a = (int) in.nval;\n\t\t\tin.nextToken(); b = (int) in.nval;\n\t\t\tin.nextToken(); c = (int) in.nval;\n\t\t\tif (a == 1) {\n\t\t\t\tadd(b, c);\n\t\t\t} else {\n\t\t\t\tout.println(range(b, c));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_IndexTreeSingleAddIntervalQuery.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
62d36da0-600b-443b-b6a2-9c483a3e826b	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class108;\n\n// 树状数组范围增加、单点查询模版\n// 测试链接 : https://www.luogu.com.cn/problem/P3368\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_IndexTreeIntervalAddSingleQuery {\n\n\tpublic static int MAXN = 500002;\n\n\t// 树状数组不维护原数组的信息，维护原数组的差分信息\n\t// 注意下标一定从1开始，不从0开始\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\t// 返回1~i范围累加和\n\tpublic static int sum(int i) {\n\t\tint ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, v; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tadd(i, v);\n\t\t\tadd(i + 1, -v);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tint op = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken(); int l = (int) in.nval;\n\t\t\t\tin.nextToken(); int r = (int) in.nval;\n\t\t\t\tin.nextToken(); int v = (int) in.nval;\n\t\t\t\tadd(l, v);\n\t\t\t\tadd(r + 1, -v);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tint index = (int) in.nval;\n\t\t\t\tout.println(sum(index));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_IndexTreeIntervalAddSingleQuery.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
37420130-7b74-4e58-92f7-ecf7778640a2	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class108;\n\n// 树状数组范围增加、范围查询模版\n// 测试链接 : https://www.luogu.com.cn/problem/P3372\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_IndexTreeIntervalAddIntervalQuery {\n\n\tpublic static int MAXN = 100001;\n\n\t// 维护原始数组的差分信息：Di\n\tpublic static long[] info1 = new long[MAXN];\n\n\t// 维护原始数组的差分加工信息：(i-1) * Di\n\tpublic static long[] info2 = new long[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(long[] tree, int i, long v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static long sum(long[] tree, int i) {\n\t\tlong ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 原始数组中[l..r]每个数值+v\n\tpublic static void add(int l, int r, long v) {\n\t\tadd(info1, l, v);\n\t\tadd(info1, r + 1, -v);\n\t\tadd(info2, l, (l - 1) * v);\n\t\tadd(info2, r + 1, -(r * v));\n\t}\n\n\t// 原始数组中[l..r]范围上的累加和\n\tpublic static long range(int l, int r) {\n\t\treturn sum(info1, r) * r - sum(info2, r) - sum(info1, l - 1) * (l - 1) + sum(info2, l - 1);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tlong cur;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcur = (long) in.nval;\n\t\t\tadd(i, i, cur);\n\t\t}\n\t\tlong v;\n\t\tfor (int i = 1, op, l, r; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken(); l = (int) in.nval;\n\t\t\t\tin.nextToken(); r = (int) in.nval;\n\t\t\t\tin.nextToken(); v = (long) in.nval;\n\t\t\t\tadd(l, r, v);\n\t\t\t} else {\n\t\t\t\tin.nextToken(); l = (int) in.nval;\n\t\t\t\tin.nextToken(); r = (int) in.nval;\n\t\t\t\tout.println(range(l, r));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_IndexTreeIntervalAddIntervalQuery.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
577abb01-32ef-4e02-b9c6-c9f4be1f8c8e	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class108;\n\n// 二维数组上单点增加、范围查询，使用树状数组的模版\n// 测试链接 : https://leetcode.cn/problems/range-sum-query-2d-mutable/\npublic class Code04_TwoDimensionSingleAddIntervalQuery {\n\n\tclass NumMatrix {\n\n\t\tpublic int[][] tree;\n\n\t\tpublic int[][] nums;\n\n\t\tpublic int n;\n\n\t\tpublic int m;\n\n\t\t// 入参二维数组下标从0开始\n\t\t// 树状数组一定下标从1开始\n\t\tpublic NumMatrix(int[][] matrix) {\n\t\t\tn = matrix.length;\n\t\t\tm = matrix[0].length;\n\t\t\ttree = new int[n + 1][m + 1];\n\t\t\tnums = new int[n + 1][m + 1];\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\t\tupdate(i, j, matrix[i][j]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tprivate int lowbit(int i) {\n\t\t\treturn i & -i;\n\t\t}\n\n\t\tprivate void add(int x, int y, int v) {\n\t\t\tfor (int i = x; i <= n; i += lowbit(i)) {\n\t\t\t\tfor (int j = y; j <= m; j += lowbit(j)) {\n\t\t\t\t\ttree[i][j] += v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// 从(1,1)到(x,y)这个部分的累加和\n\t\tprivate int sum(int x, int y) {\n\t\t\tint ans = 0;\n\t\t\tfor (int i = x; i > 0; i -= lowbit(i)) {\n\t\t\t\tfor (int j = y; j > 0; j -= lowbit(j)) {\n\t\t\t\t\tans += tree[i][j];\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\t// 实际二维数组的位置是(x,y)\n\t\t// 树状数组上的位置是(x+1, y+1)\n\t\t// 题目说的是单点更新，转化成单点增加(老值-新值)即可\n\t\t// 不要忘了在nums中把老值改成新值\n\t\tpublic void update(int x, int y, int v) {\n\t\t\tadd(x + 1, y + 1, v - nums[x + 1][y + 1]);\n\t\t\tnums[x + 1][y + 1] = v;\n\t\t}\n\n\t\t// 实际二维数组的位置是(x,y)\n\t\t// 树状数组上的位置是(x+1, y+1)\n\t\tpublic int sumRegion(int a, int b, int c, int d) {\n\t\t\treturn sum(c + 1, d + 1) - sum(a, d + 1) - sum(c + 1, b) + sum(a, b);\n\t\t}\n\n\t}\n\n}\n	模板：Code04_TwoDimensionSingleAddIntervalQuery.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c90f9b0f-b5d1-4dd0-bac5-fab2ed6b346d	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\n// 逆序对数量(归并分治)\n// 给定一个长度为n的数组arr\n// 如果 i < j 且 arr[i] > arr[j]\n// 那么(i,j)就是一个逆序对\n// 求arr中逆序对的数量\n// 1 <= n <= 5 * 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1908\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_NumberOfReversePair1 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] help = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\treturn f(1, n);\n\t}\n\n\t// 归并分治\n\t// 1) 统计i、j来自l~r范围的情况下，逆序对数量\n\t// 2) 统计完成后，让arr[l...r]变成有序的\n\tpublic static long f(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\treturn f(l, m) + f(m + 1, r) + merge(l, m, r);\n\t}\n\n\tpublic static long merge(int l, int m, int r) {\n\t\t// i来自l.....m\n\t\t// j来自m+1...r\n\t\t// 统计有多少逆序对\n\t\tlong ans = 0;\n\t\tfor (int i = m, j = r; i >= l; i--) {\n\t\t\twhile (j >= m + 1 && arr[i] <= arr[j]) {\n\t\t\t\tj--;\n\t\t\t}\n\t\t\tans += j - m;\n\t\t}\n\t\t// 左右部分合并，整体变有序，归并排序的过程\n\t\tint i = l;\n\t\tint a = l;\n\t\tint b = m + 1;\n\t\twhile (a <= m && b <= r) {\n\t\t\thelp[i++] = arr[a] <= arr[b] ? arr[a++] : arr[b++];\n\t\t}\n\t\twhile (a <= m) {\n\t\t\thelp[i++] = arr[a++];\n\t\t}\n\t\twhile (b <= r) {\n\t\t\thelp[i++] = arr[b++];\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tarr[i] = help[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_NumberOfReversePair1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6017d06c-8737-49d7-8ac2-27fc9824f47f	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\n// 逆序对数量(值域树状数组)\n// 给定一个长度为n的数组arr\n// 如果 i < j 且 arr[i] > arr[j]\n// 那么(i,j)就是一个逆序对\n// 求arr中逆序对的数量\n// 1 <= n <= 5 * 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1908\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_NumberOfReversePair2 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] sort = new int[MAXN];\n\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= m) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\t// 1~i范围的累加和\n\tpublic static long sum(int i) {\n\t\tlong ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t\tsort[i] = arr[i];\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tArrays.sort(sort, 1, n + 1);\n\t\tm = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sort[m] != sort[i]) {\n\t\t\t\tsort[++m] = sort[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = rank(arr[i]);\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = n; i >= 1; i--) {\n\t\t\t// 右边有多少数字是 <= 当前数值 - 1\n\t\t\tans += sum(arr[i] - 1);\n\t\t\t// 增加当前数字的词频\n\t\t\tadd(arr[i], 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 给定原始值v\n\t// 返回排名值(排序部分1~m中的下标)\n\tpublic static int rank(int v) {\n\t\tint l = 1, r = m, mid;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) / 2;\n\t\t\tif (sort[mid] >= v) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_NumberOfReversePair2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5f975655-5bfd-4068-8cca-2185963c6b38	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\n// 升序三元组数量\n// 给定一个数组arr，如果i < j < k且arr[i] < arr[j] < arr[k]\n// 那么称(i, j, k)为一个升序三元组\n// 返回arr中升序三元组的数量\n// 测试链接 : https://www.luogu.com.cn/problem/P1637\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_IncreasingTriples {\n\n\tpublic static int MAXN = 30001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] sort = new int[MAXN];\n\n\t// 维护信息 : 课上讲的up1数组\n\t// tree1不是up1数组，是up1数组的树状数组\n\tpublic static long[] tree1 = new long[MAXN];\n\n\t// 维护信息 : 课上讲的up2数组\n\t// tree2不是up2数组，是up2数组的树状数组\n\tpublic static long[] tree2 = new long[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(long[] tree, int i, long c) {\n\t\twhile (i <= m) {\n\t\t\ttree[i] += c;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static long sum(long[] tree, int i) {\n\t\tlong ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t\tsort[i] = arr[i];\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// 时间复杂度O(n * logn)\n\tpublic static long compute() {\n\t\tArrays.sort(sort, 1, n + 1);\n\t\tm = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sort[m] != sort[i]) {\n\t\t\t\tsort[++m] = sort[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = rank(arr[i]);\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t// 查询以当前值做结尾的升序三元组数量\n\t\t\tans += sum(tree2, arr[i] - 1);\n\t\t\t// 更新以当前值做结尾的升序一元组数量\n\t\t\tadd(tree1, arr[i], 1);\n\t\t\t// 更新以当前值做结尾的升序二元组数量\n\t\t\tadd(tree2, arr[i], sum(tree1, arr[i] - 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int rank(int v) {\n\t\tint l = 1, r = m, mid;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) / 2;\n\t\t\tif (sort[mid] >= v) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code02_IncreasingTriples.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0a1ec31c-2354-4fc2-8b02-dfa28e1eef61	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\nimport java.util.Arrays;\n\n// 最长递增子序列的个数\n// 给定一个未排序的整数数组nums，返回最长递增子序列的个数\n// 测试链接 : https://leetcode.cn/problems/number-of-longest-increasing-subsequence/\n// 本题在讲解072，最长递增子序列问题与扩展，就做出过预告\n// 具体可以看讲解072视频最后的部分\n// 用树状数组实现时间复杂度O(n * logn)\npublic class Code03_NumberOfLIS {\n\n\tpublic static int MAXN = 2001;\n\n\tpublic static int[] sort = new int[MAXN];\n\n\t// 维护信息 : 以数值i结尾的最长递增子序列，长度是多少\n\t// 维护的信息以树状数组组织\n\tpublic static int[] treeMaxLen = new int[MAXN];\n\n\t// 维护信息 : 以数值i结尾的最长递增子序列，个数是多少\n\t// 维护的信息以树状数组组织\n\tpublic static int[] treeMaxLenCnt = new int[MAXN];\n\n\tpublic static int m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\t// 查询结尾数值<=i的最长递增子序列的长度，赋值给maxLen\n\t// 查询结尾数值<=i的最长递增子序列的个数，赋值给maxLenCnt\n\tpublic static int maxLen, maxLenCnt;\n\n\tpublic static void query(int i) {\n\t\tmaxLen = maxLenCnt = 0;\n\t\twhile (i > 0) {\n\t\t\tif (maxLen == treeMaxLen[i]) {\n\t\t\t\tmaxLenCnt += treeMaxLenCnt[i];\n\t\t\t} else if (maxLen < treeMaxLen[i]) {\n\t\t\t\tmaxLen = treeMaxLen[i];\n\t\t\t\tmaxLenCnt = treeMaxLenCnt[i];\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\t// 以数值i结尾的最长递增子序列，长度达到了len，个数增加了cnt\n\t// 更新树状数组\n\tpublic static void add(int i, int len, int cnt) {\n\t\twhile (i <= m) {\n\t\t\tif (treeMaxLen[i] == len) {\n\t\t\t\ttreeMaxLenCnt[i] += cnt;\n\t\t\t} else if (treeMaxLen[i] < len) {\n\t\t\t\ttreeMaxLen[i] = len;\n\t\t\t\ttreeMaxLenCnt[i] = cnt;\n\t\t\t}\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int findNumberOfLIS(int[] nums) {\n\t\tint n = nums.length;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsort[i] = nums[i - 1];\n\t\t}\n\t\tArrays.sort(sort, 1, n + 1);\n\t\tm = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sort[m] != sort[i]) {\n\t\t\t\tsort[++m] = sort[i];\n\t\t\t}\n\t\t}\n\t\tArrays.fill(treeMaxLen, 1, m + 1, 0);\n\t\tArrays.fill(treeMaxLenCnt, 1, m + 1, 0);\n\t\tint i;\n\t\tfor (int num : nums) {\n\t\t\ti = rank(num);\n\t\t\tquery(i - 1);\n\t\t\tif (maxLen == 0) {\n\t\t\t\t// 如果查出数值<=i-1结尾的最长递增子序列长度为0\n\t\t\t\t// 那么说明，以值i结尾的最长递增子序列长度就是1，计数增加1\n\t\t\t\tadd(i, 1, 1);\n\t\t\t} else {\n\t\t\t\t// 如果查出数值<=i-1结尾的最长递增子序列长度为maxLen != 0\n\t\t\t\t// 那么说明，以值i结尾的最长递增子序列长度就是maxLen + 1，计数增加maxLenCnt\n\t\t\t\tadd(i, maxLen + 1, maxLenCnt);\n\t\t\t}\n\t\t}\n\t\tquery(m);\n\t\treturn maxLenCnt;\n\t}\n\n\tpublic static int rank(int v) {\n\t\tint ans = 0;\n\t\tint l = 1, r = m, mid;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) / 2;\n\t\t\tif (sort[mid] >= v) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code03_NumberOfLIS.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
7c615c01-68e1-4d6d-90a6-9f9ef67c70e8	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\n// HH的项链\n// 一共有n个位置，每个位置颜色给定，i位置的颜色是arr[i]\n// 一共有m个查询，question[i] = {li, ri}\n// 表示第i条查询想查arr[li..ri]范围上一共有多少种不同颜色\n// 返回每条查询的答案\n// 1 <= n、m、arr[i] <= 10^6\n// 1 <= li <= ri <= n\n// 测试链接 : https://www.luogu.com.cn/problem/P1972\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n// 代码逻辑和课上讲的完全一致，但是重写了读写工具类，增加了io效率\n\nimport java.io.BufferedWriter;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.util.Arrays;\n\npublic class Code04_DifferentColors {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[][] query = new int[MAXN][3];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int[] map = new int[MAXN];\n\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int sum(int i) {\n\t\tint ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int range(int l, int r) {\n\t\treturn sum(r) - sum(l - 1);\n\t}\n\n\tpublic static void compute() {\n\t\tArrays.sort(query, 1, m + 1, (a, b) -> a[1] - b[1]);\n\t\tfor (int s = 1, q = 1, l, r, i; q <= m; q++) {\n\t\t\tr = query[q][1];\n\t\t\tfor (; s <= r; s++) {\n\t\t\t\tint color = arr[s];\n\t\t\t\tif (map[color] != 0) {\n\t\t\t\t\tadd(map[color], -1);\n\t\t\t\t}\n\t\t\t\tadd(s, 1);\n\t\t\t\tmap[color] = s;\n\t\t\t}\n\t\t\tl = query[q][0];\n\t\t\ti = query[q][2];\n\t\t\tans[i] = range(l, r);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tBufferedWriter out = new BufferedWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.write(ans[i] + "\\n");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic boolean hasNext() throws IOException {\n\t\t\twhile (hasNextByte()) {\n\t\t\t\tbyte b = buffer[ptr];\n\t\t\t\tif (!isWhitespace(b))\n\t\t\t\t\treturn true;\n\t\t\t\tptr++;\n\t\t\t}\n\t\t\treturn false;\n\t\t}\n\n\t\tpublic String next() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn null;\n\t\t\t} while (c <= ' ');\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > ' ') {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic double nextDouble() throws IOException {\n\t\t\tdouble num = 0, div = 1;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != '.' && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tif (b == '.') {\n\t\t\t\tb = readByte();\n\t\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\t\tnum += (b - '0') / (div *= 10);\n\t\t\t\t\tb = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code04_DifferentColors.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
451dd023-9b42-4a85-9877-2e76bb422f85	589f50c6-9fba-4220-81b9-5eb38cec4d76	java	package class109;\n\nimport java.util.Arrays;\n\n// 得到回文串的最少操作次数\n// 给你一个只包含小写英文字母的字符串s\n// 每一次操作可以选择s中两个相邻的字符进行交换\n// 返回将s变成回文串的最少操作次数\n// 输入数据会确保s一定能变成一个回文串\n// 测试链接 : https://leetcode.cn/problems/minimum-number-of-moves-to-make-palindrome/\npublic class Code05_MinimumNumberOfMovesToMakePalindrome {\n\n\tpublic static int MAXN = 2001;\n\n\tpublic static int MAXV = 26;\n\n\tpublic static int n;\n\n\tpublic static char[] s;\n\n\t// 所有字符的位置列表\n\tpublic static int[] end = new int[MAXV];\n\tpublic static int[] pre = new int[MAXN];\n\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXN];\n\n\t// 归并分治\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] help = new int[MAXN];\n\n\tpublic static void build() {\n\t\tArrays.fill(end, 0, MAXV, 0);\n\t\tArrays.fill(arr, 1, n + 1, 0);\n\t\tArrays.fill(tree, 1, n + 1, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(i, 1);\n\t\t}\n\t}\n\n\t// 字符v把下标j加入列表\n\tpublic static void push(int v, int j) {\n\t\tpre[j] = end[v];\n\t\tend[v] = j;\n\t}\n\n\t// 弹出当前v字符最后的下标\n\tpublic static int pop(int v) {\n\t\tint ans = end[v];\n\t\tend[v] = pre[end[v]];\n\t\treturn ans;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int sum(int i) {\n\t\tint ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 时间复杂度O(n * logn)\n\tpublic static int minMovesToMakePalindrome(String str) {\n\t\ts = str.toCharArray();\n\t\tn = s.length;\n\t\tbuild();\n\t\tfor (int i = 0, j = 1; i < n; i++, j++) {\n\t\t\tpush(s[i] - 'a', j);\n\t\t}\n\t\t// arr[i]记录每个位置的字符最终要去哪\n\t\tfor (int i = 0, l = 1, r, k; i < n; i++, l++) {\n\t\t\tif (arr[l] == 0) {\n\t\t\t\tr = pop(s[i] - 'a');\n\t\t\t\tif (l < r) {\n\t\t\t\t\tk = sum(l);\n\t\t\t\t\tarr[l] = k;\n\t\t\t\t\tarr[r] = n - k + 1;\n\t\t\t\t} else {\n\t\t\t\t\tarr[l] = (1 + n) / 2;\n\t\t\t\t}\n\t\t\t\tadd(r, -1);\n\t\t\t}\n\t\t}\n\t\treturn number(1, n);\n\t}\n\n\tpublic static int number(int l, int r) {\n\t\tif (l >= r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\treturn number(l, m) + number(m + 1, r) + merge(l, m, r);\n\t}\n\n\tpublic static int merge(int l, int m, int r) {\n\t\tint ans = 0;\n\t\tfor (int i = m, j = r; i >= l; i--) {\n\t\t\twhile (j >= m + 1 && arr[i] <= arr[j]) {\n\t\t\t\tj--;\n\t\t\t}\n\t\t\tans += j - m;\n\t\t}\n\t\tint i = l;\n\t\tint a = l;\n\t\tint b = m + 1;\n\t\twhile (a <= m && b <= r) {\n\t\t\thelp[i++] = arr[a] <= arr[b] ? arr[a++] : arr[b++];\n\t\t}\n\t\twhile (a <= m) {\n\t\t\thelp[i++] = arr[a++];\n\t\t}\n\t\twhile (b <= r) {\n\t\t\thelp[i++] = arr[b++];\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tarr[i] = help[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code05_MinimumNumberOfMovesToMakePalindrome.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
