e;\n//        in_bag_2[i] = false;\n//        head_2[i] = 0;\n//    }\n//    bag_siz = 0;\n//    cnt_2 = 0;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand((unsigned)time(nullptr));\n//    cout << "树状数组优化建图" << endl;\n//    cout << "============" << endl;\n//    n = 100;\n//    v = 200;\n//    int weightMax = 1000;\n//    int round = 20;\n//    for (int t = 1; t <= round; t++) {\n//        cout << "第" << t << "轮" << endl;\n//        cout << "测试开始" << endl;\n//        cntt = n;\n//        int opCnt = 200;\n//        for (int i = 1; i <= opCnt; i++) {\n//            int op = random(4);\n//            if (op == 1) {\n//                int x = random(n);\n//                int xv = random(v);\n//                add(x, xv);\n//                add_2(x, xv);\n//            } else {\n//                int p = random(v);\n//                int p2 = random(v);\n//                int x = random(n);\n//                int w = random(weightMax);\n//                if (op == 2) {\n//                    rangeToX(p, x, w);\n//                    rangeToX_2(p, x, w);\n//                } else if (op == 3) {\n//                    xToRange(x, p, w);\n//                    xToRange_2(x, p, w);\n//                } else {\n//                    rangeToRange(p, p2, w);\n//                    rangeToRange_2(p, p2, w);\n//                }\n//            }\n//        }\n//        for (int x = 1; x <= n; x++) {\n//            for (int y = 1; y <= n; y++) {\n//                int ans1 = dijkstra(x, y);\n//                int ans2 = dijkstra2(x, y);\n//                if (ans1 != ans2) {\n//                    cout << "出错了!" << endl;\n//                }\n//            }\n//        }\n//        clear();\n//        cout << "测试结束" << endl;\n//        cout << "=======" << endl;\n//    }\n//    return 0;\n//}	模板：Code01_Fenwick_Tree_Optimization_cpp.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
988994b4-1fa5-4530-82c7-f7647e8b1ce7	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class172;\n\n// Give Away，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 0 a b c : 打印arr[a..b]范围上>=c的数字个数\n// 操作 1 a b   : 把arr[a]的值改成b\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^5\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/SP18185\n// 测试链接 : https://www.spoj.com/problems/GIVEAWAY\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_GiveAway1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXB = 1001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\tpublic static void build() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tArrays.sort(sortv, bl[i], br[i] + 1);\n\t\t}\n\t}\n\n\tpublic static int getCnt(int i, int v) {\n\t\tint l = bl[i], r = br[i], m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (sortv[m] >= v) {\n\t\t\t\tans += r - m + 1;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int query(int l, int r, int v) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tans += getCnt(i, v);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void update(int i, int v) {\n\t\tint l = bl[bi[i]];\n\t\tint r = br[bi[i]];\n\t\tarr[i] = v;\n\t\tfor (int j = l; j <= r; j++) {\n\t\t\tsortv[j] = arr[j];\n\t\t}\n\t\tArrays.sort(sortv, l, r + 1);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, op, a, b, c; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tc = in.nextInt();\n\t\t\t\tout.println(query(a, b, c));\n\t\t\t} else {\n\t\t\t\tupdate(a, b);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_GiveAway1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
