91eda1fe-161b-4684-a4a4-4dccfe364c7a	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class172;\n\n// 教主的魔法，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 A l r v : 打印arr[l..r]范围上>=v的数字个数\n// 操作 M l r v : 把arr[l..r]范围上每个值都加上v\n// 1 <= n <= 10^6\n// 1 <= m <= 3000\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2801\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_Magic1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int MAXB = 1001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\tpublic static int[] lazy = new int[MAXB];\n\n\tpublic static void build() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tArrays.sort(sortv, bl[i], br[i] + 1);\n\t\t}\n\t}\n\n\tpublic static int getCnt(int i, int v) {\n\t\tv -= lazy[i];\n\t\tint l = bl[i], r = br[i], m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (sortv[m] >= v) {\n\t\t\t\tans += r - m + 1;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int innerQuery(int l, int r, int v) {\n\t\tv -= lazy[bi[l]];\n\t\tint ans = 0;\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tif (arr[i] >= v) {\n\t\t\t\tans++;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int query(int l, int r, int v) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tans = innerQuery(l, r, v);\n\t\t} else {\n\t\t\tans += innerQuery(l, br[bi[l]], v);\n\t\t\tans += innerQuery(bl[bi[r]], r, v);\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tans += getCnt(i, v);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void innerAdd(int l, int r, int v) {\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tarr[i] += v;\n\t\t}\n\t\tfor (int i = bl[bi[l]]; i <= br[bi[l]]; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sortv, bl[bi[l]], br[bi[l]] + 1);\n\t}\n\n\tpublic static void add(int l, int r, int v) {\n\t\tif (bi[l] == bi[r]) {\n\t\t\tinnerAdd(l, r, v);\n\t\t} else {\n\t\t\tinnerAdd(l, br[bi[l]], v);\n\t\t\tinnerAdd(bl[bi[r]], r, v);\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tlazy[i] += v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild();\n\t\tchar op;\n\t\tint l, r, v;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (op == 'A') {\n\t\t\t\tout.println(query(l, r, v));\n\t\t\t} else {\n\t\t\t\tadd(l, r, v);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code02_Magic1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
