ad305d26-001a-4993-ad0f-f7520a4d6dff	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class172;\n\n// 作诗，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上，有多少个数出现正偶数次\n// 1 <= 所有数值 <= 10^5\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P4135\n// 提交交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Poem1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int n, c, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\t// freq[i][j]表示前i块中j出现的次数\n\tpublic static int[][] freq = new int[MAXB][MAXN];\n\t// even[i][j]表示从第i块到第j块，有多少个数出现正偶数次\n\tpublic static int[][] even = new int[MAXB][MAXB];\n\t// 数字词频统计\n\tpublic static int[] numCnt = new int[MAXN];\n\n\t// 返回从l块到r块，数字v的次数\n\tpublic static int getCnt(int l, int r, int v) {\n\t\treturn freq[r][v] - freq[l - 1][v];\n\t}\n\n\t// 某种数的之前词频是pre，现在如果词频加1\n\t// 返回 出现正偶数次的数字个数 的变化量\n\tpublic static int delta(int pre) {\n\t\tif (pre == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif ((pre & 1) == 0) {\n\t\t\treturn -1;\n\t\t}\n\t\treturn 1;\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = bl[i]; j <= br[i]; j++) {\n\t\t\t\tfreq[i][arr[j]]++;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= c; j++) {\n\t\t\t\tfreq[i][j] += freq[i - 1][j];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = i; j <= bnum; j++) {\n\t\t\t\teven[i][j] = even[i][j - 1];\n\t\t\t\tfor (int k = bl[j]; k <= br[j]; k++) {\n\t\t\t\t\teven[i][j] += delta(numCnt[arr[k]]);\n\t\t\t\t\tnumCnt[arr[k]]++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int j = 1; j <= c; j++) {\n\t\t\t\tnumCnt[j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans += delta(numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t} else {\n\t\t\tans = even[bi[l] + 1][bi[r] - 1];\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tans += delta(getCnt(bi[l] + 1, bi[r] - 1, arr[i]) + numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tans += delta(getCnt(bi[l] + 1, bi[r] - 1, arr[i]) + numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tc = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, a, b, l, r, lastAns = 0; i <= m; i++) {\n\t\t\ta = (in.nextInt() + lastAns) % n + 1;\n\t\t\tb = (in.nextInt() + lastAns) % n + 1;\n\t\t\tl = Math.min(a, b);\n\t\t\tr = Math.max(a, b);\n\t\t\tlastAns = query(l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_Poem1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
