d68b7856-de1f-483e-bf3c-2055d5aed733	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class173;\n\n// 由乃打扑克，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，操作类型如下\n// 操作 1 l r v : 查询arr[l..r]范围上，第v小的数\n// 操作 2 l r v : arr[l..r]范围上每个数加v，v可能是负数\n// 1 <= n、m <= 10^5\n// -2 * 10^4 <= 数组中的值 <= +2 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P5356\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_Poker1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 1001;\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\tpublic static int[] lazy = new int[MAXB];\n\n\tpublic static void innerAdd(int l, int r, int v) {\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tarr[i] += v;\n\t\t}\n\t\tfor (int i = bl[bi[l]]; i <= br[bi[l]]; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sortv, bl[bi[l]], br[bi[l]] + 1);\n\t}\n\n\tpublic static void add(int l, int r, int v) {\n\t\tif (bi[l] == bi[r]) {\n\t\t\tinnerAdd(l, r, v);\n\t\t} else {\n\t\t\tinnerAdd(l, br[bi[l]], v);\n\t\t\tinnerAdd(bl[bi[r]], r, v);\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tlazy[i] += v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getMin(int l, int r) {\n\t\tint lb = bi[l], rb = bi[r], ans = 10000000;\n\t\tif (lb == rb) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans = Math.min(ans, arr[i] + lazy[lb]);\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[lb]; i++) {\n\t\t\t\tans = Math.min(ans, arr[i] + lazy[lb]);\n\t\t\t}\n\t\t\tfor (int i = bl[rb]; i <= r; i++) {\n\t\t\t\tans = Math.min(ans, arr[i] + lazy[rb]);\n\t\t\t}\n\t\t\tfor (int i = lb + 1; i <= rb - 1; i++) {\n\t\t\t\tans = Math.min(ans, sortv[bl[i]] + lazy[i]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getMax(int l, int r) {\n\t\tint lb = bi[l], rb = bi[r], ans = -10000000;\n\t\tif (lb == rb) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans = Math.max(ans, arr[i] + lazy[lb]);\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[lb]; i++) {\n\t\t\t\tans = Math.max(ans, arr[i] + lazy[lb]);\n\t\t\t}\n\t\t\tfor (int i = bl[rb]; i <= r; i++) {\n\t\t\t\tans = Math.max(ans, arr[i] + lazy[rb]);\n\t\t\t}\n\t\t\tfor (int i = lb + 1; i <= rb - 1; i++) {\n\t\t\t\tans = Math.max(ans, sortv[br[i]] + lazy[i]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 返回第i块内<= v的数字个数\n\tpublic static int blockCnt(int i, int v) {\n\t\tv -= lazy[i];\n\t\tint l = bl[i], r = br[i];\n\t\tif (sortv[l] > v) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (sortv[r] <= v) {\n\t\t\treturn r - l + 1;\n\t\t}\n\t\tint m, find = l;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) / 2;\n\t\t\tif (sortv[m] <= v) {\n\t\t\t\tfind = m;\n\t\t\t\tl = m + 1;\n\t\t\t} else {\n\t\t\t\tr = m - 1;\n\t\t\t}\n\t\t}\n\t\treturn find - bl[i] + 1;\n\t}\n\n\t// 返回arr[l..r]范围上<= v的数字个数\n\tpublic static int getCnt(int l, int r, int v) {\n\t\tint lb = bi[l], rb = bi[r], ans = 0;\n\t\tif (lb == rb) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (arr[i] + lazy[lb] <= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[lb]; i++) {\n\t\t\t\tif (arr[i] + lazy[lb] <= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bl[rb]; i <= r; i++) {\n\t\t\t\tif (arr[i] + lazy[rb] <= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = lb + 1; i <= rb - 1; i++) {\n\t\t\t\tans += blockCnt(i, v);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int query(int l, int r, int k) {\n\t\tif (k < 1 || k > r - l + 1) {\n\t\t\treturn -1;\n\t\t}\n\t\tint minv = getMin(l, r);\n\t\tint maxv = getMax(l, r);\n\t\tint midv;\n\t\tint ans = -1;\n\t\twhile (minv <= maxv) {\n\t\t\tmidv = minv + (maxv - minv) / 2;\n\t\t\tif (getCnt(l, r, midv) >= k) {\n\t\t\t\tans = midv;\n\t\t\t\tmaxv = midv - 1;\n\t\t\t} else {\n\t\t\t\tminv = midv + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 注意调整块长\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n / 2);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tArrays.sort(sortv, bl[i], br[i] + 1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, l, r, v; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tout.println(query(l, r, v));\n\t\t\t} else {\n\t\t\t\tadd(l, r, v);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code01_Poker1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
