b2796ddb-bbd8-48e5-b988-8ab98ccc4810	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class173;\n\n// 树上分块模版题，重链序列分块，java版\n// 一共有n个节点，每个节点有点权，给定n-1条边，所有节点连成一棵树\n// 接下来有m条操作，每条操作都要打印两个答案，描述如下\n// 操作 k x1 y1 x2 y2 .. (一共k个点对) \n// 每个点对(x, y)，在树上都有从x到y的路径，那么k个点对就有k条路径\n// 先打印k条路径上不同点权的数量，再打印点权集合中没有出现的最小非负数(mex)\n// 1 <= n、点对总数 <= 10^5    点权 <= 30000\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P3603\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_HLD1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int MAXV = 30001;\n\tpublic static int n, m, f, k;\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\t// 重链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\t// 分块\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\tpublic static BitSet[] bitSet = new BitSet[MAXB];\n\n\tpublic static BitSet ans = new BitSet();\n\n\tstatic class BitSet {\n\n\t\tint len;\n\n\t\tpublic int[] set;\n\n\t\tpublic BitSet() {\n\t\t\tlen = (MAXV + 31) / 32;\n\t\t\tset = new int[len];\n\t\t}\n\n\t\tpublic void clear() {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tset[i] = 0;\n\t\t\t}\n\t\t}\n\n\t\tpublic void setOne(int v) {\n\t\t\tset[v / 32] |= 1 << (v % 32);\n\t\t}\n\n\t\tpublic void or(BitSet obj) {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tset[i] |= obj.set[i];\n\t\t\t}\n\t\t}\n\n\t\tpublic int getOnes() {\n\t\t\tint ans = 0;\n\t\t\tfor (int x : set) {\n\t\t\t\tans += Integer.bitCount(x);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int mex() {\n\t\t\tfor (int i = 0, inv; i < len; i++) {\n\t\t\t\tinv = ~set[i];\n\t\t\t\tif (inv != 0) {\n\t\t\t\t\treturn i * 32 + Integer.numberOfTrailingZeros(inv);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tval[cntd] = arr[u];\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tval[cntd] = arr[first];\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) {\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void query(int l, int r) {\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans.setOne(val[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tans.setOne(val[i]);\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tans.setOne(val[i]);\n\t\t\t}\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tans.or(bitSet[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void updateAns(int x, int y) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tint tmp = x;\n\t\t\t\tx = y;\n\t\t\t\ty = tmp;\n\t\t\t}\n\t\t\tquery(dfn[top[x]], dfn[x]);\n\t\t\tx = fa[top[x]];\n\t\t}\n\t\tquery(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]));\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs3();\n\t\tdfs4();\n\t\tblen = (int) Math.sqrt(n * 20);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t\tbitSet[i] = new BitSet();\n\t\t\tfor (int j = bl[i]; j <= br[i]; j++) {\n\t\t\t\tbitSet[i].setOne(val[j]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tf = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, lastAns = 0; i <= m; i++) {\n\t\t\tans.clear();\n\t\t\tk = in.nextInt();\n\t\t\tfor (int j = 1, x, y; j <= k; j++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tif (f > 0) {\n\t\t\t\t\tx = x ^ lastAns;\n\t\t\t\t\ty = y ^ lastAns;\n\t\t\t\t}\n\t\t\t\tupdateAns(x, y);\n\t\t\t}\n\t\t\tint ans1 = ans.getOnes();\n\t\t\tint ans2 = ans.mex();\n\t\t\tout.println(ans1 + " " + ans2);\n\t\t\tlastAns = ans1 + ans2;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_HLD1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
