1a2b1d58-bef8-4e8a-88c8-f840ade45af9	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class173;\n\n// 树上分块模版题，随机撒点，java版\n// 一共有n个节点，每个节点有点权，给定n-1条边，所有节点连成一棵树\n// 接下来有m条操作，每条操作都要打印两个答案，描述如下\n// 操作 k x1 y1 x2 y2 .. (一共k个点对) \n// 每个点对(x, y)，在树上都有从x到y的路径，那么k个点对就有k条路径\n// 先打印k条路径上不同点权的数量，再打印点权集合中没有出现的最小非负数(mex)\n// 1 <= n、点对总数 <= 10^5    点权 <= 30000\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P3603\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_Random1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int MAXV = 30001;\n\tpublic static int MAXP = 17;\n\tpublic static int n, m, f, k;\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\t// 树上倍增，就只是为了快速求出LCA\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\t// 随机撒点\n\t// markNum表示关键点数量\n\tpublic static int markNum;\n\t// vis[i]表示i号节点是否已经是关键点\n\tpublic static boolean[] vis = new boolean[MAXN];\n\t// markNode[k] = i 表示第k个关键点是编号为i的节点\n\tpublic static int[] markNode = new int[MAXB];\n\t// kthMark[i] = k 表示i号节点是第k个关键点，kthMark[i] = 0 表示i号节点是非关键点\n\tpublic static int[] kthMark = new int[MAXN];\n\t// up[i] = j，表示i号节点是关键点，它往上跳到最近的关键点是j号节点\n\tpublic static int[] up = new int[MAXN];\n\t// downSet[k]的含义，路径是[第k个的关键点 .. 最近的上方关键点)，沿途所有节点值组成的位图\n\tpublic static BitSet[] downSet = new BitSet[MAXB];\n\n\tpublic static BitSet ans = new BitSet();\n\n\tstatic class BitSet {\n\n\t\tint len;\n\n\t\tpublic int[] set;\n\n\t\tpublic BitSet() {\n\t\t\tlen = (MAXV + 31) / 32;\n\t\t\tset = new int[len];\n\t\t}\n\n\t\tpublic void clear() {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tset[i] = 0;\n\t\t\t}\n\t\t}\n\n\t\tpublic void setOne(int v) {\n\t\t\tset[v / 32] |= 1 << (v % 32);\n\t\t}\n\n\t\tpublic void or(BitSet obj) {\n\t\t\tfor (int i = 0; i < len; i++) {\n\t\t\t\tset[i] |= obj.set[i];\n\t\t\t}\n\t\t}\n\n\t\tpublic int countOnes() {\n\t\t\tint ans = 0;\n\t\t\tfor (int x : set) {\n\t\t\t\tans += Integer.bitCount(x);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int mex() {\n\t\t\tfor (int i = 0, inv; i < len; i++) {\n\t\t\t\tinv = ~set[i];\n\t\t\t\tif (inv != 0) {\n\t\t\t\t\treturn i * 32 + Integer.numberOfTrailingZeros(inv);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 树上倍增递归版\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 树上倍增迭代版，讲解118进行了详细讲述\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stacksize, cur, fath, edge;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tcur = ufe[stacksize][0];\n\t\tfath = ufe[stacksize][1];\n\t\tedge = ufe[stacksize][2];\n\t}\n\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tdep[cur] = dep[fath] + 1;\n\t\t\t\tstjump[cur][0] = fath;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[cur][p] = stjump[stjump[cur][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\tedge = head[cur];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(cur, fath, edge);\n\t\t\t\tif (to[edge] != fath) {\n\t\t\t\t\tpush(to[edge], cur, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void query(int x, int xylca) {\n\t\twhile (kthMark[x] == 0 && x != xylca) {\n\t\t\tans.setOne(arr[x]);\n\t\t\tx = stjump[x][0];\n\t\t}\n\t\twhile (up[x] > 0 && dep[up[x]] > dep[xylca]) {\n\t\t\tans.or(downSet[kthMark[x]]);\n\t\t\tx = up[x];\n\t\t}\n\t\twhile (x != xylca) {\n\t\t\tans.setOne(arr[x]);\n\t\t\tx = stjump[x][0];\n\t\t}\n\t}\n\n\tpublic static void updateAns(int x, int y) {\n\t\tint xylca = lca(x, y);\n\t\tquery(x, xylca);\n\t\tquery(y, xylca);\n\t\tans.setOne(arr[xylca]);\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs2();\n\t\tint len = (int) Math.sqrt(n * 10);\n\t\tmarkNum = (n + len - 1) / len;\n\t\tfor (int b = 1, pick; b <= markNum; b++) {\n\t\t\tdo {\n\t\t\t\tpick = (int) (Math.random() * n) + 1;\n\t\t\t} while (vis[pick]);\n\t\t\tvis[pick] = true;\n\t\t\tmarkNode[b] = pick;\n\t\t\tkthMark[pick] = b;\n\t\t}\n\t\tfor (int b = 1, cur; b <= markNum; b++) {\n\t\t\tdownSet[b] = new BitSet();\n\t\t\tdownSet[b].setOne(arr[markNode[b]]);\n\t\t\tcur = stjump[markNode[b]][0];\n\t\t\twhile (cur != 0) {\n\t\t\t\tif (kthMark[cur] > 0) {\n\t\t\t\t\tup[markNode[b]] = cur;\n\t\t\t\t\tbreak;\n\t\t\t\t} else {\n\t\t\t\t\tdownSet[b].setOne(arr[cur]);\n\t\t\t\t\tcur = stjump[cur][0];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tf = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, lastAns = 0; i <= m; i++) {\n\t\t\tans.clear();\n\t\t\tk = in.nextInt();\n\t\t\tfor (int j = 1, x, y; j <= k; j++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tif (f > 0) {\n\t\t\t\t\tx = x ^ lastAns;\n\t\t\t\t\ty = y ^ lastAns;\n\t\t\t\t}\n\t\t\t\tupdateAns(x, y);\n\t\t\t}\n\t\t\tint ans1 = ans.countOnes();\n\t\t\tint ans2 = ans.mex();\n\t\t\tout.println(ans1 + " " + ans2);\n\t\t\tlastAns = ans1 + ans2;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Random1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
