318f7d9d-939d-496e-902d-35b5c882f38c	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class173;\n\n// 王室联邦，java版\n// 一共有n个城市，编号1~n，给定n-1条边，所有城市连成一棵树\n// 给定数值b，请把树划分成若干个省，划分要求如下\n// 每个省至少要有b个城市，最多有3 * b个城市，每个省必须有一个省会\n// 省会可在省内也可在省外，一个城市可以是多个省的省会\n// 一个省里，任何城市到达省会的路径上，除了省会之外的其他城市，必须都在省内\n// 根据要求完成一种有效划分即可，先打印划分了多少个省，假设数量为k\n// 然后打印n个数字，范围[1, k]，表示每个城市被划分给了哪个省\n// 最后打印k个数字，表示每个省会的城市编号\n// 1 <= n、b <= 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P2325\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_Royal1 {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int n, b;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] capital = new int[MAXN];\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int cntb;\n\n\tpublic static int[] stack = new int[MAXN];\n\tpublic static int siz;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tint x = siz;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t\tif (siz - x >= b) {\n\t\t\t\t\tcapital[++cntb] = u;\n\t\t\t\t\twhile (siz != x) {\n\t\t\t\t\t\tbelong[stack[siz--]] = cntb;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tstack[++siz] = u;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tb = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs(1, 0);\n\t\tif (cntb == 0) {\n\t\t\tcapital[++cntb] = 1;\n\t\t}\n\t\twhile (siz > 0) {\n\t\t\tbelong[stack[siz--]] = cntb;\n\t\t}\n\t\tout.println(cntb);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(belong[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tfor (int i = 1; i <= cntb; i++) {\n\t\t\tout.print(capital[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_Royal1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
