l2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a2be3b63-cac9-4958-b8bb-1fb7cd0b99ed	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class173;\n\n// 区间父变小，java版\n// 一棵大小为n树，节点1是树头，给定fa[2..n]表示父亲节点编号\n// 对于每个i > 1，都有fa[i] < i，下来有m条操作，操作类型如下\n// 操作 1 x y z : [x..y]范围上任何一点i，fa[i] = max(1, fa[i] - z)\n// 操作 2 x y   : 查询点x和点y的最低公共祖先\n// 2 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1491H\n// 测试链接 : https://codeforces.com/problemset/problem/1491/H\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_FatherMinus1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 501;\n\tpublic static int n, m;\n\n\t// 节点的父亲节点\n\tpublic static int[] fa = new int[MAXN];\n\t// 节点如果从所在块出去，会去往的最近节点\n\tpublic static int[] out = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\t// 块内所有节点的父亲编号，统一减少的幅度\n\tpublic static int[] lazy = new int[MAXB];\n\t// 块内所有节点的父亲编号，统一削减的次数\n\tpublic static int[] minusCnt = new int[MAXB];\n\n\tpublic static void innerUpdate(int b) {\n\t\tfor (int i = bl[b]; i <= br[b]; i++) {\n\t\t\tfa[i] = Math.max(1, fa[i] - lazy[b]);\n\t\t}\n\t\tlazy[b] = 0;\n\t\tfor (int i = bl[b]; i <= br[b]; i++) {\n\t\t\tif (fa[i] < bl[b]) {\n\t\t\t\tout[i] = fa[i];\n\t\t\t} else {\n\t\t\t\tout[i] = out[fa[i]];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void update(int l, int r, int v) {\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tfa[i] = Math.max(1, fa[i] - v);\n\t\t\t}\n\t\t\tinnerUpdate(bi[l]);\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tfa[i] = Math.max(1, fa[i] - v);\n\t\t\t}\n\t\t\tinnerUpdate(bi[l]);\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tfa[i] = Math.max(1, fa[i] - v);\n\t\t\t}\n\t\t\tinnerUpdate(bi[r]);\n\t\t\tfor (int b = bi[l] + 1; b <= bi[r] - 1; b++) {\n\t\t\t\t// 减少的幅度最多到n，不会更大\n\t\t\t\t// 这样还可以让lazy保持int类型并且不溢出\n\t\t\t\tlazy[b] = Math.min(n, lazy[b] + v);\n\t\t\t\tif (++minusCnt[b] <= blen) {\n\t\t\t\t\tinnerUpdate(b);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int jumpFa(int i) {\n\t\treturn Math.max(1, fa[i] - lazy[bi[i]]);\n\t}\n\n\tpublic static int jumpOut(int i) {\n\t\treturn Math.max(1, out[i] - lazy[bi[i]]);\n\t}\n\n\tpublic static int lca(int x, int y) {\n\t\twhile (bi[x] != bi[y] || jumpOut(x) != jumpOut(y)) {\n\t\t\tif (bi[x] != bi[y]) {\n\t\t\t\tif (bi[x] < bi[y]) {\n\t\t\t\t\tint tmp = x;\n\t\t\t\t\tx = y;\n\t\t\t\t\ty = tmp;\n\t\t\t\t}\n\t\t\t\tx = jumpOut(x);\n\t\t\t} else {\n\t\t\t\tx = jumpOut(x);\n\t\t\t\ty = jumpOut(y);\n\t\t\t}\n\t\t}\n\t\twhile (x != y) {\n\t\t\tif (x < y) {\n\t\t\t\tint tmp = x;\n\t\t\t\tx = y;\n\t\t\t\ty = tmp;\n\t\t\t}\n\t\t\tx = jumpFa(x);\n\t\t}\n\t\treturn x;\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t\tinnerUpdate(i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfa[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tz = in.nextInt();\n\t\t\t\tupdate(x, y, z);\n\t\t\t} else {\n\t\t\t\tout.println(lca(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code08_FatherMinus1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
