7af8d334-efaf-44b8-8d88-67b7a58249ef	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class175;\n\n// 哈希冲突，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，操作格式如下\n// 操作 A x y : 下标 % x == y，符合要求的下标，把对应的值累加起来，打印结果\n// 操作 C x y : arr[x]的值改成y\n// 1 <= n、m <= 1.5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3396\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_HashCollision1 {\n\n\tpublic static int MAXN = 150001;\n\tpublic static int MAXB = 401;\n\tpublic static int n, m, blen;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static long[][] dp = new long[MAXB][MAXB];\n\n\tpublic static long query(int x, int y) {\n\t\tif (x <= blen) {\n\t\t\treturn dp[x][y];\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = y; i <= n; i += x) {\n\t\t\tans += arr[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void update(int i, int v) {\n\t\tint delta = v - arr[i];\n\t\tarr[i] = v;\n\t\tfor (int x = 1; x <= blen; x++) {\n\t\t\tdp[x][i % x] += delta;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tfor (int x = 1; x <= blen; x++) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tdp[x][i % x] += arr[i];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tchar op;\n\t\tint x, y;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 'A') {\n\t\t\t\tout.println(query(x, y));\n\t\t\t} else {\n\t\t\t\tupdate(x, y);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code01_HashCollision1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
