202fdea3-e40c-4f44-b354-3befd2cbc159	828d3dd9-108c-439f-8cb7-a731b1efcd63	java	package class156;\n\n// 狡猾的商人，带权并查集模版题2\n// 有n个月的收入，下标1 ~ n，但是并不知道每个月收入是多少\n// 操作 l r v，代表从第l个月到第r个月，总收入为v\n// 一共给你m个操作，请判断给定的数据是自洽还是自相矛盾\n// 自洽打印true，自相矛盾打印false\n// 1 <= n <= 100    1 <= m <= 1000\n// 总收入不会超过int类型范围\n// 测试链接 : https://www.luogu.com.cn/problem/P2294\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_CunningMerchant {\n\n\tpublic static int MAXN = 102;\n\n\tpublic static int t, n, m;\n\n\tpublic static boolean ans;\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tans = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tdist[i] = 0;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tint tmp = father[i];\n\t\t\tfather[i] = find(tmp);\n\t\t\tdist[i] += dist[tmp];\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void union(int l, int r, int v) {\n\t\tint lf = find(l), rf = find(r);\n\t\tif (lf != rf) {\n\t\t\tfather[lf] = rf;\n\t\t\tdist[lf] = v + dist[r] - dist[l];\n\t\t}\n\t}\n\n\tpublic static boolean check(int l, int r, int v) {\n\t\tif (find(l) == find(r)) {\n\t\t\tif ((dist[l] - dist[r]) != v) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tt = (int) in.nval;\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval + 1;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tprepare();\n\t\t\tfor (int i = 1, l, r, v; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tr = (int) in.nval + 1;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tif (!check(l, r, v)) {\n\t\t\t\t\tans = false;\n\t\t\t\t} else {\n\t\t\t\t\tunion(l, r, v);\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_CunningMerchant.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5270426d-017b-4dc1-868c-6e7d5a63d2bb	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class175;\n\n// 等差数列求和，java版\n// 一共有t组测试，每组测试遵循同样的设定\n// 给定一个长度为n的数组arr，接下来有q条查询，查询格式如下\n// 查询 s d k : arr[s]作为第1项、arr[s + 1d]作为第2项、arr[s + 2d]作为第3项...\n//             每项的值 * 项的编号，一共k项都累加起来，打印累加和\n// 1 <= n <= 10^5\n// 1 <= q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1921F\n// 测试链接 : https://codeforces.com/problemset/problem/1921/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_SumOfProgression1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int t, n, q, blen;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static long[][] f = new long[MAXB][MAXN];\n\tpublic static long[][] g = new long[MAXB][MAXN];\n\n\tpublic static long query(int s, int d, int k) {\n\t\tlong ans = 0;\n\t\tif (d <= blen) {\n\t\t\tans = g[d][s];\n\t\t\tif (s + d * k <= n) {\n\t\t\t\tans = ans - g[d][s + d * k] - f[d][s + d * k] * k;\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = 1; i <= k; i++) {\n\t\t\t\tans += 1L * arr[s + (i - 1) * d] * i;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tfor (int d = 1; d <= blen; d++) {\n\t\t\tfor (int i = n; i >= 1; i--) {\n\t\t\t\tf[d][i] = arr[i] + (i + d > n ? 0 : f[d][i + d]);\n\t\t\t}\n\t\t}\n\t\tfor (int d = 1; d <= blen; d++) {\n\t\t\tfor (int i = n; i >= 1; i--) {\n\t\t\t\tg[d][i] = f[d][i] + (i + d > n ? 0 : g[d][i + d]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tq = in.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tarr[i] = in.nextInt();\n\t\t\t}\n\t\t\tprepare();\n\t\t\tfor (int i = 1, s, d, k; i <= q; i++) {\n\t\t\t\ts = in.nextInt();\n\t\t\t\td = in.nextInt();\n\t\t\t\tk = in.nextInt();\n\t\t\t\tout.println(query(s, d, k));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_SumOfProgression1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
