2bb46537-3bdf-4bfe-ae9b-ae4e6239e8b1	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class175;\n\n// 初始化，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，操作格式如下\n// 操作 1 x y z : 从arr[y]开始，下标每次+x，所有相应位置的数都+z，题目保证 y <= x\n// 操作 2 x y   : 打印arr[x..y]的累加和，答案对1000000007取余\n// 1 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5309\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code04_Initialization2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Initialization1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXB = 501;\n\tpublic static int MOD = 1000000007;\n\tpublic static int n, m;\n\n\tpublic static long[][] pre = new long[MAXB][MAXB];\n\tpublic static long[][] suf = new long[MAXB][MAXB];\n\tpublic static long[] arr = new long[MAXN];\n\tpublic static long[] sum = new long[MAXB];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\tpublic static void add(int x, int y, int z) {\n\t\tif (x <= blen) {\n\t\t\tfor (int i = y; i <= x; i++) {\n\t\t\t\tpre[x][i] += z;\n\t\t\t}\n\t\t\tfor (int i = y; i >= 1; i--) {\n\t\t\t\tsuf[x][i] += z;\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = y; i <= n; i += x) {\n\t\t\t\tarr[i] += z;\n\t\t\t\tsum[bi[i]] += z;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long querySum(int l, int r) {\n\t\tint lb = bi[l], rb = bi[r];\n\t\tlong ans = 0;\n\t\tif (lb == rb) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans += arr[i];\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[lb]; i++) {\n\t\t\t\tans += arr[i];\n\t\t\t}\n\t\t\tfor (int i = bl[rb]; i <= r; i++) {\n\t\t\t\tans += arr[i];\n\t\t\t}\n\t\t\tfor (int b = lb + 1; b <= rb - 1; b++) {\n\t\t\t\tans += sum[b];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long query(int l, int r) {\n\t\tlong ans = querySum(l, r);\n\t\tfor (int x = 1, lth, rth, num; x <= blen; x++) {\n\t\t\tlth = (l - 1) / x + 1;\n\t\t\trth = (r - 1) / x + 1;\n\t\t\tnum = rth - lth - 1;\n\t\t\tif (lth == rth) {\n\t\t\t\tans = ans + pre[x][(r - 1) % x + 1] - pre[x][(l - 1) % x];\n\t\t\t} else {\n\t\t\t\tans = ans + suf[x][(l - 1) % x + 1] + pre[x][x] % MOD * num + pre[x][(r - 1) % x + 1];\n\t\t\t}\n\t\t}\n\t\treturn ans % MOD;\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int b = 1; b <= bnum; b++) {\n\t\t\tbl[b] = (b - 1) * blen + 1;\n\t\t\tbr[b] = Math.min(b * blen, n);\n\t\t\tfor (int i = bl[b]; i <= br[b]; i++) {\n\t\t\t\tsum[b] += arr[i];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tz = in.nextInt();\n\t\t\t\tadd(x, y, z);\n\t\t\t} else {\n\t\t\t\tout.println(query(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_Initialization1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
