+ 1);\n//        }\n//    }\n//    return -1;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    int s, sjump, t, tjump;\n//    cin >> s >> sjump >> t >> tjump;\n//    add(s, sjump);\n//    add(t, tjump);\n//    for (int i = 2, idx, jump; i < m; i++) {\n//        cin >> idx >> jump;\n//        add(idx, jump);\n//    }\n//    cout << bfs(s, t) << '\\n';\n//    return 0;\n//}	模板：Code05_Skyscraper2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
1487e379-bc92-484c-b0fc-80e57355405c	828d3dd9-108c-439f-8cb7-a731b1efcd63	java	package class156;\n\n// 错误答案数量，带权并查集模版题3\n// 有n个数字，下标1 ~ n，但是并不知道每个数字是多少\n// 操作 l r v，代表l~r范围上累加和为v\n// 一共m个操作，如果某个操作和之前的操作信息自相矛盾，认为当前操作是错误的，不进行这个操作\n// 最后打印错误操作的数量\n// 1 <= n <= 200000    1 <= m <= 40000\n// 累加和不会超过int类型范围\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=3038\n// 测试链接 : https://vjudge.net/problem/HDU-3038\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_WrongAnswers {\n\n\tpublic static int MAXN = 200002;\n\n\tpublic static int n, m, ans;\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tans = 0;\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tdist[i] = 0;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tint tmp = father[i];\n\t\t\tfather[i] = find(tmp);\n\t\t\tdist[i] += dist[tmp];\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void union(int l, int r, int v) {\n\t\tint lf = find(l), rf = find(r);\n\t\tif (lf != rf) {\n\t\t\tfather[lf] = rf;\n\t\t\tdist[lf] = v + dist[r] - dist[l];\n\t\t}\n\t}\n\n\tpublic static boolean check(int l, int r, int v) {\n\t\tif (find(l) == find(r)) {\n\t\t\tif ((dist[l] - dist[r]) != v) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval + 1;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tprepare();\n\t\t\tfor (int i = 1, l, r, v; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tr = (int) in.nval + 1;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tif (!check(l, r, v)) {\n\t\t\t\t\tans++;\n\t\t\t\t} else {\n\t\t\t\t\tunion(l, r, v);\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_WrongAnswers.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
813f981f-d6e0-4f74-a8d1-eb789e448600	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	java	package class175;\n\n// 最少划分，java版\n// 给定一个长度为n的数组arr，考虑如下问题的解\n// 数组arr划分成若干段子数组，保证每段不同数字的种类 <= k，返回至少划分成几段\n// 打印k = 1, 2, 3..n时，所有的答案\n// 1 <= arr[i] <= n <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF786C\n// 测试链接 : https://codeforces.com/problemset/problem/786/C\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.InputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.io.IOException;\n\npublic class Code06_TillCollapse1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, blen;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int query(int limit) {\n\t\tint kind = 0, cnt = 0, start = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (!vis[arr[i]]) {\n\t\t\t\tkind++;\n\t\t\t\tif (kind > limit) {\n\t\t\t\t\tcnt++;\n\t\t\t\t\tfor (int j = start; j < i; j++) {\n\t\t\t\t\t\tvis[arr[j]] = false;\n\t\t\t\t\t}\n\t\t\t\t\tstart = i;\n\t\t\t\t\tkind = 1;\n\t\t\t\t}\n\t\t\t\tvis[arr[i]] = true;\n\t\t\t}\n\t\t}\n\t\tif (kind > 0) {\n\t\t\tcnt++;\n\t\t\tfor (int j = start; j <= n; j++) {\n\t\t\t\tvis[arr[j]] = false;\n\t\t\t}\n\t\t}\n\t\treturn cnt;\n\t}\n\n\tpublic static int jump(int l, int r, int curAns) {\n\t\tint find = l;\n\t\twhile (l <= r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tint check = query(mid);\n\t\t\tif (check < curAns) {\n\t\t\t\tr = mid - 1;\n\t\t\t} else if (check > curAns) {\n\t\t\t\tl = mid + 1;\n\t\t\t} else {\n\t\t\t\tfind = mid;\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn find + 1;\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int i = 1; i <= blen; i++) {\n\t\t\tans[i] = query(i);\n\t\t}\n\t\tfor (int i = blen + 1; i <= n; i = jump(i, n, ans[i])) {\n\t\t\tans[i] = query(i);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint log2n = 0;\n\t\twhile ((1 << log2n) <= (n >> 1)) {\n\t\t\tlog2n++;\n\t\t}\n\t\tblen = Math.max(1, (int) Math.sqrt(n * log2n));\n\t\tArrays.fill(ans, 1, n + 1, -1);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(System.out);\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (ans[i] == -1) {\n\t\t\t\tans[i] = ans[i - 1];\n\t\t\t}\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_TillCollapse1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
