9acd9f0c-1429-489d-b4f4-dd8dcb981fdb	828d3dd9-108c-439f-8cb7-a731b1efcd63	java	package class165;\n\n// 可撤销并查集模版题，java版\n// 一共有n个点，每个点有两个小球，每个点给定两个小球的编号\n// 一共有n-1条无向边，所有节点连成一棵树\n// 对i号点，2 <= i <= n，都计算如下问题的答案并打印\n// 从1号点到i号点的最短路径上，每个点只能拿一个小球，最多能拿几个编号不同的小球\n// 1 <= n <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc302_h\n// 测试链接 : https://atcoder.jp/contests/abc302/tasks/abc302_h\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_UndoUnionFind1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt;\n\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] edgeCnt = new int[MAXN];\n\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int ball = 0;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\tedgeCnt[fx] += edgeCnt[fy] + 1;\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t\tedgeCnt[fx] -= edgeCnt[fy] + 1;\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tint fx = find(arr[u][0]);\n\t\tint fy = find(arr[u][1]);\n\t\tboolean added = false;\n\t\tboolean unioned = false;\n\t\tif (fx == fy) {\n\t\t\tif (edgeCnt[fx] < siz[fx]) {\n\t\t\t\tball++;\n\t\t\t\tadded = true;\n\t\t\t}\n\t\t\tedgeCnt[fx]++;\n\t\t} else {\n\t\t\tif (edgeCnt[fx] < siz[fx] || edgeCnt[fy] < siz[fy]) {\n\t\t\t\tball++;\n\t\t\t\tadded = true;\n\t\t\t}\n\t\t\tunion(fx, fy);\n\t\t\tunioned = true;\n\t\t}\n\t\tans[u] = ball;\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs(to[e], u);\n\t\t\t}\n\t\t}\n\t\tif (added) {\n\t\t\tball--;\n\t\t}\n\t\tif (unioned) {\n\t\t\tundo();\n\t\t} else {\n\t\t\tedgeCnt[fx]--;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tarr[i][1] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t\tedgeCnt[i] = 0;\n\t\t}\n\t\tdfs(1, 0);\n\t\tfor (int i = 2; i < n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println(ans[n]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_UndoUnionFind1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
