7cfa7634-98f2-4e2b-95c6-f1efcaf1a723	828d3dd9-108c-439f-8cb7-a731b1efcd63	java	package class174;\n\n// 五彩斑斓的世界，java版\n// 给定一个长度为n的数组arr，一共有m条操作，每条操作类型如下\n// 操作 1 l r x : arr[l..r]范围上，所有大于x的数减去x\n// 操作 2 l r x : arr[l..r]范围上，查询x出现的次数\n// 1 <= n <= 10^6\n// 1 <= m <= 5 * 10^5\n// 0 <= arr[i]、x <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4117\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code03_ColorfulWorld2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code03_ColorfulWorld1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int MAXM = 500001;\n\tpublic static int MAXV = 100002;\n\tpublic static int n, m;\n\tpublic static int blen, bnum;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] op = new int[MAXM];\n\tpublic static int[] ql = new int[MAXM];\n\tpublic static int[] qr = new int[MAXM];\n\tpublic static int[] qx = new int[MAXM];\n\n\t// maxv代表一个序列块中的最大值\n\t// lazy代表一个序列块中，所有数字需要统计减去多少\n\t// fa代表值域并查集\n\t// pre0代表数组前缀上0的词频统计\n\t// cntv代表一个序列块中每种值的词频统计\n\tpublic static int maxv, lazy;\n\tpublic static int[] fa = new int[MAXV];\n\tpublic static int[] pre0 = new int[MAXN];\n\tpublic static int[] cntv = new int[MAXV];\n\n\t// 查询的答案\n\tpublic static int[] ans = new int[MAXM];\n\n\t// 查询x值变成了什么\n\tpublic static int find(int x) {\n\t\tif (x != fa[x]) {\n\t\t\tfa[x] = find(fa[x]);\n\t\t}\n\t\treturn fa[x];\n\t}\n\n\t// 所有x值变成y值\n\tpublic static void change(int x, int y) {\n\t\tfa[x] = y;\n\t}\n\n\t// 修改保留在值域并查集，把修改写入arr[l..r]\n\tpublic static void down(int l, int r) {\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tarr[i] = find(arr[i]);\n\t\t}\n\t}\n\n\tpublic static void update(int qi, int l, int r) {\n\t\tint jobl = ql[qi], jobr = qr[qi], jobx = qx[qi];\n\t\tif (jobx >= maxv - lazy || jobl > r || jobr < l) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tif ((jobx << 1) <= maxv - lazy) {\n\t\t\t\tfor (int v = lazy + 1; v <= lazy + jobx; v++) {\n\t\t\t\t\tcntv[v + jobx] += cntv[v];\n\t\t\t\t\tcntv[v] = 0;\n\t\t\t\t\tchange(v, v + jobx);\n\t\t\t\t}\n\t\t\t\tlazy += jobx;\n\t\t\t} else {\n\t\t\t\tfor (int v = lazy + jobx + 1; v <= maxv; v++) {\n\t\t\t\t\tcntv[v - jobx] += cntv[v];\n\t\t\t\t\tcntv[v] = 0;\n\t\t\t\t\tchange(v, v - jobx);\n\t\t\t\t}\n\t\t\t\tfor (int v = maxv; v >= 0; v--) {\n\t\t\t\t\tif (cntv[v] != 0) {\n\t\t\t\t\t\tmaxv = v;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tdown(l, r);\n\t\t\tfor (int i = Math.max(l, jobl); i <= Math.min(r, jobr); i++) {\n\t\t\t\tif (arr[i] - lazy > jobx) {\n\t\t\t\t\tcntv[arr[i]]--;\n\t\t\t\t\tarr[i] -= jobx;\n\t\t\t\t\tcntv[arr[i]]++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int v = maxv; v >= 0; v--) {\n\t\t\t\tif (cntv[v] != 0) {\n\t\t\t\t\tmaxv = v;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void query(int qi, int l, int r) {\n\t\tint jobl = ql[qi], jobr = qr[qi], jobx = qx[qi];\n\t\tif (jobx == 0 || jobx > maxv - lazy || jobl > r || jobr < l) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tans[qi] += cntv[jobx + lazy];\n\t\t} else {\n\t\t\tdown(l, r);\n\t\t\tfor (int i = Math.max(l, jobl); i <= Math.min(r, jobr); i++) {\n\t\t\t\tif (arr[i] - lazy == jobx) {\n\t\t\t\t\tans[qi]++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void compute(int l, int r) {\n\t\tArrays.fill(cntv, 0);\n\t\tmaxv = lazy = 0;\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tmaxv = Math.max(maxv, arr[i]);\n\t\t\tcntv[arr[i]]++;\n\t\t}\n\t\tfor (int v = 0; v <= maxv; v++) {\n\t\t\tfa[v] = v;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (op[i] == 1) {\n\t\t\t\tupdate(i, l, r);\n\t\t\t} else {\n\t\t\t\tquery(i, l, r);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tpre0[i] = pre0[i - 1] + (arr[i] == 0 ? 1 : 0);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (op[i] == 2 && qx[i] == 0) {\n\t\t\t\tans[i] = pre0[qr[i]] - pre0[ql[i] - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top[i] = in.nextInt();\n\t\t\tql[i] = in.nextInt();\n\t\t\tqr[i] = in.nextInt();\n\t\t\tqx[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, l, r; i <= bnum; i++) {\n\t\t\tl = (i - 1) * blen + 1;\n\t\t\tr = Math.min(i * blen, n);\n\t\t\tcompute(l, r);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (op[i] == 2) {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_ColorfulWorld1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
