= r) {\n//                    merge(l, r);\n//                }\n//            }\n//        } else {\n//            int x;\n//            cin >> x;\n//            if (num[x] == -1) {\n//                cout << -1 << "\\n";\n//            } else {\n//                int ans = find(x);\n//                cout << num[ans] << "\\n";\n//                pop(ans);\n//                num[ans] = -1;\n//            }\n//        }\n//    }\n//    return 0;\n//}	模板：Code01_LeftistTree2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0cff940d-3848-4767-9533-1f0e39e49726	48f4d1f2-7369-4f40-865e-2a8a70005ef4	java	package class154;\n\n// 左偏树模版题2，数据量增强，java版\n// 依次给定n个非负数字，表示有n个小根堆，每个堆只有一个数\n// 实现如下两种操作，操作一共调用m次\n// M x y : 第x个数字所在的堆和第y个数字所在的堆合并\n//         如果两个数字已经在一个堆或者某个数字已经删除，不进行合并\n// K x   : 打印第x个数字所在堆的最小值，并且在堆里删掉这个最小值\n//         如果第x个数字已经被删除，也就是找不到所在的堆，打印0\n//         若有多个最小值，优先删除编号小的\n// 1 <= n <= 10^6\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2713\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code01_LeftistTree3 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (num[i] > num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tn = in.readInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum[i] = in.readInt();\n\t\t}\n\t\tm = in.readInt();\n\t\tString op;\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\top = in.readString();\n\t\t\tif (op.equals("M")) {\n\t\t\t\tx = in.readInt();\n\t\t\t\ty = in.readInt();\n\t\t\t\tif (num[x] != -1 && num[y] != -1) {\n\t\t\t\t\tint l = find(x);\n\t\t\t\t\tint r = find(y);\n\t\t\t\t\tif (l != r) {\n\t\t\t\t\t\tmerge(l, r);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tx = in.readInt();\n\t\t\t\tif (num[x] == -1) {\n\t\t\t\t\tout.println(0);\n\t\t\t\t} else {\n\t\t\t\t\tint ans = find(x);\n\t\t\t\t\tout.println(num[ans]);\n\t\t\t\t\tpop(ans);\n\t\t\t\t\tnum[ans] = -1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic String readString() {\n\t\t\tchar cur;\n\t\t\tdo {\n\t\t\t\tcur = (char) readByte();\n\t\t\t} while (cur == ' ' || cur == '\\n');\n\t\t\tStringBuilder builder = new StringBuilder();\n\t\t\twhile (cur != ' ' && cur != '\\n') {\n\t\t\t\tbuilder.append(cur);\n\t\t\t\tcur = (char) readByte();\n\t\t\t}\n\t\t\treturn builder.toString();\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n	模板：Code01_LeftistTree3.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
