3581289a-fade-43b3-8bfe-dcd63f992073	48f4d1f2-7369-4f40-865e-2a8a70005ef4	java	package class154;\n\n// 断罪者，删除任意编号节点，java版\n// 给定t，w，k，表示一共有t个人，死亡方式都为w，地狱阈值都为k，w和k含义稍后解释\n// 每个人都给定n和m，表示这人一生有n件错事，有m次领悟\n// 这个人的n件错事，给定对应的n个罪恶值，然后给定m次领悟，领悟类型如下\n// 2 a   : 第a件错事的罪恶值变成0\n// 3 a b : 第a件错事所在的集合中，最大罪恶值的错事，罪恶值减少b\n//         如果减少后罪恶值变成负数，认为这件错事的罪恶值变为0\n//         如果集合中，两件错事都是最大的罪恶值，取编号较小的错事\n// 4 a b : 第a件错事所在的集合与第b件错事所在的集合合并\n// 一个错事集合的罪恶值 = 这个集合中的最大罪恶值，只取一个\n// 一个人的罪恶值 = 这个人所有错事集合的罪恶值累加起来\n// 然后根据死亡方式w，对每个人的罪恶值做最后调整，然后打印这个人的下场\n// 如果w==1，不调整\n// 如果w==2，人的罪恶值 -= 错事集合的罪恶值中的最大值\n// 如果w==3，人的罪恶值 += 错事集合的罪恶值中的最大值\n// 如果一个人的罪恶值 == 0，打印"Gensokyo 0"\n// 如果一个人的罪恶值  > k，打印"Hell "，然后打印罪恶值\n// 如果一个人的罪恶值 <= k，打印"Heaven "，然后打印罪恶值\n// 一共有t个人，所以最终会有t次打印\n// 1 <= t <= 30\n// 1 <= n <= 2 * 10^6\n// 错事罪恶值可能很大，输入保证每个人的罪恶值用long类型不溢出\n// 测试链接 : https://www.luogu.com.cn/problem/P4971\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code02_Convict1 {\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int t, w, n, m;\n\n\tpublic static long k;\n\n\tpublic static long[] num = new long[MAXN];\n\n\t// up[i]表示节点i在左偏树结构上的父亲节点\n\tpublic static int[] up = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// father[i]表示并查集里节点i的路径信息\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆，如果值一样，编号小的节点做头\n\t\tif (num[i] < num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\t// 设置up信息\n\t\tup[right[i]] = i;\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\t// 节点i是所在左偏树的任意节点，删除节点i，返回整棵树的头节点编号\n\tpublic static int remove(int i) {\n\t\tint h = find(i);\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tint s = merge(left[i], right[i]);\n\t\tint f = up[i];\n\t\tfather[i] = s;\n\t\tup[s] = f;\n\t\tif (h != i) {\n\t\t\tfather[s] = h;\n\t\t\tif (left[f] == i) {\n\t\t\t\tleft[f] = s;\n\t\t\t} else {\n\t\t\t\tright[f] = s;\n\t\t\t}\n\t\t\tfor (int d = dist[s], tmp; dist[f] > d + 1; f = up[f], d++) {\n\t\t\t\tdist[f] = d + 1;\n\t\t\t\tif (dist[left[f]] < dist[right[f]]) {\n\t\t\t\t\ttmp = left[f]; left[f] = right[f]; right[f] = tmp;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\treturn father[s];\n\t}\n\n\tpublic static void reduce(int i, long v) {\n\t\tint h = remove(i);\n\t\tnum[i] = Math.max(num[i] - v, 0);\n\t\tfather[h] = father[i] = merge(h, i);\n\t}\n\n\tpublic static long compute() {\n\t\tlong ans = 0;\n\t\tlong max = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (father[i] == i) {\n\t\t\t\tans += num[i];\n\t\t\t\tmax = Math.max(max, num[i]);\n\t\t\t}\n\t\t}\n\t\tif (w == 2) {\n\t\t\tans -= max;\n\t\t} else if (w == 3) {\n\t\t\tans += max;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tt = in.readInt();\n\t\tw = in.readInt();\n\t\tk = in.readLong();\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tn = in.readInt();\n\t\t\tm = in.readInt();\n\t\t\tprepare();\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tnum[j] = in.readLong();\n\t\t\t}\n\t\t\tfor (int j = 1, op, a, b; j <= m; j++) {\n\t\t\t\top = in.readInt();\n\t\t\t\ta = in.readInt();\n\t\t\t\tif (op == 2) {\n\t\t\t\t\treduce(a, num[a]);\n\t\t\t\t} else if (op == 3) {\n\t\t\t\t\tb = in.readInt();\n\t\t\t\t\treduce(find(a), b);\n\t\t\t\t} else {\n\t\t\t\t\tb = in.readInt();\n\t\t\t\t\tint l = find(a);\n\t\t\t\t\tint r = find(b);\n\t\t\t\t\tif (l != r) {\n\t\t\t\t\t\tmerge(l, r);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tlong ans = compute();\n\t\t\tif (ans == 0) {\n\t\t\t\tout.write("Gensokyo ");\n\t\t\t} else if (ans > k) {\n\t\t\t\tout.write("Hell ");\n\t\t\t} else {\n\t\t\t\tout.write("Heaven ");\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}	模板：Code02_Convict1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
