d10b088d-5eb6-4783-840c-f9425630ae77	48f4d1f2-7369-4f40-865e-2a8a70005ef4	java	package class154;\n\n// 数字序列，java版\n// 给定一个长度为n的数组A，要求构造出一个长度为n的递增数组B\n// 希望 |A[1] - B[1]| + |A[2] - B[2]| + ... + |A[n] - B[n]| 最小\n// 打印这个最小值，然后打印数组B，如果有多个方案，只打印其中的一个\n// 1 <= n <= 10^6\n// 0 <= A[i] <= 2^32 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P4331\n// 提交以下的code，提交时请把类名改成"Main"，一些测试用例通过不了，空间超了\n// 这是洛谷平台没有考虑其他语言导致的，同样的逻辑，C++实现就能完全通过\n// C++实现的版本，就是Code05_NumberSequence2文件\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code05_NumberSequence1 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\t// 左偏树需要\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 并查集向上的路径\n\tpublic static int[] father = new int[MAXN];\n\n\t// 集合表达区域的左下标\n\tpublic static int[] from = new int[MAXN];\n\n\t// 集合表达区域的右下标\n\tpublic static int[] to = new int[MAXN];\n\n\t// 集合里有几个数字\n\tpublic static int[] size = new int[MAXN];\n\n\t// 单调栈\n\tpublic static int[] stack = new int[MAXN];\n\n\t// 构造的数组\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = from[i] = to[i] = i;\n\t\t\tsize[i] = 1;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆\n\t\tif (arr[i] < arr[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static long compute() {\n\t\tint stackSize = 0;\n\t\tfor (int i = 1, pre, cur, s; i <= n; i++) {\n\t\t\twhile (stackSize > 0) {\n\t\t\t\tpre = find(stack[stackSize]);\n\t\t\t\tcur = find(i);\n\t\t\t\tif (arr[pre] <= arr[cur]) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\ts = size[pre] + size[cur];\n\t\t\t\tcur = merge(pre, cur);\n\t\t\t\t// 大根堆只保留到上中位数\n\t\t\t\twhile (s > (i - from[pre] + 1 + 1) / 2) {\n\t\t\t\t\tcur = pop(cur);\n\t\t\t\t\ts--;\n\t\t\t\t}\n\t\t\t\tfrom[cur] = from[pre];\n\t\t\t\tto[cur] = i;\n\t\t\t\tsize[cur] = s;\n\t\t\t\tstackSize--;\n\t\t\t}\n\t\t\tstack[++stackSize] = i;\n\t\t}\n\t\tlong sum = 0;\n\t\tfor (int i = 1, cur; i <= stackSize; i++) {\n\t\t\tcur = find(stack[i]);\n\t\t\tfor (int j = from[cur]; j <= to[cur]; j++) {\n\t\t\t\tans[j] = arr[cur];\n\t\t\t\tsum += Math.abs(ans[j] - arr[j]);\n\t\t\t}\n\t\t}\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tn = in.readInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.readLong() - i;\n\t\t}\n\t\tout.println(compute());\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.write((ans[i] + i));\n\t\t\tout.write(" ");\n\t\t}\n\t\tout.writeln();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n	模板：Code05_NumberSequence1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
