29233300-29fc-49ec-8417-8b11e1afc22b	48f4d1f2-7369-4f40-865e-2a8a70005ef4	java	package class154;\n\n// 可并堆2，java版\n// 这道题课上没有讲，一个值得实现的左偏树模版题\n// 完全是课上讲过的代码，看懂课就能看懂如下实现\n// 给定n个元素，编号为1到n，给定每个元素的值num[i]\n// 初始时每个元素单独组成一个集合，接下来有m次操作，类型有四种，格式如下\n// 操作 0 x y   : 集合x中删除元素y，题目保证y一定在集合x中\n// 操作 1 x     : 查询集合x中的最小值，这是唯一需要打印的操作\n// 操作 2 x y   : 集合y合并到集合x，题目保证以后不会再有以y做集合编号的操作\n// 操作 3 x y z : 集合x中元素y的权值修改为z，题目保证修改操作值只可能变小\n// 测试链接 : https://www.luogu.com.cn/problem/P11266\n// 注意打注释位置的代码即可\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class FollowUp1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\tpublic static int[] father = new int[MAXN];\n\n\t// root[x]表示集合x的堆头节点编号\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tup[i] = ls[i] = rs[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t\t// 初始每个集合i只有元素i\n\t\t\troot[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 小根堆\n\t\t// 值越小越优先\n\t\t// 值一样，按照编号越小越优先\n\t\tif (num[i] > num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\trs[i] = merge(rs[i], j);\n\t\tup[rs[i]] = i;\n\t\tif (dist[ls[i]] < dist[rs[i]]) {\n\t\t\ttmp = ls[i];\n\t\t\tls[i] = rs[i];\n\t\t\trs[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[rs[i]] + 1;\n\t\tfather[ls[i]] = father[rs[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int remove(int i) {\n\t\tint h = find(i);\n\t\tfather[ls[i]] = ls[i];\n\t\tfather[rs[i]] = rs[i];\n\t\tint s = merge(ls[i], rs[i]);\n\t\tint f = up[i];\n\t\tfather[i] = s;\n\t\tup[s] = f;\n\t\tif (h != i) {\n\t\t\tfather[s] = h;\n\t\t\tif (ls[f] == i) {\n\t\t\t\tls[f] = s;\n\t\t\t} else {\n\t\t\t\trs[f] = s;\n\t\t\t}\n\t\t\tfor (int d = dist[s], tmp; dist[f] > d + 1; f = up[f], d++) {\n\t\t\t\tdist[f] = d + 1;\n\t\t\t\tif (dist[ls[f]] < dist[rs[f]]) {\n\t\t\t\t\ttmp = ls[f];\n\t\t\t\t\tls[f] = rs[f];\n\t\t\t\t\trs[f] = tmp;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup[i] = ls[i] = rs[i] = dist[i] = 0;\n\t\treturn father[s];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\t// 删除后需要更新集合x的堆头\n\t\t\t\troot[x] = remove(y);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t} else if (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tout.println(num[root[x]]);\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\t// 合并集合x和集合y\n\t\t\t\troot[x] = merge(root[x], root[y]);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tint h = remove(y);\n\t\t\t\tnum[y] = z;\n\t\t\t\t// y改值后重新作为单点堆\n\t\t\t\tfather[y] = y;\n\t\t\t\t// 合并到集合x\n\t\t\t\troot[x] = merge(h, y);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：FollowUp1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
