d963812a-da58-4966-a272-6c28c1c6111b	23b25e15-7392-4212-9127-98d99c9d240f	java	package class155;\n\n// 棘手的操作，java版\n// 编号1~n个节点，每个节点独立且有自己的权值，实现如下7种操作，操作一共调用m次\n// U x y  : x所在的集合和y所在的集合合并\n// A1 x v : x节点的权值增加v\n// A2 x v : x所在的集合所有节点的权值增加v\n// A3 v   : 所有节点的权值增加v\n// F1 x   : 打印x节点的权值\n// F2 x   : 打印x所在的集合中，权值最大的节点的权值\n// F3     : 打印所有节点中，权值最大的节点的权值\n// 1 <= n、m <= 3 * 10^5，权值不会超过int类型的范围\n// 测试链接 : https://www.luogu.com.cn/problem/P3273\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.PrintWriter;\nimport java.util.TreeMap;\n\npublic class Code02_TrickyOperation1 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int n, m;\n\n\t// 左偏树需要\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] up = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 并查集的路径信息\n\tpublic static int[] father = new int[MAXN];\n\n\t// 集合的大小信息\n\tpublic static int[] size = new int[MAXN];\n\n\t// 集合内所有数字应该加多少值\n\tpublic static int[] add = new int[MAXN];\n\n\t// 所有集合头节点的值，进入这个有序表，头节点有序表\n\tpublic static TreeMap<Integer, Integer> heads = new TreeMap<>();\n\n\t// 所有数字应该加多少\n\tpublic static int addAll = 0;\n\n\t// 准备好一个栈，用迭代方式实现先序遍历，不用递归方式\n\tpublic static int[] stack = new int[MAXN];\n\n\t// 编号为h的节点不再是左偏树的头，在头节点有序表里删掉一份h节点的值\n\tpublic static void minusHead(int h) {\n\t\tif (h != 0) {\n\t\t\tint hnum = num[h] + add[h];\n\t\t\tif (heads.get(hnum) == 1) {\n\t\t\t\theads.remove(hnum);\n\t\t\t} else {\n\t\t\t\theads.put(hnum, heads.get(hnum) - 1);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 编号为h的节点当前是左偏树的头，在头节点有序表里增加一份h节点的值\n\tpublic static void addHead(int h) {\n\t\tif (h != 0) {\n\t\t\tint hnum = num[h] + add[h];\n\t\t\theads.put(hnum, heads.getOrDefault(hnum, 0) + 1);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\theads.clear();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t\tsize[i] = 1;\n\t\t\tadd[i] = 0;\n\t\t\taddHead(i);\n\t\t}\n\t\taddAll = 0;\n\t}\n\n\t// 返回i节点所在左偏树的树头\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\t// 合并两棵左偏树\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (num[i] < num[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tup[right[i]] = i;\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\t// 节点i是所在左偏树的任意节点，删除节点i，返回整棵树的头节点编号\n\tpublic static int remove(int i) {\n\t\tint h = find(i);\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tint s = merge(left[i], right[i]);\n\t\tint f = up[i];\n\t\tfather[i] = s;\n\t\tup[s] = f;\n\t\tif (h != i) {\n\t\t\tfather[s] = h;\n\t\t\tif (left[f] == i) {\n\t\t\t\tleft[f] = s;\n\t\t\t} else {\n\t\t\t\tright[f] = s;\n\t\t\t}\n\t\t\tfor (int d = dist[s], tmp; dist[f] > d + 1; f = up[f], d++) {\n\t\t\t\tdist[f] = d + 1;\n\t\t\t\tif (dist[left[f]] < dist[right[f]]) {\n\t\t\t\t\ttmp = left[f];\n\t\t\t\t\tleft[f] = right[f];\n\t\t\t\t\tright[f] = tmp;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\treturn father[s];\n\t}\n\n\t// 以i为头的左偏树，遭遇了更大的左偏树\n\t// i的标签信息取消，以i为头的整棵树所有节点的值增加v\n\t// 不用递归实现先序遍历，容易爆栈，所以用迭代实现先序遍历\n\tpublic static void down(int i, int v) {\n\t\tif (i != 0) {\n\t\t\tadd[i] = 0;\n\t\t\tint size = 0;\n\t\t\tstack[++size] = i;\n\t\t\twhile (size > 0) {\n\t\t\t\ti = stack[size--];\n\t\t\t\tnum[i] += v;\n\t\t\t\tif (right[i] != 0) {\n\t\t\t\t\tstack[++size] = right[i];\n\t\t\t\t}\n\t\t\t\tif (left[i] != 0) {\n\t\t\t\t\tstack[++size] = left[i];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void u(int i, int j) {\n\t\tint l = find(i);\n\t\tint r = find(j);\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint lsize = size[l];\n\t\tminusHead(l);\n\t\tint rsize = size[r];\n\t\tminusHead(r);\n\t\tint addTag;\n\t\tif (lsize <= rsize) {\n\t\t\tdown(l, add[l] - add[r]);\n\t\t\taddTag = add[r];\n\t\t} else {\n\t\t\tdown(r, add[r] - add[l]);\n\t\t\taddTag = add[l];\n\t\t}\n\t\tint h = merge(l, r);\n\t\tsize[h] = lsize + rsize;\n\t\tadd[h] = addTag;\n\t\taddHead(h);\n\t}\n\n\tpublic static void a1(int i, int v) {\n\t\tint h = find(i);\n\t\tminusHead(h);\n\t\tint l = remove(i);\n\t\tif (l != 0) {\n\t\t\tsize[l] = size[h] - 1;\n\t\t\tadd[l] = add[h];\n\t\t\taddHead(l);\n\t\t}\n\t\tnum[i] = num[i] + add[h] + v;\n\t\tfather[i] = i;\n\t\tsize[i] = 1;\n\t\tadd[i] = 0;\n\t\taddHead(i);\n\t\tu(l, i);\n\t}\n\n\tpublic static void a2(int i, int v) {\n\t\tint h = find(i);\n\t\tminusHead(h);\n\t\tadd[h] += v;\n\t\taddHead(h);\n\t}\n\n\tpublic static void a3(int v) {\n\t\taddAll += v;\n\t}\n\n\tpublic static int f1(int i) {\n\t\treturn num[i] + add[find(i)] + addAll;\n\t}\n\n\tpublic static int f2(int i) {\n\t\tint h = find(i);\n\t\treturn num[h] + add[h] + addAll;\n\t}\n\n\tpublic static int f3() {\n\t\treturn heads.lastKey() + addAll;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tReaderWriter io = new ReaderWriter();\n\t\tn = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum[i] = io.nextInt();\n\t\t}\n\t\tprepare();\n\t\tm = io.nextInt();\n\t\tString op;\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\top = io.next();\n\t\t\tif (op.equals("F3")) {\n\t\t\t\tio.println(f3());\n\t\t\t} else {\n\t\t\t\tx = io.nextInt();\n\t\t\t\tif (op.equals("U")) {\n\t\t\t\t\ty = io.nextInt();\n\t\t\t\t\tu(x, y);\n\t\t\t\t} else if (op.equals("A1")) {\n\t\t\t\t\ty = io.nextInt();\n\t\t\t\t\ta1(x, y);\n\t\t\t\t} else if (op.equals("A2")) {\n\t\t\t\t\ty = io.nextInt();\n\t\t\t\t\ta2(x, y);\n\t\t\t\t} else if (op.equals("A3")) {\n\t\t\t\t\ta3(x);\n\t\t\t\t} else if (op.equals("F1")) {\n\t\t\t\t\tio.println(f1(x));\n\t\t\t\t} else {\n\t\t\t\t\tio.println(f2(x));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class ReaderWriter extends PrintWriter {\n\t\tbyte[] buf = new byte[1 << 10];\n\t\tint bId = 0, bSize = 0;\n\t\tboolean eof = false;\n\n\t\tpublic ReaderWriter() {\n\t\t\tsuper(System.out);\n\t\t}\n\n\t\tprivate byte getByte() {\n\t\t\tif (bId >= bSize) {\n\t\t\t\ttry {\n\t\t\t\t\tbSize = System.in.read(buf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\te.printStackTrace();\n\t\t\t\t}\n\t\t\t\tif (bSize == -1)\n\t\t\t\t\teof = true;\n\t\t\t\tbId = 0;\n\t\t\t}\n\t\t\treturn buf[bId++];\n\t\t}\n\n\t\tbyte c;\n\n\t\tpublic boolean hasNext() {\n\t\t\tif (eof)\n\t\t\t\treturn false;\n\t\t\twhile ((c = getByte()) <= 32 && !eof)\n\t\t\t\t;\n\t\t\tif (eof)\n\t\t\t\treturn false;\n\t\t\tbId--;\n\t\t\treturn true;\n\t\t}\n\n\t\tpublic String next() {\n\t\t\tif (!hasNext())\n\t\t\t\treturn null;\n\t\t\tbyte c = getByte();\n\t\t\twhile (c <= 32)\n\t\t\t\tc = getByte();\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > 32) {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tif (!hasNext())\n\t\t\t\treturn Integer.MIN_VALUE;\n\t\t\tint sign = 1;\n\t\t\tbyte c = getByte();\n\t\t\twhile (c <= 32)\n\t\t\t\tc = getByte();\n\t\t\tif (c == '-') {\n\t\t\t\tsign = -1;\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c >= '0' && c <= '9') {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tbId--;\n\t\t\treturn val * sign;\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\tif (!hasNext())\n\t\t\t\treturn Long.MIN_VALUE;\n\t\t\tint sign = 1;\n\t\t\tbyte c = getByte();\n\t\t\twhile (c <= 32)\n\t\t\t\tc = getByte();\n\t\t\tif (c == '-') {\n\t\t\t\tsign = -1;\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c >= '0' && c <= '9') {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tbId--;\n\t\t\treturn val * sign;\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\tif (!hasNext())\n\t\t\t\treturn Double.NaN;\n\t\t\tint sign = 1;\n\t\t\tbyte c = getByte();\n\t\t\twhile (c <= 32)\n\t\t\t\tc = getByte();\n\t\t\tif (c == '-') {\n\t\t\t\tsign = -1;\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tdouble val = 0;\n\t\t\twhile (c >= '0' && c <= '9') {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = getByte();\n\t\t\t}\n\t\t\tif (c == '.') {\n\t\t\t\tdouble mul = 1;\n\t\t\t\tc = getByte();\n\t\t\t\twhile (c >= '0' && c <= '9') {\n\t\t\t\t\tmul *= 0.1;\n\t\t\t\t\tval += (c - '0') * mul;\n\t\t\t\t\tc = getByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\tbId--;\n\t\t\treturn val * sign;\n\t\t}\n\t}\n\n}\n	模板：Code02_TrickyOperation1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
