24bb8d15-53f5-449f-aae5-4844f240a420	291cef48-7bc6-4684-b1ce-43dcf7ca5149	java	package class153;\n\n// 郁闷的出纳员(java版)\n// 最低薪水为limit，一旦员工薪水低于limit，员工会离职，实现如下四种操作\n// I x : 新来员工初始薪水是x，如果x低于limit，该员工不会入职当然也不算离职\n// A x : 所有员工的薪水都加上x\n// S x : 所有员工的薪水都减去x，一旦有员工低于limit那么就会离职\n// F x : 查询第x多的工资，如果x大于当前员工数量，打印-1\n// 所有操作完成后，打印有多少员工在操作期间离开了公司\n// 测试链接 : https://www.luogu.com.cn/problem/P1486\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code02_FrustratedCashier1 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] key = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int limit;\n\n\tpublic static int change = 0;\n\n\tpublic static int enter = 0;\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\tpublic static int lr(int i) {\n\t\treturn right[father[i]] == i ? 1 : 0;\n\t}\n\n\tpublic static void rotate(int i) {\n\t\tint f = father[i], g = father[f], soni = lr(i), sonf = lr(f);\n\t\tif (soni == 1) {\n\t\t\tright[f] = left[i];\n\t\t\tif (right[f] != 0) {\n\t\t\t\tfather[right[f]] = f;\n\t\t\t}\n\t\t\tleft[i] = f;\n\t\t} else {\n\t\t\tleft[f] = right[i];\n\t\t\tif (left[f] != 0) {\n\t\t\t\tfather[left[f]] = f;\n\t\t\t}\n\t\t\tright[i] = f;\n\t\t}\n\t\tif (g != 0) {\n\t\t\tif (sonf == 1) {\n\t\t\t\tright[g] = i;\n\t\t\t} else {\n\t\t\t\tleft[g] = i;\n\t\t\t}\n\t\t}\n\t\tfather[f] = i;\n\t\tfather[i] = g;\n\t\tup(f);\n\t\tup(i);\n\t}\n\n\tpublic static void splay(int i, int goal) {\n\t\tint f = father[i], g = father[f];\n\t\twhile (f != goal) {\n\t\t\tif (g != goal) {\n\t\t\t\tif (lr(i) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(i);\n\t\t\tf = father[i];\n\t\t\tg = father[f];\n\t\t}\n\t\tif (goal == 0) {\n\t\t\thead = i;\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tkey[++cnt] = num;\n\t\tsize[cnt] = 1;\n\t\tif (head == 0) {\n\t\t\thead = cnt;\n\t\t} else {\n\t\t\tint f = 0, i = head, son = 0;\n\t\t\twhile (i != 0) {\n\t\t\t\tf = i;\n\t\t\t\tif (key[i] <= num) {\n\t\t\t\t\tson = 1;\n\t\t\t\t\ti = right[i];\n\t\t\t\t} else {\n\t\t\t\t\tson = 0;\n\t\t\t\t\ti = left[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (son == 1) {\n\t\t\t\tright[f] = cnt;\n\t\t\t} else {\n\t\t\t\tleft[f] = cnt;\n\t\t\t}\n\t\t\tfather[cnt] = f;\n\t\t\tsplay(cnt, 0);\n\t\t}\n\t}\n\n\tpublic static int index(int x) {\n\t\tint i = head, last = head;\n\t\twhile (i != 0) {\n\t\t\tlast = i;\n\t\t\tif (size[left[i]] >= x) {\n\t\t\t\ti = left[i];\n\t\t\t} else if (size[left[i]] + 1 < x) {\n\t\t\t\tx -= size[left[i]] + 1;\n\t\t\t\ti = right[i];\n\t\t\t} else {\n\t\t\t\ti = 0;\n\t\t\t}\n\t\t}\n\t\tsplay(last, 0);\n\t\treturn key[last];\n\t}\n\n\tpublic static void departure() {\n\t\tint num = limit - change - 1;\n\t\tint i = head, ans = 0;\n\t\twhile (i != 0) {\n\t\t\tif (key[i] > num) {\n\t\t\t\tans = i;\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\tif (ans == 0) {\n\t\t\thead = 0;\n\t\t} else {\n\t\t\tsplay(ans, 0);\n\t\t\tleft[head] = 0;\n\t\t\tup(head);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tint n = io.nextInt();\n\t\tlimit = io.nextInt();\n\t\tString op;\n\t\tint x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt();\n\t\t\tif (op.equals("I")) {\n\t\t\t\tif (x >= limit) {\n\t\t\t\t\tenter++;\n\t\t\t\t\tadd(x - change);\n\t\t\t\t}\n\t\t\t} else if (op.equals("A")) {\n\t\t\t\tchange += x;\n\t\t\t} else if (op.equals("S")) {\n\t\t\t\tchange -= x;\n\t\t\t\tdeparture();\n\t\t\t} else {\n\t\t\t\tif (x > size[head]) {\n\t\t\t\t\tio.println(-1);\n\t\t\t\t} else {\n\t\t\t\t\tio.println(index(size[head] - x + 1) + change);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.println(enter - size[head]);\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code02_FrustratedCashier1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
