2ef8ad94-7dfc-48b7-8acf-4f57f2d2ea6e	291cef48-7bc6-4684-b1ce-43dcf7ca5149	java	package class153;\n\n// Splay树实现普通有序表，不用词频压缩，数据加强的测试，java版\n// 这个文件课上没有讲，测试数据加强了，而且有强制在线的要求\n// 基本功能要求都是不变的，可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P6136\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class FollowUp1 {\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] key = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\tpublic static int lr(int i) {\n\t\treturn right[father[i]] == i ? 1 : 0;\n\t}\n\n\tpublic static void rotate(int i) {\n\t\tint f = father[i], g = father[f], soni = lr(i), sonf = lr(f);\n\t\tif (soni == 1) {\n\t\t\tright[f] = left[i];\n\t\t\tif (right[f] != 0) {\n\t\t\t\tfather[right[f]] = f;\n\t\t\t}\n\t\t\tleft[i] = f;\n\t\t} else {\n\t\t\tleft[f] = right[i];\n\t\t\tif (left[f] != 0) {\n\t\t\t\tfather[left[f]] = f;\n\t\t\t}\n\t\t\tright[i] = f;\n\t\t}\n\t\tif (g != 0) {\n\t\t\tif (sonf == 1) {\n\t\t\t\tright[g] = i;\n\t\t\t} else {\n\t\t\t\tleft[g] = i;\n\t\t\t}\n\t\t}\n\t\tfather[f] = i;\n\t\tfather[i] = g;\n\t\tup(f);\n\t\tup(i);\n\t}\n\n\tpublic static void splay(int i, int goal) {\n\t\tint f = father[i], g = father[f];\n\t\twhile (f != goal) {\n\t\t\tif (g != goal) {\n\t\t\t\tif (lr(i) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(i);\n\t\t\tf = father[i];\n\t\t\tg = father[f];\n\t\t}\n\t\tif (goal == 0) {\n\t\t\thead = i;\n\t\t}\n\t}\n\n\t// 整棵树上找到中序排名为rank的节点，返回节点编号\n\t// 这个方法不是题目要求的查询操作，作为内部方法使用\n\t// 为什么该方法不进行提根操作？\n\t// 因为remove方法使用该方法时，要求find不能提根！\n\tpublic static int find(int rank) {\n\t\tint i = head;\n\t\twhile (i != 0) {\n\t\t\tif (size[left[i]] + 1 == rank) {\n\t\t\t\treturn i;\n\t\t\t} else if (size[left[i]] >= rank) {\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\trank -= size[left[i]] + 1;\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\treturn 0;\n\t}\n\n\tpublic static void add(int num) {\n\t\tkey[++cnt] = num;\n\t\tsize[cnt] = 1;\n\t\tif (head == 0) {\n\t\t\thead = cnt;\n\t\t} else {\n\t\t\tint f = 0, i = head, son = 0;\n\t\t\twhile (i != 0) {\n\t\t\t\tf = i;\n\t\t\t\tif (key[i] <= num) {\n\t\t\t\t\tson = 1;\n\t\t\t\t\ti = right[i];\n\t\t\t\t} else {\n\t\t\t\t\tson = 0;\n\t\t\t\t\ti = left[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (son == 1) {\n\t\t\t\tright[f] = cnt;\n\t\t\t} else {\n\t\t\t\tleft[f] = cnt;\n\t\t\t}\n\t\t\tfather[cnt] = f;\n\t\t\tsplay(cnt, 0);\n\t\t}\n\t}\n\n\tpublic static int rank(int num) {\n\t\tint i = head, last = head;\n\t\tint ans = 0;\n\t\twhile (i != 0) {\n\t\t\tlast = i;\n\t\t\tif (key[i] >= num) {\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\tans += size[left[i]] + 1;\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\tsplay(last, 0);\n\t\treturn ans + 1;\n\t}\n\n\tpublic static int index(int x) {\n\t\tint i = find(x);\n\t\tsplay(i, 0);\n\t\treturn key[i];\n\t}\n\n\tpublic static int pre(int num) {\n\t\tint i = head, last = head;\n\t\tint ans = Integer.MIN_VALUE;\n\t\twhile (i != 0) {\n\t\t\tlast = i;\n\t\t\tif (key[i] >= num) {\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\tans = Math.max(ans, key[i]);\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\tsplay(last, 0);\n\t\treturn ans;\n\t}\n\n\tpublic static int post(int num) {\n\t\tint i = head, last = head;\n\t\tint ans = Integer.MAX_VALUE;\n\t\twhile (i != 0) {\n\t\t\tlast = i;\n\t\t\tif (key[i] <= num) {\n\t\t\t\ti = right[i];\n\t\t\t} else {\n\t\t\t\tans = Math.min(ans, key[i]);\n\t\t\t\ti = left[i];\n\t\t\t}\n\t\t}\n\t\tsplay(last, 0);\n\t\treturn ans;\n\t}\n\n\tpublic static void remove(int num) {\n\t\tint kth = rank(num);\n\t\tif (kth != rank(num + 1)) {\n\t\t\tint i = find(kth);\n\t\t\tsplay(i, 0);\n\t\t\tif (left[i] == 0) {\n\t\t\t\thead = right[i];\n\t\t\t} else if (right[i] == 0) {\n\t\t\t\thead = left[i];\n\t\t\t} else {\n\t\t\t\tint j = find(kth + 1);\n\t\t\t\tsplay(j, i);\n\t\t\t\tleft[j] = left[i];\n\t\t\t\tfather[left[j]] = j;\n\t\t\t\tup(j);\n\t\t\t\thead = j;\n\t\t\t}\n\t\t\tfather[head] = 0;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, num; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tnum = (int) in.nval;\n\t\t\tadd(num);\n\t\t}\n\t\tint lastAns = 0;\n\t\tint ans = 0;\n\t\tfor (int i = 1, op, x; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval ^ lastAns;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(x);\n\t\t\t} else if (op == 3) {\n\t\t\t\tlastAns = rank(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 4) {\n\t\t\t\tlastAns = index(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 5) {\n\t\t\t\tlastAns = pre(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else {\n\t\t\t\tlastAns = post(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：FollowUp1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
