d = rs[i];\n//        } else if (rs[i] == 0) {\n//            head = ls[i];\n//        } else {\n//            int j = find(kth + 1);\n//            splay(j, i);\n//            ls[j] = ls[i];\n//            fa[ls[j]] = j;\n//            up(j);\n//            head = j;\n//        }\n//        if (head != 0) {\n//            fa[head] = 0;\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    int n, m, lastAns = 0, ans = 0;\n//    cin >> n;\n//    cin >> m;\n//    for (int i = 1, num; i <= n; i++) {\n//        cin >> num;\n//        add(num);\n//    }\n//    for (int i = 1, op, x; i <= m; i++) {\n//        cin >> op >> x;\n//        x ^= lastAns;\n//        if (op == 1) {\n//            add(x);\n//        } else if (op == 2) {\n//            remove(x);\n//        } else if (op == 3) {\n//            lastAns = getRank(x);\n//            ans ^= lastAns;\n//        } else if (op == 4) {\n//            lastAns = index(x);\n//            ans ^= lastAns;\n//        } else if (op == 5) {\n//            lastAns = pre(x);\n//            ans ^= lastAns;\n//        } else {\n//            lastAns = post(x);\n//            ans ^= lastAns;\n//        }\n//    }\n//    cout << ans << endl;\n//    return 0;\n//}	模板：FollowUp2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b9d98c10-dcae-486a-8be3-eb1b13295faa	291cef48-7bc6-4684-b1ce-43dcf7ca5149	java	package class153;\n\n// 提根操作的代码 + 长链高度变化的实验\n// 分别去生成一字型长链和之字型长链\n// 每一种长链都让最下方节点提根上去\n// 然后看看长链的高度变化\npublic class ShowDetail {\n\n\tpublic static int MAXN = 100001;\n\n\t// 整棵树的头节点编号\n\tpublic static int head = 0;\n\n\t// 分配了多少节点编号\n\tpublic static int cnt = 0;\n\n\t// key[i]    : 编号为i的节点的key\n\tpublic static int[] key = new int[MAXN];\n\n\t// father[i] : 编号为i的节点的父节点编号\n\tpublic static int[] father = new int[MAXN];\n\n\t// left[i]   : 编号为i的节点的左孩子编号\n\tpublic static int[] left = new int[MAXN];\n\n\t// right[i]  : 编号为i的节点的右孩子编号\n\tpublic static int[] right = new int[MAXN];\n\n\t// size[i]   : 以编号为i的节点做头的子树，一共有多少个节点\n\t//             这个数组和具体要实现的功能有关，属于常用信息\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\t// 判断编号为i的节点，是其父亲的什么儿子\n\t// 0代表左儿子，1代表右儿子\n\tpublic static int lr(int i) {\n\t\treturn right[father[i]] == i ? 1 : 0;\n\t}\n\n\t// 编号为i的节点上升一步，在结构上做调整\n\tpublic static void rotate(int i) {\n\t\tint f = father[i], g = father[f], soni = lr(i), sonf = lr(f);\n\t\tif (soni == 1) {\n\t\t\tright[f] = left[i];\n\t\t\tif (right[f] != 0) {\n\t\t\t\tfather[right[f]] = f;\n\t\t\t}\n\t\t\tleft[i] = f;\n\t\t} else {\n\t\t\tleft[f] = right[i];\n\t\t\tif (left[f] != 0) {\n\t\t\t\tfather[left[f]] = f;\n\t\t\t}\n\t\t\tright[i] = f;\n\t\t}\n\t\tif (g != 0) {\n\t\t\tif (sonf == 1) {\n\t\t\t\tright[g] = i;\n\t\t\t} else {\n\t\t\t\tleft[g] = i;\n\t\t\t}\n\t\t}\n\t\tfather[f] = i;\n\t\tfather[i] = g;\n\t\tup(f);\n\t\tup(i);\n\t}\n\n\t// 编号为i的节点提根，变成编号为goal的节点的儿子\n\t// 如果goal == 0，表示把编号为i的节点变成整棵树的头\n\tpublic static void splay(int i, int goal) {\n\t\tint f = father[i], g = father[f];\n\t\twhile (f != goal) {\n\t\t\tif (g != goal) {\n\t\t\t\tif (lr(i) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(i);\n\t\t\tf = father[i];\n\t\t\tg = father[f];\n\t\t}\n\t\tif (goal == 0) {\n\t\t\thead = i;\n\t\t}\n\t}\n\n\t// 构建一字型长链\n\tpublic static int build1(int l, int r) {\n\t\tint h = cnt + 1;\n\t\tfor (int i = l, last = 0; i <= r; i++, last = cnt) {\n\t\t\tkey[++cnt] = i;\n\t\t\tfather[cnt] = last;\n\t\t\tleft[cnt] = right[cnt] = 0;\n\t\t\tsize[cnt] = r - i + 1;\n\t\t\tif (last != 0) {\n\t\t\t\tright[last] = cnt;\n\t\t\t}\n\t\t}\n\t\treturn h;\n\t}\n\n\t// 构建之字形长链\n\tpublic static int build2(int l, int r, int fa) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\tkey[++cnt] = l;\n\t\tfather[cnt] = fa;\n\t\tleft[cnt] = right[cnt] = 0;\n\t\tint h = cnt;\n\t\tif (l < r) {\n\t\t\tkey[++cnt] = r;\n\t\t\tfather[cnt] = h;\n\t\t\tleft[cnt] = right[cnt] = 0;\n\t\t\tint c = cnt;\n\t\t\tright[h] = c;\n\t\t\tleft[c] = build2(l + 1, r - 1, c);\n\t\t\tup(c);\n\t\t}\n\t\tup(h);\n\t\treturn h;\n\t}\n\n\t// 返回以i为头的树的高度\n\tpublic static int height(int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn Math.max(height(left[i]), height(right[i])) + 1;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("构建一字型长链");\n\t\tSystem.out.println("最下方节点执行splay，观察高度变化");\n\t\thead = build1(1, 1000);\n\t\tSystem.out.println("splay之前的链长度 : " + height(head));\n\t\tsplay(cnt, 0);\n\t\tSystem.out.println("splay之后的链长度 : " + height(head));\n\n\t\tSystem.out.println("==================");\n\n\t\tSystem.out.println("构建之字型长链");\n\t\tSystem.out.println("最下方节点执行splay，观察高度变化");\n\t\thead = build2(1, 1000, 0);\n\t\tSystem.out.println("splay之前的链长度 : " + height(head));\n\t\tsplay(cnt, 0);\n\t\tSystem.out.println("splay之后的链长度 : " + height(head));\n\t}\n\n}\n	模板：ShowDetail.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f92166c4-8a46-43a9-8717-b6df9a96a627	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 嗅探器，java版\n// 给定一张n个点、m条边的无向图，所有节点属于一个连通区\n// 给定点a和点b，如果删掉别的点能让a和b不再连通，这个点叫关键点\n// 打印编号最小的关键点，不存在打印"No solution"\n// 1 <= n <= 2 * 10^5\n// 1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5058\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Sniffer1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 500001;\n\tpublic static int n, a, b;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static boolean[] isKey = new boolean[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u] && u != a && u != b && dfn[b] >= dfn[v]) {\n\t\t\t\t\tisKey[u] = true;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u] && u != a && u != b && dfn[b] >= dfn[v]) {\n\t\t\t\t\t\tisKey[u] = true;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tint u = in.nextInt();\n\t\tint v = in.nextInt();\n\t\twhile (u != 0 || v != 0) {\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t}\n\t\ta = in.nextInt();\n\t\tb = in.nextInt();\n\t\t// tarjan1(a);\n\t\ttarjan2(a);\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (isKey[i]) {\n\t\t\t\tans = i;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (ans == 0) {\n\t\t\tout.println("No solution");\n\t\t} else {\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_Sniffer1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e5bae5d9-1644-4147-aad5-24aee481ab1d	91090307-c3f6-43ef-841b-e4eedbb8f6e7	java	package class151;\n\n// 笛卡尔树模版(C++版)\n// 给定一个长度为n的数组arr，下标从1开始\n// 构建一棵二叉树，下标按照搜索二叉树组织，值按照小根堆组织\n// 建树的过程要求时间复杂度O(n)\n// 建树之后，为了验证\n// 打印，i * (left[i] + 1)，所有信息异或起来的值\n// 打印，i * (right[i] + 1)，所有信息异或起来的值\n// 1 <= n <= 10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P5854\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <vector>\n//#include <stack>\n//#include <cstdio>\n//\n//#define LL long long\n//\n//using namespace std;\n//\n//const int MAXN = 10000001;\n//\n//int arr[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int sta[MAXN];\n//int n;\n//\n//void build() {\n//    int top = 0;\n//    for (int i = 1; i <= n; i++) {\n//        int pos = top;\n//        while (pos > 0 && arr[sta[pos]] > arr[i]) {\n//            pos--;\n//        }\n//        if (pos > 0) {\n//            rs[sta[pos]] = i;\n//        }\n//        if (pos < top) {\n//            ls[i] = sta[pos + 1];\n//        }\n//        sta[++pos] = i;\n//        top = pos;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    build();\n//    long long ans1 = 0, ans2 = 0;\n//    for (int i = 1; i <= n; i++) {\n//        ans1 ^= 1LL * i * (ls[i] + 1);\n//        ans2 ^= 1LL * i * (rs[i] + 1);\n//    }\n//    cout << ans1 << " " << ans2 << endl;\n//    return 0;\n//}	模板：Code01_DescartesTree2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b8f555aa-ff06-4de0-8f4b-49884ef94f4c	91090307-c3f6-43ef-841b-e4eedbb8f6e7	java	package class151;\n\n// Treap树的实现(java版)\n// 实现一种结构，支持如下操作，要求单次调用的时间复杂度O(log n)\n// 1，增加x，重复加入算多个词频\n// 2，删除x，如果有多个，只删掉一个\n// 3，查询x的排名，x的排名为，比x小的数的个数+1\n// 4，查询数据中排名为x的数\n// 5，查询x的前驱，x的前驱为，小于x的数中最大的数，不存在返回整数最小值\n// 6，查询x的后继，x的后继为，大于x的数中最小的数，不存在返回整数最大值\n// 所有操作的次数 <= 10^5\n// -10^7 <= x <= +10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P3369\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_Treap1 {\n\n\tpublic static int MAXN = 100001;\n\n\t// 整棵树的头节点编号\n\tpublic static int head = 0;\n\n\t// 空间使用计数\n\tpublic static int cnt = 0;\n\n\t// 节点的key值\n\tpublic static int[] key = new int[MAXN];\n\n\t// 节点key的计数\n\tpublic static int[] count = new int[MAXN];\n\n\t// 左孩子\n\tpublic static int[] left = new int[MAXN];\n\n\t// 右孩子\n\tpublic static int[] right = new int[MAXN];\n\n\t// 数字总数\n\tpublic static int[] size = new int[MAXN];\n\n\t// 节点优先级\n\tpublic static double[] priority = new double[MAXN];\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + count[i];\n\t}\n\n\tpublic static int leftRotate(int i) {\n\t\tint r = right[i];\n\t\tright[i] = left[r];\n\t\tleft[r] = i;\n\t\tup(i);\n\t\tup(r);\n\t\treturn r;\n\t}\n\n\tpublic static int rightRotate(int i) {\n\t\tint l = left[i];\n\t\tleft[i] = right[l];\n\t\tright[l] = i;\n\t\tup(i);\n\t\tup(l);\n\t\treturn l;\n\t}\n\n\tpublic static int add(int i, int num) {\n\t\tif (i == 0) {\n\t\t\tkey[++cnt] = num;\n\t\t\tcount[cnt] = size[cnt] = 1;\n\t\t\tpriority[cnt] = Math.random();\n\t\t\treturn cnt;\n\t\t}\n\t\tif (key[i] == num) {\n\t\t\tcount[i]++;\n\t\t} else if (key[i] > num) {\n\t\t\tleft[i] = add(left[i], num);\n\t\t} else {\n\t\t\tright[i] = add(right[i], num);\n\t\t}\n\t\tup(i);\n\t\tif (left[i] != 0 && priority[left[i]] > priority[i]) {\n\t\t\treturn rightRotate(i);\n\t\t}\n\t\tif (right[i] != 0 && priority[right[i]] > priority[i]) {\n\t\t\treturn leftRotate(i);\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void add(int num) {\n\t\thead = add(head, num);\n\t}\n\n\tpublic static int small(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn small(left[i], num);\n\t\t} else {\n\t\t\treturn size[left[i]] + count[i] + small(right[i], num);\n\t\t}\n\t}\n\n\tpublic static int rank(int num) {\n\t\treturn small(head, num) + 1;\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + count[i] < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - count[i]);\n\t\t}\n\t\treturn key[i];\n\t}\n\n\tpublic static int index(int x) {\n\t\treturn index(head, x);\n\t}\n\n\tpublic static int pre(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MIN_VALUE;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn pre(left[i], num);\n\t\t} else {\n\t\t\treturn Math.max(key[i], pre(right[i], num));\n\t\t}\n\t}\n\n\tpublic static int pre(int num) {\n\t\treturn pre(head, num);\n\t}\n\n\tpublic static int post(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t}\n\t\tif (key[i] <= num) {\n\t\t\treturn post(right[i], num);\n\t\t} else {\n\t\t\treturn Math.min(key[i], post(left[i], num));\n\t\t}\n\t}\n\n\tpublic static int post(int num) {\n\t\treturn post(head, num);\n\t}\n\n\tpublic static int remove(int i, int num) {\n\t\tif (key[i] < num) {\n\t\t\tright[i] = remove(right[i], num);\n\t\t} else if (key[i] > num) {\n\t\t\tleft[i] = remove(left[i], num);\n\t\t} else {\n\t\t\tif (count[i] > 1) {\n\t\t\t\tcount[i]--;\n\t\t\t} else {\n\t\t\t\tif (left[i] == 0 && right[i] == 0) {\n\t\t\t\t\treturn 0;\n\t\t\t\t} else if (left[i] != 0 && right[i] == 0) {\n\t\t\t\t\ti = left[i];\n\t\t\t\t} else if (left[i] == 0 && right[i] != 0) {\n\t\t\t\t\ti = right[i];\n\t\t\t\t} else {\n\t\t\t\t\tif (priority[left[i]] >= priority[right[i]]) {\n\t\t\t\t\t\ti = rightRotate(i);\n\t\t\t\t\t\tright[i] = remove(right[i], num);\n\t\t\t\t\t} else {\n\t\t\t\t\t\ti = leftRotate(i);\n\t\t\t\t\t\tleft[i] = remove(left[i], num);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup(i);\n\t\treturn i;\n\t}\n\n\tpublic static void remove(int num) {\n\t\tif (rank(num) != rank(num + 1)) {\n\t\t\thead = remove(head, num);\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tArrays.fill(key, 1, cnt + 1, 0);\n\t\tArrays.fill(count, 1, cnt + 1, 0);\n\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\tArrays.fill(size, 1, cnt + 1, 0);\n\t\tArrays.fill(priority, 1, cnt + 1, 0);\n\t\tcnt = 0;\n\t\thead = 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1, op, x; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(x);\n\t\t\t} else if (op == 3) {\n\t\t\t\tout.println(rank(x));\n\t\t\t} else if (op == 4) {\n\t\t\t\tout.println(index(x));\n\t\t\t} else if (op == 5) {\n\t\t\t\tout.println(pre(x));\n\t\t\t} else {\n\t\t\t\tout.println(post(x));\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_Treap1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
