9c60e22d-7412-429f-bfd6-3cccced16245	91090307-c3f6-43ef-841b-e4eedbb8f6e7	java	package class152;\n\n// 可持久化平衡树，FHQ-Treap实现，不用词频压缩，java版\n// 认为一开始是0版本的树，为空树，实现如下操作，操作一共发生n次\n// v 1 x : 基于v版本的树，增加一个x，生成新版本的树\n// v 2 x : 基于v版本的树，删除一个x，生成新版本的树\n// v 3 x : 基于v版本的树，查询x的排名，生成新版本的树状况=v版本状况\n// v 4 x : 基于v版本的树，查询数据中排名为x的数，生成新版本的树状况=v版本状况\n// v 5 x : 基于v版本的树，查询x的前驱，生成新版本的树状况=v版本状况\n// v 6 x : 基于v版本的树，查询x的后继，生成新版本的树状况=v版本状况\n// 不管什么操作，都基于某个v版本，操作完成后得到新版本的树，但v版本不会变化\n// 如果x的前驱不存在，返回-2^31 + 1，如果x的后继不存在，返回+2^31 - 1\n// 1 <= n <= 5 * 10^5\n// -10^9 <= x <= +10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3835\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code05_PersistentFHQTreap1 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int MAXM = MAXN * 50;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] key = new int[MAXM];\n\n\tpublic static int[] left = new int[MAXM];\n\n\tpublic static int[] right = new int[MAXM];\n\n\tpublic static int[] size = new int[MAXM];\n\n\tpublic static double[] priority = new double[MAXM];\n\n\tpublic static int copy(int i) {\n\t\tkey[++cnt] = key[i];\n\t\tleft[cnt] = left[i];\n\t\tright[cnt] = right[i];\n\t\tsize[cnt] = size[i];\n\t\tpriority[cnt] = priority[i];\n\t\treturn cnt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\tpublic static void split(int l, int r, int i, int num) {\n\t\tif (i == 0) {\n\t\t\tright[l] = left[r] = 0;\n\t\t} else {\n\t\t\ti = copy(i);\n\t\t\tif (key[i] <= num) {\n\t\t\t\tright[l] = i;\n\t\t\t\tsplit(i, r, right[i], num);\n\t\t\t} else {\n\t\t\t\tleft[r] = i;\n\t\t\t\tsplit(l, i, left[i], num);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int merge(int l, int r) {\n\t\tif (l == 0 || r == 0) {\n\t\t\treturn l + r;\n\t\t}\n\t\tif (priority[l] >= priority[r]) {\n\t\t\tl = copy(l);\n\t\t\tright[l] = merge(right[l], r);\n\t\t\tup(l);\n\t\t\treturn l;\n\t\t} else {\n\t\t\tr = copy(r);\n\t\t\tleft[r] = merge(l, left[r]);\n\t\t\tup(r);\n\t\t\treturn r;\n\t\t}\n\t}\n\n\t// v : 新生成的版本编号\n\t// i : 基于的历史版本，树的头节点编号\n\t// num : 加入的数字\n\tpublic static void add(int v, int i, int num) {\n\t\tsplit(0, 0, i, num);\n\t\tint l = right[0];\n\t\tint r = left[0];\n\t\t// 后续可能基于0版本，去生成新版本的树，所以一定要清空，保证0版本始终是空树\n\t\tleft[0] = right[0] = 0;\n\t\tkey[++cnt] = num;\n\t\tsize[cnt] = 1;\n\t\tpriority[cnt] = Math.random();\n\t\thead[v] = merge(merge(l, cnt), r);\n\t}\n\n\t// v : 新生成的版本编号\n\t// i : 基于的历史版本，树的头节点编号\n\t// num : 加入的数字\n\tpublic static void remove(int v, int i, int num) {\n\t\tsplit(0, 0, i, num);\n\t\tint lm = right[0];\n\t\tint r = left[0];\n\t\tsplit(0, 0, lm, num - 1);\n\t\tint l = right[0];\n\t\tint m = left[0];\n\t\t// 后续可能基于0版本，去生成新版本的树，所以一定要清空，保证0版本始终是空树\n\t\tleft[0] = right[0] = 0;\n\t\thead[v] = merge(merge(l, merge(left[m], right[m])), r);\n\t}\n\n\tpublic static int small(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn small(left[i], num);\n\t\t} else {\n\t\t\treturn size[left[i]] + 1 + small(right[i], num);\n\t\t}\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + 1 < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - 1);\n\t\t} else {\n\t\t\treturn key[i];\n\t\t}\n\t}\n\n\tpublic static int pre(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MIN_VALUE + 1;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn pre(left[i], num);\n\t\t} else {\n\t\t\treturn Math.max(key[i], pre(right[i], num));\n\t\t}\n\t}\n\n\tpublic static int post(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t}\n\t\tif (key[i] <= num) {\n\t\t\treturn post(right[i], num);\n\t\t} else {\n\t\t\treturn Math.min(key[i], post(left[i], num));\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tint n = in.readInt();\n\t\tfor (int i = 1, version, op, x; i <= n; i++) {\n\t\t\tversion = in.readInt();\n\t\t\top = in.readInt();\n\t\t\tx = in.readInt();\n\t\t\tif (op == 1) {\n\t\t\t\tadd(i, head[version], x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(i, head[version], x);\n\t\t\t} else {\n\t\t\t\thead[i] = head[version];\n\t\t\t\tif (op == 3) {\n\t\t\t\t\tout.println(small(head[i], x) + 1);\n\t\t\t\t} else if (op == 4) {\n\t\t\t\t\tout.println(index(head[i], x));\n\t\t\t\t} else if (op == 5) {\n\t\t\t\t\tout.println(pre(head[i], x));\n\t\t\t\t} else {\n\t\t\t\t\tout.println(post(head[i], x));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n	模板：Code05_PersistentFHQTreap1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
