);\n//        } else {\n//            addEdge(x1, x2 + n);\n//            addEdge(x2, x1 + n);\n//        }\n//    }\n//    for (int i = 1; i <= n << 1; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == belong[i + n]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    if (check) {\n//        cout << "POSSIBLE" << "\\n";\n//        for (int i = 1; i <= n; i++) {\n//            if (belong[i] < belong[i + n]) {\n//                cout << "1 ";\n//            } else {\n//                cout << "0 ";\n//            }\n//        }\n//    } else {\n//        cout << "IMPOSSIBLE" << "\\n";\n//    }\n//    return 0;\n//}	模板：Code01_2SAT2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fac856dd-f5f1-4065-853c-a738ad8a0ee8	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 和平委员会，java版\n// 一共n个团体，每个团体有两个代表，所以有2n个代表\n// 第i号团体两个代表的编号为2i−1和2i，然后给定m个讨厌关系\n// 格式 x y : 编号x和编号y这两个代表，相互讨厌，不可共事\n// 现在要选出n个人组成委员会，每个团体的两个代表，有且仅有1人入选\n// 同时要求选出的委员会中，没有相互讨厌的代表，如果做不到，打印"NIE"\n// 如果能做到，按升序打印组成委员会的n个人的编号，任何一种方案都可以\n// 1 <= n <= 8 * 10^3\n// 0 <= m <= 2 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P5782\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_Committee1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 50001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn (x & 1) == 0 ? (x - 1) : (x + 1);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, other(v));\n\t\t\taddEdge(v, other(u));\n\t\t}\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1, a, b; i <= n; i++) {\n\t\t\ta = i << 1;\n\t\t\tb = a - 1;\n\t\t\tif (belong[a] == belong[b]) {\n\t\t\t\tcheck = false;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1, a, b; i <= n; i++) {\n\t\t\t\ta = i << 1;\n\t\t\t\tb = a - 1;\n\t\t\t\tif (belong[a] < belong[b]) {\n\t\t\t\t\tout.println(a);\n\t\t\t\t} else {\n\t\t\t\t\tout.println(b);\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("NIE");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_Committee1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
