5c79920b-ea83-4b1f-997c-93d8e056b7c3	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 宇航员，java版\n// 一共n个人，一共A、B、C三个任务，所有人都能执行C任务，给定每人的年龄，假设平均年龄为f\n// 年龄 >= f 的人可以执行A任务，年龄 < f 的人可以执行B任务\n// 给定m个厌恶关系，格式 x y，代表编号x和编号y的两人相互讨厌\n// 每个人必须选一个任务，相互讨厌的人不能分配相同任务，允许某个任务无人执行\n// 如果存在分配任务的方案，打印每个人分配了什么任务，任何一种方案都可以\n// 如果不存在方案，打印"No solution."\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/UVA1391\n// 测试链接 : https://vjudge.net/problem/UVA-1391\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Astronauts1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 500001;\n\tpublic static int n, m;\n\tpublic static int[] age = new int[MAXN];\n\tpublic static int sumAge;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void prepare() {\n\t\tsumAge = cntg = cntd = sccCnt = 0;\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = belong[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static boolean older(int x) {\n\t\treturn age[x] * n >= sumAge;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\twhile (n != 0 && m != 0) {\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tage[i] = in.nextInt();\n\t\t\t\tsumAge += age[i];\n\t\t\t}\n\t\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\taddEdge(x + n, y);\n\t\t\t\taddEdge(y + n, x);\n\t\t\t\tif (older(x) == older(y)) {\n\t\t\t\t\taddEdge(x, y + n);\n\t\t\t\t\taddEdge(y, x + n);\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\t// tarjan1(i);\n\t\t\t\t\ttarjan2(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\tboolean check = true;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\t\tcheck = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (check) {\n\t\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\t\tif (belong[i] < belong[i + n]) {\n\t\t\t\t\t\tif (older(i)) {\n\t\t\t\t\t\t\tout.println("A");\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tout.println("B");\n\t\t\t\t\t\t}\n\t\t\t\t\t} else {\n\t\t\t\t\t\tout.println("C");\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tout.println("No solution.");\n\t\t\t}\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_Astronauts1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
