!= 0) {\n//        prepare();\n//        for (int i = 1; i <= n; i++) {\n//            cin >> age[i];\n//            sumAge += age[i];\n//        }\n//        for (int i = 1, x, y; i <= m; i++) {\n//            cin >> x >> y;\n//            addEdge(x + n, y);\n//            addEdge(y + n, x);\n//            if (older(x) == older(y)) {\n//                addEdge(x, y + n);\n//                addEdge(y, x + n);\n//            }\n//        }\n//        for (int i = 1; i <= n << 1; i++) {\n//            if (dfn[i] == 0) {\n//                tarjan(i);\n//            }\n//        }\n//        bool check = true;\n//        for (int i = 1; i <= n; i++) {\n//            if (belong[i] == belong[i + n]) {\n//                check = false;\n//                break;\n//            }\n//        }\n//        if (check) {\n//            for (int i = 1; i <= n; i++) {\n//                if (belong[i] < belong[i + n]) {\n//                    if (older(i)) {\n//                        cout << "A" << "\\n";\n//                    } else {\n//                        cout << "B" << "\\n";\n//                    }\n//                } else {\n//                    cout << "C" << "\\n";\n//                }\n//            }\n//        } else {\n//            cout << "No solution." << "\\n";\n//        }\n//        cin >> n >> m;\n//    }\n//    return 0;\n//}	模板：Code03_Astronauts2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3cad3d1d-d0cf-4483-b425-ffb6f62e54b6	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 约束条件，java版\n// 你需要构造长度为n的数组arr，每个元素的值在1~k之间，数组是非递减的\n// 接下来给定m个约束条件，构造方案要满足所有约束条件，约束的格式如下\n// 约束 1 i x   : arr[i] != x\n// 约束 2 i j x : arr[i] + arr[j] <= x\n// 约束 3 i j x : arr[i] + arr[j] >= x\n// 如果不存在构造方案打印-1，存在方案就打印arr，任何一种方案都可以\n// n、m <= 2 * 10^4\n// 2 <= k <= 10\n// 测试链接 : https://www.luogu.com.cn/problem/CF1697F\n// 测试链接 : https://codeforces.com/problemset/problem/1697/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Constraints1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 2000001;\n\tpublic static int MAXK = 12;\n\tpublic static int MAXT = MAXN * MAXK * 2;\n\tpublic static int t, n, m, k;\n\n\tpublic static int[][][] id = new int[MAXN][MAXK][2];\n\tpublic static int cntt;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tcntg = cntd = sccCnt = 0;\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = belong[i] = 0;\n\t\t}\n\t\t// 每个假设分配节点编号\n\t\tcntt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int v = 1; v <= k + 1; v++) {\n\t\t\t\tid[i][v][0] = ++cntt;\n\t\t\t\tid[i][v][1] = ++cntt;\n\t\t\t}\n\t\t}\n\t\t// 天然成立\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int v = 1; v <= k; v++) {\n\t\t\t\taddEdge(id[i][v][0], id[i][v + 1][0]);\n\t\t\t\taddEdge(id[i][v + 1][1], id[i][v][1]);\n\t\t\t}\n\t\t}\n\t\t// 数组非递减\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tfor (int v = 1; v <= k; v++) {\n\t\t\t\taddEdge(id[i + 1][v][0], id[i][v][0]);\n\t\t\t\taddEdge(id[i][v][1], id[i + 1][v][1]);\n\t\t\t}\n\t\t}\n\t\t// 每个位置的值在[1, k]范围\n\t\t// 规避错误假设\n\t\t// 强连通分量解决2-SAT问题的特性，永远选择拓扑序靠后的假设\n\t\t// (值 < 1) -> (值 >= 1)，推出矛盾固然不可行，如果无矛盾，会以后者为准\n\t\t// (值 >= k+1) -> (值 < k+1)，推出矛盾固然不可行，如果无矛盾，会以后者为准\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddEdge(id[i][1][0], id[i][1][1]);\n\t\t\taddEdge(id[i][k + 1][1], id[i][k + 1][0]);\n\t\t}\n\t}\n\n\tpublic static void notEqual(int i, int x) {\n\t\taddEdge(id[i][x][1], id[i][x + 1][1]);\n\t\taddEdge(id[i][x + 1][0], id[i][x][0]);\n\t}\n\n\tpublic static void lessEqual(int i, int j, int x) {\n\t\tfor (int w = 1; w <= k; w++) {\n\t\t\tif (w >= x) {\n\t\t\t\tnotEqual(i, w);\n\t\t\t} else {\n\t\t\t\tif (x - w + 1 <= k) {\n\t\t\t\t\taddEdge(id[i][w][1], id[j][x - w + 1][0]);\n\t\t\t\t\taddEdge(id[j][x - w + 1][1], id[i][w][0]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void moreEqual(int i, int j, int x) {\n\t\tfor (int w = 1; w <= k; w++) {\n\t\t\tif (w <= x - k - 1) {\n\t\t\t\tnotEqual(i, w);\n\t\t\t} else {\n\t\t\t\tif (x - w > 1) {\n\t\t\t\t\taddEdge(id[i][w + 1][0], id[j][x - w][1]);\n\t\t\t\t\taddEdge(id[j][x - w][0], id[i][w + 1][1]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tk = in.nextInt();\n\t\t\tprepare();\n\t\t\tfor (int i = 1, op, x, y, v; i <= m; i++) {\n\t\t\t\top = in.nextInt();\n\t\t\t\tif (op == 1) {\n\t\t\t\t\tx = in.nextInt();\n\t\t\t\t\tv = in.nextInt();\n\t\t\t\t\tnotEqual(x, v);\n\t\t\t\t} else if (op == 2) {\n\t\t\t\t\tx = in.nextInt();\n\t\t\t\t\ty = in.nextInt();\n\t\t\t\t\tv = in.nextInt();\n\t\t\t\t\tlessEqual(x, y, v);\n\t\t\t\t\tint tmp = x;\n\t\t\t\t\tx = y;\n\t\t\t\t\ty = tmp;\n\t\t\t\t\tlessEqual(x, y, v);\n\t\t\t\t} else {\n\t\t\t\t\tx = in.nextInt();\n\t\t\t\t\ty = in.nextInt();\n\t\t\t\t\tv = in.nextInt();\n\t\t\t\t\tmoreEqual(x, y, v);\n\t\t\t\t\tint tmp = x;\n\t\t\t\t\tx = y;\n\t\t\t\t\ty = tmp;\n\t\t\t\t\tmoreEqual(x, y, v);\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\ttarjan(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\tboolean check = true;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int v = 1; v <= k + 1; v++) {\n\t\t\t\t\tif (belong[id[i][v][0]] == belong[id[i][v][1]]) {\n\t\t\t\t\t\tcheck = false;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (!check) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (check) {\n\t\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\t\tfor (int v = k; v >= 1; v--) {\n\t\t\t\t\t\tif (belong[id[i][v][1]] < belong[id[i][v][0]]) {\n\t\t\t\t\t\t\tout.print(v + " ");\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tout.println();\n\t\t\t} else {\n\t\t\t\tout.println(-1);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_Constraints1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
