d523f936-22f7-4899-8f6c-c589e91ed21e	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 同谋者，java版\n// 一共n个人，编号1~n，分配每个人进入交流队或者保密队中的一个\n// 交流队要求内部任意两人都认识，保密队要求内部任意两人都不认识\n// 给定每人的认识列表，如果x的认识列表里有y，那么y的认识列表里有x\n// 分配还要求交流队和保密队都不能为空，计算n个人分成两组的方法数\n// 如果不存在任何方法，打印0\n// 2 <= n <= 5000\n// 所有认识列表的总人数 <= n * (n - 1)\n// 测试链接 : https://www.luogu.com.cn/problem/P3513\n// 测试链接 : https://loj.ac/p/2155\n// 提交以下的code，提交时请把类名改成"Main"\n// 本题给的使用空间很小，java的实现无法通过\n// 想通过用C++实现，本节课Code05_Conspiracy2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Conspiracy1 {\n\n\tpublic static int MAXN = 5001;\n\tpublic static int MAXT = MAXN << 1;\n\tpublic static int MAXM = MAXN * MAXN;\n\tpublic static int n, k, x;\n\tpublic static boolean[][] know = new boolean[MAXN][MAXN];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\tpublic static int[] team1 = new int[MAXN];\n\tpublic static int[] team2 = new int[MAXN];\n\tpublic static int cnt1, cnt2;\n\n\t// 如果i在交流队\n\t// other[i] >= 1，表示i认识保密队中的人的编号\n\t// other[i] == 0，表示i不认识保密队中的所有人\n\t// other[i] == -1，表示i认识保密队中的人数，不止一个\n\t//\n\t// 如果i在保密队\n\t// other[i] >= 1，表示i不认识交流队中的人的编号\n\t// other[i] == 0，表示i认识交流队中的所有人\n\t// other[i] == -1，表示i不认识交流队中的人数，不止一个\n\tpublic static int[] other = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] < belong[i + n]) {\n\t\t\t\tteam1[++cnt1] = i;\n\t\t\t} else {\n\t\t\t\tteam2[++cnt2] = i;\n\t\t\t}\n\t\t}\n\t\tint ans = cnt1 > 0 && cnt2 > 0 ? 1 : 0;\n\t\tfor (int i = 1, a, b; i <= cnt1; i++) {\n\t\t\ta = team1[i];\n\t\t\tfor (int j = 1; j <= cnt2; j++) {\n\t\t\t\tb = team2[j];\n\t\t\t\tif (know[a][b]) {\n\t\t\t\t\tother[a] = other[a] == 0 ? b : -1;\n\t\t\t\t} else {\n\t\t\t\t\tother[b] = other[b] == 0 ? a : -1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (cnt1 > 1) {\n\t\t\tfor (int i = 1; i <= cnt1; i++) {\n\t\t\t\tif (other[team1[i]] == 0) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (cnt2 > 1) {\n\t\t\tfor (int i = 1; i <= cnt2; i++) {\n\t\t\t\tif (other[team2[i]] == 0) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1, a, b; i <= cnt1; i++) {\n\t\t\ta = team1[i];\n\t\t\tfor (int j = 1; j <= cnt2; j++) {\n\t\t\t\tb = team2[j];\n\t\t\t\tif (know[a][b]) {\n\t\t\t\t\tif (other[a] == b && other[b] == 0) {\n\t\t\t\t\t\tans++;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (other[b] == a && other[a] == 0) {\n\t\t\t\t\t\tans++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tknow[i][x] = true;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = i + 1; j <= n; j++) {\n\t\t\t\tif (know[i][j]) {\n\t\t\t\t\taddEdge(i + n, j);\n\t\t\t\t\taddEdge(j + n, i);\n\t\t\t\t} else {\n\t\t\t\t\taddEdge(i, j + n);\n\t\t\t\t\taddEdge(j, i + n);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tint ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_Conspiracy1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
