 ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> k;\n//    cntt = n << 1;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u + n, v);\n//        addEdge(v + n, u);\n//    }\n//    for (int i = 1; i <= k; i++) {\n//        cin >> w;\n//        for (int j = 1; j <= w; j++) {\n//            cin >> arr[j];\n//        }\n//        link();\n//    }\n//    for (int i = 1; i <= cntt; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == belong[i + n]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    cout << (check ? "TAK" : "NIE") << "\\n";\n//    return 0;\n//}	模板：Code06_Riddle2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
01c16f86-fcb2-4ca2-af1e-15e96b43ed41	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 互质，java版\n// 一共n张卡片，每张卡片给定两个待选数字，选择其中一个数字作为卡片的值\n// 确定每张卡片的值之后，如果任意两张卡片的值都是互质的，那么算作成功\n// 存在成功的选值方案打印"Yes"，不存在打印"No"\n// 1 <= n <= 3 * 10^4\n// 1 <= 待选数字 <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc210_f\n// 测试链接 : https://atcoder.jp/contests/abc210/tasks/abc210_f\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code07_Coprime1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int MAXV = 2000001;\n\tpublic static int MAXM = 3000001;\n\tpublic static int n, cntt, maxv;\n\tpublic static int[] ab = new int[MAXN];\n\n\t// 利用欧拉筛生成最小质因子表\n\tpublic static boolean[] vis = new boolean[MAXV];\n\tpublic static int[] prime = new int[MAXV];\n\tpublic static int[] minp = new int[MAXV];\n\tpublic static int cntp;\n\n\t// 质因子、拥有这个质因子的数字编号\n\t// 排序后得到每个质因子的数字编号列表\n\tpublic static int[][] arr = new int[MAXN][2];\n\tpublic static int cnta;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? (x + n) : (x - n);\n\t}\n\n\t// 欧拉筛，讲解097\n\t// 利用欧拉筛的过程，生成最小质因子表\n\tpublic static void euler() {\n\t\tfor (int i = 2; i <= maxv; i++) {\n\t\t\tif (!vis[i]) {\n\t\t\t\tprime[++cntp] = i;\n\t\t\t\tminp[i] = i;\n\t\t\t}\n\t\t\tfor (int j = 1, p, v; j <= cntp; j++) {\n\t\t\t\tp = prime[j];\n\t\t\t\tv = i * p;\n\t\t\t\tif (v > maxv) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tvis[v] = true;\n\t\t\t\tminp[v] = p;\n\t\t\t\tif (i % p == 0) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 质因子分解\n\tpublic static void decompose() {\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tfor (int v = ab[i], p = minp[v]; v > 1; p = minp[v]) {\n\t\t\t\tarr[++cnta][0] = p;\n\t\t\t\tarr[cnta][1] = i;\n\t\t\t\twhile (v % p == 0) {\n\t\t\t\t\tv /= p;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 前后缀优化建图\n\tpublic static void link() {\n\t\tArrays.sort(arr, 1, cnta + 1, (a, b) -> a[0] != b[0] ? (a[0] - b[0]) : (a[1] - b[1]));\n\t\tfor (int l = 1, r = 1; l <= cnta; l = ++r) {\n\t\t\twhile (r + 1 <= cnta && arr[l][0] == arr[r + 1][0]) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tcntt++;\n\t\t\taddEdge(cntt, other(arr[l][1]));\n\t\t\tfor (int i = l + 1; i <= r; i++) {\n\t\t\t\tcntt++;\n\t\t\t\taddEdge(cntt, other(arr[i][1]));\n\t\t\t\taddEdge(arr[i][1], cntt - 1);\n\t\t\t\taddEdge(cntt, cntt - 1);\n\t\t\t}\n\t\t\tcntt++;\n\t\t\taddEdge(cntt, other(arr[r][1]));\n\t\t\tfor (int i = r - 1; i >= l; i--) {\n\t\t\t\tcntt++;\n\t\t\t\taddEdge(cntt, other(arr[i][1]));\n\t\t\t\taddEdge(arr[i][1], cntt - 1);\n\t\t\t\taddEdge(cntt, cntt - 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tcntt = n << 1;\n\t\tfor (int i = 1, a, b; i <= n; i++) {\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tab[i] = a;\n\t\t\tab[i + n] = b;\n\t\t\tmaxv = Math.max(maxv, Math.max(a, b));\n\t\t}\n\t\teuler();\n\t\tdecompose();\n\t\tlink();\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tout.println(check ? "Yes" : "No");\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_Coprime1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
