045b162e-07fb-4cd6-8cf7-2eac27ed0d39	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class196;\n\n// 电台，java版\n// 给定数值f，范围[1, f]上，你要选一个数字ansx作为固定频率\n// 一共p个电台，每个电台给定频率范围[l, r]，频率范围包含ansx的电台才能签约\n// 签约电台还要满足n个要求和m个限制，具体格式如下\n// 要求 u v : 必须签下电台u或者电台v\n// 限制 u v : 电台u和电台v不能同时签下\n// 如果存在签约方案，找到任何一种即可，依次打印，签约电台的数量、ansx、所有签约电台的编号\n// 如果不存在签约方案，打印-1\n// 2 <= n、p、f、m <= 4 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1215F\n// 测试链接 : https://codeforces.com/problemset/problem/1215/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_RadioStations1 {\n\n\tpublic static int MAXN = 400001;\n\tpublic static int MAXT = 2000001;\n\tpublic static int MAXM = 4000001;\n\tpublic static int n, p, f, m, cntt;\n\n\tpublic static int[] l = new int[MAXN];\n\tpublic static int[] r = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\tpublic static int[] pre = new int[MAXN];\n\tpublic static int[] suf = new int[MAXN];\n\n\tpublic static int ansx;\n\tpublic static int[] pick = new int[MAXN];\n\tpublic static int siz;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void link() {\n\t\tpre[1] = ++cntt;\n\t\tfor (int i = 2; i <= f; i++) {\n\t\t\tpre[i] = ++cntt;\n\t\t\taddEdge(pre[i - 1], pre[i]);\n\t\t}\n\t\tsuf[f] = ++cntt;\n\t\tfor (int i = f - 1; i >= 1; i--) {\n\t\t\tsuf[i] = ++cntt;\n\t\t\taddEdge(suf[i + 1], suf[i]);\n\t\t}\n\t\tfor (int i = 1; i <= p; i++) {\n\t\t\taddEdge(i, pre[r[i]]);\n\t\t\taddEdge(i, suf[l[i]]);\n\t\t\tif (l[i] - 1 >= 1) {\n\t\t\t\taddEdge(pre[l[i] - 1], i + p);\n\t\t\t}\n\t\t\tif (r[i] + 1 <= f) {\n\t\t\t\taddEdge(suf[r[i] + 1], i + p);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= p; i++) {\n\t\t\tif (belong[i] == belong[i + p]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t} else if (belong[i] < belong[i + p]) {\n\t\t\t\tansx = Math.max(ansx, l[i]);\n\t\t\t\tpick[++siz] = i;\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tp = in.nextInt();\n\t\tf = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntt = p << 1;\n\t\tfor (int i = 1, u, v; i <= n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u + p, v);\n\t\t\taddEdge(v + p, u);\n\t\t}\n\t\tfor (int i = 1; i <= p; i++) {\n\t\t\tl[i] = in.nextInt();\n\t\t\tr[i] = in.nextInt();\n\t\t}\n\t\tlink();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v + p);\n\t\t\taddEdge(v, u + p);\n\t\t}\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println(siz + " " + ansx);\n\t\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\t\tout.print(pick[i] + " ");\n\t\t\t}\n\t\t} else {\n\t\t\tout.println(-1);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code08_RadioStations1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
