cdb010d2-3fc3-403f-8e9a-a0acc44b7da2	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class197;\n\n// 旗帜，java版\n// 一共n个旗子，第i号旗子有a[i]和b[i]两个可选位置\n// 你需要决定每个旗子，到底放在两个可选位置中的哪一个\n// 两面旗子之间的最小距离 d 越大，排列看起来就越美观\n// 找到最美观的情况，即求出所有可能的 d 值中的最大值\n// 2 <= n <= 10^4\n// 1 <= a[i]、b[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/AT_arc069_d\n// 测试链接 : https://atcoder.jp/contests/arc069/tasks/arc069_d\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_Flags1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXT = 100001;\n\tpublic static int MAXE = 1000001;\n\tpublic static int n, k;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\n\t// 所在的地点pos、决定的编号xid\n\tpublic static int[][] arr = new int[MAXN << 1][2];\n\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int root;\n\tpublic static int cntt;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\tpublic static int kth(int num) {\n\t\tint l = 1, r = k, mid, ans = k + 1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (arr[mid][0] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static int other(int i) {\n\t\treturn i <= n ? i + n : i - n;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = other(arr[l][1]);\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt]);\n\t\t\taddEdge(rt, rs[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int xid, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(xid, i);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(xid, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(xid, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void buildGraph(int d) {\n\t\tcntt = k;\n\t\troot = build(1, k);\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tint pos = arr[i][0];\n\t\t\tint l = kth(pos - d + 1);\n\t\t\tint r = kth(pos + d) - 1;\n\t\t\tint x = arr[i][1];\n\t\t\txToRange(x, l, i - 1, 1, k, root);\n\t\t\txToRange(x, i + 1, r, 1, k, root);\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = dfn[i] = belong[i] = 0;\n\t\t}\n\t\tcntt = cntg = cntd = top = sccCnt = 0;\n\t}\n\n\tpublic static boolean check(int d) {\n\t\tbuildGraph(d);\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\treturn check;\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = a[i];\n\t\t\tarr[i][1] = i;\n\t\t\tarr[i + n][0] = b[i];\n\t\t\tarr[i + n][1] = i + n;\n\t\t}\n\t\tk = n << 1;\n\t\tArrays.sort(arr, 1, k + 1, (x, y) -> x[0] != y[0] ? x[0] - y[0] : x[1] - y[1]);\n\t\tint l = 0, r = arr[k][0], d, ans = 0;\n\t\twhile (l <= r) {\n\t\t\td = (l + r) >> 1;\n\t\t\tif (check(d)) {\n\t\t\t\tans = d;\n\t\t\t\tl = d + 1;\n\t\t\t} else {\n\t\t\t\tr = d - 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tint ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_Flags1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
