0c5948ec-78e1-4dbf-967d-0494a580bcf1	3979cfd0-853c-4b8b-aa1d-10e768b17691	java	package class197;\n\n// 布尔，java版\n// 一共n个变量，取值为0或1，一共m条限制，格式 u x v y，含义如下\n// 如果u的取值为x，则v的取值为y，同时如果v的取值为y，则u的取值为x\n// 限制的编号范围1~m，限制区间[a, b]如果满足如下条件，就认为是合法的\n// 区间[a, b]内的所有限制，存在一种变量赋值方案，能让它们全部成立\n// 一共有q条查询，格式 l r，含义如下\n// 整个限制区间[l, r]，最少划分成多少段连续区间，使得每个连续区间都合法\n// 打印划分的连续区间数量，如果怎么划分都做不到上述要求，打印-1\n// 1 <= n <= 10^5\n// 1 <= m <= 6 * 10^5\n// 1 <= q <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P7843\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Boolean1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 600001;\n\tpublic static int MAXQ = 1000001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q;\n\n\t// 错误计数\n\tpublic static int[] error = new int[MAXM];\n\n\t// 决定编号\n\tpublic static int[] u = new int[MAXM];\n\tpublic static int[] v = new int[MAXM];\n\n\t// 可撤销并查集\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize;\n\n\t// first[i] = 从i位置开始，向右不停添加限制，首次违规的位置\n\tpublic static int[] first = new int[MAXM];\n\n\t// st[i][p] = 从i位置开始，允许拆成2的p次个连续区间，每个都合法，往右能到什么位置\n\tpublic static int[][] st = new int[MAXM + 1][MAXP];\n\n\tpublic static int find(int i) {\n\t\twhile (i != fa[i]) {\n\t\t\ti = fa[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx != fy) {\n\t\t\tif (siz[fx] < siz[fy]) {\n\t\t\t\tint tmp = fx;\n\t\t\t\tfx = fy;\n\t\t\t\tfy = tmp;\n\t\t\t}\n\t\t\tfa[fy] = fx;\n\t\t\tsiz[fx] += siz[fy];\n\t\t\trollback[++opsize][0] = fx;\n\t\t\trollback[opsize][1] = fy;\n\t\t}\n\t}\n\n\tpublic static void undo(int oldsiz) {\n\t\twhile (opsize > oldsiz) {\n\t\t\tint fx = rollback[opsize][0];\n\t\t\tint fy = rollback[opsize--][1];\n\t\t\tfa[fy] = fy;\n\t\t\tsiz[fx] -= siz[fy];\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static boolean conflict(int x) {\n\t\treturn find(x) == find(other(x));\n\t}\n\n\t// 整体二分，计算每个位置i的first[i]信息\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tfirst[i] = vl;\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\tint mid = (vl + vr) >> 1;\n\t\tint backup1 = opsize;\n\t\tboolean bad = false;\n\t\tfor (int i = Math.max(qr + 1, vl); i <= mid; i++) {\n\t\t\tunion(u[i], v[i]);\n\t\t\tunion(other(u[i]), other(v[i]));\n\t\t\tif (conflict(u[i])) {\n\t\t\t\tbad = true;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (bad) {\n\t\t\tundo(backup1);\n\t\t\tcompute(ql, qr, vl, mid);\n\t\t} else {\n\t\t\tint backup2 = opsize;\n\t\t\tint split = Math.min(qr, mid);\n\t\t\tfor (; split >= ql; split--) {\n\t\t\t\tunion(u[split], v[split]);\n\t\t\t\tunion(other(u[split]), other(v[split]));\n\t\t\t\tif (conflict(u[split])) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tundo(backup2);\n\t\t\tcompute(split + 1, qr, mid + 1, vr);\n\t\t\tundo(backup1);\n\t\t\tfor (int i = split + 1; i <= qr && i < vl; i++) {\n\t\t\t\tunion(u[i], v[i]);\n\t\t\t\tunion(other(u[i]), other(v[i]));\n\t\t\t}\n\t\t\tcompute(ql, split, vl, mid);\n\t\t}\n\t}\n\n\tpublic static void buildst() {\n\t\topsize = 0;\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tfa[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tcompute(1, m, 1, m + 1);\n\t\tfor (int p = 0; p < MAXP; p++) {\n\t\t\tst[m + 1][p] = m + 1;\n\t\t}\n\t\tfor (int i = m; i >= 1; i--) {\n\t\t\tst[i][0] = first[i];\n\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\tst[i][p] = st[st[i][p - 1]][p - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\terror[i] = u[i] == v[i] && x != y ? 1 : 0;\n\t\t\tu[i] = x == 0 ? u[i] : (u[i] + n);\n\t\t\tv[i] = y == 0 ? v[i] : (v[i] + n);\n\t\t}\n\t\tbuildst();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\terror[i] += error[i - 1];\n\t\t}\n\t\tfor (int i = 1, l, r; i <= q; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tif (error[r] - error[l - 1] > 0) {\n\t\t\t\tout.println(-1);\n\t\t\t} else {\n\t\t\t\tint ans = 0;\n\t\t\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\t\t\tif (st[l][p] <= r) {\n\t\t\t\t\t\tl = st[l][p];\n\t\t\t\t\t\tans += 1 << p;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans++;\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_Boolean1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
