41ccdaeb-b557-4b2c-87a9-005bffa5b156	2b19ef41-f490-4b2e-82cb-679bd626879d	java	package class202;\n\n// 动态树的加和乘，java版\n// 一共有n个点、n-1条边，每个点的初始点权都是1，所有节点组成一棵树\n// 接下来有q条操作，操作类型有四种，格式如下\n// 操作 + x y z   : x到y的路径上，点的权值都加上z，z是非负整数\n// 操作 * x y z   : x到y的路径上，点的权值都乘上z，z是非负整数\n// 操作 - x y a b : 删除原边(x,y)，加入新边(a,b)，操作后仍然是一棵树\n// 操作 / x y     : x到y的路径上，查询点权累加和，对 51061 取模\n// 1 <= n、q <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1501\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_DynamicAddMul1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MOD = 51061;\n\tpublic static int n, q;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static boolean[] rev = new boolean[MAXN];\n\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static long[] arr = new long[MAXN];\n\tpublic static long[] sum = new long[MAXN];\n\tpublic static long[] mulTag = new long[MAXN];\n\tpublic static long[] addTag = new long[MAXN];\n\n\tpublic static void up(int x) {\n\t\tsiz[x] = siz[ls[x]] + siz[rs[x]] + 1;\n\t\tsum[x] = (sum[ls[x]] + sum[rs[x]] + arr[x]) % MOD;\n\t}\n\n\tpublic static boolean isroot(int x) {\n\t\treturn ls[fa[x]] != x && rs[fa[x]] != x;\n\t}\n\n\tpublic static int lr(int x) {\n\t\treturn ls[fa[x]] == x ? 0 : 1;\n\t}\n\n\tpublic static void reverse(int x) {\n\t\tif (x != 0) {\n\t\t\tint tmp = ls[x];\n\t\t\tls[x] = rs[x];\n\t\t\trs[x] = tmp;\n\t\t\trev[x] = !rev[x];\n\t\t}\n\t}\n\n\tpublic static void effect(int x, long mul, long add) {\n\t\tif (x != 0) {\n\t\t\tarr[x] = (arr[x] * mul + add) % MOD;\n\t\t\tsum[x] = (sum[x] * mul + siz[x] * add) % MOD;\n\t\t\tmulTag[x] = mulTag[x] * mul % MOD;\n\t\t\taddTag[x] = (addTag[x] * mul + add) % MOD;\n\t\t}\n\t}\n\n\tpublic static void down(int x) {\n\t\tif (rev[x]) {\n\t\t\treverse(ls[x]);\n\t\t\treverse(rs[x]);\n\t\t\trev[x] = false;\n\t\t}\n\t\tif (mulTag[x] != 1 || addTag[x] != 0) {\n\t\t\teffect(ls[x], mulTag[x], addTag[x]);\n\t\t\teffect(rs[x], mulTag[x], addTag[x]);\n\t\t\tmulTag[x] = 1;\n\t\t\taddTag[x] = 0;\n\t\t}\n\t}\n\n\tpublic static void rotate(int x) {\n\t\tint f = fa[x], g = fa[f];\n\t\tif (lr(x) == 0) {\n\t\t\tls[f] = rs[x];\n\t\t\tif (ls[f] != 0) {\n\t\t\t\tfa[ls[f]] = f;\n\t\t\t}\n\t\t\trs[x] = f;\n\t\t} else {\n\t\t\trs[f] = ls[x];\n\t\t\tif (rs[f] != 0) {\n\t\t\t\tfa[rs[f]] = f;\n\t\t\t}\n\t\t\tls[x] = f;\n\t\t}\n\t\tif (!isroot(f)) {\n\t\t\tif (lr(f) == 0) {\n\t\t\t\tls[g] = x;\n\t\t\t} else {\n\t\t\t\trs[g] = x;\n\t\t\t}\n\t\t}\n\t\tfa[f] = x;\n\t\tfa[x] = g;\n\t\tup(f);\n\t\tup(x);\n\t}\n\n\tpublic static void splay(int x) {\n\t\tint siz = 0;\n\t\tsta[++siz] = x;\n\t\tfor (int y = x; !isroot(y); y = fa[y]) {\n\t\t\tsta[++siz] = fa[y];\n\t\t}\n\t\twhile (siz != 0) {\n\t\t\tdown(sta[siz--]);\n\t\t}\n\t\twhile (!isroot(x)) {\n\t\t\tint f = fa[x];\n\t\t\tif (!isroot(f)) {\n\t\t\t\tif (lr(x) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(x);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(x);\n\t\t}\n\t}\n\n\tpublic static void access(int x) {\n\t\tfor (int y = 0; x != 0; y = x, x = fa[x]) {\n\t\t\tsplay(x);\n\t\t\trs[x] = y;\n\t\t\tup(x);\n\t\t}\n\t}\n\n\tpublic static void makeroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\treverse(x);\n\t}\n\n\tpublic static int findroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\tdown(x);\n\t\twhile (ls[x] != 0) {\n\t\t\tx = ls[x];\n\t\t\tdown(x);\n\t\t}\n\t\tsplay(x);\n\t\treturn x;\n\t}\n\n\tpublic static void split(int x, int y) {\n\t\tmakeroot(x);\n\t\taccess(y);\n\t\tsplay(y);\n\t}\n\n\tpublic static void link(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) != x) {\n\t\t\tfa[x] = y;\n\t\t}\n\t}\n\n\tpublic static void cut(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) == x && fa[y] == x && ls[y] == 0 && rs[x] == y) {\n\t\t\tfa[y] = rs[x] = 0;\n\t\t\tup(x);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsiz[i] = 1;\n\t\t\tarr[i] = 1;\n\t\t\tsum[i] = 1;\n\t\t\tmulTag[i] = 1;\n\t\t\taddTag[i] = 0;\n\t\t}\n\t\tfor (int i = 1, x, y; i < n; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tlink(x, y);\n\t\t}\n\t\tString op;\n\t\tint x, y, z, a, b;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = in.nextString();\n\t\t\tif (op.equals("+")) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tz %= MOD;\n\t\t\t\tsplit(x, y);\n\t\t\t\teffect(y, 1, z);\n\t\t\t} else if (op.equals("*")) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tz %= MOD;\n\t\t\t\tsplit(x, y);\n\t\t\t\teffect(y, z, 0);\n\t\t\t} else if (op.equals("-")) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tcut(x, y);\n\t\t\t\tlink(a, b);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tsplit(x, y);\n\t\t\t\tout.println(sum[y]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tString nextString() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tif (c == -1) {\n\t\t\t\treturn null;\n\t\t\t}\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t}\n\n}\n	模板：Code01_DynamicAddMul1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
