97706f4d-f4dd-4138-81d7-5c4ed96dbe4f	2b19ef41-f490-4b2e-82cb-679bd626879d	java	package class202;\n\n// 星球联盟，java版\n// 一共有n个点、m条无向边，接下来依次加入p条无向边\n// 如果两个点属于同一个联盟，必须存在一条环形线路经过这两个点\n// 等价地说，两个点之间存在两条没有公共边的路径，也就是在同一个边双连通分量中\n// 每次加入一条新边(x,y)，加入之后判断点x和点y是否属于同一个联盟\n// 如果不属于同一个联盟，打印"No"\n// 如果属于同一个联盟，打印这个联盟里的节点数\n// 1 <= n、m、p <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P10657\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Alliance1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int n, m, p;\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static boolean[] rev = new boolean[MAXN];\n\tpublic static int[] sta = new int[MAXN];\n\n\t// nodeCnt[x]表示x代表的边双连通分量中，有多少个原图节点\n\tpublic static int[] nodeCnt = new int[MAXN];\n\n\tpublic static int find(int x) {\n\t\tif (x != father[x]) {\n\t\t\tfather[x] = find(father[x]);\n\t\t}\n\t\treturn father[x];\n\t}\n\n\tpublic static boolean isroot(int x) {\n\t\treturn ls[fa[x]] != x && rs[fa[x]] != x;\n\t}\n\n\tpublic static int lr(int x) {\n\t\treturn ls[fa[x]] == x ? 0 : 1;\n\t}\n\n\tpublic static void reverse(int x) {\n\t\tif (x != 0) {\n\t\t\tint tmp = ls[x];\n\t\t\tls[x] = rs[x];\n\t\t\trs[x] = tmp;\n\t\t\trev[x] = !rev[x];\n\t\t}\n\t}\n\n\tpublic static void down(int x) {\n\t\tif (rev[x]) {\n\t\t\treverse(ls[x]);\n\t\t\treverse(rs[x]);\n\t\t\trev[x] = false;\n\t\t}\n\t}\n\n\tpublic static void rotate(int x) {\n\t\tint f = fa[x], g = fa[f];\n\t\tif (lr(x) == 0) {\n\t\t\tls[f] = rs[x];\n\t\t\tif (ls[f] != 0) {\n\t\t\t\tfa[ls[f]] = f;\n\t\t\t}\n\t\t\trs[x] = f;\n\t\t} else {\n\t\t\trs[f] = ls[x];\n\t\t\tif (rs[f] != 0) {\n\t\t\t\tfa[rs[f]] = f;\n\t\t\t}\n\t\t\tls[x] = f;\n\t\t}\n\t\tif (!isroot(f)) {\n\t\t\tif (lr(f) == 0) {\n\t\t\t\tls[g] = x;\n\t\t\t} else {\n\t\t\t\trs[g] = x;\n\t\t\t}\n\t\t}\n\t\tfa[f] = x;\n\t\tfa[x] = g;\n\t}\n\n\tpublic static void splay(int x) {\n\t\tint siz = 0;\n\t\tsta[++siz] = x;\n\t\tfor (int y = x; !isroot(y); y = fa[y]) {\n\t\t\tsta[++siz] = fa[y];\n\t\t}\n\t\twhile (siz != 0) {\n\t\t\tdown(sta[siz--]);\n\t\t}\n\t\twhile (!isroot(x)) {\n\t\t\tint f = fa[x];\n\t\t\tif (!isroot(f)) {\n\t\t\t\tif (lr(x) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(x);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(x);\n\t\t}\n\t}\n\n\tpublic static void access(int x) {\n\t\tx = find(x);\n\t\tfor (int y = 0; x != 0; y = x, x = fa[x]) {\n\t\t\tsplay(x);\n\t\t\trs[x] = y;\n\t\t\tfa[x] = find(fa[x]);\n\t\t}\n\t}\n\n\tpublic static void makeroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\treverse(x);\n\t}\n\n\tpublic static int findroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\tdown(x);\n\t\twhile (ls[x] != 0) {\n\t\t\tx = ls[x];\n\t\t\tdown(x);\n\t\t}\n\t\tsplay(x);\n\t\treturn x;\n\t}\n\n\tpublic static void condense(int x, int root) {\n\t\tif (x != 0) {\n\t\t\tfather[x] = root;\n\t\t\tnodeCnt[root] += nodeCnt[x];\n\t\t\tcondense(ls[x], root);\n\t\t\tcondense(rs[x], root);\n\t\t}\n\t}\n\n\t// 如果两点不连通就连接，如果连通，说明形成环，缩成一个边双\n\t// 如果不连通就返回-1，否则返回边双的节点数量\n\tpublic static int link(int x, int y) {\n\t\tx = find(x);\n\t\ty = find(y);\n\t\tif (x == y) {\n\t\t\treturn nodeCnt[x];\n\t\t}\n\t\tmakeroot(x);\n\t\tif (findroot(y) != x) {\n\t\t\tfa[x] = y;\n\t\t\treturn -1;\n\t\t} else {\n\t\t\tcondense(rs[x], x);\n\t\t\trs[x] = 0;\n\t\t\treturn nodeCnt[x];\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tp = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tnodeCnt[i] = 1;\n\t\t}\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tlink(x, y);\n\t\t}\n\t\tfor (int i = 1, x, y; i <= p; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tint ans = link(x, y);\n\t\t\tif (ans == -1) {\n\t\t\t\tout.println("No");\n\t\t\t} else {\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code05_Alliance1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
215ad037-1328-4e4c-96f3-f88ab0988235	2b19ef41-f490-4b2e-82cb-679bd626879d	java	package class202;\n\n// 星球联盟，C++版\n// 一共有n个点、m条无向边，接下来依次加入p条无向边\n// 如果两个点属于同一个联盟，必须存在一条环形线路经过这两个点\n// 等价地说，两个点之间存在两条没有公共边的路径，也就是在同一个边双连通分量中\n// 每次加入一条新边(x,y)，加入之后判断点x和点y是否属于同一个联盟\n// 如果不属于同一个联盟，打印"No"\n// 如果属于同一个联盟，打印这个联盟里的节点数\n// 1 <= n、m、p <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P10657\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//int n, m, p;\n//\n//int father[MAXN];\n//\n//int fa[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//bool rev[MAXN];\n//int sta[MAXN];\n//\n//int nodeCnt[MAXN];\n//\n//int find(int x) {\n//    if (x != father[x]) {\n//        father[x] = find(father[x]);\n//    }\n//    return father[x];\n//}\n//\n//bool isroot(int x) {\n//    return ls[fa[x]] != x && rs[fa[x]] != x;\n//}\n//\n//int lr(int x) {\n//    return ls[fa[x]] == x ? 0 : 1;\n//}\n//\n//void reverse(int x) {\n//    if (x != 0) {\n//        swap(ls[x], rs[x]);\n//        rev[x] = !rev[x];\n//    }\n//}\n//\n//void down(int x) {\n//    if (rev[x]) {\n//        reverse(ls[x]);\n//        reverse(rs[x]);\n//        rev[x] = false;\n//    }\n//}\n//\n//void rotate(int x) {\n//    int f = fa[x], g = fa[f];\n//    if (lr(x) == 0) {\n//        ls[f] = rs[x];\n//        if (ls[f] != 0) {\n//            fa[ls[f]] = f;\n//        }\n//        rs[x] = f;\n//    } else {\n//        rs[f] = ls[x];\n//        if (rs[f] != 0) {\n//            fa[rs[f]] = f;\n//        }\n//        ls[x] = f;\n//    }\n//    if (!isroot(f)) {\n//        if (lr(f) == 0) {\n//            ls[g] = x;\n//        } else {\n//            rs[g] = x;\n//        }\n//    }\n//    fa[f] = x;\n//    fa[x] = g;\n//}\n//\n//void splay(int x) {\n//    int siz = 0;\n//    sta[++siz] = x;\n//    for (int y = x; !isroot(y); y = fa[y]) {\n//        sta[++siz] = fa[y];\n//    }\n//    while (siz != 0) {\n//        down(sta[siz--]);\n//    }\n/