be6b61c8-9a7e-4aa1-ab7d-b78b799aaa0f	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 割点模版题，java版\n// 给定一张无向图，一共n个点、m条边，不保证所有点连通\n// 打印图中割点的数量，然后从小到大打印所有割点的编号\n// 1 <= n <= 2 * 10^4\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3388\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_CutVertex1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static boolean[] cutVertex = new boolean[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, root, son, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int root, int son, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = root;\n\t\tstack[stacksize][2] = son;\n\t\tstack[stacksize][3] = status;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\troot = stack[stacksize][1];\n\t\tson = stack[stacksize][2];\n\t\tstatus = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，Tarjan算法求解割点\n\tpublic static void tarjan1(int u, boolean root) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tint son = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tson++;\n\t\t\t\ttarjan1(v, false);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tif (!root || son >= 2) {\n\t\t\t\t\t\tcutVertex[u] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版，Tarjan算法求解割点\n\tpublic static void tarjan2(int node, boolean rt) {\n\t\tstacksize = 0;\n\t\tpush(node, rt ? 1 : 0, 0, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\t\tif (root == 0 || son >= 2) {\n\t\t\t\t\t\t\tcutVertex[u] = true;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tson++;\n\t\t\t\t\tpush(u, root, son, 0, e);\n\t\t\t\t\tpush(v, 0, 0, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, root, son, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i, true);\n\t\t\t\ttarjan2(i, true);\n\t\t\t}\n\t\t}\n\t\tint cntCnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (cutVertex[i]) {\n\t\t\t\tcntCnt++;\n\t\t\t}\n\t\t}\n\t\tout.println(cntCnt);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (cutVertex[i]) {\n\t\t\t\tout.print(i + " ");\n\t\t\t}\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_CutVertex1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
