45f87d16-845e-46a7-823e-29b3dfb31b69	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 点双连通分量模版题1，java版\n// 给定一张无向图，一共n个点、m条边，建图时忽略自环\n// 打印点双连通分量的个数\n// 打印每个点双连通分量的大小和节点编号\n// 打印顺序随意\n// 每个孤立点分配一个点双连通分量\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8435\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_VBCC1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 2000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] vbccSiz = new int[MAXN];\n\tpublic static int[] vbccArr = new int[MAXN << 1];\n\tpublic static int[] vbccl = new int[MAXN];\n\tpublic static int[] vbccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int vbccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，Tarjan算法求解点双连通分量\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tvbccCnt++;\n\t\t\t\t\tvbccSiz[vbccCnt] = 1;\n\t\t\t\t\tvbccArr[++idx] = u;\n\t\t\t\t\tvbccl[vbccCnt] = idx;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tvbccSiz[vbccCnt]++;\n\t\t\t\t\t\tvbccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t\tvbccr[vbccCnt] = idx;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版，Tarjan算法求解点双连通分量\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\t\tvbccCnt++;\n\t\t\t\t\t\tvbccSiz[vbccCnt] = 1;\n\t\t\t\t\t\tvbccArr[++idx] = u;\n\t\t\t\t\t\tvbccl[vbccCnt] = idx;\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\tvbccSiz[vbccCnt]++;\n\t\t\t\t\t\t\tvbccArr[++idx] = pop;\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t\tvbccr[vbccCnt] = idx;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (u != v) {\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\tif (head[i] == 0) {\n\t\t\t\t\tvbccCnt++;\n\t\t\t\t\tvbccSiz[vbccCnt] = 1;\n\t\t\t\t\tvbccArr[++idx] = i;\n\t\t\t\t\tvbccl[vbccCnt] = vbccr[vbccCnt] = idx;\n\t\t\t\t} else {\n\t\t\t\t\t// tarjan1(i);\n\t\t\t\t\ttarjan2(i);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.println(vbccCnt);\n\t\tfor (int i = 1; i <= vbccCnt; i++) {\n\t\t\tout.println(vbccSiz[i]);\n\t\t\tfor (int j = vbccl[i]; j <= vbccr[i]; j++) {\n\t\t\t\tout.print(vbccArr[j] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_VBCC1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
