672773d7-a967-4b2d-b58a-bcbcb4426f04	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 矿场搭建，java版\n// 一共n个地点，地点至少2个，每个地点都有人，m条双向道路连通所有地点\n// 地震会发生在任何一个地点，地震发生时，其他地点的人都要去往救援点\n// 你可以在任何地点设立救援点，但是发生地震的地点，道路和救援点都会失效\n// 打印至少需要几个救援点，打印设立救援点的方案总数，方案认为是无序集合\n// 1 <= n <= 1000\n// 1 <= m <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3225\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_MiningFarm1 {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int MAXM = 1001;\n\tpublic static int t, n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static boolean[] cutVertex = new boolean[MAXN];\n\tpublic static int[] vbccSiz = new int[MAXN];\n\tpublic static int[] vbccArr = new int[MAXN << 1];\n\tpublic static int[] vbccl = new int[MAXN];\n\tpublic static int[] vbccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int vbccCnt;\n\n\tpublic static long ans1, ans2;\n\n\tpublic static void prepare() {\n\t\tcntg = cntd = top = idx = vbccCnt = 0;\n\t\tfor (int i = 1; i < MAXN; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = 0;\n\t\t\tcutVertex[i] = false;\n\t\t}\n\t\tn = 0;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, boolean root) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tint son = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tson++;\n\t\t\t\ttarjan(v, false);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tif (!root || son >= 2) {\n\t\t\t\t\t\tcutVertex[u] = true;\n\t\t\t\t\t}\n\t\t\t\t\tvbccCnt++;\n\t\t\t\t\tvbccSiz[vbccCnt] = 1;\n\t\t\t\t\tvbccArr[++idx] = u;\n\t\t\t\t\tvbccl[vbccCnt] = idx;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tvbccSiz[vbccCnt]++;\n\t\t\t\t\t\tvbccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t\tvbccr[vbccCnt] = idx;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tif (vbccCnt == 1) {\n\t\t\tans1 = 2;\n\t\t\tans2 = n * (n - 1) / 2;\n\t\t} else {\n\t\t\tans1 = 0;\n\t\t\tans2 = 1;\n\t\t\tfor (int i = 1; i <= vbccCnt; i++) {\n\t\t\t\tint siz = vbccSiz[i], cut = 0;\n\t\t\t\tfor (int j = vbccl[i]; j <= vbccr[i]; j++) {\n\t\t\t\t\tif (cutVertex[vbccArr[j]]) {\n\t\t\t\t\t\tcut++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (cut == 1) {\n\t\t\t\t\tans1 += 1;\n\t\t\t\t\tans2 = ans2 * (siz - 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = 0;\n\t\tm = in.nextInt();\n\t\twhile (m != 0) {\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\tn = Math.max(n, u);\n\t\t\t\tn = Math.max(n, v);\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\ttarjan(1, true);\n\t\t\tcompute();\n\t\t\tout.println("Case " + (++t) + ": " + ans1 + " " + ans2);\n\t\t\tm = in.nextInt();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_MiningFarm1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
39978ea1-8078-4c6d-a064-b6166244fb01	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 矿场搭建，C++版\n// 一共n个地点，地点至少2个，每个地点都有人，m条双向道路连通所有地点\n// 地震会发生在任何一个地点，地震发生时，其他地点的人都要去往救援点\n// 你可以在任何地点设立救援点，但是发生地震的地点，道路和救援点都会失效\n// 打印至少需要几个救援点，打印设立救援点的方案总数，方案认为是无序集合\n// 1 <= n <= 1000\n// 1 <= m <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3225\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 1001;\n//const int MAXM = 1001;\n//int t, n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//bool cutVertex[MAXN];\n//int vbccSiz[MAXN];\n//int vbccArr[MAXN << 1];\n//int vbccl[MAXN];\n//int vbccr[MAXN];\n//int idx;\n//int vbccCnt;\n//\n//ll ans1, ans2;\n//\n//void prepare() {\n//    cntg = cntd = top = idx = vbccCnt = 0;\n//    for (int i = 1; i < MAXN; i++) {\n//        head[i] = dfn[i] = low[i] = 0;\n//        cutVertex[i] = false;\n//    }\n//    n = 0;\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, bool root) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    int son = 0;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            son++;\n//            tarjan(v, false);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] >= dfn[u]) {\n//                if (!root || son >= 2) {\n//                    cutVertex[u] = true;\n//                }\n//                vbccCnt++;\n//                vbccSiz[vbccCnt] = 1;\n//                vbccArr[++idx] = u;\n//                vbccl[vbccCnt] = idx;\n//                int pop;\n//                do {\n//                    pop = sta[top--];\n//                    vbccSiz[vbccCnt]++;\n//      