e379dba9-53de-484a-adea-a260d9edce54	f73b38de-e9d4-4ad5-b2eb-72d7dc03b2f3	java	package class193;\n\n// 圆桌骑士，java版\n// 一共n个骑士，有m条厌恶关系，每条厌恶关系代表两个骑士互相讨厌对方\n// 你可以任选骑士参加圆桌会议，但是厌恶关系的骑士无法在圆桌中相邻\n// 圆桌会议的骑士数量必须是大于1的奇数，以防止赞同票和反对票一样多\n// 也许有的骑士，不管怎么安排都无法参加圆桌会议，打印这个数量\n// 1 <= n <= 10^3\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/SP2878\n// 测试链接 : https://www.spoj.com/problems/KNIGHTS/\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_RoundTable1 {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m;\n\tpublic static boolean[][] hate = new boolean[MAXN][MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] vbccArr = new int[MAXN << 1];\n\tpublic static int[] vbccl = new int[MAXN];\n\tpublic static int[] vbccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int vbccCnt;\n\n\tpublic static boolean[] curVbcc = new boolean[MAXN];\n\tpublic static int[] color = new int[MAXN];\n\tpublic static boolean[] ok = new boolean[MAXN];\n\n\tpublic static void prepare() {\n\t\tcntg = cntd = top = idx = vbccCnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = 0;\n\t\t\tok[i] = false;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\thate[i][j] = false;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tvbccCnt++;\n\t\t\t\t\tvbccArr[++idx] = u;\n\t\t\t\t\tvbccl[vbccCnt] = idx;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tvbccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t\tvbccr[vbccCnt] = idx;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// u表示当前节点，c表示当前分配给u节点的颜色，只有1和2两种颜色\n\t// 返回是否发现了节点数量为奇数的环\n\tpublic static boolean oddLoop(int u, int c) {\n\t\tcolor[u] = c;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (curVbcc[v]) {\n\t\t\t\tif (color[v] == c) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tif (color[v] == 0 && oddLoop(v, c == 1 ? 2 : 1)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= vbccCnt; i++) {\n\t\t\tfor (int j = vbccl[i]; j <= vbccr[i]; j++) {\n\t\t\t\tcurVbcc[vbccArr[j]] = true;\n\t\t\t\tcolor[vbccArr[j]] = 0;\n\t\t\t}\n\t\t\tboolean check = oddLoop(vbccArr[vbccl[i]], 1);\n\t\t\tfor (int j = vbccl[i]; j <= vbccr[i]; j++) {\n\t\t\t\tcurVbcc[vbccArr[j]] = false;\n\t\t\t\tok[vbccArr[j]] |= check;\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (!ok[i]) {\n\t\t\t\tans++;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\twhile (n != 0 || m != 0) {\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\thate[u][v] = true;\n\t\t\t\thate[v][u] = true;\n\t\t\t}\n\t\t\tfor (int u = 1; u <= n; u++) {\n\t\t\t\tfor (int v = u + 1; v <= n; v++) {\n\t\t\t\t\tif (!hate[u][v]) {\n\t\t\t\t\t\taddEdge(u, v);\n\t\t\t\t\t\taddEdge(v, u);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\ttarjan(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\tint ans = compute();\n\t\t\tout.println(ans);\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code08_RoundTable1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
