];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXM];\n\n\tpublic static void build(int n) {\n\t\tArrays.fill(num, 1, n + 1, 0);\n\t\ttcnt = qcnt = 1;\n\t\tArrays.fill(headEdge, 1, n + 1, 0);\n\t\tArrays.fill(headQuery, 1, n + 1, 0);\n\t\tArrays.fill(visited, 1, n + 1, false);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tunionfind[i] = i;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tedgeNext[tcnt] = headEdge[u];\n\t\tedgeTo[tcnt] = v;\n\t\theadEdge[u] = tcnt++;\n\t}\n\n\tpublic static void addQuery(int u, int v, int i) {\n\t\tqueryNext[qcnt] = headQuery[u];\n\t\tqueryTo[qcnt] = v;\n\t\tqueryIndex[qcnt] = i;\n\t\theadQuery[u] = qcnt++;\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != unionfind[i]) {\n\t\t\tunionfind[i] = find(unionfind[i]);\n\t\t}\n\t\treturn unionfind[i];\n\t}\n\n\tpublic static void tarjan(int u, int f) {\n\t\tvisited[u] = true;\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\ttarjan(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = headQuery[u], v; e != 0; e = queryNext[e]) {\n\t\t\tv = queryTo[e];\n\t\t\tif (visited[v]) {\n\t\t\t\tans[queryIndex[e]] = find(v);\n\t\t\t}\n\t\t}\n\t\tunionfind[u] = f;\n\t\tfather[u] = f;\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\tnum[u] += num[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int no, yes;\n\n\tpublic static void dp(int u, int f) {\n\t\tint n = price[u] * num[u];\n\t\tint y = (price[u] / 2) * num[u];\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp(v, u);\n\t\t\t\tn += Math.min(no, yes);\n\t\t\t\ty += no;\n\t\t\t}\n\t\t}\n\t\tno = n;\n\t\tyes = y;\n\t}\n\n}	模板：Code03_MinimizePriceOfTrips2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
