46552955-05c9-4d38-b353-4ffd06bca6ec	ca7d6569-a723-4f88-adac-5ccd93a14b7e	java	package class187;\n\n// 可持久化边分树，java版\n// 树上有n个节点，给定n-1条边，每条边有边权\n// 给定长度为n的数组arr，代表点编号组成的一个排列\n// 接下来有q条操作，每条操作是如下两种类型中的一种\n// 操作 1 x y z : 打印arr[x..y]中每个节点到节点z的简单路径距离之和\n// 操作 2 x     : 交换arr[x]和arr[x+1]的值，输入保证 1 <= x < n\n// 1 <= n、q <= 2 * 10^5\n// 本题要求强制在线，得到操作参数的规则，打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/CF757G\n// 测试链接 : https://codeforces.com/problemset/problem/757/G\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_PersistentEdgeDecompositionTree1 {\n\n\tpublic static int MAXN = 400001;\n\tpublic static int MAXT = MAXN * 30;\n\tpublic static int n, q, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int[] weight1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN << 1];\n\tpublic static int[] to2 = new int[MAXN << 1];\n\tpublic static int[] weight2 = new int[MAXN << 1];\n\tpublic static int cnt2;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] lcnt = new int[MAXT];\n\tpublic static int[] rcnt = new int[MAXT];\n\tpublic static long[] lsum = new long[MAXT];\n\tpublic static long[] rsum = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] pre = new int[MAXN];\n\n\tpublic static void addEdge1(int u, int v, int w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, int w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void rebuild(int u, int fa) {\n\t\tint last = 0;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tint w = weight1[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (last == 0) {\n\t\t\t\t\tlast = u;\n\t\t\t\t\taddEdge2(u, v, w);\n\t\t\t\t\taddEdge2(v, u, w);\n\t\t\t\t} else {\n\t\t\t\t\tint add = ++cntn;\n\t\t\t\t\taddEdge2(last, add, 0);\n\t\t\t\t\taddEdge2(add, last, 0);\n\t\t\t\t\taddEdge2(add, v, w);\n\t\t\t\t\taddEdge2(v, add, w);\n\t\t\t\t\tlast = add;\n\t\t\t\t}\n\t\t\t\trebuild(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroidEdge(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint total = siz[u];\n\t\tint half = total >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\t\tint v = to2[e];\n\t\t\t\tif (v != fa && !vis[e >> 1] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint best = 0, edge = 0;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tif (!vis[e >> 1]) {\n\t\t\t\tint v = to2[e];\n\t\t\t\tint sub = v == fa ? (total - siz[u]) : siz[v];\n\t\t\t\tif (sub > best) {\n\t\t\t\t\tbest = sub;\n\t\t\t\t\tedge = e;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static void dfs(int u, int fa, long dist, int op) {\n\t\tif (u <= n) {\n\t\t\tif (up[u] == 0) {\n\t\t\t\tup[u] = ++cntt;\n\t\t\t\troot[u] = cntt;\n\t\t\t}\n\t\t\tint cur = up[u];\n\t\t\tint nxt = ++cntt;\n\t\t\tif (op == 0) {\n\t\t\t\tls[cur] = nxt;\n\t\t\t\tlsum[cur] = dist;\n\t\t\t\tlcnt[cur] = 1;\n\t\t\t} else {\n\t\t\t\trs[cur] = nxt;\n\t\t\t\trsum[cur] = dist;\n\t\t\t\trcnt[cur] = 1;\n\t\t\t}\n\t\t\tup[u] = nxt;\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tdfs(v, u, dist + weight2[e], op);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tint edge = getCentroidEdge(u, 0);\n\t\tif (edge > 0) {\n\t\t\tvis[edge >> 1] = true;\n\t\t\tint v1 = to2[edge];\n\t\t\tint v2 = to2[edge ^ 1];\n\t\t\tdfs(v1, 0, 0, 0);\n\t\t\tdfs(v2, 0, weight2[edge], 1);\n\t\t\tsolve(v1);\n\t\t\tsolve(v2);\n\t\t}\n\t}\n\n\tpublic static int add(int p, int i) {\n\t\tif (p == 0 || i == 0) {\n\t\t\treturn p + i;\n\t\t}\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[p];\n\t\trs[rt] = rs[p];\n\t\tlcnt[rt] = lcnt[p] + lcnt[i];\n\t\trcnt[rt] = rcnt[p] + rcnt[i];\n\t\tlsum[rt] = lsum[p] + lsum[i];\n\t\trsum[rt] = rsum[p] + rsum[i];\n\t\tif (ls[i] > 0) {\n\t\t\tls[rt] = add(ls[rt], ls[i]);\n\t\t} else {\n\t\t\trs[rt] = add(rs[rt], rs[i]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static long query(int p1, int p2, int i) {\n\t\tif (ls[i] == 0 && rs[i] == 0) {\n\t\t\treturn 0;\n\t\t} else if (ls[i] > 0) {\n\t\t\treturn query(ls[p1], ls[p2], ls[i]) + rsum[p2] - rsum[p1] + lsum[i] * (rcnt[p2] - rcnt[p1]);\n\t\t} else {\n\t\t\treturn query(rs[p1], rs[p2], rs[i]) + lsum[p2] - lsum[p1] + rsum[i] * (lcnt[p2] - lcnt[p1]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge1(u, v, w);\n\t\t\taddEdge1(v, u, w);\n\t\t}\n\t\tcntn = n;\n\t\tcnt2 = 1;\n\t\trebuild(1, 0);\n\t\tsolve(1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tpre[i] = add(pre[i - 1], root[arr[i]]);\n\t\t}\n\t\tlong mask = (1L << 30) - 1;\n\t\tlong lastAns = 0;\n\t\tlong a, b, c;\n\t\tint op, x, y, z, tmp;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\ta ^= lastAns;\n\t\t\t\tb ^= lastAns;\n\t\t\t\tc ^= lastAns;\n\t\t\t\tx = (int) a;\n\t\t\t\ty = (int) b;\n\t\t\t\tz = (int) c;\n\t\t\t\tlastAns = query(pre[x - 1], pre[y], root[z]);\n\t\t\t\tout.println(lastAns);\n\t\t\t\tlastAns &= mask;\n\t\t\t} else {\n\t\t\t\ta = in.nextInt();\n\t\t\t\ta ^= lastAns;\n\t\t\t\tx = (int) a;\n\t\t\t\ttmp = arr[x];\n\t\t\t\tarr[x] = arr[x + 1];\n\t\t\t\tarr[x + 1] = tmp;\n\t\t\t\tpre[x] = add(pre[x - 1], root[arr[x]]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_PersistentEdgeDecompositionTree1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
