c396e2be-05d4-4b60-8f9a-62fc709039d3	ca7d6569-a723-4f88-adac-5ccd93a14b7e	java	package class187;\n\n// 暴力写挂，java版\n// 两棵树t1、t2都有n个节点，都以1号节点作为树头\n// 各自给定n-1条边，以及每条边的边权，边权可能为负数\n// 在t1中，点x到树头的距离记为dis1(x)，在t2中，该距离记为dis2(x)\n// 点x和点y在t1中的LCA记为lca1(x, y)，在t2中的LCA记为lca2(x, y)\n// 点对(x, y)的指标 = dis1(x) + dis1(y) - dis1(lca1(x, y)) - dis2(lca2(x, y))\n// 点对(x, y)，要求x <= y，打印这个指标的最大值\n// 1 <= n <= 366666\n// 测试链接 : https://www.luogu.com.cn/problem/P4565\n// 测试链接 : https://loj.ac/p/2553\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是需要把太多递归函数改成迭代才能通过，索性不改了\n// 想通过用C++实现，本节课Code04_ViolentWriting2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_ViolentWriting1 {\n\n\tpublic static int MAXN = 366667;\n\tpublic static int MAXM = MAXN << 1;\n\tpublic static int MAXT = 10000001;\n\tpublic static long INF = 1L << 50;\n\tpublic static int n, cntn;\n\n\tpublic static int[] head0 = new int[MAXN];\n\tpublic static int[] next0 = new int[MAXN << 1];\n\tpublic static int[] to0 = new int[MAXN << 1];\n\tpublic static int[] weight0 = new int[MAXN << 1];\n\tpublic static int cnt0;\n\n\tpublic static int[] head1 = new int[MAXM];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int[] weight1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN << 1];\n\tpublic static int[] to2 = new int[MAXN << 1];\n\tpublic static int[] weight2 = new int[MAXN << 1];\n\tpublic static int cnt2;\n\n\tpublic static long[] dis1 = new long[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXM];\n\tpublic static int[] siz = new int[MAXM];\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static long[] lmax = new long[MAXT];\n\tpublic static long[] rmax = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static long ans;\n\n\tpublic static void addEdge0(int u, int v, int w) {\n\t\tnext0[++cnt0] = head0[u];\n\t\tto0[cnt0] = v;\n\t\tweight0[cnt0] = w;\n\t\thead0[u] = cnt0;\n\t}\n\n\tpublic static void addEdge1(int u, int v, int w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, int w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void getDist(int u, int fa, long dist1) {\n\t\tdis1[u] = dist1;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tgetDist(v, u, dist1 + weight0[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rebuild(int u, int fa) {\n\t\tint last = 0;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tint w = weight0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (last == 0) {\n\t\t\t\t\tlast = u;\n\t\t\t\t\taddEdge1(u, v, w);\n\t\t\t\t\taddEdge1(v, u, w);\n\t\t\t\t} else {\n\t\t\t\t\tint add = ++cntn;\n\t\t\t\t\taddEdge1(last, add, 0);\n\t\t\t\t\taddEdge1(add, last, 0);\n\t\t\t\t\taddEdge1(add, v, w);\n\t\t\t\t\taddEdge1(v, add, w);\n\t\t\t\t\tlast = add;\n\t\t\t\t}\n\t\t\t\trebuild(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroidEdge(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint total = siz[u];\n\t\tint half = total >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tif (v != fa && !vis[e >> 1] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint best = 0, edge = 0;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif (!vis[e >> 1]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tint sub = v == fa ? (total - siz[u]) : siz[v];\n\t\t\t\tif (sub > best) {\n\t\t\t\t\tbest = sub;\n\t\t\t\t\tedge = e;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static void dfs(int u, int fa, long path, int op) {\n\t\tif (u <= n) {\n\t\t\tif (up[u] == 0) {\n\t\t\t\tup[u] = ++cntt;\n\t\t\t\troot[u] = cntt;\n\t\t\t}\n\t\t\tint cur = up[u];\n\t\t\tint nxt = ++cntt;\n\t\t\tif (op == 0) {\n\t\t\t\tls[cur] = nxt;\n\t\t\t\tlmax[cur] = dis1[u] + path;\n\t\t\t} else {\n\t\t\t\trs[cur] = nxt;\n\t\t\t\trmax[cur] = dis1[u] + path;\n\t\t\t}\n\t\t\tup[u] = nxt;\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tdfs(v, u, path + weight1[e], op);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tint edge = getCentroidEdge(u, 0);\n\t\tif (edge > 0) {\n\t\t\tvis[edge >> 1] = true;\n\t\t\tint v1 = to1[edge];\n\t\t\tint v2 = to1[edge ^ 1];\n\t\t\tdfs(v1, 0, 0, 0);\n\t\t\tdfs(v2, 0, weight1[edge], 1);\n\t\t\tsolve(v1);\n\t\t\tsolve(v2);\n\t\t}\n\t}\n\n\tpublic static int mergeTree(int x, int y, long add) {\n\t\tif (x == 0 || y == 0) {\n\t\t\treturn x + y;\n\t\t}\n\t\tans = Math.max(ans, Math.max(lmax[x] + rmax[y], lmax[y] + rmax[x]) + add);\n\t\tlmax[x] = Math.max(lmax[x], lmax[y]);\n\t\trmax[x] = Math.max(rmax[x], rmax[y]);\n\t\tls[x] = mergeTree(ls[x], ls[y], add);\n\t\trs[x] = mergeTree(rs[x], rs[y], add);\n\t\treturn x;\n\t}\n\n\tpublic static void compute(int u, int fa, long dist2) {\n\t\tans = Math.max(ans, (dis1[u] - dist2) * 2);\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcompute(v, u, dist2 + weight2[e]);\n\t\t\t\troot[u] = mergeTree(root[u], root[v], -dist2 * 2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge0(u, v, w);\n\t\t\taddEdge0(v, u, w);\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge2(u, v, w);\n\t\t\taddEdge2(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < MAXT; i++) {\n\t\t\tlmax[i] = rmax[i] = -INF;\n\t\t}\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tans = -INF;\n\t\tgetDist(1, 0, 0);\n\t\trebuild(1, 0);\n\t\tsolve(1);\n\t\tcompute(1, 0, 0);\n\t\tout.println(ans >> 1);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code04_ViolentWriting1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2f4a2bd5-3776-43ea-9b2a-bd37b5cbf05e	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class122;\n\n// 边差分实战\n// 使图不连通的方法数\n// 有n个节点，给定n-1条老边使其连接成一棵树，再给定m条新边额外加在树上\n// 你可以切断两条边让这个图不连通，切断的两条边必须是一条老边和一条新边\n// 返回方法数\n// 测试链接 : http://poj.org/problem?id=3417\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_Network {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int LIMIT = 17;\n\n\tpublic static int power;\n\n\tpublic static int log2(int n) {\n\t\tint ans = 0;\n\t\twhile ((1 << ans) <= (n >> 1)) {\n\t\t\tans++;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] deep = new int[MAXN];\n\n\tpublic static int[][] stjump = new int[MAXN][LIMIT];\n\n\tpublic static int ans;\n\n\tpublic static void build() {\n\t\tpower = log2(n);\n\t\tArrays.fill(num, 1, n + 1, 0);\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tans = 0;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tdeep[u] = deep[f] + 1;\n\t\tstjump[u][0] = f;\n\t\tfor (int p = 1; p <= power; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs1(to[e], u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (deep[a] < deep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (deep[stjump[a][p]] >= deep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs2(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v, w; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tw = 0 + num[v];\n\t\t\t\tif (w == 0) {\n\t\t\t\t\tans += m;\n\t\t\t\t} else if (w == 1) {\n\t\t\t\t\tans += 1;\n\t\t\t\t} else {\n\t\t\t\t\tans += 0;\n\t\t\t\t}\n\t\t\t\tnum[u] += num[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tfor (int i = 1, u, v, lca; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tlca = lca(u, v);\n\t\t\tnum[u]++;\n\t\t\tnum[v]++;\n\t\t\tnum[lca] -= 2;\n\t\t}\n\t\tdfs2(1, 0);\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_Network.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
76f442c3-05ef-474d-9384-b10a0faa7741	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class122;\n\n// 运输计划，java递归版\n// 有n个节点，给定n-1条边使其连接成一棵树，每条边有正数边权\n// 给定很多运输计划，每个运输计划(a,b)表示从a去往b\n// 每个运输计划的代价就是沿途边权和，运输计划之间完全互不干扰\n// 你只能选择一条边，将其边权变成0\n// 你的目的是让所有运输计划代价的最大值尽量小\n// 返回所有运输计划代价的最大值最小能是多少\n// 测试链接 : https://www.luogu.com.cn/problem/P2680\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// 本节课Code05_TransportPlan3文件就是C++的实现\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_TransportPlan1 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int MAXM = 300001;\n\n\tpublic static int n;\n\n\tpublic static int m;\n\n\t// num[i] : i节点和其父节点的边，有多少代价>=limit的运输计划用到\n\tpublic static int[] num = new int[MAXN];\n\n\t// 链式前向星建图需要\n\tpublic static int[] headEdge = new int[MAXN];\n\n\tpublic static int[] edgeNext = new int[MAXN << 1];\n\n\tpublic static int[] edgeTo = new int[MAXN << 1];\n\n\tpublic static int[] edgeWeight = new int[MAXN << 1];\n\n\tpublic static int tcnt;\n\n\t// tarjan算法需要\n\tpublic static int[] headQuery = new int[MAXN];\n\n\tpublic static int[] queryNext = new int[MAXM << 1];\n\n\tpublic static int[] queryTo = new int[MAXM << 1];\n\n\tpublic static int[] queryIndex = new int[MAXM << 1];\n\n\tpublic static int qcnt;\n\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\tpublic static int[] unionfind = new int[MAXN];\n\n\tpublic static int[] quesu = new int[MAXM];\n\n\tpublic static int[] quesv = new int[MAXM];\n\n\t// distance[i] : 头节点到i号点的距离，tarjan算法过程中更新\n\tpublic static int[] distance = new int[MAXN];\n\n\t// lca[i] : 第i号运输计划的两端点lca，tarjan算法过程中更新\n\tpublic static int[] lca = new int[MAXM];\n\n\t// cost[i] : 第i号运输计划代价是多少，tarjan算法过程中更新\n\tpublic static int[] cost = new int[MAXM];\n\n\t// 所有运输计划的最大代价，tarjan算法过程中更新\n\tpublic static int maxCost;\n\n\tpublic static void build() {\n\t\ttcnt = qcnt = 1;\n\t\tArrays.fill(headEdge, 1, n + 1, 0);\n\t\tArrays.fill(headQuery, 1, n + 1, 0);\n\t\tArrays.fill(visited, 1, n + 1, false);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tunionfind[i] = i;\n\t\t}\n\t\tmaxCost = 0;\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tedgeNext[tcnt] = headEdge[u];\n\t\tedgeTo[tcnt] = v;\n\t\tedgeWeight[tcnt] = w;\n\t\theadEdge[u] = tcnt++;\n\t}\n\n\tpublic static void addQuery(int u, int v, int i) {\n\t\tqueryNext[qcnt] = headQuery[u];\n\t\tqueryTo[qcnt] = v;\n\t\tqueryIndex[qcnt] = i;\n\t\theadQuery[u] = qcnt++;\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != unionfind[i]) {\n\t\t\tunionfind[i] = find(unionfind[i]);\n\t\t}\n\t\treturn unionfind[i];\n\t}\n\n\tpublic static void tarjan(int u, int f, int w) {\n\t\tvisited[u] = true;\n\t\tdistance[u] = distance[f] + w;\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\ttarjan(v, u, edgeWeight[e]);\n\t\t\t}\n\t\t}\n\t\tfor (int e = headQuery[u], v, i; e != 0; e = queryNext[e]) {\n\t\t\tv = queryTo[e];\n\t\t\tif (visited[v]) {\n\t\t\t\ti = queryIndex[e];\n\t\t\t\tlca[i] = find(v);\n\t\t\t\tcost[i] = distance[u] + distance[v] - 2 * distance[lca[i]];\n\t\t\t\tmaxCost = Math.max(maxCost, cost[i]);\n\t\t\t}\n\t\t}\n\t\tunionfind[u] = f;\n\t}\n\n\t// 只能把一条边的权值变成0\n\t// 还要求每个运输计划的代价都要<=limit\n\t// 返回能不能做到\n\tpublic static boolean f(int limit) {\n\t\tatLeast = maxCost - limit;\n\t\tArrays.fill(num, 1, n + 1, 0);\n\t\tbeyond = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (cost[i] > limit) {\n\t\t\t\tnum[quesu[i]]++;\n\t\t\t\tnum[quesv[i]]++;\n\t\t\t\tnum[lca[i]] -= 2;\n\t\t\t\tbeyond++;\n\t\t\t}\n\t\t}\n\t\treturn beyond == 0 || dfs(1, 0, 0);\n\t}\n\n\t// 至少要减少多少边权\n\tpublic static int atLeast;\n\n\t// 超过要求的运输计划有几个\n\tpublic static int beyond;\n\n\tpublic static boolean dfs(int u, int f, int w) {\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\tif (dfs(v, u, edgeWeight[e])) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\tnum[u] += num[v];\n\t\t\t}\n\t\t}\n\t\treturn num[u] == beyond && w >= atLeast;\n\t}\n\n\tpublic static int compute() {\n\t\ttarjan(1, 0, 0);\n\t\tint l = 0, r = maxCost, mid;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) / 2;\n\t\t\tif (f(mid)) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tquesu[i] = u;\n\t\t\tquesv[i] = v;\n\t\t\taddQuery(u, v, i);\n\t\t\taddQuery(v, u, i);\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code05_TransportPlan1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
96540fa1-7d64-4d0f-82ca-3dffa00d9437	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class122;\n\n// 运输计划，java迭代版\n// 有n个节点，给定n-1条边使其连接成一棵树，每条边有正数边权\n// 给定很多运输计划，每个运输计划(a,b)表示从a去往b\n// 每个运输计划的代价就是沿途边权和，运输计划之间完全互不干扰\n// 你只能选择一条边，将其边权变成0\n// 你的目的是让所有运输计划代价的最大值尽量小\n// 返回所有运输计划代价的最大值最小能是多少\n// 测试链接 : https://www.luogu.com.cn/problem/P2680\n// 提交以下的code，提交时请把类名改成"Main"\n// 有时候可以完全通过，有时候会有一个测试用例超时\n// 因为这道题根据C++的运行时间，制定通过标准，根本没考虑java的用户\n// 本节课Code05_TransportPlan3文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_TransportPlan2 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int MAXM = 300001;\n\n\tpublic static int n;\n\n\tpublic static int m;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] headEdge = new int[MAXN];\n\n\tpublic static int[] edgeNext = new int[MAXN << 1];\n\n\tpublic static int[] edgeTo = new int[MAXN << 1];\n\n\tpublic static int[] edgeWeight = new int[MAXN << 1];\n\n\tpublic static int tcnt;\n\n\tpublic static int[] headQuery = new int[MAXN];\n\n\tpublic static int[] queryNext = new int[MAXM << 1];\n\n\tpublic static int[] queryTo = new int[MAXM << 1];\n\n\tpublic static int[] queryIndex = new int[MAXM << 1];\n\n\tpublic static int qcnt;\n\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\tpublic static int[] unionfind = new int[MAXN];\n\n\tpublic static int[] quesu = new int[MAXM];\n\n\tpublic static int[] quesv = new int[MAXM];\n\n\tpublic static int[] distance = new int[MAXN];\n\n\tpublic static int[] lca = new int[MAXM];\n\n\tpublic static int[] cost = new int[MAXM];\n\n\tpublic static int maxCost;\n\n\tpublic static void build() {\n\t\ttcnt = qcnt = 1;\n\t\tArrays.fill(headEdge, 1, n + 1, 0);\n\t\tArrays.fill(headQuery, 1, n + 1, 0);\n\t\tArrays.fill(visited, 1, n + 1, false);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tunionfind[i] = i;\n\t\t}\n\t\tmaxCost = 0;\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tedgeNext[tcnt] = headEdge[u];\n\t\tedgeTo[tcnt] = v;\n\t\tedgeWeight[tcnt] = w;\n\t\theadEdge[u] = tcnt++;\n\t}\n\n\tpublic static void addQuery(int u, int v, int i) {\n\t\tqueryNext[qcnt] = headQuery[u];\n\t\tqueryTo[qcnt] = v;\n\t\tqueryIndex[qcnt] = i;\n\t\theadQuery[u] = qcnt++;\n\t}\n\n\t// find方法的递归版改迭代版\n\tpublic static int[] stack = new int[MAXN];\n\n\tpublic static int find(int i) {\n\t\tint size = 0;\n\t\twhile (i != unionfind[i]) {\n\t\t\tstack[size++] = i;\n\t\t\ti = unionfind[i];\n\t\t}\n\t\twhile (size > 0) {\n\t\t\tunionfind[stack[--size]] = i;\n\t\t}\n\t\treturn i;\n\t}\n\n\t// tarjan方法的递归版改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static int[][] ufwe = new int[MAXN][4];\n\n\tpublic static int stackSize, u, f, w, e;\n\n\tpublic static void push(int u, int f, int w, int e) {\n\t\tufwe[stackSize][0] = u;\n\t\tufwe[stackSize][1] = f;\n\t\tufwe[stackSize][2] = w;\n\t\tufwe[stackSize][3] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufwe[stackSize][0];\n\t\tf = ufwe[stackSize][1];\n\t\tw = ufwe[stackSize][2];\n\t\te = ufwe[stackSize][3];\n\t}\n\n\tpublic static void tarjan(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tvisited[u] = true;\n\t\t\t\tdistance[u] = distance[f] + w;\n\t\t\t\te = headEdge[u];\n\t\t\t} else {\n\t\t\t\te = edgeNext[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, w, e);\n\t\t\t\tif (edgeTo[e] != f) {\n\t\t\t\t\tpush(edgeTo[e], u, edgeWeight[e], -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int q = headQuery[u], v, i; q != 0; q = queryNext[q]) {\n\t\t\t\t\tv = queryTo[q];\n\t\t\t\t\tif (visited[v]) {\n\t\t\t\t\t\ti = queryIndex[q];\n\t\t\t\t\t\tlca[i] = find(v);\n\t\t\t\t\t\tcost[i] = distance[u] + distance[v] - 2 * distance[lca[i]];\n\t\t\t\t\t\tmaxCost = Math.max(maxCost, cost[i]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tunionfind[u] = f;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean f(int limit) {\n\t\tatLeast = maxCost - limit;\n\t\tArrays.fill(num, 1, n + 1, 0);\n\t\tbeyond = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (cost[i] > limit) {\n\t\t\t\tnum[quesu[i]]++;\n\t\t\t\tnum[quesv[i]]++;\n\t\t\t\tnum[lca[i]] -= 2;\n\t\t\t\tbeyond++;\n\t\t\t}\n\t\t}\n\t\treturn beyond == 0 || dfs(1);\n\t}\n\n\t// 至少要减少多少边权\n\tpublic static int atLeast;\n\n\t// 超过要求的运输计划有几个\n\tpublic static int beyond;\n\n\t// dfs方法的递归版改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static boolean dfs(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = headEdge[u];\n\t\t\t} else {\n\t\t\t\te = edgeNext[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, w, e);\n\t\t\t\tif (edgeTo[e] != f) {\n\t\t\t\t\tpush(edgeTo[e], u, edgeWeight[e], -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\t\t\tv = edgeTo[e];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tnum[u] += num[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (num[u] == beyond && w >= atLeast) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static int compute() {\n\t\ttarjan(1);\n\t\tint l = 0, r = maxCost, mid;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) / 2;\n\t\t\tif (f(mid)) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastIO in = new FastIO();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out), false);\n\t\tn = in.nextInt();\n\t\tbuild();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tquesu[i] = u;\n\t\t\tquesv[i] = v;\n\t\t\taddQuery(u, v, i);\n\t\t\taddQuery(v, u, i);\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// IO工具类\n\tstatic class FastIO {\n\t\tprivate final int SIZE = 1 << 20;\n\t\tprivate byte[] buf;\n\t\tprivate int pos;\n\t\tprivate int count;\n\t\tprivate InputStream is;\n\n\t\tpublic FastIO() {\n\t\t\tbuf = new byte[SIZE];\n\t\t\tpos = 0;\n\t\t\tcount = 0;\n\t\t\tis = System.in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (count == -1) {\n\t\t\t\treturn -1;\n\t\t\t}\n\t\t\tif (pos >= count) {\n\t\t\t\tpos = 0;\n\t\t\t\tcount = is.read(buf);\n\t\t\t\tif (count == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn buf[pos++] & 0xff;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint c, value = 0;\n\t\t\tboolean neg = false;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t} while (c <= ' ');\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tfor (; c >= '0' && c <= '9'; c = readByte()) {\n\t\t\t\tvalue = value * 10 + (c - '0');\n\t\t\t}\n\t\t\treturn neg ? -value : value;\n\t\t}\n\t}\n\n}\n	模板：Code05_TransportPlan2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
