32712901-485d-42a7-ab3c-cd2a9e181a6d	ca7d6569-a723-4f88-adac-5ccd93a14b7e	java	package class187;\n\n// 通道，java版\n// 三棵树t1、t2、t3都有n个节点，各自给定n-1条边以及每条边的边权，边权没有负数\n// 点对(x, y)，要求两点必须不同，两点在树上的距离就是简单路径上边权的累加和\n// 点对(x, y)，在t1、t2、t3的距离，分别记为dis1(x, y)、dis2(x, y)、dis3(x, y)\n// 打印最大的dis1(x, y) + dis2(x, y) + dis3(x, y)\n// 2 <= n <= 10^5\n// 0 <= 边权 <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P4220\n// 测试链接 : https://loj.ac/p/2339\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是需要把太多递归函数改成迭代才能通过，索性不改了\n// 想通过用C++实现，本节课Code05_Passage2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Passage1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = MAXN << 1;\n\tpublic static int MAXP = 20;\n\tpublic static int MAXT = MAXN * 20;\n\tpublic static long INF = 1L << 60;\n\tpublic static int n, cntn;\n\n\tpublic static int[] head0 = new int[MAXN];\n\tpublic static int[] next0 = new int[MAXN << 1];\n\tpublic static int[] to0 = new int[MAXN << 1];\n\tpublic static long[] weight0 = new long[MAXN << 1];\n\tpublic static int cnt0;\n\n\tpublic static int[] head1 = new int[MAXM];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static long[] weight1 = new long[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN << 1];\n\tpublic static int[] to2 = new int[MAXN << 1];\n\tpublic static long[] weight2 = new long[MAXN << 1];\n\tpublic static int cnt2;\n\n\tpublic static int[] head3 = new int[MAXN];\n\tpublic static int[] next3 = new int[MAXN << 1];\n\tpublic static int[] to3 = new int[MAXN << 1];\n\tpublic static long[] weight3 = new long[MAXN << 1];\n\tpublic static int cnt3;\n\n\tpublic static long[] dep2 = new long[MAXN];\n\tpublic static long[] dist3 = new long[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXM];\n\tpublic static int[] siz = new int[MAXM];\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] lg2 = new int[MAXN];\n\tpublic static int[][] rmq = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] lx = new int[MAXT];\n\tpublic static int[] ly = new int[MAXT];\n\tpublic static long[] lxv = new long[MAXT];\n\tpublic static long[] lyv = new long[MAXT];\n\tpublic static int[] rx = new int[MAXT];\n\tpublic static int[] ry = new int[MAXT];\n\tpublic static long[] rxv = new long[MAXT];\n\tpublic static long[] ryv = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static long ans;\n\n\tpublic static void addEdge0(int u, int v, long w) {\n\t\tnext0[++cnt0] = head0[u];\n\t\tto0[cnt0] = v;\n\t\tweight0[cnt0] = w;\n\t\thead0[u] = cnt0;\n\t}\n\n\tpublic static void addEdge1(int u, int v, long w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, long w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addEdge3(int u, int v, long w) {\n\t\tnext3[++cnt3] = head3[u];\n\t\tto3[cnt3] = v;\n\t\tweight3[cnt3] = w;\n\t\thead3[u] = cnt3;\n\t}\n\n\tpublic static void dfsTree2(int u, int fa, long dep) {\n\t\tdep2[u] = dep;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsTree2(v, u, dep + weight2[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rebuildTree1(int u, int fa) {\n\t\tint last = 0;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tlong w = weight0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (last == 0) {\n\t\t\t\t\tlast = u;\n\t\t\t\t\taddEdge1(u, v, w);\n\t\t\t\t\taddEdge1(v, u, w);\n\t\t\t\t} else {\n\t\t\t\t\tint add = ++cntn;\n\t\t\t\t\taddEdge1(last, add, 0);\n\t\t\t\t\taddEdge1(add, last, 0);\n\t\t\t\t\taddEdge1(add, v, w);\n\t\t\t\t\taddEdge1(v, add, w);\n\t\t\t\t\tlast = add;\n\t\t\t\t}\n\t\t\t\trebuildTree1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroidEdge(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint total = siz[u];\n\t\tint half = total >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tif (v != fa && !vis[e >> 1] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint best = 0, edge = 0;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif (!vis[e >> 1]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tint sub = v == fa ? (total - siz[u]) : siz[v];\n\t\t\t\tif (sub > best) {\n\t\t\t\t\tbest = sub;\n\t\t\t\t\tedge = e;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static void dfsTree1(int u, int fa, long path, int op) {\n\t\tif (u <= n) {\n\t\t\tif (up[u] == 0) {\n\t\t\t\tup[u] = ++cntt;\n\t\t\t\troot[u] = cntt;\n\t\t\t}\n\t\t\tint cur = up[u];\n\t\t\tint nxt = ++cntt;\n\t\t\tlong val = path + dep2[u];\n\t\t\tif (op == 0) {\n\t\t\t\tls[cur] = nxt;\n\t\t\t\tlx[cur] = ly[cur] = u;\n\t\t\t\tlxv[cur] = lyv[cur] = val;\n\t\t\t} else {\n\t\t\t\trs[cur] = nxt;\n\t\t\t\trx[cur] = ry[cur] = u;\n\t\t\t\trxv[cur] = ryv[cur] = val;\n\t\t\t}\n\t\t\tup[u] = nxt;\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tdfsTree1(v, u, path + weight1[e], op);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solveTree1(int u) {\n\t\tint edge = getCentroidEdge(u, 0);\n\t\tif (edge > 0) {\n\t\t\tvis[edge >> 1] = true;\n\t\t\tint v1 = to1[edge];\n\t\t\tint v2 = to1[edge ^ 1];\n\t\t\tdfsTree1(v1, 0, 0, 0);\n\t\t\tdfsTree1(v2, 0, weight1[edge], 1);\n\t\t\tsolveTree1(v1);\n\t\t\tsolveTree1(v2);\n\t\t}\n\t}\n\n\tpublic static int getUp(int x, int y) {\n\t\treturn dfn[x] < dfn[y] ? x : y;\n\t}\n\n\tpublic static void dfsTree3(int u, int fa, long dist) {\n\t\tdfn[u] = ++cntd;\n\t\trmq[dfn[u]][0] = fa;\n\t\tdist3[u] = dist;\n\t\tfor (int e = head3[u]; e > 0; e = next3[e]) {\n\t\t\tint v = to3[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsTree3(v, u, dist + weight3[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rmqTree3() {\n\t\tdfsTree3(1, 0, 0);\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tlg2[i] = lg2[i >> 1] + 1;\n\t\t}\n\t\tfor (int pre = 0, cur = 1; cur <= lg2[n]; pre++, cur++) {\n\t\t\tfor (int i = 1; i + (1 << cur) - 1 <= n; i++) {\n\t\t\t\trmq[i][cur] = getUp(rmq[i][pre], rmq[i + (1 << pre)][pre]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lcaTree3(int x, int y) {\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tx = dfn[x];\n\t\ty = dfn[y];\n\t\tif (x > y) {\n\t\t\tint tmp = x; x = y; y = tmp;\n\t\t}\n\t\tx++;\n\t\tint k = lg2[y - x + 1];\n\t\treturn getUp(rmq[x][k], rmq[y - (1 << k) + 1][k]);\n\t}\n\n\tpublic static long getDist3(int x, int y) {\n\t\treturn dist3[x] + dist3[y] - dist3[lcaTree3(x, y)] * 2;\n\t}\n\n\tpublic static long getDist(int x, int y, long xv, long yv) {\n\t\tif (x == y) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn getDist3(x, y) + xv + yv;\n\t}\n\n\tpublic static int a, b, c, d;\n\tpublic static long av, bv, cv, dv;\n\n\tpublic static void getInfo(int i, int j, int iop, int jop) {\n\t\tif (iop == 0) {\n\t\t\ta = lx[i]; b = ly[i]; av = lxv[i]; bv = lyv[i];\n\t\t} else {\n\t\t\ta = rx[i]; b = ry[i]; av = rxv[i]; bv = ryv[i];\n\t\t}\n\t\tif (jop == 0) {\n\t\t\tc = lx[j]; d = ly[j]; cv = lxv[j]; dv = lyv[j];\n\t\t} else {\n\t\t\tc = rx[j]; d = ry[j]; cv = rxv[j]; dv = ryv[j];\n\t\t}\n\t}\n\n\tpublic static long bestCross(int i, int j, int iop, int jop) {\n\t\tgetInfo(i, j, iop, jop);\n\t\tlong p1 = getDist(a, c, av, cv);\n\t\tlong p2 = getDist(a, d, av, dv);\n\t\tlong p3 = getDist(b, c, bv, cv);\n\t\tlong p4 = getDist(b, d, bv, dv);\n\t\treturn Math.max(Math.max(p1, p2), Math.max(p3, p4));\n\t}\n\n\tpublic static int x, y;\n\tpublic static long xv, yv;\n\tpublic static long bestDist;\n\n\tpublic static void better(int curx, int cury, long curxv, long curyv) {\n\t\tif (curx == 0 || cury == 0) {\n\t\t\treturn;\n\t\t}\n\t\tlong curDist = getDist(curx, cury, curxv, curyv);\n\t\tif (curDist > bestDist) {\n\t\t\tx = curx; y = cury; xv = curxv; yv = curyv;\n\t\t\tbestDist = curDist;\n\t\t}\n\t}\n\n\tpublic static void mergeInfo(int i, int j, int op) {\n\t\tgetInfo(i, j, op, op);\n\t\tx = y = 0;\n\t\txv = yv = 0;\n\t\tbestDist = -INF;\n\t\tbetter(a, b, av, bv);\n\t\tbetter(c, d, cv, dv);\n\t\tbetter(a, c, av, cv);\n\t\tbetter(a, d, av, dv);\n\t\tbetter(b, c, bv, cv);\n\t\tbetter(b, d, bv, dv);\n\t\tif (op == 0) {\n\t\t\tlx[i] = x; ly[i] = y; lxv[i] = xv; lyv[i] = yv;\n\t\t} else {\n\t\t\trx[i] = x; ry[i] = y; rxv[i] = xv; ryv[i] = yv;\n\t\t}\n\t}\n\n\tpublic static int mergeTree(int i, int j, long add) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tif (ls[i] > 0 && rs[j] > 0) {\n\t\t\tans = Math.max(ans, bestCross(i, j, 0, 1) + add);\n\t\t}\n\t\tif (rs[i] > 0 && ls[j] > 0) {\n\t\t\tans = Math.max(ans, bestCross(i, j, 1, 0) + add);\n\t\t}\n\t\tmergeInfo(i, j, 0);\n\t\tmergeInfo(i, j, 1);\n\t\tls[i] = mergeTree(ls[i], ls[j], add);\n\t\trs[i] = mergeTree(rs[i], rs[j], add);\n\t\treturn i;\n\t}\n\n\tpublic static void compute(int u, int fa) {\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcompute(v, u);\n\t\t\t\troot[u] = mergeTree(root[u], root[v], -dep2[u] * 2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tint u, v;\n\t\tlong w;\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge0(u, v, w);\n\t\t\taddEdge0(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge2(u, v, w);\n\t\t\taddEdge2(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge3(u, v, w);\n\t\t\taddEdge3(v, u, w);\n\t\t}\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tans = -INF;\n\t\tdfsTree2(1, 0, 0);\n\t\trebuildTree1(1, 0);\n\t\tsolveTree1(1);\n\t\trmqTree3();\n\t\tcompute(1, 0);\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code05_Passage1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
23384cd9-7bcf-4735-a2bc-2a279ad001b8	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class142;\n\n// 小k的农场\n// 一共有n个农场，编号1~n，给定m条关系，每条关系是如下三种形式中的一种\n// 关系1 a b c : 表示农场a比农场b至少多种植了c个作物\n// 关系2 a b c : 表示农场a比农场b至多多种植了c个作物\n// 关系3 a b   : 表示农场a和农场b种植了一样多的作物\n// 如果关系之间能推出矛盾，打印"No"，不存在矛盾，打印"Yes"\n// 1 <= n、m <= 5 * 10^3\n// 1 <= c <= 5 * 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P1993\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_KsFarm {\n\n\tpublic static int MAXN = 5001;\n\n\tpublic static int MAXM = 20001;\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// spfa需要\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] update = new int[MAXN];\n\n\tpublic static int MAXQ = 20000001;\n\n\tpublic static int[] queue = new int[MAXQ];\n\n\tpublic static int h, t;\n\n\tpublic static boolean[] enter = new boolean[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\th = t = 0;\n\t\tArrays.fill(head, 0, n + 1, 0);\n\t\tArrays.fill(dist, 0, n + 1, Integer.MAX_VALUE);\n\t\tArrays.fill(update, 0, n + 1, 0);\n\t\tArrays.fill(enter, 0, n + 1, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static boolean spfa(int s) {\n\t\tdist[s] = 0;\n\t\tupdate[s] = 1;\n\t\tqueue[t++] = s;\n\t\tenter[s] = true;\n\t\twhile (h < t) {\n\t\t\tint u = queue[h++];\n\t\t\tenter[u] = false;\n\t\t\tfor (int ei = head[u], v, w; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tw = weight[ei];\n\t\t\t\tif (dist[v] > dist[u] + w) {\n\t\t\t\t\tdist[v] = dist[u] + w;\n\t\t\t\t\tif (!enter[v]) {\n\t\t\t\t\t\tif (++update[v] > n) {\n\t\t\t\t\t\t\treturn true;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tqueue[t++] = v;\n\t\t\t\t\t\tenter[v] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddEdge(0, i, 0);\n\t\t}\n\t\tfor (int i = 1, type, u, v, w; i <= m; i++) {\n\t\t\tin.nextToken(); type = (int) in.nval;\n\t\t\tin.nextToken(); u = (int) in.nval;\n\t\t\tin.nextToken(); v = (int) in.nval;\n\t\t\tif (type == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tw = (int) in.nval;\n\t\t\t\taddEdge(u, v, -w);\n\t\t\t} else if (type == 2) {\n\t\t\t\tin.nextToken();\n\t\t\t\tw = (int) in.nval;\n\t\t\t\taddEdge(v, u, w);\n\t\t\t} else {\n\t\t\t\taddEdge(u, v, 0);\n\t\t\t\taddEdge(v, u, 0);\n\t\t\t}\n\t\t}\n\t\tif (spfa(0)) {\n\t\t\tout.println("No");\n\t\t} else {\n\t\t\tout.println("Yes");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_KsFarm.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fc4c70fc-6347-4bb5-979b-1add7017c71d	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class142;\n\n// 布局奶牛\n// 编号1到编号n的奶牛从左往右站成一排，你可以决定任意相邻奶牛之间的距离\n// 有m1条好友信息，有m2条情敌信息，好友间希望距离更近，情敌间希望距离更远\n// 每条好友信息为 : u v w，表示希望u和v之间的距离 <= w，输入保证u < v\n// 每条情敌信息为 : u v w，表示希望u和v之间的距离 >= w，输入保证u < v\n// 你需要安排奶牛的布局，满足所有的好友信息和情敌信息\n// 如果不存在合法方案，返回-1\n// 如果存在合法方案，返回1号奶牛和n号奶牛之间的最大距离\n// 如果存在合法方案，并且1号奶牛和n号奶牛之间的距离可以无穷远，返回-2\n// 测试链接 : https://www.luogu.com.cn/problem/P4878\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_LayoutCow {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int MAXM = 20001;\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// spfa需要\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] update = new int[MAXN];\n\n\tpublic static int MAXQ = 1000001;\n\n\tpublic static int[] queue = new int[MAXQ];\n\n\tpublic static int h, t;\n\n\tpublic static boolean[] enter = new boolean[MAXN];\n\n\tpublic static int n, m1, m2;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 0, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static int spfa(int s) {\n\t\th = t = 0;\n\t\tArrays.fill(dist, 0, n + 1, Integer.MAX_VALUE);\n\t\tArrays.fill(update, 0, n + 1, 0);\n\t\tArrays.fill(enter, 0, n + 1, false);\n\t\tdist[s] = 0;\n\t\tupdate[s] = 1;\n\t\tqueue[t++] = s;\n\t\tenter[s] = true;\n\t\twhile (h < t) {\n\t\t\tint u = queue[h++];\n\t\t\tenter[u] = false;\n\t\t\tfor (int ei = head[u], v, w; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tw = weight[ei];\n\t\t\t\tif (dist[v] > dist[u] + w) {\n\t\t\t\t\tdist[v] = dist[u] + w;\n\t\t\t\t\tif (!enter[v]) {\n\t\t\t\t\t\tif (++update[v] > n) {\n\t\t\t\t\t\t\treturn -1;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tqueue[t++] = v;\n\t\t\t\t\t\tenter[v] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dist[n] == Integer.MAX_VALUE) {\n\t\t\treturn -2;\n\t\t}\n\t\treturn dist[n];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken(); n = (int) in.nval;\n\t\tin.nextToken(); m1 = (int) in.nval;\n\t\tin.nextToken(); m2 = (int) in.nval;\n\t\tprepare();\n\t\t// 0号点是连通超级源点，保证图的连通性\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddEdge(0, i, 0);\n\t\t}\n\t\t// 好友关系连边\n\t\tfor (int i = 1, u, v, w; i <= m1; i++) {\n\t\t\tin.nextToken(); u = (int) in.nval;\n\t\t\tin.nextToken(); v = (int) in.nval;\n\t\t\tin.nextToken(); w = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t}\n\t\t// 情敌关系连边\n\t\tfor (int i = 1, u, v, w; i <= m2; i++) {\n\t\t\tin.nextToken(); u = (int) in.nval;\n\t\t\tin.nextToken(); v = (int) in.nval;\n\t\t\tin.nextToken(); w = (int) in.nval;\n\t\t\taddEdge(v, u, -w);\n\t\t}\n\t\t// 根据本题的模型，一定要增加如下的边，不然会出错\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\taddEdge(i + 1, i, 0);\n\t\t}\n\t\tint ans = spfa(0);\n\t\tif (ans == -1) {\n\t\t\tout.println(ans);\n\t\t} else {\n\t\t\tans = spfa(1);\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_LayoutCow.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
10ee116c-7c89-46c4-b23f-9e5bd1587a6c	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class142;\n\n// 倍杀测量者\n// 如果 A的分数 >= B的分数 * k，k是正实数，就称 A k倍杀 B，或称 B被A k倍杀了\n// 一场比赛中，一共有n个选手，有m1条誓言记录，有m2条选手得分记录，得分只可能是正实数\n// 类型1的誓言 u v k : 选手u 没有k倍杀 选手v，那么选手u就穿女装\n// 类型2的誓言 u v k : 选手u 被选手v k倍杀了，那么选手u就穿女装\n// 选手的得分    u w : 选手u得了w分，如果某选手没有得分记录，按照尽量不穿女装的情况推测\n// 你希望看到比赛后有人穿女装，但不想看到很多人穿女装，于是想制定正实数ans，效果如下\n// 类型1的誓言，比例调整成(k-ans)，类型2的誓言，比例调整成(k+ans)，即提高了穿女装的条件\n// 计算ans最大多少，依然有人穿女装，保留小数点后4位，如果不干预也没人穿女装，返回-1\n// 1 <= n, m1, m2 <= 1000\n// 1 <= k <= 10\n// 1 <= w <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4926\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_Measurer1 {\n\n\tpublic static int MAXN = 1002;\n\n\tpublic static int MAXM = 3001;\n\n\tpublic static double INF = 1e10;\n\n\tpublic static double sml = 1e-6;\n\n\tpublic static int n, m1, m2;\n\n\t// 誓言记录(誓言类型, u, v, k)\n\tpublic static int[][] vow = new int[MAXN][4];\n\n\t// 得分记录(u, w)\n\tpublic static int[][] score = new int[MAXN][2];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\t// spfa需要\n\tpublic static double[] dist = new double[MAXN];\n\n\tpublic static int[] update = new int[MAXN];\n\n\tpublic static int MAXQ = 1000001;\n\n\tpublic static int[] queue = new int[MAXQ];\n\n\tpublic static int h, t;\n\n\tpublic static boolean[] enter = new boolean[MAXN];\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\th = t = 0;\n\t\tArrays.fill(head, 0, n + 2, 0);\n\t\tArrays.fill(dist, 0, n + 2, INF);\n\t\tArrays.fill(update, 0, n + 2, 0);\n\t\tArrays.fill(enter, 0, n + 2, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static double compute() {\n\t\tdouble l = 0, r = INF, m, ans = 0;\n\t\twhile (r - l >= sml) {\n\t\t\tm = (l + r) / 2;\n\t\t\tif (check(m)) {\n\t\t\t\tans = m;\n\t\t\t\tl = m + sml;\n\t\t\t} else {\n\t\t\t\tr = m - sml;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 是否有人穿女装\n\tpublic static boolean check(double limit) {\n\t\tprepare();\n\t\t// 0号点是连通超级源点，保证图的连通\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddEdge(0, i, 0);\n\t\t}\n\t\t// 倍杀关系的建边\n\t\tfor (int i = 1; i <= m1; i++) {\n\t\t\tif (vow[i][0] == 1) {\n\t\t\t\t// 课上的代码没有这个判断，加上才是正确的，防止log里出现负数\n\t\t\t\tif (-limit + vow[i][3] >= 0) {\n\t\t\t\t\taddEdge(vow[i][1], vow[i][2], -Math.log(-limit + vow[i][3]));\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\t// 因为类型2的誓言是<关系，所以减去最小精度后，就可以认为是<=关系\n\t\t\t\taddEdge(vow[i][1], vow[i][2], Math.log(limit + vow[i][3] - sml));\n\t\t\t}\n\t\t}\n\t\t// n+1号点是限制超级源点，保证确定得分的选手之间的关系\n\t\t// 本题测试数据有限，两个超级源点合并居然也能通过\n\t\t// 原理上两个超级源点一定要分开，课上进行了重点讲解\n\t\tfor (int i = 1; i <= m2; i++) {\n\t\t\taddEdge(n + 1, score[i][0], Math.log(score[i][1]));\n\t\t\taddEdge(score[i][0], n + 1, -Math.log(score[i][1]));\n\t\t}\n\t\treturn spfa(0);\n\t}\n\n\tpublic static boolean spfa(int s) {\n\t\tdist[s] = 0;\n\t\tupdate[s] = 1;\n\t\tqueue[t++] = s;\n\t\tenter[s] = true;\n\t\twhile (h < t) {\n\t\t\tint u = queue[h++];\n\t\t\tenter[u] = false;\n\t\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\t\tint v = to[ei];\n\t\t\t\tdouble w = weight[ei];\n\t\t\t\tif (dist[v] > dist[u] + w) {\n\t\t\t\t\tdist[v] = dist[u] + w;\n\t\t\t\t\tif (!enter[v]) {\n\t\t\t\t\t\t// 0...n+1号点，一共n+2个点，所以这里判断 > n + 1\n\t\t\t\t\t\tif (++update[v] > n + 1) {\n\t\t\t\t\t\t\treturn true;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tqueue[t++] = v;\n\t\t\t\t\t\tenter[v] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm1 = (int) in.nval;\n\t\tin.nextToken();\n\t\tm2 = (int) in.nval;\n\t\tfor (int i = 1; i <= m1; i++) {\n\t\t\tin.nextToken();\n\t\t\tvow[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][2] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][3] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1; i <= m2; i++) {\n\t\t\tin.nextToken();\n\t\t\tscore[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tscore[i][1] = (int) in.nval;\n\t\t}\n\t\tdouble ans = compute();\n\t\tif (ans == 0) {\n\t\t\tout.println("-1");\n\t\t} else {\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_Measurer1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6c87e582-d8ed-4788-b22c-c30179c0b88b	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class142;\n\n// 题目4，倍杀测量者，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P4926\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_Measurer2 {\n\n\tpublic static int MAXN = 1002;\n\n\tpublic static int MAXM = 3001;\n\n\tpublic static double INF = 1e10;\n\n\tpublic static int n, m1, m2;\n\n\tpublic static int[][] vow = new int[MAXN][4];\n\n\tpublic static int[][] score = new int[MAXN][2];\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\tpublic static double[] dist = new double[MAXN];\n\n\tpublic static int[] update = new int[MAXN];\n\n\tpublic static int MAXQ = 1000001;\n\n\tpublic static int[] queue = new int[MAXQ];\n\n\tpublic static int h, t;\n\n\tpublic static boolean[] enter = new boolean[MAXN];\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\th = t = 0;\n\t\tArrays.fill(head, 0, n + 2, 0);\n\t\tArrays.fill(dist, 0, n + 2, INF);\n\t\tArrays.fill(update, 0, n + 2, 0);\n\t\tArrays.fill(enter, 0, n + 2, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 另一种二分的写法\n\tpublic static double compute() {\n\t\tdouble l = 0, r = INF, m;\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tm = (l + r) / 2;\n\t\t\tif (check(m)) {\n\t\t\t\tl = m;\n\t\t\t} else {\n\t\t\t\tr = m;\n\t\t\t}\n\t\t}\n\t\treturn l;\n\t}\n\n\tpublic static boolean check(double limit) {\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddEdge(0, i, 0);\n\t\t}\n\t\tfor (int i = 1; i <= m1; i++) {\n\t\t\tif (vow[i][0] == 1) {\n\t\t\t\t// 课上的代码没有这个判断，加上才是正确的，防止log里出现负数\n\t\t\t\tif (-limit + vow[i][3] >= 0) {\n\t\t\t\t\taddEdge(vow[i][1], vow[i][2], -Math.log(-limit + vow[i][3]));\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\taddEdge(vow[i][1], vow[i][2], Math.log(limit + vow[i][3]));\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m2; i++) {\n\t\t\taddEdge(n + 1, score[i][0], Math.log(score[i][1]));\n\t\t\taddEdge(score[i][0], n + 1, -Math.log(score[i][1]));\n\t\t}\n\t\treturn spfa(0);\n\t}\n\n\tpublic static boolean spfa(int s) {\n\t\tdist[s] = 0;\n\t\tupdate[s] = 1;\n\t\tqueue[t++] = s;\n\t\tenter[s] = true;\n\t\twhile (h < t) {\n\t\t\tint u = queue[h++];\n\t\t\tenter[u] = false;\n\t\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\t\tint v = to[ei];\n\t\t\t\tdouble w = weight[ei];\n\t\t\t\tif (dist[v] > dist[u] + w) {\n\t\t\t\t\tdist[v] = dist[u] + w;\n\t\t\t\t\tif (!enter[v]) {\n\t\t\t\t\t\tif (++update[v] > n + 1) {\n\t\t\t\t\t\t\treturn true;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tqueue[t++] = v;\n\t\t\t\t\t\tenter[v] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm1 = (int) in.nval;\n\t\tin.nextToken();\n\t\tm2 = (int) in.nval;\n\t\tfor (int i = 1; i <= m1; i++) {\n\t\t\tin.nextToken();\n\t\t\tvow[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][2] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tvow[i][3] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1; i <= m2; i++) {\n\t\t\tin.nextToken();\n\t\t\tscore[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tscore[i][1] = (int) in.nval;\n\t\t}\n\t\tdouble ans = compute();\n\t\tif (ans == 0) {\n\t\t\tout.println("-1");\n\t\t} else {\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_Measurer2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0b1ef099-6def-443b-9453-7c730a5b00b0	94c527ef-9eb8-4db5-9295-71efa212a3f1	java	package class142;\n\n// 天平\n// 一共有n个砝码，编号1~n，每个砝码的重量均为1克，或者2克，或者3克 \n// 砝码与砝码之间的关系是一个n * n的二维数组s\n// s[i][j] == '+'，砝码i比砝码j重        s[i][j] == '-'，砝码i比砝码j轻\n// s[i][j] == '='，砝码i和砝码j重量一样   s[i][j] == '?'，砝码i和砝码j关系未知\n// 数据保证至少存在一种情况符合该矩阵\n// 给定编号为a和b的砝码，这两个砝码一定会放在天平的左边，你要另选两个砝码放在天平右边\n// 返回有多少种方法，一定让天平左边重(ans1)，一定让天平一样重(ans2)，一定让天平右边重(ans3)\n// 1 <= n <= 50\n// 测试链接 : https://www.luogu.com.cn/problem/P2474\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Balance {\n\n\tpublic static int MAXN = 51;\n\n\tpublic static int[][] dmin = new int[MAXN][MAXN];\n\n\tpublic static int[][] dmax = new int[MAXN][MAXN];\n\n\tpublic static char[][] s = new char[MAXN][MAXN];\n\n\tpublic static int n, a, b;\n\n\tpublic static int ans1, ans2, ans3;\n\n\tpublic static void compute() {\n\t\t// 设置初始关系\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (s[i][j] == '=') {\n\t\t\t\t\tdmin[i][j] = 0;\n\t\t\t\t\tdmax[i][j] = 0;\n\t\t\t\t} else if (s[i][j] == '+') {\n\t\t\t\t\tdmin[i][j] = 1;\n\t\t\t\t\tdmax[i][j] = 2;\n\t\t\t\t} else if (s[i][j] == '-') {\n\t\t\t\t\tdmin[i][j] = -2;\n\t\t\t\t\tdmax[i][j] = -1;\n\t\t\t\t} else {\n\t\t\t\t\tdmin[i][j] = -2;\n\t\t\t\t\tdmax[i][j] = 2;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdmin[i][i] = 0;\n\t\t\tdmax[i][i] = 0;\n\t\t}\n\t\t// 来自讲解065，Floyd算法\n\t\tfor (int bridge = 1; bridge <= n; bridge++) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tdmin[i][j] = Math.max(dmin[i][j], dmin[i][bridge] + dmin[bridge][j]);\n\t\t\t\t\tdmax[i][j] = Math.min(dmax[i][j], dmax[i][bridge] + dmax[bridge][j]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t// 统计答案\n\t\tans1 = ans2 = ans3 = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j < i; j++) {\n\t\t\t\tif (i != a && i != b && j != a && j != b) {\n\t\t\t\t\tif (dmin[a][i] > dmax[j][b] || dmin[a][j] > dmax[i][b]) {\n\t\t\t\t\t\tans1++;\n\t\t\t\t\t}\n\t\t\t\t\tif (dmax[a][i] < dmin[j][b] || dmax[a][j] < dmin[i][b]) {\n\t\t\t\t\t\tans3++;\n\t\t\t\t\t}\n\t\t\t\t\tif (dmin[a][i] == dmax[a][i] && dmin[j][b] == dmax[j][b] && dmin[a][i] == dmin[j][b]) {\n\t\t\t\t\t\tans2++;\n\t\t\t\t\t} else if (dmin[b][i] == dmax[b][i] && dmin[j][a] == dmax[j][a] && dmin[b][i] == dmin[j][a]) {\n\t\t\t\t\t\tans2++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tString[] numbers = br.readLine().split(" ");\n\t\tn = Integer.valueOf(numbers[0]);\n\t\ta = Integer.valueOf(numbers[1]);\n\t\tb = Integer.valueOf(numbers[2]);\n\t\tchar[] line;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tline = br.readLine().toCharArray();\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\ts[i][j] = line[j - 1];\n\t\t\t}\n\t\t}\n\t\tcompute();\n\t\tout.println(ans1 + " " + ans2 + " " + ans3);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_Balance.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4c608240-3835-4a39-8be2-23e3fd2d64bb	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class161;\n\n// 重链剖分模版题，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树\n// 给定每个节点的初始权值，给定树的头节点编号root\n// 一共有m条操作，每种操作是如下4种类型中的一种\n// 操作 1 x y v : x到y的路径上，每个节点值增加v\n// 操作 2 x y   : x到y的路径上，打印所有节点值的累加和\n// 操作 3 x v   : x为头的子树上，每个节点值增加v\n// 操作 4 x     : x为头的子树上，打印所有节点值的累加和\n// 1 <= n、m <= 10^5\n// 1 <= MOD <= 2^30\n// 输入的值都为int类型\n// 查询操作时，打印(查询结果 % MOD)，题目会给定MOD值\n// 测试链接 : https://www.luogu.com.cn/problem/P3384\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_HLD1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m, root, MOD;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static long[] sum = new long[MAXN << 2];\n\tpublic static long[] addTag = new long[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\t// 来到节点u，节点u树上的父节点是f\n\t// dfs1的过程去设置 fa dep siz son\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\t// 来到节点u，节点u所在重链的头节点是t\n\t// dfs2的过程去设置 top dfn seg\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(root, root, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tseg[cntd] = first;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = (sum[i << 1] + sum[i << 1 | 1]) % MOD;\n\t}\n\n\tpublic static void lazy(int i, long v, int n) {\n\t\tsum[i] = (sum[i] + v * n) % MOD;\n\t\taddTag[i] = (addTag[i] + v) % MOD;\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (addTag[i] != 0) {\n\t\t\tlazy(i << 1, addTag[i], ln);\n\t\t\tlazy(i << 1 | 1, addTag[i], rn);\n\t\t\taddTag[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = arr[seg[l]] % MOD;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans = (ans + query(jobl, jobr, l, mid, i << 1)) % MOD;\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = (ans + query(jobl, jobr, mid + 1, r, i << 1 | 1)) % MOD;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 从x到y的路径上，所有节点的值增加v\n\tpublic static void pathAdd(int x, int y, int v) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tadd(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tadd(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tadd(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\t// x的子树上，所有节点的值增加v\n\tpublic static void subtreeAdd(int x, int v) {\n\t\tadd(dfn[x], dfn[x] + siz[x] - 1, v, 1, n, 1);\n\t}\n\n\t// 从x到y的路径上，查询所有节点的累加和\n\tpublic static long pathSum(int x, int y) {\n\t\tlong ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans = (ans + query(dfn[top[y]], dfn[y], 1, n, 1)) % MOD;\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans = (ans + query(dfn[top[x]], dfn[x], 1, n, 1)) % MOD;\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans = (ans + query(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1)) % MOD;\n\t\treturn ans;\n\t}\n\n\t// x的子树上，查询所有节点的累加和\n\tpublic static long subtreeSum(int x) {\n\t\treturn query(dfn[x], dfn[x] + siz[x] - 1, 1, n, 1);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tin.nextToken();\n\t\troot = (int) in.nval;\n\t\tin.nextToken();\n\t\tMOD = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(root, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(root, root)，调用迭代版防止爆栈\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, op, x, y, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tpathAdd(x, y, v);\n\t\t\t} else if (op == 2) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tout.println(pathSum(x, y));\n\t\t\t} else if (op == 3) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tsubtreeAdd(x, v);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tout.println(subtreeSum(x));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n}	模板：Code01_HLD1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
