a7860d34-1c6b-45e9-9a71-b7d8dabfdaa3	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class161;\n\n// 重链剖分解决LCA查询，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，给定头节点编号root\n// 一共有m条查询，每条查询给定a和b，打印a和b的最低公共祖先\n// 请用树链剖分的方式实现\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3379\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_LCA1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m, root;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(root, root, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tin.nextToken();\n\t\troot = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(root, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(root, root)，调用迭代版防止爆栈\n\t\tfor (int i = 1, a, b; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\ta = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tb = (int) in.nval;\n\t\t\tout.println(lca(a, b));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_LCA1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
305814c7-a88a-46c3-b31e-77a73b7630a3	ca7d6569-a723-4f88-adac-5ccd93a14b7e	java	package class187;\n\n// 通道，C++版\n// 三棵树t1、t2、t3都有n个节点，各自给定n-1条边以及每条边的边权，边权没有负数\n// 点对(x, y)，要求两点必须不同，两点在树上的距离就是简单路径上边权的累加和\n// 点对(x, y)，在t1、t2、t3的距离，分别记为dis1(x, y)、dis2(x, y)、dis3(x, y)\n// 打印最大的dis1(x, y) + dis2(x, y) + dis3(x, y)\n// 2 <= n <= 10^5\n// 0 <= 边权 <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P4220\n// 测试链接 : https://loj.ac/p/2339\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 100001;\n//const int MAXM = MAXN << 1;\n//const int MAXP = 20;\n//const int MAXT = MAXN * 20;\n//const ll INF = 1LL << 60;\n//int n, cntn;\n//\n//int head0[MAXN];\n//int next0[MAXN << 1];\n//int to0[MAXN << 1];\n//ll weight0[MAXN << 1];\n//int cnt0;\n//\n//int head1[MAXM];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//ll weight1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN];\n//int next2[MAXN << 1];\n//int to2[MAXN << 1];\n//ll weight2[MAXN << 1];\n//int cnt2;\n//\n//int head3[MAXN];\n//int next3[MAXN << 1];\n//int to3[MAXN << 1];\n//ll weight3[MAXN << 1];\n//int cnt3;\n//\n//ll dep2[MAXN];\n//ll dist3[MAXN];\n//\n//bool vis[MAXM];\n//int siz[MAXM];\n//\n//int dfn[MAXN];\n//int lg2[MAXN];\n//int rmq[MAXN][MAXP];\n//int cntd;\n//\n//int up[MAXN];\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int lx[MAXT];\n//int ly[MAXT];\n//ll lxv[MAXT];\n//ll lyv[MAXT];\n//int rx[MAXT];\n//int ry[MAXT];\n//ll rxv[MAXT];\n//ll ryv[MAXT];\n//int cntt;\n//\n//ll ans;\n//\n//void addEdge0(int u, int v, ll w) {\n//    next0[++cnt0] = head0[u];\n//    to0[cnt0] = v;\n//    weight0[cnt0] = w;\n//    head0[u] = cnt0;\n//}\n//\n//void addEdge1(int u, int v, ll w) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    weight1[cnt1] = w;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v, ll w) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    weight2