];\n//    }\n//    for (int i = 1; i < n; i++) {\n//        int u, v;\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    build(1, n, 1);\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        int x, y, v;\n//        cin >> x >> y >> v;\n//        cout << compute(x, y, v) << "\\n";\n//    }\n//    return 0;\n//}	模板：Code06_Tourism2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5b6a94cd-0a52-4b4e-86dd-1e2b72b91725	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class161;\n\n// 遥远的国度，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，给定树的初始头节点，给定每个点的点权\n// 一共有m条操作，每种操作是如下3种类型中的一种\n// 操作 1 x     : 树的头节点变成x，整棵树需要重新组织\n// 操作 2 x y v : x到y的路径上，所有节点的值改成v\n// 操作 3 x     : 在当前树的状态下，打印u的子树中的最小值\n// 1 <= n、m <= 10^5\n// 任何时候节点值一定是正数\n// 测试链接 : https://www.luogu.com.cn/problem/P3979\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code07_FarAway1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static int[] min = new int[MAXN << 2];\n\t// 重置操作的懒更新信息\n\t// 因为题目说了，任何时候节点值一定是正数\n\t// change[i] == 0，表示没有重置懒更新\n\t// change[i] != 0，表示范围内的数字修改为change[i]\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tseg[cntd] = first;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tmin[i] = Math.min(min[i << 1], min[i << 1 | 1]);\n\t}\n\n\tpublic static void lazy(int i, int v) {\n\t\tmin[i] = v;\n\t\tchange[i] = v;\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (change[i] != 0) {\n\t\t\tlazy(i << 1, change[i]);\n\t\t\tlazy(i << 1 | 1, change[i]);\n\t\t\tchange[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tmin[i] = arr[seg[l]];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv);\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn min[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) / 2;\n\t\tint ans = Integer.MAX_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void pathUpdate(int x, int y, int v) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tupdate(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tupdate(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tupdate(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\t// 已知root一定在u的子树上\n\t// 找到u哪个儿子的子树里有root，返回那个儿子的编号\n\tpublic static int findSon(int root, int u) {\n\t\twhile (top[root] != top[u]) {\n\t\t\tif (fa[top[root]] == u) {\n\t\t\t\treturn top[root];\n\t\t\t}\n\t\t\troot = fa[top[root]];\n\t\t}\n\t\treturn son[u];\n\t}\n\n\t// 假设树的头节点变成root，在当前树的状态下，查询u的子树中的最小值\n\tpublic static int treeQuery(int root, int u) {\n\t\tif (root == u) {\n\t\t\treturn min[1];\n\t\t} else if (dfn[root] < dfn[u] || dfn[u] + siz[u] <= dfn[root]) {\n\t\t\treturn query(dfn[u], dfn[u] + siz[u] - 1, 1, n, 1);\n\t\t} else {\n\t\t\tint uson = findSon(root, u);\n\t\t\tint ans = query(1, dfn[uson] - 1, 1, n, 1);\n\t\t\tif (dfn[uson] + siz[uson] <= n) {\n\t\t\t\tans = Math.min(ans, query(dfn[uson] + siz[uson], n, 1, n, 1));\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(1, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(1, 1)，调用迭代版防止爆栈\n\t\tbuild(1, n, 1);\n\t\tin.nextToken();\n\t\tint root = (int) in.nval;\n\t\tfor (int i = 1, op, x, y, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\troot = (int) in.nval;\n\t\t\t} else if (op == 2) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tpathUpdate(x, y, v);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tout.println(treeQuery(root, x));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code07_FarAway1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
