x = fa[top[x]];\n//        }\n//    }\n//    ans = max(ans, queryMax(min(dfn[x], dfn[y]) + 1, max(dfn[x], dfn[y]), 1, n, 1));\n//    return ans;\n//}\n//\n//int pathMin(int x, int y) {\n//    int ans = INT_MAX;\n//    while (top[x] != top[y]) {\n//        if (dep[top[x]] <= dep[top[y]]) {\n//            ans = min(ans, queryMin(dfn[top[y]], dfn[y], 1, n, 1));\n//            y = fa[top[y]];\n//        } else {\n//            ans = min(ans, queryMin(dfn[top[x]], dfn[x], 1, n, 1));\n//            x = fa[top[x]];\n//        }\n//    }\n//    ans = min(ans, queryMin(min(dfn[x], dfn[y]) + 1, max(dfn[x], dfn[y]), 1, n, 1));\n//    return ans;\n//}\n//\n//void prepare() {\n//    for (int i = 1; i < n; i++) {\n//        addEdge(arr[i][0], arr[i][1]);\n//        addEdge(arr[i][1], arr[i][0]);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    for (int i = 1; i < n; i++) {\n//        edgeUpdate(i, arr[i][2]);\n//    }\n//}\n//\n//int main(){\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for(int i = 1; i < n; i++){\n//        cin >> arr[i][0] >> arr[i][1] >> arr[i][2];\n//        arr[i][0]++;\n//        arr[i][1]++;\n//    }\n//    prepare();\n//    cin >> m;\n//    string op;\n//    for(int i = 1, x, y; i <= m; i++){\n//        string op;\n//        cin >> op;\n//        if(op == "C"){\n//            cin >> x >> y;\n//            edgeUpdate(x, y);\n//        } else {\n//            cin >> x >> y;\n//            x++;\n//            y++;\n//            if(op == "N"){\n//            \tpathNegative(x, y);\n//            } else if(op == "SUM"){\n//                cout << pathSum(x, y) << "\\n";\n//            } else if(op == "MAX"){\n//                cout << pathMax(x, y) << "\\n";\n//            } else {\n//                cout << pathMin(x, y) << "\\n";\n//            }\n//        }\n//    }\n//    return 0;\n//}	模板：Code02_NationalTour2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
636b2f3d-00df-49b2-9945-5df6b1c73261	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class162;\n\n// 月下毛景树，java版\n// 一共有n个节点，节点编号从1到n，所有节点连成一棵树\n// 给定n-1条边，边的编号从1到n-1，每条边给定初始边权\n// 会进行若干次操作，每条操作的类型是如下4种类型中的一种\n// 操作 Change x v  : 第x条边的边权改成v\n// 操作 Cover x y v : x号点到y号点的路径上，所有边权改成v\n// 操作 Add x y v   : x号点到y号点的路径上，所有边权增加v\n// 操作 Max x y     : x号点到y号点的路径上，打印最大的边权\n// 1 <= n <= 10^5\n// 任何时候的边权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4315\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code03_UnderMoon1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n;\n\tpublic static int[][] arr = new int[MAXN][3];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\t// 重链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\t// 线段树查询区间最大值\n\t// 但是需要同时兼顾，区间增加、区间重置，这两种操作\n\t// 那么就牵扯到两种操作相互影响的问题\n\t// 因为区间重置操作会取消之前的区间增加操作\n\t// 讲解110，线段树章节，题目5、题目6，重点讲了这种线段树\n\t// 不会的同学可以看看，讲的非常清楚\n\tpublic static int[] max = new int[MAXN << 2];\n\tpublic static int[] addTag = new int[MAXN << 2];\n\tpublic static boolean[] updateTag = new boolean[MAXN << 2];\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) {\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void addLazy(int i, int v) {\n\t\tmax[i] += v;\n\t\taddTag[i] += v;\n\t}\n\n\tpublic static void updateLazy(int i, int v) {\n\t\tmax[i] = v;\n\t\taddTag[i] = 0;\n\t\tupdateTag[i] = true;\n\t\tchange[i] = v;\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (updateTag[i]) {\n\t\t\tupdateLazy(i << 1, change[i]);\n\t\t\tupdateLazy(i << 1 | 1, change[i]);\n\t\t\tupdateTag[i] = false;\n\t\t}\n\t\tif (addTag[i] != 0) {\n\t\t\taddLazy(i << 1, addTag[i]);\n\t\t\taddLazy(i << 1 | 1, addTag[i]);\n\t\t\taddTag[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tupdateLazy(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void add(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddLazy(i, jobv);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tdown(i);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tadd(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tadd(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tdown(i);\n\t\tint ans = Integer.MIN_VALUE;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void edgeUpdate(int ei, int val) {\n\t\tint x = arr[ei][0];\n\t\tint y = arr[ei][1];\n\t\tint down = Math.max(dfn[x], dfn[y]);\n\t\tupdate(down, down, val, 1, n, 1);\n\t}\n\n\tpublic static void pathUpdate(int x, int y, int v) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tupdate(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tupdate(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tupdate(Math.min(dfn[x], dfn[y]) + 1, Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\tpublic static void pathAdd(int x, int y, int v) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tadd(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tadd(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tadd(Math.min(dfn[x], dfn[y]) + 1, Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\tpublic static int pathMax(int x, int y) {\n\t\tint ans = Integer.MIN_VALUE;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans = Math.max(ans, query(dfn[top[y]], dfn[y], 1, n, 1));\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans = Math.max(ans, query(dfn[top[x]], dfn[x], 1, n, 1));\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans = Math.max(ans, query(Math.min(dfn[x], dfn[y]) + 1, Math.max(dfn[x], dfn[y]), 1, n, 1));\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\taddEdge(arr[i][0], arr[i][1]);\n\t\t\taddEdge(arr[i][1], arr[i][0]);\n\t\t}\n\t\tdfs3();\n\t\tdfs4();\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tedgeUpdate(i, arr[i][2]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tarr[i][0] = io.nextInt();\n\t\t\tarr[i][1] = io.nextInt();\n\t\t\tarr[i][2] = io.nextInt();\n\t\t}\n\t\tprepare();\n\t\tString op = io.next();\n\t\tint x, y, v;\n\t\twhile (!op.equals("Stop")) {\n\t\t\tif (op.equals("Change")) {\n\t\t\t\tx = io.nextInt();\n\t\t\t\tv = io.nextInt();\n\t\t\t\tedgeUpdate(x, v);\n\t\t\t} else if (op.equals("Cover")) {\n\t\t\t\tx = io.nextInt();\n\t\t\t\ty = io.nextInt();\n\t\t\t\tv = io.nextInt();\n\t\t\t\tpathUpdate(x, y, v);\n\t\t\t} else if (op.equals("Add")) {\n\t\t\t\tx = io.nextInt();\n\t\t\t\ty = io.nextInt();\n\t\t\t\tv = io.nextInt();\n\t\t\t\tpathAdd(x, y, v);\n\t\t\t} else {\n\t\t\t\tx = io.nextInt();\n\t\t\t\ty = io.nextInt();\n\t\t\t\tio.println(pathMax(x, y));\n\t\t\t}\n\t\t\top = io.next();\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_UnderMoon1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
154b63d4-fdfc-48a3-b667-1668c026d3f7	33ae640b-cdab-4563-b53c-02099c3eb093	java	package class162;\n\n// 月下毛景树，C++版\n// 一共有n个节点，节点编号从1到n，所有节点连成一棵树\n// 给定n-1条边，边的编号从1到n-1，每条边给定初始边权\n// 会进行若干次操作，每条操作的类型是如下4种类型中的一种\n// 操作 Change x v  : 第x条边的边权改成v\n// 操作 Cover x y v : x号点到y号点的路径上，所有边权改成v\n// 操作 Add x y v   : x号点到y号点的路径上，所有边权增加v\n// 操作 Max x y     : x号点到y号点的路径上，打印最大的边权\n// 1 <= n <= 10^5\n// 任何时候的边权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4315\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n;\n//int arr[MAXN][3];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg = 0;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dfn[MAXN];\n//int cntd = 0;\n//\n//int maxv[MAXN << 2];\n//int addTag[MAXN << 2];\n//bool updateTag[MAXN << 2];\n//int change[MAXN << 2];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//        }\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    dfn[u] = ++cntd;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//void up(int i) {\n//    maxv[i] = max(maxv[i << 1], maxv[i << 1 | 1]);\n//}\n//\n//