    setf(u, 0, 1);\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs3(son[u]);\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != son[u] && v != fa[u]) {\n//            dfs3(v);\n//        }\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != son[u] && v != fa[u]) {\n//            for (int i = 0; i <= len[v]; i++) {\n//                if (i < len[u] && i - 1 >= 0) {\n//                    ans += getg(u, i) * getf(v, i - 1);\n//                }\n//                if (i > 0 && i + 1 < len[v]) {\n//                    ans += getf(u, i) * getg(v, i + 1);\n//                }\n//            }\n//            for (int i = 0; i <= len[v]; i++) {\n//                if (i + 1 < len[v]) {\n//                    setg(u, i, getg(u, i) + getg(v, i + 1));\n//                }\n//                if (i - 1 >= 0) {\n//                    setg(u, i, getg(u, i) + getf(u, i) * getf(v, i - 1));\n//                }\n//            }\n//            for (int i = 0; i <= len[v]; i++) {\n//                if (i - 1 >= 0) {\n//                    setf(u, i, getf(u, i) + getf(v, i - 1));\n//                }\n//            }\n//        }\n//    }\n//    ans += getg(u, 0);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    dfs3(1);\n//    cout << ans << "\\n";\n//    return 0;\n//}	模板：Code07_HotHotels2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6041a801-2394-4699-8563-d6538c5fc608	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\n// Dijkstra算法模版（Leetcode）\n// 网络延迟时间\n// 有 n 个网络节点，标记为 1 到 n\n// 给你一个列表 times，表示信号经过 有向 边的传递时间\n// times[i] = (ui, vi, wi)，表示从ui到vi传递信号的时间是wi\n// 现在，从某个节点 s 发出一个信号\n// 需要多久才能使所有节点都收到信号\n// 如果不能使所有节点收到信号，返回 -1\n// 测试链接 : https://leetcode.cn/problems/network-delay-time\npublic class Code01_DijkstraLeetcode {\n\n\t// 动态建图+普通堆的实现\n\tpublic static int networkDelayTime1(int[][] times, int n, int s) {\n\t\tArrayList<ArrayList<int[]>> graph = new ArrayList<>();\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tgraph.add(new ArrayList<>());\n\t\t}\n\t\tfor (int[] edge : times) {\n\t\t\tgraph.get(edge[0]).add(new int[] { edge[1], edge[2] });\n\t\t}\n\t\tint[] distance = new int[n + 1];\n\t\tArrays.fill(distance, Integer.MAX_VALUE);\n\t\tdistance[s] = 0;\n\t\tboolean[] visited = new boolean[n + 1];\n\t\t// 0 : 当前节点\n\t\t// 1 : 源点到当前点距离\n\t\tPriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[1] - b[1]);\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint u = heap.poll()[0];\n\t\t\tif (visited[u]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u] = true;\n\t\t\tfor (int[] edge : graph.get(u)) {\n\t\t\t\tint v = edge[0];\n\t\t\t\tint w = edge[1];\n\t\t\t\tif (!visited[v] && distance[u] + w < distance[v]) {\n\t\t\t\t\tdistance[v] = distance[u] + w;\n\t\t\t\t\theap.add(new int[] { v, distance[u] + w });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint ans = Integer.MIN_VALUE;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (distance[i] == Integer.MAX_VALUE) {\n\t\t\t\treturn -1;\n\t\t\t}\n\t\t\tans = Math.max(ans, distance[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 链式前向星+反向索引堆的实现\n\tpublic static int networkDelayTime2(int[][] times, int n, int s) {\n\t\tbuild(n);\n\t\tfor (int[] edge : times) {\n\t\t\taddEdge(edge[0], edge[1], edge[2]);\n\t\t}\n\t\taddOrUpdateOrIgnore(s, 0);\n\t\twhile (!isEmpty()) {\n\t\t\tint u = pop();\n\t\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\t\taddOrUpdateOrIgnore(to[ei], distance[u] + weight[ei]);\n\t\t\t}\n\t\t}\n\t\tint ans = Integer.MIN_VALUE;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (distance[i] == Integer.MAX_VALUE) {\n\t\t\t\treturn -1;\n\t\t\t}\n\t\t\tans = Math.max(ans, distance[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int MAXN = 101;\n\n\tpublic static int MAXM = 6001;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// 反向索引堆\n\tpublic static int[] heap = new int[MAXN];\n\n\t// where[v] = -1，表示v这个节点，从来没有进入过堆\n\t// where[v] = -2，表示v这个节点，已经弹出过了\n\t// where[v] = i(>=0)，表示v这个节点，在堆上的i位置\n\tpublic static int[] where = new int[MAXN];\n\n\tpublic static int heapSize;\n\n\tpublic static int[] distance = new int[MAXN];\n\n\tpublic static void build(int n) {\n\t\tcnt = 1;\n\t\theapSize = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(where, 1, n + 1, -1);\n\t\tArrays.fill(distance, 1, n + 1, Integer.MAX_VALUE);\n\t}\n\n\t// 链式前向星建图\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void addOrUpdateOrIgnore(int v, int c) {\n\t\tif (where[v] == -1) {\n\t\t\theap[heapSize] = v;\n\t\t\twhere[v] = heapSize++;\n\t\t\tdistance[v] = c;\n\t\t\theapInsert(where[v]);\n\t\t} else if (where[v] >= 0) {\n\t\t\tdistance[v] = Math.min(distance[v], c);\n\t\t\theapInsert(where[v]);\n\t\t}\n\t}\n\n\tpublic static void heapInsert(int i) {\n\t\twhile (distance[heap[i]] < distance[heap[(i - 1) / 2]]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\tpublic static int pop() {\n\t\tint ans = heap[0];\n\t\tswap(0, --heapSize);\n\t\theapify(0);\n\t\twhere[ans] = -2;\n\t\treturn ans;\n\t}\n\n\tpublic static void heapify(int i) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < heapSize) {\n\t\t\tint best = l + 1 < heapSize && distance[heap[l + 1]] < distance[heap[l]] ? l + 1 : l;\n\t\t\tbest = distance[heap[best]] < distance[heap[i]] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static boolean isEmpty() {\n\t\treturn heapSize == 0;\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint tmp = heap[i];\n\t\theap[i] = heap[j];\n\t\theap[j] = tmp;\n\t\twhere[heap[i]] = i;\n\t\twhere[heap[j]] = j;\n\t}\n\n}\n	模板：Code01_DijkstraLeetcode.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4643df66-dd6b-42f3-a296-23cd94dd86a1	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\n// Dijkstra算法模版（洛谷）\n// 静态空间实现 : 链式前向星 + 反向索引堆\n// 测试链接 : https://www.luogu.com.cn/problem/P4779\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_DijkstraLuogu {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXM = 200001;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// 反向索引堆\n\tpublic static int[] heap = new int[MAXN];\n\n\t// where[v] = -1，表示v这个节点，从来没有进入过堆\n\t// where[v] = -2，表示v这个节点，已经弹出过了\n\t// where[v] = i(>=0)，表示v这个节点，在堆上的i位置\n\tpublic static int[] where = new int[MAXN];\n\n\tpublic static int heapSize;\n\n\tpublic static int[] distance = new int[MAXN];\n\n\tpublic static int n, m, s;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\theapSize = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(where, 1, n + 1, -1);\n\t\tArrays.fill(distance, 1, n + 1, Integer.MAX_VALUE);\n\t}\n\n\t// 链式前向星建图\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void addOrUpdateOrIgnore(int v, int w) {\n\t\tif (where[v] == -1) {\n\t\t\theap[heapSize] = v;\n\t\t\twhere[v] = heapSize++;\n\t\t\tdistance[v] = w;\n\t\t\theapInsert(where[v]);\n\t\t} else if (where[v] >= 0) {\n\t\t\tdistance[v] = Math.min(distance[v], w);\n\t\t\theapInsert(where[v]);\n\t\t}\n\t}\n\n\tpublic static void heapInsert(int i) {\n\t\twhile (distance[heap[i]] < distance[heap[(i - 1) / 2]]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\tpublic static int pop() {\n\t\tint ans = heap[0];\n\t\tswap(0, --heapSize);\n\t\theapify(0);\n\t\twhere[ans] = -2;\n\t\treturn ans;\n\t}\n\n\tpublic static void heapify(int i) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < heapSize) {\n\t\t\tint best = l + 1 < heapSize && distance[heap[l + 1]] < distance[heap[l]] ? l + 1 : l;\n\t\t\tbest = distance[heap[best]] < distance[heap[i]] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static boolean isEmpty() {\n\t\treturn heapSize == 0;\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint tmp = heap[i];\n\t\theap[i] = heap[j];\n\t\theap[j] = tmp;\n\t\twhere[heap[i]] = i;\n\t\twhere[heap[j]] = j;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken(); m = (int) in.nval;\n\t\t\tin.nextToken(); s = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0, u, v, w; i < m; i++) {\n\t\t\t\tin.nextToken(); u = (int) in.nval;\n\t\t\t\tin.nextToken(); v = (int) in.nval;\n\t\t\t\tin.nextToken(); w = (int) in.nval;\n\t\t\t\taddEdge(u, v, w);\n\t\t\t}\n\t\t\tdijkstra();\n\t\t\tout.print(distance[1]);\n\t\t\tfor (int i = 2; i <= n; i++) {\n\t\t\t\tout.print(" " + distance[i]);\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static void dijkstra() {\n\t\taddOrUpdateOrIgnore(s, 0);\n\t\twhile (!isEmpty()) {\n\t\t\tint v = pop();\n\t\t\tfor (int ei = head[v]; ei > 0; ei = next[ei]) {\n\t\t\t\taddOrUpdateOrIgnore(to[ei], distance[v] + weight[ei]);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code01_DijkstraLuogu.java	2026-07-25 03:11:34.779768+0