dc24f7aa-35ca-4b3b-83ce-d882d2a68a96	980c727f-f969-4eac-9ccf-bdf918b2d2c2	java	package class041;\n\nimport java.math.BigInteger;\n\n// 加法、减法、乘法的同余原理\n// 不包括除法，因为除法必须求逆元，后续课讲述\npublic class Code03_SameMod {\n\n\t// 为了测试\n\tpublic static long random() {\n\t\treturn (long) (Math.random() * Long.MAX_VALUE);\n\t}\n\n\t// 计算 ((a + b) * (c - d) + (a * c - b * d)) % mod 的非负结果\n\tpublic static int f1(long a, long b, long c, long d, int mod) {\n\t\tBigInteger o1 = new BigInteger(String.valueOf(a)); // a\n\t\tBigInteger o2 = new BigInteger(String.valueOf(b)); // b\n\t\tBigInteger o3 = new BigInteger(String.valueOf(c)); // c\n\t\tBigInteger o4 = new BigInteger(String.valueOf(d)); // d\n\t\tBigInteger o5 = o1.add(o2); // a + b\n\t\tBigInteger o6 = o3.subtract(o4); // c - d\n\t\tBigInteger o7 = o1.multiply(o3); // a * c\n\t\tBigInteger o8 = o2.multiply(o4); // b * d\n\t\tBigInteger o9 = o5.multiply(o6); // (a + b) * (c - d)\n\t\tBigInteger o10 = o7.subtract(o8); // (a * c - b * d)\n\t\tBigInteger o11 = o9.add(o10); // ((a + b) * (c - d) + (a * c - b * d))\n\t\t// ((a + b) * (c - d) + (a * c - b * d)) % mod\n\t\tBigInteger o12 = o11.mod(new BigInteger(String.valueOf(mod)));\n\t\tif (o12.signum() == -1) {\n\t\t\t// 如果是负数那么+mod返回\n\t\t\treturn o12.add(new BigInteger(String.valueOf(mod))).intValue();\n\t\t} else {\n\t\t\t// 如果不是负数直接返回\n\t\t\treturn o12.intValue();\n\t\t}\n\t}\n\n\t// 计算 ((a + b) * (c - d) + (a * c - b * d)) % mod 的非负结果\n\tpublic static int f2(long a, long b, long c, long d, int mod) {\n\t\tint o1 = (int) (a % mod); // a\n\t\tint o2 = (int) (b % mod); // b\n\t\tint o3 = (int) (c % mod); // c\n\t\tint o4 = (int) (d % mod); // d\n\t\tint o5 = (o1 + o2) % mod; // a + b\n\t\tint o6 = (o3 - o4 + mod) % mod; // c - d\n\t\tint o7 = (int) (((long) o1 * o3) % mod); // a * c\n\t\tint o8 = (int) (((long) o2 * o4) % mod); // b * d\n\t\tint o9 = (int) (((long) o5 * o6) % mod); // (a + b) * (c - d)\n\t\tint o10 = (o7 - o8 + mod) % mod; // (a * c - b * d)\n\t\tint ans = (o9 + o10) % mod; // ((a + b) * (c - d) + (a * c - b * d)) % mod\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("测试开始");\n\t\tint testTime = 100000;\n\t\tint mod = 1000000007;\n\t\tfor (int i = 0; i < testTime; i++) {\n\t\t\tlong a = random();\n\t\t\tlong b = random();\n\t\t\tlong c = random();\n\t\t\tlong d = random();\n\t\t\tif (f1(a, b, c, d, mod) != f2(a, b, c, d, mod)) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\n\t\tSystem.out.println("===");\n\t\tlong a = random();\n\t\tlong b = random();\n\t\tlong c = random();\n\t\tlong d = random();\n\t\tSystem.out.println("a : " + a);\n\t\tSystem.out.println("b : " + b);\n\t\tSystem.out.println("c : " + c);\n\t\tSystem.out.println("d : " + d);\n\t\tSystem.out.println("===");\n\t\tSystem.out.println("f1 : " + f1(a, b, c, d, mod));\n\t\tSystem.out.println("f2 : " + f2(a, b, c, d, mod));\n\t}\n\n}	模板：Code03_SameMod.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
70578ee9-cad2-4faf-bd7b-e1f9db8d9cff	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\nimport java.util.PriorityQueue;\n\n// 最小体力消耗路径\n// 你准备参加一场远足活动。给你一个二维 rows x columns 的地图 heights\n// 其中 heights[row][col] 表示格子 (row, col) 的高度\n// 一开始你在最左上角的格子 (0, 0) ，且你希望去最右下角的格子 (rows-1, columns-1) \n// （注意下标从 0 开始编号）。你每次可以往 上，下，左，右 四个方向之一移动\n// 你想要找到耗费 体力 最小的一条路径\n// 一条路径耗费的体力值是路径上，相邻格子之间高度差绝对值的最大值\n// 请你返回从左上角走到右下角的最小 体力消耗值\n// 测试链接 ：https://leetcode.cn/problems/path-with-minimum-effort/\npublic class Code02_PathWithMinimumEffort {\n\n\t// 0:上，1:右，2:下，3:左\n\tpublic static int[] move = new int[] { -1, 0, 1, 0, -1 };\n\n\tpublic int minimumEffortPath(int[][] heights) {\n\t\t// (0,0)源点\n\t\t// -> (x,y)\n\t\tint n = heights.length;\n\t\tint m = heights[0].length;\n\t\tint[][] distance = new int[n][m];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tdistance[i][j] = Integer.MAX_VALUE;\n\t\t\t}\n\t\t}\n\t\tdistance[0][0] = 0;\n\t\tboolean[][] visited = new boolean[n][m];\n\t\t// 0 : 格子的行\n\t\t// 1 : 格子的列\n\t\t// 2 : 源点到当前格子的代价\n\t\tPriorityQueue<int[]> heap = new PriorityQueue<int[]>((a, b) -> a[2] - b[2]);\n\t\theap.add(new int[] { 0, 0, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] record = heap.poll();\n\t\t\tint x = record[0];\n\t\t\tint y = record[1];\n\t\t\tint c = record[2];\n\t\t\tif (visited[x][y]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tif (x == n - 1 && y == m - 1) {\n\t\t\t\t// 常见剪枝\n\t\t\t\t// 发现终点直接返回\n\t\t\t\t// 不用等都结束\n\t\t\t\treturn c;\n\t\t\t}\n\t\t\tvisited[x][y] = true;\n\t\t\tfor (int i = 0; i < 4; i++) {\n\t\t\t\tint nx = x + move[i];\n\t\t\t\tint ny = y + move[i + 1];\n\t\t\t\tif (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {\n\t\t\t\t\tint nc = Math.max(c, Math.abs(heights[x][y] - heights[nx][ny]));\n\t\t\t\t\tif (nc < distance[nx][ny]) {\n\t\t\t\t\t\tdistance[nx][ny] = nc;\n\t\t\t\t\t\theap.add(new int[] { nx, ny, nc });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code02_PathWithMinimumEffort.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bb0b7416-58c0-400d-9227-cac28666350a	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\nimport java.util.PriorityQueue;\n\n// 水位上升的泳池中游泳\n// 在一个 n x n 的整数矩阵 grid 中\n// 每一个方格的值 grid[i][j] 表示位置 (i, j) 的平台高度\n// 当开始下雨时，在时间为 t 时，水池中的水位为 t\n// 你可以从一个平台游向四周相邻的任意一个平台，但是前提是此时水位必须同时淹没这两个平台\n// 假定你可以瞬间移动无限距离，也就是默认在方格内部游动是不耗时的\n// 当然，在你游泳的时候你必须待在坐标方格里面。\n// 你从坐标方格的左上平台 (0，0) 出发\n// 返回 你到达坐标方格的右下平台 (n-1, n-1) 所需的最少时间\n// 测试链接 : https://leetcode.cn/problems/swim-in-rising-water/\npublic class Code03_SwimInRisingWater {\n\n\t// 0:上，1:右，2:下，3:左\n\tpublic static int[] move = new int[] { -1, 0, 1, 0, -1 };\n\n\tpublic static int swimInWater(int[][] grid) {\n\t\tint n = grid.length;\n\t\tint m = grid[0].length;\n\t\tint[][] distance = new int[n][m];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tdistance[i][j] = Integer.MAX_VALUE;\n\t\t\t}\n\t\t}\n\t\tdistance[0][0] = grid[0][0];\n\t\tboolean[][] visited = new boolean[n][m];\n\t\t// 0 : 格子的行\n\t\t// 1 : 格子的列\n\t\t// 2 : 源点到当前格子的代价\n\t\tPriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[2] - b[2]);\n\t\theap.add(new int[] { 0, 0, grid[0][0] });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint x = heap.peek()[0];\n\t\t\tint y = heap.peek()[1];\n\t\t\tint c = heap.peek()[2];\n\t\t\theap.poll();\n\t\t\tif (visited[x][y]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[x][y] = true;\n\t\t\tif (x == n - 1 && y == m - 1) {\n\t\t\t\t// 常见剪枝\n\t\t\t\t// 发现终点直接返回\n\t\t\t\t// 不用等都结束\n\t\t\t\treturn c;\n\t\t\t}\n\t\t\tfor (int i = 0, nx, ny, nc; i < 4; i++) {\n\t\t\t\tnx = x + move[i];\n\t\t\t\tny = y + move[i + 1];\n\t\t\t\tif (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {\n\t\t\t\t\tnc = Math.max(c, grid[nx][ny]);\n\t\t\t\t\tif (nc < distance[nx][ny]) {\n\t\t\t\t\t\tdistance[nx][ny] = nc;\n\t\t\t\t\t\theap.add(new int[] { nx, ny, nc });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code03_SwimInRisingWater.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f804fbb6-8d4c-44fa-a165-deb45252e68f	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\n// 获取所有钥匙的最短路径\n// 给定一个二维网格 grid ，其中：\n// '.' 代表一个空房间、'#' 代表一堵、'@' 是起点\n// 小写字母代表钥匙、大写字母代表锁\n// 从起点开始出发，一次移动是指向四个基本方向之一行走一个单位空间\n// 不能在网格外面行走，也无法穿过一堵墙\n// 如果途经一个钥匙，我们就把它捡起来。除非我们手里有对应的钥匙，否则无法通过锁。\n// 假设 k 为 钥匙/锁 的个数，且满足 1 <= k <= 6，\n// 字母表中的前 k 个字母在网格中都有自己对应的一个小写和一个大写字母\n// 换言之，每个锁有唯一对应的钥匙，每个钥匙也有唯一对应的锁\n// 另外，代表钥匙和锁的字母互为大小写并按字母顺序排列\n// 返回获取所有钥匙所需要的移动的最少次数。如果无法获取所有钥匙，返回 -1 。\n// 测试链接：https://leetcode.cn/problems/shortest-path-to-get-all-keys\npublic class Code04_ShortestPathToGetAllKeys {\n\n\tpublic static int MAXN = 31;\n\n\tpublic static int MAXM = 31;\n\n\tpublic static int MAXK = 6;\n\n\t// 0:上，1:右，2:下，3:左\n\tpublic static int[] move = new int[] { -1, 0, 1, 0, -1 };\n\n\tpublic static char[][] grid = new char[MAXN][];\n\n\tpublic static boolean[][][] visited = new boolean[MAXN][MAXM][1 << MAXK];\n\n\t// 0 : 行\n\t// 1 : 列\n\t// 2 : 收集钥匙的状态\n\tpublic static int[][] queue = new int[MAXN * MAXM * (1 << MAXK)][3];\n\n\tpublic static int l, r, n, m, key;\n\n\tpublic static void build(String[] g) {\n\t\tl = r = key = 0;\n\t\tn = g.length;\n\t\tm = g[0].length();\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tgrid[i] = g[i].toCharArray();\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tif (grid[i][j] == '@') {\n\t\t\t\t\tqueue[r][0] = i;\n\t\t\t\t\tqueue[r][1] = j;\n\t\t\t\t\t// 0 : 000000\n\t\t\t\t\tqueue[r++][2] = 0;\n\t\t\t\t}\n\t\t\t\tif (grid[i][j] >= 'a' && grid[i][j] <= 'f') {\n\t\t\t\t\tkey |= 1 << (grid[i][j] - 'a');\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tfor (int s = 0; s <= key; s++) {\n\t\t\t\t\tvisited[i][j][s] = false;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int shortestPathAllKeys(String[] g) {\n\t\tbuild(g);\n\t\tint level = 1;\n\t\twhile (l < r) {\n\t\t\tfor (int k = 0, size = r - l, x, y, s; k < size; k++) {\n\t\t\t\tx = queue[l][0];\n\t\t\t\ty = queue[l][1];\n\t\t\t\ts = queue[l++][2];\n\t\t\t\tfor (int i = 0, nx, ny, ns; i < 4; i++) {\n\t\t\t\t\tnx = x + move[i];\n\t\t\t\t\tny = y + move[i + 1];\n\t\t\t\t\tns = s;\n\t\t\t\t\tif (nx < 0 || nx == n || ny < 0 || ny == m || grid[nx][ny] == '#') {\n\t\t\t\t\t\t// 越界或者障碍\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tif (grid[nx][ny] >= 'A' && grid[nx][ny] <= 'F' && ((ns & (1 << (grid[nx][ny] - 'A'))) == 0)) {\n\t\t\t\t\t\t// 是锁，又没有对应的钥匙\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tif (grid[nx][ny] >= 'a' && grid[nx][ny] <= 'f') {\n\t\t\t\t\t\t// 是某一把钥匙\n\t\t\t\t\t\tns |= (1 << (grid[nx][ny] - 'a'));\n\t\t\t\t\t}\n\t\t\t\t\tif (ns == key) {\n\t\t\t\t\t\t// 常见剪枝\n\t\t\t\t\t\t// 发现终点直接返回\n\t\t\t\t\t\t// 不用等都结束\n\t\t\t\t\t\treturn level;\n\t\t\t\t\t}\n\t\t\t\t\tif (!visited[nx][ny][ns]) {\n\t\t\t\t\t\tvisited[nx][ny][ns] = true;\n\t\t\t\t\t\tqueue[r][0] = nx;\n\t\t\t\t\t\tqueue[r][1] = ny;\n\t\t\t\t\t\tqueue[r++][2] = ns;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tlevel++;\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code04_ShortestPathToGetAllKeys.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
64709959-61c4-409a-bda1-8120d0cf7b34	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\nimport java.util.ArrayList;\nimport java.util.PriorityQueue;\n\n// 电动车游城市\n// 小明的电动车电量充满时可行驶距离为 cnt，每行驶 1 单位距离消耗 1 单位电量，且花费 1 单位时间\n// 小明想选择电动车作为代步工具。地图上共有 N 个景点，景点编号为 0 ~ N-1\n// 他将地图信息以 [城市 A 编号,城市 B 编号,两城市间距离] 格式整理在在二维数组 paths，\n// 表示城市 A、B 间存在双向通路。\n// 初始状态，电动车电量为 0。每个城市都设有充电桩，\n// charge[i] 表示第 i 个城市每充 1 单位电量需要花费的单位时间。\n// 请返回小明最少需要花费多少单位时间从起点城市 start 抵达终点城市 end\n// 测试链接 : https://leetcode.cn/problems/DFPeFJ/\npublic class Code05_VisitCityMinCost {\n\n\t// 电动车总电量，cnt\n\tpublic static int electricCarPlan(int[][] paths, int cnt, int start, int end, int[] charge) {\n\t\tint n = charge.length;\n\t\tArrayList<ArrayList<int[]>> graph = new ArrayList<>();\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tgraph.add(new ArrayList<>());\n\t\t}\n\t\tfor (int[] path : paths) {\n\t\t\tgraph.get(path[0]).add(new int[] { path[1], path[2] });\n\t\t\tgraph.get(path[1]).add(new int[] { path[0], path[2] });\n\t\t}\n\t\t// n : 0 ~ n-1，不代表图上的点\n\t\t// (点，到达这个点的电量)图上的点！\n\t\tint[][] distance = new int[n][cnt + 1];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j <= cnt; j++) {\n\t\t\t\tdistance[i][j] = Integer.MAX_VALUE;\n\t\t\t}\n\t\t}\n\t\tdistance[start][0] = 0;\n\t\tboolean[][] visited = new boolean[n][cnt + 1];\n\t\t// 0 : 当前点\n\t\t// 1 : 来到当前点的电量\n\t\t// 2 : 花费时间\n\t\tPriorityQueue<int[]> heap = new PriorityQueue<int[]>((a, b) -> (a[2] - b[2]));\n\t\theap.add(new int[] { start, 0, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] record = heap.poll();\n\t\t\tint cur = record[0];\n\t\t\tint power = record[1];\n\t\t\tint cost = record[2];\n\t\t\tif (visited[cur][power]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tif (cur == end) {\n\t\t\t\t// 常见剪枝\n\t\t\t\t// 发现终点直接返回\n\t\t\t\t// 不用等都结束\n\t\t\t\treturn cost;\n\t\t\t}\n\t\t\tvisited[cur][power] = true;\n\t\t\tif (power < cnt) {\n\t\t\t\t// 充一格电\n\t\t\t\t// cur, power+1\n\t\t\t\tif (!visited[cur][power + 1] && cost + charge[cur] < distance[cur][power + 1]) {\n\t\t\t\t\tdistance[cur][power + 1] = cost + charge[cur];\n\t\t\t\t\theap.add(new int[] { cur, power + 1, cost + charge[cur] });\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int[] edge : graph.get(cur)) {\n\t\t\t\t// 不充电去别的城市\n\t\t\t\tint nextCity = edge[0];\n\t\t\t\tint restPower = power - edge[1];\n\t\t\t\tint nextCost = cost + edge[1];\n\t\t\t\tif (restPower >= 0 && !visited[nextCity][restPower] && nextCost < distance[nextCity][restPower]) {\n\t\t\t\t\tdistance[nextCity][restPower] = nextCost;\n\t\t\t\t\theap.add(new int[] { nextCity, restPower, nextCost });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code05_VisitCityMinCost.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6f443429-9c56-49fd-80b0-3921cf677296	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\n// 飞行路线（语言提供的堆）\n// Alice和Bob现在要乘飞机旅行，他们选择了一家相对便宜的航空公司\n// 该航空公司一共在n个城市设有业务，设这些城市分别标记为0 ~ n−1\n// 一共有m种航线，每种航线连接两个城市，并且航线有一定的价格\n// Alice 和 Bob 现在要从一个城市沿着航线到达另一个城市，途中可以进行转机\n// 航空公司对他们这次旅行也推出优惠，他们可以免费在最多k种航线上搭乘飞机\n// 那么 Alice 和 Bob 这次出行最少花费多少\n// 测试链接 : https://www.luogu.com.cn/problem/P4568\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.PriorityQueue;\n\npublic class Code06_FlightPath1 {\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int MAXM = 100001;\n\n\tpublic static int MAXK = 11;\n\n\t// 链式前向星建图需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// Dijkstra需要\n\tpublic static int[][] distance = new int[MAXN][MAXK];\n\n\tpublic static boolean[][] visited = new boolean[MAXN][MAXK];\n\n\t// 用语言自己提供的堆\n\t// 动态结构，不推荐\n\t// 0 : 到达的城市编号\n\t// 1 : 已经使用的免单次数\n\t// 2 : 沿途的花费\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[2] - b[2]);\n\n\tpublic static int n, m, k, s, t;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tfor (int j = 0; j <= k; j++) {\n\t\t\t\tdistance[i][j] = Integer.MAX_VALUE;\n\t\t\t\tvisited[i][j] = false;\n\t\t\t}\n\t\t}\n\t\theap.clear();\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken(); m = (int) in.nval;\n\t\t\tin.nextToken(); k = (int) in.nval;\n\t\t\tin.nextToken(); s = (int) in.nval;\n\t\t\tin.nextToken(); t = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0, a, b, c; i < m; i++) {\n\t\t\t\tin.nextToken(); a = (int) in.nval;\n\t\t\t\tin.nextToken(); b = (int) in.nval;\n\t\t\t\tin.nextToken(); c = (int) in.nval;\n\t\t\t\taddEdge(a, b, c);\n\t\t\t\taddEdge(b, a, c);\n\t\t\t}\n\t\t\tout.println(dijkstra());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int dijkstra() {\n\t\tdistance[s][0] = 0;\n\t\theap.add(new int[] { s, 0, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] record = heap.poll();\n\t\t\tint u = record[0];\n\t\t\tint use = record[1];\n\t\t\tint cost = record[2];\n\t\t\tif (visited[u][use]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u][use] = true;\n\t\t\tif (u == t) {\n\t\t\t\t// 常见剪枝\n\t\t\t\t// 发现终点直接返回\n\t\t\t\t// 不用等都结束\n\t\t\t\treturn cost;\n\t\t\t}\n\t\t\tfor (int ei = head[u], v, w; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tw = weight[ei];\n\t\t\t\tif (use < k && distance[v][use + 1] > distance[u][use]) {\n\t\t\t\t\t// 使用免费\n\t\t\t\t\tdistance[v][use + 1] = distance[u][use];\n\t\t\t\t\theap.add(new int[] { v, use + 1, distance[v][use + 1] });\n\t\t\t\t}\n\t\t\t\tif (distance[v][use] > distance[u][use] + w) {\n\t\t\t\t\t// 不用免费\n\t\t\t\t\tdistance[v][use] = distance[u][use] + w;\n\t\t\t\t\theap.add(new int[] { v, use, distance[v][use] });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code06_FlightPath1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
439cb8d4-35a4-4fd3-9458-e346f3ad6eae	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class064;\n\n// 飞行路线（自己手撸的堆）\n// Alice和Bob现在要乘飞机旅行，他们选择了一家相对便宜的航空公司\n// 该航空公司一共在n个城市设有业务，设这些城市分别标记为0 ~ n−1\n// 一共有m种航线，每种航线连接两个城市，并且航线有一定的价格\n// Alice 和 Bob 现在要从一个城市沿着航线到达另一个城市，途中可以进行转机\n// 航空公司对他们这次旅行也推出优惠，他们可以免费在最多k种航线上搭乘飞机\n// 那么 Alice 和 Bob 这次出行最少花费多少\n// 测试链接 : https://www.luogu.com.cn/problem/P4568\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_FlightPath2 {\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int MAXM = 100001;\n\n\tpublic static int MAXK = 11;\n\n\t// 链式前向星建图需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// Dijkstra需要\n\tpublic static int[][] distance = new int[MAXN][MAXK];\n\n\tpublic static boolean[][] visited = new boolean[MAXN][MAXK];\n\n\t// 自己写的普通堆，静态结构，推荐\n\t// 注意是自己写的普通堆，不是反向索引堆\n\t// 因为(点编号，使用免费路线的次数)，两个参数的组合才是图中的点\n\t// 两个参数的组合对应一个点(一个堆的下标)，所以反向索引堆不好写\n\t// 其实也能实现，二维点变成一维下标即可\n\t// 但是会造成很多困惑，索性算了，就手写普通堆吧\n\tpublic static int[][] heap = new int[MAXM * MAXK][3];\n\n\tpublic static int heapSize;\n\n\tpublic static int n, m, k, s, t;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\theapSize = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tfor (int j = 0; j <= k; j++) {\n\t\t\t\tdistance[i][j] = Integer.MAX_VALUE;\n\t\t\t\tvisited[i][j] = false;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void push(int u, int t, int c) {\n\t\theap[heapSize][0] = u;\n\t\theap[heapSize][1] = t;\n\t\theap[heapSize][2] = c;\n\t\tint i = heapSize++;\n\t\twhile (heap[i][2] < heap[(i - 1) / 2][2]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\tpublic static int u, use, cost;\n\n\tpublic static void pop() {\n\t\tu = heap[0][0];\n\t\tuse = heap[0][1];\n\t\tcost = heap[0][2];\n\t\tswap(0, --heapSize);\n\t\theapify(0);\n\t}\n\n\tpublic static void heapify(int i) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < heapSize) {\n\t\t\tint best = l + 1 < heapSize && heap[l + 1][2] < heap[l][2] ? l + 1 : l;\n\t\t\tbest = heap[best][2] < heap[i][2] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static void swap(int i, int j) {\n\t\tint[] tmp = heap[i];\n\t\theap[i] = heap[j];\n\t\theap[j] = tmp;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken(); m = (int) in.nval;\n\t\t\tin.nextToken(); k = (int) in.nval;\n\t\t\tin.nextToken(); s = (int) in.nval;\n\t\t\tin.nextToken(); t = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0, a, b, c; i < m; i++) {\n\t\t\t\tin.nextToken(); a = (int) in.nval;\n\t\t\t\tin.nextToken(); b = (int) in.nval;\n\t\t\t\tin.nextToken(); c = (int) in.nval;\n\t\t\t\taddEdge(a, b, c);\n\t\t\t\taddEdge(b, a, c);\n\t\t\t}\n\t\t\tout.println(dijkstra());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int dijkstra() {\n\t\tdistance[s][0] = 0;\n\t\tpush(s, 0, 0);\n\t\twhile (heapSize > 0) {\n\t\t\tpop();\n\t\t\tif (visited[u][use]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u][use] = true;\n\t\t\tif (u == t) {\n\t\t\t\t// 常见剪枝\n\t\t\t\t// 发现终点直接返回\n\t\t\t\t// 不用等都结束\n\t\t\t\treturn cost;\n\t\t\t}\n\t\t\tfor (int ei = head[u], v, w; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tw = weight[ei];\n\t\t\t\tif (use < k && distance[v][use + 1] > distance[u][use]) {\n\t\t\t\t\t// 使用免费\n\t\t\t\t\tdistance[v][use + 1] = distance[u][use];\n\t\t\t\t\tpush(v, use + 1, distance[v][use + 1]);\n\t\t\t\t}\n\t\t\t\tif (distance[v][use] > distance[u][use] + w) {\n\t\t\t\t\t// 不用免费\n\t\t\t\t\tdistance[v][use] = distance[u][use] + w;\n\t\t\t\t\tpush(v, use, distance[v][use]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n}\n	模板：Code06_FlightPath2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
432603ac-7ea9-4ba2-a21d-9edfb8641a8b	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 跳楼机\n// 一座大楼一共有h层，楼层编号1~h，有如下四种移动方式\n// 1, 向上移动x层\n// 2, 向上移动y层\n// 3, 向上移动z层\n// 4, 回到1层\n// 假设你正在第1层，请问大楼里有多少楼层你可以到达\n// 1 <= h <= 2^63 - 1\n// 1 <= x、y、z <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3403\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\nimport java.util.StringTokenizer;\n\npublic class Code01_Elevator {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXM = 200001;\n\n\tpublic static long h;\n\n\tpublic static int x, y, z;\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static long[] weight = new long[MAXM];\n\n\tpublic static int cnt;\n\n\t// dijkstra算法需要\n\t// 0 : 当前节点\n\t// 1 : 源点到当前点距离\n\tpublic static PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> a[1] <= b[1] ? -1 : 1);\n\n\tpublic static long[] distance = new long[MAXN];\n\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\theap.clear();\n\t\tArrays.fill(head, 0, x, 0);\n\t\tArrays.fill(distance, 0, x, Long.MAX_VALUE);\n\t\tArrays.fill(visited, 0, x, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, long w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 来自讲解064，dijkstra算法\n\tpublic static void dijkstra() {\n\t\theap.add(new long[] { 0, 0 });\n\t\tdistance[0] = 0;\n\t\tlong[] cur;\n\t\tint u;\n\t\tlong w;\n\t\twhile (!heap.isEmpty()) {\n\t\t\tcur = heap.poll();\n\t\t\tu = (int) cur[0];\n\t\t\tw = cur[1];\n\t\t\tif (visited[u]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u] = true;\n\t\t\tfor (int ei = head[u], v; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tif (!visited[v] && distance[v] > w + weight[ei]) {\n\t\t\t\t\tdistance[v] = w + weight[ei];\n\t\t\t\t\theap.add(new long[] { v, distance[v] });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tdijkstra();\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i < x; i++) {\n\t\t\tif (distance[i] <= h) {\n\t\t\t\tans += (h - distance[i]) / x + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\th = io.nextLong() - 1;\n\t\tx = io.nextInt();\n\t\ty = io.nextInt();\n\t\tz = io.nextInt();\n\t\tprepare();\n\t\tfor (int i = 0; i < x; i++) {\n\t\t\taddEdge(i, (i + y) % x, y);\n\t\t\taddEdge(i, (i + z) % x, z);\n\t\t}\n\t\tio.println(compute());\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code01_Elevator.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9817bfd4-dfa0-433c-bea0-80c188c99d08	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 牛场围栏\n// 给定一个长度为n的数组arr, arr[i]代表第i种木棍的长度，每种木棍有无穷多个\n// 给定一个正数m，表示你可以把任何一根木棍消去最多m的长度，同一种木棍可以消去不同的长度\n// 你可以随意拼接木棍形成一个长度，返回不能拼出来的长度中，最大值是多少\n// 如果你可以拼出所有的长度，返回-1\n// 如果不能拼出来的长度有无穷多，返回-1\n// 1 <= n <= 100\n// 1 <= arr[i] <= 3000\n// 1 <= m <= 3000\n// 测试链接 : https://www.luogu.com.cn/problem/P2662\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\npublic class Code02_CattleFence {\n\n\tpublic static int MAXN = 101;\n\n\tpublic static int MAXV = 3001;\n\n\tpublic static int MAXM = 30001;\n\n\tpublic static int inf = Integer.MAX_VALUE;\n\n\tpublic static int n, m, x;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static boolean[] set = new boolean[MAXV];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXV];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// dijkstra算法需要\n\t// 0 : 当前节点\n\t// 1 : 源点到当前点距离\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[1] - b[1]);\n\n\tpublic static int[] distance = new int[MAXV];\n\n\tpublic static boolean[] visited = new boolean[MAXV];\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\theap.clear();\n\t\tArrays.fill(set, false);\n\t\tArrays.fill(head, 0, x, 0);\n\t\tArrays.fill(distance, 0, x, inf);\n\t\tArrays.fill(visited, 0, x, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 来自讲解064，dijkstra算法\n\tpublic static void dijkstra() {\n\t\theap.add(new int[] { 0, 0 });\n\t\tdistance[0] = 0;\n\t\tint[] cur;\n\t\tint u, w;\n\t\twhile (!heap.isEmpty()) {\n\t\t\tcur = heap.poll();\n\t\t\tu = (int) cur[0];\n\t\t\tw = cur[1];\n\t\t\tif (visited[u]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u] = true;\n\t\t\tfor (int ei = head[u], v; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tif (!visited[v] && distance[v] > w + weight[ei]) {\n\t\t\t\t\tdistance[v] = w + weight[ei];\n\t\t\t\t\theap.add(new int[] { v, distance[v] });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int compute() {\n\t\tint ans = 0;\n\t\tif (x == 1) {\n\t\t\tans = -1;\n\t\t} else {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = Math.max(1, arr[i] - m); j <= arr[i]; j++) {\n\t\t\t\t\tif (!set[j]) {\n\t\t\t\t\t\tset[j] = true;\n\t\t\t\t\t\tfor (int k = 0; k < x; k++) {\n\t\t\t\t\t\t\taddEdge(k, (k + j) % x, j);\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tdijkstra();\n\t\t\tfor (int i = 1; i < x; i++) {\n\t\t\t\tif (distance[i] == inf) {\n\t\t\t\t\tans = -1;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tans = Math.max(ans, distance[i] - x);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tx = inf;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t\tx = Math.min(x, Math.max(1, arr[i] - m));\n\t\t}\n\t\tprepare();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_CattleFence.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
627bfef2-0b21-41e8-90bc-df0f6b124a79	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 正整数倍的最小数位和\n// 给定一个整数k，求一个k的正整数倍s，使得在十进制下，s的数位累加和最小\n// 2 <= k <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_arc084_b\n// 测试链接 : https://atcoder.jp/contests/abc077/tasks/arc084_b\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.ArrayDeque;\n\npublic class Code03_SmallMultiple {\n\n\tpublic static int MAXK = 100001;\n\n\tpublic static int k;\n\n\t// 01bfs需要\n\tpublic static ArrayDeque<int[]> deque = new ArrayDeque<>();\n\n\tpublic static boolean[] visit = new boolean[MAXK];\n\n\t// 来自讲解062，01bfs\n\tpublic static int bfs() {\n\t\tdeque.clear();\n\t\tdeque.add(new int[] { 1, 1 });\n\t\tint[] cur;\n\t\tint mod, cost;\n\t\twhile (!deque.isEmpty()) {\n\t\t\tcur = deque.pollFirst();\n\t\t\tmod = cur[0];\n\t\t\tcost = cur[1];\n\t\t\tif (!visit[mod]) {\n\t\t\t\tvisit[mod] = true;\n\t\t\t\tif (mod == 0) {\n\t\t\t\t\treturn cost;\n\t\t\t\t}\n\t\t\t\tdeque.addFirst(new int[] { (mod * 10) % k, cost });\n\t\t\t\tdeque.addLast(new int[] { (mod + 1) % k, cost + 1 });\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tout.println(bfs());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_SmallMultiple.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0e0eaf51-df1f-414f-a228-42275e6ca444	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 墨墨的等式(dijkstra算法)\n// 一共有n种正数，每种数可以选择任意个，个数不能是负数\n// 那么一定有某些数值可以由这些数字累加得到\n// 请问在[l...r]范围上，有多少个数能被累加得到\n// 0 <= n <= 12\n// 0 <= 数值范围 <= 5 * 10^5\n// 1 <= l <= r <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P2371\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\npublic class Code04_MomoEquation1 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int MAXM = 5000001;\n\n\tpublic static int n, x;\n\n\tpublic static long l, r;\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static long[] weight = new long[MAXM];\n\n\tpublic static int cnt;\n\n\t// dijkstra算法需要\n\t// 0 : 当前节点\n\t// 1 : 源点到当前点距离\n\tpublic static PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> a[1] <= b[1] ? -1 : 1);\n\n\tpublic static long[] distance = new long[MAXN];\n\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\theap.clear();\n\t\tArrays.fill(head, 0, x, 0);\n\t\tArrays.fill(distance, 0, x, Long.MAX_VALUE);\n\t\tArrays.fill(visited, 0, x, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, long w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dijkstra() {\n\t\theap.add(new long[] { 0, 0 });\n\t\tdistance[0] = 0;\n\t\tlong[] cur;\n\t\tint u;\n\t\tlong w;\n\t\twhile (!heap.isEmpty()) {\n\t\t\tcur = heap.poll();\n\t\t\tu = (int) cur[0];\n\t\t\tw = cur[1];\n\t\t\tif (visited[u]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tvisited[u] = true;\n\t\t\tfor (int ei = head[u], v; ei > 0; ei = next[ei]) {\n\t\t\t\tv = to[ei];\n\t\t\t\tif (!visited[v] && distance[v] > w + weight[ei]) {\n\t\t\t\t\tdistance[v] = w + weight[ei];\n\t\t\t\t\theap.add(new long[] { v, distance[v] });\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tdijkstra();\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i < x; i++) {\n\t\t\tif (r >= distance[i]) {\n\t\t\t\tans += (r - distance[i]) / x + 1;\n\t\t\t}\n\t\t\tif (l >= distance[i]) {\n\t\t\t\tans -= (l - distance[i]) / x + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tl = (long) in.nval - 1;\n\t\tin.nextToken();\n\t\tr = (long) in.nval;\n\t\tx = 0;\n\t\tfor (int i = 1, vi; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tvi = (int) in.nval;\n\t\t\tif (vi != 0) {\n\t\t\t\tif (x == 0) {\n\t\t\t\t\tx = vi;\n\t\t\t\t\tprepare();\n\t\t\t\t} else {\n\t\t\t\t\tfor (int j = 0; j < x; j++) {\n\t\t\t\t\t\taddEdge(j, (j + vi) % x, vi);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_MomoEquation1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5aa92a17-e71b-46b4-bbf3-00f3478186c3	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 墨墨的等式(两次转圈法)\n// 一共有n种正数，每种数可以选择任意个，个数不能是负数\n// 那么一定有某些数值可以由这些数字累加得到\n// 请问在[l...r]范围上，有多少个数能被累加得到\n// 0 <= n <= 12\n// 0 <= 数值范围 <= 5 * 10^5\n// 1 <= l <= r <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P2371\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_MomoEquation2 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static long inf = Long.MAX_VALUE;\n\n\tpublic static int[] v = new int[MAXN];\n\n\tpublic static long[] dist = new long[MAXN];\n\n\tpublic static int n, x;\n\n\tpublic static long l, r;\n\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static long compute() {\n\t\tArrays.sort(v, 1, n + 1);\n\t\tint size = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (v[i] != 0) {\n\t\t\t\tv[++size] = v[i];\n\t\t\t}\n\t\t}\n\t\tif (size == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tx = v[1];\n\t\tArrays.fill(dist, 0, x, inf);\n\t\tdist[0] = 0;\n\t\tfor (int i = 2, d; i <= size; i++) { // 出现基准数之外的其他数，更新最短路\n\t\t\td = gcd(v[i], x); // 求最大公约数\n\t\t\tfor (int j = 0; j < d; j++) { // j是每个子环的起点\n\t\t\t\tfor (int cur = j, next, circle = 0; circle < 2; circle += cur == j ? 1 : 0) {\n\t\t\t\t\tnext = (cur + v[i]) % x;\n\t\t\t\t\tif (dist[cur] != inf) {\n\t\t\t\t\t\tdist[next] = Math.min(dist[next], dist[cur] + v[i]);\n\t\t\t\t\t}\n\t\t\t\t\tcur = next;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i < x; i++) {\n\t\t\tif (r >= dist[i]) {\n\t\t\t\tans += Math.max(0, (r - dist[i]) / x + 1);\n\t\t\t}\n\t\t\tif (l >= dist[i]) {\n\t\t\t\tans -= Math.max(0, (l - dist[i]) / x + 1);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tl = (long) in.nval - 1;\n\t\tin.nextToken();\n\t\tr = (long) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tv[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_MomoEquation2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
579adbae-a2dd-4d5f-942a-a7849110a276	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 墨墨的等式(不排序+两次转圈法)\n// 不排序也一样能通过，本文件实现没有任何新内容，只是去掉了排序逻辑\n// 一共有n种正数，每种数可以选择任意个，个数不能是负数\n// 那么一定有某些数值可以由这些数字累加得到\n// 请问在[l...r]范围上，有多少个数能被累加得到\n// 0 <= n <= 12\n// 0 <= 数值范围 <= 5 * 10^5\n// 1 <= l <= r <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P2371\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_MomoEquation3 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static long inf = Long.MAX_VALUE;\n\n\tpublic static int[] v = new int[MAXN];\n\n\tpublic static long[] dist = new long[MAXN];\n\n\tpublic static int n, size, x;\n\n\tpublic static long l, r;\n\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static long compute() {\n\t\tx = v[1];\n\t\tArrays.fill(dist, 0, x, inf);\n\t\tdist[0] = 0;\n\t\tfor (int i = 2, d; i <= size; i++) {\n\t\t\td = gcd(v[i], x);\n\t\t\tfor (int j = 0; j < d; j++) {\n\t\t\t\tfor (int cur = j, next, circle = 0; circle < 2; circle += cur == j ? 1 : 0) {\n\t\t\t\t\tnext = (cur + v[i]) % x;\n\t\t\t\t\tif (dist[cur] != inf) {\n\t\t\t\t\t\tdist[next] = Math.min(dist[next], dist[cur] + v[i]);\n\t\t\t\t\t}\n\t\t\t\t\tcur = next;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i < x; i++) {\n\t\t\tif (r >= dist[i]) {\n\t\t\t\tans += Math.max(0, (r - dist[i]) / x + 1);\n\t\t\t}\n\t\t\tif (l >= dist[i]) {\n\t\t\t\tans -= Math.max(0, (l - dist[i]) / x + 1);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tsize = 0;\n\t\tin.nextToken();\n\t\tl = (long) in.nval - 1;\n\t\tin.nextToken();\n\t\tr = (long) in.nval;\n\t\tfor (int i = 1, num; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tnum = (int) in.nval;\n\t\t\tif (num != 0) {\n\t\t\t\tv[++size] = num;\n\t\t\t}\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_MomoEquation3.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d2e1ba8c-05a7-4473-a8de-63ca607bd563	980c727f-f969-4eac-9ccf-bdf918b2d2c2	java	package class140;\n\n// 无法组成的最大值\n// 一共有a、b两种面值的硬币，a和b一定互质，每种硬币都有无限个\n// 返回a和b无法组成的钱数中，最大值是多少\n// 题目的输入保证存在最大的无法组成的钱数\n// 1 <= a、b <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3951\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code05_LargestUnattainable {\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tlong a = (long) in.nval;\n\t\tin.nextToken();\n\t\tlong b = (long) in.nval;\n\t\tout.println(a * b - a - b);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_LargestUnattainable.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ce238df5-d657-4215-bfde-ca806fa68086	c4d632e0-14bc-4c2f-9bcc-3410dc36b49c	java	package class143;\n\n// 背包(两次转圈法)\n// 一共有n种物品，第i种物品的体积为v[i]，价值为c[i]，每种物品可以选择任意个，个数不能是负数\n// 一共有m条查询，每次查询都会给定jobv，代表体积的要求\n// 要求挑选物品的体积和一定要严格是jobv，返回能得到的最大价值和\n// 如果没有方案能正好凑满jobv，返回-1\n// 1 <= n <= 50\n// 1 <= m <= 10^5\n// 1 <= v[i] <= 10^5\n// 1 <= c[i] <= 10^6\n// 10^11 <= jobv <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P9140\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_Knapsack {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static long inf = Long.MIN_VALUE;\n\n\tpublic static int[] v = new int[MAXN];\n\n\tpublic static int[] c = new int[MAXN];\n\n\t// dp[i] : 总体积为某数，先尽可能用基准物品填入，剩余的体积为i\n\t// 可以去掉若干基准物品，加入若干其他物品，最终凑齐总体积\n\t// 能获得的最大补偿是多少\n\tpublic static long[] dp = new long[MAXN];\n\n\tpublic static int n, m, x, y;\n\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static void compute() {\n\t\tArrays.fill(dp, 0, x, inf);\n\t\tdp[0] = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (v[i] != x) {\n\t\t\t\tfor (int j = 0, d = gcd(v[i], x); j < d; j++) {\n\t\t\t\t\tfor (int cur = j, next, circle = 0; circle < 2; circle += cur == j ? 1 : 0) {\n\t\t\t\t\t\tnext = (cur + v[i]) % x;\n\t\t\t\t\t\tif (dp[cur] != inf) {\n\t\t\t\t\t\t\tdp[next] = Math.max(dp[next], dp[cur] - (long) ((cur + v[i]) / x) * y + c[i]);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tcur = next;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tdouble best = 0, ratio;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tv[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tc[i] = (int) in.nval;\n\t\t\tratio = (double) c[i] / v[i];\n\t\t\tif (ratio > best) {\n\t\t\t\tbest = ratio;\n\t\t\t\tx = v[i];\n\t\t\t\ty = c[i];\n\t\t\t}\n\t\t}\n\t\tcompute();\n\t\tlong jobv;\n\t\tfor (int i = 1, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tjobv = (long) in.nval;\n\t\t\tv = (int) (jobv % x);\n\t\t\tif (dp[v] == inf) {\n\t\t\t\tout.println("-1");\n\t\t\t} else {\n\t\t\t\tout.println(jobv / x * y + dp[v]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_Knapsack.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
7af83677-4ab9-4b83-b340-e990074c5754	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\n// Kruskal算法模版（洛谷）\n// 静态空间实现\n// 测试链接 : https://www.luogu.com.cn/problem/P3366\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\n// 时间复杂度O(m * log m) + O(n + m)\npublic class Code01_Kruskal {\n\n\tpublic static int MAXN = 5001;\n\n\tpublic static int MAXM = 200001;\n\n\tpublic static int[] father = new int[MAXN];\n\n\t// u, v, w\n\tpublic static int[][] edges = new int[MAXM][3];\n\n\tpublic static int n, m;\n\n\tpublic static void build() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\t// 如果x和y本来就是一个集合，返回false\n\t// 如果x和y不是一个集合，合并之后返回true\n\tpublic static boolean union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx != fy) {\n\t\t\tfather[fx] = fy;\n\t\t\treturn true;\n\t\t} else {\n\t\t\treturn false;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][0] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][1] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][2] = (int) in.nval;\n\t\t\t}\n\t\t\tArrays.sort(edges, 0, m, (a, b) -> a[2] - b[2]);\n\t\t\tint ans = 0;\n\t\t\tint edgeCnt = 0;\n\t\t\tfor (int[] edge : edges) {\n\t\t\t\tif (union(edge[0], edge[1])) {\n\t\t\t\t\tedgeCnt++;\n\t\t\t\t\tans += edge[2];\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(edgeCnt == n - 1 ? ans : "orz");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Kruskal.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5750a16c-a50a-4003-afcb-6fbd670c379e	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\n// Prim算法模版（洛谷）\n// 动态空间实现\n// 测试链接 : https://www.luogu.com.cn/problem/P3366\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.ArrayList;\nimport java.util.PriorityQueue;\n\n// 时间复杂度O(n + m) + O(m * log m)\npublic class Code02_PrimDynamic {\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tArrayList<ArrayList<int[]>> graph = new ArrayList<>();\n\t\t\tint n = (int) in.nval;\n\t\t\tfor (int i = 0; i <= n; i++) {\n\t\t\t\tgraph.add(new ArrayList<>());\n\t\t\t}\n\t\t\tin.nextToken();\n\t\t\tint m = (int) in.nval;\n\t\t\tfor (int i = 0, u, v, w; i < m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tu = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tw = (int) in.nval;\n\t\t\t\tgraph.get(u).add(new int[] { v, w });\n\t\t\t\tgraph.get(v).add(new int[] { u, w });\n\t\t\t}\n\t\t\t// int[] record\n\t\t\t// record[0] : 到达的节点\n\t\t\t// record[1] : 到达的花费\n\t\t\tPriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[1] - b[1]);\n\t\t\tfor (int[] edge : graph.get(1)) {\n\t\t\t\theap.add(edge);\n\t\t\t}\n\t\t\t// 哪些节点已经发现过了\n\t\t\tboolean[] set = new boolean[n + 1];\n\t\t\tint nodeCnt = 1;\n\t\t\tset[1] = true;\n\t\t\tint ans = 0;\n\t\t\twhile (!heap.isEmpty()) {\n\t\t\t\tint[] edge = heap.poll();\n\t\t\t\tint next = edge[0];\n\t\t\t\tint cost = edge[1];\n\t\t\t\tif (!set[next]) {\n\t\t\t\t\tnodeCnt++;\n\t\t\t\t\tset[next] = true;\n\t\t\t\t\tans += cost;\n\t\t\t\t\tfor (int[] e : graph.get(next)) {\n\t\t\t\t\t\theap.add(e);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(nodeCnt == n ? ans : "orz");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code02_PrimDynamic.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0a05e039-6c78-40ca-a233-d7dc8cc12218	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\n// Prim算法优化（洛谷）\n// 静态空间实现\n// 时间复杂度O(n + m) + O((m+n) * log n)\n// 测试链接 : https://www.luogu.com.cn/problem/P3366\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\n// 建图用链式前向星\n// 堆也是用数组结构手写的、且只和节点个数有关\n// 这个实现留给有需要的同学\n// 但是一般情况下并不需要做到这个程度\n\npublic class Code02_PrimStatic {\n\n\tpublic static int MAXN = 5001;\n\n\tpublic static int MAXM = 400001;\n\n\tpublic static int n, m;\n\n\t// 链式前向星建图\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int[] weight = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// 改写的堆结构\n\tpublic static int[][] heap = new int[MAXN][2];\n\n\t// where[v] = -1，表示v这个节点，从来没有进入过堆\n\t// where[v] = -2，表示v这个节点，已经弹出过了\n\t// where[v] = i(>=0)，表示v这个节点，在堆上的i位置\n\tpublic static int[] where = new int[MAXN];\n\n\t// 堆的大小\n\tpublic static int heapSize;\n\n\t// 找到的节点个数\n\tpublic static int nodeCnt;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\theapSize = 0;\n\t\tnodeCnt = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(where, 1, n + 1, -1);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 当前处理的是编号为ei的边！\n\tpublic static void addOrUpdateOrIgnore(int ei) {\n\t\tint v = to[ei];\n\t\tint w = weight[ei];\n\t\t// 去往v点，权重w\n\t\tif (where[v] == -1) {\n\t\t\t// v这个点，从来没有进入过堆！\n\t\t\theap[heapSize][0] = v;\n\t\t\theap[heapSize][1] = w;\n\t\t\twhere[v] = heapSize++;\n\t\t\theapInsert(where[v]);\n\t\t} else if (where[v] >= 0) {\n\t\t\t// v这个点的记录，在堆上的位置是where[v]\n\t\t\theap[where[v]][1] = Math.min(heap[where[v]][1], w);\n\t\t\theapInsert(where[v]);\n\t\t}\n\t}\n\n\tpublic static void heapInsert(int i) {\n\t\twhile (heap[i][1] < heap[(i - 1) / 2][1]) {\n\t\t\tswap(i, (i - 1) / 2);\n\t\t\ti = (i - 1) / 2;\n\t\t}\n\t}\n\n\tpublic static int u;\n\n\tpublic static int w;\n\n\t// 堆顶的记录：节点 -> u、到节点的花费 -> w\n\tpublic static void pop() {\n\t\tu = heap[0][0];\n\t\tw = heap[0][1];\n\t\tswap(0, --heapSize);\n\t\theapify(0);\n\t\twhere[u] = -2;\n\t\tnodeCnt++;\n\t}\n\n\tpublic static void heapify(int i) {\n\t\tint l = i * 2 + 1;\n\t\twhile (l < heapSize) {\n\t\t\tint best = l + 1 < heapSize && heap[l + 1][1] < heap[l][1] ? l + 1 : l;\n\t\t\tbest = heap[best][1] < heap[i][1] ? best : i;\n\t\t\tif (best == i) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tswap(best, i);\n\t\t\ti = best;\n\t\t\tl = i * 2 + 1;\n\t\t}\n\t}\n\n\tpublic static boolean isEmpty() {\n\t\treturn heapSize == 0;\n\t}\n\n\t// 堆上，i位置的信息 和 j位置的信息 交换！\n\tpublic static void swap(int i, int j) {\n\t\tint a = heap[i][0];\n\t\tint b = heap[j][0];\n\t\twhere[a] = j;\n\t\twhere[b] = i;\n\t\tint[] tmp = heap[i];\n\t\theap[i] = heap[j];\n\t\theap[j] = tmp;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0, u, v, w; i < m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tu = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tw = (int) in.nval;\n\t\t\t\taddEdge(u, v, w);\n\t\t\t\taddEdge(v, u, w);\n\t\t\t}\n\t\t\tint ans = prim();\n\t\t\tout.println(nodeCnt == n ? ans : "orz");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int prim() {\n\t\t// 1节点出发\n\t\tnodeCnt = 1;\n\t\twhere[1] = -2;\n\t\tfor (int ei = head[1]; ei > 0; ei = next[ei]) {\n\t\t\taddOrUpdateOrIgnore(ei);\n\t\t}\n\t\tint ans = 0;\n\t\twhile (!isEmpty()) {\n\t\t\tpop();\n\t\t\tans += w;\n\t\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\t\taddOrUpdateOrIgnore(ei);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}	模板：Code02_PrimStatic.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
60915991-e49e-4d00-9234-667a0759622f	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\nimport java.util.Arrays;\n\n// 水资源分配优化\n// 村里面一共有 n 栋房子。我们希望通过建造水井和铺设管道来为所有房子供水。\n// 对于每个房子 i，我们有两种可选的供水方案：一种是直接在房子内建造水井\n// 成本为 wells[i - 1] （注意 -1 ，因为 索引从0开始 ）\n// 另一种是从另一口井铺设管道引水，数组 pipes 给出了在房子间铺设管道的成本，\n// 其中每个 pipes[j] = [house1j, house2j, costj] \n// 代表用管道将 house1j 和 house2j连接在一起的成本。连接是双向的。\n// 请返回 为所有房子都供水的最低总成本\n// 测试链接 : https://leetcode.cn/problems/optimize-water-distribution-in-a-village/\npublic class Code03_OptimizeWaterDistribution {\n\n\tpublic static int minCostToSupplyWater(int n, int[] wells, int[][] pipes) {\n\t\tbuild(n);\n\t\tfor (int i = 0; i < n; i++, cnt++) {\n\t\t\t// wells : 100   30\n\t\t\t//         0(1)  1(2)\n\t\t\tedges[cnt][0] = 0;\n\t\t\tedges[cnt][1] = i + 1;\n\t\t\tedges[cnt][2] = wells[i];\n\t\t}\n\t\tfor (int i = 0; i < pipes.length; i++, cnt++) {\n\t\t\tedges[cnt][0] = pipes[i][0];\n\t\t\tedges[cnt][1] = pipes[i][1];\n\t\t\tedges[cnt][2] = pipes[i][2];\n\t\t}\n\t\tArrays.sort(edges, 0, cnt, (a, b) -> a[2] - b[2]);\n\t\tint ans = 0;\n\t\tfor (int i = 0; i < cnt; i++) {\n\t\t\tif (union(edges[i][0], edges[i][1])) {\n\t\t\t\tans += edges[i][2];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int MAXN = 10010;\n\n\tpublic static int[][] edges = new int[MAXN << 1][3];\n\n\tpublic static int cnt;\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void build(int n) {\n\t\tcnt = 0;\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\t// 如果x和y，原本是一个集合，返回false\n\t// 如果x和y，不是一个集合，合并之后后返回true\n\tpublic static boolean union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx != fy) {\n\t\t\tfather[fx] = fy;\n\t\t\treturn true;\n\t\t} else {\n\t\t\treturn false;\n\t\t}\n\t}\n\n}\n	模板：Code03_OptimizeWaterDistribution.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
03bb3dbd-8d51-4f56-8d77-1faacf69b98d	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\nimport java.util.Arrays;\n\n// 检查边长度限制的路径是否存在\n// 给你一个 n 个点组成的无向图边集 edgeList\n// 其中 edgeList[i] = [ui, vi, disi] 表示点 ui 和点 vi 之间有一条长度为 disi 的边\n// 请注意，两个点之间可能有 超过一条边 。\n// 给你一个查询数组queries ，其中 queries[j] = [pj, qj, limitj]\n// 你的任务是对于每个查询 queries[j] ，判断是否存在从 pj 到 qj 的路径\n// 且这条路径上的每一条边都 严格小于 limitj 。\n// 请你返回一个 布尔数组 answer ，其中 answer.length == queries.length\n// 当 queries[j] 的查询结果为 true 时， answer 第 j 个值为 true ，否则为 false\n// 测试链接 : https://leetcode.cn/problems/checking-existence-of-edge-length-limited-paths/\npublic class Code04_CheckingExistenceOfEdgeLengthLimit {\n\n\tpublic static boolean[] distanceLimitedPathsExist(int n, int[][] edges, int[][] queries) {\n\t\tArrays.sort(edges, (a, b) -> a[2] - b[2]);\n\t\tint m = edges.length;\n\t\tint k = queries.length;\n\t\tfor (int i = 0; i < k; i++) {\n\t\t\tquestions[i][0] = queries[i][0];\n\t\t\tquestions[i][1] = queries[i][1];\n\t\t\tquestions[i][2] = queries[i][2];\n\t\t\tquestions[i][3] = i;\n\t\t}\n\t\tArrays.sort(questions, 0, k, (a, b) -> a[2] - b[2]);\n\t\tbuild(n);\n\t\tboolean[] ans = new boolean[k];\n\t\tfor (int i = 0, j = 0; i < k; i++) {\n\t\t\t// i : 问题编号\n\t\t\t// j : 边的编号\n\t\t\tfor (; j < m && edges[j][2] < questions[i][2]; j++) {\n\t\t\t\tunion(edges[j][0], edges[j][1]);\n\t\t\t}\n\t\t\tans[questions[i][3]] = isSameSet(questions[i][0], questions[i][1]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int[][] questions = new int[MAXN][4];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void build(int n) {\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static boolean isSameSet(int x, int y) {\n\t\treturn find(x) == find(y);\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tfather[find(x)] = find(y);\n\t}\n\n}\n	模板：Code04_CheckingExistenceOfEdgeLengthLimit.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
81eacec8-1c76-4b50-bf2a-c60df6f95be7	c21e1270-21fa-4094-8da4-5440f527973e	java	package class061;\n\n// 繁忙的都市\n// 一个非常繁忙的大都市，城市中的道路十分的拥挤，于是市长决定对其中的道路进行改造\n// 城市的道路是这样分布的：城市中有n个交叉路口，有些交叉路口之间有道路相连\n// 两个交叉路口之间最多有一条道路相连接，这些道路是双向的\n// 且把所有的交叉路口直接或间接的连接起来了\n// 每条道路都有一个分值，分值越小表示这个道路越繁忙，越需要进行改造\n// 但是市政府的资金有限，市长希望进行改造的道路越少越好，于是他提出下面的要求：\n// 1. 改造的那些道路能够把所有的交叉路口直接或间接的连通起来\n// 2. 在满足要求1的情况下，改造的道路尽量少\n// 3. 在满足要求1、2的情况下，改造的那些道路中分值最大的道路分值尽量小\n// 作为市规划局的你，应当作出最佳的决策，选择哪些道路应当被修建\n// 返回选出了几条道路 以及 分值最大的那条道路的分值是多少\n// 测试链接 : https://www.luogu.com.cn/problem/P2330\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_BusyCities {\n\n\tpublic static int MAXN = 301;\n\n\tpublic static int MAXM = 8001;\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[][] edges = new int[MAXM][3];\n\n\tpublic static int n, m;\n\n\tpublic static void build() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\t// 如果x和y本来就是一个集合，返回false\n\t// 如果x和y不是一个集合，合并之后返回true\n\tpublic static boolean union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx != fy) {\n\t\t\tfather[fx] = fy;\n\t\t\treturn true;\n\t\t} else {\n\t\t\treturn false;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][0] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][1] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tedges[i][2] = (int) in.nval;\n\t\t\t}\n\t\t\tArrays.sort(edges, 0, m, (a, b) -> a[2] - b[2]);\n\t\t\tint ans = 0;\n\t\t\tint edgeCnt = 0;\n\t\t\tfor (int[] edge : edges) {\n\t\t\t\tif (union(edge[0], edge[1])) {\n\t\t\t\t\tedgeCnt++;\n\t\t\t\t\tans = Math.max(ans, edge[2]);\n\t\t\t\t}\n\t\t\t\tif (edgeCnt == n - 1) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println((n - 1) + " " + ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_BusyCities.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
98d3d0bf-990c-4ea7-b93c-be1f878b8441	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class189;\n\n// 强连通分量模版题1，java版\n// 给定一张n个点，m条边的有向图\n// 求出所有强连通分量，先打印强连通分量的数量\n// 然后打印1号点所在的强连通分量，然后打印2号点所在的强连通分量，以此类推\n// 如果当前节点属于之前的强连通分量，那就跳过，直到打印所有强连通分量\n// 打印每个强连通分量时，按照节点编号从小到大打印\n// 1 <= n <= 10^4\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/B3609\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_SCC1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sccArr = new int[MAXN];\n\tpublic static int[] sccl = new int[MAXN];\n\tpublic static int[] sccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int sccCnt;\n\n\tpublic static boolean[] sccPrint = new boolean[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) { // 树边\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) { // 回边\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\t// 如果 belong[v] != 0 就是遇到了弃边，什么也不做\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsccl[sccCnt] = idx + 1;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsccArr[++idx] = pop;\n\t\t\t} while (pop != u);\n\t\t\tsccr[sccCnt] = idx;\n\t\t}\n\t}\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\t// 迭代版\n\t// u表示当前节点\n\t// e表示u当前处理的边，如果e == 0，说明所有边都处理完了\n\t// status的具体说明如下\n\t//     如果status == -1，表示u没有遍历过任何儿子\n\t//     如果status == 0，表示u遍历到儿子v，然后发现dfn[v] == 0\n\t//         并且执行完了tarjan(v)，对应递归版for循环中的第一个分支\n\t//     如果status == 1，表示u遍历到儿子v，然后发现dfn[v] != 0\n\t//         对应递归版for循环中的第二个分支\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\t// (当前节点, 状态, 边)先进入栈\n\t\t\t\t\t// (儿子节点, 状态, 边)再进入栈\n\t\t\t\t\t// 那么儿子节点的tarjan过程会先执行\n\t\t\t\t\t// 等到处理当前节点时，low[儿子节点]信息就生成好了\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsccl[sccCnt] = idx + 1;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t\tsccr[sccCnt] = idx;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tout.println(sccCnt);\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tArrays.sort(sccArr, sccl[i], sccr[i] + 1);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tint scc = belong[i];\n\t\t\tif (!sccPrint[scc]) {\n\t\t\t\tsccPrint[scc] = true;\n\t\t\t\tfor (int j = sccl[scc]; j <= sccr[scc]; j++) {\n\t\t\t\t\tout.print(sccArr[j] + " ");\n\t\t\t\t}\n\t\t\t\tout.println();\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_SCC1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
