a12c8fa1-506f-4d63-8da1-0f4276691f20	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 割边模版题2，java版\n// 给定一张无向图，一共n个点、m条边\n// 点的编号0~n-1，保证所有点连通\n// 找出图中所有的割边，返回每条割边的两个端点\n// 请保证原图即使有重边和自环，答案依然正确\n// 1 <= n、m <= 10^5\n// 测试链接 : https://leetcode.cn/problems/critical-connections-in-a-network/\n// 提交以下代码中的Solution类，可以通过所有测试用例\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\npublic class Code02_CutEdge1 {\n\n\tclass Solution {\n\n\t\tpublic static int MAXN = 100001;\n\t\tpublic static int MAXM = 100001;\n\t\tpublic static int n, m;\n\t\tpublic static int[] a = new int[MAXM];\n\t\tpublic static int[] b = new int[MAXM];\n\n\t\tpublic static int[] head = new int[MAXN];\n\t\tpublic static int[] nxt = new int[MAXM << 1];\n\t\tpublic static int[] to = new int[MAXM << 1];\n\t\tpublic static int cntg;\n\n\t\tpublic static int[] dfn = new int[MAXN];\n\t\tpublic static int[] low = new int[MAXN];\n\t\tpublic static int cntd;\n\n\t\tpublic static boolean[] cutEdge = new boolean[MAXM];\n\n\t\tpublic static void prepare() {\n\t\t\tcntg = 1;\n\t\t\tcntd = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\thead[i] = dfn[i] = low[i] = 0;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tcutEdge[i] = false;\n\t\t\t}\n\t\t}\n\n\t\tpublic static void addEdge(int u, int v) {\n\t\t\tnxt[++cntg] = head[u];\n\t\t\tto[cntg] = v;\n\t\t\thead[u] = cntg;\n\t\t}\n\n\t\tpublic static void tarjan(int u, int preEdge) {\n\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tint v = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\ttarjan(v, e);\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\t\tcutEdge[e >> 1] = true;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic static List<List<Integer>> criticalConnections(int nodeCnt, List<List<Integer>> connections) {\n\t\t\tn = nodeCnt;\n\t\t\tm = connections.size();\n\t\t\tprepare();\n\t\t\tfor (int i = 1, j = 0; i <= m; i++, j++) {\n\t\t\t\ta[i] = connections.get(j).get(0) + 1;\n\t\t\t\tb[i] = connections.get(j).get(1) + 1;\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t\taddEdge(b[i], a[i]);\n\t\t\t}\n\t\t\ttarjan(1, 0);\n\t\t\tList<List<Integer>> ans = new ArrayList<>();\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tif (cutEdge[i]) {\n\t\t\t\t\tans.add(Arrays.asList(a[i] - 1, b[i] - 1));\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t}\n\n}\n	模板：Code02_CutEdge1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2f252b88-a19a-4d25-a56c-fb13611a06a2	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class189;\n\n// 任意两点都有路，java版\n// 给定一张n个点，m条边的有向图\n// 两点u、v，不管是从u出发能到达v，还是从v出发能到达u，都叫两点间有路\n// 判断这个有向图是否能做到，任意两点都有路，能打印"Yes"，不能打印"No"\n// 1 <= n <= 1000\n// 1 <= m <= 6000\n// 测试链接 : https://www.luogu.com.cn/problem/P10944\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code09_HasPath1 {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int MAXM = 6001;\n\tpublic static int t, n, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] indegree = new int[MAXN];\n\tpublic static int[] que = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean topo() {\n\t\tint l = 1, r = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++r] = i;\n\t\t\t}\n\t\t}\n\t\twhile (l <= r) {\n\t\t\tint siz = r - l + 1;\n\t\t\tif (siz > 1) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tint u = que[l++];\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++r] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tcntg = cntd = sccCnt = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\thead[i] = dfn[i] = belong[i] = indegree[i] = 0;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\ta[i] = in.nextInt();\n\t\t\t\tb[i] = in.nextInt();\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\ttarjan(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\tcondense();\n\t\t\tboolean ans = topo();\n\t\t\tout.println(ans ? "Yes" : "No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code09_HasPath1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
