05d5fa5f-f280-493e-b072-e9b17b23cfcf	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class190;\n\n// 最大半连通子图，java版\n// 有向图中节点u和v，只要其中一点能到达另一点，就说两点是半连通的\n// 如果一个有向图，任意两点都是半连通的，这样的有向图就是半连通图\n// 有向图中的一个点集，该点集中只要某两点在原图中有边，那么这条边就保留，则可以得到一个子图\n// 如果该子图既是半连通图，又有节点数量最多，那么这个子图就是原图的最大半连通子图\n// 给定一张n个点，m条边的有向图，打印最大半连通子图的大小\n// 可能存在多个最大半连通子图，打印这个数量，数量对给定的数字x取余\n// 1 <= n <= 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P2272\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_MaximumSemi1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m, x;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sccSiz = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static long[] edgeArr = new long[MAXM];\n\tpublic static int cnte;\n\n\tpublic static int[] indegree = new int[MAXN];\n\tpublic static int[] dpSum = new int[MAXN];\n\tpublic static int[] dpCnt = new int[MAXN];\n\n\tpublic static int ans1, ans2;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsccSiz[sccCnt] = 0;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsccSiz[sccCnt] = 0;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tedgeArr[++cnte] = ((long) scc1 << 32) | scc2;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(edgeArr, 1, cnte + 1);\n\t\tlong pre = 0, cur;\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\tcur = edgeArr[i];\n\t\t\tif (cur != pre) {\n\t\t\t\tint scc1 = (int) (cur >>> 32);\n\t\t\t\tint scc2 = (int) (cur & 0xffffffffL);\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t\tpre = cur;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dpOnDAG() {\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tif (indegree[u] == 0) {\n\t\t\t\tdpSum[u] = sccSiz[u];\n\t\t\t\tdpCnt[u] = 1;\n\t\t\t}\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (dpSum[v] < dpSum[u] + sccSiz[v]) {\n\t\t\t\t\tdpSum[v] = dpSum[u] + sccSiz[v];\n\t\t\t\t\tdpCnt[v] = dpCnt[u];\n\t\t\t\t} else if (dpSum[v] == dpSum[u] + sccSiz[v]) {\n\t\t\t\t\tdpCnt[v] = (dpCnt[v] + dpCnt[u]) % x;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tans1 = ans2 = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (dpSum[i] > ans1) {\n\t\t\t\tans1 = dpSum[i];\n\t\t\t\tans2 = dpCnt[i];\n\t\t\t} else if (dpSum[i] == ans1) {\n\t\t\t\tans2 = (ans2 + dpCnt[i]) % x;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tx = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tcondense();\n\t\tdpOnDAG();\n\t\tout.println(ans1);\n\t\tout.println(ans2);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_MaximumSemi1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
