 scc2 = belong[i];\n//            if (scc1 != scc2) {\n//                indegree[scc2]++;\n//                addEdge(scc1, scc2);\n//            }\n//        }\n//    }\n//    for (int i = 1; i <= sccCnt; i++) {\n//        if (indegree[i] == 0) {\n//            addEdge(0, i);\n//        }\n//    }\n//}\n//\n//int dfs(int u) {\n//    int i = ++dfnCnt;\n//    siz[i] = 1;\n//    weight[i] = wsum[u];\n//    value[i] = vsum[u];\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        siz[i] += dfs(v);\n//    }\n//    return siz[i];\n//}\n//\n//int knapsackOnTree() {\n//    dfs(0);\n//    for (int i = dfnCnt; i >= 2; i--) {\n//        for (int j = 1; j <= m; j++) {\n//            dp[i][j] = dp[i + siz[i]][j];\n//            if (j - weight[i] >= 0) {\n//                dp[i][j] = max(dp[i][j], value[i] + dp[i + 1][j - weight[i]]);\n//            }\n//        }\n//    }\n//    return dp[2][m];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> w[i];\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cin >> v[i];\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cin >> depend[i];\n//        if (depend[i] > 0) {\n//            addEdge(depend[i], i);\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    condense();\n//    int ans = knapsackOnTree();\n//    cout << ans << "\\n";\n//    return 0;\n//}	模板：Code07_SoftwareInstallation2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8fc1aa1b-4759-45e5-9ad0-6fb297cdebe2	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class190;\n\n// 糖果，java版\n// 一共n个人，每人至少得到一个糖果，一共k条要求，要求有5种类型\n// 1 u v : u的糖果 == v的糖果    2 u v : u的糖果 < v的糖果\n// 3 u v : u的糖果 >= v的糖果    4 u v : u的糖果 > v的糖果\n// 5 u v : u的糖果 <= v的糖果\n// 如果无法满足所有要求打印-1，否则打印需要的最少糖果数\n// 1 <= n、k <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3275\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_Candy1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int n, k, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\tpublic static int[] c = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int[] weight = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sccSiz = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] indegree = new int[MAXN];\n\tpublic static long[] dp = new long[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsccSiz[sccCnt] = 0;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsccSiz[sccCnt] = 0;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tint w = c[i];\n\t\t\tif (scc1 == scc2 && w > 0) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2, w);\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static long dpOnDAG() {\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tif (indegree[u] == 0) {\n\t\t\t\tdp[u] = 1;\n\t\t\t}\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tdp[v] = Math.max(dp[v], dp[u] + w);\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tans += dp[i] * sccSiz[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tk = in.nextInt();\n\t\tm = 0;\n\t\tfor (int i = 1, op, u, v; i <= k; i++) {\n\t\t\top = in.nextInt();\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\ta[++m] = u; b[m] = v; c[m] = 0;\n\t\t\t\ta[++m] = v; b[m] = u; c[m] = 0;\n\t\t\t} else if (op == 2) {\n\t\t\t\ta[++m] = u; b[m] = v; c[m] = 1;\n\t\t\t} else if (op == 3) {\n\t\t\t\ta[++m] = v; b[m] = u; c[m] = 0;\n\t\t\t} else if (op == 4) {\n\t\t\t\ta[++m] = v; b[m] = u; c[m] = 1;\n\t\t\t} else {\n\t\t\t\ta[++m] = u; b[m] = v; c[m] = 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\taddEdge(a[i], b[i], c[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = condense();\n\t\tif (!check) {\n\t\t\tout.println(-1);\n\t\t} else {\n\t\t\tlong ans = dpOnDAG();\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code08_Candy1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
