7412cc57-a8dd-4037-a766-cc7c1591c3dc	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class190;\n\n// 杀人游戏，java版\n// 一共n个人，只有一个杀手，每个人是杀手的概率均等，其他人都是平民\n// 给定m个知晓关系，如果x知晓y，那么y是不是杀手，x就知道情况了\n// 知晓关系是单向且可传递的，比如a知晓b，b知晓c，那么a知晓c\n// 你可以盘问任何人，不仅能知道对方身份，并且对方知晓的所有情况都能获得\n// 但是如果你直接盘问到杀手的话，杀手会原地爆炸，炸死所有人\n// 你一定要确定所有人的身份，而且你充分了解知晓关系网，会用最优的盘问策略\n// 返回最优盘问策略下，杀手不爆炸还能被揪出来的概率，保留小数点后面6位\n// 1 <= n <= 10^5\n// 0 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4819\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code09_KillingGame1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 300001;\n\tpublic static int n, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sccSiz = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static long[] edgeArr = new long[MAXM];\n\tpublic static int cnte;\n\n\tpublic static int[] indegree = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsccSiz[sccCnt] = 0;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsccSiz[sccCnt] = 0;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsccSiz[sccCnt]++;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tedgeArr[++cnte] = ((long) scc1 << 32) | scc2;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(edgeArr, 1, cnte + 1);\n\t\tlong pre = 0, cur;\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\tcur = edgeArr[i];\n\t\t\tif (cur != pre) {\n\t\t\t\tint scc1 = (int) (cur >>> 32);\n\t\t\t\tint scc2 = (int) (cur & 0xffffffffL);\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t\tpre = cur;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean isolated(int i) {\n\t\tif (indegree[i] > 0 || sccSiz[i] > 1) {\n\t\t\treturn false;\n\t\t}\n\t\tif (head[i] == 0) {\n\t\t\treturn true;\n\t\t}\n\t\tfor (int e = head[i]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (indegree[v] == 1) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static double compute() {\n\t\tint inZero = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tinZero++;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (isolated(i)) {\n\t\t\t\tinZero--;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\treturn 1.0 - (double) inZero / n;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tcondense();\n\t\tdouble ans = compute();\n\t\tout.printf("%.6f\\n", ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code09_KillingGame1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
