4f49c833-9f83-4000-ac11-3d0542b05d72	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 割边模版题1，java版\n// 给定一张无向图，一共n个点、m条边\n// 图中可能存在多个连通区，对每个连通区求割边\n// 先打印割边的总数量，然后从小到大打印所有割边的序号\n// 请保证原图即使有重边和自环，答案依然正确\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/U582665\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_CutEdge1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 2000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static boolean[] cutEdge = new boolean[MAXM];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = preEdge;\n\t\tstack[stacksize][2] = status;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tpreEdge = stack[stacksize][1];\n\t\tstatus = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) { // 从哪条边来的要忽略\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) { // 树边\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\tcutEdge[e >> 1] = true;\n\t\t\t\t}\n\t\t\t} else { // 回边或弃边\n\t\t\t\t// 回边是dfn[v] < dfn[u]，弃边是dfn[v] > dfn[u]\n\t\t\t\t// 因为low[u]初始值就是dfn[u]，所以弃边出现时，无法更新low[u]\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\t// u表示当前节点，preEdge表示来边\n\t// e表示u当前处理的边\n\t//     如果(e ^ 1) == preEdge，跳过当前边，对应递归版中的第一个if\n\t//     如果e == 0，说明所有边都处理完了\n\t// status的具体说明如下\n\t//     如果status == -1，表示u没有遍历过任何儿子\n\t//     如果status == 0，表示u遍历到儿子v，然后发现dfn[v] == 0\n\t//         并且执行完了tarjan(v, e)，对应递归版for循环的第二个if\n\t//     如果status == 1，表示u遍历到儿子v，然后发现dfn[v] != 0\n\t//         对应递归版for循环中的else分支\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksize = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\t\tcutEdge[e >> 1] = true;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i, 0);\n\t\t\t\ttarjan2(i, 0);\n\t\t\t}\n\t\t}\n\t\tint ansCnt = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (cutEdge[i]) {\n\t\t\t\tansCnt++;\n\t\t\t}\n\t\t}\n\t\tout.println(ansCnt);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (cutEdge[i]) {\n\t\t\t\tout.print(i + " ");\n\t\t\t}\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_CutEdge1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8c05ed78-014d-4510-9470-7ae424b4d7d4	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 关键网络线路，C++版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 给定k个提供A服务的节点，给定l个提供B服务的节点，保证k和l都是正数\n// 一个节点可能不提供服务，也可能提供A服务或者B服务或者两种都有\n// 每个节点可以通过边，获得任何节点提供的服务，但是必须同时获得两种服务\n// 如果断开某一条边，使得某些节点无法同时获得两种服务，这样的边叫关键边\n// 打印关键边的数量，打印每条关键边的两个端点\n// 1 <= n <= 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P7687\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 1000001;\n//int n, m, k, l;\n//int acnt[MAXN];\n//int bcnt[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int ans1[MAXN];\n//int ans2[MAXN];\n//int cnta;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] > dfn[u]) {\n//                if (acnt[v] == 0 || acnt[v] == k || bcnt[v] == 0 || bcnt[v] == l) {\n//                    cnta++;\n//                    ans1[cnta] = v;\n//                    ans2[cnta] = u;\n//                }\n//            }\n//            acnt[u] += acnt[v];\n//            bcnt[u] += bcnt[v];\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cntg = 1;\n//    cin >> n >> m >> k >> l;\n//    for (int i = 1, x; i <= k; i++) {\n//        cin >> x;\n//        acnt[x] = 1;\n//    }\n//    for (int i = 1, x; i <= l; i++) {\n//        cin >> x;\