c95aa238-f65e-401f-845a-6f6a6e805106	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 贝尔敦道路，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 每条无向边需要指定一个方向，变成有向边，还要保证任意两点互相可达\n// 如果不存在方案打印0，如果存在方案，打印m条有向边\n// 可以任意次序打印有向边，如果方案不只一种，打印其中一种即可\n// 1 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF118E\n// 测试链接 : https://codeforces.com/problemset/problem/118/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_BertownRoads1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 300001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static boolean check;\n\tpublic static int[] ans1 = new int[MAXM];\n\tpublic static int[] ans2 = new int[MAXM];\n\tpublic static int cnta;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\t// 树边和回边需要处理，弃边不要处理\n\t\t\tif (dfn[v] == 0 || dfn[v] < dfn[u]) {\n\t\t\t\tcnta++;\n\t\t\t\tans1[cnta] = u;\n\t\t\t\tans2[cnta] = v;\n\t\t\t}\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\tcheck = false;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tcheck = true;\n\t\ttarjan(1, 0);\n\t\tif (!check) {\n\t\t\tout.println(0);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tout.println(ans1[i] + " " + ans2[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_BertownRoads1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
