f2b3f29c-4c2b-471b-ad19-a96c8b21a819	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 边双连通分量模版题，java版\n// 给定一张无向图，一共n个点、m条边\n// 图中可能存在多个连通区，对每个连通区求边双连通分量\n// 先打印边双连通分量的总数量，然后对每个边双连通分量\n// 打印节点个数，然后任意顺序打印该边双连通分量的节点\n// 请保证原图即使有重边和自环，答案依然正确\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8436\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_EBCC1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 2000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] ebccSiz = new int[MAXN];\n\tpublic static int[] ebccArr = new int[MAXN];\n\tpublic static int[] ebccl = new int[MAXN];\n\tpublic static int[] ebccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int ebccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = preEdge;\n\t\tstack[stacksize][2] = status;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tpreEdge = stack[stacksize][1];\n\t\tstatus = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\tebccl[ebccCnt] = idx + 1;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t\tebccArr[++idx] = pop;\n\t\t\t} while (pop != u);\n\t\t\tebccr[ebccCnt] = idx;\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksize = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tebccCnt++;\n\t\t\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\t\t\tebccl[ebccCnt] = idx + 1;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t\t\t\tebccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t\tebccr[ebccCnt] = idx;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i, 0);\n\t\t\t\ttarjan2(i, 0);\n\t\t\t}\n\t\t}\n\t\tout.println(ebccCnt);\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\tout.println(ebccSiz[i]);\n\t\t\tfor (int j = ebccl[i]; j <= ebccr[i]; j++) {\n\t\t\t\tout.print(ebccArr[j] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_EBCC1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
