; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i, 0);\n//        }\n//    }\n//    cout << ebccCnt << "\\n";\n//    for (int i = 1; i <= ebccCnt; i++) {\n//        cout << ebccSiz[i] << "\\n";\n//        for (int j = ebccl[i]; j <= ebccr[i]; j++) {\n//            cout << ebccArr[j] << " ";\n//        }\n//        cout << "\\n";\n//    }\n//    return 0;\n//}	模板：Code05_EBCC2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c92e6f04-d486-4c61-a928-8b103fb988db	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 网络，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 一共q条操作，格式 x y : 点x和点y之间新增一条边，打印此时割边的数量\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=2460\n// 测试链接 : http://poj.org/problem?id=3694\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_Network1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int t, n, m, q;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] fa = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tcntg = 1;\n\t\tcntd = top = ebccCnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\taddEdge(ebcc1, ebcc2);\n\t\t\t\taddEdge(ebcc2, ebcc1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tdep[u] = dep[f] + 1;\n\t\tup[u] = f;\n\t\tfa[u] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != fa[i]) {\n\t\t\tfa[i] = find(fa[i]);\n\t\t}\n\t\treturn fa[i];\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tx = find(x);\n\t\ty = find(y);\n\t\tif (x != y) {\n\t\t\tif (dep[x] < dep[y]) {\n\t\t\t\tfa[y] = x;\n\t\t\t} else {\n\t\t\t\tfa[x] = y;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void link(int x, int y) {\n\t\tx = find(belong[x]);\n\t\ty = find(belong[y]);\n\t\twhile (x != y) {\n\t\t\tif (dep[x] >= dep[y]) {\n\t\t\t\tunion(x, up[x]);\n\t\t\t\tx = find(x);\n\t\t\t} else {\n\t\t\t\tunion(y, up[y]);\n\t\t\t\ty = find(y);\n\t\t\t}\n\t\t\tebccCnt--;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = 0;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\twhile (n != 0 || m != 0) {\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\ta[i] = in.nextInt();\n\t\t\t\tb[i] = in.nextInt();\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t\taddEdge(b[i], a[i]);\n\t\t\t}\n\t\t\ttarjan(1, 0);\n\t\t\tcondense();\n\t\t\tdfs(1, 0);\n\t\t\tout.println("Case " + (++t) + ":");\n\t\t\tq = in.nextInt();\n\t\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tlink(x, y);\n\t\t\t\tout.println(ebccCnt - 1);\n\t\t\t}\n\t\t\tout.println();\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Network1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ea728eb5-d578-48e9-82b2-b1988d95ec57	55327a5f-27fb-40b4-a7fb-d39bb7bd400c	java	package class059;\n\n// 拓扑排序模版（牛客）\n// 链式前向星建图（静态方式）\n// 测试链接 : https://www.nowcoder.com/practice/88f7e156ca7d43a1a535f619cd3f495c\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下所有代码，把主类名改成Main，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_TopoSortStaticNowcoder {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int MAXM = 200001;\n\n\t// 建图相关，链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static int cnt;\n\n\t// 拓扑排序，用到队列\n\tpublic static int[] queue = new int[MAXN];\n\n\tpublic static int l, r;\n\n\t// 拓扑排序，入度表\n\tpublic static int[] indegree = new int[MAXN];\n\n\t// 收集拓扑排序的结果\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void build(int n) {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 0, n + 1, 0);\n\t\tArrays.fill(indegree, 0, n + 1, 0);\n\t}\n\n\t// 用链式前向星建图\n\tpublic static void addEdge(int f, int t) {\n\t\tnext[cnt] = head[f];\n\t\tto[cnt] = t;\n\t\thead[f] = cnt++;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tbuild(n);\n\t\t\tfor (int i = 0, from, to; i < m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tfrom = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tto = (int) in.nval;\n\t\t\t\taddEdge(from, to);\n\t\t\t\tindegree[to]++;\n\t\t\t}\n\t\t\tif (!topoSort()) {\n\t\t\t\tout.println(-1);\n\t\t\t} else {\n\t\t\t\tfor (int i = 0; i < n - 1; i++) {\n\t\t\t\t\tout.print(ans[i] + " ");\n\t\t\t\t}\n\t\t\t\tout.println(ans[n - 1]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static boolean topoSort() {\n\t\tl = r = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tqueue[r++] = i;\n\t\t\t}\n\t\t}\n\t\tint fill = 0;\n\t\twhile (l < r) {\n\t\t\tint cur = queue[l++];\n\t\t\tans[fill++] = cur;\n\t\t\t// 用链式前向星的方式，遍历cur的相邻节点\n\t\t\tfor (int ei = head[cur]; ei != 0; ei = next[ei]) {\n\t\t\t\tif (--indegree[to[ei]] == 0) {\n\t\t\t\t\tqueue[r++] = to[ei];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn fill == n;\n\t}\n\n}	模板：Code02_TopoSortStaticNowcoder.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
