38d268c0-d512-409b-83bf-ada305d63f62	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class191;\n\n// 冗余路径，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 打印至少添加几条边可以让整张图变成一个边双连通分量\n// 1 <= n <= 5000\n// 1 <= m <= 10000\n// 测试链接 : https://www.luogu.com.cn/problem/P2860\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_RedundantPaths1 {\n\n\tpublic static int MAXN = 5001;\n\tpublic static int MAXM = 10001;\n\tpublic static int n, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\tpublic static int[] degree = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static int getLeaf() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\tdegree[ebcc1]++;\n\t\t\t\tdegree[ebcc2]++;\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\tif (degree[i] == 1) {\n\t\t\t\tans++;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t\taddEdge(b[i], a[i]);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tint leafCnt = getLeaf();\n\t\tout.println((leafCnt + 1) / 2);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_RedundantPaths1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
