064f4446-ef1e-4440-8bdc-b0f78e3d47bf	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class192;\n\n// 追寻文物，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 每条边除了端点之外，还有一个属性，值为1表示该边上有商品，值为0表示该边上无商品\n// 给定起点s和终点t，路途怎么走随意，但是沿途每条边只能经过一次\n// 从s到t的路途中能遇到商品打印"YES"，否则打印"NO"\n// 1 <= n、m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF652E\n// 测试链接 : https://codeforces.com/problemset/problem/652/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_PursuitArtifacts1 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int MAXM = 300001;\n\tpublic static int n, m, s, t;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\tpublic static int[] c = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int[] weight = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tint w = c[i];\n\t\t\tif (ebcc1 == ebcc2) {\n\t\t\t\tif (w == 1) {\n\t\t\t\t\tval[ebcc1] = 1;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\taddEdge(ebcc1, ebcc2, w);\n\t\t\t\taddEdge(ebcc2, ebcc1, w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean check(int u, int fa, boolean ok) {\n\t\tok |= val[u] > 0;\n\t\tif (u == t) {\n\t\t\treturn ok;\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (check(v, u, ok || w > 0)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\tc[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i], 0);\n\t\t\taddEdge(b[i], a[i], 0);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tcondense();\n\t\ts = in.nextInt();\n\t\tt = in.nextInt();\n\t\ts = belong[s];\n\t\tt = belong[t];\n\t\tif (check(s, 0, false)) {\n\t\t\tout.println("YES");\n\t\t} else {\n\t\t\tout.println("NO");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_PursuitArtifacts1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
