861fd545-a274-4e33-a5be-7736a2381504	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class192;\n\n// 神会作弊，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通，两点间出现重边只连一次\n// 边双连通分量缩点后，如果点x和点y属于同一个边双连通分量，认为两点距离是1\n// 如果不属于同一个边双连通分量，距离为缩点后的树上，两点简单路径上的节点个数\n// 一共有q条查询，格式 x y : 计算点x和点y的距离，打印距离的二进制形式\n// 1 <= n <= 10000\n// 1 <= m <= 50000\n// 测试链接 : https://www.luogu.com.cn/problem/P2783\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code04_GodCheat1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 50001;\n\tpublic static int MAXP = 15;\n\tpublic static int n, m, q;\n\tpublic static int[][] edgeArr = new int[MAXM][2];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(edgeArr, 1, m + 1, (a, b) -> a[0] != b[0] ? (a[0] - b[0]) : (a[1] - b[1]));\n\t\tint k = 1;\n\t\tfor (int i = 2; i <= m; i++) {\n\t\t\tif (edgeArr[k][0] != edgeArr[i][0] || edgeArr[k][1] != edgeArr[i][1]) {\n\t\t\t\tedgeArr[++k][0] = edgeArr[i][0];\n\t\t\t\tedgeArr[k][1] = edgeArr[i][1];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\taddEdge(edgeArr[i][0], edgeArr[i][1]);\n\t\t\taddEdge(edgeArr[i][1], edgeArr[i][0]);\n\t\t}\n\t\tm = k;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[edgeArr[i][0]];\n\t\t\tint ebcc2 = belong[edgeArr[i][1]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\taddEdge(ebcc1, ebcc2);\n\t\t\t\taddEdge(ebcc2, ebcc1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dep[x] + dep[y] - 2 * dep[getLca(x, y)];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tedgeArr[i][0] = Math.min(u, v);\n\t\t\tedgeArr[i][1] = Math.max(u, v);\n\t\t}\n\t\tbuildGraph();\n\t\ttarjan(1, 0);\n\t\tcondense();\n\t\tdfs(1, 0);\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tx = belong[x];\n\t\t\ty = belong[y];\n\t\t\tout.println(Integer.toBinaryString(getDist(x, y) + 1));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_GodCheat1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
