i <= q; i++) {\n//        cin >> x >> y;\n//        x = belong[x];\n//        y = belong[y];\n//        if (block[x] != block[y]) {\n//            ans = false;\n//            break;\n//        }\n//        xylca = getLca(x, y);\n//        upCnt[x]++;\n//        upCnt[xylca]--;\n//        downCnt[y]++;\n//        downCnt[xylca]--;\n//    }\n//    if (ans) {\n//        for (int i = 1; i <= ebccCnt; i++) {\n//            if (!vis[i] && !check(i, 0)) {\n//                ans = false;\n//                break;\n//            }\n//        }\n//    }\n//    cout << (ans ? "Yes" : "No") << "\\n";\n//    return 0;\n//}	模板：Code06_OneDirection2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ab6e18d2-032f-417d-97e9-5a352325133c	e4b5422d-916b-402f-b657-9735ea671cc9	java	package class192;\n\n// 建造军营，java版\n// 一共n个城市、m条道路，道路是无向边，保证所有城市连通\n// 你可以选择任何城市，在城市内建造军营，至少要选一座城市\n// 你可以选择任何道路，在道路上派兵看守，也可以一条都不选\n// 选择的城市集合 + 选择的道路集合，被认为是一种方案\n// 敌人会袭击任意一条道路，如果有兵看守就不会被切断，否则会被切断\n// 敌人袭击之后，如果造成任意两座军营无法连通，那么算你失败\n// 确保不会失败的情况下，计算方案数，答案对 1000000007 取余\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8867\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_MilitaryCamp1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int MOD = 1000000007;\n\tpublic static int n, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] ebccSiz = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\t// power2[i] = 2的i次方\n\tpublic static long[] power2 = new long[MAXM];\n\n\t// dp[u] : 子树u上，原图的点可以考虑造军营，至少造一个\n\t//         从所造军营到u的割边都派兵，其他割边随意，这样的方案数\n\tpublic static long[] dp = new long[MAXN];\n\n\t// bridge[u] : 子树u上割边的数量\n\tpublic static int[] bridge = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, preEdge, status, fa, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int preEdge, int status, int fa, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = preEdge;\n\t\tstack[stacksize][2] = status;\n\t\tstack[stacksize][3] = fa;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tpreEdge = stack[stacksize][1];\n\t\tstatus = stack[stacksize][2];\n\t\tfa = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksize = 0;\n\t\tpush(node, pree, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, 0, e);\n\t\t\t\t\tpush(v, e, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, 0, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tebccCnt++;\n\t\t\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\taddEdge(ebcc1, ebcc2);\n\t\t\t\taddEdge(ebcc2, ebcc1);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dpOnTree1(int u, int fa) {\n\t\t// 情况1，不考虑下方的节点，在u自己的边双连通分量里，选点造军营\n\t\tdp[u] = power2[ebccSiz[u]] - 1;\n\t\tbridge[u] = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdpOnTree1(v, u);\n\t\t\t\t// 情况2，之前部分的方案数 * 子树v完全不造军营时割边的自由发挥 * u到v的割边自由发挥\n\t\t\t\t// 情况3，之前部分完全不造军营时割边的自由发挥 * 子树v的方案数\n\t\t\t\t// 情况4，之前部分的方案数 * 子树v的方案数\n\t\t\t\tdp[u] = (dp[u] * power2[bridge[v]] * 2 % MOD\n\t\t\t\t\t\t+ power2[bridge[u]] * dp[v] % MOD\n\t\t\t\t\t\t+ dp[u] * dp[v] % MOD)\n\t\t\t\t\t\t% MOD;\n\t\t\t\tbridge[u] += bridge[v] + 1;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dpOnTree2(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, 0, father, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdp[u] = power2[ebccSiz[u]] - 1;\n\t\t\t\tbridge[u] = 0;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, fa, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa) {\n\t\t\t\t\tpush(v, 0, 0, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != fa) {\n\t\t\t\t\t\tdp[u] = (dp[u] * power2[bridge[v] + 1] % MOD\n\t\t\t\t\t\t\t\t+ power2[bridge[u]] * dp[v] % MOD\n\t\t\t\t\t\t\t\t+ dp[u] * dp[v] % MOD) % MOD;\n\t\t\t\t\t\tbridge[u] += bridge[v] + 1;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tpower2[0] = 1;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tpower2[i] = power2[i - 1] * 2 % MOD;\n\t\t}\n\t\t// dpOnTree1(1, 0);\n\t\tdpOnTree2(1, 0);\n\t\tint total = bridge[1];\n\t\tlong ans = dp[1];\n\t\tfor (int i = 2; i <= ebccCnt; i++) {\n\t\t\tans = (ans + dp[i] * power2[total - bridge[i] - 1] % MOD) % MOD;\n\t\t}\n\t\tans = ans * power2[m - total] % MOD;\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t\taddEdge(b[i], a[i]);\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tcondense();\n\t\tlong ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_MilitaryCamp1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6fc6a40b-de3b-4d7d-9407-2333c30b7002	55327a5f-27fb-40b4-a7fb-d39bb7bd400c	java	package class060;\n\nimport java.util.ArrayList;\n\n// 喧闹和富有\n// 从 0 到 n - 1 编号，其中每个人都有不同数目的钱，以及不同程度的安静值\n// 给你一个数组richer，其中richer[i] = [ai, bi] 表示 \n// person ai 比 person bi 更有钱\n// 还有一个整数数组 quiet ，其中 quiet[i] 是 person i 的安静值\n// richer 中所给出的数据 逻辑自洽\n// 也就是说，在 person x 比 person y 更有钱的同时，不会出现\n// person y 比 person x 更有钱的情况\n// 现在，返回一个整数数组 answer 作为答案，其中 answer[x] = y 的前提是,\n// 在所有拥有的钱肯定不少于 person x 的人中，\n// person y 是最安静的人（也就是安静值 quiet[y] 最小的人）。\n// 测试链接 : https://leetcode.cn/problems/loud-and-rich/\npublic class Code02_LoudAndRich {\n\n\tpublic static int[] loudAndRich(int[][] richer, int[] quiet) {\n\t\tint n = quiet.length;\n\t\tArrayList<ArrayList<Integer>> graph = new ArrayList<>();\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tgraph.add(new ArrayList<>());\n\t\t}\n\t\tint[] indegree = new int[n];\n\t\tfor (int[] r : richer) {\n\t\t\tgraph.get(r[0]).add(r[1]);\n\t\t\tindegree[r[1]]++;\n\t\t}\n\t\tint[] queue = new int[n];\n\t\tint l = 0;\n\t\tint r = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tqueue[r++] = i;\n\t\t\t}\n\t\t}\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = i;\n\t\t}\n\t\twhile (l < r) {\n\t\t\tint cur = queue[l++];\n\t\t\tfor (int next : graph.get(cur)) {\n\t\t\t\tif (quiet[ans[cur]] < quiet[ans[next]] ) {\n\t\t\t\t\tans[next] = ans[cur];\n\t\t\t\t}\n\t\t\t\tif (--indegree[next] == 0) {\n\t\t\t\t\tqueue[r++] = next;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code02_LoudAndRich.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
