[u] > 1) {\n//        cost[u]++;\n//        siz[u] = 0;\n//    }\n//}\n//\n//int compute() {\n//    for (int i = 1; i <= k; i++) {\n//        isKey[arr[i]] = true;\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= k; i++) {\n//        if (isKey[stjump[arr[i]][0]]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    int ans = -1;\n//    if (check) {\n//        int tree = buildVirtualTree1();\n//        // int tree = buildVirtualTree2();\n//        dp(tree);\n//        ans = cost[tree];\n//    }\n//    for (int i = 1; i <= k; i++) {\n//        isKey[arr[i]] = false;\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdgeG(u, v);\n//        addEdgeG(v, u);\n//    }\n//    dfs(1, 0);\n//    cin >> q;\n//    for (int t = 1; t <= q; t++) {\n//        cin >> k;\n//        for (int i = 1; i <= k; i++) {\n//            cin >> arr[i];\n//        }\n//        cout << compute() << '\\n';\n//    }\n//    return 0;\n//}	模板：Code01_KingdomAndCities2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
81c9449b-0398-406e-8c6e-85e1a0d0a6ed	c77c53ee-2f5b-457e-8e11-588526380953	java	package class180;\n\n// 大工程，java版\n// 一共有n个节点，给定n-1条无向边，所有节点组成一棵树\n// 如果在节点a和节点b之间建立新通道，那么代价是两个节点在树上的距离\n// 一共有q条查询，每条查询格式如下\n// 查询 k a1 a2 ... ak : 给出了k个不同的节点，任意两个节点之间都会建立新通道\n//                       打印新通道的代价和、新通道中代价最小的值、新通道中代价最大的值\n// 1 <= n <= 10^6\n// 1 <= q <= 5 * 10^4\n// 1 <= 所有查询给出的点的总数 <= 2 * n\n// 测试链接 : https://www.luogu.com.cn/problem/P4103\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_BigProject1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int MAXP = 20;\n\tpublic static long INF = 1L << 60;\n\tpublic static int n, q, k;\n\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] headv = new int[MAXN];\n\tpublic static int[] nextv = new int[MAXN];\n\tpublic static int[] tov = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static boolean[] isKey = new boolean[MAXN];\n\n\tpublic static int[] tmp = new int[MAXN << 1];\n\tpublic static int[] stk = new int[MAXN];\n\n\t// siz[u]表示子树u上，关键点的数量\n\t// sum[u]表示子树u上，所有关键点到u的总距离\n\t// near[u]表示子树u上，到u最近关键点的距离\n\t// far[u]表示子树u上，到u最远关键点的距离\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static long[] sum = new long[MAXN];\n\tpublic static long[] near = new long[MAXN];\n\tpublic static long[] far = new long[MAXN];\n\n\t// 新通道的代价和、新通道中代价最小的值、新通道中代价最大的值\n\tpublic static long costSum, costMin, costMax;\n\n\t// dfs过程和dp过程，C++同学可以使用递归版\n\t// 但是java同学必须改迭代版否则会爆栈\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\t// ufe不仅用于dfs改迭代，也用于dp改迭代\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdgeG(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addEdgeV(int u, int v) {\n\t\tnextv[++cntv] = headv[u];\n\t\ttov[cntv] = v;\n\t\theadv[u] = cntv;\n\t}\n\n\tpublic static void sortByDfn(int[] nums, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r;\n\t\tint pivot = nums[(l + r) >> 1];\n\t\twhile (i <= j) {\n\t\t\twhile (dfn[nums[i]] < dfn[pivot]) i++;\n\t\t\twhile (dfn[nums[j]] > dfn[pivot]) j--;\n\t\t\tif (i <= j) {\n\t\t\t\tint tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsortByDfn(nums, l, j);\n\t\tsortByDfn(nums, i, r);\n\t}\n\n\t// dfs递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdfn[u] = ++cntd;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tif (tog[e] != fa) {\n\t\t\t\tdfs1(tog[e], u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (tog[e] != f) {\n\t\t\t\t\tpush(tog[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a; a = b; b = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\t// 二次排序 + LCA连边的方式建立虚树\n\tpublic static int buildVirtualTree1() {\n\t\tsortByDfn(arr, 1, k);\n\t\tint len = 0;\n\t\tfor (int i = 1; i < k; i++) {\n\t\t\ttmp[++len] = arr[i];\n\t\t\ttmp[++len] = getLca(arr[i], arr[i + 1]);\n\t\t}\n\t\ttmp[++len] = arr[k];\n\t\tsortByDfn(tmp, 1, len);\n\t\tint unique = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (tmp[unique] != tmp[i]) {\n\t\t\t\ttmp[++unique] = tmp[i];\n\t\t\t}\n\t\t}\n\t\tcntv = 0;\n\t\tfor (int i = 1; i <= unique; i++) {\n\t\t\theadv[tmp[i]] = 0;\n\t\t}\n\t\tfor (int i = 1; i < unique; i++) {\n\t\t\taddEdgeV(getLca(tmp[i], tmp[i + 1]), tmp[i + 1]);\n\t\t}\n\t\treturn tmp[1];\n\t}\n\n\t// 单调栈的方式建立虚树\n\tpublic static int buildVirtualTree2() {\n\t\tsortByDfn(arr, 1, k);\n\t\tcntv = 0;\n\t\theadv[arr[1]] = 0;\n\t\tint top = 0;\n\t\tstk[++top] = arr[1];\n\t\tfor (int i = 2; i <= k; i++) {\n\t\t\tint x = arr[i];\n\t\t\tint y = stk[top];\n\t\t\tint lca = getLca(x, y);\n\t\t\twhile (top > 1 && dfn[stk[top - 1]] >= dfn[lca]) {\n\t\t\t\taddEdgeV(stk[top - 1], stk[top]);\n\t\t\t\ttop--;\n\t\t\t}\n\t\t\tif (lca != stk[top]) {\n\t\t\t\theadv[lca] = 0;\n\t\t\t\taddEdgeV(lca, stk[top]);\n\t\t\t\tstk[top] = lca;\n\t\t\t}\n\t\t\theadv[x] = 0;\n\t\t\tstk[++top] = x;\n\t\t}\n\t\twhile (top > 1) {\n\t\t\taddEdgeV(stk[top - 1], stk[top]);\n\t\t\ttop--;\n\t\t}\n\t\treturn stk[1];\n\t}\n\n\t// dp递归版，java会爆栈，C++可以通过\n\tpublic static void dp1(int u) {\n\t\tsiz[u] = isKey[u] ? 1 : 0;\n\t\tsum[u] = 0;\n\t\tif (isKey[u]) {\n\t\t\tfar[u] = near[u] = 0;\n\t\t} else {\n\t\t\tnear[u] = INF;\n\t\t\tfar[u] = -INF;\n\t\t}\n\t\tfor (int e = headv[u]; e > 0; e = nextv[e]) {\n\t\t\tdp1(tov[e]);\n\t\t}\n\t\tfor (int e = headv[u]; e > 0; e = nextv[e]) {\n\t\t\tint v = tov[e];\n\t\t\tlong len = dep[v] - dep[u];\n\t\t\tcostSum += (sum[u] + 1L * siz[u] * len) * siz[v] + sum[v] * siz[u];\n\t\t\tsiz[u] += siz[v];\n\t\t\tsum[u] += sum[v] + len * siz[v];\n\t\t\tcostMin = Math.min(costMin, near[u] + near[v] + len);\n\t\t\tcostMax = Math.max(costMax, far[u] + far[v] + len);\n\t\t\tnear[u] = Math.min(near[u], near[v] + len);\n\t\t\tfar[u] = Math.max(far[u], far[v] + len);\n\t\t}\n\t}\n\n\t// dp1的迭代版\n\tpublic static void dp2(int tree) {\n\t\tstacksize = 0;\n\t\tpush(tree, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = isKey[u] ? 1 : 0;\n\t\t\t\tsum[u] = 0;\n\t\t\t\tif (isKey[u]) {\n\t\t\t\t\tfar[u] = near[u] = 0;\n\t\t\t\t} else {\n\t\t\t\t\tnear[u] = INF;\n\t\t\t\t\tfar[u] = -INF;\n\t\t\t\t}\n\t\t\t\te = headv[u];\n\t\t\t} else {\n\t\t\t\te = nextv[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, e);\n\t\t\t\tpush(tov[e], 0, -1);\n\t\t\t} else {\n\t\t\t\tfor (int ei = headv[u]; ei > 0; ei = nextv[ei]) {\n\t\t\t\t\tint v = tov[ei];\n\t\t\t\t\tlong len = dep[v] - dep[u];\n\t\t\t\t\tcostSum += (sum[u] + 1L * siz[u] * len) * siz[v] + sum[v] * siz[u];\n\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\tsum[u] += sum[v] + len * siz[v];\n\t\t\t\t\tcostMin = Math.min(costMin, near[u] + near[v] + len);\n\t\t\t\t\tcostMax = Math.max(costMax, far[u] + far[v] + len);\n\t\t\t\t\tnear[u] = Math.min(near[u], near[v] + len);\n\t\t\t\t\tfar[u] = Math.max(far[u], far[v] + len);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tisKey[arr[i]] = true;\n\t\t}\n\t\tint tree = buildVirtualTree1();\n\t\t// int tree = buildVirtualTree2();\n\t\tcostSum = 0;\n\t\tcostMin = INF;\n\t\tcostMax = -INF;\n\t\t// dp1(tree);\n\t\tdp2(tree);\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tisKey[arr[i]] = false;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdgeG(u, v);\n\t\t\taddEdgeG(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tq = in.nextInt();\n\t\tfor (int t = 1; t <= q; t++) {\n\t\t\tk = in.nextInt();\n\t\t\tfor (int i = 1; i <= k; i++) {\n\t\t\t\tarr[i] = in.nextInt();\n\t\t\t}\n\t\t\tcompute();\n\t\t\tout.println(costSum + " " + costMin + " " + costMax);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_BigProject1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
