3a89a9b7-b7c2-4cc3-aef6-9cb011799c4b	c77c53ee-2f5b-457e-8e11-588526380953	java	package class180;\n\n// 消耗战，java版\n// 一共有n个节点，给定n-1条无向边，每条边有边权，所有节点组成一棵树\n// 一共有q条查询，每条查询格式如下\n// 查询 k a1 a2 ... ak : 给出了k个不同的关键节点，并且一定不包含1号节点\n//                       你可以随意选择边进行切断，切断的代价就是边权\n//                       目的是让所有关键点都无法到达1号节点，打印最小总代价\n// 1 <= n、q <= 5 * 10^5\n// 1 <= 所有查询给出的点的总数 <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2495\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_War1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, q, k;\n\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int[] weightg = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] headv = new int[MAXN];\n\tpublic static int[] nextv = new int[MAXN];\n\tpublic static int[] tov = new int[MAXN];\n\tpublic static int[] weightv = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\t// 上方最小距离的倍增表\n\tpublic static int[][] mindist = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static boolean[] isKey = new boolean[MAXN];\n\tpublic static int[] tmp = new int[MAXN << 1];\n\tpublic static int[] stk = new int[MAXN];\n\n\t// cost[u]表示虚树中，u下方的所有关键节点，都连不上u的话，最小总代价\n\tpublic static long[] cost = new long[MAXN];\n\n\tpublic static void addEdgeG(int u, int v, int w) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\tweightg[cntg] = w;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addEdgeV(int u, int v, int w) {\n\t\tnextv[++cntv] = headv[u];\n\t\ttov[cntv] = v;\n\t\tweightv[cntv] = w;\n\t\theadv[u] = cntv;\n\t}\n\n\tpublic static void sortByDfn(int[] nums, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r;\n\t\tint pivot = nums[(l + r) >> 1];\n\t\twhile (i <= j) {\n\t\t\twhile (dfn[nums[i]] < dfn[pivot]) i++;\n\t\t\twhile (dfn[nums[j]] > dfn[pivot]) j--;\n\t\t\tif (i <= j) {\n\t\t\t\tint tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsortByDfn(nums, l, j);\n\t\tsortByDfn(nums, i, r);\n\t}\n\n\tpublic static void dfs(int u, int fa, int w) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdfn[u] = ++cntd;\n\t\tstjump[u][0] = fa;\n\t\tmindist[u][0] = w;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\tmindist[u][p] = Math.min(mindist[u][p - 1], mindist[stjump[u][p - 1]][p - 1]);\n\t\t}\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tif (tog[e] != fa) {\n\t\t\t\tdfs(tog[e], u, weightg[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a; a = b; b = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\t// 已知u一定是v的祖先节点，返回u到v路径上的最小边权\n\tpublic static int getDist(int u, int v) {\n\t\tint dist = 100000001;\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[v][p]] >= dep[u]) {\n\t\t\t\tdist = Math.min(dist, mindist[v][p]);\n\t\t\t\tv = stjump[v][p];\n\t\t\t}\n\t\t}\n\t\treturn dist;\n\t}\n\n\t// 二次排序 + LCA连边的方式建立虚树\n\tpublic static int buildVirtualTree1() {\n\t\tsortByDfn(arr, 1, k);\n\t\t// 因为题目是让所有关键点不能和1号点连通\n\t\t// 所以一定要让1号点加入\n\t\tint len = 0;\n\t\ttmp[++len] = 1;\n\t\tfor (int i = 1; i < k; i++) {\n\t\t\ttmp[++len] = arr[i];\n\t\t\ttmp[++len] = getLca(arr[i], arr[i + 1]);\n\t\t}\n\t\ttmp[++len] = arr[k];\n\t\tsortByDfn(tmp, 1, len);\n\t\tint unique = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (tmp[unique] != tmp[i]) {\n\t\t\t\ttmp[++unique] = tmp[i];\n\t\t\t}\n\t\t}\n\t\tcntv = 0;\n\t\tfor (int i = 1; i <= unique; i++) {\n\t\t\theadv[tmp[i]] = 0;\n\t\t}\n\t\tfor (int i = 1; i < unique; i++) {\n\t\t\tint lca = getLca(tmp[i], tmp[i + 1]);\n\t\t\taddEdgeV(lca, tmp[i + 1], getDist(lca, tmp[i + 1]));\n\t\t}\n\t\treturn tmp[1];\n\t}\n\n\t// 单调栈的方式建立虚树\n\tpublic static int buildVirtualTree2() {\n\t\tsortByDfn(arr, 1, k);\n\t\t// 因为题目是让所有关键点不能和1号点连通\n\t\t// 所以一定要让1号点加入\n\t\tcntv = 0;\n\t\theadv[1] = 0;\n\t\tint top = 0;\n\t\tstk[++top] = 1;\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tint x = arr[i];\n\t\t\tint y = stk[top];\n\t\t\tint lca = getLca(x, y);\n\t\t\twhile (top > 1 && dfn[stk[top - 1]] >= dfn[lca]) {\n\t\t\t\taddEdgeV(stk[top - 1], stk[top], getDist(stk[top - 1], stk[top]));\n\t\t\t\ttop--;\n\t\t\t}\n\t\t\tif (lca != stk[top]) {\n\t\t\t\theadv[lca] = 0;\n\t\t\t\taddEdgeV(lca, stk[top], getDist(lca, stk[top]));\n\t\t\t\tstk[top] = lca;\n\t\t\t}\n\t\t\theadv[x] = 0;\n\t\t\tstk[++top] = x;\n\t\t}\n\t\twhile (top > 1) {\n\t\t\taddEdgeV(stk[top - 1], stk[top], getDist(stk[top - 1], stk[top]));\n\t\t\ttop--;\n\t\t}\n\t\treturn stk[1];\n\t}\n\n\tpublic static void dp(int u) {\n\t\tfor (int e = headv[u]; e > 0; e = nextv[e]) {\n\t\t\tdp(tov[e]);\n\t\t}\n\t\tcost[u] = 0;\n\t\tfor (int e = headv[u], v, w; e > 0; e = nextv[e]) {\n\t\t\tv = tov[e];\n\t\t\tw = weightv[e];\n\t\t\tif (isKey[v]) {\n\t\t\t\tcost[u] += w;\n\t\t\t} else {\n\t\t\t\tcost[u] += Math.min(cost[v], w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tisKey[arr[i]] = true;\n\t\t}\n\t\tint tree = buildVirtualTree1();\n\t\t// int tree = buildVirtualTree2();\n\t\tdp(tree);\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tisKey[arr[i]] = false;\n\t\t}\n\t\treturn cost[tree];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdgeG(u, v, w);\n\t\t\taddEdgeG(v, u, w);\n\t\t}\n\t\tdfs(1, 0, 0);\n\t\tq = in.nextInt();\n\t\tfor (int t = 1; t <= q; t++) {\n\t\t\tk = in.nextInt();\n\t\t\tfor (int i = 1; i <= k; i++) {\n\t\t\t\tarr[i] = in.nextInt();\n\t\t\t}\n\t\t\tout.println(compute());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_War1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
