\n//    }\n//    int mid = (l + r) / 2;\n//    cdq(l, mid);\n//    cdq(mid + 1, r);\n//    merge(l, mid, r);\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        arr[++cnt].v = num[i];\n//        arr[cnt].i = i;\n//        arr[cnt].d = 1;\n//        arr[cnt].q = 0;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        arr[++cnt].v = del[i];\n//        arr[cnt].i = pos[del[i]];\n//        arr[cnt].d = -1;\n//        arr[cnt].q = i;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> num[i];\n//        pos[num[i]] = i;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> del[i];\n//    }\n//    prepare();\n//    cdq(1, cnt);\n//    for (int i = 1; i < m; i++) {\n//        ans[i] += ans[i - 1];\n//    }\n//    for (int i = 0; i < m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}	模板：Code02_DynamicInversion2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c7fc49b2-ad46-4403-8eef-a606894ba9ac	67161c77-a40f-4fa2-9f44-19778c64647d	java	package class170;\n\n// 园丁的烦恼，java版\n// 有n棵树，每棵树给定位置坐标(x, y)，接下来有m条查询，格式如下\n// 查询 a b c d : 打印左上角(a, b)、右下角(c, d)的区域里有几棵树\n// 0 <= n <= 5 * 10^5\n// 1 <= m <= 5 * 10^5\n// 0 <= 坐标值 <= 10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P2163\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但无法通过测试用例，内存使用过大\n// 因为这道题只考虑C++能通过的空间极限，根本没考虑java的用户\n// 想通过用C++实现，本节课Code03_GardenerTrouble2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code03_GardenerTrouble1 {\n\n\tpublic static int MAXN = 500001 * 5;\n\tpublic static int n, m;\n\n\t// op == 1代表树木，x、y\n\t// op == 2代表查询，x、y、效果v、查询编号q\n\tpublic static int[][] arr = new int[MAXN][5];\n\tpublic static int cnt = 0;\n\n\t// 归并排序需要\n\tpublic static int[][] tmp = new int[MAXN][5];\n\n\t// 问题的答案\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void clone(int[] a, int[] b) {\n\t\ta[0] = b[0];\n\t\ta[1] = b[1];\n\t\ta[2] = b[2];\n\t\ta[3] = b[3];\n\t\ta[4] = b[4];\n\t}\n\n\tpublic static void addTree(int x, int y) {\n\t\tarr[++cnt][0] = 1;\n\t\tarr[cnt][1] = x;\n\t\tarr[cnt][2] = y;\n\t}\n\n\tpublic static void addQuery(int x, int y, int v, int q) {\n\t\tarr[++cnt][0] = 2;\n\t\tarr[cnt][1] = x;\n\t\tarr[cnt][2] = y;\n\t\tarr[cnt][3] = v;\n\t\tarr[cnt][4] = q;\n\t}\n\n\tpublic static void merge(int l, int m, int r) {\n\t\tint p1, p2, tree = 0;\n\t\tfor (p1 = l - 1, p2 = m + 1; p2 <= r; p2++) {\n\t\t\twhile (p1 + 1 <= m && arr[p1 + 1][2] <= arr[p2][2]) {\n\t\t\t\tp1++;\n\t\t\t\tif (arr[p1][0] == 1) {\n\t\t\t\t\ttree++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (arr[p2][0] == 2) {\n\t\t\t\tans[arr[p2][4]] += tree * arr[p2][3];\n\t\t\t}\n\t\t}\n\t\t// 下面是经典归并的过程，为啥不直接排序了？\n\t\t// 因为没有用到高级数据结构，复杂度可以做到O(n * log n)\n\t\t// 那么就维持最好的复杂度，不用排序\n\t\tp1 = l;\n\t\tp2 = m + 1;\n\t\tint i = l;\n\t\twhile (p1 <= m && p2 <= r) {\n\t\t\tclone(tmp[i++], arr[p1][2] <= arr[p2][2] ? arr[p1++] : arr[p2++]);\n\t\t}\n\t\twhile (p1 <= m) {\n\t\t\tclone(tmp[i++], arr[p1++]);\n\t\t}\n\t\twhile (p2 <= r) {\n\t\t\tclone(tmp[i++], arr[p2++]);\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tclone(arr[i], tmp[i]);\n\t\t}\n\t}\n\n\tpublic static void cdq(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid);\n\t\tcdq(mid + 1, r);\n\t\tmerge(l, mid, r);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= n; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\taddTree(x, y);\n\t\t}\n\t\tfor (int i = 1, a, b, c, d; i <= m; i++) {\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\td = in.nextInt();\n\t\t\taddQuery(c, d, 1, i);\n\t\t\taddQuery(a - 1, b - 1, 1, i);\n\t\t\taddQuery(a - 1, d, -1, i);\n\t\t\taddQuery(c, b - 1, -1, i);\n\t\t}\n\t\tArrays.sort(arr, 1, cnt + 1, (a, b) -> a[1] != b[1] ? a[1] - b[1] : a[0] - b[0]);\n\t\tcdq(1, cnt);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_GardenerTrouble1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
