2a862f39-5163-423e-9b9a-a286586a69a3	67161c77-a40f-4fa2-9f44-19778c64647d	java	package class170;\n\n// 老C的任务，java版\n// 有n个基站，每个基站给定x、y、v，表示基站在(x, y)位置，功率为v\n// 接下来有m条查询，每条查询格式如下\n// 查询 a b c d : 打印左上角(a, b)、右下角(c, d)的区域里基站的功率和\n// 1 <= n、m <= 10^5\n// 其余数值都在int类型的范围\n// 测试链接 : https://www.luogu.com.cn/problem/P3755\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code04_TaskOfC1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m;\n\n\t// op == 1代表基站，x、y、功率v\n\t// op == 2代表查询，x、y、效果v、查询编号q\n\tpublic static int[][] arr = new int[MAXN][5];\n\tpublic static int cnt = 0;\n\n\t// 归并排序需要\n\tpublic static int[][] tmp = new int[MAXN][5];\n\n\t// 问题的答案\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void clone(int[] a, int[] b) {\n\t\ta[0] = b[0];\n\t\ta[1] = b[1];\n\t\ta[2] = b[2];\n\t\ta[3] = b[3];\n\t\ta[4] = b[4];\n\t}\n\n\tpublic static void addStation(int x, int y, int v) {\n\t\tarr[++cnt][0] = 1;\n\t\tarr[cnt][1] = x;\n\t\tarr[cnt][2] = y;\n\t\tarr[cnt][3] = v;\n\t}\n\n\tpublic static void addQuery(int x, int y, int v, int q) {\n\t\tarr[++cnt][0] = 2;\n\t\tarr[cnt][1] = x;\n\t\tarr[cnt][2] = y;\n\t\tarr[cnt][3] = v;\n\t\tarr[cnt][4] = q;\n\t}\n\n\tpublic static void merge(int l, int m, int r) {\n\t\tint p1, p2;\n\t\tlong sum = 0;\n\t\tfor (p1 = l - 1, p2 = m + 1; p2 <= r; p2++) {\n\t\t\twhile (p1 + 1 <= m && arr[p1 + 1][2] <= arr[p2][2]) {\n\t\t\t\tp1++;\n\t\t\t\tif (arr[p1][0] == 1) {\n\t\t\t\t\tsum += arr[p1][3];\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (arr[p2][0] == 2) {\n\t\t\t\tans[arr[p2][4]] += sum * arr[p2][3];\n\t\t\t}\n\t\t}\n\t\t// 下面是经典归并的过程，为啥不直接排序了？\n\t\t// 因为没有用到高级数据结构，复杂度可以做到O(n * log n)\n\t\t// 那么就维持最好的复杂度，不用排序\n\t\tp1 = l;\n\t\tp2 = m + 1;\n\t\tint i = l;\n\t\twhile (p1 <= m && p2 <= r) {\n\t\t\tclone(tmp[i++], arr[p1][2] <= arr[p2][2] ? arr[p1++] : arr[p2++]);\n\t\t}\n\t\twhile (p1 <= m) {\n\t\t\tclone(tmp[i++], arr[p1++]);\n\t\t}\n\t\twhile (p2 <= r) {\n\t\t\tclone(tmp[i++], arr[p2++]);\n\t\t}\n\t\tfor (i = l; i <= r; i++) {\n\t\t\tclone(arr[i], tmp[i]);\n\t\t}\n\t}\n\n\tpublic static void cdq(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid);\n\t\tcdq(mid + 1, r);\n\t\tmerge(l, mid, r);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, x, y, v; i <= n; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddStation(x, y, v);\n\t\t}\n\t\tfor (int i = 1, a, b, c, d; i <= m; i++) {\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\td = in.nextInt();\n\t\t\taddQuery(c, d, 1, i);\n\t\t\taddQuery(a - 1, b - 1, 1, i);\n\t\t\taddQuery(a - 1, d, -1, i);\n\t\t\taddQuery(c, b - 1, -1, i);\n\t\t}\n\t\tArrays.sort(arr, 1, cnt + 1, (a, b) -> a[1] != b[1] ? a[1] - b[1] : a[0] - b[0]);\n\t\tcdq(1, cnt);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_TaskOfC1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
