5bcff4f6-e5c9-476b-8363-21fb1693f6cd	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 普通莫队入门题，java版\n// 给定一个长度为n的数组arr，一共有q条查询，格式如下\n// 查询 l r : 打印arr[l..r]范围上有几种不同的数字\n// 1 <= n <= 3 * 10^4\n// 1 <= arr[i] <= 10^6\n// 1 <= q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/SP3267\n// 测试链接 : https://www.spoj.com/problems/DQUERY/\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code01_MoAlgorithm1 {\n\n\tpublic static int MAXN = 30001;\n\tpublic static int MAXV = 1000001;\n\tpublic static int MAXQ = 200001;\n\tpublic static int n, q;\n\tpublic static int[] arr = new int[MAXN];\n\t// jobl, jobr, 问题id\n\tpublic static int[][] query = new int[MAXQ][3];\n\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] cnt = new int[MAXV];\n\tpublic static int kind = 0;\n\n\tpublic static int[] ans = new int[MAXQ];\n\n\t// 普通莫队经典排序\n\tpublic static class QueryCmp1 implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\t// 普通莫队奇偶排序\n\tpublic static class QueryCmp2 implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif ((bi[a[0]] & 1) == 1) {\n\t\t\t\treturn a[1] - b[1];\n\t\t\t} else {\n\t\t\t\treturn b[1] - a[1];\n\t\t\t}\n\t\t}\n\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (--cnt[num] == 0) {\n\t\t\tkind--;\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tif (++cnt[num] == 1) {\n\t\t\tkind++;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\t// Arrays.sort(query, 1, q + 1, new QueryCmp1());\n\t\tArrays.sort(query, 1, q + 1, new QueryCmp2());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tans[query[i][2]] = kind;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_MoAlgorithm1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b59759fe-ef98-40c7-bc1c-81d2f509c347	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 小B的询问，java版\n// 给定一个长度为n的数组arr，所有数字在[1..k]范围上\n// 定义f(i) = i这种数的出现次数的平方\n// 一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，打印 f(1) + f(2) + .. + f(k) 的值\n// 1 <= n、m、k <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P2709\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code02_QueryFromB1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int n, m, k;\n\tpublic static int[] arr = new int[MAXN];\n\t// jobl, jobr, 问题id\n\tpublic static int[][] query = new int[MAXN][3];\n\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] cnt = new int[MAXN];\n\tpublic static int sum = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\tpublic static void del(int num) {\n\t\tsum -= cnt[num] * cnt[num];\n\t\tcnt[num]--;\n\t\tsum += cnt[num] * cnt[num];\n\t}\n\n\tpublic static void add(int num) {\n\t\tsum -= cnt[num] * cnt[num];\n\t\tcnt[num]++;\n\t\tsum += cnt[num] * cnt[num];\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tans[query[i][2]] = sum;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code02_QueryFromB1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
