df09d926-8f29-40ec-8b0e-921313ec896c	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 小Z的袜子，java版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，随机选不同位置的两个数，打印数值相同的概率\n//            概率用分数的形式表达，并且约分到最简的形式\n// 1 <= n、m、arr[i] <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P1494\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code03_SockFromZ2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code03_SockFromZ1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] cnt = new int[MAXN];\n\tpublic static long sum = 0;\n\n\t// 每个查询的分子的值\n\tpublic static long[] ans1 = new long[MAXN];\n\t// 每个查询的分母的值\n\tpublic static long[] ans2 = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\tpublic static long gcd(long a, long b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static void del(int num) {\n\t\tsum -= cnt[num] * cnt[num];\n\t\tcnt[num]--;\n\t\tsum += cnt[num] * cnt[num];\n\t}\n\n\tpublic static void add(int num) {\n\t\tsum -= cnt[num] * cnt[num];\n\t\tcnt[num]++;\n\t\tsum += cnt[num] * cnt[num];\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint id = query[i][2];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tif (jobl == jobr) {\n\t\t\t\tans1[id] = 0;\n\t\t\t\tans2[id] = 1;\n\t\t\t} else {\n\t\t\t\tans1[id] = sum - (jobr - jobl + 1);\n\t\t\t\tans2[id] = 1L * (jobr - jobl + 1) * (jobr - jobl);\n\t\t\t\tlong g = gcd(ans1[id], ans2[id]);\n\t\t\t\tans1[id] /= g;\n\t\t\t\tans2[id] /= g;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans1[i] + "/" + ans2[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code03_SockFromZ1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
