c804d13b-8935-4339-987c-d08951980c4f	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 异或序列，java版\n// 给定一个长度为n的数组arr，给定一个数字k，一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，有多少子数组的异或和为k，打印其数量\n// 0 <= n、m、k、arr[i] <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4462\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code05_XorSequence1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXS = 1 << 20;\n\tpublic static int n, m, k;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] bi = new int[MAXN];\n\n\t// pre[i] == x，表示前i个数字的前缀异或和为x\n\tpublic static int[] pre = new int[MAXN];\n\t// cnt[x] = a，表示窗口内，前缀异或和x，一共有a个\n\tpublic static long[] cnt = new long[MAXS];\n\t// num表示窗口内，异或和为k的子数组数量\n\tpublic static long num;\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\t// 前缀异或和x要删除一次\n\tpublic static void del(int x) {\n\t\tif (k != 0) {\n\t\t\tnum -= cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum -= (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t\tcnt[x]--;\n\t\tif (k != 0) {\n\t\t\tnum += cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum += (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t}\n\n\t// 前缀异或和x要增加一次\n\tpublic static void add(int x) {\n\t\tif (k != 0) {\n\t\t\tnum -= cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum -= (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t\tcnt[x]++;\n\t\tif (k != 0) {\n\t\t\tnum += cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum += (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tpre[i] = pre[i - 1] ^ arr[i];\n\t\t}\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t// 任务范围[jobl, jobr]，但是前缀可能性会多一种\n\t\t\t// 所以左边界-1\n\t\t\tint jobl = query[i][0] - 1;\n\t\t\tint jobr = query[i][1];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(pre[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(pre[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(pre[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(pre[winr--]);\n\t\t\t}\n\t\t\tans[query[i][2]] = num;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_XorSequence1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
