fc114f16-e0aa-479b-981c-1e659ba3ec46	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 统计出现1次的数，java版\n// 给定一个长度为n的数组arr，下标0~n-1，一共有m条操作，格式如下\n// 操作 1 pos val : 把arr[pos]的值设置成val\n// 操作 2 l r     : 查询arr[l..r]范围上，有多少种数出现了1次\n// 0 <= n、m、arr[i] <= 2 * 10^5 \n// 测试链接 : https://www.luogu.com.cn/problem/SP30906\n// 测试链接 : https://www.spoj.com/problems/ADAUNIQ/\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code07_UniqueNumbers2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code07_UniqueNumbers1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[][] query = new int[MAXN][4];\n\tpublic static int[][] update = new int[MAXN][2];\n\tpublic static int cntq, cntu;\n\n\t// 每种数字的词频统计\n\tpublic static int[] cnt = new int[MAXN];\n\t// curCnt代表出现次数1次的数有几种\n\tpublic static int curCnt = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif (bi[a[1]] != bi[b[1]]) {\n\t\t\t\treturn bi[a[1]] - bi[b[1]];\n\t\t\t}\n\t\t\treturn a[2] - b[2];\n\t\t}\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (cnt[num] == 1) {\n\t\t\tcurCnt--;\n\t\t}\n\t\tif (cnt[num] == 2) {\n\t\t\tcurCnt++;\n\t\t}\n\t\tcnt[num]--;\n\t}\n\n\tpublic static void add(int num) {\n\t\tif (cnt[num] == 0) {\n\t\t\tcurCnt++;\n\t\t}\n\t\tif (cnt[num] == 1) {\n\t\t\tcurCnt--;\n\t\t}\n\t\tcnt[num]++;\n\t}\n\n\tpublic static void moveTime(int jobl, int jobr, int tim) {\n\t\tint pos = update[tim][0];\n\t\tint val = update[tim][1];\n\t\tif (jobl <= pos && pos <= jobr) {\n\t\t\tdel(arr[pos]);\n\t\t\tadd(val);\n\t\t}\n\t\tint tmp = arr[pos];\n\t\tarr[pos] = val;\n\t\tupdate[tim][1] = tmp;\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0, wint = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint jobt = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\twhile (wint < jobt) {\n\t\t\t\tmoveTime(jobl, jobr, ++wint);\n\t\t\t}\n\t\t\twhile (wint > jobt) {\n\t\t\t\tmoveTime(jobl, jobr, wint--);\n\t\t\t}\n\t\t\tans[id] = curCnt;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = Math.max(1, (int) Math.pow(n, 2.0 / 3));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, l, r, pos, val; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tpos = in.nextInt();\n\t\t\t\tval = in.nextInt();\n\t\t\t\tcntu++;\n\t\t\t\tupdate[cntu][0] = pos + 1;\n\t\t\t\tupdate[cntu][1] = val;\n\t\t\t} else {\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tcntq++;\n\t\t\t\tquery[cntq][0] = l + 1;\n\t\t\t\tquery[cntq][1] = r + 1;\n\t\t\t\tquery[cntq][2] = cntu;\n\t\t\t\tquery[cntq][3] = cntq;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code07_UniqueNumbers1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
