262af843-14a3-41c3-9c59-5370815576ab	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class176;\n\n// 机器学习，java版\n// 给定一个长度为n的数组arr，一共有m条操作，操作格式如下\n// 操作 1 l r     : arr[l..r]范围上，每种数字出现的次数，假设构成一个集合\n//                  打印这个集合中，没出现过的最小正数\n// 操作 2 pos val : 把arr[pos]的值设置成val\n// 1 <= n、m <= 10^5\n// 1 <= arr[i]、val <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF940F\n// 测试链接 : https://codeforces.com/problemset/problem/940/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code08_MachineLearning1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN << 1];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[][] query = new int[MAXN][4];\n\tpublic static int[][] update = new int[MAXN][2];\n\tpublic static int cntq, cntu;\n\n\t// cnt1[i] = j，表示i这种数出现了j次\n\t// cnt2[i] = j，表示出现次数为i的数有j种\n\tpublic static int[] cnt1 = new int[MAXN << 1];\n\tpublic static int[] cnt2 = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif (bi[a[1]] != bi[b[1]]) {\n\t\t\t\treturn bi[a[1]] - bi[b[1]];\n\t\t\t}\n\t\t\treturn a[2] - b[2];\n\t\t}\n\t}\n\n\tpublic static int kth(int len, int num) {\n\t\tint left = 1, right = len, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void del(int num) {\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]--;\n\t\tcnt2[cnt1[num]]++;\n\t}\n\n\tpublic static void add(int num) {\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]++;\n\t\tcnt2[cnt1[num]]++;\n\t}\n\n\tpublic static void moveTime(int jobl, int jobr, int tim) {\n\t\tint pos = update[tim][0];\n\t\tint val = update[tim][1];\n\t\tif (jobl <= pos && pos <= jobr) {\n\t\t\tdel(arr[pos]);\n\t\t\tadd(val);\n\t\t}\n\t\tint tmp = arr[pos];\n\t\tarr[pos] = val;\n\t\tupdate[tim][1] = tmp;\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0, wint = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint jobt = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\twhile (wint < jobt) {\n\t\t\t\tmoveTime(jobl, jobr, ++wint);\n\t\t\t}\n\t\t\twhile (wint > jobt) {\n\t\t\t\tmoveTime(jobl, jobr, wint--);\n\t\t\t}\n\t\t\t// 如下枚举看似暴力，其实O(根号n)的复杂度\n\t\t\tint ret = 1;\n\t\t\twhile (ret <= n && cnt2[ret] > 0) {\n\t\t\t\tret++;\n\t\t\t}\n\t\t\tans[id] = ret;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint len = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++len] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tsorted[++len] = update[i][1];\n\t\t}\n\t\tArrays.sort(sorted, 1, len + 1);\n\t\tint tmp = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (sorted[tmp] != sorted[i]) {\n\t\t\t\tsorted[++tmp] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tlen = tmp;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(len, arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tupdate[i][1] = kth(len, update[i][1]);\n\t\t}\n\t\tint blen = Math.max(1, (int) Math.pow(n, 2.0 / 3));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, l, r, pos, val; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tcntq++;\n\t\t\t\tquery[cntq][0] = l;\n\t\t\t\tquery[cntq][1] = r;\n\t\t\t\tquery[cntq][2] = cntu;\n\t\t\t\tquery[cntq][3] = cntq;\n\t\t\t} else {\n\t\t\t\tpos = in.nextInt();\n\t\t\t\tval = in.nextInt();\n\t\t\t\tcntu++;\n\t\t\t\tupdate[cntu][0] = pos;\n\t\t\t\tupdate[cntu][1] = val;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code08_MachineLearning1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8d1f0f43-0704-4897-ac60-a0d007257d43	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class177;\n\n// 只增回滚莫队入门题，java版\n// 给定一个长度为n的数组arr，下面定义重要度的概念\n// 如果一段范围上，数字x出现c次，那么这个数字的重要度为x * c\n// 范围上的最大重要度，就是该范围上，每种数字的重要度，取最大值\n// 一共有m条查询，格式 l r : 打印arr[l..r]范围上的最大重要度\n// 1 <= n、m <= 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/AT_joisc2014_c\n// 测试链接 : https://atcoder.jp/contests/joisc2014/tasks/joisc2014_c\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code01_MoAddUndo1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int cntv;\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] br = new int[MAXB];\n\n\t// 词频表\n\tpublic static int[] cnt = new int[MAXN];\n\t// 当前窗口的最大重要度\n\tpublic static long curAns = 0;\n\n\t// 收集所有答案\n\tpublic static long[] ans = new long[MAXN];\n\n\t// 只增回滚莫队经典排序\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\t// 暴力遍历arr[l..r]得到答案\n\tpublic static long force(int l, int r) {\n\t\tlong ret = 0;\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tcnt[arr[i]]++;\n\t\t}\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tret = Math.max(ret, (long) cnt[arr[i]] * sorted[arr[i]]);\n\t\t}\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tcnt[arr[i]]--;\n\t\t}\n\t\treturn ret;\n\t}\n\n\t// 窗口增加num，词频和答案都更新\n\tpublic static void add(int num) {\n\t\tcnt[num]++;\n\t\tcurAns = Math.max(curAns, (long) cnt[num] * sorted[num]);\n\t}\n\n\t// 窗口减少num，词频更新、答案不更新\n\tpublic static void del(int num) {\n\t\tcnt[num]--;\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int block = 1, qi = 1; block <= bnum && qi <= m; block++) {\n\t\t\tcurAns = 0;\n\t\t\tArrays.fill(cnt, 1, cntv + 1, 0);\n\t\t\tint winl = br[block] + 1, winr = br[block];\n\t\t\tfor (; qi <= m && bi[query[qi][0]] == block; qi++) {\n\t\t\t\tint jobl = query[qi][0];\n\t\t\t\tint jobr = query[qi][1];\n\t\t\t\tint id = query[qi][2];\n\t\t\t\tif (jobr <= br[block]) {\n\t\t\t\t\tans[id] = force(jobl, jobr);\n\t\t\t\t} else {\n\t\t\t\t\twhile (winr < jobr) {\n\t\t\t\t\t\tadd(arr[++winr]);\n\t\t\t\t\t}\n\t\t\t\t\tlong backup = curAns;\n\t\t\t\t\twhile (winl > jobl) {\n\t\t\t\t\t\tadd(arr[--winl]);\n\t\t\t\t\t}\n\t\t\t\t\tans[id] = curAns;\n\t\t\t\t\tcurAns = backup;\n\t\t\t\t\twhile (winl <= br[block]) {\n\t\t\t\t\t\tdel(arr[winl++]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\tcntv = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[cntv] != sorted[i]) {\n\t\t\t\tsorted[++cntv] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t}\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_MoAddUndo1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
