eed45011-5e4f-42f4-bef6-4a59121f4b43	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class177;\n\n// 达到阈值的最小众数，java版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r k : arr[l..r]范围上，如果所有数字的出现次数 < k，打印-1\n//              如果有些数字的出现次数 >= k，打印其中的最小众数\n// 1 <= n <= 10^4\n// 1 <= m <= 5 * 10^4\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://leetcode.cn/problems/threshold-majority-queries/\n// 提交以下代码中的Solution类，可以通过所有测试用例\n\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code02_ThresholdMajority1 {\n\n\tclass Solution {\n\n\t\tpublic static int MAXN = 10001;\n\t\tpublic static int MAXM = 50001;\n\t\tpublic static int MAXB = 301;\n\t\tpublic static int n, m;\n\t\tpublic static int[] arr = new int[MAXN];\n\t\tpublic static int[][] query = new int[MAXM][4];\n\t\tpublic static int[] sorted = new int[MAXN];\n\t\tpublic static int cntv;\n\n\t\tpublic static int blen, bnum;\n\t\tpublic static int[] bi = new int[MAXN];\n\t\tpublic static int[] br = new int[MAXB];\n\n\t\tpublic static int[] cnt = new int[MAXN];\n\t\tpublic static int maxCnt;\n\t\tpublic static int minMode;\n\n\t\tpublic static int[] ans = new int[MAXM];\n\n\t\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t\t@Override\n\t\t\tpublic int compare(int[] a, int[] b) {\n\t\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t\t}\n\t\t\t\treturn a[1] - b[1];\n\t\t\t}\n\n\t\t}\n\n\t\tpublic static int kth(int num) {\n\t\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\t\twhile (left <= right) {\n\t\t\t\tmid = (left + right) >> 1;\n\t\t\t\tif (sorted[mid] <= num) {\n\t\t\t\t\tret = mid;\n\t\t\t\t\tleft = mid + 1;\n\t\t\t\t} else {\n\t\t\t\t\tright = mid - 1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn ret;\n\t\t}\n\n\t\tpublic static int force(int l, int r, int k) {\n\t\t\tint mx = 0;\n\t\t\tint who = 0;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tcnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tint num = arr[i];\n\t\t\t\tif (cnt[num] > mx || (cnt[num] == mx && num < who)) {\n\t\t\t\t\tmx = cnt[num];\n\t\t\t\t\twho = num;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tcnt[arr[i]]--;\n\t\t\t}\n\t\t\treturn mx >= k ? sorted[who] : -1;\n\t\t}\n\n\t\tpublic static void add(int num) {\n\t\t\tcnt[num]++;\n\t\t\tif (cnt[num] > maxCnt || (cnt[num] == maxCnt && num < minMode)) {\n\t\t\t\tmaxCnt = cnt[num];\n\t\t\t\tminMode = num;\n\t\t\t}\n\t\t}\n\n\t\tpublic static void del(int num) {\n\t\t\tcnt[num]--;\n\t\t}\n\n\t\tpublic static void compute() {\n\t\t\tfor (int block = 1, qi = 1; block <= bnum && qi <= m; block++) {\n\t\t\t\tmaxCnt = 0;\n\t\t\t\tminMode = 0;\n\t\t\t\tArrays.fill(cnt, 1, cntv + 1, 0);\n\t\t\t\tint winl = br[block] + 1, winr = br[block];\n\t\t\t\tfor (; qi <= m && bi[query[qi][0]] == block; qi++) {\n\t\t\t\t\tint jobl = query[qi][0];\n\t\t\t\t\tint jobr = query[qi][1];\n\t\t\t\t\tint jobk = query[qi][2];\n\t\t\t\t\tint id = query[qi][3];\n\t\t\t\t\tif (jobr <= br[block]) {\n\t\t\t\t\t\tans[id] = force(jobl, jobr, jobk);\n\t\t\t\t\t} else {\n\t\t\t\t\t\twhile (winr < jobr) {\n\t\t\t\t\t\t\tadd(arr[++winr]);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tint backupCnt = maxCnt;\n\t\t\t\t\t\tint backupNum = minMode;\n\t\t\t\t\t\twhile (winl > jobl) {\n\t\t\t\t\t\t\tadd(arr[--winl]);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (maxCnt >= jobk) {\n\t\t\t\t\t\t\tans[id] = sorted[minMode];\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tans[id] = -1;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tmaxCnt = backupCnt;\n\t\t\t\t\t\tminMode = backupNum;\n\t\t\t\t\t\twhile (winl <= br[block]) {\n\t\t\t\t\t\t\tdel(arr[winl++]);\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic static void prepare() {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tsorted[i] = arr[i];\n\t\t\t}\n\t\t\tArrays.sort(sorted, 1, n + 1);\n\t\t\tcntv = 1;\n\t\t\tfor (int i = 2; i <= n; i++) {\n\t\t\t\tif (sorted[cntv] != sorted[i]) {\n\t\t\t\t\tsorted[++cntv] = sorted[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tarr[i] = kth(arr[i]);\n\t\t\t}\n\t\t\tblen = (int) Math.sqrt(n);\n\t\t\tbnum = (n + blen - 1) / blen;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t\t}\n\t\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t\t}\n\n\t\tpublic static int[] subarrayMajority(int[] nums, int[][] queries) {\n\t\t\tn = nums.length;\n\t\t\tm = queries.length;\n\t\t\tfor (int i = 1, j = 0; i <= n; i++, j++) {\n\t\t\t\tarr[i] = nums[j];\n\t\t\t}\n\t\t\tfor (int i = 1, j = 0; i <= m; i++, j++) {\n\t\t\t\tquery[i][0] = queries[j][0] + 1;\n\t\t\t\tquery[i][1] = queries[j][1] + 1;\n\t\t\t\tquery[i][2] = queries[j][2];\n\t\t\t\tquery[i][3] = i;\n\t\t\t}\n\t\t\tprepare();\n\t\t\tcompute();\n\t\t\tint[] ret = new int[m];\n\t\t\tfor (int i = 1, j = 0; i <= m; i++, j++) {\n\t\t\t\tret[j] = ans[i];\n\t\t\t}\n\t\t\treturn ret;\n\t\t}\n\n\t}\n\n}\n	模板：Code02_ThresholdMajority1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
