2ec6b669-a839-41a4-98ca-867fe6d1fd07	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class179;\n\n// 美好的每一天，java版\n// 给定一个长度为n的字符串str，其中都是小写字母\n// 如果一个子串重新排列字符之后能成为回文串，那么该子串叫做达标子串\n// 接下来有m条查询，格式为 l r : 打印str[l..r]范围上有多少达标子串\n// 1 <= n、m <= 6 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P3604\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code01_NiceDay2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code01_NiceDay1 {\n\n\tpublic static int MAXN = 60002;\n\tpublic static int MAXV = 1 << 26;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[] cnt = new int[MAXV];\n\tpublic static long curAns = 0;\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif ((bi[a[0]] & 1) == 1) {\n\t\t\t\treturn a[1] - b[1];\n\t\t\t} else {\n\t\t\t\treturn b[1] - a[1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int s) {\n\t\tcurAns += cnt[s];\n\t\tcnt[s]++;\n\t\tfor (int i = 0; i < 26; i++) {\n\t\t\tcurAns += cnt[s ^ (1 << i)];\n\t\t}\n\t}\n\n\tpublic static void del(int s) {\n\t\tcnt[s]--;\n\t\tcurAns -= cnt[s];\n\t\tfor (int i = 0; i < 26; i++) {\n\t\t\tcurAns -= cnt[s ^ (1 << i)];\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint id = query[i][2];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tans[id] = curAns;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] ^= arr[i - 1];\n\t\t}\n\t\tfor (int i = n; i >= 0; i--) {\n\t\t\tarr[i + 1] = arr[i];\n\t\t}\n\t\tn++;\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][1]++;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tchar c;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tc = in.nextLowerCase();\n\t\t\tarr[i] = 1 << (c - 'a');\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextLowerCase() throws IOException {\n\t\t\tint c;\n\t\t\twhile (true) {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c >= 'a' && c <= 'z')\n\t\t\t\t\treturn (char) c;\n\t\t\t}\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_NiceDay1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
