n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        query[i].r++;\n//    }\n//    sort(query + 1, query + m + 1, QueryCmp);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    char c;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> c;\n//        arr[i] = 1 << (c - 'a');\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> query[i].l >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}	模板：Code01_NiceDay2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9d67390f-0582-4083-b417-078abaebe001	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class179;\n\n// 简单的询问，java版\n// 给定一个长度为n的数组arr，下标从1到n\n// 函数get(l, r, x) = arr[l..r]范围上，数组x出现的次数\n// 接下来有q条查询，格式如下\n// 查询 l1 r1 l2 r2 : 每种x都算，打印 get(l1, r1, x) * get(l2, r2, x) 的累加和\n// 1 <= n、q <= 5 * 10^4\n// 1 <= arr[i] <= n\n// 测试链接 : https://www.luogu.com.cn/problem/P5268\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code02_SimpleQuery1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int n, q, cntq;\n\tpublic static int[] arr = new int[MAXN];\n\t// 查询任务，siz1、siz2、op、id\n\tpublic static int[][] query = new int[MAXN << 2][4];\n\tpublic static int[] bi = new int[MAXN];\n\n\t// cnt1 : arr[1..siz1]范围内每种数字出现的次数\n\t// cnt2 : arr[1..siz2]范围内每种数字出现的次数\n\tpublic static int[] cnt1 = new int[MAXN];\n\tpublic static int[] cnt2 = new int[MAXN];\n\tpublic static long curAns = 0;\n\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif ((bi[a[0]] & 1) == 1) {\n\t\t\t\treturn a[1] - b[1];\n\t\t\t} else {\n\t\t\t\treturn b[1] - a[1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addQuery(int siz1, int siz2, int op, int id) {\n\t\tquery[++cntq][0] = siz1;\n\t\tquery[cntq][1] = siz2;\n\t\tquery[cntq][2] = op;\n\t\tquery[cntq][3] = id;\n\t}\n\n\t// win1和win2不代表一段区间，而是代表两个独立区域各自去覆盖arr\n\t// win1 = 0，win2 = 0，表示两个覆盖区域一开始都没有数字\n\t// job1和job2也不代表区间，而是代表两个区域各自要覆盖多大\n\tpublic static void compute() {\n\t\tint win1 = 0, win2 = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint job1 = query[i][0];\n\t\t\tint job2 = query[i][1];\n\t\t\tint op = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (win1 < job1) {\n\t\t\t\twin1++;\n\t\t\t\tcnt1[arr[win1]]++;\n\t\t\t\tcurAns += cnt2[arr[win1]];\n\t\t\t}\n\t\t\twhile (win1 > job1) {\n\t\t\t\tcnt1[arr[win1]]--;\n\t\t\t\tcurAns -= cnt2[arr[win1]];\n\t\t\t\twin1--;\n\t\t\t}\n\t\t\twhile (win2 < job2) {\n\t\t\t\twin2++;\n\t\t\t\tcnt2[arr[win2]]++;\n\t\t\t\tcurAns += cnt1[arr[win2]];\n\t\t\t}\n\t\t\twhile (win2 > job2) {\n\t\t\t\tcnt2[arr[win2]]--;\n\t\t\t\tcurAns -= cnt1[arr[win2]];\n\t\t\t\twin2--;\n\t\t\t}\n\t\t\tans[id] += curAns * op;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tif (query[i][0] > query[i][1]) {\n\t\t\t\tint tmp = query[i][0];\n\t\t\t\tquery[i][0] = query[i][1];\n\t\t\t\tquery[i][1] = tmp;\n\t\t\t}\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, l1, r1, l2, r2; i <= q; i++) {\n\t\t\tl1 = in.nextInt();\n\t\t\tr1 = in.nextInt();\n\t\t\tl2 = in.nextInt();\n\t\t\tr2 = in.nextInt();\n\t\t\taddQuery(r1, r2, 1, i);\n\t\t\taddQuery(r1, l2 - 1, -1, i);\n\t\t\taddQuery(l1 - 1, r2, -1, i);\n\t\t\taddQuery(l1 - 1, l2 - 1, 1, i);\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_SimpleQuery1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
