    }\n//        ans[id] += curAns * op;\n//    }\n//}\n//\n//void prepare() {\n//    int blen = (int)sqrt(n);\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= cntq; i++) {\n//        if (query[i].siz1 > query[i].siz2) {\n//            swap(query[i].siz1, query[i].siz2);\n//        }\n//    }\n//    sort(query + 1, query + cntq + 1, QueryCmp);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    cin >> q;\n//    for (int i = 1, l1, r1, l2, r2; i <= q; i++) {\n//        cin >> l1 >> r1 >> l2 >> r2;\n//        addQuery(r1, r2, 1, i);\n//        addQuery(r1, l2 - 1, -1, i);\n//        addQuery(l1 - 1, r2, -1, i);\n//        addQuery(l1 - 1, l2 - 1, 1, i);\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= q; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}	模板：Code02_SimpleQuery2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c273619e-76cc-4409-9579-febb67d80093	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class179;\n\n// 区间lcp达标对，java版\n// 给定一个长度为n的字符串str，还有一个参数k\n// 位置a开头和位置b开头的字符串，如果最长公共前缀的长度 >= k，那么(a, b)构成lcp达标对\n// 构成lcp达标对，必须是不同的位置，并且(a, b)和(b, a)只算一个达标对，不要重复统计\n// 接下来有m条查询，格式为 l r : str[l..r]范围上，可以任选开头位置，打印lcp达标对的数量\n// 1 <= n、k <= 3 * 10^6       1 <= m <= 10^5\n// 1 <= n * n * m <= 10^15    字符集为 f z o u t s y\n// 测试链接 : https://www.luogu.com.cn/problem/P5112\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code03_LCP1 {\n\n\tpublic static int MAXN = 3000001;\n\tpublic static int MAXM = 100001;\n\tpublic static int n, m, k;\n\tpublic static int len, cntq, cntv;\n\tpublic static char[] str = new char[MAXN];\n\tpublic static int[][] query = new int[MAXM][3];\n\n\t// 字符串哈希\n\tpublic static int base = 499;\n\tpublic static long[] basePower = new long[MAXN];\n\tpublic static long[] hashValue = new long[MAXN];\n\n\t// 哈希值离散化，用哈希值替代字符串，再用排名替代哈希值\n\tpublic static long[] val = new long[MAXN];\n\tpublic static long[] sorted = new long[MAXN];\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[] cnt = new int[MAXN];\n\tpublic static long curAns;\n\tpublic static long[] ans = new long[MAXM];\n\n\tpublic static int kth(long num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif ((bi[a[0]] & 1) == 1) {\n\t\t\t\treturn a[1] - b[1];\n\t\t\t} else {\n\t\t\t\treturn b[1] - a[1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int x) {\n\t\tcurAns += cnt[x];\n\t\tcnt[x]++;\n\t}\n\n\tpublic static void del(int x) {\n\t\tcnt[x]--;\n\t\tcurAns -= cnt[x];\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint id = query[i][2];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tans[id] = curAns;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tbasePower[0] = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbasePower[i] = basePower[i - 1] * base;\n\t\t\thashValue[i] = hashValue[i - 1] * base + (str[i] - 'a' + 1);\n\t\t}\n\t\tfor (int l = 1, r = k; r <= n; l++, r++) {\n\t\t\tval[l] = hashValue[r] - hashValue[l - 1] * basePower[r - l + 1];\n\t\t}\n\t\tfor (int i = 1; i <= len; i++) {\n\t\t\tsorted[i] = val[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, len + 1);\n\t\tcntv = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (sorted[cntv] != sorted[i]) {\n\t\t\t\tsorted[++cntv] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= len; i++) {\n\t\t\tarr[i] = kth(val[i]);\n\t\t}\n\t\t// 优化块长\n\t\tint blen = Math.max(1, (int) ((double) n / Math.sqrt(m)));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tstr[i] = in.nextLowerCase();\n\t\t}\n\t\t// 有效开头的个数，剩下的开头舍弃\n\t\tlen = n - k + 1;\n\t\tcntq = 0;\n\t\tfor (int i = 1, l, r; i <= m; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\t// 过滤查询并调整查询参数\n\t\t\tif (l <= len) {\n\t\t\t\tquery[++cntq][0] = l;\n\t\t\t\tquery[cntq][1] = Math.min(r, len);\n\t\t\t\tquery[cntq][2] = i;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextLowerCase() throws IOException {\n\t\t\tint c;\n\t\t\twhile (true) {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c >= 'a' && c <= 'z')\n\t\t\t\t\treturn (char) c;\n\t\t\t}\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code03_LCP1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
458efc3f-99e6-4abc-b1b5-92705c8647d9	3c599088-f16d-4b80-ba2c-7d755f4d8d12	java	package class104;\n\n// 最长回文子串\n// 找到字符串s中最长的回文子串并返回\n// 测试链接 : https://leetcode.cn/problems/longest-palindromic-substring/\npublic class Code01_LongestPalindromeSubstring {\n\n\tpublic static String longestPalindrome(String s) {\n\t\tmanacher(s);\n\t\treturn s.substring(end - max, end);\n\t}\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static char[] ss = new char[MAXN << 1];\n\n\tpublic static int[] p = new int[MAXN << 1];\n\n\tpublic static int n, max, end;\n\n\tpublic static void manacher(String str) {\n\t\tmanacherss(str.toCharArray());\n\t\tmax = end = 0;\n\t\tfor (int i = 0, c = 0, r = 0, len; i < n; i++) {\n\t\t\tlen = r > i ? Math.min(p[2 * c - i], r - i) : 1;\n\t\t\twhile (i + len < n && i - len >= 0 && ss[i + len] == ss[i - len]) {\n\t\t\t\tlen++;\n\t\t\t}\n\t\t\tif (i + len > r) {\n\t\t\t\tr = i + len;\n\t\t\t\tc = i;\n\t\t\t}\n\t\t\tif (len > max) {\n\t\t\t\tmax = len - 1;\n\t\t\t\tend = (i + len - 1) / 2;\n\t\t\t}\n\t\t\tp[i] = len;\n\t\t}\n\t}\n\n\tpublic static void manacherss(char[] a) {\n\t\tn = a.length * 2 + 1;\n\t\tfor (int i = 0, j = 0; i < n; i++) {\n\t\t\tss[i] = (i & 1) == 0 ? '#' : a[j++];\n\t\t}\n\t}\n\n}\n	模板：Code01_LongestPalindromeSubstring.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
