96dda93c-b891-430a-a2dd-94f784c9ae2f	dc8e0873-ae17-4933-9204-6358babc43e7	java	package class179;\n\n// 区间最大匹配，java版\n// 给定长度为n的数组a、长度为m的数组b、一个正数z\n// 数组a中数字x、数组b中数字y，如果x + y <= z，那么构成一个匹配\n// 已经匹配的数字，不可以重复使用，一共有q条查询，格式如下\n// 查询 l r : 数组b[l..r]范围上的数字，随意选择数组a中的数字，打印最多匹配数\n// 1 <= n <= 152501\n// 1 <= m、q <= 52501\n// 1 <= a[i]、b[i]、z <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4477\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code04_MaximumMatch1 {\n\n\tpublic static int MAXN = 152502;\n\tpublic static int MAXM = 52502;\n\tpublic static int MAXQ = 52502;\n\tpublic static int n, m, z, q;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXM];\n\tpublic static int[][] query = new int[MAXQ][3];\n\tpublic static int[] bi = new int[MAXM];\n\n\t// 线段树维护匹配信息，a[l..r]和b数组的数字进行匹配，l..r对应的信息在i位置\n\t// match[i] = v，a[l..r]和b数组的数字，一共匹配了v对\n\t// resta[i] = v，a[l..r]中还有v个数，可用于匹配b数组的数字\n\t// overb[i] = v，a[l..r]已经耗尽，但是还有v个b数组的数字没有满足\n\tpublic static int[] match = new int[MAXN << 2];\n\tpublic static int[] resta = new int[MAXN << 2];\n\tpublic static int[] overb = new int[MAXN << 2];\n\n\tpublic static int[] ans = new int[MAXQ];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif ((bi[a[0]] & 1) == 1) {\n\t\t\t\treturn a[1] - b[1];\n\t\t\t} else {\n\t\t\t\treturn b[1] - a[1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tint newMatch = Math.min(resta[l], overb[r]);\n\t\tresta[i] = resta[l] + resta[r] - newMatch;\n\t\toverb[i] = overb[l] + overb[r] - newMatch;\n\t\tmatch[i] = match[l] + match[r] + newMatch;\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tmatch[i] = 0;\n\t\t\tresta[i] = 1;\n\t\t\toverb[i] = 0;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void add(int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (resta[i] == 1) {\n\t\t\t\tmatch[i] = 1;\n\t\t\t\tresta[i] = 0;\n\t\t\t} else {\n\t\t\t\toverb[i]++;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobv + a[mid + 1] <= z) {\n\t\t\t\tadd(jobv, mid + 1, r, i << 1 | 1);\n\t\t\t} else if (jobv + a[l] <= z) {\n\t\t\t\tadd(jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void del(int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (overb[i] > 0) {\n\t\t\t\toverb[i]--;\n\t\t\t} else {\n\t\t\t\tmatch[i] = 0;\n\t\t\t\tresta[i] = 1;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobv + a[mid + 1] <= z) {\n\t\t\t\tdel(jobv, mid + 1, r, i << 1 | 1);\n\t\t\t} else if (jobv + a[l] <= z) {\n\t\t\t\tdel(jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tArrays.sort(a, 1, n + 1);\n\t\tint blen = (int) Math.sqrt(m);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, q + 1, new QueryCmp());\n\t\tbuild(1, n, 1);\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint id = query[i][2];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(b[--winl], 1, n, 1);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(b[++winr], 1, n, 1);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(b[winl++], 1, n, 1);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(b[winr--], 1, n, 1);\n\t\t\t}\n\t\t\tans[id] = match[1];\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tz = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_MaximumMatch1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
