 + len > r) {\n\t\t\t\tr = i + len;\n\t\t\t\tc = i;\n\t\t\t}\n\t\t\tp[i] = len;\n\t\t}\n\t}\n\n\tpublic static void manacherss(char[] a) {\n\t\tn = a.length * 2 + 1;\n\t\tfor (int i = 0, j = 0; i < n; i++) {\n\t\t\tss[i] = (i & 1) == 0 ? '#' : a[j++];\n\t\t}\n\t}\n\n\tpublic static long power(long x, long n) {\n\t\tlong ans = 1;\n\t\twhile (n > 0) {\n\t\t\tif ((n & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tn >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_TopKOddLengthProduct.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
