public static void manacherss(char[] a) {\n\t\tn = a.length * 2 + 1;\n\t\tfor (int i = 0, j = 0; i < n; i++) {\n\t\t\tss[i] = (i & 1) == 0 ? '#' : a[j++];\n\t\t}\n\t}\n\n}\n	模板：Code05_LongestDoublePalindrome.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f8780e1a-725d-4f12-81c3-00e21e3716a9	1d110387-a78d-4596-8552-a088f5f96189	java	package class044;\n\nimport java.util.HashMap;\n\n// 用类描述实现前缀树。不推荐！\n// 测试链接 : https://leetcode.cn/problems/implement-trie-ii-prefix-tree/\npublic class Code01_TrieTree {\n\n\t// 路是数组实现的\n\t// 提交时把类名、构造方法改为Trie\n\tclass Trie1 {\n\n\t\tclass TrieNode {\n\t\t\tpublic int pass;\n\t\t\tpublic int end;\n\t\t\tpublic TrieNode[] nexts;\n\n\t\t\tpublic TrieNode() {\n\t\t\t\tpass = 0;\n\t\t\t\tend = 0;\n\t\t\t\tnexts = new TrieNode[26];\n\t\t\t}\n\t\t}\n\n\t\tprivate TrieNode root;\n\n\t\tpublic Trie1() {\n\t\t\troot = new TrieNode();\n\t\t}\n\n\t\tpublic void insert(String word) {\n\t\t\tTrieNode node = root;\n\t\t\tnode.pass++;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) { // 从左往右遍历字符\n\t\t\t\tpath = word.charAt(i) - 'a'; // 由字符，对应成走向哪条路\n\t\t\t\tif (node.nexts[path] == null) {\n\t\t\t\t\tnode.nexts[path] = new TrieNode();\n\t\t\t\t}\n\t\t\t\tnode = node.nexts[path];\n\t\t\t\tnode.pass++;\n\t\t\t}\n\t\t\tnode.end++;\n\t\t}\n\n\t\t// 如果之前word插入过前缀树，那么此时删掉一次\n\t\t// 如果之前word没有插入过前缀树，那么什么也不做\n\t\tpublic void erase(String word) {\n\t\t\tif (countWordsEqualTo(word) > 0) {\n\t\t\t\tTrieNode node = root;\n\t\t\t\tnode.pass--;\n\t\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\t\tpath = word.charAt(i) - 'a';\n\t\t\t\t\tif (--node.nexts[path].pass == 0) {\n\t\t\t\t\t\tnode.nexts[path] = null;\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t\tnode = node.nexts[path];\n\t\t\t\t}\n\t\t\t\tnode.end--;\n\t\t\t}\n\t\t}\n\n\t\t// 查询前缀树里，word单词出现了几次\n\t\tpublic int countWordsEqualTo(String word) {\n\t\t\tTrieNode node = root;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\tpath = word.charAt(i) - 'a';\n\t\t\t\tif (node.nexts[path] == null) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t\tnode = node.nexts[path];\n\t\t\t}\n\t\t\treturn node.end;\n\t\t}\n\n\t\t// 查询前缀树里，有多少单词以pre做前缀\n\t\tpublic int countWordsStartingWith(String pre) {\n\t\t\tTrieNode node = root;\n\t\t\tfor (int i = 0, path; i < pre.length(); i++) {\n\t\t\t\tpath = pre.charAt(i) - 'a';\n\t\t\t\tif (node.nexts[path] == null) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t\tnode = node.nexts[path];\n\t\t\t}\n\t\t\treturn node.pass;\n\t\t}\n\n\t}\n\n\t// 路是哈希表实现的\n\t// 提交时把类名、构造方法改为Trie\n\tclass Trie2 {\n\n\t\tclass TrieNode {\n\t\t\tpublic int pass;\n\t\t\tpublic int end;\n\t\t\tHashMap<Integer, TrieNode> nexts;\n\n\t\t\tpublic TrieNode() {\n\t\t\t\tpass = 0;\n\t\t\t\tend = 0;\n\t\t\t\tnexts = new HashMap<>();\n\t\t\t}\n\t\t}\n\n\t\tprivate TrieNode root;\n\n\t\tpublic Trie2() {\n\t\t\troot = new TrieNode();\n\t\t}\n\n\t\tpublic void insert(String word) {\n\t\t\tTrieNode node = root;\n\t\t\tnode.pass++;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) { // 从左往右遍历字符\n\t\t\t\tpath = word.charAt(i);\n\t\t\t\tif (!node.nexts.containsKey(path)) {\n\t\t\t\t\tnode.nexts.put(path, new TrieNode());\n\t\t\t\t}\n\t\t\t\tnode = node.nexts.get(path);\n\t\t\t\tnode.pass++;\n\t\t\t}\n\t\t\tnode.end++;\n\t\t}\n\n\t\tpublic void erase(String word) {\n\t\t\tif (countWordsEqualTo(word) > 0) {\n\t\t\t\tTrieNode node = root;\n\t\t\t\tTrieNode next;\n\t\t\t\tnode.pass--;\n\t\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\t\tpath = word.charAt(i);\n\t\t\t\t\tnext = node.nexts.get(path);\n\t\t\t\t\tif (--next.pass == 0) {\n\t\t\t\t\t\tnode.nexts.remove(path);\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t\tnode = next;\n\t\t\t\t}\n\t\t\t\tnode.end--;\n\t\t\t}\n\t\t}\n\n\t\tpublic int countWordsEqualTo(String word) {\n\t\t\tTrieNode node = root;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\tpath = word.charAt(i);\n\t\t\t\tif (!node.nexts.containsKey(path)) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t\tnode = node.nexts.get(path);\n\t\t\t}\n\t\t\treturn node.end;\n\t\t}\n\n\t\tpublic int countWordsStartingWith(String pre) {\n\t\t\tTrieNode node = root;\n\t\t\tfor (int i = 0, path; i < pre.length(); i++) {\n\t\t\t\tpath = pre.charAt(i);\n\t\t\t\tif (!node.nexts.containsKey(path)) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t\tnode = node.nexts.get(path);\n\t\t\t}\n\t\t\treturn node.pass;\n\t\t}\n\n\t}\n\n}	模板：Code01_TrieTree.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
31c8cb4d-357a-4c11-83ff-c2998deb4c1d	1d110387-a78d-4596-8552-a088f5f96189	java	package class044;\n\n// 用固定数组实现前缀树，空间使用是静态的。推荐！\n// 测试链接 : https://www.nowcoder.com/practice/7f8a8553ddbf4eaab749ec988726702b\n// 请同学们务必参考如下代码中关于输入、输出的处理\n// 这是输入输出处理效率很高的写法\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_TrieTree {\n\n\t// 如果将来增加了数据量，就改大这个值\n\tpublic static int MAXN = 150001;\n\n\tpublic static int[][] tree = new int[MAXN][26];\n\n\tpublic static int[] end = new int[MAXN];\n\n\tpublic static int[] pass = new int[MAXN];\n\n\tpublic static int cnt;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t}\n\n\tpublic static void insert(String word) {\n\t\tint cur = 1;\n\t\tpass[cur]++;\n\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\tpath = word.charAt(i) - 'a';\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\ttree[cur][path] = ++cnt;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t\tpass[cur]++;\n\t\t}\n\t\tend[cur]++;\n\t}\n\n\tpublic static int search(String word) {\n\t\tint cur = 1;\n\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\tpath = word.charAt(i) - 'a';\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t}\n\t\treturn end[cur];\n\t}\n\n\tpublic static int prefixNumber(String pre) {\n\t\tint cur = 1;\n\t\tfor (int i = 0, path; i < pre.length(); i++) {\n\t\t\tpath = pre.charAt(i) - 'a';\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t}\n\t\treturn pass[cur];\n\t}\n\n\tpublic static void delete(String word) {\n\t\tif (search(word) > 0) {\n\t\t\tint cur = 1;\n\t\t\t// 下面这一行代码，讲课的时候没加\n\t\t\t// 本题不会用到pass[1]的信息，所以加不加都可以，不过正确的写法是加上\n\t\t\tpass[cur]--;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\tpath = word.charAt(i) - 'a';\n\t\t\t\tif (--pass[tree[cur][path]] == 0) {\n\t\t\t\t\ttree[cur][path] = 0;\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tcur = tree[cur][path];\n\t\t\t}\n\t\t\tend[cur]--;\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tArrays.fill(tree[i], 0);\n\t\t\tend[i] = 0;\n\t\t\tpass[i] = 0;\n\t\t}\n\t}\n\n\tpublic static int m, op;\n\n\tpublic static String[] splits;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tString line = null;\n\t\twhile ((line = in.readLine()) != null) {\n\t\t\tbuild();\n\t\t\tm = Integer.valueOf(line);\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tsplits = in.readLine().split(" ");\n\t\t\t\top = Integer.valueOf(splits[0]);\n\t\t\t\tif (op == 1) {\n\t\t\t\t\tinsert(splits[1]);\n\t\t\t\t} else if (op == 2) {\n\t\t\t\t\tdelete(splits[1]);\n\t\t\t\t} else if (op == 3) {\n\t\t\t\t\tout.println(search(splits[1]) > 0 ? "YES" : "NO");\n\t\t\t\t} else if (op == 4) {\n\t\t\t\t\tout.println(prefixNumber(splits[1]));\n\t\t\t\t}\n\t\t\t}\n\t\t\tclear();\n\t\t}\n\t\tout.flush();\n\t\tin.close();\n\t\tout.close();\n\t}\n\n}	模板：Code02_TrieTree.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
999e1d0c-bb59-4118-99c5-ac8453f65ff8	1d110387-a78d-4596-8552-a088f5f96189	java	package class045;\n\nimport java.util.Arrays;\n\n// 牛牛和他的朋友们约定了一套接头密匙系统，用于确认彼此身份\n// 密匙由一组数字序列表示，两个密匙被认为是一致的，如果满足以下条件：\n// 密匙 b 的长度不超过密匙 a 的长度。\n// 对于任意 0 <= i < length(b)，有b[i+1] - b[i] == a[i+1] - a[i]\n// 现在给定了m个密匙 b 的数组，以及n个密匙 a 的数组\n// 请你返回一个长度为 m 的结果数组 ans，表示每个密匙b都有多少一致的密匙\n// 数组 a 和数组 b 中的元素个数均不超过 10^5\n// 1 <= m, n <= 1000\n// 测试链接 : https://www.nowcoder.com/practice/c552d3b4dfda49ccb883a6371d9a6932\npublic class Code01_CountConsistentKeys {\n\n\tpublic static int[] countConsistentKeys(int[][] b, int[][] a) {\n\t\tbuild();\n\t\tStringBuilder builder = new StringBuilder();\n\t\t// [3,6,50,10] -> "3#44#-40#"\n\t\tfor (int[] nums : a) {\n\t\t\tbuilder.setLength(0);\n\t\t\tfor (int i = 1; i < nums.length; i++) {\n\t\t\t\tbuilder.append(String.valueOf(nums[i] - nums[i - 1]) + "#");\n\t\t\t}\n\t\t\tinsert(builder.toString());\n\t\t}\n\t\tint[] ans = new int[b.length];\n\t\tfor (int i = 0; i < b.length; i++) {\n\t\t\tbuilder.setLength(0);\n\t\t\tint[] nums = b[i];\n\t\t\tfor (int j = 1; j < nums.length; j++) {\n\t\t\t\tbuilder.append(String.valueOf(nums[j] - nums[j - 1]) + "#");\n\t\t\t}\n\t\t\tans[i] = count(builder.toString());\n\t\t}\n\t\tclear();\n\t\treturn ans;\n\t}\n\n\t// 如果将来增加了数据量，就改大这个值\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int[][] tree = new int[MAXN][12];\n\n\tpublic static int[] pass = new int[MAXN];\n\n\tpublic static int cnt;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t}\n\n\t// '0' ~ '9' 10个 0~9\n\t// '#' 10\n\t// '-' 11\n\tpublic static int path(char cha) {\n\t\tif (cha == '#') {\n\t\t\treturn 10;\n\t\t} else if (cha == '-') {\n\t\t\treturn 11;\n\t\t} else {\n\t\t\treturn cha - '0';\n\t\t}\n\t}\n\n\tpublic static void insert(String word) {\n\t\tint cur = 1;\n\t\tpass[cur]++;\n\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\tpath = path(word.charAt(i));\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\ttree[cur][path] = ++cnt;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t\tpass[cur]++;\n\t\t}\n\t}\n\n\tpublic static int count(String pre) {\n\t\tint cur = 1;\n\t\tfor (int i = 0, path; i < pre.length(); i++) {\n\t\t\tpath = path(pre.charAt(i));\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t}\n\t\treturn pass[cur];\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tArrays.fill(tree[i], 0);\n\t\t\tpass[i] = 0;\n\t\t}\n\t}\n\n}\n	模板：Code01_CountConsistentKeys.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b21a8736-6c83-4668-a49b-d68cd74eefab	1d110387-a78d-4596-8552-a088f5f96189	java	package class045;\n\nimport java.util.HashSet;\n\n// 数组中两个数的最大异或值\n// 给你一个整数数组 nums ，返回 nums[i] XOR nums[j] 的最大运算结果，其中 0<=i<=j<=n\n// 1 <= nums.length <= 2 * 10^5\n// 0 <= nums[i] <= 2^31 - 1\n// 测试链接 : https://leetcode.cn/problems/maximum-xor-of-two-numbers-in-an-array/\npublic class Code02_TwoNumbersMaximumXor {\n\n\t// 前缀树的做法\n\t// 好想\n\tpublic static int findMaximumXOR1(int[] nums) {\n\t\tbuild(nums);\n\t\tint ans = 0;\n\t\tfor (int num : nums) {\n\t\t\tans = Math.max(ans, maxXor(num));\n\t\t}\n\t\tclear();\n\t\treturn ans;\n\t}\n\n\t// 准备这么多静态空间就够了，实验出来的\n\t// 如果测试数据升级了规模，就改大这个值\n\tpublic static int MAXN = 3000001;\n\n\tpublic static int[][] tree = new int[MAXN][2];\n\n\t// 前缀树目前使用了多少空间\n\tpublic static int cnt;\n\n\t// 数字只需要从哪一位开始考虑\n\tpublic static int high;\n\n\tpublic static void build(int[] nums) {\n\t\tcnt = 1;\n\t\t// 找个最大值\n\t\tint max = Integer.MIN_VALUE;\n\t\tfor (int num : nums) {\n\t\t\tmax = Math.max(num, max);\n\t\t}\n\t\t// 计算数组最大值的二进制状态，有多少个前缀的0\n\t\t// 可以忽略这些前置的0，从left位开始考虑\n\t\thigh = 31 - Integer.numberOfLeadingZeros(max);\n\t\tfor (int num : nums) {\n\t\t\tinsert(num);\n\t\t}\n\t}\n\n\tpublic static void insert(int num) {\n\t\tint cur = 1;\n\t\tfor (int i = high, path; i >= 0; i--) {\n\t\t\tpath = (num >> i) & 1;\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\ttree[cur][path] = ++cnt;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t}\n\t}\n\n\tpublic static int maxXor(int num) {\n\t\t// 最终异或的结果(尽量大)\n\t\tint ans = 0;\n\t\t// 前缀树目前来到的节点编号\n\t\tint cur = 1;\n\t\tfor (int i = high, status, want; i >= 0; i--) {\n\t\t\t// status : num第i位的状态\n\t\t\tstatus = (num >> i) & 1;\n\t\t\t// want : num第i位希望遇到的状态\n\t\t\twant = status ^ 1;\n\t\t\tif (tree[cur][want] == 0) { // 询问前缀树，能不能达成\n\t\t\t\t// 不能达成\n\t\t\t\twant ^= 1;\n\t\t\t}\n\t\t\t// want变成真的往下走的路\n\t\t\tans |= (status ^ want) << i;\n\t\t\tcur = tree[cur][want];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\ttree[i][0] = tree[i][1] = 0;\n\t\t}\n\t}\n\n\t// 用哈希表的做法\n\t// 难想\n\tpublic int findMaximumXOR2(int[] nums) {\n\t\tint max = Integer.MIN_VALUE;\n\t\tfor (int num : nums) {\n\t\t\tmax = Math.max(num, max);\n\t\t}\n\t\tint ans = 0;\n\t\tHashSet<Integer> set = new HashSet<>();\n\t\tfor (int i = 31 - Integer.numberOfLeadingZeros(max); i >= 0; i--) {\n\t\t\t// ans : 31....i+1 已经达成的目标\n\t\t\tint better = ans | (1 << i);\n\t\t\tset.clear();\n\t\t\tfor (int num : nums) {\n\t\t\t\t// num : 31.....i 这些状态保留，剩下全成0\n\t\t\t\tnum = (num >> i) << i;\n\t\t\t\tset.add(num);\n\t\t\t\t// num ^ 某状态 是否能 达成better目标，就在set中找 某状态 : better ^ num\n\t\t\t\tif (set.contains(better ^ num)) {\n\t\t\t\t\tans = better;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}	模板：Code02_TwoNumbersMaximumXor.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b848cabb-a156-4d01-bb2c-2a1825103cc0	1d110387-a78d-4596-8552-a088f5f96189	java	package class045;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n// 在二维字符数组中搜索可能的单词\n// 给定一个 m x n 二维字符网格 board 和一个单词（字符串）列表 words\n// 返回所有二维网格上的单词。单词必须按照字母顺序，通过 相邻的单元格 内的字母构成\n// 其中“相邻”单元格是那些水平相邻或垂直相邻的单元格\n// 同一个单元格内的字母在一个单词中不允许被重复使用\n// 1 <= m, n <= 12\n// 1 <= words.length <= 3 * 10^4\n// 1 <= words[i].length <= 10\n// 测试链接 : https://leetcode.cn/problems/word-search-ii/\npublic class Code03_WordSearchII {\n\n\tpublic static List<String> findWords(char[][] board, String[] words) {\n\t\tbuild(words);\n\t\tList<String> ans = new ArrayList<>();\n\t\tfor (int i = 0; i < board.length; i++) {\n\t\t\tfor (int j = 0; j < board[0].length; j++) {\n\t\t\t\tdfs(board, i, j, 1, ans);\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\treturn ans;\n\t}\n\n\t// board : 二维网格\n\t// i,j : 此时来到的格子位置，i行、j列\n\t// t : 前缀树的编号\n\t// List<String> ans : 收集到了哪些字符串，都放入ans\n\t// 返回值 : 收集到了几个字符串\n\tpublic static int dfs(char[][] board, int i, int j, int t, List<String> ans) {\n\t\t// 越界 或者 走了回头路，直接返回0\n\t\tif (i < 0 || i == board.length || j < 0 || j == board[0].length || board[i][j] == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\t// 不越界 且 不是回头路\n\t\t// 用tmp记录当前字符\n\t\tchar tmp = board[i][j];\n\t\t// 路的编号\n\t\t// a -> 0\n\t\t// b -> 1\n\t\t// ...\n\t\t// z -> 25\n\t\tint road = tmp - 'a';\n\t\tt = tree[t][road];\n\t\tif (pass[t] == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\t// i，j位置有必要来\n\t\t// fix ：从当前i，j位置出发，一共收集到了几个字符串\n\t\tint fix = 0;\n\t\tif (end[t] != null) {\n\t\t\tfix++;\n\t\t\tans.add(end[t]);\n\t\t\tend[t] = null;\n\t\t}\n\t\t// 把i，j位置的字符，改成0，后续的过程，是不可以再来到i，j位置的！\n\t\tboard[i][j] = 0;\n\t\tfix += dfs(board, i - 1, j, t, ans);\n\t\tfix += dfs(board, i + 1, j, t, ans);\n\t\tfix += dfs(board, i, j - 1, t, ans);\n\t\tfix += dfs(board, i, j + 1, t, ans);\n\t\tpass[t] -= fix;\n\t\tboard[i][j] = tmp;\n\t\treturn fix;\n\t}\n\n\tpublic static int MAXN = 10001;\n\n\tpublic static int[][] tree = new int[MAXN][26];\n\n\tpublic static int[] pass = new int[MAXN];\n\n\tpublic static String[] end = new String[MAXN];\n\n\tpublic static int cnt;\n\n\tpublic static void build(String[] words) {\n\t\tcnt = 1;\n\t\tfor (String word : words) {\n\t\t\tint cur = 1;\n\t\t\tpass[cur]++;\n\t\t\tfor (int i = 0, path; i < word.length(); i++) {\n\t\t\t\tpath = word.charAt(i) - 'a';\n\t\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\t\ttree[cur][path] = ++cnt;\n\t\t\t\t}\n\t\t\t\tcur = tree[cur][path];\n\t\t\t\tpass[cur]++;\n\t\t\t}\n\t\t\tend[cur] = word;\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tArrays.fill(tree[i], 0);\n\t\t\tpass[i] = 0;\n\t\t\tend[i] = null;\n\t\t}\n\t}\n\n}	模板：Code03_WordSearchII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5a9e740c-5bba-409d-b69f-131c0927a528	1d110387-a78d-4596-8552-a088f5f96189	java	package class159;\n\n// 最大异或和，java版\n// 非负序列arr的初始长度为n，一共有m条操作，每条操作是如下两种类型中的一种\n// A x     : arr的末尾增加数字x，arr的长度n也增加1\n// Q l r x : l~r这些位置中，选一个位置p，现在希望\n//           arr[p] ^ arr[p+1] ^ .. ^ arr[n] ^ x 这个值最大\n//           打印这个最大值\n// 1 <= n、m <= 3 * 10^5\n// 0 <= arr[i]、x <= 10^7\n// 因为练的就是可持久化前缀树，所以就用在线算法，不要使用离线算法\n// 测试链接 : https://www.luogu.com.cn/problem/P4735\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是有一些测试用例通过不了\n// 因为这道题根据C++的运行时间，制定通过标准，根本没考虑java的用户\n// 想通过用C++实现，本节课Code01_MaxXor2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.InputStream;\n\npublic class Code01_MaxXor1 {\n\n\tpublic static int MAXN = 600001;\n\n\tpublic static int MAXT = MAXN * 22;\n\n\tpublic static int BIT = 25;\n\n\tpublic static int n, m, eor;\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[][] tree = new int[MAXT][2];\n\n\tpublic static int[] pass = new int[MAXT];\n\n\tpublic static int cnt = 0;\n\n\tpublic static int insert(int num, int i) {\n\t\tint rt = ++cnt;\n\t\ttree[rt][0] = tree[i][0];\n\t\ttree[rt][1] = tree[i][1];\n\t\tpass[rt] = pass[i] + 1;\n\t\tfor (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\ti = tree[i][path];\n\t\t\tcur = ++cnt;\n\t\t\ttree[cur][0] = tree[i][0];\n\t\t\ttree[cur][1] = tree[i][1];\n\t\t\tpass[cur] = pass[i] + 1;\n\t\t\ttree[pre][path] = cur;\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(int num, int u, int v) {\n\t\tint ans = 0;\n\t\tfor (int b = BIT, path, best; b >= 0; b--) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\tbest = path ^ 1;\n\t\t\tif (pass[tree[v][best]] > pass[tree[u][best]]) {\n\t\t\t\tans += 1 << b;\n\t\t\t\tu = tree[u][best];\n\t\t\t\tv = tree[v][best];\n\t\t\t} else {\n\t\t\t\tu = tree[u][path];\n\t\t\t\tv = tree[v][path];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\teor = 0;\n\t\t// 其实有空版本，空版本的头节点编号是0\n\t\troot[0] = insert(eor, 0);\n\t\tfor (int i = 1, num; i <= n; i++) {\n\t\t\tnum = in.nextInt();\n\t\t\teor ^= num;\n\t\t\troot[i] = insert(eor, root[i - 1]);\n\t\t}\n\t\tString op;\n\t\tint x, y, z;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.next();\n\t\t\tif (op.equals("A")) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\teor ^= x;\n\t\t\t\tn++;\n\t\t\t\troot[n] = insert(eor, root[n - 1]);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt(); // l\n\t\t\t\ty = in.nextInt(); // r\n\t\t\t\tz = in.nextInt(); // x\n\t\t\t\tif (x == 1) {\n\t\t\t\t\tout.println(query(eor ^ z, 0, root[y - 1]));\n\t\t\t\t} else {\n\t\t\t\t\tout.println(query(eor ^ z, root[x - 2], root[y - 1]));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic boolean hasNext() throws IOException {\n\t\t\twhile (hasNextByte()) {\n\t\t\t\tbyte b = buffer[ptr];\n\t\t\t\tif (!isWhitespace(b))\n\t\t\t\t\treturn true;\n\t\t\t\tptr++;\n\t\t\t}\n\t\t\treturn false;\n\t\t}\n\n\t\tpublic String next() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn null;\n\t\t\t} while (c <= ' ');\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > ' ') {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic double nextDouble() throws IOException {\n\t\t\tdouble num = 0, div = 1;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != '.' && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tif (b == '.') {\n\t\t\t\tb = readByte();\n\t\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\t\tnum += (b - '0') / (div *= 10);\n\t\t\t\t\tb = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}	模板：Code01_MaxXor1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
