9b6b29b2-ede0-4e5a-8463-c27336931339	1d110387-a78d-4596-8552-a088f5f96189	java	package class159;\n\n// 字符串树，java版\n// 一共有n个节点，n-1条边，组成一棵树，每条边的边权为字符串\n// 一共有m条查询，每条查询的格式为\n// u v s : 查询节点u到节点v的路径中，有多少边的字符串以字符串s作为前缀\n// 1 <= n、m <= 10^5\n// 所有字符串长度不超过10，并且都由字符a~z组成\n// 测试链接 : https://www.luogu.com.cn/problem/P6088\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code02_StringTree1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXT = 1000001;\n\n\tpublic static int MAXP = 20;\n\n\tpublic static int n, m;\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static String[] weight = new String[MAXN << 1];\n\n\tpublic static int cntg = 0;\n\n\t// 可持久化前缀树需要\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[][] tree = new int[MAXT][27];\n\n\tpublic static int[] pass = new int[MAXT];\n\n\tpublic static int cntt = 0;\n\n\t// 树上倍增和LCA需要\n\tpublic static int[] deep = new int[MAXN];\n\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static void addEdge(int u, int v, String w) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int num(char cha) {\n\t\treturn cha - 'a' + 1;\n\t}\n\n\tpublic static int clone(int i) {\n\t\tint rt = ++cntt;\n\t\tfor (int cha = 1; cha <= 26; cha++) {\n\t\t\ttree[rt][cha] = tree[i][cha];\n\t\t}\n\t\tpass[rt] = pass[i];\n\t\treturn rt;\n\t}\n\n\tpublic static int insert(String str, int i) {\n\t\tint rt = clone(i);\n\t\tpass[rt]++;\n\t\tfor (int j = 0, path, pre = rt, cur; j < str.length(); j++, pre = cur) {\n\t\t\tpath = num(str.charAt(j));\n\t\t\ti = tree[i][path];\n\t\t\tcur = clone(i);\n\t\t\tpass[cur]++;\n\t\t\ttree[pre][path] = cur;\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(String str, int i) {\n\t\tfor (int j = 0, path; j < str.length(); j++) {\n\t\t\tpath = num(str.charAt(j));\n\t\t\ti = tree[i][path];\n\t\t\tif (i == 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t}\n\t\treturn pass[i];\n\t}\n\n\t// 递归版，C++可以通过，java无法通过，递归会爆栈\n\tpublic static void dfs1(int u, int fa, String path) {\n\t\troot[u] = insert(path, root[fa]);\n\t\tdeep[u] = deep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u, weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版，都可以通过\n\t// 讲解118，详解了从递归版改迭代版\n\tpublic static int[] us = new int[MAXN];\n\tpublic static int[] fs = new int[MAXN];\n\tpublic static int[] es = new int[MAXN];\n\tpublic static String[] ps = new String[MAXN];\n\tpublic static int stackSize;\n\tpublic static int u;\n\tpublic static int f;\n\tpublic static int e;\n\tpublic static String p;\n\n\tpublic static void push(int u, int f, int e, String p) {\n\t\tus[stackSize] = u;\n\t\tfs[stackSize] = f;\n\t\tes[stackSize] = e;\n\t\tps[stackSize] = p;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = us[stackSize];\n\t\tf = fs[stackSize];\n\t\te = es[stackSize];\n\t\tp = ps[stackSize];\n\t}\n\n\t// dfs1方法改成迭代版\n\tpublic static void dfs2() {\n\t\tstackSize = 0;\n\t\tpush(1, 0, -1, "");\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\troot[u] = insert(p, root[f]);\n\t\t\t\tdeep[u] = deep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e, p);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1, weight[e]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (deep[a] < deep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (deep[stjump[a][p]] >= deep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int compute(int u, int v, String s) {\n\t\treturn query(s, root[u]) + query(s, root[v]) - 2 * query(s, root[lca(u, v)]);\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tint u, v;\n\t\tString s;\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\ts = io.next();\n\t\t\taddEdge(u, v, s);\n\t\t\taddEdge(v, u, s);\n\t\t}\n\t\tdfs2(); // 使用迭代版防止爆栈\n\t\tm = io.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\ts = io.next();\n\t\t\tio.println(compute(u, v, s));\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code02_StringTree1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
