6cbf7616-ff8a-442c-b5c4-8d7270145768	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 最大异或和\n// 给定一个长度为n的数组arr，arr中都是long类型的非负数，可能有重复值\n// 在这些数中选取任意个，使得异或和最大，返回最大的异或和\n// 1 <= n <= 50\n// 0 <= arr[i] <= 2^50\n// 测试链接 : https://www.luogu.com.cn/problem/P3812\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_MaximumXor {\n\n\tpublic static int MAXN = 51;\n\n\tpublic static int BIT = 50;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static long[] basis = new long[BIT + 1];\n\n\tpublic static int n;\n\n\t// 普通消元\n\t// 计算最大异或和\n\tpublic static long compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tinsert(arr[i]);\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tans = Math.max(ans, ans ^ basis[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 线性基里插入num，如果线性基增加了返回true，否则返回false\n\tpublic static boolean insert(long num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (long) in.nval;\n\t\t}\n\t\tcompute();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_MaximumXor.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b9c88d7c-7f3a-416c-b519-1e20279d09d7	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 第k小的异或和\n// 给定一个长度为n的数组arr，arr中都是long类型的非负数，可能有重复值\n// 在这些数中选取任意个，至少要选一个数字\n// 可以得到很多异或和，假设异或和的结果去重\n// 返回第k小的异或和\n// 1 <= n <= 10^5\n// 0 <= arr[i] <= 2^50\n// 1 <= k <= 2^50\n// 测试链接 : https://loj.ac/p/114\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_KthXor {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int BIT = 50;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static int len;\n\n\tpublic static boolean zero;\n\n\tpublic static int n;\n\n\t// 高斯消元\n\tpublic static void compute() {\n\t\tlen = 1;\n\t\tfor (long i = BIT; i >= 0; i--) {\n\t\t\tfor (int j = len; j <= n; j++) {\n\t\t\t\tif ((arr[j] & (1L << i)) != 0) {\n\t\t\t\t\tswap(j, len);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif ((arr[len] & (1L << i)) != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (j != len && (arr[j] & (1L << i)) != 0) {\n\t\t\t\t\t\tarr[j] ^= arr[len];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tlen++;\n\t\t\t}\n\t\t}\n\t\tlen--;\n\t\tzero = len != n;\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tlong tmp = arr[a];\n\t\tarr[a] = arr[b];\n\t\tarr[b] = tmp;\n\t}\n\n\t// 返回第k小的异或和\n\tpublic static long query(long k) {\n\t\tif (zero && k == 1) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (zero) {\n\t\t\tk--;\n\t\t}\n\t\tif (k >= 1L << len) {\n\t\t\treturn -1;\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = len, j = 0; i >= 1; i--, j++) {\n\t\t\tif ((k & (1L << j)) != 0) {\n\t\t\t\tans ^= arr[i];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (long) in.nval;\n\t\t}\n\t\tcompute();\n\t\tin.nextToken();\n\t\tint q = (int) in.nval;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tin.nextToken();\n\t\t\tlong k = (long) in.nval;\n\t\t\tout.println(query(k));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_KthXor.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d1984e03-cc6d-4573-9c0c-61275af76acd	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 第k小的异或和，HDU的题目\n// 这道题课上没有讲，核心逻辑和题目2一样，只是数据范围稍有不同\n// 注意如下代码中，有注释的部分即可，其他代码都一样\n// 给定一个长度为n的数组arr，arr中都是long类型的非负数，可能有重复值\n// 在这些数中选取任意个，至少要选一个数字，可以得到很多异或和\n// 假设异或和的结果去重，返回第k小的异或和\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=3949\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_XOR {\n\n\tpublic static int MAXN = 100001;\n\n\t// 数字最大为10^18，需要更高的二进制位\n\tpublic static int BIT = 60;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static int len;\n\n\tpublic static boolean zero;\n\n\tpublic static int t, n;\n\n\tpublic static void compute() {\n\t\tlen = 1;\n\t\tfor (long i = BIT; i >= 0; i--) {\n\t\t\tfor (int j = len; j <= n; j++) {\n\t\t\t\tif ((arr[j] & (1L << i)) != 0) {\n\t\t\t\t\tswap(j, len);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif ((arr[len] & (1L << i)) != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (j != len && (arr[j] & (1L << i)) != 0) {\n\t\t\t\t\t\tarr[j] ^= arr[len];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tlen++;\n\t\t\t}\n\t\t}\n\t\tlen--;\n\t\tzero = len != n;\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tlong tmp = arr[a];\n\t\tarr[a] = arr[b];\n\t\tarr[b] = tmp;\n\t}\n\n\tpublic static long query(long k) {\n\t\tif (zero && k == 1) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (zero) {\n\t\t\tk--;\n\t\t}\n\t\tif (k >= 1L << len) {\n\t\t\treturn -1;\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = len, j = 0; i >= 1; i--, j++) {\n\t\t\tif ((k & (1L << j)) != 0) {\n\t\t\t\tans ^= arr[i];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\t// 注意有多组测试\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tarr[i] = in.nextLong();\n\t\t\t}\n\t\t\t// 确保arr[n + 1]是0\n\t\t\tarr[n + 1] = 0;\n\t\t\tcompute();\n\t\t\tout.println("Case #" + c + ":");\n\t\t\tint q = in.nextInt();\n\t\t\tfor (int i = 1; i <= q; i++) {\n\t\t\t\tlong k = in.nextLong();\n\t\t\t\tout.println(query(k));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code02_XOR.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b9052d26-3d50-4641-940e-9c6bcc0fbf44	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 元素\n// 给定n个魔法矿石，每个矿石有状态和魔力，都是整数\n// 若干矿石组成的组合能否有效，根据状态异或的结果来决定\n// 如果一个矿石组合内部会产生异或和为0的子集，那么这个组合无效\n// 返回有效的矿石组合中，最大的魔力和是多少\n// 1 <= n <= 1000\n// 1 <= 状态 <= 10^18\n// 1 <= 魔力 <= 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P4570\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class Code03_Elements {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int BIT = 60;\n\n\tpublic static long[][] arr = new long[MAXN][2];\n\n\tpublic static long[] basis = new long[BIT + 1];\n\n\tpublic static int n;\n\n\t// 普通消元\n\t// 计算得到最大线性基的最少花费\n\tpublic static long compute() {\n\t\tlong ans = 0;\n\t\tArrays.sort(arr, 1, n + 1, (a, b) -> a[1] >= b[1] ? -1 : 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (insert(arr[i][0])) {\n\t\t\t\tans += arr[i][1];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 线性基里插入num，如果线性基增加了返回true，否则返回false\n\tpublic static boolean insert(long num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\t// 题目会读取10^18范围内的long类型数字\n\t\t// 用StreamTokenizer可能无法正确读取，因为先变成double再转成long\n\t\t// 这里用Kattio类，具体看讲解019的代码中，Code05_Kattio文件\n\t\t// 有详细的说明\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = io.nextLong();\n\t\t\tarr[i][1] = io.nextInt();\n\t\t}\n\t\tio.println(compute());\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_Elements.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8877636a-0d37-434e-84a8-92ce4b85068d	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 彩灯\n// 一共有n个灯泡，开始都是不亮的状态，有m个开关\n// 每个开关能改变若干灯泡的状态，改变是指，亮变不亮、不亮变亮\n// 比如n=5，某个开关为XXOOO，表示这个开关只能改变后3个灯泡的状态\n// 可以随意使用开关，返回有多少种亮灯的组合，全不亮也算一种组合\n// 答案可能很大，对 2008 取模\n// 1 <= n <= 50\n// 1 <= m <= 50\n// 测试链接 : https://www.luogu.com.cn/problem/P3857\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code04_Lanterns {\n\n\tpublic static int MAXN = 51;\n\n\tpublic static int MOD = 2008;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static long[] basis = new long[MAXN];\n\n\tpublic static int n, m;\n\n\t// 普通消元\n\t// 计算线性基的大小\n\tpublic static int compute() {\n\t\tint size = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (insert(arr[i])) {\n\t\t\t\tsize++;\n\t\t\t}\n\t\t}\n\t\treturn size;\n\t}\n\n\t// 线性基里插入num，如果线性基增加了返回true，否则返回false\n\tpublic static boolean insert(long num) {\n\t\tfor (int i = n; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt() - 1;\n\t\tm = io.nextInt();\n\t\tchar[] s;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ts = io.next().toCharArray();\n\t\t\tlong num = 0;\n\t\t\tfor (int j = 0; j <= n; j++) {\n\t\t\t\tif (s[j] == 'O') {\n\t\t\t\t\tnum |= 1L << j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tarr[i] = num;\n\t\t}\n\t\tint size = compute();\n\t\tio.println((1L << size) % MOD);\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code04_Lanterns.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
42de77e7-d34a-429c-9dfb-fffb7400f6f6	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class136;\n\n// 课上讲述普通消元、高斯消元构建异或空间线性基的例子\n\nimport java.util.Arrays;\nimport java.util.HashSet;\n\npublic class ShowDetails {\n\n\tpublic static int MAXN = 101;\n\n\t// 最高位从哪开始\n\tpublic static int BIT = 60;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static int n;\n\n\t// 普通消元\n\tpublic static long[] basis1 = new long[BIT + 1];\n\n\tpublic static boolean zero1;\n\n\tpublic static void compute1() {\n\t\tzero1 = false;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (!insert(arr[i])) {\n\t\t\t\tzero1 = true;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 线性基里插入num，如果线性基增加了返回true，否则返回false\n\tpublic static boolean insert(long num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis1[i] == 0) {\n\t\t\t\t\tbasis1[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis1[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\t// 高斯消元\n\t// 因为不需要维护主元和自由元的依赖关系\n\t// 所以高斯消元的写法可以得到简化\n\tpublic static long[] basis2 = new long[MAXN];\n\n\tpublic static int len;\n\n\tpublic static boolean zero2;\n\n\tpublic static void compute2() {\n\t\tlen = 1;\n\t\tfor (long i = BIT; i >= 0; i--) {\n\t\t\tfor (int j = len; j <= n; j++) {\n\t\t\t\tif ((basis2[j] & (1L << i)) != 0) {\n\t\t\t\t\tswap(j, len);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif ((basis2[len] & (1L << i)) != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (j != len && (basis2[j] & (1L << i)) != 0) {\n\t\t\t\t\t\tbasis2[j] ^= basis2[len];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tlen++;\n\t\t\t}\n\t\t}\n\t\tlen--;\n\t\tzero2 = len != n;\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tlong tmp = basis2[a];\n\t\tbasis2[a] = basis2[b];\n\t\tbasis2[b] = tmp;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 课上讲的普通消元，例子1\n\t\t// 12, 9, 14, 11\n\t\tSystem.out.println("例子1");\n\t\tArrays.fill(basis1, 0);\n\t\tarr[1] = 12;\n\t\tarr[2] = 9;\n\t\tarr[3] = 14;\n\t\tarr[4] = 11;\n\t\tn = 4;\n\t\tSystem.out.println("原始数组得到的异或结果如下");\n\t\tprintXor(arr, n);\n\n\t\tSystem.out.println("===========================");\n\t\tSystem.out.println("普通消元得到的线性基 : ");\n\t\tcompute1();\n\t\tlong[] b1 = new long[MAXN];\n\t\tint s1 = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (basis1[i] != 0) {\n\t\t\t\tSystem.out.print(basis1[i] + " ");\n\t\t\t\tb1[++s1] = basis1[i];\n\t\t\t}\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("是否能异或出0 : " + zero1);\n\t\tSystem.out.println("普通消元得到的异或结果如下");\n\t\tprintXor(b1, s1);\n\t\tSystem.out.println("===========================");\n\n\t\tSystem.out.println();\n\t\tSystem.out.println();\n\n\t\t// 课上讲的普通消元，例子2\n\t\t// 2, 5, 11, 6\n\t\tSystem.out.println("例子2");\n\t\tArrays.fill(basis1, 0);\n\t\tarr[1] = 2;\n\t\tarr[2] = 5;\n\t\tarr[3] = 11;\n\t\tarr[4] = 6;\n\t\tn = 4;\n\t\tSystem.out.println("原始数组得到的异或结果如下");\n\t\tprintXor(arr, n);\n\t\tSystem.out.println("===========================");\n\t\tSystem.out.println("普通消元得到的线性基 : ");\n\t\tcompute1();\n\t\tlong[] b2 = new long[MAXN];\n\t\tint s2 = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (basis1[i] != 0) {\n\t\t\t\tSystem.out.print(basis1[i] + " ");\n\t\t\t\tb2[++s2] = basis1[i];\n\t\t\t}\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("是否能异或出0 : " + zero1);\n\t\tSystem.out.println("普通消元得到的异或结果如下");\n\t\tprintXor(b2, s2);\n\t\tSystem.out.println("===========================");\n\n\t\tSystem.out.println();\n\t\tSystem.out.println();\n\n\t\t// 课上讲的高斯消元的例子，例子3\n\t\t// 6, 37, 35, 33\n\t\tSystem.out.println("例子3");\n\t\tArrays.fill(basis2, 0);\n\t\tarr[1] = basis2[1] = 6;\n\t\tarr[2] = basis2[2] = 37;\n\t\tarr[3] = basis2[3] = 35;\n\t\tarr[4] = basis2[4] = 33;\n\t\tn = 4;\n\t\tSystem.out.println("原始数组得到的异或结果如下");\n\t\tprintXor(arr, n);\n\t\tSystem.out.println("===========================");\n\t\tSystem.out.println("高斯消元得到的线性基 : ");\n\t\tcompute2();\n\t\tfor (int i = 1; i <= len; i++) {\n\t\t\tSystem.out.print(basis2[i] + " ");\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("是否能异或出0 : " + zero2);\n\t\tSystem.out.println("高斯消元得到的异或结果如下");\n\t\tprintXor(basis2, len);\n\t\tSystem.out.println("===========================");\n\n\t\tSystem.out.println();\n\t\tSystem.out.println();\n\n\t\t// 课上讲的高斯消元的例子，例子4\n\t\t// 如果想得到第k小的非0异或和\n\t\t// 必须用高斯消元，不能用普通消元，比如\n\t\t// arr = { 7, 10, 4 }\n\t\t// 普通消元得到的异或空间线性基是 : 10 7 3\n\t\t// 第三小异或和是4，第四小异或和是10，这是错误的\n\t\t// 高斯消元可以得到正确结果\n\t\t// 高斯消元得到的异或空间线性基是 : 9 4 3\n\t\t// 第三小异或和是7，第四小异或和是9，这是正确的\n\t\tSystem.out.println("例子4");\n\t\tArrays.fill(basis1, 0);\n\t\tArrays.fill(basis2, 0);\n\t\tarr[1] = basis2[1] = 7;\n\t\tarr[2] = basis2[2] = 10;\n\t\tarr[3] = basis2[3] = 4;\n\t\tn = 3;\n\t\tSystem.out.println("原始数组得到的异或结果如下");\n\t\tprintXor(arr, n);\n\t\tSystem.out.println("===========================");\n\t\tSystem.out.println("普通消元");\n\t\tcompute1();\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (basis1[i] != 0) {\n\t\t\t\tSystem.out.print(basis1[i] + " ");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("是否能异或出0 : " + zero1);\n\n\t\tSystem.out.println("===========================");\n\n\t\tSystem.out.println("高斯消元");\n\t\tcompute2();\n\t\tfor (int i = 1; i <= len; i++) {\n\t\t\tSystem.out.print(basis2[i] + " ");\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("是否能异或出0 : " + zero2);\n\t}\n\n\t// nums中1~n的范围\n\t// 所有可能的异或和打印出来\n\t// 要求去重并且至少选择一个数字\n\tpublic static void printXor(long[] nums, int n) {\n\t\tHashSet<Long> set = new HashSet<>();\n\t\tdfs(nums, n, 1, false, 0, set);\n\t\tSystem.out.println("至少选择一个数字所有可能的异或和:");\n\t\tfor (Long s : set) {\n\t\t\tSystem.out.print(s + ", ");\n\t\t}\n\t\tSystem.out.println();\n\t}\n\n\t// 当前来到i位置\n\t// 之前是否选择过数字用pick表示\n\t// 之前做的决定形成的异或和是path\n\t// 当前i位置的数字要或者不要全决策\n\t// 收集所有可能的异或和\n\tpublic static void dfs(long[] nums, int n, int i, boolean pick, long path, HashSet<Long> set) {\n\t\tif (i > n) {\n\t\t\tif (pick) {\n\t\t\t\tset.add(path);\n\t\t\t}\n\t\t} else {\n\t\t\tdfs(nums, n, i + 1, pick, path, set);\n\t\t\tdfs(nums, n, i + 1, true, path ^ nums[i], set);\n\t\t}\n\t}\n\n}\n	模板：ShowDetails.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
aea18231-bc90-407d-9e1b-200e3d3b5051	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class137;\n\n// 装备购买\n// 一共有n个物品，每个物品都有m个属性值\n// 下面定义什么是不必要的物品：如果已经选择了k个物品，此时又有一件当前物品\n// 如果给已经选择的物品分配一组相乘的系数，并把属性值相加，就能得到当前物品\n// 那么就说当前物品是不必要的，比如下面的例子\n// a = { 4, 6, 2 }, b = { 2, 8, 4 }, c = { 6, 19, 9 }\n// a * 0.5 + b * 2 = c，那么c物品是不必要的\n// 每个物品都有价格，现在希望尽量多的购买物品，但不能出现不必要的物品\n// 返回最多能买几件物品和最少的花费\n// 1 <= n、m <= 500\n// 0 <= 属性值 <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3265\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_BuyEquipment {\n\n\tpublic static int MAXN = 502;\n\n\tpublic static int MAXM = 502;\n\n\tpublic static double sml = 1e-5;\n\n\tpublic static double[][] mat = new double[MAXN][MAXM];\n\n\t// 记录的是物品编号\n\tpublic static int[] basis = new int[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static int cnt, cost;\n\n\tpublic static void compute() {\n\t\tcnt = cost = 0;\n\t\tArrays.sort(mat, 1, n + 1, (a, b) -> a[m + 1] <= b[m + 1] ? -1 : 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (insert(i)) {\n\t\t\t\tcnt++;\n\t\t\t\tcost += (int) mat[i][m + 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean insert(int i) {\n\t\tfor (int j = 1; j <= m; j++) {\n\t\t\tif (Math.abs(mat[i][j]) >= sml) {\n\t\t\t\tif (basis[j] == 0) {\n\t\t\t\t\tbasis[j] = i;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tdouble rate = mat[i][j] / mat[basis[j]][j];\n\t\t\t\tfor (int k = j; k <= m; k++) {\n\t\t\t\t\tmat[i][k] -= rate * mat[basis[j]][k];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tmat[i][j] = (double) in.nval;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tmat[i][m + 1] = (double) in.nval;\n\t\t}\n\t\tcompute();\n\t\tout.println(cnt + " " + cost);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code01_BuyEquipment.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a873b16a-0570-41ee-ad7e-63ebedf11ef5	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class137;\n\n// P哥的桶\n// 一共有n个桶，排成一排，编号1~n，每个桶可以装下任意个数字\n// 高效的实现如下两个操作\n// 操作 1 k v : 把数字v放入k号桶中\n// 操作 2 l r : 可以从l..r号桶中随意拿数字，返回异或和最大的结果\n// 1 <= n、m <= 5 * 10^4\n// 0 <= v <= 2^31 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P4839\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_BucketMaximumXor {\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int BIT = 30;\n\n\t// 线段树的每个范围上维护线性基\n\tpublic static int[][] treeBasis = new int[MAXN << 2][BIT + 1];\n\n\tpublic static int[] basis = new int[BIT + 1];\n\n\tpublic static void add(int jobi, int jobv, int l, int r, int i) {\n\t\tinsert(treeBasis[i], jobv);\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tadd(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tadd(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean insert(int[] basis, int num) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int m) {\n\t\tArrays.fill(basis, 0);\n\t\tmerge(jobl, jobr, 1, m, 1);\n\t\tint ans = 0;\n\t\tfor (int j = BIT; j >= 0; j--) {\n\t\t\tans = Math.max(ans, ans ^ basis[j]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void merge(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tfor (int j = BIT; j >= 0; j--) {\n\t\t\t\tif (treeBasis[i][j] != 0) {\n\t\t\t\t\tinsert(basis, treeBasis[i][j]);\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tmerge(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tmerge(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tint op = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobi = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobv = (int) in.nval;\n\t\t\t\tadd(jobi, jobv, 1, m, 1);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobl = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tint jobr = (int) in.nval;\n\t\t\t\tout.println(query(jobl, jobr, m));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_BucketMaximumXor.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bc032c28-756f-4ecc-8251-673861825a0a	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class137;\n\n// 幸运数字(递归版)\n// 一共有n个点，编号1~n，由n-1条边连成一棵树，每个点上有数字\n// 一共有q条查询，每次返回a到b的路径上，可以随意选择数字，能得到的最大异或和\n// 1 <= n <= 2 * 10^4\n// 1 <= q <= 2 * 10^5\n// 0 <= 点上的数字 <= 2^60\n// 测试链接 : https://www.luogu.com.cn/problem/P3292\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code03_LuckyNumber2文件\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class Code03_LuckyNumber1 {\n\n\t// 节点个数上限\n\tpublic static int MAXN = 20002;\n\n\t// 树上倍增的次方上限\n\tpublic static int LIMIT = 16;\n\n\t// 节点值最大的位数\n\tpublic static int BIT = 60;\n\n\t// 每个节点值的数组\n\tpublic static long[] arr = new long[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// 树上倍增需要的深度表\n\tpublic static int[] deep = new int[MAXN];\n\n\t// 树上倍增需要的倍增表\n\tpublic static int[][] stjump = new int[MAXN][LIMIT];\n\n\t// 树上倍增根据实际节点个数确定的次方\n\tpublic static int power;\n\n\t// bases[i][j]表示：\n\t// 头节点到i节点路径上的数字，建立异或空间线性基，其中j位的线性基是哪个数字\n\tpublic static long[][] bases = new long[MAXN][BIT + 1];\n\n\t// levels[i][j]表示：\n\t// 头节点到i节点路径上的数字，建立异或空间线性基，其中j位的线性基来自哪一层\n\tpublic static int[][] levels = new int[MAXN][BIT + 1];\n\n\tpublic static void prepare(int n) {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tpower = log2(n);\n\t}\n\n\tpublic static int log2(int n) {\n\t\tint ans = 0;\n\t\twhile ((1 << ans) <= (n >> 1)) {\n\t\t\tans++;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tdeep[u] = deep[f] + 1;\n\t\tstjump[u][0] = f;\n\t\tfor (int p = 1; p <= power; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\tbases[u][i] = bases[f][i];\n\t\t\tlevels[u][i] = levels[f][i];\n\t\t}\n\t\tinsertReplace(arr[u], deep[u], bases[u], levels[u]);\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs(to[e], u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 插入和替换线性基，本题最重要的函数\n\tpublic static boolean insertReplace(long curv, int curl, long[] basis, int[] level) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (curv >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = curv;\n\t\t\t\t\tlevel[i] = curl;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tif (curl > level[i]) {\n\t\t\t\t\tlong tmp1 = curv;\n\t\t\t\t\tcurv = basis[i];\n\t\t\t\t\tbasis[i] = tmp1;\n\t\t\t\t\tint tmp2 = level[i];\n\t\t\t\t\tlevel[i] = curl;\n\t\t\t\t\tcurl = tmp2;\n\t\t\t\t}\n\t\t\t\tcurv ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static int lca(int x, int y) {\n\t\tif (deep[x] < deep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (deep[stjump[x][p]] >= deep[y]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[x][0];\n\t}\n\n\tpublic static long[] basis = new long[BIT + 1];\n\n\tpublic static long query(int x, int y) {\n\t\tint lca = lca(x, y);\n\t\tlong[] basisx = bases[x];\n\t\tint[] levelx = levels[x];\n\t\tlong[] basisy = bases[y];\n\t\tint[] levely = levels[y];\n\t\tArrays.fill(basis, 0);\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tlong num = basisx[i];\n\t\t\tif (levelx[i] >= deep[lca] && num != 0) {\n\t\t\t\tbasis[i] = num;\n\t\t\t}\n\t\t}\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tlong num = basisy[i];\n\t\t\tif (levely[i] >= deep[lca] && num != 0) {\n\t\t\t\tfor (int j = i; j >= 0; j--) {\n\t\t\t\t\tif (num >> j == 1) {\n\t\t\t\t\t\tif (basis[j] == 0) {\n\t\t\t\t\t\t\tbasis[j] = num;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tnum ^= basis[j];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tans = Math.max(ans, ans ^ basis[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\tint n = io.nextInt();\n\t\tint q = io.nextInt();\n\t\tprepare(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextLong();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs(1, 0);\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tio.println(query(x, y));\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_LuckyNumber1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9d3d3774-8a69-4b31-9df1-496caf6d2d0e	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class137;\n\n// 幸运数字(迭代版)\n// 一共有n个点，编号1~n，由n-1条无向边连成一棵树，每个点上有数字\n// 一共有q条查询，每次返回a到b的路径上，可以随意选择数字，能得到的最大异或和\n// 1 <= n <= 2 * 10^4\n// 1 <= q <= 2 * 10^5\n// 0 <= 点上的数字 <= 2^60\n// 测试链接 : https://www.luogu.com.cn/problem/P3292\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class Code03_LuckyNumber2 {\n\n\tpublic static int MAXN = 20002;\n\n\tpublic static int LIMIT = 16;\n\n\tpublic static int BIT = 60;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] deep = new int[MAXN];\n\n\tpublic static int[][] stjump = new int[MAXN][LIMIT];\n\n\tpublic static int power;\n\n\tpublic static long[][] bases = new long[MAXN][BIT + 1];\n\n\tpublic static int[][] levels = new int[MAXN][BIT + 1];\n\n\tpublic static void prepare(int n) {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tpower = log2(n);\n\t}\n\n\tpublic static int log2(int n) {\n\t\tint ans = 0;\n\t\twhile ((1 << ans) <= (n >> 1)) {\n\t\t\tans++;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\t// dfs迭代版\n\t// 不懂去看讲解118，递归改迭代的部分\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = f;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tf = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\tpublic static void dfs(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdeep[u] = deep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p <= power; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\tfor (int i = 0; i <= BIT; i++) {\n\t\t\t\t\tbases[u][i] = bases[f][i];\n\t\t\t\t\tlevels[u][i] = levels[f][i];\n\t\t\t\t}\n\t\t\t\tinsertReplace(arr[u], deep[u], bases[u], levels[u]);\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean insertReplace(long curv, int curl, long[] basis, int[] level) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (curv >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = curv;\n\t\t\t\t\tlevel[i] = curl;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tif (curl > level[i]) {\n\t\t\t\t\tlong tmp1 = curv;\n\t\t\t\t\tcurv = basis[i];\n\t\t\t\t\tbasis[i] = tmp1;\n\t\t\t\t\tint tmp2 = level[i];\n\t\t\t\t\tlevel[i] = curl;\n\t\t\t\t\tcurl = tmp2;\n\t\t\t\t}\n\t\t\t\tcurv ^= basis[i];\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static int lca(int x, int y) {\n\t\tif (deep[x] < deep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (deep[stjump[x][p]] >= deep[y]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tfor (int p = power; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[x][0];\n\t}\n\n\tpublic static long[] basis = new long[BIT + 1];\n\n\tpublic static long query(int x, int y) {\n\t\tint lca = lca(x, y);\n\t\tlong[] basisx = bases[x];\n\t\tint[] levelx = levels[x];\n\t\tlong[] basisy = bases[y];\n\t\tint[] levely = levels[y];\n\t\tArrays.fill(basis, 0);\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tlong num = basisx[i];\n\t\t\tif (levelx[i] >= deep[lca] && num != 0) {\n\t\t\t\tbasis[i] = num;\n\t\t\t}\n\t\t}\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tlong num = basisy[i];\n\t\t\tif (levely[i] >= deep[lca] && num != 0) {\n\t\t\t\tfor (int j = i; j >= 0; j--) {\n\t\t\t\t\tif (num >> j == 1) {\n\t\t\t\t\t\tif (basis[j] == 0) {\n\t\t\t\t\t\t\tbasis[j] = num;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tnum ^= basis[j];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tans = Math.max(ans, ans ^ basis[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\tint n = io.nextInt();\n\t\tint q = io.nextInt();\n\t\tprepare(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextLong();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs(1);\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tio.println(query(x, y));\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_LuckyNumber2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6e5da0d8-1970-41f7-895e-a972181702d3	dfd5fb93-5a17-45a0-bf48-36ce5ee971ac	java	package class137;\n\n// 路径最大异或和(递归版)\n// 一共有n个点，编号1~n，由m条无向边连接\n// 每条边有权值，输入保证图是连通的，可能有环\n// 找到1到n的一条路径，路径可以重复经过某些点或边\n// 当一条边在路径中出现了多次时，异或的时候也要算多次\n// 希望找到一条从1到n的路径，所有边权异或和尽量大，返回这个最大异或和\n// 1 <= n <= 50000\n// 1 <= m <= 100000\n// 0 <= 边权 <= 10^18\n// 测试链接 : https://www.luogu.com.cn/problem/P4151\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code04_MaximumXorOfPath2文件\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class Code04_MaximumXorOfPath1 {\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int MAXM = 200002;\n\n\tpublic static int BIT = 60;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static long[] weight = new long[MAXM];\n\n\tpublic static int cnt;\n\n\t// 所有环的异或和构建的线性基\n\tpublic static long[] basis = new long[BIT + 1];\n\n\t// 某个节点在dfs过程中是否被访问过\n\tpublic static boolean[] visited = new boolean[MAXN];\n\n\t// 从头结点到当前节点的异或和\n\tpublic static long[] path = new long[MAXN];\n\n\tpublic static void prepare(int n) {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(basis, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, long w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static boolean insert(long num) {\n\t\tfor (int i = BIT; i >= 0; i--)\n\t\t\tif (num >> i == 1) {\n\t\t\t\tif (basis[i] == 0) {\n\t\t\t\t\tbasis[i] = num;\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\tnum ^= basis[i];\n\t\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void dfs(int u, int f, long p) {\n\t\tpath[u] = p;\n\t\tvisited[u] = true;\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tlong xor = p ^ weight[e];\n\t\t\t\tif (visited[v]) {\n\t\t\t\t\tinsert(xor ^ path[v]);\n\t\t\t\t} else {\n\t\t\t\t\tdfs(v, u, xor);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long query(long init) {\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tinit = Math.max(init, init ^ basis[i]);\n\t\t}\n\t\treturn init;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tint n = io.nextInt();\n\t\tint m = io.nextInt();\n\t\tprepare(n);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint u = io.nextInt();\n\t\t\tint v = io.nextInt();\n\t\t\tlong w = io.nextLong();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tdfs(1, 0, 0);\n\t\tio.println(query(path[n]));\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code04_MaximumXorOfPath1.java	2026-07-25 03:11:34.779768+