int ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (mat[i][i] == 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t\tif (mat[i][n + 1] <= 0 || mat[i][n + 1] != (int) mat[i][n + 1]) {\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t\tif (maxv < mat[i][n + 1]) {\n\t\t\t\tmaxv = mat[i][n + 1];\n\t\t\t\tmaxt = 1;\n\t\t\t\tans = i;\n\t\t\t} else if (maxv == mat[i][n + 1]) {\n\t\t\t\tmaxt++;\n\t\t\t}\n\t\t}\n\t\tif (maxt > 1) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1, m; i <= n + 1; i++) {\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tfor (int j = 1, cur; j <= m; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tcur = (int) in.nval;\n\t\t\t\tdata[i][cur] = 1;\n\t\t\t}\n\t\t\tin.nextToken();\n\t\t\tdata[i][n + 1] = (int) in.nval;\n\t\t}\n\t\tint ans = 0;\n\t\tint times = 0;\n\t\tfor (int k = 1; k <= n + 1; k++) {\n\t\t\tswapData(k, n + 1);\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n + 1; j++) {\n\t\t\t\t\tmat[i][j] = data[i][j];\n\t\t\t\t}\n\t\t\t}\n\t\t\tswapData(k, n + 1);\n\t\t\tint cur = check();\n\t\t\tif (cur != 0) {\n\t\t\t\ttimes++;\n\t\t\t\tans = cur;\n\t\t\t}\n\t\t}\n\t\tif (times != 1) {\n\t\t\tout.println("illegal");\n\t\t} else {\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static void swapData(int i, int j) {\n\t\tint[] tmp = data[i];\n\t\tdata[i] = data[j];\n\t\tdata[j] = tmp;\n\t}\n\n}\n	模板：Code04_FindMaxWeighing.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fd8f7dbc-73d3-4944-8496-18f85ea839c0	15a69f23-3718-4970-86d6-79f72afea960	java	package class010;\n\n// 将两个升序链表合并为一个新的 升序 链表并返回\n// 新链表是通过拼接给定的两个链表的所有节点组成的\n// 测试链接 : https://leetcode.cn/problems/merge-two-sorted-lists/\npublic class MergeTwoLists {\n\n\t// 不要提交这个类\n\tpublic static class ListNode {\n\t\tpublic int val;\n\t\tpublic ListNode next;\n\n\t\tpublic ListNode(int val) {\n\t\t\tthis.val = val;\n\t\t}\n\n\t\tpublic ListNode(int val, ListNode next) {\n\t\t\tthis.val = val;\n\t\t\tthis.next = next;\n\t\t}\n\t}\n\n\tclass Solution {\n\n\t\tpublic static ListNode mergeTwoLists(ListNode head1, ListNode head2) {\n\t\t\tif (head1 == null || head2 == null) {\n\t\t\t\treturn head1 == null ? head2 : head1;\n\t\t\t}\n\t\t\tListNode head = head1.val <= head2.val ? head1 : head2;\n\t\t\tListNode cur1 = head.next;\n\t\t\tListNode cur2 = head == head1 ? head2 : head1;\n\t\t\tListNode pre = head;\n\t\t\twhile (cur1 != null && cur2 != null) {\n\t\t\t\tif (cur1.val <= cur2.val) {\n\t\t\t\t\tpre.next = cur1;\n\t\t\t\t\tcur1 = cur1.next;\n\t\t\t\t} else {\n\t\t\t\t\tpre.next = cur2;\n\t\t\t\t\tcur2 = cur2.next;\n\t\t\t\t}\n\t\t\t\tpre = pre.next;\n\t\t\t}\n\t\t\tpre.next = cur1 != null ? cur1 : cur2;\n\t\t\treturn head;\n\t\t}\n\n\t}\n\n}\n	模板：MergeTwoLists.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0aba874d-6421-4eff-a38f-985994e41e33	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class133;\n\n// 课上讲述高斯消元解决加法方程组的例子\n\npublic class ShowDetails {\n\n\tpublic static int MAXN = 101;\n\n\tpublic static double[][] mat = new double[MAXN][MAXN];\n\n\t// 0.0000001 == 1e-7\n\t// 因为double类型有精度问题，所以认为\n\t// 如果一个数字绝对值  <  sml，则认为该数字是0\n\t// 如果一个数字绝对值  >= sml，则认为该数字不是0\n\tpublic static double sml = 1e-7;\n\n\t// 高斯消元解决加法方程组模版\n\t// 需要保证变量有n个，表达式也有n个\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t// 如果想严格区分矛盾、多解、唯一解，一定要这么写\n\t\t\tint max = i;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && Math.abs(mat[j][j]) >= sml) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (Math.abs(mat[j][i]) > Math.abs(mat[max][i])) {\n\t\t\t\t\tmax = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tswap(i, max);\n\t\t\tif (Math.abs(mat[i][i]) >= sml) {\n\t\t\t\tdouble tmp = mat[i][i];\n\t\t\t\tfor (int j = i; j <= n + 1; j++) {\n\t\t\t\t\tmat[i][j] /= tmp;\n\t\t\t\t}\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j) {\n\t\t\t\t\t\tdouble rate = mat[j][i] / mat[i][i];\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] -= mat[i][k] * rate;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tdouble[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void print(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n + 1; j++) {\n\t\t\t\tSystem.out.printf("%.2f  ", mat[i][j]);\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t\tSystem.out.println("========================");\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 唯一解\n\t\t// 1*x1 + 2*x2 - 1*x3 = 9\n\t\t// 2*x1 - 1*x2 + 2*x3 = 7\n\t\t// 1*x1 - 2*x2 + 2*x3 = 0\n\t\tSystem.out.println("唯一解");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 9;\n\t\tmat[2][1] = 2; mat[2][2] = -1; mat[2][3] = 2; mat[2][4] = 7;\n\t\tmat[3][1] = 1; mat[3][2] = -2; mat[3][3] = 2; mat[3][4] = 0;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\t// 矛盾\n\t\t// 1*x1 + 1*x2 = 3\n\t\t// 2*x1 + 2*x2 = 7\n\t\tSystem.out.println("矛盾");\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 3;\n\t\tmat[2][1] = 2; mat[2][2] = 2; mat[2][3] = 7;\n\t\tgauss(2);\n\t\tprint(2);\n\n\t\t// 多解\n\t\t// 1*x1 + 1*x2 = 3\n\t\t// 2*x1 + 2*x2 = 6\n\t\tSystem.out.println("多解");\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 3;\n\t\tmat[2][1] = 2; mat[2][2] = 2; mat[2][3] = 6;\n\t\tgauss(2);\n\t\tprint(2);\n\n\t\t// 表达式冗余，唯一解\n\t\t// 1*x1 + 2*x2 - 1*x3 + 0*x4 = 9\n\t\t// 2*x1 + 4*x2 - 2*x3 + 0*x4 = 18\n\t\t// 2*x1 - 1*x2 + 2*x3 + 0*x4 = 7\n\t\t// 1*x1 - 2*x2 + 2*x3 + 0*x4 = 0\n\t\tSystem.out.println("表达式冗余，唯一解");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 0; mat[1][5] = 9;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = -2; mat[2][4] = 0; mat[2][5] = 18;\n\t\tmat[3][1] = 2; mat[3][2] = -1; mat[3][3] = 2; mat[3][4] = 0; mat[3][5] = 7;\n\t\tmat[4][1] = 1; mat[4][2] = -2; mat[4][3] = 2; mat[4][4] = 0; mat[4][5] = 0;\n\t\tgauss(4);\n\t\tprint(4);\n\n\t\t// 表达式冗余，矛盾\n\t\t// 1*x1 + 2*x2 - 1*x3 = 9\n\t\t// 2*x1 + 4*x2 - 2*x3 = 18\n\t\t// 2*x1 - 1*x2 + 2*x3 = 7\n\t\t// 4*x1 - 2*x2 + 4*x3 = 10\n\t\tSystem.out.println("表达式冗余，矛盾");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 0; mat[1][5] = 9;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = -2; mat[2][4] = 0; mat[2][5] = 18;\n\t\tmat[3][1] = 2; mat[3][2] = -1; mat[3][3] = 2; mat[3][4] = 0; mat[3][5] = 7;\n\t\tmat[4][1] = 4; mat[4][2] = -2; mat[4][3] = 4; mat[4][4] = 0; mat[4][5] = 10;\n\t\tgauss(4);\n\t\tprint(4);\n\n\t\t// 表达式冗余，多解\n\t\t// 1*x1 + 2*x2 - 1*x3 = 9\n\t\t// 2*x1 + 4*x2 - 2*x3 = 18\n\t\t// 2*x1 - 1*x2 + 2*x3 = 7\n\t\t// 4*x1 - 2*x2 + 4*x3 = 14\n\t\tSystem.out.println("表达式冗余，多解");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 0; mat[1][5] = 9;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = -2; mat[2][4] = 0; mat[2][5] = 18;\n\t\tmat[3][1] = 2; mat[3][2] = -1; mat[3][3] = 2; mat[3][4] = 0; mat[3][5] = 7;\n\t\tmat[4][1] = 4; mat[4][2] = -2; mat[4][3] = 4; mat[4][4] = 0; mat[4][5] = 14;\n\t\tgauss(4);\n\t\tprint(4);\n\n\t\t// 表达式不足，矛盾\n\t\t// 1*x1 + 2*x2 - 1*x3 = 5\n\t\t// 2*x1 + 4*x2 - 2*x3 = 7\n\t\tSystem.out.println("表达式不足，矛盾");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 5;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = -2; mat[2][4] = 7;\n\t\tmat[3][1] = 0; mat[3][2] = 0; mat[3][3] = 0;  mat[3][4] = 0;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\t// 表达式不足，多解\n\t\t// 1*x1 + 2*x2 - 1*x3 = 5\n\t\t// 2*x1 + 2*x2 - 1*x3 = 8\n\t\tSystem.out.println("表达式不足，多解");\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = -1; mat[1][4] = 5;\n\t\tmat[2][1] = 2; mat[2][2] = 2; mat[2][3] = -1; mat[2][4] = 8;\n\t\tmat[3][1] = 0; mat[3][2] = 0; mat[3][3] = 0;  mat[3][4] = 0;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\t// 正确区分矛盾、多解、唯一解\n\t\t// 0*x1 + 2*x2 = 3\n\t\t// 0*x1 + 0*x2 = 0\n\t\tSystem.out.println("正确区分矛盾、多解、唯一解");\n\t\tmat[1][1] = 0; mat[1][2] = 2; mat[1][3] = 3;\n\t\tmat[2][1] = 0; mat[2][2] = 0; mat[2][3] = 0;\n\t\tgauss(2);\n\t\tprint(2);\n\n\t\t// 有些主元可以确定值\n\t\t// a  + b + c = 5\n\t\t// 2a + b + c = 7\n\t\tSystem.out.println("有些主元可以确定值");\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 1; mat[1][4] = 5;\n\t\tmat[2][1] = 2; mat[2][2] = 1; mat[2][3] = 1; mat[2][4] = 7;\n\t\tmat[3][1] = 0; mat[3][2] = 0; mat[3][3] = 0; mat[3][4] = 0;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\t// 有些主元还受到自由元的影响\n\t\t// a + b = 5\n\t\tSystem.out.println("有些主元还受到自由元的影响");\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 5;\n\t\tmat[2][1] = 0; mat[2][2] = 0; mat[2][3] = 0;\n\t\tgauss(2);\n\t\tprint(2);\n\t}\n\n}	模板：ShowDetails.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
43d4e56b-2332-4082-bf13-a63a55a9255e	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class134;\n\n// 高斯消元解决异或方程组模版题\n// 有一个长度为n的数组arr，可能有重复值，数字都是long类型的正数\n// 每个数拥有的质数因子一定不超过2000，每个数最多挑选一次\n// 在至少要选一个数的情况下，你可以随意挑选数字乘起来\n// 乘得的结果需要是完全平方数，请问有几种挑选数字的方法\n// 方法数可能很大，答案对 1000000007 取模\n// 1 <= n <= 300\n// 1 <= arr[i] <= 10^18\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5833\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code01_GaussEor {\n\n\tpublic static int MOD = 1000000007;\n\n\tpublic static int MAXV = 2000;\n\n\tpublic static int MAXN = 305;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\tpublic static int[][] mat = new int[MAXN][MAXN];\n\n\t// 收集2000以内的质数，一共就303个，这是大于arr的个数的\n\tpublic static int[] prime = new int[MAXV + 1];\n\n\t// 2000以内质数的个数，一共就303个，这是大于arr的个数的\n\tpublic static int cnt;\n\n\t// 埃氏筛需要\n\tpublic static boolean[] visit = new boolean[MAXV + 1];\n\n\t// pow2[i] : 2的i次方 % MOD\n\tpublic static int[] pow2 = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static void prepare() {\n\t\t// 得到2000以内的质数\n\t\t// 如果不会就去看，讲解097，埃氏筛\n\t\t// 当然也可以用欧拉筛，也在讲解097\n\t\tfor (int i = 2; i * i <= MAXV; i++) {\n\t\t\tif (!visit[i]) {\n\t\t\t\tfor (int j = i * i; j <= MAXV; j += i) {\n\t\t\t\t\tvisit[j] = true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tcnt = 0;\n\t\tfor (int i = 2; i <= MAXV; i++) {\n\t\t\tif (!visit[i]) {\n\t\t\t\tprime[++cnt] = i;\n\t\t\t}\n\t\t}\n\t\t// 2的i次方%MOD的结果\n\t\tpow2[0] = 1;\n\t\tfor (int i = 1; i < MAXN; i++) {\n\t\t\tpow2[i] = (pow2[i - 1] * 2) % MOD;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tprepare();\n\t\t// 题目会读取10^18范围内的long类型数字\n\t\t// 用StreamTokenizer可能无法正确读取，因为先变成double再转成long\n\t\t// 这里用Kattio类，具体看讲解019的代码中，Code05_Kattio文件\n\t\t// 有详细的说明\n\t\tKattio io = new Kattio();\n\t\tint test = io.nextInt();\n\t\tfor (int t = 1; t <= test; t++) {\n\t\t\tn = io.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tarr[i] = io.nextLong();\n\t\t\t}\n\t\t\tio.println("Case #" + t + ":");\n\t\t\tio.println(compute());\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tfor (int j = 1; j <= cnt + 1; j++) {\n\t\t\t\tmat[i][j] = 0;\n\t\t\t}\n\t\t}\n\t\tlong cur;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcur = arr[i];\n\t\t\tfor (int j = 1; j <= cnt && cur != 0; j++) {\n\t\t\t\twhile (cur % prime[j] == 0) {\n\t\t\t\t\tmat[j][i] ^= 1;\n\t\t\t\t\tcur /= prime[j];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tgauss(cnt);\n\t\tint main = 0; // 主元的数量\n\t\tfor (int i = 1; i <= cnt; i++) {\n\t\t\tif (mat[i][i] == 1) {\n\t\t\t\tmain++;\n\t\t\t}\n\t\t}\n\t\t// 影响每个主元的自由元们一旦确定\n\t\t// 那么该主元选和不选也就唯一确定了\n\t\t// 所以重点是自由元如何决策，n - main就是自由元的数量\n\t\t// 自由元之间一定相互独立，每个自由元都可以做出选和不选的决定\n\t\t// 所以一共是2的(n - main)次方种决策\n\t\t// 但是想象一下，如果所有自由元都不选，\n\t\t// mat值的部分(cnt+1列)全是0啊！那么意味着，所有主元也都不选\n\t\t// 但是题目要求至少要选一个数，所以不能出现自由元都不选的情况\n\t\t// 所以返回方法数-1\n\t\t// 能够分析的前提是对主元和自由元之间的关系有清晰的认识\n\t\treturn pow2[n - main] - 1;\n\t}\n\n\t// 高斯消元解决异或方程组模版\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && mat[j][j] == 1) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (mat[j][i] == 1) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] == 1) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] == 1) {\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] ^= mat[i][k];\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}	模板：Code01_GaussEor.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
232c085f-30c4-44f2-b3da-fb6c4bfbf231	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class134;\n\n// 全变成1的最少操作次数\n// 一共有n个点，m条无向边，每个点的初始状态都是0\n// 可以操作任意一个点，操作后该点以及相邻点的状态都会改变\n// 最终是希望所有点都变成1状态，那么可能会若干方案都可以做到\n// 那么其中存在需要最少操作次数的方案，打印这个最少操作次数\n// 题目保证一定能做到所有点都变成1状态，并且没有重边和自环\n// 1 <= n <= 35\n// 1 <= m <= 595\n// 测试链接 : https://www.luogu.com.cn/problem/P2962\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_MinimumOperations {\n\n\tpublic static int MAXN = 37;\n\n\tpublic static int[][] mat = new int[MAXN][MAXN];\n\n\tpublic static int[] op = new int[MAXN];\n\n\tpublic static int n, ans;\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tmat[i][j] = 0;\n\t\t\t}\n\t\t\tmat[i][i] = 1;\n\t\t\tmat[i][n + 1] = 1;\n\t\t\top[i] = 0;\n\t\t}\n\t}\n\n\t// 高斯消元解决异或方程组模版\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && mat[j][j] == 1) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (mat[j][i] == 1) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] == 1) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] == 1) {\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] ^= mat[i][k];\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void dfs(int i, int num) {\n\t\tif (num >= ans) { // 剪枝\n\t\t\treturn;\n\t\t}\n\t\tif (i == 0) {\n\t\t\tans = num;\n\t\t} else {\n\t\t\tif (mat[i][i] == 0) {\n\t\t\t\t// 当前是自由元\n\t\t\t\t// 自由元一定不依赖主元\n\t\t\t\t// 自由元也一定不依赖其他自由元\n\t\t\t\t// 所以当前自由元一定可以自行决定要不要操作\n\t\t\t\top[i] = 0;\n\t\t\t\tdfs(i - 1, num);\n\t\t\t\top[i] = 1;\n\t\t\t\tdfs(i - 1, num + 1);\n\t\t\t} else {\n\t\t\t\t// 当前是主元\n\t\t\t\t// 主元可能被其他自由元影响\n\t\t\t\t// 而且一定有，当前主元的编号 < 影响它的自由元编号\n\t\t\t\t// 所以会影响当前主元的自由元们，一定已经确定了要不要操作\n\t\t\t\t// 那么当前主元要不要操作，也就确定了\n\t\t\t\tint cur = mat[i][n + 1];\n\t\t\t\tfor (int j = i + 1; j <= n; j++) {\n\t\t\t\t\tif (mat[i][j] == 1) {\n\t\t\t\t\t\tcur ^= op[j];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tdfs(i - 1, num + cur);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tprepare();\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tmat[u][v] = 1;\n\t\t\tmat[v][u] = 1;\n\t\t}\n\t\tgauss(n);\n\t\tint sign = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (mat[i][i] == 0) {\n\t\t\t\tsign = 0;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (sign == 1) {\n\t\t\t// 唯一解\n\t\t\tans = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (mat[i][n + 1] == 1) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\t// 多解\n\t\t\tans = n;\n\t\t\tdfs(n, 0);\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code02_MinimumOperations.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
12d233ef-c7b9-4a56-a5d8-55d3cacf5b93	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class134;\n\n// 外星千足虫\n// 一共有n种虫子，编号1~n，虫子腿为奇数认为是外星虫，偶数认为是地球虫\n// 一共有m条虫子腿的测量记录，记录编号1~m\n// 比如其中一条测量记录为，011 1，表示1号虫没参与，2号、3号虫参与了，总腿数为奇数\n// 测量记录保证不会有自相矛盾的情况，但是可能有冗余的测量结果\n// 也许拥有从第1号到第k号测量记录就够了，k+1~m号测量记录有或者没有都不影响测量结果\n// 打印这个k，并且打印每种虫子到底是外星虫还是地球虫\n// 如果使用所有的测量结果，依然无法确定每种虫子的属性，打印"Cannot Determine"\n// 1 <= n <= 1000\n// 1 <= m <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P2447\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code03_AlienInsectLegs {\n\n\tpublic static int BIT = 64;\n\n\tpublic static int MAXN = 2002;\n\n\tpublic static int MAXM = MAXN / BIT + 1;\n\n\tpublic static long[][] mat = new long[MAXN][MAXM];\n\n\tpublic static int n, m, s;\n\n\tpublic static int need;\n\n\t// 高斯消元解决异或方程组模版 + 位图，很小的改写\n\tpublic static void gauss(int n) {\n\t\tneed = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = i; j <= n; j++) {\n\t\t\t\tif (get(j, i) == 1) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tneed = Math.max(need, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 一旦没有唯一解，可以结束了\n\t\t\tif (get(i, i) == 0) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (i != j && get(j, i) == 1) {\n\t\t\t\t\t// 因为列从1开始，所以从第1位状态开始才有用\n\t\t\t\t\t// 于是1~n+1列的状态，对应1~n+1位\n\t\t\t\t\t// 但是位图中永远有0位，只不过从来不使用\n\t\t\t\t\t// 于是一共有n+2位状态，都需要异或\n\t\t\t\t\teor(i, j, n + 2);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 把row行，col列的状态设置成v\n\tpublic static void set(int row, int col, int v) {\n\t\tif (v == 0) {\n\t\t\tmat[row][col / BIT] &= ~(1L << (col % BIT));\n\t\t} else {\n\t\t\tmat[row][col / BIT] |= 1L << (col % BIT);\n\t\t}\n\t}\n\n\t// 得到row行，col列的状态\n\tpublic static int get(int row, int col) {\n\t\treturn ((mat[row][col / BIT] >> (col % BIT)) & 1) == 1 ? 1 : 0;\n\t}\n\n\t// row2行状态 = row2行状态 ^ row1行状态\n\t// 状态一共有bits位\n\tpublic static void eor(int row1, int row2, int bits) {\n\t\tfor (int k = 0; k <= bits / BIT; k++) {\n\t\t\tmat[row2][k] ^= mat[row1][k];\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tlong[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\ts = Math.max(n, m);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tchar[] line = io.next().toCharArray();\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tset(i, j, line[j - 1] - '0');\n\t\t\t}\n\t\t\tset(i, s + 1, io.nextInt());\n\t\t}\n\t\tgauss(s);\n\t\tint sign = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (get(i, i) == 0) {\n\t\t\t\tsign = 0;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (sign == 0) {\n\t\t\tio.println("Cannot Determine");\n\t\t} else {\n\t\t\tio.println(need);\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (get(i, s + 1) == 1) {\n\t\t\t\t\tio.println("?y7M#");\n\t\t\t\t} else {\n\t\t\t\t\tio.println("Earth");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code03_AlienInsectLegs.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2a7619af-d0a4-4ecc-898d-72fac37a8fcb	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class134;\n\n// 课上讲述高斯消元解决异或方程组的例子\n\npublic class ShowDetails {\n\n\tpublic static int MAXN = 101;\n\n\tpublic static int[][] mat = new int[MAXN][MAXN];\n\n\t// 高斯消元解决异或方程组模版\n\t// 需要保证变量有n个，表达式也有n个\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && mat[j][j] == 1) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (mat[j][i] == 1) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] == 1) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] == 1) {\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] ^= mat[i][k];\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void print(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n + 1; j++) {\n\t\t\t\tSystem.out.print(mat[i][j] + " ");\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t\tSystem.out.println("========================");\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("课上图解的例子，有唯一解");\n\t\t// x1 ^ x2 ^ x3 = 0\n\t\t// x1 ^ x3 ^ x4 = 1\n\t\t// x2 ^ x3 ^ x4 = 1\n\t\t// x3 ^ x4 = 0\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 1; mat[1][4] = 0; mat[1][5] = 0;\n\t\tmat[2][1] = 1; mat[2][2] = 0; mat[2][3] = 1; mat[2][4] = 1; mat[2][5] = 1;\n\t\tmat[3][1] = 0; mat[3][2] = 1; mat[3][3] = 1; mat[3][4] = 1; mat[3][5] = 1;\n\t\tmat[4][1] = 0; mat[4][2] = 0; mat[4][3] = 1; mat[4][4] = 1; mat[4][5] = 0;\n\t\tgauss(4);\n\t\tprint(4);\n\n\t\tSystem.out.println("表达式存在矛盾的例子");\n\t\t// x1 ^ x2 = 1\n\t\t// x1 ^ x3 = 1\n\t\t// x2 ^ x3 = 1\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 0; mat[1][4] = 1;\n\t\tmat[2][1] = 1; mat[2][2] = 0; mat[2][3] = 1; mat[2][4] = 1;\n\t\tmat[3][1] = 0; mat[3][2] = 1; mat[3][3] = 1; mat[3][4] = 1;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\tSystem.out.println("表达式存在多解的例子");\n\t\t// x1 ^ x3 = 1\n\t\t// x2 ^ x3 = 1\n\t\t// x1 ^ x2 = 0\n\t\tmat[1][1] = 1; mat[1][2] = 0; mat[1][3] = 1; mat[1][4] = 1;\n\t\tmat[2][1] = 0; mat[2][2] = 1; mat[2][3] = 1; mat[2][4] = 1;\n\t\tmat[3][1] = 1; mat[3][2] = 1; mat[3][3] = 0; mat[3][4] = 0;\n\t\tmat[4][1] = 1; mat[4][2] = 1; mat[4][3] = 0; mat[4][4] = 0;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\tSystem.out.println("注意下面这个多解的例子");\n\t\t// x1 ^ x3 ^ x4 = 0\n\t\t// x2 ^ x3 ^ x4 = 0\n\t\t// x1 ^ x2 = 0\n\t\t// x3 ^ x4 = 1\n\t\tmat[1][1] = 1; mat[1][2] = 0; mat[1][3] = 1; mat[1][4] = 1; mat[1][5] = 0;\n\t\tmat[2][1] = 0; mat[2][2] = 1; mat[2][3] = 1; mat[2][4] = 1; mat[2][5] = 0;\n\t\tmat[3][1] = 1; mat[3][2] = 1; mat[3][3] = 0; mat[3][4] = 0; mat[3][5] = 0;\n\t\tmat[4][1] = 0; mat[4][2] = 0; mat[4][3] = 1; mat[4][4] = 1; mat[4][5] = 1;\n\t\tgauss(4);\n\t\tprint(4);\n\t\tSystem.out.println("最后一个例子里");\n\t\tSystem.out.println("主元x1和x2，不受其他自由元影响，值可以直接确定");\n\t\tSystem.out.println("但是主元x3，受到自由元x4的影响，x3 ^ x4 = 1");\n\t\tSystem.out.println("只有自由元x4确定了值，主元x3的值才能确定");\n\t\tSystem.out.println("这里是想说，消元完成后，如果结论是多解，那么");\n\t\tSystem.out.println("有些主元的值可以直接确定");\n\t\tSystem.out.println("有些主元的值需要若干自由元确定之后才能确定");\n\t\tSystem.out.println("这就是上节课，也就是讲解133讲的：");\n\t\tSystem.out.println("主元和自由元之间的依赖关系");\n\t\tSystem.out.println("请确保已经掌握");\n\t}\n\n}	模板：ShowDetails.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d36833eb-8801-41d0-afed-37c09bed2182	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class135;\n\n// 格子全变成0的操作方案\n// 有一个n*m的二维网格，给定每个网格的初始值，一定是0、1、2中的一个\n// 如果某个网格获得了一些数值加成，也会用%3的方式变成0、1、2中的一个\n// 比如有个网格一开始值是1，获得4的加成之后，值为(1+4)%3 = 2\n// 有一个神奇的刷子，一旦在某个网格处刷一下，该网格会获得2的加成\n// 并且该网格上、下、左、右的格子，都会获得1的加成\n// 最终目标是所有网格都变成0，题目保证一定有解，但不保证唯一解\n// 得到哪一种方案都可以，打印一共需要刷几下，并且把操作方案打印出来\n// 1 <= n、m <= 30\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5755\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_GamblerBo {\n\n\tpublic static int MOD = 3;\n\n\tpublic static int MAXS = 1001;\n\n\tpublic static int[][] mat = new int[MAXS][MAXS];\n\n\tpublic static int[] dir = { 0, -1, 0, 1, 0 };\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] inv = new int[MOD];\n\n\tpublic static void inv() {\n\t\tinv[1] = 1;\n\t\tfor (int i = 2; i < MOD; i++) {\n\t\t\tinv[i] = (int) (MOD - (long) inv[MOD % i] * (MOD / i) % MOD);\n\t\t}\n\t}\n\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= s; i++) {\n\t\t\tfor (int j = 1; j <= s + 1; j++) {\n\t\t\t\tmat[i][j] = 0;\n\t\t\t}\n\t\t}\n\t\tint cur, row, col;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\tcur = i * m + j + 1;\n\t\t\t\tmat[cur][cur] = 2;\n\t\t\t\tfor (int d = 0; d <= 3; d++) {\n\t\t\t\t\trow = i + dir[d];\n\t\t\t\t\tcol = j + dir[d + 1];\n\t\t\t\t\tif (row >= 0 && row < n && col >= 0 && col < m) {\n\t\t\t\t\t\tmat[cur][row * m + col + 1] = 1;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 这道题目比较特殊，打印任何一种方案都可以\n\t// 于是认为所有自由元的操作次数为0\n\t// 也就是认为消元之后，主元不被任何自由元影响\n\t// 所以代码可以简化\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (mat[j][i] != 0) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] != 0) {\n\t\t\t\t\t\tint gcd = gcd(mat[j][i], mat[i][i]);\n\t\t\t\t\t\tint a = mat[i][i] / gcd;\n\t\t\t\t\t\tint b = mat[j][i] / gcd;\n\t\t\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\t\t\t// 只需要调整，j行主元的系数，也就是j行j列的值\n\t\t\t\t\t\t\t// 不需要调整，j行，j+1列 ~ i-1列的值，所对应自由元的系数\n\t\t\t\t\t\t\t// 因为最终方案默认所有自由元都不操作\n\t\t\t\t\t\t\tmat[j][j] = (mat[j][j] * a) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t\t// 正常消元\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] = ((mat[j][k] * a - mat[i][k] * b) % MOD + MOD) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t// 由于本题的特殊性，不需要去管任何自由元的影响\n\t\t// 就当自由元不操作，直接求主元的操作次数即可\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\tmat[i][n + 1] = (mat[i][n + 1] * inv[mat[i][i]]) % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tinv();\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint test = (int) in.nval;\n\t\tfor (int t = 1; t <= test; t++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\ts = n * m;\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= s; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tmat[i][s + 1] = (3 - (int) in.nval) % MOD;\n\t\t\t}\n\t\t\tgauss(s);\n\t\t\tint ans = 0;\n\t\t\tfor (int i = 1; i <= s; i++) {\n\t\t\t\tans += mat[i][s + 1];\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t\tfor (int i = 1, id = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= m; j++, id++) {\n\t\t\t\t\twhile (mat[id][s + 1]-- > 0) {\n\t\t\t\t\t\tout.println(i + " " + j);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code01_GamblerBo.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dcbf80ff-4f18-4706-9ddc-e78dfb6986a3	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class135;\n\n// 工具工厂\n// 一共有n种工具，编号1~n，一共有m条记录，其中一条记录格式如下：\n// 4 WED SUN 13 18 1 13\n// 表示有个工人一共加工了4件工具，从某个星期三开始工作，到某个星期天结束工作\n// 加工的工具依次为13号、18号、1号、13号\n// 每个工人在工作期间不休息，每件工具都是串行加工的，完成一件后才开始下一件\n// 每种工具制作天数是固定的，并且任何工具的制作天数最少3天、最多9天\n// 但该数据丢失了，所以现在需要根据记录，推断出每种工具的制作天数\n// 如果记录之间存在矛盾，打印"Inconsistent data."\n// 如果记录无法确定每种工具的制作天数，打印"Multiple solutions."\n// 如果记录能够确定每种工具的制作天数，打印所有结果\n// 1 <= n、m <= 300\n// 测试链接 : http://poj.org/problem?id=2947\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code02_WidgetFactory {\n\n\tpublic static int MOD = 7;\n\n\tpublic static int MAXN = 302;\n\n\tpublic static int[][] mat = new int[MAXN][MAXN];\n\n\tpublic static int[] inv = new int[MOD];\n\n\tpublic static String[] days = { "MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN" };\n\n\tpublic static int n, m, s;\n\n\tpublic static void inv() {\n\t\tinv[1] = 1;\n\t\tfor (int i = 2; i < MOD; i++) {\n\t\t\tinv[i] = (int) (MOD - (long) inv[MOD % i] * (MOD / i) % MOD);\n\t\t}\n\t}\n\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= s; i++) {\n\t\t\tfor (int j = 1; j <= s + 1; j++) {\n\t\t\t\tmat[i][j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int day(String str) {\n\t\tfor (int i = 0; i < days.length; i++) {\n\t\t\tif (str.equals(days[i])) {\n\t\t\t\treturn i;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\t// 高斯消元解决同余方程组模版，保证初始系数没有负数\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (mat[j][i] != 0) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] != 0) {\n\t\t\t\t\t\tint gcd = gcd(mat[j][i], mat[i][i]);\n\t\t\t\t\t\tint a = mat[i][i] / gcd;\n\t\t\t\t\t\tint b = mat[j][i] / gcd;\n\t\t\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\t\t\tfor (int k = j; k < i; k++) {\n\t\t\t\t\t\t\t\tmat[j][k] = (mat[j][k] * a) % MOD;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] = ((mat[j][k] * a - mat[i][k] * b) % MOD + MOD) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\tboolean flag = false;\n\t\t\t\tfor (int j = i + 1; j <= n; j++) {\n\t\t\t\t\tif (mat[i][j] != 0) {\n\t\t\t\t\t\tflag = true;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (!flag) {\n\t\t\t\t\tmat[i][n + 1] = (mat[i][n + 1] * inv[mat[i][i]]) % MOD;\n\t\t\t\t\tmat[i][i] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tinv();\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\twhile (n != 0 && m != 0) {\n\t\t\ts = Math.max(n, m);\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint k = io.nextInt();\n\t\t\t\tString st = io.next();\n\t\t\t\tString et = io.next();\n\t\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\t\tint tool = io.nextInt();\n\t\t\t\t\tmat[i][tool] = (mat[i][tool] + 1) % MOD;\n\t\t\t\t}\n\t\t\t\tmat[i][s + 1] = ((day(et) - day(st) + 1) % MOD + MOD) % MOD;\n\t\t\t}\n\t\t\tgauss(s);\n\t\t\tint sign = 1;\n\t\t\tfor (int i = 1; i <= s; i++) {\n\t\t\t\tif (mat[i][i] == 0 && mat[i][s + 1] != 0) {\n\t\t\t\t\tsign = -1;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tif (i <= n && mat[i][i] == 0) {\n\t\t\t\t\tsign = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (sign == -1) {\n\t\t\t\tio.println("Inconsistent data.");\n\t\t\t} else if (sign == 0) {\n\t\t\t\tio.println("Multiple solutions.");\n\t\t\t} else {\n\t\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\t\tif (mat[i][s + 1] < 3) {\n\t\t\t\t\t\tmat[i][s + 1] += 7;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tfor (int i = 1; i < n; i++) {\n\t\t\t\t\tio.print(mat[i][s + 1] + " ");\n\t\t\t\t}\n\t\t\t\tio.println(mat[n][s + 1]);\n\t\t\t}\n\t\t\t// 下一组n和m\n\t\t\tn = io.nextInt();\n\t\t\tm = io.nextInt();\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n	模板：Code02_WidgetFactory.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dc165538-a34d-4d27-a674-9f5b3efcd553	693a3d4a-560c-4f4a-b4c7-cf12badc3086	java	package class135;\n\n// 课上讲述高斯消元解决同余方程组的例子\n\npublic class ShowDetails {\n\n\t// 题目会保证取模的数字为质数\n\tpublic static int MOD = 7;\n\n\tpublic static int MAXN = 101;\n\n\tpublic static int[][] mat = new int[MAXN][MAXN];\n\n\t// 逆元线性递推公式求逆元表，讲解099 - 除法同余\n\tpublic static int[] inv = new int[MOD];\n\n\tpublic static void inv() {\n\t\tinv[1] = 1;\n\t\tfor (int i = 2; i < MOD; i++) {\n\t\t\tinv[i] = (int) (MOD - (long) inv[MOD % i] * (MOD / i) % MOD);\n\t\t}\n\t}\n\n\t// 求a和b的最大公约数，保证a和b都不等于0\n\tpublic static int gcd(int a, int b) {\n\t\treturn b == 0 ? a : gcd(b, a % b);\n\t}\n\n\t// 高斯消元解决同余方程组模版，保证初始系数没有负数\n\t// ((系数 % MOD) + MOD) % MOD\n\tpublic static void gauss(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t// 已经成为主元的行不参与\n\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t// 找到系数不等于0的行做主元即可\n\t\t\t\tif (mat[j][i] != 0) {\n\t\t\t\t\tswap(i, j);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j && mat[j][i] != 0) {\n\t\t\t\t\t\tint gcd = gcd(mat[j][i], mat[i][i]);\n\t\t\t\t\t\tint a = mat[i][i] / gcd;\n\t\t\t\t\t\tint b = mat[j][i] / gcd;\n\t\t\t\t\t\tif (j < i && mat[j][j] != 0) {\n\t\t\t\t\t\t\t// 如果j行有主元，那么从j列到i-1列的所有系数 * a\n\t\t\t\t\t\t\t// 正确更新主元和自由元之间的关系\n\t\t\t\t\t\t\tfor (int k = j; k < i; k++) {\n\t\t\t\t\t\t\t\tmat[j][k] = (mat[j][k] * a) % MOD;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\t// 正常消元\n\t\t\t\t\t\tfor (int k = i; k <= n + 1; k++) {\n\t\t\t\t\t\t\tmat[j][k] = ((mat[j][k] * a - mat[i][k] * b) % MOD + MOD) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (mat[i][i] != 0) {\n\t\t\t\t// 检查当前主元是否被若干自由元影响\n\t\t\t\t// 如果当前主元不受自由元影响，那么可以确定当前主元的值\n\t\t\t\t// 否则保留这种影响，正确显示主元和自由元的关系\n\t\t\t\tboolean flag = false;\n\t\t\t\tfor (int j = i + 1; j <= n; j++) {\n\t\t\t\t\tif (mat[i][j] != 0) {\n\t\t\t\t\t\tflag = true;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (!flag) {\n\t\t\t\t\t// 本来应该是，mat[i][n + 1] = mat[i][n + 1] / mat[i][i]\n\t\t\t\t\t// 但是在模意义下应该求逆元，(a / b) % MOD = (a * b的逆元) % MOD\n\t\t\t\t\t// 如果不会，去看讲解099 - 除法同余\n\t\t\t\t\tmat[i][n + 1] = (mat[i][n + 1] * inv[mat[i][i]]) % MOD;\n\t\t\t\t\tmat[i][i] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int a, int b) {\n\t\tint[] tmp = mat[a];\n\t\tmat[a] = mat[b];\n\t\tmat[b] = tmp;\n\t}\n\n\tpublic static void print(int n) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int j = 1; j <= n + 1; j++) {\n\t\t\t\tSystem.out.print(mat[i][j] + " ");\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t\tSystem.out.println("========================");\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 逆元表建立好\n\t\tinv();\n\t\tSystem.out.println("课上图解的例子，唯一解");\n\t\t// 4*x1 + 2*x2 + 4*x3 同余 3\n\t\t// 2*x1 + 5*x2 + 2*x3 同余 2\n\t\t// 6*x1 + 3*x2 + 4*x3 同余 5\n\t\tmat[1][1] = 4; mat[1][2] = 2; mat[1][3] = 4; mat[1][4] = 3;\n\t\tmat[2][1] = 2; mat[2][2] = 5; mat[2][3] = 2; mat[2][4] = 2;\n\t\tmat[3][1] = 6; mat[3][2] = 3; mat[3][3] = 4; mat[3][4] = 5;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\tSystem.out.println("表达式存在矛盾的例子");\n\t\t// 1*x1 + 2*x2 + 3*x3 同余 2\n\t\t// 2*x1 + 4*x2 + 6*x3 同余 5\n\t\t// 0*x1 + 3*x2 + 4*x3 同余 2\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = 3; mat[1][4] = 2;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = 6; mat[2][4] = 5;\n\t\tmat[3][1] = 0; mat[3][2] = 3; mat[3][3] = 4; mat[3][4] = 2;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\tSystem.out.println("课上图解的例子，多解");\n\t\tSystem.out.println("只有确定了自由元，才能确定主元的值");\n\t\tSystem.out.println("如果是多解的情况，那么在消元结束后");\n\t\tSystem.out.println("二维矩阵中主元和自由元的关系是正确的");\n\t\tSystem.out.println("课上也进行了验证");\n\t\t// 1*x1 + 2*x2 + 3*x3 同余 2\n\t\t// 2*x1 + 4*x2 + 6*x3 同余 4\n\t\t// 0*x1 + 3*x2 + 4*x3 同余 2\n\t\tmat[1][1] = 1; mat[1][2] = 2; mat[1][3] = 3; mat[1][4] = 2;\n\t\tmat[2][1] = 2; mat[2][2] = 4; mat[2][3] = 6; mat[2][4] = 4;\n\t\tmat[3][1] = 0; mat[3][2] = 3; mat[3][3] = 4; mat[3][4] = 2;\n\t\tgauss(3);\n\t\tprint(3);\n\n\t\tSystem.out.println("注意下面这个多解的例子");\n\t\t// 1*x1 + 1*x2 + 1*x3 同余 3\n\t\t// 2*x1 + 1*x2 + 1*x3 同余 5\n\t\t// 0*x1 + 3*x2 + 3*x3 同余 3\n\t\tmat[1][1] = 1; mat[1][2] = 1; mat[1][3] = 1; mat[1][4] = 3;\n\t\tmat[2][1] = 2; mat[2][2] = 1; mat[2][3] = 1; mat[2][4] = 5;\n\t\tmat[3][1] = 0; mat[3][2] = 3; mat[3][3] = 3; mat[3][4] = 3;\n\t\tgauss(3);\n\t\tprint(3);\n\t\tSystem.out.println("最后一个例子里");\n\t\tSystem.out.println("主元x1，不受其他自由元影响，值可以直接确定");\n\t\tSystem.out.println("但是主元x2，受到自由元x3的影响，6*x2 + 6*x3 同余 6");\n\t\tSystem.out.println("只有自由元x3确定了值，主元x2的值才能确定");\n\t\tSystem.out.println("本节课提供的模版，对于能求出的主元可以得到正确结果");\n\t\tSystem.out.println("对于不能求出的主元，该模版也能给出，主元和自由元的正确关系");\n\t\tSystem.out.println("有些题目需要这种多解情况下，主元和自由元之间的正确关系");\n\t\tSystem.out.println("绝大多数模版和讲解都没有考虑这个，但值得引起重视");\n\t\tSystem.out.println("如果有些题目不需要这种正确关系");\n\t\tSystem.out.println("那么逻辑可以化简，让常数时间更快，比如本节课的题目1");\n\t}\n\n}	模板：ShowDetails.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
32cd4821-44fc-46f7-80c3-a83c5df43d3e	e84c0090-f5e5-416c-935e-4fec468a16d2	java	package class001;\n\n// 测试链接 : https://leetcode.cn/problems/sort-an-array/\n// 此时不要求掌握，因为这些排序后续的课都会讲到的\n// 这里只是想说明代码语言的转换并不困难\n// 整个系列虽然都是java讲的，但使用不同语言的同学听懂思路之后，想理解代码真的不是问题\n// 语言问题并不是学习算法的障碍，有了人工智能工具之后，就更不是障碍了\npublic class LanguageConversion {\n\n\tclass Solution {\n\n\t\tpublic static int[] sortArray(int[] nums) {\n\t\t\tif (nums.length > 1) {\n\t\t\t\tmergeSort(nums);\n\t\t\t}\n\t\t\treturn nums;\n\t\t}\n\n\t\tpublic static int MAXN = 50001;\n\n\t\t// 以下是归并排序\n\t\tpublic static int[] help = new int[MAXN];\n\n\t\tpublic static void mergeSort(int[] arr) {\n\t\t\tint n = arr.length;\n\t\t\tfor (int l, m, r, step = 1; step < n; step <<= 1) {\n\t\t\t\tl = 0;\n\t\t\t\twhile (l < n) {\n\t\t\t\t\tm = l + step - 1;\n\t\t\t\t\tif (m + 1 >= n) {\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t\tr = Math.min(l + (step << 1) - 1, n - 1);\n\t\t\t\t\tmerge(arr, l, m, r);\n\t\t\t\t\tl = r + 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic static void merge(int[] nums, int l, int m, int r) {\n\t\t\tint p1 = l;\n\t\t\tint p2 = m + 1;\n\t\t\tint i = l;\n\t\t\twhile (p1 <= m && p2 <= r) {\n\t\t\t\thelp[i++] = nums[p1] <= nums[p2] ? nums[p1++] : nums[p2++];\n\t\t\t}\n\t\t\twhile (p1 <= m) {\n\t\t\t\thelp[i++] = nums[p1++];\n\t\t\t}\n\t\t\twhile (p2 <= r) {\n\t\t\t\thelp[i++] = nums[p2++];\n\t\t\t}\n\t\t\tfor (i = l; i <= r; i++) {\n\t\t\t\tnums[i] = help[i];\n\t\t\t}\n\t\t}\n\n\t\t// 以下是随机快速排序\n\t\tpublic static void quickSort(int[] arr) {\n\t\t\tsort(arr, 0, arr.length - 1);\n\t\t}\n\n\t\tpublic static void sort(int[] arr, int l, int r) {\n\t\t\tif (l >= r) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\t// 随机这一下，常数时间比较大\n\t\t\t// 但只有这一下随机，才能在概率上把快速排序的时间复杂度收敛到O(n * logn)\n\t\t\tint x = arr[l + (int) (Math.random() * (r - l + 1))];\n\t\t\tpartition(arr, l, r, x);\n\t\t\tint left = first;\n\t\t\tint right = last;\n\t\t\tsort(arr, l, left - 1);\n\t\t\tsort(arr, right + 1, r);\n\t\t}\n\n\t\tpublic static int first, last;\n\n\t\tpublic static void partition(int[] nums, int l, int r, int x) {\n\t\t\tfirst = l;\n\t\t\tlast = r;\n\t\t\tint i = l;\n\t\t\twhile (i <= last) {\n\t\t\t\tif (nums[i] == x) {\n\t\t\t\t\ti++;\n\t\t\t\t} else if (nums[i] < x) {\n\t\t\t\t\tswap(nums, first++, i++);\n\t\t\t\t} else {\n\t\t\t\t\tswap(nums, i, last--);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic static void swap(int[] arr, int i, int j) {\n\t\t\tint tmp = arr[i];\n\t\t\tarr[i] = arr[j];\n\t\t\tarr[j] = tmp;\n\t\t}\n\n\t\t// 以下是堆排序\n\t\tpublic static void heapSort(int[] nums) {\n\t\t\tint n = nums.length;\n\t\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\t\theapify(nums, i, n);\n\t\t\t}\n\t\t\twhile (n > 1) {\n\t\t\t\tswap(nums, 0, --n);\n\t\t\t\theapify(nums, 0, n);\n\t\t\t}\n\t\t}\n\n\t\t// 这个方法虽然堆排序用不上，但是堆结构里是重要方法，所以这里保留\n\t\t// 后面的课会讲\n\t\tpublic static void heapInsert(int[] nums, int i) {\n\t\t\twhile (nums[i] > nums[(i - 1) / 2]) {\n\t\t\t\tswap(nums, i, (i - 1) / 2);\n\t\t\t\ti = (i - 1) / 2;\n\t\t\t}\n\t\t}\n\n\t\tpublic static void heapify(int[] nums, int i, int s) {\n\t\t\tint l = i * 2 + 1;\n\t\t\twhile (l < s) {\n\t\t\t\tint best = l + 1 < s && nums[l + 1] > nums[l] ? l + 1 : l;\n\t\t\t\tbest = nums[best] > nums[i] ? best : i;\n\t\t\t\tif (best == i) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tswap(nums, best, i);\n\t\t\t\ti = best;\n\t\t\t\tl = i * 2 + 1;\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n	模板：LanguageConversion.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4388bad7-6116-41dc-b83b-a18633f01db8	d1b94a5f-c216-4bd1-83ea-2beceb128568	java	package class002;\n\nimport java.util.Arrays;\n\n// 一开始有100个人，每个人都有100元\n// 在每一轮都做如下的事情 : \n// 每个人都必须拿出1元钱给除自己以外的其他人，给谁完全随机\n// 如果某个人在这一轮的钱数为0，那么他可以不给，但是可以接收\n// 发生很多很多轮之后，这100人的社会财富分布很均匀吗？\npublic class Experiment {\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("一个社会的基尼系数是一个在0~1之间的小数");\n\t\tSystem.out.println("基尼系数为0代表所有人的财富完全一样");\n\t\tSystem.out.println("基尼系数为1代表有1个人掌握了全社会的财富");\n\t\tSystem.out.println("基尼系数越小，代表社会财富分布越均衡；越大则代表财富分布越不均衡");\n\t\tSystem.out.println("在2022年，世界各国的平均基尼系数为0.44");\n\t\tSystem.out.println("目前普遍认为，当基尼系数到达 0.5 时");\n\t\tSystem.out.println("就意味着社会贫富差距非常大，分布非常不均匀");\n\t\tSystem.out.println("社会可能会因此陷入危机，比如大量的犯罪或者经历社会动荡");\n\t\tSystem.out.println("测试开始");\n\t\tint n = 100;\n\t\tint t = 1000000;\n\t\tSystem.out.println("人数 : " + n);\n\t\tSystem.out.println("轮数 : " + t);\n\t\texperiment(n, t);\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 完全按照说的来实验\n\tpublic static void experiment(int n, int t) {\n\t\tdouble[] wealth = new double[n];\n\t\tArrays.fill(wealth, 100);\n\t\tboolean[] hasMoney = new boolean[n];\n\t\tfor (int i = 0; i < t; i++) {\n\t\t\tArrays.fill(hasMoney, false);\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\tif (wealth[j] > 0) {\n\t\t\t\t\thasMoney[j] = true;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\tif (hasMoney[j]) {\n\t\t\t\t\tint other = j;\n\t\t\t\t\tdo {\n\t\t\t\t\t\t// (int) (Math.random() * n);\n\t\t\t\t\t\t// int : 0 ~ n-1，等概率随机\n\t\t\t\t\t\tother = (int) (Math.random() * n);\n\t\t\t\t\t} while (other == j);\n\t\t\t\t\twealth[j]--;\n\t\t\t\t\twealth[other]++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tArrays.sort(wealth);\n\t\tSystem.out.println("列出每个人的财富(贫穷到富有) : ");\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tSystem.out.print((int) wealth[i] + " ");\n\t\t\tif (i % 10 == 9) {\n\t\t\t\tSystem.out.println();\n\t\t\t}\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("这个社会的基尼系数为 : " + calculateGini(wealth));\n\t}\n\n\t// 计算基尼系数\n\t// 看代码就可以轻易知道怎么算的\n\tpublic static double calculateGini(double[] wealth) {\n\t\tdouble sumOfAbsoluteDifferences = 0;\n\t\tdouble sumOfWealth = 0;\n\t\tint n = wealth.length;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tsumOfWealth += wealth[i];\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\tsumOfAbsoluteDifferences += Math.abs(wealth[i] - wealth[j]);\n\t\t\t}\n\t\t}\n\t\treturn sumOfAbsoluteDifferences / (2 * n * sumOfWealth);\n\t}\n\n}	模板：Experiment.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6e49a131-4ec4-4640-9cc0-9a2e8e066bc0	6a9970d2-0a62-4a31-8362-470e716f7b4e	java	package class003;\n\n// 本文件的实现是用int来举例的\n// 对于long类型完全同理\n// 不过要注意，如果是long类型的数字num，有64位\n// num & (1 << 48)，这种写法不对\n// 因为1是一个int类型，只有32位，所以(1 << 48)早就溢出了，所以无意义\n// 应该写成 : num & (1L << 48)\npublic class BinarySystem {\n\n\t// 打印一个int类型的数字，32位进制的状态\n\t// 左侧是高位，右侧是低位\n\tpublic static void printBinary(int num) {\n\t\tfor (int i = 31; i >= 0; i--) {\n\t\t\t// 下面这句写法，可以改成 :\n\t\t\t// System.out.print((a & (1 << i)) != 0 ? "1" : "0");\n\t\t\t// 但不可以改成 :\n\t\t\t// System.out.print((a & (1 << i)) == 1 ? "1" : "0");\n\t\t\t// 因为a如果第i位有1，那么(a & (1 << i))是2的i次方，而不一定是1\n\t\t\t// 比如，a = 0010011\n\t\t\t// a的第0位是1，第1位是1，第4位是1\n\t\t\t// (a & (1<<4)) == 16（不是1），说明a的第4位是1状态\n\t\t\tSystem.out.print((num & (1 << i)) == 0 ? "0" : "1");\n\t\t}\n\t\tSystem.out.println();\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 非负数\n\t\tint a = 78;\n\t\tSystem.out.println(a);\n\t\tprintBinary(a);\n\t\tSystem.out.println("===a===");\n\t\t// 负数\n\t\tint b = -6;\n\t\tSystem.out.println(b);\n\t\tprintBinary(b);\n\t\tSystem.out.println("===b===");\n\t\t// 直接写二进制的形式定义变量\n\t\tint c = 0b1001110;\n\t\tSystem.out.println(c);\n\t\tprintBinary(c);\n\t\tSystem.out.println("===c===");\n\t\t// 直接写十六进制的形式定义变量\n\t\t// 0100 -> 4\n\t\t// 1110 -> e\n\t\t// 0x4e -> 01001110\n\t\tint d = 0x4e;\n\t\tSystem.out.println(d);\n\t\tprintBinary(d);\n\t\tSystem.out.println("===d===");\n\t\t// ~、相反数\n\t\tSystem.out.println(a);\n\t\tprintBinary(a);\n\t\tprintBinary(~a);\n\t\tint e = ~a + 1;\n\t\tSystem.out.println(e);\n\t\tprintBinary(e);\n\t\tSystem.out.println("===e===");\n\t\t// int、long的最小值，取相反数、绝对值，都是自己\n\t\tint f = Integer.MIN_VALUE;\n\t\tSystem.out.println(f);\n\t\tprintBinary(f);\n\t\tSystem.out.println(-f);\n\t\tprintBinary(-f);\n\t\tSystem.out.println(~f + 1);\n\t\tprintBinary(~f + 1);\n\t\tSystem.out.println("===f===");\n\t\t// | & ^\n\t\tint g = 0b0001010;\n\t\tint h = 0b0001100;\n\t\tprintBinary(g | h);\n\t\tprintBinary(g & h);\n\t\tprintBinary(g ^ h);\n\t\tSystem.out.println("===g、h===");\n\t\t// 可以这么写 : int num = 3231 | 6434;\n\t\t// 可以这么写 : int num = 3231 & 6434;\n\t\t// 不能这么写 : int num = 3231 || 6434;\n\t\t// 不能这么写 : int num = 3231 && 6434;\n\t\t// 因为 ||、&& 是 逻辑或、逻辑与，只能连接boolean类型\n\t\t// 不仅如此，|、& 连接的两侧一定都会计算\n\t\t// 而 ||、&& 有穿透性的特点\n\t\tSystem.out.println("test1测试开始");\n\t\tboolean test1 = returnTrue() | returnFalse();\n\t\tSystem.out.println("test1结果，" + test1);\n\t\tSystem.out.println("test2测试开始");\n\t\tboolean test2 = returnTrue() || returnFalse();\n\t\tSystem.out.println("test2结果，" + test2);\n\t\tSystem.out.println("test3测试开始");\n\t\tboolean test3 = returnFalse() & returnTrue();\n\t\tSystem.out.println("test3结果，" + test3);\n\t\tSystem.out.println("test4测试开始");\n\t\tboolean test4 = returnFalse() && returnTrue();\n\t\tSystem.out.println("test4结果，" + test4);\n\t\tSystem.out.println("===|、&、||、&&===");\n\t\t// <<\n\t\tint i = 0b0011010;\n\t\tprintBinary(i);\n\t\tprintBinary(i << 1);\n\t\tprintBinary(i << 2);\n\t\tprintBinary(i << 3);\n\t\tSystem.out.println("===i << ===");\n\t\t// 非负数 >> >>>，效果一样\n\t\tprintBinary(i);\n\t\tprintBinary(i >> 2);\n\t\tprintBinary(i >>> 2);\n\t\tSystem.out.println("===i >> >>>===");\n\t\t// 负数 >> >>>，效果不一样\n\t\tint j = 0b11110000000000000000000000000000;\n\t\tprintBinary(j);\n\t\tprintBinary(j >> 2);\n\t\tprintBinary(j >>> 2);\n\t\tSystem.out.println("===j >> >>>===");\n\t\t// 非负数 << 1，等同于乘以2\n\t\t// 非负数 << 2，等同于乘以4\n\t\t// 非负数 << 3，等同于乘以8\n\t\t// 非负数 << i，等同于乘以2的i次方\n\t\t// ...\n\t\t// 非负数 >> 1，等同于除以2\n\t\t// 非负数 >> 2，等同于除以4\n\t\t// 非负数 >> 3，等同于除以8\n\t\t// 非负数 >> i，等同于除以2的i次方\n\t\t// 只有非负数符合这个特征，负数不要用\n\t\tint k = 10;\n\t\tSystem.out.println(k);\n\t\tSystem.out.println(k << 1);\n\t\tSystem.out.println(k << 2);\n\t\tSystem.out.println(k << 3);\n\t\tSystem.out.println(k >> 1);\n\t\tSystem.out.println(k >> 2);\n\t\tSystem.out.println(k >> 3);\n\t\tSystem.out.println("===k===");\n\t}\n\n\tpublic static boolean returnTrue() {\n\t\tSystem.out.println("进入了returnTrue函数");\n\t\treturn true;\n\t}\n\n\tpublic static boolean returnFalse() {\n\t\tSystem.out.println("进入了returnFalse函数");\n\t\treturn false;\n\t}\n\n}	模板：BinarySystem.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9cffcd1a-c8b6-4cdf-a1a4-7c0addbc8a53	ea629300-702f-4c47-86a4-a644b2c049cc	java	package class005;\n\npublic class Validator {\n\n\t// 为了验证\n\tpublic static void main(String[] args) {\n\t\t// 随机数组最大长度\n\t\tint N = 200;\n\t\t// 随机数组每个值，在1~V之间等概率随机\n\t\tint V = 1000;\n\t\t// testTimes : 测试次数\n\t\tint testTimes = 50000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 0; i < testTimes; i++) {\n\t\t\t// 随机得到一个长度，长度在[0~N-1]\n\t\t\tint n = (int) (Math.random() * N);\n\t\t\t// 得到随机数组\n\t\t\tint[] arr = randomArray(n, V);\n\t\t\tint[] arr1 = copyArray(arr);\n\t\t\tint[] arr2 = copyArray(arr);\n\t\t\tint[] arr3 = copyArray(arr);\n\t\t\tselectionSort(arr1);\n\t\t\tbubbleSort(arr2);\n\t\t\tinsertionSort(arr3);\n\t\t\tif (!sameArray(arr1, arr2) || !sameArray(arr1, arr3)) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t// 当有错了\n\t\t\t\t// 打印是什么例子，出错的\n\t\t\t\t// 打印三个功能，各自排序成了什么样\n\t\t\t\t// 可能要把例子带入，每个方法，去debug！\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n\t// 为了验证\n\t// 得到一个随机数组，长度是n\n\t// 数组中每个数，都在1~v之间，随机得到\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] arr = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// Math.random() -> double -> [0,1)范围山的一个小数，0.37463473126、0.001231231，等概率！\n\t\t\t// Math.random() * v -> double -> [0,v)一个小数，依然等概率\n\t\t\t// (int)(Math.random() * v) -> int -> 0 1 2 3 ... v-1，等概率的！\n\t\t\t// (int) (Math.random() * v) + 1 -> int -> 1 2 3 .... v，等概率的！\n\t\t\tarr[i] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\treturn arr;\n\t}\n\n\t// 为了验证\n\tpublic static int[] copyArray(int[] arr) {\n\t\tint n = arr.length;\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = arr[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了验证\n\tpublic static boolean sameArray(int[] arr1, int[] arr2) {\n\t\tint n = arr1.length;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tif (arr1[i] != arr2[i]) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\t// 数组中交换i和j位置的数\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\t// 选择排序\n\tpublic static void selectionSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int minIndex, i = 0; i < arr.length - 1; i++) {\n\t\t\tminIndex = i;\n\t\t\tfor (int j = i + 1; j < arr.length; j++) {\n\t\t\t\tif (arr[j] < arr[minIndex]) {\n\t\t\t\t\tminIndex = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tswap(arr, i, minIndex);\n\t\t}\n\t}\n\n\t// 冒泡排序\n\tpublic static void bubbleSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int end = arr.length - 1; end > 0; end--) {\n\t\t\tfor (int i = 0; i < end; i++) {\n\t\t\t\tif (arr[i] > arr[i + 1]) {\n\t\t\t\t\tswap(arr, i, i + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 插入排序\n\tpublic static void insertionSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int i = 1; i < arr.length; i++) {\n\t\t\tfor (int j = i - 1; j >= 0 && arr[j] > arr[j + 1]; j--) {\n\t\t\t\tswap(arr, j, j + 1);\n\t\t\t}\n\t\t}\n\t}\n\n}	模板：Validator.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f7a15bdc-4fd7-4809-84bf-602b23cf453c	dbfd74b1-a3d9-41bc-b918-acc12e3c2613	java	package class007;\n\nimport java.util.ArrayList;\n\npublic class Complexity {\n\n\t// 只用一个循环完成冒泡排序\n\t// 但这是时间复杂度O(N^2)的！\n\tpublic static void bubbleSort(int[] arr) {\n\t\tif (arr == null || arr.length < 2) {\n\t\t\treturn;\n\t\t}\n\t\tint n = arr.length;\n\t\tint end = n - 1, i = 0;\n\t\twhile (end > 0) {\n\t\t\tif (arr[i] > arr[i + 1]) {\n\t\t\t\tswap(arr, i, i + 1);\n\t\t\t}\n\t\t\tif (i < end - 1) {\n\t\t\t\ti++;\n\t\t\t} else {\n\t\t\t\tend--;\n\t\t\t\ti = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\t// 随机生成长度为n\n\t\t// 值在0~v-1之间\n\t\t// 且任意相邻两数不相等的数组\n\t\tint n = 10;\n\t\tint v = 4;\n\t\tint[] arr1 = new int[n];\n\t\tarr1[0] = (int) (Math.random() * v);\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tdo {\n\t\t\t\tarr1[i] = (int) (Math.random() * v);\n\t\t\t} while (arr1[i] == arr1[i - 1]);\n\t\t}\n\t\tfor (int num : arr1) {\n\t\t\tSystem.out.print(num + " ");\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("=========");\n\n\t\t// java中的动态数组是ArrayList\n\t\t// 各个语言中的动态数组的初始大小和实际扩容因子可能会变化，但是均摊都是O(1)\n\t\t// 课上用2作为扩容因子只是举例而已\n\t\tArrayList<Integer> arr2 = new ArrayList<>();\n\t\tarr2.add(5); // 0\n\t\tarr2.add(4); // 1\n\t\tarr2.add(9); // 2\n\t\tarr2.set(1, 6); // arr[1]由4改成了6\n\t\tSystem.out.println(arr2.get(1));\n\t\tSystem.out.println("=========");\n\n\t\tint[] arr = { 64, 31, 78, 0, 5, 7, 103 };\n\t\tbubbleSort(arr);\n\t\tfor (int num : arr) {\n\t\t\tSystem.out.print(num + " ");\n\t\t}\n\t\tSystem.out.println();\n\t\tSystem.out.println("=========");\n\n\t\tint N = 200000;\n\t\tlong start;\n\t\tlong end;\n\t\tSystem.out.println("测试开始");\n\t\tstart = System.currentTimeMillis();\n\t\tfor (int i = 1; i <= N; i++) {\n\t\t\tfor (int j = i; j <= N; j += i) {\n\t\t\t\t// 这两个嵌套for循环的流程，时间复杂度为O(N * logN)\n\t\t\t\t// 1/1 + 1/2 + 1/3 + 1/4 + 1/5 + ... + 1/n，也叫"调和级数"，收敛于O(logN)\n\t\t\t\t// 所以如果一个流程的表达式 : n/1 + n/2 + n/3 + ... + n/n\n\t\t\t\t// 那么这个流程时间复杂度O(N * logN)\n\t\t\t}\n\t\t}\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("测试结束，运行时间 : " + (end - start) + " 毫秒");\n\n\t\tSystem.out.println("测试开始");\n\t\tstart = System.currentTimeMillis();\n\t\tfor (int i = 1; i <= N; i++) {\n\t\t\tfor (int j = i; j <= N; j++) {\n\t\t\t\t// 这两个嵌套for循环的流程，时间复杂度为O(N^2)\n\t\t\t\t// 很明显等差数列\n\t\t\t}\n\t\t}\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("测试结束，运行时间 : " + (end - start) + " 毫秒");\n\n\t}\n\n}\n	模板：Complexity.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
08fad5b6-b0f1-4aed-b86a-e6931d1f8949	87a80abb-7653-43cb-98c7-8940af59b8ca	java	package class009;\n\n// 按值传递、按引用传递\n// 从堆栈角度解释链表节点\n// 以堆栈视角来看链表反转\npublic class ListReverse {\n\n\tpublic static void main(String[] args) {\n\t\t// int、long、byte、short\n\t\t// char、float、double、boolean\n\t\t// 还有String\n\t\t// 都是按值传递\n\t\tint a = 10;\n\t\tf(a);\n\t\tSystem.out.println(a);\n\n\t\t// 其他类型按引用传递\n\t\t// 比如下面的Number是自定义的类\n\t\tNumber b = new Number(5);\n\t\tg1(b);\n\t\tSystem.out.println(b.val);\n\t\tg2(b);\n\t\tSystem.out.println(b.val);\n\n\t\t// 比如下面的一维数组\n\t\tint[] c = { 1, 2, 3, 4 };\n\t\tg3(c);\n\t\tSystem.out.println(c[0]);\n\t\tg4(c);\n\t\tSystem.out.println(c[0]);\n\t}\n\n\tpublic static void f(int a) {\n\t\ta = 0;\n\t}\n\n\tpublic static class Number {\n\t\tpublic int val;\n\n\t\tpublic Number(int v) {\n\t\t\tval = v;\n\t\t}\n\t}\n\n\tpublic static void g1(Number b) {\n\t\tb = null;\n\t}\n\n\tpublic static void g2(Number b) {\n\t\tb.val = 6;\n\t}\n\n\tpublic static void g3(int[] c) {\n\t\tc = null;\n\t}\n\n\tpublic static void g4(int[] c) {\n\t\tc[0] = 100;\n\t}\n\n\t// 单链表节点\n\tpublic static class ListNode {\n\t\tpublic int val;\n\t\tpublic ListNode next;\n\n\t\tpublic ListNode(int val) {\n\t\t\tthis.val = val;\n\t\t}\n\n\t\tpublic ListNode(int val, ListNode next) {\n\t\t\tthis.val = val;\n\t\t\tthis.next = next;\n\t\t}\n\t}\n\n\t// 反转单链表测试链接 : https://leetcode.cn/problems/reverse-linked-list/\n\tclass Solution {\n\n\t\tpublic static ListNode reverseList(ListNode head) {\n\t\t\tListNode pre = null;\n\t\t\tListNode next = null;\n\t\t\twhile (head != null) {\n\t\t\t\tnext = head.next;\n\t\t\t\thead.next = pre;\n\t\t\t\tpre = head;\n\t\t\t\thead = next;\n\t\t\t}\n\t\t\treturn pre;\n\t\t}\n\n\t}\n\n\t// 双链表节点\n\tpublic static class DoubleListNode {\n\t\tpublic int value;\n\t\tpublic DoubleListNode last;\n\t\tpublic DoubleListNode next;\n\n\t\tpublic DoubleListNode(int v) {\n\t\t\tvalue = v;\n\t\t}\n\t}\n\n\t// 反转双链表\n\t// 没有找到测试链接\n\t// 如下方法是对的\n\tpublic static DoubleListNode reverseDoubleList(DoubleListNode head) {\n\t\tDoubleListNode pre = null;\n\t\tDoubleListNode next = null;\n\t\twhile (head != null) {\n\t\t\tnext = head.next;\n\t\t\thead.next = pre;\n\t\t\thead.last = next;\n\t\t\tpre = head;\n\t\t\thead = next;\n\t\t}\n\t\treturn pre;\n\t}\n\n}\n	模板：ListReverse.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8e4496a4-e9a2-4848-9fa2-43111ea1d045	27905478-bb88-48ec-b75a-738722da89d8	java	package class011;\n\n// 给你两个 非空 的链表，表示两个非负的整数\n// 它们每位数字都是按照 逆序 的方式存储的，并且每个节点只能存储 一位 数字\n// 请你将两个数相加，并以相同形式返回一个表示和的链表。\n// 你可以假设除了数字 0 之外，这两个数都不会以 0 开头\n// 测试链接：https://leetcode.cn/problems/add-two-numbers/\npublic class AddTwoNumbers {\n\n\t// 不要提交这个类\n\tpublic static class ListNode {\n\t\tpublic int val;\n\t\tpublic ListNode next;\n\n\t\tpublic ListNode(int val) {\n\t\t\tthis.val = val;\n\t\t}\n\n\t\tpublic ListNode(int val, ListNode next) {\n\t\t\tthis.val = val;\n\t\t\tthis.next = next;\n\t\t}\n\t}\n\n\tclass Solution {\n\n\t\t// 也可以复用老链表\n\t\t// 不过这个实现没有这么做，都是生成的新节点(为了教学好懂)\n\t\tpublic static ListNode addTwoNumbers(ListNode h1, ListNode h2) {\n\t\t\tListNode ans = null, cur = null;\n\t\t\tint carry = 0;\n\t\t\tfor (int sum, val; // 声明变量\n\t\t\t\t\th1 != null || h2 != null; // 终止条件\n\t\t\t\t\th1 = h1 == null ? null : h1.next, // 每一步h1的跳转\n\t\t\t\t\th2 = h2 == null ? null : h2.next // 每一步h2的跳转\n\t\t\t\t\t) {\n\n\t\t\t\tsum = (h1 == null ? 0 : h1.val)\n\t\t\t\t\t\t+ (h2 == null ? 0 : h2.val)\n\t\t\t\t\t\t+ carry;\n\n\t\t\t\tval = sum % 10;\n\t\t\t\tcarry = sum / 10;\n\t\t\t\tif (ans == null) {\n\t\t\t\t\tans = new ListNode(val);\n\t\t\t\t\tcur = ans;\n\t\t\t\t} else {\n\t\t\t\t\tcur.next = new ListNode(val);\n\t\t\t\t\tcur = cur.next;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (carry == 1) {\n\t\t\t\tcur.next = new ListNode(1);\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t}\n\n}\n	模板：AddTwoNumbers.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3b9b24e4-4282-478b-897e-74defbe75973	36813089-90c0-4468-b9ef-506dce3ac8e1	java	package class012;\n\n// 给你一个链表的头节点 head 和一个特定值 x\n// 请你对链表进行分隔，使得所有 小于 x 的节点都出现在 大于或等于 x 的节点之前。\n// 你应当 保留 两个分区中每个节点的初始相对位置\n// 测试链接 : https://leetcode.cn/problems/partition-list/\npublic class PartitionList {\n\n\t// 不要提交这个类\n\tpublic static class ListNode {\n\t\tpublic int val;\n\t\tpublic ListNode next;\n\n\t\tpublic ListNode(int val) {\n\t\t\tthis.val = val;\n\t\t}\n\n\t\tpublic ListNode(int val, ListNode next) {\n\t\t\tthis.val = val;\n\t\t\tthis.next = next;\n\t\t}\n\t}\n\n\tclass Solution {\n\n\t\tpublic static ListNode partition(ListNode head, int x) {\n\t\t\tListNode leftHead = null, leftTail = null; // < x的区域\n\t\t\tListNode rightHead = null, rightTail = null; // >=x的区域\n\t\t\tListNode next = null;\n\t\t\twhile (head != null) {\n\t\t\t\tnext = head.next;\n\t\t\t\thead.next = null;\n\t\t\t\tif (head.val < x) {\n\t\t\t\t\tif (leftHead == null) {\n\t\t\t\t\t\tleftHead = head;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tleftTail.next = head;\n\t\t\t\t\t}\n\t\t\t\t\tleftTail = head;\n\t\t\t\t} else {\n\t\t\t\t\tif (rightHead == null) {\n\t\t\t\t\t\trightHead = head;\n\t\t\t\t\t} else {\n\t\t\t\t\t\trightTail.next = head;\n\t\t\t\t\t}\n\t\t\t\t\trightTail = head;\n\t\t\t\t}\n\t\t\t\thead = next;\n\t\t\t}\n\t\t\tif (leftHead == null) {\n\t\t\t\treturn rightHead;\n\t\t\t}\n\t\t\t// < x的区域有内容！\n\t\t\tleftTail.next = rightHead;\n\t\t\treturn leftHead;\n\t\t}\n\n\t}\n\n}\n	模板：PartitionList.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f8ac3fe8-6904-418f-8c53-bc30ea32deb3	d72d17b4-2ffb-4f9d-a0be-b08c1edebc9c	java	package class013;\n\nimport java.util.Queue;\nimport java.util.LinkedList;\nimport java.util.Stack;\n\npublic class QueueStackAndCircularQueue {\n\n\t// 直接用java内部的实现\n\t// 其实内部就是双向链表，常数操作慢\n\tpublic static class Queue1 {\n\n\t\t// java中的双向链表LinkedList\n\t\t// 单向链表就足够了\n\t\tpublic Queue<Integer> queue = new LinkedList<>();\n\n\t\t// 调用任何方法之前，先调用这个方法来判断队列内是否有东西\n\t\tpublic boolean isEmpty() {\n\t\t\treturn queue.isEmpty();\n\t\t}\n\n\t\t// 向队列中加入num，加到尾巴\n\t\tpublic void offer(int num) {\n\t\t\tqueue.offer(num);\n\t\t}\n\n\t\t// 从队列拿，从头拿\n\t\tpublic int poll() {\n\t\t\treturn queue.poll();\n\t\t}\n\n\t\t// 返回队列头的元素但是不弹出\n\t\tpublic int peek() {\n\t\t\treturn queue.peek();\n\t\t}\n\n\t\t// 返回目前队列里有几个数\n\t\tpublic int size() {\n\t\t\treturn queue.size();\n\t\t}\n\n\t}\n\n\t// 实际刷题时更常见的写法，常数时间好\n\t// 如果可以确定加入操作的总次数不超过n，那么可以用\n\t// 一般笔试、面试都会有一个明确数据量，所以这是最常用的方式\n\tpublic static class Queue2 {\n\n\t\tpublic int[] queue;\n\t\tpublic int l;\n\t\tpublic int r;\n\n\t\t// 加入操作的总次数上限是多少，一定要明确\n\t\tpublic Queue2(int n) {\n\t\t\tqueue = new int[n];\n\t\t\tl = 0;\n\t\t\tr = 0;\n\t\t}\n\n\t\t// 调用任何方法之前，先调用这个方法来判断队列内是否有东西\n\t\tpublic boolean isEmpty() {\n\t\t\treturn l == r;\n\t\t}\n\n\t\tpublic void offer(int num) {\n\t\t\tqueue[r++] = num;\n\t\t}\n\n\t\tpublic int poll() {\n\t\t\treturn queue[l++];\n\t\t}\n\t\t// ?\n\t\t// l...r-1 r\n\t\t// [l..r)\n\t\tpublic int head() {\n\t\t\treturn queue[l];\n\t\t}\n\n\t\tpublic int tail() {\n\t\t\treturn queue[r - 1];\n\t\t}\n\n\t\tpublic int size() {\n\t\t\treturn r - l;\n\t\t}\n\n\t}\n\n\t// 直接用java内部的实现\n\t// 其实就是动态数组，不过常数时间并不好\n\tpublic static class Stack1 {\n\n\t\tpublic Stack<Integer> stack = new Stack<>();\n\n\t\t// 调用任何方法之前，先调用这个方法来判断栈内是否有东西\n\t\tpublic boolean isEmpty() {\n\t\t\treturn stack.isEmpty();\n\t\t}\n\n\t\tpublic void push(int num) {\n\t\t\tstack.push(num);\n\t\t}\n\n\t\tpublic int pop() {\n\t\t\treturn stack.pop();\n\t\t}\n\n\t\tpublic int peek() {\n\t\t\treturn stack.peek();\n\t\t}\n\n\t\tpublic int size() {\n\t\t\treturn stack.size();\n\t\t}\n\n\t}\n\n\t// 实际刷题时更常见的写法，常数时间好\n\t// 如果可以保证同时在栈里的元素个数不会超过n，那么可以用\n\t// 也就是发生弹出操作之后，空间可以复用\n\t// 一般笔试、面试都会有一个明确数据量，所以这是最常用的方式\n\tpublic static class Stack2 {\n\n\t\tpublic int[] stack;\n\t\tpublic int size;\n\n\t\t// 同时在栈里的元素个数不会超过n\n\t\tpublic Stack2(int n) {\n\t\t\tstack = new int[n];\n\t\t\tsize = 0;\n\t\t}\n\n\t\t// 调用任何方法之前，先调用这个方法来判断栈内是否有东西\n\t\tpublic boolean isEmpty() {\n\t\t\treturn size == 0;\n\t\t}\n\n\t\tpublic void push(int num) {\n\t\t\tstack[size++] = num;\n\t\t}\n\n\t\tpublic int pop() {\n\t\t\treturn stack[--size];\n\t\t}\n\n\t\tpublic int peek() {\n\t\t\treturn stack[size - 1];\n\t\t}\n\n\t\tpublic int size() {\n\t\t\treturn size;\n\t\t}\n\n\t}\n\n\t// 设计循环队列\n\t// 测试链接 : https://leetcode.cn/problems/design-circular-queue/\n\tclass MyCircularQueue {\n\n\t\tpublic int[] queue;\n\n\t\tpublic int l, r, size, limit;\n\n\t\t// 同时在队列里的数字个数，不要超过k\n\t\tpublic MyCircularQueue(int k) {\n\t\t\tqueue = new int[k];\n\t\t\tl = r = size = 0;\n\t\t\tlimit = k;\n\t\t}\n\n\t\t// 如果队列满了，什么也不做，返回false\n\t\t// 如果队列没满，加入value，返回true\n\t\tpublic boolean enQueue(int value) {\n\t\t\tif (isFull()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tqueue[r] = value;\n\t\t\t\t// r++, 结束了，跳回0\n\t\t\t\tr = r == limit - 1 ? 0 : (r + 1);\n\t\t\t\tsize++;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\t// 如果队列空了，什么也不做，返回false\n\t\t// 如果队列没空，弹出头部的数字，返回true\n\t\tpublic boolean deQueue() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\t// l++, 结束了，跳回0\n\t\t\t\tl = l == limit - 1 ? 0 : (l + 1);\n\t\t\t\tsize--;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\t// 返回队列头部的数字（不弹出），如果没有数返回-1\n\t\tpublic int Front() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn queue[l];\n\t\t\t}\n\t\t}\n\n\t\tpublic int Rear() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\tint last = r == 0 ? (limit - 1) : (r - 1);\n\t\t\t\treturn queue[last];\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean isEmpty() {\n\t\t\treturn size == 0;\n\t\t}\n\n\t\tpublic boolean isFull() {\n\t\t\treturn size == limit;\n\t\t}\n\n\t}\n\n}\n	模板：QueueStackAndCircularQueue.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cfaa101f-24f9-49f3-af31-18eb9d52bc27	f4aed713-ace9-4a78-afa8-7f73e6af0501	java	package class014;\n\nimport java.util.LinkedList;\nimport java.util.Queue;\nimport java.util.Stack;\n\n// 用栈实现队列\n// 用队列实现栈\npublic class ConvertQueueAndStack {\n\n\t// 测试链接 : https://leetcode.cn/problems/implement-queue-using-stacks/\n\tclass MyQueue {\n\n\t\tpublic Stack<Integer> in;\n\n\t\tpublic Stack<Integer> out;\n\n\t\tpublic MyQueue() {\n\t\t\tin = new Stack<Integer>();\n\t\t\tout = new Stack<Integer>();\n\t\t}\n\n\t\t// 倒数据\n\t\t// 从in栈，把数据倒入out栈\n\t\t// 1) out空了，才能倒数据\n\t\t// 2) 如果倒数据，in必须倒完\n\t\tprivate void inToOut() {\n\t\t\tif (out.empty()) {\n\t\t\t\twhile (!in.empty()) {\n\t\t\t\t\tout.push(in.pop());\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tpublic void push(int x) {\n\t\t\tin.push(x);\n\t\t\tinToOut();\n\t\t}\n\n\t\tpublic int pop() {\n\t\t\tinToOut();\n\t\t\treturn out.pop();\n\t\t}\n\n\t\tpublic int peek() {\n\t\t\tinToOut();\n\t\t\treturn out.peek();\n\t\t}\n\n\t\tpublic boolean empty() {\n\t\t\treturn in.isEmpty() && out.isEmpty();\n\t\t}\n\n\t}\n\n\t// 测试链接 : https://leetcode.cn/problems/implement-stack-using-queues/\n\tclass MyStack {\n\n\t\tQueue<Integer> queue;\n\n\t\tpublic MyStack() {\n\t\t\tqueue = new LinkedList<Integer>();\n\t\t}\n\n\t\t// O(n)\n\t\tpublic void push(int x) {\n\t\t\tint n = queue.size();\n\t\t\tqueue.offer(x);\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tqueue.offer(queue.poll());\n\t\t\t}\n\t\t}\n\n\t\tpublic int pop() {\n\t\t\treturn queue.poll();\n\t\t}\n\n\t\tpublic int top() {\n\t\t\treturn queue.peek();\n\t\t}\n\n\t\tpublic boolean empty() {\n\t\t\treturn queue.isEmpty();\n\t\t}\n\n\t}\n\n}\n	模板：ConvertQueueAndStack.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bcf9fa6f-fff8-4a10-ba25-086555bd455f	fa8b3b9f-2d1f-46e9-8c02-d6f5c214e78d	java	package class024;\n\n// 无序数组中第K大的元素\n// 测试链接 : https://leetcode.cn/problems/kth-largest-element-in-an-array/\npublic class RandomizedSelect {\n\n\t// 随机选择算法，时间复杂度O(n)\n\tpublic static int findKthLargest(int[] nums, int k) {\n\t\treturn randomizedSelect(nums, nums.length - k);\n\t}\n\n\t// 如果arr排序的话，在i位置的数字是什么\n\tpublic static int randomizedSelect(int[] arr, int i) {\n\t\tint ans = 0;\n\t\tfor (int l = 0, r = arr.length - 1; l <= r;) {\n\t\t\t// 随机这一下，常数时间比较大\n\t\t\t// 但只有这一下随机，才能在概率上把时间复杂度收敛到O(n)\n\t\t\tpartition(arr, l, r, arr[l + (int) (Math.random() * (r - l + 1))]);\n\t\t\t// 因为左右两侧只需要走一侧\n\t\t\t// 所以不需要临时变量记录全局的first、last\n\t\t\t// 直接用即可\n\t\t\tif (i < first) {\n\t\t\t\tr = first - 1;\n\t\t\t} else if (i > last) {\n\t\t\t\tl = last + 1;\n\t\t\t} else {\n\t\t\t\tans = arr[i];\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 荷兰国旗问题\n\tpublic static int first, last;\n\n\tpublic static void partition(int[] arr, int l, int r, int x) {\n\t\tfirst = l;\n\t\tlast = r;\n\t\tint i = l;\n\t\twhile (i <= last) {\n\t\t\tif (arr[i] == x) {\n\t\t\t\ti++;\n\t\t\t} else if (arr[i] < x) {\n\t\t\t\tswap(arr, first++, i++);\n\t\t\t} else {\n\t\t\t\tswap(arr, i, last--);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n}\n	模板：RandomizedSelect.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cf8d1b75-feb7-4d9b-baf4-7a1587298511	853ef809-26be-4146-bfab-429205b9aacd	java	package class015;\n\nimport java.util.Stack;\n\n// 最小栈\n// 测试链接 : https://leetcode.cn/problems/min-stack/\npublic class GetMinStack {\n\n\t// 提交时把类名、构造方法改成MinStack\n\tclass MinStack1 {\n\t\tpublic Stack<Integer> data;\n\t\tpublic Stack<Integer> min;\n\n\t\tpublic MinStack1() {\n\t\t\tdata = new Stack<Integer>();\n\t\t\tmin = new Stack<Integer>();\n\t\t}\n\n\t\tpublic void push(int val) {\n\t\t\tdata.push(val);\n\t\t\tif (min.isEmpty() || val <= min.peek()) {\n\t\t\t\tmin.push(val);\n\t\t\t} else { // !min.isEmpty() && val > min.peek()\n\t\t\t\tmin.push(min.peek());\n\t\t\t}\n\t\t}\n\n\t\tpublic void pop() {\n\t\t\tdata.pop();\n\t\t\tmin.pop();\n\t\t}\n\n\t\tpublic int top() {\n\t\t\treturn data.peek();\n\t\t}\n\n\t\tpublic int getMin() {\n\t\t\treturn min.peek();\n\t\t}\n\t}\n\n\t// 提交时把类名、构造方法改成MinStack\n\tclass MinStack2 {\n\t\t// leetcode的数据在测试时，同时在栈里的数据不超过这个值\n\t\t// 这是几次提交实验出来的，哈哈\n\t\t// 如果leetcode补测试数据了，超过这个量导致出错，就调大\n\t\tpublic final int MAXN = 8001;\n\n\t\tpublic int[] data;\n\t\tpublic int[] min;\n\t\tint size;\n\n\t\tpublic MinStack2() {\n\t\t\tdata = new int[MAXN];\n\t\t\tmin = new int[MAXN];\n\t\t\tsize = 0;\n\t\t}\n\n\t\tpublic void push(int val) {\n\t\t\tdata[size] = val;\n\t\t\tif (size == 0 || val <= min[size - 1]) {\n\t\t\t\tmin[size] = val;\n\t\t\t} else {\n\t\t\t\tmin[size] = min[size - 1];\n\t\t\t}\n\t\t\tsize++;\n\t\t}\n\n\t\tpublic void pop() {\n\t\t\tsize--;\n\t\t}\n\n\t\tpublic int top() {\n\t\t\treturn data[size - 1];\n\t\t}\n\n\t\tpublic int getMin() {\n\t\t\treturn min[size - 1];\n\t\t}\n\t}\n\n}\n	模板：GetMinStack.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
158ec3ce-1aa0-41a1-bb14-ff7d0212358a	7d89a981-64d8-4838-b6a9-1fe4280deca7	java	package class016;\n\nimport java.util.Deque;\nimport java.util.LinkedList;\n\n// 设计循环双端队列\n// 测试链接 : https://leetcode.cn/problems/design-circular-deque/\npublic class CircularDeque {\n\n\t// 提交时把类名、构造方法改成 : MyCircularDeque\n\t// 其实内部就是双向链表\n\t// 常数操作慢，但是leetcode数据量太小了，所以看不出劣势\n\tclass MyCircularDeque1 {\n\n\t\tpublic Deque<Integer> deque = new LinkedList<>();\n\t\tpublic int size;\n\t\tpublic int limit;\n\n\t\tpublic MyCircularDeque1(int k) {\n\t\t\tsize = 0;\n\t\t\tlimit = k;\n\t\t}\n\n\t\tpublic boolean insertFront(int value) {\n\t\t\tif (isFull()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tdeque.offerFirst(value);\n\t\t\t\tsize++;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean insertLast(int value) {\n\t\t\tif (isFull()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tdeque.offerLast(value);\n\t\t\t\tsize++;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean deleteFront() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tsize--;\n\t\t\t\tdeque.pollFirst();\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean deleteLast() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tsize--;\n\t\t\t\tdeque.pollLast();\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic int getFront() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn deque.peekFirst();\n\t\t\t}\n\t\t}\n\n\t\tpublic int getRear() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn deque.peekLast();\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean isEmpty() {\n\t\t\treturn size == 0;\n\t\t}\n\n\t\tpublic boolean isFull() {\n\t\t\treturn size == limit;\n\t\t}\n\n\t}\n\n\t// 提交时把类名、构造方法改成 : MyCircularDeque\n\t// 自己用数组实现，常数操作快，但是leetcode数据量太小了，看不出优势\n\tclass MyCircularDeque2 {\n\n\t\tpublic int[] deque;\n\t\tpublic int l, r, size, limit;\n\n\t\tpublic MyCircularDeque2(int k) {\n\t\t\tdeque = new int[k];\n\t\t\tl = r = size = 0;\n\t\t\tlimit = k;\n\t\t}\n\n\t\tpublic boolean insertFront(int value) {\n\t\t\tif (isFull()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tif (isEmpty()) {\n\t\t\t\t\tl = r = 0;\n\t\t\t\t\tdeque[0] = value;\n\t\t\t\t} else {\n\t\t\t\t\tl = l == 0 ? (limit - 1) : (l - 1);\n\t\t\t\t\tdeque[l] = value;\n\t\t\t\t}\n\t\t\t\tsize++;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean insertLast(int value) {\n\t\t\tif (isFull()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tif (isEmpty()) {\n\t\t\t\t\tl = r = 0;\n\t\t\t\t\tdeque[0] = value;\n\t\t\t\t} else {\n\t\t\t\t\tr = r == limit - 1 ? 0 : (r + 1);\n\t\t\t\t\tdeque[r] = value;\n\t\t\t\t}\n\t\t\t\tsize++;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean deleteFront() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tl = (l == limit - 1) ? 0 : (l + 1);\n\t\t\t\tsize--;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean deleteLast() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn false;\n\t\t\t} else {\n\t\t\t\tr = r == 0 ? (limit - 1) : (r - 1);\n\t\t\t\tsize--;\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\n\t\tpublic int getFront() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn deque[l];\n\t\t\t}\n\t\t}\n\n\t\tpublic int getRear() {\n\t\t\tif (isEmpty()) {\n\t\t\t\treturn -1;\n\t\t\t} else {\n\t\t\t\treturn deque[r];\n\t\t\t}\n\t\t}\n\n\t\tpublic boolean isEmpty() {\n\t\t\treturn size == 0;\n\t\t}\n\n\t\tpublic boolean isFull() {\n\t\t\treturn size == limit;\n\t\t}\n\n\t}\n\n}\n	模板：CircularDeque.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
994119bf-489b-4675-9dbc-b0c96aa9b0df	d9fb8914-8168-41cd-a424-446143887d6f	java	package class017;\n\n// 递归序的解释\n// 用递归实现二叉树的三序遍历\npublic class BinaryTreeTraversalRecursion {\n\n\tpublic static class TreeNode {\n\t\tpublic int val;\n\t\tpublic TreeNode left;\n\t\tpublic TreeNode right;\n\n\t\tpublic TreeNode(int v) {\n\t\t\tval = v;\n\t\t}\n\t}\n\n\t// 递归基本样子，用来理解递归序\n\tpublic static void f(TreeNode head) {\n\t\tif (head == null) {\n\t\t\treturn;\n\t\t}\n\t\t// 1\n\t\tf(head.left);\n\t\t// 2\n\t\tf(head.right);\n\t\t// 3\n\t}\n\n\t// 先序打印所有节点，递归版\n\tpublic static void preOrder(TreeNode head) {\n\t\tif (head == null) {\n\t\t\treturn;\n\t\t}\n\t\tSystem.out.print(head.val + " ");\n\t\tpreOrder(head.left);\n\t\tpreOrder(head.right);\n\t}\n\n\t// 中序打印所有节点，递归版\n\tpublic static void inOrder(TreeNode head) {\n\t\tif (head == null) {\n\t\t\treturn;\n\t\t}\n\t\tinOrder(head.left);\n\t\tSystem.out.print(head.val + " ");\n\t\tinOrder(head.right);\n\t}\n\n\t// 后序打印所有节点，递归版\n\tpublic static void posOrder(TreeNode head) {\n\t\tif (head == null) {\n\t\t\treturn;\n\t\t}\n\t\tposOrder(head.left);\n\t\tposOrder(head.right);\n\t\tSystem.out.print(head.val + " ");\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tTreeNode head = new TreeNode(1);\n\t\thead.left = new TreeNode(2);\n\t\thead.right = new TreeNode(3);\n\t\thead.left.left = new TreeNode(4);\n\t\thead.left.right = new TreeNode(5);\n\t\thead.right.left = new TreeNode(6);\n\t\thead.right.right = new TreeNode(7);\n\n\t\tpreOrder(head);\n\t\tSystem.out.println();\n\t\tSystem.out.println("先序遍历递归版");\n\n\t\tinOrder(head);\n\t\tSystem.out.println();\n\t\tSystem.out.println("中序遍历递归版");\n\n\t\tposOrder(head);\n\t\tSystem.out.println();\n\t\tSystem.out.println("后序遍历递归版");\n\n\t}\n\n}\n	模板：BinaryTreeTraversalRecursion.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c50c6e3a-30f0-460b-9ec0-173d0338a6a1	ffb91a90-0ce9-4e56-ae90-40bfdc271c04	java	package class018;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Stack;\n\n// 不用递归，用迭代的方式实现二叉树的三序遍历\npublic class BinaryTreeTraversalIteration {\n\n\tpublic static class TreeNode {\n\t\tpublic int val;\n\t\tpublic TreeNode left;\n\t\tpublic TreeNode right;\n\n\t\tpublic TreeNode(int v) {\n\t\t\tval = v;\n\t\t}\n\t}\n\n\t// 先序打印所有节点，非递归版\n\tpublic static void preOrder(TreeNode head) {\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tstack.push(head);\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\thead = stack.pop();\n\t\t\t\tSystem.out.print(head.val + " ");\n\t\t\t\tif (head.right != null) {\n\t\t\t\t\tstack.push(head.right);\n\t\t\t\t}\n\t\t\t\tif (head.left != null) {\n\t\t\t\t\tstack.push(head.left);\n\t\t\t\t}\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t}\n\n\t// 中序打印所有节点，非递归版\n\tpublic static void inOrder(TreeNode head) {\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\twhile (!stack.isEmpty() || head != null) {\n\t\t\t\tif (head != null) {\n\t\t\t\t\tstack.push(head);\n\t\t\t\t\thead = head.left;\n\t\t\t\t} else {\n\t\t\t\t\thead = stack.pop();\n\t\t\t\t\tSystem.out.print(head.val + " ");\n\t\t\t\t\thead = head.right;\n\t\t\t\t}\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t}\n\n\t// 后序打印所有节点，非递归版\n\t// 这是用两个栈的方法\n\tpublic static void posOrderTwoStacks(TreeNode head) {\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tStack<TreeNode> collect = new Stack<>();\n\t\t\tstack.push(head);\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\thead = stack.pop();\n\t\t\t\tcollect.push(head);\n\t\t\t\tif (head.left != null) {\n\t\t\t\t\tstack.push(head.left);\n\t\t\t\t}\n\t\t\t\tif (head.right != null) {\n\t\t\t\t\tstack.push(head.right);\n\t\t\t\t}\n\t\t\t}\n\t\t\twhile (!collect.isEmpty()) {\n\t\t\t\tSystem.out.print(collect.pop().val + " ");\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t}\n\n\t// 后序打印所有节点，非递归版\n\t// 这是用一个栈的方法\n\tpublic static void posOrderOneStack(TreeNode h) {\n\t\tif (h != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tstack.push(h);\n\t\t\t// 如果始终没有打印过节点，h就一直是头节点\n\t\t\t// 一旦打印过节点，h就变成打印节点\n\t\t\t// 之后h的含义 : 上一次打印的节点\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\tTreeNode cur = stack.peek();\n\t\t\t\tif (cur.left != null && h != cur.left && h != cur.right) {\n\t\t\t\t\t// 有左树且左树没处理过\n\t\t\t\t\tstack.push(cur.left);\n\t\t\t\t} else if (cur.right != null && h != cur.right) {\n\t\t\t\t\t// 有右树且右树没处理过\n\t\t\t\t\tstack.push(cur.right);\n\t\t\t\t} else {\n\t\t\t\t\t// 左树、右树 没有 或者 都处理过了\n\t\t\t\t\tSystem.out.print(cur.val + " ");\n\t\t\t\t\th = stack.pop();\n\t\t\t\t}\n\t\t\t}\n\t\t\tSystem.out.println();\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tTreeNode head = new TreeNode(1);\n\t\thead.left = new TreeNode(2);\n\t\thead.right = new TreeNode(3);\n\t\thead.left.left = new TreeNode(4);\n\t\thead.left.right = new TreeNode(5);\n\t\thead.right.left = new TreeNode(6);\n\t\thead.right.right = new TreeNode(7);\n\t\tpreOrder(head);\n\t\tSystem.out.println("先序遍历非递归版");\n\t\tinOrder(head);\n\t\tSystem.out.println("中序遍历非递归版");\n\t\tposOrderTwoStacks(head);\n\t\tSystem.out.println("后序遍历非递归版 - 2个栈实现");\n\t\tposOrderOneStack(head);\n\t\tSystem.out.println("后序遍历非递归版 - 1个栈实现");\n\t}\n\n\t// 用一个栈完成先序遍历\n\t// 测试链接 : https://leetcode.cn/problems/binary-tree-preorder-traversal/\n\tpublic static List<Integer> preorderTraversal(TreeNode head) {\n\t\tList<Integer> ans = new ArrayList<>();\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tstack.push(head);\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\thead = stack.pop();\n\t\t\t\tans.add(head.val);\n\t\t\t\tif (head.right != null) {\n\t\t\t\t\tstack.push(head.right);\n\t\t\t\t}\n\t\t\t\tif (head.left != null) {\n\t\t\t\t\tstack.push(head.left);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 用一个栈完成中序遍历\n\t// 测试链接 : https://leetcode.cn/problems/binary-tree-inorder-traversal/\n\tpublic static List<Integer> inorderTraversal(TreeNode head) {\n\t\tList<Integer> ans = new ArrayList<>();\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\twhile (!stack.isEmpty() || head != null) {\n\t\t\t\tif (head != null) {\n\t\t\t\t\tstack.push(head);\n\t\t\t\t\thead = head.left;\n\t\t\t\t} else {\n\t\t\t\t\thead = stack.pop();\n\t\t\t\t\tans.add(head.val);\n\t\t\t\t\thead = head.right;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 用两个栈完成后序遍历\n\t// 提交时函数名改为postorderTraversal\n\t// 测试链接 : https://leetcode.cn/problems/binary-tree-postorder-traversal/\n\tpublic static List<Integer> postorderTraversalTwoStacks(TreeNode head) {\n\t\tList<Integer> ans = new ArrayList<>();\n\t\tif (head != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tStack<TreeNode> collect = new Stack<>();\n\t\t\tstack.push(head);\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\thead = stack.pop();\n\t\t\t\tcollect.push(head);\n\t\t\t\tif (head.left != null) {\n\t\t\t\t\tstack.push(head.left);\n\t\t\t\t}\n\t\t\t\tif (head.right != null) {\n\t\t\t\t\tstack.push(head.right);\n\t\t\t\t}\n\t\t\t}\n\t\t\twhile (!collect.isEmpty()) {\n\t\t\t\tans.add(collect.pop().val);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 用一个栈完成后序遍历\n\t// 提交时函数名改为postorderTraversal\n\t// 测试链接 : https://leetcode.cn/problems/binary-tree-postorder-traversal/\n\tpublic static List<Integer> postorderTraversalOneStack(TreeNode h) {\n\t\tList<Integer> ans = new ArrayList<>();\n\t\tif (h != null) {\n\t\t\tStack<TreeNode> stack = new Stack<>();\n\t\t\tstack.push(h);\n\t\t\twhile (!stack.isEmpty()) {\n\t\t\t\tTreeNode cur = stack.peek();\n\t\t\t\tif (cur.left != null && h != cur.left && h != cur.right) {\n\t\t\t\t\tstack.push(cur.left);\n\t\t\t\t} else if (cur.right != null && h != cur.right) {\n\t\t\t\t\tstack.push(cur.right);\n\t\t\t\t} else {\n\t\t\t\t\tans.add(cur.val);\n\t\t\t\t\th = stack.pop();\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	