ad44992c-9e9c-43ca-92e5-807a057799a3	8f3a8a5b-3e6f-4921-9315-bb989b9cba42	java	package class030;\n\n// 不用任何判断语句和比较操作，返回两个数的最大值\n// 测试链接 : https://www.nowcoder.com/practice/d2707eaf98124f1e8f1d9c18ad487f76\npublic class Code02_GetMaxWithoutJudge {\n\n\t// 必须保证n一定是0或者1\n\t// 0变1，1变0\n\tpublic static int flip(int n) {\n\t\treturn n ^ 1;\n\t}\n\n\t// 非负数返回1\n\t// 负数返回0\n\tpublic static int sign(int n) {\n\t\treturn flip(n >>> 31);\n\t}\n\n\t// 有溢出风险的实现\n\tpublic static int getMax1(int a, int b) {\n\t\tint c = a - b;\n\t\t// c非负，returnA -> 1\n\t\t// c非负，returnB -> 0\n\t\t// c负数，returnA -> 0\n\t\t// c负数，returnB -> 1\n\t\tint returnA = sign(c);\n\t\tint returnB = flip(returnA);\n\t\treturn a * returnA + b * returnB;\n\t}\n\n\t// 没有任何问题的实现\n\tpublic static int getMax2(int a, int b) {\n\t\t// c可能是溢出的\n\t\tint c = a - b;\n\t\t// a的符号\n\t\tint sa = sign(a);\n\t\t// b的符号\n\t\tint sb = sign(b);\n\t\t// c的符号\n\t\tint sc = sign(c);\n\t\t// 判断A和B，符号是不是不一样，如果不一样diffAB=1，如果一样diffAB=0\n\t\tint diffAB = sa ^ sb;\n\t\t// 判断A和B，符号是不是一样，如果一样sameAB=1，如果不一样sameAB=0\n\t\tint sameAB = flip(diffAB);\n\t\tint returnA = diffAB * sa + sameAB * sc;\n\t\tint returnB = flip(returnA);\n\t\treturn a * returnA + b * returnB;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tint a = Integer.MIN_VALUE;\n\t\tint b = Integer.MAX_VALUE;\n\t\t// getMax1方法会错误，因为溢出\n\t\tSystem.out.println(getMax1(a, b));\n\t\t// getMax2方法永远正确\n\t\tSystem.out.println(getMax2(a, b));\n\t}\n\n}\n\n// 以下代码是C++版本，去掉注释之后，提交可以通过\n// 测试链接 : https://www.nowcoder.com/practice/d2707eaf98124f1e8f1d9c18ad487f76\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//class Solution {\n//public:\n//    static int flip(int n) {\n//        return n ^ 1;\n//    }\n//\n//    static int sign(int n) {\n//        return flip((uint32_t) n >> 31);\n//    }\n//\n//    static int getMax(int a, int b) {\n//        uint32_t c = (uint32_t) a - (uint32_t) b;\n//        int sa = sign(a);\n//        int sb = sign(b);\n//        int sc = flip(c >> 31);\n//        int diffAB = sa ^ sb;\n//        int sameAB = flip(diffAB);\n//        int returnA = diffAB * sa + sameAB * sc;\n//        int returnB = flip(returnA);\n//        return a * returnA + b * returnB;\n//    }\n//};\n	模板：Code02_GetMaxWithoutJudge.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
