\t\t\t\tmap.remove(key);\n\t\t\t} else {\n\t\t\t\tif (bucket.last.cnt == bucket.cnt - 1) {\n\t\t\t\t\tmap.put(key, bucket.last);\n\t\t\t\t\tbucket.last.set.add(key);\n\t\t\t\t} else {\n\t\t\t\t\tBucket newBucket = new Bucket(key, bucket.cnt - 1);\n\t\t\t\t\tmap.put(key, newBucket);\n\t\t\t\t\tinsert(bucket.last, newBucket);\n\t\t\t\t}\n\t\t\t}\n\t\t\tbucket.set.remove(key);\n\t\t\tif (bucket.set.isEmpty()) {\n\t\t\t\tremove(bucket);\n\t\t\t}\n\t\t}\n\n\t\tpublic String getMaxKey() {\n\t\t\treturn tail.last.set.iterator().next();\n\t\t}\n\n\t\tpublic String getMinKey() {\n\t\t\treturn head.next.set.iterator().next();\n\t\t}\n\n\t}\n\n}\n	模板：Code07_AllO1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e3e826cb-ccd5-428b-8db5-7bc8c076faad	16994b70-c89d-48b4-8883-bc4ab5f1851b	java	package class038;\n\nimport java.util.HashSet;\n\n// 字符串的全部子序列\n// 子序列本身是可以有重复的，只是这个题目要求去重\n// 测试链接 : https://www.nowcoder.com/practice/92e6247998294f2c933906fdedbc6e6a\npublic class Code01_Subsequences {\n\n\tpublic static String[] generatePermutation1(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tHashSet<String> set = new HashSet<>();\n\t\tf1(s, 0, new StringBuilder(), set);\n\t\tint m = set.size();\n\t\tString[] ans = new String[m];\n\t\tint i = 0;\n\t\tfor (String cur : set) {\n\t\t\tans[i++] = cur;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// s[i...]，之前决定的路径path，set收集结果时去重\n\tpublic static void f1(char[] s, int i, StringBuilder path, HashSet<String> set) {\n\t\tif (i == s.length) {\n\t\t\tset.add(path.toString());\n\t\t} else {\n\t\t\tpath.append(s[i]); // 加到路径中去\n\t\t\tf1(s, i + 1, path, set);\n\t\t\tpath.deleteCharAt(path.length() - 1); // 从路径中移除\n\t\t\tf1(s, i + 1, path, set);\n\t\t}\n\t}\n\n\tpublic static String[] generatePermutation2(String str) {\n\t\tchar[] s = str.toCharArray();\n\t\tHashSet<String> set = new HashSet<>();\n\t\tf2(s, 0, new char[s.length], 0, set);\n\t\tint m = set.size();\n\t\tString[] ans = new String[m];\n\t\tint i = 0;\n\t\tfor (String cur : set) {\n\t\t\tans[i++] = cur;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void f2(char[] s, int i, char[] path, int size, HashSet<String> set) {\n\t\tif (i == s.length) {\n\t\t\tset.add(String.valueOf(path, 0, size));\n\t\t} else {\n\t\t\tpath[size] = s[i];\n\t\t\tf2(s, i + 1, path, size + 1, set);\n\t\t\tf2(s, i + 1, path, size, set);\n\t\t}\n\t}\n\n}\n	模板：Code01_Subsequences.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e2afeb03-1f2f-4d7d-a82a-82a151bc4b18	16994b70-c89d-48b4-8883-bc4ab5f1851b	java	package class038;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n// 给你一个整数数组 nums ，其中可能包含重复元素，请你返回该数组所有可能的组合\n// 答案 不能 包含重复的组合。返回的答案中，组合可以按 任意顺序 排列\n// 注意其实要求返回的不是子集，因为子集一定是不包含相同元素的，要返回的其实是不重复的组合\n// 比如输入：nums = [1,2,2]\n// 输出：[[],[1],[1,2],[1,2,2],[2],[2,2]]\n// 测试链接 : https://leetcode.cn/problems/subsets-ii/\npublic class Code02_Combinations {\n\n\tpublic static List<List<Integer>> subsetsWithDup(int[] nums) {\n\t\tList<List<Integer>> ans = new ArrayList<>();\n\t\tArrays.sort(nums);\n\t\tf(nums, 0, new int[nums.length], 0, ans);\n\t\treturn ans;\n\t}\n\n\tpublic static void f(int[] nums, int i, int[] path, int size, List<List<Integer>> ans) {\n\t\tif (i == nums.length) {\n\t\t\tArrayList<Integer> cur = new ArrayList<>();\n\t\t\tfor (int j = 0; j < size; j++) {\n\t\t\t\tcur.add(path[j]);\n\t\t\t}\n\t\t\tans.add(cur);\n\t\t} else {\n\t\t\t// 下一组的第一个数的位置\n\t\t\tint j = i + 1;\n\t\t\twhile (j < nums.length && nums[i] == nums[j]) {\n\t\t\t\tj++;\n\t\t\t}\n\t\t\t// 当前数x，要0个\n\t\t\tf(nums, j, path, size, ans);\n\t\t\t// 当前数x，要1个、要2个、要3个...都尝试\n\t\t\tfor (; i < j; i++) {\n\t\t\t\tpath[size++] = nums[i];\n\t\t\t\tf(nums, j, path, size, ans);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code02_Combinations.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
