her[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\t// tarjan算法递归版\n\t// 一般来说都这么写，但是本题附加的测试数据很毒\n\t// java这么写就会因为递归太深而爆栈，C++这么写就能通过\n\tpublic static void tarjan(int u, int f) {\n\t\tvisited[u] = true;\n\t\tfor (int e = headEdge[u], v; e != 0; e = edgeNext[e]) {\n\t\t\tv = edgeTo[e];\n\t\t\tif (v != f) {\n\t\t\t\ttarjan(v, u);\n\t\t\t\tfather[v] = u;\n\t\t\t}\n\t\t}\n\t\tfor (int e = headQuery[u], v; e != 0; e = queryNext[e]) {\n\t\t\tv = queryTo[e];\n\t\t\tif (visited[v]) {\n\t\t\t\tans[queryIndex[e]] = find(v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tin.nextToken();\n\t\tint root = (int) in.nval;\n\t\tbuild(n);\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddQuery(u, v, i);\n\t\t\taddQuery(v, u, i);\n\t\t}\n\t\ttarjan(root, 0);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_Tarjan1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
