3cfbba58-dc8e-4cb7-83aa-b61af1391412	d8c9542f-b2d8-45ca-babf-3ebe19546b6f	java	package class186;\n\n// dfn序求LCA，java版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树，给定树头root\n// 一共有m条查询，格式 u v : 打印u和v的最低公共祖先\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3379\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_DfnLCA1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, root;\n\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] lg2 = new int[MAXN];\n\tpublic static int[][] rmq = new int[MAXN][MAXP];\n\tpublic static int cntDfn;\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, f, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static int getUp(int x, int y) {\n\t\treturn dfn[x] < dfn[y] ? x : y;\n\t}\n\n\t// dfn序递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdfn[u] = ++cntDfn;\n\t\trmq[dfn[u]][0] = fa;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1迭代版\n\tpublic static void dfs2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdfn[u] = ++cntDfn;\n\t\t\t\trmq[dfn[u]][0] = f;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void buildRmq() {\n\t\t// dfs1(root, 0);\n\t\tdfs2(root, 0);\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tlg2[i] = lg2[i >> 1] + 1;\n\t\t}\n\t\tfor (int pre = 0, cur = 1; cur <= lg2[n]; pre++, cur++) {\n\t\t\tfor (int i = 1; i + (1 << cur) - 1 <= n; i++) {\n\t\t\t\trmq[i][cur] = getUp(rmq[i][pre], rmq[i + (1 << pre)][pre]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLCA(int x, int y) {\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tx = dfn[x];\n\t\ty = dfn[y];\n\t\tif (x > y) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tx++;\n\t\tint k = lg2[y - x + 1];\n\t\treturn getUp(rmq[x][k], rmq[y - (1 << k) + 1][k]);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\troot = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tbuildRmq();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tout.println(getLCA(u, v));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_DfnLCA1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
