 {\n//        cin >> u >> v;\n//        cout << getLCA(u, v) << '\\n';\n//    }\n//    return 0;\n//}	模板：Code02_DfnLCA2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
028b3368-819e-4a2f-8383-e63f32a2c6dc	d53260ea-4e8d-45fc-b435-78b5c9cd9527	java	package class120;\n\n// 教父\n// 一共有n个节点，编号1~n，有n-1条边形成一棵树\n// 返回所有重心点\n// 树的重心第二种求解方式\n// 以某个节点为根时，每颗子树的节点数不超过总节点数的一半，那么这个节点是重心\n// 测试链接 : http://poj.org/problem?id=3107\n// 提交以下的code，提交时请把类名改成"Main"，可以直接通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_Godfather {\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[] maxsub = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tsize[u] = 1;\n\t\tmaxsub[u] = 0;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tmaxsub[u] = Math.max(maxsub[u], size[v]);\n\t\t\t}\n\t\t}\n\t\tmaxsub[u] = Math.max(maxsub[u], n - size[u]);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs(1, 0);\n\t\tint m = 0;\n\t\tint[] centers = new int[2];\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (maxsub[i] <= n / 2) {\n\t\t\t\tcenters[m++] = i;\n\t\t\t}\n\t\t}\n\t\tif (m == 1) {\n\t\t\tout.println(centers[0]);\n\t\t} else { // m == 2\n\t\t\tout.println(centers[0] + " " + centers[1]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_Godfather.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
69e0722f-e54c-4b7e-97ab-e18516b8425f	d53260ea-4e8d-45fc-b435-78b5c9cd9527	java	package class120;\n\n// 牛群聚集(递归版)\n// 一共有n个节点，编号1~n，每个点有牛的数量\n// 一共有n-1条边把所有点连通起来形成一棵树，每条边有权值\n// 想把所有的牛汇聚在一点，希望走过的总距离最小\n// 返回总距离最小是多少\n// 利用重心的性质：\n// 树上的边权如果都>=0，不管边权怎么分布，所有节点都走向重心的总距离和最小\n// 测试链接 : https://www.luogu.com.cn/problem/P2986\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code03_GreatCowGathering2文件\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_GreatCowGathering1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n;\n\n\t// cow[i] : i号农场牛的数量\n\tpublic static int[] cow = new int[MAXN];\n\n\t// 牛的总数\n\tpublic static int cowSum;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int best, center;\n\n\t// size[i] : 从1号节点开始dfs的过程中，以i为头的子树，牛的总量\n\tpublic static int[] size = new int[MAXN];\n\n\t// path[i] : 从重心节点开始dfs的过程中，从重心到达i节点，距离是多少\n\tpublic static int[] path = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tcowSum = 0;\n\t\tbest = Integer.MAX_VALUE;\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void findCenter(int u, int f) {\n\t\tsize[u] = cow[u];\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tfindCenter(v, u);\n\t\t\t}\n\t\t}\n\t\t// 如下代码是遍历完成后再做统计工作\n\t\t// 这个写法和之前的逻辑是一样的，为什么要拆开写？\n\t\t// 为了后续改迭代版方便\n\t\tint maxsub = 0;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tmaxsub = Math.max(maxsub, size[v]);\n\t\t\t}\n\t\t}\n\t\tmaxsub = Math.max(maxsub, cowSum - size[u]);\n\t\tif (maxsub < best) {\n\t\t\tbest = maxsub;\n\t\t\tcenter = u;\n\t\t}\n\t}\n\n\tpublic static void setPath(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tpath[v] = path[u] + weight[e];\n\t\t\t\tsetPath(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcow[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcowSum += cow[i];\n\t\t}\n\t\tfindCenter(1, 0);\n\t\tpath[center] = 0;\n\t\tsetPath(center, 0);\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans += (long) cow[i] * path[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code03_GreatCowGathering1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ec6e8b94-b3bc-47a7-b6ba-4721339b9bd0	d53260ea-4e8d-45fc-b435-78b5c9cd9527	java	package class120;\n\n// 牛群聚集(迭代版)\n// 一共有n个节点，编号1~n，每个点有牛的数量\n// 一共有n-1条边把所有点连通起来形成一棵树，每条边有权值\n// 想把所有的牛汇聚在一点，希望走过的总距离最小\n// 返回总距离最小是多少\n// 利用重心的性质：\n// 树上的边权如果都>=0，不管边权怎么分布，所有节点都走向重心的总距离和最小\n// 测试链接 : https://www.luogu.com.cn/problem/P2986\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_GreatCowGathering2 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n;\n\n\tpublic static int[] cow = new int[MAXN];\n\n\tpublic static int cowSum;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int best, center;\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[] path = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tcowSum = 0;\n\t\tbest = Integer.MAX_VALUE;\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// ufe是为了实现迭代版而准备的栈\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = f;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tf = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\t// 迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static void findCenter(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) { // 如果第一次来到当前节点u\n\t\t\t\tsize[u] = cow[u];\n\t\t\t\te = head[u];\n\t\t\t} else { // 如果不是第一次来到当前节点u\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) { // 如果还有后续边、还有后续子节点\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else { // 如果没有后续边了，那么就做最后的统计工作\n\t\t\t\tint maxsub = 0;\n\t\t\t\tfor (int i = head[u], v; i != 0; i = next[i]) {\n\t\t\t\t\tv = to[i];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsize[u] += size[v];\n\t\t\t\t\t\tmaxsub = Math.max(maxsub, size[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tmaxsub = Math.max(maxsub, cowSum - size[u]);\n\t\t\t\tif (maxsub < best) {\n\t\t\t\t\tbest = maxsub;\n\t\t\t\t\tcenter = u;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static void setPath(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpath[v] = path[u] + weight[e];\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcow[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcowSum += cow[i];\n\t\t}\n\t\tfindCenter(1);\n\t\tpath[center] = 0;\n\t\tsetPath(center);\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans += (long) cow[i] * path[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code03_GreatCowGathering2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
72db5fc3-7c1a-47a2-9e2f-49a93b7e54bb	d53260ea-4e8d-45fc-b435-78b5c9cd9527	java	package class120;\n\n// 删增边使其重心唯一\n// 一共有n个节点，编号1~n，有n-1条边形成一棵树\n// 现在希望重心是唯一的节点，调整的方式是先删除一条边、然后增加一条边\n// 如果树上只有一个重心，需要删掉连接重心的任意一条边，再把这条边加上(否则无法通过已经实测)\n// 如果树上有两个重心，调整的方式是先删除一条边、然后增加一条边，使重心是唯一的\n// 如果方案有多种，打印其中一种即可\n// 比如先删除节点3和节点4之间的边，再增加节点4和节点7之间的边，那么打印:\n// "3 4"\n// "4 7"\n// 测试链接 : https://www.luogu.com.cn/problem/CF1406C\n// 测试链接 : https://codeforces.com/problemset/problem/1406/C\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_LinkCutCentroids {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// size[i] : 从1号节点开始dfs的过程中，以i为头的子树的节点数\n\tpublic static int[] size = new int[MAXN];\n\n\t// maxsub[i] : 如果节点i做整棵树的根，最大子树的大小\n\tpublic static int[] maxsub = new int[MAXN];\n\n\t// 收集所有的重心\n\tpublic static int[] centers = new int[2];\n\n\t// 最大子树上的叶节点\n\tpublic static int leaf;\n\n\t// 叶节点的父亲节点\n\tpublic static int leafFather;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tsize[u] = 1;\n\t\tmaxsub[u] = 0;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tmaxsub[u] = Math.max(maxsub[u], size[v]);\n\t\t\t}\n\t\t}\n\t\tmaxsub[u] = Math.max(maxsub[u], n - size[u]);\n\t}\n\n\t// 随意找一个叶节点和该叶节点的父亲节点\n\t// 哪一组都可以\n\tpublic static void find(int u, int f) {\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tfind(to[e], u);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tleaf = u;\n\t\tleafFather = f;\n\t}\n\n\t// 返回重心的数量\n\tpublic static int centerCnt() {\n\t\tint m = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (maxsub[i] <= n / 2) {\n\t\t\t\tcenters[m++] = i;\n\t\t\t}\n\t\t}\n\t\treturn m;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint testCase = (int) in.nval;\n\t\tfor (int t = 1; t <= testCase; t++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tu = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\tdfs(1, 0);\n\t\t\tif (centerCnt() == 1) {\n\t\t\t\tout.println(centers[0] + " " + to[head[centers[0]]]);\n\t\t\t\tout.println(centers[0] + " " + to[head[centers[0]]]);\n\t\t\t} else {\n\t\t\t\tfind(centers[1], centers[0]);\n\t\t\t\tout.println(leafFather + " " + leaf);\n\t\t\t\tout.println(centers[0] + " " + leaf);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_LinkCutCentroids.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
20c0b3fe-0586-439c-a417-bc3ef3b68608	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 树的直径模版(两遍dfs)\n// 给定一棵树，边权可能为负，求直径长度\n// 测试链接 : https://www.luogu.com.cn/problem/U81904\n// 提交以下的code，提交时请把类名改成"Main"\n// 会有无法通过的用例，因为树上有负边\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_Diameter1 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// 直径的开始点\n\tpublic static int start;\n\n\t// 直径的结束点\n\tpublic static int end;\n\n\t// 直径长度\n\tpublic static int diameter;\n\n\t// dist[i] : 从规定的头节点出发，走到i的距离\n\tpublic static int[] dist = new int[MAXN];\n\n\t// last[i] : 从规定的头节点出发，i节点的上一个节点\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1, 0, 0);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start, 0, 0);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter = dist[end];\n\t}\n\n\tpublic static void dfs(int u, int f, int w) {\n\t\tlast[u] = f;\n\t\tdist[u] = dist[f] + w;\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs(to[e], u, weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\troad();\n\t\tout.println(diameter);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Diameter1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
143079a3-8bd2-4c36-b447-e17e4757b47b	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 树的直径模版(树型dp)\n// 给定一棵树，边权可能为负，求直径长度\n// 测试链接 : https://www.luogu.com.cn/problem/U81904\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有的用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_Diameter2 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// dist[u] : 从u开始必须往下走，能走出的最大距离，可以不选任何边\n\tpublic static int[] dist = new int[MAXN];\n\n\t// ans[u] : 路径必须包含点u的情况下，最大路径和\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(dist, 1, n + 1, 0);\n\t\tArrays.fill(ans, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dp(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tans[u] = Math.max(ans[u], dist[u] + dist[v] + weight[e]);\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tdp(1, 0);\n\t\tint diameter = Integer.MIN_VALUE;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdiameter = Math.max(diameter, ans[i]);\n\t\t}\n\t\tout.println(diameter);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Diameter2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a4bc8d1d-a389-4cdf-91a4-e7710ad88ea3	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 树的直径模版(树型dp版逻辑小化简)\n// 给定一棵树，边权可能为负，求直径长度\n// 测试链接 : https://www.luogu.com.cn/problem/U81904\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有的用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_Diameter3 {\n\n\tpublic static int MAXN = 500001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 直径的长度\n\tpublic static int diameter;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(dist, 1, n + 1, 0);\n\t\tdiameter = Integer.MIN_VALUE;\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dp(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\t// 干脆直接去更新diameter\n\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + weight[e]);\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tdp(1, 0);\n\t\tout.println(diameter);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Diameter3.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cd5bdae5-d075-4ba6-9bed-2059a1a08bb7	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 所有直径的公共部分(递归版)\n// 给定一棵树，边权都为正\n// 打印直径长度、所有直径的公共部分有几条边\n// 测试链接 : https://www.luogu.com.cn/problem/P3304\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code02_DiameterAndCommonEdges2文件\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_DiameterAndCommonEdges1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int start;\n\n\tpublic static int end;\n\n\tpublic static long[] dist = new long[MAXN];\n\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static long diameter;\n\n\tpublic static boolean[] diameterPath = new boolean[MAXN];\n\n\tpublic static int commonEdges;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(diameterPath, 1, n + 1, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1, 0, 0);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start, 0, 0);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter = dist[end];\n\t}\n\n\tpublic static void dfs(int u, int f, long c) {\n\t\tlast[u] = f;\n\t\tdist[u] = c;\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs(to[e], u, c + weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不能走向直径路径上的节点\n\t// 能走出的最大距离\n\tpublic static long maxDistanceExceptDiameter(int u, int f, long c) {\n\t\tlong ans = c;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (!diameterPath[v] && v != f) {\n\t\t\t\tans = Math.max(ans, maxDistanceExceptDiameter(v, u, c + weight[e]));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void compute() {\n\t\troad();\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tdiameterPath[i] = true;\n\t\t}\n\t\tint l = start;\n\t\tint r = end;\n\t\tlong maxDist;\n\t\tfor (int i = last[end]; i != start; i = last[i]) {\n\t\t\tmaxDist = maxDistanceExceptDiameter(i, 0, 0);\n\t\t\tif (maxDist == diameter - dist[i]) {\n\t\t\t\tr = i;\n\t\t\t}\n\t\t\tif (maxDist == dist[i] && l == start) {\n\t\t\t\tl = i;\n\t\t\t}\n\t\t}\n\t\tif (l == r) {\n\t\t\tcommonEdges = 0;\n\t\t} else {\n\t\t\tcommonEdges = 1;\n\t\t\tfor (int i = last[r]; i != l; i = last[i]) {\n\t\t\t\tcommonEdges++;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tcompute();\n\t\tout.println(diameter);\n\t\tout.println(commonEdges);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_DiameterAndCommonEdges1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
efc29200-c1f1-41ab-8cee-057991d9982d	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 所有直径的公共部分(迭代版)\n// 给定一棵树，边权都为正\n// 打印直径长度、所有直径的公共部分有几条边\n// 测试链接 : https://www.luogu.com.cn/problem/P3304\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_DiameterAndCommonEdges2 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int start;\n\n\tpublic static int end;\n\n\tpublic static long[] dist = new long[MAXN];\n\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static long diameter;\n\n\tpublic static boolean[] diameterPath = new boolean[MAXN];\n\n\tpublic static int commonEdges;\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(diameterPath, 1, n + 1, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter = dist[end];\n\t}\n\n\t// dfs方法改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static int[][] ufeStack = new int[MAXN][3];\n\n\tpublic static long[] distStack = new long[MAXN];\n\n\tpublic static int stackSize;\n\n\tpublic static int u, f, e;\n\n\tpublic static long c;\n\n\tpublic static void push(int u, int f, int e, long c) {\n\t\tufeStack[stackSize][0] = u;\n\t\tufeStack[stackSize][1] = f;\n\t\tufeStack[stackSize][2] = e;\n\t\tdistStack[stackSize] = c;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufeStack[stackSize][0];\n\t\tf = ufeStack[stackSize][1];\n\t\te = ufeStack[stackSize][2];\n\t\tc = distStack[stackSize];\n\t}\n\n\tpublic static void dfs(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1, 0);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tlast[u] = f;\n\t\t\t\tdist[u] = c;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e, c);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1, c + weight[e]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// maxDistanceExceptDiameter方法改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static long maxDistanceExceptDiameter(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1, 0);\n\t\tlong ans = 0;\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tint v;\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e, c);\n\t\t\t\tv = to[e];\n\t\t\t\tif (!diameterPath[v] && v != f) {\n\t\t\t\t\tpush(v, u, -1, c + weight[e]);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tans = Math.max(ans, c);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void compute() {\n\t\troad();\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tdiameterPath[i] = true;\n\t\t}\n\t\tint l = start;\n\t\tint r = end;\n\t\tlong maxDist;\n\t\tfor (int i = last[end]; i != start; i = last[i]) {\n\t\t\tmaxDist = maxDistanceExceptDiameter(i);\n\t\t\tif (maxDist == diameter - dist[i]) {\n\t\t\t\tr = i;\n\t\t\t}\n\t\t\tif (maxDist == dist[i] && l == start) {\n\t\t\t\tl = i;\n\t\t\t}\n\t\t}\n\t\tif (l == r) {\n\t\t\tcommonEdges = 0;\n\t\t} else {\n\t\t\tcommonEdges = 1;\n\t\t\tfor (int i = last[r]; i != l; i = last[i]) {\n\t\t\t\tcommonEdges++;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tcompute();\n\t\tout.println(diameter);\n\t\tout.println(commonEdges);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_DiameterAndCommonEdges2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f1672a93-3b33-4189-bb3e-d6213721ee90	6eda5810-8fbe-4dae-9315-857d318c4f24	java	package class123;\n\n// 染色的最大收益\n// 给定一棵n个点的树，初始时所有节点全是白点\n// 第一次操作，你可以选择任意点染黑\n// 以后每次操作，必须选择已经染黑的点的相邻点继续染黑，一直到所有的点都被染完\n// 每次都获得，当前被染色点的白色连通块大小，作为收益\n// 返回可获得的最大收益和\n// 测试链接 : https://www.luogu.com.cn/problem/CF1187E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_TreePainting {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static long[] dp = new long[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(size, 1, n + 1, 0);\n\t\tArrays.fill(dp, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\t// dp[i]更新成\n\t// 节点i作为自己这棵子树最先染的点，染完子树后，收益是多少\n\tpublic static void dfs1(int u, int f) {\n\t\tsize[u] = 1;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tdp[u] += dp[v];\n\t\t\t}\n\t\t}\n\t\tdp[u] += size[u];\n\t}\n\n\t// dp[i]更新成\n\t// 节点i作为整棵树最先染的点，染完整棵树后，收益是多少\n\tpublic static void dfs2(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp[v] = dp[u] + n - size[v] - size[v];\n\t\t\t\tdfs2(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans = Math.max(ans, dp[i]);\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_TreePainting.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
290f682d-051a-4f6a-b863-b033d40da67f	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 造公园\n// 一共n个节点，编号1~n，有m条边连接，边权都是1\n// 所有节点可能形成多个连通区，每个连通区保证是树结构\n// 有两种类型的操作\n// 操作 1 x   : 返回x到离它最远的点的距离\n// 操作 2 x y : 如果x和y已经连通，那么忽略\n//              如果不连通，那么执行连通操作，把x和y各自的区域连通起来\n//              并且要保证连通成的大区域的直径长度最小\n// 测试链接 : https://www.luogu.com.cn/problem/P2195\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_BuildPark {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// 并查集需要\n\tpublic static int[] father = new int[MAXN];\n\n\t// 树型dp需要\n\t// dist[u] : 从u开始必须往下走，能走出的最大距离，可以不选任何边\n\tpublic static int[] dist = new int[MAXN];\n\n\t// diameter[i] : 如果i是集合的头节点，diameter[i]表示整个集合的直径长度\n\t//               如果i不再是集合的头节点，diameter[i]的值没有用\n\t// 并查集 + 集合打标签技巧，不会的看讲解056、讲解057\n\tpublic static int[] diameter = new int[MAXN];\n\n\tpublic static void build(int n) {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tArrays.fill(dist, 1, n, 0);\n\t\tArrays.fill(diameter, 1, n, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\t// 树型dp的方式求直径长度\n\tpublic static void dp(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdiameter[u] = Math.max(diameter[u], Math.max(diameter[v], dist[u] + dist[v] + 1));\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tin.nextToken();\n\t\tint q = (int) in.nval;\n\t\tbuild(n);\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t\tu = find(u);\n\t\t\tv = find(v);\n\t\t\tfather[u] = v;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (i == father[i]) {\n\t\t\t\tdp(i, 0);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1, op, x, y; i <= q; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tx = find(x);\n\t\t\t\tout.println(diameter[x]);\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tx = find(x);\n\t\t\t\ty = find(y);\n\t\t\t\tif (x != y) {\n\t\t\t\t\tfather[x] = y;\n\t\t\t\t\tdiameter[y] = Math.max((diameter[x] + 1) / 2 + (diameter[y] + 1) / 2 + 1,\n\t\t\t\t\t\t\tMath.max(diameter[x], diameter[y]));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_BuildPark.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ba167f6e-f0b0-4177-bbba-ef03d6ab34ea	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 巡逻\n// 一共n个节点，编号1~n，结构是一棵树，每条边都是双向的\n// 警察局在1号点，警车每天从1号点出发，一定要走过树上所有的边，最后回到1号点\n// 现在为了减少经过边的数量，你可以新建k条边，把树上任意两点直接相连\n// 并且每天警车必须经过新建的道路正好一次\n// 计算出最佳的新建道路的方案，返回巡逻走边数量的最小值\n// 测试链接 : https://www.luogu.com.cn/problem/P3629\n// 1 <= n <= 10^5\n// 1 <= k <= 2\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_Patrol {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n;\n\n\tpublic static int k;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int start;\n\n\tpublic static int end;\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static int diameter1;\n\n\tpublic static int diameter2;\n\n\tpublic static boolean[] diameterPath = new boolean[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tdiameter1 = 0;\n\t\tdiameter2 = 0;\n\t\tArrays.fill(diameterPath, 1, n, false);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1, 0, 0);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start, 0, 0);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter1 = dist[end];\n\t}\n\n\tpublic static void dfs(int u, int f, int w) {\n\t\tlast[u] = f;\n\t\tdist[u] = dist[f] + w;\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs(to[e], u, 1);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 树型dp第二次求直径长度\n\tpublic static void dp(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v, w; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tw = diameterPath[u] && diameterPath[v] ? -1 : 1;\n\t\t\t\tdiameter2 = Math.max(diameter2, dist[u] + dist[v] + w);\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static int compute() {\n\t\troad();\n\t\tif (k == 1) {\n\t\t\treturn 2 * (n - 1) - diameter1 + 1;\n\t\t} else {\n\t\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\t\tdiameterPath[i] = true;\n\t\t\t}\n\t\t\tArrays.fill(dist, 1, n + 1, 0);\n\t\t\tdp(1, 0);\n\t\t\treturn 2 * (n - 1) - diameter1 - diameter2 + 2;\n\t\t}\n\t}\n\n}	模板：Code04_Patrol.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5871e27c-8de7-405a-9967-e48a5ede4972	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 消防(递归版)\n// 一共n个节点，编号1~n，有n-1条边连接成一棵树，每条边上有非负权值\n// 给定一个非负整数s，表示可以在树上选择一条长度不超过s的路径\n// 然后在这条路径的点上建立消防站，每个居民可以去往这条路径上的任何消防站\n// 目标：哪怕最远的居民走到消防站的距离也要尽量少\n// 返回最远居民走到消防站的最短距离\n// 测试链接 : https://www.luogu.com.cn/problem/P2491\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code05_FireFighting2文件\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_FireFighting1 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int n;\n\n\tpublic static int s;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int start;\n\n\tpublic static int end;\n\n\tpublic static int diameter;\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] last = new int[MAXN];\n\n\t// pred[i] : i节点在直径上，和前一个点之间的距离，以start做根\n\tpublic static int[] pred = new int[MAXN];\n\n\tpublic static boolean[] diameterPath = new boolean[MAXN];\n\n\tpublic static int[] maxDist = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(diameterPath, 1, n, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1, 0, 0);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start, 0, 0);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter = dist[end];\n\t}\n\n\tpublic static void dfs(int u, int f, int w) {\n\t\tlast[u] = f;\n\t\tdist[u] = dist[f] + w;\n\t\tpred[u] = w;\n\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\tif (to[e] != f) {\n\t\t\t\tdfs(to[e], u, weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void distance() {\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tdiameterPath[i] = true;\n\t\t}\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tmaxDist[i] = maxDistanceExceptDiameter(i, 0, 0);\n\t\t}\n\t}\n\n\t// 不能走向直径路径上的节点\n\t// 能走出的最大距离\n\tpublic static int maxDistanceExceptDiameter(int u, int f, int c) {\n\t\tint ans = c;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (!diameterPath[v] && v != f) {\n\t\t\t\tans = Math.max(ans, maxDistanceExceptDiameter(v, u, c + weight[e]));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 单调队列维护窗口内最大值\n\t// 不会的看讲解054\n\tpublic static int[] queue = new int[MAXN];\n\n\tpublic static int compute() {\n\t\tint suml = 0, sumr = 0;\n\t\t// 用h和t表示单调队列的头和尾\n\t\tint h = 0, t = 0;\n\t\tint ans = Integer.MAX_VALUE;\n\t\t// 窗口范围[l,r)，左闭右开，直径上的窗口[l...r-1]\n\t\t// l是窗口左端点，r是窗口右端点的再下一个点\n\t\t// 课上图解是从start到end，实际是从end到start，思路没有区别\n\t\tfor (int l = end, r = end; l != 0; l = last[l]) {\n\t\t\twhile (r != 0 && sumr - suml + pred[r] <= s) {\n\t\t\t\twhile (h < t && maxDist[queue[t - 1]] <= maxDist[r]) {\n\t\t\t\t\tt--;\n\t\t\t\t}\n\t\t\t\tsumr += pred[r];\n\t\t\t\tqueue[t++] = r;\n\t\t\t\tr = last[r];\n\t\t\t}\n\t\t\tans = Math.min(ans, Math.max(Math.max(suml, maxDist[queue[h]]), diameter - sumr));\n\t\t\tif (queue[h] == l) {\n\t\t\t\th++;\n\t\t\t}\n\t\t\tsuml += pred[l];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\ts = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\troad();\n\t\tdistance();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_FireFighting1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
bca6fe08-4644-4685-9c12-2e2656537e31	167ea2d6-261a-459e-9588-e8793863de00	java	package class121;\n\n// 消防(迭代版)\n// 一共n个节点，编号1~n，有n-1条边连接成一棵树，每条边上有非负权值\n// 给定一个非负整数s，表示可以在树上选择一条长度不超过s的路径\n// 然后在这条路径的点上建立消防站，每个居民可以去往这条路径上的任何消防站\n// 目标：哪怕最远的居民走到消防站的距离也要尽量少\n// 返回最远居民走到消防站的最短距离\n// 测试链接 : https://www.luogu.com.cn/problem/P2491\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_FireFighting2 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int n;\n\n\tpublic static int s;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int start;\n\n\tpublic static int end;\n\n\tpublic static int diameter;\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static int[] pred = new int[MAXN];\n\n\tpublic static boolean[] diameterPath = new boolean[MAXN];\n\n\tpublic static int[] maxDist = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(diameterPath, 1, n, false);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void road() {\n\t\tdfs(1);\n\t\tstart = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[start]) {\n\t\t\t\tstart = i;\n\t\t\t}\n\t\t}\n\t\tdfs(start);\n\t\tend = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (dist[i] > dist[end]) {\n\t\t\t\tend = i;\n\t\t\t}\n\t\t}\n\t\tdiameter = dist[end];\n\t}\n\n\t// dfs方法改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static int[][] ufwe = new int[MAXN][4];\n\n\tpublic static int stackSize;\n\n\tpublic static int u, f, w, e;\n\n\tpublic static void push(int u, int f, int w, int e) {\n\t\tufwe[stackSize][0] = u;\n\t\tufwe[stackSize][1] = f;\n\t\tufwe[stackSize][2] = w;\n\t\tufwe[stackSize][3] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufwe[stackSize][0];\n\t\tf = ufwe[stackSize][1];\n\t\tw = ufwe[stackSize][2];\n\t\te = ufwe[stackSize][3];\n\t}\n\n\tpublic static void dfs(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tlast[u] = f;\n\t\t\t\tdist[u] = dist[f] + w;\n\t\t\t\tpred[u] = w;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, w, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, weight[e], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void distance() {\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tdiameterPath[i] = true;\n\t\t}\n\t\tfor (int i = end; i != 0; i = last[i]) {\n\t\t\tmaxDist[i] = maxDistanceExceptDiameter(i, 0, 0);\n\t\t}\n\t}\n\n\t// maxDistanceExceptDiameter方法不用改迭代居然能通过\n\t// 那就不改了\n\tpublic static int maxDistanceExceptDiameter(int u, int f, int c) {\n\t\tint ans = c;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (!diameterPath[v] && v != f) {\n\t\t\t\tans = Math.max(ans, maxDistanceExceptDiameter(v, u, c + weight[e]));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int[] queue = new int[MAXN];\n\n\tpublic static int compute() {\n\t\tint suml = 0, sumr = 0;\n\t\tint h = 0, t = 0;\n\t\tint ans = Integer.MAX_VALUE;\n\t\tfor (int l = end, r = end; l != 0; l = last[l]) {\n\t\t\twhile (r != 0 && sumr + pred[r] - suml <= s) {\n\t\t\t\twhile (h < t && maxDist[queue[t - 1]] <= maxDist[r]) {\n\t\t\t\t\tt--;\n\t\t\t\t}\n\t\t\t\tsumr += pred[r];\n\t\t\t\tqueue[t++] = r;\n\t\t\t\tr = last[r];\n\t\t\t}\n\t\t\tans = Math.min(ans, Math.max(Math.max(suml, maxDist[queue[h]]), diameter - sumr));\n\t\t\tif (queue[h] == l) {\n\t\t\t\th++;\n\t\t\t}\n\t\t\tsuml += pred[l];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\ts = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tw = (int) in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\troad();\n\t\tdistance();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_FireFighting2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a4dae2ed-c1dd-4e42-b7ec-4b48a755f71e	6eda5810-8fbe-4dae-9315-857d318c4f24	java	package class123;\n\n// 最大深度和(递归版)\n// 给定一棵n个点的树，找到一个节点，使得以这个节点为根时，到达所有节点的深度之和最大\n// 如果有多个节点满足要求，返回节点编号最小的\n// 测试链接 : https://www.luogu.com.cn/problem/P3478\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code01_MaximizeSumOfDeeps2文件\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_MaximizeSumOfDeeps1 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN];\n\n\tpublic static long[] dp = new long[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tsize[u] = 1;\n\t\tsum[u] = 0;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tsum[u] += sum[v] + size[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdp[v] = dp[u] - size[v] + n - size[v];\n\t\t\t\tdfs2(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdp[1] = sum[1];\n\t\tdfs2(1, 0);\n\t\tlong max = Long.MIN_VALUE;\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dp[i] > max) {\n\t\t\t\tmax = dp[i];\n\t\t\t\tans = i;\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_MaximizeSumOfDeeps1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c2830686-d4d0-41ba-8aa1-1d69a28602bc	6eda5810-8fbe-4dae-9315-857d318c4f24	java	package class123;\n\n// 最大深度和(迭代版)\n// 给定一棵n个点的树，找到一个节点，使得以这个节点为根时，到达所有节点的深度之和最大\n// 如果有多个节点满足要求，返回节点编号最小的\n// 测试链接 : https://www.luogu.com.cn/problem/P3478\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code01_MaximizeSumOfDeeps2 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN];\n\n\tpublic static long[] dp = new long[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\t// dfs1方法改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize;\n\n\tpublic static int u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = f;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tf = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\tpublic static void dfs1(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tsize[u] = 1;\n\t\t\t\tsum[u] = 0;\n\t\t\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsize[u] += size[v];\n\t\t\t\t\t\tsum[u] += sum[v] + size[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2方法改迭代版\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static void dfs2(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tdp[v] = dp[u] - size[v] + (n - size[v]);\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1);\n\t\tdp[1] = sum[1];\n\t\tdfs2(1);\n\t\tlong max = Long.MIN_VALUE;\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dp[i] > max) {\n\t\t\t\tmax = dp[i];\n\t\t\t\tans = i;\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_MaximizeSumOfDeeps2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
1829e910-8610-41c6-9cad-21f71892e3b1	6eda5810-8fbe-4dae-9315-857d318c4f24	java	package class123;\n\n// 翻转道路数量最少的首都\n// 给定一棵n个点的树，但是给定的每条边都是有向的\n// 需要选择某个城市为首都，要求首都一定可以去往任何一个城市\n// 这样一来，可能需要翻转一些边的方向才能做到，现在想翻转道路的数量尽量少\n// 打印最少翻转几条道路就可以拥有首都\n// 如果有若干点做首都时，翻转道路的数量都是最少的，那么打印这些点\n// 测试链接 : https://www.luogu.com.cn/problem/CF219D\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_ChooseCapital {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// reverse[u] : u到所有子节点需要逆转的边数\n\tpublic static int[] reverse = new int[MAXN];\n\n\t// dp[u] : u做根到全树节点需要逆转的边数\n\tpublic static int[] dp = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(reverse, 1, n + 1, 0);\n\t\tArrays.fill(dp, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfor (int e = head[u], v, w; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tw = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\treverse[u] += reverse[v] + w;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfor (int e = head[u], v, w; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tw = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tif (w == 0) {\n\t\t\t\t\t// 边的方向 : u -> v\n\t\t\t\t\tdp[v] = dp[u] + 1;\n\t\t\t\t} else {\n\t\t\t\t\t// 边的方向 : v -> u\n\t\t\t\t\tdp[v] = dp[u] - 1;\n\t\t\t\t}\n\t\t\t\tdfs2(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tu = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\taddEdge(u, v, 0);\n\t\t\t\taddEdge(v, u, 1);\n\t\t\t}\n\t\t\tdfs1(1, 0);\n\t\t\tdp[1] = reverse[1];\n\t\t\tdfs2(1, 0);\n\t\t\tint min = Integer.MAX_VALUE;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (min > dp[i]) {\n\t\t\t\t\tmin = dp[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(min);\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (min == dp[i]) {\n\t\t\t\t\tout.print(i + " ");\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_ChooseCapital.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
22ba32c8-1061-4a39-b8b1-5a4227ac6e9b	6eda5810-8fbe-4dae-9315-857d318c4f24	java	package class123;\n\n// 选择节点做根使流量和最大(递归版)\n// 给定一棵n个点的树，边的边权代表流量限制\n// 从边上流过的流量，不能超过流量限制\n// 现在想知道以某个节点做根时，流到所有叶节点的流量，最大是多少\n// 测试链接 : http://poj.org/problem?id=3585\n// 提交以下的code，提交时请把类名改成"Main"\n// C++这么写能通过，java会因为递归层数太多而爆栈\n// java能通过的写法参考本节课Code04_MaximizeFlow2文件\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_MaximizeFlow1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] weight = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// degree[u] : 有几条边和u节点相连\n\tpublic static int[] degree = new int[MAXN];\n\n\t// flow[u] : 从u出发流向u节点为头的子树上，所有的叶节点，流量是多少\n\tpublic static int[] flow = new int[MAXN];\n\n\t// dp[u] : 从u出发流向u节点为根的整棵树上，所有的叶节点，流量是多少\n\tpublic static int[] dp = new int[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t\tArrays.fill(degree, 1, n + 1, 0);\n\t\tArrays.fill(flow, 1, n + 1, 0);\n\t\tArrays.fill(dp, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tif (degree[v] == 1) {\n\t\t\t\t\tflow[u] += weight[e];\n\t\t\t\t} else {\n\t\t\t\t\tflow[u] += Math.min(flow[v], weight[e]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tif (degree[u] == 1) {\n\t\t\t\t\tdp[v] = flow[v] + weight[e];\n\t\t\t\t} else {\n\t\t\t\t\t// uOut : u流向外的流量\n\t\t\t\t\tint uOut = dp[u] - Math.min(flow[v], weight[e]);\n\t\t\t\t\tdp[v] = flow[v] + Math.min(uOut, weight[e]);\n\t\t\t\t}\n\t\t\t\tdfs2(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint testCase = (int) in.nval;\n\t\tfor (int t = 1; t <= testCase; t++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tbuild();\n\t\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tu = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tv = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tw = (int) in.nval;\n\t\t\t\taddEdge(u, v, w);\n\t\t\t\taddEdge(v, u, w);\n\t\t\t\tdegree[u]++;\n\t\t\t\tdegree[v]++;\n\t\t\t}\n\t\t\tdfs1(1, 0);\n\t\t\tdp[1] = flow[1];\n\t\t\tdfs2(1, 0);\n\t\t\tint ans = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tans = Math.max(ans, dp[i]);\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_MaximizeFlow1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
