tatic int special() {\n\t\tif ((n & 1) == 0) {\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tif (start[i] == end[i]) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tif (start[i] != end[i]) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn 1;\n\t}\n\n\tpublic static int compute() {\n\t\tstartStatus = endStatus = 0;\n\t\tfor (int j = 0; j < m; j++) {\n\t\t\tstartStatus = set(startStatus, j, start[j]);\n\t\t\tendStatus = set(endStatus, j, end[j]);\n\t\t}\n\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\tprepare[s] = different(s, endStatus) ? 1 : 0;\n\t\t}\n\t\tfor (int i = n - 2; i >= 1; i--) {\n\t\t\t// j == m\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tdp[m][s] = prepare[s];\n\t\t\t}\n\t\t\t// 普通位置\n\t\t\tfor (int j = m - 1; j >= 0; j--) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tint ans = 0;\n\t\t\t\t\tfor (int color = 0; color < k; color++) {\n\t\t\t\t\t\tif ((j == 0 || get(s, j - 1) != color) && get(s, j) != color) {\n\t\t\t\t\t\t\tans = (ans + dp[j + 1][set(s, j, color)]) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tdp[j][s] = ans;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 设置prepare\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tprepare[s] = dp[0][s];\n\t\t\t}\n\t\t}\n\t\treturn dp[0][startStatus];\n\t}\n\n\tpublic static boolean different(int a, int b) {\n\t\tfor (int j = 0; j < m; j++) {\n\t\t\tif (get(a, j) == get(b, j)) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> (j << 1)) & 3;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn s & (~(3 << (j << 1))) | (v << (j << 1));\n\t}\n\n}\n	模板：Code03_AdjacentDifferent2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
106a10bc-92e8-4c0e-8f8e-66a58219dc25	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 题目1，01分数规划模版题，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P10505\n// 测试链接 : http://poj.org/problem?id=2976\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Other1 {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double[][] arr = new double[MAXN][3];\n\n\tpublic static int n, k;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][2] = arr[i][0] - x * arr[i][1];\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, new MyComparator());\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tsum += arr[i][2];\n\t\t}\n\t\treturn sum >= 0;\n\t}\n\n\tpublic static class MyComparator implements Comparator<double[]> {\n\n\t\t@Override\n\t\tpublic int compare(double[] o1, double[] o2) {\n\t\t\treturn o1[2] >= o2[2] ? -1 : 1;\n\t\t}\n\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\twhile (n != 0 || k != 0) {\n\t\t\tk = n - k;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][0] = in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][1] = in.nval;\n\t\t\t}\n\t\t\tdouble l = 0, r = 0, x;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tr += arr[i][0];\n\t\t\t}\n\t\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t\t// 二分完成后，l就是答案\n\t\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (check(x)) {\n\t\t\t\t\tl = x;\n\t\t\t\t} else {\n\t\t\t\t\tr = x;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println((int) (100 * (l + 0.005)));\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Other1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b22305e3-a0e7-4dea-907f-81027c27d4af	45daf64a-9589-48f3-b77e-26420d90b443	java	package class125;\n\n// 摆放国王的方法数(轮廓线dp)\n// 给定两个参数n和k，表示n*n的区域内要摆放k个国王\n// 国王可以攻击临近的8个方向，所以摆放时不能让任何两个国王打架\n// 返回摆放的方法数\n// 1 <= n <= 9\n// 1 <= k <= n*n\n// 测试链接 : https://www.luogu.com.cn/problem/P1896\n// 提交以下的code，提交时请把类名改成"Main"，有可能全部通过\n// 不过更推荐写出空间压缩的版本\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_KingsFighting1 {\n\n\tpublic static int MAXN = 9;\n\n\tpublic static int MAXK = 82;\n\n\tpublic static long[][][][][] dp = new long[MAXN][MAXN][1 << MAXN][2][MAXK];\n\n\tpublic static int n, kings, maxs;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tkings = (int) in.nval;\n\t\tmaxs = 1 << n;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tfor (int leftup = 0; leftup <= 1; leftup++) {\n\t\t\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\t\t\tdp[i][j][s][leftup][k] = -1;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn f(0, 0, 0, 0, kings);\n\t}\n\n\t// 当前来到i行j列\n\t// i-1行中，[j..m-1]列有没有摆放国王，用s[j..m-1]号格子表示\n\t// i行中，[0..j-1]列有没有摆放国王，用s[0..j-1]号格子表示\n\t// s表示轮廓线的状况\n\t// (i-1, j-1)位置，也就是左上角，有没有摆放国王，用leftup表示\n\t// 国王还剩下k个需要去摆放\n\t// 返回有多少种摆放方法\n\tpublic static long f(int i, int j, int s, int leftup, int k) {\n\t\tif (i == n) {\n\t\t\treturn k == 0 ? 1 : 0;\n\t\t}\n\t\tif (j == n) {\n\t\t\treturn f(i + 1, 0, s, 0, k);\n\t\t}\n\t\tif (dp[i][j][s][leftup][k] != -1) {\n\t\t\treturn dp[i][j][s][leftup][k];\n\t\t}\n\t\tint left = j == 0 ? 0 : get(s, j - 1);\n\t\tint up = get(s, j);\n\t\tint rightup = get(s, j + 1);\n\t\tlong ans = f(i, j + 1, set(s, j, 0), up, k);\n\t\tif (k > 0 && left == 0 && leftup == 0 && up == 0 && rightup == 0) {\n\t\t\tans += f(i, j + 1, set(s, j, 1), up, k - 1);\n\t\t}\n\t\tdp[i][j][s][leftup][k] = ans;\n\t\treturn ans;\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> j) & 1;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn v == 0 ? (s & (~(1 << j))) : (s | (1 << j));\n\t}\n\n}\n	模板：Code04_KingsFighting1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
9e7bd1da-5992-44c5-8545-aa60a6259282	45daf64a-9589-48f3-b77e-26420d90b443	java	package class125;\n\n// 摆放国王的方法数(轮廓线dp+空间压缩)\n// 给定两个参数n和k，表示n*n的区域内要摆放k个国王\n// 国王可以攻击临近的8个方向，所以摆放时不能让任何两个国王打架\n// 返回摆放的方法数\n// 1 <= n <= 9\n// 1 <= k <= n*n\n// 测试链接 : https://www.luogu.com.cn/problem/P1896\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n// 空间压缩的版本一定稳定通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_KingsFighting2 {\n\n\tpublic static int MAXN = 9;\n\n\tpublic static int MAXK = 82;\n\n\tpublic static long[][][][] dp = new long[MAXN + 1][1 << MAXN][2][MAXK];\n\n\tpublic static long[][] prepare = new long[1 << MAXN][MAXK];\n\n\tpublic static int n, kings, maxs;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tkings = (int) in.nval;\n\t\tmaxs = 1 << n;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\tprepare[s][k] = k == 0 ? 1 : 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\t// j == n\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\tdp[n][s][0][k] = prepare[s][k];\n\t\t\t\t\tdp[n][s][1][k] = prepare[s][k];\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 普通位置\n\t\t\tfor (int j = n - 1; j >= 0; j--) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tfor (int leftup = 0; leftup <= 1; leftup++) {\n\t\t\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\t\t\tint left = j == 0 ? 0 : get(s, j - 1);\n\t\t\t\t\t\t\tint up = get(s, j);\n\t\t\t\t\t\t\tint rightup = get(s, j + 1);\n\t\t\t\t\t\t\tlong ans = dp[j + 1][set(s, j, 0)][up][k];\n\t\t\t\t\t\t\tif (k > 0 && left == 0 && leftup == 0 && up == 0 && rightup == 0) {\n\t\t\t\t\t\t\t\tans += dp[j + 1][set(s, j, 1)][up][k - 1];\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tdp[j][s][leftup][k] = ans;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 设置prepare\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\tprepare[s][k] = dp[0][s][0][k];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[0][0][0][kings];\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> j) & 1;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn v == 0 ? (s & (~(1 << j))) : (s | (1 << j));\n\t}\n\n}\n	模板：Code04_KingsFighting2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b57bbf71-5533-4d0b-89a2-53e7ab1f34a4	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 01分数规划模版题\n// 给定n个数据，每个数据有(a, b)两个值，都为整数，并且都是非负的\n// 请舍弃掉k个数据，希望让剩下数据做到，所有a的和 / 所有b的和，这个比值尽量大\n// 如果剩下数据所有b的和为0，认为无意义\n// 最后，将该比值 * 100，小数部分四舍五入的整数结果返回\n// 1 <= n <= 100\n// 0 <= a、b <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P10505\n// 测试链接 : http://poj.org/problem?id=2976\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code01_DroppingTests {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double sml = 1e-6;\n\n\t// arr[i][0] = i号数据的a\n\t// arr[i][1] = i号数据的b\n\t// arr[i][2] = i号数据的结余，a - x * b\n\tpublic static double[][] arr = new double[MAXN][3];\n\n\tpublic static int n, k;\n\n\tpublic static boolean check(double x) {\n\t\t// x固定的情况下，得到所有数据的结余\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][2] = arr[i][0] - x * arr[i][1];\n\t\t}\n\t\t// 结余从大到小排序\n\t\tArrays.sort(arr, 1, n + 1, new MyComparator());\n\t\t// 最大k个结余的累加和\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tsum += arr[i][2];\n\t\t}\n\t\treturn sum >= 0;\n\t}\n\n\t// poj平台java版本较老，不支持Lambda表达式方式的比较器，需要自己定义\n\tpublic static class MyComparator implements Comparator<double[]> {\n\n\t\t@Override\n\t\tpublic int compare(double[] o1, double[] o2) {\n\t\t\treturn o1[2] >= o2[2] ? -1 : 1;\n\t\t}\n\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\twhile (n != 0 || k != 0) {\n\t\t\t// 题目要求舍弃掉k个，其实就是挑选n-k个\n\t\t\tk = n - k;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][0] = in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][1] = in.nval;\n\t\t\t}\n\t\t\tdouble l = 0, r = 0, x;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tr += arr[i][0];\n\t\t\t}\n\t\t\tdouble ans = 0;\n\t\t\twhile (l < r && r - l >= sml) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (check(x)) {\n\t\t\t\t\tans = x;\n\t\t\t\t\tl = x + sml;\n\t\t\t\t} else {\n\t\t\t\t\tr = x - sml;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println((int) (100 * (ans + 0.005)));\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_DroppingTests.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2d69e104-2cf7-44e7-b457-c09ab6cb491c	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 牛群的才艺展示\n// 一共有n只牛，每只牛有重量和才艺两个属性值\n// 要求一定要选若干只牛，使得总重量不少于w，并且选出的牛，希望让\n// 才艺的和 / 重量的和，这个比值尽量大\n// 返回该比值 * 1000的整数结果，小数部分舍弃\n// 1 <= n <= 250\n// 1 <= w <= 1000\n// 1 <= 牛的重量 <= 10^6\n// 1 <= 牛的才艺 <= 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P4377\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_TalentShow {\n\n\tpublic static int MAXN = 251;\n\n\tpublic static int MAXW = 1001;\n\n\t// 足够小代表无效解\n\tpublic static double NA = -1e9;\n\n\t// 最小精度\n\tpublic static double sml = 1e-6;\n\n\t// 重量\n\tpublic static int[] weight = new int[MAXN];\n\n\t// 才艺\n\tpublic static int[] talent = new int[MAXN];\n\n\t// (才艺 - x * 重量)的结余\n\tpublic static double[] value = new double[MAXN];\n\n\t// dp[i][j] : 1...i号牛自由选择，重量必须是j的情况下，最大的结余和\n\t// 特别的，dp[i][w]表示1...i号牛自由选择，重量必须是w、w+1...的所有情况中，最大的结余和\n\t// 为了节省时间和空间选择这么定义，同时做空间压缩\n\tpublic static double[] dp = new double[MAXW];\n\n\tpublic static int n, w;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvalue[i] = (double) talent[i] - x * weight[i];\n\t\t}\n\t\tdp[0] = 0;\n\t\tArrays.fill(dp, 1, w + 1, NA);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int p = w, j; p >= 0; p--) {\n\t\t\t\tj = (int) (p + weight[i]);\n\t\t\t\tif (j >= w) {\n\t\t\t\t\tdp[w] = Math.max(dp[w], dp[p] + value[i]);\n\t\t\t\t} else {\n\t\t\t\t\tdp[j] = Math.max(dp[j], dp[p] + value[i]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[w] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tw = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tweight[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ttalent[i] = (int) in.nval;\n\t\t}\n\t\tdouble l = 0, r = 0, x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tr += talent[i];\n\t\t}\n\t\tdouble ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t} else {\n\t\t\t\tr = x - sml;\n\t\t\t}\n\t\t}\n\t\tout.println((int) (ans * 1000));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_TalentShow.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
62659b87-f5fc-4c46-95f6-78398cb48e68	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 最优比率生成树\n// 一共有n个村庄，每个村庄由(x, y, z)表示\n// 其中(x,y)代表村庄在二维地图中的位置，z代表其海拔高度\n// 任意两个村庄之间的距离就是二维地图中的欧式距离\n// 任意两个村庄之间的修路花费就是海拔差值的绝对值\n// 现在想把所有村庄连通起来，希望修路的条数尽量少，同时希望让\n// 总花费 / 总距离，这个比值尽量小，返回最小的比值是多少，结果保留小数点后3位其余部分舍弃\n// 2 <= n <= 10^3\n// 0 <= x、y <= 10^4\n// 0 <= z <= 10^7\n// 测试链接 : http://poj.org/problem?id=2728\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_DesertKing {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double sml = 1e-6;\n\n\tpublic static int[] x = new int[MAXN];\n\n\tpublic static int[] y = new int[MAXN];\n\n\tpublic static int[] z = new int[MAXN];\n\n\tpublic static double[][] dist = new double[MAXN][MAXN];\n\n\tpublic static double[][] cost = new double[MAXN][MAXN];\n\n\tpublic static boolean[] visit = new boolean[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int n;\n\n\t// 邻接矩阵结构下的prim算法，从节点1出发得到最小生成树的权值和\n\tpublic static double prim(double x) {\n\t\t// 结余值做边权，进而统计距离\n\t\t// 距离只和边权有关，原始的dist、cost不重要\n\t\t// 从1号点出发，更新到所有点的距离，也就是value数组\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvisit[i] = false;\n\t\t\tvalue[i] = cost[1][i] - x * dist[1][i];\n\t\t}\n\t\tvisit[1] = true;\n\t\tdouble sum = 0;\n\t\t// 最小生成树一定有n-1条边，所以一共有n-1轮解锁，每次解锁新的点进入最小生成树的点集\n\t\tfor (int i = 1; i <= n - 1; i++) {\n\t\t\t// 在没有解锁的点中，找到离最小生成树的点集最近的点，进行解锁\n\t\t\tdouble minDist = Double.MAX_VALUE;\n\t\t\tint next = 0;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] < minDist) {\n\t\t\t\t\tminDist = value[j];\n\t\t\t\t\tnext = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 最小的边进入最小生成树的边集，解锁的点进入最小生成树的点集\n\t\t\tsum += minDist;\n\t\t\tvisit[next] = true;\n\t\t\t// 查看新的解锁点能不能拉进其他点的距离\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] > cost[next][j] - x * dist[next][j]) {\n\t\t\t\t\tvalue[j] = cost[next][j] - x * dist[next][j];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t// 返回最小生成树的权值和\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\twhile (n != 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tz[i] = (int) in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j) {\n\t\t\t\t\t\tdist[i][j] = Math.sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));\n\t\t\t\t\t\tcost[i][j] = Math.abs(z[i] - z[j]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tdouble l = 0, r = 100, x, ans = 0;\n\t\t\twhile (l < r && r - l >= sml) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\t// 如果最小生成树的权值 <= 0，达标，左侧二分找寻更小比值\n\t\t\t\t// 如果最小生成树的权值 > 0，不达标，右侧二分找寻更大比值\n\t\t\t\tif (prim(x) <= 0) {\n\t\t\t\t\tans = x;\n\t\t\t\t\tr = x - sml;\n\t\t\t\t} else {\n\t\t\t\t\tl = x + sml;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.printf("%.3f\\n", ans);\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_DesertKing.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
7d4f553a-1dad-4db6-9af6-e72364c17cec	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 最小圈\n// 一共有n个节点，m条有向边，每条边有权值\n// 这个有向带权图中，可能有若干环，规定环的平均值为\n// 环中边的权值和 / 环中边的数量\n// 返回所有环的平均值中最少的平均值，结果保留小数点后8位，其余部分舍弃\n// 1 <= n <= 3000\n// 1 <= m <= 10000\n// -10^7 <= 边权 <= 10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P3199\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_MinimumAverageCircle {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int MAXM = 10001;\n\n\tpublic static double MAXE = 1e7;\n\n\tpublic static double sml = 1e-9;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\t// dfs判断负环，每个点的累积边权\n\tpublic static double[] value = new double[MAXN];\n\n\t// dfs判断负环，每个点是否是递归路径上的点\n\tpublic static boolean[] path = new boolean[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 所有边都减去x，返回图中是否存在负环\n\tpublic static boolean check(double x) {\n\t\tArrays.fill(value, 1, n + 1, 0);\n\t\tArrays.fill(path, 1, n + 1, false);\n\t\treturn dfs(0, x);\n\t}\n\n\t// 其实就是spfa的递归版，时间复杂度O(n * m)\n\tpublic static boolean dfs(int u, double x) {\n\t\tif (u == 0) {\n\t\t\t// 认为0号点是超级源点，具有通往所有点的有向边\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfs(i, x)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tpath[u] = true;\n\t\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdouble w = weight[e] - x;\n\t\t\t\t// 只有v的累积边权变小，才会递归，非常强的剪枝\n\t\t\t\t// 如果递归路径回到v，并且此时是v的累积边权更小的情况，说明遇到了负环\n\t\t\t\t// 或者后续递归找到了负环\n\t\t\t\t// 直接返回true\n\t\t\t\tif (value[v] > value[u] + w) {\n\t\t\t\t\tvalue[v] = value[u] + w;\n\t\t\t\t\tif (path[v] || dfs(v, x)) {\n\t\t\t\t\t\treturn true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tpath[u] = false;\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tint u = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint v = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tdouble w = in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t}\n\t\tdouble l = -MAXE, r = MAXE, x, ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tr = x - sml;\n\t\t\t} else {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.8f\\n", ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_MinimumAverageCircle.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d6ad9df1-ca06-4175-ab71-2015a983a8de	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 最佳团体\n// 给定一棵树，节点编号0~n，0号节点是整棵树的头\n// 编号1~n的节点，每个节点都有招募花费和战斗值，0号节点这两个值都是0\n// 给定每条边(a,b)，表示节点a的父节点是b，有些节点的父节点是0节点\n// 当招募了某个节点，那么该节点及其上方的所有祖先节点都需要招募\n// 除了0号节点之外，一共可以招募k个人，希望让\n// 战斗值之和 / 招募花费之和，这个比值尽量大，答案只需保留三位小数，更大的精度舍弃\n// 1 <= k <= n <= 2500\n// 0 <= 招募花费、战斗值 <= 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P4322\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_BestTeam {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int LIMIT = 10000;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static double sml = 1e-6;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN];\n\n\tpublic static int[] to = new int[MAXN];\n\n\tpublic static int edgeCnt;\n\n\t// 招募花费，下标为节点原始编号\n\tpublic static int[] cost = new int[MAXN];\n\n\t// 战斗值，下标为节点原始编号\n\tpublic static int[] strength = new int[MAXN];\n\n\t// dfn[a] = b，表示原始a号节点的dfn编号为b\n\tpublic static int[] dfn = new int[MAXN];\n\n\t// dfn序计数\n\tpublic static int dfnCnt;\n\n\t// (战斗值 - x * 招募花费)的结余，下标为节点dfn编号\n\tpublic static double[] value = new double[MAXN];\n\n\t// 子树大小，下标为节点dfn编号\n\tpublic static int[] size = new int[MAXN];\n\n\t// 树型dp\n\tpublic static double[][] dp = new double[MAXN][MAXN];\n\n\tpublic static int k, n;\n\n\tpublic static void prepare() {\n\t\tedgeCnt = 1;\n\t\tdfnCnt = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[edgeCnt] = head[u];\n\t\tto[edgeCnt] = v;\n\t\thead[u] = edgeCnt++;\n\t}\n\n\t// 记录节点u的dfn编号 + 返回u这棵子树的节点数\n\t// 如下实现和讲解079，题目5，选课问题的最优解，几乎完全一样\n\tpublic static int dfs(int u) {\n\t\tint i = ++dfnCnt;\n\t\tdfn[u] = i;\n\t\tsize[i] = 1;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tsize[i] += dfs(v);\n\t\t}\n\t\treturn size[i];\n\t}\n\n\t// 根据x的值，计算节点的结余值，在树上选k+1个点\n\t// 一定要形成有效结构，返回最大的结余和\n\t// 核心逻辑完全来自讲解079，题目5，选课问题，重点介绍的最优解\n\tpublic static boolean check(double x) {\n\t\t// value[节点i的dfn编号] = 节点i的战斗值 - x * 节点i的招募花费\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tvalue[dfn[i]] = (double) strength[i] - x * cost[i];\n\t\t}\n\t\t// 越界位置认为都是无效解\n\t\tfor (int j = 1; j <= k; j++) {\n\t\t\tdp[dfnCnt + 1][j] = NA;\n\t\t}\n\t\t// 讲解079题目5的最优解逻辑\n\t\tfor (int i = dfnCnt; i >= 2; i--) {\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i + size[i]][j], value[i] + dp[i + 1][j - 1]);\n\t\t\t}\n\t\t}\n\t\t// 原始的0号节点，dfn编号是1，其他节点的dfn编号从2开始\n\t\t// 0号节点的战斗值和招募花费都是0，其他节点一共招募k个\n\t\treturn dp[2][k] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcost[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tstrength[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\taddEdge((int) in.nval, i);\n\t\t}\n\t\tdfs(0);\n\t\tdouble l = 0, r = LIMIT, x, ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t} else {\n\t\t\t\tr = x - sml;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.3f\\n", ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_BestTeam.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ba97b6a9-6dfa-4a36-ab7f-49f28bf2e305	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 题目2，牛群的才艺展示，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P4377\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other2 {\n\n\tpublic static int MAXN = 251;\n\n\tpublic static int MAXW = 1001;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static int[] weight = new int[MAXN];\n\n\tpublic static int[] talent = new int[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static double[] dp = new double[MAXW];\n\n\tpublic static int n, w;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvalue[i] = (double) talent[i] - x * weight[i];\n\t\t}\n\t\tdp[0] = 0;\n\t\tArrays.fill(dp, 1, w + 1, NA);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int p = w, j; p >= 0; p--) {\n\t\t\t\tj = (int) (p + weight[i]);\n\t\t\t\tif (j >= w) {\n\t\t\t\t\tdp[w] = Math.max(dp[w], dp[p] + value[i]);\n\t\t\t\t} else {\n\t\t\t\t\tdp[j] = Math.max(dp[j], dp[p] + value[i]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[w] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tw = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tweight[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ttalent[i] = (int) in.nval;\n\t\t}\n\t\tdouble l = 0, r = 0, x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tr += talent[i];\n\t\t}\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tl = x;\n\t\t\t} else {\n\t\t\t\tr = x;\n\t\t\t}\n\t\t}\n\t\tout.println((int) (l * 1000));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Other2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
551cc2c0-8070-4191-adbe-dd966828aff9	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 题目3，最优比率生成树，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : http://poj.org/problem?id=2728\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Other3 {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int[] x = new int[MAXN];\n\n\tpublic static int[] y = new int[MAXN];\n\n\tpublic static int[] z = new int[MAXN];\n\n\tpublic static double[][] dist = new double[MAXN][MAXN];\n\n\tpublic static double[][] cost = new double[MAXN][MAXN];\n\n\tpublic static boolean[] visit = new boolean[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int n;\n\n\tpublic static double prim(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvisit[i] = false;\n\t\t\tvalue[i] = cost[1][i] - x * dist[1][i];\n\t\t}\n\t\tvisit[1] = true;\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= n - 1; i++) {\n\t\t\tdouble minDist = Double.MAX_VALUE;\n\t\t\tint next = 0;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] < minDist) {\n\t\t\t\t\tminDist = value[j];\n\t\t\t\t\tnext = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tsum += minDist;\n\t\t\tvisit[next] = true;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] > cost[next][j] - x * dist[next][j]) {\n\t\t\t\t\tvalue[j] = cost[next][j] - x * dist[next][j];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\twhile (n != 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tz[i] = (int) in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j) {\n\t\t\t\t\t\tdist[i][j] = Math.sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));\n\t\t\t\t\t\tcost[i][j] = Math.abs(z[i] - z[j]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tdouble l = 0, r = 100, x;\n\t\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t\t// 二分完成后，l就是答案\n\t\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (prim(x) <= 0) {\n\t\t\t\t\tr = x;\n\t\t\t\t} else {\n\t\t\t\t\tl = x;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.printf("%.3f\\n", l);\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Other3.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cf3e0a1b-78c8-43b5-a0f0-0f08891d71f2	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 题目4，最小圈，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P3199\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other4 {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int MAXM = 10001;\n\n\tpublic static double MAXE = 1e7;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static boolean[] path = new boolean[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static boolean check(double x) {\n\t\tArrays.fill(value, 1, n + 1, 0);\n\t\tArrays.fill(path, 1, n + 1, false);\n\t\treturn dfs(0, x);\n\t}\n\n\tpublic static boolean dfs(int u, double x) {\n\t\tif (u == 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfs(i, x)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tpath[u] = true;\n\t\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdouble w = weight[e] - x;\n\t\t\t\tif (value[v] > value[u] + w) {\n\t\t\t\t\tvalue[v] = value[u] + w;\n\t\t\t\t\tif (path[v] || dfs(v, x)) {\n\t\t\t\t\t\treturn true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tpath[u] = false;\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tint u = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint v = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tdouble w = in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t}\n\t\tdouble l = -MAXE, r = MAXE, x;\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tr = x;\n\t\t\t} else {\n\t\t\t\tl = x;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.8f\\n", l);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Other4.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
207dc158-7a44-4a80-9218-19cd6e7f7e6e	67ae3d3c-d9ba-476e-be7d-4390d0131663	java	package class138;\n\n// 题目5，最佳团体，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P4322\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other5 {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int LIMIT = 10000;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN];\n\n\tpublic static int[] to = new int[MAXN];\n\n\tpublic static int edgeCnt;\n\n\tpublic static int[] cost = new int[MAXN];\n\n\tpublic static int[] strength = new int[MAXN];\n\n\tpublic static int[] dfn = new int[MAXN];\n\n\tpublic static int dfnCnt;\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static double[][] dp = new double[MAXN][MAXN];\n\n\tpublic static int k, n;\n\n\tpublic static void prepare() {\n\t\tedgeCnt = 1;\n\t\tdfnCnt = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[edgeCnt] = head[u];\n\t\tto[edgeCnt] = v;\n\t\thead[u] = edgeCnt++;\n\t}\n\n\tpublic static int dfs(int u) {\n\t\tint i = ++dfnCnt;\n\t\tdfn[u] = i;\n\t\tsize[i] = 1;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tsize[i] += dfs(v);\n\t\t}\n\t\treturn size[i];\n\t}\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tvalue[dfn[i]] = (double) strength[i] - x * cost[i];\n\t\t}\n\t\tfor (int j = 1; j <= k; j++) {\n\t\t\tdp[dfnCnt + 1][j] = NA;\n\t\t}\n\t\tfor (int i = dfnCnt; i >= 2; i--) {\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i + size[i]][j], value[i] + dp[i + 1][j - 1]);\n\t\t\t}\n\t\t}\n\t\treturn dp[2][k] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcost[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tstrength[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\taddEdge((int) in.nval, i);\n\t\t}\n\t\tdfs(0);\n\t\tdouble l = 0, r = LIMIT, x;\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tl = x;\n\t\t\t} else {\n\t\t\t\tr = x;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.3f\\n", l);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Other5.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e18c97e4-0a87-4f49-be8a-2efa083923a1	9230e5a9-7dbf-4d07-8d0b-12818e23537d	java	package class144;\n\n// 杨辉三角\n// 给定数字n，打印杨辉三角的前n行\n// 1 <= n <= 20\n// 测试链接 : https://www.luogu.com.cn/problem/P5732\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_PascalTriangle {\n\n\tpublic static int MAXN = 20;\n\n\tpublic static long[][] tri = new long[MAXN][MAXN];\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\ttri[i][0] = tri[i][i] = 1;\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tfor (int j = 1; j < i; j++) {\n\t\t\t\ttri[i][j] = tri[i - 1][j] + tri[i - 1][j - 1];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j <= i; j++) {\n\t\t\t\tout.print(tri[i][j] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_PascalTriangle.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
155e7015-9f1a-4445-bd78-e18addf93c7d	9230e5a9-7dbf-4d07-8d0b-12818e23537d	java	package class144;\n\n// 计算系数\n// 多项式为，(ax + by)的k次方，其中a、b、k为常数\n// 计算这个多项式展开后，x的n次方 * y的m次方，这一项的系数\n// 0 <= k <= 1000\n// 0 <= a、b <= 10^6\n// n + m == k\n// 测试链接 : https://www.luogu.com.cn/problem/P1313\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_CalculateCoefficients {\n\n\tpublic static int MAXK = 1001;\n\n\tpublic static int MOD = 10007;\n\n\t// fac[i]代表 i! 在 %MOD 意义下的余数\n\tpublic static long[] fac = new long[MAXK + 1];\n\n\t// inv[i]代表 i! 在 %MOD 意义下的逆元\n\tpublic static long[] inv = new long[MAXK + 1];\n\n\tpublic static int a, b, k, n, m;\n\n\t// 来自讲解098，乘法快速幂，x的p次方 % MOD\n\tpublic static long power(long x, int p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 来自讲解099，生成阶乘表和逆元表\n\tpublic static void build() {\n\t\t// 阶乘表线性递推\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= MAXK; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\t// 逆元表线性递推\n\t\tinv[MAXK] = power(fac[MAXK], MOD - 2);\n\t\tfor (int i = MAXK - 1; i >= 0; i--) {\n\t\t\tinv[i] = ((long) (i + 1) * inv[i + 1]) % MOD;\n\t\t}\n\t}\n\n\t// 组合公式\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv[k]) % MOD) * inv[n - k]) % MOD;\n\t}\n\n\tpublic static long compute() {\n\t\tbuild();\n\t\treturn (((power(a, n) * power(b, m)) % MOD) * c(k, k - n)) % MOD;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken(); a = (int) in.nval;\n\t\tin.nextToken(); b = (int) in.nval;\n\t\tin.nextToken(); k = (int) in.nval;\n\t\tin.nextToken(); n = (int) in.nval;\n\t\tin.nextToken(); m = (int) in.nval;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_CalculateCoefficients.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
341b38ef-5b7a-460a-a989-4f09b3f8c505	9230e5a9-7dbf-4d07-8d0b-12818e23537d	java	package class144;\n\n// 组合数问题\n// 组合公式c(i, j)，表示从i个物品中选出j个物品的方案数\n// 如果该数值是k的整数倍，那么称(i, j)是一个合法对\n// 给定具体的一组数字n和m，当i和j满足：0 <= i <= n，0 <= j <= min(i, m)\n// 返回有多少合法对\n// 一共有t组测试，所有测试的k都为同一个值\n// 每组测试给定n和m，打印每组测试的答案\n// 1 <= t <= 10^4\n// 2 <= k <= 21\n// 0 <= n、m <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P2822\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_CombinationNumber {\n\n\tpublic static int MAXV = 2000;\n\n\tpublic static int MAXN = 2002;\n\n\tpublic static int[][] c = new int[MAXN][MAXN];\n\n\tpublic static int[][] f = new int[MAXN][MAXN];\n\n\tpublic static int[][] sum = new int[MAXN][MAXN];\n\n\tpublic static int t, k, n, m;\n\n\tpublic static void build() {\n\t\tfor (int i = 0; i <= MAXV; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % k;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= MAXV; i++) {\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tf[i][j] = c[i][j] % k == 0 ? 1 : 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 2; i <= MAXV; i++) {\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tsum[i][j] = sum[i][j - 1] + sum[i - 1][j] - sum[i - 1][j - 1] + f[i][j];\n\t\t\t}\n\t\t\tsum[i][i + 1] = sum[i][i];\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tt = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tif (m > n) {\n\t\t\t\tout.println(sum[n][n]);\n\t\t\t} else {\n\t\t\t\tout.println(sum[n][m]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n}\n	模板：Code03_CombinationNumber.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
ad1cfa46-93cf-4a21-a4b3-30a399a167b7	9230e5a9-7dbf-4d07-8d0b-12818e23537d	java	package class144;\n\n// 分割的方法数\n// 给定一个长度为n的数组A, 将其分割成数组B和数组C，满足A[i] = B[i] + C[i]\n// 也就是一个数字分成两份，然后各自进入B和C，要求B[i], C[i] >= 1\n// 同时要求，B数组从左到右不能降序，C数组从左到右不能升序\n// 比如，A = { 5, 4, 5 }，一种有效的划分，B = { 2, 2, 3 }，C = { 3, 2, 2 }\n// 返回有多少种有效的划分方式\n// 1 <= n <= 10^7\n// 1 <= A[i] <= 10^7\n// 最终结果可能很大，答案对 1000000007 取模\n// 来自真实大厂笔试题，该实现为对数器版本\n// 有同学找到了测试链接，就是Code04_SplitWays2文件\npublic class Code04_SplitWays1 {\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int ways1(int[] arr) {\n\t\tint ans = 0;\n\t\tfor (int b = 1, c = arr[0] - 1; b < arr[0]; b++, c--) {\n\t\t\tans += f(arr, 1, b, c);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int f(int[] arr, int i, int preb, int prec) {\n\t\tif (i == arr.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int b = 1, c = arr[i] - 1; b < arr[i]; b++, c--) {\n\t\t\tif (preb <= b && prec >= c) {\n\t\t\t\tans += f(arr, i + 1, b, c);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 正式方法\n\t// 转化成杨辉三角\n\tpublic static final int MOD = 1000000007;\n\n\tpublic static int ways2(int[] arr) {\n\t\tint n = arr.length;\n\t\tint k = arr[0] - 1;\n\t\tfor (int i = 1; i < n && k > 0; i++) {\n\t\t\tif (arr[i - 1] > arr[i]) {\n\t\t\t\tk -= arr[i - 1] - arr[i];\n\t\t\t}\n\t\t}\n\t\tif (k <= 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn c(k + n - 1, n);\n\t}\n\n\t// 组合公式\n\tpublic static int c(int n, int k) {\n\t\tlong fac = 1;\n\t\tlong inv1 = 1;\n\t\tlong inv2 = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfac = (fac * i) % MOD;\n\t\t\tif (i == k) {\n\t\t\t\tinv1 = power(fac, MOD - 2); // 费马小定理求逆元\n\t\t\t}\n\t\t\tif (i == n - k) {\n\t\t\t\tinv2 = power(fac, MOD - 2); // 费马小定理求逆元\n\t\t\t}\n\t\t}\n\t\treturn (int) ((((fac * inv1) % MOD) * inv2) % MOD);\n\t}\n\n\t// 乘法快速幂\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("功能测试开始");\n\t\tint N = 10;\n\t\tint V = 20;\n\t\tint test = 20000;\n\t\tfor (int i = 0; i < test; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[] arr = randomArray(n, V);\n\t\t\tint ans1 = ways1(arr);\n\t\t\tint ans2 = ways2(arr);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("功能测试结束");\n\n\t\tSystem.out.println("==========");\n\n\t\tSystem.out.println("性能测试开始");\n\t\tint n = 10000000;\n\t\tint v = 10000000;\n\t\tlong start, end;\n\t\tint[] arr = new int[n];\n\t\tSystem.out.println("随机生成的数据测试");\n\t\tSystem.out.println("数组长度 : " + n);\n\t\tSystem.out.println("数值范围 : [" + 1 + "," + v + "]");\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\tstart = System.currentTimeMillis();\n\t\tways2(arr);\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("运行时间 : " + (end - start) + " 毫秒");\n\n\t\tSystem.out.println();\n\n\t\tSystem.out.println("运行最慢的数据测试");\n\t\tSystem.out.println("数组长度 : " + n);\n\t\tSystem.out.println("数值都是 : " + v);\n\t\tSystem.out.println("这种情况其实是复杂度最高的情况");\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = v;\n\t\t}\n\t\tstart = System.currentTimeMillis();\n\t\tways2(arr);\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("运行时间 : " + (end - start) + " 毫秒");\n\t\tSystem.out.println("性能测试结束");\n\t}\n\n}\n	模板：Code04_SplitWays1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
446219a4-7598-4115-8804-87bb2c2255b0	9230e5a9-7dbf-4d07-8d0b-12818e23537d	java	package class144;\n\n// 分割的方法数\n// 有同学找到了测试链接，题意几乎一样，而且数据量小很多\n// 唯一的区别是：\n// 课上讲的题意，单独的3可以分裂成(1, 2)、(2, 1)，一共两种方式\n// 测试链接题意，单独的3可以分裂成(0, 3)、(1, 2)、(2, 1)、(3, 0)，一共四种方式\n// 也就是对单独的v来说，课上讲的题意，分裂方式为v-1种。测试链接题意，分裂方式为v+1种\n// 别的没有任何区别，实现代码中唯一有注释的那行，是仅有的改动\n// 测试链接 : https://leetcode.cn/problems/find-the-count-of-monotonic-pairs-ii/\npublic class Code04_SplitWays2 {\n\n\tpublic static final int MOD = 1000000007;\n\n\tpublic static int countOfPairs(int[] arr) {\n\t\tint n = arr.length;\n\t\t// 原始题意，k = arr[0] - 1，这里改成，k = arr[0] + 1\n\t\t// 其他代码毫无区别\n\t\tint k = arr[0] + 1;\n\t\tfor (int i = 1; i < n && k > 0; i++) {\n\t\t\tif (arr[i - 1] > arr[i]) {\n\t\t\t\tk -= arr[i - 1] - arr[i];\n\t\t\t}\n\t\t}\n\t\tif (k <= 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn c(k + n - 1, n);\n\t}\n\n\tpublic static int c(int n, int k) {\n\t\tlong fac = 1;\n\t\tlong inv1 = 1;\n\t\tlong inv2 = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfac = (fac * i) % MOD;\n\t\t\tif (i == k) {\n\t\t\t\tinv1 = power(fac, MOD - 2);\n\t\t\t}\n\t\t\tif (i == n - k) {\n\t\t\t\tinv2 = power(fac, MOD - 2);\n\t\t\t}\n\t\t}\n\t\treturn (int) ((((fac * inv1) % MOD) * inv2) % MOD);\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code04_SplitWays2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
810c0231-9703-4907-8ba5-878d185fa482	8db00069-efb2-4b4d-b4c2-4a27025f4f6b	java	package class146;\n\n// 约瑟夫环问题\n// 一共有1~n这些点，组成首尾相接的环\n// 从1号点从数字1开始报数，哪个节点报到数字k，就删除该节点\n// 然后下一个节点从数字1开始重新报数，最终环上会剩下一个节点\n// 返回该节点的编号\n// 1 <= n, k <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8671\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_Joseph {\n\n\tpublic static int compute(int n, int k) {\n\t\tint ans = 1;\n\t\tfor (int c = 2; c <= n; c++) {\n\t\t\tans = (ans + k - 1) % c + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint k = (int) in.nval;\n\t\tout.println(compute(n, k));\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_Joseph.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
a5210c04-5f22-4f51-8c0c-7f18e769d183	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 信封问题(错排问题)\n// 一共n个人，每个人都写了一封信\n// 每个人必须寄出一封信，每个人必须收到一封信，并且不能自己寄给自己\n// 返回一共有多少种寄信的方法\n// 1 <= n <= 20\n// 测试链接 : https://www.luogu.com.cn/problem/P1595\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_Derangement {\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\t// out.println(ways1(n));\n\t\tout.println(ways2(n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\t// 普通动态规划的方法\n\tpublic static long ways1(int n) {\n\t\tlong[] dp = new long[n + 1];\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (i == 1) {\n\t\t\t\tdp[i] = 0;\n\t\t\t} else if (i == 2) {\n\t\t\t\tdp[i] = 1;\n\t\t\t} else {\n\t\t\t\tdp[i] = (i - 1) * (dp[i - 1] + dp[i - 2]);\n\t\t\t}\n\t\t}\n\t\treturn dp[n];\n\t}\n\n\t// 二项式反演的方法\n\tpublic static long ways2(int n) {\n\t\tlong facn = 1; // n!\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfacn *= i;\n\t\t}\n\t\tlong ans = facn; // i = 0时的项\n\t\tlong faci = 1; // i!\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t// i = 1...n\n\t\t\t// (-1)的i次方 * (n! / i!)\n\t\t\tfaci = faci * i;\n\t\t\tif ((i & 1) == 0) {\n\t\t\t\tans += facn / faci;\n\t\t\t} else {\n\t\t\t\tans -= facn / faci;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n	模板：Code01_Derangement.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
83370fbf-5add-49b7-a867-9eb21842d6bd	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 集合计数\n// 一共有n个不同的数，能构成2^n个不同集合\n// 在2^n个集合中挑出若干个集合，至少挑一个\n// 希望这若干个集合的交集，正好有k个数\n// 返回挑选集合的方案数，答案对 1000000007 取模\n// 1 <= n <= 10^6\n// 0 <= k <= n\n// 测试链接 : https://www.luogu.com.cn/problem/P10596\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_SetCounting {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int MOD = 1000000007;\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[] inv = new long[MAXN];\n\n\tpublic static long[] g = new long[MAXN];\n\n\tpublic static int n, k;\n\n\tpublic static void build() {\n\t\tfac[0] = inv[0] = 1;\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\tinv[n] = power(fac[n], MOD - 2);\n\t\tfor (int i = n - 1; i >= 1; i--) {\n\t\t\tinv[i] = ((long) (i + 1) * inv[i + 1]) % MOD;\n\t\t}\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv[k]) % MOD) * inv[n - k]) % MOD;\n\t}\n\n\tpublic static long compute() {\n\t\tbuild();\n\t\tlong tmp = 2;\n\t\tfor (int i = n; i >= 0; i--) {\n\t\t\tg[i] = tmp;\n\t\t\ttmp = tmp * tmp % MOD;\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\t// -1 和 (MOD-1) 同余\n\t\t\tg[i] = (g[i] + MOD - 1) * c(n, i) % MOD;\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = k; i <= n; i++) {\n\t\t\tif (((i - k) & 1) == 0) {\n\t\t\t\tans = (ans + c(i, k) * g[i] % MOD) % MOD;\n\t\t\t} else {\n\t\t\t\t// -1 和 (MOD-1) 同余\n\t\t\t\tans = (ans + c(i, k) * g[i] % MOD * (MOD - 1) % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_SetCounting.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
8ad68aaf-6ca5-4b1a-93c0-a47389d86fc1	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 分特产\n// 一共有m种特产，arr[i]表示i种特产有几个\n// 一共有n个同学，每个同学至少要得到一个特产\n// 返回分配特产的方法数，答案对 1000000007 取模\n// 0 <= n、m <= 1000\n// 0 <= arr[i] <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/P5505\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_DistributeSpecialties {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int MAXK = MAXN * 2;\n\n\tpublic static int MOD = 1000000007;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static long[][] c = new long[MAXK][MAXK];\n\n\tpublic static long[] g = new long[MAXN];\n\n\tpublic static int n, k, m;\n\n\tpublic static long compute() {\n\t\tfor (int i = 0; i <= k; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % MOD;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tg[i] = c[n][i];\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tg[i] = (int) ((g[i] * c[arr[j] + n - i - 1][n - i - 1]) % MOD);\n\t\t\t}\n\t\t}\n\t\tg[n] = 0;\n\t\tlong ans = 0;\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tif ((i & 1) == 0) {\n\t\t\t\tans = (ans + g[i]) % MOD;\n\t\t\t} else {\n\t\t\t\t// -1 和 (MOD-1) 同余\n\t\t\t\tans = (ans + g[i] * (MOD - 1) % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tk = n * 2;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_DistributeSpecialties.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
e2bc1f27-3742-4396-aec4-5089eb8df928	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 已经没有什么好害怕的了\n// 给定两个长度为n的数组，a[i]表示第i个糖果的能量，b[i]表示第i个药片的能量\n// 所有能量数值都不相同，每一个糖果要选一个药片进行配对\n// 如果配对之后，糖果能量 > 药片能量，称为糖果大的配对\n// 如果配对之后，糖果能量 < 药片能量，称为药片大的配对\n// 希望做到，糖果大的配对数量 = 药片大的配对数量 + k\n// 返回配对方法数，答案对 1000000009 取模\n// 举例，a = [5, 35, 15, 45]，b = [40, 20, 10, 30]，k = 2，返回4，因为有4种配对方法\n// (5-40，35-20，15-10，45-30)、(5-40，35-30，15-10，45-20)\n// (5-20，35-30，15-10，45-40)、(5-30，35-20，15-10，45-40)\n// 1 <= n <= 2000\n// 0 <= k <= n\n// 测试链接 : https://www.luogu.com.cn/problem/P4859\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_NothingFear {\n\n\tpublic static int MAXN = 2001;\n\n\tpublic static int MOD = 1000000009;\n\n\tpublic static int n, k;\n\n\tpublic static int[] a = new int[MAXN];\n\n\tpublic static int[] b = new int[MAXN];\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[][] c = new long[MAXN][MAXN];\n\n\tpublic static long[] small = new long[MAXN];\n\n\tpublic static long[][] dp = new long[MAXN][MAXN];\n\n\tpublic static long[] g = new long[MAXN];\n\n\tpublic static void build() {\n\t\tfac[0] = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfac[i] = fac[i - 1] * i % MOD;\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tbuild();\n\t\tArrays.sort(a, 1, n + 1);\n\t\tArrays.sort(b, 1, n + 1);\n\t\tfor (int i = 1, cnt = 0; i <= n; i++) {\n\t\t\twhile (cnt + 1 <= n && b[cnt + 1] < a[i]) {\n\t\t\t\tcnt++;\n\t\t\t}\n\t\t\tsmall[i] = cnt;\n\t\t}\n\t\tdp[0][0] = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdp[i][0] = dp[i - 1][0];\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tdp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1] * (small[i] - j + 1) % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tg[i] = fac[n - i] * dp[n][i] % MOD;\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = k; i <= n; i++) {\n\t\t\tif (((i - k) & 1) == 0) {\n\t\t\t\tans = (ans + c[i][k] * g[i] % MOD) % MOD;\n\t\t\t} else {\n\t\t\t\t// -1 和 (MOD-1) 同余\n\t\t\t\tans = (ans + c[i][k] * g[i] % MOD * (MOD - 1) % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\ta[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tb[i] = (int) in.nval;\n\t\t}\n\t\tif (((n + k) & 1) == 0) {\n\t\t\tk = (n + k) / 2;\n\t\t\tout.println(compute());\n\t\t} else {\n\t\t\tout.println(0);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code04_NothingFear.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
340bc547-2022-4a72-acb0-e88970993982	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 游戏(递归版)\n// 一共有n个节点，n <= 5000，n为偶数，其中有m个点属于小A，有m个点属于小B，m为n的一半\n// 给定n-1条边，节点之间组成一颗树，1号节点是根节点\n// 给定长度为n的数组arr，arr[i]的值表示i号节点由谁拥有，0为小A拥有，1为小B拥有\n// 游戏有m回合，每回合都有胜负，两人需要选择一个自己拥有、但之前没选过的点，作为本回合当前点\n// 小A当前点的子树里有小B当前点，则小A胜；小B当前点的子树里有小A当前点，则小B胜；否则平局\n// 返回m回合里能出现k次非平局的游戏方法数，打印k=0..m时的所有答案，对 998244353 取模\n// 两场游戏视为不同的定义：当且仅当存在小A拥有的点x，小B在小A选择x的那个回合所选择的点不同\n// 测试链接 : https://www.luogu.com.cn/problem/P6478\n// 提交以下的code，提交时请把类名改成"Main"，注意dfs是递归函数\n// C++的同学可以全部通过，java的同学有时可以全部通过，有时因为递归展开太深而爆栈\n// dfs从递归版改迭代版的实现，请看Code05_Game2文件\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code05_Game1 {\n\n\tpublic static final int MAXN = 5001;\n\n\tpublic static final int MOD = 998244353;\n\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[][] c = new long[MAXN][MAXN];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// dfs需要\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[][] belong = new int[MAXN][2];\n\n\tpublic static long[][] dp = new long[MAXN][MAXN];\n\n\tpublic static long[] backup = new long[MAXN];\n\n\t// 反演需要\n\tpublic static long[] g = new long[MAXN];\n\n\t// 最后答案\n\tpublic static long[] f = new long[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tfac[0] = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tfac[i] = fac[i - 1] * i % MOD;\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 递归版\n\tpublic static void dfs(int u, int fa) {\n\t\tsize[u] = 1;\n\t\tbelong[u][arr[u]] = 1;\n\t\tdp[u][0] = 1;\n\t\t// 首先计算不包含头节点的方法数\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u);\n\t\t\t\t// 之前所有子树结合的计算结果，拷贝进backup\n\t\t\t\tfor (int i = 0; i <= Math.min(size[u] / 2, m); i++) {\n\t\t\t\t\tbackup[i] = dp[u][i];\n\t\t\t\t\tdp[u][i] = 0;\n\t\t\t\t}\n\t\t\t\t// 树型dp的枚举行为利用子树的节点数做上限进行复杂度优化\n\t\t\t\tfor (int l = 0; l <= Math.min(size[u] / 2, m); l++) {\n\t\t\t\t\tfor (int r = 0; r <= Math.min(size[v] / 2, m - l); r++) {\n\t\t\t\t\t\tdp[u][l + r] = (dp[u][l + r] + backup[l] * dp[v][r] % MOD) % MOD;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tsize[u] += size[v];\n\t\t\t\tbelong[u][0] += belong[v][0];\n\t\t\t\tbelong[u][1] += belong[v][1];\n\t\t\t}\n\t\t}\n\t\t// 最后计算包含头节点的方法数\n\t\t// 更新dp[u][i]，i可以把上限定为min(对手拥有的节点数，m)\n\t\t// u为头的子树中，对手有几个节点\n\t\tint num = belong[u][arr[u] ^ 1];\n\t\t// 不包含头节点的方法数，拷贝到backup\n\t\tfor (int i = 1; i <= Math.min(num, m); i++) {\n\t\t\tbackup[i] = dp[u][i];\n\t\t}\n\t\t// 计算包含头节点的方法数，累加上\n\t\tfor (int i = 1; i <= Math.min(num, m); i++) {\n\t\t\tdp[u][i] = (dp[u][i] + backup[i - 1] * (num - i + 1) % MOD) % MOD;\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tdfs(1, 0); // dfs是递归版\n\t\tfor (int i = 0; i <= m; i++) {\n\t\t\tg[i] = dp[1][i] * fac[m - i] % MOD;\n\t\t}\n\t\tfor (int k = 0; k <= m; k++) {\n\t\t\tfor (int i = k; i <= m; i++) {\n\t\t\t\tif (((i - k) & 1) == 0) {\n\t\t\t\t\tf[k] = (f[k] + c[i][k] * g[i] % MOD) % MOD;\n\t\t\t\t} else {\n\t\t\t\t\t// -1 和 (MOD-1) 同余\n\t\t\t\t\tf[k] = (f[k] + c[i][k] * g[i] % MOD * (MOD - 1) % MOD) % MOD;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = n >> 1;\n\t\tbuild();\n\t\tString str = io.next();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = str.charAt(i - 1) - '0';\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tcompute();\n\t\tfor (int k = 0; k <= m; k++) {\n\t\t\tio.println(f[k]);\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}	模板：Code05_Game1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
92a9e862-6555-476e-bfbe-34525d946caa	429eb6f0-cac9-49bc-90f0-febcb38cd4dc	java	package class145;\n\n// 游戏(迭代版)\n// 一共有n个节点，n <= 5000，n为偶数，其中有m个点属于小A，有m个点属于小B，m为n的一半\n// 给定n-1条边，节点之间组成一颗树，1号节点是根节点\n// 给定长度为n的数组arr，arr[i]的值表示i号节点由谁拥有，0为小A拥有，1为小B拥有\n// 游戏有m回合，每回合都有胜负，两人需要选择一个自己拥有、但之前没选过的点，作为本回合当前点\n// 小A当前点的子树里有小B当前点，则小A胜；小B当前点的子树里有小A当前点，则小B胜；否则平局\n// 返回m回合里能出现k次非平局的游戏方法数，打印k=0..m时的所有答案，对 998244353 取模\n// 两场游戏视为不同的定义：当且仅当存在小A拥有的点x，小B在小A选择x的那个回合所选择的点不同\n// 测试链接 : https://www.luogu.com.cn/problem/P6478\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code05_Game2 {\n\n\tpublic static final int MAXN = 5001;\n\n\tpublic static final int MOD = 998244353;\n\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[][] c = new long[MAXN][MAXN];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cnt;\n\n\t// dfs需要\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[][] belong = new int[MAXN][2];\n\n\tpublic static long[][] dp = new long[MAXN][MAXN];\n\n\tpublic static long[] backup = new long[MAXN];\n\n\t// 反演需要\n\tpublic static long[] g = new long[MAXN];\n\n\t// 最后答案\n\tpublic static long[] f = new long[MAXN];\n\n\tpublic static void build() {\n\t\tcnt = 1;\n\t\tfac[0] = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tfac[i] = fac[i - 1] * i % MOD;\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 迭代版\n\t// ufe是为了实现迭代版而准备的栈\n\t// 不会改，看讲解118，讲了怎么从递归版改成迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize, u, fa, e;\n\n\tpublic static void push(int u, int fa, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = fa;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tfa = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\t// 迭代版\n\tpublic static void dfs(int root) {\n\t\tstackSize = 0;\n\t\tpush(root, 0, -1);\n\t\tint v, num;\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) { // 第一次来到当前节点，设置初始值\n\t\t\t\tsize[u] = 1;\n\t\t\t\tbelong[u][arr[u]] = 1;\n\t\t\t\tdp[u][0] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else { // 不是第一次来到当前节点\n\t\t\t\tv = to[e];\n\t\t\t\tif (v != fa) { // 之前的孩子，dfs过程计算完了，所以用之前孩子的信息，更新当前节点的信息\n\t\t\t\t\tfor (int i = 0; i <= Math.min(size[u] / 2, m); i++) {\n\t\t\t\t\t\tbackup[i] = dp[u][i];\n\t\t\t\t\t\tdp[u][i] = 0;\n\t\t\t\t\t}\n\t\t\t\t\tfor (int l = 0; l <= Math.min(size[u] / 2, m); l++) {\n\t\t\t\t\t\tfor (int r = 0; r <= Math.min(size[v] / 2, m - l); r++) {\n\t\t\t\t\t\t\tdp[u][l + r] = (dp[u][l + r] + backup[l] * dp[v][r] % MOD) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tsize[u] += size[v];\n\t\t\t\t\tbelong[u][0] += belong[v][0];\n\t\t\t\t\tbelong[u][1] += belong[v][1];\n\t\t\t\t}\n\t\t\t\t// 来到去往下一个孩子的边\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) { // 还有后续子树\n\t\t\t\tpush(u, fa, e);\n\t\t\t\tif (to[e] != fa) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else { // 没有后续子树，最后计算包含头节点的方法数\n\t\t\t\tnum = belong[u][arr[u] ^ 1];\n\t\t\t\tfor (int i = 1; i <= Math.min(num, m); i++) {\n\t\t\t\t\tbackup[i] = dp[u][i];\n\t\t\t\t}\n\t\t\t\tfor (int i = 1; i <= Math.min(num, m); i++) {\n\t\t\t\t\tdp[u][i] = (dp[u][i] + backup[i - 1] * (num - i + 1) % MOD) % MOD;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void compute() {\n\t\tdfs(1); // dfs是迭代版\n\t\tfor (int i = 0; i <= m; i++) {\n\t\t\tg[i] = dp[1][i] * fac[m - i] % MOD;\n\t\t}\n\t\tfor (int k = 0; k <= m; k++) {\n\t\t\tfor (int i = k; i <= m; i++) {\n\t\t\t\tif (((i - k) & 1) == 0) {\n\t\t\t\t\tf[k] = (f[k] + c[i][k] * g[i] % MOD) % MOD;\n\t\t\t\t} else {\n\t\t\t\t\tf[k] = (f[k] + c[i][k] * g[i] % MOD * (MOD - 1) % MOD) % MOD;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = n >> 1;\n\t\tbuild();\n\t\tString str = io.next();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = str.charAt(i - 1) - '0';\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tcompute();\n\t\tfor (int k = 0; k <= m; k++) {\n\t\t\tio.println(f[k]);\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}	模板：Code05_Game2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
59a35732-3829-4f2a-bfc8-ceeabb9669e4	8db00069-efb2-4b4d-b4c2-4a27025f4f6b	java	package class146;\n\n// 康托展开\n// 数字从1到n，可以有很多排列，给出具体的一个排列，求该排列的名次，答案对 998244353 取模\n// 1 <= n <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P5367\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_CantorExpansion {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int MOD = 998244353;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 阶乘余数表\n\tpublic static int[] fac = new int[MAXN];\n\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static int n;\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static int sum(int i) {\n\t\tint ans = 0;\n\t\twhile (i > 0) {\n\t\t\tans = (ans + tree[i]) % MOD;\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tfac[0] = 1;\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tfac[i] = (int) ((long) fac[i - 1] * i % MOD);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(i, 1);\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans = (ans + (long) sum(arr[i] - 1) * fac[n - i] % MOD) % MOD;\n\t\t\tadd(arr[i], -1);\n\t\t}\n\t\t// 求的排名从0开始，但是题目要求从1开始，所以最后+1再返回\n\t\tans = (ans + 1) % MOD;\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_CantorExpansion.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
0022df56-7bd8-496a-be45-29833d62a708	8db00069-efb2-4b4d-b4c2-4a27025f4f6b	java	package class146;\n\n// 逆康托展开\n// 数字从1到n，可以有很多排列，给定一个长度为n的数组s，表示具体的一个排列\n// 求出这个排列的排名假设为x，打印第x+m名的排列是什么\n// 1 <= n <= 10^5\n// 1 <= m <= 10^15\n// 题目保证s是一个由1~n数字组成的正确排列，题目保证x+m不会超过排列的总数\n// 测试链接 : https://www.luogu.com.cn/problem/U72177\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_InverseCantorExpansion {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\t// 线段树\n\t// 这种使用线段树的方式叫线段树二分\n\t// 讲解169的题目1，也涉及线段树二分\n\tpublic static int[] sum = new int[MAXN << 2];\n\n\tpublic static int n;\n\n\tpublic static long m;\n\n\t// 初始化线段树，单点范围的初始累加和为1，认为所有数字都可用\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = 1;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\t}\n\t}\n\n\t// 单点jobi上，增加jobv，因为是单点更新，所以不需要建立懒更新机制\n\tpublic static void add(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tadd(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tadd(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\t}\n\t}\n\n\t// 查询jobl~jobr范围的累加和\n\tpublic static int sum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += sum(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += sum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 线段树上找到第k名的是什么，找到后删掉词频，返回的过程修改累加和\n\tpublic static int getAndDelete(int k, int l, int r, int i) {\n\t\tint ans;\n\t\tif (l == r) {\n\t\t\tsum[i]--;\n\t\t\tans = l;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (sum[i << 1] >= k) {\n\t\t\t\tans = getAndDelete(k, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tans = getAndDelete(k - sum[i << 1], mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void compute() {\n\t\t// 当前排列转化为阶乘进制的排名\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1, x; i <= n; i++) {\n\t\t\tx = (int) arr[i];\n\t\t\tif (x == 1) {\n\t\t\t\tarr[i] = 0;\n\t\t\t} else {\n\t\t\t\tarr[i] = sum(1, x - 1, 1, n, 1);\n\t\t\t}\n\t\t\tadd(x, -1, 1, n, 1);\n\t\t}\n\t\t// 当前排名加上m之后，得到新的排名，用阶乘进制表示\n\t\tarr[n] += m; // 最低位获得增加的幅度\n\t\tfor (int i = n; i >= 1; i--) {\n\t\t\t// 往上进位多少\n\t\t\tarr[i - 1] += arr[i] / (n - i + 1);\n\t\t\t// 当前位是多少\n\t\t\tarr[i] %= n - i + 1;\n\t\t}\n\t\t// 根据阶乘进制转化为具体的排列\n\t\tbuild(1, n, 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = getAndDelete((int) arr[i] + 1, 1, n, 1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (long) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tcompute();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(arr[i] + " ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}	模板：Code02_InverseCantorExpansion.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
04681d61-9539-4acf-9bce-d99d4528a9fb	8db00069-efb2-4b4d-b4c2-4a27025f4f6b	java	package class146;\n\n// 完美洗牌算法\n// 给定数组arr，给定某个范围arr[l..r]，该范围长度为n，n是偶数\n// 因为n是偶数，所以给定的范围可以分成左右两个部分，arr[l1, l2, ...lk, r1, r2, ...rk]\n// 请把arr[l..r]范围上的数字调整成arr[r1, l1, r2, l2, ... rk, lk]，其他位置的数字不变\n// 要求时间复杂度O(n)，额外空间复杂度O(1)，对数器验证\npublic class Code05_PerfectShuffle {\n\n\t// 申请额外空间的做法\n\t// 保证调整的范围是偶数长度\n\t// 为了测试\n\tpublic static void shuffle1(int[] arr, int l, int r) {\n\t\tint n = r - l + 1;\n\t\tint[] help = new int[n];\n\t\tfor (int l1 = l, r1 = (l + r) / 2 + 1, j = 0; j < n; l1++, r1++) {\n\t\t\thelp[j++] = arr[r1];\n\t\t\thelp[j++] = arr[l1];\n\t\t}\n\t\tfor (int i = l, j = 0; j < n; i++, j++) {\n\t\t\tarr[i] = help[j];\n\t\t}\n\t}\n\n\t// 正式方法\n\t// 完美洗牌算法\n\tpublic static int MAXN = 20;\n\n\tpublic static int[] start = new int[MAXN];\n\n\tpublic static int[] split = new int[MAXN];\n\n\tpublic static int size;\n\n\t// 保证调整的范围是偶数长度\n\tpublic static void shuffle2(int[] arr, int l, int r) {\n\t\tint n = r - l + 1;\n\t\tbuild(n);\n\t\tfor (int i = size, m; n > 0;) {\n\t\t\tif (split[i] <= n) {\n\t\t\t\tm = (l + r) / 2;\n\t\t\t\trotate(arr, l + split[i] / 2, m, m + split[i] / 2);\n\t\t\t\tcircle(arr, l, l + split[i] - 1, i);\n\t\t\t\tl += split[i];\n\t\t\t\tn -= split[i];\n\t\t\t} else {\n\t\t\t\ti--;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void build(int n) {\n\t\tsize = 0;\n\t\tfor (int s = 1, p = 2; p <= n; s *= 3, p = s * 3 - 1) {\n\t\t\tstart[++size] = s;\n\t\t\tsplit[size] = p;\n\t\t}\n\t}\n\n\tpublic static void rotate(int[] arr, int l, int m, int r) {\n\t\treverse(arr, l, m);\n\t\treverse(arr, m + 1, r);\n\t\treverse(arr, l, r);\n\t}\n\n\tpublic static void reverse(int[] arr, int l, int r) {\n\t\twhile (l < r) {\n\t\t\tswap(arr, l++, r--);\n\t\t}\n\t}\n\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\tpublic static void circle(int[] arr, int l, int r, int i) {\n\t\tfor (int j = 1, init, cur, next, curv, nextv; j <= i; j++) {\n\t\t\tinit = cur = l + start[j] - 1;\n\t\t\tnext = to(cur, l, r);\n\t\t\tcurv = arr[cur];\n\t\t\twhile (next != init) {\n\t\t\t\tnextv = arr[next];\n\t\t\t\tarr[next] = curv;\n\t\t\t\tcurv = nextv;\n\t\t\t\tcur = next;\n\t\t\t\tnext = to(cur, l, r);\n\t\t\t}\n\t\t\tarr[init] = curv;\n\t\t}\n\t}\n\n\tpublic static int to(int i, int l, int r) {\n\t\tif (i <= (l + r) >> 1) {\n\t\t\treturn i + (i - l + 1);\n\t\t} else {\n\t\t\treturn i - (r - i + 1);\n\t\t}\n\t}\n\n\t// 生成随机数组\n\t// 为了测试\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = (int) (Math.random() * v);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 拷贝数组\n\t// 为了测试\n\tpublic static int[] copyArray(int[] arr) {\n\t\tint n = arr.length;\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = arr[i];\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tint n = 10000;\n\t\tint v = 100000;\n\t\tint[] arr1 = randomArray(n, v);\n\t\tint[] arr2 = copyArray(arr1);\n\t\tint test = 50000;\n\t\tSystem.out.println("测试开始");\n\t\tfor (int i = 1, a, b, l, r; i <= test; i++) {\n\t\t\ta = (int) (Math.random() * n);\n\t\t\tb = (int) (Math.random() * n);\n\t\t\tl = Math.min(a, b);\n\t\t\tr = Math.max(a, b);\n\t\t\tif (((r - l + 1) & 1) == 0) {\n\t\t\t\tshuffle1(arr1, l, r);\n\t\t\t\tshuffle2(arr2, l, r);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tif (arr1[i] != arr2[i]) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n	模板：Code05_PerfectShuffle.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b348b6bf-fada-44d7-ae20-64385436ee06	8db00069-efb2-4b4d-b4c2-4a27025f4f6b	java	package class146;\n\n// 摇摆排序ii(满足全部进阶要求)\n// 给定一个数组arr，重新排列数组，确保满足：arr[0] < arr[1] > arr[2] < arr[3] > ...\n// 题目保证输入的数组一定有解，要求时间复杂度O(n)，额外空间复杂度O(1)\n// 测试链接 : https://leetcode.cn/problems/wiggle-sort-ii/\npublic class Code06_WiggleSortII {\n\n\t// 最优解\n\t// 时间复杂度O(n)，额外空间复杂度O(1)\n\tpublic static void wiggleSort(int[] arr) {\n\t\tint n = arr.length;\n\t\trandomizedSelect(arr, n, n / 2);\n\t\tif ((n & 1) == 0) {\n\t\t\tshuffle(arr, 0, n - 1);\n\t\t\treverse(arr, 0, n - 1);\n\t\t} else {\n\t\t\tshuffle(arr, 1, n - 1);\n\t\t}\n\t}\n\n\t// 随机选择算法，不会去看讲解024\n\t// 无序数组中找到，如果排序之后，在i位置的数x，顺便把数组调整为\n\t// 左边是小于x的部分    中间是等于x的部分    右边是大于x的部分\n\t// 时间复杂度O(n)，额外空间复杂度O(1)\n\tpublic static int randomizedSelect(int[] arr, int n, int i) {\n\t\tint ans = 0;\n\t\tfor (int l = 0, r = n - 1; l <= r;) {\n\t\t\tpartition(arr, l, r, arr[l + (int) (Math.random() * (r - l + 1))]);\n\t\t\tif (i < first) {\n\t\t\t\tr = first - 1;\n\t\t\t} else if (i > last) {\n\t\t\t\tl = last + 1;\n\t\t\t} else {\n\t\t\t\tans = arr[i];\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int first, last;\n\n\tpublic static void partition(int[] arr, int l, int r, int x) {\n\t\tfirst = l;\n\t\tlast = r;\n\t\tint i = l;\n\t\twhile (i <= last) {\n\t\t\tif (arr[i] == x) {\n\t\t\t\ti++;\n\t\t\t} else if (arr[i] < x) {\n\t\t\t\tswap(arr, first++, i++);\n\t\t\t} else {\n\t\t\t\tswap(arr, i, last--);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 完美洗牌算法\n\t// 时间复杂度O(n)，额外空间复杂度O(1)\n\tpublic static int MAXN = 20;\n\n\tpublic static int[] start = new int[MAXN];\n\n\tpublic static int[] split = new int[MAXN];\n\n\tpublic static int size;\n\n\tpublic static void shuffle(int[] arr, int l, int r) {\n\t\tint n = r - l + 1;\n\t\tbuild(n);\n\t\tfor (int i = size, m; n > 0;) {\n\t\t\tif (split[i] <= n) {\n\t\t\t\tm = (l + r) / 2;\n\t\t\t\trotate(arr, l + split[i] / 2, m, m + split[i] / 2);\n\t\t\t\tcircle(arr, l, l + split[i] - 1, i);\n\t\t\t\tl += split[i];\n\t\t\t\tn -= split[i];\n\t\t\t} else {\n\t\t\t\ti--;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void build(int n) {\n\t\tsize = 0;\n\t\tfor (int s = 1, p = 2; p <= n; s *= 3, p = s * 3 - 1) {\n\t\t\tstart[++size] = s;\n\t\t\tsplit[size] = p;\n\t\t}\n\t}\n\n\tpublic static void rotate(int[] arr, int l, int m, int r) {\n\t\treverse(arr, l, m);\n\t\treverse(arr, m + 1, r);\n\t\treverse(arr, l, r);\n\t}\n\n\tpublic static void reverse(int[] arr, int l, int r) {\n\t\twhile (l < r) {\n\t\t\tswap(arr, l++, r--);\n\t\t}\n\t}\n\n\tpublic static void swap(int[] arr, int i, int j) {\n\t\tint tmp = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = tmp;\n\t}\n\n\tpublic static void circle(int[] arr, int l, int r, int i) {\n\t\tfor (int j = 1, init, cur, next, curv, nextv; j <= i; j++) {\n\t\t\tinit = cur = l + start[j] - 1;\n\t\t\tnext = to(cur, l, r);\n\t\t\tcurv = arr[cur];\n\t\t\twhile (next != init) {\n\t\t\t\tnextv = arr[next];\n\t\t\t\tarr[next] = curv;\n\t\t\t\tcurv = nextv;\n\t\t\t\tcur = next;\n\t\t\t\tnext = to(cur, l, r);\n\t\t\t}\n\t\t\tarr[init] = curv;\n\t\t}\n\t}\n\n\tpublic static int to(int i, int l, int r) {\n\t\tif (i <= (l + r) >> 1) {\n\t\t\treturn i + (i - l + 1);\n\t\t} else {\n\t\t\treturn i - (r - i + 1);\n\t\t}\n\t}\n\n}\n	模板：Code06_WiggleSortII.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
155cb67f-9b27-4e4b-abf6-f11a01f1ae52	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 卡特兰数模版\n// 进栈顺序规定为1、2、3..n，返回有多少种不同的出栈顺序\n// 测试题目的数据量很小，得到的卡特兰数没有多大，不需要取模处理\n// 但是请假设，当n比较大时，卡特兰数是很大的，答案对 1000000007 取模\n// 测试链接 : https://www.luogu.com.cn/problem/P1044\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_Catalan {\n\n\tpublic static int MOD = 1000000007;\n\n\tpublic static int MAXN = 1000001;\n\n\t// 阶乘余数表\n\tpublic static long[] fac = new long[MAXN];\n\n\t// 阶乘逆元表\n\tpublic static long[] inv1 = new long[MAXN];\n\n\t// 连续数逆元表\n\tpublic static long[] inv2 = new long[MAXN];\n\n\t// 来自讲解099，题目3，生成阶乘余数表、阶乘逆元表\n\tpublic static void build1(int n) {\n\t\tfac[0] = inv1[0] = 1;\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\tinv1[n] = power(fac[n], MOD - 2);\n\t\tfor (int i = n - 1; i >= 1; i--) {\n\t\t\tinv1[i] = ((long) (i + 1) * inv1[i + 1]) % MOD;\n\t\t}\n\t}\n\n\t// 来自讲解099，题目2，生成连续数逆元表\n\tpublic static void build2(int n) {\n\t\tinv2[1] = 1;\n\t\tfor (int i = 2; i <= n + 1; i++) {\n\t\t\tinv2[i] = MOD - inv2[MOD % i] * (MOD / i) % MOD;\n\t\t}\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv1[k]) % MOD) * inv1[n - k]) % MOD;\n\t}\n\n\t// 公式1\n\tpublic static long compute1(int n) {\n\t\tbuild1(2 * n);\n\t\treturn (c(2 * n, n) - c(2 * n, n - 1) + MOD) % MOD;\n\t}\n\n\t// 公式2\n\tpublic static long compute2(int n) {\n\t\tbuild1(2 * n);\n\t\treturn c(2 * n, n) * power(n + 1, MOD - 2) % MOD;\n\t}\n\n\t// 公式3\n\tpublic static long compute3(int n) {\n\t\tbuild2(n);\n\t\tlong[] f = new long[n + 1];\n\t\tf[0] = f[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tf[i] = f[i - 1] * (4 * i - 2) % MOD * inv2[i + 1] % MOD;\n\t\t}\n\t\treturn f[n];\n\t}\n\n\t// 公式4\n\tpublic static long compute4(int n) {\n\t\tlong[] f = new long[n + 1];\n\t\tf[0] = f[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfor (int l = 0, r = i - 1; l < i; l++, r--) {\n\t\t\t\tf[i] = (f[i] + f[l] * f[r] % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\treturn f[n];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tout.println(compute1(n));\n//\t\tout.println(compute2(n));\n//\t\tout.println(compute3(n));\n//\t\tout.println(compute4(n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_Catalan.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
b4e10bc6-9c86-4362-9e1f-400debd04b29	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 圆上连线\n// 圆上有2n个点，这些点成对连接起来，形成n条线段，任意两条线段不能相交，返回连接的方法数\n// 注意！答案不对 10^9 + 7 取模！而是对 10^8 + 7 取模！\n// 1 <= n <= 2999\n// 测试链接 : https://www.luogu.com.cn/problem/P1976\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_CircleLine {\n\n\tpublic static int MOD = 100000007;\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[] inv = new long[MAXN];\n\n\tpublic static void build(int n) {\n\t\tfac[0] = inv[0] = 1;\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\tinv[n] = power(fac[n], MOD - 2);\n\t\tfor (int i = n - 1; i >= 1; i--) {\n\t\t\tinv[i] = ((long) (i + 1) * inv[i + 1]) % MOD;\n\t\t}\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv[k]) % MOD) * inv[n - k]) % MOD;\n\t}\n\n\t// 这里用公式1\n\tpublic static long compute(int n) {\n\t\tbuild(2 * n);\n\t\treturn (c(2 * n, n) - c(2 * n, n - 1) + MOD) % MOD;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tout.println(compute(n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_CircleLine.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
76455dfb-574d-4f3d-b800-ccea38456019	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 任意前缀上红多于黑\n// 有n个红和n个黑，要组成2n长度的数列，保证任意前缀上，红的数量 >= 黑的数量\n// 返回有多少种排列方法，答案对 100 取模\n// 1 <= n <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P1722\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_RedMore {\n\n\tpublic static int MOD = 100;\n\n\t// 因为取模的数字含有很多因子\n\t// 无法用费马小定理或者扩展欧几里得求逆元\n\t// 同时注意到n的范围并不大，直接使用公式4\n\tpublic static long compute(int n) {\n\t\tlong[] f = new long[n + 1];\n\t\tf[0] = f[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfor (int l = 0, r = i - 1; l < i; l++, r--) {\n\t\t\t\tf[i] = (f[i] + f[l] * f[r] % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t\treturn f[n];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tout.println(compute(n));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_RedMore.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c5c7d016-cd0f-427c-ae47-1e0a408bbbcc	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 不同结构的二叉树数量\n// 一共有n个节点，认为节点之间无差别，返回能形成多少种不同结构的二叉树\n// 1 <= n <= 19\n// 测试链接 : https://leetcode.cn/problems/unique-binary-search-trees/\npublic class Code04_UniqueTrees {\n\n\t// 数据量小用哪个公式都可以\n\t// 不用考虑溢出、取模等问题\n\t// 同时注意到n的范围并不大，直接使用公式4\n\tpublic static int numTrees(int n) {\n\t\tint[] f = new int[n + 1];\n\t\tf[0] = f[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfor (int l = 0, r = i - 1; l < i; l++, r--) {\n\t\t\t\tf[i] += f[l] * f[r];\n\t\t\t}\n\t\t}\n\t\treturn f[n];\n\t}\n\n}\n	模板：Code04_UniqueTrees.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
fefaf596-08fa-43a9-b6f5-53a4b3c0572a	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 有趣的数列(重要! 因子计数法)\n// 求第n项卡特兰数，要求答案对p取模\n// 1 <= n <= 10^6\n// 1 <= p <= 10^9\n// p可能不为质数\n// 测试链接 : https://www.luogu.com.cn/problem/P3200\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_FunnySequence {\n\n\tpublic static int MAXN = 2000001;\n\n\t// 如果minpf[i] == 0，代表i是质数\n\t// 如果minpf[i] != 0，代表i是合数，并且最小质因子是minpf[i]\n\tpublic static int[] minpf = new int[MAXN];\n\n\t// 质数表\n\tpublic static int[] prime = new int[MAXN];\n\n\t// 质数表大小\n\tpublic static int cnt;\n\n\t// 因子计数\n\tpublic static int[] counts = new int[MAXN];\n\n\t// 来自讲解097，欧拉筛，时间复杂度O(n)\n\tpublic static void euler(int n) {\n\t\tArrays.fill(minpf, 2, n, 0);\n\t\tcnt = 0;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\t// minpf[i] == 0代表i为质数，收集进质数表\n\t\t\t// minpf数组替代了讲解097中visit数组的作用\n\t\t\tif (minpf[i] == 0) {\n\t\t\t\tprime[cnt++] = i;\n\t\t\t}\n\t\t\tfor (int j = 0; j < cnt; j++) {\n\t\t\t\tif (i * prime[j] > n) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\t// 此时收集(i * prime[j])这个数的最小质因子为prime[j]\n\t\t\t\t// minpf[i * prime[j]] != 0，也标记了(i * prime[j])是合数\n\t\t\t\t// 讲解097欧拉筛的部分，重点解释了这个过程，看完必懂\n\t\t\t\tminpf[i * prime[j]] = prime[j];\n\t\t\t\tif (i % prime[j] == 0) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long power(long x, long p, int mod) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % mod;\n\t\t\t}\n\t\t\tx = (x * x) % mod;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 使用的是公式2 + 质因子计数法\n\tpublic static int compute(int n, int mod) {\n\t\t// 利用欧拉筛生成[2 ~ 2*n]范围上所有数的最小质因子\n\t\t// 如果x为质数，minpf[x] == 0\n\t\t// 如果x为合数，x的最小质因子为minpf[x]\n\t\teuler(2 * n);\n\t\t// 分母每个因子设置计数\n\t\tArrays.fill(counts, 2, n + 1, -1);\n\t\t// 分子每个因子设置计数\n\t\tArrays.fill(counts, n + 2, 2 * n + 1, 1);\n\t\t// 从大到小的每个数统计计数\n\t\t// 合数根据最小质因子来分解，变成更小数字的计数\n\t\t// 质数无法分解，计数确定，最后快速幂计算乘积\n\t\tfor (int i = 2 * n; i >= 2; i--) {\n\t\t\tif (minpf[i] != 0) {\n\t\t\t\tcounts[minpf[i]] += counts[i];\n\t\t\t\tcounts[i / minpf[i]] += counts[i];\n\t\t\t\tcounts[i] = 0;\n\t\t\t}\n\t\t}\n\t\t// 每个质数的幂，都乘起来，就是最后答案\n\t\tlong ans = 1;\n\t\tfor (int i = 2; i <= 2 * n; i++) {\n\t\t\tif (counts[i] != 0) {\n\t\t\t\tans = ans * power(i, counts[i], mod) % mod;\n\t\t\t}\n\t\t}\n\t\treturn (int) ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint mod = (int) in.nval;\n\t\tout.println(compute(n, mod));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code05_FunnySequence.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
211558b7-9e48-4053-a784-7cc5ab345907	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 生成字符串\n// 有n个1和m个0，要组成n+m长度的数列，保证任意前缀上，1的数量 >= 0的数量\n// 返回有多少种排列方法，答案对 20100403 取模\n// 1 <= m <= n <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P1641\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_GenerateString {\n\n\tpublic static int MOD = 20100403;\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static long[] fac = new long[MAXN];\n\n\tpublic static long[] inv = new long[MAXN];\n\n\tpublic static void build(int n) {\n\t\tfac[0] = inv[0] = 1;\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\tinv[n] = power(fac[n], MOD - 2);\n\t\tfor (int i = n - 1; i >= 1; i--) {\n\t\t\tinv[i] = ((long) (i + 1) * inv[i + 1]) % MOD;\n\t\t}\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv[k]) % MOD) * inv[n - k]) % MOD;\n\t}\n\n\tpublic static long compute(int n, int m) {\n\t\tbuild(n + m);\n\t\treturn (c(n + m, m) - c(n + m, m - 1) + MOD) % MOD;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tout.println(compute(n, m));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code06_GenerateString.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
477fb07b-531a-492b-a6a5-e52fffe39c66	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 不含递增三元组的排列方法数\n// 数字从1到n，可以形成很多排列，要求任意从左往右的三个位置，不能出现依次递增的样子\n// 返回排列的方法数，答案对 1000000 取模\n// 1 <= n <= 1000\n// 测试链接 : https://www.luogu.com.cn/problem/SP7897\n// 测试链接 : https://www.spoj.com/problems/SKYLINE\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code07_Skyline {\n\n\tpublic static int MOD = 1000000;\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static long[] f = new long[MAXN];\n\n\t// 因为取模的数字含有很多因子\n\t// 无法用费马小定理或者扩展欧几里得求逆元\n\t// 同时注意到n的范围并不大，直接使用公式4\n\tpublic static void build() {\n\t\tf[0] = f[1] = 1;\n\t\tfor (int i = 2; i < MAXN; i++) {\n\t\t\tfor (int l = 0, r = i - 1; l < i; l++, r--) {\n\t\t\t\tf[i] = (f[i] + f[l] * f[r] % MOD) % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tbuild();\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tint n = (int) in.nval;\n\t\t\tif (n == 0) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tout.println(f[n]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code07_Skyline.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d1811142-40a2-49e1-bc42-d88c6dd3fe7d	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 树屋阶梯\n// 地面高度是0，想搭建一个阶梯，要求每一个台阶上升1的高度，最终到达高度n\n// 有无穷多任意规格的矩形材料，但是必须选择n个矩形，希望能搭建出阶梯的样子\n// 返回搭建阶梯的不同方法数，答案可能很大，不取模！就打印真实答案\n// 1 <= n <= 500\n// 测试链接 : https://www.luogu.com.cn/problem/P2532\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.math.BigInteger;\n\npublic class Code08_TreehouseLadder {\n\n\t// 这里用公式2\n\t// java同学使用BigInteger即可\n\t// C++同学需要自己实现高精度乘法\n\tpublic static BigInteger compute(int n) {\n\t\tBigInteger a = new BigInteger("1");\n\t\tBigInteger b = new BigInteger("1");\n\t\tBigInteger cur;\n\t\tfor (int i = 1; i <= 2 * n; i++) {\n\t\t\tcur = new BigInteger(String.valueOf(i));\n\t\t\ta = a.multiply(cur);\n\t\t\tif (i <= n) {\n\t\t\t\tb = b.multiply(cur);\n\t\t\t}\n\t\t}\n\t\treturn a.divide(b.multiply(b)).divide(new BigInteger(String.valueOf(n + 1)));\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tBigInteger ans = compute(n);\n\t\tout.println(ans.toString());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code08_TreehouseLadder.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2dfe972d-445b-4b0f-854e-8c6ece903db9	734d500a-fde8-497b-bcbc-21e3979acc65	java	package class147;\n\n// 叶子节点数的期望\n// 一共有n个节点，认为节点之间无差别，能形成很多不同结构的二叉树\n// 假设所有不同结构的二叉树，等概率出现一棵，返回叶子节点的期望\n// 1 <= n <= 10^9\n// 答案误差小于10的-9次方\n// 测试链接 : https://www.luogu.com.cn/problem/P3978\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code09_LeafExpectation {\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tdouble n = in.nval;\n\t\tout.printf("%.9f", n * (n + 1) / ((2 * n - 1) * 2));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code09_LeafExpectation.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
68854f05-4571-4f61-8876-1bb01c132c5a	edeafa19-f420-4dc9-baff-fcc8b56e4410	java	package class150;\n\n// 平衡因子影响替罪羊树的实验\n// 一旦，max(左树节点数，右树节点数) > 平衡因子 * 整树节点数，就会发生重构\n// 平衡因子范围是(0.5, 1.0)，否则无意义\n// 平衡因子等于0.5时，树高很小，查询效率高，但是重构发生很频繁\n// 平衡因子等于1.0时，重构完全不发生，但是树高很大，查询效率低\n// 保证查询效率、同时保证重构的节点总数不多，0.7为最常用的平衡因子\n// 这保证了查询效率，因为树高几乎是O(log n)\n// 同时重构触发的时机合适，单次调整的均摊代价为O(log n)\n\nimport java.util.Arrays;\n\npublic class Code01_ShowDetails {\n\n\tpublic static void main(String[] args) {\n\t\tALPHA = 0.7; // 设置平衡因子\n\t\tmax = 10000; // 设置插入范围\n\t\tSystem.out.println("测试开始");\n\t\tcost = 0; // 清空重构节点计数\n\t\tfor (int num = 1; num <= max; num++) {\n\t\t\tadd(num);\n\t\t}\n\t\tSystem.out.println("插入数字 : " + "1~" + max);\n\t\tSystem.out.println("平衡因子 : " + ALPHA);\n\t\tSystem.out.println("树的高度 : " + deep(head));\n\t\tSystem.out.println("重构节点 : " + cost);\n\t\tSystem.out.println("测试结束");\n\t\tclear();\n\t}\n\n\t// 统计树高\n\tpublic static int deep(int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn Math.max(deep(left[i]), deep(right[i])) + 1;\n\t}\n\n\tpublic static int max;\n\n\tpublic static int cost;\n\n\tpublic static double ALPHA = 0.7;\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] key = new int[MAXN];\n\n\tpublic static int[] count = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[] diff = new int[MAXN];\n\n\tpublic static int[] collect = new int[MAXN];\n\n\tpublic static int ci;\n\n\tpublic static int top;\n\n\tpublic static int father;\n\n\tpublic static int side;\n\n\tpublic static int init(int num) {\n\t\tkey[++cnt] = num;\n\t\tleft[cnt] = right[cnt] = 0;\n\t\tcount[cnt] = size[cnt] = diff[cnt] = 1;\n\t\treturn cnt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + count[i];\n\t\tdiff[i] = diff[left[i]] + diff[right[i]] + (count[i] > 0 ? 1 : 0);\n\t}\n\n\tpublic static void inorder(int i) {\n\t\tif (i != 0) {\n\t\t\tinorder(left[i]);\n\t\t\tif (count[i] > 0) {\n\t\t\t\tcollect[++ci] = i;\n\t\t\t}\n\t\t\tinorder(right[i]);\n\t\t}\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\tint h = collect[m];\n\t\tleft[h] = build(l, m - 1);\n\t\tright[h] = build(m + 1, r);\n\t\tup(h);\n\t\treturn h;\n\t}\n\n\tpublic static void rebuild() {\n\t\tif (top != 0) {\n\t\t\tci = 0;\n\t\t\tinorder(top);\n\t\t\tif (ci > 0) {\n\t\t\t\tcost += ci; // 统计重构节点数\n\t\t\t\tif (father == 0) {\n\t\t\t\t\thead = build(1, ci);\n\t\t\t\t} else if (side == 1) {\n\t\t\t\t\tleft[father] = build(1, ci);\n\t\t\t\t} else {\n\t\t\t\t\tright[father] = build(1, ci);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean balance(int i) {\n\t\treturn ALPHA * diff[i] >= Math.max(diff[left[i]], diff[right[i]]);\n\t}\n\n\tpublic static void add(int i, int f, int s, int num) {\n\t\tif (i == 0) {\n\t\t\tif (f == 0) {\n\t\t\t\thead = init(num);\n\t\t\t} else if (s == 1) {\n\t\t\t\tleft[f] = init(num);\n\t\t\t} else {\n\t\t\t\tright[f] = init(num);\n\t\t\t}\n\t\t} else {\n\t\t\tif (key[i] == num) {\n\t\t\t\tcount[i]++;\n\t\t\t} else if (key[i] > num) {\n\t\t\t\tadd(left[i], i, 1, num);\n\t\t\t} else {\n\t\t\t\tadd(right[i], i, 2, num);\n\t\t\t}\n\t\t\tup(i);\n\t\t\tif (!balance(i)) {\n\t\t\t\ttop = i;\n\t\t\t\tfather = f;\n\t\t\t\tside = s;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\ttop = father = side = 0;\n\t\tadd(head, 0, 0, num);\n\t\trebuild();\n\t}\n\n\tpublic static int small(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn small(left[i], num);\n\t\t} else {\n\t\t\treturn size[left[i]] + count[i] + small(right[i], num);\n\t\t}\n\t}\n\n\tpublic static int rank(int num) {\n\t\treturn small(head, num) + 1;\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + count[i] < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - count[i]);\n\t\t}\n\t\treturn key[i];\n\t}\n\n\tpublic static int index(int x) {\n\t\treturn index(head, x);\n\t}\n\n\tpublic static int pre(int num) {\n\t\tint kth = rank(num);\n\t\tif (kth == 1) {\n\t\t\treturn Integer.MIN_VALUE;\n\t\t} else {\n\t\t\treturn index(kth - 1);\n\t\t}\n\t}\n\n\tpublic static int post(int num) {\n\t\tint kth = rank(num + 1);\n\t\tif (kth == size[head] + 1) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t} else {\n\t\t\treturn index(kth);\n\t\t}\n\t}\n\n\tpublic static void remove(int i, int f, int s, int num) {\n\t\tif (key[i] == num) {\n\t\t\tcount[i]--;\n\t\t} else if (key[i] > num) {\n\t\t\tremove(left[i], i, 1, num);\n\t\t} else {\n\t\t\tremove(right[i], i, 2, num);\n\t\t}\n\t\tup(i);\n\t\tif (!balance(i)) {\n\t\t\ttop = i;\n\t\t\tfather = f;\n\t\t\tside = s;\n\t\t}\n\t}\n\n\tpublic static void remove(int num) {\n\t\tif (rank(num) != rank(num + 1)) {\n\t\t\ttop = father = side = 0;\n\t\t\tremove(head, 0, 0, num);\n\t\t\trebuild();\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tArrays.fill(key, 1, cnt + 1, 0);\n\t\tArrays.fill(count, 1, cnt + 1, 0);\n\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\tArrays.fill(size, 1, cnt + 1, 0);\n\t\tArrays.fill(diff, 1, cnt + 1, 0);\n\t\tcnt = 0;\n\t\thead = 0;\n\t}\n\n}	模板：Code01_ShowDetails.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
348c90df-4756-4b50-b372-a0848936002b	edeafa19-f420-4dc9-baff-fcc8b56e4410	java	package class150;\n\n// 替罪羊树的实现(java版)\n// 实现一种结构，支持如下操作，要求单次调用的时间复杂度O(log n)\n// 1，增加x，重复加入算多个词频\n// 2，删除x，如果有多个，只删掉一个\n// 3，查询x的排名，x的排名为，比x小的数的个数+1\n// 4，查询数据中排名为x的数\n// 5，查询x的前驱，x的前驱为，小于x的数中最大的数，不存在返回整数最小值\n// 6，查询x的后继，x的后继为，大于x的数中最小的数，不存在返回整数最大值\n// 所有操作的次数 <= 10^5\n// -10^7 <= x <= +10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P3369\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_ScapeGoat1 {\n\n\t// 平衡因子\n\tpublic static double ALPHA = 0.7;\n\n\t// 空间的最大使用量\n\tpublic static int MAXN = 100001;\n\n\t// 整棵树的头节点编号\n\tpublic static int head = 0;\n\n\t// 空间使用计数\n\tpublic static int cnt = 0;\n\n\t// 节点的key值\n\tpublic static int[] key = new int[MAXN];\n\n\t// 节点key的计数\n\tpublic static int[] count = new int[MAXN];\n\n\t// 左孩子\n\tpublic static int[] left = new int[MAXN];\n\n\t// 右孩子\n\tpublic static int[] right = new int[MAXN];\n\n\t// 数字总数\n\tpublic static int[] size = new int[MAXN];\n\n\t// 节点总数\n\tpublic static int[] diff = new int[MAXN];\n\n\t// 中序收集节点的数组\n\tpublic static int[] collect = new int[MAXN];\n\n\t// 中序收集节点的计数\n\tpublic static int ci;\n\n\t// 最上方的不平衡节点\n\tpublic static int top;\n\n\t// top的父节点\n\tpublic static int father;\n\n\t// top是父节点的什么孩子，1代表左孩子，2代表右孩子\n\tpublic static int side;\n\n\tpublic static int init(int num) {\n\t\tkey[++cnt] = num;\n\t\tleft[cnt] = right[cnt] = 0;\n\t\tcount[cnt] = size[cnt] = diff[cnt] = 1;\n\t\treturn cnt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + count[i];\n\t\tdiff[i] = diff[left[i]] + diff[right[i]] + (count[i] > 0 ? 1 : 0);\n\t}\n\n\tpublic static void inorder(int i) {\n\t\tif (i != 0) {\n\t\t\tinorder(left[i]);\n\t\t\tif (count[i] > 0) {\n\t\t\t\tcollect[++ci] = i;\n\t\t\t}\n\t\t\tinorder(right[i]);\n\t\t}\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\tint h = collect[m];\n\t\tleft[h] = build(l, m - 1);\n\t\tright[h] = build(m + 1, r);\n\t\tup(h);\n\t\treturn h;\n\t}\n\n\tpublic static void rebuild() {\n\t\tif (top != 0) {\n\t\t\tci = 0;\n\t\t\tinorder(top);\n\t\t\tif (ci > 0) {\n\t\t\t\tif (father == 0) {\n\t\t\t\t\thead = build(1, ci);\n\t\t\t\t} else if (side == 1) {\n\t\t\t\t\tleft[father] = build(1, ci);\n\t\t\t\t} else {\n\t\t\t\t\tright[father] = build(1, ci);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean balance(int i) {\n\t\treturn ALPHA * diff[i] >= Math.max(diff[left[i]], diff[right[i]]);\n\t}\n\n\tpublic static void add(int i, int f, int s, int num) {\n\t\tif (i == 0) {\n\t\t\tif (f == 0) {\n\t\t\t\thead = init(num);\n\t\t\t} else if (s == 1) {\n\t\t\t\tleft[f] = init(num);\n\t\t\t} else {\n\t\t\t\tright[f] = init(num);\n\t\t\t}\n\t\t} else {\n\t\t\tif (key[i] == num) {\n\t\t\t\tcount[i]++;\n\t\t\t} else if (key[i] > num) {\n\t\t\t\tadd(left[i], i, 1, num);\n\t\t\t} else {\n\t\t\t\tadd(right[i], i, 2, num);\n\t\t\t}\n\t\t\tup(i);\n\t\t\tif (!balance(i)) {\n\t\t\t\ttop = i;\n\t\t\t\tfather = f;\n\t\t\t\tside = s;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\ttop = father = side = 0;\n\t\tadd(head, 0, 0, num);\n\t\trebuild();\n\t}\n\n\tpublic static int small(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn small(left[i], num);\n\t\t} else {\n\t\t\treturn size[left[i]] + count[i] + small(right[i], num);\n\t\t}\n\t}\n\n\tpublic static int rank(int num) {\n\t\treturn small(head, num) + 1;\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + count[i] < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - count[i]);\n\t\t}\n\t\treturn key[i];\n\t}\n\n\tpublic static int index(int x) {\n\t\treturn index(head, x);\n\t}\n\n\tpublic static int pre(int num) {\n\t\tint kth = rank(num);\n\t\tif (kth == 1) {\n\t\t\treturn Integer.MIN_VALUE;\n\t\t} else {\n\t\t\treturn index(kth - 1);\n\t\t}\n\t}\n\n\tpublic static int post(int num) {\n\t\tint kth = rank(num + 1);\n\t\tif (kth == size[head] + 1) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t} else {\n\t\t\treturn index(kth);\n\t\t}\n\t}\n\n\tpublic static void remove(int i, int f, int s, int num) {\n\t\tif (key[i] == num) {\n\t\t\tcount[i]--;\n\t\t} else if (key[i] > num) {\n\t\t\tremove(left[i], i, 1, num);\n\t\t} else {\n\t\t\tremove(right[i], i, 2, num);\n\t\t}\n\t\tup(i);\n\t\tif (!balance(i)) {\n\t\t\ttop = i;\n\t\t\tfather = f;\n\t\t\tside = s;\n\t\t}\n\t}\n\n\tpublic static void remove(int num) {\n\t\tif (rank(num) != rank(num + 1)) {\n\t\t\ttop = father = side = 0;\n\t\t\tremove(head, 0, 0, num);\n\t\t\trebuild();\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tArrays.fill(key, 1, cnt + 1, 0);\n\t\tArrays.fill(count, 1, cnt + 1, 0);\n\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\tArrays.fill(size, 1, cnt + 1, 0);\n\t\tArrays.fill(diff, 1, cnt + 1, 0);\n\t\tcnt = 0;\n\t\thead = 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1, op, x; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(x);\n\t\t\t} else if (op == 3) {\n\t\t\t\tout.println(rank(x));\n\t\t\t} else if (op == 4) {\n\t\t\t\tout.println(index(x));\n\t\t\t} else if (op == 5) {\n\t\t\t\tout.println(pre(x));\n\t\t\t} else {\n\t\t\t\tout.println(post(x));\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code02_ScapeGoat1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
