b1619e3b-1ddc-47c3-85f6-77d2f07dcd0e	43d09237-83e1-4139-baff-e5d17c531750	java	package class160;\n\n// 排队，java版\n// 给定一个长度为n的数组arr，下标1~n\n// 如果有i < j，并且arr[i] > arr[j]，那么(i,j)就叫做一个逆序对\n// 首先打印原始arr中有多少逆序对，然后进行如下类型的操作，一共发生m次\n// 操作 a b : 交换arr中a位置的数和b位置的数，打印数组中逆序对的数量\n// 1 <= n <= 2 * 10^4\n// 1 <= m <= 2 * 10^3\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1975\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code06_LineUp1 {\n\n\tpublic static int MAXN = 20001;\n\n\tpublic static int MAXT = MAXN * 80;\n\n\tpublic static int INF = 1000000001;\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] sorted = new int[MAXN + 2];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int[] sum = new int[MAXT];\n\n\tpublic static int cnt = 0;\n\n\tpublic static int ans = 0;\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\t// 线段树单点修改，jobi这个数字词频增加jobv\n\tpublic static int innerAdd(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cnt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[i] = innerAdd(jobi, jobv, l, mid, left[i]);\n\t\t\t} else {\n\t\t\t\tright[i] = innerAdd(jobi, jobv, mid + 1, r, right[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[left[i]] + sum[right[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\t// 查询的数字范围[jobl...jobr]，线段树的数字范围[l..r]，节点编号i\n\t// 返回有多少词频\n\tpublic static int innerQuery(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += innerQuery(jobl, jobr, l, mid, left[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += innerQuery(jobl, jobr, mid + 1, r, right[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// arr的i位置的数字，词频增加v\n\tpublic static void add(int i, int v) {\n\t\tfor (int j = i; j <= n; j += lowbit(j)) {\n\t\t\troot[j] = innerAdd(arr[i], v, 1, s, root[j]);\n\t\t}\n\t}\n\n\t// arr[al..ar]范围上，有多少数字在[numl..numr]范围上\n\tpublic static int query(int al, int ar, int numl, int numr) {\n\t\tint ans = 0;\n\t\tfor (int i = ar; i > 0; i -= lowbit(i)) {\n\t\t\tans += innerQuery(numl, numr, 1, s, root[i]);\n\t\t}\n\t\tfor (int i = al - 1; i > 0; i -= lowbit(i)) {\n\t\t\tans -= innerQuery(numl, numr, 1, s, root[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 交换a和b位置的数字，保证a在前，b在后\n\t// 修正好逆序对的数量ans\n\tpublic static void compute(int a, int b) {\n\t\tans -= query(a + 1, b - 1, 1, arr[a] - 1);\n\t\tans += query(a + 1, b - 1, arr[a] + 1, s);\n\t\tans -= query(a + 1, b - 1, arr[b] + 1, s);\n\t\tans += query(a + 1, b - 1, 1, arr[b] - 1);\n\t\tif (arr[a] < arr[b]) {\n\t\t\tans++;\n\t\t} else if (arr[a] > arr[b]) {\n\t\t\tans--;\n\t\t}\n\t\tadd(a, -1);\n\t\tadd(b, -1);\n\t\tint tmp = arr[a];\n\t\tarr[a] = arr[b];\n\t\tarr[b] = tmp;\n\t\tadd(a, 1);\n\t\tadd(b, 1);\n\t}\n\n\tpublic static void prepare() {\n\t\ts = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++s] = arr[i];\n\t\t}\n\t\tsorted[++s] = -INF;\n\t\tsorted[++s] = INF;\n\t\tArrays.sort(sorted, 1, s + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= s; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\ts = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t\tadd(i, 1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tans += query(1, i - 1, arr[i] + 1, s);\n\t\t}\n\t\tout.println(ans);\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, a, b; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\ta = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tb = (int) in.nval;\n\t\t\tif (a > b) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = b;\n\t\t\t\tb = tmp;\n\t\t\t}\n\t\t\tcompute(a, b);\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code06_LineUp1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
