d201b665-4d4c-466d-aaa6-2f421b85acb9	dbfe17d0-f5aa-4468-849a-b90b0c83a4eb	java	package class201;\n\n// 动态树LCA，C++版\n// 一共n个点，初始时每个点各自是一棵单点有根树，一共m条操作，操作类型如下\n// 操作 link x y : 让点x成为点y的儿子，保证x是所在树的根，并且x和y不连通\n// 操作 cut x    : 删除点x和它父亲节点之间的直接边，保证x不是根\n// 操作 lca x y  : 查询点x和点y的最低公共祖先，保证x和y在同一棵树中\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/SP8791\n// 测试链接 : https://www.spoj.com/problems/DYNALCA/\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//\n//int fa[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//\n//bool isroot(int x) {\n//    return ls[fa[x]] != x && rs[fa[x]] != x;\n//}\n//\n//int lr(int x) {\n//    return ls[fa[x]] == x ? 0 : 1;\n//}\n//\n//void rotate(int x) {\n//    int f = fa[x], g = fa[f];\n//    if (lr(x) == 0) {\n//        ls[f] = rs[x];\n//        if (ls[f] != 0) {\n//            fa[ls[f]] = f;\n//        }\n//        rs[x] = f;\n//    } else {\n//        rs[f] = ls[x];\n//        if (rs[f] != 0) {\n//            fa[rs[f]] = f;\n//        }\n//        ls[x] = f;\n//    }\n//    if (!isroot(f)) {\n//        if (lr(f) == 0) {\n//            ls[g] = x;\n//        } else {\n//            rs[g] = x;\n//        }\n//    }\n//    fa[f] = x;\n//    fa[x] = g;\n//}\n//\n//void splay(int x) {\n//    while (!isroot(x)) {\n//        int f = fa[x];\n//        if (!isroot(f)) {\n//            if (lr(x) == lr(f)) {\n//                rotate(f);\n//            } else {\n//                rotate(x);\n//            }\n//        }\n//        rotate(x);\n//    }\n//}\n//\n//int access(int x) {\n//    int ans = 0;\n//    for (int y = 0; x != 0; y = x, x = fa[x]) {\n//        splay(x);\n//        rs[x] = y;\n//        ans = x;\n//    }\n//    return ans;\n//}\n//\n//void makeson(int x, int y) {\n//    access(x);\n//    splay(x);\n//    fa[x] = y;\n//}\n//\n//void cutfa(int x) {\n//    access(x);\n//    splay(x);\n//    fa[ls[x]] = 0;\n//    ls[x] = 0;\n//}\n//\n//int lca(int x, int y) {\n//    if (x == y) {\n//        return x;\n//    }\n//    access(x);\n//    return access(y);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, x, y; i <= m; i++) {\n//        string op;\n//        cin >> op;\n//        if (op == "link") {\n//            cin >> x >> y;\n//            makeson(x, y);\n//        } else if (op == "cut") {\n//            cin >> x;\n//            cutfa(x);\n//        } else {\n//            cin >> x >> y;\n//            cout << lca(x, y) << "\\n";\n//        }\n//    }\n//    return 0;\n//}	模板：Code02_DynamicLCA2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
dc3fb5aa-7182-4eef-ae0a-edface4e196a	9ab2707f-10da-440e-8095-71214bc17c55	java	package class163;\n\n// 树上启发式合并模版题，java版\n// 一共有n个节点，编号1~n，给定n-1条边，所有节点连成一棵树，1号节点为树头\n// 每个节点给定一种颜色值，一共有m条查询，每条查询给定参数x\n// 每条查询打印x为头的子树上，一共有多少种不同的颜色\n// 1 <= n、m、颜色值 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/U41492\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_DsuOnTree1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n, m;\n\n\t// 每个节点的颜色\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\n\t// 树上启发式合并\n\t// colorCnt[i] = j，表示i这种颜色出现了j次\n\tpublic static int[] colorCnt = new int[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int diffColors = 0;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\t// 重链剖分\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 子树u每个节点贡献信息\n\tpublic static void effect(int u) {\n\t\tif (++colorCnt[arr[u]] == 1) {\n\t\t\tdiffColors++;\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 子树u每个节点取消贡献\n\tpublic static void cancel(int u) {\n\t\tif (--colorCnt[arr[u]] == 0) {\n\t\t\tdiffColors--;\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\tcancel(v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 树上启发式合并的过程\n\tpublic static void dfs2(int u, int keep) {\n\t\t// 遍历轻儿子的子树，统计子树的答案，然后取消贡献\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\t// 遍历重儿子的子树，统计子树的答案，然后保留贡献\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\t// 当前节点贡献信息\n\t\tif (++colorCnt[arr[u]] == 1) {\n\t\t\tdiffColors++;\n\t\t}\n\t\t// 遍历轻儿子的子树，重新贡献一遍\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t\t// 记录子树u的答案\n\t\tans[u] = diffColors;\n\t\t// 如果u是上级节点的轻儿子，子树u的贡献取消，否则保留\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, cur; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tcur = (int) in.nval;\n\t\t\tout.println(ans[cur]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_DsuOnTree1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
f563001e-8737-493d-8c63-f8659de23dc3	9ab2707f-10da-440e-8095-71214bc17c55	java	package class163;\n\n// 树上启发式合并模版题，java版\n// 只需要关注有注释的代码\n// 揭示了轻儿子取消自己的影响后\n// 其实全局的信息统计就是空的\n// 所以改成注释的代码也是正确的\n// 测试链接 : https://www.luogu.com.cn/problem/U41492\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_DsuOnTree2 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] colorCnt = new int[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int diffColors = 0;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void effect(int u) {\n\t\tif (++colorCnt[arr[u]] == 1) {\n\t\t\tdiffColors++;\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tcolorCnt[arr[u]] = 0; // 出现任何颜色，直接把该颜色的计数重置为0\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\tcancel(v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\tif (++colorCnt[arr[u]] == 1) {\n\t\t\tdiffColors++;\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t\tans[u] = diffColors;\n\t\tif (keep == 0) {\n\t\t\tdiffColors = 0; // 直接把全局的不同颜色数量重置为0\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, cur; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tcur = (int) in.nval;\n\t\t\tout.println(ans[cur]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code01_DsuOnTree2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
