0d04b227-dc23-456f-bdc2-f243681c1a44	dbfe17d0-f5aa-4468-849a-b90b0c83a4eb	java	package class201;\n\n// 洞穴勘测，java版\n// 一共n个点，初始时没有任何边，任意时刻图都是森林，一共m条操作，类型如下\n// 操作 Connect x y : 点x和点y之间增加直接边，保证原来不存在这条直接边\n// 操作 Destroy x y : 删除点x和点y之间的直接边，保证原来存在这条直接边\n// 操作 Query x y   : 查询点x和点y之间是否连通，打印 Yes 或 No\n// 1 <= n <= 10^4\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2147\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_CaveSurvey1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int n, m;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static boolean[] rev = new boolean[MAXN];\n\n\tpublic static boolean isroot(int x) {\n\t\treturn ls[fa[x]] != x && rs[fa[x]] != x;\n\t}\n\n\tpublic static int lr(int x) {\n\t\treturn ls[fa[x]] == x ? 0 : 1;\n\t}\n\n\tpublic static void reverse(int x) {\n\t\tif (x != 0) {\n\t\t\tint tmp = ls[x];\n\t\t\tls[x] = rs[x];\n\t\t\trs[x] = tmp;\n\t\t\trev[x] = !rev[x];\n\t\t}\n\t}\n\n\tpublic static void down(int x) {\n\t\tif (rev[x]) {\n\t\t\treverse(ls[x]);\n\t\t\treverse(rs[x]);\n\t\t\trev[x] = false;\n\t\t}\n\t}\n\n\tpublic static void rotate(int x) {\n\t\tint f = fa[x], g = fa[f];\n\t\tif (lr(x) == 0) {\n\t\t\tls[f] = rs[x];\n\t\t\tif (ls[f] != 0) {\n\t\t\t\tfa[ls[f]] = f;\n\t\t\t}\n\t\t\trs[x] = f;\n\t\t} else {\n\t\t\trs[f] = ls[x];\n\t\t\tif (rs[f] != 0) {\n\t\t\t\tfa[rs[f]] = f;\n\t\t\t}\n\t\t\tls[x] = f;\n\t\t}\n\t\tif (!isroot(f)) {\n\t\t\tif (lr(f) == 0) {\n\t\t\t\tls[g] = x;\n\t\t\t} else {\n\t\t\t\trs[g] = x;\n\t\t\t}\n\t\t}\n\t\tfa[f] = x;\n\t\tfa[x] = g;\n\t}\n\n\tpublic static void splay(int x) {\n\t\tint siz = 0;\n\t\tsta[++siz] = x;\n\t\tfor (int y = x; !isroot(y); y = fa[y]) {\n\t\t\tsta[++siz] = fa[y];\n\t\t}\n\t\twhile (siz != 0) {\n\t\t\tdown(sta[siz--]);\n\t\t}\n\t\twhile (!isroot(x)) {\n\t\t\tint f = fa[x];\n\t\t\tif (!isroot(f)) {\n\t\t\t\tif (lr(x) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(x);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(x);\n\t\t}\n\t}\n\n\tpublic static void access(int x) {\n\t\tfor (int y = 0; x != 0; y = x, x = fa[x]) {\n\t\t\tsplay(x);\n\t\t\trs[x] = y;\n\t\t}\n\t}\n\n\tpublic static void makeroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\treverse(x);\n\t}\n\n\tpublic static int findroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\tdown(x);\n\t\twhile (ls[x] != 0) {\n\t\t\tx = ls[x];\n\t\t\tdown(x);\n\t\t}\n\t\tsplay(x);\n\t\treturn x;\n\t}\n\n\tpublic static void link(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) != x) {\n\t\t\tfa[x] = y;\n\t\t}\n\t}\n\n\tpublic static void cut(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) == x && fa[y] == x && ls[y] == 0 && rs[x] == y) {\n\t\t\tfa[y] = rs[x] = 0;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tString op = in.nextString();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op.equals("Connect")) {\n\t\t\t\tlink(x, y);\n\t\t\t} else if (op.equals("Destroy")) {\n\t\t\t\tcut(x, y);\n\t\t\t} else {\n\t\t\t\tif (findroot(x) == findroot(y)) {\n\t\t\t\t\tout.println("Yes");\n\t\t\t\t} else {\n\t\t\t\t\tout.println("No");\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tString nextString() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tif (c == -1) {\n\t\t\t\treturn null;\n\t\t\t}\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t}\n\n}\n	模板：Code03_CaveSurvey1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d001adc5-a170-423b-8a70-2d55f5a53f1b	9ab2707f-10da-440e-8095-71214bc17c55	java	package class163;\n\n// 主导颜色累加和，java版\n// 一共有n个节点，编号1~n，给定n-1条边，所有节点连成一棵树，1号节点为树头\n// 每个节点给定一种颜色值，主导颜色累加和定义如下\n// 以x为头的子树上，哪种颜色出现最多，那种颜色就是主导颜色，主导颜色可能不止一种\n// 所有主导颜色的值累加起来，每个主导颜色只累加一次，就是该子树的主导颜色累加和\n// 打印1~n每个节点为头的子树的主导颜色累加和\n// 1 <= n、颜色值 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF600E\n// 测试链接 : https://codeforces.com/problemset/problem/600/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_LomsatGelral1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n;\n\tpublic static int[] color = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\n\tpublic static int[] colorCnt = new int[MAXN];\n\tpublic static int[] maxCnt = new int[MAXN];\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void effect(int u, int h) {\n\t\tcolorCnt[color[u]]++;\n\t\tif (colorCnt[color[u]] == maxCnt[h]) {\n\t\t\tans[h] += color[u];\n\t\t} else if (colorCnt[color[u]] > maxCnt[h]) {\n\t\t\tmaxCnt[h] = colorCnt[color[u]];\n\t\t\tans[h] = color[u];\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\teffect(v, h);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tcolorCnt[color[u]] = 0;\n\t\tmaxCnt[u] = 0;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\tcancel(v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\tmaxCnt[u] = maxCnt[son[u]];\n\t\tans[u] = ans[son[u]];\n\t\tcolorCnt[color[u]]++;\n\t\tif (colorCnt[color[u]] == maxCnt[u]) {\n\t\t\tans[u] += color[u];\n\t\t} else if (colorCnt[color[u]] > maxCnt[u]) {\n\t\t\tmaxCnt[u] = colorCnt[color[u]];\n\t\t\tans[u] = color[u];\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\teffect(v, u);\n\t\t\t}\n\t\t}\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcolor[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n	模板：Code03_LomsatG