580fbf9a-1d6f-4d40-b6d4-57907ba8224f	b76ca3d9-a01a-4385-b39c-7644fec9a106	java	package class164;\n\n// youyou的军训，java版\n// 图里有n个点，m条无向边，每条边给定不同的边权，图里可能有若干个连通的部分\n// 一开始limit = 0，接下来有q条操作，每种操作的格式如下\n// 操作 1 x   : 所有修改操作生效，然后limit设置成x\n// 操作 2 x   : 从点x出发，只能走 边权 >= limit 的边，查询最多到达几个点\n// 操作 3 x y : 第x条边的边权修改为y，不是立刻生效，等到下次操作1发生时生效\n// 题目保证边权不管如何修改，所有边权都不相等，并且每条边的边权排名不发生变化\n// 1 <= n、m、q <= 4 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P9638\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.util.Arrays;\n\npublic class Code02_Training1 {\n\n\tpublic static int MAXK = 800001;\n\tpublic static int MAXM = 400001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q;\n\n\t// 每条边的信息，节点u、节点v、边权w、边的编号i\n\tpublic static int[][] edge = new int[MAXM][4];\n\t// 边的编号对应重构树上的点的编号\n\tpublic static int[] edgeToTree = new int[MAXM];\n\n\t// 边权的修改操作先不生效，等到下次操作1发生时生效\n\t// 修改了哪些边\n\tpublic static int[] pendEdge = new int[MAXM];\n\t// 修改成了什么边权\n\tpublic static int[] pendVal = new int[MAXM];\n\t// 修改操作的个数\n\tpublic static int cntp = 0;\n\n\t// 并查集\n\tpublic static int[] father = new int[MAXK];\n\tpublic static int[] stack = new int[MAXK];\n\n\t// Kruskal重构树\n\tpublic static int[] head = new int[MAXK];\n\tpublic static int[] next = new int[MAXK];\n\tpublic static int[] to = new int[MAXK];\n\tpublic static int cntg = 0;\n\tpublic static int[] nodeKey = new int[MAXK];\n\tpublic static int cntu;\n\n\t// 树上dfs，Kruskal重构树的节点，子树上面有几个叶节点\n\tpublic static int[] leafsiz = new int[MAXK];\n\t// 树上dfs，Kruskal重构树的节点，倍增表\n\tpublic static int[][] stjump = new int[MAXK][MAXP];\n\n\t// 并查集的find方法，需要改成迭代版不然会爆栈，C++实现不需要\n\tpublic static int find(int i) {\n\t\tint size = 0;\n\t\twhile (i != father[i]) {\n\t\t\tstack[size++] = i;\n\t\t\ti = father[i];\n\t\t}\n\t\twhile (size > 0) {\n\t\t\tfather[stack[--size]] = i;\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void kruskalRebuild() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tArrays.sort(edge, 1, m + 1, (a, b) -> b[2] - a[2]);\n\t\tcntu = n;\n\t\tfor (int i = 1, fx, fy; i <= m; i++) {\n\t\t\tfx = find(edge[i][0]);\n\t\t\tfy = find(edge[i][1]);\n\t\t\tif (fx != fy) {\n\t\t\t\tfather[fx] = father[fy] = ++cntu;\n\t\t\t\tfather[cntu] = cntu;\n\t\t\t\tnodeKey[cntu] = edge[i][2];\n\t\t\t\taddEdge(cntu, fx);\n\t\t\t\taddEdge(cntu, fy);\n\t\t\t\tedgeToTree[edge[i][3]] = cntu;\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1是递归函数，需要改成迭代版，不然会爆栈，C++实现不需要\n\tpublic static void dfs1(int u, int fa) {\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tdfs1(to[e], u);\n\t\t}\n\t\tif (u <= n) {\n\t\t\tleafsiz[u] = 1;\n\t\t} else {\n\t\t\tleafsiz[u] = 0;\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tleafsiz[u] += leafsiz[to[e]];\n\t\t}\n\t}\n\n\tpublic static int[][] ufe = new int[MAXK][3];\n\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\t// dfs2是dfs1的迭代版\n\tpublic static void dfs2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tpush(to[e], u, -1);\n\t\t\t} else {\n\t\t\t\tif (u <= n) {\n\t\t\t\t\tleafsiz[u] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tleafsiz[u] = 0;\n\t\t\t\t}\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\t\t\tleafsiz[u] += leafsiz[to[ei]];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int u, int limit) {\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[u][p] > 0 && nodeKey[stjump[u][p]] >= limit) {\n\t\t\t\tu = stjump[u][p];\n\t\t\t}\n\t\t}\n\t\treturn leafsiz[u];\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tq = io.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tedge[i][0] = io.nextInt();\n\t\t\tedge[i][1] = io.nextInt();\n\t\t\tedge[i][2] = io.nextInt();\n\t\t\tedge[i][3] = i;\n\t\t}\n\t\tkruskalRebuild();\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tif (i == father[i]) {\n\t\t\t\tdfs2(i, 0);\n\t\t\t}\n\t\t}\n\t\tint op, x, y, limit = 0;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = io.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\t// 收集的修改操作生效\n\t\t\t\tfor (int k = 1; k <= cntp; k++) {\n\t\t\t\t\tnodeKey[edgeToTree[pendEdge[k]]] = pendVal[k];\n\t\t\t\t}\n\t\t\t\tcntp = 0;\n\t\t\t\tlimit = io.nextInt();\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = io.nextInt();\n\t\t\t\tio.writelnInt(query(x, limit));\n\t\t\t} else {\n\t\t\t\tx = io.nextInt();\n\t\t\t\ty = io.nextInt();\n\t\t\t\t// 收集修改操作\n\t\t\t\tif (edgeToTree[x] != 0) {\n\t\t\t\t\tpendEdge[++cntp] = x;\n\t\t\t\t\tpendVal[cntp] = y;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code02_Training1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
