a4fa51fe-a3b1-4cb8-b0d7-b88b1654678f	b76ca3d9-a01a-4385-b39c-7644fec9a106	java	package class164;\n\n// 加边直到连通，java版\n// 图里有n个点，m条无向边，点的编号1~n，边的编号1~m，所有点都连通\n// 一共有q条查询，每条查询格式如下\n// 查询 l r : 至少要加完编号前多少的边，才能使得[l, r]中的所有点连通\n// 1 <= n <= 10^5\n// 1 <= m、q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1706E\n// 测试链接 : https://codeforces.com/problemset/problem/1706/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.util.Arrays;\n\npublic class Code05_UntilConnect1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXK = 200001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXP = 20;\n\tpublic static int t, n, m, q;\n\tpublic static int[][] edge = new int[MAXM][3];\n\n\t// 并查集\n\tpublic static int[] father = new int[MAXK];\n\n\t// Kruskal重构树\n\tpublic static int[] head = new int[MAXK];\n\tpublic static int[] next = new int[MAXK];\n\tpublic static int[] to = new int[MAXK];\n\tpublic static int cntg;\n\tpublic static int[] nodeKey = new int[MAXK];\n\tpublic static int cntu;\n\n\t// 深度\n\tpublic static int[] dep = new int[MAXK];\n\t// dfn序\n\tpublic static int[] dfn = new int[MAXK];\n\t// seg[i] = j，代表树上节点的dfn序号为i，对应原始节点的编号为j\n\tpublic static int[] seg = new int[MAXK];\n\t// 树上的倍增表\n\tpublic static int[][] stjump = new int[MAXK][MAXP];\n\t// dfn序号的计数\n\tpublic static int cntd;\n\n\t// 一维数组的倍增表，查询区间最大值、最小值\n\tpublic static int[] lg2 = new int[MAXN];\n\tpublic static int[][] stmax = new int[MAXN][MAXP];\n\tpublic static int[][] stmin = new int[MAXN][MAXP];\n\n\tpublic static void clear() {\n\t\tcntg = cntd = 0;\n\t\tArrays.fill(head, 1, n * 2, 0);\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void kruskalRebuild() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tArrays.sort(edge, 1, m + 1, (a, b) -> a[2] - b[2]);\n\t\tcntu = n;\n\t\tfor (int i = 1, fx, fy; i <= m; i++) {\n\t\t\tfx = find(edge[i][0]);\n\t\t\tfy = find(edge[i][1]);\n\t\t\tif (fx != fy) {\n\t\t\t\tfather[fx] = father[fy] = ++cntu;\n\t\t\t\tfather[cntu] = cntu;\n\t\t\t\tnodeKey[cntu] = edge[i][2];\n\t\t\t\taddEdge(cntu, fx);\n\t\t\t\taddEdge(cntu, fy);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tdfs(to[e], u);\n\t\t}\n\t}\n\n\t// 构建数组上的st表，讲解117进行了详细的讲述\n\tpublic static void buildst() {\n\t\tlg2[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlg2[i] = lg2[i >> 1] + 1;\n\t\t\tstmax[i][0] = dfn[i];\n\t\t\tstmin[i][0] = dfn[i];\n\t\t}\n\t\tfor (int p = 1; p <= lg2[n]; p++) {\n\t\t\tfor (int i = 1; i + (1 << p) - 1 <= n; i++) {\n\t\t\t\tstmax[i][p] = Math.max(stmax[i][p - 1], stmax[i + (1 << (p - 1))][p - 1]);\n\t\t\t\tstmin[i][p] = Math.min(stmin[i][p - 1], stmin[i + (1 << (p - 1))][p - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 根据st表，[l..r]范围上的最小值，讲解117进行了详细的讲述\n\tpublic static int dfnmin(int l, int r) {\n\t\tint p = lg2[r - l + 1];\n\t\tint ans = Math.min(stmin[l][p], stmin[r - (1 << p) + 1][p]);\n\t\treturn ans;\n\t}\n\n\t// 根据st表，[l..r]范围上的最大值，讲解117进行了详细的讲述\n\tpublic static int dfnmax(int l, int r) {\n\t\tint p = lg2[r - l + 1];\n\t\tint ans = Math.max(stmax[l][p], stmax[r - (1 << p) + 1][p]);\n\t\treturn ans;\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint x = seg[dfnmin(l, r)];\n\t\tint y = seg[dfnmax(l, r)];\n\t\treturn nodeKey[lca(x, y)];\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tt = io.nextInt();\n\t\tfor (int test = 1; test <= t; test++) {\n\t\t\tn = io.nextInt();\n\t\t\tm = io.nextInt();\n\t\t\tq = io.nextInt();\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tedge[i][0] = io.nextInt();\n\t\t\t\tedge[i][1] = io.nextInt();\n\t\t\t\tedge[i][2] = i;\n\t\t\t}\n\t\t\tclear();\n\t\t\tkruskalRebuild();\n\t\t\tdfs(cntu, 0);\n\t\t\tbuildst();\n\t\t\tfor (int i = 1, l, r; i <= q; i++) {\n\t\t\t\tl = io.nextInt();\n\t\t\t\tr = io.nextInt();\n\t\t\t\tif (l == r) {\n\t\t\t\t\tio.write("0 ");\n\t\t\t\t} else {\n\t\t\t\t\tio.write(query(l, r) + " ");\n\t\t\t\t}\n\t\t\t}\n\t\t\tio.write("\\n");\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：Code05_UntilConnect1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
