bed74afc-c77f-4332-9ff9-a0bb59a15afd	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class184;\n\n// 首都，java版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树\n// 给定长度为n的数组color，color[i]表示i号节点的颜色，颜色有k种\n// 你需要在树上找到一个连通区，连通区内出现的每种颜色，在连通区外不存在\n// 这样的连通区可能有多个，希望包含的颜色数量尽量少，打印(最少颜色数 - 1)的结果\n// 1 <= n、k <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P7215\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_Capital1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, k;\n\tpublic static int[] color = new int[MAXN];\n\n\t// 建树的链式前向星\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\t// 颜色拥有的节点列表\n\tpublic static int[] headc = new int[MAXN];\n\tpublic static int[] nextc = new int[MAXN];\n\tpublic static int[] toc = new int[MAXN];\n\tpublic static int cntc;\n\n\t// 点分治\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\t// father[x] = y，表示x此时的父亲节点是y\n\tpublic static int[] father = new int[MAXN];\n\t// nodeRoot[x] = y，表示x此时的重心是y\n\tpublic static int[] nodeRoot = new int[MAXN];\n\n\t// 宽度优先遍历的队列\n\tpublic static int[] que = new int[MAXN];\n\t// 节点是否进过队列\n\tpublic static boolean[] nodeVis = new boolean[MAXN];\n\t// 颜色是否讨论过\n\tpublic static boolean[] colorVis = new boolean[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, f, rt, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int rt, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = rt;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\trt = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addNode(int color, int node) {\n\t\tnextc[++cntc] = headc[color];\n\t\ttoc[cntc] = node;\n\t\theadc[color] = cntc;\n\t}\n\n\t// 得到子树大小递归版，java会爆栈，C++可以通过\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 得到子树大小迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = headg[u]; ei > 0; ei = nextg[ei]) {\n\t\t\t\t\tint v = tog[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 收集信息递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa, int rt) {\n\t\tfather[u] = fa;\n\t\tnodeRoot[u] = rt;\n\t\tnodeVis[u] = false;\n\t\tcolorVis[color[u]] = false;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs1(v, u, rt);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 收集信息迭代版\n\tpublic static void dfs2(int cur, int fa, int root) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, root, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfather[u] = f;\n\t\t\t\tnodeRoot[u] = rt;\n\t\t\t\tnodeVis[u] = false;\n\t\t\t\tcolorVis[color[u]] = false;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, rt, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, rt, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int calc(int u) {\n\t\t// dfs1(u, 0, u);\n\t\tdfs2(u, 0, u);\n\t\tint l = 1, r = 0;\n\t\tque[++r] = u;\n\t\tnodeVis[u] = true;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tint cur = que[l++];\n\t\t\tif (cur != u && !nodeVis[father[cur]]) {\n\t\t\t\tque[++r] = father[cur];\n\t\t\t\tnodeVis[father[cur]] = true;\n\t\t\t}\n\t\t\tif (!colorVis[color[cur]]) {\n\t\t\t\tcolorVis[color[cur]] = true;\n\t\t\t\tans++;\n\t\t\t\tfor (int e = headc[color[cur]]; e > 0; e = nextc[e]) {\n\t\t\t\t\tint v = toc[e];\n\t\t\t\t\tif (nodeRoot[v] != u) {\n\t\t\t\t\t\treturn INF;\n\t\t\t\t\t}\n\t\t\t\t\tif (!nodeVis[v]) {\n\t\t\t\t\t\tque[++r] = v;\n\t\t\t\t\t\tnodeVis[v] = true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int solve(int u) {\n\t\tvis[u] = true;\n\t\tint ans = calc(u);\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tans = Math.min(ans, solve(getCentroid(v, u)));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tk = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcolor[i] = in.nextInt();\n\t\t\taddNode(color[i], i);\n\t\t}\n\t\tint ans = solve(getCentroid(1, 0));\n\t\tout.println(ans - 1);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_Capital1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
