0b45817e-ab13-4dbd-8db8-62d3a26d5ff3	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class184;\n\n// 快递员，java版\n// 一共有n个节点，给定n-1条边，每条边给定边权，所有节点组成一棵树\n// 对于点对(a, b)，假设你选择的中心点为x，那么点对的距离如下\n// 点对(a, b)的距离 = a到x的路径权值和 + b到x的路径权值和\n// 一共有m个点对，你需要选择中心点x，使得点对距离的最大值尽量小\n// 打印这个最小的点对距离最大值\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4886\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Courier1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\tpublic static int[] tree = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, d, t, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int d, int t, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = d;\n\t\tstack[stacksize][3] = t;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\td = stack[stacksize][2];\n\t\tt = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// 得到子树大小递归版，java会爆栈，C++可以通过\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 得到子树大小迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 收集信息递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa, int d, int t) {\n\t\ttree[u] = t;\n\t\tdist[u] = d;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u, d + weight[e], t);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 收集信息迭代版\n\tpublic static void dfs2(int cur, int fa, int di, int tr) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, di, tr, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttree[u] = t;\n\t\t\t\tdist[u] = d;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, d, t, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, d + weight[e], t, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int compute() {\n\t\tint ans = 1000000001;\n\t\tint u = getCentroid(1, 0);\n\t\twhile (!vis[u]) {\n\t\t\tvis[u] = true;\n\t\t\ttree[u] = u;\n\t\t\tdist[u] = 0;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\t// dfs1(v, u, w, v);\n\t\t\t\tdfs2(v, u, w, v);\n\t\t\t}\n\t\t\tint maxDist = 0, son = 0;\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint curDist = dist[a[i]] + dist[b[i]];\n\t\t\t\tint t1 = tree[a[i]];\n\t\t\t\tint t2 = tree[b[i]];\n\t\t\t\tif (maxDist < curDist) {\n\t\t\t\t\tmaxDist = curDist;\n\t\t\t\t\tson = t1 == t2 ? t1 : 0;\n\t\t\t\t} else if (maxDist == curDist && (t1 != t2 || t1 != son)) {\n\t\t\t\t\tson = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans = Math.min(ans, maxDist);\n\t\t\tif (son == 0) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tu = getCentroid(son, u);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_Courier1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
