cb5cfed3-780c-406a-b922-07d3b007051b	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class184;\n\n// 树上购物，java版\n// 一共有n个商店，有n-1条路构成一棵树，第i个商店只卖第i种物品\n// 给定每种物品三个属性，价值v[i]、单价c[i]、数量d[i]\n// 你逛商店可能会购买物品，要求所有买过东西的商店，在树上必须连通\n// 你有m元，打印能获得的最大价值总和\n// 1 <= n <= 500    1 <= m <= 4000    1 <= d[i] <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P6326\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Shopping1 {\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXM = 4001;\n\tpublic static int t, n, m;\n\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] c = new int[MAXN];\n\tpublic static int[] d = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\tpublic static int[] nodeArr = new int[MAXN];\n\tpublic static int[] endDfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int[] cost = new int[MAXN];\n\tpublic static int[][] dp = new int[MAXN + 1][MAXM];\n\n\tpublic static void prepare() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tvis[i] = false;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tnodeArr[++cntd] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t\tendDfn[u] = cntd;\n\t}\n\n\tpublic static int calc(int u) {\n\t\tcntd = 0;\n\t\tdfs(u, 0);\n\t\tfor (int i = cntd; i > 0; i--) {\n\t\t\tint cur = nodeArr[i];\n\t\t\t// 二进制分组优化，注意物品量-1，然后二进制分组\n\t\t\t// 先必选一件，然后考虑更多件，课上解释了为什么\n\t\t\tint cnt = d[cur] - 1;\n\t\t\tint num = 0;\n\t\t\tfor (int k = 1; k <= cnt; k <<= 1) {\n\t\t\t\tval[++num] = v[cur] * k;\n\t\t\t\tcost[num] = c[cur] * k;\n\t\t\t\tcnt -= k;\n\t\t\t}\n\t\t\tif (cnt > 0) {\n\t\t\t\tval[++num] = v[cur] * cnt;\n\t\t\t\tcost[num] = c[cur] * cnt;\n\t\t\t}\n\t\t\t// 必选cur的情况，先必选一件\n\t\t\tfor (int j = m; j >= c[cur]; j--) {\n\t\t\t\tdp[i][j] = dp[i + 1][j - c[cur]] + v[cur];\n\t\t\t}\n\t\t\t// 然后用二进制分组，拼出可能的更多件\n\t\t\tfor (int k = 1; k <= num; k++) {\n\t\t\t\tfor (int j = m; j >= cost[k]; j--) {\n\t\t\t\t\tdp[i][j] = Math.max(dp[i][j], dp[i][j - cost[k]] + val[k]);\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 不选cur的情况，那么cur的子树都跳过，直接跳到endDfn[cur] + 1\n\t\t\tfor (int j = 0; j <= m; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i][j], dp[endDfn[cur] + 1][j]);\n\t\t\t}\n\t\t}\n\t\tint ans = dp[1][m];\n\t\t// 返回之前清空\n\t\tfor (int i = 1; i <= cntd; i++) {\n\t\t\tfor (int j = 0; j <= m; j++) {\n\t\t\t\tdp[i][j] = 0;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int solve(int u) {\n\t\tvis[u] = true;\n\t\tint ans = calc(u);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tans = Math.max(ans, solve(getCentroid(v, u)));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int k = 1; k <= t; k++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tv[i] = in.nextInt();\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tc[i] = in.nextInt();\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\td[i] = in.nextInt();\n\t\t\t}\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\tout.println(solve(getCentroid(1, 0)));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_Shopping1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
