rt;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (outDeg[i] > 0) {\n//            return i;\n//        }\n//    }\n//    return -1;\n//}\n//\n//void euler(int u) {\n//    for (int e = cur[u]; e > 0; e = cur[u]) {\n//        cur[u] = nxt[e];\n//        euler(to[e]);\n//    }\n//    path[++cntp] = u;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> edgeArr[i].u >> edgeArr[i].v;\n//    }\n//    connect();\n//    int start = directedStart();\n//    if (start == -1) {\n//        cout << "No\\n";\n//    } else {\n//        euler(start);\n//        if (cntp != m + 1) {\n//            cout << "No\\n";\n//        } else {\n//            for (int i = cntp; i >= 1; i--) {\n//                cout << path[i] << " ";\n//            }\n//            cout << "\\n";\n//        }\n//    }\n//    return 0;\n//}	模板：Code01_DirectedEuler2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3d1659dc-e87f-46a5-84e7-c1547089f6ea	53918e6b-d5a7-42a9-9b64-3307c74afc39	java	package class188;\n\n// 无向图的欧拉路径，java版\n// 图中给定m条无向边，每条边给出两个端点\n// 如果存在欧拉路径，输出字典序最小的结果，如果不存在打印No\n// 节点编号的范围是[1, 500]，所有点不一定都出现，以给定的边为准\n// 1 <= m <= 1024\n// 测试链接 : https://www.luogu.com.cn/problem/P2731\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code02_UndirectedEuler1 {\n\n\tpublic static class EdgeCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] e1, int[] e2) {\n\t\t\treturn e1[0] != e2[0] ? (e1[0] - e2[0]) : (e1[1] - e2[1]);\n\t\t}\n\t}\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXM = 2001;\n\tpublic static int n = 500, m, k;\n\tpublic static int[][] edgeArr = new int[MAXM << 1][3];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int[] eid = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] cur = new int[MAXN];\n\tpublic static int[] deg = new int[MAXN];\n\tpublic static boolean[] vis = new boolean[MAXM];\n\n\tpublic static int[] path = new int[MAXM];\n\tpublic static int cntp;\n\n\tpublic static void addEdge(int u, int v, int id) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\teid[cntg] = id;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void connect() {\n\t\tArrays.sort(edgeArr, 1, k + 1, new EdgeCmp());\n\t\tfor (int l = 1, r = 1; l <= k; l = ++r) {\n\t\t\twhile (r + 1 <= k && edgeArr[l][0] == edgeArr[r + 1][0]) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tfor (int i = r, u, v, id; i >= l; i--) {\n\t\t\t\tu = edgeArr[i][0];\n\t\t\t\tv = edgeArr[i][1];\n\t\t\t\tid = edgeArr[i][2];\n\t\t\t\tdeg[u]++;\n\t\t\t\taddEdge(u, v, id);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcur[i] = head[i];\n\t\t}\n\t}\n\n\t// 无向图中找到一个起点，去生成欧拉回路 或者 欧拉路径\n\tpublic static int undirectedStart() {\n\t\tint odd = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif ((deg[i] & 1) == 1) {\n\t\t\t\todd++;\n\t\t\t}\n\t\t}\n\t\tif (odd != 0 && odd != 2) {\n\t\t\treturn -1;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (odd == 0 && deg[i] > 0) {\n\t\t\t\treturn i;\n\t\t\t}\n\t\t\tif (odd == 2 && (deg[i] & 1) == 1) {\n\t\t\t\treturn i;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\t// Hierholzer算法递归版\n\tpublic static void euler1(int u) {\n\t\tfor (int e = cur[u]; e > 0; e = cur[u]) {\n\t\t\tcur[u] = nxt[e];\n\t\t\tif (!vis[eid[e]]) {\n\t\t\t\tvis[eid[e]] = true;\n\t\t\t\teuler1(to[e]);\n\t\t\t}\n\t\t}\n\t\tpath[++cntp] = u;\n\t}\n\n\t// Hierholzer算法迭代版\n\tpublic static int[] sta = new int[MAXM];\n\tpublic static int top;\n\n\tpublic static void euler2(int node) {\n\t\ttop = 0;\n\t\tsta[++top] = node;\n\t\twhile (top > 0) {\n\t\t\tint u = sta[top--];\n\t\t\tint e = cur[u];\n\t\t\tif (e != 0) {\n\t\t\t\tcur[u] = nxt[e];\n\t\t\t\tif (!vis[eid[e]]) {\n\t\t\t\t\tvis[eid[e]] = true;\n\t\t\t\t\tsta[++top] = u;\n\t\t\t\t\tsta[++top] = to[e];\n\t\t\t\t} else {\n\t\t\t\t\tsta[++top] = u;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tpath[++cntp] = u;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tm = in.nextInt();\n\t\tk = 0;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tedgeArr[++k][0] = u;\n\t\t\tedgeArr[k][1] = v;\n\t\t\tedgeArr[k][2] = i;\n\t\t\tedgeArr[++k][0] = v;\n\t\t\tedgeArr[k][1] = u;\n\t\t\tedgeArr[k][2] = i;\n\t\t}\n\t\tconnect();\n\t\tint start = undirectedStart();\n\t\tif (start == -1) {\n\t\t\tout.println("No");\n\t\t} else {\n\t\t\t// euler1(start);\n\t\t\teuler2(start);\n\t\t\tif (cntp != m + 1) {\n\t\t\t\tout.println("No");\n\t\t\t} else {\n\t\t\t\tfor (int i = cntp; i >= 1; i--) {\n\t\t\t\t\tout.println(path[i]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code02_UndirectedEuler1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
