dc8a6024-8c33-4e68-b205-e65ae194b056	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// Atm的树，java版\n// 树上有n个点，给定n-1条边，每条边有边权\n// 现在关心，从节点x出发到达其他点的距离中，第k小的距离\n// 注意，节点x到自己的距离0，不参与距离评比\n// 给定正数k，打印每个节点的第k小距离，一共n条打印\n// 1 <= n <= 15000\n// 1 <= k <= 5000\n// 1 <= 边权 <= 10\n// 测试链接 : https://www.luogu.com.cn/problem/P10604\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_AtmTree1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXP = 18;\n\tpublic static int MAXT = 1000001;\n\tpublic static int n, k, sumw;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\tpublic static int[] addTree = new int[MAXN];\n\tpublic static int[] minusTree = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] sum = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u, int fa, int dis) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdist[u] = dis;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[i] = add(jobi, jobv, l, mid, ls[i]);\n\t\t\t} else {\n\t\t\t\trs[i] = add(jobi, jobv, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[ls[i]] + sum[rs[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, rs[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void add(int x, int v) {\n\t\taddTree[x] = add(0, v, 0, sumw, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\taddTree[fa] = add(dist, v, 0, sumw, addTree[fa]);\n\t\t\tminusTree[cur] = add(dist, v, 0, sumw, minusTree[cur]);\n\t\t}\n\t}\n\n\tpublic static int query(int x, int limit) {\n\t\tint ans = query(0, limit, 0, sumw, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tif (limit - dist >= 0) {\n\t\t\t\tans += query(0, limit - dist, 0, sumw, addTree[fa]);\n\t\t\t\tans -= query(0, limit - dist, 0, sumw, minusTree[cur]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int compute(int x) {\n\t\tint ans = 0;\n\t\tint l = 0, r = sumw, mid;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (query(x, mid) >= k) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tk = in.nextInt() + 1;\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t\tsumw += w;\n\t\t}\n\t\tdfs(1, 0, 0);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(i, 1);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(compute(i));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_AtmTree1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
