f21ded67-9ed2-4418-8969-fe462b2e4bf7	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// 幻想乡战略游戏，java版\n// 树上有n个点，每个点的初始点权是0，给定n-1条边，每条边有边权\n// 如果点x是指挥点，它指挥点y的花费 = x到y的简单路径权值和 * y的点权\n// 树上存在某个最佳的指挥点，指挥所有点的总花费最小，叫做最小指挥总花费\n// 一共m条操作，格式 x v : 先把x的点权增加v，然后打印此时的最小指挥总花费\n// 注意参数v有可能是负数，但题目保证任何时候，点权不会出现负数\n// 1 <= n、m <= 10^5\n// 1 <= 边权 <= 1000\n// -1000 <= v <= +1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3345\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Fantasy1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int[] cent = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN];\n\tpublic static long[] addCost = new long[MAXN];\n\tpublic static long[] minusCost = new long[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, a, b, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int a, int b, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = a;\n\t\tstack[stacksize][3] = b;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\ta = stack[stacksize][2];\n\t\tb = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f, int dis) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tdist[u] = dis;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int cur, int father, int distance) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, distance, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdist[u] = a;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, a + w, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = b;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, 0, b, -2);\n\t\t\t\tpush(son[u], 0, 0, b, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tint nextCent = getCentroid(v, u);\n\t\t\t\tcent[e] = nextCent;\n\t\t\t\tcentroidTree(nextCent, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int x, int v) {\n\t\tsum[x] += v;\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tsum[fa] += v;\n\t\t\taddCost[fa] += 1L * v * dist;\n\t\t\tminusCost[cur] += 1L * v * dist;\n\t\t}\n\t}\n\n\tpublic static long query(int x) {\n\t\tlong ans = addCost[x];\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tans += addCost[fa];\n\t\t\tans -= minusCost[cur];\n\t\t\tans += (sum[fa] - sum[cur]) * dist;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long compute(int u) {\n\t\tlong ans = query(u);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (query(v) < ans) {\n\t\t\t\treturn compute(cent[e]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\t// dfs1(1, 0, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0, 0);\n\t\tdfs4(1, 1);\n\t\tint root = getCentroid(1, 0);\n\t\tcentroidTree(root, 0);\n\t\tfor (int i = 1, x, v; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tadd(x, v);\n\t\t\tout.println(compute(root));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_Fantasy1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
