9ac8113c-0486-458e-b6d3-b4c4dcd5a858	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// 开店，java版\n// 一共n个人，每个人有年龄，给定n-1条路，每条路有距离，路把人连成一棵树\n// 一共m条查询，格式 u l r : 查询年龄范围[l, r]的所有人，到第u号人的距离总和\n// 1 <= n <= 1.5 * 10^5    1 <= m <= 2 * 10^5\n// 0 <= 年龄值 <= 10^9      1 <= 距离值 <= 1000\n// 本题要求强制在线，得到操作参数的规则，打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P3241\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_OpenStore1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXK = 4000001;\n\tpublic static int n, m, A;\n\tpublic static int[] age = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\t// cur列表(年龄，到当前重心距离)\n\tpublic static int[] curl = new int[MAXN];\n\tpublic static int[] curr = new int[MAXN];\n\tpublic static int[] curAge = new int[MAXK];\n\tpublic static long[] curSum = new long[MAXK];\n\tpublic static int cntc;\n\n\t// fa列表(年龄，到上级重心距离)\n\tpublic static int[] fal = new int[MAXN];\n\tpublic static int[] far = new int[MAXN];\n\tpublic static int[] faAge = new int[MAXK];\n\tpublic static long[] faSum = new long[MAXK];\n\tpublic static int cntf;\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, a, b, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int a, int b, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = a;\n\t\tstack[stacksize][3] = b;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\ta = stack[stacksize][2];\n\t\tb = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f, int dis) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tdist[u] = dis;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int cur, int father, int distance) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, distance, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdist[u] = a;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, a + w, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = b;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, 0, b, -2);\n\t\t\t\tpush(son[u], 0, 0, b, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\t// 来到了一片连通区，当前重心是rt，上级重心是centfa[rt]\n\t// 生成两个列表，距离到当前重心的列表，距离到上级重心的列表\n\tpublic static void getList1(int u, int fa, int sum, int rt) {\n\t\tcurAge[++cntc] = age[u];\n\t\tcurSum[cntc] = sum;\n\t\tif (centfa[rt] > 0) {\n\t\t\tfaAge[++cntf] = age[u];\n\t\t\tfaSum[cntf] = getDist(u, centfa[rt]);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetList1(v, u, sum + w, rt);\n\t\t\t}\n\t\t}\n\t}\n\n\t// getList1的迭代版\n\tpublic static void getList2(int cur, int father, int psum, int cen) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, psum, cen, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tcurAge[++cntc] = age[u];\n\t\t\t\tcurSum[cntc] = a;\n\t\t\t\tif (centfa[b] > 0) {\n\t\t\t\t\tfaAge[++cntf] = age[u];\n\t\t\t\t\tfaSum[cntf] = getDist(u, centfa[b]);\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, a + w, b, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tcurl[u] = cntc + 1;\n\t\tfal[u] = cntf + 1;\n\t\t// getList1(u, 0, 0, u);\n\t\tgetList2(u, 0, 0, u);\n\t\tcurr[u] = cntc;\n\t\tfar[u] = cntf;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 查询x在有序数组arr中的排名\n\tpublic static int kth(int[] arr, int l, int r, int x) {\n\t\tint ans = r + 1;\n\t\twhile (l <= r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (arr[mid] >= x) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 每个对象两个属性(age, sum)，所有对象根据年龄排序\n\t// java自带的排序慢，手撸双指针快排，C++实现时可以用自带的排序\n\tpublic static void sort(int[] age, long[] sum, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r, pivot = age[(l + r) >> 1], tmp1;\n\t\tlong tmp2;\n\t\twhile (i <= j) {\n\t\t\twhile (age[i] < pivot) i++;\n\t\t\twhile (age[j] > pivot) j--;\n\t\t\tif (i <= j) {\n\t\t\t\ttmp1 = age[i]; age[i] = age[j]; age[j] = tmp1;\n\t\t\t\ttmp2 = sum[i]; sum[i] = sum[j]; sum[j] = tmp2;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsort(age, sum, l, j);\n\t\tsort(age, sum, i, r);\n\t}\n\n\tpublic static long nodeCnt, pathSum;\n\n\t// 下标范围[l...r]代表当前节点的列表，找到年龄范围[agel, ager]的人\n\t// 查到的人数设置给nodeCnt，查到的距离总和设置给pathSum\n\tpublic static void query(int[] age, long[] sum, int l, int r, int agel, int ager) {\n\t\tnodeCnt = pathSum = 0;\n\t\tif (l <= r) {\n\t\t\tint a = kth(age, l, r, agel);\n\t\t\tint b = kth(age, l, r, ager + 1) - 1;\n\t\t\tif (a <= b) {\n\t\t\t\tnodeCnt = b - a + 1;\n\t\t\t\tpathSum = sum[b] - (a == l ? 0 : sum[a - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute(int x, int agel, int ager) {\n\t\tquery(curAge, curSum, curl[x], curr[x], agel, ager);\n\t\tlong ans = pathSum;\n\t\tlong cnt1, sum1, cnt2, sum2;\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tquery(curAge, curSum, curl[fa], curr[fa], agel, ager);\n\t\t\tcnt1 = nodeCnt;\n\t\t\tsum1 = pathSum;\n\t\t\tquery(faAge, faSum, fal[cur], far[cur], agel, ager);\n\t\t\tcnt2 = nodeCnt;\n\t\t\tsum2 = pathSum;\n\t\t\tans += sum1;\n\t\t\tans -= sum2;\n\t\t\tans += (cnt1 - cnt2) * getDist(x, fa);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tA = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tage[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\t// dfs1(1, 0, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0, 0);\n\t\tdfs4(1, 1);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsort(curAge, curSum, curl[i], curr[i]);\n\t\t\tfor (int j = curl[i] + 1; j <= curr[i]; j++) {\n\t\t\t\tcurSum[j] += curSum[j - 1];\n\t\t\t}\n\t\t\tsort(faAge, faSum, fal[i], far[i]);\n\t\t\tfor (int j = fal[i] + 1; j <= far[i]; j++) {\n\t\t\t\tfaSum[j] += faSum[j - 1];\n\t\t\t}\n\t\t}\n\t\tlong lastAns = 0;\n\t\tfor (int i = 1, u, l, r; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tl = (int) ((lastAns + l) % A);\n\t\t\tr = (int) ((lastAns + r) % A);\n\t\t\tif (l > r) {\n\t\t\t\tint tmp = l; l = r; r = tmp;\n\t\t\t}\n\t\t\tlastAns = compute(u, l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code05_OpenStore1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
