 v = tog[e];\n//        if (!vis[v]) {\n//            solve(getCentroid(v, u));\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> color[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1, l, r, x; i <= m; i++) {\n//        cin >> l >> r >> x;\n//        addQuery(x, l, r, i);\n//    }\n//    solve(getCentroid(1, 0));\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}	模板：Code06_ChengDu2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
d2c68df9-0e81-4f8b-8d5e-40385a017846	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// 捉迷藏，点分树的解，java版\n// 树上有n个点，点的初始颜色为黑，给定n-1条边，边权都是1\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 C x : 改变点x的颜色，黑变成白，白变成黑\n// 操作 G   : 打印最远的两个黑点的距离，只有一个黑点打印0，无黑点打印-1\n// 1 <= n <= 10^5    1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2056\n// 提交以下的code，提交时请把类名改成"Main"，一个测试用例空间超标\n// 本节课Code07_HideSeek3文件是最优解的实现，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.PriorityQueue;\n\npublic class Code07_HideSeek1 {\n\n\tstatic class Set {\n\t\tPriorityQueue<Integer> addHeap;\n\t\tPriorityQueue<Integer> delHeap;\n\n\t\tpublic Set() {\n\t\t\taddHeap = new PriorityQueue<>((a, b) -> b.compareTo(a));\n\t\t\tdelHeap = new PriorityQueue<>((a, b) -> b.compareTo(a));\n\t\t}\n\n\t\tvoid clean() {\n\t\t\twhile (!delHeap.isEmpty() && delHeap.peek().equals(addHeap.peek())) {\n\t\t\t\taddHeap.poll();\n\t\t\t\tdelHeap.poll();\n\t\t\t}\n\t\t}\n\n\t\tint popHead() {\n\t\t\tint ans = addHeap.poll();\n\t\t\tclean();\n\t\t\treturn ans;\n\t\t}\n\n\t\tint size() {\n\t\t\treturn addHeap.size() - delHeap.size();\n\t\t}\n\n\t\tvoid add(int v) {\n\t\t\taddHeap.add(v);\n\t\t}\n\n\t\tvoid del(int v) {\n\t\t\tdelHeap.add(v);\n\t\t\tclean();\n\t\t}\n\n\t\tint first() {\n\t\t\treturn addHeap.peek();\n\t\t}\n\n\t\tint second() {\n\t\t\tint a = popHead();\n\t\t\tint b = first();\n\t\t\tadd(a);\n\t\t\treturn b;\n\t\t}\n\t}\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static boolean[] black = new boolean[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\t// distFa[u] : u的连通区里，每个黑点到上级重心的距离，组成的集合\n\t// sonMax[u] : u的每个儿子连通区里，都选一个最远的黑点，到u的最大距离，组成的集合\n\t//             如果u自己是黑点，那么0要加入集合\n\t// maxDist   : 每个重心在连通区里，选两个最远黑点的最大距离，作为自己的答案，放入全局集合\n\tpublic static Set[] distFa = new Set[MAXN];\n\tpublic static Set[] sonMax = new Set[MAXN];\n\tpublic static Set maxDist = new Set();\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, f, t, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int t, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = t;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\tt = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 重链剖分收集信息递归版，java会爆栈，C++不会\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 根据重儿子剖分的递归版，java会爆栈，C++不会\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改成迭代版\n\tpublic static void dfs3(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2改成迭代版\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = t;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, t, -2);\n\t\t\t\tpush(son[u], 0, t, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, t, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 找重心需要计算子树大小的递归版，java会爆栈，C++不会\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// getSize1的迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dep[x] + dep[y] - (dep[getLca(x, y)] << 1);\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addAns(int x) {\n\t\tif (sonMax[x].size() >= 2) {\n\t\t\tmaxDist.add(sonMax[x].first() + sonMax[x].second());\n\t\t}\n\t}\n\n\tpublic static void delAns(int x) {\n\t\tif (sonMax[x].size() >= 2) {\n\t\t\tmaxDist.del(sonMax[x].first() + sonMax[x].second());\n\t\t}\n\t}\n\n\tpublic static void on(int x) {\n\t\tdelAns(x);\n\t\tsonMax[x].del(0);\n\t\taddAns(x);\n\t\tfor (int u = x, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\tdelAns(fa);\n\t\t\tsonMax[fa].del(distFa[u].first());\n\t\t\tdistFa[u].del(getDist(x, fa));\n\t\t\tif (distFa[u].size() > 0) {\n\t\t\t\tsonMax[fa].add(distFa[u].first());\n\t\t\t}\n\t\t\taddAns(fa);\n\t\t}\n\t}\n\n\tpublic static void off(int x) {\n\t\tdelAns(x);\n\t\tsonMax[x].add(0);\n\t\taddAns(x);\n\t\tfor (int u = x, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\tdelAns(fa);\n\t\t\tif (distFa[u].size() > 0) {\n\t\t\t\tsonMax[fa].del(distFa[u].first());\n\t\t\t}\n\t\t\tdistFa[u].add(getDist(x, fa));\n\t\t\tsonMax[fa].add(distFa[u].first());\n\t\t\taddAns(fa);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tblack[i] = true;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdistFa[i] = new Set();\n\t\t\tsonMax[i] = new Set();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int u = i, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\t\tdistFa[u].add(getDist(i, fa));\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsonMax[i].add(0);\n\t\t\tif (centfa[i] > 0) {\n\t\t\t\tsonMax[centfa[i]].add(distFa[i].first());\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddAns(i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0);\n\t\tdfs4(1, 1);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tprepare();\n\t\tm = in.nextInt();\n\t\tint blackCnt = n;\n\t\tchar op;\n\t\tfor (int i = 1, x; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'C') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tblack[x] = !black[x];\n\t\t\t\tif (black[x]) {\n\t\t\t\t\toff(x);\n\t\t\t\t\tblackCnt++;\n\t\t\t\t} else {\n\t\t\t\t\ton(x);\n\t\t\t\t\tblackCnt--;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (blackCnt <= 1) {\n\t\t\t\t\tout.println(blackCnt - 1);\n\t\t\t\t} else {\n\t\t\t\t\tout.println(maxDist.first());\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}	模板：Code07_HideSeek1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
