701cdd56-debf-4e55-af3d-d3f69d32bb92	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// 捉迷藏，最优解，树的括号序 + 巧妙线段树，java版\n// 树上有n个点，点的初始颜色为黑，给定n-1条边，边权都是1\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 C x : 改变点x的颜色，黑变成白，白变成黑\n// 操作 G   : 打印最远的两个黑点的距离，只有一个黑点打印0，无黑点打印-1\n// 1 <= n <= 10^5    1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2056\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_HideSeek3 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 12;\n\tpublic static int INF = 1000000001;\n\tpublic static int PAR = -1;\n\tpublic static int PAL = -2;\n\tpublic static int n, m;\n\tpublic static boolean[] black = new boolean[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN * 3];\n\tpublic static int cntd;\n\n\t// 以下概念都是括号序列消除到最简状态之后的情况\n\t// pr : 右括号数量\n\t// pl : 左括号数量\n\t// ladd   : 左端点到任意黑点，max(右括号 + 左括号)\n\t// lminus : 左端点到任意黑点，max(左括号 - 右括号)\n\t// radd   : 任意黑点到右端点，max(右括号 + 左括号)\n\t// rminus : 任意黑点到右端点，max(右括号 - 左括号)\n\t// dist   : 选择两个黑点的最大距离\n\t// 注意区分lminus、rminus\n\tpublic static int[] pr = new int[MAXT];\n\tpublic static int[] pl = new int[MAXT];\n\tpublic static int[] ladd = new int[MAXT];\n\tpublic static int[] lminus = new int[MAXT];\n\tpublic static int[] radd = new int[MAXT];\n\tpublic static int[] rminus = new int[MAXT];\n\tpublic static int[] dist = new int[MAXT];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, f, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 收集括号序递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tseg[++cntd] = PAL;\n\t\tseg[++cntd] = u;\n\t\tdfn[u] = cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tseg[++cntd] = PAR;\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tseg[++cntd] = PAL;\n\t\t\t\tseg[++cntd] = u;\n\t\t\t\tdfn[u] = cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tseg[++cntd] = PAR;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tint pre = i << 1;\n\t\tint post = i << 1 | 1;\n\t\tif (pl[pre] > pr[post]) {\n\t\t\tpr[i] = pr[pre];\n\t\t\tpl[i] = pl[pre] - pr[post] + pl[post];\n\t\t} else {\n\t\t\tpr[i] = pr[pre] + pr[post] - pl[pre];\n\t\t\tpl[i] = pl[post];\n\t\t}\n\t\tladd[i] = Math.max(ladd[pre], Math.max(pr[pre] + ladd[post] - pl[pre], pr[pre] + pl[pre] + lminus[post]));\n\t\tlminus[i] = Math.max(lminus[pre], pl[pre] - pr[pre] + lminus[post]);\n\t\tradd[i] = Math.max(radd[post], Math.max(radd[pre] - pr[post] + pl[post], rminus[pre] + pr[post] + pl[post]));\n\t\trminus[i] = Math.max(rminus[post], rminus[pre] + pr[post] - pl[post]);\n\t\tdist[i] = Math.max(Math.max(dist[pre], dist[post]), Math.max(radd[pre] + lminus[post], rminus[pre] + ladd[post]));\n\t}\n\n\tpublic static void point(int i, int v) {\n\t\tpr[i] = pl[i] = 0;\n\t\tladd[i] = lminus[i] = radd[i] = rminus[i] = dist[i] = -INF;\n\t\tif (v == PAR) {\n\t\t\tpr[i] = 1;\n\t\t} else if (v == PAL) {\n\t\t\tpl[i] = 1;\n\t\t} else if (black[v]) {\n\t\t\tladd[i] = lminus[i] = radd[i] = rminus[i] = dist[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tpoint(i, seg[l]);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tpoint(i, seg[l]);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tblack[i] = true;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tbuild(1, cntd, 1);\n\t\tm = in.nextInt();\n\t\tint blackCnt = n;\n\t\tchar op;\n\t\tfor (int i = 1, x; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'C') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tblack[x] = !black[x];\n\t\t\t\tif (black[x]) {\n\t\t\t\t\tblackCnt++;\n\t\t\t\t} else {\n\t\t\t\t\tblackCnt--;\n\t\t\t\t}\n\t\t\t\tupdate(dfn[x], 1, cntd, 1);\n\t\t\t} else {\n\t\t\t\tif (blackCnt <= 1) {\n\t\t\t\t\tout.println(blackCnt - 1);\n\t\t\t\t} else {\n\t\t\t\t\tout.println(dist[1]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n	模板：Code07_HideSeek3.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
5109a1a2-8577-4a5e-b210-d421d26613ff	e96d7dd8-5f3b-443f-adef-95ee0420ba2a	java	package class185;\n\n// 捉迷藏，最优解，树的括号序 + 巧妙线段树，C++版\n// 树上有n个点，点的初始颜色为黑，给定n-1条边，边权都是1\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 C x : 改变点x的颜色，黑变成白，白变成黑\n// 操作 G   : 打印最远的两个黑点的距离，只有一个黑点打印0，无黑点打印-1\n// 1 <= n <= 10^5    1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2056\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXT = MAXN * 12;\n//const int INF = 1000000001;\n//const int PAR = -1;\n//const int PAL = -2;\n//int n, m;\n//bool black[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int seg[MAXN * 3];\n//int cntd;\n//\n//int pr[MAXT];\n//int pl[MAXT];\n//int ladd[MAXT];\n//int lminus[MAXT];\n//int radd[MAXT];\n//int rminus[MAXT];\n//int dist[MAXT];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u, int fa) {\n//    seg[++cntd] = PAL;\n//    seg[++cntd] = u;\n//    dfn[u] = cntd;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            dfs(v, u);\n//        }\n//    }\n//    seg[++cntd] = PAR;\n//}\n//\n//void up(int i) {\n//    int pre = i << 1;\n//    int post = i << 1 | 1;\n//    if (pl[pre] > pr[post]) {\n//        pr[i] = pr[pre];\n//        pl[i] = pl[pre] - pr[post] + pl[post];\n//    } else {\n//        pr[i] = pr[pre] + pr[post] - pl[pre];\n//        pl[i] = pl[post];\n//    }\n//    ladd[i] = max(ladd[pre], max(pr[pre] + ladd[post] - pl[pre], pr[pre] + pl[pre] + lminus[post]));\n//    lminus[i] = max(lminus[pre], pl[pre] - pr[pre] + lminus[post]);\n//    radd[i] = max(radd[post], max(radd[pre] - pr[post] + pl[post], rminus[pre] + pr[post] + pl[post]));\n//    rminus[i] = max(rminus[post], rminus[pre] + pr[post] - pl[post]);\n//    dist[i] = max(max(dist[pre], dist[post]), max(radd[pre] + lminus[post], rminus[pre] + ladd[post]));\n//}\n//\n//void point(int i, int v) {\n//    pr[i] = pl[i] = 0;\n//    ladd[i] = lminus[i] = radd[i] = rminus[i] = dist[i] = -INF;\n//    if (v == PAR) {\n//        pr[i] = 1;\n//    } else if (v == PAL) {\n//        pl[i] = 1;\n//    } else if (black[v]) {\n//        ladd[i] = lminus[i] = radd[i] = rminus[i] = dist[i] = 0;\n//    }\n//}\n//\n//void build(int l, int r, int i) {\n//    if (l == r) {\n//        point(i, seg[l]);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        build(l, mid, i << 1);\n//        build(mid + 1, r, i << 1 | 1);\n//        up(i);\n//    }\n//}\n//\n//void update(int jobi, int l, int r, int i) {\n//    if (l == r) {\n//        point(i, seg[l]);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            update(jobi, l, mid, i << 1);\n//        } else {\n//            update(jobi, mid + 1, r, i << 1 | 1);\n//        }\n//        up(i);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        black[i] = true;\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs(1, 0);\n//    build(1, cntd, 1);\n//    cin >> m;\n//    int blackCnt = n;\n//    char op;\n//    for (int i = 1, x; i <= m; i++) {\n//        cin >> op;\n//        if (op == 'C') {\n//            cin >> x;\n//            black[x] = !black[x];\n//            if (black[x]) {\n//                blackCnt++;\n//            } else {\n//                blackCnt--;\n//            }\n//            update(dfn[x], 1, cntd, 1);\n//        } else {\n//            if (blackCnt <= 1) {\n//                cout << (blackCnt - 1) << '\\n';\n//            } else {\n//                cout << dist[1] << '\\n';\n//            }\n//        }\n//    }\n//    return 0;\n//}	模板：Code07_Hi