ac936fb7-7240-4ed5-b919-a9c457796e5e	dbda5e44-b693-4c79-aa7b-4262f231533c	java	package class195;\n\n// 遗产，java版\n// 一共n个点，给定起点s，一共q条操作，操作类型如下\n// 操作 1 x y w   : 从点x到点y增加有向边，边权是w\n// 操作 2 x l r w : 从点x到l~r范围的每个点增加有向边，边权都是w\n// 操作 3 x l r w : 从l~r范围的每个点到点x增加有向边，边权都是w\n// 所有操作完成后，计算起点s到每个点的最短距离并打印，如果不连通打印-1\n// 1 <= n、q <= 10^5\n// 1 <= w <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF786B\n// 测试链接 : https://codeforces.com/problemset/problem/786/B\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.PriorityQueue;\n\npublic class Code01_Legacy1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int MAXE = MAXN * 30;\n\tpublic static long INF = 1L << 60;\n\tpublic static int n, q, s;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\t// 出树和入树共用ls和rs\n\t// 出树的头节点编号rootOut\n\t// 入树的头节点编号rootIn\n\t// 空间利用cntt计数来分配\n\t// 可持久化线段树，即主席树，也是这种设计\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int rootOut, rootIn;\n\tpublic static int cntt;\n\n\tpublic static long[] dist = new long[MAXT];\n\tpublic static boolean[] vis = new boolean[MAXT];\n\t// 当前点、源点到当前点的代价\n\tpublic static PriorityQueue<long[]> heap = new PriorityQueue<>((x, y) -> Long.compare(x[1], y[1]));\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt, 0);\n\t\t\taddEdge(rs[rt], rt, 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt], 0);\n\t\t\taddEdge(rt, rs[rt], 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int jobw, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i, jobw);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int jobw, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, jobw);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, jobw, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, jobw, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dijkstra() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t}\n\t\tdist[s] = 0;\n\t\theap.add(new long[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tlong[] cur = heap.poll();\n\t\t\tint u = (int) cur[0];\n\t\t\tlong d = cur[1];\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\t\tint v = to[e];\n\t\t\t\t\tint w = weight[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new long[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tq = in.nextInt();\n\t\ts = in.nextInt();\n\t\tcntt = n;\n\t\trootOut = buildOut(1, n);\n\t\trootIn = buildIn(1, n);\n\t\tfor (int i = 1, op, x, y, l, r, w; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\taddEdge(x, y, w);\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\txToRange(x, l, r, w, 1, n, rootIn);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\trangeToX(l, r, x, w, 1, n, rootOut);\n\t\t\t}\n\t\t}\n\t\tdijkstra();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(dist[i] == INF ? -1 : dist[i]);\n\t\t\tout.print(" ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code01_Legacy1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
20e896a9-6729-48ec-9cd1-fe04295223d2	53918e6b-d5a7-42a9-9b64-3307c74afc39	java	package class188;\n\n// 无序字母对，C++版\n// 给定n个字母对，每个字母对有两个字母，字母只可能是A~Z、a~z\n// 字母对内部不区分顺序，ab和ba是相同的，但是区分大小写，Ab和ab是不同的\n// 题目不会给定重复的字母对，构造一个长度n+1的字符串，让每个字母对都出现\n// 一个字母对的两个字母，在字符串中相邻出现即可，请输出字典序最小的方案\n// 如果没有满足要求的方案，打印"No Solution"\n// 1 <= n <= 1326\n// 测试链接 : https://www.luogu.com.cn/problem/P1341\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 53;\n//const int MAXM = 2001;\n//int n = 52, m;\n//char arr[MAXM][2];\n//\n//int graph[MAXN][MAXN];\n//int deg[MAXN];\n//int cur[MAXN];\n//\n//int path[MAXM];\n//int cntp;\n//\n//int getInt(char c) {\n//    return c <= 'Z' ? (c - 'A' + 1) : (c - 'a' + 27);\n//}\n//\n//char getChar(int v) {\n//    return (char)(v <= 26 ? ('A' + v - 1) : ('a' + v - 27));\n//}\n//\n//void connect() {\n//    for (int i = 1, u, v; i <= m; i++) {\n//        u = getInt(arr[i][0]);\n//        v = getInt(arr[i][1]);\n//        graph[u][v]++;\n//        graph[v][u]++;\n//        deg[u]++;\n//        deg[v]++;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cur[i] = 1;\n//    }\n//}\n//\n//int undirectedStart() {\n//    int odd = 0;\n//    for (int i = 1; i <= n; i++) {\n//        if ((deg[i] & 1) == 1) {\n//            odd++;\n//        }\n//    }\n//    if (odd != 0 && odd != 2) {\n//        return -1;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (odd == 0 && deg[i] > 0) {\n//            return i;\n//        }\n//        if (odd == 2 && (deg[i] & 1) == 1) {\n//            return i;\n//        }\n//    }\n//    return -1;\n//}\n//\n//void euler(int u) {\n//    for (int v = cur[u]; v <= n; v = cur[u]) {\n//        cur[u]++;\n//        if (graph[u][v] > 0) {\n//            graph[u][v]--;\n//            graph[v][u]--;\n//            euler(v);\n//        }\n//    }\n//    path[++cntp] = u;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nu