1ac21693-7173-4ca6-8f08-8f530c7d6b15	53918e6b-d5a7-42a9-9b64-3307c74afc39	java	package class188;\n\n// 邮递员，java版\n// 一共n个点，m条有向边，不会有重边和自环\n// 邮递员一定要从1号点开始，最后回到1号点，每条边都要走1次\n// 邮递员依次走过的点的编号，就可以形成一个路径\n// 给定t个序列，每个序列先给定长度k，然后是k个节点的编号\n// 希望每个序列都是路径的连续子段，如果不存在这样的路径，打印"NIE"\n// 如果存在这样的路径，先打印"TAK"，然后打印依次走过的节点编号\n// 2 <= n <= 5 * 10^4    1 <= m <= 2 * 10^5\n// 0 <= t <= 10^4        所有序列的节点总量 <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P3443\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\n\npublic class Code10_Postman1 {\n\n\tstatic class PairMap {\n\t\tpublic HashMap<Long, Integer> map = new HashMap<>();\n\n\t\tpublic long key(int a, int b) {\n\t\t\treturn (((long) a) << 32) | (b & 0xffffffffL);\n\t\t}\n\n\t\tpublic boolean contains(int a, int b) {\n\t\t\treturn map.containsKey(key(a, b));\n\t\t}\n\n\t\tpublic boolean isEmpty() {\n\t\t\treturn map.isEmpty();\n\t\t}\n\n\t\tpublic void put(int a, int b, int v) {\n\t\t\tmap.put(key(a, b), v);\n\t\t}\n\n\t\tpublic int get(int a, int b) {\n\t\t\treturn map.get(key(a, b));\n\t\t}\n\n\t\tpublic void remove(int a, int b) {\n\t\t\tmap.remove(key(a, b));\n\t\t}\n\n\t\tpublic void clear() {\n\t\t\tmap.clear();\n\t\t}\n\t}\n\n\tpublic static int MAXN = 50005;\n\tpublic static int MAXM = 200005;\n\tpublic static int MAXC = 2000005;\n\tpublic static int n, m, t;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\tpublic static int[] seq = new int[MAXC];\n\n\tpublic static PairMap pairEdge = new PairMap();\n\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXM];\n\tpublic static int[] tog = new int[MAXM];\n\tpublic static int[] chainHead = new int[MAXM];\n\tpublic static int cntg;\n\tpublic static int edgeCnt;\n\n\tpublic static int[] cur = new int[MAXN];\n\tpublic static int[] inDeg = new int[MAXN];\n\tpublic static int[] outDeg = new int[MAXN];\n\n\tpublic static boolean[] isHead = new boolean[MAXM];\n\tpublic static int[] etoe = new int[MAXM];\n\tpublic static boolean[] vis = new boolean[MAXM];\n\n\tpublic static int[] path = new int[MAXM];\n\tpublic static int cntp;\n\n\tpublic static int[] ans = new int[MAXM];\n\tpublic static int cnta;\n\n\tpublic static int[][] sta = new int[MAXM][2];\n\tpublic static int u, h;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int c) {\n\t\tsta[stacksize][0] = u;\n\t\tsta[stacksize][1] = c;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = sta[stacksize][0];\n\t\th = sta[stacksize][1];\n\t}\n\n\tpublic static void addEdge(int x, int y, int h) {\n\t\tnextg[++cntg] = headg[x];\n\t\ttog[cntg] = y;\n\t\tchainHead[cntg] = h;\n\t\theadg[x] = cntg;\n\t}\n\n\tpublic static boolean linkEdge() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tpairEdge.put(a[i], b[i], i);\n\t\t\tisHead[i] = true;\n\t\t}\n\t\tint siz = seq[1], l = 2, r = l + siz - 1;\n\t\tint a, b, ledge, redge;\n\t\twhile (siz > 0) {\n\t\t\tledge = 0;\n\t\t\tfor (int i = l; i < r; i++) {\n\t\t\t\ta = seq[i];\n\t\t\t\tb = seq[i + 1];\n\t\t\t\tif (!pairEdge.contains(a, b)) {\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t\tredge = pairEdge.get(a, b);\n\t\t\t\tif (ledge != 0) {\n\t\t\t\t\tif (etoe[ledge] != 0 && etoe[ledge] != redge) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\tetoe[ledge] = redge;\n\t\t\t\t\tisHead[redge] = false;\n\t\t\t\t}\n\t\t\t\tledge = redge;\n\t\t\t}\n\t\t\tsiz = seq[r + 1];\n\t\t\tl = r + 2;\n\t\t\tr = l + siz - 1;\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static int getLinkEnd(int edge) {\n\t\twhile (etoe[edge] != 0) {\n\t\t\tif (vis[edge] == true) {\n\t\t\t\treturn -1;\n\t\t\t}\n\t\t\tvis[edge] = true;\n\t\t\tedge = etoe[edge];\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static boolean compress() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (isHead[i]) {\n\t\t\t\tint x = a[i];\n\t\t\t\tint y = b[i];\n\t\t\t\tif (etoe[i] != 0) {\n\t\t\t\t\tint end = getLinkEnd(i);\n\t\t\t\t\tif (end == -1) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\ty = b[end];\n\t\t\t\t}\n\t\t\t\toutDeg[x]++;\n\t\t\t\tinDeg[y]++;\n\t\t\t\tedgeCnt++;\n\t\t\t\taddEdge(x, y, i);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (inDeg[i] != outDeg[i]) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcur[i] = headg[i];\n\t\t}\n\t\treturn true;\n\t}\n\n\t// 递归版，u表示当前节点，h表示来到当前节点的链，链头是什么边的序号\n\tpublic static void euler1(int u, int h) {\n\t\tfor (int e = cur[u]; e > 0; e = cur[u]) {\n\t\t\tcur[u] = nextg[e];\n\t\t\teuler1(tog[e], chainHead[e]);\n\t\t}\n\t\tpath[++cntp] = h;\n\t}\n\n\t// 迭代版\n\tpublic static void euler2(int node, int chainh) {\n\t\tstacksize = 0;\n\t\tpush(node, chainh);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tint e = cur[u];\n\t\t\tif (e > 0) {\n\t\t\t\tcur[u] = nextg[e];\n\t\t\t\tpush(u, h);\n\t\t\t\tpush(tog[e], chainHead[e]);\n\t\t\t} else {\n\t\t\t\tpath[++cntp] = h;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void decompress() {\n\t\tans[++cnta] = 1;\n\t\tfor (int i = cntp - 1; i >= 1; i--) {\n\t\t\tint e = path[i];\n\t\t\twhile (e > 0) {\n\t\t\t\tans[++cnta] = b[e];\n\t\t\t\te = etoe[e];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tif (!linkEdge()) {\n\t\t\treturn false;\n\t\t}\n\t\tif (!compress()) {\n\t\t\treturn false;\n\t\t}\n\t\t// euler1(1, -1);\n\t\teuler2(1, -1);\n\t\tif (cntp != edgeCnt + 1) {\n\t\t\treturn false;\n\t\t}\n\t\tdecompress();\n\t\treturn cnta == m + 1;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tt = in.nextInt();\n\t\tfor (int i = 1, siz, idx = 0; i <= t; i++) {\n\t\t\tsiz = in.nextInt();\n\t\t\tseq[++idx] = siz;\n\t\t\tfor (int j = 1; j <= siz; j++) {\n\t\t\t\tseq[++idx] = in.nextInt();\n\t\t\t}\n\t\t}\n\t\tboolean check = compute();\n\t\tif (!check) {\n\t\t\tout.println("NIE");\n\t\t} else {\n\t\t\tout.println("TAK");\n\t\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code10_Postman1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
