0f675660-bd8a-4c3d-bdf2-5699fe852c59	661fea7b-f964-478f-9d0d-9ef36ebcd166	java	package class194;\n\n// 路径问题，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通，无重边和自环\n// 给定三个不同的点a、b、c，打印是否存在一条路径\n// 从a到达b，然后从b到达c，要求途中不能出现重复的点\n// 1 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc318_g\n// 测试链接 : https://atcoder.jp/contests/abc318/tasks/abc318_g\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_PathProblem1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 200001;\n\tpublic static int n, m, a, b, c, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static boolean[] flag = new boolean[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tdep[u] = dep[f] + 1;\n\t\tfa[u] = f;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean check() {\n\t\tfor (int e = head2[b]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tflag[v] = true;\n\t\t}\n\t\twhile (a != c) {\n\t\t\tif (dep[a] < dep[c]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = c;\n\t\t\t\tc = tmp;\n\t\t\t}\n\t\t\ta = fa[a];\n\t\t\tif (flag[a]) {\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\ta = in.nextInt();\n\t\tb = in.nextInt();\n\t\tc = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs(1, 0);\n\t\tout.println(check() ? "Yes" : "No");\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_PathProblem1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
