or (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa) {\n//            dpOnTree(v, u);\n//            if (u <= n) {\n//                ans += 1LL * siz[v] * (total - siz[v] - 1);\n//            } else {\n//                ans += 1LL * siz[v] * (deg[u] - 2) * (total - siz[v]);\n//            }\n//            siz[u] += siz[v];\n//        }\n//    }\n//    siz[u] += u <= n ? 1 : 0;\n//    if (u <= n) {\n//        ans += 1LL * (siz[u] - 1) * (total - siz[u]);\n//    } else {\n//        ans += 1LL * siz[u] * (deg[u] - 2) * (total - siz[u]);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntn = n;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge1(u, v);\n//        addEdge1(v, u);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            total = 0;\n//            tarjan(i);\n//            dpOnTree(i, 0);\n//        }\n//    }\n//    cout << ans << "\\n";\n//    return 0;\n//}	模板：Code05_Duathlon2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
397fcbf1-6da1-4dab-abdf-252f9a331f18	661fea7b-f964-478f-9d0d-9ef36ebcd166	java	package class194;\n\n// 边的查询，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通\n// 一共q条查询，格式 x y，含义如下\n// 所有从x到y的简单路径上出现的边中，统计有多少条边满足\n// 如果移除该边，x和y仍然可以互相到达，打印这个数量\n// 1 <= n、m、q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1763F\n// 测试链接 : https://codeforces.com/problemset/problem/1763/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_EdgeQueries1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q, cntn;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[][] stjump = new int[MAXN << 1][MAXP];\n\tpublic static int[] edgeCnt = new int[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int x, int y) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[x][p]] >= dep[y]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[x][0];\n\t}\n\n\tpublic static void dfsCnt(int u, int fa) {\n\t\tedgeCnt[u] += edgeCnt[fa];\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsCnt(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void buildEdgeCnt() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint fa = stjump[a[i]][0];\n\t\t\tint fb = stjump[b[i]][0];\n\t\t\tif (fa == fb || stjump[fa][0] == b[i]) {\n\t\t\t\tedgeCnt[fa]++;\n\t\t\t} else {\n\t\t\t\tedgeCnt[fb]++;\n\t\t\t}\n\t\t}\n\t\tfor (int i = n + 1; i <= cntn; i++) {\n\t\t\tif (edgeCnt[i] == 1) {\n\t\t\t\tedgeCnt[i] = 0;\n\t\t\t}\n\t\t}\n\t\tdfsCnt(1, 0);\n\t}\n\n\tpublic static int query(int x, int y) {\n\t\tint xylca = getLca(x, y);\n\t\tint lcafa = stjump[xylca][0];\n\t\treturn edgeCnt[x] + edgeCnt[y] - edgeCnt[xylca] - edgeCnt[lcafa];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge1(a[i], b[i]);\n\t\t\taddEdge1(b[i], a[i]);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs(1, 0);\n\t\tbuildEdgeCnt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tout.println(query(x, y));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_EdgeQueries1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
