a6a33bcd-bfd5-4813-b938-4228447bd7c6	661fea7b-f964-478f-9d0d-9ef36ebcd166	java	package class194;\n\n// 警察，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通并且无重边\n// 一共q条查询，每条查询是如下两种类型中的一种\n// 查询 1 a b c d : 已知c和d之间有边，如果删去这条边，打印a和b是否连通\n// 查询 2 a b c   : 如果删除点c，打印a和b是否连通\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 1 <= q <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4334\n// 提交以下的code，提交时请把类名改成"Main"\n// 本题卡常导致java的实现无法通过，很多递归函数索性也不改迭代了\n// 想通过用C++实现，本节课Code07_Policija2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\n\npublic class Code07_Policija1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 500001;\n\tpublic static int n, m, q, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int cnts;\n\n\tpublic static HashMap<Long, Integer> cutMap = new HashMap<>();\n\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[] son = new int[MAXN << 1];\n\tpublic static int[] top = new int[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addCut(int x, int y, int cut) {\n\t\tint a = Math.min(x, y);\n\t\tint b = Math.max(x, y);\n\t\tcutMap.put(((long) a << 32) | b, cut);\n\t}\n\n\tpublic static int getCut(int x, int y) {\n\t\tint a = Math.min(x, y);\n\t\tint b = Math.max(x, y);\n\t\tInteger ans = cutMap.get(((long) a << 32) | b);\n\t\treturn ans == null ? 0 : ans;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++cnts] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\t\taddCut(u, v, cntn);\n\t\t\t\t\t}\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[cnts--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean mustPass(int a, int b, int c) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] < dep[top[b]]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = b;\n\t\t\t\tb = tmp;\n\t\t\t}\n\t\t\tif (top[c] == top[a] && dep[c] <= dep[a]) {\n\t\t\t\treturn true;\n\t\t\t}\n\t\t\ta = fa[top[a]];\n\t\t}\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\treturn top[a] == top[c] && dep[b] <= dep[c] && dep[c] <= dep[a];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, op, a, b, c, d; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\td = in.nextInt();\n\t\t\t\tint cut = getCut(c, d);\n\t\t\t\tif (cut == 0) {\n\t\t\t\t\tout.println("yes");\n\t\t\t\t} else {\n\t\t\t\t\tout.println(mustPass(a, b, cut) ? "no" : "yes");\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\tout.println(mustPass(a, b, c) ? "no" : "yes");\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code07_Policija1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
