b79b82c9-4b16-4516-ba69-d11567de3554	661fea7b-f964-478f-9d0d-9ef36ebcd166	java	package class194;\n\n// 游客，java版\n// 一共n个城市、m条双向道路，所有城市都连通，商品只有一种\n// 每个城市给定商品报价，接下来有q条操作，操作类型有两种\n// 操作 C x y : 城市x的商品报价改成y\n// 操作 A x y : 从x到y可自由选路，但不能有重复城市，打印能遇到的最低报价\n// 1 <= n、m、q <= 10^5\n// 1 <= 商品报价 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF487E\n// 测试链接 : https://codeforces.com/problemset/problem/487/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\nimport java.util.TreeMap;\n\npublic class Code08_Tourists1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 100001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m, q, cntn;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int cnts;\n\n\t// nid是圆方树的点获得的dfn序号\n\t// cnti是圆方树的dfn序号计数\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[] son = new int[MAXN << 1];\n\tpublic static int[] top = new int[MAXN << 1];\n\tpublic static int[] nid = new int[MAXN << 1];\n\tpublic static int cnti;\n\n\t// 每个方点分配有序表\n\tpublic static HashMap<Integer, TreeMap<Integer, Integer>> maps = new HashMap<>();\n\t// 圆方树中每个点的点权\n\tpublic static int[] val = new int[MAXN << 1];\n\t// 线段树\n\tpublic static int[] minv = new int[MAXN << 3];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addNum(int u, int num) {\n\t\tif (!maps.containsKey(u)) {\n\t\t\tmaps.put(u, new TreeMap<>());\n\t\t}\n\t\tmaps.get(u).put(num, maps.get(u).getOrDefault(num, 0) + 1);\n\t}\n\n\tpublic static void delNum(int u, int num) {\n\t\tint cnt = maps.get(u).get(num);\n\t\tif (cnt == 1) {\n\t\t\tmaps.get(u).remove(num);\n\t\t} else {\n\t\t\tmaps.get(u).put(num, cnt - 1);\n\t\t}\n\t}\n\n\tpublic static int getMin(int u) {\n\t\treturn maps.get(u).firstKey();\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++cnts] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[cnts--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t\tif (u > n) {\n\t\t\t\t\taddNum(u, arr[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tnid[u] = ++cnti;\n\t\tval[nid[u]] = u <= n ? arr[u] : getMin(u);\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tminv[i] = Math.min(minv[i << 1], minv[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tminv[i] = val[l];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tminv[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn minv[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = INF;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int pathMin(int x, int y) {\n\t\tint ans = INF;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tint tmp = x;\n\t\t\t\tx = y;\n\t\t\t\ty = tmp;\n\t\t\t}\n\t\t\tans = Math.min(ans, query(nid[top[x]], nid[x], 1, cnti, 1));\n\t\t\tx = fa[top[x]];\n\t\t}\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tans = Math.min(ans, query(nid[y], nid[x], 1, cnti, 1));\n\t\tif (y > n) {\n\t\t\tans = Math.min(ans, arr[fa[y]]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tbuild(1, cnti, 1);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tchar op = in.nextChar();\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tif (op == 'C') {\n\t\t\t\tint father = fa[x];\n\t\t\t\tif (father > 0) {\n\t\t\t\t\tdelNum(father, arr[x]);\n\t\t\t\t\taddNum(father, y);\n\t\t\t\t\tupdate(nid[father], getMin(father), 1, cnti, 1);\n\t\t\t\t}\n\t\t\t\tarr[x] = y;\n\t\t\t\tupdate(nid[x], y, 1, cnti, 1);\n\t\t\t} else {\n\t\t\t\tout.println(pathMin(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tchar nextChar() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')));\n\t\t\treturn (char) c;\n\t\t}\n\t}\n\n}\n	模板：Code08_Tourists1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
