, cnti, 1);\n//        } else {\n//            cout << pathMin(x, y) << "\\n";\n//        }\n//    }\n//    return 0;\n//}	模板：Code08_Tourists2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4ee64c9e-e16a-4283-8104-3696a555995a	661fea7b-f964-478f-9d0d-9ef36ebcd166	java	package class194;\n\n// 战略游戏，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通，图中可能有重边\n// 一共有q条查询，每条查询格式 s K1 K2 .. Ks，含义如下\n// 当前查询涉及s个点，给出s个点的编号，你只能删掉一个另外的点\n// 删除该点后，只要这s个点中存在任意两点不连通，就算成功\n// 对每条查询，打印你能选择的点的个数\n// 2 <= n <= 10^5    1 <= m <= 2 * 10^5    1 <= q <= 10^5\n// 所有查询中s的总和 <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4606\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code09_StrategyGame1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXP = 20;\n\tpublic static int t, n, m, q, s, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// nid是圆方树的点获得的dfn序号\n\t// cnti是圆方树的dfn序号计数\n\tpublic static int[] dist = new int[MAXN << 1];\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[][] stjump = new int[MAXN << 1][MAXP];\n\tpublic static int[] nid = new int[MAXN << 1];\n\tpublic static int cnti;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN << 1][4];\n\tpublic static int u, status, fa, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int fa, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = fa;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\tfa = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head1[u];\n\t\t\t} else {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\t\tcntn++;\n\t\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = next1[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, 0, e);\n\t\t\t\t\tpush(v, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, 0, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dfs1(int u, int fa) {\n\t\tnid[u] = ++cnti;\n\t\tdist[u] = dist[fa] + (u <= n ? 1 : 0);\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dfs2(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, father, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tnid[u] = ++cnti;\n\t\t\t\tdist[u] = dist[fa] + (u <= n ? 1 : 0);\n\t\t\t\tdep[u] = dep[fa] + 1;\n\t\t\t\tstjump[u][0] = fa;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head2[u];\n\t\t\t} else {\n\t\t\t\te = next2[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, fa, e);\n\t\t\t\tif (to2[e] != fa) {\n\t\t\t\t\tpush(to2[e], 0, u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a; a = b; b = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - 2 * dist[getLca(x, y)];\n\t}\n\n\tpublic static void sort(int[] nums, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r;\n\t\tint pivot = nums[(l + r) >> 1];\n\t\twhile (i <= j) {\n\t\t\twhile (nid[nums[i]] < nid[pivot]) i++;\n\t\t\twhile (nid[nums[j]] > nid[pivot]) j--;\n\t\t\tif (i <= j) {\n\t\t\t\tint tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;\n\t\t\t\ti++;\n\t\t\t\tj--;\n\t\t\t}\n\t\t}\n\t\tsort(nums, l, j);\n\t\tsort(nums, i, r);\n\t}\n\n\tpublic static int compute() {\n\t\tsort(arr, 1, s);\n\t\tint sumDist = 0;\n\t\tfor (int i = 1; i < s; i++) {\n\t\t\tsumDist += getDist(arr[i], arr[i + 1]);\n\t\t}\n\t\tsumDist += getDist(arr[1], arr[s]);\n\t\tint extra = getLca(arr[1], arr[s]) <= n ? 1 : 0;\n\t\treturn sumDist / 2 + extra - s;\n\t}\n\n\tpublic static void prepare() {\n\t\tcnt1 = cnt2 = cntd = top = cnti = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead1[i] = head2[i] = dfn[i] = 0;\n\t\t\thead2[i + n] = 0;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tcntn = n;\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\taddEdge1(u, v);\n\t\t\t\taddEdge1(v, u);\n\t\t\t}\n\t\t\t// tarjan1(1);\n\t\t\ttarjan2(1);\n\t\t\t// dfs1(1, 0);\n\t\t\tdfs2(1, 0);\n\t\t\tq = in.nextInt();\n\t\t\tfor (int i = 1; i <= q; i++) {\n\t\t\t\ts = in.nextInt();\n\t\t\t\tfor (int j = 1; j <= s; j++) {\n\t\t\t\t\tarr[j] = in.nextInt();\n\t\t\t\t}\n\t\t\t\tout.println(compute());\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code09_StrategyGame1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
