0cc2f3c6-dffe-4230-aa3c-6b711f1396a9	dbda5e44-b693-4c79-aa7b-4262f231533c	java	package class195;\n\n// 沙漠，java版\n// 一共n个数字，所有数字都在 1 ~ 10^9 的范围，这是范围说明\n// 接下来给定s条设置说明，格式 x v ，表示第x个数的值确定是v\n// 接下来给定m条关系说明，格式 l r k x1 x2 ... xk 含义如下\n// 第l到第r个数字，其中有k个数字，分别是第x1、第x2 .. 第xk个数字\n// 这k个数字中的每一个，都比剩下的(r - l + 1 - k)个数字要大，严格大于\n// 根据上面的说明，找到没有矛盾的，给每个数字赋值的方案，任何一个方案即可\n// 如果存在方案打印"TAK"，然后打印每个数字，不存在方案打印"NIE"\n// 1 <= n、s <= 10^5\n// 1 <= m <= 2 * 10^5\n// 所有k的累加和 <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3588\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Desert1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 5;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int LIMIT = 1000000000;\n\tpublic static int n, s, m;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int root;\n\tpublic static int cntt;\n\n\tpublic static int[] val = new int[MAXT];\n\tpublic static int[] atMost = new int[MAXT];\n\tpublic static int[] indegree = new int[MAXT];\n\tpublic static int[] que = new int[MAXT];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t\tindegree[v]++;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt], 0);\n\t\t\taddEdge(rt, rs[rt], 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int jobw, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i, jobw);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean topo() {\n\t\tint qi = 1, qsiz = 0;\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++qsiz] = i;\n\t\t\t}\n\t\t\tatMost[i] = val[i] == 0 ? LIMIT : val[i];\n\t\t}\n\t\twhile (qi <= qsiz) {\n\t\t\tint u = que[qi++];\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (atMost[v] > atMost[u] + w) {\n\t\t\t\t\tatMost[v] = atMost[u] + w;\n\t\t\t\t\tif ((val[v] != 0 && atMost[v] < val[v]) || atMost[v] < 1) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++qsiz] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn qsiz == cntt;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\ts = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntt = n;\n\t\troot = build(1, n);\n\t\tfor (int i = 1; i <= s; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tval[x] = v;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint l = in.nextInt();\n\t\t\tint r = in.nextInt();\n\t\t\tint k = in.nextInt();\n\t\t\tint vnode = ++cntt;\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tint x = in.nextInt();\n\t\t\t\taddEdge(x, vnode, 0);\n\t\t\t\txToRange(vnode, l, x - 1, -1, 1, n, root);\n\t\t\t\tl = x + 1;\n\t\t\t}\n\t\t\txToRange(vnode, l, r, -1, 1, n, root);\n\t\t}\n\t\tboolean check = topo();\n\t\tif (check) {\n\t\t\tout.println("TAK");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(atMost[i] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t} else {\n\t\t\tout.println("NIE");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code04_Desert1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
