17248124-af57-408a-9853-5264c1abeefa	dbda5e44-b693-4c79-aa7b-4262f231533c	java	package class195;\n\n// 炸弹，java版\n// 一共有n个炸弹，所有炸弹排成一条直线，给定每个炸弹的坐标xi、爆炸半径ri\n// 炸弹A引爆时，如果炸弹B在其影响范围里，那么炸弹B也会引爆，进而引发一连串的爆炸\n// 炸弹i如果作为初始引爆的炸弹，最终会引爆多少个炸弹记为query(i)\n// 计算i = 1 2 .. n时，i * query(i)的累加和，答案对 1000000007 取余\n// 1 <= n <= 5 * 10^5\n// -(10^18) <= xi <= +(10^18)，题目依次输入的坐标保证严格递增\n// 0 <= ri <= 2 * 10^18\n// 测试链接 : https://www.luogu.com.cn/problem/P5025\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Bomb1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXT = MAXN * 5;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int INF = 1 << 30;\n\tpublic static int MOD = 1000000007;\n\tpublic static int n;\n\tpublic static long[] location = new long[MAXN];\n\tpublic static long[] radius = new long[MAXN];\n\n\tpublic static int[] a = new int[MAXE];\n\tpublic static int[] b = new int[MAXE];\n\tpublic static int cnte;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] rangel = new int[MAXT];\n\tpublic static int[] ranger = new int[MAXT];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int root;\n\tpublic static int cntt;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int[] mostl = new int[MAXT];\n\tpublic static int[] mostr = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXT][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void saveEdge(int u, int v) {\n\t\ta[++cnte] = u;\n\t\tb[cnte] = v;\n\t}\n\n\tpublic static int lower(long num) {\n\t\tint l = 1, r = n, mid, ans = n + 1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (location[mid] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt);\n\t\t\taddEdge(rs[rt], rt);\n\t\t\tsaveEdge(ls[rt], rt);\n\t\t\tsaveEdge(rs[rt], rt);\n\t\t}\n\t\trangel[rt] = l;\n\t\tranger[rt] = r;\n\t\treturn rt;\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx);\n\t\t\tsaveEdge(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tmostl[sccCnt] = INF;\n\t\t\tmostr[sccCnt] = -INF;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tmostl[sccCnt] = Math.min(mostl[sccCnt], rangel[pop]);\n\t\t\t\tmostr[sccCnt] = Math.max(mostr[sccCnt], ranger[pop]);\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tmostl[sccCnt] = INF;\n\t\t\t\t\tmostr[sccCnt] = -INF;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tmostl[sccCnt] = Math.min(mostl[sccCnt], rangel[pop]);\n\t\t\t\t\t\tmostr[sccCnt] = Math.max(mostr[sccCnt], ranger[pop]);\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dpOnDAG() {\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tmostl[v] = Math.min(mostl[v], mostl[u]);\n\t\t\t\tmostr[v] = Math.max(mostr[v], mostr[u]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int u) {\n\t\tint scc = belong[u];\n\t\tint num = mostr[scc] - mostl[scc] + 1;\n\t\treturn num;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tcntt = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlocation[i] = in.nextLong();\n\t\t\tradius[i] = in.nextLong();\n\t\t}\n\t\troot = build(1, n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tint l = lower(location[i] - radius[i]);\n\t\t\tint r = lower(location[i] + radius[i] + 1) - 1;\n\t\t\trangeToX(l, r, i, 1, n, root);\n\t\t}\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tcondense();\n\t\tdpOnDAG();\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans = (ans + 1L * query(i) * i) % MOD;\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code05_Bomb1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
