42ebd090-2a15-4817-8314-018f3633d56c	dbda5e44-b693-4c79-aa7b-4262f231533c	java	package class195;\n\n// 逛森林，java版\n// 一共n个点，给定出发点s，初始时没有边，一共m条操作，操作类型有两种\n// 操作 1 a b c d w : 如果点a和点b不连通，或者点c和点d不连通，忽略该操作\n//       点a到点b路径上的任何一点，可以花费w的代价，传送到点c到点d路径上的任何一点\n//       该操作是单向传送，不代表加边，判断连通性只考虑2类型的操作加入的边\n// 操作 2 u v w : 点u和点v如果已经连通，忽略该操作，否则增加一条边权为w的无向边\n// 完成m条操作后，打印从s点出发，到每个节点的最小花费，到达不了的节点打印-1\n// 1 <= n <= 5 * 10^4    1 <= m <= 10^6    1 <= w <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P5344\n// 提交以下的code，提交时请把类名改成"Main"\n// 本题卡常java的实现无法通过\n// 想通过用C++实现，本节课Code08_Forest2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.PriorityQueue;\n\npublic class Code08_Forest1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int MAXT = 4000001;\n\tpublic static int MAXE = 30000001;\n\tpublic static int MAXP = 17;\n\tpublic static int INF = 1 << 30;\n\tpublic static int n, m, s;\n\n\t// 操作1记录一下，只记录应该发生的操作1\n\tpublic static int[] u1 = new int[MAXM];\n\tpublic static int[] v1 = new int[MAXM];\n\tpublic static int[] u2 = new int[MAXM];\n\tpublic static int[] v2 = new int[MAXM];\n\tpublic static int[] weight = new int[MAXM];\n\tpublic static int cntq;\n\n\t// 操作2建立的树\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\t// 操作1 + 操作2 建立的图\n\tpublic static int[] head2 = new int[MAXT];\n\tpublic static int[] next2 = new int[MAXE];\n\tpublic static int[] to2 = new int[MAXE];\n\tpublic static int[] weight2 = new int[MAXE];\n\tpublic static int cnt2;\n\n\t// 并查集\n\tpublic static int[] father = new int[MAXN];\n\n\t// 树上倍增\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int[][] stout = new int[MAXN][MAXP];\n\tpublic static int[][] stin = new int[MAXN][MAXP];\n\tpublic static int cntt;\n\n\t// dijkstra算法\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static boolean[] vis = new boolean[MAXT];\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[1] - b[1]);\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, int w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void build(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tstout[u][0] = ++cntt;\n\t\taddEdge2(u, cntt, 0);\n\t\taddEdge2(fa, cntt, 0);\n\t\tstin[u][0] = ++cntt;\n\t\taddEdge2(cntt, u, 0);\n\t\taddEdge2(cntt, fa, 0);\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\tstout[u][p] = ++cntt;\n\t\t\taddEdge2(stout[u][p - 1], cntt, 0);\n\t\t\taddEdge2(stout[stjump[u][p - 1]][p - 1], cntt, 0);\n\t\t\tstin[u][p] = ++cntt;\n\t\t\taddEdge2(cntt, stin[u][p - 1], 0);\n\t\t\taddEdge2(cntt, stin[stjump[u][p - 1]][p - 1], 0);\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa) {\n\t\t\t\tbuild(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void pathOut(int x, int y, int vnode) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\taddEdge2(y, vnode, 0);\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[x][p]] >= dep[y]) {\n\t\t\t\taddEdge2(stout[x][p], vnode, 0);\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\taddEdge2(stout[x][p], vnode, 0);\n\t\t\t\taddEdge2(stout[y][p], vnode, 0);\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\taddEdge2(stout[x][0], vnode, 0);\n\t}\n\n\tpublic static void pathIn(int x, int y, int vnode) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\taddEdge2(vnode, y, 0);\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[x][p]] >= dep[y]) {\n\t\t\t\taddEdge2(vnode, stin[x][p], 0);\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\taddEdge2(vnode, stin[x][p], 0);\n\t\t\t\taddEdge2(vnode, stin[y][p], 0);\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\taddEdge2(vnode, stin[x][0], 0);\n\t}\n\n\tpublic static void pathToPath(int a, int b, int c, int d, int w) {\n\t\tint x = ++cntt;\n\t\tint y = ++cntt;\n\t\tpathOut(a, b, x);\n\t\tpathIn(c, d, y);\n\t\taddEdge2(x, y, w);\n\t}\n\n\tpublic static void dijkstra() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t}\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\t\t\tint v = to2[e];\n\t\t\t\t\tint w = weight2[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\ts = in.nextInt();\n\t\tcntt = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tfor (int i = 1, op, a, b, c, d, w, u, v; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\td = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\tif (find(a) == find(b) && find(c) == find(d)) {\n\t\t\t\t\tu1[++cntq] = a;\n\t\t\t\t\tv1[cntq] = b;\n\t\t\t\t\tu2[cntq] = c;\n\t\t\t\t\tv2[cntq] = d;\n\t\t\t\t\tweight[cntq] = w;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\tint ufa = find(u);\n\t\t\t\tint vfa = find(v);\n\t\t\t\tif (ufa != vfa) {\n\t\t\t\t\taddEdge1(u, v);\n\t\t\t\t\taddEdge1(v, u);\n\t\t\t\t\taddEdge2(u, v, w);\n\t\t\t\t\taddEdge2(v, u, w);\n\t\t\t\t\tfather[ufa] = vfa;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dep[i] == 0) {\n\t\t\t\tbuild(i, i);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tpathToPath(u1[i], v1[i], u2[i], v2[i], weight[i]);\n\t\t}\n\t\tdijkstra();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(dist[i] == INF ? -1 : dist[i]);\n\t\t\tout.print(" ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code08_Forest1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
c45015fb-faca-45c1-b86c-397bf0903eac	dbda5e44-b693-4c79-aa7b-4262f231533c	java	package class195;\n\n// 逛森林，C++版\n// 一共n个点，给定出发点s，初始时没有边，一共m条操作，操作类型有两种\n// 操作 1 a b c d w : 如果点a和点b不连通，或者点c和点d不连通，忽略该操作\n//       点a到点b路径上的任何一点，可以花费w的代价，传送到点c到点d路径上的任何一点\n//       该操作是单向传送，不代表加边，判断连通性只考虑2类型的操作加入的边\n// 操作 2 u v w : 点u和点v如果已经连通，忽略该操作，否则增加一条边权为w的无向边\n// 完成m条操作后，打印从s点出发，到每个节点的最小花费，到达不了的节点打印-1\n// 1 <= n <= 5 * 10^4    1 <= m <= 10^6    1 <= w <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P5344\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 50001;\n//const int MAXM = 1000001;\n//const int MAXT = 4000001;\n//const int MAXE = 30000001;\n//const int MAXP = 17;\n//const int INF = 1 << 30;\n//int n, m, s;\n//\n//int u1[MAXM];\n//int v1[MAXM];\n//int u2[MAXM];\n//int v2[MAXM];\n//int weight[MAXM];\n//int cntq;\n//\n//int head1[MAXN];\n//int next1[MAXN << 1];\n//int to1[MAXN << 1];\n//int cnt1;\n//\n//int head2[MAXT];\n//int next2[MAXE];\n//int to2[MAXE];\n//int weight2[MAXE];\n//int cnt2;\n//\n//int father[MAXN];\n//\n//int dep[MAXN];\n//int stjump[MAXN][MAXP];\n//int stout[MAXN][MAXP];\n//int stin[MAXN][MAXP];\n//int cntt;\n//\n//int dist[MAXT];\n//bool vis[MAXT];\n//\n//struct Node {\n//    int u;\n//    int d;\n//\n//    bool operator < (const Node &other) const {\n//        return d > other.d;\n//    }\n//};\n//\n//priority_queue<Node> heap;\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v, int w) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    weight2[cnt2] = w;\n//    head2[u] = cnt2;\n//}\n//\n//int find(int i) {\n//    if (i != father[i]) {\n//        father[i] = find(father[i]);\n//    }\n//    return father[i];\n//}\n//\n//void build(int u, int fa) {\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    stout[u][0] = ++cntt;\n//    addEdge2(u, cntt,