\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int c = 1; c <= t; c++) {\n//        cin >> n;\n//        prepare();\n//        for (int i = 1, u, v; i <= n; i++) {\n//            cin >> u >> v;\n//            addEdge(u, v);\n//            addEdge(v, u);\n//        }\n//        ll ans = compute();\n//        cout << ans << "\\n";\n//    }\n//    return 0;\n//}	模板：Code02_NumberOfSimplePaths2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
4b43c35f-0bda-4796-9fda-f802719b5876	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 有向图的基环树找环，C++版\n// 这个文件课上没讲，有向图中找到基环，非常容易理解\n// 无向图的入环节点u，可以发现环的末尾节点v，因为边是无向的\n// 于是用dfn[u] < dfn[v]来判断环\n// 但是对有向图来说，假设出现的环如下\n// 入环节点a -> b -> c -> 环的末尾节点d -> 入环节点a\n// 不能放在入环节点a处判断，因为环的末尾节点d，不一定在a的邻居列表里\n// 边是有向的，也许只有d到a的边，不一定有a到d的边\n// 所以有向图的基环树找环，判断的时机，放在环的末尾节点处，具体说明如下\n// 节点一共三种状态，0表示没有访问，1表示在递归路径上，2表示递归执行完了\n// 依然记录每个点，在递归路径的前一个节点，也就是课上讲的from信息\n// 来到节点u时，判断儿子节点v，看看是否在递归路径上\n// 是的话，从u开始通过from走回v，环路就找全了，v是入环节点，u是环末尾点\n// 调用时扫过所有节点，没有访问过的节点去调用dfs，直到环被找到\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//\n//int head[MAXN];\n//int nxt[MAXN];\n//int to[MAXN];\n//int cntg;\n//\n//int state[MAXN];\n//int from[MAXN];\n//bool cycle[MAXN];\n//\n//bool dfs(int u) {\n//    state[u] = 1;\n//    bool find = false;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (state[v] == 0) {\n//            from[v] = u;\n//            if (dfs(v)) {\n//                find = true;\n//            }\n//        } else if (state[v] == 1) {\n//            cycle[v] = true;\n//            for (int i = u; i != v; i = from[i]) {\n//                cycle[i] = true;\n//            }\n//            find = true;\n//        }\n//        if (find) {\n//            break;\n//        }\n//    }\n//    state[u] = 2;\n//    return find;\n//}	模板：FollowUp2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
6d656665-dcfd-4f95-b517-38d738d70033	1c76ab63-b008-4242-b35c-c2ccba6b1d65	java	package class200;\n\n// 仙人掌删边方案数，java版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 如果图不是仙人掌打印0，如果图是仙人掌，可以在图中删除一些边\n// 如果删除后剩下的图仍然连通，就叫有效的删边方案\n// 允许一条边也不删，打印有效删边的方案数，答案可能很大，需要高精度\n// 1 <= n <= 2 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4129\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.math.BigInteger;\n\npublic class Code01_CactusDeleteEdge1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// 统计每个环的边数\n\tpublic static int[] edgeCnt = new int[MAXN];\n\tpublic static int cntc;\n\n\t// 不作为环顶节点的情况下，参与了几个环\n\tpublic static int[] cycleCnt = new int[MAXN];\n\n\t// 本题需要高精度乘法\n\tpublic static BigInteger ans;\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\tcntc++;\n\t\t\t\t\tedgeCnt[cntc] = 1;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tedgeCnt[cntc]++;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\tcycleCnt[u]++;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tcntc++;\n\t\t\t\t\t\tedgeCnt[cntc] = 1;\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\tedgeCnt[cntc]++;\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, k, x, y; i <= m; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tfor (int j = 2; j <= k; j++) {\n\t\t\t\ty = in.nextInt();\n\t\t\t\taddEdge(x, y);\n\t\t\t\taddEdge(y, x);\n\t\t\t\tx = y;\n\t\t\t}\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0 || cycleCnt[i] >= 2) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tans = BigInteger.ONE;\n\t\t\tfor (int i = 1; i <= cntc; i++) {\n\t\t\t\tans = ans.multiply(BigInteger.valueOf(edgeCnt[i] + 1));\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t} else {\n\t\t\tout.println(0);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code01_CactusDeleteEdge1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
cf498ae4-2f1f-4600-a59f-eac96177741b	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 骑士，java版\n// 图中有n个点、n条无向边，每个点有点权\n// 图中可能有多个连通块，保证每个连通块都是一棵基环树\n// 图中任意相邻两点不能同时选择，计算能得到的最大点权累加和\n// 1 <= n、点权 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P2607\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Knight1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int n;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int x, y, skip;\n\n\tpublic static long[][] dp = new long[MAXN][2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tdfs(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tx = u;\n\t\t\t\ty = v;\n\t\t\t\tskip = (e + 1) >> 1;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dpOnTree(int u, int fa) {\n\t\tdp[u][0] = 0;\n\t\tdp[u][1] = arr[u];\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && (e + 1) >> 1 != skip) {\n\t\t\t\tdpOnTree(v, u);\n\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\tx = y = 0;\n\t\t\t\tdfs(i);\n\t\t\t\tdpOnTree(x, 0);\n\t\t\t\tlong cur = dp[x][0];\n\t\t\t\tdpOnTree(y, 0);\n\t\t\t\tcur = Math.max(cur, dp[y][0]);\n\t\t\t\tans += cur;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int x = 1, y; x <= n; x++) {\n\t\t\tarr[x] = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\taddEdge(x, y);\n\t\t\taddEdge(y, x);\n\t\t}\n\t\tlong ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code03_Knight1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
