767d2250-3edb-4206-ab9a-809e0a3a71b0	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 城市环路，java版\n// 图中有n个点、n条无向边，每个点有点权，图是一棵基环树\n// 图中任意相邻两点不能同时选择，先得到最大的点权累加和\n// 然后乘以题目给定的系数k，打印结果\n// 1 <= n <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1453\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_RingRoad1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n;\n\tpublic static double k;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int x, y, skip;\n\n\tpublic static int[][] dp = new int[MAXN][2];\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] staf = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int stacksize, u, status, fa, e;\n\n\tpublic static void push(int u, int status, int fa, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstaf[stacksize] = fa;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\tfa = staf[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void dfs1(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tx = u;\n\t\t\t\ty = v;\n\t\t\t\tskip = (e + 1) >> 1;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dfs2(int cur) {\n\t\tstacksize = 0;\n\t\tpush(cur, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 1 && dfn[u] < dfn[v]) {\n\t\t\t\t\tx = u;\n\t\t\t\t\ty = v;\n\t\t\t\t\tskip = (e + 1) >> 1;\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, 0, e);\n\t\t\t\t\tpush(v, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, 0, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dpOnTree1(int u, int fa) {\n\t\tdp[u][0] = 0;\n\t\tdp[u][1] = arr[u];\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && (e + 1) >> 1 != skip) {\n\t\t\t\tdpOnTree1(v, u);\n\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dpOnTree2(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, father, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdp[u][0] = 0;\n\t\t\t\tdp[u][1] = arr[u];\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, fa, e);\n\t\t\t\tif (to[e] != fa && (e + 1) >> 1 != skip) {\n\t\t\t\t\tpush(to[e], 0, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != fa && (ei + 1) >> 1 != skip) {\n\t\t\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tx = y = 0;\n\t\t// dfs1(1);\n\t\tdfs2(1);\n\t\t// dpOnTree1(x, 0);\n\t\tdpOnTree2(x, 0);\n\t\tlong ans = dp[x][0];\n\t\t// dpOnTree1(y, 0);\n\t\tdpOnTree2(y, 0);\n\t\tans = Math.max(ans, dp[y][0]);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i <= n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tu++;\n\t\t\tv++;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tk = in.nextDouble();\n\t\tlong ans = compute();\n\t\tout.printf("%.1f\\n", k * ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tdouble nextDouble() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong intPart = 0;\n\t\t\twhile (c > ' ' && c != -1 && c != '.') {\n\t\t\t\tintPart = intPart * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tdouble val = (double) intPart;\n\t\t\tif (c == '.') {\n\t\t\t\tc = readByte();\n\t\t\t\tdouble base = 0.1;\n\t\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\t\tval += (c - '0') * base;\n\t\t\t\t\tbase *= 0.1;\n\t\t\t\t\tc = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code04_RingRoad1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
