ae0e4041-72e1-41f1-a24d-4ab9e637382a	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 岛屿，java版\n// 图中有n个点、n条无向边，每条边有边权\n// 图中可能有多个连通块，保证每个连通块都是一棵基环树\n// 对每个连通块，计算点不重复的路径能得到的最大边权和，即基环树直径\n// 图中每棵基环树的直径累加起来，打印这个结果\n// 2 <= n <= 10^6\n// 1 <= 边权 <= 10^8\n// 测试链接 : https://www.luogu.com.cn/problem/P4381\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_Island1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int n;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] fromNode = new int[MAXN];\n\tpublic static int[] fromWeight = new int[MAXN];\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int cnta;\n\n\tpublic static long[] dist = new long[MAXN];\n\tpublic static long diameter;\n\n\tpublic static long[] sum = new long[MAXN << 1];\n\tpublic static long[] height = new long[MAXN << 1];\n\tpublic static int[] que = new int[MAXN << 1];\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int stacksize, u, status, e;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void dfs1(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tfromNode[v] = u;\n\t\t\t\tfromWeight[v] = weight[e];\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tcycle[u] = true;\n\t\t\t\tarr[++cnta] = u;\n\t\t\t\tval[cnta] = weight[e];\n\t\t\t\tfor (int i = v; i != u; i = fromNode[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t\tarr[++cnta] = i;\n\t\t\t\t\tval[cnta] = fromWeight[i];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dfs2(int cur) {\n\t\tstacksize = 0;\n\t\tpush(cur, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 1 && dfn[u] < dfn[v]) {\n\t\t\t\t\tcycle[u] = true;\n\t\t\t\t\tarr[++cnta] = u;\n\t\t\t\t\tval[cnta] = weight[e];\n\t\t\t\t\tfor (int i = v; i != u; i = fromNode[i]) {\n\t\t\t\t\t\tcycle[i] = true;\n\t\t\t\t\t\tarr[++cnta] = i;\n\t\t\t\t\t\tval[cnta] = fromWeight[i];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tfromNode[v] = u;\n\t\t\t\t\tfromWeight[v] = weight[e];\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dpOnTree(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa && !cycle[v]) {\n\t\t\t\tdpOnTree(v, u);\n\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + w);\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute(int root) {\n\t\tcnta = 0;\n\t\t// dfs1(root);\n\t\tdfs2(root);\n\t\tsum[1] = 0;\n\t\tfor (int i = 2, j = 1; j <= cnta; i++, j++) {\n\t\t\tsum[i] = val[j];\n\t\t}\n\t\tfor (int i = cnta + 2; i <= cnta * 2; i++) {\n\t\t\tsum[i] = sum[i - cnta];\n\t\t}\n\t\tfor (int i = 1; i <= cnta * 2; i++) {\n\t\t\tsum[i] += sum[i - 1];\n\t\t}\n\t\tlong ans1 = 0;\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tdiameter = 0;\n\t\t\tdpOnTree(arr[i], 0);\n\t\t\tans1 = Math.max(ans1, diameter);\n\t\t\theight[i] = dist[arr[i]];\n\t\t\theight[i + cnta] = height[i];\n\t\t}\n\t\tlong ans2 = 0;\n\t\tint ql = 1, qr = 0;\n\t\tfor (int i = 1; i <= cnta * 2; i++) {\n\t\t\twhile (ql <= qr && que[ql] <= i - cnta) {\n\t\t\t\tql++;\n\t\t\t}\n\t\t\tif (ql <= qr) {\n\t\t\t\tans2 = Math.max(ans2, height[i] + height[que[ql]] + sum[i] - sum[que[ql]]);\n\t\t\t}\n\t\t\twhile (ql <= qr && height[que[qr]] - sum[que[qr]] <= height[i] - sum[i]) {\n\t\t\t\tqr--;\n\t\t\t}\n\t\t\tque[++qr] = i;\n\t\t}\n\t\treturn Math.max(ans1, ans2);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int u = 1, v, w; u <= n; u++) {\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\tans += compute(i);\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n	模板：Code06_Island1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
