1478b0a3-6110-47d0-8fe2-b93a98263419	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 最短距离，巧妙的解法，java版\n// 图中有n个点、n条无向边，每条边有边权，图是一棵基环树\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 1 x y : 第x号边的边权修改为y\n// 操作 2 x y : 查询点x和点y之间的最短距离\n// 1 <= n <= 10^5 + 6\n// 1 <= m <= 10^5\n// 0 <= 边权 <= 5000\n// 测试链接 : https://www.luogu.com.cn/problem/P4949\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_ShortestDistance_java_1 {\n\n\tpublic static int MAXN = 100007;\n\tpublic static int n, m;\n\tpublic static int[] u = new int[MAXN];\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] w = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int node1, node2, skipEdge;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static int[] tree = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tnode1 = u;\n\t\t\t\tnode2 = v;\n\t\t\t\tskipEdge = (e + 1) >> 1;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif ((e + 1) >> 1 != skipEdge && v != f) {\n\t\t\t\tdfs2(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] != 0) {\n\t\t\tdfs3(son[u], t);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif ((e + 1) >> 1 != skipEdge && v != fa[u] && v != son[u]) {\n\t\t\t\tdfs3(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int query(int i) {\n\t\tint ans = 0;\n\t\twhile (i >= 1) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int sum(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn query(r) - query(l - 1);\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs1(1);\n\t\tcntd = 0;\n\t\tdfs2(1, 0);\n\t\tdfs3(1, 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (i != skipEdge) {\n\t\t\t\tadd(Math.max(dfn[u[i]], dfn[v[i]]), w[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void setEdge(int edge, int val) {\n\t\tif (edge != skipEdge) {\n\t\t\tadd(Math.max(dfn[u[edge]], dfn[v[edge]]), val - w[edge]);\n\t\t}\n\t\tw[edge] = val;\n\t}\n\n\tpublic static int jump(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tans += sum(dfn[top[y]], dfn[y]);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += sum(dfn[top[x]], dfn[x]);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tif (dfn[x] < dfn[y]) {\n\t\t\tans += sum(dfn[x] + 1, dfn[y]);\n\t\t} else {\n\t\t\tans += sum(dfn[y] + 1, dfn[x]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getDistance(int x, int y) {\n\t\tint p1 = jump(x, y);\n\t\tint p2 = jump(x, node1) + w[skipEdge] + jump(node2, y);\n\t\tint p3 = jump(x, node2) + w[skipEdge] + jump(node1, y);\n\t\treturn Math.min(p1, Math.min(p2, p3));\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\tw[i] = in.nextInt();\n\t\t\taddEdge(u[i], v[i]);\n\t\t\taddEdge(v[i], u[i]);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tsetEdge(x, y);\n\t\t\t} else {\n\t\t\t\tout.println(getDistance(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code07_ShortestDistance_java_1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
3ab5ca1f-602f-4875-8af8-d93ab2538866	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 最短距离，好想的解法，java版\n// 图中有n个点、n条无向边，每条边有边权，图是一棵基环树\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 1 x y : 第x号边的边权修改为y\n// 操作 2 x y : 查询点x和点y之间的最短距离\n// 1 <= n <= 10^5 + 6\n// 1 <= m <= 10^5\n// 0 <= 边权 <= 5000\n// 测试链接 : https://www.luogu.com.cn/problem/P4949\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_ShortestDistance_java_2 {\n\n\tpublic static int MAXN = 100007;\n\tpublic static int n, m;\n\tpublic static int[] u = new int[MAXN];\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] w = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\t// 基环树找环\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] from = new int[MAXN];\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int cnta;\n\n\t// 环上的边，确定归属，不是环上的边，这个信息没用\n\tpublic static int[] cycleEdgeTo = new int[MAXN];\n\t// 环上的点依次分配编号，继续cntd自增获得编号\n\tpublic static int[] cycleId = new int[MAXN];\n\t// 记录每个节点属于哪棵分树，分树的头一定是环上节点\n\tpublic static int[] belong = new int[MAXN];\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\t// 所有分树节点的dfn序号范围[1, n]\n\t// 环上节点会额外再次编号，范围[n+1, cntd]\n\tpublic static int[] tree = new int[MAXN << 1];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tfrom[v] = u;\n\t\t\t\tcycleEdgeTo[(e + 1) >> 1] = v;\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tcycleEdgeTo[(e + 1) >> 1] = u;\n\t\t\t\tcycle[u] = true;\n\t\t\t\tarr[++cnta] = u;\n\t\t\t\tfor (int i = v; i != u; i = from[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t\tarr[++cnta] = i;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f, int h) {\n\t\tbelong[u] = h;\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (!cycle[v] && v != f) {\n\t\t\t\tdfs2(v, u, h);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] != 0) {\n\t\t\tdfs3(son[u], t);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!cycle[v] && v != fa[u] && v != son[u]) {\n\t\t\t\tdfs3(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= cntd) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int query(int i) {\n\t\tint ans = 0;\n\t\twhile (i >= 1) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int sum(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn query(r) - query(l - 1);\n\t}\n\n\tpublic static int edgeToNode(int i) {\n\t\tif (cycle[u[i]] && cycle[v[i]]) {\n\t\t\treturn cycleId[cycleEdgeTo[i]];\n\t\t} else {\n\t\t\treturn Math.max(dfn[u[i]], dfn[v[i]]);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs1(1);\n\t\tcntd = 0;\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tdfs2(arr[i], 0, arr[i]);\n\t\t\tdfs3(arr[i], arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tcycleId[arr[i]] = ++cntd;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(edgeToNode(i), w[i]);\n\t\t}\n\t}\n\n\tpublic static void setEdge(int edge, int val) {\n\t\tadd(edgeToNode(edge), val - w[edge]);\n\t\tw[edge] = val;\n\t}\n\n\tpublic static int jump(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tans += sum(dfn[top[y]], dfn[y]);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += sum(dfn[top[x]], dfn[x]);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tif (dfn[x] < dfn[y]) {\n\t\t\tans += sum(dfn[x] + 1, dfn[y]);\n\t\t} else {\n\t\t\tans += sum(dfn[y] + 1, dfn[x]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getDistance(int x, int y) {\n\t\tif (belong[x] == belong[y]) {\n\t\t\treturn jump(x, y);\n\t\t} else {\n\t\t\tint a = Math.min(cycleId[belong[x]], cycleId[belong[y]]);\n\t\t\tint b = Math.max(cycleId[belong[x]], cycleId[belong[y]]);\n\t\t\tint p1 = sum(a, b - 1);\n\t\t\tint p2 = sum(n + 1, cntd) - p1;\n\t\t\treturn jump(x, belong[x]) + jump(y, belong[y]) + Math.min(p1, p2);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\tw[i] = in.nextInt();\n\t\t\taddEdge(u[i], v[i]);\n\t\t\taddEdge(v[i], u[i]);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tsetEdge(x, y);\n\t\t\t} else {\n\t\t\t\tout.println(getDistance(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code07_ShortestDistance_java_2.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
2f32ca58-1959-4cbd-adc8-24cf8d13c055	0a0421cc-d47b-4084-b849-b4df67c85ed1	java	package class199;\n\n// 旅行，java版\n// 图中有n个点、m条无向边，节点编号1~n，图是普通树或者基环树\n// 对于普通树，从1号节点开始，选择不同的遍历顺序，会形成不同的dfs序列\n// 其中字典序最小的dfs序列，叫做普通树的答案\n// 对于基环树，可以删掉环上的任何一条边，让基环树变成某棵普通树\n// 众多普通树的答案中，字典序最小的结果，叫做基环树的答案\n// 图如果是普通树，打印普通树的答案，图如果是基环树，打印基环树的答案\n// 1 <= n <= 5 * 10^5\n// 普通版测试 : https://www.luogu.com.cn/problem/P5022\n// 加强版测试 : https://www.luogu.com.cn/problem/P5049\n// 提交以下的code，提交时请把类名改成"Main"，可以通过普通版测试\n// 加强版测试卡常数时间，java实现无法通过，索性递归函数也不改迭代了\n// 想通过用C++实现，本节课Code08_Journey2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code08_Journey1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m;\n\tpublic static int[][] arr = new int[MAXN << 1][2];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] from = new int[MAXN];\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\n\tpublic static boolean turn;\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int cnta;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tfrom[v] = u;\n\t\t\t\tdfs(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tcycle[u] = true;\n\t\t\t\tfor (int i = v; i != u; i = from[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void path(int u, int back) {\n\t\tvis[u] = true;\n\t\tans[++cnta] = u;\n\t\tif (!cycle[u] || turn) {\n\t\t\t// u不在环上 或者 已经回过头了\n\t\t\t// 那么像在树上遍历即可\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (!vis[v]) {\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t// u在环上 并且 还没回过头\n\t\t// 考察最后一个儿子是否符合回头需要\n\t\tint end = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tend = v;\n\t\t\t}\n\t\t}\n\t\tturn = cycle[end] && end > back;\n\t\tif (turn) {\n\t\t\t// 回头成功\n\t\t\t// 无视最后一个儿子\n\t\t\t// 因为会从环的另一侧到达\n\t\t\t// 其他儿子像在树上遍历即可\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (!vis[v] && v != end) {\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t// 回头不成功\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tif (!cycle[v]) {\n\t\t\t\t\t// 当前儿子v不在环上\n\t\t\t\t\t// 像在树上遍历即可\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t} else {\n\t\t\t\t\t// 当前儿子v在环上\n\t\t\t\t\t// 设置好后续的back\n\t\t\t\t\t// 回头可能发生在后续的环上\n\t\t\t\t\t// 因为节点u最多两个环上的孩子\n\t\t\t\t\t// 所以如下for循环最多发生两次\n\t\t\t\t\t// 所以时间复杂度不会变高\n\t\t\t\t\tint next = back;\n\t\t\t\t\tfor (int ne = nxt[e]; ne > 0; ne = nxt[ne]) {\n\t\t\t\t\t\tint nv = to[ne];\n\t\t\t\t\t\tif (!vis[nv]) {\n\t\t\t\t\t\t\tnext = nv;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tpath(v, next);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tarr[i][0] = u;\n\t\t\tarr[i][1] = v;\n\t\t\tarr[i + m][0] = v;\n\t\t\tarr[i + m][1] = u;\n\t\t}\n\t\tArrays.sort(arr, 1, m * 2 + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);\n\t\tfor (int i = 1; i <= m * 2; i++) {\n\t\t\taddEdge(arr[i][0], arr[i][1]);\n\t\t}\n\t\tdfs(1);\n\t\tpath(1, n + 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}	模板：Code08_Journey1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
