89cd9548-e6b7-41b2-a4e3-813fba21b581	1c76ab63-b008-4242-b35c-c2ccba6b1d65	java	package class200;\n\n// 仙人掌最长路线，java版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 路线可以从任何城市开始，但必须在1号点结束\n// 路线可以重复经过同一个点，但不能重复经过同一条边\n// 计算最长路线的边数\n// 1 <= n <= 10^4\n// 1 <= m <= 2 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P6335\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_CactusLongestRoute1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 20001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] cycle = new int[MAXN];\n\n\t// f[u] : 在u向下的结构中（以u为头的子仙人掌），从u出发并最终回到u，能走过的最大边数\n\tpublic static int[] f = new int[MAXN];\n\n\t// g[u] : 在u向下的结构中（以u为头的子仙人掌），从u出发，终点任意，能走过的最大边数\n\tpublic static int[] g = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tcycle[++siz] = pop;\n\t\t} while (pop != v);\n\t\t// best表示，这个环上任选一个点作为最后出去的位置\n\t\t// 从u沿两侧之一走到它，能够得到的不回到u的最大边数\n\t\tint best = 0;\n\t\tint sum = 1;\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\tbest = Math.max(best, sum + g[cycle[i]]);\n\t\t\tsum += f[cycle[i]] + 1;\n\t\t}\n\t\t// u可以下方有多个环，所以新增此时的sum\n\t\tf[u] += sum;\n\t\tint otherSide = sum;\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\totherSide -= f[cycle[i]] + 1;\n\t\t\tbest = Math.max(best, otherSide + g[cycle[i]]);\n\t\t}\n\t\treturn best - sum;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\t// f[u]表示从u出发并最终回到u的最大边数\n\t\t// delta为了计算，g[u] = f[u] + delta\n\t\t// 表示额外选择一条最后不回到u的出口路线，能带来的最大增量\n\t\tint delta = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t\tdelta = Math.max(delta, g[v] + 1);\n\t\t\t\t} else {\n\t\t\t\t\tdelta = Math.max(delta, dpOnCycle(u, v));\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tg[u] = f[u] + delta;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tout.println(g[1]);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code03_CactusLongestRoute1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
