5f3809bb-af1f-4bfe-8124-ca72498146af	1c76ab63-b008-4242-b35c-c2ccba6b1d65	java	package class200;\n\n// 仙人掌最大独立集，java版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 你可以选择一些点，但是图中任意相邻两点不能同时选择\n// 计算能得到的最大点权累加和\n// 第一个测试链接，给定每个点的点权\n// 第二个测试链接，认为每个点的点权是1\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4410\n// 测试链接 : https://www.luogu.com.cn/problem/P10779\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_CactusIndependentSet1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int INF = 1000000000;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// 收集环上的节点，不包含环顶\n\tpublic static int[] cycle = new int[MAXN];\n\n\t// dp[u][0] : 以u为头的子仙人掌中，不选u的情况下，获得的最大收益\n\t// dp[u][1] : 以u为头的子仙人掌中，选u的情况下，获得的最大收益\n\tpublic static int[][] dp = new int[MAXN][2];\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tcycle[++siz] = pop;\n\t\t} while (pop != v);\n\t\t// 不选u\n\t\tint pre0 = dp[cycle[1]][0];\n\t\tint pre1 = dp[cycle[1]][1];\n\t\tint cur0, cur1;\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tint x = cycle[i];\n\t\t\tcur0 = Math.max(pre0, pre1) + dp[x][0];\n\t\t\tcur1 = pre0 + dp[x][1];\n\t\t\tpre0 = cur0;\n\t\t\tpre1 = cur1;\n\t\t}\n\t\tdp[u][0] += Math.max(pre0, pre1);\n\t\t// 选u\n\t\tpre0 = dp[cycle[1]][0];\n\t\tpre1 = -INF;\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tint x = cycle[i];\n\t\t\tcur0 = Math.max(pre0, pre1) + dp[x][0];\n\t\t\tcur1 = pre0 + dp[x][1];\n\t\t\tpre0 = cur0;\n\t\t\tpre1 = cur1;\n\t\t}\n\t\tdp[u][1] += pre0;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tdp[u][0] = 0;\n\t\tdp[u][1] = arr[u];\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\tdp[u][0] = 0;\n\t\t\t\tdp[u][1] = arr[u];\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\n\t\t// 洛谷P4410，使用如下的点权设置\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\n\t\t// 洛谷P10779，使用如下的点权设置\n//\t\tfor (int i = 1; i <= n; i++) {\n//\t\t\tarr[i] = 1;\n//\t\t}\n\n\t\ttarjan2(1, 0);\n\t\tout.println(Math.max(dp[1][0], dp[1][1]));\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code04_CactusIndependentSet1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
