9397e4bc-dfda-42df-9c58-f894e0cfab7b	1c76ab63-b008-4242-b35c-c2ccba6b1d65	java	package class200;\n\n// 仙人掌直径，java版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 点x到点y的距离，是指x到y的最短路径中的边数\n// 仙人掌直径，是指任意两点距离的最大值\n// 输入保证图是仙人掌，计算仙人掌直径\n// 1 <= n <= 5 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4244\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_CactusDiameter1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// dist[u] : 以u为头的子仙人掌中，u到任意点的最短路距离的最大值\n\tpublic static int[] dist = new int[MAXN];\n\t// 收集环中每个点的dist，然后复制一份\n\tpublic static int[] arr = new int[MAXN << 1];\n\t// 单调队列\n\tpublic static int[] que = new int[MAXN << 1];\n\t// 答案\n\tpublic static int diameter;\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tarr[++siz] = dist[u];\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tarr[++siz] = dist[pop];\n\t\t} while (pop != v);\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\tarr[i + siz] = arr[i];\n\t\t}\n\t\tint l = 1, r = 0;\n\t\tque[++r] = 1;\n\t\tfor (int i = 2; i <= siz << 1; i++) {\n\t\t\twhile (l <= r && (i - que[l]) * 2 > siz) {\n\t\t\t\tl++;\n\t\t\t}\n\t\t\tdiameter = Math.max(diameter, arr[i] + i + arr[que[l]] - que[l]);\n\t\t\twhile (l <= r && arr[que[r]] - que[r] <= arr[i] - i) {\n\t\t\t\tr--;\n\t\t\t}\n\t\t\tque[++r] = i;\n\t\t}\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tdist[u] = Math.max(dist[u], arr[i] + Math.min(i - 1, siz - (i - 1)));\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + 1);\n\t\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + 1);\n\t\t\t\t} else {\n\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + 1);\n\t\t\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + 1);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, k, x, y; i <= m; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tfor (int j = 2; j <= k; j++) {\n\t\t\t\ty = in.nextInt();\n\t\t\t\taddEdge(x, y);\n\t\t\t\taddEdge(y, x);\n\t\t\t\tx = y;\n\t\t\t}\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tout.println(diameter);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n	模板：Code05_CactusDiameter1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
