e6c175f2-75a4-43ed-a243-de5351ec7cbc	1c76ab63-b008-4242-b35c-c2ccba6b1d65	java	package class200;\n\n// 仙人掌遍历和找环的过程，java版\n\npublic class ShowDetail1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int[] weight = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] fromWeight = new int[MAXN];\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) continue;\n\t\t\tint v = to[e], w = weight[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tfromWeight[v] = w; // 设置v的from信息\n\t\t\t\tif (low[v] < dfn[u]) { // 没有扎起口袋\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t// 发现割边，实现有关割边的处理\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\t// 发现了环，实现有关环的处理\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[v] < dfn[u]) { // 发现回边\n\t\t\t\t\tfromWeight[v] = w; // 闭合边的信息给入环节点\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\t// 如果发现弃边，一般什么也不做\n\t\t\t}\n\t\t}\n\t}\n\n}\n	模板：ShowDetail1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
