13c85e46-ffd3-4dfd-bc59-2c0ffadcb864	dbfe17d0-f5aa-4468-849a-b90b0c83a4eb	java	package class201;\n\n// 网络，java版\n// 无向图中有n个点，点有点权，有m条边，边有颜色，颜色总数量为C，颜色的数值0 ~ C-1\n// 无向图保证没有重边和自环，并且始终满足如下两个性质\n// 性质1，对于任意节点连出去的边中，相同颜色的边不超过两条\n// 性质2，图中不存在同色的环，指相同颜色的边构成的环\n// 一共有q条操作，类型如下\n// 操作 0 x y   : 点x的点权变成y\n// 操作 2 c x y : 颜色c的边构成的图中，打印x到y路径上的点权最大值，不连通打印-1\n// 操作 1 x y c : 点x到点y的直接边，颜色改成c，下面是具体说明\n// 若修改后不满足性质1，不修改边的颜色，打印 "Error 1.”\n// 若修改后不满足性质2，不修改边的颜色，打印 "Error 2."\n// 若同时不满足性质1和性质2，优先打印 "Error 1."\n// 若不存在直接边，不修改边的颜色，打印 "No such edge."\n// 若上述情况都没出现，那么修改边的颜色，打印 "Success."\n// 1 <= n <= 10^4\n// C <= 10\n// 1 <= m、q <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2173\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\n\npublic class Code07_Network1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m, C, q;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static boolean[] rev = new boolean[MAXN];\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] maxv = new int[MAXN];\n\n\tpublic static int[] nodeDegree = new int[MAXN];\n\tpublic static HashMap<Long, Integer> edgeColor = new HashMap<>();\n\n\tpublic static void up(int x) {\n\t\tmaxv[x] = Math.max(Math.max(maxv[ls[x]], maxv[rs[x]]), arr[x]);\n\t}\n\n\tpublic static boolean isroot(int x) {\n\t\treturn ls[fa[x]] != x && rs[fa[x]] != x;\n\t}\n\n\tpublic static int lr(int x) {\n\t\treturn ls[fa[x]] == x ? 0 : 1;\n\t}\n\n\tpublic static void reverse(int x) {\n\t\tif (x != 0) {\n\t\t\tint tmp = ls[x];\n\t\t\tls[x] = rs[x];\n\t\t\trs[x] = tmp;\n\t\t\trev[x] = !rev[x];\n\t\t}\n\t}\n\n\tpublic static void down(int x) {\n\t\tif (rev[x]) {\n\t\t\treverse(ls[x]);\n\t\t\treverse(rs[x]);\n\t\t\trev[x] = false;\n\t\t}\n\t}\n\n\tpublic static void rotate(int x) {\n\t\tint f = fa[x], g = fa[f];\n\t\tif (lr(x) == 0) {\n\t\t\tls[f] = rs[x];\n\t\t\tif (ls[f] != 0) {\n\t\t\t\tfa[ls[f]] = f;\n\t\t\t}\n\t\t\trs[x] = f;\n\t\t} else {\n\t\t\trs[f] = ls[x];\n\t\t\tif (rs[f] != 0) {\n\t\t\t\tfa[rs[f]] = f;\n\t\t\t}\n\t\t\tls[x] = f;\n\t\t}\n\t\tif (!isroot(f)) {\n\t\t\tif (lr(f) == 0) {\n\t\t\t\tls[g] = x;\n\t\t\t} else {\n\t\t\t\trs[g] = x;\n\t\t\t}\n\t\t}\n\t\tfa[f] = x;\n\t\tfa[x] = g;\n\t\tup(f);\n\t\tup(x);\n\t}\n\n\tpublic static void splay(int x) {\n\t\tint siz = 0;\n\t\tsta[++siz] = x;\n\t\tfor (int y = x; !isroot(y); y = fa[y]) {\n\t\t\tsta[++siz] = fa[y];\n\t\t}\n\t\twhile (siz != 0) {\n\t\t\tdown(sta[siz--]);\n\t\t}\n\t\twhile (!isroot(x)) {\n\t\t\tint f = fa[x];\n\t\t\tif (!isroot(f)) {\n\t\t\t\tif (lr(x) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(x);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(x);\n\t\t}\n\t}\n\n\tpublic static void access(int x) {\n\t\tfor (int y = 0; x != 0; y = x, x = fa[x]) {\n\t\t\tsplay(x);\n\t\t\trs[x] = y;\n\t\t\tup(x);\n\t\t}\n\t}\n\n\tpublic static void makeroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\treverse(x);\n\t}\n\n\tpublic static int findroot(int x) {\n\t\taccess(x);\n\t\tsplay(x);\n\t\tdown(x);\n\t\twhile (ls[x] != 0) {\n\t\t\tx = ls[x];\n\t\t\tdown(x);\n\t\t}\n\t\tsplay(x);\n\t\treturn x;\n\t}\n\n\tpublic static void split(int x, int y) {\n\t\tmakeroot(x);\n\t\taccess(y);\n\t\tsplay(y);\n\t}\n\n\tpublic static void link(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) != x) {\n\t\t\tfa[x] = y;\n\t\t}\n\t}\n\n\tpublic static void cut(int x, int y) {\n\t\tmakeroot(x);\n\t\tif (findroot(y) == x && fa[y] == x && ls[y] == 0 && rs[x] == y) {\n\t\t\tfa[y] = rs[x] = 0;\n\t\t\tup(x);\n\t\t}\n\t}\n\n\tpublic static int node(int c, int x) {\n\t\treturn c * n + x;\n\t}\n\n\tpublic static long edge(int x, int y) {\n\t\tint a = Math.min(x, y);\n\t\tint b = Math.max(x, y);\n\t\treturn (1L * a) << 32 | b;\n\t}\n\n\tpublic static void connect(int c, int x, int y) {\n\t\tint u = node(c, x);\n\t\tint v = node(c, y);\n\t\tnodeDegree[u]++;\n\t\tnodeDegree[v]++;\n\t\tlink(u, v);\n\t\tedgeColor.put(edge(x, y), c);\n\t}\n\n\tpublic static void disconnect(int c, int x, int y) {\n\t\tint u = node(c, x);\n\t\tint v = node(c, y);\n\t\tnodeDegree[u]--;\n\t\tnodeDegree[v]--;\n\t\tcut(u, v);\n\t\tedgeColor.remove(edge(x, y));\n\t}\n\n\tpublic static void updateNode(int x, int v) {\n\t\tfor (int c = 0; c < C; c++) {\n\t\t\tint cur = node(c, x);\n\t\t\tsplay(cur);\n\t\t\tarr[cur] = v;\n\t\t\tup(cur);\n\t\t}\n\t}\n\n\tpublic static int updateEdge(int x, int y, int c) {\n\t\tInteger pre = edgeColor.get(edge(x, y));\n\t\tif (pre == null) {\n\t\t\treturn 3;\n\t\t}\n\t\tint p = pre;\n\t\tif (p == c) {\n\t\t\treturn 4;\n\t\t}\n\t\tif (nodeDegree[node(c, x)] >= 2 || nodeDegree[node(c, y)] >= 2) {\n\t\t\treturn 1;\n\t\t}\n\t\tif (findroot(node(c, x)) == findroot(node(c, y))) {\n\t\t\treturn 2;\n\t\t}\n\t\tdisconnect(p, x, y);\n\t\tconnect(c, x, y);\n\t\treturn 4;\n\t}\n\n\tpublic static int query(int c, int x, int y) {\n\t\tint u = node(c, x);\n\t\tint v = node(c, y);\n\t\tif (findroot(u) != findroot(v)) {\n\t\t\treturn -1;\n\t\t}\n\t\tsplit(u, v);\n\t\treturn maxv[v];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tC = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, v; i <= n; i++) {\n\t\t\tv = in.nextInt();\n\t\t\tfor (int c = 0; c < C; c++) {\n\t\t\t\tint cur = node(c, i);\n\t\t\t\tarr[cur] = v;\n\t\t\t\tmaxv[cur] = v;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1, x, y, c; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\tconnect(c, x, y);\n\t\t}\n\t\tfor (int i = 1, op, x, y, c; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tupdateNode(x, y);\n\t\t\t} else if (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\tint ans = updateEdge(x, y, c);\n\t\t\t\tif (ans == 1) {\n\t\t\t\t\tout.println("Error 1.");\n\t\t\t\t}\n\t\t\t\tif (ans == 2) {\n\t\t\t\t\tout.println("Error 2.");\n\t\t\t\t}\n\t\t\t\tif (ans == 3) {\n\t\t\t\t\tout.println("No such edge.");\n\t\t\t\t}\n\t\t\t\tif (ans == 4) {\n\t\t\t\t\tout.println("Success.");\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tc = in.nextInt();\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tout.println(query(c, x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}	模板：Code07_Network1.java	2026-07-25 03:11:34.779768+00	2026-07-25 03:11:34.779768+00
