 cin >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans1[i] << '/' << ans2[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_BloodyString1.java`\n\n```java\npackage class176;\n\n// 大爷的字符串题，java版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，众数出现了几次，打印次数的相反数\n// 1 <= n、m <= 2 * 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3709\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code04_BloodyString1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] bi = new int[MAXN];\n\n\t// cnt1[i] = j，表示窗口内，数字i出现了j次\n\t// cnt2[i] = j，表示窗口内，出现了i次的数，有j种\n\t// maxCnt，表示窗口内，众数的次数\n\tpublic static int[] cnt1 = new int[MAXN];\n\tpublic static int[] cnt2 = new int[MAXN];\n\tpublic static int maxCnt = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\tpublic static int kth(int len, int num) {\n\t\tint left = 1, right = len, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (cnt1[num] == maxCnt && cnt2[cnt1[num]] == 1) {\n\t\t\tmaxCnt--;\n\t\t}\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]--;\n\t\tcnt2[cnt1[num]]++;\n\t}\n\n\tpublic static void add(int num) {\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]++;\n\t\tcnt2[cnt1[num]]++;\n\t\tmaxCnt = Math.max(maxCnt, cnt1[num]);\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(len, arr[i]);\n\t\t}\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\tans[query[i][2]] = maxCnt;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(-ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n```\n\n### `Code04_BloodyString2.java`\n\n```java\npackage class176;\n\n// 大爷的字符串题，C++版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，众数出现了几次，打印次数的相反数\n// 1 <= n、m <= 2 * 10^5\n// 1 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3709\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, id;\n//};\n//\n//const int MAXN = 200001;\n//int n, m;\n//int arr[MAXN];\n//int sorted[MAXN];\n//Query query[MAXN];\n//int bi[MAXN];\n//\n//int cnt1[MAXN];\n//int cnt2[MAXN];\n//int maxCnt = 0;\n//\n//int ans[MAXN];\n//\n//bool QueryCmp(Query &a, Query &b) {\n//    if (bi[a.l] != bi[b.l]) {\n//        return bi[a.l] < bi[b.l];\n//    }\n//    return a.r < b.r;\n//}\n//\n//int kth(int len, int num) {\n//    int left = 1, right = len, mid, ret = 0;\n//    while (left <= right) {\n//        mid = (left + right) >> 1;\n//        if (sorted[mid] <= num) {\n//        \tret = mid;\n//            left = mid + 1;\n//        } else {\n//            right = mid - 1;\n//        }\n//    }\n//    return ret;\n//}\n//\n//void del(int num) {\n//    if (cnt1[num] == maxCnt && cnt2[cnt1[num]] == 1) {\n//        maxCnt--;\n//    }\n//    cnt2[cnt1[num]]--;\n//    cnt1[num]--;\n//    cnt2[cnt1[num]]++;\n//}\n//\n//void add(int num) {\n//    cnt2[cnt1[num]]--;\n//    cnt1[num