eamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code05_XorSequence1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXS = 1 << 20;\n\tpublic static int n, m, k;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] bi = new int[MAXN];\n\n\t// pre[i] == x，表示前i个数字的前缀异或和为x\n\tpublic static int[] pre = new int[MAXN];\n\t// cnt[x] = a，表示窗口内，前缀异或和x，一共有a个\n\tpublic static long[] cnt = new long[MAXS];\n\t// num表示窗口内，异或和为k的子数组数量\n\tpublic static long num;\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\t// 前缀异或和x要删除一次\n\tpublic static void del(int x) {\n\t\tif (k != 0) {\n\t\t\tnum -= cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum -= (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t\tcnt[x]--;\n\t\tif (k != 0) {\n\t\t\tnum += cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum += (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t}\n\n\t// 前缀异或和x要增加一次\n\tpublic static void add(int x) {\n\t\tif (k != 0) {\n\t\t\tnum -= cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum -= (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t\tcnt[x]++;\n\t\tif (k != 0) {\n\t\t\tnum += cnt[x] * cnt[x ^ k];\n\t\t} else {\n\t\t\tnum += (cnt[x] * (cnt[x] - 1)) >> 1;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tpre[i] = pre[i - 1] ^ arr[i];\n\t\t}\n\t\tint blen = (int) Math.sqrt(n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t// 任务范围[jobl, jobr]，但是前缀可能性会多一种\n\t\t\t// 所以左边界-1\n\t\t\tint jobl = query[i][0] - 1;\n\t\t\tint jobr = query[i][1];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(pre[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(pre[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(pre[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(pre[winr--]);\n\t\t\t}\n\t\t\tans[query[i][2]] = num;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_XorSequence2.java`\n\n```java\npackage class176;\n\n// 异或序列，C++版\n// 给定一个长度为n的数组arr，给定一个数字k，一共有m条查询，格式如下\n// 查询 l r : arr[l..r]范围上，有多少子数组的异或和为k，打印其数量\n// 0 <= n、m、k、arr[i] <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4462\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, id;\n//};\n//\n//const int MAXN = 100001;\n//const int MAXS = 1 << 20;\n//int n, m, k;\n//int arr[MAXN];\n//Query query[MAXN];\n//int bi[MAXN];\n//\n//int pre[MAXN];\n//long long cnt[MAXS];\n//long long num;\n//long long ans[MAXN];\n//\n//bool QueryCmp(Query &a, Query &b) {\n//    if (bi[a.l] != bi[b.l]) {\n//        return bi[a.l] < bi[b.l];\n//    }\n//    return a.r < b.r;\n//}\n//\n//void del(int x) {\n//    if (k != 0) {\n//        num -= cnt[x] * cnt[x ^ k];\n//    } else {\n//        num -= (cnt[x] * (cnt[x] - 1)) >> 1;\n//    }\n//    cnt[x]--;\n//    if (k != 0) {\n//        num += cnt[x] * cnt[x ^ k];\n//    } else {\n//        num += (cnt[x] * (cnt[x] - 1)) >> 1;\n//    }\n//}\n//\n//void add(int x) {\n//    if (k != 0) {\n//        num -= cnt[x] * cnt[x ^ k];\n//    } else {\n//        num -= (cnt[x] * (cnt[x] - 1)) >> 1;\n//    }\n//    cnt[x]++;\n//    if (k != 0) {\n//        num += cnt[x] * cnt[x ^ k];\n//    } else {\n//        num += (cnt[x] * (cnt[x] - 1)) >> 1;\n//    }\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        pre[i] = pre[i - 1] ^ arr[i];\n//    }\n//    int blen = (int)sqrt(n);\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    sort(query + 1, query + m + 1, QueryCmp);\n//}\n//\n//void compute() {\n//    int winl = 1, winr = 0;\n//    for (int i = 1; i <= m; i++) {\n//        int jobl = query[i].l - 1;\n//        int jobr = query[i].r;\n//        while (winl > jobl) {\n//            add(pre[--winl]);\n//        }\n//        while (winr < jobr) {\n//            add(pre[++winr]);\n//        }\n//        while (winl < jobl) {\n//            del(pre[winl++]);\n//        }\n//        while (winr > jobr) {\n//            del(pre[winr--]);\n//        }\n//        ans[query[i].id] = num;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> k;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> query[i].l;\n//        cin >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_MoWithModify1.java`\n\n```java\npackage class176;\n\n// 带修莫队入门题，java版\n// 给定一个长度为n的数组arr，一共有m条操作，操作格式如下\n// 操作 Q l r     : 打印arr[l..r]范围上有几种不同的数\n// 操作 R pos val : 把arr[pos]的值设置成val\n// 1 <= n、m <= 2 * 10^5\n// 1 <= arr[i]、val <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P1903\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code06_MoWithModify1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXV = 1000001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] bi = new int[MAXN];\n\n\t// 每条查询 : jobl、jobr、jobt、id\n\tpublic static int[][] query = new int[MAXN][4];\n\t// 每条修改 : pos、val\n\tpublic static int[][] update = new int[MAXN][2];\n\tpublic static int cntq, cntu;\n\n\tpublic static int[] cnt = new int[MAXV];\n\tpublic static int kind;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 带修莫队的任务排序\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif (bi[a[1]] != bi[b[1]]) {\n\t\t\t\treturn bi[a[1]] - bi[b[1]];\n\t\t\t}\n\t\t\treturn a[2] - b[2];\n\t\t}\n\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (--cnt[num] == 0) {\n\t\t\tkind--;\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tif (++cnt[num] == 1) {\n\t\t\tkind++;\n\t\t}\n\t}\n\n\t// jobl..jobr 数组范围\n\t// tim : 生效或者撤销的修改时间点\n\tpublic static void moveTime(int jobl, int jobr, int tim) {\n\t\tint pos = update[tim][0];\n\t\tint val = update[tim][1];\n\t\tif (jobl <= pos && pos <= jobr) {\n\t\t\tdel(arr[pos]);\n\t\t\tadd(val);\n\t\t}\n\t\t// 不管生效还是撤销，数据只要在arr和update之间交换即可\n\t\tint tmp = arr[pos];\n\t\tarr[pos] = val;\n\t\tupdate[tim][1] = tmp;\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0, wint = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint jobt = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\twhile (wint < jobt) {\n\t\t\t\tmoveTime(jobl, jobr, ++wint);\n\t\t\t}\n\t\t\twhile (wint > jobt) {\n\t\t\t\tmoveTime(jobl, jobr, wint--);\n\t\t\t}\n\t\t\tans[id] = kind;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = Math.max(1, (int) Math.pow(n, 2.0 / 3));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tchar op;\n\t\tint l, r, pos, val;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'Q') {\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tcntq++;\n\t\t\t\tquery[cntq][0] = l;\n\t\t\t\tquery[cntq][1] = r;\n\t\t\t\tquery[cntq][2] = cntu;\n\t\t\t\tquery[cntq][3] = cntq;\n\t\t\t} else {\n\t\t\t\tpos = in.nextInt();\n\t\t\t\tval = in.nextInt();\n\t\t\t\tcntu++;\n\t\t\t\tupdate[cntu][0] = pos;\n\t\t\t\tupdate[cntu][1] = val;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_MoWithModify2.java`\n\n```java\npackage class176;\n\n// 带修莫队入门题，C++版\n// 给定一个长度为n的数组arr，一共有m条操作，操作格式如下\n// 操作 Q l r     : 打印arr[l..r]范围上有几种不同的数\n// 操作 R pos val : 把arr[pos]的值设置成val\n// 1 <= n、m <= 2 * 10^5\n// 1 <= arr[i]、val <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P1903\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, t, id;\n//};\n//\n//struct Update {\n//    int pos, val;\n//};\n//\n//const int MAXN = 200001;\n//const int MAXV = 1000001;\n//int n, m;\n//int arr[MAXN];\n//int bi[MAXN];\n//\n//Query query[MAXN];\n//Update update[MAXN];\n//int cntq, cntu;\n//\n//int cnt[MAXV];\n//int kind;\n//\n//int ans[MAXN];\n//\n//bool QueryCmp(Query &a, Query &b) {\n//    if (bi[a.l] != bi[b.l]) {\n//        return bi[a.l] < bi[b.l];\n//    }\n//    if (bi[a.r] != bi[b.r]) {\n//        return bi[a.r] < bi[b.r];\n//    }\n//    return a.t < b.t;\n//}\n//\n//void del(int num) {\n//    if (--cnt[num] == 0) {\n//        kind--;\n//    }\n//}\n//\n//void add(int num) {\n//    if (++cnt[num] == 1) {\n//        kind++;\n//    }\n//}\n//\n//void moveTime(int jobl, int jobr, int tim) {\n//    int pos = update[tim].pos;\n//    int val = update[tim].val;\n//    if (jobl <= pos && pos <= jobr) {\n//        del(arr[pos]);\n//        add(val);\n//    }\n//    int tmp = arr[pos];\n//    arr[pos] = val;\n//    update[tim].val = tmp;\n//}\n//\n//void compute() {\n//    int winl = 1, winr = 0, wint = 0;\n//    for (int i = 1; i <= cntq; i++) {\n//        int jobl = query[i].l;\n//        int jobr = query[i].r;\n//        int jobt = query[i].t;\n//        int id = query[i].id;\n//        while (winl > jobl) {\n//            add(arr[--winl]);\n//        }\n//        while (winr < jobr) {\n//            add(arr[++winr]);\n//        }\n//        while (winl < jobl) {\n//            del(arr[winl++]);\n//        }\n//        while (winr > jobr) {\n//            del(arr[winr--]);\n//        }\n//        while (wint < jobt) {\n//            moveTime(jobl, jobr, ++wint);\n//        }\n//        while (wint > jobt) {\n//            moveTime(jobl, jobr, wint--);\n//        }\n//        ans[id] = kind;\n//     }\n//}\n//\n//void prepare() {\n//    int blen = max(1, (int)pow(n, 2.0 / 3));\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    sort(query + 1, query + cntq + 1, QueryCmp);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    char op;\n//    int l, r, pos, val;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op;\n//        if (op == 'Q') {\n//            cin >> l >> r;\n//            cntq++;\n//            query[cntq].l = l;\n//            query[cntq].r = r;\n//            query[cntq].t = cntu;\n//            query[cntq].id = cntq;\n//        } else {\n//            cin >> pos >> val;\n//            cntu++;\n//            update[cntu].pos = pos;\n//            update[cntu].val = val;\n//        }\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= cntq; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_UniqueNumbers1.java`\n\n```java\npackage class176;\n\n// 统计出现1次的数，java版\n// 给定一个长度为n的数组arr，下标0~n-1，一共有m条操作，格式如下\n// 操作 1 pos val : 把arr[pos]的值设置成val\n// 操作 2 l r     : 查询arr[l..r]范围上，有多少种数出现了1次\n// 0 <= n、m、arr[i] <= 2 * 10^5 \n// 测试链接 : https://www.luogu.com.cn/problem/SP30906\n// 测试链接 : https://www.spoj.com/problems/ADAUNIQ/\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code07_UniqueNumbers2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code07_UniqueNumbers1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[][] query = new int[MAXN][4];\n\tpublic static int[][] update = new int[MAXN][2];\n\tpublic static int cntq, cntu;\n\n\t// 每种数字的词频统计\n\tpublic static int[] cnt = new int[MAXN];\n\t// curCnt代表出现次数1次的数有几种\n\tpublic static int curCnt = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif (bi[a[1]] != bi[b[1]]) {\n\t\t\t\treturn bi[a[1]] - bi[b[1]];\n\t\t\t}\n\t\t\treturn a[2] - b[2];\n\t\t}\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (cnt[num] == 1) {\n\t\t\tcurCnt--;\n\t\t}\n\t\tif (cnt[num] == 2) {\n\t\t\tcurCnt++;\n\t\t}\n\t\tcnt[num]--;\n\t}\n\n\tpublic static void add(int num) {\n\t\tif (cnt[num] == 0) {\n\t\t\tcurCnt++;\n\t\t}\n\t\tif (cnt[num] == 1) {\n\t\t\tcurCnt--;\n\t\t}\n\t\tcnt[num]++;\n\t}\n\n\tpublic static void moveTime(int jobl, int jobr, int tim) {\n\t\tint pos = update[tim][0];\n\t\tint val = update[tim][1];\n\t\tif (jobl <= pos && pos <= jobr) {\n\t\t\tdel(arr[pos]);\n\t\t\tadd(val);\n\t\t}\n\t\tint tmp = arr[pos];\n\t\tarr[pos] = val;\n\t\tupdate[tim][1] = tmp;\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0, wint = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint jobt = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\twhile (wint < jobt) {\n\t\t\t\tmoveTime(jobl, jobr, ++wint);\n\t\t\t}\n\t\t\twhile (wint > jobt) {\n\t\t\t\tmoveTime(jobl, jobr, wint--);\n\t\t\t}\n\t\t\tans[id] = curCnt;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint blen = Math.max(1, (int) Math.pow(n, 2.0 / 3));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, l, r, pos, val; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tpos = in.nextInt();\n\t\t\t\tval = in.nextInt();\n\t\t\t\tcntu++;\n\t\t\t\tupdate[cntu][0] = pos + 1;\n\t\t\t\tupdate[cntu][1] = val;\n\t\t\t} else {\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tcntq++;\n\t\t\t\tquery[cntq][0] = l + 1;\n\t\t\t\tquery[cntq][1] = r + 1;\n\t\t\t\tquery[cntq][2] = cntu;\n\t\t\t\tquery[cntq][3] = cntq;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_UniqueNumbers2.java`\n\n```java\npackage class176;\n\n// 统计出现1次的数，C++版\n// 给定一个长度为n的数组arr，下标0~n-1，一共有m条操作，格式如下\n// 操作 1 pos val : 把arr[pos]的值设置成val\n// 操作 2 l r     : 查询arr[l..r]范围上，有多少种数出现了1次\n// 0 <= n、m、arr[i] <= 2 * 10^5 \n// 测试链接 : https://www.luogu.com.cn/problem/SP30906\n// 测试链接 : https://www.spoj.com/problems/ADAUNIQ/\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, t, id;\n//};\n//\n//struct Update {\n//    int pos, val;\n//};\n//\n//const int MAXN = 200001;\n//int n, m;\n//int arr[MAXN];\n//int bi[MAXN];\n//\n//Query query[MAXN];\n//Update update[MAXN];\n//int cntq, cntu;\n//\n//int cnt[MAXN];\n//int curCnt;\n//\n//int ans[MAXN];\n//\n//bool QueryCmp(Query &a, Query &b) {\n//    if (bi[a.l] != bi[b.l]) {\n//        return bi[a.l] < bi[b.l];\n//    }\n//    if (bi[a.r] != bi[b.r]) {\n//        return bi[a.r] < bi[b.r];\n//    }\n//    return a.t < b.t;\n//}\n//\n//void del(int num) {\n//    if (cnt[num] == 1) {\n//        curCnt--;\n//    }\n//    if (cnt[num] == 2) {\n//        curCnt++;\n//    }\n//    cnt[num]--;\n//}\n//\n//void add(int num) {\n//    if (cnt[num] == 0) {\n//        curCnt++;\n//    }\n//    if (cnt[num] == 1) {\n//        curCnt--;\n//    }\n//    cnt[num]++;\n//}\n//\n//void moveTime(int jobl, int jobr, int tim) {\n//    int pos = update[tim].pos;\n//    int val = update[tim].val;\n//    if (jobl <= pos && pos <= jobr) {\n//        