e class176;\n\n// 机器学习，java版\n// 给定一个长度为n的数组arr，一共有m条操作，操作格式如下\n// 操作 1 l r     : arr[l..r]范围上，每种数字出现的次数，假设构成一个集合\n//                  打印这个集合中，没出现过的最小正数\n// 操作 2 pos val : 把arr[pos]的值设置成val\n// 1 <= n、m <= 10^5\n// 1 <= arr[i]、val <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF940F\n// 测试链接 : https://codeforces.com/problemset/problem/940/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code08_MachineLearning1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN << 1];\n\tpublic static int[] bi = new int[MAXN];\n\n\tpublic static int[][] query = new int[MAXN][4];\n\tpublic static int[][] update = new int[MAXN][2];\n\tpublic static int cntq, cntu;\n\n\t// cnt1[i] = j，表示i这种数出现了j次\n\t// cnt2[i] = j，表示出现次数为i的数有j种\n\tpublic static int[] cnt1 = new int[MAXN << 1];\n\tpublic static int[] cnt2 = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\tif (bi[a[1]] != bi[b[1]]) {\n\t\t\t\treturn bi[a[1]] - bi[b[1]];\n\t\t\t}\n\t\t\treturn a[2] - b[2];\n\t\t}\n\t}\n\n\tpublic static int kth(int len, int num) {\n\t\tint left = 1, right = len, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void del(int num) {\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]--;\n\t\tcnt2[cnt1[num]]++;\n\t}\n\n\tpublic static void add(int num) {\n\t\tcnt2[cnt1[num]]--;\n\t\tcnt1[num]++;\n\t\tcnt2[cnt1[num]]++;\n\t}\n\n\tpublic static void moveTime(int jobl, int jobr, int tim) {\n\t\tint pos = update[tim][0];\n\t\tint val = update[tim][1];\n\t\tif (jobl <= pos && pos <= jobr) {\n\t\t\tdel(arr[pos]);\n\t\t\tadd(val);\n\t\t}\n\t\tint tmp = arr[pos];\n\t\tarr[pos] = val;\n\t\tupdate[tim][1] = tmp;\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0, wint = 0;\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint jobt = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tadd(arr[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tdel(arr[winr--]);\n\t\t\t}\n\t\t\twhile (wint < jobt) {\n\t\t\t\tmoveTime(jobl, jobr, ++wint);\n\t\t\t}\n\t\t\twhile (wint > jobt) {\n\t\t\t\tmoveTime(jobl, jobr, wint--);\n\t\t\t}\n\t\t\t// 如下枚举看似暴力，其实O(根号n)的复杂度\n\t\t\tint ret = 1;\n\t\t\twhile (ret <= n && cnt2[ret] > 0) {\n\t\t\t\tret++;\n\t\t\t}\n\t\t\tans[id] = ret;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tint len = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++len] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tsorted[++len] = update[i][1];\n\t\t}\n\t\tArrays.sort(sorted, 1, len + 1);\n\t\tint tmp = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (sorted[tmp] != sorted[i]) {\n\t\t\t\tsorted[++tmp] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tlen = tmp;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(len, arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tupdate[i][1] = kth(len, update[i][1]);\n\t\t}\n\t\tint blen = Math.max(1, (int) Math.pow(n, 2.0 / 3));\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, cntq + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, l, r, pos, val; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tl = in.nextInt();\n\t\t\t\tr = in.nextInt();\n\t\t\t\tcntq++;\n\t\t\t\tquery[cntq][0] = l;\n\t\t\t\tquery[cntq][1] = r;\n\t\t\t\tquery[cntq][2] = cntu;\n\t\t\t\tquery[cntq][3] = cntq;\n\t\t\t} else {\n\t\t\t\tpos = in.nextInt();\n\t\t\t\tval = in.nextInt();\n\t\t\t\tcntu++;\n\t\t\t\tupdate[cntu][0] = pos;\n\t\t\t\tupdate[cntu][1] = val;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= cntq; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code08_MachineLearning2.java`\n\n```java\npackage class176;\n\n// 机器学习，java版\n// 给定一个长度为n的数组arr，一共有m条操作，操作格式如下\n// 操作 1 l r     : arr[l..r]范围上，每种数字出现的次数，假设构成一个集合\n//                  打印这个集合中，没出现过的最小正数\n// 操作 2 pos val : 把arr[pos]的值设置成val\n// 1 <= n、m <= 10^5\n// 1 <= arr[i]、val <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF940F\n// 测试链接 : https://codeforces.com/problemset/problem/940/F\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, t, id;\n//};\n//\n//struct Update {\n//    int pos, val;\n//};\n//\n//const int MAXN = 100001;\n//int n, m;\n//int arr[MAXN];\n//int sorted[MAXN << 1];\n//\n//int bi[MAXN];\n//Query query[MAXN];\n//Update update[MAXN];\n//int cntq, cntu;\n//\n//int cnt1[MAXN << 1];\n//int cnt2[MAXN];\n//\n//int ans[MAXN];\n//\n//bool QueryCmp(Query &a, Query &b) {\n//    if (bi[a.l] != bi[b.l]) {\n//        return bi[a.l] < bi[b.l];\n//    }\n//    if (bi[a.r] != bi[b.r]) {\n//        return bi[a.r] < bi[b.r];\n//    }\n//    return a.t < b.t;\n//}\n//\n//int kth(int len, int num) {\n//    int left = 1, right = len, mid, ret = 0;\n//    while (left <= right) {\n//        mid = (left + right) >> 1;\n//        if (sorted[mid] <= num) {\n//            ret = mid;\n//            left = mid + 1;\n//        } else {\n//            right = mid - 1;\n//        }\n//    }\n//    return ret;\n//}\n//\n//void del(int num) {\n//    cnt2[cnt1[num]]--;\n//    cnt1[num]--;\n//    cnt2[cnt1[num]]++;\n//}\n//\n//void add(int num) {\n//    cnt2[cnt1[num]]--;\n//    cnt1[num]++;\n//    cnt2[cnt1[num]]++;\n//}\n//\n//void moveTime(int jobl, int jobr, int tim) {\n//    int pos = updat