/                }\n//                int backup = maxDist;\n//                while (winl > jobl) {\n//                    addLeft(--winl);\n//                }\n//                ans[id] = maxDist;\n//                maxDist = backup;\n//                while (winl <= br[block]) {\n//                    delLeft(winl++);\n//                }\n//            }\n//        }\n//    }\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        arr[i] += arr[i - 1];\n//    }\n//    for (int i = n; i >= 0; i--) {\n//        arr[i + 1] = arr[i];\n//    }\n//    n++;\n//    for (int i = 1; i <= m; i++) {\n//        query[i].r++;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        sorted[i] = arr[i];\n//    }\n//    sort(sorted + 1, sorted + n + 1);\n//    cntv = 1;\n//    for (int i = 2; i <= n; i++) {\n//        if (sorted[cntv] != sorted[i]) {\n//            sorted[++cntv] = sorted[i];\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        arr[i] = kth(arr[i]);\n//    }\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        br[i] = min(i * blen, n);\n//    }\n//    sort(query + 1, query + m + 1, QueryCmp);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> query[i].l >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_MoDelUndo1.java`\n\n```java\npackage class177;\n\n// 只删回滚莫队入门题，java版\n// 本题最优解为主席树，讲解158，题目2，已经讲述\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : 打印arr[l..r]内没有出现过的最小自然数，注意0是自然数\n// 0 <= n、m、arr[i] <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4137\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code05_MoDelUndo1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXB = 501;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\n\tpublic static int[] cnt = new int[MAXN];\n\tpublic static int mex;\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 只删回滚莫队经典排序\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn b[1] - a[1];\n\t\t}\n\n\t}\n\n\tpublic static void del(int num) {\n\t\tif (--cnt[num] == 0) {\n\t\t\tmex = Math.min(mex, num);\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tcnt[num]++;\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcnt[arr[i]]++;\n\t\t}\n\t\tmex = 0;\n\t\twhile (cnt[mex] != 0) {\n\t\t\tmex++;\n\t\t}\n\t\tint winl = 1, winr = n;\n\t\tfor (int block = 1, qi = 1; block <= bnum && qi <= m; block++) {\n\t\t\twhile (winl < bl[block]) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\tint beforeJob = mex;\n\t\t\tfor (; qi <= m && bi[query[qi][0]] == block; qi++) {\n\t\t\t\tint jobl = query[qi][0];\n\t\t\t\tint jobr = query[qi][1];\n\t\t\t\tint id = query[qi][2];\n\t\t\t\twhile (winr > jobr) {\n\t\t\t\t\tdel(arr[winr--]);\n\t\t\t\t}\n\t\t\t\tint backup = mex;\n\t\t\t\twhile (winl < jobl) {\n\t\t\t\t\tdel(arr[winl++]);\n\t\t\t\t}\n\t\t\t\tans[id] = mex;\n\t\t\t\tmex = backup;\n\t\t\t\twhile (winl > bl[block]) {\n\t\t\t\t\tadd(arr[--winl]);\n\t\t\t\t}\n\t\t\t}\n\t\t\twhile (winr < n) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\tmex = beforeJob;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_MoDelUndo2.java`\n\n```java\npackage class177;\n\n// 只删回滚莫队入门题，C++版\n// 本题最优解为主席树，讲解158，题目2，已经讲述\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : 