n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        bl[i] = (i - 1) * blen + 1;\n//    }\n//    sort(query + 1, query + m + 1, QueryCmp);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> query[i].l >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_BaldChief1.java`\n\n```java\npackage class177;\n\n// 秃子酋长，java版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : 打印arr[l..r]范围上，如果所有数排序后，\n//            相邻的数在原序列中的位置的差的绝对值之和\n// 注意arr很特殊，1~n这些数字在arr中都只出现1次\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P8078\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code06_BaldChief2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code06_BaldChief1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[][] query = new int[MAXN][3];\n\tpublic static int[] pos = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXN];\n\n\tpublic static int[] last = new int[MAXN + 1];\n\tpublic static int[] next = new int[MAXN + 1];\n\tpublic static long sum;\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn b[1] - a[1];\n\t\t}\n\n\t}\n\n\tpublic static void del(int num) {\n\t\tint less = last[num], more = next[num];\n\t\tif (less != 0) {\n\t\t\tsum -= Math.abs(pos[num] - pos[less]);\n\t\t}\n\t\tif (more != n + 1) {\n\t\t\tsum -= Math.abs(pos[more] - pos[num]);\n\t\t}\n\t\tif (less != 0 && more != n + 1) {\n\t\t\tsum += Math.abs(pos[more] - pos[less]);\n\t\t}\n\t\tnext[less] = more;\n\t\tlast[more] = less;\n\t}\n\n\t// 加数字的顺序，就是删数字顺序的回滚，才能这么方便的更新\n\tpublic static void add(int num) {\n\t\tnext[last[num]] = num;\n\t\tlast[next[num]] = num;\n\t}\n\n\tpublic static void compute() {\n\t\tfor (int v = 1; v <= n; v++) {\n\t\t\tlast[v] = v - 1;\n\t\t\tnext[v] = v + 1;\n\t\t}\n\t\tnext[0] = 1;\n\t\tlast[n + 1] = n;\n\t\tfor (int v = 2; v <= n; v++) {\n\t\t\tsum += Math.abs(pos[v] - pos[v - 1]);\n\t\t}\n\t\tint winl = 1, winr = n;\n\t\tfor (int block = 1, qi = 1; block <= bnum && qi <= m; block++) {\n\t\t\twhile (winl < bl[block]) {\n\t\t\t\tdel(arr[winl++]);\n\t\t\t}\n\t\t\tlong beforeJob = sum;\n\t\t\tfor (; qi <= m && bi[query[qi][0]] == block; qi++) {\n\t\t\t\tint jobl = query[qi][0];\n\t\t\t\tint jobr = query[qi][1];\n\t\t\t\tint id = query[qi][2];\n\t\t\t\twhile (winr > jobr) {\n\t\t\t\t\tdel(arr[winr--]);\n\t\t\t\t}\n\t\t\t\tlong backup = sum;\n\t\t\t\twhile (winl < jobl) {\n\t\t\t\t\tdel(arr[winl++]);\n\t\t\t\t}\n\t\t\t\tans[id] = sum;\n\t\t\t\tsum = backup;\n\t\t\t\twhile (winl > bl[block]) {\n\t\t\t\t\tadd(arr[--winl]);\n\t\t\t\t}\n\t\t\t}\n\t\t\twhile (winr < n) {\n\t\t\t\tadd(arr[++winr]);\n\t\t\t}\n\t\t\tsum = beforeJob;\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tpos[arr[i]] = i;\n\t\t}\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tquery[i][0] = in.nextInt();\n\t\t\tquery[i][1] = in.nextInt();\n\t\t\tquery[i][2] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n```\n\n### `Code06_BaldChief2.java`\n\n```java\npackage class177;\n\n// 秃子酋长，C++版\n// 给定一个长度为n的数组arr，一共有m条查询，格式如下\n// 查询 l r : 打印arr[l..r]范围上，如果所有数排序后，\n//            相邻的数在原序列中的位置的差的绝对值之和\n// 注意arr很特殊，1~n这些数字在arr中都只出现1次\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P8078\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Query {\n//    int l, r, id;\n//};\n//\n//const int MAXN = 500001;\n//int n, m;\n//int arr[MAXN];\n//Query query[MAXN];\n//int pos[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//i