//            }\n//            ans[id] = sum;\n//            sum = backup;\n//            while (winl > bl[block]) {\n//                add(arr[--winl]);\n//            }\n//        }\n//        while (winr < n) {\n//            add(arr[++winr]);\n//        }\n//        sum = beforeJob;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> query[i].l >> query[i].r;\n//        query[i].id = i;\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_MoOnTree1.java`\n\n```java\npackage class177;\n\n// 树上莫队入门题，java版\n// 一共有n个节点，每个节点给定颜色值，给定n-1条边，所有节点连成一棵树\n// 一共有m条查询，格式 u v : 打印点u到点v的简单路径上，有几种不同的颜色\n// 1 <= n <= 4 * 10^4\n// 1 <= m <= 10^5\n// 1 <= 颜色值 <= 2 * 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/SP10707\n// 测试链接 : https://www.spoj.com/problems/COT2/\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是本题卡常，无法通过所有测试用例\n// 想通过用C++实现，本节课Code07_MoOnTree2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code07_MoOnTree1 {\n\n\tpublic static int MAXN = 40001;\n\tpublic static int MAXM = 100001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\tpublic static int[] color = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int cntv;\n\n\t// 查询的参数，jobl、jobr、lca、id\n\t// 如果是类型1，那么lca == 0，表示空缺\n\t// 如果是类型2，那么lca > 0，查询结果需要补充这个单点信息\n\tpublic static int[][] query = new int[MAXM][4];\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\t// dep是深度\n\t// seg是括号序\n\t// st是节点开始序\n\t// ed是节点结束序\n\t// stjump是倍增表\n\t// cntd是括号序列的长度\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN << 1];\n\tpublic static int[] st = new int[MAXN];\n\tpublic static int[] ed = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\t// 分块\n\tpublic static int[] bi = new int[MAXN << 1];\n\n\t// 窗口信息\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] cnt = new int[MAXN];\n\tpublic static int kind = 0;\n\n\tpublic static int[] ans = new int[MAXM];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = cntv, mid, ret = 0;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) >> 1;\n\t\t\tif (sorted[mid] <= num) {\n\t\t\t\tret = mid;\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tseg[++cntd] = u;\n\t\tst[u] = cntd;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t\tseg[++cntd] = u;\n\t\ted[u] = cntd;\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\t// 普通莫队经典排序\n\tpublic static class QueryCmp implements Comparator<int[]> {\n\n\t\t@Override\n\t\tpublic int compare(int[] a, int[] b) {\n\t\t\tif (bi[a[0]] != bi[b[0]]) {\n\t\t\t\treturn bi[a[0]] - bi[b[0]];\n\t\t\t}\n\t\t\treturn a[1] - b[1];\n\t\t}\n\n\t}\n\n\t// 窗口不管是加入还是删除node\n\t// 只要遇到node就翻转信息即可\n\tpublic static void invert(int node) {\n\t\tint val = color[node];\n\t\tif (vis[node]) {\n\t\t\tif (--cnt[val] == 0) {\n\t\t\t\tkind--;\n\t\t\t}\n\t\t} else {\n\t\t\tif (++cnt[val] == 1) {\n\t\t\t\tkind++;\n\t\t\t}\n\t\t}\n\t\tvis[node] = !vis[node];\n\t}\n\n\tpublic static void compute() {\n\t\tint winl = 1, winr = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint jobl = query[i][0];\n\t\t\tint jobr = query[i][1];\n\t\t\tint lca = query[i][2];\n\t\t\tint id = query[i][3];\n\t\t\twhile (winl > jobl) {\n\t\t\t\tinvert(seg[--winl]);\n\t\t\t}\n\t\t\twhile (winr < jobr) {\n\t\t\t\tinvert(seg[++winr]);\n\t\t\t}\n\t\t\twhile (winl < jobl) {\n\t\t\t\tinvert(seg[winl++]);\n\t\t\t}\n\t\t\twhile (winr > jobr) {\n\t\t\t\tinvert(seg[winr--]);\n\t\t\t}\n\t\t\tif (lca > 0) {\n\t\t\t\tinvert(lca);\n\t\t\t}\n\t\t\tans[id] = kind;\n\t\t\tif (lca > 0) {\n\t\t\t\tinvert(lca);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = color[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\tcntv = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[cntv] != sorted[i]) {\n\t\t\t\tsorted[++cntv] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcolor[i] = kth(color[i]);\n\t\t}\n\t\t// 括号序列分块\n\t\tint blen = (int) Math.sqrt(cntd);\n\t\tfor (int i = 1; i <= cntd; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tArrays.sort(query, 1, m + 1, new QueryCmp());\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcolor[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs(1, 0);\n\t\tfor (int i = 1, u, v, uvlca; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (st[v] < st[u]) {\n\t\t\t\tint tmp = u;\n\t\t\t\tu = v;\n\t\t\t\tv = tmp;\n\t\t\t}\n\t\t\tuvlca = lca(u, v);\n\t\t\tif (u == uvlca) {\n\t\t\t\tquery[i][0] = st[u];\n\t\t\t\tquery[i][1] = st[v];\n\t\t\t\tquery[i][2] = 0;\n\t\t\t} else {\n\t\t\t\tquery[i][0] = ed[u];\n\t\t\t\tquery[i][1] = st[v];\n\t\t\t\tquery[i][2] = uvlca;\n\t\t\t}\n\t\t\tquery[i][3] = i;\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_MoOnTree2.java`\n\n```java\npackage class177;\n\n// 树上莫队入门题，C++版\n// 一共有n个节点，每个节点给定颜色值，给定n-1条边，所有节点连成一棵树\n// 一共有m条查询，格式 u v : 打印点u到点v的简单路径上，有几种不同的颜色\n// 1 <= n <= 4 * 10^4\n// 1 <= m <= 10^5\n// 1 <= 颜色值 <= 2 * 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/SP10707\n// 测试链接 : https://www.spoj.com/problems/COT2/\n// 如下实现是C++的版本，C+