   }\n//    dfs(1, 0, "");\n//    cin >> m;\n//    while (m--) {\n//        int u, v;\n//        string s;\n//        cin >> u >> v >> s;\n//        cout << compute(u, v, s) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_PathDfnXor1.java`\n\n```java\npackage class159;\n\n// 路径和子树的异或，java版\n// 一共有n个节点，n-1条边，组成一棵树，1号节点为树头，每个节点给定点权\n// 一共有m条查询，每条查询是如下两种类型中的一种\n// 1 x y   : 以x为头的子树中任选一个值，希望异或y之后的值最大，打印最大值\n// 2 x y z : 节点x到节点y的路径中任选一个值，希望异或z之后的值最大，打印最大值\n// 2 <= n、m <= 10^5\n// 1 <= 点权、z < 2^30\n// 测试链接 : https://www.luogu.com.cn/problem/P4592\n// java实现的逻辑一定是正确的，但是通过不了\n// 因为这道题根据C++的运行空间，制定通过标准，根本没考虑java的用户\n// 想通过用C++实现，本节课Code03_PathDfnXor2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_PathDfnXor1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXT = MAXN * 62;\n\n\tpublic static int MAXP = 16;\n\n\tpublic static int BIT = 29;\n\n\tpublic static int n, m;\n\n\t// 每个节点的点权\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\t// 链式前向星的边的计数\n\tpublic static int cntg = 0;\n\n\t// 树上dfs求节点深度\n\tpublic static int[] deep = new int[MAXN];\n\n\t// 树上dfs求子树大小\n\tpublic static int[] size = new int[MAXN];\n\n\t// 树上dfs求st表\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\t// 树上dfs求每个节点的dfn序号\n\tpublic static int[] dfn = new int[MAXN];\n\n\t// dfn序号计数\n\tpublic static int cntd = 0;\n\n\t// 1类型的可持久化01Trie，根据dfn序号的次序建树\n\tpublic static int[] root1 = new int[MAXN];\n\n\t// 2类型的可持久化01Trie，根据父节点的版本建新树\n\tpublic static int[] root2 = new int[MAXN];\n\n\t// 1类型和2类型都可以用这个tree结构\n\tpublic static int[][] tree = new int[MAXT][2];\n\n\t// 1类型和2类型都可以用这个pass数组\n\tpublic static int[] pass = new int[MAXT];\n\n\t// 1类型和2类型一起的节点计数\n\tpublic static int cntt = 0;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int insert(int num, int i) {\n\t\tint rt = ++cntt;\n\t\ttree[rt][0] = tree[i][0];\n\t\ttree[rt][1] = tree[i][1];\n\t\tpass[rt] = pass[i] + 1;\n\t\tfor (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\ti = tree[i][path];\n\t\t\tcur = ++cntt;\n\t\t\ttree[cur][0] = tree[i][0];\n\t\t\ttree[cur][1] = tree[i][1];\n\t\t\tpass[cur] = pass[i] + 1;\n\t\t\ttree[pre][path] = cur;\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(int num, int u, int v) {\n\t\tint ans = 0;\n\t\tfor (int b = BIT, path, best; b >= 0; b--) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\tbest = path ^ 1;\n\t\t\tif (pass[tree[v][best]] > pass[tree[u][best]]) {\n\t\t\t\tans += 1 << b;\n\t\t\t\tu = tree[u][best];\n\t\t\t\tv = tree[v][best];\n\t\t\t} else {\n\t\t\t\tu = tree[u][path];\n\t\t\t\tv = tree[v][path];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 按道理说dfs1应该改成迭代版，防止递归爆栈\n\t// 不过本题给定的空间很小，java版怎么也无法通过，索性不改了\n\t// 有兴趣的同学可以看一下，讲解118，详解了树上dfs从递归版改迭代版\n\tpublic static void dfs1(int u, int fa) {\n\t\tdeep[u] = deep[fa] + 1;\n\t\tsize[u] = 1;\n\t\tstjump[u][0] = fa;\n\t\tdfn[u] = ++cntd;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = next[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsize[u] += size[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 按道理说dfs2应该改成迭代版，防止递归爆栈\n\t// 不过本题给定的空间很小，java版怎么也无法通过，索性不改了\n\t// 有兴趣的同学可以看一下，讲解118，详解了树上dfs从递归版改迭代版\n\tpublic static void dfs2(int u, int fa) {\n\t\troot1[dfn[u]] = insert(arr[u], root1[dfn[u] - 1]);\n\t\troot2[u] = insert(arr[u], root2[fa]);\n\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\tif (to[ei] != fa) {\n\t\t\t\tdfs2(to[ei], u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (deep[a] < deep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (deep[stjump[a][p]] >= deep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ty = (int) in.nval;\n\t\t\tif (op == 1) {\n\t\t\t\tout.println(query(y, root1[dfn[x] - 1], root1[dfn[x] + size[x] - 1]));\n\t\t\t} else {\n\t\t\t\tin.nextToken();\n\t\t\t\tz = (int) in.nval;\n\t\t\t\tint lcafa = stjump[lca(x, y)][0];\n\t\t\t\tint ans = Math.max(query(z, root2[lcafa], root2[x]), query(z, root2[lcafa], root2[y]));\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_PathDfnXor2.java`\n\n```java\npackage class159;\n\n// 路径和子树的异或，C++版\n// 一共有n个节点，n-1条边，组成一棵树，1号节点为树头，每个节点给定点权\n// 一共有m条查询，每条查询是如下两种类型中的一种\n// 1 x y   : 以x为头的子树中任选一个值，希望异或y之后的值最大，打印最大值\n// 2 x y z : 节点x到节点y的路径中任选一个值，希望异或z之后的值最大，打印最大值\n// 2 <= n、m <= 10^5\n// 1 <= 点权、z < 2^30\n// 测试链接 : https://www.luogu.com.cn/problem/P4592\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXT = MAXN * 62;\n//const int MAXP = 16;\n//const int BIT = 29;\n//int n, m;\n//int arr[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg = 0;\n//\n//int deep[MAXN];\n//int siz[MAXN];\n//int stjump[MAXN][MAXP];\n//int dfn[MAXN];\n//int cntd = 0;\n//\n//int root1[MAXN];\n//int root2[MAXN];\n//int tree[MAXT][2];\n//int pass[MAXT];\n//int cntt = 0;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//int insert(int num, int i) {\n//    int rt = ++cntt;\n//    tree[rt][0] = tree[i][0];\n//    tree[rt][1] = tree[i][1];\n//    pass[rt] = pass[i] + 1;\n//    for (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n//        path = (num >> b) & 1;\n//        i = tree[i][path];\n//        cur = ++cntt;\n//        tree[cur][0] = tree[i][0];\n//        tree[cur][1] = tree[i][1];\n//        pass[cur] = pass[i] + 1;\n//        tree[pre][path] = cur;\n//    }\n//    return rt;\n//}\n//\n//int query(int num, int u, int v) {\n//    int ans = 0;\n//    for (int b = BIT, path, best; b >= 0; b--) {\n//        path = (num >> b) & 1;\n//        best = path ^ 1;\n//        if (pass[tree[v][best]] > pass[tree[u][best]]) {\n//            ans += (1 << b);\n//            u = tree[u][best];\n//            v = tree[v][best];\n//        } else {\n//            u = tree[u][path];\n//            v = tree[v][path];\n//        }\n//    }\n//    return ans;\n//}\n//\n//void dfs1(int u, int fa) {\n//    deep[u] = deep[fa] + 1;\n//    siz[u] = 1;\n//    stjump[u][0] = fa;\n//    dfn[u] = ++cntd;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n//        v = to[ei];\n//        if (v != fa) {\n//            dfs1(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int fa) {\n//    root1[dfn[u]] = insert(arr[u], root1[dfn[u] - 1]);\n//    root2[u] = insert(arr[u], root2[fa]);\n//    for (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n//        if (to[ei] != fa) {\n//            dfs2(to[ei], u);\n//        }\n//    }\n//}\n//\n//int lca(int a, int b) {\n//    if (deep[a] < deep[b]) {\n//        swap(a, b);\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (deep[stjump[a][p]] >= deep[b]) {\n//            a = stjump[a][p];\n//        }\n//    }\n//    if (a == b) {\n//        return a;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (stjump[a][p] != stjump[b][p]) {\n//            a = stjump[a][p];\n//            b = stjump[b][p];\n//        }\n//    }\n//    return stjump[a][0];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 0);\n//    for (int i = 1, op, x, y, z; i <= m; i++) {\n//        cin >> op >> x >> y;\n//        if (op == 1) {\n//            cout << query(y, root1[dfn[x] - 1], root1[dfn[x] + siz[x] - 1]) << '\\n';\n//        } else {\n//            cin >> z;\n//            int lcafa = stjump[lca(x, y)][0];\n//            int ans = max(query(z, root2[lcafa], root2[x]), query(z, root2[lcafa], root2[y]));\n//            cout << ans << '\\n';\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Yummy1.java`\n\n```java\npackage class159;\n\n// 美味，java版\n// 给定一个长度为n的数组arr，一共有m条查询，查询格式如下\n// b x l r : 从arr[l..r]中选一个数字，希望b ^ (该数字 + x)的值最大，打印这个值\n// 1 <= n <= 2 * 10^5\n// 1 <= m <= 10^5\n// 0 <= arr[i]、b、x < 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3293\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_Yummy1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int MAXT = 4000001;\n\n\tpublic static int BIT = 18;\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 可持久化线段树需要\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int[] size = new int[MAXT];\n\n\tpublic static int cnt;\n\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cnt;\n\t\tsize[rt] = 0;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tleft[rt] = build(l, mid);\n\t\t\tright[rt] = build(mid + 1, r);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = ++cnt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tsize[rt] = size[i] + 1;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[rt] = insert(jobi, l, mid, left[rt]);\n\t\t\t} else {\n\t\t\t\tright[rt] = insert(jobi, mid + 1, r, right[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int u, int v) {\n\t\tif (jobr < l || jobl > r) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn size[v] - size[u];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, left[u], left[v]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, right[u], right[v]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tcnt = 0;\n\t\ts = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\ts = Math.max(s, arr[i]);\n\t\t}\n\t\troot[0] = build(0, s);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\troot[i] = insert(arr[i], 0, s, root[i - 1]);\n\t\t}\n\t}\n\n\tpublic static int compute(int b, int x, int l, int r) {\n\t\tint best = 0;\n\t\tfor (int i = BIT; i >= 0; i--) {\n\t\t\tif (((b >> i) & 1) == 1) {\n\t\t\t\tif (query(best - x, best + (1 << i) - 1 - x, 0, s, root[l - 1], root[r]) == 0) {\n\t\t\t\t\tbest += 1 << i;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (query(best + (1 << i) - x, best + (1 << (i + 1)) - 1 - x, 0, s, root[l - 1], root[r]) != 0) {\n\t\t\t\t\tbest += 1 << i;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn best ^ b;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, b, x, l, r; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tb = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tr = (int) in.nval;\n\t\t\tout.println(compute(b, x, l, r));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_Yummy2.java`\n\n```java\npackage class159;\n\n// 美味，C++版\n// 给定一个长度为n的数组arr，一共有m条查询，查询格式如下\n// b x l r : 从arr[l..r]中选一个数字，希望b ^ (该数字 + x)的值最大，打印这个值\n// 1 <= n <= 2 * 10^5\n// 1 <= m <= 10^5\n// 0 <= arr[i]、b、x < 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3293\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = 4000001;\n//const int BIT = 18;\n//int n, m, s;\n//int arr[MAXN];\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n/