o(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    prepare();\n//    for (int i = 1, b, x, l, r; i <= m; i++) {\n//        cin >> b >> x >> l >> r;\n//        cout << compute(b, x, l, r) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_ALO1.java`\n\n```java\npackage class159;\n\n// 生成能量密度最大的宝石，java版\n// 给定一个长度为n的数组arr，数组中没有重复数字\n// 你可以随意选择一个子数组，长度要求大于等于2，因为这样一来，子数组必存在次大值\n// 子数组的次大值 ^ 子数组中除了次大值之外随意选一个数字\n// 所能得到的最大结果，叫做子数组的能量密度\n// 那么必有某个子数组，拥有最大的能量密度，打印这个最大的能量密度\n// 2 <= n <= 5 * 10^4\n// 0 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4098\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_ALO1 {\n\n\tpublic static int MAXN = 50002;\n\n\tpublic static int MAXT = MAXN * 32;\n\n\tpublic static int BIT = 30;\n\n\tpublic static int n;\n\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[][] tree = new int[MAXT][2];\n\n\tpublic static int[] pass = new int[MAXT];\n\n\tpublic static int cnt;\n\n\tpublic static int[] last = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN];\n\n\tpublic static int insert(int num, int i) {\n\t\tint rt = ++cnt;\n\t\ttree[rt][0] = tree[i][0];\n\t\ttree[rt][1] = tree[i][1];\n\t\tpass[rt] = pass[i] + 1;\n\t\tfor (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\ti = tree[i][path];\n\t\t\tcur = ++cnt;\n\t\t\ttree[cur][0] = tree[i][0];\n\t\t\ttree[cur][1] = tree[i][1];\n\t\t\tpass[cur] = pass[i] + 1;\n\t\t\ttree[pre][path] = cur;\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(int num, int u, int v) {\n\t\tint ans = 0;\n\t\tfor (int b = BIT, path, best; b >= 0; b--) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\tbest = path ^ 1;\n\t\t\tif (pass[tree[v][best]] > pass[tree[u][best]]) {\n\t\t\t\tans += 1 << b;\n\t\t\t\tu = tree[u][best];\n\t\t\t\tv = tree[v][best];\n\t\t\t} else {\n\t\t\t\tu = tree[u][path];\n\t\t\t\tv = tree[v][path];\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tlast[0] = 0;\n\t\tnext[0] = 1;\n\t\tlast[n + 1] = n;\n\t\tnext[n + 1] = n + 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\troot[i] = insert(arr[i][1], root[i - 1]);\n\t\t\tlast[i] = i - 1;\n\t\t\tnext[i] = i + 1;\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, (a, b) -> a[1] - b[1]);\n\t}\n\n\tpublic static int compute() {\n\t\tint ans = 0;\n\t\tfor (int i = 1, index, value, l1, l2, r1, r2; i <= n; i++) {\n\t\t\tindex = arr[i][0];\n\t\t\tvalue = arr[i][1];\n\t\t\tl1 = last[index];\n\t\t\tl2 = last[l1];\n\t\t\tr1 = next[index];\n\t\t\tr2 = next[r1];\n\t\t\tif (l1 != 0) {\n\t\t\t\tans = Math.max(ans, query(value, root[l2], root[r1 - 1]));\n\t\t\t}\n\t\t\tif (r1 != n + 1) {\n\t\t\t\tans = Math.max(ans, query(value, root[l1], root[r2 - 1]));\n\t\t\t}\n\t\t\tnext[l1] = r1;\n\t\t\tlast[r1] = l1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = i;\n\t\t\tin.nextToken();\n\t\t\tarr[i][1] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code05_ALO2.java`\n\n```java\npackage class159;\n\n// 生成能量密度最大的宝石，C++版\n// 给定一个长度为n的数组arr，数组中没有重复数字\n// 你可以随意选择一个子数组，长度要求大于等于2，因为这样一来，子数组必存在次大值\n// 子数组的次大值 ^ 子数组中除了次大值之外随意选一个数字\n// 所能得到的最大结果，叫做子数组的能量密度\n// 那么必有某个子数组，拥有最大的能量密度，打印这个最大的能量密度\n// 2 <= n <= 5 * 10^4\n// 0 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P4098\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 50002;\n//const int MAXT = MAXN * 32;\n//const int BIT = 30;\n//int n;\n//vector<pair<int, int>> arr;\n//int root[MAXN];\n//int tree[MAXT][2];\n//int pass[MAXT];\n//int cnt;\n//int last[MAXN];\n//int nxt[MAXN];\n//\n//int insert(int num, int i) {\n//    int rt = ++cnt;\n//    tree[rt][0] = tree[i][0];\n//    tree[rt][1] = tree[i][1];\n//    pass[rt] = pass[i] + 1;\n//    for (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n//        path = (num >> b) & 1;\n//        i = tree[i][path];\n//        cur = ++cnt;\n//        tree[cur][0] = tree[i][0];\n//        tree[cur][1] = tree[i][1];\n//        pass[cur] = pass[i] + 1;\n//        tree[pre][path] = cur;\n//    }\n//    return rt;\n//}\n//\n//int query(int num, int u, int v) {\n//    int ans = 0;\n//    for (int b = BIT, path, best; b >= 0; b--) {\n//        path = (num >> b) & 1;\n//        best = path ^ 1;\n//        if (pass[tree[v][best]] > pass[tree[u][best]]) {\n//            ans += 1 << b;\n//            u = tree[u][best];\n//            v = tree[v][best];\n//        } else {\n//            u = tree[u][path];\n//            v = tree[v][path];\n//        }\n//    }\n//    return ans;\n//}\n//\n//void prepare() {\n//    last[0] = 0;\n//    nxt[0] = 1;\n//    last[n + 1] = n;\n//    nxt[n + 1] = n + 1;\n//    for (int i = 1; i <= n; i++) {\n//        root[i] = insert(arr[i].second, root[i - 1]);\n//        last[i] = i - 1;\n//        nxt[i] = i + 1;\n//    }\n//    sort(arr.begin() + 1, arr.end(), [](const pair<int, int>& a, const pair<int, int>& b) {\n//        return a.second < b.second;\n//    });\n//}\n//\n//int compute() {\n//    int ans = 0;\n//    for (int i = 1, index, value, l1, l2, r1, r2; i <= n; i++) {\n//        index = arr[i].first;\n//        value = arr[i].second;\n//        l1 = last[index];\n//        l2 = last[l1];\n//        r1 = nxt[index];\n//        r2 = nxt[r1];\n//        if (l1 != 0) {\n//            ans = max(ans, query(value, root[l2], root[r1 - 1]));\n//        }\n//        if (r1 != n + 1) {\n//            ans = max(ans, query(value, root[l1], root[r2 - 1]));\n//        }\n//        nxt[l1] = r1;\n//        last[r1] = l1;\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    arr.resize(n + 1);\n//    for (int i = 1; i <= n; i++) {\n//        arr[i].first = i;\n//        cin >> arr[i].second;\n//    }\n//    prepare();\n//    cout << compute() << "\\n";\n//    return 0;\n//}\n```\n\n### `Code06_XorOperation1.java`\n\n```java\npackage class159;\n\n// 异或运算，java版\n// 给定一个长度n的数组x，还有一个长度为m的数组y\n// 想象一个二维矩阵mat，数组x作为行，数组y作为列，mat[i][j] = x[i] ^ y[j]\n// 一共有p条查询，每条查询格式如下\n// xl xr yl yr k : 划定mat的范围是，行从xl~xr，列从yl~yr，打印其中第k大的值\n// 1 <= n <= 1000\n// 1 <= m <= 3 * 10^5\n// 1 <= p <= 500\n// 0 <= x[i]、y[i] < 2^31\n// 测试链接 : https://www.luogu.com.cn/problem/P5795\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_XorOperation1 {\n\n\tpublic static int MAXN = 300001;\n\n\tpublic static int MAXT = MAXN * 32;\n\n\tpublic static int BIT = 30;\n\n\tpublic static int n, m, p;\n\n\tpublic static int[] x = new int[MAXN];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[][] tree = new int[MAXT][2];\n\n\tpublic static int[] pass = new int[MAXT];\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[][] xroad = new int[MAXN][2];\n\n\tpublic static int insert(int num, int i) {\n\t\tint rt = ++cnt;\n\t\ttree[rt][0] = tree[i][0];\n\t\ttree[rt][1] = tree[i][1];\n\t\tpass[rt] = pass[i] + 1;\n\t\tfor (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\ti = tree[i][path];\n\t\t\tcur = ++cnt;\n\t\t\ttree[cur][0] = tree[i][0];\n\t\t\ttree[cur][1] = tree[i][1];\n\t\t\tpass[cur] = pass[i] + 1;\n\t\t\ttree[pre][path] = cur;\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int maxKth(int xl, int xr, int yl, int yr, int k) {\n\t\t// 基于哪两个节点的pass值查询，一开始x[xl...xr]每个数字，都是一样的\n\t\tfor (int i = xl; i <= xr; i++) {\n\t\t\txroad[i][0] = root[yl - 1];\n\t\t\txroad[i][1] = root[yr];\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int b = BIT, path, best, sum; b >= 0; b--) {\n\t\t\tsum = 0;\n\t\t\t// 统计x[xl...xr]范围上\n\t\t\t// 每个数字 ^ y[yl...yr]任意一个数字，在第b位上能取得1的结果，有多少个\n\t\t\t// 结果数量累加起来\n\t\t\tfor (int i = xl; i <= xr; i++) {\n\t\t\t\tpath = (x[i] >> b) & 1;\n\t\t\t\tbest = path ^ 1;\n\t\t\t\tsum += pass[tree[xroad[i][1]][best]] - pass[tree[xroad[i][0]][best]];\n\t\t\t}\n\t\t\t// 如果sum >= k\n\t\t\t// 说明x[xl...xr]对应y[yl...yr]，第k大的异或结果，在第b位上能是1\n\t\t\t// 如果sum < k\n\t\t\t// 说明x[xl...xr]对应y[yl...yr]，第k大的异或结果，在第b位上只能是0\n\t\t\t// x[xl...xr]每个数字，都有自己专属的跳转，要记录好！\n\t\t\tfor (int i = xl; i <= xr; i++) {\n\t\t\t\tpath = (x[i] >> b) & 1;\n\t\t\t\tbest = path ^ 1;\n\t\t\t\tif (sum >= k) {\n\t\t\t\t\txroad[i][0] = tree[xroad[i][0]][best];\n\t\t\t\t\txroad[i][1] = tree[xroad[i][1]][best];\n\t\t\t\t} else {\n\t\t\t\t\txroad[i][0] = tree[xroad[i][0]][path];\n\t\t\t\t\txroad[i][1] = tree[xroad[i][1]][path];\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (sum >= k) {\n\t\t\t\tans += 1 << b;\n\t\t\t} else {\n\t\t\t\tk -= sum;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tx[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, yi; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tyi = (int) in.nval;\n\t\t\troot[i] = insert(yi, root[i - 1]);\n\t\t}\n\t\tin.nextToken();\n\t\tp = (int) in.nval;\n\t\tfor (int i = 1, xl, xr, yl, yr, k; i <= p; i++) {\n\t\t\tin.nextToken();\n\t\t\txl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\txr = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tyl = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tyr = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t\tout.println(maxKth(xl, xr, yl, yr, k));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code06_XorOperation2.java`\n\n```java\npackage class159;\n\n// 异或运算，C++版\n// 给定一个长度n的数组x，还有一个长度为m的数组y\n// 想象一个二维矩阵mat，数组x作为行，数组y作为列，mat[i][j] = x[i] ^ y[j]\n// 一共有p条查询，每条查询格式如下\n// xl xr yl yr k : 划定mat的范围是，行从xl~xr，列从yl~yr，打印其中第k大的值\n// 1 <= n <= 1000\n// 1 <= m <= 3 * 10^5\n// 1 <= p <= 500\n// 0 <= x[i]、y[i] < 2^31\n// 测试链接 : https://www.luogu.com.cn/problem/P5795\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 300001;\n//const int MAXT = MAXN * 32;\n//const int BIT = 30;\n//int n, m, p;\n//int x[MAXN];\n//int root[MAXN];\n//int tree[MAXT][2];\n//int pass[MAXT];\n//int cnt = 0;\n//int xroad[MAXN][2];\n//\n//int insert(int num, int i) {\n//    int rt = ++cnt;\n//    tree[rt][0] = tree[i][0];\n//    tree[rt][1] = tree[i][1];\n//    pass[rt] = pass[i] + 1;\n//    for (int b = BIT, path, pre = rt, cur; b >= 0; b--, pre = cur) {\n//        path = (num >> b) & 1;\n//        i = tree[i][path];\n//        cur = ++cnt;\n//        tree[cur][0] = tree[i][0];\n//        tree[cur][1] = tree[i][1];\n//        pass[cur] = pass[i] + 1;\n//        tree[pre][path] = cur;\n//    }\n//    return rt;\n//}\n//\n//int maxKth(int xl, int xr, int yl, int yr, int k) {\n//    for (int i = xl; i <= xr; i++) {\n//        xroad[i][0] = root[yl - 1];\n//        xroad[i][1] = root[yr];\n//    }\n//    int ans = 0;\n//    for (int b = BIT, path, best, sum; b >= 0; b--) {\n//        sum = 0;\n//        for (int i = xl; i <= xr; i++) {\n//            path = (x[i] >> b) & 1;\n//            best = path ^ 1;\n//            sum += pass[tree[xroad[i][1]][best]] - pass[tree[xroad[i][0]][best]];\n//        }\n//        for (int i = xl; i <= xr; i++) {\n//            path = (x[i] >> b) & 1;\n//            best = path ^ 1;\n//            if (sum >= k) {\n//                xroad[i][0] = tree[xroad[i][0]][best];\n//                xroad[i][1] = tree[xroad[i][1]][best];\n//            } else {\n//                xroad[i][0] = tree[xroad[i][0]][path];\n//                xroad[i][1] = tree[xroad[i][1]][path];\n//            }\n//        }\n//        if (sum >= k) {\n//            ans += 1 << b;\n//        } else {\n//            k -= sum;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> x[i];\n//    }\n//    for (int i = 1, yi; i <= m; i++) {\n//        cin >> yi;\n//        root[i] = insert(yi, root[i - 1]);\n//    }\n//    cin >> p;\n//    for (int i = 1, xl, xr, yl, yr, k; i <= p; i++) {\n//        cin >> xl >> xr >> yl >> yr >> k;\n//        cout << maxKth(xl, xr, yl, yr, k) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_Friends1.java`\n\n```java\npackage class159;\n\n// 前m大两两异或值的和，java版\n// 本题只用到了经典前缀树，没有用到可持久化前缀树\n// 给定一个长度为n的数组arr，下标1~n\n// 你可以随意选两个不同位置的数字进行异或，得到两两异或值，顺序不同的话，算做一个两两异或值\n// 那么，两两异或值，就有第1大、第2大...\n// 返回前k大两两异或值的累加和，答案对1000000007取模\n// 1 <= n <= 5 * 10^4\n// 0 <= k <= n * (n-1) / 2\n// 0 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF241B\n// 测试链接 : https://codeforces.com/problemset/problem/241/B\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code07_Friends1 {\n\n\tpublic static int MAXN = 50001;\n\n\tpublic static int MAXT = MAXN * 20;\n\n\tpublic static int BIT = 30;\n\n\tpublic static int MOD = 1000000007;\n\n\tpublic static int INV2 = 500000004;\n\n\tpublic static int n, k;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[][] tree = new int[MAXT][2];\n\n\tpublic static int[] pass = new int[MAXT];\n\n\tpublic static int cnt = 1;\n\n\tpublic static int[][] sum = new int[MAXT][BIT + 1];\n\n\tpublic static void insert(int num) {\n\t\tint cur = 1;\n\t\tpass[1]++;\n\t\tfor (int b = BIT, path; b >= 0; b--) {\n\t\t\tpath = (num >> b) & 1;\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\ttree[cur][path] = ++cnt;\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t\tpass[cur]++;\n\t\t}\n\t}\n\n\tpublic static void dfs(int i, int h, int s) {\n\t\tif (i == 0) {\n\t\t\treturn;\n\t\t}\n\t\tif (h == 0) {\n\t\t\tfor (int j = 0; j <= BIT; j++) {\n\t\t\t\tif (((s >> j) & 1) == 1) {\n\t\t\t\t\tsum[i][j] = pass[i];\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tdfs(tree[i][0], h - 1, s);\n\t\t\tdfs(tree[i][1], h - 1, s | (1 << (h - 1)));\n\t\t\tfor (int j = 0; j <= BIT; j++) {\n\t\t\t\tsum[i][j] = sum[tree[i][0]][j] + sum[tree[i][1]][j];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long moreEqual(int x) {\n\t\tlong ans = 0;\n\t\tfor (int i = 1, num, cur; i <= n; i++) {\n\t\t\tnum = arr[i];\n\t\t\tcur = 1;\n\t\t\tfor (int b = BIT, path, best, xpath; b >= 0; b--) {\n\t\t\t\tpath = (num >> b) & 1;\n\t\t\t\tbest = path ^ 1;\n\t\t\t\txpath = (x >> b) & 1;\n\t\t\t\tif (xpath == 0) {\n\t\t\t\t\tans += pass[tree[cur][best]];\n\t\t\t\t\tcur = tree[cur][path];\n\t\t\t\t} else {\n\t\t\t\t\tcur = tree[cur][best];\n\t\t\t\t}\n\t\t\t\tif (cur == 0) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans += pass[cur];\n\t\t}\n\t\tif (x == 0) {\n\t\t\tans -= n;\n\t\t}\n\t\treturn ans / 2;\n\t}\n\n\tpublic static int maxKth() {\n\t\tint l = 0, r = 1 << BIT, m;\n\t\tint ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) / 2;\n\t\t\tif (moreEqual(m) >= k) {\n\t\t\t\tans = m;\n\t\t\t\tl = m + 1;\n\t\t\t} else {\n\t\t\t\tr = m - 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long compute() {\n\t\tint kth = maxKth();\n\t\tlong ans = 0;\n\t\tfor (int i = 1, cur; i <= n; i++) {\n\t\t\tcur = 1;\n\t\t\tfor (int b = BIT, path, best, kpath; b >= 0; b--) {\n\t\t\t\tpath = (arr[i] >> b) & 1;\n\t\t\t\tbest = path ^ 1;\n\t\t\t\tkpath = (kth >> b) & 1;\n\t\t\t\tif (kpath == 0) {\n\t\t\t\t\tfor (int j = 0; j <= BIT; j++) {\n\t\t\t\t\t\tif (((arr[i] >> j) & 1) == 1) {\n\t\t\t\t\t\t\tans = (ans + ((long) pass[tree[cur][best]] - sum[tree[cur][best]][j]) * (1L << j)) % MOD;\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tans = (ans + (long) sum[tree[cur][best]][j] * (1L << j)) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tcur = tree[cur][path];\n\t\t\t\t} else {\n\t\t\t\t\tcur = tree[cur][best];\n\t\t\t\t}\n\t\t\t\tif (cur == 0) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans = (ans + (long) pass[cur] * kth) % MOD;\n\t\t}\n\t\tans = ans * INV2 % MOD;\n\t\tans = ((ans - (moreEqual(kth) - k) * kth % MOD) % MOD + MOD) % MOD;\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tinsert(arr[i]);\n\t\t}\n\t\tdfs(tree[1][0], BIT, 0);\n\t\tdfs(tree[1][1], BIT, 1 << BIT);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tif (k == 0) {\n\t\t\tout.println(0);\n\t\t} else {\n\t\t\tprepare();\n\t\t\tout.println(compute());\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code07_Friends2.java`\n\n```java\npackage class159;\n\n// 前m大两两异或值的和，C++版\n// 本题只用到了经典前缀树，没有用到可持久化前缀树\n// 给定一个长度为n的数组arr，下标1~n\n// 你可以随意选两个不同位置的数字进行异或，得到两两异或值，顺序不同的话，算做一个两两异或值\n// 那么，两两异或值，就有第1大、第2大...\n// 返回前k大两两异或值的累加和，答案对1000000007取模\n// 1 <= n <= 5 * 10^4\n// 0 <= k <= n * (n-1) / 2\n// 0 <= arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF241B\n// 测试链接 : https://codeforces.com/problemset/problem/241/B\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 50001;\n//const int MAXT = MAXN * 20;\n//const int BIT = 30;\n//const int MOD = 1000000007;\n//const int INV2 = 500000004;\n//int n, k;\n//int arr[MAXN];\n//int tree[MAXT][2];\n//int pass[MAXT];\n//int cnt = 1;\n//int sum[MAXT][BIT + 1];\n//\n//void insert(int num) {\n//    int cur = 1;\n//    pass[1]++;\n//    for (int b = BIT; b >= 0; b--) {\n//        int path = (num >> b) & 1;\n//        if (!tree[cur][path]) {\n//            tree[cur][path] = ++cnt;\n//        }\n//        cur = tree[cur][path];\n//        pass[cur]++;\n//    }\n//}\n//\n//void dfs(int i, int h, int s) {\n//    if (!i) {\n//        return;\n//    }\n//    if (!h) {\n//        for (int j = 0; j <= BIT; j++) {\n//            if ((s >> j) & 1) {\n//                sum[i][j] = pass[i];\n//            }\n//        }\n//    } else {\n//        dfs(tree[i][0], h - 1, s);\n//        dfs(tree[i][1], h - 1, s | (1 << (h - 1)));\n//        for (int j = 0; j <= BIT; j++) {\n//            sum[i][j] = sum[tree[i][0]][j] + sum[tree[i][1]][j];\n//        }\n//    }\n//}\n//\n//long long moreEqual(int x) {\n//    long long ans = 0;\n//    for (int i = 1; i <= n; i++) {\n//        int num = arr[i];\n//        int cur = 1;\n//        for (int b = BIT; b >= 0; b--) {\n//            int path = (num >> b) & 1;\n//            int best = path ^ 1;\n//            int xpath = (x >> b) & 1;\n//            if (!xpath) {\n//                ans += pass[tree[cur][best]];\n//                cur = tree[cur][path];\n//            } else {\n//                cur = tree[cur][best];\n//            }\n//            if (!cur) {\n//                break;\n//            }\n//        }\n//        ans += pass[cur];\n//    }\n//    if (x == 0) {\n//        ans -= n;\n//    }\n//    return ans / 2;\n//}\n//\n//int maxKth() {\n//    int l = 0, r = 1 << BIT, ans = 0;\n//    while (l <= r) {\n//        int m = (l + r) >> 1;\n//        if (moreEqual(m) >= k) {\n//            ans = m;\n//            l = m + 1;\n//        } else {\n//            r = m - 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//long long compute() {\n//    int kth = maxKth();\n//    long long ans = 0;\n//    for (int i = 1, cur; i <= n; i++) {\n//        cur = 1;\n//        for (int b = BIT; b >= 0; b--) {\n//            int path = (arr[i] >> b) & 1;\n//            int best = path ^ 1;\n//            int kpath = (kth >> b) & 1;\n//            if (!kpath) {\n//                if (tree[cur][best]) {\n//                    for (int j = 0; j <= BIT; j++) {\n//                        if ((arr[i] >> j) & 1) {\n//                            ans = (ans + ((long long)pass[tree[cur][best]] - sum[tree[cur][best]][j]) * (1LL << j)) % MOD;\n//                        } else {\n//                            ans = (ans + ((long long)sum[tree[cur][best]][j]) * (1LL << j)) % MOD;\n//                        }\n//                    }\n//                }\n//                cur = tree[cur][path];\n//            } else {\n//                cur = tree[cur][best];\n//            }\n//            if (!cur) {\n//                break;\n//            }\n//        }\n//        if (cur) {\n//            ans = (ans + (long long)pass[cur] * kth) % MOD;\n//        }\n//    }\n//    ans = ans * INV2 % MOD;    \n//    ans = ((ans - ((moreEqual(kth) - k) * kth) % MOD) % MOD + MOD) % MOD;\n//    return ans;\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        insert(arr[i]);\n//    }\n//    dfs(tree[1][0], BIT, 0);\n//    d