t\t\tif (start[i] == end[i]) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tif (start[i] != end[i]) {\n\t\t\t\t\treturn 0;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn 1;\n\t}\n\n\tpublic static int compute() {\n\t\tstartStatus = endStatus = 0;\n\t\tfor (int j = 0; j < m; j++) {\n\t\t\tstartStatus = set(startStatus, j, start[j]);\n\t\t\tendStatus = set(endStatus, j, end[j]);\n\t\t}\n\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\tprepare[s] = different(s, endStatus) ? 1 : 0;\n\t\t}\n\t\tfor (int i = n - 2; i >= 1; i--) {\n\t\t\t// j == m\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tdp[m][s] = prepare[s];\n\t\t\t}\n\t\t\t// 普通位置\n\t\t\tfor (int j = m - 1; j >= 0; j--) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tint ans = 0;\n\t\t\t\t\tfor (int color = 0; color < k; color++) {\n\t\t\t\t\t\tif ((j == 0 || get(s, j - 1) != color) && get(s, j) != color) {\n\t\t\t\t\t\t\tans = (ans + dp[j + 1][set(s, j, color)]) % MOD;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tdp[j][s] = ans;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 设置prepare\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tprepare[s] = dp[0][s];\n\t\t\t}\n\t\t}\n\t\treturn dp[0][startStatus];\n\t}\n\n\tpublic static boolean different(int a, int b) {\n\t\tfor (int j = 0; j < m; j++) {\n\t\t\tif (get(a, j) == get(b, j)) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> (j << 1)) & 3;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn s & (~(3 << (j << 1))) | (v << (j << 1));\n\t}\n\n}\n\n```\n\n### `Code04_KingsFighting1.java`\n\n```java\npackage class125;\n\n// 摆放国王的方法数(轮廓线dp)\n// 给定两个参数n和k，表示n*n的区域内要摆放k个国王\n// 国王可以攻击临近的8个方向，所以摆放时不能让任何两个国王打架\n// 返回摆放的方法数\n// 1 <= n <= 9\n// 1 <= k <= n*n\n// 测试链接 : https://www.luogu.com.cn/problem/P1896\n// 提交以下的code，提交时请把类名改成"Main"，有可能全部通过\n// 不过更推荐写出空间压缩的版本\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_KingsFighting1 {\n\n\tpublic static int MAXN = 9;\n\n\tpublic static int MAXK = 82;\n\n\tpublic static long[][][][][] dp = new long[MAXN][MAXN][1 << MAXN][2][MAXK];\n\n\tpublic static int n, kings, maxs;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tkings = (int) in.nval;\n\t\tmaxs = 1 << n;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tfor (int leftup = 0; leftup <= 1; leftup++) {\n\t\t\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\t\t\tdp[i][j][s][leftup][k] = -1;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn f(0, 0, 0, 0, kings);\n\t}\n\n\t// 当前来到i行j列\n\t// i-1行中，[j..m-1]列有没有摆放国王，用s[j..m-1]号格子表示\n\t// i行中，[0..j-1]列有没有摆放国王，用s[0..j-1]号格子表示\n\t// s表示轮廓线的状况\n\t// (i-1, j-1)位置，也就是左上角，有没有摆放国王，用leftup表示\n\t// 国王还剩下k个需要去摆放\n\t// 返回有多少种摆放方法\n\tpublic static long f(int i, int j, int s, int leftup, int k) {\n\t\tif (i == n) {\n\t\t\treturn k == 0 ? 1 : 0;\n\t\t}\n\t\tif (j == n) {\n\t\t\treturn f(i + 1, 0, s, 0, k);\n\t\t}\n\t\tif (dp[i][j][s][leftup][k] != -1) {\n\t\t\treturn dp[i][j][s][leftup][k];\n\t\t}\n\t\tint left = j == 0 ? 0 : get(s, j - 1);\n\t\tint up = get(s, j);\n\t\tint rightup = get(s, j + 1);\n\t\tlong ans = f(i, j + 1, set(s, j, 0), up, k);\n\t\tif (k > 0 && left == 0 && leftup == 0 && up == 0 && rightup == 0) {\n\t\t\tans += f(i, j + 1, set(s, j, 1), up, k - 1);\n\t\t}\n\t\tdp[i][j][s][leftup][k] = ans;\n\t\treturn ans;\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> j) & 1;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn v == 0 ? (s & (~(1 << j))) : (s | (1 << j));\n\t}\n\n}\n\n```\n\n### `Code04_KingsFighting2.java`\n\n```java\npackage class125;\n\n// 摆放国王的方法数(轮廓线dp+空间压缩)\n// 给定两个参数n和k，表示n*n的区域内要摆放k个国王\n// 国王可以攻击临近的8个方向，所以摆放时不能让任何两个国王打架\n// 返回摆放的方法数\n// 1 <= n <= 9\n// 1 <= k <= n*n\n// 测试链接 : https://www.luogu.com.cn/problem/P1896\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有用例\n// 空间压缩的版本一定稳定通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_KingsFighting2 {\n\n\tpublic static int MAXN = 9;\n\n\tpublic static int MAXK = 82;\n\n\tpublic static long[][][][] dp = new long[MAXN + 1][1 << MAXN][2][MAXK];\n\n\tpublic static long[][] prepare = new long[1 << MAXN][MAXK];\n\n\tpublic static int n, kings, maxs;\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tkings = (int) in.nval;\n\t\tmaxs = 1 << n;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n\tpublic static long compute() {\n\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\tprepare[s][k] = k == 0 ? 1 : 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = n - 1; i >= 0; i--) {\n\t\t\t// j == n\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\tdp[n][s][0][k] = prepare[s][k];\n\t\t\t\t\tdp[n][s][1][k] = prepare[s][k];\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 普通位置\n\t\t\tfor (int j = n - 1; j >= 0; j--) {\n\t\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\t\tfor (int leftup = 0; leftup <= 1; leftup++) {\n\t\t\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\t\t\tint left = j == 0 ? 0 : get(s, j - 1);\n\t\t\t\t\t\t\tint up = get(s, j);\n\t\t\t\t\t\t\tint rightup = get(s, j + 1);\n\t\t\t\t\t\t\tlong ans = dp[j + 1][set(s, j, 0)][up][k];\n\t\t\t\t\t\t\tif (k > 0 && left == 0 && leftup == 0 && up == 0 && rightup == 0) {\n\t\t\t\t\t\t\t\tans += dp[j + 1][set(s, j, 1)][up][k - 1];\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tdp[j][s][leftup][k] = ans;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 设置prepare\n\t\t\tfor (int s = 0; s < maxs; s++) {\n\t\t\t\tfor (int k = 0; k <= kings; k++) {\n\t\t\t\t\tprepare[s][k] = dp[0][s][0][k];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[0][0][0][kings];\n\t}\n\n\tpublic static int get(int s, int j) {\n\t\treturn (s >> j) & 1;\n\t}\n\n\tpublic static int set(int s, int j, int v) {\n\t\treturn v == 0 ? (s & (~(1 << j))) : (s | (1 << j));\n\t}\n\n}\n\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
5f55b9e0-ed13-4f5b-99d8-f75f3b1f0d18	67ae3d3c-d9ba-476e-be7d-4390d0131663	deep	01分数规划	# 138. 01分数规划\n\n> 难度标签：**扩展** ｜ 主题：**基础** ｜ 来源：左程云《算法讲解》第 138 讲\n\n## 第 1 页：01分数规划\n\n左程云\n前置知识\n讲解051 - 二分答案法，理解01分数规划需要\n讲解059 - 链式前向星建图、图的遍历，本节课题目3、题目4、题目5需要\n讲解061 - 最小生成树prim算法，本节课题目3需要\n讲解073 - 01背包，本节课题目2需要\n讲解079 - 树型dp-下，其中的题目5选课问题，重点讲的最优解，本节课题目5需要\n01分数规划本身是一个比较简单的数学模型，理解二分答案法就能理解\n01分数规划可以和非常多的内容结合，所以推荐的前置知识比较多，本节课会讲5道题\n01分数规划还可以和网络流、费用流结合，这两部分内容会在【挺难】阶段讲述，本节课不涉及相关题目\n01分数规划与更多内容结合的题目，有兴趣的同学可以自行练习\n\n## 第 2 页：01分数规划\n\n左程云\n01分数规划最简化的问题\n给定n个数据，每个数据有(a, b)两个值，并且没有负数\n(a1, b1)、(a2, b2)、(a3, b3)、.. (an, bn)\n其中选出k个数据，希望让 : k个a的和 / k个b的和，这个比值尽量大，返回最大的比值\n错误的贪心：选择a/b最大的前k个数据，反例：(5, 5)  (0, 1)  (2, 6)\n暴力方法 : 2的n次方，每个数据都枚举要和不要两种选择\n计算机里关于小数的精度是有限的 或者 具体题目要求返回的比值精度也是规定好的\n那么此时没有必要精确求解，可以用二分答案法来逼近求解，保证规定精度内正确即可\n01分数规划的核心：\n数据转化成结余表达式的形式，当确定一个比值x，就在最优决策下，计算结余和\n最终希望获得在最优决策下，当结余和最接近0时，x的值\n手段：利用单调性进行二分\n\n## 第 3 页：01分数规划\n\n左程云\n二分答案法找到最大比值的过程\n数据这么来看 :\na1 - x * b1 = 结余1\na2 - x * b2 = 结余2\na3 - x * b3 = 结余3\n..\n规定精度的最小单位sml，找到x的可能范围[l, r]，然后二分逻辑如下：\n首先令x = (l + r) / 2，计算每一个结余，然后选出结余最大的前k名，然后加起来看看累加和\n1) 如果 结余累加和 >= 0，答案更新成此时的x，然后去右侧二分，范围变成[x + sml, r]\n2) 如果 结余累加和 <  0，答案不更新，然后去左侧二分，范围变成[l, x - sml]\n3) 如果发现范围[l,r]的大小 <= sml，过程停止，返回答案即可\n课上重点图解，时间复杂度O(n * logn * logv)\n\n## 第 4 页：01分数规划\n\n左程云\n题目1\n01分数规划模版题\n给定n个数据，每个数据有(a, b)两个值，都为整数，并且都是非负的\n请舍弃掉k个数据，希望让剩下数据做到，所有a的和 / 所有b的和，这个比值尽量大\n如果剩下数据所有b的和为0，认为无意义\n最后，将该比值 * 100，小数部分四舍五入的整数结果返回\n1 <= n <= 100\n0 <= a、b <= 10^9\n测试链接 : https://www.luogu.com.cn/problem/P10505\n测试链接 : http://poj.org/problem?id=2976\n\n## 第 5 页：01分数规划\n\n左程云\n题目2\n牛群的才艺展示\n一共有n只牛，每只牛有重量和才艺两个属性值\n要求一定要选若干只牛，使得总重量不少于w，并且选出的牛，希望让\n才艺的和 / 重量的和，这个比值尽量大\n返回该比值 * 1000的整数结果，小数部分舍弃\n1 <= n <= 250\n1 <= w <= 1000\n1 <= 牛的重量 <= 10^6\n1 <= 牛的才艺 <= 10^3\n测试链接 : https://www.luogu.com.cn/problem/P4377\n01分数规划 + 01背包\n\n## 第 6 页：01分数规划\n\n左程云\n题目3\n最优比率生成树\n一共有n个村庄，每个村庄由(x, y, z)表示\n其中(x,y)代表村庄在二维地图中的位置，z代表其海拔高度\n任意两个村庄之间的距离就是二维地图中的欧式距离\n任意两个村庄之间的修路花费就是海拔差值的绝对值\n现在想把所有村庄连通起来，希望修路的条数尽量少，同时希望让\n总花费 / 总距离，这个比值尽量小，返回最小的比值是多少，结果保留小数点后3位其余部分舍弃\n2 <= n <= 10^3\n0 <= x、y <= 10^4\n0 <= z <= 10^7\n测试链接 : http://poj.org/problem?id=2728\n01分数规划 + 最小生成树\n\n## 第 7 页：01分数规划\n\n左程云\n题目4\n最小圈\n一共有n个节点，m条有向边，每条边有权值\n这个有向带权图中，可能有若干环，规定环的平均值为\n环中边的权值和 / 环中边的数量\n返回所有环的平均值中最小的平均值，结果保留小数点后8位，其余部分舍弃\n1 <= n <= 3000\n1 <= m <= 10000\n-10^7 <= 边权 <= 10^7\n测试链接 : https://www.luogu.com.cn/problem/P3199\n01分数规划 + 图上dfs判断负环\n\n## 第 8 页：01分数规划\n\n左程云\n题目5\n最佳团体\n给定一棵树，节点编号0~n，0号节点是整棵树的头\n编号1~n的节点，每个节点都有招募花费和战斗值，0号节点这两个值都是0\n给定每条边(a,b)，表示节点a的父节点是b，有些节点的父节点是0节点\n当招募了某个节点，那么该节点及其上方的所有祖先节点都需要招募\n除了0号节点之外，一共可以招募k个节点，希望让\n战斗值之和 / 招募花费之和，这个比值尽量大，答案只需保留三位小数，更大的精度舍弃\n1 <= k <= n <= 2500\n0 <= 招募花费、战斗值 <= 10^4\n测试链接 : https://www.luogu.com.cn/problem/P4322\n01分数规划 + 树型dp + dfn序 + 状态设计优化\n讲解079，题目5，选课问题，重点介绍的最优解，看了必会\n\n## 模板代码\n\n### `Code01_DroppingTests.java`\n\n```java\npackage class138;\n\n// 01分数规划模版题\n// 给定n个数据，每个数据有(a, b)两个值，都为整数，并且都是非负的\n// 请舍弃掉k个数据，希望让剩下数据做到，所有a的和 / 所有b的和，这个比值尽量大\n// 如果剩下数据所有b的和为0，认为无意义\n// 最后，将该比值 * 100，小数部分四舍五入的整数结果返回\n// 1 <= n <= 100\n// 0 <= a、b <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P10505\n// 测试链接 : http://poj.org/problem?id=2976\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Code01_DroppingTests {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double sml = 1e-6;\n\n\t// arr[i][0] = i号数据的a\n\t// arr[i][1] = i号数据的b\n\t// arr[i][2] = i号数据的结余，a - x * b\n\tpublic static double[][] arr = new double[MAXN][3];\n\n\tpublic static int n, k;\n\n\tpublic static boolean check(double x) {\n\t\t// x固定的情况下，得到所有数据的结余\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][2] = arr[i][0] - x * arr[i][1];\n\t\t}\n\t\t// 结余从大到小排序\n\t\tArrays.sort(arr, 1, n + 1, new MyComparator());\n\t\t// 最大k个结余的累加和\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tsum += arr[i][2];\n\t\t}\n\t\treturn sum >= 0;\n\t}\n\n\t// poj平台java版本较老，不支持Lambda表达式方式的比较器，需要自己定义\n\tpublic static class MyComparator implements Comparator<double[]> {\n\n\t\t@Override\n\t\tpublic int compare(double[] o1, double[] o2) {\n\t\t\treturn o1[2] >= o2[2] ? -1 : 1;\n\t\t}\n\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\twhile (n != 0 || k != 0) {\n\t\t\t// 题目要求舍弃掉k个，其实就是挑选n-k个\n\t\t\tk = n - k;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][0] = in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][1] = in.nval;\n\t\t\t}\n\t\t\tdouble l = 0, r = 0, x;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tr += arr[i][0];\n\t\t\t}\n\t\t\tdouble ans = 0;\n\t\t\twhile (l < r && r - l >= sml) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (check(x)) {\n\t\t\t\t\tans = x;\n\t\t\t\t\tl = x + sml;\n\t\t\t\t} else {\n\t\t\t\t\tr = x - sml;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println((int) (100 * (ans + 0.005)));\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code02_TalentShow.java`\n\n```java\npackage class138;\n\n// 牛群的才艺展示\n// 一共有n只牛，每只牛有重量和才艺两个属性值\n// 要求一定要选若干只牛，使得总重量不少于w，并且选出的牛，希望让\n// 才艺的和 / 重量的和，这个比值尽量大\n// 返回该比值 * 1000的整数结果，小数部分舍弃\n// 1 <= n <= 250\n// 1 <= w <= 1000\n// 1 <= 牛的重量 <= 10^6\n// 1 <= 牛的才艺 <= 10^3\n// 测试链接 : https://www.luogu.com.cn/problem/P4377\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code02_TalentShow {\n\n\tpublic static int MAXN = 251;\n\n\tpublic static int MAXW = 1001;\n\n\t// 足够小代表无效解\n\tpublic static double NA = -1e9;\n\n\t// 最小精度\n\tpublic static double sml = 1e-6;\n\n\t// 重量\n\tpublic static int[] weight = new int[MAXN];\n\n\t// 才艺\n\tpublic static int[] talent = new int[MAXN];\n\n\t// (才艺 - x * 重量)的结余\n\tpublic static double[] value = new double[MAXN];\n\n\t// dp[i][j] : 1...i号牛自由选择，重量必须是j的情况下，最大的结余和\n\t// 特别的，dp[i][w]表示1...i号牛自由选择，重量必须是w、w+1...的所有情况中，最大的结余和\n\t// 为了节省时间和空间选择这么定义，同时做空间压缩\n\tpublic static double[] dp = new double[MAXW];\n\n\tpublic static int n, w;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvalue[i] = (double) talent[i] - x * weight[i];\n\t\t}\n\t\tdp[0] = 0;\n\t\tArrays.fill(dp, 1, w + 1, NA);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int p = w, j; p >= 0; p--) {\n\t\t\t\tj = (int) (p + weight[i]);\n\t\t\t\tif (j >= w) {\n\t\t\t\t\tdp[w] = Math.max(dp[w], dp[p] + value[i]);\n\t\t\t\t} else {\n\t\t\t\t\tdp[j] = Math.max(dp[j], dp[p] + value[i]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[w] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tw = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tweight[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ttalent[i] = (int) in.nval;\n\t\t}\n\t\tdouble l = 0, r = 0, x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tr += talent[i];\n\t\t}\n\t\tdouble ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t} else {\n\t\t\t\tr = x - sml;\n\t\t\t}\n\t\t}\n\t\tout.println((int) (ans * 1000));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_DesertKing.java`\n\n```java\npackage class138;\n\n// 最优比率生成树\n// 一共有n个村庄，每个村庄由(x, y, z)表示\n// 其中(x,y)代表村庄在二维地图中的位置，z代表其海拔高度\n// 任意两个村庄之间的距离就是二维地图中的欧式距离\n// 任意两个村庄之间的修路花费就是海拔差值的绝对值\n// 现在想把所有村庄连通起来，希望修路的条数尽量少，同时希望让\n// 总花费 / 总距离，这个比值尽量小，返回最小的比值是多少，结果保留小数点后3位其余部分舍弃\n// 2 <= n <= 10^3\n// 0 <= x、y <= 10^4\n// 0 <= z <= 10^7\n// 测试链接 : http://poj.org/problem?id=2728\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_DesertKing {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double sml = 1e-6;\n\n\tpublic static int[] x = new int[MAXN];\n\n\tpublic static int[] y = new int[MAXN];\n\n\tpublic static int[] z = new int[MAXN];\n\n\tpublic static double[][] dist = new double[MAXN][MAXN];\n\n\tpublic static double[][] cost = new double[MAXN][MAXN];\n\n\tpublic static boolean[] visit = new boolean[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int n;\n\n\t// 邻接矩阵结构下的prim算法，从节点1出发得到最小生成树的权值和\n\tpublic static double prim(double x) {\n\t\t// 结余值做边权，进而统计距离\n\t\t// 距离只和边权有关，原始的dist、cost不重要\n\t\t// 从1号点出发，更新到所有点的距离，也就是value数组\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvisit[i] = false;\n\t\t\tvalue[i] = cost[1][i] - x * dist[1][i];\n\t\t}\n\t\tvisit[1] = true;\n\t\tdouble sum = 0;\n\t\t// 最小生成树一定有n-1条边，所以一共有n-1轮解锁，每次解锁新的点进入最小生成树的点集\n\t\tfor (int i = 1; i <= n - 1; i++) {\n\t\t\t// 在没有解锁的点中，找到离最小生成树的点集最近的点，进行解锁\n\t\t\tdouble minDist = Double.MAX_VALUE;\n\t\t\tint next = 0;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] < minDist) {\n\t\t\t\t\tminDist = value[j];\n\t\t\t\t\tnext = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 最小的边进入最小生成树的边集，解锁的点进入最小生成树的点集\n\t\t\tsum += minDist;\n\t\t\tvisit[next] = true;\n\t\t\t// 查看新的解锁点能不能拉进其他点的距离\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] > cost[next][j] - x * dist[next][j]) {\n\t\t\t\t\tvalue[j] = cost[next][j] - x * dist[next][j];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t// 返回最小生成树的权值和\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\twhile (n != 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tz[i] = (int) in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j) {\n\t\t\t\t\t\tdist[i][j] = Math.sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));\n\t\t\t\t\t\tcost[i][j] = Math.abs(z[i] - z[j]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tdouble l = 0, r = 100, x, ans = 0;\n\t\t\twhile (l < r && r - l >= sml) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\t// 如果最小生成树的权值 <= 0，达标，左侧二分找寻更小比值\n\t\t\t\t// 如果最小生成树的权值 > 0，不达标，右侧二分找寻更大比值\n\t\t\t\tif (prim(x) <= 0) {\n\t\t\t\t\tans = x;\n\t\t\t\t\tr = x - sml;\n\t\t\t\t} else {\n\t\t\t\t\tl = x + sml;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.printf("%.3f\\n", ans);\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_MinimumAverageCircle.java`\n\n```java\npackage class138;\n\n// 最小圈\n// 一共有n个节点，m条有向边，每条边有权值\n// 这个有向带权图中，可能有若干环，规定环的平均值为\n// 环中边的权值和 / 环中边的数量\n// 返回所有环的平均值中最少的平均值，结果保留小数点后8位，其余部分舍弃\n// 1 <= n <= 3000\n// 1 <= m <= 10000\n// -10^7 <= 边权 <= 10^7\n// 测试链接 : https://www.luogu.com.cn/problem/P3199\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_MinimumAverageCircle {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int MAXM = 10001;\n\n\tpublic static double MAXE = 1e7;\n\n\tpublic static double sml = 1e-9;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\t// dfs判断负环，每个点的累积边权\n\tpublic static double[] value = new double[MAXN];\n\n\t// dfs判断负环，每个点是否是递归路径上的点\n\tpublic static boolean[] path = new boolean[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\t// 所有边都减去x，返回图中是否存在负环\n\tpublic static boolean check(double x) {\n\t\tArrays.fill(value, 1, n + 1, 0);\n\t\tArrays.fill(path, 1, n + 1, false);\n\t\treturn dfs(0, x);\n\t}\n\n\t// 其实就是spfa的递归版，时间复杂度O(n * m)\n\tpublic static boolean dfs(int u, double x) {\n\t\tif (u == 0) {\n\t\t\t// 认为0号点是超级源点，具有通往所有点的有向边\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfs(i, x)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tpath[u] = true;\n\t\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdouble w = weight[e] - x;\n\t\t\t\t// 只有v的累积边权变小，才会递归，非常强的剪枝\n\t\t\t\t// 如果递归路径回到v，并且此时是v的累积边权更小的情况，说明遇到了负环\n\t\t\t\t// 或者后续递归找到了负环\n\t\t\t\t// 直接返回true\n\t\t\t\tif (value[v] > value[u] + w) {\n\t\t\t\t\tvalue[v] = value[u] + w;\n\t\t\t\t\tif (path[v] || dfs(v, x)) {\n\t\t\t\t\t\treturn true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tpath[u] = false;\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tint u = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint v = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tdouble w = in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t}\n\t\tdouble l = -MAXE, r = MAXE, x, ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tr = x - sml;\n\t\t\t} else {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.8f\\n", ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code05_BestTeam.java`\n\n```java\npackage class138;\n\n// 最佳团体\n// 给定一棵树，节点编号0~n，0号节点是整棵树的头\n// 编号1~n的节点，每个节点都有招募花费和战斗值，0号节点这两个值都是0\n// 给定每条边(a,b)，表示节点a的父节点是b，有些节点的父节点是0节点\n// 当招募了某个节点，那么该节点及其上方的所有祖先节点都需要招募\n// 除了0号节点之外，一共可以招募k个人，希望让\n// 战斗值之和 / 招募花费之和，这个比值尽量大，答案只需保留三位小数，更大的精度舍弃\n// 1 <= k <= n <= 2500\n// 0 <= 招募花费、战斗值 <= 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P4322\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code05_BestTeam {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int LIMIT = 10000;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static double sml = 1e-6;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN];\n\n\tpublic static int[] to = new int[MAXN];\n\n\tpublic static int edgeCnt;\n\n\t// 招募花费，下标为节点原始编号\n\tpublic static int[] cost = new int[MAXN];\n\n\t// 战斗值，下标为节点原始编号\n\tpublic static int[] strength = new int[MAXN];\n\n\t// dfn[a] = b，表示原始a号节点的dfn编号为b\n\tpublic static int[] dfn = new int[MAXN];\n\n\t// dfn序计数\n\tpublic static int dfnCnt;\n\n\t// (战斗值 - x * 招募花费)的结余，下标为节点dfn编号\n\tpublic static double[] value = new double[MAXN];\n\n\t// 子树大小，下标为节点dfn编号\n\tpublic static int[] size = new int[MAXN];\n\n\t// 树型dp\n\tpublic static double[][] dp = new double[MAXN][MAXN];\n\n\tpublic static int k, n;\n\n\tpublic static void prepare() {\n\t\tedgeCnt = 1;\n\t\tdfnCnt = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[edgeCnt] = head[u];\n\t\tto[edgeCnt] = v;\n\t\thead[u] = edgeCnt++;\n\t}\n\n\t// 记录节点u的dfn编号 + 返回u这棵子树的节点数\n\t// 如下实现和讲解079，题目5，选课问题的最优解，几乎完全一样\n\tpublic static int dfs(int u) {\n\t\tint i = ++dfnCnt;\n\t\tdfn[u] = i;\n\t\tsize[i] = 1;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tsize[i] += dfs(v);\n\t\t}\n\t\treturn size[i];\n\t}\n\n\t// 根据x的值，计算节点的结余值，在树上选k+1个点\n\t// 一定要形成有效结构，返回最大的结余和\n\t// 核心逻辑完全来自讲解079，题目5，选课问题，重点介绍的最优解\n\tpublic static boolean check(double x) {\n\t\t// value[节点i的dfn编号] = 节点i的战斗值 - x * 节点i的招募花费\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tvalue[dfn[i]] = (double) strength[i] - x * cost[i];\n\t\t}\n\t\t// 越界位置认为都是无效解\n\t\tfor (int j = 1; j <= k; j++) {\n\t\t\tdp[dfnCnt + 1][j] = NA;\n\t\t}\n\t\t// 讲解079题目5的最优解逻辑\n\t\tfor (int i = dfnCnt; i >= 2; i--) {\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i + size[i]][j], value[i] + dp[i + 1][j - 1]);\n\t\t\t}\n\t\t}\n\t\t// 原始的0号节点，dfn编号是1，其他节点的dfn编号从2开始\n\t\t// 0号节点的战斗值和招募花费都是0，其他节点一共招募k个\n\t\treturn dp[2][k] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcost[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tstrength[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\taddEdge((int) in.nval, i);\n\t\t}\n\t\tdfs(0);\n\t\tdouble l = 0, r = LIMIT, x, ans = 0;\n\t\twhile (l < r && r - l >= sml) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tans = x;\n\t\t\t\tl = x + sml;\n\t\t\t} else {\n\t\t\t\tr = x - sml;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.3f\\n", ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Other1.java`\n\n```java\npackage class138;\n\n// 题目1，01分数规划模版题，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P10505\n// 测试链接 : http://poj.org/problem?id=2976\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Other1 {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static double[][] arr = new double[MAXN][3];\n\n\tpublic static int n, k;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][2] = arr[i][0] - x * arr[i][1];\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, new MyComparator());\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tsum += arr[i][2];\n\t\t}\n\t\treturn sum >= 0;\n\t}\n\n\tpublic static class MyComparator implements Comparator<double[]> {\n\n\t\t@Override\n\t\tpublic int compare(double[] o1, double[] o2) {\n\t\t\treturn o1[2] >= o2[2] ? -1 : 1;\n\t\t}\n\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\twhile (n != 0 || k != 0) {\n\t\t\tk = n - k;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][0] = in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[i][1] = in.nval;\n\t\t\t}\n\t\t\tdouble l = 0, r = 0, x;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tr += arr[i][0];\n\t\t\t}\n\t\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t\t// 二分完成后，l就是答案\n\t\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (check(x)) {\n\t\t\t\t\tl = x;\n\t\t\t\t} else {\n\t\t\t\t\tr = x;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println((int) (100 * (l + 0.005)));\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Other2.java`\n\n```java\npackage class138;\n\n// 题目2，牛群的才艺展示，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P4377\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other2 {\n\n\tpublic static int MAXN = 251;\n\n\tpublic static int MAXW = 1001;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static int[] weight = new int[MAXN];\n\n\tpublic static int[] talent = new int[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static double[] dp = new double[MAXW];\n\n\tpublic static int n, w;\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvalue[i] = (double) talent[i] - x * weight[i];\n\t\t}\n\t\tdp[0] = 0;\n\t\tArrays.fill(dp, 1, w + 1, NA);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int p = w, j; p >= 0; p--) {\n\t\t\t\tj = (int) (p + weight[i]);\n\t\t\t\tif (j >= w) {\n\t\t\t\t\tdp[w] = Math.max(dp[w], dp[p] + value[i]);\n\t\t\t\t} else {\n\t\t\t\t\tdp[j] = Math.max(dp[j], dp[p] + value[i]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn dp[w] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tw = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tweight[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ttalent[i] = (int) in.nval;\n\t\t}\n\t\tdouble l = 0, r = 0, x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tr += talent[i];\n\t\t}\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tl = x;\n\t\t\t} else {\n\t\t\t\tr = x;\n\t\t\t}\n\t\t}\n\t\tout.println((int) (l * 1000));\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Other3.java`\n\n```java\npackage class138;\n\n// 题目3，最优比率生成树，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : http://poj.org/problem?id=2728\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Other3 {\n\n\tpublic static int MAXN = 1001;\n\n\tpublic static int[] x = new int[MAXN];\n\n\tpublic static int[] y = new int[MAXN];\n\n\tpublic static int[] z = new int[MAXN];\n\n\tpublic static double[][] dist = new double[MAXN][MAXN];\n\n\tpublic static double[][] cost = new double[MAXN][MAXN];\n\n\tpublic static boolean[] visit = new boolean[MAXN];\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int n;\n\n\tpublic static double prim(double x) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvisit[i] = false;\n\t\t\tvalue[i] = cost[1][i] - x * dist[1][i];\n\t\t}\n\t\tvisit[1] = true;\n\t\tdouble sum = 0;\n\t\tfor (int i = 1; i <= n - 1; i++) {\n\t\t\tdouble minDist = Double.MAX_VALUE;\n\t\t\tint next = 0;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] < minDist) {\n\t\t\t\t\tminDist = value[j];\n\t\t\t\t\tnext = j;\n\t\t\t\t}\n\t\t\t}\n\t\t\tsum += minDist;\n\t\t\tvisit[next] = true;\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tif (!visit[j] && value[j] > cost[next][j] - x * dist[next][j]) {\n\t\t\t\t\tvalue[j] = cost[next][j] - x * dist[next][j];\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\twhile (n != 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty[i] = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\tz[i] = (int) in.nval;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t\tif (i != j) {\n\t\t\t\t\t\tdist[i][j] = Math.sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));\n\t\t\t\t\t\tcost[i][j] = Math.abs(z[i] - z[j]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tdouble l = 0, r = 100, x;\n\t\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t\t// 二分完成后，l就是答案\n\t\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\t\tx = (l + r) / 2;\n\t\t\t\tif (prim(x) <= 0) {\n\t\t\t\t\tr = x;\n\t\t\t\t} else {\n\t\t\t\t\tl = x;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.printf("%.3f\\n", l);\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Other4.java`\n\n```java\npackage class138;\n\n// 题目4，最小圈，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P3199\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other4 {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int MAXM = 10001;\n\n\tpublic static double MAXE = 1e7;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXM];\n\n\tpublic static int[] to = new int[MAXM];\n\n\tpublic static double[] weight = new double[MAXM];\n\n\tpublic static int cnt;\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static boolean[] path = new boolean[MAXN];\n\n\tpublic static int n, m;\n\n\tpublic static void prepare() {\n\t\tcnt = 1;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v, double w) {\n\t\tnext[cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt++;\n\t}\n\n\tpublic static boolean check(double x) {\n\t\tArrays.fill(value, 1, n + 1, 0);\n\t\tArrays.fill(path, 1, n + 1, false);\n\t\treturn dfs(0, x);\n\t}\n\n\tpublic static boolean dfs(int u, double x) {\n\t\tif (u == 0) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfs(i, x)) {\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tpath[u] = true;\n\t\t\tfor (int e = head[u]; e != 0; e = next[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdouble w = weight[e] - x;\n\t\t\t\tif (value[v] > value[u] + w) {\n\t\t\t\t\tvalue[v] = value[u] + w;\n\t\t\t\t\tif (path[v] || dfs(v, x)) {\n\t\t\t\t\t\treturn true;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tpath[u] = false;\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tint u = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tint v = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tdouble w = in.nval;\n\t\t\taddEdge(u, v, w);\n\t\t}\n\t\tdouble l = -MAXE, r = MAXE, x;\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tr = x;\n\t\t\t} else {\n\t\t\t\tl = x;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.8f\\n", l);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Other5.java`\n\n```java\npackage class138;\n\n// 题目5，最佳团体，另一种二分的写法\n// 思路是不变的，二分的写法多种多样\n// 代码中打注释的位置，就是更简单的二分逻辑，其他代码没有变化\n// 测试链接 : https://www.luogu.com.cn/problem/P4322\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Other5 {\n\n\tpublic static int MAXN = 3001;\n\n\tpublic static int LIMIT = 10000;\n\n\tpublic static double NA = -1e9;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN];\n\n\tpublic static int[] to = new int[MAXN];\n\n\tpublic static int edgeCnt;\n\n\tpublic static int[] cost = new int[MAXN];\n\n\tpublic static int[] strength = new int[MAXN];\n\n\tpublic static int[] dfn = new int[MAXN];\n\n\tpublic static int dfnCnt;\n\n\tpublic static double[] value = new double[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static double[][] dp = new double[MAXN][MAXN];\n\n\tpublic static int k, n;\n\n\tpublic static void prepare() {\n\t\tedgeCnt = 1;\n\t\tdfnCnt = 0;\n\t\tArrays.fill(head, 1, n + 1, 0);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[edgeCnt] = head[u];\n\t\tto[edgeCnt] = v;\n\t\thead[u] = edgeCnt++;\n\t}\n\n\tpublic static int dfs(int u) {\n\t\tint i = ++dfnCnt;\n\t\tdfn[u] = i;\n\t\tsize[i] = 1;\n\t\tfor (int e = head[u], v; e != 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tsize[i] += dfs(v);\n\t\t}\n\t\treturn size[i];\n\t}\n\n\tpublic static boolean check(double x) {\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tvalue[dfn[i]] = (double) strength[i] - x * cost[i];\n\t\t}\n\t\tfor (int j = 1; j <= k; j++) {\n\t\t\tdp[dfnCnt + 1][j] = NA;\n\t\t}\n\t\tfor (int i = dfnCnt; i >= 2; i--) {\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i + size[i]][j], value[i] + dp[i + 1][j - 1]);\n\t\t\t}\n\t\t}\n\t\treturn dp[2][k] >= 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcost[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tstrength[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\taddEdge((int) in.nval, i);\n\t\t}\n\t\tdfs(0);\n\t\tdouble l = 0, r = LIMIT, x;\n\t\t// 二分进行60次，足够达到题目要求的精度\n\t\t// 二分完成后，l就是答案\n\t\tfor (int i = 1; i <= 60; i++) {\n\t\t\tx = (l + r) / 2;\n\t\t\tif (check(x)) {\n\t\t\t\tl = x;\n\t\t\t} else {\n\t\t\t\tr = x;\n\t\t\t}\n\t\t}\n\t\tout.printf("%.3f\\n", l);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
10b14013-8d9b-4ab2-9ee4-42f399409ada	9230e5a9-7dbf-4d07-8d0b-12818e23537d	deep	二项式定理证明和相关题目	# 144. 二项式定理证明和相关题目\n\n> 难度标签：**扩展** ｜ 主题：**数学** ｜ 来源：左程云《算法讲解》第 144 讲\n\n## 第 1 页：⼆项式定理证明和相关题⽬\n\n前置知识\n098 -\n讲解 乘法快速幂\n099 - 3\n讲解 题⽬ ，阶乘余数表、阶乘逆元表的线性递推求法\n本节课讲述\n⼆项式定理证明和相关题⽬\n下节课讲述\n⼆项式反演的四种形式、证明、相关题⽬\n⼆项式反演⽐较难理解，但是我进⾏了⼤量的备课，下节课⼀定能让你懂，觉得好帮我扩散！\n左程云\n\n## 第 2 页：⼆项式定理证明和相关题⽬\n\n⼆项式定理\na = 1 b = 1\n当 ， 时，就是著名的杨辉三⻆，也叫帕斯卡三⻆\n左程云\n\n## 第 3 页：⼆项式定理证明和相关题⽬\n\n(1+1) 0 1 ...5\n的 次⽅、 次⽅ 次⽅的展开\n可以得到⼀个结论，也就是著名的组合恒等式\nn * n O(n^2) O(1)\n这可以⽤于打表，⼤规模⽣成组合的⽅法数，⽣成 的表时间复杂度 ，单次查询\nc(n, k) O(n) O(1)\n当然也可以⽤阶乘余数表、阶乘逆元表来求解 ，⽣成的时间复杂度 ，单次查询\n左程云\n\n## 第 4 页：⼆项式定理证明和相关题⽬\n\n左程云\n\n## 第 5 页：⼆项式定理证明和相关题⽬\n\n左程云\n\n## 第 6 页：⼆项式定理证明和相关题⽬\n\n左程云\n\n## 第 7 页：⼆项式定理证明和相关题⽬\n\nc(n, k) % MOD\n利⽤阶乘余数表和阶乘逆元表，计算任意 的结果，步骤如下\n1 0! 1 0 0 1\n，注意， 是 ， 的 次⽅也是\n2 0! 1! 2! ..i! ..n! % MOD fac[i]\n，根据乘法同余，正序递推 、 、 、 ， 意义下的余数，结果记录在\n3 n! (n-1)! ..i! ..1! % MOD inv[i]\n，根据逆元概念，逆序递推 、 、 ， 意义下的逆元，结果记录在\n4 c(n, k)\n，计算任意 ，利⽤如下函数即可\n099 3 099\n这个内容在讲解 ，题⽬ ，有⾮常详细的讲述，不会的同学可以学习讲解\n左程云\n\n## 第 8 页：⼆项式定理证明和相关题⽬\n\n1\n题⽬\n杨辉三⻆\nn n\n给定数字 ，打印杨辉三⻆的前 ⾏\n1 <= n <= 20\n: https://www.luogu.com.cn/problem/P5732\n测试链接\n左程云\n\n## 第 9 页：⼆项式定理证明和相关题⽬\n\n2\n题⽬\n计算系数\n(ax + by) k a b k\n多项式为， 的 次⽅，其中 、 、 为常数\nx n * y m\n计算这个多项式展开后， 的 次⽅ 的 次⽅，这⼀项的系数\n0 <= k <= 1000\n0 <= a b <= 10^6\n、\nn + m == k\n: https://www.luogu.com.cn/problem/P1313\n测试链接\n左程云\n\n## 第 10 页：⼆项式定理证明和相关题⽬\n\n3\n题⽬\n组合数问题\nc(i, j) i j\n组合公式 ，表示从 个物品中选出 个物品的⽅案数\nk (i, j)\n如果该数值是 的整数倍，那么称 是⼀个合法对\nn m i j 0 <= i <= n 0 <= j <= min(i, m)\n给定具体的⼀组数字 和 ，当 和 满⾜： ，\n返回有多少合法对\nt k\n⼀共有 组测试，所有测试的 都为同⼀个值\nn m\n每组测试给定 和 ，打印每组测试的答案\n1 <= t <= 10^4\n2 <= k <= 21\n0 <= n m <= 2000\n、\n: https://www.luogu.com.cn/problem/P2822\n测试链接\n048\n涉及⼆维前缀和的内容，在讲解 ，有需要的同学可以看⼀下，不过本题理解难度不⼤，听我讲也能理解\n左程云\n\n## 第 11 页：⼆项式定理证明和相关题⽬\n\n4\n题⽬\n分割的⽅法数\nn A, B C A[i] = B[i] + C[i]\n给定⼀个⻓度为 的数组 将其分割成数组 和数组 ，满⾜\nB C B[i], C[i] >= 1\n也就是⼀个数字分成两份，然后各⾃进⼊ 和 ，要求\nB C\n同时要求， 数组从左到右不能降序， 数组从左到右不能升序\nA = { 5, 4, 5 } B = { 2, 2, 3 } C = { 3, 2, 2 }\n⽐如， ，⼀种有效的划分， ，\n返回有多少种有效的划分⽅式\n1 <= n <= 10^7\n1 <= A[i] <= 10^7\n1000000007\n最终结果可能很⼤，对 取余\n来⾃真实⼤⼚笔试题，对数器验证\n转化为⼆项式定理是本题的重点\n左程云\n\n## 模板代码\n\n### `Code01_PascalTriangle.java`\n\n```java\npackage class144;\n\n// 杨辉三角\n// 给定数字n，打印杨辉三角的前n行\n// 1 <= n <= 20\n// 测试链接 : https://www.luogu.com.cn/problem/P5732\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code01_PascalTriangle {\n\n\tpublic static int MAXN = 20;\n\n\tpublic static long[][] tri = new long[MAXN][MAXN];\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\ttri[i][0] = tri[i][i] = 1;\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tfor (int j = 1; j < i; j++) {\n\t\t\t\ttri[i][j] = tri[i - 1][j] + tri[i - 1][j - 1];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tfor (int j = 0; j <= i; j++) {\n\t\t\t\tout.print(tri[i][j] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code02_CalculateCoefficients.java`\n\n```java\npackage class144;\n\n// 计算系数\n// 多项式为，(ax + by)的k次方，其中a、b、k为常数\n// 计算这个多项式展开后，x的n次方 * y的m次方，这一项的系数\n// 0 <= k <= 1000\n// 0 <= a、b <= 10^6\n// n + m == k\n// 测试链接 : https://www.luogu.com.cn/problem/P1313\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_CalculateCoefficients {\n\n\tpublic static int MAXK = 1001;\n\n\tpublic static int MOD = 10007;\n\n\t// fac[i]代表 i! 在 %MOD 意义下的余数\n\tpublic static long[] fac = new long[MAXK + 1];\n\n\t// inv[i]代表 i! 在 %MOD 意义下的逆元\n\tpublic static long[] inv = new long[MAXK + 1];\n\n\tpublic static int a, b, k, n, m;\n\n\t// 来自讲解098，乘法快速幂，x的p次方 % MOD\n\tpublic static long power(long x, int p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 来自讲解099，生成阶乘表和逆元表\n\tpublic static void build() {\n\t\t// 阶乘表线性递推\n\t\tfac[1] = 1;\n\t\tfor (int i = 2; i <= MAXK; i++) {\n\t\t\tfac[i] = ((long) i * fac[i - 1]) % MOD;\n\t\t}\n\t\t// 逆元表线性递推\n\t\tinv[MAXK] = power(fac[MAXK], MOD - 2);\n\t\tfor (int i = MAXK - 1; i >= 0; i--) {\n\t\t\tinv[i] = ((long) (i + 1) * inv[i + 1]) % MOD;\n\t\t}\n\t}\n\n\t// 组合公式\n\tpublic static long c(int n, int k) {\n\t\treturn (((fac[n] * inv[k]) % MOD) * inv[n - k]) % MOD;\n\t}\n\n\tpublic static long compute() {\n\t\tbuild();\n\t\treturn (((power(a, n) * power(b, m)) % MOD) * c(k, k - n)) % MOD;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken(); a = (int) in.nval;\n\t\tin.nextToken(); b = (int) in.nval;\n\t\tin.nextToken(); k = (int) in.nval;\n\t\tin.nextToken(); n = (int) in.nval;\n\t\tin.nextToken(); m = (int) in.nval;\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_CombinationNumber.java`\n\n```java\npackage class144;\n\n// 组合数问题\n// 组合公式c(i, j)，表示从i个物品中选出j个物品的方案数\n// 如果该数值是k的整数倍，那么称(i, j)是一个合法对\n// 给定具体的一组数字n和m，当i和j满足：0 <= i <= n，0 <= j <= min(i, m)\n// 返回有多少合法对\n// 一共有t组测试，所有测试的k都为同一个值\n// 每组测试给定n和m，打印每组测试的答案\n// 1 <= t <= 10^4\n// 2 <= k <= 21\n// 0 <= n、m <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P2822\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_CombinationNumber {\n\n\tpublic static int MAXV = 2000;\n\n\tpublic static int MAXN = 2002;\n\n\tpublic static int[][] c = new int[MAXN][MAXN];\n\n\tpublic static int[][] f = new int[MAXN][MAXN];\n\n\tpublic static int[][] sum = new int[MAXN][MAXN];\n\n\tpublic static int t, k, n, m;\n\n\tpublic static void build() {\n\t\tfor (int i = 0; i <= MAXV; i++) {\n\t\t\tc[i][0] = 1;\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tc[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % k;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= MAXV; i++) {\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tf[i][j] = c[i][j] % k == 0 ? 1 : 0;\n\t\t\t}\n\t\t}\n\t\tfor (int i = 2; i <= MAXV; i++) {\n\t\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t\tsum[i][j] = sum[i][j - 1] + sum[i - 1][j] - sum[i - 1][j - 1] + f[i][j];\n\t\t\t}\n\t\t\tsum[i][i + 1] = sum[i][i];\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tt = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tbuild();\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tin.nextToken();\n\t\t\tn = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tif (m > n) {\n\t\t\t\tout.println(sum[n][n]);\n\t\t\t} else {\n\t\t\t\tout.println(sum[n][m]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n}\n\n```\n\n### `Code04_SplitWays1.java`\n\n```java\npackage class144;\n\n// 分割的方法数\n// 给定一个长度为n的数组A, 将其分割成数组B和数组C，满足A[i] = B[i] + C[i]\n// 也就是一个数字分成两份，然后各自进入B和C，要求B[i], C[i] >= 1\n// 同时要求，B数组从左到右不能降序，C数组从左到右不能升序\n// 比如，A = { 5, 4, 5 }，一种有效的划分，B = { 2, 2, 3 }，C = { 3, 2, 2 }\n// 返回有多少种有效的划分方式\n// 1 <= n <= 10^7\n// 1 <= A[i] <= 10^7\n// 最终结果可能很大，答案对 1000000007 取模\n// 来自真实大厂笔试题，该实现为对数器版本\n// 有同学找到了测试链接，就是Code04_SplitWays2文件\npublic class Code04_SplitWays1 {\n\n\t// 暴力方法\n\t// 为了验证\n\tpublic static int ways1(int[] arr) {\n\t\tint ans = 0;\n\t\tfor (int b = 1, c = arr[0] - 1; b < arr[0]; b++, c--) {\n\t\t\tans += f(arr, 1, b, c);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int f(int[] arr, int i, int preb, int prec) {\n\t\tif (i == arr.length) {\n\t\t\treturn 1;\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int b = 1, c = arr[i] - 1; b < arr[i]; b++, c--) {\n\t\t\tif (preb <= b && prec >= c) {\n\t\t\t\tans += f(arr, i + 1, b, c);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 正式方法\n\t// 转化成杨辉三角\n\tpublic static final int MOD = 1000000007;\n\n\tpublic static int ways2(int[] arr) {\n\t\tint n = arr.length;\n\t\tint k = arr[0] - 1;\n\t\tfor (int i = 1; i < n && k > 0; i++) {\n\t\t\tif (arr[i - 1] > arr[i]) {\n\t\t\t\tk -= arr[i - 1] - arr[i];\n\t\t\t}\n\t\t}\n\t\tif (k <= 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn c(k + n - 1, n);\n\t}\n\n\t// 组合公式\n\tpublic static int c(int n, int k) {\n\t\tlong fac = 1;\n\t\tlong inv1 = 1;\n\t\tlong inv2 = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfac = (fac * i) % MOD;\n\t\t\tif (i == k) {\n\t\t\t\tinv1 = power(fac, MOD - 2); // 费马小定理求逆元\n\t\t\t}\n\t\t\tif (i == n - k) {\n\t\t\t\tinv2 = power(fac, MOD - 2); // 费马小定理求逆元\n\t\t\t}\n\t\t}\n\t\treturn (int) ((((fac * inv1) % MOD) * inv2) % MOD);\n\t}\n\n\t// 乘法快速幂\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static int[] randomArray(int n, int v) {\n\t\tint[] ans = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tans[i] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 为了测试\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("功能测试开始");\n\t\tint N = 10;\n\t\tint V = 20;\n\t\tint test = 20000;\n\t\tfor (int i = 0; i < test; i++) {\n\t\t\tint n = (int) (Math.random() * N) + 1;\n\t\t\tint[] arr = randomArray(n, V);\n\t\t\tint ans1 = ways1(arr);\n\t\t\tint ans2 = ways2(arr);\n\t\t\tif (ans1 != ans2) {\n\t\t\t\tSystem.out.println("出错了!");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("功能测试结束");\n\n\t\tSystem.out.println("==========");\n\n\t\tSystem.out.println("性能测试开始");\n\t\tint n = 10000000;\n\t\tint v = 10000000;\n\t\tlong start, end;\n\t\tint[] arr = new int[n];\n\t\tSystem.out.println("随机生成的数据测试");\n\t\tSystem.out.println("数组长度 : " + n);\n\t\tSystem.out.println("数值范围 : [" + 1 + "," + v + "]");\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = (int) (Math.random() * v) + 1;\n\t\t}\n\t\tstart = System.currentTimeMillis();\n\t\tways2(arr);\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("运行时间 : " + (end - start) + " 毫秒");\n\n\t\tSystem.out.println();\n\n\t\tSystem.out.println("运行最慢的数据测试");\n\t\tSystem.out.println("数组长度 : " + n);\n\t\tSystem.out.println("数值都是 : " + v);\n\t\tSystem.out.println("这种情况其实是复杂度最高的情况");\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = v;\n\t\t}\n\t\tstart = System.currentTimeMillis();\n\t\tways2(arr);\n\t\tend = System.currentTimeMillis();\n\t\tSystem.out.println("运行时间 : " + (end - start) + " 毫秒");\n\t\tSystem.out.println("性能测试结束");\n\t}\n\n}\n\n```\n\n### `Code04_SplitWays2.java`\n\n```java\npackage class144;\n\n// 分割的方法数\n// 有同学找到了测试链接，题意几乎一样，而且数据量小很多\n// 唯一的区别是：\n// 课上讲的题意，单独的3可以分裂成(1, 2)、(2, 1)，一共两种方式\n// 测试链接题意，单独的3可以分裂成(0, 3)、(1, 2)、(2, 1)、(3, 0)，一共四种方式\n// 也就是对单独的v来说，课上讲的题意，分裂方式为v-1种。测试链接题意，分裂方式为v+1种\n// 别的没有任何区别，实现代码中唯一有注释的那行，是仅有的改动\n// 测试链接 : https://leetcode.cn/problems/find-the-count-of-monotonic-pairs-ii/\npublic class Code04_SplitWays2 {\n\n\tpublic static final int MOD = 1000000007;\n\n\tpublic static int countOfPairs(int[] arr) {\n\t\tint n = arr.length;\n\t\t// 原始题意，k = arr[0] - 1，这里改成，k = arr[0] + 1\n\t\t// 其他代码毫无区别\n\t\tint k = arr[0] + 1;\n\t\tfor (int i = 1; i < n && k > 0; i++) {\n\t\t\tif (arr[i - 1] > arr[i]) {\n\t\t\t\tk -= arr[i - 1] - arr[i];\n\t\t\t}\n\t\t}\n\t\tif (k <= 0) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn c(k + n - 1, n);\n\t}\n\n\tpublic static int c(int n, int k) {\n\t\tlong fac = 1;\n\t\tlong inv1 = 1;\n\t\tlong inv2 = 1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfac = (fac * i) % MOD;\n\t\t\tif (i == k) {\n\t\t\t\tinv1 = power(fac, MOD - 2);\n\t\t\t}\n\t\t\tif (i == n - k) {\n\t\t\t\tinv2 = power(fac, MOD - 2);\n\t\t\t}\n\t\t}\n\t\treturn (int) ((((fac * inv1) % MOD) * inv2) % MOD);\n\t}\n\n\tpublic static long power(long x, long p) {\n\t\tlong ans = 1;\n\t\twhile (p > 0) {\n\t\t\tif ((p & 1) == 1) {\n\t\t\t\tans = (ans * x) % MOD;\n\t\t\t}\n\t\t\tx = (x * x) % MOD;\n\t\t\tp >>= 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n}\n\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
