ar();\n//    return 0;\n//}\n```\n\n### `FollowUp1.java`\n\n```java\npackage class150;\n\n// 替罪羊树实现普通有序表，数据加强的测试，java版\n// 这个文件课上没有讲，测试数据加强了，而且有强制在线的要求\n// 基本功能要求都是不变的，可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P6136\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class FollowUp1 {\n\n\tpublic static double ALPHA = 0.7;\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] key = new int[MAXN];\n\n\tpublic static int[] count = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[] diff = new int[MAXN];\n\n\tpublic static int[] collect = new int[MAXN];\n\n\tpublic static int ci;\n\n\tpublic static int top;\n\n\tpublic static int father;\n\n\tpublic static int side;\n\n\tpublic static int init(int num) {\n\t\tkey[++cnt] = num;\n\t\tleft[cnt] = right[cnt] = 0;\n\t\tcount[cnt] = size[cnt] = diff[cnt] = 1;\n\t\treturn cnt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + count[i];\n\t\tdiff[i] = diff[left[i]] + diff[right[i]] + (count[i] > 0 ? 1 : 0);\n\t}\n\n\tpublic static void inorder(int i) {\n\t\tif (i != 0) {\n\t\t\tinorder(left[i]);\n\t\t\tif (count[i] > 0) {\n\t\t\t\tcollect[++ci] = i;\n\t\t\t}\n\t\t\tinorder(right[i]);\n\t\t}\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint m = (l + r) / 2;\n\t\tint h = collect[m];\n\t\tleft[h] = build(l, m - 1);\n\t\tright[h] = build(m + 1, r);\n\t\tup(h);\n\t\treturn h;\n\t}\n\n\tpublic static void rebuild() {\n\t\tif (top != 0) {\n\t\t\tci = 0;\n\t\t\tinorder(top);\n\t\t\tif (ci > 0) {\n\t\t\t\tif (father == 0) {\n\t\t\t\t\thead = build(1, ci);\n\t\t\t\t} else if (side == 1) {\n\t\t\t\t\tleft[father] = build(1, ci);\n\t\t\t\t} else {\n\t\t\t\t\tright[father] = build(1, ci);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean balance(int i) {\n\t\treturn ALPHA * diff[i] >= Math.max(diff[left[i]], diff[right[i]]);\n\t}\n\n\tpublic static void add(int i, int f, int s, int num) {\n\t\tif (i == 0) {\n\t\t\tif (f == 0) {\n\t\t\t\thead = init(num);\n\t\t\t} else if (s == 1) {\n\t\t\t\tleft[f] = init(num);\n\t\t\t} else {\n\t\t\t\tright[f] = init(num);\n\t\t\t}\n\t\t} else {\n\t\t\tif (key[i] == num) {\n\t\t\t\tcount[i]++;\n\t\t\t} else if (key[i] > num) {\n\t\t\t\tadd(left[i], i, 1, num);\n\t\t\t} else {\n\t\t\t\tadd(right[i], i, 2, num);\n\t\t\t}\n\t\t\tup(i);\n\t\t\tif (!balance(i)) {\n\t\t\t\ttop = i;\n\t\t\t\tfather = f;\n\t\t\t\tside = s;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\ttop = father = side = 0;\n\t\tadd(head, 0, 0, num);\n\t\trebuild();\n\t}\n\n\tpublic static int small(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn small(left[i], num);\n\t\t} else {\n\t\t\treturn size[left[i]] + count[i] + small(right[i], num);\n\t\t}\n\t}\n\n\tpublic static int rank(int num) {\n\t\treturn small(head, num) + 1;\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + count[i] < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - count[i]);\n\t\t}\n\t\treturn key[i];\n\t}\n\n\tpublic static int index(int x) {\n\t\treturn index(head, x);\n\t}\n\n\tpublic static int pre(int num) {\n\t\tint kth = rank(num);\n\t\tif (kth == 1) {\n\t\t\treturn Integer.MIN_VALUE;\n\t\t} else {\n\t\t\treturn index(kth - 1);\n\t\t}\n\t}\n\n\tpublic static int post(int num) {\n\t\tint kth = rank(num + 1);\n\t\tif (kth == size[head] + 1) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t} else {\n\t\t\treturn index(kth);\n\t\t}\n\t}\n\n\tpublic static void remove(int i, int f, int s, int num) {\n\t\tif (key[i] == num) {\n\t\t\tcount[i]--;\n\t\t} else if (key[i] > num) {\n\t\t\tremove(left[i], i, 1, num);\n\t\t} else {\n\t\t\tremove(right[i], i, 2, num);\n\t\t}\n\t\tup(i);\n\t\tif (!balance(i)) {\n\t\t\ttop = i;\n\t\t\tfather = f;\n\t\t\tside = s;\n\t\t}\n\t}\n\n\tpublic static void remove(int num) {\n\t\tif (rank(num) != rank(num + 1)) {\n\t\t\ttop = father = side = 0;\n\t\t\tremove(head, 0, 0, num);\n\t\t\trebuild();\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tArrays.fill(key, 1, cnt + 1, 0);\n\t\tArrays.fill(count, 1, cnt + 1, 0);\n\t\tArrays.fill(left, 1, cnt + 1, 0);\n\t\tArrays.fill(right, 1, cnt + 1, 0);\n\t\tArrays.fill(size, 1, cnt + 1, 0);\n\t\tArrays.fill(diff, 1, cnt + 1, 0);\n\t\tcnt = 0;\n\t\thead = 0;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, num; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tnum = (int) in.nval;\n\t\t\tadd(num);\n\t\t}\n\t\tint lastAns = 0;\n\t\tint ans = 0;\n\t\tfor (int i = 1, op, x; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval ^ lastAns;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(x);\n\t\t\t} else if (op == 3) {\n\t\t\t\tlastAns = rank(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 4) {\n\t\t\t\tlastAns = index(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 5) {\n\t\t\t\tlastAns = pre(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else {\n\t\t\t\tlastAns = post(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tclear();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `FollowUp2.java`\n\n```java\npackage class150;\n\n// 替罪羊树实现普通有序表，数据加强的测试，C++版\n// 这个文件课上没有讲，测试数据加强了，而且有强制在线的要求\n// 基本功能要求都是不变的，可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P6136\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <vector>\n//#include <algorithm>\n//#include <cmath>\n//#include <climits>\n//#include <cstring>\n//\n//using namespace std;\n//\n//const double ALPHA = 0.7;\n//const int MAXN = 2000001;\n//int head = 0;\n//int cnt = 0;\n//int key[MAXN];\n//int key_count[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int siz[MAXN];\n//int diff[MAXN];\n//int collect[MAXN];\n//int ci;\n//int top;\n//int father;\n//int side;\n//\n//int init(int num) {\n//    key[++cnt] = num;\n//    ls[cnt] = rs[cnt] = 0;\n//    key_count[cnt] = siz[cnt] = diff[cnt] = 1;\n//    return cnt;\n//}\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]] + key_count[i];\n//    diff[i] = diff[ls[i]] + diff[rs[i]] + (key_count[i] > 0 ? 1 : 0);\n//}\n//\n//void inorder(int i) {\n//    if (i != 0) {\n//        inorder(ls[i]);\n//        if (key_count[i] > 0) {\n//            collect[++ci] = i;\n//        }\n//        inorder(rs[i]);\n//    }\n//}\n//\n//int build(int l, int r) {\n//    if (l > r) {\n//        return 0;\n//    }\n//    int m = (l + r) / 2;\n//    int h = collect[m];\n//    ls[h] = build(l, m - 1);\n//    rs[h] = build(m + 1, r);\n//    up(h);\n//    return h;\n//}\n//\n//void rebuild() {\n//    if (top != 0) {\n//        ci = 0;\n//        inorder(top);\n//        if (ci > 0) {\n//            if (father == 0) {\n//                head = build(1, ci);\n//            } else if (side == 1) {\n//                ls[father] = build(1, ci);\n//            } else {\n//                rs[father] = build(1, ci);\n//            }\n//        }\n//    }\n//}\n//\n//bool balance(int i) {\n//    return ALPHA * diff[i] >= max(diff[ls[i]], diff[rs[i]]);\n//}\n//\n//void add(int i, int f, int s, int num) {\n//    if (