d(jobi, jobv, mid + 1, r, i << 1 | 1);\n//    }\n//}\n//\n//void update(int jobi, int jobv, int l, int r, int i) {\n//    root[i] = innerRemove(arr[jobi], root[i]);\n//    root[i] = innerInsert(jobv, root[i]);\n//    if (l < r) {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) update(jobi, jobv, l, mid, i << 1);\n//        else update(jobi, jobv, mid + 1, r, i << 1 | 1);\n//    }\n//}\n//\n//int small(int jobl, int jobr, int jobv, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) return innerSmall(jobv, root[i]);\n//    int mid = (l + r) >> 1, ans = 0;\n//    if (jobl <= mid) ans += small(jobl, jobr, jobv, l, mid, i << 1);\n//    if (jobr > mid) ans += small(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n//    return ans;\n//}\n//\n//int number(int jobl, int jobr, int jobk) {\n//    int l = 0, r = 100000000, mid, ans = 0;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (small(jobl, jobr, mid + 1, 1, n, 1) + 1 > jobk) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int pre(int jobl, int jobr, int jobv, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) return innerPre(jobv, root[i]);\n//    int mid = (l + r) >> 1, ans = -INF;\n//    if (jobl <= mid) ans = max(ans, pre(jobl, jobr, jobv, l, mid, i << 1));\n//    if (jobr > mid) ans = max(ans, pre(jobl, jobr, jobv, mid + 1, r, i << 1 | 1));\n//    return ans;\n//}\n//\n//int post(int jobl, int jobr, int jobv, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) return innerPost(jobv, root[i]);\n//    int mid = (l + r) >> 1, ans = INF;\n//    if (jobl <= mid) ans = min(ans, post(jobl, jobr, jobv, l, mid, i << 1));\n//    if (jobr > mid) ans = min(ans, post(jobl, jobr, jobv, mid + 1, r, i << 1 | 1));\n//    return ans;\n//}\n//\n//int main(){\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for(int i = 1; i <= n; i++) cin >> arr[i];\n//    for(int i = 1; i <= n; i++) add(i, arr[i], 1, n, 1);\n//    for(int i = 1, op, x, y, z; i <= m; i++) {\n//        cin >> op >> x >> y;\n//        if(op == 3) {\n//            update(x, y, 1, n, 1);\n//            arr[x] = y;\n//        } else {\n//            cin >> z;\n//            if(op == 1) cout << small(x, y, z, 1, n, 1) + 1 << "\\n";\n//            else if(op == 2) cout << number(x, y, z) << "\\n";\n//            else if(op == 4) cout << pre(x, y, z, 1, n, 1) << "\\n";\n//            else cout << post(x, y, z, 1, n, 1) << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_IndexWithSegment1.java`\n\n```java\npackage class160;\n\n// 树状数组套线段树，java版\n// 给定一个长度为n的数组arr，下标1~n，每条操作都是如下5种类型中的一种，一共进行m次操作\n// 操作 1 x y z : 查询数字z在arr[x..y]中的排名\n// 操作 2 x y z : 查询arr[x..y]中排第z名的数字\n// 操作 3 x y   : arr中x位置的数字改成y\n// 操作 4 x y z : 查询数字z在arr[x..y]中的前驱，不存在返回-2147483647\n// 操作 5 x y z : 查询数字z在arr[x..y]中的后继，不存在返回+2147483647\n// 1 <= n、m <= 2 * 10^5\n// 数组中的值永远在[0, 10^8]范围内\n// 测试链接 : https://www.luogu.com.cn/problem/P3380\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n// 本题之后增加了测试用例，数据范围放大到 2 * 10^5\n// 树状数组套线段树的java实现和C++实现都能通过\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_IndexWithSegment1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int MAXT = MAXN * 160;\n\n\tpublic static int INF = Integer.MAX_VALUE;\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[][] ques = new int[MAXN][4];\n\n\tpublic static int[] sorted = new int[MAXN * 2];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] sum = new int[MAXT];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int cntt = 0;\n\n\tpublic static int[] addTree = new int[MAXN];\n\n\tpublic static int[] minusTree = new int[MAXN];\n\n\tpublic static int cntadd;\n\n\tpublic static int cntminus;\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\t// 第jobi小的数字，增加jobv的计数，数字范围l~r，节点编号i，返回头节点编号\n\tpublic static int innerAdd(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[i] = innerAdd(jobi, jobv, l, mid, left[i]);\n\t\t\t} else {\n\t\t\t\tright[i] = innerAdd(jobi, jobv, mid + 1, r, right[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[left[i]] + sum[right[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\t// 查询比jobi小的数字个数，数字范围l~r\n\t// 不需要头节点编号，因为有多棵树，所有的头节点记录在addTree、minusTree\n\tpublic static int innerSmall(int jobi, int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn 0;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tif (jobi <= mid) {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = left[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = left[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerSmall(jobi, l, mid);\n\t\t} else {\n\t\t\tint leftsum = 0;\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\tleftsum += sum[left[addTree[i]]];\n\t\t\t\taddTree[i] = right[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tleftsum -= sum[left[minusTree[i]]];\n\t\t\t\tminusTree[i] = right[minusTree[i]];\n\t\t\t}\n\t\t\treturn leftsum + innerSmall(jobi, mid + 1, r);\n\t\t}\n\t}\n\n\t// 查询第jobk小的数字，数字范围l~r\n\t// 不需要头节点编号，因为有多棵树，所有的头节点记录在addTree、minusTree\n\tpublic static int innerQuery(int jobk, int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint leftsum = 0;\n\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\tleftsum += sum[left[addTree[i]]];\n\t\t}\n\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\tleftsum -= sum[left[minusTree[i]]];\n\t\t}\n\t\tif (jobk <= leftsum) {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = left[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = left[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk, l, mid);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = right[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = right[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk - leftsum, mid + 1, r);\n\t\t}\n\t}\n\n\t// arr中i下标的数字，增加cnt的计数\n\tpublic static void add(int i, int cnt) {\n\t\tfor (int j = i; j <= n; j += lowbit(j)) {\n\t\t\troot[j] = innerAdd(arr[i], cnt, 1, s, root[j]);\n\t\t}\n\t}\n\n\t// arr中i下标的数字，改成v\n\tpublic static void update(int i, int v) {\n\t\tadd(i, -1);\n\t\tarr[i] = kth(v);\n\t\tadd(i, 1);\n\t}\n\n\t// arr[l..r]范围上，比v小的数字个数\n\tpublic static int small(int l, int r, int v) {\n\t\tcntadd = cntminus = 0;\n\t\tfor (int i = r; i > 0; i -= lowbit(i)) {\n\t\t\taddTree[++cntadd] = root[i];\n\t\t}\n\t\tfor (int i = l - 1; i > 0; i -= lowbit(i)) {\n\t\t\tminusTree[++cntminus] = root[i];\n\t\t}\n\t\treturn innerSmall(v, 1, s);\n\t}\n\n\t// arr[l..r]范围上，查询第k小的数字是什么\n\tpublic static int number(int l, int r, int k) {\n\t\tcntadd = cntminus = 0;\n\t\tfor (int i = r; i > 0; i -= lowbit(i)) {\n\t\t\taddTree[++cntadd] = root[i];\n\t\t}\n\t\tfor (int i = l - 1; i > 0; i -= lowbit(i)) {\n\t\t\tminusTree[++cntminus] = root[i];\n\t\t}\n\t\treturn sorted[innerQuery(k, 1, s)];\n\t}\n\n\t// arr[l..r]范围上，查询v的前驱\n\tpublic static int pre(int l, int r, int v) {\n\t\tint rank = small(l, r, v) + 1;\n\t\tif (rank == 1) {\n\t\t\treturn -INF;\n\t\t}\n\t\treturn number(l, r, rank - 1);\n\t}\n\n\t// arr[l..r]范围上，查询v的后继\n\tpublic static int post(int l, int r, int v) {\n\t\tif (v == s) {\n\t\t\treturn INF;\n\t\t}\n\t\tint sml = small(l, r, v + 1);\n\t\tif (sml == r - l + 1) {\n\t\t\treturn INF;\n\t\t}\n\t\treturn number(l, r, sml + 1);\n\t}\n\n\tpublic static void prepare() {\n\t\ts = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++s] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (ques[i][0] == 3) {\n\t\t\t\tsorted[++s] = ques[i][2];\n\t\t\t} else if (ques[i][0] != 2) {\n\t\t\t\tsorted[++s] = ques[i][3];\n\t\t\t}\n\t\t}\n\t\tArrays.sort(sorted, 1, s + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= s; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\ts = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t\tadd(i, 1); // arr中i位置的数字，增加1个词频\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tques[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tques[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tques[i][2] = (int) in.nval;\n\t\t\tif (ques[i][0] != 3) {\n\t\t\t\tin.nextToken();\n\t\t\t\tques[i][3] = (int) in.nval;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = ques[i][0];\n\t\t\tx = ques[i][1];\n\t\t\ty = ques[i][2];\n\t\t\tif (op == 3) {\n\t\t\t\tupdate(x, y);\n\t\t\t} else {\n\t\t\t\tz = ques[i][3];\n\t\t\t\tif (op == 1) {\n\t\t\t\t\tout.println(small(x, y, kth(z)) + 1);\n\t\t\t\t} else if (op == 2) {\n\t\t\t\t\tout.println(number(x, y, z));\n\t\t\t\t} else if (op == 4) {\n\t\t\t\t\tout.println(pre(x, y, kth(z)));\n\t\t\t\t} else {\n\t\t\t\t\tout.println(post(x, y, kth(z)));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_IndexWithSegment2.java`\n\n```java\npackage class160;\n\n// 树状数组套线段树，C++版\n// 给定一个长度为n的数组arr，下标1~n，每条操作都是如下5种类型中的一种，一共进行m次操作\n// 操作 1 x y z : 查询数字z在arr[x..y]中的排名\n// 操作 2 x y z : 查询arr[x..y]中排第z名的数字\n// 操作 3 x y   : arr中x位置的数字改成y\n// 操作 4 x y z : 查询数字z在arr[x..y]中的前驱，不存在返回-2147483647\n// 操作 5 x y z : 查询数字z在arr[x..y]中的后继，不存在返回+2147483647\n// 1 <= n、m <= 2 * 10^5\n// 数组中的值永远在[0, 10^8]范围内\n// 测试链接 : https://www.luogu.com.cn/problem/P3380\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = MAXN * 160;\n//const int INF = INT_MAX;\n//int n, m, s;\n//int arr[MAXN];\n//int ques[MAXN][4];\n//int sorted[MAXN * 2];\n//int root[MAXN];\n//int sum[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int cntt = 0;\n//int addTree[MAXN];\n//int minusTree[MAXN];\n//int cntadd;\n//int cntminus;\n//\n//int kth(int num) {\n//    int left = 1, right = s, mid;\n//    while (left <= right) {\n//        mid = (left + right) / 2;\n//        if (sorted[mid] == num) {\n//            return mid;\n//        } else if (sorted[mid] < num) {\n//            left = mid + 1;\n//        } else {\n//            right = mid - 1;\n//        }\n//    }\n//    return -1;\n//}\n//\n//int lowbit(int i) {\n//    return i & -i;\n//}\n//\n//int innerAdd(int jobi, int jobv, int l, int r, int i) {\n//    if (i == 0) {\n//        i = ++cntt;\n//    }\n//    if (l == r) {\n//        sum[i] += jobv;\n//    } else {\n//        int mid = (l + r) / 2;\n//        if (jobi <= mid) {\n//        \tls[i] = innerAdd(jobi, jobv, l, mid, ls[i]);\n//        } else {\n//        \trs[i] = innerAdd(jobi, jobv, mid + 1, r, rs[i]);\n//        }\n//        sum[i] = sum[l