e(int i, int v) {\n//    add(i, -1);\n//    arr[i] = kth(v);\n//    add(i, 1);\n//}\n//\n//int small(int l, int r, int v) {\n//    cntadd = cntminus = 0;\n//    for (int i = r; i > 0; i -= lowbit(i)) {\n//        addTree[++cntadd] = root[i];\n//    }\n//    for (int i = l - 1; i > 0; i -= lowbit(i)) {\n//        minusTree[++cntminus] = root[i];\n//    }\n//    return innerSmall(v, 1, s);\n//}\n//\n//int number(int l, int r, int k) {\n//    cntadd = cntminus = 0;\n//    for (int i = r; i > 0; i -= lowbit(i)) {\n//        addTree[++cntadd] = root[i];\n//    }\n//    for (int i = l - 1; i > 0; i -= lowbit(i)) {\n//        minusTree[++cntminus] = root[i];\n//    }\n//    return sorted[innerQuery(k, 1, s)];\n//}\n//\n//int pre(int l, int r, int v) {\n//    int rank = small(l, r, v) + 1;\n//    if (rank == 1) {\n//        return -INF;\n//    }\n//    return number(l, r, rank - 1);\n//}\n//\n//int post(int l, int r, int v) {\n//    if (v == s) {\n//        return INF;\n//    }\n//    int sml = small(l, r, v + 1);\n//    if (sml == r - l + 1) {\n//        return INF;\n//    }\n//    return number(l, r, sml + 1);\n//}\n//\n//void prepare() {\n//    s = 0;\n//    for (int i = 1; i <= n; i++) {\n//        sorted[++s] = arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        if (ques[i][0] == 3) {\n//            sorted[++s] = ques[i][2];\n//        } else if (ques[i][0] != 2) {\n//            sorted[++s] = ques[i][3];\n//        }\n//    }\n//    sort(sorted + 1, sorted + s + 1);\n//    int len = 1;\n//    for (int i = 2; i <= s; i++) {\n//        if (sorted[len] != sorted[i]) {\n//            sorted[++len] = sorted[i];\n//        }\n//    }\n//    s = len;\n//    for (int i = 1; i <= n; i++) {\n//        arr[i] = kth(arr[i]);\n//        add(i, 1);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    cin >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> ques[i][0];\n//        cin >> ques[i][1];\n//        cin >> ques[i][2];\n//        if (ques[i][0] != 3) {\n//            cin >> ques[i][3];\n//        }\n//    }\n//    prepare();\n//    for (int i = 1, op, x, y, z; i <= m; i++) {\n//        op = ques[i][0];\n//        x = ques[i][1];\n//        y = ques[i][2];\n//        if (op == 3) {\n//            update(x, y);\n//        } else {\n//            z = ques[i][3];\n//            if (op == 1) {\n//                cout << small(x, y, kth(z)) + 1 << "\\n";\n//            } else if (op == 2) {\n//                cout << number(x, y, z) << "\\n";\n//            } else if (op == 4) {\n//                cout << pre(x, y, kth(z)) << "\\n";\n//            } else {\n//                cout << post(x, y, kth(z)) << "\\n";\n//            }\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_DynamicRankings1.java`\n\n```java\npackage class160;\n\n// 动态排名，java版\n// 给定一个长度为n的数组arr，下标1~n，每条操作都是如下2种类型中的一种，一共进行m次操作\n// 操作 Q x y z : 查询arr[x..y]中排第z名的数字\n// 操作 C x y   : arr中x位置的数字改成y\n// 1 <= n、m <= 10^5\n// 数组中的值永远在[0, 10^9]范围内\n// 测试链接 : https://www.luogu.com.cn/problem/P2617\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class Code05_DynamicRankings1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXT = MAXN * 130;\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[][] ques = new int[MAXN][4];\n\n\tpublic static int[] sorted = new int[MAXN * 2];\n\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] sum = new int[MAXT];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int cntt = 0;\n\n\tpublic static int[] addTree = new int[MAXN];\n\n\tpublic static int[] minusTree = new int[MAXN];\n\n\tpublic static int cntadd;\n\n\tpublic static int cntminus;\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static int innerAdd(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[i] = innerAdd(jobi, jobv, l, mid, left[i]);\n\t\t\t} else {\n\t\t\t\tright[i] = innerAdd(jobi, jobv, mid + 1, r, right[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[left[i]] + sum[right[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static int innerQuery(int jobk, int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint leftsum = 0;\n\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\tleftsum += sum[left[addTree[i]]];\n\t\t}\n\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\tleftsum -= sum[left[minusTree[i]]];\n\t\t}\n\t\tif (jobk <= leftsum) {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = left[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = left[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk, l, mid);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = right[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = right[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk - leftsum, mid + 1, r);\n\t\t}\n\t}\n\n\tpublic static void add(int i, int cnt) {\n\t\tfor (int j = i; j <= n; j += lowbit(j)) {\n\t\t\troot[j] = innerAdd(arr[i], cnt, 1, s, root[j]);\n\t\t}\n\t}\n\n\tpublic static void update(int i, int v) {\n\t\tadd(i, -1);\n\t\tarr[i] = kth(v);\n\t\tadd(i, 1);\n\t}\n\n\tpublic static int number(int l, int r, int k) {\n\t\tcntadd = cntminus = 0;\n\t\tfor (int i = r; i > 0; i -= lowbit(i)) {\n\t\t\taddTree[++cntadd] = root[i];\n\t\t}\n\t\tfor (int i = l - 1; i > 0; i -= lowbit(i)) {\n\t\t\tminusTree[++cntminus] = root[i];\n\t\t}\n\t\treturn sorted[innerQuery(k, 1, s)];\n\t}\n\n\tpublic static void prepare() {\n\t\ts = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++s] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (ques[i][0] == 2) {\n\t\t\t\tsorted[++s] = ques[i][2];\n\t\t\t}\n\t\t}\n\t\tArrays.sort(sorted, 1, s + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= s; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\ts = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t\tadd(i, 1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tques[i][0] = io.next().equals("Q") ? 1 : 2;\n\t\t\tques[i][1] = io.nextInt();\n\t\t\tques[i][2] = io.nextInt();\n\t\t\tif (ques[i][0] == 1) {\n\t\t\t\tques[i][3] = io.nextInt();\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = ques[i][0];\n\t\t\tx = ques[i][1];\n\t\t\ty = ques[i][2];\n\t\t\tif (op == 1) {\n\t\t\t\tz = ques[i][3];\n\t\t\t\tio.println(number(x, y, z));\n\t\t\t} else {\n\t\t\t\tupdate(x, y);\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n```\n\n### `Code05_DynamicRankings2.java`\n\n```java\npackage class160;\n\n// 动态排名，C++版\n// 给定一个长度为n的数组arr，下标1~n，每条操作都是如下2种类型中的一种，一共进行m次操作\n// 操作 Q x y z : 查询arr[x..y]中排第z名的数字\n// 操作 C x y   : arr中x位置的数字改成y\n// 1 <= n、m <= 10^5\n// 数组中的值永远在[0, 10^9]范围内\n// 测试链接 : https://www.luogu.com.cn/problem/P2617\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXT = MAXN * 130;\n//int n, m, s;\n//int arr[MAXN];\n//int ques[MAXN][4];\n//int sorted[MAXN * 2];\n//int root[MAXN];\n//int sum[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int cntt = 0;\n//int addTree[MAXN];\n//int minusTree[MAXN];\n//int cntadd;\n//int cntminus;\n//\n//int kth(int num) {\n//    int l = 1, r = s, mid;\n//    while (l <= r) {\n//        mid = (l + r) / 2;\n//        if (sorted[mid] == num) {\n//            return mid;\n//        } else if (sorted[mid] < num) {\n//            l = mid + 1;\n//        } else {\n//            r = mid - 1;\n//        }\n//    }\n//    return -1;\n//}\n//\n//int lowbit(int i) {\n//    return i & -i;\n//}\n//\n//int innerAdd(int jobi, int jobv, int l, int r, int i) {\n//    if (i == 0) {\n//        i = ++cntt;\n//    }\n//    if (l == r) {\n//    \tsu