\n//}\n```\n\n### `Code07_NetworkManagement1.java`\n\n```java\npackage class160;\n\n// 网络管理，java版\n// 一共有n个点，编号1~n，每个点给定点权，给定n-1条边，所有点连成一棵树\n// 实现如下类型的操作，操作一共发生m次\n// 操作 0 x y : x号点的点权变成y\n// 操作 k x y : 保证k > 0，点x到点y的路径上，打印第k大的值\n//              如果路径上不够k个点，打印"invalid request!"\n// 1 <= n、m <= 8 * 10^4\n// 点权 <= 10^8\n// 测试链接 : https://www.luogu.com.cn/problem/P4175\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code07_NetworkManagement1 {\n\n\tpublic static int MAXN = 80001;\n\n\tpublic static int MAXT = MAXN * 110;\n\n\tpublic static int MAXP = 18;\n\n\tpublic static int n, m, s;\n\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[][] ques = new int[MAXN][3];\n\n\tpublic static int[] sorted = new int[MAXN << 1];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int cntg = 0;\n\n\t// 外层的树状数组\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int[] sum = new int[MAXT];\n\n\tpublic static int cntt = 0;\n\n\t// 树上倍增需要\n\tpublic static int[] deep = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static int[] dfn = new int[MAXN];\n\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int cntd = 0;\n\n\tpublic static int[] addTree = new int[MAXN];\n\n\tpublic static int[] minusTree = new int[MAXN];\n\n\tpublic static int cntadd;\n\n\tpublic static int cntminus;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\t// dfs1是递归版，java版本提交会爆栈，C++版本不会爆栈\n\tpublic static void dfs1(int u, int fa) {\n\t\tdeep[u] = deep[fa] + 1;\n\t\tsize[u] = 1;\n\t\tdfn[u] = ++cntd;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tsize[u] += size[to[e]];\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs迭代版，都可以通过\n\t// 讲解118，详解了从递归版改迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = f;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tf = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstackSize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdeep[u] = deep[f] + 1;\n\t\t\t\tsize[u] = 1;\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\t\t\tif (to[e] != f) {\n\t\t\t\t\t\tsize[u] += size[to[e]];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (deep[a] < deep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (deep[stjump[a][p]] >= deep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int innerAdd(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[i] = innerAdd(jobi, jobv, l, mid, left[i]);\n\t\t\t} else {\n\t\t\t\tright[i] = innerAdd(jobi, jobv, mid + 1, r, right[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[left[i]] + sum[right[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static int innerQuery(int jobk, int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint leftsum = 0;\n\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\tleftsum += sum[left[addTree[i]]];\n\t\t}\n\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\tleftsum -= sum[left[minusTree[i]]];\n\t\t}\n\t\tif (jobk <= leftsum) {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = left[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = left[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk, l, mid);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= cntadd; i++) {\n\t\t\t\taddTree[i] = right[addTree[i]];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= cntminus; i++) {\n\t\t\t\tminusTree[i] = right[minusTree[i]];\n\t\t\t}\n\t\t\treturn innerQuery(jobk - leftsum, mid + 1, r);\n\t\t}\n\t}\n\n\t// i是dfn序号，val这是值，增加cnt的计数\n\tpublic static void add(int i, int val, int cnt) {\n\t\tfor (; i <= n; i += lowbit(i)) {\n\t\t\troot[i] = innerAdd(val, cnt, 1, s, root[i]);\n\t\t}\n\t}\n\n\tpublic static void update(int i, int v) {\n\t\tadd(dfn[i], arr[i], -1);\n\t\tadd(dfn[i] + size[i], arr[i], 1);\n\t\tarr[i] = kth(v);\n\t\tadd(dfn[i], arr[i], 1);\n\t\tadd(dfn[i] + size[i], arr[i], -1);\n\t}\n\n\tpublic static int query(int x, int y, int k) {\n\t\tint lca = lca(x, y);\n\t\tint lcafa = stjump[lca][0];\n\t\tint num = deep[x] + deep[y] - deep[lca] - deep[lcafa];\n\t\tif (num < k) {\n\t\t\treturn -1;\n\t\t}\n\t\tcntadd = cntminus = 0;\n\t\tfor (int i = dfn[x]; i > 0; i -= lowbit(i)) {\n\t\t\taddTree[++cntadd] = root[i];\n\t\t}\n\t\tfor (int i = dfn[y]; i > 0; i -= lowbit(i)) {\n\t\t\taddTree[++cntadd] = root[i];\n\t\t}\n\t\tfor (int i = dfn[lca]; i > 0; i -= lowbit(i)) {\n\t\t\tminusTree[++cntminus] = root[i];\n\t\t}\n\t\tfor (int i = dfn[lcafa]; i > 0; i -= lowbit(i)) {\n\t\t\tminusTree[++cntminus] = root[i];\n\t\t}\n\t\treturn sorted[innerQuery(num - k + 1, 1, s)];\n\t}\n\n\tpublic static void prepare() {\n\t\ts = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[++s] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (ques[i][0] == 0) {\n\t\t\t\tsorted[++s] = ques[i][2];\n\t\t\t}\n\t\t}\n\t\tArrays.sort(sorted, 1, s + 1);\n\t\tint len = 1;\n\t\tfor (int i = 2; i <= s; i++) {\n\t\t\tif (sorted[len] != sorted[i]) {\n\t\t\t\tsorted[++len] = sorted[i];\n\t\t\t}\n\t\t}\n\t\ts = len;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t}\n\t\tdfs2();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(dfn[i], arr[i], 1);\n\t\t\tadd(dfn[i] + size[i], arr[i], -1);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tques[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tques[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tques[i][2] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, k, x, y; i <= m; i++) {\n\t\t\tk = ques[i][0];\n\t\t\tx = ques[i][1];\n\t\t\ty = ques[i][2];\n\t\t\tif (k == 0) {\n\t\t\t\tupdate(x, y);\n\t\t\t} else {\n\t\t\t\tint ans = query(x, y, k);\n\t\t\t\tif (ans == -1) {\n\t\t\t\t\tout.println("invalid request!");\n\t\t\t\t} else {\n\t\t\t\t\tout.println(ans);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code07_NetworkManagement2.java`\n\n```java\npackage class160;\n\n// 网络管理，C++版\n// 一共有n个点，编号1~n，每个点给定点权，给定n-1条边，所有点连成一棵树\n// 实现如下类型的操作，操作一共发生m次\n// 操作 0 x y : x号点的点权变成y\n// 操作 k x y : 保证k > 0，点x到点y的路径上，打印第k大的值\n//              如果路径上不够k个点，打印"invalid request!"\n// 1 <= n、m <= 8 * 10^4\n// 点权 <= 10^8\n// 测试链接 : https://www.luogu.com.cn/problem/P4175\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 80001;\n//const int MAXT = MAXN * 110;\n//const int MAXP = 18;\n//int n, m, s;\n//\n//int arr[MAXN];\n//int ques[MAXN][3];\n//int sorted[MAXN << 1];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int sum[MAXT];\n//int cntt;\n//\n//int deep[MAXN];\n//int siz[MAXN];\n//int dfn[MAXN];\n//int stjump[MAXN][MAXP];\n//int cntd;\n//\n//int addTree[MAXN];\n//int minusTree[MAXN];\n//int cntadd, cntminus;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//int kth(int num) {\n//    int l