nizer;\n\npublic class Code03_LomsatGelral1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n;\n\tpublic static int[] color = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\n\tpublic static int[] colorCnt = new int[MAXN];\n\tpublic static int[] maxCnt = new int[MAXN];\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void effect(int u, int h) {\n\t\tcolorCnt[color[u]]++;\n\t\tif (colorCnt[color[u]] == maxCnt[h]) {\n\t\t\tans[h] += color[u];\n\t\t} else if (colorCnt[color[u]] > maxCnt[h]) {\n\t\t\tmaxCnt[h] = colorCnt[color[u]];\n\t\t\tans[h] = color[u];\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\teffect(v, h);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tcolorCnt[color[u]] = 0;\n\t\tmaxCnt[u] = 0;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u]) {\n\t\t\t\tcancel(v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\tmaxCnt[u] = maxCnt[son[u]];\n\t\tans[u] = ans[son[u]];\n\t\tcolorCnt[color[u]]++;\n\t\tif (colorCnt[color[u]] == maxCnt[u]) {\n\t\t\tans[u] += color[u];\n\t\t} else if (colorCnt[color[u]] > maxCnt[u]) {\n\t\t\tmaxCnt[u] = colorCnt[color[u]];\n\t\t\tans[u] = color[u];\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\teffect(v, u);\n\t\t\t}\n\t\t}\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tcolor[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_LomsatGelral2.java`\n\n```java\npackage class163;\n\n// 主导颜色累加和，C++版\n// 一共有n个节点，编号1~n，给定n-1条边，所有节点连成一棵树，1号节点为树头\n// 每个节点给定一种颜色值，主导颜色累加和定义如下\n// 以x为头的子树上，哪种颜色出现最多，那种颜色就是主导颜色，主导颜色可能不止一种\n// 所有主导颜色的值累加起来，每个主导颜色只累加一次，就是该子树的主导颜色累加和\n// 打印1~n每个节点为头的子树的主导颜色累加和\n// 1 <= n、颜色值 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF600E\n// 测试链接 : https://codeforces.com/problemset/problem/600/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n;\n//int color[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cnt = 0;\n//\n//int fa[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//\n//int colorCnt[MAXN];\n//int maxCnt[MAXN];\n//long long ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cnt] = head[u];\n//    to[cnt] = v;\n//    head[u] = cnt;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//        }\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void effect(int u, int h) {\n//    colorCnt[color[u]]++;\n//    if (colorCnt[color[u]] == maxCnt[h]) {\n//        ans[h] += color[u];\n//    } else if (colorCnt[color[u]] > maxCnt[h]) {\n//        maxCnt[h] = colorCnt[color[u]];\n//        ans[h] = color[u];\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u]) {\n//            effect(v, h);\n//        }\n//    }\n//}\n//\n//void cancel(int u) {\n//    colorCnt[color[u]] = 0;\n//    maxCnt[u] = 0;\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u]) {\n//            cancel(v);\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int keep) {\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, 0);\n//        }\n//    }\n//    if (son[u] != 0) {\n//        dfs2(son[u], 1);\n//    }\n//    maxCnt[u] = maxCnt[son[u]];\n//    ans[u] = ans[son[u]];\n//    colorCnt[color[u]]++;\n//    if (colorCnt[color[u]] == maxCnt[u]) {\n//        ans[u] += color[u];\n//    } else if (colorCnt[color[u]] > maxCnt[u]) {\n//        maxCnt[u] = colorCnt[color[u]];\n//        ans[u] = color[u];\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            effect(v, u);\n//        }\n//    }\n//    if (keep == 0) {\n//        cancel(u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> color[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 0);\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] << " ";\n//    }\n//    cout << "\\n";\n//    return 0;\n//}\n```\n\n### `Code04_DifferntName1.java`\n\n```java\npackage class163;\n\n// 不同名字数量，java版\n// 一共有n个节点，编号1~n，给定每个节点的名字和父亲节点编号\n// 名字是string类型，如果父亲节点编号为0，说明当前节点是某棵树的头节点\n// 注意，n个节点组成的是森林结构，可能有若干棵树\n// 一共有m条查询，每条查询 x k，含义如下\n// 以x为头的子树上，到x距离为k的所有节点中，打印不同名字的数量\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF246E\n// 测试链接 : https://codeforces.com/problemset/problem/246/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.StringTokenizer;\n\npublic class Code04_DifferntName1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\n\tpublic static HashMap<String, Integer> nameId = new HashMap<>();\n\tpublic static boolean[] root = new boolean[MAXN];\n\tpublic static int[] id = new int[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN];\n\tpublic static int[] tog = new int[MAXN];\n\tpublic static int cntg;\n\n\t// 问题列表\n\tpublic static int[] headq = new int[MAXN];\n\tpublic static int[] nextq = new int[MAXN];\n\tpublic static int[] ansiq = new int[MAXN];\n\tpublic static int[] kq = new int[MAXN];\n\tpublic static int cntq;\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\n\t// 树上启发式合并\n\tpublic static ArrayList<HashSet<Integer>> depSet = new ArrayList<>();\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int getNameId(String name) {\n\t\tif (nameId.containsKey(name)) {\n\t\t\treturn nameId.get(name);\n\t\t}\n\t\tnameId.put(name, nameId.size() + 1);\n\t\treturn nameId.size();\n\t}\n\n\tpublic static void addId(int deep, int id) {\n\t\tdepSet.get(deep).add(id);\n\t}\n\n\tpublic static void removeId(int deep, int id) {\n\t\tdepSet.get(deep).remove(id);\n\t}\n\n\tpublic static int sizeOfDeep(int deep) {\n\t\tif (deep > n) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn depSet.get(deep).size();\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addQuestion(int u, int ansi, int k) {\n\t\tnextq[++cntq] = headq[u];\n\t\tansiq[cntq] = ansi;\n\t\tkq[cntq] = k;\n\t\theadq[u] = cntq;\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tsiz[u] = 1;\n\t\tdep[u] = dep[f] + 1;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tdfs1(tog[e], u);\n\t\t}\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tsiz[u] += siz[v];\n\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\tson[u] = v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void effect(int u) {\n\t\taddId(dep[u], id[u]);\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\teffect(tog[e]);\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tremoveId(dep[u], id[u]);\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tcancel(tog[e]);\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\taddId(dep[u], id[u]);\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t\tfor (int i = headq[u]; i > 0; i = nextq[i]) {\n\t\t\tans[ansiq[i]] = sizeOfDeep(dep[u] + kq[i]);\n\t\t}\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tString name;\n\t\tint father;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tname = io.next();\n\t\t\tfather = io.nextInt();\n\t\t\tid[i] = getNameId(name);\n\t\t\tif (father == 0) {\n\t\t\t\troot[i] = true;\n\t\t\t} else {\n\t\t\t\taddEdge(father, i);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (root[i]) {\n\t\t\t\tdfs1(i, 0);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 0; i <= n; i++) {\n\t\t\tdepSet.add(new HashSet<>());\n\t\t}\n\t\tm = io.nextInt();\n\t\tfor (int i = 1, node, k; i <= m; i++) {\n\t\t\tnode = io.nextInt();\n\t\t\tk = io.nextInt();\n\t\t\taddQuestion(node, i, k);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (root[i]) {\n\t\t\t\tdfs2(i, 0);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tio.println(ans[i]);\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_DifferntName2.java`\n\n```java\npackage class163;\n\n// 不同名字数量，C++版\n// 一共有n个节点，编号1~n，给定每个节点的名字和父亲节点编号\n// 名字是string类型，如果父亲节点编号为0，说明当前节点是某棵树的头节点\n// 注意，n个节点组成的是森林结构，可能有若干棵树\n// 一共有m条查询，每条查询 x k，含义如下\n// 以x为头的子树上，到x距离为k的所有节点中，打印不同名字的数量\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF246E\n// 测试链接 : https://codeforces.com/problemset/problem/246/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//\n//unordered_map<string, int> nameId;\n//bool root[MAXN];\n//int id[MAXN];\n//\n//int headg[MAXN];\n//int nextg[MAXN];\n//int tog[MAXN];\n//int cntg;\n//\n//int headq[MAXN];\n//int nextq[MAXN];\n//int ansiq[MAXN];\n//int kq[MAXN];\n//int cntq;\n//\n//int fa[MAXN];\n//int siz[MAXN];\n//int dep[MAXN];\n//int son[MAXN];\n//\n//vector<unordered_set<int>> depSet;\n//int ans[MAXN];\n//\n//int getNameId(const string &name) {\n//    if (nameId.find(name) != nameId.end()) {\n//        return nameId[name];\n//    }\n//    int newId = nameId.size() + 1;\n//    nameId[name] = newId;\n//    return newId;\n//}\n//\n//void addId(int deep, int id) {\n//    depSet[deep].insert(id);\n//}\n//\n//void removeId(int deep, int id) {\n//    depSet[deep].erase(id);\n//}\n//\n//int sizeOfDeep(int deep) {\n//    if (deep > n) {\n//        return 0;\n//    }\n//    return (int)depSet[deep].size();\n//}\n//\n//void addEdge(int u, int v) {\n//    nextg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    headg[u] = cntg;\n//}\n//\n//void addQuestion(int u, int ansi, int k) {\n//    nextq[++cntq] = headq[u];\n