 cin >> node >> k;\n//        addQuestion(node, i, k);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (root[i]) {\n//            dfs2(i, 0);\n//        }\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_BloodCousins1.java`\n\n```java\npackage class163;\n\n// 表亲数量，java版\n// 一共有n个节点，编号1~n，给定每个节点的父亲节点编号，父亲节点为0，说明当前节点是某棵树的头\n// 注意，n个节点组成的是森林结构，可能有若干棵树\n// 一共有m条查询，每条查询 x k，含义如下\n// 如果x往上走k的距离，没有祖先节点，打印0\n// 如果x往上走k的距离，能找到祖先节点a，那么从a往下走k的距离，除了x之外，可能还有其他节点\n// 这些节点叫做x的k级表亲，打印这个表亲的数量\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF208E\n// 测试链接 : https://codeforces.com/problemset/problem/208/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code05_BloodCousins1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\tpublic static boolean[] root = new boolean[MAXN];\n\n\t// 链式前向星\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN];\n\tpublic static int[] tog = new int[MAXN];\n\tpublic static int cntg;\n\n\t// 问题列表\n\tpublic static int[] headq = new int[MAXN];\n\tpublic static int[] nextq = new int[MAXN];\n\tpublic static int[] ansiq = new int[MAXN];\n\tpublic static int[] kq = new int[MAXN];\n\tpublic static int cntq;\n\n\t// 树链剖分\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\t// 树上启发式合并\n\tpublic static int[] depCnt = new int[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addQuestion(int u, int i, int k) {\n\t\tnextq[++cntq] = headq[u];\n\t\tansiq[cntq] = i;\n\t\tkq[cntq] = k;\n\t\theadq[u] = cntq;\n\t}\n\n\tpublic static void dfs1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tdfs1(tog[e], u);\n\t\t}\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tsiz[u] += siz[v];\n\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\tson[u] = v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int kAncestor(int u, int k) {\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (k >= 1 << p) {\n\t\t\t\tk -= 1 << p;\n\t\t\t\tu = stjump[u][p];\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void effect(int u) {\n\t\tdepCnt[dep[u]]++;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\teffect(tog[e]);\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tdepCnt[dep[u]]--;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tcancel(tog[e]);\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\tdepCnt[dep[u]]++;\n\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\tv = tog[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t\tfor (int i = headq[u]; i > 0; i = nextq[i]) {\n\t\t\tans[ansiq[i]] = depCnt[dep[u] + kq[i]];\n\t\t}\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tfor (int i = 1, father; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tfather = (int) in.nval;\n\t\t\tif (father == 0) {\n\t\t\t\troot[i] = true;\n\t\t\t} else {\n\t\t\t\taddEdge(father, i);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (root[i]) {\n\t\t\t\tdfs1(i, 0);\n\t\t\t}\n\t\t}\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1, u, k, kfather; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t\tkfather = kAncestor(u, k);\n\t\t\tif (kfather != 0) {\n\t\t\t\taddQuestion(kfather, i, k);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (root[i]) {\n\t\t\t\tdfs2(i, 0);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (ans[i] == 0) {\n\t\t\t\tout.print("0 ");\n\t\t\t} else {\n\t\t\t\tout.print((ans[i] - 1) + " ");\n\t\t\t}\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code05_BloodCousins2.java`\n\n```java\npackage class163;\n\n// 表亲数量，C++版\n// 一共有n个节点，编号1~n，给定每个节点的父亲节点编号，父亲节点为0，说明当前节点是某棵树的头\n// 注意，n个节点组成的是森林结构，可能有若干棵树\n// 一共有m条查询，每条查询 x k，含义如下\n// 如果x往上走k的距离，没有祖先节点，打印0\n// 如果x往上走k的距离，能找到祖先节点a，那么从a往下走k的距离，除了x之外，可能还有其他节点\n// 这些节点叫做x的k级表亲，打印这个表亲的数量\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF208E\n// 测试链接 : https://codeforces.com/problemset/problem/208/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXP = 20;\n//int n, m;\n//bool root[MAXN];\n//\n//int headg[MAXN];\n//int nextg[MAXN];\n//int tog[MAXN];\n//int cntg;\n//\n//int headq[MAXN];\n//int nextq[MAXN];\n//int ansiq[MAXN];\n//int kq[MAXN];\n//int cntq;\n//\n//int siz[MAXN];\n//int dep[MAXN];\n//int son[MAXN];\n//int stjump[MAXN][MAXP];\n//\n//int depCnt[MAXN];\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nextg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    headg[u] = cntg;\n//}\n//\n//void addQuestion(int u, int i, int k) {\n//    nextq[++cntq] = headq[u];\n//    ansiq[cntq] = i;\n//    kq[cntq] = k;\n//    headq[u] = cntq;\n//}\n//\n//void dfs1(int u, int fa) {\n//    siz[u] = 1;\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[ stjump[u][p - 1] ][p - 1];\n//    }\n//    for (int e = headg[u]; e > 0; e = nextg[e]) {\n//        dfs1(tog[e], u);\n//    }\n//    for (int e = headg[u], v; e > 0; e = nextg[e]) {\n//        v = tog[e];\n//        siz[u] += siz[v];\n//        if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//            son[u] = v;\n//        }\n//    }\n//}\n//\n//int kAncestor(int u, int k) {\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (k >= (1 << p)) {\n//            k -= (1 << p);\n//            u = stjump[u][p];\n//        }\n//    }\n//    return u;\n//}\n//\n//void effect(int u) {\n//    depCnt[dep[u]]++;\n//    for (int e = headg[u]; e > 0; e = nextg[e]) {\n//        effect(tog[e]);\n//    }\n//}\n//\n//void cancel(int u) {\n//    depCnt[dep[u]]--;\n//    for (int e = headg[u]; e > 0; e = nextg[e]) {\n//        cancel(tog[e]);\n//    }\n//}\n//\n//void dfs2(int u, int keep) {\n//    for (int e = headg[u], v; e > 0; e = nextg[e]) {\n//        v = tog[e];\n//        if (v != son[u]) {\n//            dfs2(v, 0);\n//        }\n//    }\n//    if (son[u] != 0) {\n//        dfs2(son[u], 1);\n//    }\n//    depCnt[dep[u]]++;\n//    for (int e = headg[u], v; e > 0; e = nextg[e]) {\n//        v = tog[e];\n//        if (v != son[u]) {\n//            effect(v);\n//        }\n//    }\n//    for (int i = headq[u]; i > 0; i = nextq[i]) {\n//    \tans[ansiq[i]] = depCnt[dep[u] + kq[i]];\n//    }\n//    if (keep == 0) {\n//        cancel(u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, father; i <= n; i++) {\n//        cin >> father;\n//        if (father == 0) {\n//        \troot[i] = true;\n//        } else {\n//            addEdge(father, i);\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (root[i]) {\n//            dfs1(i, 0);\n//        }\n//    }\n//    cin >> m;\n//    for (int i = 1, u, k, kfather; i <= m; i++) {\n//        cin >> u >> k;\n//        kfather = kAncestor(u, k);\n//        if (kfather != 0) {\n//            addQuestion(kfather, i, k);\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (root[i]) {\n//            dfs2(i, 0);\n//        }\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        if (ans[i] == 0) {\n//            cout << "0 ";\n//        } else {\n//            cout << ans[i] - 1 << " ";\n//        }\n//    }\n//    cout << "\\n";\n//    return 0;\n//}\n```\n\n### `Code06_RearrangePalindrome1.java`\n\n```java\npackage class163;\n\n// 最长重排回文路径，java版\n// 一共有n个节点，编号1~n，给定n-1条边，所有节点连成一棵树，1号节点为树头\n// 每条边上都有一个字符，字符范围[a~v]，字符一共22种，重排回文路径的定义如下\n// 节点a到节点b的路径，如果所有边的字符收集起来，能重新排列成回文串，该路径是重排回文路径\n// 打印1~n每个节点为头的子树中，最长重排回文路径的长度\n// 1 <= n <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF741D\n// 测试链接 : https://codeforces.com/problemset/problem/741/D\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_RearrangePalindrome1 {\n\n\tpublic static int MAXN = 500001;\n\t// 字符种类最多22种\n\tpublic static int MAXV = 22;\n\tpublic static int n;\n\n\t// 链式前向星\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int[] weight = new int[MAXN];\n\tpublic static int cnt = 0;\n\n\t// 树链剖分\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] eor = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\n\t// 树上启发式合并\n\tpublic static int[] maxdep = new int[1 << MAXV];\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\tweight[cnt] = w;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static void dfs1(int u, int d, int x) {\n\t\tsiz[u] = 1;\n\t\tdep[u] = d;\n\t\teor[u] = x;\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tdfs1(to[e], d + 1, x ^ (1 << weight[e]));\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tsiz[u] += siz[v];\n\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\tson[u] = v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void effect(int u) {\n\t\tmaxdep[eor[u]] = Math.max(maxdep[eor[u]], dep[u]);\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\teffect(to[e]);\n\t\t}\n\t}\n\n\tpublic static void cancel(int u) {\n\t\tmaxdep[eor[u]] = 0;\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tcancel(to[e]);\n\t\t}\n\t}\n\n\tpublic static void answerFromLight(int light, int u) {\n\t\tif (maxdep[eor[light]] != 0) {\n\t\t\tans[u] = Math.max(ans[u], maxdep[eor[light]] + dep[light] - dep[u] * 2);\n\t\t}\n\t\tfor (int i = 0; i < MAXV; i++) {\n\t\t\tif (maxdep[eor[light] ^ (1 << i)] != 0) {\n\t\t\t\tans[u] = Math.max(ans[u], maxdep[eor[light] ^ (1 << i)] + dep[light] - dep[u] * 2);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[light]; e > 0; e = next[e]) {\n\t\t\tanswerFromLight(to[e], u);\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int keep) {\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\tdfs2(v, 0);\n\t\t\t}\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], 1);\n\t\t}\n\t\t// 每一个儿子的子树，里得到的答案\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tans[u] = Math.max(ans[u], ans[to[e]]);\n\t\t}\n\t\t// 选择当前节点，再选择重儿子树上的任意一点，得到的答案\n\t\t// 枚举所有可能得到的异或值\n\t\tif (maxdep[eor[u]] != 0) {\n\t\t\tans[u] = Math.max(ans[u], maxdep[eor[u]] - dep[u]);\n\t\t}\n\t\tfor (int i = 0; i < MAXV; i++) {\n\t\t\tif (maxdep[eor[u] ^ (1 << i)] != 0) {\n\t\t\t\tans[u] = Math.max(ans[u], maxdep[eor[u] ^ (1 << i)] - dep[u]);\n\t\t\t}\n\t\t}\n\t\t// 当前点的异或值，更新最大深度信息\n\t\tmaxdep[eor[u]] = Math.max(maxdep[eor[u]], dep[u]);\n\t\t// 选择遍历过的部分里的任意一点，再选择当前遍历到的子树里的任意一点，得到的答案\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != son[u]) {\n\t\t\t\tanswerFromLight(v, u);\n\t\t\t\teffect(v);\n\t\t\t}\n\t\t}\n\t\tif (keep == 0) {\n\t\t\tcancel(u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 2, fth, edg; i <= n; i++) {\n\t\t\tfth = in.nextInt();\n\t\t\tedg = in.nextChar() - 'a';\n\t\t\taddEdge(fth, i, edg);\n\t\t}\n\t\tdfs1(1, 1, 0);\n\t\tdfs2(1, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic double nextDouble() throws IOException {\n\t\t\tdouble num = 0, div = 1;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != '.' && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tif (b == '.') {\n\t\t\t\tb = readByte();\n\t\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\t\tnum += (b - '0') / (div *= 10);\n\t\t\t\t\tb = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_RearrangePalindrome2.java`\n\n```java\npackage class163;\n\n// 最长重排回文路径，C++版\n// 一共有n个节点，编号1~n，给定n-1条边，所有节点连成一棵树，1号节点为树头\n// 每条边上都有一个字符，字符范围[a~v]，字符一共22种，重排回文路径的定义如下\n// 节点a到节点b的路径，如果所有边的字符收集起来，能重新排列成回文串，该路径是重排回文路径\n// 打印1~n每个节点为头的子树中，最长重排回文路径的长度\n// 1 <= n <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF741D\n// 测试链接 : https://codeforces.com/problemset/problem/741/D\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXV = 22;\n//int n;\n//int head[MAXN];\n//int nxt[MAXN];\n//int to[MAXN];\n//int weight[MAXN];\n//int cnt = 0;\n//int siz[MAXN];\n//int dep[MAXN];\n//int eor[MAXN];\n//int son[MAXN];\n//int maxdep[1 << MAXV];\n//int ans[MAXN];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cnt] = head[u];\n//    to[cnt] = v;\n//    weight[cnt] = w;\n//    head[u] = cnt;\n//}\n//\n//void dfs1(int u, int d, int x) {\n//    siz[u] = 1;\n//    dep[u] = d;\n//    eor[u] = x;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        dfs1(to[e], d + 1, x ^ (1 << weight[e]));\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        siz[u] += siz[v];\n//        if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//            son[u] = v;\n//        }\n//    }\n//}\n//\n//void effect(int u) {\n//    maxdep[eor[u]] = max(maxdep[eor[u]], dep[u]);\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        effect(to[e]);\n//    }\n//}\n//\n//void cancel(int u) {\n//    maxdep[eor[u]] = 0;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        cancel(to[e]);\n//    }\n//}\n//\n//void answerFromLight(int light, int u) {\n//    if (maxdep[eor[light]] != 0) {\n//        ans[u] = max(ans[u], maxdep[eor[light]] + dep[light] - dep[u] * 2);\n//    }\n//    for (int i = 0; i < MAXV; i++) {\n//        if (maxdep[eor[light] ^ (1 << i)] != 0) {\n//            ans[u] = max(ans[u], maxdep[eor[light] ^ (1 << i)] + dep[light] - dep[u] * 2);\n//        }\n//    }\n//    for (int e = head[light]; e > 0; e = nxt[e]) {\n//        answerFromLight(to[e], u);\n//    }\n//}\n//\n//void dfs2(int u, int keep) {\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != son[u]) {\n//            dfs2(v, 0);\n//        }\n//    }\n//    if (son[u] != 0) {\n//        dfs2(son[u], 1);\n//    }\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        ans[u] = max(ans[u], ans[to[e]]);\n//    }\n//    if (maxdep[eor[u]] != 0) {\n//        ans[u] = max(ans[u], maxdep[eor[u]] - dep[u]);\n//    }\n//    for (int i = 0; i < MAXV; i++) {\n//        if (maxdep[eor[u] ^ (1 << i)] != 0) {\n//            ans[u] = max(ans[u], maxdep[eor[u] ^ (1 << i)] - dep[u]);\n//        }\n//    }\n//    maxdep[eor[u]] = max(maxdep[eor[u]], dep[u]);\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != son[u]) {\n//            answerFromLight(v, u);\n//            effect(v);\n//        }\n//    }\n//    if (keep == 0) {\n//        cancel(u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    int fth;\n//    int edg;\n//    char c;\n//    for (int i = 2; i <= n; i++) {\n//        cin >> fth;\n//        cin >> c;\n//        edg = c - 'a';\n//        addEdge(fth, i, edg);\n//    }\n//    dfs1(1, 1, 0);\n//    dfs2(1, 0);\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] << " ";\n//    }\n//    cout << "\\n";\n//    return 0;\n//}\n```\n\n### `Code07_Forest1.java`\n\n```java\npackage class163;\n\n// 森林，java版\n// 一共有n个节点，编号1~n，初始时给定m条边，所有节点可能组成森林结构\n// 每个节点都给定非负的点权，一共有t条操作，每条操作是如下两种类型中的一种\n// 操作 Q x y k : 点x到点y路径上所有的权值中，打印第k小的权值是多少\n//                题目保证x和y联通，并且路径上至少有k个点\n// 操作 L x y   : 点x和点y之间连接一条边\n//                题目保证操作后，所有节点仍然是森林\n// 题目要求强制在线，请不要使用离线算法\n// 1 <= n、m、t <= 8 * 10^4    点权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3302\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code07_Forest1 {\n\n\tpublic static int MAXN = 80001;\n\tpublic static int MAXT = MAXN * 110;\n\tpublic static int MAXP = 20;\n\tpublic static int testcase;\n\tpublic static int n, m, t;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int diff;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] left = new int[MAXT];\n\tpublic static int[] right = new int[MAXT];\n\tpublic static int[] siz = new int[MAXT];\n\tpublic static int cntt = 0;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int[] treeHead = new int[MAXN];\n\tpublic static int[] setSiz = new int[MAXN];\n\n\t// 来自讲解158，题目4\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = diff, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\t// 来自讲解158，题目4\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 来自讲解158，题目4\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tsiz[rt] = siz[i] + 1;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[rt] = insert(jobi, l, mid, left[rt]);\n\t\t\t} else {\n\t\t\t\tright[rt] = insert(jobi, mid + 1, r, right[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 来自讲解158，题目4\n\tpublic static int query(int jobk, int l, int r, int u, int v, int lca, int lcafa) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint lsize = siz[left[u]] + siz[left[v]] - siz[left[lca]] - siz[left[lcafa]];\n\t\tint mid = (l + r) / 2;\n\t\tif (lsize >= jobk) {\n\t\t\treturn query(jobk, l, mid, left[u], left[v], left[lca], left[lcafa]);\n\t\t} else {\n\t\t\treturn query(jobk - lsize, mid + 1, r, right[u], right[v], right[lca], right[lcafa]);\n\t\t}\n\t}\n\n\t// 来自讲解158，题目4\n\tpublic static int lca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\t// 来自讲解158，题目4\n\tpublic static int queryKth(int x, int y, int k) {\n\t\tint xylca = lca(x, y);\n\t\tint lcafa = stjump[xylca][0];\n\t\tint i = query(k, 1, diff, root[x], root[y], root[xylca], root[lcafa]);\n\t\treturn sorted[i];\n\t}\n\n\t// 递归版，C++可以通过，java无法通过，递归会爆栈\n\tpublic static void dfs1(int u, int fa, int treeh) {\n\t\troot[u] = insert(arr[u], 1, diff, root[fa]);\n\t\tdep[u] = dep[fa] + 1;\n\t\ttreeHead[u] = treeh;\n\t\tsetSiz[treeh]++;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u, treeh);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版，都可以通过\n\t// 讲解118，详解了从递归版改迭代版\n\tpublic static int[][] stack = new int[MAXN][4];\n\n\tpublic static int stackSize, cur, father, treehead, edge;\n\n\tpublic static void push(int cur, int father, int treehead, int edge) {\n\t\tstack[stackSize][0] = cur;\n\t\tstack[stackSize][1] = father;\n\t\tstack[stackSize][2] = treehead;\n\t\tstack[stackSize][3] = edge;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tcur = stack[stackSize][0];\n\t\tfather = stack[stackSize][1];\n\t\ttreehead = stack[stackSize][2];\n\t\tedge = stack[stackSize][3];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2(int i, int fa, int treeh) {\n\t\tstackSize = 0;\n\t\tpush(i, fa, treeh, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\troot[cur] = insert(arr[cur], 1, diff, root[father]);\n\t\t\t\tdep[cur] = dep[father] + 1;\n\t\t\t\ttreeHead[cur] = treehead;\n\t\t\t\tsetSiz[treehead]++;\n\t\t\t\tstjump[cur][0] = father;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[cur][p] = stjump[stjump[cur][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\tedge = head[cur];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(cur, father, treehead, edge);\n\t\t\t\tif (to[edge] != father) {\n\t\t\t\t\tpush(to[edge], cur, treehead, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// x所在的树和y所在的树，合并成一棵树\n\tpublic static void connect(int x, int y) {\n\t\taddEdge(x, y);\n\t\taddEdge(y, x);\n\t\tint fx = treeHead[x];\n\t\tint fy = treeHead[y];\n\t\tif (setSiz[fx] >= setSiz[fy]) {\n\t\t\tdfs2(y, x, fx); // 调用dfs1的迭代版\n\t\t} else {\n\t\t\tdfs2(x, y, fy); // 调用dfs1的迭代版\n\t\t}\n\t}\n\n\t// 离散化\n\t// 每棵子树建立可持久化线段树\n\t// 记录每个节点的所在子树的头节点\n\t// 记录每棵子树的大小\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\tdiff = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[diff] != sorted[i]) {\n\t\t\t\tsorted[++diff] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = kth(arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (treeHead[i] == 0) {\n\t\t\t\tdfs2(i, 0, i); // 调用dfs1的迭代版\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\ttestcase = in.nextInt();\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tt = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tprepare();\n\t\tchar op;\n\t\tint x, y, k, lastAns = 0;\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\top = in.nextChar();\n\t\t\tx = in.nextInt() ^ lastAns;\n\t\t\ty = in.nextInt() ^ lastAns;\n\t\t\tif (op == 'Q') {\n\t\t\t\tk = in.nextInt() ^ lastAns;\n\t\t\t\tlastAns = queryKth(x, y, k);\n\t\t\t\tout.println(lastAns);\n\t\t\t} else {\n\t\t\t\tconnect(x, y);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic double nextDouble() throws IOException {\n\t\t\tdouble num = 0, div = 1;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != '.' && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tif (b == '.') {\n\t\t\t\tb = readByte();\n\t\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\t\tnum += (b - '0') / (div *= 10);\n\t\t\t\t\tb = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_Forest2.java`\n\n```java\npa