{\n//    int p = lg2[r - l + 1];\n//    int ans = max(stmax[l][p], stmax[r - (1 << p) + 1][p]);\n//    return ans;\n//}\n//\n//int lca(int a, int b) {\n//    if (dep[a] < dep[b]) {\n//        int tmp = a;\n//        a = b;\n//        b = tmp;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (dep[stjump[a][p]] >= dep[b]) {\n//            a = stjump[a][p];\n//        }\n//    }\n//    if (a == b) {\n//        return a;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (stjump[a][p] != stjump[b][p]) {\n//            a = stjump[a][p];\n//            b = stjump[b][p];\n//        }\n//    }\n//    return stjump[a][0];\n//}\n//\n//int query(int l, int r) {\n//    int x = seg[dfnmin(l, r)];\n//    int y = seg[dfnmax(l, r)];\n//    return nodeKey[lca(x, y)];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int test = 1; test <= t; test++) {\n//        cin >> n >> m >> q;\n//        for (int i = 1; i <= m; i++) {\n//            cin >> edge[i].u >> edge[i].v;\n//            edge[i].w = i;\n//        }\n//        clear();\n//        kruskalRebuild();\n//        dfs(cntu, 0);\n//        buildst();\n//        for (int i = 1, l, r; i <= q; i++) {\n//            cin >> l >> r;\n//            if (l == r) {\n//                cout << 0 << " ";\n//            } else {\n//                cout << query(l, r) << " ";\n//            }\n//        }\n//        cout << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_GraphQueries1.java`\n\n```java\npackage class164;\n\n// 删边和查询，java版\n// 图里有n个点，m条无向边，初始时点权都不同，图里可能有若干个连通的部分\n// 一共有q条操作，每条操作是如下两种类型中的一种\n// 操作 1 x : 点x所在的连通区域中，假设点y拥有最大的点权\n//            打印y的点权，然后把y的点权修改为0\n// 操作 2 x : 删掉第x条边\n// 1 <= n <= 2 * 10^5    1 <= m <= 3 * 10^5    1 <= q <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1416D\n// 测试链接 : https://codeforces.com/problemset/problem/1416/D\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.util.Arrays;\n\npublic class Code06_GraphQueries1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXK = 400001;\n\tpublic static int MAXM = 300001;\n\tpublic static int MAXQ = 500001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q;\n\n\t// 节点值的数组，需要记录，线段树也要使用\n\tpublic static int[] node = new int[MAXN];\n\t// 所有边的数组，逆序处理删除操作，设置每条边的权值\n\tpublic static int[][] edge = new int[MAXM][3];\n\t// 记录所有操作\n\tpublic static int[][] ques = new int[MAXQ][2];\n\n\t// 并查集\n\tpublic static int[] father = new int[MAXK];\n\n\t// Kruskal重构树\n\tpublic static int[] head = new int[MAXK];\n\tpublic static int[] next = new int[MAXK];\n\tpublic static int[] to = new int[MAXK];\n\tpublic static int cntg = 0;\n\tpublic static int[] nodeKey = new int[MAXK];\n\tpublic static int cntu;\n\n\t// 倍增表\n\tpublic static int[][] stjump = new int[MAXK][MAXP];\n\t// 子树上的叶节点个数\n\tpublic static int[] leafsiz = new int[MAXK];\n\t// 子树上叶节点的dfn序号最小值\n\tpublic static int[] leafDfnMin = new int[MAXK];\n\t// leafseg[i] = j，表示dfn序号为i的叶节点，原始编号为j\n\tpublic static int[] leafseg = new int[MAXK];\n\t// dfn的计数\n\tpublic static int cntd = 0;\n\n\t// 线段树的下标是dfn序号，维护范围内，拥有最大点权的dfn序号\n\tpublic static int[] maxValueDfn = new int[MAXN << 2];\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tif (ques[i][0] == 2) {\n\t\t\t\tedge[ques[i][1]][2] = -1;\n\t\t\t}\n\t\t}\n\t\tint weight = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tif (edge[i][2] != -1) {\n\t\t\t\tedge[i][2] = ++weight;\n\t\t\t}\n\t\t}\n\t\tfor (int i = q; i >= 1; i--) {\n\t\t\tif (ques[i][0] == 2) {\n\t\t\t\tedge[ques[i][1]][2] = ++weight;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void kruskalRebuild() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tArrays.sort(edge, 1, m + 1, (a, b) -> a[2] - b[2]);\n\t\tcntu = n;\n\t\tfor (int i = 1, fx, fy; i <= m; i++) {\n\t\t\tfx = find(edge[i][0]);\n\t\t\tfy = find(edge[i][1]);\n\t\t\tif (fx != fy) {\n\t\t\t\tfather[fx] = father[fy] = ++cntu;\n\t\t\t\tfather[cntu] = cntu;\n\t\t\t\tnodeKey[cntu] = edge[i][2];\n\t\t\t\taddEdge(cntu, fx);\n\t\t\t\taddEdge(cntu, fy);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tdfs(to[e], u);\n\t\t}\n\t\tif (u <= n) {\n\t\t\tleafsiz[u] = 1;\n\t\t\tleafDfnMin[u] = ++cntd;\n\t\t\tleafseg[cntd] = u;\n\t\t} else {\n\t\t\tleafsiz[u] = 0;\n\t\t\tleafDfnMin[u] = n + 1;\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tleafsiz[u] += leafsiz[to[e]];\n\t\t\tleafDfnMin[u] = Math.min(leafDfnMin[u], leafDfnMin[to[e]]);\n\t\t}\n\t}\n\n\tpublic static int getAncestor(int u, int limit) {\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[u][p] > 0 && nodeKey[stjump[u][p]] <= limit) {\n\t\t\t\tu = stjump[u][p];\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void up(int i) {\n\t\tint l = i << 1;\n\t\tint r = i << 1 | 1;\n\t\tif (node[leafseg[maxValueDfn[l]]] > node[leafseg[maxValueDfn[r]]]) {\n\t\t\tmaxValueDfn[i] = maxValueDfn[l];\n\t\t} else {\n\t\t\tmaxValueDfn[i] = maxValueDfn[r];\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tmaxValueDfn[i] = l;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\t// dfn序号为jobi，点权更新成jobv\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tnode[leafseg[jobi]] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\t// dfn范围[jobl..jobr]，哪个节点拥有最大点权，返回该节点的dfn序号\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn maxValueDfn[i];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tint ldfn = 0, rdfn = 0;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tldfn = query(jobl, jobr, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trdfn = query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tif (node[leafseg[ldfn]] > node[leafseg[rdfn]]) {\n\t\t\t\treturn ldfn;\n\t\t\t} else {\n\t\t\t\treturn rdfn;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int queryAndUpdate(int x, int limit) {\n\t\tint anc = getAncestor(x, limit);\n\t\tint dfn = query(leafDfnMin[anc], leafDfnMin[anc] + leafsiz[anc] - 1, 1, n, 1);\n\t\tint ans = node[leafseg[dfn]];\n\t\tupdate(dfn, 0, 1, n, 1);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tq = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnode[i] = io.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tedge[i][0] = io.nextInt();\n\t\t\tedge[i][1] = io.nextInt();\n\t\t\tedge[i][2] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tques[i][0] = io.nextInt();\n\t\t\tques[i][1] = io.nextInt();\n\t\t}\n\t\tprepare();\n\t\tkruskalRebuild();\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tif (i == father[i]) {\n\t\t\t\tdfs(i, 0);\n\t\t\t}\n\t\t}\n\t\tbuild(1, n, 1);\n\t\tint limit = m;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tif (ques[i][0] == 1) {\n\t\t\t\tio.writelnInt(queryAndUpdate(ques[i][1], limit));\n\t\t\t} else {\n\t\t\t\tlimit--;\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_GraphQueries2.java`\n\n```java\npackage class164;\n\n// 删边和查询，C++版\n// 图里有n个点，m条无向边，初始时点权都不同，图里可能有若干个连通的部分\n// 一共有q条操作，每条操作是如下两种类型中的一种\n// 操作 1 x : 点x所在的连通区域中，假设点y拥有最大的点权\n//            打印y的点权，然后把y的点权修改为0\n// 操作 2 x : 删掉第x条边\n// 1 <= n <= 2 * 10^5    1 <= m <= 3 * 10^5    1 <= q <= 5 * 10^5\n// 测试链接 : https://w