= 0, rdfn = 0;\n//        if (jobl <= mid) {\n//        \tldfn = query(jobl, jobr, l, mid, i << 1);\n//        }\n//        if (jobr > mid) {\n//        \trdfn = query(jobl, jobr, mid + 1, r, i << 1 | 1);\n//        }\n//        if (node[leafseg[ldfn]] > node[leafseg[rdfn]]) {\n//            return ldfn;\n//        } else {\n//            return rdfn;\n//        }\n//    }\n//}\n//\n//int queryAndUpdate(int x, int limit) {\n//    int anc = getAncestor(x, limit);\n//    int dfn = query(leafDfnMin[anc], leafDfnMin[anc] + leafsiz[anc] - 1, 1, n, 1);\n//    int ans = node[leafseg[dfn]];\n//    update(dfn, 0, 1, n, 1);\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> q;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> node[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> edge[i].u >> edge[i].v;\n//        edge[i].w = 0;\n//    }\n//    for (int i = 1; i <= q; i++) {\n//        cin >> ques[i][0] >> ques[i][1];\n//    }\n//    prepare();\n//    kruskalRebuild();\n//    for (int i = 1; i <= cntu; i++) {\n//        if (i == father[i]) {\n//            dfs(i, 0);\n//        }\n//    }\n//    build(1, n, 1);\n//    int limit = m;\n//    for (int i = 1; i <= q; i++) {\n//        if (ques[i][0] == 1) {\n//            cout << queryAndUpdate(ques[i][1], limit) << "\\n";\n//        } else {\n//            limit--;\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_Peaks1.java`\n\n```java\npackage class164;\n\n// 边权上限内第k大点权，java版\n// 图里有n个点，m条无向边，点有点权，边有边权，图里可能有若干个连通的部分\n// 一共有q条查询，查询格式如下\n// 查询 u x k : 从点u开始，只能走过权值<=x的边\n//              所有能到达的点中，打印第k大点权，如果不存在打印-1\n// 1 <= n <= 10^5\n// 0 <= m、q <= 5 * 10^5\n// 1 <= 点权、边权 <= 10^9\n// 本题要求强制在线，具体规定请打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P7834\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是通过不了\n// 因为这道题根据C++的运行空间，制定通过标准，根本没考虑java的用户\n// 想通过用C++实现，本节课Code07_Peaks2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.util.Arrays;\n\npublic class Code07_Peaks1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXK = 200001;\n\tpublic static int MAXM = 500001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q, s;\n\n\tpublic static int[] node = new int[MAXN];\n\tpublic static int[] sorted = new int[MAXN];\n\tpublic static int[][] edge = new int[MAXM][3];\n\n\t// 并查集\n\tpublic static int[] father = new int[MAXK];\n\n\t// Kruskal重构树\n\tpublic static int[] head = new int[MAXK];\n\tpublic static int[] next = new int[MAXK];\n\tpublic static int[] to = new int[MAXK];\n\tpublic static int cntg = 0;\n\tpublic static int[] nodeKey = new int[MAXK];\n\tpublic static int cntu;\n\n\t// 倍增表\n\tpublic static int[][] stjump = new int[MAXK][MAXP];\n\t// 子树上的叶节点个数\n\tpublic static int[] leafsiz = new int[MAXK];\n\t// 子树上叶节点的dfn序号最小值\n\tpublic static int[] leafDfnMin = new int[MAXK];\n\t// leafseg[i] = j，表示dfn序号为i的叶节点，原始编号为j\n\tpublic static int[] leafseg = new int[MAXK];\n\t// dfn的计数\n\tpublic static int cntd = 0;\n\n\t// 可持久化线段树\n\t// 线段树的下标为某个数字，所以是值域线段树\n\t// 数值范围[l..r]上，一共有几个数字，就是numcnt的含义\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] numcnt = new int[MAXT];\n\tpublic static int cntt = 0;\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = node[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\ts = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[s] != sorted[i]) {\n\t\t\t\tsorted[++s] = sorted[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnode[i] = kth(node[i]);\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void kruskalRebuild() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t}\n\t\tArrays.sort(edge, 1, m + 1, (a, b) -> a[2] - b[2]);\n\t\tcntu = n;\n\t\tfor (int i = 1, fx, fy; i <= m; i++) {\n\t\t\tfx = find(edge[i][0]);\n\t\t\tfy = find(edge[i][1]);\n\t\t\tif (fx != fy) {\n\t\t\t\tfather[fx] = father[fy] = ++cntu;\n\t\t\t\tfather[cntu] = cntu;\n\t\t\t\tnodeKey[cntu] = edge[i][2];\n\t\t\t\taddEdge(cntu, fx);\n\t\t\t\taddEdge(cntu, fy);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tdfs(to[e], u);\n\t\t}\n\t\tif (u <= n) {\n\t\t\tleafsiz[u] = 1;\n\t\t\tleafDfnMin[u] = ++cntd;\n\t\t\tleafseg[cntd] = u;\n\t\t} else {\n\t\t\tleafsiz[u] = 0;\n\t\t\tleafDfnMin[u] = n + 1;\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tleafsiz[u] += leafsiz[to[e]];\n\t\t\tleafDfnMin[u] = Math.min(leafDfnMin[u], leafDfnMin[to[e]]);\n\t\t}\n\t}\n\n\t// 可持久化线段树的build\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tnumcnt[rt] = 0;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 数值范围[l..r]，加了一个数字jobi，生成新版本的可持久化线段树\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\tnumcnt[rt] = numcnt[i] + 1;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = insert(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = insert(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\t// 可持久化线段树，前版本pre，后版本post，两个版本做差，得到数值范围[l..r]的词频\n\t// 查询这个数值范围上，第jobk大的数字是什么\n\tpublic static int query(int jobk, int l, int r, int pre, int post) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint rsize = numcnt[rs[post]] - numcnt[rs[pre]];\n\t\tint mid = (l + r) / 2;\n\t\tif (rsize >= jobk) {\n\t\t\treturn query(jobk, mid + 1, r, rs[pre], rs[post]);\n\t\t} else {\n\t\t\treturn query(jobk - rsize, l, mid, ls[pre], ls[post]);\n\t\t}\n\t}\n\n\tpublic static int kthMax(int u, int x, int k) {\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[u][p] > 0 && nodeKey[stjump[u][p]] <= x) {\n\t\t\t\tu = stjump[u][p];\n\t\t\t}\n\t\t}\n\t\tif (leafsiz[u] < k) {\n\t\t\treturn 0;\n\t\t}\n\t\tint idx = query(k, 1, s, root[leafDfnMin[u] - 1], root[leafDfnMin[u] + leafsiz[u] - 1]);\n\t\treturn sorted[idx];\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastIO io = new FastIO(System.in, System.out);\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tq = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnode[i] = io.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tedge[i][0] = io.nextInt();\n\t\t\tedge[i][1] = io.nextInt();\n\t\t\tedge[i][2] = io.nextInt();\n\t\t}\n\t\tprepare();\n\t\tkruskalRebuild();\n\t\tfor (int i = 1; i <= cntu; i++) {\n\t\t\tif (i == father[i]) {\n\t\t\t\tdfs(i, 0);\n\t\t\t}\n\t\t}\n\t\troot[0] = build(1, s);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\troot[i] = insert(node[leafseg[i]], 1, s, root[i - 1]);\n\t\t}\n\t\tfor (int i = 1, u, x, k, lastAns = 0; i <= q; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tx = io.nextInt();\n\t\t\tk = io.nextInt();\n\t\t\tu = (u ^ lastAns) % n + 1;\n\t\t\tx = x ^ lastAns;\n\t\t\tk = (k ^ lastAns) % n + 1;\n\t\t\tlastAns = kthMax(u, x, k);\n\t\t\tif (lastAns == 0) {\n\t\t\t\tio.writelnInt(-1);\n\t\t\t} else {\n\t\t\t\tio.writelnInt(lastAns);\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t}\n\n\t// 读写工具类\n\tstatic class FastIO {\n\t\tprivate final InputStream is;\n\t\tprivate final OutputStream os;\n\t\tprivate final byte[] inbuf = new byte[1 << 16];\n\t\tprivate int lenbuf = 0;\n\t\tprivate int ptrbuf = 0;\n\t\tprivate final StringBuilder outBuf = new StringBuilder();\n\n\t\tpublic FastIO(InputStream is, OutputStream os) {\n\t\t\tthis.is = is;\n\t\t\tthis.os = os;\n\t\t}\n\n\t\tprivate int readByte() {\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new RuntimeException(e);\n\t\t\t\t}\n\t\t\t\tif (lenbuf == -1) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++] & 0xff;\n\t\t}\n\n\t\tprivate int skip() {\n\t\t\tint b;\n\t\t\twhile ((b = readByte()) != -1) {\n\t\t\t\tif (b > ' ') {\n\t\t\t\t\treturn b;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn -1;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\tint b = skip();\n\t\t\tif (b == -1) {\n\t\t\t\tthrow new RuntimeException("No more integers (EOF)");\n\t\t\t}\n\t\t\tboolean negative = false;\n\t\t\tif (b == '-') {\n\t\t\t\tnegative = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (b >= '0' && b <= '9') {\n\t\t\t\tval = val * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn negative ? -val : val;\n\t\t}\n\n\t\tpublic void write(String s) {\n\t\t\toutBuf.append(s);\n\t\t}\n\n\t\tpublic void writeInt(int x) {\n\t\t\toutBuf.append(x);\n\t\t}\n\n\t\tpublic void writelnInt(int x) {\n\t\t\toutBuf.append(x).append('\\n');\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\ttry {\n\t\t\t\tos.write(outBuf.toString().getBytes());\n\t\t\t\tos.flush();\n\t\t\t\toutBuf.setLength(0);\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException(e);\n\t\t\t}\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_Peaks2.java`\n\n```java\npackage class164;\n\n// 边权上限内第k大点权，C++版\n// 图里有n个点，m条无向边，点有点权，边有边权，图里可能有若干个连通的部分\n// 一共有q条查询，查询格式如下\n//