1);\n//    }\n//    return ans;\n//}\n//\n//long long solve(int u) {\n//    vis[u] = true;\n//    long long ans = calc(u, 0, 0);\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            ans -= calc(v, weight[e], 1);\n//            ans += solve(getCentroid(v, u));\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> l >> r;\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge(u, v, w);\n//        addEdge(v, u, w);\n//    }\n//    long long ans = solve(getCentroid(1, 0));\n//    cout << (ans << 1) << '\\n';\n//    return 0;\n//}\n```\n\n### `Code07_Message1.java`\n\n```java\npackage class183;\n\n// 消息传递，java版\n// 一共有n个节点，给定n-1条边，每条边的权值为1，所有节点组成一棵树\n// 一共有m条查询，格式 x k : 打印有多少点与x的距离恰好为k\n// 1 <= n、m <= 10^5\n// 0 <= k < n\n// 测试链接 : https://www.luogu.com.cn/problem/P6626\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_Message1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int t, n, m;\n\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nextg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] headq = new int[MAXN];\n\tpublic static int[] nextq = new int[MAXN];\n\tpublic static int[] dis = new int[MAXN];\n\tpublic static int[] qid = new int[MAXN];\n\tpublic static int cntq;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\t// nodeCnt[i] = j，表示从u往下走i条边，一共能找到j个点\n\tpublic static int[] nodeCnt = new int[MAXN];\n\tpublic static int maxEdge;\n\n\tpublic static int[] needArr = new int[MAXN];\n\tpublic static int[] qidArr = new int[MAXN];\n\tpublic static int cnta;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, f, edge, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int edge, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = edge;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\tedge = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addQuery(int u, int k, int id) {\n\t\tnextq[++cntq] = headq[u];\n\t\tdis[cntq] = k;\n\t\tqid[cntq] = id;\n\t\theadq[u] = cntq;\n\t}\n\n\t// 得到子树大小递归版，java会爆栈，C++可以通过\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 得到子树大小迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = headg[u]; ei > 0; ei = nextg[ei]) {\n\t\t\t\t\tint v = tog[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 收集信息递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa, int edge) {\n\t\tnodeCnt[edge]++;\n\t\tmaxEdge = Math.max(maxEdge, edge);\n\t\tfor (int e = headq[u]; e > 0; e = nextq[e]) {\n\t\t\tif (dis[e] >= edge) {\n\t\t\t\tneedArr[++cnta] = dis[e] - edge;\n\t\t\t\tqidArr[cnta] = qid[e];\n\t\t\t}\n\t\t}\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs1(v, u, edge + 1);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 收集信息迭代版\n\tpublic static void dfs2(int cur, int fa, int edg) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, edg, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tnodeCnt[edge]++;\n\t\t\t\tmaxEdge = Math.max(maxEdge, edge);\n\t\t\t\tfor (int e = headq[u]; e > 0; e = nextq[e]) {\n\t\t\t\t\tif (dis[e] >= edge) {\n\t\t\t\t\t\tneedArr[++cnta] = dis[e] - edge;\n\t\t\t\t\t\tqidArr[cnta] = qid[e];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, edge, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(tog[e], u, edge + 1, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void calc(int u, int edge, int effect) {\n\t\tcnta = 0;\n\t\tmaxEdge = 0;\n\t\t// dfs1(u, 0, edge);\n\t\tdfs2(u, 0, edge);\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tans[qidArr[i]] += nodeCnt[needArr[i]] * effect;\n\t\t}\n\t\tfor (int v = 0; v <= maxEdge; v++) {\n\t\t\tnodeCnt[v] = 0;\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tvis[u] = true;\n\t\tcalc(u, 0, 1);\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcalc(v, 1, -1);\n\t\t\t\tsolve(getCentroid(v, u));\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tcntg = 0;\n\t\tcntq = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\theadg[i] = 0;\n\t\t\theadq[i] = 0;\n\t\t\tvis[i] = false;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tans[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\tfor (int i = 1, x, k; i <= m; i++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tk = in.nextInt();\n\t\t\t\taddQuery(x, k, i);\n\t\t\t}\n\t\t\tsolve(getCentroid(1, 0));\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_Message2.java`\n\n```java\npackage class183;\n\n// 消息传递，C++版\n// 一共有n个节点，给定n-1条边，每条边的权值为1，所有节点组成一棵树\n// 一共有m条查询，格式 x k : 打印有多少点与x的距离恰好为k\n// 1 <= n、m <= 10^5\n// 0 <= 