 update(preTree, 0, 0, 0, n, 1);\n//    long long ans = -INF;\n//    cntc = 0;\n//    for (int k = 1; k <= cnte; k++) {\n//        int v = edgeArr[k].node;\n//        int c = edgeArr[k].color;\n//        if (k > 1 && edgeArr[k - 1].color != c) {\n//            clear(curTree, 0, n, 1);\n//            for (int i = 1; i <= cntc; i++) {\n//                int node = colorNode[i];\n//                update(preTree, edgeCnt[node], pathSum[node], 0, n, 1);\n//            }\n//            cntc = 0;\n//        }\n//        cnts = 0;\n//        dfs(v, u, c, 1, val[c]);\n//        for (int i = 1; i <= cnts; i++) {\n//            int node = subtreeNode[i];\n//            int l = max(0, limitl - edgeCnt[node]);\n//            int r = limitr - edgeCnt[node];\n//            ans = max(ans, query(preTree, l, r, 0, n, 1) + pathSum[node]);\n//            ans = max(ans, query(curTree, l, r, 0, n, 1) + pathSum[node] - val[c]);\n//        }\n//        for (int i = 1; i <= cnts; i++) {\n//            int node = subtreeNode[i];\n//            colorNode[++cntc] = node;\n//            update(curTree, edgeCnt[node], pathSum[node], 0, n, 1);\n//        }\n//    }\n//    clear(preTree, 0, n, 1);\n//    clear(curTree, 0, n, 1);\n//    return ans;\n//}\n//\n//long long solve(int u) {\n//    vis[u] = true;\n//    long long ans = calc(u);\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            ans = max(ans, solve(getCentroid(v, u)));\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> limitl >> limitr;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> val[i];\n//    }\n//    for (int i = 1, u, v, c; i < n; i++) {\n//        cin >> u >> v >> c;\n//        addEdge(u, v, c);\n//        addEdge(v, u, c);\n//    }\n//    build(preTree, 0, n, 1);\n//    build(curTree, 0, n, 1);\n//    cout << solve(getCentroid(1, 0)) << '\\n';\n//    return 0;\n//}\n```\n\n### `Code03_Courier1.java`\n\n```java\npackage class184;\n\n// 快递员，java版\n// 一共有n个节点，给定n-1条边，每条边给定边权，所有节点组成一棵树\n// 对于点对(a, b)，假设你选择的中心点为x，那么点对的距离如下\n// 点对(a, b)的距离 = a到x的路径权值和 + b到x的路径权值和\n// 一共有m个点对，你需要选择中心点x，使得点对距离的最大值尽量小\n// 打印这个最小的点对距离最大值\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4886\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Courier1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\tpublic static int[] tree = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, d, t, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int d, int t, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = d;\n\t\tstack[stacksize][3] = t;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\td = stack[stacksize][2];\n\t\tt = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// 得到子树大小递归版，java会爆栈，C++可以通过\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// 得到子树大小迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 收集信息递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa, int d, int t) {\n\t\ttree[u] = t;\n\t\tdist[u] = d;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u, d + weight[e], t);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 收集信息迭代版\n\tpublic static void dfs2(int cur, int fa, int di, int tr) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, di, tr, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttree[u] = t;\n\t\t\t\tdist[u] = d;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, d, t, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, d + weight[e], t, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int compute() {\n\t\tint ans = 1000000001;\n\t\tint u = getCentroid(1, 0);\n\t\twhile (!vis[u]) {\n\t\t\tvis[u] = true;\n\t\t\ttree[u] = u;\n\t\t\tdist[u] = 0;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\t// dfs1(v, u, w, v);\n\t\t\t\tdfs2(v, u, w, v);\n\t\t\t}\n\t\t\tint maxDist = 0, son = 0;\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint curDist = dist[a[i]] + dist[b[i]];\n\t\t\t\tint t1 = tree[a[i]];\n\t\t\t\tint t2 = tree[b[i]];\n\t\t\t\tif (maxDist < curDist) {\n\t\t\t\t\tmaxDist = curDist;\n\t\t\t\t\tson = t1 == t2 ? t1 : 0;\n\t\t\t\t} else if (maxDist == curDist && (t1 != t2 || t1 != son)) {\n\t\t\t\t\tson = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans = Math.min(ans, maxDist);\n\t\t\tif (son == 0) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tu = getCentroid(son, u);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_Courier2.java`\n\n```java\npackage class184;\n\n// 快递员，C++版\n// 一共有n个节点，给定n-1条边，每条边给定边权，所有节点组成一棵树\n// 对于点对(a, b)，假设你选择的中心点为x，那么点对的距离如下\n// 点对(a, b)的距离 = a到x的路径权值和 + b到x的路径权值和\n// 一共有m个点对，你需要选择中心点x，使得点对距离的最大值尽量小\n// 打印这个最小的点对距离最大值\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4886\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//int a[MAXN];\n//int b[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int weight[MAXN << 1];\n//int cntg;\n//\n//bool vis[MAXN];\n//int siz[MAXN];\n//\n//int tree[MAXN];\n//int dist[MAXN];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//void getSize(int u, int fa) {\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroid(int u, int fa) {\n//    getSize(u, fa);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            if (v != fa && !vis[v] && siz[v] > half) {\n//                fa = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void dfs(int u, int fa, int d, int t) {\n//    tree[u] = t;\n//    dist[u] = d;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            dfs(v, u, d + weight[e], t);\n//        }\n//    }\n//}\n//\n//int compute() {\n//    int ans = 1000000001;\n//    int u = getCentroid(1, 0);\n//    while (!vis[u]) {\n//        vis[u] = true;\n//        tree[u] = u;\n//        dist[u] = 0;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            int w = weight[e];\n//            dfs(v, u, w, v);\n//        }\n//        int maxDist = 0, son = 0;\n//        for (int i = 1; i <= m; i++) {\n//            int curDist = dist[a[i]] + dist[b[i]];\n//            int t1 = tree[a[i]];\n//            int t2 = tree[b[i]];\n//            if (maxDist < curDist) {\n//                maxDist = curDist;\n//                son = (t1 == t2) ? t1 : 0;\n//            } else if (maxDist == curDist && (t1 != t2 || t1 != son)) {\n//                son = 0;\n//            }\n//        }\n//        ans = min(ans, maxDist);\n//        if (son == 0) {\n//            break;\n//        }\n//        u = getCentroid(son, u);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge(u, v, w);\n//        addEdge(v, u, w);\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//    }\n//    cout << compute() << '\\n';\n//    return 0;\n//}\n```\n\n### `Code04_Shopping1.java`\n\n```java\npackage class184;\n\n// 树上购物，java版\n// 一共有n个商店，有n-1条路构成一棵树，第i个商店只卖第i种物品\n// 给定每种物品三个属性，价值v[i]、单价c[i]、数量d[i]\n// 你逛商店可能会购买物品，要求所有买过东西的商店，在树上必须连通\n// 你有m元，打印能获得的最大价值总和\n// 1 <= n <= 500    1 <= m <= 4000    1 <= d[i] <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P6326\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Shopping1 {\n\n\tpublic static int MAXN = 501;\n\tpublic static int MAXM = 4001;\n\tpublic static int t, n, m;\n\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] c = new int[MAXN];\n\tpublic static int[] d = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\tpublic static int[] nodeArr = new int[MAXN];\n\tpublic static int[] endDfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int[] cost = new int[MAXN];\n\tpublic static int[][] dp = new int[MAXN + 1][MAXM];\n\n\tpublic static void prepare() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = 0;\n\t\t\tvis[i] = false;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tnodeArr[++cntd] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t\tendDfn[u] = cntd;\n\t}\n\n\tpublic static int calc(int u) {\n\t\tcntd = 0;\n\t\tdfs(u, 0);\n\t\tfor (int i = cntd; i > 0; i--) {\n\t\t\tint cur = nodeArr[i];\n\t\t\t// 二进制分组优化，注意物品量-1，然后二进制分组\n\t\t\t// 先必选一件，然后考虑更多件，课上解释了为什么\n\t\t\tint cnt = d[cur] - 1;\n\t\t\tint num = 0;\n\t\t\tfor (int k = 1; k <= cnt; k <<= 1) {\n\t\t\t\tval[++num] = v[cur] * k;\n\t\t\t\tcost[num] = c[cur] * k;\n\t\t\t\tcnt -= k;\n\t\t\t}\n\t\t\tif (cnt > 0) {\n\t\t\t\tval[++num] = v[cur] * cnt;\n\t\t\t\tcost[num] = c[cur] * cnt;\n\t\t\t}\n\t\t\t// 必选cur的情况，先必选一件\n\t\t\tfor (int j = m; j >= c[cur]; j--) {\n\t\t\t\tdp[i][j] = dp[i + 1][j - c[cur]] + v[cur];\n\t\t\t}\n\t\t\t// 然后用二进制分组，拼出可能的更多件\n\t\t\tfor (int k = 1; k <= num; k++) {\n\t\t\t\tfor (int j = m; j >= cost[k]; j--) {\n\t\t\t\t\tdp[i][j] = Math.max(dp[i][j], dp[i][j - cost[k]] + val[k]);\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 不选cur的情况，那么cur的子树都跳过，直接跳到endDfn[cur] + 1\n\t\t\tfor (int j = 0; j <= m; j++) {\n\t\t\t\tdp[i][j] = Math.max(dp[i][j], dp[endDfn[cur] + 1][j]);\n\t\t\t}\n\t\t}\n\t\tint ans = dp[1][m];\n\t\t// 返回之前清空\n\t\tfor (int i = 1; i <= cntd; i++) {\n\t\t\tfor (int j = 0; j <= m; j++) {\n\t\t\t\tdp[i][j] = 0;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int solve(int u) {\n\t\tvis[u] = true;\n\t\tint ans = calc(u);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tans = Math.max(ans, solve(getCentroid(v, u)));\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int k = 1; k <= t; k++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tv[i] = in.nextInt();\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tc[i] = in.nextInt();\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\td[i] = in.nextInt();\n\t\t\t}\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\tout.println(solve(getCentroid(1, 0)));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Shopping2.java`\n\n```java\npackage class184;\n\n// 树上购物，C++版\n// 一共有n个商店，有n-1条路构成一棵树，第i个商店只卖第i种物品\n// 给定每种物品三个属性，价值v[i]、单价c[i]、数量d[i]\n// 你逛商店可能会购买物品，要求所有买过东西的商店，在树上必须连通\n// 你有m元，打印能获得的最大价值总和\n// 1 <= n <= 500    1 <= m <= 4000    1 <= d[i] <= 2000\n// 测试链接 : https://www.luogu.com.cn/problem/P6326\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 501;\n//const int MAXM = 4001;\n//int t, n, m;\n//\n//int v[MAXN];\n//int c[MAXN];\n//int d[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//bool vis[MAXN];\n//int siz[MAXN];\n//\n//int nodeArr[MAXN];\n//int endDfn[MAXN];\n//int cntd;\n//\n//int val[MAXN];\n//int cost[MAXN];\n//int dp[MAXN + 1][MAXM];\n//\n//void prepare() {\n//    cntg = 0;\n//    for (int i = 1; i <= n; i++) {\n//        head[i] = 0;\n//        vis[i] = false;\n//    }\n//}\n//\n//void addEdge(int u, int v