ns = dp[1][m];\n//    for (int i = 1; i <= cntd; i++) {\n//        for (int j = 0; j <= m; j++) {\n//            dp[i][j] = 0;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int solve(int u) {\n//    vis[u] = true;\n//    int ans = calc(u);\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            ans = max(ans, solve(getCentroid(v, u)));\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int k = 1; k <= t; k++) {\n//        cin >> n >> m;\n//        for (int i = 1; i <= n; i++) {\n//            cin >> v[i];\n//        }\n//        for (int i = 1; i <= n; i++) {\n//            cin >> c[i];\n//        }\n//        for (int i = 1; i <= n; i++) {\n//            cin >> d[i];\n//        }\n//        prepare();\n//        for (int i = 1, u, v; i < n; i++) {\n//            cin >> u >> v;\n//            addEdge(u, v);\n//            addEdge(v, u);\n//        }\n//        cout << solve(getCentroid(1, 0)) << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Freezing1.java`\n\n```java\npackage class184;\n\n// 最大中位数路径，java版\n// 一共有n个节点，给定n-1条边，每条边给定边权，所有节点组成一棵树\n// 一条简单路径上，收集所有边权组成序列，其中的 下中位数 作为路径的权\n// 边数在[limitl, limitr]范围的所有路径中，找到最大权的路径\n// 如果有多条路径，找到其中一个方案即可，打印两个端点\n// 1 <= n <= 10^5    0 <= 边权 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF150E\n// 测试链接 : https://codeforces.com/problemset/problem/150/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_Freezing1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, limitl, limitr, cntw;\n\n\t// 端点u、端点v、边权w\n\tpublic static int[][] arr = new int[MAXN][3];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\t// 边的编号eid、边连接的子树大小size\n\tpublic static int[][] edgeArr = new int[MAXN][2];\n\tpublic static int cnte;\n\n\tpublic static int[] preVal = new int[MAXN];\n\tpublic static int[] preNode = new int[MAXN];\n\tpublic static int preLen;\n\n\tpublic static int[] curVal = new int[MAXN];\n\tpublic static int[] curNode = new int[MAXN];\n\tpublic static int curLen;\n\n\tpublic static int[] que = new int[MAXN];\n\n\tpublic static int ans, ansu, ansv;\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void dfs(int u, int fa, int edge, int sum, int limit) {\n\t\tcurLen = Math.max(curLen, edge);\n\t\tif (sum > curVal[edge]) {\n\t\t\tcurVal[edge] = sum;\n\t\t\tcurNode[edge] = u;\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs(v, u, edge + 1, sum + (w >= limit ? 1 : -1), limit);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean check(int u, int limit) {\n\t\tpreVal[0] = 0;\n\t\tpreNode[0] = u;\n\t\tpreLen = 0;\n\t\tfor (int k = 1; k <= cnte; k++) {\n\t\t\tint v = to[edgeArr[k][0]];\n\t\t\tint w = weight[edgeArr[k][0]];\n\t\t\tfor (int i = 1; i <= siz[v]; i++) {\n\t\t\t\tcurVal[i] = -INF;\n\t\t\t}\n\t\t\tcurLen = 0;\n\t\t\tdfs(v, u, 1, w >= limit ? 1 : -1, limit);\n\t\t\tint ql = 1, qr = 0;\n\t\t\t// 根据之前的信息，初步建立窗口，子树按秩处理非常重要\n\t\t\tfor (int i = Math.min(preLen, limitr); i >= limitl; i--) {\n\t\t\t\twhile (ql <= qr && preVal[que[qr]] <= preVal[i]) {\n\t\t\t\t\tqr--;\n\t\t\t\t}\n\t\t\t\tque[++qr] = i;\n\t\t\t}\n\t\t\tint down = limitr, up = limitl;\n\t\t\tfor (int i = 1; i <= curLen; i++) {\n\t\t\t\tup--;\n\t\t\t\tif (up >= 0 && up <= preLen) {\n\t\t\t\t\twhile (ql <= qr && preVal[que[qr]] <= preVal[up]) {\n\t\t\t\t\t\tqr--;\n\t\t\t\t\t}\n\t\t\t\t\tque[++qr] = up;\n\t\t\t\t}\n\t\t\t\tif (ql <= qr && que[ql] == down) {\n\t\t\t\t\tql++;\n\t\t\t\t}\n\t\t\t\tdown--;\n\t\t\t\tif (ql <= qr && preVal[que[ql]] + curVal[i] >= 0) {\n\t\t\t\t\tif (limit > ans) {\n\t\t\t\t\t\tans = limit;\n\t\t\t\t\t\tansu = curNode[i];\n\t\t\t\t\t\tansv = preNode[que[ql]];\n\t\t\t\t\t}\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= curLen; i++) {\n\t\t\t\tif (i > preLen || curVal[i] > preVal[i]) {\n\t\t\t\t\tpreVal[i] = curVal[i];\n\t\t\t\t\tpreNode[i] = curNode[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tpreLen = Math.max(preLen, curLen);\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void calc(int u) {\n\t\tgetSize(u, 0);\n\t\tcnte = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tedgeArr[++cnte][0] = e;\n\t\t\t\tedgeArr[cnte][1] = siz[v];\n\t\t\t}\n\t\t}\n\t\t// 子树按大小或者高度排序，然后依次处理\n\t\t// 如果不按秩处理，建立窗口阶段，复杂度会炸\n\t\t// 课上会重点解释\n\t\tArrays.sort(edgeArr, 1, cnte + 1, (a, b) -> a[1] - b[1]);\n\t\tint l = 1, r = cntw, mid;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (check(u, mid)) {\n\t\t\t\tl = mid + 1;\n\t\t\t} else {\n\t\t\t\tr = mid - 1;\n\t\t\t}\n\t\t\tif (r <= ans) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tvis[u] = true;\n\t\tcalc(u);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tsolve(getCentroid(v, u));\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tlimitl = in.nextInt();\n\t\tlimitr = in.nextInt();\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tarr[i][0] = in.nextInt();\n\t\t\tarr[i][1] = in.nextInt();\n\t\t\tarr[i][2] = in.nextInt();\n\t\t}\n\t\tArrays.sort(arr, 1, n, (a, b) -> a[2] - b[2]);\n\t\tcntw = 0;\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tif (i == 1 || arr[i - 1][2] != arr[i][2]) {\n\t\t\t\tcntw++;\n\t\t\t}\n\t\t\taddEdge(arr[i][0], arr[i][1], cntw);\n\t\t\taddEdge(arr[i][1], arr[i][0], cntw);\n\t\t}\n\t\tsolve(getCentroid(1, 0));\n\t\tout.println(ansu + " " + ansv);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Freezing2.java`\n\n```java\npackage class184;\n\n// 最大中位数路径，C++版\n// 一共有n个节点，给定n-1条边，