ree(getCentroid(v, u), u);\n//        }\n//    }\n//}\n//\n//int add(int jobi, int jobv, int l, int r, int i) {\n//    if (i == 0) {\n//        i = ++cntt;\n//    }\n//    if (l == r) {\n//        sum[i] += jobv;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            ls[i] = add(jobi, jobv, l, mid, ls[i]);\n//        } else {\n//            rs[i] = add(jobi, jobv, mid + 1, r, rs[i]);\n//        }\n//        sum[i] = sum[ls[i]] + sum[rs[i]];\n//    }\n//    return i;\n//}\n//\n//int query(int jobl, int jobr, int l, int r, int i) {\n//    if (i == 0) {\n//        return 0;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        return sum[i];\n//    }\n//    int mid = (l + r) >> 1;\n//    int ans = 0;\n//    if (jobl <= mid) {\n//        ans += query(jobl, jobr, l, mid, ls[i]);\n//    }\n//    if (jobr > mid) {\n//        ans += query(jobl, jobr, mid + 1, r, rs[i]);\n//    }\n//    return ans;\n//}\n//\n//void add(int x, int v) {\n//    addTree[x] = add(0, v, 0, n - 1, addTree[x]);\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        addTree[fa] = add(dist, v, 0, n - 1, addTree[fa]);\n//        minusTree[cur] = add(dist, v, 0, n - 1, minusTree[cur]);\n//    }\n//}\n//\n//int query(int x, int k) {\n//    int ans = query(0, k, 0, n - 1, addTree[x]);\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        if (k - dist >= 0) {\n//            ans += query(0, k - dist, 0, n - 1, addTree[fa]);\n//            ans -= query(0, k - dist, 0, n - 1, minusTree[cur]);\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    centroidTree(getCentroid(1, 0), 0);\n//    for (int i = 1; i <= n; i++) {\n//        add(i, arr[i]);\n//    }\n//    int lastAns = 0;\n//    for (int i = 1, op, x, y; i <= m; i++) {\n//        cin >> op >> x >> y;\n//        x ^= lastAns;\n//        y ^= lastAns;\n//        if (op == 0) {\n//            lastAns = query(x, y);\n//            cout << lastAns << '\\n';\n//        } else {\n//            add(x, y - arr[x]);\n//            arr[x] = y;\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_Game1.java`\n\n```java\npackage class185;\n\n// 烁烁的游戏，java版\n// 树上有n个点，每个点的初始点权是0，给定n-1条边，边权都是1\n// 接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 M x k v : 点x出发，距离<=k的所有点，点权都加上v\n// 操作 Q x     : 打印点x的点权\n// 1 <= n、m <= 10^5\n// -10000 <= v <= +10000\n// 测试链接 : https://www.luogu.com.cn/problem/P10603\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_Game1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXP = 18;\n\tpublic static int MAXT = 20000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\tpublic static int[] addTree = new int[MAXN];\n\tpublic static int[] minusTree = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] sum = new int[MAXT];\n\tpublic static int cntt;\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, f, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 树上倍增收集信息递归版，java会爆栈，C++不会\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dep[x] + dep[y] - (dep[getLca(x, y)] << 1);\n\t}\n\n\t// 找重心需要计算子树大小的递归版，java会爆栈，C++不会\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// getSize1的迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[i] = add(jobi, jobv, l, mid, ls[i]);\n\t\t\t} else {\n\t\t\t\trs[i] = add(jobi, jobv, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[ls[i]] + sum[rs[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, rs[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void add(int x, int k, int v) {\n\t\taddTree[x] = add(k, v, 0, n - 1, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tif (k - dist >= 0) {\n\t\t\t\taddTree[fa] = add(k - dist, v, 0, n - 1, addTree[fa]);\n\t\t\t\tminusTree[cur] = add(k - dist, v, 0, n - 1, minusTree[cur]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int x) {\n\t\tint ans = query(0, n - 1, 0, n - 1, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tans += query(dist, n - 1, 0, n - 1, addTree[fa]);\n\t\t\tans -= query(dist, n - 1, 0, n - 1, minusTree[cur]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2(1, 0);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tchar op;\n\t\tint x, k, v;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'M') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tk = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\tadd(x, k, v);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tout.println(query(x));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_Game2.java`\n\n```java\npackage class185;\n\n// 烁烁的游戏，C++版\n// 树上有n个点，每个点的初始点权是0，给定n-1条边，边权都是1\n// 接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 M x k v : 点x出发，距离<=k的所有点，点权都加上v\n// 操作 Q x     : 打印点x的点权\n// 1 <= n、m <= 10^5\n// -10000 <= v <= +10000\n// 测试链接 : https://www.luogu.com.cn/problem/P10603\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXP = 18;\n//const int MAXT = 20000001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int dep[MAXN];\n//int stjump[MAXN][MAXP];\n//\n//bool vis[MAXN];\n//int siz[MAXN];\n//int centfa[MAXN];\n//\n//int addTree[MAXN];\n//int minusTree[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int sum[MAXT];\n//int cntt;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u, int fa) {\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            dfs(v, u);\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    if (dep[a] < dep[b]) {\n//        swap(a, b);\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (dep[stjump[a][p]] >= dep[b]) {\n//            a = stjump[a][p];\n//        }\n//    }\n//    if (a == b) {\n//        return a;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (stjump[a][p] != stjump[b][p]) {\n//            a = stjump[a][p];\n//            b = stjump[b][p];\n//        }\n//    }\n//    return stjump[a][0];\n//}\n//\n//int getDist(int x, int y) {\n//    return dep[x] + dep[y] - (dep[getLca(x, y)] << 1);\n//}\n//\n//void getSize(int u, int fa) {\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroid(int u, int fa) {\n//    getSize(u, fa);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            if (v != fa && !vis[v] && siz[v] > half) {\n//                fa = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void centroidTree(int u, int fa) {\n//    centfa[u] = fa;\n//    vis[u] = true;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            centroidTree(getCentroid(v, u), u);\n//        }\n//    }\n//}\n//\n//int add(int jobi, int jobv, int l, int r, int i) {\n//    if (i == 0) {\n//        i = ++cntt;\n//    }\n//    if (l == r) {\n//        sum[i] += jobv;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            ls[i] = add(jobi, jobv, l, mid, ls[i]);\n//        } else {\n//            rs[i] = add(jobi, jobv, mid + 1, r, rs[i]);\n//        }\n//        sum[i] = sum[ls[i]] + sum[rs[i]];\n//    }\n//    return i;\n//}\n//\n//int query(int jobl, int jobr, int l, int r, int i) {\n//    if (i == 0) {\n//        return 0;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        return sum[i];\n//    }\n//    int mid = (l + r) >> 1;\n//    int ans = 0;\n//    if (jobl <= mid) {\n//        ans += query(jobl, jobr, l, mid, ls[i]);\n//    }\n//    if (jobr > mid) {\n//        ans += query(jobl, jobr, mid + 1, r, rs[i]);\n//    }\n//    return ans;\n//}\n//\n//void add(int x, int k, int v) {\n//    addTree[x] = add(k, v, 0, n - 1, addTree[x]);\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        if (k - dist >= 0) {\n//            addTree[fa] = add(k - dist, v, 0, n - 1, addTree[fa]);\n//            minusTree[cur] = add(k - dist, v, 0, n - 1, minusTree[cur]);\n//        }\n//    }\n//}\n//\n//int query(int x) {\n//    int ans = query(0, n - 1, 0, n - 1, addTree[x]);\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        ans += query(dist, n - 1, 0, n - 1, addTree[fa]);\n//        ans -= query(dist, n - 1, 0, n - 1, minusTree[cur]);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs(1, 0);\n//    centroidTree(getCentroid(1, 0), 0);\n//    char op;\n//    int x, k, v;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op;\n//        if (op == 'M') {\n//            cin >> x >> k >> v;\n//            add(x, k, v);\n//        } else {\n//            cin >> x;\n//            cout << query(x) << '\\n';\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_AtmTree1.java`\n\n```java\npackage class185;\n\n// Atm的树，java版\n// 树上有n个点，给定n-1条边，每条边有边权\n// 现在关心，从节点x出发到达其他点的距离中，第k小的距离\n// 注意，节点x到自己的距离0，不参与距离评比\n// 给定正数k，打印每个节点的第k小距离，一共n条打印\n// 1 <= n <= 15000\n// 1 <= k <= 5000\n// 1 <= 边权 <= 10\n// 测试链接 : https://www.luogu.com.cn/problem/P10604\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_AtmTree1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXP = 18;\n\tpublic static int MAXT = 1000001;\n\tpublic static int n, k, sumw;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\tpublic static int[] addTree = new int[MAXN];\n\tpublic static int[] minusTree = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] sum = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u, int fa, int dis) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdist[u] = dis;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\ti = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[i] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[i] = add(jobi, jobv, l, mid, ls[i]);\n\t\t\t} else {\n\t\t\t\trs[i] = add(jobi, jobv, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t\tsum[i] = sum[ls[i]] + sum[rs[i]];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, rs[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void add(int x, int v) {\n\t\taddTree[x] = add(0, v, 0, sumw, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\taddTree[fa] = add(dist, v, 0, sumw, addTree[fa]);\n\t\t\tminusTree[cur] = add(dist, v, 0, sumw, minusTree[cur]);\n\t\t}\n\t}\n\n\tpublic static int query(int x, int limit) {\n\t\tint ans = query(0, limit, 0, sumw, addTree[x]);\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tif (limit - dist >= 0) {\n\t\t\t\tans += query(0, limit - dist, 0, sumw, addTree[fa]);\n\t\t\t\tans -= query(0, limit - dist, 0, sumw, minusTree[cur]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int compute(int x) {\n\t\tint ans = 0;\n\t\tint l = 0, r = sumw, mid;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (query(x, mid) >= k) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tk = in.nextInt() + 1;\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t\tsumw += w;\n\t\t}\n\t\tdfs(1, 0, 0);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(i, 1);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(compute(i));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_AtmTree2.java`\n\n```java\npackage class185;\n\n// Atm的树，C++版\n// 树上有n个点，给定n-1条边，每条边有边权\n// 现在关心，从节点x出发到达其他点的距离中，第k小的距离\n// 注意，节点x到自己的距离0，不参与距离评比\n// 给定正数k，打印每个节点的第k小距离，一共n条打印\n// 1 <= n <= 15000\n// 1 <= k <= 5000\n// 1 <= 边权 <= 10\n// 测试链接 : https://www.luogu.com.cn/problem/P10604\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 20001;\n//const int MAXP = 18;\n//const int MAXT = 1000001;\n//int n, k, sumw;\n//\