0) {\n//            ans += query(0, limit - dist, 0, sumw, addTree[fa]);\n//            ans -= query(0, limit - dist, 0, sumw, minusTree[cur]);\n//        }\n//    }\n//    return ans;\n//}\n//\n//int compute(int x) {\n//    int ans = 0;\n//    int l = 0, r = sumw, mid;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (query(x, mid) >= k) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    cin >> k;\n//    k = k + 1;\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge(u, v, w);\n//        addEdge(v, u, w);\n//        sumw += w;\n//    }\n//    dfs(1, 0, 0);\n//    centroidTree(getCentroid(1, 0), 0);\n//    for (int i = 1; i <= n; i++) {\n//        add(i, 1);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cout << compute(i) << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Fantasy1.java`\n\n```java\npackage class185;\n\n// 幻想乡战略游戏，java版\n// 树上有n个点，每个点的初始点权是0，给定n-1条边，每条边有边权\n// 如果点x是指挥点，它指挥点y的花费 = x到y的简单路径权值和 * y的点权\n// 树上存在某个最佳的指挥点，指挥所有点的总花费最小，叫做最小指挥总花费\n// 一共m条操作，格式 x v : 先把x的点权增加v，然后打印此时的最小指挥总花费\n// 注意参数v有可能是负数，但题目保证任何时候，点权不会出现负数\n// 1 <= n、m <= 10^5\n// 1 <= 边权 <= 1000\n// -1000 <= v <= +1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3345\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Fantasy1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int[] cent = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\tpublic static long[] sum = new long[MAXN];\n\tpublic static long[] addCost = new long[MAXN];\n\tpublic static long[] minusCost = new long[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, a, b, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int a, int b, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = a;\n\t\tstack[stacksize][3] = b;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\ta = stack[stacksize][2];\n\t\tb = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f, int dis) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tdist[u] = dis;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int cur, int father, int distance) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, distance, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdist[u] = a;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, a + w, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = b;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, 0, b, -2);\n\t\t\t\tpush(son[u], 0, 0, b, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tint nextCent = getCentroid(v, u);\n\t\t\t\tcent[e] = nextCent;\n\t\t\t\tcentroidTree(nextCent, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int x, int v) {\n\t\tsum[x] += v;\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tsum[fa] += v;\n\t\t\taddCost[fa] += 1L * v * dist;\n\t\t\tminusCost[cur] += 1L * v * dist;\n\t\t}\n\t}\n\n\tpublic static long query(int x) {\n\t\tlong ans = addCost[x];\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tint dist = getDist(x, fa);\n\t\t\tans += addCost[fa];\n\t\t\tans -= minusCost[cur];\n\t\t\tans += (sum[fa] - sum[cur]) * dist;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static long compute(int u) {\n\t\tlong ans = query(u);\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (query(v) < ans) {\n\t\t\t\treturn compute(cent[e]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\t// dfs1(1, 0, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0, 0);\n\t\tdfs4(1, 1);\n\t\tint root = getCentroid(1, 0);\n\t\tcentroidTree(root, 0);\n\t\tfor (int i = 1, x, v; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tadd(x, v);\n\t\t\tout.println(compute(root));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Fantasy2.java`\n\n```java\npackage class185;\n\n// 幻想乡战略游戏，C++版\n// 树上有n个点，每个点的初始点权是0，给定n-1条边，每条边有边权\n// 如果点x是指挥点，它指挥点y的花费 = x到y的简单路径权值和 * y的点权\n// 树上存在某个最佳的指挥点，指挥所有点的总花费最小，叫做最小指挥总花费\n// 一共m条操作，格式 x v : 先把x的点权增加v，然后打印此时的最小指挥总花费\n// 注意参数v有可能是负数，但题目保证任何时候，点权不会出现负数\n// 1 <= n、m <= 10^5\n// 1 <= 边权 <= 1000\n// -1000 <= v <= +1000\n// 测试链接 : https://www.luogu.com.cn/problem/P3345\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int weight[MAXN << 1];\n//int cent[MAXN << 1];\n//int cntg;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dist[MAXN];\n//\n//bool vis[MAXN];\n//int centfa[MAXN];\n//\n//long long sum[MAXN];\n//long long addCost[MAXN];\n//long long minusCost[MAXN];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f, int dis) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    dist[u] = dis;\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        int w = weight[e];\n//        if (v != f) {\n//            dfs1(v, u, dis + w);\n//        }\n//    }\n//    for (int ei = head[u], v; ei; ei = nxt[ei]) {\n//        v = to[ei];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] <= dep[top[b]]) {\n//            b = fa[top[b]];\n//        } else {\n//            a = fa[top[a]];\n//        }\n//    }\n//    return dep[a] <= dep[b] ? a : b;\n//}\n//\n//int getDist(int x, int y) {\n//    return dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n//}\n//\n//void getSize(int u, int f) {\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != f && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroid(int u, int f) {\n//    getSize(u, f);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            if (v != f && !vis[v] && siz[v] > half) {\n//                f = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void centroidTree(int u, int f) {\n//    centfa[u] = f;\n//    vis[u] = true;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            int nextCent = getCentroid(v, u);\n//            cent[e] = nextCent;\n//            centroidTree(nextCent, u);\n//        }\n//    }\n//}\n//\n//void add(int x, int v) {\n//    sum[x] += v;\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        sum[fa] += v;\n//        addCost[fa] += 1LL * v * dist;\n//        minusCost[cur] += 1LL * v * dist;\n//    }\n//}\n//\n//long long query(int x) {\n//    long long ans = addCost[x];\n//    for (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n//        int dist = getDist(x, fa);\n//        ans += addCost[fa];\n//        ans -= minusCost[cur];\n//        ans += (sum[fa] - sum[cur]) * dist;\n//    }\n//    return ans;\n//}\n//\n//long long compute(int u) {\n//    long long ans = query(u);\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (query(v) < ans) {\n//            return compute(cent[e]);\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge(u, v, w);\n//        addEdge(v, u, w);\n//    }\n//    dfs1(1, 0, 0);\n//    dfs2(1, 1);\n//    int root = getCentroid(1, 0);\n//    centroidTree(root, 0);\n//    for (int i = 1, x, v; i <= m; i++) {\n//        cin >> x >> v;\n//        add(x, v);\n//        cout << compute(root) << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_OpenStore1.java`\n\n```java\npackage class185;\n\n// 开店，java版\n// 一共n个人，每个人有年龄，给定n-1条路，每条路有距离，路把人连成一棵树\n// 一共m条查询，格式 u l r : 查询年龄范围[l, r]的所有人，到第u号人的距离总和\n// 1 <= n <= 1.5 * 10^5    1 <= m <= 2 * 10^5\n// 0 <= 年龄值 <= 10^9      1 <= 距离值 <= 1000\n// 本题要求强制在线，得到操作参数的规则，打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P3241\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_OpenStore1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXK = 4000001;\n\tpublic static int n, m, A;\n\tpublic static int[] age = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\t// cur列表(年龄，到当前重心距离)\n\tpublic static int[] curl = new int[MAXN];\n\tpublic static int[] curr = new int[MAXN];\n\tpublic static int[] curAge = new int[MAXK];\n\tpublic static long[] curSum = new long[MAXK];\n\tpublic static int cntc;\n\n\t// fa列表(年龄，到上级重心距离)\n\tpublic static int[] fal = new int[MAXN];\n\tpublic static int[] far = new int[MAXN];\n\tpublic static int[] faAge = new int[MAXK];\n\tpublic static long[] faSum = new long[MAXK];\n\tpublic static int cntf;\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, a, b, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int a, int b, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = a;\n\t\tstack[stacksize][3] = b;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\ta = stack[stacksize][2];\n\t\tb = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u, int f, int dis) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tdist[u] = dis;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, dis + w);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int cur, int father, int distance) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, distance, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdist[u] = a;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, a + w, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = b;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, 0, b, -2);\n\t\t\t\tpush(son[u], 0, 0, b, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n\t}\n\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\t// 来到了一片连通区，当前重心是rt，上级重心是centfa[rt]\n\t// 生成两个列表，距离到当前重心的列表，距离到上级重心的列表\n\tpublic static void getList1(int u, int fa, int sum, int rt) {\n\t\tcurAge[++cntc] = age[u];\n\t\tcurSum[cntc] = sum;\n\t\tif (centfa[rt] > 0) {\n\t\t\tfaAge[++cntf] = age[u];\n\t\t\tfaSum[cntf] = getDist(u, centfa[rt]);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tint w = weight[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetList1(v, u, sum + w, rt);\n\t\t\t}\n\t\t}\n\t}\n\n\t// getList1的迭代版\n\tpublic static void getList2(int cur, int father, int psum, int cen) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, psum, cen, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tcurAge[++cntc] = age[u];\n\t\t\t\tcurSum[cntc] = a;\n\t\t\t\tif (centfa[b] > 0) {\n\t\t\t\t\tfaAge[++cntf] = age[u];\n\t\t\t\t\tfaSum[cntf] = getDist(u, centfa[b]);\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, a, b, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, a + w, b, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tcurl[u] = cntc + 1;\n\t\tfal[u] = cntf + 1;\n\t\t// getList1(u, 0, 0, u);\n\t\tgetList2(u, 0, 0, u);\n\t\tcurr[u] = cntc;\n\t\tfar[u] = cntf;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 查询x在有序数组arr中的排名\n\tpublic static int kth(int[] arr, int l, int r, int x) {\n\t\tint ans = r + 1;\n\t\twhile (l <= r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (arr[mid] >= x) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 每个对象两个属性(age, sum)，所有对象根据年龄排序\n\t// java自带的排序慢，手撸双指针快排，C++实现时可以用自带的排序\n\tpublic static void sort(int[] age, long[] sum, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r, pivot = age[(l + r) >> 1], tmp1;\n\t\tlong tmp2;\n\t\twhile (i <= j) {\n\t\t\twhile (age[i] < pivot) i++;\n\t\t\twhile (age[j] > pivot) j--;\n\t\t\tif (i <= j) {\n\t\t\t\ttmp1 = age[i]; age[i] = age[j]; age[j] = tmp1;\n\t\t\t\ttmp2 = sum[i]; sum[i] = sum[j]; sum[j] = tmp2;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsort(age, sum, l, j);\n\t\tsort(age, sum, i, r);\n\t}\n\n\tpublic static long nodeCnt, pathSum;\n\n\t// 下标范围[l...r]代表当前节点的列表，找到年龄范围[agel, ager]的人\n\t// 查到的人数设置给nodeCnt，查到的距离总和设置给pathSum\n\tpublic static void query(int[] age, long[] sum, int l, int r, int agel, int ager) {\n\t\tnodeCnt = pathSum = 0;\n\t\tif (l <= r) {\n\t\t\tint a = kth(age, l, r, agel);\n\t\t\tint b = kth(age, l, r, ager + 1) - 1;\n\t\t\tif (a <= b) {\n\t\t\t\tnodeCnt = b - a + 1;\n\t\t\t\tpathSum = sum[b] - (a == l ? 0 : sum[a - 1]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute(int x, int agel, int ager) {\n\t\tquery(curAge, curSum, curl[x], curr[x], agel, ager);\n\t\tlong ans = pathSum;\n\t\tlong cnt1, sum1, cnt2, sum2;\n\t\tfor (int cur = x, fa = centfa[cur]; fa > 0; cur = fa, fa = centfa[cur]) {\n\t\t\tquery(curAge, curSum, curl[fa], curr[fa], agel, ager);\n\t\t\tcnt1 = nodeCnt;\n\t\t\tsum1 = pathSum;\n\t\t\tquery(faAge, faSum, fal[cur], far[cur], agel, ager);\n\t\t\tcnt2 = nodeCnt;\n\t\t\tsum2 = pathSum;\n\t\t\tans += sum1;\n\t\t\tans -= sum2;\n\t\t\tans += (cnt1 - cnt2) * getDist(x, fa);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tA = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tage[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\t// dfs1(1, 0, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0, 0);\n\t\tdfs4(1, 1);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsort(curAge, curSum, curl[i], curr[i]);\n\t\t\tfor (int j = curl[i] + 1; j <= curr[i]; j++) {\n\t\t\t\tcurSum[j] += curSum[j - 1];\n\t\t\t}\n\t\t\tsort(faAge, faSum, fal[i], far[i]);\n\t\t\tfor (int j = fal[i] + 1; j <= far[i]; j++) {\n\t\t\t\tfaSum[j] += faSum[j - 1];\n\t\t\t}\n\t\t}\n\t\tlong lastAns = 0;\n\t\tfor (int i = 1, u, l, r; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tl = (int) ((lastAns + l) % A);\n\t\t\tr = (int) ((lastAns + r) % A);\n\t\t\tif (l > r) {\n\t\t\t\tint tmp = l; l = r; r = tmp;\n\t\t\t}\n\t\t\tlastAns = compute(u, l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_OpenStore2.java`\n\n```java\npackage class185;\n\n// 开店，C++版\n// 一共n个人，每个人有年龄，给定n-1条路，每条路有距离，路把人连成一棵树\n// 一共m条查询，格式 u l r : 查询年龄范围[l, r]的所有人，到第u号人的距离总和\n// 1 <= n <= 1.5 * 10^5    1 <= m <= 2 * 10^5\n// 0 <= 年龄值 <= 10^9      1 <= 距离值 <= 1000\n// 本题要求强制在线，得到操作参数的规则，打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P3241\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int age;\n//    long long sum;\n//};\n//\n//bool NodeCmp(Node x, Node y) {\n//    return x.age < y.age;\n//}\n//\n//const int MAXN = 200001;\n//const int MAXK = 4000001;\n//int n, m, A;\n//int age[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int weight[MAXN << 1];\n//int cntg;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dist[MAXN];\n//\n//bool vis[MAXN];\n//int centfa[MAXN];\n//\n//int curl[MAXN];\n//int curr[MAXN];\n//Node curArr[MAXK];\n//int cntc;\n//\n//int fal[MAXN];\n//int far[MAXN];\n//Node faArr[MAXK];\n//int cntf;\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f, int dis) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    dist[u] = dis;\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        int w = weight[e];\n//        if (v != f) {\n//            dfs1(v, u, dis + w);\n//        }\n//    }\n//    for (int ei = head[u], v; ei; ei = nxt[ei]) {\n//        v = to[ei];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] <= dep[top[b]]) {\n//            b = fa[top[b]];\n//        } else {\n//            a = fa[top[a]];\n//        }\n//    }\n//    return dep[a] <= dep[b] ? a : b;\n//}\n//\n//int getDist(int x, int y) {\n//    return dist[x] + dist[y] - (dist[getLca(x, y)] << 1);\n//}\n//\n//void getSize(int u, int f) {\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != f && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroid(int u, int f) {\n//    getSize(u, f);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            if (v != f && !vis[v] && siz[v] > half) {\n//                f = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void getList(int u, int f, int sum, int rt) {\n//    curArr[++cntc] = { age[u], sum };\n//    if (centfa[rt] > 0) {\n//        faArr[++cntf] = { age[u], getDist(u, centfa[rt]) };\n//    }\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        int w = weight[e];\n//        if (v != f && !vis[v]) {\n//            getList(v, u, sum + w, rt);\n//        }\n//    }\n//}\n//\n//void centroidTree(int u, int f) {\n//    centfa[u] = f;\n//    vis[u] = true;\n//    curl[u] = cntc + 1;\n//    fal[u] = cntf + 1;\n//    getList(u, 0, 0, u);\n//    curr[u] = cntc;\n//    far[u] = cntf;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            centroidTree(getCentroid(v, u), u);\n//        }\n//    }\n//}\n//\n//int kth(Node arr[], int l, int r, int x) {\n//    int ans = r + 1;\n//    while (l <= r) {\n//        int mid = (l + r) >> 1;\n//        if (arr[mid].age >= x) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//long long nodeCnt, pathSum;\n//\n//void query(Node arr[], int l, int r, int agel, int ager) {\n//    nodeCnt = pathSum = 0;\n//    if (l <= r) {\n//        int a = kth(arr, l, r, agel);\n//        int b = kth(arr, l, r, ager + 1) - 1;\n//        if (a <= b) {\n//            nodeCnt = b - a + 1;\n//            pathSum = arr[b].sum - (a == l ? 0 : arr[a - 1].sum);\n//        }\n//    }\n//}\n//\n//long long compute(int u, int agel, int ager) {\n//    query(curArr, curl[u], curr[u], agel, ager);\n//    long long ans = pathSum;\n//    long long cnt1, sum1, cnt2, sum2;\n//    for (int cur = u, f = centfa[cur]; f > 0; cur = f, f = centfa[cur]) {\n//        query(curArr, curl[f], curr[f], agel, ager);\n//        cnt1 = nodeCnt;\n//        sum1 = pathSum;\n//        query(faArr, fal[cur], far[cur], agel, ager);\n//        cnt2 = nodeCnt;\n//        sum2 = pathSum;\n//        ans += sum1;\n//        ans -= sum2;\n//        ans += (cnt1 - cnt2) * getDist(u, f);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> A;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> age[i];\n//    }\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge(u, v, w);\n//        addEdge(v, u, w);\n//    }\n//    dfs1(1, 0, 0);\n//    dfs2(1, 1);\n//    centroidTree(getCentroid(1, 0), 0);\n//    for (int i = 1; i <= n; i++) {\n//        sort(curArr + curl[i], curArr + curr[i] + 1, NodeCmp);\n//        for (int j = curl[i] + 1; j <= curr[i]; j++) {\n//            curArr[j].sum += curArr[j - 1].sum;\n//        }\n//        sort(faArr + fal[i], faArr + far[i] + 1, NodeCmp);\n//        for (int j = fal[i] + 1; j <= far[i]; j++) {\n//            faArr[j].sum += faArr[j - 1].sum;\n//        }\n//    }\n//    long long lastAns = 0;\n//    for (int i = 1, u, l, r; i <= m; i++) {\n//        cin >> u >> l >> r;\n//        l = (int)((lastAns + l) % A);\n//        r = (int)((lastAns + r) % A);\n//        if (l > r) {\n//            swap(l, r);\n//        }\n//        lastAns = compute(u, l, r);\n//        cout << lastAns << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_ChengDu1.java`\n\n```java\npackage class185;\n\n// 成都七中，java版\n// 树上有n个点，每个点给定颜色，给定n-1条边\n// 一共m条查询，查询之间不会相互影响，格式如下\n// 查询 l r x : 只保留编号在[l, r]的节点，打印点x所在连通块的颜色数量\n// 1 <= 所有数据 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5311\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_ChengDu1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] color = new int[MAXN];\n\n\t// 建树\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] nxtg = new int[MAXN << 1];\n\tpublic static int[] tog = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\t// 每个节点的问题列表\n\tpublic static int[] headq = new int[MAXN];\n\tpublic static int[] nxtq = new int[MAXN];\n\tpublic static int[] ql = new int[MAXN];\n\tpublic static int[] qr = new int[MAXN];\n\tpublic static int[] qid = new int[MAXN];\n\tpublic static int cntq;\n\n\t// 点分治\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\n\t// 每来到一个重心，收集节点列表，nodel和noder是解锁条件，ncolor是节点颜色\n\tpublic static int[] nodel = new int[MAXN];\n\tpublic static int[] noder = new int[MAXN];\n\tpublic static int[] ncolor = new int[MAXN];\n\tpublic static int cntNode;\n\n\t// 每来到一个重心，收集问题列表，只收集值得讨论的问题\n\tpublic static int[] quesl = new int[MAXN];\n\tpublic static int[] quesr = new int[MAXN];\n\tpublic static int[] quesid = new int[MAXN];\n\tpublic static int cntQues;\n\n\t// pos[v] = i，表示颜色v的左边界，最右位置出现在i\n\tpublic static int[] pos = new int[MAXN];\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXN];\n\t// 问题答案\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][5];\n\tpublic static int u, f, nl, nr, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int nl, int nr, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = nl;\n\t\tstack[stacksize][3] = nr;\n\t\tstack[stacksize][4] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\tnl = stack[stacksize][2];\n\t\tnr = stack[stacksize][3];\n\t\te = stack[stacksize][4];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxtg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addQuery(int u, int l, int r, int id) {\n\t\tnxtq[++cntq] = headq[u];\n\t\tql[cntq] = l;\n\t\tqr[cntq] = r;\n\t\tqid[cntq] = id;\n\t\theadq[u] = cntq;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\tif (i <= 0) {\n\t\t\treturn;\n\t\t}\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int sum(int i) {\n\t\tint ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\treturn sum(r) - sum(l - 1);\n\t}\n\n\t// 找重心需要计算子树大小的递归版，java会爆栈，C++不会\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = headg[u]; e > 0; e = nxtg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// getSize1的迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nxtg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, 0, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = headg[u]; ei > 0; ei = nxtg[ei]) {\n\t\t\t\t\tint v = tog[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = headg[u]; e > 0; e = nxtg[e]) {\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void dfs1(int u, int fa, int nl, int nr) {\n\t\tnodel[++cntNode] = nl;\n\t\tnoder[cntNode] = nr;\n\t\tncolor[cntNode] = color[u];\n\t\tfor (int ei = headq[u]; ei > 0; ei = nxtq[ei]) {\n\t\t\tif (ql[ei] <= nl && nr <= qr[ei]) {\n\t\t\t\tquesl[++cntQues] = ql[ei];\n\t\t\t\tquesr[cntQues] = qr[ei];\n\t\t\t\tquesid[cntQues] = qid[ei];\n\t\t\t}\n\t\t}\n\t\tfor (int e = headg[u]; e > 0; e = nxtg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tdfs1(v, u, Math.min(v, nl), Math.max(v, nr));\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2(int cur, int fa, int nodeMin, int nodeMax) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, nodeMin, nodeMax, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tnodel[++cntNode] = nl;\n\t\t\t\tnoder[cntNode] = nr;\n\t\t\t\tncolor[cntNode] = color[u];\n\t\t\t\tfor (int ei = headq[u]; ei > 0; ei = nxtq[ei]) {\n\t\t\t\t\tif (ql[ei] <= nl && nr <= qr[ei]) {\n\t\t\t\t\t\tquesl[++cntQues] = ql[ei];\n\t\t\t\t\t\tquesr[cntQues] = qr[ei];\n\t\t\t\t\t\tquesid[cntQues] = qid[ei];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\te = nxtg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, nl, nr, e);\n\t\t\t\tint v = tog[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, Math.min(v, nl), Math.max(v, nr), -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void sort(int[] al, int[] ar, int[] ai, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r, pivot = ar[(l + r) >> 1], tmp;\n\t\twhile (i <= j) {\n\t\t\twhile (ar[i] < pivot) i++;\n\t\t\twhile (ar[j] > pivot) j--;\n\t\t\tif (i <= j) {\n\t\t\t\ttmp = al[i]; al[i] = al[j]; al[j] = tmp;\n\t\t\t\ttmp = ar[i]; ar[i] = ar[j]; ar[j] = tmp;\n\t\t\t\ttmp = ai[i]; ai[i] = ai[j]; ai[j] = tmp;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsort(al, ar, ai, l, j);\n\t\tsort(al, ar, ai, i, r);\n\t}\n\n\tpublic static void calc(int u) {\n\t\tcntNode = 0;\n\t\tcntQues = 0;\n\t\t// dfs1(u, 0, u, u);\n\t\tdfs2(u, 0, u, u);\n\t\tsort(nodel, noder, ncolor, 1, cntNode);\n\t\tsort(quesl, quesr, quesid, 1, cntQues);\n\t\tfor (int i = 1, j = 1; i <= cntQues; i++) {\n\t\t\twhile (j <= cntNode && noder[j] <= quesr[i]) {\n\t\t\t\tif (nodel[j] > pos[ncolor[j]]) {\n\t\t\t\t\tadd(pos[ncolor[j]], -1);\n\t\t\t\t\tpos[ncolor[j]] = nodel[j];\n\t\t\t\t\tadd(pos[ncolor[j]], 1);\n\t\t\t\t}\n\t\t\t\tj++;\n\t\t\t}\n\t\t\tans[quesid[i]] = Math.max(ans[quesid[i]], query(quesl[i], n));\n\t\t}\n\t\tfor (int i = 1; i <= cntNode; i++) {\n\t\t\tadd(pos[ncolor[i]], -1);\n\t\t\tpos[ncolor[i]] = 0;\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tvis[u] = true;\n\t\tcalc(u);\n\t\tfor (int e = headg[u]; e > 0; e = nxtg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tsolve(getCentroid(v, u));\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcolor[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1, l, r, x; i <= m; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\taddQuery(x, l, r, i);\n\t\t}\n\t\tsolve(getCentroid(1, 0));\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_ChengDu2.java`\n\n```java\npackage class185;\n\n// 成都七中，C++版\n// 树上有n个点，每个点给定颜色，给定n-1条边\n// 一共m条查询，查询之间不会相互影响，格式如下\n// 查询 l r x : 只保留编号在[l, r]的节点，打印点x所在连通块的颜色数量\n// 1 <= 所有数据 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5311\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int l, r, color;\n//};\n//\n//struct Ques {\n//    int l, r, qid;\n//};\n//\n//bool NodeCmp(Node x, Node y) {\n//    return x.r < y.r;\n//}\n//\n//bool QuesCmp(Ques x, Ques y) {\n//    return x.r < y.r;\n//}\n//\n//const int MAXN = 100001;\n//int n, m;\n//int color[MAXN];\n//\n//int headg[MAXN];\n//int nxtg[MAXN << 1];\n//int tog[MAXN << 1];\n//int cntg;\n//\n//int headq[MAXN];\n//int nxtq[MAXN];\n//int ql[MAXN];\n//int qr[MAXN];\n//int qid[MAXN];\n//int cntq;\n//\n//bool vis[MAXN];\n//int siz[MAXN];\n//\n//Node nodeArr[MAXN];\n//int cntNode;\n//\n//Ques quesArr[MAXN];\n//int cntQues;\n//\n//int pos[MAXN];\n//int tree[MAXN];\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxtg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    headg[u] = cntg;\n//}\n//\n//void addQuery(int u, int l, int r, int id) {\n//    nxtq[++cntq] = headq[u];\n//    ql[cntq] = l;\n//    qr[cntq] = r;\n//    qid[cntq] = id;\n//    headq[u] = cntq;\n//}\n//\n//int lowbit(int i) {\n//    return i & -i;\n//}\n//\n//void add(int i, int v) {\n//    if (i <= 0) {\n//        return;\n//    }\n//    while (i <= n) {\n//        tree[i] += v;\n//        i += lowbit(i);\n//    }\n//}\n//\n//int sum(int i) {\n//    int ret = 0;\n//    while (i > 0) {\n//        ret += tree[i];\n//        i -= lowbit(i);\n//    }\n//    return ret;\n//}\n//\n//int query(int l, int r) {\n//    return sum(r) - sum(l - 1);\n//}\n//\n//void getSize(int u, int fa) {\n//    siz[u] = 1;\n//    for (int e = headg[u]; e > 0; e = nxtg[e]) {\n//        int v = tog[e];\n//        if (v != fa && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroid(int u, int fa) {\n//    getSize(u, fa);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = headg[u]; e > 0; e = nxtg[e]) {\n//            int v = tog[e];\n//            if (v != fa && !vis[v] && siz[v] > half) {\n//                fa = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void dfs(int u, int fa, int nl, int nr) {\n//    nodeArr[++cntNode] = { nl, nr, color[u] };\n//    for (int e = headq[u]; e > 0; e = nxtq[e]) {\n//        if (ql[e] <= nl && nr <= qr[e]) {\n//            quesArr[++cntQues] = { ql[e], qr[e], qid[e] };\n//        }\n//    }\n//    for (int e = headg[u]; e > 0; e = nxtg[e]) {\n//        int v = tog[e];\n//        if (v != fa && !vis[v]) {\n//            dfs(v, u, min(v, nl), max(v, nr));\n//        }\n//    }\n//}\n//\n//void calc(int u) {\n//    cntNode = 0;\n//    cntQues = 0;\n//    dfs(u, 0, u, u);\n//    sort(nodeArr + 1, nodeArr + cntNode + 1, NodeCmp);\n//    sort(quesArr + 1, quesArr + cntQues + 1, QuesCmp);\n//    for (int i = 1, j = 1; i <= cntQues; i++) {\n//        while (j <= cntNode && nodeArr[j].r <= quesArr[i].r) {\n//            if (nodeArr[j].l > pos[nodeArr[j].color]) {\n//                add(pos[nodeArr[j].color], -1);\n//                pos[nodeArr[j].color] = nodeArr[j].l;\n//                add(pos[nodeArr[j].color], 1);\n//            }\n//            j++;\n//        }\n//        ans[quesArr[i].qid] = max(ans[quesArr[i].qid], query(quesArr[i].l, n));\n//    }\n//    for (int i = 1; i <= cntNode; i++) {\n//        add(pos[nodeArr[i].color], -1);\n//        pos[nodeArr[i].color] = 0;\n//    }\n//}\n//\n//void solve(int u) {\n//    vis[u] = true;\n//    calc(u);\n//    for (int e = headg[u]; e > 0; e = nxtg[e]) {\n//        int v = tog[e];\n//        if (!vis[v]) {\n//            solve(getCentroid(v, u));\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> color[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1, l, r, x; i <= m; i++) {\n//        cin >> l >> r >> x;\n//        addQuery(x, l, r, i);\n//    }\n//    solve(getCentroid(1, 0));\n//    for (int i = 1; i <= m; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_HideSeek1.java`\n\n```java\npackage class185;\n\n// 捉迷藏，点分树的解，java版\n// 树上有n个点，点的初始颜色为黑，给定n-1条边，边权都是1\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 C x : 改变点x的颜色，黑变成白，白变成黑\n// 操作 G   : 打印最远的两个黑点的距离，只有一个黑点打印0，无黑点打印-1\n// 1 <= n <= 10^5    1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2056\n// 提交以下的code，提交时请把类名改成"Main"，一个测试用例空间超标\n// 本节课Code07_HideSeek3文件是最优解的实现，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.PriorityQueue;\n\npublic class Code07_HideSeek1 {\n\n\tstatic class Set {\n\t\tPriorityQueue<Integer> addHeap;\n\t\tPriorityQueue<Integer> delHeap;\n\n\t\tpublic Set() {\n\t\t\taddHeap = new PriorityQueue<>((a, b) -> b.compareTo(a));\n\t\t\tdelHeap = new PriorityQueue<>((a, b) -> b.compareTo(a));\n\t\t}\n\n\t\tvoid clean() {\n\t\t\twhile (!delHeap.isEmpty() && delHeap.peek().equals(addHeap.peek())) {\n\t\t\t\taddHeap.poll();\n\t\t\t\tdelHeap.poll();\n\t\t\t}\n\t\t}\n\n\t\tint popHead() {\n\t\t\tint ans = addHeap.poll();\n\t\t\tclean();\n\t\t\treturn ans;\n\t\t}\n\n\t\tint size() {\n\t\t\treturn addHeap.size() - delHeap.size();\n\t\t}\n\n\t\tvoid add(int v) {\n\t\t\taddHeap.add(v);\n\t\t}\n\n\t\tvoid del(int v) {\n\t\t\tdelHeap.add(v);\n\t\t\tclean();\n\t\t}\n\n\t\tint first() {\n\t\t\treturn addHeap.peek();\n\t\t}\n\n\t\tint second() {\n\t\t\tint a = popHead();\n\t\t\tint b = first();\n\t\t\tadd(a);\n\t\t\treturn b;\n\t\t}\n\t}\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static boolean[] black = new boolean[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] centfa = new int[MAXN];\n\n\t// distFa[u] : u的连通区里，每个黑点到上级重心的距离，组成的集合\n\t// sonMax[u] : u的每个儿子连通区里，都选一个最远的黑点，到u的最大距离，组成的集合\n\t//             如果u自己是黑点，那么0要加入集合\n\t// maxDist   : 每个重心在连通区里，选两个最远黑点的最大距离，作为自己的答案，放入全局集合\n\tpublic static Set[] distFa = new Set[MAXN];\n\tpublic static Set[] sonMax = new Set[MAXN];\n\tpublic static Set maxDist = new Set();\n\n\t// 讲解118，递归函数改成迭代所需要的栈\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, f, t, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int f, int t, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = f;\n\t\tstack[stacksize][2] = t;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = stack[stacksize][0];\n\t\tf = stack[stacksize][1];\n\t\tt = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 重链剖分收集信息递归版，java会爆栈，C++不会\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int ei = head[u], v; ei > 0; ei = nxt[ei]) {\n\t\t\tv = to[ei];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 根据重儿子剖分的递归版，java会爆栈，C++不会\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改成迭代版\n\tpublic static void dfs3(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, father, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tfa[u] = f;\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\t\t\tson[u] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2改成迭代版\n\tpublic static void dfs4(int cur, int tag) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, tag, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\ttop[u] = t;\n\t\t\t\tif (son[u] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(u, 0, t, -2);\n\t\t\t\tpush(son[u], 0, t, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (e == -2) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, t, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\t\tpush(v, 0, v, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 找重心需要计算子树大小的递归版，java会爆栈，C++不会\n\tpublic static void getSize1(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !vis[v]) {\n\t\t\t\tgetSize1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\t// getSize1的迭代版\n\tpublic static void getSize2(int cur, int fa) {\n\t\tstacksize = 0;\n\t\tpush(cur, fa, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tsiz[u] = 1;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, 0, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\tpush(v, u, 0, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f && !vis[v]) {\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int getDist(int x, int y) {\n\t\treturn dep[x] + dep[y] - (dep[getLca(x, y)] << 1);\n\t}\n\n\tpublic static int getCentroid(int u, int fa) {\n\t\t// getSize1(u, fa);\n\t\tgetSize2(u, fa);\n\t\tint half = siz[u] >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !vis[v] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn u;\n\t}\n\n\tpublic static void centroidTree(int u, int fa) {\n\t\tcentfa[u] = fa;\n\t\tvis[u] = true;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tcentroidTree(getCentroid(v, u), u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void addAns(int x) {\n\t\tif (sonMax[x].size() >= 2) {\n\t\t\tmaxDist.add(sonMax[x].first() + sonMax[x].second());\n\t\t}\n\t}\n\n\tpublic static void delAns(int x) {\n\t\tif (sonMax[x].size() >= 2) {\n\t\t\tmaxDist.del(sonMax[x].first() + sonMax[x].second());\n\t\t}\n\t}\n\n\tpublic static void on(int x) {\n\t\tdelAns(x);\n\t\tsonMax[x].del(0);\n\t\taddAns(x);\n\t\tfor (int u = x, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\tdelAns(fa);\n\t\t\tsonMax[fa].del(distFa[u].first());\n\t\t\tdistFa[u].del(getDist(x, fa));\n\t\t\tif (distFa[u].size() > 0) {\n\t\t\t\tsonMax[fa].add(distFa[u].first());\n\t\t\t}\n\t\t\taddAns(fa);\n\t\t}\n\t}\n\n\tpublic static void off(int x) {\n\t\tdelAns(x);\n\t\tsonMax[x].add(0);\n\t\taddAns(x);\n\t\tfor (int u = x, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\tdelAns(fa);\n\t\t\tif (distFa[u].size() > 0) {\n\t\t\t\tsonMax[fa].del(distFa[u].first());\n\t\t\t}\n\t\t\tdistFa[u].add(getDist(x, fa));\n\t\t\tsonMax[fa].add(distFa[u].first());\n\t\t\taddAns(fa);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tblack[i] = true;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdistFa[i] = new Set();\n\t\t\tsonMax[i] = new Set();\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfor (int u = i, fa = centfa[u]; fa > 0; u = fa, fa = centfa[u]) {\n\t\t\t\tdistFa[u].add(getDist(i, fa));\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsonMax[i].add(0);\n\t\t\tif (centfa[i] > 0) {\n\t\t\t\tsonMax[centfa[i]].add(distFa[i].first());\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\taddAns(i);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\t// dfs2(1, 1);\n\t\tdfs3(1, 0);\n\t\tdfs4(1, 1);\n\t\tcentroidTree(getCentroid(1, 0), 0);\n\t\tprepare();\n\t\tm = in.nextInt();\n\t\tint blackCnt = n;\n\t\tchar op;\n\t\tfor (int i = 1, x; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'C') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tblack[x] = !black[x];\n\t\t\t\tif (black[x]) {\n\t\t\t\t\toff(x);\n\t\t\t\t\tblackCnt++;\n\t\t\t\t} else {\n\t\t\t\t\ton(x);\n\t\t\t\t\tblackCnt--;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (blackCnt <= 1) {\n\t\t\t\t\tout.println(blackCnt - 1);\n\t\t\t\t} else {\n\t\t\t\t\tout.println(maxDist.first());\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n```\n\n### `Code07_HideSeek2.java`\n\n```java\npackage class185;\n\n// 捉迷藏，点分树的解，C++版\n// 树上有n个点，点的初始颜色为黑，给定n-1条边，边权都是1\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 C x : 改变点x的颜色，黑变成白，白变成黑\n// 操作 G   : 打印最远的两个黑点的距离，只有一个黑点打印0，无黑点打印-1\n// 1 <= n <= 10^5    1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2056\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Set {\n//    priority_queue<int> addHeap;\n//    priority_queue<int> delHeap;\n//\n//    void clean() {\n//        while (!delHeap.empty() && !addHeap.empty() && delHeap.top() == addHeap.top()) {\n//            addHeap.pop();\n//            delHeap.pop();\n//        }\n//    }\n//\n//    int popHead() {\n//        int ans = addHeap.top();\n//        addHeap.pop();\n//        clean();\n//        return ans;\n//    }\n//\n//    int size() {\n//        return (int)addHeap.size() - (int)delHeap.size();\n//    }\n//\n//    void add(int v) {\n//        addHeap.push(v);\n//    }\n//\n//    void del(int v) {\n//        delHeap.push(v);\n//        clean();\n//    }\n//\n//    int first() {\n//        return addHeap.top();\n//    }\n//\n//    int second() {\n//        int a = popHead();\n//        int b = first();\n//        add(a);\n//        return b;\n//    }\n//};\n//\n//const int MAXN = 100001;\n//int n, m;\n//bool black[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//\n//bool vis[MAXN];\n//int centfa[MAXN];\n//\n//Set distFa[MAXN];\n//Set sonMax[MAXN];\n//Set maxDist;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//        }\n//    }\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//void getSize(int u, int f) {\n//    siz[u] = 1;\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != f && !vis[v]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] <= dep[top[b]]) {\n//            b = fa[top[b]];\n//        } else {\n//            a = fa[top[a]];\n//        }\n//    }\n//    return dep[a] <= dep[b] ? a : b;\n//}\n//\n//int getDist(int x, int y) {\n//    return dep[x] + dep[y] - (dep[getLca(x, y)] << 1);\n//}\n//\n//int getCentroid(int u, int f) {\n//    getSize(u, f);\n//    int half = siz[u] >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head[u]; e; e = nxt[e]) {\n//            int v = to[e];\n//            if (v != f && !vis[v] && siz[v] > half) {\n//                f = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    return u;\n//}\n//\n//void centroidTree(int u, int f) {\n//    centfa[u] = f;\