   for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa && !vis[e >> 1]) {\n//            dfs(v, u, dist + weight2[e], op);\n//        }\n//    }\n//}\n//\n//void solve(int u) {\n//    int edge = getCentroidEdge(u, 0);\n//    if (edge > 0) {\n//        vis[edge >> 1] = true;\n//        int v1 = to2[edge];\n//        int v2 = to2[edge ^ 1];\n//        dfs(v1, 0, 0, 0);\n//        dfs(v2, 0, weight2[edge], 1);\n//        solve(v1);\n//        solve(v2);\n//    }\n//}\n//\n//int add(int p, int i) {\n//    if (p == 0 || i == 0) {\n//        return p + i;\n//    }\n//    int rt = ++cntt;\n//    ls[rt] = ls[p];\n//    rs[rt] = rs[p];\n//    lcnt[rt] = lcnt[p] + lcnt[i];\n//    rcnt[rt] = rcnt[p] + rcnt[i];\n//    lsum[rt] = lsum[p] + lsum[i];\n//    rsum[rt] = rsum[p] + rsum[i];\n//    if (ls[i] > 0) {\n//        ls[rt] = add(ls[rt], ls[i]);\n//    } else {\n//        rs[rt] = add(rs[rt], rs[i]);\n//    }\n//    return rt;\n//}\n//\n//ll query(int p1, int p2, int i) {\n//    if (ls[i] == 0 && rs[i] == 0) {\n//        return 0;\n//    } else if (ls[i] > 0) {\n//        return query(ls[p1], ls[p2], ls[i]) + rsum[p2] - rsum[p1] + lsum[i] * (rcnt[p2] - rcnt[p1]);\n//    } else {\n//        return query(rs[p1], rs[p2], rs[i]) + lsum[p2] - lsum[p1] + rsum[i] * (lcnt[p2] - lcnt[p1]);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> q;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge1(u, v, w);\n//        addEdge1(v, u, w);\n//    }\n//    cntn = n;\n//    cnt2 = 1;\n//    rebuild(1, 0);\n//    solve(1);\n//    for (int i = 1; i <= n; i++) {\n//        pre[i] = add(pre[i - 1], root[arr[i]]);\n//    }\n//    ll mask = (1LL << 30) - 1;\n//    ll lastAns = 0;\n//    ll a, b, c;\n//    int op, x, y, z, tmp;\n//    for (int i = 1; i <= q; i++) {\n//        cin >> op;\n//        if (op == 1) {\n//            cin >> a >> b >> c;\n//            a ^= lastAns;\n//            b ^= lastAns;\n//            c ^= lastAns;\n//            x = (int)a;\n//            y = (int)b;\n//            z = (int)c;\n//            lastAns = query(pre[x - 1], pre[y], root[z]);\n//            cout << lastAns << '\\n';\n//            lastAns &= mask;\n//        } else {\n//            cin >> a;\n//            a ^= lastAns;\n//            x = (int)a;\n//            tmp = arr[x];\n//            arr[x] = arr[x + 1];\n//            arr[x + 1] = tmp;\n//            pre[x] = add(pre[x - 1], root[arr[x]]);\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_ViolentWriting1.java`\n\n```java\npackage class187;\n\n// 暴力写挂，java版\n// 两棵树t1、t2都有n个节点，都以1号节点作为树头\n// 各自给定n-1条边，以及每条边的边权，边权可能为负数\n// 在t1中，点x到树头的距离记为dis1(x)，在t2中，该距离记为dis2(x)\n// 点x和点y在t1中的LCA记为lca1(x, y)，在t2中的LCA记为lca2(x, y)\n// 点对(x, y)的指标 = dis1(x) + dis1(y) - dis1(lca1(x, y)) - dis2(lca2(x, y))\n// 点对(x, y)，要求x <= y，打印这个指标的最大值\n// 1 <= n <= 366666\n// 测试链接 : https://www.luogu.com.cn/problem/P4565\n// 测试链接 : https://loj.ac/p/2553\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是需要把太多递归函数改成迭代才能通过，索性不改了\n// 想通过用C++实现，本节课Code04_ViolentWriting2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_ViolentWriting1 {\n\n\tpublic static int MAXN = 366667;\n\tpublic static int MAXM = MAXN << 1;\n\tpublic static int MAXT = 10000001;\n\tpublic static long INF = 1L << 50;\n\tpublic static int n, cntn;\n\n\tpublic static int[] head0 = new int[MAXN];\n\tpublic static int[] next0 = new int[MAXN << 1];\n\tpublic static int[] to0 = new int[MAXN << 1];\n\tpublic static int[] weight0 = new int[MAXN << 1];\n\tpublic static int cnt0;\n\n\tpublic static int[] head1 = new int[MAXM];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int[] weight1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN << 1];\n\tpublic static int[] to2 = new int[MAXN << 1];\n\tpublic static int[] weight2 = new int[MAXN << 1];\n\tpublic static int cnt2;\n\n\tpublic static long[] dis1 = new long[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXM];\n\tpublic static int[] siz = new int[MAXM];\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static long[] lmax = new long[MAXT];\n\tpublic static long[] rmax = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static long ans;\n\n\tpublic static void addEdge0(int u, int v, int w) {\n\t\tnext0[++cnt0] = head0[u];\n\t\tto0[cnt0] = v;\n\t\tweight0[cnt0] = w;\n\t\thead0[u] = cnt0;\n\t}\n\n\tpublic static void addEdge1(int u, int v, int w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, int w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void getDist(int u, int fa, long dist1) {\n\t\tdis1[u] = dist1;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tgetDist(v, u, dist1 + weight0[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rebuild(int u, int fa) {\n\t\tint last = 0;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tint w = weight0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (last == 0) {\n\t\t\t\t\tlast = u;\n\t\t\t\t\taddEdge1(u, v, w);\n\t\t\t\t\taddEdge1(v, u, w);\n\t\t\t\t} else {\n\t\t\t\t\tint add = ++cntn;\n\t\t\t\t\taddEdge1(last, add, 0);\n\t\t\t\t\taddEdge1(add, last, 0);\n\t\t\t\t\taddEdge1(add, v, w);\n\t\t\t\t\taddEdge1(v, add, w);\n\t\t\t\t\tlast = add;\n\t\t\t\t}\n\t\t\t\trebuild(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroidEdge(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint total = siz[u];\n\t\tint half = total >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tif (v != fa && !vis[e >> 1] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint best = 0, edge = 0;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif (!vis[e >> 1]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tint sub = v == fa ? (total - siz[u]) : siz[v];\n\t\t\t\tif (sub > best) {\n\t\t\t\t\tbest = sub;\n\t\t\t\t\tedge = e;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static void dfs(int u, int fa, long path, int op) {\n\t\tif (u <= n) {\n\t\t\tif (up[u] == 0) {\n\t\t\t\tup[u] = ++cntt;\n\t\t\t\troot[u] = cntt;\n\t\t\t}\n\t\t\tint cur = up[u];\n\t\t\tint nxt = ++cntt;\n\t\t\tif (op == 0) {\n\t\t\t\tls[cur] = nxt;\n\t\t\t\tlmax[cur] = dis1[u] + path;\n\t\t\t} else {\n\t\t\t\trs[cur] = nxt;\n\t\t\t\trmax[cur] = dis1[u] + path;\n\t\t\t}\n\t\t\tup[u] = nxt;\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tdfs(v, u, path + weight1[e], op);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solve(int u) {\n\t\tint edge = getCentroidEdge(u, 0);\n\t\tif (edge > 0) {\n\t\t\tvis[edge >> 1] = true;\n\t\t\tint v1 = to1[edge];\n\t\t\tint v2 = to1[edge ^ 1];\n\t\t\tdfs(v1, 0, 0, 0);\n\t\t\tdfs(v2, 0, weight1[edge], 1);\n\t\t\tsolve(v1);\n\t\t\tsolve(v2);\n\t\t}\n\t}\n\n\tpublic static int mergeTree(int x, int y, long add) {\n\t\tif (x == 0 || y == 0) {\n\t\t\treturn x + y;\n\t\t}\n\t\tans = Math.max(ans, Math.max(lmax[x] + rmax[y], lmax[y] + rmax[x]) + add);\n\t\tlmax[x] = Math.max(lmax[x], lmax[y]);\n\t\trmax[x] = Math.max(rmax[x], rmax[y]);\n\t\tls[x] = mergeTree(ls[x], ls[y], add);\n\t\trs[x] = mergeTree(rs[x], rs[y], add);\n\t\treturn x;\n\t}\n\n\tpublic static void compute(int u, int fa, long dist2) {\n\t\tans = Math.max(ans, (dis1[u] - dist2) * 2);\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcompute(v, u, dist2 + weight2[e]);\n\t\t\t\troot[u] = mergeTree(root[u], root[v], -dist2 * 2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge0(u, v, w);\n\t\t\taddEdge0(v, u, w);\n\t\t}\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge2(u, v, w);\n\t\t\taddEdge2(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < MAXT; i++) {\n\t\t\tlmax[i] = rmax[i] = -INF;\n\t\t}\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tans = -INF;\n\t\tgetDist(1, 0, 0);\n\t\trebuild(1, 0);\n\t\tsolve(1);\n\t\tcompute(1, 0, 0);\n\t\tout.println(ans >> 1);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n```\n\n### `Code04_ViolentWriting2.java`\n\n```java\npackage class187;\n\n// 暴力写挂，C++版\n// 两棵树t1、t2都有n个节点，都以1号节点作为树头\n// 各自给定n-1条边，以及每条边的边权，边权可能为负数\n// 在t1中，点x到树头的距离记为dis1(x)，在t2中，该距离记为dis2(x)\n// 点x和点y在t1中的LCA记为lca1(x, y)，在t2中的LCA记为lca2(x, y)\n// 点对(x, y)的指标 = dis1(x) + dis1(y) - dis1(lca1(x, y)) - dis2(lca2(x, y))\n// 点对(x, y)，要求x <= y，打印这个指标的最大值\n// 1 <= n <= 366666\n// 测试链接 : https://www.luogu.com.cn/problem/P4565\n// 测试链接 : https://loj.ac/p/2553\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 366667;\n//const int MAXM = MAXN << 1;\n//const int MAXT = 10000001;\n//const ll INF = 1LL << 50;\n//\n//int n, cntn;\n//\n//int head0[MAXN];\n//int next0[MAXN << 1];\n//int to0[MAXN << 1];\n//int weight0[MAXN << 1];\n//int cnt0;\n//\n//int head1[MAXM];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int weight1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN];\n//int next2[MAXN << 1];\n//int to2[MAXN << 1];\n//int weight2[MAXN << 1];\n//int cnt2;\n//\n//ll dis1[MAXN];\n//\n//bool vis[MAXM];\n//int siz[MAXM];\n//\n//int up[MAXN];\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//ll lmax[MAXT];\n//ll rmax[MAXT];\n//int cntt;\n//\n//ll ans;\n//\n//void addEdge0(int u, int v, int w) {\n//    next0[++cnt0] = head0[u];\n//    to0[cnt0] = v;\n//    weight0[cnt0] = w;\n//    head0[u] = cnt0;\n//}\n//\n//void addEdge1(int u, int v, int w) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    weight1[cnt1] = w;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v, int w) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    weight2[cnt2] = w;\n//    head2[u] = cnt2;\n//}\n//\n//void getDist(int u, int fa, ll dist1) {\n//    dis1[u] = dist1;\n//    for (int e = head0[u]; e > 0; e = next0[e]) {\n//        int v = to0[e];\n//        if (v != fa) {\n//            getDist(v, u, dist1 + weight0[e]);\n//        }\n//    }\n//}\n//\n//void rebuild(int u, int fa) {\n//    int last = 0;\n//    for (int e = head0[u]; e > 0; e = next0[e]) {\n//        int v = to0[e];\n//        int w = weight0[e];\n//        if (v != fa) {\n//            if (last == 0) {\n//                last = u;\n//                addEdge1(u, v, w);\n//                addEdge1(v, u, w);\n//            } else {\n//                int add = ++cntn;\n//                addEdge1(last, add, 0);\n//                addEdge1(add, last, 0);\n//                addEdge1(add, v, w);\n//                addEdge1(v, add, w);\n//                last = add;\n//            }\n//            rebuild(v, u);\n//        }\n//    }\n//}\n//\n//void getSize(int u, int fa) {\n//    siz[u] = 1;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        int v = to1[e];\n//        if (v != fa && !vis[e >> 1]) {\n//            getSize(v, u);\n//            siz[u] += siz[v];\n//        }\n//    }\n//}\n//\n//int getCentroidEdge(int u, int fa) {\n//    getSize(u, fa);\n//    int total = siz[u];\n//    int half = total >> 1;\n//    bool find = false;\n//    while (!find) {\n//        find = true;\n//        for (int e = head1[u]; e > 0; e = next1[e]) {\n//            int v = to1[e];\n//            if (v != fa && !vis[e >> 1] && siz[v] > half) {\n//                fa = u;\n//                u = v;\n//                find = false;\n//                break;\n//            }\n//        }\n//    }\n//    int best = 0, edge = 0;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        if (!vis[e >> 1]) {\n//            int v = to1[e];\n//            int sub = (v == fa ? (total - siz[u]) : siz[v]);\n//            if (sub > best) {\n//                best = sub;\n//                edge = e;\n//            }\n//        }\n//    }\n//    return edge;\n//}\n//\n//void dfs(int u, int fa, ll path, int op) {\n//    if (u <= n) {\n//        if (up[u] == 0) {\n//            up[u] = ++cntt;\n//            root[u] = cntt;\n//        }\n//        int cur = up[u];\n//        int nxt = ++cntt;\n//        if (op == 0) {\n//            ls[cur] = nxt;\n//            lmax[cur] = dis1[u] + path;\n//        } else {\n//            rs[cur] = nxt;\n//            rmax[cur] = dis1[u] + path;\n//        }\n//        up[u] = nxt;\n//    }\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        int v = to1[e];\n//        if (v != fa && !vis[e >> 1]) {\n//            dfs(v, u, path + weight1[e], op);\n//        }\n//    }\n//}\n//\n//void solve(int u) {\n//    int edge = getCentroidEdge(u, 0);\n//    if (edge > 0) {\n//        vis[edge >> 1] = true;\n//        int v1 = to1[edge];\n//        int v2 = to1[edge ^ 1];\n//        dfs(v1, 0, 0, 0);\n//        dfs(v2, 0, weight1[edge], 1);\n//        solve(v1);\n//        solve(v2);\n//    }\n//}\n//\n//int mergeTree(int x, int y, ll add) {\n//    if (x == 0 || y == 0) {\n//        return x + y;\n//    }\n//    ans = max(ans, max(lmax[x] + rmax[y], lmax[y] + rmax[x]) + add);\n//    lmax[x] = max(lmax[x], lmax[y]);\n//    rmax[x] = max(rmax[x], rmax[y]);\n//    ls[x] = mergeTree(ls[x], ls[y], add);\n//    rs[x] = mergeTree(rs[x], rs[y], add);\n//    return x;\n//}\n//\n//void compute(int u, int fa, ll dist2) {\n//    ans = max(ans, (dis1[u] - dist2) * 2);\n//    for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa) {\n//            compute(v, u, dist2 + weight2[e]);\n//            root[u] = mergeTree(root[u], root[v], -dist2 * 2);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge0(u, v, w);\n//        addEdge0(v, u, w);\n//    }\n//    for (int i = 1, u, v, w; i < n; i++) {\n//        cin >> u >> v >> w;\n//        addEdge2(u, v, w);\n//        addEdge2(v, u, w);\n//    }\n//    for (int i = 1; i < MAXT; i++) {\n//        lmax[i] = rmax[i] = -INF;\n//    }\n//    cntn = n;\n//    cnt1 = 1;\n//    ans = -INF;\n//    getDist(1, 0, 0);\n//    rebuild(1, 0);\n//    solve(1);\n//    compute(1, 0, 0);\n//    cout << (ans >> 1) << '\\n';\n//    return 0;\n//}\n```\n\n### `Code05_Passage1.java`\n\n```java\npackage class187;\n\n// 通道，java版\n// 三棵树t1、t2、t3都有n个节点，各自给定n-1条边以及每条边的边权，边权没有负数\n// 点对(x, y)，要求两点必须不同，两点在树上的距离就是简单路径上边权的累加和\n// 点对(x, y)，在t1、t2、t3的距离，分别记为dis1(x, y)、dis2(x, y)、dis3(x, y)\n// 打印最大的dis1(x, y) + dis2(x, y) + dis3(x, y)\n// 2 <= n <= 10^5\n// 0 <= 边权 <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P4220\n// 测试链接 : https://loj.ac/p/2339\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是需要把太多递归函数改成迭代才能通过，索性不改了\n// 想通过用C++实现，本节课Code05_Passage2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Passage1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = MAXN << 1;\n\tpublic static int MAXP = 20;\n\tpublic static int MAXT = MAXN * 20;\n\tpublic static long INF = 1L << 60;\n\tpublic static int n, cntn;\n\n\tpublic static int[] head0 = new int[MAXN];\n\tpublic static int[] next0 = new int[MAXN << 1];\n\tpublic static int[] to0 = new int[MAXN << 1];\n\tpublic static long[] weight0 = new long[MAXN << 1];\n\tpublic static int cnt0;\n\n\tpublic static int[] head1 = new int[MAXM];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static long[] weight1 = new long[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN << 1];\n\tpublic static int[] to2 = new int[MAXN << 1];\n\tpublic static long[] weight2 = new long[MAXN << 1];\n\tpublic static int cnt2;\n\n\tpublic static int[] head3 = new int[MAXN];\n\tpublic static int[] next3 = new int[MAXN << 1];\n\tpublic static int[] to3 = new int[MAXN << 1];\n\tpublic static long[] weight3 = new long[MAXN << 1];\n\tpublic static int cnt3;\n\n\tpublic static long[] dep2 = new long[MAXN];\n\tpublic static long[] dist3 = new long[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXM];\n\tpublic static int[] siz = new int[MAXM];\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] lg2 = new int[MAXN];\n\tpublic static int[][] rmq = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] lx = new int[MAXT];\n\tpublic static int[] ly = new int[MAXT];\n\tpublic static long[] lxv = new long[MAXT];\n\tpublic static long[] lyv = new long[MAXT];\n\tpublic static int[] rx = new int[MAXT];\n\tpublic static int[] ry = new int[MAXT];\n\tpublic static long[] rxv = new long[MAXT];\n\tpublic static long[] ryv = new long[MAXT];\n\tpublic static int cntt;\n\n\tpublic static long ans;\n\n\tpublic static void addEdge0(int u, int v, long w) {\n\t\tnext0[++cnt0] = head0[u];\n\t\tto0[cnt0] = v;\n\t\tweight0[cnt0] = w;\n\t\thead0[u] = cnt0;\n\t}\n\n\tpublic static void addEdge1(int u, int v, long w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, long w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addEdge3(int u, int v, long w) {\n\t\tnext3[++cnt3] = head3[u];\n\t\tto3[cnt3] = v;\n\t\tweight3[cnt3] = w;\n\t\thead3[u] = cnt3;\n\t}\n\n\tpublic static void dfsTree2(int u, int fa, long dep) {\n\t\tdep2[u] = dep;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsTree2(v, u, dep + weight2[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rebuildTree1(int u, int fa) {\n\t\tint last = 0;\n\t\tfor (int e = head0[u]; e > 0; e = next0[e]) {\n\t\t\tint v = to0[e];\n\t\t\tlong w = weight0[e];\n\t\t\tif (v != fa) {\n\t\t\t\tif (last == 0) {\n\t\t\t\t\tlast = u;\n\t\t\t\t\taddEdge1(u, v, w);\n\t\t\t\t\taddEdge1(v, u, w);\n\t\t\t\t} else {\n\t\t\t\t\tint add = ++cntn;\n\t\t\t\t\taddEdge1(last, add, 0);\n\t\t\t\t\taddEdge1(add, last, 0);\n\t\t\t\t\taddEdge1(add, v, w);\n\t\t\t\t\taddEdge1(v, add, w);\n\t\t\t\t\tlast = add;\n\t\t\t\t}\n\t\t\t\trebuildTree1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void getSize(int u, int fa) {\n\t\tsiz[u] = 1;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tgetSize(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getCentroidEdge(int u, int fa) {\n\t\tgetSize(u, fa);\n\t\tint total = siz[u];\n\t\tint half = total >> 1;\n\t\tboolean find = false;\n\t\twhile (!find) {\n\t\t\tfind = true;\n\t\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tif (v != fa && !vis[e >> 1] && siz[v] > half) {\n\t\t\t\t\tfa = u;\n\t\t\t\t\tu = v;\n\t\t\t\t\tfind = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint best = 0, edge = 0;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif (!vis[e >> 1]) {\n\t\t\t\tint v = to1[e];\n\t\t\t\tint sub = v == fa ? (total - siz[u]) : siz[v];\n\t\t\t\tif (sub > best) {\n\t\t\t\t\tbest = sub;\n\t\t\t\t\tedge = e;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn edge;\n\t}\n\n\tpublic static void dfsTree1(int u, int fa, long path, int op) {\n\t\tif (u <= n) {\n\t\t\tif (up[u] == 0) {\n\t\t\t\tup[u] = ++cntt;\n\t\t\t\troot[u] = cntt;\n\t\t\t}\n\t\t\tint cur = up[u];\n\t\t\tint nxt = ++cntt;\n\t\t\tlong val = path + dep2[u];\n\t\t\tif (op == 0) {\n\t\t\t\tls[cur] = nxt;\n\t\t\t\tlx[cur] = ly[cur] = u;\n\t\t\t\tlxv[cur] = lyv[cur] = val;\n\t\t\t} else {\n\t\t\t\trs[cur] = nxt;\n\t\t\t\trx[cur] = ry[cur] = u;\n\t\t\t\trxv[cur] = ryv[cur] = val;\n\t\t\t}\n\t\t\tup[u] = nxt;\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa && !vis[e >> 1]) {\n\t\t\t\tdfsTree1(v, u, path + weight1[e], op);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void solveTree1(int u) {\n\t\tint edge = getCentroidEdge(u, 0);\n\t\tif (edge > 0) {\n\t\t\tvis[edge >> 1] = true;\n\t\t\tint v1 = to1[edge];\n\t\t\tint v2 = to1[edge ^ 1];\n\t\t\tdfsTree1(v1, 0, 0, 0);\n\t\t\tdfsTree1(v2, 0, weight1[edge], 1);\n\t\t\tsolveTree1(v1);\n\t\t\tsolveTree1(v2);\n\t\t}\n\t}\n\n\tpublic static int getUp(int x, int y) {\n\t\treturn dfn[x] < dfn[y] ? x : y;\n\t}\n\n\tpublic static void dfsTree3(int u, int fa, long dist) {\n\t\tdfn[u] = ++cntd;\n\t\trmq[dfn[u]][0] = fa;\n\t\tdist3[u] = dist;\n\t\tfor (int e = head3[u]; e > 0; e = next3[e]) {\n\t\t\tint v = to3[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsTree3(v, u, dist + weight3[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rmqTree3() {\n\t\tdfsTree3(1, 0, 0);\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tlg2[i] = lg2[i >> 1] + 1;\n\t\t}\n\t\tfor (int pre = 0, cur = 1; cur <= lg2[n]; pre++, cur++) {\n\t\t\tfor (int i = 1; i + (1 << cur) - 1 <= n; i++) {\n\t\t\t\trmq[i][cur] = getUp(rmq[i][pre], rmq[i + (1 << pre)][pre]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lcaTree3(int x, int y) {\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tx = dfn[x];\n\t\ty = dfn[y];\n\t\tif (x > y) {\n\t\t\tint tmp = x; x = y; y = tmp;\n\t\t}\n\t\tx++;\n\t\tint k = lg2[y - x + 1];\n\t\treturn getUp(rmq[x][k], rmq[y - (1 << k) + 1][k]);\n\t}\n\n\tpublic static long getDist3(int x, int y) {\n\t\treturn dist3[x] + dist3[y] - dist3[lcaTree3(x, y)] * 2;\n\t}\n\n\tpublic static long getDist(int x, int y, long xv, long yv) {\n\t\tif (x == y) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn getDist3(x, y) + xv + yv;\n\t}\n\n\tpublic static int a, b, c, d;\n\tpublic static long av, bv, cv, dv;\n\n\tpublic static void getInfo(int i, int j, int iop, int jop) {\n\t\tif (iop == 0) {\n\t\t\ta = lx[i]; b = ly[i]; av = lxv[i]; bv = lyv[i];\n\t\t} else {\n\t\t\ta = rx[i]; b = ry[i]; av = rxv[i]; bv = ryv[i];\n\t\t}\n\t\tif (jop == 0) {\n\t\t\tc = lx[j]; d = ly[j]; cv = lxv[j]; dv = lyv[j];\n\t\t} else {\n\t\t\tc = rx[j]; d = ry[j]; cv = rxv[j]; dv = ryv[j];\n\t\t}\n\t}\n\n\tpublic static long bestCross(int i, int j, int iop, int jop) {\n\t\tgetInfo(i, j, iop, jop);\n\t\tlong p1 = getDist(a, c, av, cv);\n\t\tlong p2 = getDist(a, d, av, dv);\n\t\tlong p3 = getDist(b, c, bv, cv);\n\t\tlong p4 = getDist(b, d, bv, dv);\n\t\treturn Math.max(Math.max(p1, p2), Math.max(p3, p4));\n\t}\n\n\tpublic static int x, y;\n\tpublic static long xv, yv;\n\tpublic static long bestDist;\n\n\tpublic static void better(int curx, int cury, long curxv, long curyv) {\n\t\tif (curx == 0 || cury == 0) {\n\t\t\treturn;\n\t\t}\n\t\tlong curDist = getDist(curx, cury, curxv, curyv);\n\t\tif (curDist > bestDist) {\n\t\t\tx = curx; y = cury; xv = curxv; yv = curyv;\n\t\t\tbestDist = curDist;\n\t\t}\n\t}\n\n\tpublic static void mergeInfo(int i, int j, int op) {\n\t\tgetInfo(i, j, op, op);\n\t\tx = y = 0;\n\t\txv = yv = 0;\n\t\tbestDist = -INF;\n\t\tbetter(a, b, av, bv);\n\t\tbetter(c, d, cv, dv);\n\t\tbetter(a, c, av, cv);\n\t\tbetter(a, d, av, dv);\n\t\tbetter(b, c, bv, cv);\n\t\tbetter(b, d, bv, dv);\n\t\tif (op == 0) {\n\t\t\tlx[i] = x; ly[i] = y; lxv[i] = xv; lyv[i] = yv;\n\t\t} else {\n\t\t\trx[i] = x; ry[i] = y; rxv[i] = xv; ryv[i] = yv;\n\t\t}\n\t}\n\n\tpublic static int mergeTree(int i, int j, long add) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tif (ls[i] > 0 && rs[j] > 0) {\n\t\t\tans = Math.max(ans, bestCross(i, j, 0, 1) + add);\n\t\t}\n\t\tif (rs[i] > 0 && ls[j] > 0) {\n\t\t\tans = Math.max(ans, bestCross(i, j, 1, 0) + add);\n\t\t}\n\t\tmergeInfo(i, j, 0);\n\t\tmergeInfo(i, j, 1);\n\t\tls[i] = mergeTree(ls[i], ls[j], add);\n\t\trs[i] = mergeTree(rs[i], rs[j], add);\n\t\treturn i;\n\t}\n\n\tpublic static void compute(int u, int fa) {\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcompute(v, u);\n\t\t\t\troot[u] = mergeTree(root[u], root[v], -dep2[u] * 2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tint u, v;\n\t\tlong w;\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge0(u, v, w);\n\t\t\taddEdge0(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge2(u, v, w);\n\t\t\taddEdge2(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextLong();\n\t\t\taddEdge3(u, v, w);\n\t\t\taddEdge3(v, u, w);\n\t\t}\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tans = -INF;\n\t\tdfsTree2(1, 0, 0);\n\t\trebuildTree1(1, 0);\n\t\tsolveTree1(1);\n\t\trmqTree3();\n\t\tcompute(1, 0);\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code05_Passage2.java`\n\n```java\npackage class187;\n\n// 通道，C++版\n// 三棵树t1、t2、t3都有n个节点，各自给定n-1条边以及每条边的边权，边权没有负数\n// 点对(x, y)，要求两点必须不同，两点在树上的距离就是简单路径上边权的累加和\n// 点对(x, y)，在t1、t2、t3的距离，分别记为dis1(x, y)、dis2(x, y)、dis3(x, y)\n// 打印最大的dis1(x, y) + dis2(x, y) + dis3(x, y)\n// 2 <= n <= 10^5\n// 0 <= 边权 <= 10^12\n// 测试链接 : https://www.luogu.com.cn/problem/P4220\n// 测试链接 : https://loj.ac/p/2339\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 100001;\n//const int MAXM = MAXN << 1;\n//const int MAXP = 20;\n//const int MAXT = MAXN * 20;\n//const ll INF = 1LL << 60;\n//int n, cntn;\n//\n//int head0[MAXN];\n//int next0[MAXN << 1];\n//int to0[MAXN << 1];\n//ll weight0[MAXN << 1];\n//int cnt0;\n//\n//int head1[MAXM];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//ll weight1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN];\n//int next2[MAXN << 1];\n//int to2[MAXN << 1];\n//ll weight2[MAXN << 1];\n//int cnt2;\n//\n//int head3[MAXN];\n//int next3[MAXN << 1];\n//int to3[MAXN << 1];\n//ll weight3[MAXN << 1];\n//int cnt3;\n//\n//ll dep2[MAXN];\n//ll dist3[MAXN];\n//\n//bool vis[MAXM];\n//int siz[MAXM];\n//\n//int dfn[MAXN];\n//int lg2[MAXN];\n//int rmq[MAXN][MAXP];\n//int cntd;\n//\n//int up[MAXN];\n//int root[M