return false;\n//                }\n//                y = b[end];\n//            }\n//            outDeg[x]++;\n//            inDeg[y]++;\n//            edgeCnt++;\n//            addEdge(x, y, i);\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (inDeg[i] != outDeg[i]) {\n//            return false;\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cur[i] = headg[i];\n//    }\n//    return true;\n//}\n//\n//void euler(int u, int h) {\n//    for (int e = cur[u]; e > 0; e = cur[u]) {\n//        cur[u] = nextg[e];\n//        euler(tog[e], chainHead[e]);\n//    }\n//    path[++cntp] = h;\n//}\n//\n//void decompress() {\n//    ans[++cnta] = 1;\n//    for (int i = cntp - 1; i >= 1; i--) {\n//        int e = path[i];\n//        while (e > 0) {\n//            ans[++cnta] = b[e];\n//            e = etoe[e];\n//        }\n//    }\n//}\n//\n//bool compute() {\n//    if (!linkEdge()) {\n//        return false;\n//    }\n//    if (!compress()) {\n//        return false;\n//    }\n//    euler(1, -1);\n//    if (cntp != edgeCnt + 1) {\n//        return false;\n//    }\n//    decompress();\n//    return cnta == m + 1;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//    }\n//    cin >> t;\n//    for (int i = 1, siz, idx = 0; i <= t; i++) {\n//        cin >> siz;\n//        seq[++idx] = siz;\n//        for (int j = 1; j <= siz; j++) {\n//            cin >> seq[++idx];\n//        }\n//    }\n//    bool check = compute();\n//    if (!check) {\n//        cout << "NIE\\n";\n//    } else {\n//        cout << "TAK\\n";\n//        for (int i = 1; i <= cnta; i++) {\n//            cout << ans[i] << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code11_DingXiangRoad1.java`\n\n```java\npackage class188;\n\n// 丁香之路，java版\n// 一共有n个点，点i和点j的距离为|i - j|，所以这是完全图，边是无向边\n// 给定m个点对，每个点对(a, b)，保证 a != b，表示a和b之间的无向边做了标记\n// 给定起点s，不管终点是什么，每条被标记的无向边，走过至少一次\n// 打印起点s，终点i的情况下，走过路程的最小距离是多少\n// 终点i可以是1~n中的任意一点，所以一共打印n个数值\n// 1 <= n <= 2500\n// m <= n个顶点的完全图的边数\n// 测试链接 : https://www.luogu.com.cn/problem/P6628\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\nimport java.util.Comparator;\nimport java.util.TreeSet;\n\npublic class Code11_DingXiangRoad1 {\n\n\tpublic static int MAXN = 3001;\n\tpublic static int MAXM = 3000001;\n\tpublic static int n, m, s;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static boolean[] fix = new boolean[MAXN];\n\tpublic static TreeSet<Integer> nodeSet = new TreeSet<>();\n\tpublic static int[] nodeArr = new int[MAXN];\n\tpublic static int cnt;\n\n\tpublic static int[] fa1 = new int[MAXN];\n\tpublic static int[] deg1 = new int[MAXN];\n\tpublic static int[] fa2 = new int[MAXN];\n\tpublic static int[] deg2 = new int[MAXN];\n\n\t// u、v、w\n\tpublic static int[][] edgeArr = new int[MAXN][3];\n\n\tpublic static long sum;\n\n\tpublic static class EdgeCmp implements Comparator<int[]> {\n\t\t@Override\n\t\tpublic int compare(int[] e1, int[] e2) {\n\t\t\tif (e1[2] != e2[2]) {\n\t\t\t\treturn e1[2] - e2[2];\n\t\t\t}\n\t\t\tif (e1[0] != e2[0]) {\n\t\t\t\treturn e1[0] - e2[0];\n\t\t\t}\n\t\t\treturn e1[1] - e2[1];\n\t\t}\n\t}\n\n\tpublic static int dist(int x, int y) {\n\t\treturn Math.abs(x - y);\n\t}\n\n\tpublic static int find(int[] fa, int x) {\n\t\tif (x != fa[x]) {\n\t\t\tfa[x] = find(fa, fa[x]);\n\t\t}\n\t\treturn fa[x];\n\t}\n\n\tpublic static void union(int[] fa, int x, int y) {\n\t\tint fx = find(fa, x);\n\t\tint fy = find(fa, y);\n\t\tif (fx != fy) {\n\t\t\tfa[fx] = fy;\n\t\t}\n\t}\n\n\tpublic static long kruskal() {\n\t\tlong cost = 0;\n\t\tint edgeCnt = cnt - 1;\n\t\tArrays.sort(edgeArr, 1, edgeCnt + 1, new EdgeCmp());\n\t\tfor (int i = 1; i <= edgeCnt; i++) {\n\t\t\tint u = edgeArr[i][0];\n\t\t\tint v = edgeArr[i][1];\n\t\t\tint w = edgeArr[i][2];\n\t\t\tif (find(fa2, u) != find(fa2, v)) {\n\t\t\t\tcost += w * 2;\n\t\t\t\tunion(fa2, u, v);\n\t\t\t}\n\t\t}\n\t\treturn cost;\n\t}\n\n\tpublic static long compute(int start, int end) {\n\t\tcnt = 0;\n\t\tfor (int x : nodeSet) {\n\t\t\tnodeArr[++cnt] = x;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfa2[i] = find(fa1, i);\n\t\t\tdeg2[i] = deg1[i];\n\t\t}\n\t\tlong ans = sum;\n\t\tdeg2[start]++;\n\t\tdeg2[end]++;\n\t\tunion(fa2, start, end);\n\t\tfor (int i = 1, p = 0; i <= cnt; i++) {\n\t\t\tif ((deg2[nodeArr[i]] & 1) == 1) {\n\t\t\t\tif (p == 0) {\n\t\t\t\t\tp = i;\n\t\t\t\t} else {\n\t\t\t\t\tans += dist(nodeArr[p], nodeArr[i]);\n\t\t\t\t\twhile (p < i) {\n\t\t\t\t\t\tunion(fa2, nodeArr[p++], nodeArr[i]);\n\t\t\t\t\t}\n\t\t\t\t\tp = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= cnt - 1; i++) {\n\t\t\tedgeArr[i][0] = nodeArr[i];\n\t\t\tedgeArr[i][1] = nodeArr[i + 1];\n\t\t\tedgeArr[i][2] = nodeArr[i + 1] - nodeArr[i];\n\t\t}\n\t\tans += kruskal();\n\t\treturn ans;\n\t}\n\n\tpublic static void prepare() {\n\t\tfix[s] = true;\n\t\tnodeSet.add(s);\n\t\tsum = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfa1[i] = i;\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = a[i];\n\t\t\tv = b[i];\n\t\t\tdeg1[u]++;\n\t\t\tdeg1[v]++;\n\t\t\tfix[u] = true;\n\t\t\tfix[v] = true;\n\t\t\tnodeSet.add(u);\n\t\t\tnodeSet.add(v);\n\t\t\tunion(fa1, u, v);\n\t\t\tsum += dist(u, v);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\ts = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (!fix[i]) {\n\t\t\t\tnodeSet.add(i);\n\t\t\t}\n\t\t\tout.print(compute(s, i) + " ");\n\t\t\tif (!fix[i]) {\n\t\t\t\tnodeSet.remove(i);\n\t\t\t}\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code11_DingXiangRoad2.java`\n\n```java\npackage class188;\n\n// 丁香之路，C++版\n// 一共有n个点，点i和点j的距离为|i - j|，所以这是完全图，边是无向边\n// 给定m个点对，每个点对(a, b)，保证 a != b，表示a和b之间的无向边做了标记\n// 给定起点s，不管终点是什么，每条被标记的无向边，走过至少一次\n// 打印起点s，终点i的情况下，走过路程的最小距离是多少\n// 终点i可以是1~n中的任意一点，所以一共打印n个数值\n// 1 <= n <= 2500\n// m <= n个顶点的完全图的边数\n// 测试链接 : https://www.luogu.com.cn/problem/P6628\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//struct Edge {\n//    int u, v, w;\n//};\n//\n//bool EdgeCmp(Edge e1, Edge e2) {\n//    if (e1.w != e2.w) {\n//        return e1.w < e2.w;\n//    }\n//    if (e1.u != e2.u) {\n//        return e1.u < e2.u;\n//    }\n//    return e1.v < e2.v;\n//}\n//\n//const int MAXN = 3001;\n//const int MAXM = 3000001;\n//int n, m, s;\n//int a[MAXM];\n//int b[MAXM];\n//\n//bool fix[MAXN];\n//set<int> nodeSet;\n//int nodeArr[MAXN];\n//int cnt;\n//\n//int fa1[MAXN];\n//int deg1[MAXN];\n//int fa2[MAXN]