测试链接 : https://atcoder.jp/contests/abc318/tasks/abc318_g\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_PathProblem1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 200001;\n\tpublic static int n, m, a, b, c, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static boolean[] flag = new boolean[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tdep[u] = dep[f] + 1;\n\t\tfa[u] = f;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean check() {\n\t\tfor (int e = head2[b]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tflag[v] = true;\n\t\t}\n\t\twhile (a != c) {\n\t\t\tif (dep[a] < dep[c]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = c;\n\t\t\t\tc = tmp;\n\t\t\t}\n\t\t\ta = fa[a];\n\t\t\tif (flag[a]) {\n\t\t\t\treturn true;\n\t\t\t}\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\ta = in.nextInt();\n\t\tb = in.nextInt();\n\t\tc = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs(1, 0);\n\t\tout.println(check() ? "Yes" : "No");\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_PathProblem2.java`\n\n```java\npackage class194;\n\n// 路径问题，C++版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通，无重边和自环\n// 给定三个不同的点a、b、c，打印是否存在一条路径\n// 从a到达b，然后从b到达c，要求途中不能出现重复的点\n// 1 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc318_g\n// 测试链接 : https://atcoder.jp/contests/abc318/tasks/abc318_g\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXM = 200001;\n//int n, m, a, b, c, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[MAXM << 2];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int dep[MAXN << 1];\n//int fa[MAXN << 1];\n//bool flag[MAXN << 1];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        int v = to1[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] >= dfn[u]) {\n//                cntn++;\n//                addEdge2(cntn, u);\n//                addEdge2(u, cntn);\n//                int pop;\n//                do {\n//                    pop = sta[top--];\n//                    addEdge2(cntn, pop);\n//                    addEdge2(pop, cntn);\n//                } while (pop != v);\n//            }\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//void dfs(int u, int f) {\n//    dep[u] = dep[f] + 1;\n//    fa[u] = f;\n//    for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != f) {\n//            dfs(v, u);\n//        }\n//    }\n//}\n//\n//bool check() {\n//    for (int e = head2[b]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        flag[v] = true;\n//    }\n//    while (a != c) {\n//        if (dep[a] < dep[c]) {\n//            swap(a, c);\n//        }\n//        a = fa[a];\n//        if (flag[a]) {\n//            return true;\n//        }\n//    }\n//    return false;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> a >> b >> c;\n//    cntn = n;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge1(u, v);\n//        addEdge1(v, u);\n//    }\n//    tarjan(1);\n//    dfs(1, 0);\n//    cout << (check() ? "Yes" : "No") << "\\n";\n//    return 0;\n//}\n```\n\n### `Code04_Blockade1.java`\n\n```java\npackage class194;\n\n// 城市阻断，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通\n// 对每个点i，打印如下的答案\n// 节点i相连的边去掉以后，无向图有多少点对(x, y)，x和y不连通\n// 注意(x, y)和(y, x)是不同点对\n// 删掉和i相连的边，但是节点i本身不删掉，要参与点对数量的计算\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3469\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Blockade1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 500001;\n\tpublic static int n, m, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// dfs过程中，子树中的圆点数量\n\tpublic static int[] siz = new int[MAXN << 1];\n\n\t// 每个原图中的点，如果把相邻的边删掉，所统计的答案\n\tpublic static long[] ans = new long[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN << 1][4];\n\tpublic static int u, status, fa, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int fa, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = fa;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\tfa = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head1[u];\n\t\t\t} else {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\t\tcntn++;\n\t\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = next1[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, 0, e);\n\t\t\t\t\tpush(v, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, 0, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dpOnTree1(int u, int fa) {\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdpOnTree1(v, u);\n\t\t\t\tif (u <= n) {\n\t\t\t\t\tans[u] += 1L * siz[v] * (n - siz[v] - 1);\n\t\t\t\t}\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t\tsiz[u] += u <= n ? 1 : 0;\n\t\tif (u <= n) {\n\t\t\tans[u] += 1L * (n - siz[u]) * (siz[u] - 1);\n\t\t\tans[u] += 2L * (n - 1);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dpOnTree2(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head2[u];\n\t\t\t} else {\n\t\t\t\te = next2[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, fa, e);\n\t\t\t\tif (to2[e] != fa) {\n\t\t\t\t\tpush(to2[e], 0, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head2[u]; ei > 0; ei = next2[ei]) {\n\t\t\t\t\tint v = to2[ei];\n\t\t\t\t\tif (v != fa) {\n\t\t\t\t\t\tif (u <= n) {\n\t\t\t\t\t\t\tans[u] += 1L * siz[v] * (n - siz[v] - 1);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tsiz[u] += u <= n ? 1 : 0;\n\t\t\t\tif (u <= n) {\n\t\t\t\t\tans[u] += 1L * (n - siz[u]) * (siz[u] - 1);\n\t\t\t\t\tans[u] += 2L * (n - 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\t// tarjan1(1);\n\t\ttarjan2(1);\n\t\t// dpOnTree1(1, 0);\n\t\tdpOnTree2(1, 0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Blockade2.java`\n\n```java\npackage class194;\n\n// 城市阻断，C++版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通\n// 对每个点i，打印如下的答案\n// 节点i相连的边去掉以后，无向图有多少点对(x, y)，x和y不连通\n// 注意(x, y)和(y, x)是不同点对\n// 删掉和i相连的边，但是节点i本身不删掉，要参与点对数量的计算\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3469\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 100001;\n//const int MAXM = 500001;\n//int n, m, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[