n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Duathlon1.java`\n\n```java\npackage class194;\n\n// 铁人两项，java版\n// 给定一张无向图，一共n个点、m条边，图中可能存在多个连通区\n// 有效的点对三元组(a, b, c)，首先要求a、b、c是不同的点\n// 其次要求存在一条从a出发，经过b，最终到达c的路径，沿途无重复节点\n// 打印有效的点对三元组的数量\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4630\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Duathlon1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int n, m, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// 方点才有deg，点双连通分量的节点数，也就是度\n\tpublic static int[] deg = new int[MAXN << 1];\n\n\t// dfs过程中，子树中的圆点数量\n\tpublic static int[] siz = new int[MAXN << 1];\n\n\t// 当前连通区的总节点数\n\tpublic static int total;\n\n\t// 答案\n\tpublic static long ans;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN << 1][4];\n\tpublic static int u, status, fa, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int fa, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = fa;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\tfa = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\ttotal++;\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tdeg[cntn]++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t\tdeg[cntn]++;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\ttotal++;\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head1[u];\n\t\t\t} else {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\t\tcntn++;\n\t\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\t\tdeg[cntn]++;\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t\t\tdeg[cntn]++;\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = next1[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to1[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, 0, e);\n\t\t\t\t\tpush(v, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, 0, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dpOnTree1(int u, int fa) {\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdpOnTree1(v, u);\n\t\t\t\tif (u <= n) {\n\t\t\t\t\tans += 1L * siz[v] * (total - siz[v] - 1);\n\t\t\t\t} else {\n\t\t\t\t\tans += 1L * siz[v] * (deg[u] - 2) * (total - siz[v]);\n\t\t\t\t}\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t\tsiz[u] += u <= n ? 1 : 0;\n\t\tif (u <= n) {\n\t\t\tans += 1L * (siz[u] - 1) * (total - siz[u]);\n\t\t} else {\n\t\t\tans += 1L * siz[u] * (deg[u] - 2) * (total - siz[u]);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void dpOnTree2(int cur, int father) {\n\t\tstacksize = 0;\n\t\tpush(cur, 0, fa, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head2[u];\n\t\t\t} else {\n\t\t\t\te = next2[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, fa, e);\n\t\t\t\tif (to2[e] != fa) {\n\t\t\t\t\tpush(to2[e], 0, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head2[u]; ei > 0; ei = next2[ei]) {\n\t\t\t\t\tint v = to2[ei];\n\t\t\t\t\tif (v != fa) {\n\t\t\t\t\t\tif (u <= n) {\n\t\t\t\t\t\t\tans += 1L * siz[v] * (total - siz[v] - 1);\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tans += 1L * siz[v] * (deg[u] - 2) * (total - siz[v]);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tsiz[u] += siz[v];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tsiz[u] += u <= n ? 1 : 0;\n\t\t\t\tif (u <= n) {\n\t\t\t\t\tans += 1L * (siz[u] - 1) * (total - siz[u]);\n\t\t\t\t} else {\n\t\t\t\t\tans += 1L * siz[u] * (deg[u] - 2) * (total - siz[u]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttotal = 0;\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t\t// dpOnTree1(i, 0);\n\t\t\t\tdpOnTree2(i, 0);\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Duathlon2.java`\n\n```java\npackage class194;\n\n// 铁人两项，C++版\n// 给定一张无向图，一共n个点、m条边，图中可能存在多个连通区\n// 有效的点对三元组(a, b, c)，首先要求a、b、c是不同的点\n// 其次要求存在一条从a出发，经过b，最终到达c的路径，沿途无重复节点\n// 打印有效的点对三元组的数量\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4630\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 100001;\n//const int MAXM = 200001;\n//int n, m, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[MAXM << 2];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int deg[MAXN << 1];\n//int siz[MAXN << 1];\n//int total;\n//ll ans;\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//void tarjan(int u) {\n//    total++;\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        int v = to1[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] >= dfn[u]) {\n//                cntn++;\n//                addEdge2(cntn, u);\n//                addEdge2(u, cntn);\n//                deg[cntn]++;\n//                int pop;\n//                do {\n//                    pop = sta[top--];\n//                    addEdge2(cntn, pop);\n//                    addEdge2(pop, cntn);\n//                    deg[cntn]++;\n//                } while (pop != v);\n//            }\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//void dpOnTree(int u, int fa) {\n//    for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa) {\n//            dpOnTree(v, u);\n//            if (u <= n) {\n//                ans += 1LL * siz[v] * (total - siz[v] - 1);\n//            } else {\n//                ans += 1LL * siz[v] * (deg[u] - 2) * (total - siz[v]);\n//            }\n//            siz[u] += siz[v];\n//        }\n//    }\n//    siz[u] += u <= n ? 1 : 0;\n//    if (u <= n) {\n//        ans += 1LL * (siz[u] - 1) * (total - siz[u]);\n//    } else {\n//        ans += 1LL * siz[u] * (deg[u] - 2) * (total - siz[u]);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntn = n;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge1(u, v);\n//        addEdge1(v, u);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            total = 0;\n//            tarjan(i);\n//            dpOnTree(i, 0);\n//        }\n//    }\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code06_EdgeQueries1.java`\n\n```java\npackage class194;\n\n// 边的查询，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通\n// 一共q条查询，格式 x y，含义如下\n// 所有从x到y的简单路径上出现的边中，统计有多少条边满足\n// 如果移除该边，x和y仍然可以互相到达，打印这个数量\n// 1 <= n、m、q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1763F\n// 测试链接 : https://codeforces.com/problemset/problem/1763/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_EdgeQueries1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q, cntn;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[][] stjump = new int[MAXN << 1][MAXP];\n\tpublic static int[] edgeCnt = new int[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int x, int y) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[x][p]] >= dep[y]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn x;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[x][p] != stjump[y][p]) {\n\t\t\t\tx = stjump[x][p];\n\t\t\t\ty = stjump[y][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[x][0];\n\t}\n\n\tpublic static void dfsCnt(int u, int fa) {\n\t\tedgeCnt[u] += edgeCnt[fa];\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfsCnt(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void buildEdgeCnt() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint fa = stjump[a[i]][0];\n\t\t\tint fb = stjump[b[i]][0];\n\t\t\tif (fa == fb || stjump[fa][0] == b[i]) {\n\t\t\t\tedgeCnt[fa]++;\n\t\t\t} else {\n\t\t\t\tedgeCnt[fb]++;\n\t\t\t}\n\t\t}\n\t\tfor (int i = n + 1; i <= cntn; i++) {\n\t\t\tif (edgeCnt[i] == 1) {\n\t\t\t\tedgeCnt[i] = 0;\n\t\t\t}\n\t\t}\n\t\tdfsCnt(1, 0);\n\t}\n\n\tpublic static int query(int x, int y) {\n\t\tint xylca = getLca(x, y);\n\t\tint lcafa = stjump[xylca][0];\n\t\treturn edgeCnt[x] + edgeCnt[y] - edgeCnt[xylca] - edgeCnt[lcafa];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge1(a[i], b[i]);\n\t\t\taddEdge1(b[i], a[i]);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs(1, 0);\n\t\tbuildEdgeCnt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tout.println(query(x, y));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_EdgeQueries2.java`\n\n```java\npackage class194;\n\n// 边的查询，C++版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通\n// 一共q条查询，格式 x y，含义如下\n// 所有从x到y的简单路径上出现的边中，统计有多少条边满足\n// 如果移除该边，x和y仍然可以互相到达，打印这个数量\n// 1 <= n、m、q <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1763F\n// 测试链接 : https://codeforces.com/problemset/problem/1763/F\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXM = 200001;\n//const int MAXP = 20;\n//int n, m, q, cntn;\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[MAXM << 2];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int dep[MAXN << 1];\n//int stjump[MAXN << 1][MAXP];\n//int edgeCnt[MAXN << 1];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        int v = to1[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] >= dfn[u]) {\n//                cntn++;\n//                addEdge2(cntn, u);\n//                addEdge2(u, cntn);\n//                int pop;\n//                do {\n//                    pop = sta[top--];\n//                    addEdge2(cntn, pop);\n//                    addEdge2(pop, cntn);\n//                } while (pop != v);\n//            }\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//void dfs(int u, int fa) {\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa) {\n//            dfs(v, u);\n//        }\n//    }\n//}\n//\n//int getLca(int x, int y) {\n//    if (dep[x] < dep[y]) {\n//        swap(x, y);\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (dep[stjump[x][p]] >= dep[y]) {\n//            x = stjump[x][p];\n//        }\n//    }\n//    if (x == y) {\n//        return x;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (stjump[x][p] != stjump[y][p]) {\n//            x = stjump[x][p];\n//            y = stjump[y][p];\n//        }\n//    }\n//    return stjump[x][0];\n//}\n//\n//void dfsCnt(int u, int fa) {\n//    edgeCnt[u] += edgeCnt[fa];\n//    for (int e = head2[u]; e > 0; e = next2[e]) {\n//        int v = to2[e];\n//        if (v != fa) {\n//            dfsCnt(v, u);\n//        }\n//    }\n//}\n//\n//void buildEdgeCnt() {\n//    for (int i = 1; i <= m; i++) {\n//        int fa = stjump[a[i]][0];\n//        int fb = stjump[b[i]][0];\n//        if (fa == fb || stjump[fa][0] == b[i]) {\n//            edgeCnt[fa]++;\n//        } else {\n//            edgeCnt[fb]++;\n//        }\n//    }\n//    for (int i = n + 1; i <= cntn; i++) {\n//        if (edgeCnt[i] == 1) {\n//            edgeCnt[i] = 0;\n//        }\n//    }\n//    dfsCnt(1, 0);\n//}\n//\n//int query(int x, int y) {\n//    int xylca = getLca(x, y);\n//    int lcafa = stjump[xylca][0];\n//    return edgeCnt[x] + edgeCnt[y] - edgeCnt[xylca] - edgeCnt[lcafa];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntn = n;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//        addEdge1(a[i], b[i]);\n//        addEdge1(b[i], a[i]);\n//    }\n//    tarjan(1);\n//    dfs(1, 0);\n//    buildEdgeCnt();\n//    cin >> q;\n//    for (int i = 1, x, y; i <= q; i++) {\n//        cin >> x >> y;\n//        cout << query(x, y) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_Policija1.java`\n\n```java\npackage class194;\n\n// 警察，java版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通并且无重边\n// 一共q条查询，每条查询是如下两种类型中的一种\n// 查询 1 a b c d : 已知c和d之间有边，如果删去这条边，打印a和b是否连通\n// 查询 2 a b c   : 如果删除点c，打印a和b是否连通\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 1 <= q <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4334\n// 提交以下的code，提交时请把类名改成"Main"\n// 本题卡常导致java的实现无法通过，很多递归函数索性也不改迭代了\n// 想通过用C++实现，本节课Code07_Policija2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\n\npublic class Code07_Policija1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 500001;\n\tpublic static int n, m, q, cntn;\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int cnts;\n\n\tpublic static HashMap<Long, Integer> cutMap = new HashMap<>();\n\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[] son = new int[MAXN << 1];\n\tpublic static int[] top = new int[MAXN << 1];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addCut(int x, int y, int cut) {\n\t\tint a = Math.min(x, y);\n\t\tint b = Math.max(x, y);\n\t\tcutMap.put(((long) a << 32) | b, cut);\n\t}\n\n\tpublic static int getCut(int x, int y) {\n\t\tint a = Math.min(x, y);\n\t\tint b = Math.max(x, y);\n\t\tInteger ans = cutMap.get(((long) a << 32) | b);\n\t\treturn ans == null ? 0 : ans;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++cnts] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\t\taddCut(u, v, cntn);\n\t\t\t\t\t}\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[cnts--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean mustPass(int a, int b, int c) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] < dep[top[b]]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = b;\n\t\t\t\tb = tmp;\n\t\t\t}\n\t\t\tif (top[c] == top[a] && dep[c] <= dep[a]) {\n\t\t\t\treturn true;\n\t\t\t}\n\t\t\ta = fa[top[a]];\n\t\t}\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\treturn top[a] == top[c] && dep[b] <= dep[c] && dep[c] <= dep[a];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, op, a, b, c, d; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\td = in.nextInt();\n\t\t\t\tint cut = getCut(c, d);\n\t\t\t\tif (cut == 0) {\n\t\t\t\t\tout.println("yes");\n\t\t\t\t} else {\n\t\t\t\t\tout.println(mustPass(a, b, cut) ? "no" : "yes");\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\tout.println(mustPass(a, b, c) ? "no" : "yes");\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_Policija2.java`\n\n```java\npackage class194;\n\n// 警察，C++版\n// 给定一张无向图，一共n个点、m条边，所有点保证连通并且无重边\n// 一共q条查询，每条查询是如下两种类型中的一种\n// 查询 1 a b c d : 已知c和d之间有边，如果删去这条边，打印a和b是否连通\n// 查询 2 a b c   : 如果删除点c，打印a和b是否连通\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 1 <= q <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4334\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 500001;\n//int n, m, q, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[MAXM << 2];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int cnts;\n//\n//map<pair<int, int>, int> cutMap;\n//\n//int fa[MAXN << 1];\n//int dep[MAXN << 1];\n//int siz[MAXN << 1];\n//int son[MAXN << 1];\n//int top[MAXN << 1];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//void addCut(int x, int y, int cut) {\n//    int a = min(x, y);\n//    int b = max(x, y);\n//    cutMap[{a, b}] = cut;\n//}\n//\n//int getCut(int x, int y) {\n//    int a = min(x, y);\n//    int b = max(x, y);\n//    auto ans = cutMap.find({a, b});\n//    return ans == cutMap.end() ? 0 : ans -> second;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++cnts] = u;\n//    for (int e = head1[u]; e > 0; e = next1[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to1[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] >= dfn[u]) {\n//                cntn++;\n//                if (low[v] > dfn[u]) {\n//                    addCut(u, v, cntn);\n//                }\n//                addEdge2(cntn, u);\n//                addEdge2(u, cntn);\n//                int pop;\n//                do {\n//                    pop = sta[cnts--];\n//                    addEdge2(cntn, pop);\n//                    addEdge2(pop, cntn);\n//                } while (pop != v);\n//            }\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head2[u], v; e > 0; e = next2[e]) {\n//        v = to2[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head2[u], v; e > 0; e = next2[e]) {\n//        v = to2[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//bool mustPass(int a, int b, int c) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] < dep[top[b]]) {\n//            swap(a, b);\n//        }\n//        if (top[c] == top[a] && dep[c] <= dep[a]) {\n//            return true;\n//        }\n//        a = fa[top[a]];\n//    }\n//    if (dep[a] < dep[b]) {\n//        swap(a, b);\n//    }\n//    return top[a] == top[c] && dep[b] <= dep[c] && dep[c] <= dep[a];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntn = n;\n//    cnt1 = 1;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge1(u, v);\n//        addEdge1(v, u);\n//    }\n//    tarjan(1, 0);\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    cin >> q;\n//    for (int i = 1, op, a, b, c, d; i <= q; i++) {\n//        cin >> op;\n//        if (op == 1) {\n//            cin >> a >> b >> c >> d;\n//            int cut = getCut(c, d);\n//            if (cut == 0) {\n//                cout << "yes\\n";\n//            } else {\n//                cout << (mustPass(a, b, cut) ? "no" : "yes") << "\\n";\n//            }\n//        } else {\n//            cin >> a >> b >> c;\n//            cout << (mustPass(a, b, c) ? "no" : "yes") << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code08_Tourists1.java`\n\n```java\npackage class194;\n\n// 游客，java版\n// 一共n个城市、m条双向道路，所有城市都连通，商品只有一种\n// 每个城市给定商品报价，接下来有q条操作，操作类型有两种\n// 操作 C x y : 城市x的商品报价改成y\n// 操作 A x y : 从x到y可自由选路，但不能有重复城市，打印能遇到的最低报价\n// 1 <= n、m、q <= 10^5\n// 1 <= 商品报价 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF487E\n// 测试链接 : https://codeforces.com/problemset/problem/487/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\nimport java.util.TreeMap;\n\npublic class Code08_Tourists1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 100001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m, q, cntn;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXM << 1];\n\tpublic static int[] to1 = new int[MAXM << 1];\n\tpublic static int cnt1;\n\n\tpublic static int[] head2 = new int[MAXN << 1];\n\tpublic static int[] next2 = new int[MAXM << 2];\n\tpublic static int[] to2 = new int[MAXM << 2];\n\tpublic static int cnt2;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int cnts;\n\n\t// nid是圆方树的点获得的dfn序号\n\t// cnti是圆方树的dfn序号计数\n\tpublic static int[] fa = new int[MAXN << 1];\n\tpublic static int[] dep = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[] son = new int[MAXN << 1];\n\tpublic static int[] top = new int[MAXN << 1];\n\tpublic static int[] nid = new int[MAXN << 1];\n\tpublic static int cnti;\n\n\t// 每个方点分配有序表\n\tpublic static HashMap<Integer, TreeMap<Integer, Integer>> maps = new HashMap<>();\n\t// 圆方树中每个点的点权\n\tpublic static int[] val = new int[MAXN << 1];\n\t// 线段树\n\tpublic static int[] minv = new int[MAXN << 3];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addNum(int u, int num) {\n\t\tif (!maps.containsKey(u)) {\n\t\t\tmaps.put(u, new TreeMap<>());\n\t\t}\n\t\tmaps.get(u).put(num, maps.get(u).getOrDefault(num, 0) + 1);\n\t}\n\n\tpublic static void delNum(int u, int num) {\n\t\tint cnt = maps.get(u).get(num);\n\t\tif (cnt == 1) {\n\t\t\tmaps.get(u).remove(num);\n\t\t} else {\n\t\t\tmaps.get(u).put(num, cnt - 1);\n\t\t}\n\t}\n\n\tpublic static int getMin(int u) {\n\t\treturn maps.get(u).firstKey();\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++cnts] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] >= dfn[u]) {\n\t\t\t\t\tcntn++;\n\t\t\t\t\taddEdge2(cntn, u);\n\t\t\t\t\taddEdge2(u, cntn);\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[cnts--];\n\t\t\t\t\t\taddEdge2(cntn, pop);\n\t\t\t\t\t\taddEdge2(pop, cntn);\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t\tif (u > n) {\n\t\t\t\t\taddNum(u, arr[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tnid[u] = ++cnti;\n\t\tval[nid[u]] = u <= n ? arr[u] : getMin(u);\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tminv[i] = Math.min(minv[i << 1], minv[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tminv[i] = val[l];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tminv[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn minv[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = INF;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.min(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int pathMin(int x, int y) {\n\t\tint ans = INF;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tint tmp = x;\n\t\t\t\tx = y;\n\t\t\t\ty = tmp;\n\t\t\t}\n\t\t\tans = Math.min(ans, query(nid[top[x]], nid[x], 1, cnti, 1));\n\t\t\tx = fa[top[x]];\n\t\t}\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\tans = Math.min(ans, query(nid[y], nid[x], 1, cnti, 1));\n\t\tif (y > n) {\n\t\t\tans = Math.min(ans, arr[fa[y]]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tcntn = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\ttarjan(1);\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tbuild(1, cnti, 1);\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tchar op = in.nextChar();\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tif (op == 'C') {\n\t\t\t\tint father = fa[x];\n\t\t\t\tif (father > 0) {\n\t\t\t\t\tdelNum(father, arr[x]);\n\t\t\t\t\taddNum(father, y);\n\t\t\t\t\tupdate(nid[father], getMin(father), 1, cnti, 1);\n\t\t\t\t}\n\t\t\t\tarr[x] = y;\n\t\t\t\tupdate(nid[x], y, 1, cnti, 1);\n\t\t\t} else {\n\t\t\t\tout.println(pathMin(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tchar nextChar() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')));\n\t\t\treturn (char) c;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code08_Tourists2.java`\n\n```java\npackage class194;\n\n// 游客，C++版\n// 一共n个城市、m条双向道路，所有城市都连通，商品只有一种\n// 每个城市给定商品报价，接下来有q条操作，操作类型有两种\n// 操作 C x y : 城市x的商品报价改成y\n// 操作 A x y : 从x到y可自由选路，但不能有重复城市，打印能遇到的最低报价\n// 1 <= n、m、q <= 10^5\n// 1 <= 商品报价 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/CF487E\n// 测试链接 : https://codeforces.com/problemset/problem/487/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 100001;\n//const int INF = 1000000001;\n//int n, m, q, cntn;\n//int arr[MAXN];\n//\n//int head1[MAXN];\n//int next1[MAXM << 1];\n//int to1[MAXM << 1];\n//int cnt1;\n//\n//int head2[MAXN << 1];\n//int next2[MAXM << 2];\n//int to2[MAXM << 2];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int cnts;\n//\n//int fa[MAXN << 1];\n//int dep[MAXN << 1];\n//int siz[MAXN << 1];\n//int son[MAXN << 1];\n//int top[MAXN << 1];\n//int nid[MAXN << 1];\n//int cnti;\n//\n//unordered_map<int, map<int, int>> maps;\n//int val[MAXN << 1];\n//int minv[MAXN << 3];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//void addNum(int u, int num) {\n//    if (!maps.count(u)) {\n//        maps.emplace(u, map<int, int>());\n//    }\n//    auto &mp = maps[u];\n//    auto it = mp.find(num);\n//    if (it == mp.end()) {\n//        mp.emplace(num, 1);\n//    } else {\n//        it->second++;\n//    }\n//}\n//\n//void delNum(int u, int num) {\n//    auto &mp = maps[u];\n//    int cnt = mp[num];\n//    if (cnt == 1) {\n//        mp.erase(num);\n