q; i++) {\n//        cin >> op;\n//        if (op == 1) {\n//            cin >> x >> y >> w;\n//            addEdge(x, y, w);\n//        } else if (op == 2) {\n//            cin >> x >> l >> r >> w;\n//            xToRange(x, l, r, w, 1, n, rootIn);\n//        } else {\n//            cin >> x >> l >> r >> w;\n//            rangeToX(l, r, x, w, 1, n, rootOut);\n//        }\n//    }\n//    dijkstra();\n//    for (int i = 1; i <= n; i++) {\n//        cout << (dist[i] == INF ? -1 : dist[i]) << " ";\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_Journeys1.java`\n\n```java\npackage class195;\n\n// 旅程，java版\n// 一共n个点，给定起点p，一共m次操作，格式如下\n// 操作 a b c d : a~b范围每个点与c~d范围每个点之间，都增加一条无向边\n// 所有操作完成后，计算起点p到每个点经过的最少边数，题目保证整体连通\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6348\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.ArrayDeque;\n\npublic class Code02_Journeys1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int INF = 1 << 30;\n\tpublic static int n, m, p;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int rootOut, rootIn;\n\tpublic static int cntt;\n\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static ArrayDeque<Integer> deq = new ArrayDeque<>();\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt, 0);\n\t\t\taddEdge(rs[rt], rt, 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt], 0);\n\t\t\taddEdge(rt, rs[rt], 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i, 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToRange(int a, int b, int c, int d) {\n\t\tint x = ++cntt;\n\t\tint y = ++cntt;\n\t\trangeToX(a, b, x, 1, n, rootOut);\n\t\txToRange(y, c, d, 1, n, rootIn);\n\t\taddEdge(x, y, 1);\n\t}\n\n\tpublic static void bfs01() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t}\n\t\tdist[p] = 0;\n\t\tdeq.addFirst(p);\n\t\twhile (!deq.isEmpty()) {\n\t\t\tint u = deq.pollFirst();\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (dist[v] > dist[u] + w) {\n\t\t\t\t\tdist[v] = dist[u] + w;\n\t\t\t\t\tif (w == 0) {\n\t\t\t\t\t\tdeq.addFirst(v);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdeq.addLast(v);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tp = in.nextInt();\n\t\tcntt = n;\n\t\trootOut = buildOut(1, n);\n\t\trootIn = buildIn(1, n);\n\t\tfor (int i = 1, a, b, c, d; i <= m; i++) {\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\td = in.nextInt();\n\t\t\trangeToRange(a, b, c, d);\n\t\t\trangeToRange(c, d, a, b);\n\t\t}\n\t\tbfs01();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(dist[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_Journeys2.java`\n\n```java\npackage class195;\n\n// 旅程，C++版\n// 一共n个点，给定起点p，一共m次操作，格式如下\n// 操作 a b c d : a~b范围每个点与c~d范围每个点之间，都增加一条无向边\n// 所有操作完成后，计算起点p到每个点经过的最少边数，题目保证整体连通\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6348\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXT = MAXN * 10;\n//const int MAXE = MAXN * 20;\n//const int INF = 1 << 30;\n//int n, m, p;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int weight[MAXE];\n//int cntg;\n//\n//int ls[MAXT];\n//int rs[MAXT];\n//int rootOut, rootIn;\n//int cntt;\n//\n//int dist[MAXT];\n//deque<int> deq;\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//int buildOut(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildOut(l, mid);\n//        rs[rt] = buildOut(mid + 1, r);\n//        addEdge(ls[rt], rt, 0);\n//        addEdge(rs[rt], rt, 0);\n//    }\n//    return rt;\n//}\n//\n//int buildIn(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildIn(l, mid);\n//        rs[rt] = buildIn(mid + 1, r);\n//        addEdge(rt, ls[rt], 0);\n//        addEdge(rt, rs[rt], 0);\n//    }\n//    return rt;\n//}\n//\n//void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(jobx, i, 0);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            xToRange(jobx, jobl, jobr, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            xToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(i, jobx, 0);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            rangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            rangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void rangeToRange(int a, int b, int c, int d) {\n//    int x = ++cntt;\n//    int y = ++cntt;\n//    rangeToX(a, b, x, 1, n, rootOut);\n//    xToRange(y, c, d, 1, n, rootIn);\n//    addEdge(x, y, 1);\n//}\n//\n//void bfs01() {\n//    for (int i = 1; i <= cntt; i++) {\n//        dist[i] = INF;\n//    }\n//    dist[p] = 0;\n//    deq.clear();\n//    deq.push_front(p);\n//    while (!deq.empty()) {\n//        int u = deq.front();\n//        deq.pop_front();\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            int w = weight[e];\n//            if (dist[v] > dist[u] + w) {\n//                dist[v] = dist[u] + w;\n//                if (w == 0) {\n//                    deq.push_front(v);\n//                } else {\n//                    deq.push_back(v);\n//                }\n//            }\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> p;\n//    cntt = n;\n//    rootOut = buildOut(1, n);\n//    rootIn = buildIn(1, n);\n//    for (int i = 1, a, b, c, d; i <= m; i++) {\n//        cin >> a >> b >> c >> d;\n//        rangeToRange(a, b, c, d);\n//        rangeToRange(c, d, a, b);\n//    }\n//    bfs01();\n//    for (int i = 1; i <= n; i++) {\n//        cout << dist[i] << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_Road1.java`\n\n```java\npackage class195;\n\n// 道路，java版\n// 一共n个点，一共m次操作，格式如下\n// 操作 a b c d w: a~b范围每个点与c~d范围每个点之间，都增加权值为w的无向边\n// 给定数字k，表示有k次机会，每次在通过一条边时，不用支付这条边的代价\n// 所有操作完成后，打印1号点到n号点的最低代价\n// 如果不存在通路，打印"CreationAugust is a sb!"\n// 1 <= n <= 5 * 10^4\n// 1 <= m <= 10^5\n// 1 <= k <= 10\n// 1 <= w <= 10^3\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5669\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.PriorityQueue;\n\npublic class Code03_Road1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int MAXK = 11;\n\tpublic static int INF = 1 << 30;\n\tpublic static int t, n, m, k;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int rootOut, rootIn;\n\tpublic static int cntt;\n\n\tpublic static int[][] dist = new int[MAXT][MAXK];\n\tpublic static boolean[][] vis = new boolean[MAXT][MAXK];\n\t// 编号、次数、花费\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[2] - b[2]);\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt, 0);\n\t\t\taddEdge(rs[rt], rt, 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt], 0);\n\t\t\taddEdge(rt, rs[rt], 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i, 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx, 0);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToRange(int a, int b, int c, int d, int w) {\n\t\tint x = ++cntt;\n\t\tint y = ++cntt;\n\t\trangeToX(a, b, x, 1, n, rootOut);\n\t\txToRange(y, c, d, 1, n, rootIn);\n\t\taddEdge(x, y, w);\n\t}\n\n\tpublic static int dijkstra(int start, int target) {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tfor (int j = 0; j <= k; j++) {\n\t\t\t\tdist[i][j] = INF;\n\t\t\t\tvis[i][j] = false;\n\t\t\t}\n\t\t}\n\t\tdist[start][0] = 0;\n\t\theap.add(new int[] { start, 0, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint node = cur[0];\n\t\t\tint time = cur[1];\n\t\t\tint cost = cur[2];\n\t\t\tif (!vis[node][time]) {\n\t\t\t\tvis[node][time] = true;\n\t\t\t\tif (node == target) {\n\t\t\t\t\treturn cost;\n\t\t\t\t}\n\t\t\t\tfor (int e = head[node]; e > 0; e = nxt[e]) {\n\t\t\t\t\tint v = to[e];\n\t\t\t\t\tint w = weight[e];\n\t\t\t\t\tif (!vis[v][time] && dist[v][time] > cost + w) {\n\t\t\t\t\t\tdist[v][time] = cost + w;\n\t\t\t\t\t\theap.add(new int[] { v, time, dist[v][time] });\n\t\t\t\t\t}\n\t\t\t\t\tif (time < k && !vis[v][time + 1] && dist[v][time + 1] > cost) {\n\t\t\t\t\t\tdist[v][time + 1] = cost;\n\t\t\t\t\t\theap.add(new int[] { v, time + 1, dist[v][time + 1] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tcntg = cntt = 0;\n\t\theap.clear();\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int test = 1; test <= t; test++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tk = in.nextInt();\n\t\t\tcntt = n;\n\t\t\trootOut = buildOut(1, n);\n\t\t\trootIn = buildIn(1, n);\n\t\t\tfor (int i = 1, a, b, c, d, w; i <= m; i++) {\n\t\t\t\ta = in.nextInt();\n\t\t\t\tb = in.nextInt();\n\t\t\t\tc = in.nextInt();\n\t\t\t\td = in.nextInt();\n\t\t\t\tw = in.nextInt();\n\t\t\t\trangeToRange(a, b, c, d, w);\n\t\t\t\trangeToRange(c, d, a, b, w);\n\t\t\t}\n\t\t\tint ans = dijkstra(1, n);\n\t\t\tif (ans == -1) {\n\t\t\t\tout.println("CreationAugust is a sb!");\n\t\t\t} else {\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t\tclear();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_Road2.java`\n\n```java\npackage class195;\n\n// 道路，C++版\n// 一共n个点，一共m次操作，格式如下\n// 操作 a b c d w: a~b范围每个点与c~d范围每个点之间，都增加权值为w的无向边\n// 给定数字k，表示有k次机会，每次在通过一条边时，不用支付这条边的代价\n// 所有操作完成后，打印1号点到n号点的最低代价\n// 如果不存在通路，打印"CreationAugust is a sb!"\n// 1 <= n <= 5 * 10^4\n// 1 <= m <= 10^5\n// 1 <= k <= 10\n// 1 <= w <= 10^3\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=5669\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\