::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int test = 1; test <= t; test++) {\n//        cin >> n >> m >> k;\n//        cntt = n;\n//        rootOut = buildOut(1, n);\n//        rootIn = buildIn(1, n);\n//        for (int i = 1, a, b, c, d, w; i <= m; i++) {\n//            cin >> a >> b >> c >> d >> w;\n//            rangeToRange(a, b, c, d, w);\n//            rangeToRange(c, d, a, b, w);\n//        }\n//        int ans = dijkstra(1, n);\n//        if (ans == -1) {\n//            cout << "CreationAugust is a sb!" << "\\n";\n//        } else {\n//            cout << ans << "\\n";\n//        }\n//        clear();\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Desert1.java`\n\n```java\npackage class195;\n\n// 沙漠，java版\n// 一共n个数字，所有数字都在 1 ~ 10^9 的范围，这是范围说明\n// 接下来给定s条设置说明，格式 x v ，表示第x个数的值确定是v\n// 接下来给定m条关系说明，格式 l r k x1 x2 ... xk 含义如下\n// 第l到第r个数字，其中有k个数字，分别是第x1、第x2 .. 第xk个数字\n// 这k个数字中的每一个，都比剩下的(r - l + 1 - k)个数字要大，严格大于\n// 根据上面的说明，找到没有矛盾的，给每个数字赋值的方案，任何一个方案即可\n// 如果存在方案打印"TAK"，然后打印每个数字，不存在方案打印"NIE"\n// 1 <= n、s <= 10^5\n// 1 <= m <= 2 * 10^5\n// 所有k的累加和 <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3588\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Desert1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 5;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int LIMIT = 1000000000;\n\tpublic static int n, s, m;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int root;\n\tpublic static int cntt;\n\n\tpublic static int[] val = new int[MAXT];\n\tpublic static int[] atMost = new int[MAXT];\n\tpublic static int[] indegree = new int[MAXT];\n\tpublic static int[] que = new int[MAXT];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t\tindegree[v]++;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt], 0);\n\t\t\taddEdge(rt, rs[rt], 0);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int jobw, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i, jobw);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, jobw, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean topo() {\n\t\tint qi = 1, qsiz = 0;\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++qsiz] = i;\n\t\t\t}\n\t\t\tatMost[i] = val[i] == 0 ? LIMIT : val[i];\n\t\t}\n\t\twhile (qi <= qsiz) {\n\t\t\tint u = que[qi++];\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tif (atMost[v] > atMost[u] + w) {\n\t\t\t\t\tatMost[v] = atMost[u] + w;\n\t\t\t\t\tif ((val[v] != 0 && atMost[v] < val[v]) || atMost[v] < 1) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++qsiz] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn qsiz == cntt;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\ts = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntt = n;\n\t\troot = build(1, n);\n\t\tfor (int i = 1; i <= s; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tval[x] = v;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint l = in.nextInt();\n\t\t\tint r = in.nextInt();\n\t\t\tint k = in.nextInt();\n\t\t\tint vnode = ++cntt;\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tint x = in.nextInt();\n\t\t\t\taddEdge(x, vnode, 0);\n\t\t\t\txToRange(vnode, l, x - 1, -1, 1, n, root);\n\t\t\t\tl = x + 1;\n\t\t\t}\n\t\t\txToRange(vnode, l, r, -1, 1, n, root);\n\t\t}\n\t\tboolean check = topo();\n\t\tif (check) {\n\t\t\tout.println("TAK");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(atMost[i] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t} else {\n\t\t\tout.println("NIE");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Desert2.java`\n\n```java\npackage class195;\n\n// 沙漠，C++版\n// 一共n个数字，所有数字都在 1 ~ 10^9 的范围，这是范围说明\n// 接下来给定s条设置说明，格式 x v ，表示第x个数的值确定是v\n// 接下来给定m条关系说明，格式 l r k x1 x2 ... xk 含义如下\n// 第l到第r个数字，其中有k个数字，分别是第x1、第x2 .. 第xk个数字\n// 这k个数字中的每一个，都比剩下的(r - l + 1 - k)个数字要大，严格大于\n// 根据上面的说明，找到没有矛盾的，给每个数字赋值的方案，任何一个方案即可\n// 如果存在方案打印"TAK"，然后打印每个数字，不存在方案打印"NIE"\n// 1 <= n、s <= 10^5\n// 1 <= m <= 2 * 10^5\n// 所有k的累加和 <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3588\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXT = MAXN * 5;\n//const int MAXE = MAXN * 20;\n//const int LIMIT = 1000000000;\n//int n, s, m;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int weight[MAXE];\n//int cntg;\n//\n//int ls[MAXT];\n//int rs[MAXT];\n//int root;\n//int cntt;\n//\n//int val[MAXT];\n//int atMost[MAXT];\n//int indegree[MAXT];\n//int que[MAXT];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//    indegree[v]++;\n//}\n//\n//int build(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//        addEdge(rt, ls[rt], 0);\n//        addEdge(rt, rs[rt], 0);\n//    }\n//    return rt;\n//}\n//\n//void xToRange(int jobx, int jobl, int jobr, int jobw, int l, int r, int i) {\n//    if (jobl > jobr) {\n//        return;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(jobx, i, jobw);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            xToRange(jobx, jobl, jobr, jobw, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            xToRange(jobx, jobl, jobr, jobw, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//bool topo() {\n//    int qi = 1, qsiz = 0;\n//    for (int i = 1; i <= cntt; i++) {\n//        if (indegree[i] == 0) {\n//            que[++qsiz] = i;\n//        }\n//        atMost[i] = val[i] == 0 ? LIMIT : val[i];\n//    }\n//    while (qi <= qsiz) {\n//        int u = que[qi++];\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            int w = weight[e];\n//            if (atMost[v] > atMost[u] + w) {\n//                atMost[v] = atMost[u] + w;\n//                if ((val[v] != 0 && atMost[v] < val[v]) || atMost[v] < 1) {\n//                    return false;\n//                }\n//            }\n//            if (--indegree[v] == 0) {\n//                que[++qsiz] = v;\n//            }\n//        }\n//    }\n//    return qsiz == cntt;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> s >> m;\n//    cntt = n;\n//    root = build(1, n);\n//    for (int i = 1; i <= s; i++) {\n//        int x, v;\n//        cin >> x >> v;\n//        val[x] = v;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        int l, r, k;\n//        cin >> l >> r >> k;\n//        int vnode = ++cntt;\n//        for (int j = 1; j <= k; j++) {\n//            int x;\n//            cin >> x;\n//            addEdge(x, vnode, 0);\n//            xToRange(vnode, l, x - 1, -1, 1, n, root);\n//            l = x + 1;\n//        }\n//        xToRange(vnode, l, r, -1, 1, n, root);\n//    }\n//    bool check = topo();\n//    if (check) {\n//        cout << "TAK" << "\\n";\n//        for (int i = 1; i <= n; i++) {\n//            cout << atMost[i] << " ";\n//        }\n//        cout << "\\n";\n//    } else {\n//        cout << "NIE" << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Bomb1.java`\n\n```java\npackage class195;\n\n// 炸弹，java版\n// 一共有n个炸弹，所有炸弹排成一条直线，给定每个炸弹的坐标xi、爆炸半径ri\n// 炸弹A引爆时，如果炸弹B在其影响范围里，那么炸弹B也会引爆，进而引发一连串的爆炸\n// 炸弹i如果作为初始引爆的炸弹，最终会引爆多少个炸弹记为query(i)\n// 计算i = 1 2 .. n时，i * query(i)的累加和，答案对 1000000007 取余\n// 1 <= n <= 5 * 10^5\n// -(10^18) <= xi <= +(10^18)，题目依次输入的坐标保证严格递增\n// 0 <= ri <= 2 * 10^18\n// 测试链接 : https://www.luogu.com.cn/problem/P5025\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Bomb1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXT = MAXN * 5;\n\tpublic static int MAXE = MAXN * 20;\n\tpublic static int INF = 1 << 30;\n\tpublic static int MOD = 1000000007;\n\tpublic static int n;\n\tpublic static long[] location = new long[MAXN];\n\tpublic static long[] radius = new long[MAXN];\n\n\tpublic static int[] a = new int[MAXE];\n\tpublic static int[] b = new int[MAXE];\n\tpublic static int cnte;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] rangel = new int[MAXT];\n\tpublic static int[] ranger = new int[MAXT];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int root;\n\tpublic static int cntt;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int[] mostl = new int[MAXT];\n\tpublic static int[] mostr = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXT][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void saveEdge(int u, int v) {\n\t\ta[++cnte] = u;\n\t\tb[cnte] = v;\n\t}\n\n\tpublic static int lower(long num) {\n\t\tint l = 1, r = n, mid, ans = n + 1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (location[mid] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = build(l, mid);\n\t\t\trs[rt] = build(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt);\n\t\t\taddEdge(rs[rt], rt);\n\t\t\tsaveEdge(ls[rt], rt);\n\t\t\tsaveEdge(rs[rt], rt);\n\t\t}\n\t\trangel[rt] = l;\n\t\tranger[rt] = r;\n\t\treturn rt;\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx);\n\t\t\tsaveEdge(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tmostl[sccCnt] = INF;\n\t\t\tmostr[sccCnt] = -INF;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tmostl[sccCnt] = Math.min(mostl[sccCnt], rangel[pop]);\n\t\t\t\tmostr[sccCnt] = Math.max(mostr[sccCnt], ranger[pop]);\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tmostl[sccCnt] = INF;\n\t\t\t\t\tmostr[sccCnt] = -INF;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tmostl[sccCnt] = Math.min(mostl[sccCnt], rangel[pop]);\n\t\t\t\t\t\tmostr[sccCnt] = Math.max(mostr[sccCnt], ranger[pop]);\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= cnte; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dpOnDAG() {\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tmostl[v] = Math.min(mostl[v], mostl[u]);\n\t\t\t\tmostr[v] = Math.max(mostr[v], mostr[u]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int u) {\n\t\tint scc = belong[u];\n\t\tint num = mostr[scc] - mostl[scc] + 1;\n\t\treturn num;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tcntt = n;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlocation[i] = in.nextLong();\n\t\t\tradius[i] = in.nextLong();\n\t\t}\n\t\troot = build(1, n);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tint l = lower(location[i] - radius[i]);\n\t\t\tint r = lower(location[i] + radius[i] + 1) - 1;\n\t\t\trangeToX(l, r, i, 1, n, root);\n\t\t}\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tcondense();\n\t\tdpOnDAG();\n\t\tlong ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tans = (ans + 1L * query(i) * i) % MOD;\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tlong nextLong() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code05_Bomb2.java`\n\n```java\npackage class195;\n\n// 炸弹，C++版\n// 一共有n个炸弹，所有炸弹排成一条直线，给定每个炸弹的坐标xi、爆炸半径ri\n// 炸弹A引爆时，如果炸弹B在其影响范围里，那么炸弹B也会引爆，进而引发一连串的爆炸\n// 炸弹i如果作为初始引爆的炸弹，最终会引爆多少个炸弹记为query(i)\n// 计算i = 1 2 .. n时，i * query(i)的累加和，答案对 1000000007 取余\n// 1 <= n <= 5 * 10^5\n// -(10^18) <= xi <= +(10^18)，题目依次输入的坐标保证严格递增\n// 0 <= ri <= 2 * 10^18\n// 测试链接 : https://www.luogu.com.cn/problem/P5025\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 500001;\n//const int MAXT = MAXN * 5;\n//const int MAXE = MAXN * 20;\n//const int INF = 1 << 30;\n//const int MOD = 1000000007;\n//int n;\n//ll location[MAXN];\n//ll radius[MAXN];\n//\n//int a[MAXE];\n//int b[MAXE];\n//int cnte;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int rangel[MAXT];\n//int ranger[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int root;\n//int cntt;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int mostl[MAXT];\n//int mostr[MAXT];\n//int sccCnt;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void saveEdge(int u, int v) {\n//    a[++cnte] = u;\n//    b[cnte] = v;\n//}\n//\n//int lower(ll num) {\n//    int l = 1, r = n, mid, ans = n + 1;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (location[mid] >= num) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int build(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//        addEdge(ls[rt], rt);\n//        addEdge(rs[rt], rt);\n//        saveEdge(ls[rt], rt);\n//        saveEdge(rs[rt], rt);\n//    }\n//    rangel[rt] = l;\n//    ranger[rt] = r;\n//    return rt;\n//}\n//\n//void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(i, jobx);\n//        saveEdge(i, jobx);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            rangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            rangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        mostl[sccCnt] = INF;\n//        mostr[sccCnt] = -INF;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//            mostl[sccCnt] = min(mostl[sccCnt], rangel[pop]);\n//            mostr[sccCnt] = max(mostr[sccCnt], ranger[pop]);\n//        } while (pop != u);\n//    }\n//}\n//\n//void condense() {\n//    cntg = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        head[i] = 0;\n//    }\n//    for (int i = 1; i <= cnte; i++) {\n//        int scc1 = belong[a[i]];\n//        int scc2 = belong[b[i]];\n//        if (scc1 != scc2) {\n//            addEdge(scc1, scc2);\n//        }\n//    }\n//}\n//\n//void dpOnDAG() {\n//    for (int u = sccCnt; u > 0; u--) {\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            mostl[v] = min(mostl[v], mostl[u]);\n//            mostr[v] = max(mostr[v], mostr[u]);\n//        }\n//    }\n//}\n//\n//int query(int u) {\n//    int scc = belong[u];\n//    int num = mostr[scc] - mostl[scc] + 1;\n//    return num;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    cntt = n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> location[i] >> radius[i];\n//    }\n//    root = build(1, n);\n//    for (int i = 1; i <= n; i++) {\n//        int l = lower(location[i] - radius[i]);\n//        int r = lower(location[i] + radius[i] + 1) - 1;\n//        rangeToX(l, r, i, 1, n, root);\n//    }\n//    for (int i = 1; i <= cntt; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    condense();\n//    dpOnDAG();\n//    ll ans = 0;\n//    for (int i = 1; i <= n; i++) {\n//        ans = (ans + 1LL * query(i) * i) % MOD;\n//    }\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code06_BeautifulTreeHLD1.java`\n\n```java\npackage class195;\n\n// 美丽的树，树剖优化建图，java版\n// 一共n个节点，给定n-1条无向边，所有节点组成一棵树，1号节点是根\n// 你需要给每个节点赋值，但是不能破坏如下的m条关系，关系的格式如下\n// 关系 1 a b c : 节点a到节点b的路径上，值最小的节点必须是节点c，输入保证c一定在路径上\n// 关系 2 a b c : 节点a到节点b的路径上，值最大的节点必须是节点c，输入保证c一定在路径上\n// 如果存在赋值方案，并且这些值是1到n的一个排列，打印一种方案即可，否则打印-1\n// 2 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1904F\n// 测试链接 : https://codeforces.com/problemset/problem/1904/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_BeautifulTreeHLD1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int MAXE = MAXN * 50;\n\tpublic static int n, m;\n\n\t// 原始的树\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\t// 关系图，x -> y，x的值严格小于y\n\tpublic static int[] indegree = new int[MAXT];\n\tpublic static int[] head2 = new int[MAXT];\n\tpublic static int[] next2 = new int[MAXE];\n\tpublic static int[] to2 = new int[MAXE];\n\tpublic static int cnt2;\n\n\t// 线段树优化建图，出树和入树\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int rootOut, rootIn;\n\tpublic static int cntt;\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd;\n\n\t// 拓扑排序\n\tpublic static int[] que = new int[MAXT];\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tindegree[v]++;\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge2(ls[rt], rt);\n\t\t\taddEdge2(rs[rt], rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt;\n\t\tif (l == r) {\n\t\t\trt = l;\n\t\t} else {\n\t\t\trt = ++cntt;\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge2(rt, ls[rt]);\n\t\t\taddEdge2(rt, rs[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge2(jobx, i);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge2(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head1[u], v; e > 0; e = next1[e]) {\n\t\t\tv = to1[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head1[u], v; e > 0; e = next1[e]) {\n\t\t\tv = to1[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void pathSet(int op, int x, int y, int z) {\n\t\tif (op == 1) {\n\t\t\tif (x <= z && z <= y) {\n\t\t\t\txToRange(z, x, z - 1, 1, n, rootIn);\n\t\t\t\txToRange(z, z + 1, y, 1, n, rootIn);\n\t\t\t} else {\n\t\t\t\txToRange(z, x, y, 1, n, rootIn);\n\t\t\t}\n\t\t} else {\n\t\t\tif (x <= z && z <= y) {\n\t\t\t\trangeToX(x, z - 1, z, 1, n, rootOut);\n\t\t\t\trangeToX(z + 1, y, z, 1, n, rootOut);\n\t\t\t} else {\n\t\t\t\trangeToX(x, y, z, 1, n, rootOut);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void link(int op, int a, int b, int c) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] < dep[top[b]]) {\n\t\t\t\tint tmp = a;\n\t\t\t\ta = b;\n\t\t\t\tb = tmp;\n\t\t\t}\n\t\t\tpathSet(op, dfn[top[a]], dfn[a], dfn[c]);\n\t\t\ta = fa[top[a]];\n\t\t}\n\t\tpathSet(op, Math.min(dfn[a], dfn[b]), Math.max(dfn[a], dfn[b]), dfn[c]);\n\t}\n\n\tpublic static boolean topo() {\n\t\tint qi = 1, qsiz = 0;\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++qsiz] = i;\n\t\t\t}\n\t\t}\n\t\tint val = 0;\n\t\twhile (qi <= qsiz) {\n\t\t\tint u = que[qi++];\n\t\t\tif (u <= n) {\n\t\t\t\tans[seg[u]] = ++val;\n\t\t\t}\n\t\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\t\tint v = to2[e];\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++qsiz] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn qsiz == cntt;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntt = n;\n\t\trootOut = buildOut(1, n);\n\t\trootIn = buildIn(1, n);\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tfor (int i = 1, op, a, b, c; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\tlink(op, a, b, c);\n\t\t}\n\t\tboolean check = topo();\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t\tout.print(" ");\n\t\t\t}\n\t\t} else {\n\t\t\tout.println(-1);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_BeautifulTreeHLD2.java`\n\n```java\npackage class195;\n\n// 美丽的树，树剖优化建图，C++版\n// 一共n个节点，给定n-1条无向边，所有节点组成一棵树，1号节点是根\n// 你需要给每个节点赋值，但是不能破坏如下的m条关系，关系的格式如下\n// 关系 1 a b c : 节点a到节点b的路径上，值最小的节点必须是节点c，输入保证c一定在路径上\n// 关系 2 a b c : 节点a到节点b的路径上，值最大的节点必须是节点c，输入保证c一定在路径上\n// 如果存在赋值方案，并且这些值是1到n的一个排列，打印一种方案即可，否则打印-1\n// 2 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1904F\n// 测试链接 : https://codeforces.com/problemset/problem/1904/F\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = MAXN * 10;\n//const int MAXE = MAXN * 50;\n//int n, m;\n//\n//int head1[MAXN];\n//int next1[MAXN << 1];\n//int to1[MAXN << 1];\n//int cnt1;\n//\n//int indegree[MAXT];\n//int head2[MAXT];\n//int next2[MAXE];\n//int to2[MAXE];\n//int cnt2;\n//\n//int ls[MAXT];\n//int rs[MAXT];\n//int rootOut, rootIn;\n//int cntt;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dfn[MAXN];\n//int seg[MAXN];\n//int cntd;\n//\n//int que[MAXT];\n//int ans[MAXN];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//    indegree[v]++;\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    head2[u] = cnt2;\n//}\n//\n//int buildOut(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildOut(l, mid);\n//        rs[rt] = buildOut(mid + 1, r);\n//        addEdge2(ls[rt], rt);\n//        addEdge2(rs[rt], rt);\n//    }\n//    return rt;\n//}\n//\n//int buildIn(int l, int r) {\n//    int rt;\n//    if (l == r) {\n//        rt = l;\n//    } else {\n//        rt = ++cntt;\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildIn(l, mid);\n//        rs[rt] = buildIn(mid + 1, r);\n//        addEdge2(rt, ls[rt]);\n//        addEdge2(rt, rs[rt]);\n//    }\n//    return rt;\n//}\n//\n//void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n//    if (jobl > jobr) {\n//        return;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        addEdge2(jobx, i);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            xToRange(jobx, jobl, jobr, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            xToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n//    if (jobl > jobr) {\n//        return;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        addEdge2(i, jobx);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            rangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            rangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head1[u], v; e > 0; e = next1[e]) {\n//        v = to1[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    dfn[u] = ++cntd;\n//    seg[cntd] = u;\n//    if (son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head1[u], v; e > 0; e = next1[e]) {\n//        v = to1[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//void pathSet(int op, int x, int y, int z) {\n//    if (op == 1) {\n//        if (x <= z && z <= y) {\n//            xToRange(z, x, z - 1, 1, n, rootIn);\n//            xToRange(z, z + 1, y, 1, n, rootIn);\n//        } else {\n//            xToRange(z, x, y, 1, n, rootIn);\n//        }\n//    } else {\n//        if (x <= z && z <= y) {\n//            rangeToX(x, z - 1, z, 1, n, rootOut);\n//            rangeToX(z + 1, y, z, 1, n, rootOut);\n//        } else {\n//            rangeToX(x, y, z, 1, n, rootOut);\n//        }\n//    }\n//}\n//\n//void link(int op, int a, int b, int c) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] < dep[top[b]]) {\n//            swap(a, b);\n//        }\n//        pathSet(op, dfn[top[a]], dfn[a], dfn[c]);\n//        a = fa[top[a]];\n//    }\n//    pathSet(op, min(dfn[a], dfn[b]), max(dfn[a], dfn[b]), dfn[c]);\n//}\n//\n//bool topo() {\n//    int qi = 1, qsiz = 0;\n//    for (int i = 1; i <= cntt; i++) {\n//        if (indegree[i] == 0) {\n//            que[++qsiz] = i;\n//        }\n//    }\n//    int val = 0;\n//    while (qi <= qsiz) {\n//        int u = que[qi++];\n//        if (u <= n) {\n//            ans[seg[u]] = ++val;\n//        }\n//        for (int e = head2[u]; e > 0; e = next2[e]) {\n//            int v = to2[e];\n//            if (--indegree[v] == 0) {\n//                que[++qsiz] = v;\n//            }\n//        }\n//    }\n//    return qsiz == cntt;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntt = n;\n//    rootOut = buildOut(1, n);\n//    rootIn = buildIn(1, n);\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge1(u, v);\n//        addEdge1(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    for (int i = 1, op, a, b, c; i <= m; i++) {\n//        cin >> op >> a >> b >> c;\n//        link(op, a, b, c);\n//    }\n//    bool check = topo();\n//    if (check) {\n//        for (int i = 1; i <= n; i++) {\n//            cout << ans[i] << " ";\n//        }\n//    } else {\n//        cout << -1 << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_BeautifulTreeST1.java`\n\n```java\npackage class195;\n\n// 美丽的树，倍增优化建图，java版\n// 一共n个节点，给定n-1条无向边，所有节点组成一棵树，1号节点是根\n// 你需要给每个节点赋值，但是不能破坏如下的m条关系，关系的格式如下\n// 关系 1 a b c : 节点a到节点b的路径上，值最小的节点必须是节点c，输入保证c一定在路径上\n// 关系 2 a b c : 节点a到节点b的路径上，值最大的节点必须是节点c，输入保证c一定在路径上\n// 如果存在赋值方案，并且这些值是1到n的一个排列，打印一种方案即可，否则打印-1\n// 2 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1904F\n// 测试链接 : https://codeforces.com/problemset/problem/1904/F\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_BeautifulTreeST1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = MAXN * 41;\n\tpublic static int MAXE = MAXN * 201;\n\tpublic static int MAXP = 17;\n\tpublic static int MAXK = MAXN * MAXP;\n\tpublic static int n, m;\n\n\t// 原树\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\t// 关系图\n\tpublic static int[] indegree = new int[MAXT];\n\tpublic static int[] head2 = new int[MAXT];\n\tpublic static int[] next2 = new int[MAXE];\n\tpublic static int[] to2 = new int[MAXE];\n\tpublic static int cnt2;\n\n\t// 树上倍增\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] stjump = new int[MAXK];\n\tpublic static int cntd;\n\n\t// 倍增优化建图，出表和入表\n\tpublic static int[] stout = new int[MAXK];\n\tpublic static int[] stin = new int[MAXK];\n\tpublic static int cntt;\n\n\t// 拓扑排序\n\tpublic static int[] que = new int[MAXT];\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int idx(int u, int p) {\n\t\treturn u * MAXP + p;\n\t}\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tindegree[v]++;\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void build(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdfn[u] = ++cntd;\n\t\tsiz[u] = 1;\n\t\tstjump[idx(u, 0)] = fa;\n\t\tstout[idx(u, 0)] = ++cntt;\n\t\taddEdge2(u, cntt);\n\t\taddEdge2(fa, cntt);\n\t\tstin[idx(u, 0)] = ++cntt;\n\t\taddEdge2(cntt, u);\n\t\taddEdge2(cntt, fa);\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[idx(u, p)] = stjump[idx(stjump[idx(u, p - 1)], p - 1)];\n\t\t\tstout[idx(u, p)] = ++cntt;\n\t\t\taddEdge2(stout[idx(u, p - 1)], cntt);\n\t\t\taddEdge2(stout[idx(stjump[idx(u, p - 1)], p - 1)], cntt);\n\t\t\tstin[idx(u, p)] = ++cntt;\n\t\t\taddEdge2(cntt, stin[idx(u, p - 1)]);\n\t\t\taddEdge2(cntt, stin[idx(stjump[idx(u, p - 1)], p - 1)]);\n\t\t}\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tint v = to1[e];\n\t\t\tif (v != fa) {\n\t\t\t\tbuild(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean isAncestor(int a, int b) {\n\t\treturn dfn[a] <= dfn[b] && dfn[b] < dfn[a] + siz[a];\n\t}\n\n\tpublic static int kthAncestor(int x, int k) {\n\t\tfor (int p = 0; p < MAXP; p++) {\n\t\t\tif (((k >> p) & 1) != 0) {\n\t\t\t\tx = stjump[idx(x, p)];\n\t\t\t}\n\t\t}\n\t\treturn x;\n\t}\n\n\tpublic static int nearest(int x, int y) {\n\t\tif (isAncestor(y, x)) {\n\t\t\treturn kthAncestor(x, dep[x] - dep[y] - 1);\n\t\t} else {\n\t\t\treturn stjump[idx(y, 0)];\n\t\t}\n\t}\n\n\tpublic static void pathOut(int x, int y, int c) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\taddEdge2(y, c);\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[idx(x, p)]] >= dep[y]) {\n\t\t\t\taddEdge2(stout[idx(x, p)], c);\n\t\t\t\tx = stjump[idx(x, p)];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[idx(x, p)] != stjump[idx(y, p)]) {\n\t\t\t\taddEdge2(stout[idx(x, p)], c);\n\t\t\t\taddEdge2(stout[idx(y, p)], c);\n\t\t\t\tx = stjump[idx(x, p)];\n\t\t\t\ty = stjump[idx(y, p)];\n\t\t\t}\n\t\t}\n\t\taddEdge2(stout[idx(x, 0)], c);\n\t}\n\n\tpublic static void pathIn(int x, int y, int c) {\n\t\tif (dep[x] < dep[y]) {\n\t\t\tint tmp = x;\n\t\t\tx = y;\n\t\t\ty = tmp;\n\t\t}\n\t\taddEdge2(c, y);\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[idx(x, p)]] >= dep[y]) {\n\t\t\t\taddEdge2(c, stin[idx(x, p)]);\n\t\t\t\tx = stjump[idx(x, p)];\n\t\t\t}\n\t\t}\n\t\tif (x == y) {\n\t\t\treturn;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[idx(x, p)] != stjump[idx(y, p)]) {\n\t\t\t\taddEdge2(c, stin[idx(x, p)]);\n\t\t\t\taddEdge2(c, stin[idx(y, p)]);\n\t\t\t\tx = stjump[idx(x, p)];\n\t\t\t\ty = stjump[idx(y, p)];\n\t\t\t}\n\t\t}\n\t\taddEdge2(c, stin[idx(x, 0)]);\n\t}\n\n\tpublic static void pathMin(int a, int b, int c) {\n\t\tif (a != c) {\n\t\t\tpathIn(a, nearest(a, c), c);\n\t\t}\n\t\tif (b != c) {\n\t\t\tpathIn(b, nearest(b, c), c);\n\t\t}\n\t}\n\n\tpublic static void pathMax(int a, int b, int c) {\n\t\tif (a != c) {\n\t\t\tpathOut(a, nearest(a, c), c);\n\t\t}\n\t\tif (b != c) {\n\t\t\tpathOut(b, nearest(b, c), c);\n\t\t}\n\t}\n\n\tpublic static boolean topo() {\n\t\tint qi = 1, qsiz = 0;\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++qsiz] = i;\n\t\t\t}\n\t\t}\n\t\tint val = 0;\n\t\twhile (qi <= qsiz) {\n\t\t\tint u = que[qi++];\n\t\t\tif (u <= n) {\n\t\t\t\tans[u] = ++val;\n\t\t\t}\n\t\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\t\tint v = to2[e];\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++qsiz] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn qsiz == cntt;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntt = n;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\tbuild(1, 1);\n\t\tfor (int i = 1, op, a, b, c; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tpathMin(a, b, c);\n\t\t\t} else {\n\t\t\t\tpathMax(a, b, c);\n\t\t\t}\n\t\t}\n\t\tboolean check = topo();\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t\tout.print(" ");\n\t\t\t}\n\t\t} else {\n\t\t\tout.println(-1);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code07_BeautifulTreeST2.java`\n\n```java\npackage class195;\n\n// 美丽的树，倍增优化建图，C++版\n// 一共n个节点，给定n-1条无向边，所有节点组成一棵树，1号节点是根\n// 你需要给每个节点赋值，但是不能破坏如下的m条关系，关系的格式如下\n// 关系 1 a b c : 节点a到节点b的路径上，值最小的节点必须是节点c，输入保证c一定在路径上\n// 关系 2 a b c : 节点a到节点b的路径上，值最大的节点必须是节点c，输入保证c一定在路径上\n// 如果存在赋值方案，并且这些值是1到n的一个排列，打印一种方案即可，否则打印-1\n// 2 <= n、m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1904F\n// 测试链接 : https://codeforces.com/problemset/problem/1904/F\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = MAXN * 41;\n//const int MAXE = MAXN * 201;\n//const int MAXP = 17;\n//int n, m;\n//\n