 (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tnode1 = u;\n\t\t\t\tnode2 = v;\n\t\t\t\tskipEdge = (e + 1) >> 1;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif ((e + 1) >> 1 != skipEdge && v != f) {\n\t\t\t\tdfs2(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] != 0) {\n\t\t\tdfs3(son[u], t);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif ((e + 1) >> 1 != skipEdge && v != fa[u] && v != son[u]) {\n\t\t\t\tdfs3(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= n) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int query(int i) {\n\t\tint ans = 0;\n\t\twhile (i >= 1) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int sum(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn query(r) - query(l - 1);\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs1(1);\n\t\tcntd = 0;\n\t\tdfs2(1, 0);\n\t\tdfs3(1, 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (i != skipEdge) {\n\t\t\t\tadd(Math.max(dfn[u[i]], dfn[v[i]]), w[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void setEdge(int edge, int val) {\n\t\tif (edge != skipEdge) {\n\t\t\tadd(Math.max(dfn[u[edge]], dfn[v[edge]]), val - w[edge]);\n\t\t}\n\t\tw[edge] = val;\n\t}\n\n\tpublic static int jump(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tans += sum(dfn[top[y]], dfn[y]);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += sum(dfn[top[x]], dfn[x]);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tif (dfn[x] < dfn[y]) {\n\t\t\tans += sum(dfn[x] + 1, dfn[y]);\n\t\t} else {\n\t\t\tans += sum(dfn[y] + 1, dfn[x]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getDistance(int x, int y) {\n\t\tint p1 = jump(x, y);\n\t\tint p2 = jump(x, node1) + w[skipEdge] + jump(node2, y);\n\t\tint p3 = jump(x, node2) + w[skipEdge] + jump(node1, y);\n\t\treturn Math.min(p1, Math.min(p2, p3));\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\tw[i] = in.nextInt();\n\t\t\taddEdge(u[i], v[i]);\n\t\t\taddEdge(v[i], u[i]);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tsetEdge(x, y);\n\t\t\t} else {\n\t\t\t\tout.println(getDistance(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code07_ShortestDistance_java_2.java`\n\n```java\npackage class199;\n\n// 最短距离，好想的解法，java版\n// 图中有n个点、n条无向边，每条边有边权，图是一棵基环树\n// 一共有m条操作，每条操作是如下两种类型中的一种\n// 操作 1 x y : 第x号边的边权修改为y\n// 操作 2 x y : 查询点x和点y之间的最短距离\n// 1 <= n <= 10^5 + 6\n// 1 <= m <= 10^5\n// 0 <= 边权 <= 5000\n// 测试链接 : https://www.luogu.com.cn/problem/P4949\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_ShortestDistance_java_2 {\n\n\tpublic static int MAXN = 100007;\n\tpublic static int n, m;\n\tpublic static int[] u = new int[MAXN];\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] w = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\t// 基环树找环\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] from = new int[MAXN];\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int cnta;\n\n\t// 环上的边，确定归属，不是环上的边，这个信息没用\n\tpublic static int[] cycleEdgeTo = new int[MAXN];\n\t// 环上的点依次分配编号，继续cntd自增获得编号\n\tpublic static int[] cycleId = new int[MAXN];\n\t// 记录每个节点属于哪棵分树，分树的头一定是环上节点\n\tpublic static int[] belong = new int[MAXN];\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\t// 所有分树节点的dfn序号范围[1, n]\n\t// 环上节点会额外再次编号，范围[n+1, cntd]\n\tpublic static int[] tree = new int[MAXN << 1];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs1(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tfrom[v] = u;\n\t\t\t\tcycleEdgeTo[(e + 1) >> 1] = v;\n\t\t\t\tdfs1(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tcycleEdgeTo[(e + 1) >> 1] = u;\n\t\t\t\tcycle[u] = true;\n\t\t\t\tarr[++cnta] = u;\n\t\t\t\tfor (int i = v; i != u; i = from[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t\tarr[++cnta] = i;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int f, int h) {\n\t\tbelong[u] = h;\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = nxt[e]) {\n\t\t\tv = to[e];\n\t\t\tif (!cycle[v] && v != f) {\n\t\t\t\tdfs2(v, u, h);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs3(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] != 0) {\n\t\t\tdfs3(son[u], t);\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!cycle[v] && v != fa[u] && v != son[u]) {\n\t\t\t\tdfs3(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\twhile (i <= cntd) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int query(int i) {\n\t\tint ans = 0;\n\t\twhile (i >= 1) {\n\t\t\tans += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int sum(int l, int r) {\n\t\tif (l > r) {\n\t\t\treturn 0;\n\t\t}\n\t\treturn query(r) - query(l - 1);\n\t}\n\n\tpublic static int edgeToNode(int i) {\n\t\tif (cycle[u[i]] && cycle[v[i]]) {\n\t\t\treturn cycleId[cycleEdgeTo[i]];\n\t\t} else {\n\t\t\treturn Math.max(dfn[u[i]], dfn[v[i]]);\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tdfs1(1);\n\t\tcntd = 0;\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tdfs2(arr[i], 0, arr[i]);\n\t\t\tdfs3(arr[i], arr[i]);\n\t\t}\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tcycleId[arr[i]] = ++cntd;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(edgeToNode(i), w[i]);\n\t\t}\n\t}\n\n\tpublic static void setEdge(int edge, int val) {\n\t\tadd(edgeToNode(edge), val - w[edge]);\n\t\tw[edge] = val;\n\t}\n\n\tpublic static int jump(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] < dep[top[y]]) {\n\t\t\t\tans += sum(dfn[top[y]], dfn[y]);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += sum(dfn[top[x]], dfn[x]);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tif (dfn[x] < dfn[y]) {\n\t\t\tans += sum(dfn[x] + 1, dfn[y]);\n\t\t} else {\n\t\t\tans += sum(dfn[y] + 1, dfn[x]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getDistance(int x, int y) {\n\t\tif (belong[x] == belong[y]) {\n\t\t\treturn jump(x, y);\n\t\t} else {\n\t\t\tint a = Math.min(cycleId[belong[x]], cycleId[belong[y]]);\n\t\t\tint b = Math.max(cycleId[belong[x]], cycleId[belong[y]]);\n\t\t\tint p1 = sum(a, b - 1);\n\t\t\tint p2 = sum(n + 1, cntd) - p1;\n\t\t\treturn jump(x, belong[x]) + jump(y, belong[y]) + Math.min(p1, p2);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\tw[i] = in.nextInt();\n\t\t\taddEdge(u[i], v[i]);\n\t\t\taddEdge(v[i], u[i]);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x, y; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\tsetEdge(x, y);\n\t\t\t} else {\n\t\t\t\tout.println(getDistance(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code08_Journey1.java`\n\n```java\npackage class199;\n\n// 旅行，java版\n// 图中有n个点、m条无向边，节点编号1~n，图是普通树或者基环树\n// 对于普通树，从1号节点开始，选择不同的遍历顺序，会形成不同的dfs序列\n// 其中字典序最小的dfs序列，叫做普通树的答案\n// 对于基环树，可以删掉环上的任何一条边，让基环树变成某棵普通树\n// 众多普通树的答案中，字典序最小的结果，叫做基环树的答案\n// 图如果是普通树，打印普通树的答案，图如果是基环树，打印基环树的答案\n// 1 <= n <= 5 * 10^5\n// 普通版测试 : https://www.luogu.com.cn/problem/P5022\n// 加强版测试 : https://www.luogu.com.cn/problem/P5049\n// 提交以下的code，提交时请把类名改成"Main"，可以通过普通版测试\n// 加强版测试卡常数时间，java实现无法通过，索性递归函数也不改迭代了\n// 想通过用C++实现，本节课Code08_Journey2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code08_Journey1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m;\n\tpublic static int[][] arr = new int[MAXN << 1][2];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] from = new int[MAXN];\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\n\tpublic static boolean turn;\n\tpublic static boolean[] vis = new boolean[MAXN];\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int cnta;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dfs(int u) {\n\t\tdfn[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\tfrom[v] = u;\n\t\t\t\tdfs(v);\n\t\t\t} else if (dfn[u] < dfn[v]) {\n\t\t\t\tcycle[u] = true;\n\t\t\t\tfor (int i = v; i != u; i = from[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void path(int u, int back) {\n\t\tvis[u] = true;\n\t\tans[++cnta] = u;\n\t\tif (!cycle[u] || turn) {\n\t\t\t// u不在环上 或者 已经回过头了\n\t\t\t// 那么像在树上遍历即可\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (!vis[v]) {\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t// u在环上 并且 还没回过头\n\t\t// 考察最后一个儿子是否符合回头需要\n\t\tint end = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tend = v;\n\t\t\t}\n\t\t}\n\t\tturn = cycle[end] && end > back;\n\t\tif (turn) {\n\t\t\t// 回头成功\n\t\t\t// 无视最后一个儿子\n\t\t\t// 因为会从环的另一侧到达\n\t\t\t// 其他儿子像在树上遍历即可\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (!vis[v] && v != end) {\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t// 回头不成功\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (!vis[v]) {\n\t\t\t\tif (!cycle[v]) {\n\t\t\t\t\t// 当前儿子v不在环上\n\t\t\t\t\t// 像在树上遍历即可\n\t\t\t\t\tpath(v, n + 1);\n\t\t\t\t} else {\n\t\t\t\t\t// 当前儿子v在环上\n\t\t\t\t\t// 设置好后续的back\n\t\t\t\t\t// 回头可能发生在后续的环上\n\t\t\t\t\t// 因为节点u最多两个环上的孩子\n\t\t\t\t\t// 所以如下for循环最多发生两次\n\t\t\t\t\t// 所以时间复杂度不会变高\n\t\t\t\t\tint next = back;\n\t\t\t\t\tfor (int ne = nxt[e]; ne > 0; ne = nxt[ne]) {\n\t\t\t\t\t\tint nv = to[ne];\n\t\t\t\t\t\tif (!vis[nv]) {\n\t\t\t\t\t\t\tnext = nv;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tpath(v, next);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tarr[i][0] = u;\n\t\t\tarr[i][1] = v;\n\t\t\tarr[i + m][0] = v;\n\t\t\tarr[i + m][1] = u;\n\t\t}\n\t\tArrays.sort(arr, 1, m * 2 + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);\n\t\tfor (int i = 1; i <= m * 2; i++) {\n\t\t\taddEdge(arr[i][0], arr[i][1]);\n\t\t}\n\t\tdfs(1);\n\t\tpath(1, n + 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n```\n\n### `Code08_Journey2.java`\n\n```java\npackage class199;\n\n// 旅行，C++版\n// 图中有n个点、m条无向边，节点编号1~n，图是普通树或者基环树\n// 对于普通树，从1号节点开始，选择不同的遍历顺序，会形成不同的dfs序列\n// 其中字典序最小的dfs序列，叫做普通树的答案\n// 对于基环树，可以删掉环上的任何一条边，让基环树变成某棵普通树\n// 众多普通树的答案中，字典序最小的结果，叫做基环树的答案\n// 图如果是普通树，打印普通树的答案，图如果是基环树，打印基环树的答案\n// 1 <= n <= 5 * 10^5\n// 普通版测试 : https://www.luogu.com.cn/problem/P5022\n// 加强版测试 : https://www.luogu.com.cn/problem/P5049\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Edge {\n//    int u, v;\n//};\n//\n//bool EdgeCmp(Edge a, Edge b) {\n//    if (a.u != b.u) {\n//        return a.u < b.u;\n//    }\n//    return a.v > b.v;\n//}\n//\n//const int MAXN = 500001;\n//int n, m;\n//\n//Edge arr[MAXN << 1];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int cntd;\n//\n//int from[MAXN];\n//bool cycle[MAXN];\n//\n//bool turn;\n//bool vis[MAXN];\n//int ans[MAXN];\n//int cnta;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u) {\n//    dfn[u] = ++cntd;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            from[v] = u;\n//            dfs(v);\n//        } else if (dfn[u] < dfn[v]) {\n//            cycle[u] = true;\n//            for (int i = v; i != u; i = from[i]) {\n//                cycle[i] = true;\n//            }\n//        }\n//    }\n//}\n//\n//void path(int u, int back) {\n//    vis[u] = true;\n//    ans[++cnta] = u;\n//    if (!cycle[u] || turn) {\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            if (!vis[v]) {\n//                path(v, n + 1);\n//            }\n//        }\n//        return;\n//    }\n//    int end = 0;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            end = v;\n//        }\n//    }\n//    turn = cycle[end] && end > back;\n//    if (turn) {\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            if (!vis[v] && v != end) {\n//                path(v, n + 1);\n//            }\n//        }\n//        return;\n//    }\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (!vis[v]) {\n//            if (!cycle[v]) {\n//                path(v, n + 1);\n//            } else {\n//                int next = back;\n//                for (int ne = nxt[e]; ne > 0; ne = nxt[ne]) {\n//                    int nv = to[ne];\n//                    if (!vis[nv]) {\n//                        next = nv;\n//                        break;\n//                    }\n//                }\n//                path(v, next);\n//            }\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        arr[i] = {u, v};\n//        arr[i + m] = {v, u};\n//    }\n//    sort(arr + 1, arr + m * 2 + 1, EdgeCmp);\n//    for (int i = 1; i <= m * 2; i++) {\n//        addEdge(arr[i].u, arr[i].v);\n//    }\n//    dfs(1);\n//    path(1, n + 1);\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] << " ";\n//    }\n//    return 0;\n//}\n```\n\n### `FollowUp1.java`\n\n```java\npackage class199;\n\n// 有向图的基环树找环，java版\n// 这个文件课上没讲，有向图中找到基环，非常容易理解\n// 无向图的入环节点u，可以发现环的末尾节点v，因为边是无向的\n// 于是用dfn[u] < dfn[v]来判断环\n// 但是对有向图来说，假设出现的环如下\n// 入环节点a -> b -> c -> 环的末尾节点d -> 入环节点a\n// 不能放在入环节点a处判断，因为环的末尾节点d，不一定在a的邻居列表里\n// 边是有向的，也许只有d到a的边，不一定有a到d的边\n// 所以有向图的基环树找环，判断的时机，放在环的末尾节点处，具体说明如下\n// 节点一共三种状态，0表示没有访问，1表示在递归路径上，2表示递归执行完了\n// 依然记录每个点，在递归路径的前一个节点，也就是课上讲的from信息\n// 来到节点u时，判断儿子节点v，看看是否在递归路径上\n// 是的话，从u开始通过from走回v，环路就找全了，v是入环节点，u是环末尾点\n// 调用时扫过所有节点，没有访问过的节点去调用dfs，直到环被找到\n\npublic class FollowUp1 {\n\n\tpublic static int MAXN = 100001;\n\n\t// 建图\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int cntg;\n\n\t// 0表示没访问过，1表示在递归路径上，2表示递归执行完了\n\tpublic static int[] state = new int[MAXN];\n\n\t// 记录每个点在递归路径的前一个节点\n\tpublic static int[] from = new int[MAXN];\n\n\t// 标记环上节点\n\tpublic static boolean[] cycle = new boolean[MAXN];\n\n\t// 返回值表示是否找到了环\n\tpublic static boolean dfs(int u) {\n\t\tstate[u] = 1;\n\t\tboolean find = false;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (state[v] == 0) {\n\t\t\t\tfrom[v] = u;\n\t\t\t\tif (dfs(v)) {\n\t\t\t\t\tfind = true;\n\t\t\t\t}\n\t\t\t} else if (state[v] == 1) {\n\t\t\t\t// u -> v，此时v在递归路径上，说明发现了环\n\t\t\t\t// v是入环节点，u是环末尾点，利用from得到整个环\n\t\t\t\t// 这里执行的操作是标记环上节点，当然也可以生成环的其他信息\n\t\t\t\tcycle[v] = true;\n\t\t\t\tfor (int i = u; i != v; i = from[i]) {\n\t\t\t\t\tcycle[i] = true;\n\t\t\t\t}\n\t\t\t\tfind = true;\n\t\t\t}\n\t\t\tif (find) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tstate[u] = 2;\n\t\treturn find;\n\t}\n\n}\n\n```\n\n### `FollowUp2.java`\n\n```java\npackage class199;\n\n// 有向图的基环树找环，C++版\n// 这个文件课上没讲，有向图中找到基环，非常容易理解\n// 无向图的入环节点u，可以发现环的末尾节点v，因为边是无向的\n// 于是用dfn[u] < dfn[v]来判断环\n// 但是对有向图来说，假设出现的环如下\n// 入环节点a -> b -> c -> 环的末尾节点d -> 入环节点a\n// 不能放在入环节点a处判断，因为环的末尾节点d，不一定在a的邻居列表里\n// 边是有向的，也许只有d到a的边，不一定有a到d的边\n// 所以有向图的基环树找环，判断的时机，放在环的末尾节点处，具体说明如下\n// 节点一共三种状态，0表示没有访问，1表示在递归路径上，2表示递归执行完了\n// 依然记录每个点，在递归路径的前一个节点，也就是课上讲的from信息\n// 来到节点u时，判断儿子节点v，看看是否在递归路径上\n// 是的话，从u开始通过from走回v，环路就找全了，v是入环节点，u是环末尾点\n// 调用时扫过所有节点，没有访问过的节点去调用dfs，直到环被找到\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//\n//int head[MAXN];\n//int nxt[MAXN];\n//int to[MAXN];\n//int cntg;\n//\n//int state[MAXN];\n//int from[MAXN];\n//bool cycle[MAXN];\n//\n//bool dfs(int u) {\n//    state[u] = 1;\n//    bool find = false;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (state[v] == 0) {\n//            from[v] = u;\n//            if (dfs(v)) {\n//                find = true;\n//            }\n//        } else if (state[v] == 1) {\n//            cycle[v] = true;\n//            for (int i = u; i != v; i = from[i]) {\n//                cycle[i] = true;\n//            }\n//            find = true;\n//        }\n//        if (find) {\n//            break;\n//        }\n//    }\n//    state[u] = 2;\n//    return find;\n//}\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
dff46404-facf-4108-a6dd-cc6bd36d61fa	1c76ab63-b008-4242-b35c-c2ccba6b1d65	deep	仙人掌图和相关题目	# 200. 仙人掌图和相关题目\n\n> 难度标签：**进阶** ｜ 主题：**图论** ｜ 来源：左程云《算法讲解》第 200 讲\n\n## 第 1 页：仙人掌图和相关题目\n\n左程云\n前置知识\n讲解078 - 树型dp\n讲解189 ~ 讲解194 - Tarjan算法（强连通、割边、边双连通、割点、点双连通、圆方树）\n讲解194 - 圆方树\n讲解199 - 基环树\n讲解054 - 单调队列    本节课题目5、题目7需要\n讲解161 - 树链剖分    本节课题目6、题目7、题目8需要\n讲解180 - 虚树        本节课题目7需要\n本节课讲述\n仙人掌遍历和找环的过程    改写Tarjan算法\n仙人掌dp的经典题目       题目1 ~ 题目5\n仙人掌结合圆方树的题目    题目6 ~ 题目8\n\n## 第 2 页：仙人掌图和相关题目\n\n左程云\n仙人掌图是无向连通图，英文叫 cactus graph，简称 cactus\n每条边要么是割边，要么最多出现在一个简单环里\n仙人掌可以理解为允许出现简单环的树\n普通的树也是仙人掌图\n仙人掌的一个简单环是一个点双连通分量，不是一个边双连通分量\n仙人掌的割边直接作为树边\n仙人掌可以转成圆方树\n如此一来，很多仙人掌问题转化成了树上问题\n\n## 第 3 页：仙人掌图和相关题目\n\n左程云\n之前的课已经讲过的树上内容\n树型DP、树上倍增和LCA、树的直径、树的重心、树上差分、换根DP\n树链剖分、虚树、点分治、点分树、边分治、边分树、树的欧拉序和dfn序、基环树\n关于仙人掌的节点，有以下结论\n1，一个节点，有可能是多个环的环顶节点\n2，一个节点，如果不是环顶节点，最多参与一个环\n3，很多情况下，生成环上节点的信息，会刻意不包含环顶节点，就是这个原因\n4，判断仙人掌 或者 生成环上节点的信息，经常利用这个结论\n\n## 第 4 页：仙人掌图和相关题目\n\n左程云\n仙人掌遍历和找环的过程\n1，割边出现，两个圆点直连\n2，环出现，生成方点，环顶节点连接方点，方点再去连接环中其他节点\n3，利用边判断回头路，边的编号从2开始，e的反向边 = e ^ 1\n4，Tarjan算法的一个改版\n课上重点图解代码，本节课ShowDetail文件\n环中的每条边依次设置归属，尤其环的末尾边分配给环顶节点\n\n## 第 5 页：仙人掌图和相关题目\n\n左程云\n题目1\n仙人掌删边方案数\n给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n如果图不是仙人掌打印0，如果图是仙人掌，可以在图中删除一些边\n如果删除后剩下的图仍然连通，就叫有效的删边方案\n允许一条边也不删，打印有效删边的方案数，答案可能很大，需要高精度\n1 <= n <= 2 * 10^4\n1 <= 边总数 <= 10^6\n测试链接 : https://www.luogu.com.cn/problem/P4129\n\n## 第 6 页：仙人掌图和相关题目\n\n左程云\n题目2\n仙人掌加边方案数\n给定n个点、m条边的无向连通图，输入保证没有自环、没有重边\n可以在图中加入一些新的边，如果加入后得到的图是仙人掌，就叫有效的加边方案\n允许一条边也不加，但不允许加边后，形成自环或二元环，计算有效的加边方案数\n答案对 998244353 取余，每次输入可能有多组测试数据\n1 <= n <= 5 * 10^5\n1 <= m <= 10^6\n测试链接 : https://www.luogu.com.cn/problem/P3687\n\n## 第 7 页：仙人掌图和相关题目\n\n左程云\n题目3\n仙人掌最长路线\n给定n个点、m条边的无向连通图，输入保证图是仙人掌\n路线可以从任何城市开始，但必须在1号点结束\n路线可以重复经过同一个点，但不能重复经过同一条边\n计算最长路线的边数\n1 <= n <= 10^4\n1 <= m <= 2 * 10^4\n测试链接 : https://www.luogu.com.cn/problem/P6335\n\n## 第 8 页：仙人掌图和相关题目\n\n左程云\n题目4\n仙人掌最大独立集\n给定n个点、m条边的无向连通图，输入保证图是仙人掌\n你可以选择一些点，但是图中任意相邻两点不能同时选择\n计算能得到的最大点权累加和\n第一个测试链接，给定每个点的点权\n第二个测试链接，认为每个点的点权是1\n1 <= n <= 10^5\n1 <= m <= 2 * 10^5\n测试链接 : https://www.luogu.com.cn/problem/P4410\n测试链接 : https://www.luogu.com.cn/problem/P10779\n\n## 第 9 页：仙人掌图和相关题目\n\n左程云\n题目5\n仙人掌直径\n给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n点x到点y的距离，是指x到y的最短路径中的边数\n仙人掌直径，是指任意两点距离的最大值\n输入保证图是仙人掌，计算仙人掌直径\n1 <= n <= 5 * 10^4\n1 <= 边总数 <= 10^6\n测试链接 : https://www.luogu.com.cn/problem/P4244\n\n## 第 10 页：仙人掌图和相关题目\n\n左程云\n题目6\n仙人掌最短路\n给定n个点、m条边的仙人掌图，每条边有边权，没有自环，没有重边\n一共q条查询，每条查询格式为 x y，查询点x和点y之间的最短路距离\n1 <= n、q <= 10^4\n1 <= m <= 2 * 10^4\n1 <= 边权 <= 10^5\n测试链接 : https://www.luogu.com.cn/problem/P5236\n需要先看懂，树链剖分，圆方树，仙人掌结合圆方树模版题\nx点向上找到进入某环的入口节点\n\n## 第 11 页：仙人掌图和相关题目\n\n左程云\n题目7\n最短路最大值\n给定n个点、m条边的仙人掌图，每条边有边权，没有自环，可能有重边\n一共q条查询，格式 k a1 a2 .. ak 含义如下\n给定的k个点中，任意选两个点，可以选择相同点\n打印它们之间最短路的最大值是多少\n1 <= n、查询中k的总和 <= 3 * 10^5\n测试链接 : https://uoj.ac/problem/87\n需要先看懂，树链剖分，圆方树，虚树（讲解180）\n仙人掌 + 树链剖分 + 圆方树 + 虚树 + 直径\n\n## 第 12 页：仙人掌图和相关题目\n\n左程云\n题目8\n仙人掌路径翻转\n给定n个点、m条边的仙人掌图，没有自环，没有重边，1号节点是仙人掌的根\n输入保证每个简单环的边数都为奇数，所以点x到根的最短路和最长路都是唯一的\n以点x为头的子仙人掌，是指删掉根到x路径上的边后，包含x的连通块\n每个节点只有黑白两种颜色，初始时所有节点为黑，一共有q条操作，类型如下\n操作 1 x : 点x到根的最短路上所有节点，颜色翻转\n操作 2 x : 点x到根的最长路上所有节点，颜色翻转\n操作 3 x : 查询以点x为头的子仙人掌中，黑色节点的数量\n1 <= n、m、q <= 5 * 10^4\n测试链接 : https://uoj.ac/problem/158\n仙人掌 + 圆方树 + 重链剖分重新设计dfn序号分配方式 + 线段树 + 很多情况讨论\n\n## 模板代码\n\n### `Code01_CactusDeleteEdge1.java`\n\n```java\npackage class200;\n\n// 仙人掌删边方案数，java版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 如果图不是仙人掌打印0，如果图是仙人掌，可以在图中删除一些边\n// 如果删除后剩下的图仍然连通，就叫有效的删边方案\n// 允许一条边也不删，打印有效删边的方案数，答案可能很大，需要高精度\n// 1 <= n <= 2 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4129\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.math.BigInteger;\n\npublic class Code01_CactusDeleteEdge1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// 统计每个环的边数\n\tpublic static int[] edgeCnt = new int[MAXN];\n\tpublic static int cntc;\n\n\t// 不作为环顶节点的情况下，参与了几个环\n\tpublic static int[] cycleCnt = new int[MAXN];\n\n\t// 本题需要高精度乘法\n\tpublic static BigInteger ans;\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\tcntc++;\n\t\t\t\t\tedgeCnt[cntc] = 1;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tedgeCnt[cntc]++;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\tcycleCnt[u]++;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tcntc++;\n\t\t\t\t\t\tedgeCnt[cntc] = 1;\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\tedgeCnt[cntc]++;\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, k, x, y; i <= m; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tfor (int j = 2; j <= k; j++) {\n\t\t\t\ty = in.nextInt();\n\t\t\t\taddEdge(x, y);\n\t\t\t\taddEdge(y, x);\n\t\t\t\tx = y;\n\t\t\t}\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0 || cycleCnt[i] >= 2) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tans = BigInteger.ONE;\n\t\t\tfor (int i = 1; i <= cntc; i++) {\n\t\t\t\tans = ans.multiply(BigInteger.valueOf(edgeCnt[i] + 1));\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t} else {\n\t\t\tout.println(0);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code01_CactusDeleteEdge2.java`\n\n```java\npackage class200;\n\n// 仙人掌删边方案数，C++版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 如果图不是仙人掌打印0，如果图是仙人掌，可以在图中删除一些边\n// 如果删除后剩下的图仍然连通，就叫有效的删边方案\n// 允许一条边也不删，打印有效删边的方案数，答案可能很大，需要高精度\n// 1 <= n <= 2 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4129\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 20001;\n//const int MAXM = 1000001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int edgeCnt[MAXN];\n//int cntc;\n//\n//int cycleCnt[MAXN];\n//\n//string ans;\n//\n//void multiply(int x) {\n//    int carry = 0;\n//    for (int i = ans.size() - 1; i >= 0; i--) {\n//        int cur = (ans[i] - '0') * x + carry;\n//        ans[i] = cur % 10 + '0';\n//        carry = cur / 10;\n//    }\n//    string pre = "";\n//    while (carry > 0) {\n//        pre += carry % 10 + '0';\n//        carry /= 10;\n//    }\n//    reverse(pre.begin(), pre.end());\n//    ans = pre + ans;\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            if (low[v] < dfn[u]) {\n//                low[u] = min(low[u], low[v]);\n//                cycleCnt[u]++;\n//            } else if (low[v] > dfn[u]) {\n//                top--;\n//            } else {\n//                cntc++;\n//                edgeCnt[cntc] = 1;\n//                int pop;\n//                do {\n//                    pop = sta[top--];\n//                    edgeCnt[cntc]++;\n//                } while (pop != v);\n//            }\n//        } else if (dfn[v] < dfn[u]) {\n//            low[u] = min(low[u], dfn[v]);\n//            cycleCnt[u]++;\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntg = 1;\n//    for (int i = 1, k, x, y; i <= m; i++) {\n//        cin >> k >> x;\n//        for (int j = 2; j <= k; j++) {\n//            cin >> y;\n//            addEdge(x, y);\n//            addEdge(y, x);\n//            x = y;\n//        }\n//    }\n//    tarjan(1, 0);\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0 || cycleCnt[i] >= 2) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    if (check) {\n//        ans = "1";\n//        for (int i = 1; i <= cntc; i++) {\n//            multiply(edgeCnt[i] + 1);\n//        }\n//        cout << ans << "\\n";\n//    } else {\n//        cout << 0 << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_CactusAddEdge1.java`\n\n```java\npackage class200;\n\n// 仙人掌加边方案数，java版\n// 给定n个点、m条边的无向连通图，输入保证没有自环、没有重边\n// 可以在图中加入一些新的边，如果加入后得到的图是仙人掌，就叫有效的加边方案\n// 允许一条边也不加，但不允许加边后，形成自环或二元环，计算有效的加边方案数\n// 答案对 998244353 取余，每次输入可能有多组测试数据\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P3687\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_CactusAddEdge1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int MOD = 998244353;\n\tpublic static int t, n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static boolean[] cycleEdge = new boolean[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] fromEdge = new int[MAXN];\n\tpublic static int[] cycleCnt = new int[MAXN];\n\n\tpublic static boolean[] vis = new boolean[MAXN];\n\n\t// f[i] : 点周围有i个方向，一旦两个方向配对，不可再用\n\t// 方向也可不配对，总的配对方法数\n\tpublic static long[] f = new long[MAXN];\n\n\t// dp[u] : u周围的每个支路配对或者不配对，形成的方案数\n\t// 两个支路配对是指，各自选出一个端点然后连边\n\t// 如果u是根，认为上方没有支路\n\t// 如果u不是根，认为上方有支路，内有一个点\n\tpublic static long[] dp = new long[MAXN];\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] staf = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, fa, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int fa, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstaf[stacksiz] = fa;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\tfa = staf[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tcycleEdge[cntg] = false;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tfromEdge[v] = e;\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\tint pop;\n\t\t\t\t\tint edge = fromEdge[u];\n\t\t\t\t\tcycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tedge = fromEdge[pop];\n\t\t\t\t\t\tcycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n\t\t\t\t\t} while (pop != v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tfromEdge[v] = e;\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\tcycleCnt[u]++;\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, 0, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tfromEdge[v] = e;\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tint pop;\n\t\t\t\t\t\tint edge = fromEdge[u];\n\t\t\t\t\t\tcycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n\t\t\t\t\t\tdo {\n\t\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\t\tedge = fromEdge[pop];\n\t\t\t\t\t\t\tcycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n\t\t\t\t\t\t} while (pop != v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tfromEdge[v] = e;\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t\tcycleCnt[u]++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, 0, e);\n\t\t\t\t\tpush(v, e, -1, 0, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, 0, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void dpOnTree1(int u, int fa) {\n\t\tvis[u] = true;\n\t\tlong ans = 1;\n\t\tint direction = fa == 0 ? 0 : 1;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa && !cycleEdge[e]) {\n\t\t\t\tdpOnTree1(v, u);\n\t\t\t\tans = ans * dp[v] % MOD;\n\t\t\t\tdirection++;\n\t\t\t}\n\t\t}\n\t\tdp[u] = ans * f[direction] % MOD;\n\t}\n\n\t// 迭代版\n\tpublic static void dpOnTree2(int cur, int father) {\n\t\tstacksiz = 0;\n\t\tpush(cur, 0, 0, father, -1);\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tvis[u] = true;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, 0, 0, fa, e);\n\t\t\t\tint v = to[e];\n\t\t\t\tif (v != fa && !cycleEdge[e]) {\n\t\t\t\t\tpush(v, 0, 0, u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlong ans = 1;\n\t\t\t\tint direction = fa == 0 ? 0 : 1;\n\t\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\t\tint v = to[e];\n\t\t\t\t\tif (v != fa && !cycleEdge[e]) {\n\t\t\t\t\t\tans = ans * dp[v] % MOD;\n\t\t\t\t\t\tdirection++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tdp[u] = ans * f[direction] % MOD;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\tf[0] = f[1] = 1;\n\t\tf[2] = 2;\n\t\tfor (int i = 3; i <= n; i++) {\n\t\t\tf[i] = (f[i - 1] + f[i - 2] * (i - 1)) % MOD;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = fromEdge[i] = cycleCnt[i] = 0;\n\t\t\tvis[i] = false;\n\t\t\tdp[i] = 0;\n\t\t}\n\t\tcntg = 1;\n\t\tcntd = top = 0;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tprepare();\n\t\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\t\tu = in.nextInt();\n\t\t\t\tv = in.nextInt();\n\t\t\t\taddEdge(u, v);\n\t\t\t\taddEdge(v, u);\n\t\t\t}\n\t\t\t// tarjan1(1, 0);\n\t\t\ttarjan2(1, 0);\n\t\t\tboolean check = true;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (cycleCnt[i] >= 2) {\n\t\t\t\t\tcheck = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (check) {\n\t\t\t\tlong ans = 1;\n\t\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\t\tif (!vis[i]) {\n\t\t\t\t\t\t// dpOnTree1(i, 0);\n\t\t\t\t\t\tdpOnTree2(i, 0);\n\t\t\t\t\t\tans = ans * dp[i] % MOD;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tout.println(ans);\n\t\t\t} else {\n\t\t\t\tout.println(0);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code02_CactusAddEdge2.java`\n\n```java\npackage class200;\n\n// 仙人掌加边方案数，C++版\n// 给定n个点、m条边的无向连通图，输入保证没有自环、没有重边\n// 可以在图中加入一些新的边，如果加入后得到的图是仙人掌，就叫有效的加边方案\n// 允许一条边也不加，但不允许加边后，形成自环或二元环，计算有效的加边方案数\n// 答案对 998244353 取余，每次输入可能有多组测试数据\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P3687\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 500001;\n//const int MAXM = 1000001;\n//const int MOD = 998244353;\n//int t, n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//bool cycleEdge[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int fromEdge[MAXN];\n//int cycleCnt[MAXN];\n//\n//bool vis[MAXN];\n//ll f[MAXN];\n//ll dp[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    cycleEdge[cntg] = false;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            fromEdge[v] = e;\n//            if (low[v] < dfn[u]) {\n//                low[u] = min(low[u], low[v]);\n//                cycleCnt[u]++;\n//            } else if (low[v] > dfn[u]) {\n//                top--;\n//            } else {\n//                int pop;\n//                int edge = fromEdge[u];\n//                cycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n//                do {\n//                    pop = sta[top--];\n//                    edge = fromEdge[pop];\n//                    cycleEdge[edge] = cycleEdge[edge ^ 1] = true;\n//                } while (pop != v);\n//            }\n//        } else if (dfn[v] < dfn[u]) {\n//            fromEdge[v] = e;\n//            low[u] = min(low[u], dfn[v]);\n//            cycleCnt[u]++;\n//        }\n//    }\n//}\n//\n//void dpOnTree(int u, int fa) {\n//    vis[u] = true;\n//    ll ans = 1;\n//    int direction = fa == 0 ? 0 : 1;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa && !cycleEdge[e]) {\n//            dpOnTree(v, u);\n//            ans = ans * dp[v] % MOD;\n//            direction++;\n//        }\n//    }\n//    dp[u] = ans * f[direction] % MOD;\n//}\n//\n//void prepare() {\n//    f[0] = f[1] = 1;\n//    f[2] = 2;\n//    for (int i = 3; i <= n; i++) {\n//        f[i] = (f[i - 1] + f[i - 2] * (i - 1)) % MOD;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        head[i] = dfn[i] = low[i] = fromEdge[i] = cycleCnt[i] = 0;\n//        vis[i] = false;\n//        dp[i] = 0;\n//    }\n//    cntg = 1;\n//    cntd = top = 0;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int c = 1; c <= t; c++) {\n//        cin >> n >> m;\n//        prepare();\n//        for (int i = 1, u, v; i <= m; i++) {\n//            cin >> u >> v;\n//            addEdge(u, v);\n//            addEdge(v, u);\n//        }\n//        tarjan(1, 0);\n//        bool check = true;\n//        for (int i = 1; i <= n; i++) {\n//            if (cycleCnt[i] >= 2) {\n//                check = false;\n//                break;\n//            }\n//        }\n//        if (check) {\n//            ll ans = 1;\n//            for (int i = 1; i <= n; i++) {\n//                if (!vis[i]) {\n//                    dpOnTree(i, 0);\n//                    ans = ans * dp[i] % MOD;\n//                }\n//            }\n//            cout << ans << "\\n";\n//        } else {\n//            cout << 0 << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_CactusLongestRoute1.java`\n\n```java\npackage class200;\n\n// 仙人掌最长路线，java版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 路线可以从任何城市开始，但必须在1号点结束\n// 路线可以重复经过同一个点，但不能重复经过同一条边\n// 计算最长路线的边数\n// 1 <= n <= 10^4\n// 1 <= m <= 2 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P6335\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_CactusLongestRoute1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 20001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] cycle = new int[MAXN];\n\n\t// f[u] : 在u向下的结构中（以u为头的子仙人掌），从u出发并最终回到u，能走过的最大边数\n\tpublic static int[] f = new int[MAXN];\n\n\t// g[u] : 在u向下的结构中（以u为头的子仙人掌），从u出发，终点任意，能走过的最大边数\n\tpublic static int[] g = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tcycle[++siz] = pop;\n\t\t} while (pop != v);\n\t\t// best表示，这个环上任选一个点作为最后出去的位置\n\t\t// 从u沿两侧之一走到它，能够得到的不回到u的最大边数\n\t\tint best = 0;\n\t\tint sum = 1;\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\tbest = Math.max(best, sum + g[cycle[i]]);\n\t\t\tsum += f[cycle[i]] + 1;\n\t\t}\n\t\t// u可以下方有多个环，所以新增此时的sum\n\t\tf[u] += sum;\n\t\tint otherSide = sum;\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\totherSide -= f[cycle[i]] + 1;\n\t\t\tbest = Math.max(best, otherSide + g[cycle[i]]);\n\t\t}\n\t\treturn best - sum;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\t// f[u]表示从u出发并最终回到u的最大边数\n\t\t// delta为了计算，g[u] = f[u] + delta\n\t\t// 表示额外选择一条最后不回到u的出口路线，能带来的最大增量\n\t\tint delta = 0;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t\tdelta = Math.max(delta, g[v] + 1);\n\t\t\t\t} else {\n\t\t\t\t\tdelta = Math.max(delta, dpOnCycle(u, v));\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tg[u] = f[u] + delta;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tout.println(g[1]);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code03_CactusLongestRoute2.java`\n\n```java\npackage class200;\n\n// 仙人掌最长路线，C++版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 路线可以从任何城市开始，但必须在1号点结束\n// 路线可以重复经过同一个点，但不能重复经过同一条边\n// 计算最长路线的边数\n// 1 <= n <= 10^4\n// 1 <= m <= 2 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P6335\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 10001;\n//const int MAXM = 20001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int cycle[MAXN];\n//int f[MAXN];\n//int g[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//int dpOnCycle(int u, int v) {\n//    int siz = 0;\n//    int pop;\n//    do {\n//        pop = sta[top--];\n//        cycle[++siz] = pop;\n//    } while (pop != v);\n//    int best = 0;\n//    int sum = 1;\n//    for (int i = 1; i <= siz; i++) {\n//        best = max(best, sum + g[cycle[i]]);\n//        sum += f[cycle[i]] + 1;\n//    }\n//    f[u] += sum;\n//    int otherSide = sum;\n//    for (int i = 1; i <= siz; i++) {\n//        otherSide -= f[cycle[i]] + 1;\n//        best = max(best, otherSide + g[cycle[i]]);\n//    }\n//    return best - sum;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    int delta = 0;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            if (low[v] < dfn[u]) {\n//                low[u] = min(low[u], low[v]);\n//            } else if (low[v] > dfn[u]) {\n//                top--;\n//                delta = max(delta, g[v] + 1);\n//            } else {\n//                delta = max(delta, dpOnCycle(u, v));\n//            }\n//        } else if (dfn[v] < dfn[u]) {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//    g[u] = f[u] + delta;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntg = 1;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    tarjan(1, 0);\n//    cout << g[1] << "\\n";\n//    return 0;\n//}\n```\n\n### `Code04_CactusIndependentSet1.java`\n\n```java\npackage class200;\n\n// 仙人掌最大独立集，java版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 你可以选择一些点，但是图中任意相邻两点不能同时选择\n// 计算能得到的最大点权累加和\n// 第一个测试链接，给定每个点的点权\n// 第二个测试链接，认为每个点的点权是1\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4410\n// 测试链接 : https://www.luogu.com.cn/problem/P10779\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_CactusIndependentSet1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int INF = 1000000000;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// 收集环上的节点，不包含环顶\n\tpublic static int[] cycle = new int[MAXN];\n\n\t// dp[u][0] : 以u为头的子仙人掌中，不选u的情况下，获得的最大收益\n\t// dp[u][1] : 以u为头的子仙人掌中，选u的情况下，获得的最大收益\n\tpublic static int[][] dp = new int[MAXN][2];\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tcycle[++siz] = pop;\n\t\t} while (pop != v);\n\t\t// 不选u\n\t\tint pre0 = dp[cycle[1]][0];\n\t\tint pre1 = dp[cycle[1]][1];\n\t\tint cur0, cur1;\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tint x = cycle[i];\n\t\t\tcur0 = Math.max(pre0, pre1) + dp[x][0];\n\t\t\tcur1 = pre0 + dp[x][1];\n\t\t\tpre0 = cur0;\n\t\t\tpre1 = cur1;\n\t\t}\n\t\tdp[u][0] += Math.max(pre0, pre1);\n\t\t// 选u\n\t\tpre0 = dp[cycle[1]][0];\n\t\tpre1 = -INF;\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tint x = cycle[i];\n\t\t\tcur0 = Math.max(pre0, pre1) + dp[x][0];\n\t\t\tcur1 = pre0 + dp[x][1];\n\t\t\tpre0 = cur0;\n\t\t\tpre1 = cur1;\n\t\t}\n\t\tdp[u][1] += pre0;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tdp[u][0] = 0;\n\t\tdp[u][1] = arr[u];\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t\t\ttop--;\n\t\t\t\t} else {\n\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\tdp[u][0] = 0;\n\t\t\t\tdp[u][1] = arr[u];\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\tdp[u][0] += Math.max(dp[v][0], dp[v][1]);\n\t\t\t\t\t\tdp[u][1] += dp[v][0];\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\n\t\t// 洛谷P4410，使用如下的点权设置\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\n\t\t// 洛谷P10779，使用如下的点权设置\n//\t\tfor (int i = 1; i <= n; i++) {\n//\t\t\tarr[i] = 1;\n//\t\t}\n\n\t\ttarjan2(1, 0);\n\t\tout.println(Math.max(dp[1][0], dp[1][1]));\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code04_CactusIndependentSet2.java`\n\n```java\npackage class200;\n\n// 仙人掌最大独立集，C++版\n// 给定n个点、m条边的无向连通图，输入保证图是仙人掌\n// 你可以选择一些点，但是图中任意相邻两点不能同时选择\n// 计算能得到的最大点权累加和\n// 第一个测试链接，给定每个点的点权\n// 第二个测试链接，认为每个点的点权是1\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4410\n// 测试链接 : https://www.luogu.com.cn/problem/P10779\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 200001;\n//const int INF = 1000000000;\n//int n, m;\n//int arr[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int cycle[MAXN];\n//int dp[MAXN][2];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dpOnCycle(int u, int v) {\n//    int siz = 0;\n//    int pop;\n//    do {\n//        pop = sta[top--];\n//        cycle[++siz] = pop;\n//    } while (pop != v);\n//    int pre0 = dp[cycle[1]][0], pre1 = dp[cycle[1]][1];\n//    int cur0, cur1;\n//    for (int i = 2; i <= siz; i++) {\n//        int x = cycle[i];\n//        cur0 = max(pre0, pre1) + dp[x][0];\n//        cur1 = pre0 + dp[x][1];\n//        pre0 = cur0;\n//        pre1 = cur1;\n//    }\n//    dp[u][0] += max(pre0, pre1);\n//    pre0 = dp[cycle[1]][0];\n//    pre1 = -INF;\n//    for (int i = 2; i <= siz; i++) {\n//        int x = cycle[i];\n//        cur0 = max(pre0, pre1) + dp[x][0];\n//        cur1 = pre0 + dp[x][1];\n//        pre0 = cur0;\n//        pre1 = cur1;\n//    }\n//    dp[u][1] += pre0;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    dp[u][0] = 0;\n//    dp[u][1] = arr[u];\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            if (low[v] < dfn[u]) {\n//                low[u] = min(low[u], low[v]);\n//            } else if (low[v] > dfn[u]) {\n//                dp[u][0] += max(dp[v][0], dp[v][1]);\n//                dp[u][1] += dp[v][0];\n//                top--;\n//            } else {\n//                dpOnCycle(u, v);\n//            }\n//        } else if (dfn[v] < dfn[u]) {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntg = 1;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//\n//    // 洛谷P4410，使用如下的点权设置\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//\n//    // 洛谷P10779，使用如下的点权设置\n//    // for (int i = 1; i <= n; i++) {\n//    //     arr[i] = 1;\n//    // }\n//\n//    tarjan(1, 0);\n//    cout << max(dp[1][0], dp[1][1]) << "\\n";\n//    return 0;\n//}\n```\n\n### `Code05_CactusDiameter1.java`\n\n```java\npackage class200;\n\n// 仙人掌直径，java版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 点x到点y的距离，是指x到y的最短路径中的边数\n// 仙人掌直径，是指任意两点距离的最大值\n// 输入保证图是仙人掌，计算仙人掌直径\n// 1 <= n <= 5 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4244\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_CactusDiameter1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int MAXM = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\t// dist[u] : 以u为头的子仙人掌中，u到任意点的最短路距离的最大值\n\tpublic static int[] dist = new int[MAXN];\n\t// 收集环中每个点的dist，然后复制一份\n\tpublic static int[] arr = new int[MAXN << 1];\n\t// 单调队列\n\tpublic static int[] que = new int[MAXN << 1];\n\t// 答案\n\tpublic static int diameter;\n\n\t// 递归改迭代需要的栈\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stacksiz] = u;\n\t\tstap[stacksiz] = preEdge;\n\t\tstas[stacksiz] = status;\n\t\tstae[stacksiz] = e;\n\t\tstacksiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksiz--;\n\t\tu = stau[stacksiz];\n\t\tpreEdge = stap[stacksiz];\n\t\tstatus = stas[stacksiz];\n\t\te = stae[stacksiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void dpOnCycle(int u, int v) {\n\t\tint siz = 0;\n\t\tarr[++siz] = dist[u];\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[top--];\n\t\t\tarr[++siz] = dist[pop];\n\t\t} while (pop != v);\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\tarr[i + siz] = arr[i];\n\t\t}\n\t\tint l = 1, r = 0;\n\t\tque[++r] = 1;\n\t\tfor (int i = 2; i <= siz << 1; i++) {\n\t\t\twhile (l <= r && (i - que[l]) * 2 > siz) {\n\t\t\t\tl++;\n\t\t\t}\n\t\t\tdiameter = Math.max(diameter, arr[i] + i + arr[que[l]] - que[l]);\n\t\t\twhile (l <= r && arr[que[r]] - que[r] <= arr[i] - i) {\n\t\t\t\tr--;\n\t\t\t}\n\t\t\tque[++r] = i;\n\t\t}\n\t\tfor (int i = 2; i <= siz; i++) {\n\t\t\tdist[u] = Math.max(dist[u], arr[i] + Math.min(i - 1, siz - (i - 1)));\n\t\t}\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\ttop--;\n\t\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + 1);\n\t\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + 1);\n\t\t\t\t} else {\n\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\t\ttop--;\n\t\t\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + 1);\n\t\t\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + 1);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tdpOnCycle(u, v);\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tif (dfn[v] < dfn[u]) {\n\t\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntg = 1;\n\t\tfor (int i = 1, k, x, y; i <= m; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tfor (int j = 2; j <= k; j++) {\n\t\t\t\ty = in.nextInt();\n\t\t\t\taddEdge(x, y);\n\t\t\t\taddEdge(y, x);\n\t\t\t\tx = y;\n\t\t\t}\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tout.println(diameter);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code05_CactusDiameter2.java`\n\n```java\npackage class200;\n\n// 仙人掌直径，C++版\n// 给定n个点、m条路径表示无向图，每条路径的相邻两点之间都有边\n// 点x到点y的距离，是指x到y的最短路径中的边数\n// 仙人掌直径，是指任意两点距离的最大值\n// 输入保证图是仙人掌，计算仙人掌直径\n// 1 <= n <= 5 * 10^4\n// 1 <= 边总数 <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P4244\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 50001;\n//const int MAXM = 1000001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int top;\n//\n//int dist[MAXN];\n//int arr[MAXN << 1];\n//int que[MAXN << 1];\n//int diameter;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dpOnCycle(int u, int v) {\n//    int siz = 0;\n//    arr[++siz] = dist[u];\n//    int pop;\n//    do {\n//        pop = sta[top--];\n//        arr[++siz] = dist[pop];\n//    } while (pop != v);\n//    for (int i = 1; i <= siz; i++) {\n//        arr[i + siz] = arr[i];\n//    }\n//    int l = 1, r = 0;\n//    que[++r] = 1;\n//    for (int i = 2; i <= siz << 1; i++) {\n//        while (l <= r && (i - que[l]) * 2 > siz) {\n//            l++;\n//        }\n//        diameter = max(diameter, arr[i] + i + arr[que[l]] - que[l]);\n//        while (l <= r && arr[que[r]] - que[r] <= arr[i] - i) {\n//            r--;\n//        }\n//        que[++r] = i;\n//    }\n//    for (int i = 2; i <= siz; i++) {\n//        dist[u] = max(dist[u], arr[i] + min(i - 1, siz - (i - 1)));\n//    }\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            if (low[v] < dfn[u]) {\n//                low[u] = min(low[u], low[v]);\n//            } else if (low[v] > dfn[u]) {\n//                top--;\n//                diameter = max(diameter, dist[u] + dist[v] + 1);\n//                dist[u] = max(dist[u], dist[v] + 1);\n//            } else {\n//                dpOnCycle(u, v);\n//            }\n//        } else if (dfn[v] < dfn[u]) {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntg = 1;\n//    for (int i = 1, k, x, y; i <= m; i++) {\n//        cin >> k >> x;\n//        for (int j = 2; j <= k; j++) {\n//            cin >> y;\n//            addEdge(x, y);\n//            addEdge(y, x);\n//            x = y;\n//        }\n//    }\n//    tarjan(1, 0);\n//    cout << diameter << "\\n";\n//    return 0;\n//}\n```\n\n### `Code06_CactusShortestPaths1.java`\n\n```java\npackage class200;\n\n// 仙人掌最短路，java版\n// 给定n个点、m条边的仙人掌图，每条边有边权，没有自环，没有重边\n// 一共q条查询，每条查询格式为 x y，查询点x和点y之间的最短路距离\n// 1 <= n、q <= 10^4\n// 1 <= m <= 2 * 10^4\n// 1 <= 边权 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5236\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_CactusShortestPaths1 {\n\n\tpublic static int MAXN = 50001;\n\tpublic static int n, m, q, cntn;\n\n\t// 原图\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN];\n\tpublic static int[] to1 = new int[MAXN];\n\tpublic static int[] weight1 = new int[MAXN];\n\tpublic static int cnt1;\n\n\t// 圆方树，单向边\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN];\n\tpublic static int[] to2 = new int[MAXN];\n\tpublic static int[] weight2 = new int[MAXN];\n\tpublic static int cnt2;\n\n\t// tarjan算法求圆方树\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int stasiz;\n\n\t// 环的信息\n\tpublic static int[] fromWeight = new int[MAXN];\n\tpublic static int[] cycleLen = new int[MAXN];\n\tpublic static int[] cycleSum = new int[MAXN];\n\n\t// 树链剖分\n\t// len[u] : 圆方树上从头节点到u的长度\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] len = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static void addEdge1(int u, int v, int w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, int w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void cycleLink(int u, int v) {\n\t\tcntn++;\n\t\tcycleSum[cntn] = fromWeight[u];\n\t\taddEdge2(u, cntn, 0);\n\t\tint tmp = stasiz;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[tmp--];\n\t\t\tcycleLen[pop] = cycleSum[cntn];\n\t\t\tcycleSum[cntn] += fromWeight[pop];\n\t\t} while (pop != v);\n\t\tdo {\n\t\t\tpop = sta[stasiz--];\n\t\t\taddEdge2(cntn, pop, Math.min(cycleLen[pop], cycleSum[cntn] - cycleLen[pop]));\n\t\t} while (pop != v);\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++stasiz] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to1[e];\n\t\t\tint w = weight1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tfromWeight[v] = w;\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\tstasiz--;\n\t\t\t\t\taddEdge2(u, v, w);\n\t\t\t\t} else {\n\t\t\t\t\tcycleLink(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tfromWeight[v] = w;\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f, int l) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tlen[u] = l;\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\t// 因为是单向边，所以不用判断 v != f，但这里保留模版写法\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, len[u] + weight2[e]);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], t);\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\t// 因为是单向边，所以不用判断 v != fa[u]，但这里保留模版写法\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int find(int x, int square) {\n\t\tint pre = 0;\n\t\twhile (top[x] != top[square]) {\n\t\t\tpre = top[x];\n\t\t\tx = fa[pre];\n\t\t}\n\t\treturn x == square ? pre : son[square];\n\t}\n\n\tpublic static int query(int x, int y) {\n\t\tint ans = 0;\n\t\tint xylca = lca(x, y);\n\t\tif (xylca <= n) {\n\t\t\tans = len[x] + len[y] - (len[xylca] << 1);\n\t\t} else {\n\t\t\tint fx = find(x, xylca);\n\t\t\tint fy = find(y, xylca);\n\t\t\tans = len[x] + len[y] - len[fx] - len[fy];\n\t\t\tint small = Math.min(cycleLen[fx], cycleLen[fy]);\n\t\t\tint big = Math.max(cycleLen[fx], cycleLen[fy]);\n\t\t\tans += Math.min(big - small, cycleSum[xylca] - (big - small));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tfor (int i = 1, u, v, w; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge1(u, v, w);\n\t\t\taddEdge1(v, u, w);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i, 0);\n\t\t\t}\n\t\t}\n\t\tdfs1(1, 0, 0);\n\t\tdfs2(1, 1);\n\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tout.println(query(x, y));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code06_CactusShortestPaths2.java`\n\n```java\npackage class200;\n\n// 仙人掌最短路，C++版\n// 给定n个点、m条边的仙人掌图，每条边有边权，没有自环，没有重边\n// 一共q条查询，每条查询格式为 x y，查询点x和点y之间的最短路距离\n// 1 <= n、q <= 10^4\n// 1 <= m <= 2 * 10^4\n// 1 <= 边权 <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5236\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 50001;\n//int n, m, q, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXN];\n//int to1[MAXN];\n/