   for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i, 0);\n//        }\n//    }\n//    dfs1(1, 0, 0);\n//    dfs2(1, 1);\n//    for (int i = 1, x, y; i <= q; i++) {\n//        cin >> x >> y;\n//        cout << query(x, y) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code07_MaximumOfShortestPath1.java`\n\n```java\npackage class200;\n\n// 最短路最大值，java版\n// 给定n个点、m条边的仙人掌图，每条边有边权，没有自环，可能有重边\n// 一共q条查询，格式 k a1 a2 .. ak 含义如下\n// 给定的k个点中，任意选两个点，可以选择相同点\n// 打印它们之间最短路的最大值是多少\n// 1 <= n、查询中k的总和 <= 3 * 10^5\n// 测试链接 : https://uoj.ac/problem/87\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_MaximumOfShortestPath1 {\n\n\tpublic static int MAXN = 600001;\n\tpublic static int n, m, q, k, cntn;\n\n\t// 原图\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int[] weight1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\t// 圆方树\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN];\n\tpublic static int[] to2 = new int[MAXN];\n\tpublic static long[] weight2 = new long[MAXN];\n\tpublic static int cnt2;\n\n\t// 虚树\n\tpublic static int[] head3 = new int[MAXN];\n\tpublic static int[] next3 = new int[MAXN];\n\tpublic static int[] to3 = new int[MAXN];\n\tpublic static int cnt3;\n\n\t// dfn数组，tarjan和树剖都要使用\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int stasiz;\n\n\t// 环的信息\n\tpublic static long[] fromWeight = new long[MAXN];\n\tpublic static long[] cycleLen = new long[MAXN];\n\tpublic static long[] cycleSum = new long[MAXN];\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static long[] len = new long[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\t// 批量节点\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] tmp = new int[MAXN];\n\n\t// dist[u] : 以u为头的树，u到任意点的最短路距离的最大值\n\tpublic static long[] dist = new long[MAXN];\n\tpublic static long diameter;\n\n\t// 单调队列\n\tpublic static int[] idx = new int[MAXN];\n\tpublic static long[] pre = new long[MAXN];\n\tpublic static long[] val = new long[MAXN];\n\tpublic static int[] que = new int[MAXN];\n\n\tpublic static void addEdge1(int u, int v, int w) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\tweight1[cnt1] = w;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v, long w) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\tweight2[cnt2] = w;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void addEdge3(int u, int v) {\n\t\tnext3[++cnt3] = head3[u];\n\t\tto3[cnt3] = v;\n\t\thead3[u] = cnt3;\n\t}\n\n\tpublic static void sortByDfn(int[] nums, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r;\n\t\tint pivot = nums[(l + r) >> 1];\n\t\twhile (i <= j) {\n\t\t\twhile (dfn[nums[i]] < dfn[pivot]) i++;\n\t\t\twhile (dfn[nums[j]] > dfn[pivot]) j--;\n\t\t\tif (i <= j) {\n\t\t\t\tint tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsortByDfn(nums, l, j);\n\t\tsortByDfn(nums, i, r);\n\t}\n\n\tpublic static void sortByLen(int[] nums, int l, int r) {\n\t\tif (l >= r) return;\n\t\tint i = l, j = r;\n\t\tint pivot = nums[(l + r) >> 1];\n\t\twhile (i <= j) {\n\t\t\twhile (cycleLen[nums[i]] < cycleLen[pivot]) i++;\n\t\t\twhile (cycleLen[nums[j]] > cycleLen[pivot]) j--;\n\t\t\tif (i <= j) {\n\t\t\t\tint tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;\n\t\t\t\ti++; j--;\n\t\t\t}\n\t\t}\n\t\tsortByLen(nums, l, j);\n\t\tsortByLen(nums, i, r);\n\t}\n\n\tpublic static void cycleLink(int u, int v) {\n\t\tcntn++;\n\t\tcycleSum[cntn] = fromWeight[u];\n\t\taddEdge2(u, cntn, 0);\n\t\tint tmp = stasiz;\n\t\tint pop;\n\t\tdo {\n\t\t\tpop = sta[tmp--];\n\t\t\tcycleLen[pop] = cycleSum[cntn];\n\t\t\tcycleSum[cntn] += fromWeight[pop];\n\t\t} while (pop != v);\n\t\tdo {\n\t\t\tpop = sta[stasiz--];\n\t\t\taddEdge2(cntn, pop, Math.min(cycleLen[pop], cycleSum[cntn] - cycleLen[pop]));\n\t\t} while (pop != v);\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++stasiz] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to1[e];\n\t\t\tlong w = weight1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tfromWeight[v] = w;\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\tstasiz--;\n\t\t\t\t\taddEdge2(u, v, w);\n\t\t\t\t} else {\n\t\t\t\t\tcycleLink(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tfromWeight[v] = w;\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f, long l) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tlen[u] = l;\n\t\tfor (int e = head2[u], v; e > 0; e = next2[e]) {\n\t\t\tv = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u, len[u] + weight2[e]);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], t);\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static int find(int x, int square) {\n\t\tint pre = 0;\n\t\twhile (top[x] != top[square]) {\n\t\t\tpre = top[x];\n\t\t\tx = fa[pre];\n\t\t}\n\t\treturn x == square ? pre : son[square];\n\t}\n\n\t// 虚树的建立方式，二次排序 + 相邻LCA连边\n\tpublic static int buildVirtualTree() {\n\t\tsortByDfn(arr, 1, k);\n\t\tint len = 0;\n\t\tfor (int i = 1; i < k; i++) {\n\t\t\ttmp[++len] = arr[i];\n\t\t\ttmp[++len] = lca(arr[i], arr[i + 1]);\n\t\t}\n\t\ttmp[++len] = arr[k];\n\t\tsortByDfn(tmp, 1, len);\n\t\tint unique = 1;\n\t\tfor (int i = 2; i <= len; i++) {\n\t\t\tif (tmp[unique] != tmp[i]) {\n\t\t\t\ttmp[++unique] = tmp[i];\n\t\t\t}\n\t\t}\n\t\tcnt3 = 0;\n\t\tfor (int i = 1; i <= unique; i++) {\n\t\t\thead3[tmp[i]] = 0;\n\t\t}\n\t\tfor (int i = 1; i < unique; i++) {\n\t\t\taddEdge3(lca(tmp[i], tmp[i + 1]), tmp[i + 1]);\n\t\t}\n\t\treturn tmp[1];\n\t}\n\n\tpublic static void computeOnCycle(int u, int siz) {\n\t\tsortByLen(idx, 1, siz);\n\t\tfor (int i = 1; i <= siz; i++) {\n\t\t\tpre[i] = cycleLen[idx[i]];\n\t\t\tpre[i + siz] = pre[i] + cycleSum[u];\n\t\t\tval[i] = dist[idx[i]];\n\t\t\tval[i + siz] = val[i];\n\t\t}\n\t\tint l = 1;\n\t\tint r = 0;\n\t\tfor (int i = 1; i <= siz * 2; i++) {\n\t\t\twhile (l <= r && (pre[i] - pre[que[l]]) * 2 > cycleSum[u]) {\n\t\t\t\tl++;\n\t\t\t}\n\t\t\tif (l <= r) {\n\t\t\t\tdiameter = Math.max(diameter, val[que[l]] - pre[que[l]] + val[i] + pre[i]);\n\t\t\t}\n\t\t\twhile (l <= r && val[que[r]] - pre[que[r]] <= val[i] - pre[i]) {\n\t\t\t\tr--;\n\t\t\t}\n\t\t\tque[++r] = i;\n\t\t}\n\t}\n\n\tpublic static void dpOnTree(int u) {\n\t\tdist[u] = 0;\n\t\tif (u <= n) {\n\t\t\tfor (int e = head3[u]; e > 0; e = next3[e]) {\n\t\t\t\tint v = to3[e];\n\t\t\t\tdpOnTree(v);\n\t\t\t\tdiameter = Math.max(diameter, dist[u] + dist[v] + len[v] - len[u]);\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + len[v] - len[u]);\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int e = head3[u]; e > 0; e = next3[e]) {\n\t\t\t\tint v = to3[e];\n\t\t\t\tdpOnTree(v);\n\t\t\t}\n\t\t\t// 注意，下面的for循环，不能和上面的for循环合并处理\n\t\t\t// 因为idx是全局数组，此时u是方点，会收集环上的相关节点\n\t\t\t// 如果边递归边收集idx，那么当前已经写入的idx[1..siz]\n\t\t\t// 可能会被孩子的递归过程覆盖掉，导致idx收集脏数据\n\t\t\t// 所以先执行所有孩子的递归，再收集环上节点\n\t\t\tint siz = 0;\n\t\t\tfor (int e = head3[u]; e > 0; e = next3[e]) {\n\t\t\t\tint v = to3[e];\n\t\t\t\tint f = find(v, u);\n\t\t\t\tdist[f] = dist[v] + len[v] - len[f];\n\t\t\t\tidx[++siz] = f;\n\t\t\t\tdist[u] = Math.max(dist[u], dist[v] + len[v] - len[u]);\n\t\t\t}\n\t\t\tcomputeOnCycle(u, siz);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tfor (int i = 1, u, v, w; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge1(u, v, w);\n\t\t\taddEdge1(v, u, w);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tcntd = 0;\n\t\tdfs1(1, 0, 0);\n\t\tdfs2(1, 1);\n\t\tq = in.nextInt();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tk = in.nextInt();\n\t\t\tfor (int j = 1; j <= k; j++) {\n\t\t\t\tarr[j] = in.nextInt();\n\t\t\t}\n\t\t\tdiameter = 0;\n\t\t\tint tree = buildVirtualTree();\n\t\t\tdpOnTree(tree);\n\t\t\tout.println(diameter);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code07_MaximumOfShortestPath2.java`\n\n```java\npackage class200;\n\n// 最短路最大值，C++版\n// 给定n个点、m条边的仙人掌图，每条边有边权，没有自环，可能有重边\n// 一共q条查询，格式 k a1 a2 .. ak 含义如下\n// 给定的k个点中，任意选两个点，可以选择相同点\n// 打印它们之间最短路的最大值是多少\n// 1 <= n、查询中k的总和 <= 3 * 10^5\n// 测试链接 : https://uoj.ac/problem/87\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//using ll = long long;\n//\n//const int MAXN = 600001;\n//int n, m, q, k, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXN << 1];\n//int to1[MAXN << 1];\n//int weight1[MAXN << 1];\n//int cnt1;\n//\n//int head2[MAXN];\n//int next2[MAXN];\n//int to2[MAXN];\n//ll weight2[MAXN];\n//int cnt2;\n//\n//int head3[MAXN];\n//int next3[MAXN];\n//int to3[MAXN];\n//int cnt3;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int stasiz;\n//\n//ll fromWeight[MAXN];\n//ll cycleLen[MAXN];\n//ll cycleSum[MAXN];\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//ll len[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//\n//int arr[MAXN];\n//int tmp[MAXN];\n//\n//ll dist[MAXN];\n//ll diameter;\n//\n//int idx[MAXN];\n//ll pre[MAXN];\n//ll val[MAXN];\n//int que[MAXN];\n//\n//void addEdge1(int u, int v, int w) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    weight1[cnt1] = w;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v, ll w) {\n//    next2[++cnt2] = head2[u];\n//    to2[cnt2] = v;\n//    weight2[cnt2] = w;\n//    head2[u] = cnt2;\n//}\n//\n//void addEdge3(int u, int v) {\n//    next3[++cnt3] = head3[u];\n//    to3[cnt3] = v;\n//    head3[u] = cnt3;\n//}\n//\n//void cycleLink(int u, int v) {\n//    cntn++;\n//    cycleSum[cntn] = fromWeight[u];\n//    addEdge2(u, cntn, 0);\n//    int tmp = stasiz;\n//    int pop;\n//    do {\n//  