   if (u <= n) {\n//        for (int e = head3[u]; e > 0; e = next3[e]) {\n//            int v = to3[e];\n//            dpOnTree(v);\n//            diameter = max(diameter, dist[u] + dist[v] + len[v] - len[u]);\n//            dist[u] = max(dist[u], dist[v] + len[v] - len[u]);\n//        }\n//    } else {\n//        for (int e = head3[u]; e > 0; e = next3[e]) {\n//            int v = to3[e];\n//            dpOnTree(v);\n//        }\n//        int siz = 0;\n//        for (int e = head3[u]; e > 0; e = next3[e]) {\n//            int v = to3[e];\n//            int f = find(v, u);\n//            dist[f] = dist[v] + len[v] - len[f];\n//            idx[++siz] = f;\n//            dist[u] = max(dist[u], dist[v] + len[v] - len[u]);\n//        }\n//        computeOnCycle(u, siz);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    cntn = n;\n//    cnt1 = 1;\n//    for (int i = 1, u, v, w; i <= m; i++) {\n//        cin >> u >> v >> w;\n//        addEdge1(u, v, w);\n//        addEdge1(v, u, w);\n//    }\n//    tarjan(1, 0);\n//    cntd = 0;\n//    dfs1(1, 0, 0);\n//    dfs2(1, 1);\n//    cin >> q;\n//    for (int i = 1; i <= q; i++) {\n//        cin >> k;\n//        for (int j = 1; j <= k; j++) {\n//            cin >> arr[j];\n//        }\n//        diameter = 0;\n//        int tree = buildVirtualTree();\n//        dpOnTree(tree);\n//        cout << diameter << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code08_CactusPathFlip1.java`\n\n```java\npackage class200;\n\n// 仙人掌路径翻转，java版\n// 给定n个点、m条边的仙人掌图，没有自环，没有重边，1号节点是仙人掌的根\n// 输入保证每个简单环的边数都为奇数，所以点x到根的最短路和最长路都是唯一的\n// 以点x为头的子仙人掌，是指删掉根到x路径上的边后，包含x的连通块\n// 每个节点只有黑白两种颜色，初始时所有节点为黑，一共有q条操作，类型如下\n// 操作 1 x : 点x到根的最短路上所有节点，颜色翻转\n// 操作 2 x : 点x到根的最长路上所有节点，颜色翻转\n// 操作 3 x : 查询以点x为头的子仙人掌中，黑色节点的数量\n// 1 <= n、m、q <= 5 * 10^4\n// 测试链接 : https://uoj.ac/problem/158\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_CactusPathFlip1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m, q, cntn;\n\n\t// 原图\n\tpublic static int[] head1 = new int[MAXN];\n\tpublic static int[] next1 = new int[MAXN << 1];\n\tpublic static int[] to1 = new int[MAXN << 1];\n\tpublic static int cnt1;\n\n\t// 圆方树\n\tpublic static int[] head2 = new int[MAXN];\n\tpublic static int[] next2 = new int[MAXN];\n\tpublic static int[] to2 = new int[MAXN];\n\tpublic static int cnt2;\n\n\t// tarjan算法\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int stasiz;\n\n\t// 树链剖分\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\t// 仙人掌中，一个节点可能是多个环的环顶，但不做环顶的话，最多参与一个环\n\t// belongCycle[x]，表示节点x归属的环，x不是环顶节点\n\tpublic static int[] belongCycle = new int[MAXN];\n\t// 环顶节点，只对方点有意义\n\tpublic static int[] cycleRoot = new int[MAXN];\n\n\t// 圆点在环中的位置\n\tpublic static int[] pos = new int[MAXN];\n\t// 环的边数\n\tpublic static int[] cycleSum = new int[MAXN];\n\n\t// 除了环顶和重儿子之外，环中圆点的dfn编号范围，只对方点有意义\n\tpublic static int[] cyclel = new int[MAXN];\n\tpublic static int[] cycler = new int[MAXN];\n\n\t// 子树上，所有后代节点的dfn编号范围，只对圆点有意义\n\tpublic static int[] treel = new int[MAXN];\n\tpublic static int[] treer = new int[MAXN];\n\n\t// dfnType[x] = 0，dfn序号为x的节点是方点\n\t// dfnType[x] = 1，dfn序号为x的节点是圆点，位于环顶到环中重儿子的短路径侧\n\t// dfnType[x] = 2，dfn序号为x的节点是圆点，位于环顶到环中重儿子的长路径侧\n\t// dfnType[x] = 3，dfn序号为x的节点是圆点，如果不是1或2类型，那就是3类型，表示必经点\n\t// 必经点的情况比较多，可能是环中重儿子 或者 只做环顶 或者 不参与任何环\n\t// 总之无论短路径还是长路径，通过重链向上必经的点，就算3类型\n\tpublic static int[] dfnType = new int[MAXN];\n\n\t// 短路径线段树\n\tpublic static int[] all1 = new int[MAXN << 2];\n\tpublic static int[] black1 = new int[MAXN << 2];\n\tpublic static boolean[] lazy1 = new boolean[MAXN << 2];\n\n\t// 长路径线段树\n\tpublic static int[] all2 = new int[MAXN << 2];\n\tpublic static int[] black2 = new int[MAXN << 2];\n\tpublic static boolean[] lazy2 = new boolean[MAXN << 2];\n\n\t// 必经点线段树\n\tpublic static int[] all3 = new int[MAXN << 2];\n\tpublic static int[] black3 = new int[MAXN << 2];\n\tpublic static boolean[] lazy3 = new boolean[MAXN << 2];\n\n\tpublic static void addEdge1(int u, int v) {\n\t\tnext1[++cnt1] = head1[u];\n\t\tto1[cnt1] = v;\n\t\thead1[u] = cnt1;\n\t}\n\n\tpublic static void addEdge2(int u, int v) {\n\t\tnext2[++cnt2] = head2[u];\n\t\tto2[cnt2] = v;\n\t\thead2[u] = cnt2;\n\t}\n\n\tpublic static void cycleLink(int u, int v) {\n\t\tcntn++;\n\t\tcycleRoot[cntn] = u;\n\t\taddEdge2(u, cntn);\n\t\tint tmp = stasiz;\n\t\tint pop;\n\t\tint cnt = 0;\n\t\tdo {\n\t\t\tpop = sta[tmp--];\n\t\t\tcnt++;\n\t\t} while (pop != v);\n\t\tcycleSum[cntn] = cnt + 1;\n\t\tdo {\n\t\t\tpop = sta[stasiz--];\n\t\t\tbelongCycle[pop] = cntn;\n\t\t\tpos[pop] = cnt--;\n\t\t\taddEdge2(cntn, pop);\n\t\t} while (pop != v);\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++stasiz] = u;\n\t\tfor (int e = head1[u]; e > 0; e = next1[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to1[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tif (low[v] < dfn[u]) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else if (low[v] > dfn[u]) {\n\t\t\t\t\tstasiz--;\n\t\t\t\t\taddEdge2(u, v);\n\t\t\t\t} else {\n\t\t\t\t\tcycleLink(u, v);\n\t\t\t\t}\n\t\t\t} else if (dfn[v] < dfn[u]) {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void cycleDfn(int u) {\n\t\tint h = son[u];\n\t\tboolean near = pos[h] * 2 < cycleSum[u];\n\t\tcyclel[u] = cntd + 1;\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa[u] && v != h) {\n\t\t\t\tdfn[v] = ++cntd;\n\t\t\t\tif ((near && pos[v] < pos[h]) || (!near && pos[v] > pos[h])) {\n\t\t\t\t\tdfnType[cntd] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tdfnType[cntd] = 2;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tcycler[u] = cntd;\n\t\tdfn[h] = ++cntd;\n\t}\n\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (dfn[u] == 0) {\n\t\t\tdfn[u] = ++cntd;\n\t\t}\n\t\tif (u > n) {\n\t\t\tcycleDfn(u);\n\t\t}\n\t\tif (u <= n) {\n\t\t\ttreel[u] = cntd + 1;\n\t\t}\n\t\tif (son[u] != 0) {\n\t\t\tdfs2(son[u], t);\n\t\t}\n\t\tfor (int e = head2[u]; e > 0; e = next2[e]) {\n\t\t\tint v = to2[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t\tif (u <= n) {\n\t\t\ttreer[u] = cntd;\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tall1[i] = all1[i << 1] + all1[i << 1 | 1];\n\t\tall2[i] = all2[i << 1] + all2[i << 1 | 1];\n\t\tall3[i] = all3[i << 1] + all3[i << 1 | 1];\n\t\tblack1[i] = black1[i << 1] + black1[i << 1 | 1];\n\t\tblack2[i] = black2[i << 1] + black2[i << 1 | 1];\n\t\tblack3[i] = black3[i << 1] + black3[i << 1 | 1];\n\t}\n\n\tpublic static void reverse1(int i) {\n\t\tblack1[i] = all1[i] - black1[i];\n\t\tlazy1[i] = !lazy1[i];\n\t}\n\n\tpublic static void reverse2(int i) {\n\t\tblack2[i] = all2[i] - black2[i];\n\t\tlazy2[i] = !lazy2[i];\n\t}\n\n\tpublic static void reverse3(int i) {\n\t\tblack3[i] = all3[i] - black3[i];\n\t\tlazy3[i] = !lazy3[i];\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (lazy1[i]) {\n\t\t\treverse1(i << 1);\n\t\t\treverse1(i << 1 | 1);\n\t\t\tlazy1[i] = false;\n\t\t}\n\t\tif (lazy2[i]) {\n\t\t\treverse2(i << 1);\n\t\t\treverse2(i << 1 | 1);\n\t\t\tlazy2[i] = false;\n\t\t}\n\t\tif (lazy3[i]) {\n\t\t\treverse3(i << 1);\n\t\t\treverse3(i << 1 | 1);\n\t\t\tlazy3[i] = false;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tif (dfnType[l] == 1) {\n\t\t\t\tall1[i] = black1[i] = 1;\n\t\t\t}\n\t\t\tif (dfnType[l] == 2) {\n\t\t\t\tall2[i] = black2[i] = 1;\n\t\t\t}\n\t\t\tif (dfnType[l] == 3) {\n\t\t\t\tall3[i] = black3[i] = 1;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void reverse(int jobl, int jobr, int jobt, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tif (jobt == 1 || jobt == 3) {\n\t\t\t\treverse1(i);\n\t\t\t}\n\t\t\tif (jobt == 2 || jobt == 3) {\n\t\t\t\treverse2(i);\n\t\t\t}\n\t\t\treverse3(i);\n\t\t\treturn;\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tif (jobl <= mid) {\n\t\t\treverse(jobl, jobr, jobt, l, mid, i << 1);\n\t\t}\n\t\tif (mid < jobr) {\n\t\t\treverse(jobl, jobr, jobt, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\tup(i);\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl > jobr) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn black1[i] + black2[i] + black3[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) >> 1;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (mid < jobr) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void flipCycle(int u, int x, int op) {\n\t\tint h = son[u];\n\t\tboolean near = pos[x] * 2 < cycleSum[u];\n\t\tif ((near && op == 1) || (!near && op == 2)) {\n\t\t\treverse(cyclel[u], dfn[x], 3, 1, cntn, 1);\n\t\t\tif (pos[h] < pos[x]) {\n\t\t\t\treverse(dfn[h], dfn[h], 3, 1, cntn, 1);\n\t\t\t}\n\t\t} else {\n\t\t\treverse(dfn[x], cycler[u], 3, 1, cntn, 1);\n\t\t\tif (pos[h] > pos[x]) {\n\t\t\t\treverse(dfn[h], dfn[h], 3, 1, cntn, 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void flip(int x, int op) {\n\t\twhile (x != 0) {\n\t\t\tint xtop = top[x];\n\t\t\tif (xtop > n || belongCycle[xtop] == 0) {\n\t\t\t\treverse(dfn[xtop], dfn[x], op, 1, cntn, 1);\n\t\t\t\tx = fa[xtop];\n\t\t\t} else {\n\t\t\t\tif (x != xtop) {\n\t\t\t\t\treverse(dfn[son[xtop]], dfn[x], op, 1, cntn, 1);\n\t\t\t\t\tx = xtop;\n\t\t\t\t}\n\t\t\t\tflipCycle(belongCycle[x], x, op);\n\t\t\t\tx = cycleRoot[belongCycle[x]];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void prepare() {\n\t\ttarjan(1, 0);\n\t\tcntd = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdfn[i] = 0;\n\t\t}\n\t\tdfs1(1, 0);\n\t\tdfs2(1, 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfnType[dfn[i]] == 0) {\n\t\t\t\tdfnType[dfn[i]] = 3;\n\t\t\t}\n\t\t}\n\t\tbuild(1, cntn, 1);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tcntn = n;\n\t\tcnt1 = 1;\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge1(u, v);\n\t\t\taddEdge1(v, u);\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, op, x; i <= q; i++) {\n\t\t\top = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tif (op == 1 || op == 2) {\n\t\t\t\tflip(x, op);\n\t\t\t} else {\n\t\t\t\tint ans = query(dfn[x], dfn[x], 1, cntn, 1);\n\t\t\t\tans += query(treel[x], treer[x], 1, cntn, 1);\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code08_CactusPathFlip2.java`\n\n```java\npackage class200;\n\n// 仙人掌路径翻转，C++版\n// 给定n个点、m条边的仙人掌图，没有自环，没有重边，1号节点是仙人掌的根\n// 输入保证每个简单环的边数都为奇数，所以点x到根的最短路和最长路都是唯一的\n// 以点x为头的子仙人掌，是指删掉根到x路径上的边后，包含x的连通块\n// 每个节点只有黑白两种颜色，初始时所有节点为黑，一共有q条操作，类型如下\n// 操作 1 x : 点x到根的最短路上所有节点，颜色翻转\n// 操作 2 x : 点x到根的最长路上所有节点，颜色翻转\n// 操作 3 x : 查询以点x为头的子仙人掌中，黑色节点的数量\n// 1 <= n、m、q <= 5 * 10^4\n// 测试链接 : https://uoj.ac/problem/158\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m, q, cntn;\n//\n//int head1[MAXN];\n//int next1[MAXN << 1];\n//int to1[MAXN << 1];\n//int cnt1;\n//\n//int head2[MAXN];\n//int next2[MAXN];\n//int to2[MAXN];\n//int cnt2;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//int sta[MAXN];\n//int stasiz;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//\n//int belongCycle[MAXN];\n//int cycleRoot[MAXN];\n//\n//int pos[MAXN];\n//int cycleSum[MAXN];\n//\n//int cyclel[MAXN];\n//int cycler[MAXN];\n//\n//int treel[MAXN];\n//int treer[MAXN];\n//\n//int dfnType[MAXN];\n//\n//int all1[MAXN << 2];\n//int black1[MAXN << 2];\n//bool lazy1[MAXN << 2];\n//\n//int all2[MAXN << 2];\n//int black2[MAXN << 2];\n//bool lazy2[MAXN << 2];\n//\n//int all3[MAXN << 2];\n//int black3[MAXN << 2];\n//bool lazy3[MAXN << 2];\n//\n//void addEdge1(int u, int v) {\n//    next1[++cnt1] = head1[u];\n//    to1[cnt1] = v;\n//    head1[u] = cnt1;\n//}\n//\n//void addEdge2(int u, int v) {\n//