    cin >> op;\n//        rootfa[v] = rootfa[v - 1];\n//        rootsiz[v] = rootsiz[v - 1];\n//        if (op == 1) {\n//            cin >> x >> y;\n//            Union(x, y, v);\n//        } else if (op == 2) {\n//            cin >> x;\n//            rootfa[v] = rootfa[x];\n//            rootsiz[v] = rootsiz[x];\n//        } else {\n//            cin >> x >> y;\n//            if (find(x, v) == find(y, v)) {\n//                cout << 1 << "\\n";\n//            } else {\n//                cout << 0 << "\\n";\n//            }\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_UndoUnionFind1.java`\n\n```java\npackage class165;\n\n// 可撤销并查集模版题，java版\n// 一共有n个点，每个点有两个小球，每个点给定两个小球的编号\n// 一共有n-1条无向边，所有节点连成一棵树\n// 对i号点，2 <= i <= n，都计算如下问题的答案并打印\n// 从1号点到i号点的最短路径上，每个点只能拿一个小球，最多能拿几个编号不同的小球\n// 1 <= n <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc302_h\n// 测试链接 : https://atcoder.jp/contests/abc302/tasks/abc302_h\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_UndoUnionFind1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt;\n\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] edgeCnt = new int[MAXN];\n\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize = 0;\n\n\tpublic static int[] ans = new int[MAXN];\n\tpublic static int ball = 0;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\tedgeCnt[fx] += edgeCnt[fy] + 1;\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t\tedgeCnt[fx] -= edgeCnt[fy] + 1;\n\t}\n\n\tpublic static void dfs(int u, int fa) {\n\t\tint fx = find(arr[u][0]);\n\t\tint fy = find(arr[u][1]);\n\t\tboolean added = false;\n\t\tboolean unioned = false;\n\t\tif (fx == fy) {\n\t\t\tif (edgeCnt[fx] < siz[fx]) {\n\t\t\t\tball++;\n\t\t\t\tadded = true;\n\t\t\t}\n\t\t\tedgeCnt[fx]++;\n\t\t} else {\n\t\t\tif (edgeCnt[fx] < siz[fx] || edgeCnt[fy] < siz[fy]) {\n\t\t\t\tball++;\n\t\t\t\tadded = true;\n\t\t\t}\n\t\t\tunion(fx, fy);\n\t\t\tunioned = true;\n\t\t}\n\t\tans[u] = ball;\n\t\tfor (int e = head[u]; e > 0; e = next[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs(to[e], u);\n\t\t\t}\n\t\t}\n\t\tif (added) {\n\t\t\tball--;\n\t\t}\n\t\tif (unioned) {\n\t\t\tundo();\n\t\t} else {\n\t\t\tedgeCnt[fx]--;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tarr[i][1] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t\tedgeCnt[i] = 0;\n\t\t}\n\t\tdfs(1, 0);\n\t\tfor (int i = 2; i < n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println(ans[n]);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code02_UndoUnionFind2.java`\n\n```java\npackage class165;\n\n// 可撤销并查集模版题，C++版\n// 一共有n个点，每个点有两个小球，每个点给定两个小球的编号\n// 一共有n-1条无向边，所有节点连成一棵树\n// 对i号点，2 <= i <= n，都计算如下问题的答案并打印\n// 从1号点到i号点的最短路径上，每个点只能拿一个小球，最多能拿几个编号不同的小球\n// 1 <= n <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/AT_abc302_h\n// 测试链接 : https://atcoder.jp/contests/abc302/tasks/abc302_h\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//int arr[MAXN][2];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cnt;\n//\n//int father[MAXN];\n//int siz[MAXN];\n//int edgeCnt[MAXN];\n//\n//int rollback[MAXN][2];\n//int opsize = 0;\n//\n//int ans[MAXN];\n//int ball = 0;\n//\n//void addEdge(int u, int v) {\n//\tnxt[++cnt] = head[u];\n//\tto[cnt] = v;\n//    head[u] = cnt;\n//}\n//\n//int find(int i) {\n//\twhile(i != father[i]) {\n//\t\ti = father[i];\n//\t}\n//\treturn i;\n//}\n//\n//void Union(int x, int y) {\n//    int fx = find(x);\n//    int fy = find(y);\n//    if (siz[fx] < siz[fy]) {\n//        int tmp = fx;\n//        fx = fy;\n//        fy = tmp;\n//    }\n//    father[fy] = fx;\n//    siz[fx] += siz[fy];\n//    edgeCnt[fx] += edgeCnt[fy] + 1;\n//    rollback[++opsize][0] = fx;\n//    rollback[opsize][1] = fy;\n//}\n//\n//void undo() {\n//    int fx = rollback[opsize][0];\n//    int fy = rollback[opsize--][1];\n//    father[fy] = fy;\n//    siz[fx] -= siz[fy];\n//    edgeCnt[fx] -= edgeCnt[fy] + 1;\n//}\n//\n//void dfs(int u, int fa) {\n//    int fx = find(arr[u][0]);\n//    int fy = find(arr[u][1]);\n//    bool added = false;\n//    bool unioned = false;\n//    if (fx == fy) {\n//        if (edgeCnt[fx] < siz[fx]) {\n//            ball++;\n//            added = true;\n//        }\n//        edgeCnt[fx]++;\n//    } else {\n//        if (edgeCnt[fx] < siz[fx]|| edgeCnt[fy] < siz[fy]) {\n//            ball++;\n//            added = true;\n//        }\n//        Union(fx, fy);\n//        unioned = true;\n//    }\n//    ans[u] = ball;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if (to[e] != fa) {\n//            dfs(to[e], u);\n//        }\n//    }\n//    if (added) {\n//        ball--;\n//    }\n//    if (unioned) {\n//        undo();\n//    } else {\n//        edgeCnt[fx]--;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    int n;\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i][0] >> arr[i][1];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        father[i] = i;\n//        siz[i] = 1;\n//        edgeCnt[i] = 0;\n//    }\n//    dfs(1, 0);\n//    for (int i = 2; i < n; i++) {\n//        cout << ans[i] << " ";\n//    }\n//    cout << ans[n] << "\\n";\n//    return 0;\n//}\n```\n\n### `Code03_Envy1.java`\n\n```java\npackage class165;\n\n// 同在最小生成树里，java版\n// 一共有n个点，m条无向边，每条边有边权，图保证是连通的\n// 一共有q次查询，每条查询都给定参数k，表示该查询涉及k条边\n// 然后依次给出k条边的编号，打印这k条边能否同时出现在一颗最小生成树上\n// 1 <= n、m、q、所有查询涉及边的总量 <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF891C\n// 测试链接 : https://codeforces.com/problemset/problem/891/C\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code03_Envy1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m, q, k;\n\n\t// 节点u、节点v、边权w\n\tpublic static int[][] edge = new int[MAXN][3];\n\t// 节点u、节点v、边权w、问题编号i\n\tpublic static int[][] queries = new int[MAXN][4];\n\n\t// 可撤销并查集\n\tpublic static int[] father = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN << 1][2];\n\tpublic static int opsize;\n\n\t// 答案数组\n\tpublic static boolean[] ans = new boolean[MAXN];\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tArrays.sort(edge, 1, m + 1, (a, b) -> a[2] - b[2]);\n\t\tArrays.sort(queries, 1, k + 1, (a, b) -> a[2] != b[2] ? (a[2] - b[2]) : (a[3] - b[3]));\n\t\tArrays.fill(ans, 1, q + 1, true);\n\t}\n\n\tpublic static void compute() {\n\t\tint ei = 1, queryId, unionCnt;\n\t\tfor (int l = 1, r = 1; l <= k; l = ++r) {\n\t\t\twhile (r + 1 <= k && queries[l][2] == queries[r + 1][2] && queries[l][3] == queries[r + 1][3]) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\t// 添加小于当前边权的边，利用Kruskal算法增加连通性，ei是不回退的\n\t\t\tfor (; ei <= m && edge[ei][2] < queries[l][2]; ei++) {\n\t\t\t\tif (find(edge[ei][0]) != find(edge[ei][1])) {\n\t\t\t\t\tunion(edge[ei][0], edge[ei][1]);\n\t\t\t\t}\n\t\t\t}\n\t\t\tqueryId = queries[l][3];\n\t\t\tif (!ans[queryId]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tunionCnt = 0;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (find(queries[i][0]) == find(queries[i][1])) {\n\t\t\t\t\tans[queryId] = false;\n\t\t\t\t\tbreak;\n\t\t\t\t} else {\n\t\t\t\t\tunion(queries[i][0], queries[i][1]);\n\t\t\t\t\tunionCnt++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= unionCnt; i++) {\n\t\t\t\tundo();\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tedge[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tedge[i][1] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tedge[i][2] = (int) in.nval;\n\t\t}\n\t\tin.nextToken();\n\t\tq = (int) in.nval;\n\t\tk = 0;\n\t\tfor (int i = 1, s; i <= q; i++) {\n\t\t\tin.nextToken();\n\t\t\ts = (int) in.nval;\n\t\t\tfor (int j = 1, ei; j <= s; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tei = (int) in.nval;\n\t\t\t\tqueries[++k][0] = edge[ei][0];\n\t\t\t\tqueries[k][1] = edge[ei][1];\n\t\t\t\tqueries[k][2] = edge[ei][2];\n\t\t\t\tqueries[k][3] = i;\n\t\t\t}\n\t\t}\n\t\tprepare();\n\t\tcompute();\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\tif (ans[i]) {\n\t\t\t\tout.println("YES");\n\t\t\t} else {\n\t\t\t\tout.println("NO");\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_Envy2.java`\n\n```java\npackage class165;\n\n// 同在最小生成树里，C++版\n// 一共有n个点，m条无向边，每条边有边权，图保证是连通的\n// 一共有q次查询，每条查询都给定参数k，表示该查询涉及k条边\n// 然后依次给出k条边的编号，打印这k条边能否同时出现在一颗最小生成树上\n// 1 <= n、m、q、所有查询涉及边的总量 <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF891C\n// 测试链接 : https://codeforces.com/problemset/problem/891/C\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Edge {\n//    int u, v, w;\n//};\n//\n//bool EdgeCmp(Edge x, Edge y) {\n//    return x.w < y.w;\n//}\n//\n//struct Query {\n//    int u, v, w, i;\n//};\n//\n//bool QueryCmp(Query x, Query y) {\n//    if(x.w != y.w) {\n//        return x.w < y.w;\n//    } else {\n//        return x.i < y.i;\n//    }\n//}\n//\n//const int MAXN = 500001;\n//int n, m, q, k;\n//\n//Edge edge[MAXN];\n//Query queries[MAXN];\n//\n//int father[MAXN];\n//int siz[MAXN];\n//int rollback[MAXN << 1][2];\n//int opsize;\n//\n//bool ans[MAXN];\n//\n//int find(int i) {\n//    while (i != father[i]) {\n//        i = father[i];\n//    }\n//    return i;\n//}\n//\n//void Union(int x, int y) {\n//    int fx = find(x);\n//    int fy = find(y);\n//    if (siz[fx] < siz[fy]) {\n//        int tmp = fx;\n//        fx = fy;\n//        fy = tmp;\n//    }\n//    father[fy] = fx;\n//    siz[fx] += siz[fy];\n//    rollback[++opsize][0] = fx;\n//    rollback[opsize][1] = fy;\n//}\n//\n//void undo() {\n//    int fx = rollback[opsize][0];\n//    int fy = rollback[opsize--][1];\n//    father[fy] = fy;\n//    siz[fx] -= siz[fy];\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        father[i] = i;\n//        siz[i] = 1;\n//    }\n//    sort(edge + 1, edge + m + 1, EdgeCmp);\n//    sort(queries + 1, queries + k + 1, QueryCmp);\n//    for (int i = 1; i <= q; i++) {\n//        ans[i] = true;\n//    }\n//}\n//\n//void compute() {\n//    int ei = 1, queryId, unionCnt;\n//    for (int l = 1, r = 1; l <= k; l = ++r) {\n//        while (r + 1 <= k && queries[l].w == queries[r + 1].w && queries[l].i == queries[r + 1].i) {\n//            r++;\n//        }\n//        for (; ei <= m && edge[ei].w < queries[l].w; ei++) {\n//            if (find(edge[ei].u) != find(edge[ei].v)) {\n//                Union(edge[ei].u, edge[ei].v);\n//            }\n//        }\n//        queryId = queries[l].i;\n//        if (!ans[queryId]) {\n//            continue;\n//        }\n//        unionCnt = 0;\n//        for (int i = l; i <= r; i++) {\n//            if (find(queries[i].u) == find(queries[i].v)) {\n//                ans[queryId] = false;\n//                break;\n//            } else {\n//                Union(queries[i].u, queries[i].v);\n//                unionCnt++;\n//            }\n//        }\n//        for (int i = 1; i <= unionCnt; i++) {\n//            undo();\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> edge[i].u >> edge[i].v >> edge[i].w;\n//    }\n//    cin >> q;\n//    k = 0;\n//    for (int i = 1, s; i <= q; i++) {\n//        cin >> s;\n//        for (int j = 1, ei; j <= s; j++) {\n//            cin >> ei;\n//            queries[++k].u = edge[ei].u;\n//            queries[k].v = edge[ei].v;\n//            queries[k].w = edge[ei].w;\n//            queries[k].i = i;\n//        }\n//    }\n//    prepare();\n//    compute();\n//    for (int i = 1; i <= q; i++) {\n//        if (ans[i]) {\n//            cout << "YES" << "\\n";\n//        } else {\n//            cout << "NO" << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_TeamBuilding1.java`\n\n```java\npackage class165;\n\n// 团建，java版\n// 一共有n个人，每个人给定组号，一共有m条边，代表两人之间有矛盾\n// 一共有k个小组，可能有的组没人，但是组依然存在\n// 假设组a和组b，两个组的人一起去团建，组a和组b的所有人，可以重新打乱\n// 如果所有人最多分成两个集团，每人都要参加划分，并且每个集团的内部不存在矛盾\n// 那么组a和组b就叫做一个"合法组对"，注意，组b和组a就不用重复计算了\n// 一共有k个组，随意选两个组的情况很多，计算一共有多少个"合法组对"\n// 1 <= n、m、k <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1444C\n// 测试链接 : https://codeforces.com/problemset/problem/1444/C\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_TeamBuilding1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m, k;\n\n\t// 每个节点的组号\n\tpublic static int[] team = new int[MAXN];\n\t// 每条边有两个端点\n\tpublic static int[][] edge = new int[MAXN][2];\n\n\t// 两个端点为不同组的边，u、uteam、v、vteam\n\tpublic static int[][] crossEdge = new int[MAXN][4];\n\t// 两个端点为不同组的边的数量\n\tpublic static int cnt = 0;\n\n\t// conflict[i] = true，表示i号组自己去划分二分图，依然有冲突\n\t// conflict[i] = false，表示i号组自己去划分二分图，没有冲突\n\tpublic static boolean[] conflict = new boolean[MAXN];\n\n\t// 可撤销并查集\n\tpublic static int[] father = new int[MAXN << 1];\n\tpublic static int[] siz = new int[MAXN << 1];\n\tpublic static int[][] rollback = new int[MAXN << 1][2];\n\tpublic static int opsize;\n\n\tpublic static int find(int i) {\n\t\twhile (i != father[i]) {\n\t\t\ti = father[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (siz[fx] < siz[fy]) {\n\t\t\tint tmp = fx;\n\t\t\tfx = fy;\n\t\t\tfy = tmp;\n\t\t}\n\t\tfather[fy] = fx;\n\t\tsiz[fx] += siz[fy];\n\t\trollback[++opsize][0] = fx;\n\t\trollback[opsize][1] = fy;\n\t}\n\n\tpublic static void undo() {\n\t\tint fx = rollback[opsize][0];\n\t\tint fy = rollback[opsize--][1];\n\t\tfather[fy] = fy;\n\t\tsiz[fx] -= siz[fy];\n\t}\n\n\tpublic static void filter() {\n\t\tfor (int i = 1; i <= 2 * n; i++) {\n\t\t\tfather[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = edge[i][0];\n\t\t\tv = edge[i][1];\n\t\t\tif (team[u] < team[v]) {\n\t\t\t\tcrossEdge[++cnt][0] = u;\n\t\t\t\tcrossEdge[cnt][1] = team[u];\n\t\t\t\tcrossEdge[cnt][2] = v;\n\t\t\t\tcrossEdge[cnt][3] = team[v];\n\t\t\t} else if (team[u] > team[v]) {\n\t\t\t\tcrossEdge[++cnt][0] = v;\n\t\t\t\tcrossEdge[cnt][1] = team[v];\n\t\t\t\tcrossEdge[cnt][2] = u;\n\t\t\t\tcrossEdge[cnt][3] = team[u];\n\t\t\t} else {\n\t\t\t\tif (conflict[team[u]]) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (find(u) == find(v)) {\n\t\t\t\t\tk--;\n\t\t\t\t\tconflict[team[u]] = true;\n\t\t\t\t} else {\n\t\t\t\t\tunion(u, v + n);\n\t\t\t\t\tunion(v, u + n);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static long compute() {\n\t\tArrays.sort(crossEdge, 1, cnt + 1, (a, b) -> a[1] != b[1] ? (a[1] - b[1]) : (a[3] - b[3]));\n\t\tlong ans = (long) k * (k - 1) / 2;\n\t\tint u, uteam, v, vteam, unionCnt;\n\t\tfor (int l = 1, r = 1; l <= cnt; l = ++r) {\n\t\t\tuteam = crossEdge[l][1];\n\t\t\tvteam = crossEdge[l][3];\n\t\t\twhile (r + 1 <= cnt && crossEdge[r + 1][1] == uteam && crossEdge[r + 1][3] == vteam) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tif (conflict[uteam] || conflict[vteam]) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tunionCnt = 0;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tu = crossEdge[i][0];\n\t\t\t\tv = crossEdge[i][2];\n\t\t\t\tif (find(u) == find(v)) {\n\t\t\t\t\tans--;\n\t\t\t\t\tbreak;\n\t\t\t\t} else {\n\t\t\t\t\tunion(u, v + n);\n\t\t\t\t\tunion(v, u + n);\n\t\t\t\t\tunionCnt += 2;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= unionCnt; i++) {\n\t\t\t\tundo();\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tteam[i] = (int) in.nval;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tedge[i][0] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tedge[i][1] = (int) in.nval;\n\t\t}\n\t\tfilter();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_TeamBuilding2.java`\n\n```java\npackage class165;\n\n// 团建，C++版\n// 一共有n个人，每个人给定组号，一共有m条边，代表两人之间有矛盾\n// 一共有k个小组，可能有的组没人，但是组依然存在\n// 假设组a和组b，两个组的人一起去团建，组a和组b的所有人，可以重新打乱\n// 如果所有人最多分成两个集团，每人都要参加划分，并且每个集团的内部不存在矛盾\n// 那么组a和组b就叫做一个"合法组对"，注意，组b和组a就不用重复计算了\n// 一共有k个组，随意选两个组的情况很多，计算一共有多少个"合法组对"\n// 1 <= n、m、k <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF1444C\n// 测试链接 : https://codeforces.com/problemset/problem/1444/C\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n//