java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code01_LeftistTree3 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (num[i] > num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tn = in.readInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum[i] = in.readInt();\n\t\t}\n\t\tm = in.readInt();\n\t\tString op;\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\top = in.readString();\n\t\t\tif (op.equals("M")) {\n\t\t\t\tx = in.readInt();\n\t\t\t\ty = in.readInt();\n\t\t\t\tif (num[x] != -1 && num[y] != -1) {\n\t\t\t\t\tint l = find(x);\n\t\t\t\t\tint r = find(y);\n\t\t\t\t\tif (l != r) {\n\t\t\t\t\t\tmerge(l, r);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tx = in.readInt();\n\t\t\t\tif (num[x] == -1) {\n\t\t\t\t\tout.println(0);\n\t\t\t\t} else {\n\t\t\t\t\tint ans = find(x);\n\t\t\t\t\tout.println(num[ans]);\n\t\t\t\t\tpop(ans);\n\t\t\t\t\tnum[ans] = -1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic String readString() {\n\t\t\tchar cur;\n\t\t\tdo {\n\t\t\t\tcur = (char) readByte();\n\t\t\t} while (cur == ' ' || cur == '\\n');\n\t\t\tStringBuilder builder = new StringBuilder();\n\t\t\twhile (cur != ' ' && cur != '\\n') {\n\t\t\t\tbuilder.append(cur);\n\t\t\t\tcur = (char) readByte();\n\t\t\t}\n\t\t\treturn builder.toString();\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code01_LeftistTree4.java`\n\n```java\npackage class154;\n\n// 左偏树模版题2，数据量增强，C++版\n// 依次给定n个非负数字，表示有n个小根堆，每个堆只有一个数\n// 实现如下两种操作，操作一共调用m次\n// M x y : 第x个数字所在的堆和第y个数字所在的堆合并\n//         如果两个数字已经在一个堆或者某个数字已经删除，不进行合并\n// K x   : 打印第x个数字所在堆的最小值，并且在堆里删掉这个最小值\n//         如果第x个数字已经被删除，也就是找不到所在的堆，打印0\n//         若有多个最小值，优先删除编号小的\n// 1 <= n <= 10^6\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2713\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 1000001;\n//int n, m;\n//int num[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int dist[MAXN];\n//int fa[MAXN];\n//\n//void prepare() {\n//    dist[0] = -1;\n//    for(int i = 1; i <= n; i++) {\n//        ls[i] = rs[i] = dist[i] = 0;\n//        fa[i] = i;\n//    }\n//}\n//\n//int find(int i) {\n//    fa[i] = fa[i] == i ? i : find(fa[i]);\n//    return fa[i];\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) {\n//        return i + j;\n//    }\n//    if (num[i] > num[j] || (num[i] == num[j] && i > j)) {\n//        swap(i, j);\n//    }\n//    rs[i] = merge(rs[i], j);\n//    if (dist[ls[i]] < dist[rs[i]]) {\n//        swap(ls[i], rs[i]);\n//    }\n//    dist[i] = dist[rs[i]] + 1;\n//    fa[ls[i]] = fa[rs[i]] = i;\n//    return i;\n//}\n//\n//int pop(int i) {\n//    fa[ls[i]] = ls[i];\n//    fa[rs[i]] = rs[i];\n//    fa[i] = merge(ls[i], rs[i]);\n//    ls[i] = rs[i] = dist[i] = 0;\n//    return fa[i];\n//}\n//\n//int main() {\n//    ios_base::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    prepare();\n//    for (int i = 1; i <= n; i++) {\n//        cin >> num[i];\n//    }\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        string op; cin >> op;\n//        if (op == "M") {\n//            int x, y; cin >> x >> y;\n//            if (num[x] != -1 && num[y] != -1) {\n//                int l = find(x);\n//                int r = find(y);\n//                if (l != r) {\n//                    merge(l, r);\n//                }\n//            }\n//        } else {\n//            int x; cin >> x;\n//            if (num[x] == -1) {\n//                cout << 0 << endl;\n//            } else {\n//                int ans = find(x);\n//                cout << num[ans] << endl;\n//                pop(ans);\n//                num[ans] = -1;\n//            }\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_Convict1.java`\n\n```java\npackage class154;\n\n// 断罪者，删除任意编号节点，java版\n// 给定t，w，k，表示一共有t个人，死亡方式都为w，地狱阈值都为k，w和k含义稍后解释\n// 每个人都给定n和m，表示这人一生有n件错事，有m次领悟\n// 这个人的n件错事，给定对应的n个罪恶值，然后给定m次领悟，领悟类型如下\n// 2 a   : 第a件错事的罪恶值变成0\n// 3 a b : 第a件错事所在的集合中，最大罪恶值的错事，罪恶值减少b\n//         如果减少后罪恶值变成负数，认为这件错事的罪恶值变为0\n//         如果集合中，两件错事都是最大的罪恶值，取编号较小的错事\n// 4 a b : 第a件错事所在的集合与第b件错事所在的集合合并\n// 一个错事集合的罪恶值 = 这个集合中的最大罪恶值，只取一个\n// 一个人的罪恶值 = 这个人所有错事集合的罪恶值累加起来\n// 然后根据死亡方式w，对每个人的罪恶值做最后调整，然后打印这个人的下场\n// 如果w==1，不调整\n// 如果w==2，人的罪恶值 -= 错事集合的罪恶值中的最大值\n// 如果w==3，人的罪恶值 += 错事集合的罪恶值中的最大值\n// 如果一个人的罪恶值 == 0，打印"Gensokyo 0"\n// 如果一个人的罪恶值  > k，打印"Hell "，然后打印罪恶值\n// 如果一个人的罪恶值 <= k，打印"Heaven "，然后打印罪恶值\n// 一共有t个人，所以最终会有t次打印\n// 1 <= t <= 30\n// 1 <= n <= 2 * 10^6\n// 错事罪恶值可能很大，输入保证每个人的罪恶值用long类型不溢出\n// 测试链接 : https://www.luogu.com.cn/problem/P4971\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code02_Convict1 {\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int t, w, n, m;\n\n\tpublic static long k;\n\n\tpublic static long[] num = new long[MAXN];\n\n\t// up[i]表示节点i在左偏树结构上的父亲节点\n\tpublic static int[] up = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// father[i]表示并查集里节点i的路径信息\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆，如果值一样，编号小的节点做头\n\t\tif (num[i] < num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\t// 设置up信息\n\t\tup[right[i]] = i;\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\t// 节点i是所在左偏树的任意节点，删除节点i，返回整棵树的头节点编号\n\tpublic static int remove(int i) {\n\t\tint h = find(i);\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tint s = merge(left[i], right[i]);\n\t\tint f = up[i];\n\t\tfather[i] = s;\n\t\tup[s] = f;\n\t\tif (h != i) {\n\t\t\tfather[s] = h;\n\t\t\tif (left[f] == i) {\n\t\t\t\tleft[f] = s;\n\t\t\t} else {\n\t\t\t\tright[f] = s;\n\t\t\t}\n\t\t\tfor (int d = dist[s], tmp; dist[f] > d + 1; f = up[f], d++) {\n\t\t\t\tdist[f] = d + 1;\n\t\t\t\tif (dist[left[f]] < dist[right[f]]) {\n\t\t\t\t\ttmp = left[f]; left[f] = right[f]; right[f] = tmp;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup[i] = left[i] = right[i] = dist[i] = 0;\n\t\treturn father[s];\n\t}\n\n\tpublic static void reduce(int i, long v) {\n\t\tint h = remove(i);\n\t\tnum[i] = Math.max(num[i] - v, 0);\n\t\tfather[h] = father[i] = merge(h, i);\n\t}\n\n\tpublic static long compute() {\n\t\tlong ans = 0;\n\t\tlong max = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (father[i] == i) {\n\t\t\t\tans += num[i];\n\t\t\t\tmax = Math.max(max, num[i]);\n\t\t\t}\n\t\t}\n\t\tif (w == 2) {\n\t\t\tans -= max;\n\t\t} else if (w == 3) {\n\t\t\tans += max;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tt = in.readInt();\n\t\tw = in.readInt();\n\t\tk = in.readLong();\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tn = in.readInt();\n\t\t\tm = in.readInt();\n\t\t\tprepare();\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tnum[j] = in.readLong();\n\t\t\t}\n\t\t\tfor (int j = 1, op, a, b; j <= m; j++) {\n\t\t\t\top = in.readInt();\n\t\t\t\ta = in.readInt();\n\t\t\t\tif (op == 2) {\n\t\t\t\t\treduce(a, num[a]);\n\t\t\t\t} else if (op == 3) {\n\t\t\t\t\tb = in.readInt();\n\t\t\t\t\treduce(find(a), b);\n\t\t\t\t} else {\n\t\t\t\t\tb = in.readInt();\n\t\t\t\t\tint l = find(a);\n\t\t\t\t\tint r = find(b);\n\t\t\t\t\tif (l != r) {\n\t\t\t\t\t\tmerge(l, r);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tlong ans = compute();\n\t\t\tif (ans == 0) {\n\t\t\t\tout.write("Gensokyo ");\n\t\t\t} else if (ans > k) {\n\t\t\t\tout.write("Hell ");\n\t\t\t} else {\n\t\t\t\tout.write("Heaven ");\n\t\t\t}\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n```\n\n### `Code02_Convict2.java`\n\n```java\npackage class154;\n\n// 断罪者，删除任意编号节点，C++版\n// 给定t，w，k，表示一共有t个人，死亡方式都为w，地狱阈值都为k，w和k含义稍后解释\n// 每个人都给定n和m，表示这人一生有n件错事，有m次领悟\n// 这个人的n件错事，给定对应的n个罪恶值，然后给定m次领悟，领悟类型如下\n// 2 a   : 第a件错事的罪恶值变成0\n// 3 a b : 第a件错事所在的集合中，最大罪恶值的错事，罪恶值减少b\n//         如果减少后罪恶值变成负数，认为这件错事的罪恶值变为0\n//         如果集合中，两件错事都是最大的罪恶值，取编号较小的错事\n// 4 a b : 第a件错事所在的集合与第b件错事所在的集合合并\n// 一个错事集合的罪恶值 = 这个集合中的最大罪恶值，只取一个\n// 一个人的罪恶值 = 这个人所有错事集合的罪恶值累加起来\n// 然后根据死亡方式w，对每个人的罪恶值做最后调整，然后打印这个人的下场\n// 如果w==1，不调整\n// 如果w==2，人的罪恶值 -= 错事集合的罪恶值中的最大值\n// 如果w==3，人的罪恶值 += 错事集合的罪恶值中的最大值\n// 如果一个人的罪恶值 == 0，打印"Gensokyo 0"\n// 如果一个人的罪恶值  > k，打印"Hell "，然后打印罪恶值\n// 如果一个人的罪恶值 <= k，打印"Heaven "，然后打印罪恶值\n// 一共有t个人，所以最终会有t次打印\n// 1 <= t <= 30\n// 1 <= n <= 2 * 10^6\n// 错事罪恶值可能很大，输入保证每个人的罪恶值用long类型不溢出\n// 测试链接 : https://www.luogu.com.cn/problem/P4971\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 2000001;\n//int t, w, n, m;\n//long long k;\n//long long num[MAXN];\n//int up[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int dist[MAXN];\n//int fa[MAXN];\n//\n//void prepare() {\n//    dist[0] = -1;\n//    for (int i = 1; i <= n; i++) {\n//        up[i] = ls[i] = rs[i] = dist[i] = 0;\n//        fa[i] = i;\n//    }\n//}\n//\n//int find(int i) {\n//    return fa[i] == i ? i : (fa[i] = find(fa[i]));\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) {\n//        return i + j;\n//    }\n//    if (num[i] < num[j] || (num[i] == num[j] && i > j)) {\n//        swap(i, j);\n//    }\n//    rs[i] = merge(rs[i], j);\n//    up[rs[i]] = i;\n//    if (dist[ls[i]] < dist[rs[i]]) {\n//        swap(ls[i], rs[i]);\n//    }\n//    dist[i] = dist[rs[i]] + 1;\n//    fa[ls[i]] = fa[rs[i]] = i;\n//    return i;\n//}\n//\n//int remove(int i) {\n//    int h = find(i);\n//    fa[ls[i]] = ls[i];\n//    fa[rs[i]] = rs[i];\n//    int s = merge(ls[i], rs[i]);\n//    int f = up[i];\n//    fa[i] = s;\n//    up[s] = f;\n//    if (h != i) {\n//        fa[s] = h;\n//        if (ls[f] == i) {\n//            ls[f] = s;\n//        } else {\n//            rs[f] = s;\n//        }\n//        for (int d = dist[s]; dist[f] > d + 1; f = up[f], d++) {\n//            dist[f] = d + 1;\n//            if (dist[ls[f]] < dist[rs[f]]) {\n//                swap(ls[f], rs[f]);\n//            }\n//        }\n//    }\n//    up[i] = ls[i] = rs[i] = dist[i] = 0;\n//    return fa[s];\n//}\n//\n//void reduce(int i, long long v) {\n//    int h = remove(i);\n//    num[i] = max(num[i] - v, 0LL);\n//    fa[h] = fa[i] = merge(h, i);\n//}\n//\n//long long compute() {\n//    long long ans = 0;\n//    long long mx = 0;\n//    for (int i = 1; i <= n; i++) {\n//        if (fa[i] == i) {\n//            ans += num[i];\n//            if (num[i] > mx) mx = num[i];\n//        }\n//    }\n//    if (w == 2) {\n//        ans -= mx;\n//    } else if (w == 3) {\n//        ans += mx;\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(NULL);\n//    cin >> t >> w >> k;\n//    for(int i = 1; i <= t; i++) {\n//        cin >> n >> m;\n//        prepare();\n//        for (int j = 1; j <= n; j++) {\n//            cin >> num[j];\n//        }\n//        for (int j = 1, op, a, b; j <= m; j++) {\n//            cin >> op >> a;\n//            if (op == 2) {\n//                reduce(a, num[a]);\n//            } else if (op == 3) {\n//                cin >> b;\n//                reduce(find(a), b);\n//            } else {\n//                cin >> b;\n//                int l = find(a);\n//                int r = find(b);\n//                if (l != r) {\n//                    merge(l, r);\n//                }\n//            }\n//        }\n//        long long ans = compute();\n//        if (ans == 0) {\n//            cout << "Gensokyo " << ans << endl;\n//        } else if (ans > k) {\n//            cout << "Hell " << ans << endl;\n//        } else {\n//            cout << "Heaven " << ans << endl;\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_MonkeyKing1.java`\n\n```java\npackage class154;\n\n// 猴王，java版\n// 给定n只猴子的战斗力，一开始每个猴子都是独立的阵营\n// 一共有m次冲突，每次冲突给定两只猴子的编号x、y\n// 如果x和y在同一阵营，这次冲突停止，打印-1\n// 如果x和y在不同阵营，x所在阵营的最强猴子会和y所在阵营的最强猴子进行打斗\n// 打斗的结果是，两个各自阵营的最强猴子，战斗力都减半，向下取整，其他猴子战力不变\n// 然后两个阵营合并，打印合并后的阵营最大战斗力\n// 题目可能有多组数据，需要监控输入流直到结束\n// 1 <= n, m <= 10^5\n// 0 <= 猴子战斗力 <= 32768\n// 测试链接 : https://www.luogu.com.cn/problem/P1456\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_MonkeyKing1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆\n\t\tif (num[i] < num[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static int fight(int x, int y) {\n\t\tint a = find(x);\n\t\tint b = find(y);\n\t\tif (a == b) {\n\t\t\treturn -1;\n\t\t}\n\t\tint l = pop(a);\n\t\tint r = pop(b);\n\t\tnum[a] /= 2;\n\t\tnum[b] /= 2;\n\t\tfather[a] = father[b] = father[l] = father[r] = merge(merge(l, a), merge(r, b));\n\t\treturn num[father[a]];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\twhile (in.nextToken() != StreamTokenizer.TT_EOF) {\n\t\t\tn = (int) in.nval;\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tnum[i] = (int) in.nval;\n\t\t\t}\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tx = (int) in.nval;\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) in.nval;\n\t\t\t\tout.println(fight(x, y));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_MonkeyKing2.java`\n\n```java\npackage class154;\n\n// 猴王，C++版\n// 给定n只猴子的战斗力，一开始每个猴子都是独立的阵营\n// 一共有m次冲突，每次冲突给定两只猴子的编号x、y\n// 如果x和y在同一阵营，这次冲突停止，打印-1\n// 如果x和y在不同阵营，x所在阵营的最强猴子会和y所在阵营的最强猴子进行打斗\n// 打斗的结果是，两个各自阵营的最强猴子，战斗力都减半，向下取整，其他猴子战力不变\n// 然后两个阵营合并，打印合并后的阵营最大战斗力\n// 题目可能有多组数据，需要监控输入流直到结束\n// 1 <= n, m <= 10^5\n// 0 <= 猴子战斗力 <= 32768\n// 测试链接 : https://www.luogu.com.cn/problem/P1456\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//int num[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int dist[MAXN];\n//int fa[MAXN];\n//\n//void prepare() {\n//    dist[0] = -1;\n//    for(int i = 1; i <= n; i++) {\n//        ls[i] = rs[i] = dist[i] = 0;\n//        fa[i] = i;\n//    }\n//}\n//\n//int find(int i) {\n//    fa[i] = fa[i] == i ? i : find(fa[i]);\n//    return fa[i];\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) {\n//        return i + j;\n//    }\n//    if (num[i] < num[j]) {\n//        swap(i, j);\n//    }\n//    rs[i] = merge(rs[i], j);\n//    if (dist[ls[i]] < dist[rs[i]]) {\n//        swap(ls[i], rs[i]);\n//    }\n//    dist[i] = dist[rs[i]] + 1;\n//    fa[ls[i]] = fa[rs[i]] = i;\n//    return i;\n//}\n//\n//int pop(int i) {\n//    fa[ls[i]] = ls[i];\n//    fa[rs[i]] = rs[i];\n//    fa[i] = merge(ls[i], rs[i]);\n//    ls[i] = rs[i] = dist[i] = 0;\n//    return fa[i];\n//}\n//\n//int fight(int x, int y) {\n//    int a = find(x);\n//    int b = find(y);\n//    if (a == b) {\n//        return -1;\n//    }\n//    int l = pop(a);\n//    int r = pop(b);\n//    num[a] /= 2;\n//    num[b] /= 2;\n//    fa[a] = fa[b] = fa[l] = fa[r] = merge(merge(l, a), merge(r, b));\n//    return num[fa[a]];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    while (cin >> n) {\n//        prepare();\n//        for (int i = 1; i <= n; i++) {\n//            cin >> num[i];\n//        }\n//        cin >> m;\n//        for (int i = 1; i <= m; i++) {\n//            int x, y;\n//            cin >> x >> y;\n//            cout << fight(x, y) << endl;\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Dispatch1.java`\n\n```java\npackage class154;\n\n// 派遣，java版\n// 一共有n个忍者，每个忍者有上级编号、工资、能力，三个属性\n// 输入保证，任何忍者的上级编号 < 这名忍者的编号，1号忍者是整棵忍者树的头\n// 你一共有m的预算，可以在忍者树上随意选一棵子树，然后在这棵子树上挑选忍者\n// 你选择某棵子树之后，不一定要选子树头的忍者，只要不超过m的预算，可以随意选择子树上的忍者\n// 最终收益 = 雇佣人数 * 子树头忍者的能力，返回能取得的最大收益是多少\n// 1 <= n <= 10^5           1 <= m <= 10^9\n// 1 <= 每个忍者工资 <= m     1 <= 每个忍者领导力 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1552\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code04_Dispatch1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int n, m;\n\n\t// 上级\n\tpublic static int[] leader = new int[MAXN];\n\n\t// 薪水\n\tpublic static long[] cost = new long[MAXN];\n\n\t// 能力\n\tpublic static long[] ability = new long[MAXN];\n\n\t// 左孩子\n\tpublic static int[] left = new int[MAXN];\n\n\t// 右孩子\n\tpublic static int[] right = new int[MAXN];\n\n\t// 距离\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 寻找堆顶需要\n\tpublic static int[] father = new int[MAXN];\n\n\t// 堆的大小\n\tpublic static int[] size = new int[MAXN];\n\n\t// 堆的费用和\n\tpublic static long[] sum = new long[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tsize[i] = 1;\n\t\t\tsum[i] = cost[i];\n\t\t\tfather[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆\n\t\tif (cost[i] < cost[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static long compute() {\n\t\tlong ans = 0;\n\t\tint p, psize, h, hsize;\n\t\tlong hsum, psum;\n\t\tfor (int i = n; i >= 1; i--) {\n\t\t\th = find(i);\n\t\t\thsize = size[h];\n\t\t\thsum = sum[h];\n\t\t\twhile (hsum > m) {\n\t\t\t\tpop(h);\n\t\t\t\thsize--;\n\t\t\t\thsum -= cost[h];\n\t\t\t\th = find(i);\n\t\t\t}\n\t\t\tans = Math.max(ans, (long) hsize * ability[i]);\n\t\t\tif (i > 1) {\n\t\t\t\tp = find(leader[i]);\n\t\t\t\tpsize = size[p];\n\t\t\t\tpsum = sum[p];\n\t\t\t\tfather[p] = father[h] = merge(p, h);\n\t\t\t\tsize[father[p]] = psize + hsize;\n\t\t\t\tsum[father[p]] = psum + hsum;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tleader[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tcost[i] = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tability[i] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tout.println(compute());\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_Dispatch2.java`\n\n```java\npackage class154;\n\n// 派遣，C++版\n// 一共有n个忍者，每个忍者有上级编号、工资、能力，三个属性\n// 输入保证，任何忍者的上级编号 < 这名忍者的编号，1号忍者是整棵忍者树的头\n// 你一共有m的预算，可以在忍者树上随意选一棵子树，然后在这棵子树上挑选忍者\n// 你选择某棵子树之后，不一定要选子树头的忍者，只要不超过m的预算，可以随意选择子树上的忍者\n// 最终收益 = 雇佣人数 * 子树头忍者的能力，返回能取得的最大收益是多少\n// 1 <= n <= 10^5           1 <= m <= 10^9\n// 1 <= 每个忍者工资 <= m     1 <= 每个忍者领导力 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P1552\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//int leader[MAXN];\n//long long cost[MAXN];\n//long long ability[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int dist[MAXN];\n//int fa[MAXN];\n//int siz[MAXN];\n//long long sum[MAXN];\n//\n//int find(int i) {\n//    return fa[i] = (fa[i] == i ? i : find(fa[i]));\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) {\n//        return i + j;\n//    }\n//    if (cost[i] < cost[j]) {\n//        swap(i, j);\n//    }\n//    rs[i] = merge(rs[i], j);\n//    if (dist[ls[i]] < dist[rs[i]]) {\n//        swap(ls[i], rs[i]);\n//    }\n//    dist[i] = dist[rs[i]] + 1;\n//    fa[ls[i]] = fa[rs[i]] = i;\n//    return i;\n//}\n//\n//int pop(int i) {\n//    fa[ls[i]] = ls[i];\n//    fa[rs[i]] = rs[i];\n//    fa[i] = merge(ls[i], rs[i]);\n//    ls[i] = rs[i] = dist[i] = 0;\n//    return fa[i];\n//}\n//\n//void prepare() {\n//    dist[0] = -1;\n//    for (int i = 1; i <= n; i++) {\n//        ls[i] = rs[i] = dist[i] = 0;\n//        siz[i] = 1;\n//        sum[i] = cost[i];\n//        fa[i] = i;\n//    }\n//}\n//\n//long long compute() {\n//    long long ans = 0;\n//    int p, psize, h, hsize;\n//    long long hsum, psum;\n//    for (int i = n; i >= 1; i--) {\n//        h = find(i);\n//        hsize = siz[h];\n//        hsum = sum[h];\n//        while (hsum > m) {\n//            pop(h);\n//            hsize--;\n//            hsum -= cost[h];\n//            h = find(i);\n//        }\n//        ans = max(ans, (long long)hsize * ability[i]);\n//        if (i > 1) {\n//            p = find(leader[i]);\n//            psize = siz[p];\n//            psum = sum[p];\n//            fa[p] = fa[h] = merge(p, h);\n//            siz[fa[p]] = psize + hsize;\n//            sum[fa[p]] = psum + hsum;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> leader[i] >> cost[i] >> ability[i];\n//    }\n//    prepare();\n//    cout << compute() << endl;\n//    return 0;\n//}\n```\n\n### `Code05_NumberSequence1.java`\n\n```java\npackage class154;\n\n// 数字序列，java版\n// 给定一个长度为n的数组A，要求构造出一个长度为n的递增数组B\n// 希望 |A[1] - B[1]| + |A[2] - B[2]| + ... + |A[n] - B[n]| 最小\n// 打印这个最小值，然后打印数组B，如果有多个方案，只打印其中的一个\n// 1 <= n <= 10^6\n// 0 <= A[i] <= 2^32 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P4331\n// 提交以下的code，提交时请把类名改成"Main"，一些测试用例通过不了，空间超了\n// 这是洛谷平台没有考虑其他语言导致的，同样的逻辑，C++实现就能完全通过\n// C++实现的版本，就是Code05_NumberSequence2文件\n\nimport java.io.BufferedWriter;\nimport java.io.ByteArrayOutputStream;\nimport java.io.FileNotFoundException;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.Writer;\nimport java.util.InputMismatchException;\n\npublic class Code05_NumberSequence1 {\n\n\tpublic static int MAXN = 1000001;\n\n\tpublic static int n;\n\n\tpublic static long[] arr = new long[MAXN];\n\n\t// 左偏树需要\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] dist = new int[MAXN];\n\n\t// 并查集向上的路径\n\tpublic static int[] father = new int[MAXN];\n\n\t// 集合表达区域的左下标\n\tpublic static int[] from = new int[MAXN];\n\n\t// 集合表达区域的右下标\n\tpublic static int[] to = new int[MAXN];\n\n\t// 集合里有几个数字\n\tpublic static int[] size = new int[MAXN];\n\n\t// 单调栈\n\tpublic static int[] stack = new int[MAXN];\n\n\t// 构造的数组\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tleft[i] = right[i] = dist[i] = 0;\n\t\t\tfather[i] = from[i] = to[i] = i;\n\t\t\tsize[i] = 1;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 维护大根堆\n\t\tif (arr[i] < arr[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tright[i] = merge(right[i], j);\n\t\tif (dist[left[i]] < dist[right[i]]) {\n\t\t\ttmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[right[i]] + 1;\n\t\tfather[left[i]] = father[right[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tfather[left[i]] = left[i];\n\t\tfather[right[i]] = right[i];\n\t\tfather[i] = merge(left[i], right[i]);\n\t\tleft[i] = right[i] = dist[i] = 0;\n\t\treturn father[i];\n\t}\n\n\tpublic static long compute() {\n\t\tint stackSize = 0;\n\t\tfor (int i = 1, pre, cur, s; i <= n; i++) {\n\t\t\twhile (stackSize > 0) {\n\t\t\t\tpre = find(stack[stackSize]);\n\t\t\t\tcur = find(i);\n\t\t\t\tif (arr[pre] <= arr[cur]) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\ts = size[pre] + size[cur];\n\t\t\t\tcur = merge(pre, cur);\n\t\t\t\t// 大根堆只保留到上中位数\n\t\t\t\twhile (s > (i - from[pre] + 1 + 1) / 2) {\n\t\t\t\t\tcur = pop(cur);\n\t\t\t\t\ts--;\n\t\t\t\t}\n\t\t\t\tfrom[cur] = from[pre];\n\t\t\t\tto[cur] = i;\n\t\t\t\tsize[cur] = s;\n\t\t\t\tstackSize--;\n\t\t\t}\n\t\t\tstack[++stackSize] = i;\n\t\t}\n\t\tlong sum = 0;\n\t\tfor (int i = 1, cur; i <= stackSize; i++) {\n\t\t\tcur = find(stack[i]);\n\t\t\tfor (int j = from[cur]; j <= to[cur]; j++) {\n\t\t\t\tans[j] = arr[cur];\n\t\t\t\tsum += Math.abs(ans[j] - arr[j]);\n\t\t\t}\n\t\t}\n\t\treturn sum;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tFastReader in = new FastReader(System.in);\n\t\tFastWriter out = new FastWriter(System.out);\n\t\tn = in.readInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.readLong() - i;\n\t\t}\n\t\tout.println(compute());\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.write((ans[i] + i));\n\t\t\tout.write(" ");\n\t\t}\n\t\tout.writeln();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 快读\n\tpublic static class FastReader {\n\t\tInputStream is;\n\t\tprivate byte[] inbuf = new byte[1024];\n\t\tpublic int lenbuf = 0;\n\t\tpublic int ptrbuf = 0;\n\n\t\tpublic FastReader(final InputStream is) {\n\t\t\tthis.is = is;\n\t\t}\n\n\t\tpublic int readByte() {\n\t\t\tif (lenbuf == -1) {\n\t\t\t\tthrow new InputMismatchException();\n\t\t\t}\n\t\t\tif (ptrbuf >= lenbuf) {\n\t\t\t\tptrbuf = 0;\n\t\t\t\ttry {\n\t\t\t\t\tlenbuf = is.read(inbuf);\n\t\t\t\t} catch (IOException e) {\n\t\t\t\t\tthrow new InputMismatchException();\n\t\t\t\t}\n\t\t\t\tif (lenbuf <= 0) {\n\t\t\t\t\treturn -1;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn inbuf[ptrbuf++];\n\t\t}\n\n\t\tpublic int readInt() {\n\t\t\treturn (int) readLong();\n\t\t}\n\n\t\tpublic long readLong() {\n\t\t\tlong num = 0;\n\t\t\tint b;\n\t\t\tboolean minus = false;\n\t\t\twhile ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))\n\t\t\t\t;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\n\t\t\twhile (true) {\n\t\t\t\tif (b >= '0' && b <= '9') {\n\t\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\t} else {\n\t\t\t\t\treturn minus ? -num : num;\n\t\t\t\t}\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t}\n\t}\n\n\t// 快写\n\tpublic static class FastWriter {\n\t\tprivate static final int BUF_SIZE = 1 << 13;\n\t\tprivate final byte[] buf = new byte[BUF_SIZE];\n\t\tprivate OutputStream out;\n\t\tprivate Writer writer;\n\t\tprivate int ptr = 0;\n\n\t\tpublic FastWriter(Writer writer) {\n\t\t\tthis.writer = new BufferedWriter(writer);\n\t\t\tout = new ByteArrayOutputStream();\n\t\t}\n\n\t\tpublic FastWriter(OutputStream os) {\n\t\t\tthis.out = os;\n\t\t}\n\n\t\tpublic FastWriter(String path) {\n\t\t\ttry {\n\t\t\t\tthis.out = new FileOutputStream(path);\n\t\t\t} catch (FileNotFoundException e) {\n\t\t\t\tthrow new RuntimeException("FastWriter");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter write(byte b) {\n\t\t\tbuf[ptr++] = b;\n\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter write(String s) {\n\t\t\ts.chars().forEach(c -> {\n\t\t\t\tbuf[ptr++] = (byte) c;\n\t\t\t\tif (ptr == BUF_SIZE) {\n\t\t\t\t\tinnerflush();\n\t\t\t\t}\n\t\t\t});\n\t\t\treturn this;\n\t\t}\n\n\t\tprivate static int countDigits(long l) {\n\t\t\tif (l >= 1000000000000000000L) {\n\t\t\t\treturn 19;\n\t\t\t}\n\t\t\tif (l >= 100000000000000000L) {\n\t\t\t\treturn 18;\n\t\t\t}\n\t\t\tif (l >= 10000000000000000L) {\n\t\t\t\treturn 17;\n\t\t\t}\n\t\t\tif (l >= 1000000000000000L) {\n\t\t\t\treturn 16;\n\t\t\t}\n\t\t\tif (l >= 100000000000000L) {\n\t\t\t\treturn 15;\n\t\t\t}\n\t\t\tif (l >= 10000000000000L) {\n\t\t\t\treturn 14;\n\t\t\t}\n\t\t\tif (l >= 1000000000000L) {\n\t\t\t\treturn 13;\n\t\t\t}\n\t\t\tif (l >= 100000000000L) {\n\t\t\t\treturn 12;\n\t\t\t}\n\t\t\tif (l >= 10000000000L) {\n\t\t\t\treturn 11;\n\t\t\t}\n\t\t\tif (l >= 1000000000L) {\n\t\t\t\treturn 10;\n\t\t\t}\n\t\t\tif (l >= 100000000L) {\n\t\t\t\treturn 9;\n\t\t\t}\n\t\t\tif (l >= 10000000L) {\n\t\t\t\treturn 8;\n\t\t\t}\n\t\t\tif (l >= 1000000L) {\n\t\t\t\treturn 7;\n\t\t\t}\n\t\t\tif (l >= 100000L) {\n\t\t\t\treturn 6;\n\t\t\t}\n\t\t\tif (l >= 10000L) {\n\t\t\t\treturn 5;\n\t\t\t}\n\t\t\tif (l >= 1000L) {\n\t\t\t\treturn 4;\n\t\t\t}\n\t\t\tif (l >= 100L) {\n\t\t\t\treturn 3;\n\t\t\t}\n\t\t\tif (l >= 10L) {\n\t\t\t\treturn 2;\n\t\t\t}\n\t\t\treturn 1;\n\t\t}\n\n\t\tpublic FastWriter write(long x) {\n\t\t\tif (x == Long.MIN_VALUE) {\n\t\t\t\treturn write("" + x);\n\t\t\t}\n\t\t\tif (ptr + 21 >= BUF_SIZE) {\n\t\t\t\tinnerflush();\n\t\t\t}\n\t\t\tif (x < 0) {\n\t\t\t\twrite((byte) '-');\n\t\t\t\tx = -x;\n\t\t\t}\n\t\t\tint d = countDigits(x);\n\t\t\tfor (int i = ptr + d - 1; i >= ptr; i--) {\n\t\t\t\tbuf[i] = (byte) ('0' + x % 10);\n\t\t\t\tx /= 10;\n\t\t\t}\n\t\t\tptr += d;\n\t\t\treturn this;\n\t\t}\n\n\t\tpublic FastWriter writeln(long x) {\n\t\t\treturn write(x).writeln();\n\t\t}\n\n\t\tpublic FastWriter writeln() {\n\t\t\treturn write((byte) '\\n');\n\t\t}\n\n\t\tprivate void innerflush() {\n\t\t\ttry {\n\t\t\t\tout.write(buf, 0, ptr);\n\t\t\t\tptr = 0;\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("innerflush");\n\t\t\t}\n\t\t}\n\n\t\tpublic void flush() {\n\t\t\tinnerflush();\n\t\t\ttry {\n\t\t\t\tif (writer != null) {\n\t\t\t\t\twriter.write(((ByteArrayOutputStream) out).toString());\n\t\t\t\t\tout = new ByteArrayOutputStream();\n\t\t\t\t\twriter.flush();\n\t\t\t\t} else {\n\t\t\t\t\tout.flush();\n\t\t\t\t}\n\t\t\t} catch (IOException e) {\n\t\t\t\tthrow new RuntimeException("flush");\n\t\t\t}\n\t\t}\n\n\t\tpublic FastWriter println(long x) {\n\t\t\treturn writeln(x);\n\t\t}\n\n\t\tpublic void close() {\n\t\t\tflush();\n\t\t\ttry {\n\t\t\t\tout.close();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code05_NumberSequence2.java`\n\n```java\npackage class154;\n\n// 数字序列，C++版\n// 给定一个长度为n的数组A，要求构造出一个长度为n的递增数组B\n// 希望 |A[1] - B[1]| + |A[2] - B[2]| + ... + |A[n] - B[n]| 最小\n// 打印这个最小值，然后打印数组B，如果有多个方案，只打印其中的一个\n// 1 <= n <= 10^6\n// 0 <= A[i] <= 2^32 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P4331\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 1000001;\n//int n;\n//long long arr[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int dist[MAXN];\n//int fa[MAXN];\n//int from[MAXN];\n//int to[MAXN];\n//int siz[MAXN];\n//int stk[MAXN];\n//long long ans[MAXN];\n//\n//void prepare() {\n//    dist[0] = -1;\n//    for (int i = 1; i <= n; i++) {\n//        ls[i] = rs[i] = dist[i] = 0;\n//        fa[i] = from[i] = to[i] = i;\n//        siz[i] = 1;\n//    }\n//}\n//\n//int find(int i) {\n//    fa[i] = fa[i] == i ? i : find(fa[i]);\n//    return fa[i];\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) {\n//        return i + j;\n//    }\n//    if (arr[i] < arr[j]) {\n//        swap(i, j);\n//    }\n//    rs[i] = merge(rs[i], j);\n//    if (dist[ls[i]] < dist[rs[i]]) {\n//        swap(ls[i], rs[i]);\n//    }\n//    dist[i] = dist[rs[i]] + 1;\n//    fa[ls[i]] = fa[rs[i]] = i;\n//    return i;\n//}\n//\n//int pop(int i) {\n//    fa[ls[i]] = ls[i];\n//    fa[rs[i]] = rs[i];\n//    fa[i] = merge(ls[i], rs[i]);\n//    ls[i] = rs[i] = dist[i] = 0;\n//    return fa[i];\n//}\n//\n//long long compute() {\n//    int stackSize = 0;\n//    for (int i = 1, pre, cur, s; i <= n; i++) {\n//        while (stackSize > 0) {\n//            pre = find(stk[stackSize]);\n//            cur = find(i);\n//            if (arr[pre] <= arr[cur]) {\n//                break;\n//            }\n//            s = siz[pre] + siz[cur];\n//            cur = merge(pre, cur);\n//            while (s > ((i - from[pre] + 1 + 1) / 2)) {\n//                cur = pop(cur);\n//                s--;\n//            }\n//            from[cur] = from[pre];\n//            to[cur] = i;\n//            siz[cur] = s;\n//            stackSize--;\n//        }\n//        stk[++stackSize] = i;\n//    }\n//    long long sum = 0;\n//    for (int i = 1, cur; i <= stackSize; i++) {\n//        cur = find(stk[i]);\n//        for (int j = from[cur]; j <= to[cur]; j++) {\n//            ans[j] = arr[cur];\n//            sum += llabs(ans[j] - arr[j]);\n//        }\n//    }\n//    return sum;\n//}\n//\n//int main() {\n//    ios_base::sync_with_stdio(false);\n//    cin.tie(NULL);\n//    cin >> n;\n//    prepare();\n//    long long x;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> x;\n//        arr[i] = x - i;\n//    }\n//    long long res = compute();\n//    cout << res << "\\n";\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] + i << (i == n ? '\\n' : ' ');\n//    }\n//    return 0;\n//}\n```\n\n### `FollowUp1.java`\n\n```java\npackage class154;\n\n// 可并堆2，java版\n// 这道题课上没有讲，一个值得实现的左偏树模版题\n// 完全是课上讲过的代码，看懂课就能看懂如下实现\n// 给定n个元素，编号为1到n，给定每个元素的值num[i]\n// 初始时每个元素单独组成一个集合，接下来有m次操作，类型有四种，格式如下\n// 操作 0 x y   : 集合x中删除元素y，题目保证y一定在集合x中\n// 操作 1 x     : 查询集合x中的最小值，这是唯一需要打印的操作\n// 操作 2 x y   : 集合y合并到集合x，题目保证以后不会再有以y做集合编号的操作\n// 操作 3 x y z : 集合x中元素y的权值修改为z，题目保证修改操作值只可能变小\n// 测试链接 : https://www.luogu.com.cn/problem/P11266\n// 注意打注释位置的代码即可\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class FollowUp1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int n, m;\n\n\tpublic static int[] num = new int[MAXN];\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] ls = new int[MAXN];\n\tpublic static int[] rs = new int[MAXN];\n\tpublic static int[] dist = new int[MAXN];\n\tpublic static int[] father = new int[MAXN];\n\n\t// root[x]表示集合x的堆头节点编号\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tdist[0] = -1;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tup[i] = ls[i] = rs[i] = dist[i] = 0;\n\t\t\tfather[i] = i;\n\t\t\t// 初始每个集合i只有元素i\n\t\t\troot[i] = i;\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tfather[i] = father[i] == i ? i : find(father[i]);\n\t\treturn father[i];\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\t// 小根堆\n\t\t// 值越小越优先\n\t\t// 值一样，按照编号越小越优先\n\t\tif (num[i] > num[j] || (num[i] == num[j] && i > j)) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\trs[i] = merge(rs[i], j);\n\t\tup[rs[i]] = i;\n\t\tif (dist[ls[i]] < dist[rs[i]]) {\n\t\t\ttmp = ls[i];\n\t\t\tls[i] = rs[i];\n\t\t\trs[i] = tmp;\n\t\t}\n\t\tdist[i] = dist[rs[i]] + 1;\n\t\tfather[ls[i]] = father[rs[i]] = i;\n\t\treturn i;\n\t}\n\n\tpublic static int remove(int i) {\n\t\tint h = find(i);\n\t\tfather[ls[i]] = ls[i];\n\t\tfather[rs[i]] = rs[i];\n\t\tint s = merge(ls[i], rs[i]);\n\t\tint f = up[i];\n\t\tfather[i] = s;\n\t\tup[s] = f;\n\t\tif (h != i) {\n\t\t\tfather[s] = h;\n\t\t\tif (ls[f] == i) {\n\t\t\t\tls[f] = s;\n\t\t\t} else {\n\t\t\t\trs[f] = s;\n\t\t\t}\n\t\t\tfor (int d = dist[s], tmp; dist[f] > d + 1; f = up[f], d++) {\n\t\t\t\tdist[f] = d + 1;\n\t\t\t\tif (dist[ls[f]] < dist[rs[f]]) {\n\t\t\t\t\ttmp = ls[f];\n\t\t\t\t\tls[f] = rs[f];\n\t\t\t\t\trs[f] = tmp;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tup[i] = ls[i] = rs[i] = dist[i] = 0;\n\t\treturn father[s];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tprepare();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\t// 删除后需要更新集合x的堆头\n\t\t\t\troot[x] = remove(y);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t} else if (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tout.println(num[root[x]]);\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\t// 合并集合x和集合y\n\t\t\t\troot[x] = merge(root[x], root[y]);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tint h = remove(y);\n\t\t\t\tnum[y] = z;\n\t\t\t\t// y改值后重新作为单点堆\n\t\t\t\tfather[y] = y;\n\t\t\t\t// 合并到集合x\n\t\t\t\troot[x] = merge(h, y);\n\t\t\t\tif (root[x] != 0) {\n\t\t\t\t\tfather[root[x]] = root[x];\n\t\t\t\t\tup[root[x]] = 0;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `FollowUp2.java`\n\n```java\npackage class154;\n\n// 可并堆2，C++版\n// 这道题课上没有讲，一个值得实现的左偏树模版题\n// 完全是课上讲过的代码，看懂课就能看懂如下实现\n// 给定n个元素，编号为1到n，给定每个元素的值num[i]\n// 初始时每个元素单独组成一个集合，接下来有m次操作，类型有四种，格式如下\n// 操作 0 x y   : 集合x中删除元素y，题目保证y一定在集合x中\n// 操作 1 x     : 查询集合x中的最小值，这是唯一需要打印的操作\n// 操作 2 x y   : 集合y合并到集合x，题目保证以后不会再有以y做集合编号的操作\n// 操作 3 x y z : 集合x中元素y的权值修改为z，题目保证修改操作值只可能变小\n// 测试链接 : https://www.luogu.com.cn/problem/P11266\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using