) {\n//        int lca = getLca(tmp[i], tmp[i + 1]);\n//        addEdgeV(lca, tmp[i + 1]);\n//        addEdgeV(tmp[i + 1], lca);\n//    }\n//    len = unique;\n//    return tmp[1];\n//}\n//\n//void dijkstra() {\n//    for (int i = 1; i <= len; i++) {\n//        int u = tmp[i];\n//        minTime[u] = n + 1;\n//        findVirus[u] = k + 1;\n//        vis[u] = false;\n//    }\n//    for (int i = 1; i <= k; i++) {\n//        int s = start[i];\n//        minTime[s] = 0;\n//        findVirus[s] = i;\n//        heap.push(Node{s, 0, 0, i});\n//    }\n//    while (!heap.empty()) {\n//        Node cur = heap.top();\n//        heap.pop();\n//        int u = cur.id;\n//        int udist = cur.dist;\n//        int uvirus = cur.virus;\n//        if (!vis[u]) {\n//            vis[u] = true;\n//            for (int e = headv[u]; e; e = nextv[e]) {\n//                int v = tov[e];\n//                if (!vis[v]) {\n//                    int vdist = udist + abs(dep[u] - dep[v]);\n//                    int vtime = (vdist + speed[uvirus] - 1) / speed[uvirus];\n//                    if (vtime < minTime[v] || (vtime == minTime[v] && uvirus < findVirus[v])) {\n//                        minTime[v] = vtime;\n//                        findVirus[v] = uvirus;\n//                        heap.push(Node{v, vdist, vtime, uvirus});\n//                    }\n//                }\n//            }\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdgeG(u, v);\n//        addEdgeG(v, u);\n//    }\n//    dfs(1, 0);\n//    cin >> q;\n//    for (int t = 1; t <= q; t++) {\n//        cin >> k >> m;\n//        for (int i = 1, s, v; i <= k; i++) {\n//            cin >> start[i] >> speed[i];\n//        }\n//        for (int i = 1; i <= m; i++) {\n//            cin >> query[i];\n//        }\n//        buildVirtualTree();\n//        dijkstra();\n//        for (int i = 1; i <= m; i++) {\n//            cout << findVirus[query[i]] << ' ';\n//        }\n//        cout << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_TreasureHunt1.java`\n\n```java\npackage class180;\n\n// 寻宝游戏，java版\n// 一共有n个节点，节点有两种类型，刷宝的点 和 不刷宝的点\n// 一共有n-1条无向边，每条边有边权，所有节点组成一棵树\n// 开始时所有节点都是不刷宝的点，接下来有m条操作，格式如下\n// 操作 x : x号点的类型翻转，刷宝的点 变成 不刷宝的点，不刷宝的点 变成 刷宝的点\n// 一次操作后，每个刷宝的点都会产生宝物，你可以瞬移到任何点作为出发点，瞬移是无代价的\n// 你需要走路拿到所有的宝物，最后回到出发点，打印最小的行走总路程，一共有m条打印\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3320\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.TreeSet;\n\npublic class Code06_TreasureHunt1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int[] weight = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static long[] dist = new long[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\tpublic static int cntd;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static boolean[] treasure = new boolean[MAXN];\n\t// 这里为了方便，使用语言自带的有序表\n\tpublic static TreeSet<Integer> set = new TreeSet<>();\n\n\tpublic static long[] ans = new long[MAXN];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// dfs递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa, int w) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tdist[u] = dist[fa] + w;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif (to[e] != fa) {\n\t\t\t\tdfs1(to[e], u, weight[e]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] ufwe = new int[MAXN][4];\n\n\tpublic static int stacksize, u, f, w, e;\n\n\tpublic static void push(int u, int f, int w, int e) {\n\t\tufwe[stacksize][0] = u;\n\t\tufwe[stacksize][1] = f;\n\t\tufwe[stacksize][2] = w;\n\t\tufwe[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufwe[stacksize][0];\n\t\tf = ufwe[stacksize][1];\n\t\tw = ufwe[stacksize][2];\n\t\te = ufwe[stacksize][3];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tdfn[u] = ++cntd;\n\t\t\t\tseg[cntd] = u;\n\t\t\t\tdist[u] = dist[f] + w;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, w, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, weight[e], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a; a = b; b = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static long getDist(int x, int y) {\n\t\treturn dist[x] + dist[y] - 2 * dist[getLca(x, y)];\n\t}\n\n\tpublic static void compute() {\n\t\tlong curAns = 0;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint nodeId = arr[i];\n\t\t\tint dfnId = dfn[nodeId];\n\t\t\tif (!treasure[nodeId]) {\n\t\t\t\ttreasure[nodeId] = true;\n\t\t\t\tset.add(dfnId);\n\t\t\t} else {\n\t\t\t\ttreasure[nodeId] = false;\n\t\t\t\tset.remove(dfnId);\n\t\t\t}\n\t\t\tif (set.size() <= 1) {\n\t\t\t\tcurAns = 0;\n\t\t\t} else {\n\t\t\t\tint low = seg[set.lower(dfnId) != null ? set.lower(dfnId) : set.last()];\n\t\t\t\tint high = seg[set.higher(dfnId) != null ? set.higher(dfnId) : set.first()];\n\t\t\t\tlong delta = getDist(nodeId, low) + getDist(nodeId, high) - getDist(low, high);\n\t\t\t\tif (treasure[nodeId]) {\n\t\t\t\t\tcurAns += delta;\n\t\t\t\t} else {\n\t\t\t\t\tcurAns -= delta;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans[i] = curAns;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v, w; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextInt();\n\t\t\taddEdge(u, v, w);\n\t\t\taddEdge(v, u, w);\n\t\t}\n\t\t// dfs1(1, 0, 0);\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tcompute();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_TreasureHunt2.java`\n\n```java\npackage class180;\n\n// 寻宝游戏，C++版\n// 一共有n个节点，节点有两种类型，刷宝的点 和 不刷宝的点\n// 一共有n-1条无向边，每条边有边权，所有节点组成一棵树\n// 开始时所有节点都是不刷宝的点，接下来有m条操作，格式如下\n// 操作 x : x号点的类型翻转，刷宝的点 变成 不刷宝的点，不刷宝的点 变成 刷宝的点\n// 一次操作后，每个刷宝的点都会产生宝物，你可以瞬移到任何点作为出发点，瞬移是无代价的\n// 你需要走路拿到所有的宝物，最后回到出发点，打印最小的行走总路程，一共有m条打印\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3320\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXP = 20;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int weight[MAXN << 1];\n//int cntg;\n//\n//int dep[MAXN];\n//long long dist[MAXN];\n//int dfn[MAXN];\n//int seg[MAXN];\n//int stjump[MAXN][MAXP];\n//int cntd;\n//\n//int arr[MAXN];\n//bool treasure[MAXN];\n//std::set<int> st;\n//std::set<int>::iterator it;\n//\n//long long ans[MAXN];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u, int fa, int w) {\n//    dep[u] = dep[fa] + 1;\n//    dfn[u] = ++cntd;\n//    seg[cntd] = u;\n//    dist[u] = dist[fa] + w;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            dfs(v, u, weight[e]);\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    if (dep[a] < dep[b]) {\n//        swap(a, b);\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (dep[stjump[a][p]] >= dep[b]) {\n//            a = stjump[a][p];\n//        }\n//    }\n//    if (a == b) 