{\n//    if (ql > qr) {\n//        return;\n//    }\n//    if (vl == vr) {\n//        for (int i = ql; i <= qr; i++) {\n//            ans[qid[i]] = xyv[vl].v;\n//        }\n//    } else {\n//        int mid = (vl + vr) >> 1;\n//        int lsiz = 0, rsiz = 0;\n//        while (used < mid) {\n//            used++;\n//            add(xyv[used].x, xyv[used].y, 1);\n//        }\n//        while (used > mid) {\n//            add(xyv[used].x, xyv[used].y, -1);\n//            used--;\n//        }\n//        for (int i = ql; i <= qr; i++) {\n//            int id = qid[i];\n//            int satisfy = query(a[id], b[id], c[id], d[id]);\n//            if (satisfy >= k[id]) {\n//                lset[++lsiz] = id;\n//            } else {\n//                rset[++rsiz] = id;\n//            }\n//        }\n//        for (int i = 1; i <= lsiz; i++) {\n//            qid[ql + i - 1] = lset[i];\n//        }\n//        for (int i = 1; i <= rsiz; i++) {\n//            qid[ql + lsiz + i - 1] = rset[i];\n//        }\n//        compute(ql, ql + lsiz - 1, vl, mid);\n//        compute(ql + lsiz, qr, mid + 1, vr);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> q;\n//    for (int i = 1; i <= n; i++) {\n//        for (int j = 1; j <= n; j++) {\n//            xyv[++cntv].x = i;\n//            xyv[cntv].y = j;\n//            cin >> xyv[cntv].v;\n//        }\n//    }\n//    for (int i = 1; i <= q; i++) {\n//        qid[i] = i;\n//        cin >> a[i] >> b[i] >> c[i] >> d[i] >> k[i];\n//    }\n//    sort(xyv + 1, xyv + cntv + 1, NumberCmp);\n//    compute(1, q, 1, cntv);\n//    for (int i = 1; i <= q; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_Meteors1.java`\n\n```java\npackage class168;\n\n// 陨石雨，第一种写法，java版\n// 一共有n个国家，给定n个数字，表示每个国家希望收集到的陨石数量\n// 一共有m个区域，1号区顺时针到2号区...m号区顺时针到1号区，即环形相连\n// 每个区域只属于某一个国家，给定m个数字，表示每个区域归属给哪个国家\n// 接下来会依次发生k场陨石雨，陨石雨格式 l r num，含义如下\n// 从l号区顺时针到r号区发生了陨石雨，每个区域都增加num个陨石\n// 打印每个国家经历前几场陨石雨，可以达到收集要求，如果无法满足，打印"NIE"\n// 1 <= n、m、k <= 3 * 10^5    1 <= 陨石数量 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3527\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但无法通过所有测试用例，内存使用过大\n// 因为这道题只考虑C++能通过的空间极限，根本没考虑java的用户\n// 想通过用C++实现，本节课Code03_Meteors3文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Meteors1 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int n, m, k;\n\n\t// 国家编号\n\tpublic static int[] qid = new int[MAXN];\n\t// 国家的需求\n\tpublic static int[] need = new int[MAXN];\n\n\t// 陨石雨的参数\n\tpublic static int[] rainl = new int[MAXN];\n\tpublic static int[] rainr = new int[MAXN];\n\tpublic static int[] num = new int[MAXN];\n\n\t// 国家拥有的区域列表\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int cnt = 0;\n\n\t// 树状数组，支持范围修改、单点查询\n\tpublic static long[] tree = new long[MAXN << 1];\n\n\t// 整体二分\n\tpublic static int[] lset = new int[MAXN];\n\tpublic static int[] rset = new int[MAXN];\n\n\t// 每个国家的答案\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int i, int v) {\n\t\tnext[++cnt] = head[i];\n\t\tto[cnt] = v;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\tint siz = m * 2;\n\t\twhile (i <= siz) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void add(int l, int r, int v) {\n\t\tadd(l, v);\n\t\tadd(r + 1, -v);\n\t}\n\n\tpublic static long query(int i) {\n\t\tlong ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tans[qid[i]] = vl;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tfor (int i = vl; i <= mid; i++) {\n\t\t\t\tadd(rainl[i], rainr[i], num[i]);\n\t\t\t}\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tint id = qid[i];\n\t\t\t\tlong satisfy = 0;\n\t\t\t\tfor (int e = head[id]; e > 0; e = next[e]) {\n\t\t\t\t\tsatisfy += query(to[e]) + query(to[e] + m);\n\t\t\t\t\tif (satisfy >= need[id]) {\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (satisfy >= need[id]) {\n\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t} else {\n\t\t\t\t\tneed[id] -= satisfy;\n\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tqid[ql + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tqid[ql + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tfor (int i = vl; i <= mid; i++) {\n\t\t\t\tadd(rainl[i], rainr[i], -num[i]);\n\t\t\t}\n\t\t\tcompute(ql, ql + lsiz - 1, vl, mid);\n\t\t\tcompute(ql + lsiz, qr, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, nation; i <= m; i++) {\n\t\t\tnation = in.nextInt();\n\t\t\taddEdge(nation, i);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tqid[i] = i;\n\t\t\tneed[i] = in.nextInt();\n\t\t}\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\trainl[i] = in.nextInt();\n\t\t\trainr[i] = in.nextInt();\n\t\t\tif (rainr[i] < rainl[i]) {\n\t\t\t\trainr[i] += m;\n\t\t\t}\n\t\t\tnum[i] = in.nextInt();\n\t\t}\n\t\t// 答案范围[1..k+1]，第k+1场陨石雨认为满足不了要求\n\t\tcompute(1, n, 1, k + 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (ans[i] == k + 1) {\n\t\t\t\tout.println("NIE");\n\t\t\t} else {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_Meteors2.java`\n\n```java\npackage class168;\n\n// 陨石雨，第二种写法，java版\n// 一共有n个国家，给定n个数字，表示每个国家希望收集到的陨石数量\n// 一共有m个区域，1号区顺时针到2号区...m号区顺时针到1号区，即环形相连\n// 每个区域只属于某一个国家，给定m个数字，表示每个区域归属给哪个国家\n// 接下来会依次发生k场陨石雨，陨石雨格式 l r num，含义如下\n// 从l号区顺时针到r号区发生了陨石雨，每个区域都增加num个陨石\n// 打印每个国家经历前几场陨石雨，可以达到收集要求，如果无法满足，打印"NIE"\n// 1 <= n、m、k <= 3 * 10^5    1 <= 陨石数量 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3527\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但无法通过所有测试用例，内存使用过大\n// 因为这道题只考虑C++能通过的空间极限，根本没考虑java的用户\n// 想通过用C++实现，本节课Code03_Meteors4文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_Meteors2 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int n, m, k;\n\n\tpublic static int[] qid = new int[MAXN];\n\tpublic static int[] need = new int[MAXN];\n\n\tpublic static int[] rainl = new int[MAXN];\n\tpublic static int[] rainr = new int[MAXN];\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int cnt = 0;\n\n\tpublic static long[] tree = new long[MAXN << 1];\n\t// 下了多少场陨石雨\n\tpublic static int used = 0;\n\n\tpublic static int[] lset = new int[MAXN];\n\tpublic static int[] rset = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static void addEdge(int i, int v) {\n\t\tnext[++cnt] = head[i];\n\t\tto[cnt] = v;\n\t\thead[i] = cnt;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int v) {\n\t\tint siz = m * 2;\n\t\twhile (i <= siz) {\n\t\t\ttree[i] += v;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void add(int l, int r, int v) {\n\t\tadd(l, v);\n\t\tadd(r + 1, -v);\n\t}\n\n\tpublic static long query(int i) {\n\t\tlong ret = 0;\n\t\twhile (i > 0) {\n\t\t\tret += tree[i];\n\t\t\ti -= lowbit(i);\n\t\t}\n\t\treturn ret;\n\t}\n\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tans[qid[i]] = vl;\n\t\t\t}\n\t\t} else {\n\t\t\tint mid = (vl + vr) >> 1;\n\t\t\tint lsiz = 0, rsiz = 0;\n\t\t\twhile (used < mid) {\n\t\t\t\tused++;\n\t\t\t\tadd(rainl[used], rainr[used], num[used]);\n\t\t\t}\n\t\t\twhile (used > mid) {\n\t\t\t\tadd(rainl[used], rainr[used], -num[used]);\n\t\t\t\tused--;\n\t\t\t}\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tint id = qid[i];\n\t\t\t\tlong satisfy = 0;\n\t\t\t\tfor (int e = head[id]; e > 0; e = next[e]) {\n\t\t\t\t\tsatisfy += query(to[e]) + query(to[e] + m);\n\t\t\t\t\tif (satisfy >= need[id]) {\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (satisfy >= need[id]) {\n\t\t\t\t\tlset[++lsiz] = id;\n\t\t\t\t} else {\n\t\t\t\t\trset[++rsiz] = id;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= lsiz; i++) {\n\t\t\t\tqid[ql + i - 1] = lset[i];\n\t\t\t}\n\t\t\tfor (int i = 1; i <= rsiz; i++) {\n\t\t\t\tqid[ql + lsiz + i - 1] = rset[i];\n\t\t\t}\n\t\t\tcompute(ql, ql + lsiz - 1, vl, mid);\n\t\t\tcompute(ql + lsiz, qr, mid + 1, vr);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, nation; i <= m; i++) {\n\t\t\tnation = in.nextInt();\n\t\t\taddEdge(nation, i);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tqid[i] = i;\n\t\t\tneed[i] = in.nextInt();\n\t\t}\n\t\tk = in.nextInt();\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\trainl[i] = in.nextInt();\n\t\t\trainr[i] = in.nextInt();\n\t\t\tif (rainr[i] < rainl[i]) {\n\t\t\t\trainr[i] += m;\n\t\t\t}\n\t\t\tnum[i] = in.nextInt();\n\t\t}\n\t\tcompute(1, n, 1, k + 1);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (ans[i] == k + 1) {\n\t\t\t\tout.println("NIE");\n\t\t\t} else {\n\t\t\t\tout.println(ans[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_Meteors3.java`\n\n```java\npackage class168;\n\n// 陨石雨，第一种写法，C++版\n// 一共有n个国家，给定n个数字，表示每个国家希望收集到的陨石数量\n// 一共有m个区域，1号区顺时针到2号区...m号区顺时针到1号区，即环形相连\n// 每个区域只属于某一个国家，给定m个数字，表示每个区域归属给哪个国家\n// 接下来会依次发生k场陨石雨，陨石雨格式 l r num，含义如下\n// 从l号区顺时针到r号区发生了陨石雨，每个区域都增加num个陨石\n// 打印每个国家经历前几场陨石雨，可以达到收集要求，如果无法满足，打印"NIE"\n// 1 <= n、m、k <= 3 * 10^5    1 <= 陨石数量 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P3527\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 300001;\n//int n, m, k;\n//\n//int qid[MAXN];\n//int need[MAXN];\n//\n//int rainl[MAXN];\n//int rainr[MAXN];\n//int num[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN];\n//int to[MAXN];\n//int cnt = 0;\n//\n//long long tree[MAXN << 1];\n//\n//int lset[MAXN];\n//int rset[MAXN];\n//\n//int ans[MAXN];\n//\n//void addEdge(int i, int v) {\n//    nxt[++cnt] = head[i];\n//    to[cnt] = v;\n//    head[i] = cnt;\n//}\n//\n//int lowbit(int i) {\n//    return i & -i;\n//}\n//\n//void add(int i, int v) {\n//    int siz = m * 2;\n//    while (i <= siz) {\n//        tree[i] += v;\n//        i += lowbit(i);\n//    }\n//}\n//\n//void add(int l, int r, int v) {\n//    add(l, v);\n//    add(r + 1, -v);\n//}\n//\n//long long query(int i) {\n//    long long ret = 0;\n//    while (i > 0) {\n//    \tret += tree[i];\n//        i -= lowbit(i);\n//    }\n//    return ret;\n//}\n//\n//void compute(int ql, int qr, int vl, int vr) {\n//    if (ql > qr) {\n//        return;\n//    }\n//    if (vl == vr) {\n//        for (int i = ql; i <= qr; i++) {\n//            ans[qid[i]] = vl;\n//        }\n//    } else {\n//        int mid = (vl + vr) >> 1;\n//        for (int i = vl; i <= mid; i++) {\n//            add(rainl[i], rainr[i], num[i]);\n//        }\n//        int lsiz = 0, rsiz = 0;\n//        for (int i = ql; i <= qr; i++) {\n//            int id = qid[i];\n//            long long satisfy = 0;\n//            for (int e = head[id]; e > 0; e = nxt[e]) {\n//                satisfy += query(to[e]) + query(to[e] + m);\n//                if (satisfy >= need[id]) {\n//                    break;\n//                }\n//            }\n//            if (satisfy >= need[id]