uery(a, b, 1, n, root[v]);\n//    int best = info[1];\n//    initInfo();\n//    query(c, d, 1, n, root[v]);\n//    best += info[0];\n//    if (b + 1 <= c - 1) {\n//        initInfo();\n//        query(b + 1, c - 1, 1, n, root[v]);\n//        best += info[2];\n//    }\n//    return best >= 0;\n//}\n//\n//int compute(int a, int b, int c, int d) {\n//    int left = 1, right = n, mid, ans = 0;\n//    while (left <= right) {\n//        mid = (left + right) / 2;\n//        if (check(a, b, c, d, mid)) {\n//            ans = arr[mid].second;\n//            left = mid + 1;\n//        } else {\n//            right = mid - 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    arr.resize(n + 1);\n//    for (int i = 1; i <= n; i++) {\n//        arr[i].first = i;\n//        cin >> arr[i].second;\n//    }\n//    prepare();\n//    cin >> m;\n//    for (int i = 1, lastAns = 0; i <= m; i++) {\n//        for (int j = 0; j < 4; j++) {\n//            cin >> ques[j];\n//            ques[j] = (ques[j] + lastAns) % n + 1;\n//        }\n//        sort(ques, ques + 4);\n//        lastAns = compute(ques[0], ques[1], ques[2], ques[3]);\n//        cout << lastAns << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_CountOnTree1.java`\n\n```java\npackage class158;\n\n// 路径上的第k小，java版\n// 有n个节点，编号1~n，每个节点有权值，有n-1条边，所有节点组成一棵树\n// 一共有m条查询，每条查询 u v k : 打印u号点到v号点的路径上，第k小的点权\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定的u、v、k，按照如下方式得到真实的u、v、k，查询完成后更新lastAns\n// 真实u = 给定u ^ lastAns\n// 真实v = 给定v\n// 真实k = 给定k\n// 1 <= n、m <= 10^5\n// 1 <= arr[i] <= 2^32 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P2633\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_CountOnTree1 {\n\n\tpublic static int MAXN = 100001;\n\n\tpublic static int MAXP = 20;\n\n\tpublic static int MAXT = MAXN * MAXP;\n\n\tpublic static int n, m, s;\n\n\t// 各个节点权值\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 收集权值排序并且去重做离散化\n\tpublic static int[] sorted = new int[MAXN];\n\n\t// 链式前向星需要\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] to = new int[MAXN << 1];\n\n\tpublic static int[] next = new int[MAXN << 1];\n\n\tpublic static int cntg = 0;\n\n\t// 可持久化线段树需要\n\tpublic static int[] root = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXT];\n\n\tpublic static int[] right = new int[MAXT];\n\n\tpublic static int[] size = new int[MAXT];\n\n\tpublic static int cntt = 0;\n\n\t// 树上倍增找lca需要\n\tpublic static int[] deep = new int[MAXN];\n\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int kth(int num) {\n\t\tint left = 1, right = s, mid;\n\t\twhile (left <= right) {\n\t\t\tmid = (left + right) / 2;\n\t\t\tif (sorted[mid] == num) {\n\t\t\t\treturn mid;\n\t\t\t} else if (sorted[mid] < num) {\n\t\t\t\tleft = mid + 1;\n\t\t\t} else {\n\t\t\t\tright = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int build(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tsize[rt] = 0;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tleft[rt] = build(l, mid);\n\t\t\tright[rt] = build(mid + 1, r);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void prepare() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsorted[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sorted, 1, n + 1);\n\t\ts = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sorted[s] != sorted[i]) {\n\t\t\t\tsorted[++s] = sorted[i];\n\t\t\t}\n\t\t}\n\t\troot[0] = build(1, s);\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int insert(int jobi, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tleft[rt] = left[i];\n\t\tright[rt] = right[i];\n\t\tsize[rt] = size[i] + 1;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tleft[rt] = insert(jobi, l, mid, left[rt]);\n\t\t\t} else {\n\t\t\t\tright[rt] = insert(jobi, mid + 1, r, right[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int query(int jobk, int l, int r, int u, int v, int lca, int lcafa) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint lsize = size[left[u]] + size[left[v]] - size[left[lca]] - size[left[lcafa]];\n\t\tint mid = (l + r) / 2;\n\t\tif (lsize >= jobk) {\n\t\t\treturn query(jobk, l, mid, left[u], left[v], left[lca], left[lcafa]);\n\t\t} else {\n\t\t\treturn query(jobk - lsize, mid + 1, r, right[u], right[v], right[lca], right[lcafa]);\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java无法通过，递归会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\troot[u] = insert(kth(arr[u]), 1, s, root[f]);\n\t\tdeep[u] = deep[f] + 1;\n\t\tstjump[u][0] = f;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int ei = head[u]; ei > 0; ei = next[ei]) {\n\t\t\tif (to[ei] != f) {\n\t\t\t\tdfs1(to[ei], u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版，都可以通过\n\t// 讲解118，详解了从递归版改迭代版\n\tpublic static int[][] ufe = new int[MAXN][3];\n\n\tpublic static int stackSize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stackSize][0] = u;\n\t\tufe[stackSize][1] = f;\n\t\tufe[stackSize][2] = e;\n\t\tstackSize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stackSize;\n\t\tu = ufe[stackSize][0];\n\t\tf = ufe[stackSize][1];\n\t\te = ufe[stackSize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs2() {\n\t\tstackSize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stackSize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\troot[u] = insert(kth(arr[u]), 1, s, root[f]);\n\t\t\t\tdeep[u] = deep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = next[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\tif (deep[a] < deep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (deep[stjump[a][p]] >= deep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static int kth(int u, int v, int k) {\n\t\tint lca = lca(u, v);\n\t\tint i = query(k, 1, s, root[u], root[v], root[lca], root[stjump[lca][0]]);\n\t\treturn sorted[i];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tarr[i] = (int) in.nval;\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs2(); // 使用迭代版防止爆栈\n\t\tfor (int i = 1, u, v, k, lastAns = 0; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval ^ lastAns;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tk = (int) in.nval;\n\t\t\tlastAns = kth(u, v, k);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_CountOnTree2.java`\n\n```java\npackage class158;\n\n// 路径上的第k小，C++版\n// 有n个节点，编号1~n，每个节点有权值，有n-1条边，所有节点组成一棵树\n// 一共有m条查询，每条查询 u v k : 打印u号点到v号点的路径上，第k小的点权\n// 题目有强制在线的要求，上一次打印的答案为lastAns，初始时lastAns = 0\n// 每次给定的u、v、k，按照如下方式得到真实的u、v、k，查询完成后更新lastAns\n// 真实u = 给定u ^ lastAns\n// 真实v = 给定v\n// 真实k = 给定k\n// 1 <= n、m <= 10^5\n// 1 <= arr[i] <= 2^32 - 1\n// 测试链接 : https://www.luogu.com.cn/problem/P2633\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXP = 20;\n//const int MAXT = MAXN * MAXP;\n//int n, m, s;\n//int arr[MAXN];\n//int sorted[MAXN];\n//\n//int head[MAXN];\n//int to[MAXN << 1];\n//int nxt[MAXN << 1];\n//int cntg = 0;\n//\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int siz[MAXT];\n//int cntt = 0;\n//\n//int deep[MAXN];\n//int stjump[MAXN][MAXP];\n//\n//int kth(int num) {\n//    int left = 1, right = s, mid;\n//    while (left <= right) {\n//        mid = (left + right) / 2;\n//        if (sorted[mid] == num) {\n//            return mid;\n//        } else if (sorted[mid] < num) {\n//            left = mid + 1;\n//        } else {\n//            right = mid - 1;\n//        }\n//    }\n//    return -1;\n//}\n//\n//int build(int l, int r) {\n//    int rt = ++cntt;\n//    siz[rt] = 0;\n//    if (l < r) {\n//        int mid = (l + r) / 2;\n//        ls[rt] = build(l, mid);\n//        rs[rt] = build(mid + 1, r);\n//    }\n//    return rt;\n//}\n//\n//void prepare() {\n//    for (int i = 1; i <= n; i++) {\n//        sorted[i] = arr[i];\n//    }\n//    sort(sorted + 1, sorted + n + 1);\n//    s = 1;\n//    for (int i = 2; i <= n; i++) {\n//        if (sorted[s] != sorted[i]) {\n//            sorted[++s] = sorted[i];\n//        }\n//    }\n//    root[0] = build(1, s);\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//int insert(int jobi, int l, int r, int i) {\n//    int rt = ++cntt;\n//    ls[rt] = ls[i];\n//    rs[rt] = rs[i];\n//    siz[rt] = siz[i] + 1;\n//    if (l < r) {\n//        int mid = (l +