  addEdge(fa, i);\n//        addEdge(i, fa);\n//    }\n//    compute();\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_NeverLand1.java`\n\n```java\npackage class181;\n\n// 永无乡，java版\n// 一共有n个岛，每个岛分配到一个不同的数字，数字范围1~n\n// 给定初始的m座桥梁，若干点会连通起来，接下来有q条操作，格式如下\n// 操作 B x y : x号岛和y号岛之间新修建了一座桥\n// 操作 Q x k : x号岛所在的连通区里，打印第k小的数字来自几号岛，不存在打印-1\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3224\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_NeverLand1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXT = MAXN * 40;\n\tpublic static int n, m, q;\n\n\t// pos[v] = i，表示数字v属于第i号岛\n\tpublic static int[] pos = new int[MAXN];\n\t// 并查集\n\tpublic static int[] father = new int[MAXN];\n\n\t// 权值线段树\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] siz = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static void up(int i) {\n\t\tsiz[i] = siz[ls[i]] + siz[rs[i]];\n\t}\n\n\tpublic static int add(int jobi, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[rt]++;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsiz[t1] += siz[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int jobk, int l, int r, int i) {\n\t\tif (i == 0 || jobk > siz[i]) {\n\t\t\treturn -1;\n\t\t}\n\t\tif (l == r) {\n\t\t\treturn pos[l];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (siz[ls[i]] >= jobk) {\n\t\t\treturn query(jobk, l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(jobk - siz[ls[i]], mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != father[i]) {\n\t\t\tfather[i] = find(father[i]);\n\t\t}\n\t\treturn father[i];\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint xfa = find(x);\n\t\tint yfa = find(y);\n\t\tif (xfa != yfa) {\n\t\t\tfather[xfa] = yfa;\n\t\t\troot[yfa] = merge(1, n, root[yfa], root[xfa]);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tint num;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tnum = in.nextInt();\n\t\t\tpos[num] = i;\n\t\t\tfather[i] = i;\n\t\t\troot[i] = add(num, 1, n, root[i]);\n\t\t}\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tx = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\tunion(x, y);\n\t\t}\n\t\tq = in.nextInt();\n\t\tchar op;\n\t\tint x, y, k;\n\t\tfor (int i = 1; i <= q; i++) {\n\t\t\top = in.nextChar();\n\t\t\tif (op == 'B') {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tunion(x, y);\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\tk = in.nextInt();\n\t\t\t\tout.println(query(k, 1, n, root[find(x)]));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_NeverLand2.java`\n\n```java\npackage class181;\n\n// 永无乡，C++版\n// 一共有n个岛，每个岛分配到一个不同的数字，数字范围1~n\n// 给定初始的m座桥梁，若干点会连通起来，接下来有q条操作，格式如下\n// 操作 B x y : x号岛和y号岛之间新修建了一座桥\n// 操作 Q x k : x号岛所在的连通区里，打印第k小的数字来自几号岛，不存在打印-1\n// 1 <= n、m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3224\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXT = MAXN * 40;\n//int n, m, q;\n//int pos[MAXN];\n//int father[MAXN];\n//\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int siz[MAXT];\n//int cntt;\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]];\n//}\n//\n//int add(int jobi, int l, int r, int i) {\n//    int rt = i;\n//    if (rt == 0) {\n//        rt = ++cntt;\n//    }\n//    if (l == r) {\n//        siz[rt]++;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            ls[rt] = add(jobi, l, mid, ls[rt]);\n//        } else {\n//            rs[rt] = add(jobi, mid + 1, r, rs[rt]);\n//        }\n//        up(rt);\n//    }\n//    return rt;\n//}\n//\n//int merge(int l, int r, int t1, int t2) {\n//    if (t1 == 0 || t2 == 0) {\n//        return t1 + t2;\n//    }\n//    if (l == r) {\n//        siz[t1] += siz[t2];\n//    } else {\n//        int mid = (l + r) >> 1;\n//        ls[t1] = merge(l, mid, ls[t1], ls[t2]);\n//        rs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n//        up(t1);\n//    }\n//    return t1;\n//}\n//\n//int query(int jobk, int l, int r, int i) {\n//    if (i == 0 || jobk > siz[i]) {\n//        return -1;\n//    }\n//    if (l == r) {\n//        return pos[l];\n//    }\n//    int mid = (l + r) >> 1;\n//    if (siz[ls[i]] >= jobk) {\n//        return query(jobk, l, mid, ls[i]);\n//    } else {\n//        return query(jobk - siz[ls[i]], mid + 1, r, rs[i]);\n//    }\n//}\n//\n//int find(int i) {\n//    if (i != father[i]) {\n//        father[i] = find(father[i]);\n//    }\n//    return father[i];\n//}\n//\n//void Union(int x, int y) {\n//    int xfa = find(x);\n//    int yfa = find(y);\n//    if (xfa != yfa) {\n//        father[xfa] = yfa;\n//        root[yfa] = merge(1, n, root[yfa], root[xfa]);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, num; i <= n; i++) {\n//        cin >> num;\n//        pos[num] = i;\n//        father[i] = i;\n//        root[i] = add(num, 1, n, root[i]);\n//    }\n//    for (int i = 1, x, y; i <= m; i++) {\n//        cin >> x >> y;\n//        Union(x, y);\n//    }\n//    cin >> q;\n//    char op;\n//    int x, y, k;\n//    for (int i = 1; i <= q; i++) {\n//        cin >> op;\n//        if (op == 'B') {\n//            cin >> x >> y;\n//            Union(x, y);\n//        } else {\n//            cin >> x >> k;\n//            cout << query(k, 1, n, root[find(x)]) << '\\n';\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_RainyDayTail1.java`\n\n```java\npackage class181;\n\n// 雨天的尾巴，java版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树\n// 给定m条路径，格式 x y v，表示x到y路径上的每个点都收到一个数字v\n// 打印第i号点上，收到次数最多的数字，如果不止一种，打印值最小的数字\n// 如果某节点没有收到过数字，打印0\n// 一共n条打印\n// 1 <= n、m、v <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4556\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_RainyDayTail1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXV = 100000;\n\tpublic static int MAXT = MAXN * 50;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] maxCnt = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 递归改迭代需要\n\tpublic static int[][] ufe = new int[MAXN][3];\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改迭代\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void up(int i) {\n\t\tmaxCnt[i] = Math.max(maxCnt[ls[i]], maxCnt[rs[i]]);\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxCnt[rt] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tmaxCnt[t1] += maxCnt[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (maxCnt[ls[i]] >= maxCnt[rs[i]]) {\n\t\t\treturn query(l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void calc1(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcalc1(v, u);\n\t\t\t\troot[u] = merge(1, MAXV, root[u], root[v]);\n\t\t\t}\n\t\t}\n\t\tif (maxCnt[root[u]] == 0) {\n\t\t\tans[u] = 0;\n\t\t} else {\n\t\t\tans[u] = query(1, MAXV, root[u]);\n\t\t}\n\t}\n\n\t// calc1改迭代\n\tpublic static void calc2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\troot[u] = merge(1, MAXV, root[u], root[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (maxCnt[root[u]] == 0) {\n\t\t\t\t\tans[u] = 0;\n\t\t\t\t} else {\n\t\t\t\t\tans[u] = query(1, MAXV, root[u]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tint v = in.nextInt();\n\t\t\tint lca = getLca(x, y);\n\t\t\tint lcafa = stjump[lca][0];\n\t\t\troot[x] = add(v, 1, 1, MAXV, root[x]);\n\t\t\troot[y] = add(v, 1, 1, MAXV, root[y]);\n\t\t\troot[lca] = add(v, -1, 1, MAXV, root[lca]);\n\t\t\troot[lcafa] = add(v, -1, 1, MAXV, root[lcafa]);\n\t\t}\n\t\t// calc1(1, 0);\n\t\tcalc2();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.println(ans[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_RainyDayTail2.java`\n\n```java\npackage class181;\n\n// 雨天的尾巴，C++版\n// 一共有n个节点，给定n-1条边，所有节点组成一棵树\n// 给定m条路径，格式 x y v，表示x到y路径上的每个点都收到一个数字v\n// 打印第i号点上，收到次数最多的数字，如果不止一种，打印值最小的数字\n// 如果某节点没有收到过数字，打印0\n// 一共n条打印\n// 1 <= n、m、v <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P4556\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXV = 100000;\n//const int MAXT = MAXN * 50;\n//const int MAXP = 20;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int dep[MAXN];\n//int stjump[MAXN][MAXP];\n//\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int maxCnt[MAXT];\n//int cntt;\n//\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u, int fa) {\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            dfs(v, u);\n//        }\n//    }\n//}\n//\n//int getLca(int a, int b) {\n//    if (dep[a] < dep[b]) {\n//        swap(a, b);\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (dep[stjump[a][p]] >= dep[b]) {\n//            a = stjump[a][p];\n//        }\n//    }\n//    if (a == b) {\n//        return a;\n//    }\n//    for (int p = MAXP - 1; p >= 0; p--) {\n//        if (stjump[a][p] != stjump[b][p]) {\n//            a = stjump[a][p];\n//            b = stjump[b][p];\n//        }\n//    }\n//    return stjump[a][0];\n//}\n//\n//void up(int i) {\n//    maxCnt[i] = max(maxCnt[ls[i]], maxCnt[rs[i]]);\n//}\n//\n//int add(int jobi, int jobv, int l, int r, int i) {\n//    int rt = i;\n//    if (rt == 0) {\n//        rt = ++cntt;\n//    }\n//    if (l == r) {\n//        maxCnt[rt] += jobv;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            ls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n//        } else {\n//            rs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n//        }\n//        up(rt);\n//    }\n//    return rt;\n//}\n//\n//int merge(int l, int r, int t1, int t2) {\n//    if (t1 == 0 || t2 == 0) {\n//        return t1 + t2;\n//    }\n//    if (l == r) {\n//        maxCnt[t1] += maxCnt[t2];\n//    } else {\n//        int mid = (l + r) >> 1;\n//        ls[t1] = merge(l, mid, ls[t1], ls[t2]);\n//        rs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n//        up(t1);\n//    }\n//    return t1;\n//}\n//\n//int query(int l, int r, int i) {\n//    if (l == r) {\n//        return l;\n//    }\n//    int mid = (l + r) >> 1;\n//    if (maxCnt[ls[i]] >= maxCnt[rs[i]]) {\n//        return query(l, mid, ls[i]);\n//    } else {\n//        return query(mid + 1, r, rs[i]);\n//    }\n//}\n//\n//void calc(int u, int fa) {\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            calc(v, u);\n//            root[u] = merge(1, MAXV, root[u], root[v]);\n//        }\n//    }\n//    if (maxCnt[root[u]] == 0) {\n//        ans[u] = 0;\n//    } else {\n//        ans[u] = query(1, MAXV, root[u]);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs(1, 0);\n//    for (int i = 1, x, y, v; i <= m; i++) {\n//        cin >> x >> y >> v;\n//        int lca = getLca(x, y);\n//        int lcafa = stjump[lca][0];\n//        root[x] = add(v, 1, 1, MAXV, root[x]);\n//        root[y] = add(v, 1, 1, MAXV, root[y]);\n//        root[lca] = add(v, -1, 1, MAXV, root[lca]);\n//        root[lcafa] = add(v, -1, 1, MAXV, root[lcafa]);\n//    }\n//    calc(1, 0);\n//    for (int i = 1; i <= n; i++) {\n//        cout << ans[i] << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_LoveRunning1.java`\n\n```java\npackage class181;\n\n// 天天爱跑步，java版\n// 一共有n个点，给定n-1条边，所有节点组成一棵树\n// 每个点上都有一个观察员，给出每个观察员的观测时刻w[i]\n// 给出m个跑步者的路线，格式 x y : 该跑步者出发时刻为0，从x跑到y\n// 任何跑步者通过任何一条边，耗时都是1秒\n// 某个跑步者到达i号点的时刻 == w[i]，那么该跑步者才会被i号点的观察员观测到\n// 打印i号点的观察员，能观测到多少人，一共n条打印\n// 1 <= n、m、w[i] <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1600\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_LoveRunning1 {\n\n\tpublic static int MAXN = 300001;\n\tpublic static int MAXT = MAXN * 50;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m;\n\tpublic static int[] w = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[][] stjump = new int[MAXN][MAXP];\n\n\tpublic static int[] rtUp = new int[MAXN];\n\tpublic static int[] rtDown = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int[] sum = new int[MAXT];\n\tpublic static int cntt;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 递归改迭代需要\n\tpublic static int[][] ufe = new int[MAXN][3];\n\tpublic static int stacksize, u, f, e;\n\n\tpublic static void push(int u, int f, int e) {\n\t\tufe[stacksize][0] = u;\n\t\tufe[stacksize][1] = f;\n\t\tufe[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tu = ufe[stacksize][0];\n\t\tf = ufe[stacksize][1];\n\t\te = ufe[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void dfs1(int u, int fa) {\n\t\tdep[u] = dep[fa] + 1;\n\t\tstjump[u][0] = fa;\n\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t}\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs1改迭代\n\tpublic static void dfs2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\tdep[u] = dep[f] + 1;\n\t\t\t\tstjump[u][0] = f;\n\t\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\t\tstjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n\t\t\t\t}\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int getLca(int a, int b) {\n\t\tif (dep[a] < dep[b]) {\n\t\t\tint tmp = a;\n\t\t\ta = b;\n\t\t\tb = tmp;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (dep[stjump[a][p]] >= dep[b]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t}\n\t\t}\n\t\tif (a == b) {\n\t\t\treturn a;\n\t\t}\n\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\tif (stjump[a][p] != stjump[b][p]) {\n\t\t\t\ta = stjump[a][p];\n\t\t\t\tb = stjump[b][p];\n\t\t\t}\n\t\t}\n\t\treturn stjump[a][0];\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[ls[i]] + sum[rs[i]];\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = ++cntt;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[rt] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[t1] += sum[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\treturn t1;\n\t}\n\n\tpublic static int query(int jobi, int l, int r, int i) {\n\t\tif (jobi < l || jobi > r || i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (l == r) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (jobi <= mid) {\n\t\t\treturn query(jobi, l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn query(jobi, mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void calc1(int u, int fa) {\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != fa) {\n\t\t\t\tcalc1(v, u);\n\t\t\t\trtUp[u] = merge(1, n, rtUp[u], rtUp[v]);\n\t\t\t\trtDown[u] = merge(-n, n, rtDown[u], rtDown[v]);\n\t\t\t}\n\t\t}\n\t\tans[u] = query(dep[u] + w[u], 1, n, rtUp[u]) + query(dep[u] - w[u], -n, n, rtDown[u]);\n\t}\n\n\t// calc1改迭代\n\tpublic static void calc2() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (e == -1) {\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tpush(u, f, e);\n\t\t\t\tif (to[e] != f) {\n\t\t\t\t\tpush(to[e], u, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int ei = head[u]; ei > 0; ei = nxt[ei]) {\n\t\t\t\t\tint v = to[ei];\n\t\t\t\t\tif (v != f) {\n\t\t\t\t\t\trtUp[u] = merge(1, n, rtUp[u], rtUp[v]);\n\t\t\t\t\t\trtDown[u] = merge(-n, n, rtDown[u], rtDown[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans[u] = query(dep[u] + w[u], 1, n, rtUp[u]) + query(dep[u] - w[u], -n, n, rtDown[u]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tw[i] = in.nextInt();\n\t\t}\n\t\t// dfs1(1, 0);\n\t\tdfs2();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint x = in.nextInt();\n\t\t\tint y = in.nextInt();\n\t\t\tint lca = getLca(x, y);\n\t\t\tint lcafa = stjump[lca][0];\n\t\t\trtUp[x] = add(dep[x], 1, 1, n, rtUp[x]);\n\t\t\trtUp[lcafa] = add(dep[x], -1, 1, n, rtUp[lcafa]);\n\t\t\trtDown[y] = add(2 * dep[lca] - dep[x], 1, -n, n, rtDown[y]);\n\t\t\trtDown[lca] = add(2 * dep[lca] - dep[x], -1, -n, n, rtDown[lca]);\n\t\t}\n\t\t// calc1(1, 0);\n\t\tcalc2();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_LoveRunning2.java`\n\n```java\npackage class181;\n\n// 天天爱跑步，C++版\n// 一共有n个点，给定n-1条边，所有节点组成一棵树\n// 每个点上都有一个观察员，给出每个观察员的观测时刻w[i]\n// 给出m个跑步者的路线，格式 x y : 该跑步者出发时刻为0，从x跑到y\n// 任何跑步者通过任何一条边，耗时都是1秒\n// 某个跑步者到达i号点的时刻 == w[i]，那么该跑步者才会被i号点的观察员观测到\n// 打印i号点的观察员，能观测到多少人，一共n条打印\n// 1 <= n、m、w[i] <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1600\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 300001;\n//const int MAXT = MAXN * 50;\n//const int MAXP = 20;\n//int n, m;\n//int w[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg;\n//\n//int dep[MAXN];\n//int stjump[MAXN][MAXP];\n//int rtUp[MAXN];\n//int rtDown[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int sum[MAXT];\n//int cntt;\n//\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs(int u, int fa) {\n//    dep[u] = dep[fa] + 1;\n//    stjump[u][0] = fa;\n//    for (int p = 1; p < MAXP; p++) {\n//        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];\n//    }\n//    for (int e = head[u]; e; e = nxt[e]) {\n//        int v = to[e];\n//        if (v != fa) {\n//            df