n >> x >> y;\n//        if (dep[x] > maxdep[y]) {\n//            maxdep[y] = dep[x];\n//        }\n//    }\n//    dp(1, 0);\n//    long long ans = query(0, 0, 0, n, root[1]) % MOD;\n//    cout << ans << '\\n';\n//    return 0;\n//}\n```\n\n### `Code04_SegmentTreeSplit1.java`\n\n```java\npackage class182;\n\n// 线段树分裂，java版\n// 数字范围1~n，给定每种数字的个数，建立编号为1的可重集合，以后新集合的编号自增即可\n// 接下来有m条操作，每条操作是如下五种类型中的一种\n// 操作 0 x y z : x号集合中，取出[y, z]范围上的所有数字，生成新的集合\n// 操作 1 x y   : x号集合与y号集合合并，以后y编号的集合不会使用了\n// 操作 2 x y z : x号集合中，加入y个数字z\n// 操作 3 x y z : x号集合中，查询[y, z]范围上的数字个数\n// 操作 4 x y   : x号集合中，查询第y小的数字，不存在打印-1\n// 1 <= 所有数据 <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5494\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_SegmentTreeSplit1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = MAXN * 10;\n\tpublic static int n, m;\n\n\tpublic static int[] root = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static long[] sum = new long[MAXT];\n\tpublic static int version;\n\n\tpublic static int[] pool = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static void prepare() {\n\t\ttop = 0;\n\t\tfor (int i = 1; i < MAXT; i++) {\n\t\t\tpool[++top] = i;\n\t\t}\n\t}\n\n\tpublic static int newNode() {\n\t\treturn pool[top--];\n\t}\n\n\tpublic static void del(int i) {\n\t\tpool[++top] = i;\n\t\tls[i] = 0;\n\t\trs[i] = 0;\n\t\tsum[i] = 0;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = (sum[ls[i]] + sum[rs[i]]);\n\t}\n\n\tpublic static int add(int jobi, int jobv, int l, int r, int i) {\n\t\tint rt = i;\n\t\tif (rt == 0) {\n\t\t\trt = newNode();\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[rt] += jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n\t\t\t}\n\t\t\tup(rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, ls[i]);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, rs[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int kth(long jobk, int l, int r, int i) {\n\t\tif (i == 0) {\n\t\t\treturn -1;\n\t\t}\n\t\tif (l == r) {\n\t\t\treturn l;\n\t\t}\n\t\tint mid = (l + r) >> 1;\n\t\tif (sum[ls[i]] >= jobk) {\n\t\t\treturn kth(jobk, l, mid, ls[i]);\n\t\t} else {\n\t\t\treturn kth(jobk - sum[ls[i]], mid + 1, r, rs[i]);\n\t\t}\n\t}\n\n\tpublic static int merge(int l, int r, int t1, int t2) {\n\t\tif (t1 == 0 || t2 == 0) {\n\t\t\treturn t1 + t2;\n\t\t}\n\t\tif (l == r) {\n\t\t\tsum[t1] += sum[t2];\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[t1] = merge(l, mid, ls[t1], ls[t2]);\n\t\t\trs[t1] = merge(mid + 1, r, rs[t1], rs[t2]);\n\t\t\tup(t1);\n\t\t}\n\t\tdel(t2);\n\t\treturn t1;\n\t}\n\n\tpublic static int tree1, tree2;\n\n\tpublic static void split(int jobl, int jobr, int l, int r, int t1) {\n\t\tif (t1 == 0) {\n\t\t\ttree1 = t1;\n\t\t\ttree2 = 0;\n\t\t\treturn;\n\t\t}\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\ttree1 = 0;\n\t\t\ttree2 = t1;\n\t\t\treturn;\n\t\t}\n\t\tint t2 = newNode();\n\t\tint mid = (l + r) >> 1;\n\t\tif (jobl <= mid) {\n\t\t\tsplit(jobl, jobr, l, mid, ls[t1]);\n\t\t\tls[t1] = tree1;\n\t\t\tls[t2] = tree2;\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tsplit(jobl, jobr, mid + 1, r, rs[t1]);\n\t\t\trs[t1] = tree1;\n\t\t\trs[t2] = tree2;\n\t\t}\n\t\tup(t1);\n\t\tup(t2);\n\t\ttree1 = t1;\n\t\ttree2 = t2;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tprepare();\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tversion = 1;\n\t\tfor (int i = 1, x; i <= n; i++) {\n\t\t\tx = in.nextInt();\n\t\t\troot[version] = add(i, x, 1, n, root[1]);\n\t\t}\n\t\tfor (int i = 1, op, x, y, z; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tsplit(y, z, 1, n, root[x]);\n\t\t\t\troot[x] = tree1;\n\t\t\t\troot[++version] = tree2;\n\t\t\t} else if (op == 1) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\troot[x] = merge(1, n, root[x], root[y]);\n\t\t\t} else if (op == 2) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\troot[x] = add(z, y, 1, n, root[x]);\n\t\t\t} else if (op == 3) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tz = in.nextInt();\n\t\t\t\tout.println(query(y, z, 1, n, root[x]));\n\t\t\t} else {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tout.println(kth(y, 1, n, root[x]));\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_SegmentTreeSplit2.java`\n\n```java\npackage class182;\n\n// 线段树分裂，C++版\n// 数字范围1~n，给定每种数字的个数，建立编号为1的可重集合，以后新集合的编号自增即可\n// 接下来有m条操作，每条操作是如下五种类型中的一种\n// 操作 0 x y z : x号集合中，取出[y, z]范围上的所有数字，生成新的集合\n// 操作 1 x y   : x号集合与y号集合合并，以后y编号的集合不会使用了\n// 操作 2 x y z : x号集合中，加入y个数字z\n// 操作 3 x y z : x号集合中，查询[y, z]范围上的数字个数\n// 操作 4 x y   : x号集合中，查询第y小的数字，不存在打印-1\n// 1 <= 所有数据 <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P5494\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXT = MAXN * 10;\n//int n, m;\n//\n//int root[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//long long sum[MAXT];\n//int version;\n//\n//int pool[MAXT];\n//int top;\n//\n//void prepare() {\n//    top = 0;\n//    for (int i = 1; i < MAXT; i++) {\n//        pool[++top] = i;\n//    }\n//}\n//\n//int newNode() {\n//    return pool[top--];\n//}\n//\n//void del(int i) {\n//    pool[++top] = i;\n//    ls[i] = 0;\n//    rs[i] = 0;\n//    sum[i] = 0;\n//}\n//\n//void up(int i) {\n//    sum[i] = (sum[ls[i]] + sum[rs[i]]);\n//}\n//\n//int add(int jobi, int jobv, int l, int r, int i) {\n//    int rt = i;\n//    if (rt == 0) {\n//        rt = newNode();\n//    }\n//    if (l == r) {\n//        sum[rt] += jobv;\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobi <= mid) {\n//            ls[rt] = add(jobi, jobv, l, mid, ls[rt]);\n//        } else {\n//            rs[rt] = add(jobi, jobv, mid + 1, r, rs[rt]);\n//        }\n//        up(rt);\n//    }\n//    return rt;\n//}\n//\n//long long query(int jobl, int jobr, int l, int r, int i) {\n//    if (i == 0) {\n//        return 0;\n//    }\n//    if (jobl <= l && r <= jobr) {\n//        return sum[i];\n//    }\n//    int mid = (l + r) >> 1;\n//    long long ans = 0;\n//    if (jobl <= mid) {\n//        ans += query(jobl, jobr, l, mid, ls[i]);\n//    }\n//    if (jobr > mid) {\n//        ans += query(jobl, jobr, mid + 1, r, rs[i]);\n//    }\n//   