   if (ans1 != ans2) {\n//                    cout << "出错了!" << endl;\n//                }\n//            }\n//        }\n//        clear();\n//        cout << "测试结束" << endl;\n//        cout << "=======" << endl;\n//    }\n//    return 0;\n//}\n```\n\n### `Code01_Fenwick_Tree_Optimization_java.java`\n\n```java\npackage class198;\n\n// 树状数组优化建图，java版\n// 点的编号范围1~n，点权范围1~v，初始时袋子为空，没有任何边，实现如下方法\n// add(x, xv)，编号为x、点权为xv的点进入袋子，该编号已经入袋则忽略\n// rangeToX(p, x, w)，袋中点权范围1~p的每个点，向点x连边权为w的边\n// xToRange(x, p, w)，点x向袋中点权范围1~p的每个点，连边权为w的边\n// rangeToRange(p1, p2, w)，范围向范围连边，具体含义如下\n// 袋中点权1~p1的每个点，向袋中点权1~p2的每个点，连边权为w的边\n// 建好图之后可以测试图的任何算法，比如dijkstra算法求最短路\n// 对数器验证\n\nimport java.util.PriorityQueue;\n\npublic class Code01_Fenwick_Tree_Optimization_java {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int MAXV = 1001;\n\tpublic static int MAXT = 10001;\n\tpublic static int MAXE = 10001;\n\tpublic static int n, v, cntt;\n\n\tpublic static boolean[] inBag = new boolean[MAXN];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int[] weight = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] outTree = new int[MAXV];\n\tpublic static int[] inTree = new int[MAXV];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void addOut(int x, int xv) {\n\t\twhile (xv <= v) {\n\t\t\tint preo = outTree[xv];\n\t\t\tint curo = ++cntt;\n\t\t\tif (preo > 0) {\n\t\t\t\taddEdge(preo, curo, 0);\n\t\t\t}\n\t\t\taddEdge(x, curo, 0);\n\t\t\toutTree[xv] = curo;\n\t\t\txv += lowbit(xv);\n\t\t}\n\t}\n\n\tpublic static void addIn(int x, int xv) {\n\t\twhile (xv <= v) {\n\t\t\tint prei = inTree[xv];\n\t\t\tint curi = ++cntt;\n\t\t\tif (prei > 0) {\n\t\t\t\taddEdge(curi, prei, 0);\n\t\t\t}\n\t\t\taddEdge(curi, x, 0);\n\t\t\tinTree[xv] = curi;\n\t\t\txv += lowbit(xv);\n\t\t}\n\t}\n\n\tpublic static void add(int x, int xv) {\n\t\tif (!inBag[x]) {\n\t\t\tinBag[x] = true;\n\t\t\taddOut(x, xv);\n\t\t\taddIn(x, xv);\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int p, int x, int w) {\n\t\twhile (p > 0) {\n\t\t\tif (outTree[p] > 0) {\n\t\t\t\taddEdge(outTree[p], x, w);\n\t\t\t}\n\t\t\tp -= lowbit(p);\n\t\t}\n\t}\n\n\tpublic static void xToRange(int x, int p, int w) {\n\t\twhile (p > 0) {\n\t\t\tif (inTree[p] > 0) {\n\t\t\t\taddEdge(x, inTree[p], w);\n\t\t\t}\n\t\t\tp -= lowbit(p);\n\t\t}\n\t}\n\n\tpublic static void rangeToRange(int p1, int p2, int w) {\n\t\tint x = ++cntt;\n\t\tint y = ++cntt;\n\t\trangeToX(p1, x, 0);\n\t\txToRange(y, p2, 0);\n\t\taddEdge(x, y, w);\n\t}\n\n\tpublic static int MAX_2 = 100001;\n\tpublic static boolean[] in_bag_2 = new boolean[MAX_2];\n\tpublic static int[] bag_id = new int[MAX_2];\n\tpublic static int[] bag_val = new int[MAX_2];\n\tpublic static int bag_siz;\n\n\tpublic static int[] head_2 = new int[MAX_2];\n\tpublic static int[] nxt_2 = new int[MAX_2];\n\tpublic static int[] to_2 = new int[MAX_2];\n\tpublic static int[] weight_2 = new int[MAX_2];\n\tpublic static int cnt_2;\n\n\tpublic static void addEdge_2(int u, int v, int w) {\n\t\tnxt_2[++cnt_2] = head_2[u];\n\t\tto_2[cnt_2] = v;\n\t\tweight_2[cnt_2] = w;\n\t\thead_2[u] = cnt_2;\n\t}\n\n\tpublic static void add_2(int x, int xv) {\n\t\tif (!in_bag_2[x]) {\n\t\t\tin_bag_2[x] = true;\n\t\t\tbag_id[++bag_siz] = x;\n\t\t\tbag_val[bag_siz] = xv;\n\t\t}\n\t}\n\n\tpublic static void rangeToX_2(int p, int x, int w) {\n\t\tfor (int i = 1; i <= bag_siz; i++) {\n\t\t\tif (bag_val[i] <= p) {\n\t\t\t\taddEdge_2(bag_id[i], x, w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void xToRange_2(int x, int p, int w) {\n\t\tfor (int i = 1; i <= bag_siz; i++) {\n\t\t\tif (bag_val[i] <= p) {\n\t\t\t\taddEdge_2(x, bag_id[i], w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToRange_2(int p1, int p2, int w) {\n\t\tfor (int i = 1; i <= bag_siz; i++) {\n\t\t\tif (bag_val[i] <= p1) {\n\t\t\t\tfor (int j = 1; j <= bag_siz; j++) {\n\t\t\t\t\tif (bag_val[j] <= p2) {\n\t\t\t\t\t\taddEdge_2(bag_id[i], bag_id[j], w);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int INF = 1000000001;\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static boolean[] vis = new boolean[MAXT];\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> x[1] - y[1]);\n\n\tpublic static int dijkstra(int s, int t) {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\t\tint v = to[e];\n\t\t\t\t\tint w = weight[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int dijkstra2(int s, int t) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head_2[u]; e > 0; e = nxt_2[e]) {\n\t\t\t\t\tint v = to_2[e];\n\t\t\t\t\tint w = weight_2[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int random(int maxv) {\n\t\treturn (int) (Math.random() * maxv) + 1;\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tcntg = 0;\n\t\tcntt = 0;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tinTree[i] = 0;\n\t\t\toutTree[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tinBag[i] = false;\n\t\t\tin_bag_2[i] = false;\n\t\t\thead_2[i] = 0;\n\t\t}\n\t\tbag_siz = 0;\n\t\tcnt_2 = 0;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("树状数组优化建图");\n\t\tSystem.out.println("============");\n\t\tn = 100;\n\t\tv = 200;\n\t\tint weightMax = 1000;\n\t\tint round = 20;\n\t\tfor (int t = 1; t <= round; t++) {\n\t\t\tSystem.out.println("第" + t + "轮");\n\t\t\tSystem.out.println("测试开始");\n\t\t\tcntt = n;\n\t\t\tint opCnt = 200;\n\t\t\tfor (int i = 1; i <= opCnt; i++) {\n\t\t\t\tint op = random(4);\n\t\t\t\tif (op == 1) {\n\t\t\t\t\tint x = random(n);\n\t\t\t\t\tint xv = random(v);\n\t\t\t\t\tadd(x, xv);\n\t\t\t\t\tadd_2(x, xv);\n\t\t\t\t} else {\n\t\t\t\t\tint p = random(v);\n\t\t\t\t\tint p2 = random(v);\n\t\t\t\t\tint x = random(n);\n\t\t\t\t\tint w = random(weightMax);\n\t\t\t\t\tif (op == 2) {\n\t\t\t\t\t\trangeToX(p, x, w);\n\t\t\t\t\t\trangeToX_2(p, x, w);\n\t\t\t\t\t} else if (op == 3) {\n\t\t\t\t\t\txToRange(x, p, w);\n\t\t\t\t\t\txToRange_2(x, p, w);\n\t\t\t\t\t} else {\n\t\t\t\t\t\trangeToRange(p, p2, w);\n\t\t\t\t\t\trangeToRange_2(p, p2, w);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int x = 1; x <= n; x++) {\n\t\t\t\tfor (int y = 1; y <= n; y++) {\n\t\t\t\t\tint ans1 = dijkstra(x, y);\n\t\t\t\t\tint ans2 = dijkstra2(x, y);\n\t\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tclear();\n\t\t\tSystem.out.println("测试结束");\n\t\t\tSystem.out.println("=======");\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_Persistent_Segment_Tree_Optimization_cpp.java`\n\n```java\npackage class198;\n\n// 主席树优化建图，C++版\n// 点的编号范围1~n，点权范围1~v，初始时袋子为空，没有任何边，实现如下方法\n// add(x, xv)，编号为x、点权为xv的点进入袋子，该编号已经入袋则忽略\n// rangeToX(l, r, x, w)，袋中点权范围l~r的每个点，向点x连边权为w的边\n// xToRange(x, l, r, w)，点x向袋中点权范围l~r的每个点，连边权为w的边\n// rangeToRange(l1, r1, l2, r2, w)，范围向范围连边，具体含义如下\n// 袋中点权l1~r1的每个点，向袋中点权l2~r2的每个点，连边权为w的边\n// 建好图之后可以测试图的任何算法，比如dijkstra算法求最短路\n// 如下代码在C++环境运行，可以通过对数器验证\n// C++版本和java版本逻辑完全一样\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 1001;\n//const int MAXV = 1001;\n//const int MAXT = 10001;\n//const int MAXE = 10001;\n//int n, v, cntt;\n//\n//bool inBag[MAXN];\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int weight[MAXE];\n//int cntg;\n//\n//int rootOut[MAXN];\n//int rootIn[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//int curVersion;\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//int buildOut(int l, int r) {\n//    int rt = ++cntt;\n//    if (l < r) {\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildOut(l, mid);\n//        rs[rt] = buildOut(mid + 1, r);\n//        addEdge(ls[rt], rt, 0);\n//        addEdge(rs[rt], rt, 0);\n//    }\n//    return rt;\n//}\n//\n//int buildIn(int l, int r) {\n//    int rt = ++cntt;\n//    if (l < r) {\n//        int mid = (l + r) >> 1;\n//        ls[rt] = buildIn(l, mid);\n//        rs[rt] = buildIn(mid + 1, r);\n//        addEdge(rt, ls[rt], 0);\n//        addEdge(rt, rs[rt], 0);\n//    }\n//    return rt;\n//}\n//\n//int addOut(int jobx, int jobv, int l, int r, int i) {\n//    int rt = ++cntt;\n//    ls[rt] = ls[i];\n//    rs[rt] = rs[i];\n//    addEdge(i, rt, 0);\n//    if (l == r) {\n//        addEdge(jobx, rt, 0);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobv <= mid) {\n//            ls[rt] = addOut(jobx, jobv, l, mid, ls[rt]);\n//            addEdge(ls[rt], rt, 0);\n//        } else {\n//            rs[rt] = addOut(jobx, jobv, mid + 1, r, rs[rt]);\n//            addEdge(rs[rt], rt, 0);\n//        }\n//    }\n//    return rt;\n//}\n//\n//int addIn(int jobx, int jobv, int l, int r, int i) {\n//   