; i++, j++) {\n//        arr[i] = tmp[j];\n//    }\n//}\n//\n//void cdq(int l, int r) {\n//    if (l == r) {\n//        return;\n//    }\n//    int mid = (l + r) / 2;\n//    cdq(l, mid);\n//    cdq(mid + 1, r);\n//    merge(l, mid, r);\n//}\n//\n//void buildGraph() {\n//    for (int i = 1; i <= n; i++) {\n//        arr[i] = {i,a[i],b[i]};\n//    }\n//    sort(arr + 1, arr + n + 1, DataCmp);\n//    cntt = n;\n//    for (int l = 1, r = 1; l <= n; l = ++r) {\n//        int a = arr[l].a;\n//        int b = arr[l].b;\n//        while (r + 1 <= n && a == arr[r + 1].a && b == arr[r + 1].b) {\n//            r++;\n//        }\n//        int x = ++cntt;\n//        for (int i = l; i <= r; i++) {\n//            int u = arr[i].i;\n//            addEdge(u, x, 0);\n//            for (int e = headp[u]; e > 0; e = nextp[e]) {\n//                addEdge(x, u, weightp[e]);\n//                addOp(x, u, weightp[e]);\n//            }\n//        }\n//        arr[++cnta] = {x, a, b};\n//    }\n//    cdq(1, cnta);\n//}\n//\n//const int MAX_2 = 100001;\n//int head_2[MAX_2];\n//int nxt_2[MAX_2];\n//int to_2[MAX_2];\n//int weight_2[MAX_2];\n//int cnt_2;\n//\n//void addEdge_2(int u, int v, int w) {\n//    nxt_2[++cnt_2] = head_2[u];\n//    to_2[cnt_2] = v;\n//    weight_2[cnt_2] = w;\n//    head_2[u] = cnt_2;\n//}\n//\n//void link(int x, int w) {\n//    for (int i = 1; i <= n; i++) {\n//        if (a[i] <= a[x] && b[i] <= b[x]) {\n//            addEdge_2(i, x, w);\n//        }\n//    }\n//}\n//\n//struct Node {\n//    int u;\n//    int d;\n//\n//    bool operator < (const Node &other) const {\n//        return d > other.d;\n//    }\n//};\n//\n//const int INF = 1000000001;\n//int dist[MAXT];\n//bool vis[MAXT];\n//priority_queue<Node> heap;\n//\n//int dijkstra(int s, int t) {\n//    for (int i = 1; i <= cntt; i++) {\n//        dist[i] = INF;\n//        vis[i] = false;\n//    }\n//    while (!heap.empty()) {\n//        heap.pop();\n//    }\n//    dist[s] = 0;\n//    heap.push({s, 0});\n//    while (!heap.empty()) {\n//        Node cur = heap.top();\n//        heap.pop();\n//        int u = cur.u;\n//        int d = cur.d;\n//        if (u == t) {\n//            return d;\n//        }\n//        if (!vis[u]) {\n//            vis[u] = true;\n//            for (int e = headg[u]; e > 0; e = nextg[e]) {\n//                int v = tog[e];\n//                int w = weightg[e];\n//                if (!vis[v] && dist[v] > d + w) {\n//                    dist[v] = d + w;\n//                    heap.push({v, dist[v]});\n//                }\n//            }\n//        }\n//    }\n//    return -1;\n//}\n//\n//int dijkstra2(int s, int t) {\n//    for (int i = 1; i <= n; i++) {\n//        dist[i] = INF;\n//        vis[i] = false;\n//    }\n//    while (!heap.empty()) {\n//        heap.pop();\n//    }\n//    dist[s] = 0;\n//    heap.push({s, 0});\n//    while (!heap.empty()) {\n//        Node cur = heap.top();\n//        heap.pop();\n//        int u = cur.u;\n//        int d = cur.d;\n//        if (u == t) {\n//            return d;\n//        }\n//        if (!vis[u]) {\n//            vis[u] = true;\n//            for (int e = head_2[u]; e > 0; e = nxt_2[e]) {\n//                int v = to_2[e];\n//                int w = weight_2[e];\n//                if (!vis[v] && dist[v] > d + w) {\n//                    dist[v] = d + w;\n//                    heap.push({v, dist[v]});\n//                }\n//            }\n//        }\n//    }\n//    return -1;\n//}\n//\n//int random(int v) {\n//    return rand() % v + 1;\n//}\n//\n//void clear() {\n//    for (int i = 1; i <= cntt; i++) {\n//        headg[i] = headp[i] = 0;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        head_2[i] = 0;\n//    }\n//    cnta = cntg = cntp = cntt = cnt_2 = 0;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand((unsigned)time(nullptr));\n//    cout << "cdq优化建图，二维偏序" << endl;\n//    cout << "=============" << endl;\n//    n = 100;\n//    m = 1000;\n//    int valMax = 10;\n//    int weightMax = 10000;\n//    int round = 20;\n//    for (int t = 1; t <= round; t++) {\n//        cout << "第" << t << "轮" << endl;\n//        cout << "测试开始" << endl;\n//        for (int i = 1; i <= n; i++) {\n//            a[i] = random(valMax);\n//            b[i] = random(valMax);\n//        }\n//        for (int i = 1; i <= m; i++) {\n//            int x = random(n);\n//            int w = random(weightMax);\n//            addOp(x, x, w);\n//            link(x, w);\n//        }\n//        buildGraph();\n//        for (int x = 1; x <= n; x++) {\n//            for (int y = 1; y <= n; y++) {\n//                int ans1 = dijkstra(x, y);\n//                int ans2 = dijkstra2(x, y);\n//                if (ans1 != ans2) {\n//                    cout << "出错了!" << endl;\n//                }\n//            }\n//        }\n//        clear();\n//        cout << "测试结束" << endl;\n//        cout << "=======" << endl;\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_Cdq_Optimization_2D_java.java`\n\n```java\npackage class198;\n\n// cdq优化建图二维偏序，java版\n// 一共n个点，每个点给定两个点权，a[i]、b[i]，初始时没有边\n// 一共m条操作，格式 x w，每个满足如下要求的点，都向x连权值为w的边\n// 两种点权 <= x对应的点权，这样的点就算满足要求，注意x自己也是达标的\n// 建好图之后可以测试图的任何算法，比如dijkstra算法求最短路\n// 对数器验证\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\npublic class Code03_Cdq_Optimization_2D_java {\n\n\tpublic static int MAXN = 101;\n\tpublic static int MAXM = 1001;\n\tpublic static int MAXV = 10001;\n\tpublic static int MAXT = 100001;\n\tpublic static int MAXE = 100001;\n\tpublic static int n, m, cntt;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\n\t// i, a, b\n\tpublic static int[][] arr = new int[MAXN][3];\n\tpublic static int[][] tmp = new int[MAXN][3];\n\tpublic static int cnta;\n\n\t// 建图\n\tpublic static int[] headg = new int[MAXT];\n\tpublic static int[] nextg = new int[MAXE];\n\tpublic static int[] tog = new int[MAXE];\n\tpublic static int[] weightg = new int[MAXE];\n\tpublic static int cntg;\n\n\t// 每个小组的操作列表\n\tpublic static int[] headp = new int[MAXT];\n\tpublic static int[] nextp = new int[MAXM << 1];\n\tpublic static int[] top = new int[MAXM << 1];\n\tpublic static int[] weightp = new int[MAXM << 1];\n\tpublic static int cntp;\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\tweightg[cntg] = w;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addOp(int x, int u, int w) {\n\t\tnextp[++cntp] = headp[x];\n\t\ttop[cntp] = u;\n\t\tweightp[cntp] = w;\n\t\theadp[x] = cntp;\n\t}\n\n\tpublic static void clone(int[][] a, int i, int[][] b, int j) {\n\t\ta[i][0] = b[j][0];\n\t\ta[i][1] = b[j][1];\n\t\ta[i][2] = b[j][2];\n\t}\n\n\tpublic static void merge(int l, int mid, int r) {\n\t\tint pre = 0, cur = 0;\n\t\tfor (int p1 = l - 1, p2 = mid + 1; p2 <= r; p2++) {\n\t\t\tcur = ++cntt;\n\t\t\twhile (p1 + 1 <= mid && arr[p1 + 1][2] <= arr[p2][2]) {\n\t\t\t\tp1++;\n\t\t\t\taddEdge(arr[p1][0], cur, 0);\n\t\t\t}\n\t\t\tif (pre > 0) {\n\t\t\t\taddEdge(pre, cur, 0);\n\t\t\t}\n\t\t\tfor (int e = headp[arr[p2][0]]; e > 0; e = nextp[e]) {\n\t\t\t\tint u = top[e];\n\t\t\t\tint w = weightp[e];\n\t\t\t\taddEdge(cur, u, w);\n\t\t\t}\n\t\t\tpre = cur;\n\t\t}\n\t\tint p1 = l, p2 = mid + 1, ti = 0;\n\t\twhile (p1 <= mid && p2 <= r) {\n\t\t\tif (arr[p1][2] <= arr[p2][2]) {\n\t\t\t\tclone(tmp, ++ti, arr, p1++);\n\t\t\t} else {\n\t\t\t\tclone(tmp, ++ti, arr, p2++);\n\t\t\t}\n\t\t}\n\t\twhile (p1 <= mid) {\n\t\t\tclone(tmp, ++ti, arr, p1++);\n\t\t}\n\t\twhile (p2 <= r) {\n\t\t\tclone(tmp, ++ti, arr, p2++);\n\t\t}\n\t\tfor (int i = l, j = 1; i <= r; i++, j++) {\n\t\t\tclone(arr, i, tmp, j);\n\t\t}\n\t}\n\n\tpublic static void cdq(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid);\n\t\tcdq(mid + 1, r);\n\t\tmerge(l, mid, r);\n\t}\n\n\tpublic static void buildGraph() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = i;\n\t\t\tarr[i][1] = a[i];\n\t\t\tarr[i][2] = b[i];\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, (x, y) -> x[1] != y[1] ? x[1] - y[1] : x[2] - y[2]);\n\t\tcntt = n;\n\t\tfor (int l = 1, r = 1; l <= n; l = ++r) {\n\t\t\tint a = arr[l][1];\n\t\t\tint b = arr[l][2];\n\t\t\twhile (r + 1 <= n && a == arr[r + 1][1] && b == arr[r + 1][2]) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tint x = ++cntt;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tint u = arr[i][0];\n\t\t\t\taddEdge(u, x, 0);\n\t\t\t\tfor (int e = headp[u]; e > 0; e = nextp[e]) {\n\t\t\t\t\taddEdge(x, u, weightp[e]);\n\t\t\t\t\taddOp(x, u, weightp[e]);\n\t\t\t\t}\n\t\t\t}\n\t\t\tarr[++cnta][0] = x;\n\t\t\tarr[cnta][1] = a;\n\t\t\tarr[cnta][2] = b;\n\t\t}\n\t\tcdq(1, cnta);\n\t}\n\n\tpublic static int MAX_2 = 100001;\n\tpublic static int[] head_2 = new int[MAX_2];\n\tpublic static int[] nxt_2 = new int[MAX_2];\n\tpublic static int[] to_2 = new int[MAX_2];\n\tpublic static int[] weight_2 = new int[MAX_2];\n\tpublic static int cnt_2;\n\n\tpublic static void addEdge_2(int u, int v, int w) {\n\t\tnxt_2[++cnt_2] = head_2[u];\n\t\tto_2[cnt_2] = v;\n\t\tweight_2[cnt_2] = w;\n\t\thead_2[u] = cnt_2;\n\t}\n\n\tpublic static void link(int x, int w) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (a[i] <= a[x] && b[i] <= b[x]) {\n\t\t\t\taddEdge_2(i, x, w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int INF = 1000000001;\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static boolean[] vis = new boolean[MAXT];\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> x[1] - y[1]);\n\n\tpublic static int dijkstra(int s, int t) {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\t\t\tint v = tog[e];\n\t\t\t\t\tint w = weightg[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int dijkstra2(int s, int t) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head_2[u]; e > 0; e = nxt_2[e]) {\n\t\t\t\t\tint v = to_2[e];\n\t\t\t\t\tint w = weight_2[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int random(int v) {\n\t\treturn (int) (Math.random() * v) + 1;\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\theadg[i] = headp[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead_2[i] = 0;\n\t\t}\n\t\tcnta = cntg = cntp = cntt = cnt_2 = 0;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("cdq优化建图，二维偏序");\n\t\tSystem.out.println("=============");\n\t\tn = 100;\n\t\tm = 1000;\n\t\tint valMax = 10;\n\t\tint weightMax = 10000;\n\t\tint round = 20;\n\t\tfor (int t = 1; t <= round; t++) {\n\t\t\tSystem.out.println("第" + t + "轮");\n\t\t\tSystem.out.println("测试开始");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\ta[i] = random(valMax);\n\t\t\t\tb[i] = random(valMax);\n\t\t\t}\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint x = random(n);\n\t\t\t\tint w = random(weightMax);\n\t\t\t\taddOp(x, x, w);\n\t\t\t\tlink(x, w);\n\t\t\t}\n\t\t\tbuildGraph();\n\t\t\tfor (int x = 1; x <= n; x++) {\n\t\t\t\tfor (int y = 1; y <= n; y++) {\n\t\t\t\t\tint ans1 = dijkstra(x, y);\n\t\t\t\t\tint ans2 = dijkstra2(x, y);\n\t\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tclear();\n\t\t\tSystem.out.println("测试结束");\n\t\t\tSystem.out.println("=======");\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Cdq_Optimization_3D_cpp.java`\n\n```java\npackage class198;\n\n// cdq优化建图三维偏序，C++版\n// 一共n个点，每个点给定三个点权，a[i]、b[i]、c[i]，初始时没有边\n// 一共m条操作，格式 x w，每个满足如下要求的点，都向x连权值为w的边\n// 三种点权 <= x对应的点权，这样的点就算满足要求，注意x自己也是达标的\n// 建好图之后可以测试图的任何算法，比如dijkstra算法求最短路\n// 如下代码在C++环境运行，可以通过对数器验证\n// C++版本和java版本逻辑完全一样\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Data {\n//    int i, a, b, c;\n//};\n//\n//bool CmpABC(Data x, Data y) {\n//    if (x.a != y.a) {\n//        return x.a < y.a;\n//    }\n//    if (x.b != y.b) {\n//        return x.b < y.b;\n//    }\n//    return x.c < y.c;\n//}\n//\n//bool CmpB(Data x, Data y) {\n//    return x.b < y.b;\n//}\n//\n//const int MAXN = 101;\n//const int MAXM = 1001;\n//const int MAXV = 10001;\n//const int MAXT = 100001;\n//const int MAXE = 100001;\n//int n, m, maxc, cntt;\n//int a[MAXN];\n//int b[MAXN];\n//int c[MAXN];\n//\n//Data arr[MAXN];\n//int cnta;\n//\n//int headg[MAXT];\n//int nextg[MAXE];\n//int tog[MAXE];\n//int weightg[MAXE];\n//int cntg;\n//\n//int headp[MAXT];\n//int nextp[MAXM << 1];\n//int top[MAXM << 1];\n//int weightp[MAXM << 1];\n//int cntp;\n//\n//int tree[MAXV];\n//\n//void addEdge(int u, int v, int w) {\n//    nextg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    weightg[cntg] = w;\n//    headg[u] = cntg;\n//}\n//\n//void addOp(int x, int u, int w) {\n//    nextp[++cntp] = headp[x];\n//    top[cntp] = u;\n//    weightp[cntp] = w;\n//    headp[x] = cntp;\n//}\n//\n//int lowbit(int i) {\n//    return i & -i;\n//}\n//\n//void add(int i, int x) {\n//    while (i <= maxc) {\n//        int pre = tree[i];\n//        int cur = ++cntt;\n//        if (pre != 0) {\n//            addEdge(pre, cur, 0);\n//        }\n//        addEdge(x, 