1, cnta);\n//}\n//\n//const int MAX_2 = 100001;\n//int head_2[MAX_2];\n//int nxt_2[MAX_2];\n//int to_2[MAX_2];\n//int weight_2[MAX_2];\n//int cnt_2;\n//\n//void addEdge_2(int u, int v, int w) {\n//    nxt_2[++cnt_2] = head_2[u];\n//    to_2[cnt_2] = v;\n//    weight_2[cnt_2] = w;\n//    head_2[u] = cnt_2;\n//}\n//\n//void link(int x, int w) {\n//    for (int i = 1; i <= n; i++) {\n//        if (a[i] <= a[x] && b[i] <= b[x] && c[i] <= c[x]) {\n//            addEdge_2(i, x, w);\n//        }\n//    }\n//}\n//\n//struct Node {\n//    int u;\n//    int d;\n//\n//    bool operator < (const Node &other) const {\n//        return d > other.d;\n//    }\n//};\n//\n//const int INF = 1000000001;\n//int dist[MAXT];\n//bool vis[MAXT];\n//priority_queue<Node> heap;\n//\n//int dijkstra(int s, int t) {\n//    for (int i = 1; i <= cntt; i++) {\n//        dist[i] = INF;\n//        vis[i] = false;\n//    }\n//    while (!heap.empty()) {\n//        heap.pop();\n//    }\n//    dist[s] = 0;\n//    heap.push({s, 0});\n//    while (!heap.empty()) {\n//        Node cur = heap.top();\n//        heap.pop();\n//        int u = cur.u;\n//        int d = cur.d;\n//        if (u == t) {\n//            return d;\n//        }\n//        if (!vis[u]) {\n//            vis[u] = true;\n//            for (int e = headg[u]; e > 0; e = nextg[e]) {\n//                int v = tog[e];\n//                int w = weightg[e];\n//                if (!vis[v] && dist[v] > d + w) {\n//                    dist[v] = d + w;\n//                    heap.push({v, dist[v]});\n//                }\n//            }\n//        }\n//    }\n//    return -1;\n//}\n//\n//int dijkstra2(int s, int t) {\n//    for (int i = 1; i <= n; i++) {\n//        dist[i] = INF;\n//        vis[i] = false;\n//    }\n//    while (!heap.empty()) {\n//        heap.pop();\n//    }\n//    dist[s] = 0;\n//    heap.push({s, 0});\n//    while (!heap.empty()) {\n//        Node cur = heap.top();\n//        heap.pop();\n//        int u = cur.u;\n//        int d = cur.d;\n//        if (u == t) {\n//            return d;\n//        }\n//        if (!vis[u]) {\n//            vis[u] = true;\n//            for (int e = head_2[u]; e > 0; e = nxt_2[e]) {\n//                int v = to_2[e];\n//                int w = weight_2[e];\n//                if (!vis[v] && dist[v] > d + w) {\n//                    dist[v] = d + w;\n//                    heap.push({v, dist[v]});\n//                }\n//            }\n//        }\n//    }\n//    return -1;\n//}\n//\n//int random(int v) {\n//    return rand() % v + 1;\n//}\n//\n//void clear() {\n//    for (int i = 1; i <= cntt; i++) {\n//        headg[i] = headp[i] = 0;\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        head_2[i] = 0;\n//    }\n//    maxc = cnta = cntg = cntp = cntt = cnt_2 = 0;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand((unsigned)time(nullptr));\n//    cout << "cdq优化建图，三维偏序" << endl;\n//    cout << "=============" << endl;\n//    n = 100;\n//    m = 1000;\n//    int valMax = 10;\n//    int weightMax = 10000;\n//    int round = 20;\n//    for (int t = 1; t <= round; t++) {\n//        cout << "第" << t << "轮" << endl;\n//        cout << "测试开始" << endl;\n//        for (int i = 1; i <= n; i++) {\n//            a[i] = random(valMax);\n//            b[i] = random(valMax);\n//            c[i] = random(valMax);\n//        }\n//        for (int i = 1; i <= m; i++) {\n//            int x = random(n);\n//            int w = random(weightMax);\n//            addOp(x, x, w);\n//            link(x, w);\n//        }\n//        buildGraph();\n//        for (int x = 1; x <= n; x++) {\n//            for (int y = 1; y <= n; y++) {\n//                int ans1 = dijkstra(x, y);\n//                int ans2 = dijkstra2(x, y);\n//                if (ans1 != ans2) {\n//                    cout << "出错了!" << endl;\n//                }\n//            }\n//        }\n//        clear();\n//        cout << "测试结束" << endl;\n//        cout << "=======" << endl;\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Cdq_Optimization_3D_java.java`\n\n```java\npackage class198;\n\n// cdq优化建图三维偏序，java版\n// 一共n个点，每个点给定三个点权，a[i]、b[i]、c[i]，初始时没有边\n// 一共m条操作，格式 x w，每个满足如下要求的点，都向x连权值为w的边\n// 三种点权 <= x对应的点权，这样的点就算满足要求，注意x自己也是达标的\n// 建好图之后可以测试图的任何算法，比如dijkstra算法求最短路\n// 对数器验证\n\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\npublic class Code04_Cdq_Optimization_3D_java {\n\n\tpublic static int MAXN = 101;\n\tpublic static int MAXM = 1001;\n\tpublic static int MAXV = 10001;\n\tpublic static int MAXT = 100001;\n\tpublic static int MAXE = 100001;\n\tpublic static int n, m, maxc, cntt;\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\tpublic static int[] c = new int[MAXN];\n\n\t// i、a、b、c\n\tpublic static int[][] arr = new int[MAXN][4];\n\tpublic static int cnta;\n\n\t// 建图\n\tpublic static int[] headg = new int[MAXT];\n\tpublic static int[] nextg = new int[MAXE];\n\tpublic static int[] tog = new int[MAXE];\n\tpublic static int[] weightg = new int[MAXE];\n\tpublic static int cntg;\n\n\t// 每个小组的操作列表\n\tpublic static int[] headp = new int[MAXT];\n\tpublic static int[] nextp = new int[MAXM << 1];\n\tpublic static int[] top = new int[MAXM << 1];\n\tpublic static int[] weightp = new int[MAXM << 1];\n\tpublic static int cntp;\n\n\t// 树状数组\n\tpublic static int[] tree = new int[MAXV];\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\tweightg[cntg] = w;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addOp(int x, int u, int w) {\n\t\tnextp[++cntp] = headp[x];\n\t\ttop[cntp] = u;\n\t\tweightp[cntp] = w;\n\t\theadp[x] = cntp;\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void add(int i, int x) {\n\t\twhile (i <= maxc) {\n\t\t\tint pre = tree[i];\n\t\t\tint cur = ++cntt;\n\t\t\tif (pre != 0) {\n\t\t\t\taddEdge(pre, cur, 0);\n\t\t\t}\n\t\t\taddEdge(x, cur, 0);\n\t\t\ttree[i] = cur;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int i, int x, int w) {\n\t\twhile (i > 0) {\n\t\t\tif (tree[i] > 0) {\n\t\t\t\taddEdge(tree[i], x, w);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void clear(int val) {\n\t\twhile (val <= maxc) {\n\t\t\ttree[val] = 0;\n\t\t\tval += lowbit(val);\n\t\t}\n\t}\n\n\tpublic static void merge(int l, int m, int r) {\n\t\tint p1, p2;\n\t\tfor (p1 = l - 1, p2 = m + 1; p2 <= r; p2++) {\n\t\t\twhile (p1 + 1 <= m && arr[p1 + 1][2] <= arr[p2][2]) {\n\t\t\t\tp1++;\n\t\t\t\tadd(arr[p1][3], arr[p1][0]);\n\t\t\t}\n\t\t\tfor (int e = headp[arr[p2][0]]; e > 0; e = nextp[e]) {\n\t\t\t\tint u = top[e];\n\t\t\t\tint w = weightp[e];\n\t\t\t\trangeToX(arr[p2][3], u, w);\n\t\t\t}\n\t\t}\n\t\tfor (int i = l; i <= p1; i++) {\n\t\t\tclear(arr[i][3]);\n\t\t}\n\t\tArrays.sort(arr, l, r + 1, (x, y) -> x[2] - y[2]);\n\t}\n\n\tpublic static void cdq(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid);\n\t\tcdq(mid + 1, r);\n\t\tmerge(l, mid, r);\n\t}\n\n\tpublic static void buildGraph() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = i;\n\t\t\tarr[i][1] = a[i];\n\t\t\tarr[i][2] = b[i];\n\t\t\tarr[i][3] = c[i];\n\t\t\tmaxc = Math.max(maxc, c[i]);\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, (x, y) -> x[1] != y[1] ? x[1] - y[1] : x[2] != y[2] ? x[2] - y[2] : x[3] - y[3]);\n\t\tcntt = n;\n\t\tfor (int l = 1, r = 1; l <= n; l = ++r) {\n\t\t\tint a = arr[l][1];\n\t\t\tint b = arr[l][2];\n\t\t\tint c = arr[l][3];\n\t\t\twhile (r + 1 <= n && a == arr[r + 1][1] && b == arr[r + 1][2] && c == arr[r + 1][3]) {\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tint x = ++cntt;\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tint u = arr[i][0];\n\t\t\t\taddEdge(u, x, 0);\n\t\t\t\tfor (int e = headp[u]; e > 0; e = nextp[e]) {\n\t\t\t\t\taddEdge(x, u, weightp[e]);\n\t\t\t\t\taddOp(x, u, weightp[e]);\n\t\t\t\t}\n\t\t\t}\n\t\t\tarr[++cnta][0] = x;\n\t\t\tarr[cnta][1] = a;\n\t\t\tarr[cnta][2] = b;\n\t\t\tarr[cnta][3] = c;\n\t\t}\n\t\tcdq(1, cnta);\n\t}\n\n\tpublic static int MAX_2 = 100001;\n\tpublic static int[] head_2 = new int[MAX_2];\n\tpublic static int[] nxt_2 = new int[MAX_2];\n\tpublic static int[] to_2 = new int[MAX_2];\n\tpublic static int[] weight_2 = new int[MAX_2];\n\tpublic static int cnt_2;\n\n\tpublic static void addEdge_2(int u, int v, int w) {\n\t\tnxt_2[++cnt_2] = head_2[u];\n\t\tto_2[cnt_2] = v;\n\t\tweight_2[cnt_2] = w;\n\t\thead_2[u] = cnt_2;\n\t}\n\n\tpublic static void link(int x, int w) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (a[i] <= a[x] && b[i] <= b[x] && c[i] <= c[x]) {\n\t\t\t\taddEdge_2(i, x, w);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int INF = 1000000001;\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static boolean[] vis = new boolean[MAXT];\n\tpublic static PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> x[1] - y[1]);\n\n\tpublic static int dijkstra(int s, int t) {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\t\t\tint v = tog[e];\n\t\t\t\t\tint w = weightg[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int dijkstra2(int s, int t) {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tdist[i] = INF;\n\t\t\tvis[i] = false;\n\t\t}\n\t\theap.clear();\n\t\tdist[s] = 0;\n\t\theap.add(new int[] { s, 0 });\n\t\twhile (!heap.isEmpty()) {\n\t\t\tint[] cur = heap.poll();\n\t\t\tint u = cur[0];\n\t\t\tint d = cur[1];\n\t\t\tif (u == t) {\n\t\t\t\treturn d;\n\t\t\t}\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = head_2[u]; e > 0; e = nxt_2[e]) {\n\t\t\t\t\tint v = to_2[e];\n\t\t\t\t\tint w = weight_2[e];\n\t\t\t\t\tif (!vis[v] && dist[v] > d + w) {\n\t\t\t\t\t\tdist[v] = d + w;\n\t\t\t\t\t\theap.add(new int[] { v, dist[v] });\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn -1;\n\t}\n\n\tpublic static int random(int v) {\n\t\treturn (int) (Math.random() * v) + 1;\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\theadg[i] = headp[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead_2[i] = 0;\n\t\t}\n\t\tmaxc = cnta = cntg = cntp = cntt = cnt_2 = 0;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("cdq优化建图，三维偏序");\n\t\tSystem.out.println("=============");\n\t\tn = 100;\n\t\tm = 1000;\n\t\tint valMax = 10;\n\t\tint weightMax = 10000;\n\t\tint round = 20;\n\t\tfor (int t = 1; t <= round; t++) {\n\t\t\tSystem.out.println("第" + t + "轮");\n\t\t\tSystem.out.println("测试开始");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\ta[i] = random(valMax);\n\t\t\t\tb[i] = random(valMax);\n\t\t\t\tc[i] = random(valMax);\n\t\t\t}\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint x = random(n);\n\t\t\t\tint w = random(weightMax);\n\t\t\t\taddOp(x, x, w);\n\t\t\t\tlink(x, w);\n\t\t\t}\n\t\t\tbuildGraph();\n\t\t\tfor (int x = 1; x <= n; x++) {\n\t\t\t\tfor (int y = 1; y <= n; y++) {\n\t\t\t\t\tint ans1 = dijkstra(x, y);\n\t\t\t\t\tint ans2 = dijkstra2(x, y);\n\t\t\t\t\tif (ans1 != ans2) {\n\t\t\t\t\t\tSystem.out.println("出错了!");\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tclear();\n\t\t\tSystem.out.println("测试结束");\n\t\t\tSystem.out.println("=======");\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Partition_Multiset_cpp_1.java`\n\n```java\npackage class198;\n\n// 划分可重集，树状数组优化建图，C++版\n// 给定长度为n的数组arr，从左到右把每个数划分进可重集a、b\n// 每个数至少要进入a或b中的一个\n// arr[i]能进集合a的条件为，i左侧任何 <= arr[i] - k的数字，都没进集合a\n// arr[i]能进集合b的条件为，i左侧任何 >= arr[i] + k的数字，都没进集合b\n// 然后有m组关系，每组 x y，保证 x < y，表示两个位置的数不能进入同一个集合\n// 如果不存在合法划分，打印-1，如果存在方案，打印能划分成功的最小k值\n// n、m <= 2 * 10^4\n// arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P7477\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int v, i;\n//};\n//\n//bool NodeCmp(Node a, Node b) {\n//    if (a.v != b.v) {\n//        return a.v < b.v;\n//    }\n//    return a.i < b.i;\n//}\n//\n//const int MAXN = 20001;\n//const int MAXM = 20001;\n//const int MAXT = 1000001;\n//const int MAXE = 2000001;\n//int n, m, cntt;\n//int v[MAXN];\n//int x[MAXM];\n//int y[MAXM];\n//\n//int rak[MAXN];\n//Node arr[MAXN];\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//int outTree1[MAXN];\n//int inTree1[MAXN];\n//int outTree2[MAXN];\n//int inTree2[MAXN];\n//\n//int small(int num) {\n//    int l = 1, r = n, mid, ans = 0;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (arr[mid].v <= num) {\n//            ans = mid;\n//            l = mid + 1;\n//        } else {\n//            r = mid - 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int big(int num) {\n//    int l = 1, r = n, mid, ans = n + 1;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (arr[mid].v >= num) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return n - ans + 1;\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] 