合b\n// 然后有m组关系，每组 x y，保证 x < y，表示两个位置的数不能进入同一个集合\n// 如果不存在合法划分，打印-1，如果存在方案，打印能划分成功的最小k值\n// n、m <= 2 * 10^4\n// arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P7477\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 20001;\n//const int MAXM = 20001;\n//const int MAXT = 1000001;\n//const int MAXE = 2000001;\n//int n, m, cntt;\n//int v[MAXN];\n//int x[MAXM];\n//int y[MAXM];\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//int arr[MAXN];\n//int tmp[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int other(int x) {\n//    return x <= n ? x + n : x - n;\n//}\n//\n//void merge(int l, int mid, int r, int k) {\n//    int preOut = 0, curOut = 0, preIn = 0, curIn = 0;\n//    for (int p1 = l - 1, p2 = mid + 1; p2 <= r; p2++) {\n//        curOut = ++cntt;\n//        curIn = ++cntt;\n//        while (p1 + 1 <= mid && v[arr[p1 + 1]] <= v[arr[p2]] - k) {\n//            p1++;\n//            addEdge(arr[p1], curOut);\n//            addEdge(curIn, other(arr[p1]));\n//        }\n//        if (preOut > 0) {\n//            addEdge(preOut, curOut);\n//        