 check(int k) {\n//    buildGraph(k);\n//    for (int i = 1; i <= (n << 1); i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == belong[i + n]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    clear();\n//    return check;\n//}\n//\n//int compute() {\n//    int maxv = v[1];\n//    for (int i = 2; i <= n; i++) {\n//        maxv = max(maxv, v[i]);\n//    }\n//    int l = 0, r = maxv, mid, ans = -1;\n//    while (l <= r) {\n//        mid = (l + r) >> 1;\n//        if (check(mid)) {\n//            ans = mid;\n//            r = mid - 1;\n//        } else {\n//            l = mid + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> v[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> x[i] >> y[i];\n//    }\n//    int ans = compute();\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code05_Partition_Multiset_java_1.java`\n\n```java\npackage class198;\n\n// 划分可重集，树状数组优化建图，java版\n// 给定长度为n的数组arr，从左到右把每个数划分进可重集a、b\n// 每个数至少要进入a或b中的一个\n// arr[i]能进集合a的条件为，i左侧任何 <= arr[i] - k的数字，都没进集合a\n// arr[i]能进集合b的条件为，i左侧任何 >= arr[i] + k的数字，都没进集合b\n// 然后有m组关系，每组 x y，保证 x < y，表示两个位置的数不能进入同一个集合\n// 如果不存在合法划分，打印-1，如果存在方案，打印能划分成功的最小k值\n// n、m <= 2 * 10^4\n// arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P7477\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_Partition_Multiset_java_1 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 20001;\n\tpublic static int MAXT = 1000001;\n\tpublic static int MAXE = 2000001;\n\tpublic static int n, m, cntt;\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] x = new int[MAXM];\n\tpublic static int[] y = new int[MAXM];\n\n\tpublic static int[] rak = new int[MAXN];\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 树状数组\n\tpublic static int[] outTree1 = new int[MAXN];\n\tpublic static int[] inTree1 = new int[MAXN];\n\tpublic static int[] outTree2 = new int[MAXN];\n\tpublic static int[] inTree2 = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\t// <= num的范围长度\n\tpublic static int small(int num) {\n\t\tint l = 1, r = n, mid, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (arr[mid][0] <= num) {\n\t\t\t\tans = mid;\n\t\t\t\tl = mid + 1;\n\t\t\t} else {\n\t\t\t\tr = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// >= num的范围长度\n\tpublic static int big(int num) {\n\t\tint l = 1, r = n, mid, ans = n + 1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (arr[mid][0] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn n - ans + 1;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void addOut(int[] outTree, int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint preo = outTree[i];\n\t\t\tint curo = ++cntt;\n\t\t\tif (preo > 0) {\n\t\t\t\taddEdge(preo, curo);\n\t\t\t}\n\t\t\taddEdge(x, curo);\n\t\t\toutTree[i] = curo;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void addIn(int[] inTree, int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint prei = inTree[i];\n\t\t\tint curi = ++cntt;\n\t\t\tif (prei > 0) {\n\t\t\t\taddEdge(curi, prei);\n\t\t\t}\n\t\t\taddEdge(curi, x);\n\t\t\tinTree[i] = curi;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int[] outTree, int i, int x) {\n\t\twhile (i > 0) {\n\t\t\tif (outTree[i] > 0) {\n\t\t\t\taddEdge(outTree[i], x);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void xToRange(int[] inTree, int x, int i) {\n\t\twhile (i > 0) {\n\t\t\tif (inTree[i] > 0) {\n\t\t\t\taddEdge(x, inTree[i]);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void add(int x, int otherx, int si, int bi) {\n\t\taddOut(outTree1, si, x);\n\t\taddIn(inTree1, si, otherx);\n\t\taddOut(outTree2, bi, otherx);\n\t\taddIn(inTree2, bi, x);\n\t}\n\n\tpublic static void link(int x, int otherx, int lowCnt, int highCnt) {\n\t\txToRange(inTree1, x, lowCnt);\n\t\trangeToX(outTree1, lowCnt, otherx);\n\t\txToRange(inTree2, otherx, highCnt);\n\t\trangeToX(outTree2, highCnt, x);\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static void buildGraph(int k) {\n\t\tcntt = n << 1;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\taddEdge(x[i], other(y[i]));\n\t\t\taddEdge(y[i], other(x[i]));\n\t\t\taddEdge(other(x[i]), y[i]);\n\t\t\taddEdge(other(y[i]), x[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlink(i, other(i), small(v[i] - k), big(v[i] + k));\n\t\t\tadd(i, other(i), rak[i], n - rak[i] + 1);\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = dfn[i] = belong[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tinTree1[i] = outTree1[i] = inTree2[i] = outTree2[i] = 0;\n\t\t}\n\t\tcntt = cntg = cntd = top = sccCnt = 0;\n\t}\n\n\tpublic static boolean check(int k) {\n\t\tbuildGraph(k);\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\treturn check;\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = v[i];\n\t\t\tarr[i][1] = i;\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\trak[arr[i][1]] = i;\n\t\t}\n\t\tint l = 0, r = arr[n][0], mid, ans = -1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (check(mid)) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tv[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tx[i] = in.nextInt();\n\t\t\ty[i] = in.nextInt();\n\t\t}\n\t\tint ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Partition_Multiset_java_2.java`\n\n```java\npackage class198;\n\n// 划分可重集，主席树优化建图，java版\n// 给定长度为n的数组arr，从左到右把每个数划分进可重集a、b\n// 每个数至少要进入a或b中的一个\n// arr[i]能进集合a的条件为，i左侧任何 <= arr[i] - k的数字，都没进集合a\n// arr[i]能进集合b的条件为，i左侧任何 >= arr[i] + k的数字，都没进集合b\n// 然后有m组关系，每组 x y，保证 x < y，表示两个位置的数不能进入同一个集合\n// 如果不存在合法划分，打印-1，如果存在方案，打印能划分成功的最小k值\n// n、m <= 2 * 10^4\n// arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P7477\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_Partition_Multiset_java_2 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 20001;\n\tpublic static int MAXT = 2000001;\n\tpublic static int MAXE = 5000001;\n\tpublic static int n, m, cntt;\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] x = new int[MAXM];\n\tpublic static int[] y = new int[MAXM];\n\n\tpublic static int[] rak = new int[MAXN];\n\tpublic static int[][] arr = new int[MAXN][2];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 主席树\n\tpublic static int[] rootOut1 = new int[MAXN];\n\tpublic static int[] rootIn1 = new int[MAXN];\n\tpublic static int[] rootOut2 = new int[MAXN];\n\tpublic static int[] rootIn2 = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\tpublic static int curVersion;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\t// <= num的范围长度\n\tpublic static int small(int num) {\n\t\tint l = 1, r = n, mid, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (arr[mid][0] <= num) {\n\t\t\t\tans = mid;\n\t\t\t\tl = mid + 1;\n\t\t\t} else {\n\t\t\t\tr = mid - 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// >= num的范围长度\n\tpublic static int big(int num) {\n\t\tint l = 1, r = n, mid, ans = n + 1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (arr[mid][0] >= num) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn n - ans + 1;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt);\n\t\t\taddEdge(rs[rt], rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt]);\n\t\t\taddEdge(rt, rs[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addOut(int jobx, int jobv, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(i, rt);\n\t\tif (l == r) {\n\t\t\taddEdge(jobx, rt);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobv <= mid) {\n\t\t\t\tls[rt] = addOut(jobx, jobv, l, mid, ls[rt]);\n\t\t\t\taddEdge(ls[rt], rt);\n\t\t\t} else {\n\t\t\t\trs[rt] = addOut(jobx, jobv, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rs[rt], rt);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addIn(int jobx, int jobv, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(rt, i);\n\t\tif (l == r) {\n\t\t\taddEdge(rt, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobv <= mid) {\n\t\t\t\tls[rt] = addIn(jobx, jobv, l, mid, ls[rt]);\n\t\t\t\taddEdge(rt, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = addIn(jobx, jobv, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rt, rs[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void add(int x, int otherx, int si, int bi) {\n\t\tcurVersion++;\n\t\trootOut1[curVersion] = addOut(x, si, 1, n, rootOut1[curVersion - 1]);\n\t\trootIn1[curVersion] = addIn(otherx, si, 1, n, rootIn1[curVersion - 1]);\n\t\trootOut2[curVersion] = addOut(otherx, bi, 1, n, rootOut2[curVersion - 1]);\n\t\trootIn2[curVersion] = addIn(x, bi, 1, n, rootIn2[curVersion - 1]);\n\t}\n\n\tpublic static void link(int x, int otherx, int lowCnt, int hightCnt) {\n\t\tif (lowCnt > 0) {\n\t\t\txToRange(x, 1, lowCnt, 1, n, rootIn1[curVersion]);\n\t\t\trangeToX(1, lowCnt, otherx, 1, n, rootOut1[curVersion]);\n\t\t}\n\t\tif (hightCnt > 0) {\n\t\t\txToRange(otherx, 1, hightCnt, 1, n, rootIn2[curVersion]);\n\t\t\trangeToX(1, hightCnt, x, 1, n, rootOut2[curVersion]);\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static void buildGraph(int k) {\n\t\tcntt = n << 1;\n\t\trootOut1[0] = buildOut(1, n);\n\t\trootIn1[0] = buildIn(1, n);\n\t\trootOut2[0] = buildOut(1, n);\n\t\trootIn2[0] = buildIn(1, n);\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\taddEdge(x[i], other(y[i]));\n\t\t\taddEdge(y[i], other(x[i]));\n\t\t\taddEdge(other(x[i]), y[i]);\n\t\t\taddEdge(other(y[i]), x[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlink(i, other(i), small(v[i] - k), big(v[i] + k));\n\t\t\tadd(i, other(i), rak[i], n - rak[i] + 1);\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = dfn[i] = belong[i] = 0;\n\t\t}\n\t\tcntt = cntg = cntd = top = sccCnt = curVersion = 0;\n\t}\n\n\tpublic static boolean check(int k) {\n\t\tbuildGraph(k);\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\treturn check;\n\t}\n\n\tpublic static int compute() {\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i][0] = v[i];\n\t\t\tarr[i][1] = i;\n\t\t}\n\t\tArrays.sort(arr, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\trak[arr[i][1]] = i;\n\t\t}\n\t\tint l = 0, r = arr[n][0], mid, ans = -1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (check(mid)) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tv[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tx[i] = in.nextInt();\n\t\t\ty[i] = in.nextInt();\n\t\t}\n\t\tint ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Partition_Multiset_java_3.java`\n\n```java\npackage class198;\n\n// 划分可重集，cdq优化建图，java版\n// 给定长度为n的数组arr，从左到右把每个数划分进可重集a、b\n// 每个数至少要进入a或b中的一个\n// arr[i]能进集合a的条件为，i左侧任何 <= arr[i] - k的数字，都没进集合a\n// arr[i]能进集合b的条件为，i左侧任何 >= arr[i] + k的数字，都没进集合b\n// 然后有m组关系，每组 x y，保证 x < y，表示两个位置的数不能进入同一个集合\n// 如果不存在合法划分，打印-1，如果存在方案，打印能划分成功的最小k值\n// n、m <= 2 * 10^4\n// arr[i] <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P7477\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Partition_Multiset_java_3 {\n\n\tpublic static int MAXN = 20001;\n\tpublic static int MAXM = 20001;\n\tpublic static int MAXT = 1000001;\n\tpublic static int MAXE = 2000001;\n\tpublic static int n, m, cntt;\n\tpublic static int[] v = new int[MAXN];\n\tpublic static int[] x = new int[MAXM];\n\tpublic static int[] y = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// cdq\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] tmp = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static void merge(int l, int mid, int r, int k) {\n\t\tint preOut = 0, curOut = 0, preIn = 0, curIn = 0;\n\t\tfor (int p1 = l - 1, p2 = mid + 1; p2 <= r; p2++) {\n\t\t\tcurOut = ++cntt;\n\t\t\tcurIn = ++cntt;\n\t\t\twhile (p1 + 1 <= mid && v[arr[p1 + 1]] <= v[arr[p2]] - k) {\n\t\t\t\tp1++;\n\t\t\t\taddEdge(arr[p1], curOut);\n\t\t\t\taddEdge(curIn, other(arr[p1]));\n\t\t\t}\n\t\t\tif (preOut > 0) {\n\t\t\t\taddEdge(preOut, curOut);\n\t\t\t\taddEdge(curIn, preIn);\n\t\t\t}\n\t\t\taddEdge(curOut, other(arr[p2]));\n\t\t\taddEdge(arr[p2], curIn);\n\t\t\tpreOut = curOut;\n\t\t\tpreIn = curIn;\n\t\t}\n\t\tpreOut = curOut = preIn = curIn = 0;\n\t\tfor (int p1 = mid + 1, p2 = r; p2 >= mid + 1; p2--) {\n\t\t\tcurOut = ++cntt;\n\t\t\tcurIn = ++cntt;\n\t\t\twhile (p1 - 1 >= l && v[arr[p1 - 1]] >= v[arr[p2]] + k) {\n\t\t\t\tp1--;\n\t\t\t\taddEdge(other(arr[p1]), curOut);\n\t\t\t\taddEdge(curIn, arr[p1]);\n\t\t\t}\n\t\t\tif (preOut > 0) {\n\t\t\t\taddEdge(preOut, curOut);\n\t\t\t\taddEdge(curIn, preIn);\n\t\t\t}\n\t\t\taddEdge(curOut, arr[p2]);\n\t\t\taddEdge(other(arr[p2]), curIn);\n\t\t\tpreOut = curOut;\n\t\t\tpreIn = curIn;\n\t\t}\n\t\tint p1 = l, p2 = mid + 1, ti = 0;\n\t\twhile (p1 <= mid && p2 <= r) {\n\t\t\tif (v[arr[p1]] <= v[arr[p2]]) {\n\t\t\t\ttmp[++ti] = arr[p1++];\n\t\t\t} else {\n\t\t\t\ttmp[++ti] = arr[p2++];\n\t\t\t}\n\t\t}\n\t\twhile (p1 <= mid) {\n\t\t\ttmp[++ti] = arr[p1++];\n\t\t}\n\t\twhile (p2 <= r) {\n\t\t\ttmp[++ti] = arr[p2++];\n\t\t}\n\t\tfor (int i = l, j = 1; i <= r; i++, j++) {\n\t\t\tarr[i] = tmp[j];\n\t\t}\n\t}\n\n\tpublic static void cdq(int l, int r, int k) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid, k);\n\t\tcdq(mid + 1, r, k);\n\t\tmerge(l, mid, r, k);\n\t}\n\n\tpublic static void buildGraph(int k) {\n\t\tcntt = n << 1;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\taddEdge(x[i], other(y[i]));\n\t\t\taddEdge(y[i], other(x[i]));\n\t\t\taddEdge(other(x[i]), y[i]);\n\t\t\taddEdge(other(y[i]), x[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = i;\n\t\t}\n\t\tcdq(1, n, k);\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= cntt; i++) {\n\t\t\thead[i] = dfn[i] = belong[i] = 0;\n\t\t}\n\t\tcntt = cntg = cntd = top = sccCnt = 0;\n\t}\n\n\tpublic static boolean check(int k) {\n\t\tbuildGraph(k);\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tclear();\n\t\treturn check;\n\t}\n\n\tpublic static int compute() {\n\t\tint maxv = v[1];\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tmaxv = Math.max(maxv, v[i]);\n\t\t}\n\t\tint l = 0, r = maxv, mid, ans = -1;\n\t\twhile (l <= r) {\n\t\t\tmid = (l + r) >> 1;\n\t\t\tif (check(mid)) {\n\t\t\t\tans = mid;\n\t\t\t\tr = mid - 1;\n\t\t\t} else {\n\t\t\t\tl = mid + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tv[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tx[i] = in.nextInt();\n\t\t\ty[i] = in.nextInt();\n\t\t}\n\t\tint ans = compute();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_Meow_II_cpp_1.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，树状数组优化建图，C++版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int v, i;\n//};\n//\n//bool NodeCmp(Node a, Node b) {\n//    if (a.v != b.v) {\n//        return a.v < b.v;\n//    }\n//    return a.i < b.i;\n//}\n//\n//struct Group {\n//    int l, r, x;\n//};\n//\n//bool GroupCmp(Group a, Group b) {\n//    return a.r < b.r;\n//}\n//\n//const int MAXV = 50001;\n//const int MAXN = 200001;\n//const int MAXT = 5000001;\n//const int MAXE = 20000001;\n//int v, n, cntt;\n//\n//Node vi[MAXN];\n//Group group[MAXN];\n//int cntp;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//int outTree[MAXN];\n//int inTre