     cout << "No" << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_Meow_II_cpp_2.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，主席树优化建图，C++版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int v, i;\n//};\n//\n//bool NodeCmp(Node a, Node b) {\n//    if (a.v != b.v) {\n//        return a.v < b.v;\n//    }\n//    return a.i < b.i;\n//}\n//\n//struct Group {\n//    int l, r, x;\n//};\n//\n//bool GroupCmp(Group a, Group b) {\n//    return a.r < b.r;\n//}\n//\n//const int MAXV = 50001;\n//const int MAXN = 200001;\n//const int MAXT = 10000001;\n//const int MAXE = 50000001;\n//int v, n, cntt;\n//\n//Node vi[MAXN];\n//Group group[MAXN];\n//int cntp;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//int rootOut[MAXN];\n//int rootIn[MAXN];\n//int ls[MAXT];\n//int rs[MAXT];\n//\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int b