ge(jobx, jobl, jobr, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        addEdge(i, jobx);\n//    } else {\n//        int mid = (l + r) >> 1;\n//        if (jobl <= mid) {\n//            rangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n//        }\n//        if (jobr > mid) {\n//            rangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n//        }\n//    }\n//}\n//\n//int other(int x) {\n//    return x <= v ? x + v : x - v;\n//}\n//\n//void buildGraph() {\n//    sort(group + 1, group + cntp + 1, GroupCmp);\n//    cntt = v << 1;\n//    rootOut[0] = buildOut(1, n);\n//    rootIn[0] = buildIn(1, n);\n//    for (int i = 1; i <= cntp; i++) {\n//        int l = group[i].l;\n//        int r = group[i].r;\n//        int x = group[i].x;\n//        xToRange(x, l, r, 1, n, rootIn[i - 1]);\n//        rangeToX(l, r, other(x), 1, n, rootOut[i - 1]);\n//        rootIn[i] = addIn(l, other(x), 1, n, rootIn[i - 1]);\n//        rootOut[i] = addOut(l, x, 1, n, rootOut[i - 1]);\n//    }\n//}\n//\n//bool compute() {\n//    sort(vi + 1, vi + n + 1, NodeCmp);\n//    for (int i = 1; i <= n; i += 4) {\n//        int x = vi[i].v;\n//        int a = vi[i].i;\n//        int b = vi[i + 1].i;\n//        int c = vi[i + 2].i;\n//        int d = vi[i + 3].i;\n//        group[++cntp] = { a, c, x };\n//        group[++cntp] = { b, d, x };\n//        group[++cntp] = { a, b, x + v };\n//        group[++cntp] = { c, d, x + v };\n//    }\n//    buildGraph();\n//    for (int i = 1; i <= v << 1; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= v; i++) {\n//        if (belong[i] == belong[i + v]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    if (check) {\n//        for (int i = 1; i <= n; i += 4) {\n//            int x = vi[i].v;\n//            int a = vi[i].i;\n//            int b = vi[i + 1].i;\n//            int c = vi[i + 2].i;\n//            int d = vi[i + 3].i;\n//            if (belong[x] < belong[x + v]) {\n//                ans[a] = 0;\n//                ans[b] = 0;\n//                ans[c] = 1;\n//                ans[d] = 1;\n//            } else {\n//                ans[a] = 0;\n//                ans[b] = 1;\n//                ans[c] = 0;\n//                ans[d] = 1;\n//            }\n//        }\n//    }\n//    return check;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> v;\n//    n = v << 2;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> vi[i].v;\n//        vi[i].i = i;\n//    }\n//    bool check = compute();\n//    if (check) {\n//        cout << "Yes" << "\\n";\n//        for (int i = 1; i <= n; i++) {\n//            cout << ans[i];\n//        }\n//    } else {\n//        cout << "No" << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_Meow_II_cpp_3.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，cdq优化建图，C++版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int v, i;\n//};\n//\n//bool NodeCmp(Node a, Node b) {\n//    if (a.v != b.v) {\n//        return a.v < b.v;\n//    }\n//    return a.i < b.i;\n//}\n//\n//struct Group {\n//    int l, r, x;\n//};\n//\n//bool GroupCmp(Group a, Group b) {\n//    return a.r < b.r;\n//}\n//\n//const int MAXV = 50001;\n//const int MAXN = 200001;\n//const int MAXT = 5000001;\n//const int MAXE = 20000001;\n//int v, n, cntt;\n//\n//Node vi[MAXN];\n//Group group[MAXN];\n//int cntp;\n//\n//int head[MAXT];\n//int nxt[MAXE];\n//int to[MAXE];\n//int cntg;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//int arr[MAXN];\n//int tmp[MAXN];\n//\n//int ans[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int other(int x) {\n//    return x <= v ? x + v : x - v;\n//}\n//\n//void merge(int l, int mid, int r) {\n//    int preOut = 0, curOut = 0, preIn = 0, curIn = 0;\n//    for (int p1 = mid + 1, p2 = r; p2 >= mid + 1; p2--) {\n//        curOut = ++cntt;\n//        curIn = ++cntt;\n//        while (p1 - 1 >= l && group[arr[p1 - 1]].l >= group[arr[p2]].l) {\n//            p1--;\n//            addEdge(group[arr[p1]].x, curOut);\n//            addEdge(curIn, other(group[arr[p1]].x));\n//        }\n//        if (preOut > 0) {\n//            addEdge(preOut, curOut);\n//            addEdge(curIn, preIn);\n//        }\n//        addEdge(curOut, other(group[arr[p2]].x));\n//        addEdge(group[arr[p2]].x, curIn);\n//        preOut = curOut;\n//        preIn = curIn;\n//    }\n//    int p1 = l, p2 = mid + 1, ti = 0;\n//    while (p1 <= mid && p2 <= r) {\n//        if (group[arr[p1]].l <= group[arr[p2]].l) {\n//            tmp[++ti] = arr[p1++];\n//        } else {\n//            tmp[++ti] = arr[p2++];\n//        }\n//    }\n//    while (p1 <= mid) {\n//        tmp[++ti] = arr[p1++];\n//    }\n//    while (p2 <= r) {\n//        tmp[++ti] = arr[p2++];\n//    }\n//    for (int i = l, j = 1; i <= r; i++, j++) {\n//        arr[i] = tmp[j];\n//    }\n//}\n//\n//void cdq(int l, int r) {\n//    if (l == r) {\n//        return;\n//    }\n//    int mid = (l + r) / 2;\n//    cdq(l, mid);\n//    cdq(mid + 1, r);\n//    merge(l, mid, r);\n//}\n//\n//void buildGraph() {\n//    sort(group + 1, group + cntp + 1, GroupCmp);\n//    cntt = v << 1;\n//    for (int i = 1; i <= cntp; i++) {\n//        arr[i] = i;\n//    }\n//    cdq(1, cntp);\n//}\n//\n//bool compute() {\n//    sort(vi + 1, vi + n + 1, NodeCmp);\n//    for (int i = 1; i <= n; i += 4) {\n//        int x = vi[i].v;\n//        int a = vi[i].i;\n//        int b = vi[i + 1].i;\n//        int c = vi[i + 2].i;\n//        int d = vi[i + 3].i;\n//        group[++cntp] = { a, c, x };\n//        group[++cntp] = { b, d, x };\n//        group[++cntp] = { a, b, x + v };\n//        group[++cntp] = { c, d, x + v };\n//    }\n//    buildGraph();\n//    for (int i = 1; i <= v << 1; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= v; i++) {\n//        if (belong[i] == belong[i + v]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    if (check) {\n//        for (int i = 1; i <= n; i += 4) {\n//            int x = vi[i].v;\n//            int a = vi[i].i;\n//            int b = vi[i + 1].i;\n//            int c = vi[i + 2].i;\n//            int d = vi[i + 3].i;\n//            if (belong[x] < belong[x + v]) {\n//                ans[a] = 0;\n//                ans[b] = 0;\n//                ans[c] = 1;\n//                ans[d] = 1;\n//            } else {\n//                ans[a] = 0;\n//                ans[b] = 1;\n//                ans[c] = 0;\n//                ans[d] = 1;\n//            }\n//        }\n//    }\n//    return check;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> v;\n//    n = v << 2;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> vi[i].v;\n//        vi[i].i = i;\n//    }\n//    bool check = compute();\n//    if (check) {\n//        cout << "Yes" << "\\n";\n//        for (int i = 1; i <= n; i++) {\n//            cout << ans[i];\n//        }\n//    } else {\n//        cout << "No" << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_Meow_II_java_1.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，树状数组优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_1 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 5000001;\n\tpublic static int MAXE = 20000001;\n\tpublic static int v, n, cntt;\n\n\t// 值v、位置i\n\tpublic static int[][] vi = new int[MAXN][2];\n\t// 左l、右r、决定编号x\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 树状数组\n\tpublic static int[] inTree = new int[MAXN];\n\tpublic static int[] outTree = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lowbit(int i) {\n\t\treturn i & -i;\n\t}\n\n\tpublic static void addOut(int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint preo = outTree[i];\n\t\t\tint curo = ++cntt;\n\t\t\tif (preo > 0) {\n\t\t\t\taddEdge(preo, curo);\n\t\t\t}\n\t\t\taddEdge(x, curo);\n\t\t\toutTree[i] = curo;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void addIn(int i, int x) {\n\t\twhile (i <= n) {\n\t\t\tint prei = inTree[i];\n\t\t\tint curi = ++cntt;\n\t\t\tif (prei > 0) {\n\t\t\t\taddEdge(curi, prei);\n\t\t\t}\n\t\t\taddEdge(curi, x);\n\t\t\tinTree[i] = curi;\n\t\t\ti += lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int i, int x) {\n\t\twhile (i > 0) {\n\t\t\tif (outTree[i] > 0) {\n\t\t\t\taddEdge(outTree[i], x);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static void xToRange(int x, int i) {\n\t\twhile (i > 0) {\n\t\t\tif (inTree[i] > 0) {\n\t\t\t\taddEdge(x, inTree[i]);\n\t\t\t}\n\t\t\ti -= lowbit(i);\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(group, 1, cntp + 1, (a, b) -> a[1] - b[1]);\n\t\tcntt = v << 1;\n\t\tfor (int i = 1; i <= cntp; i++) {\n\t\t\tint l = group[i][0];\n\t\t\t// 后缀查询转化成前缀查询\n\t\t\tint p = n - l + 1;\n\t\t\tint x = group[i][2];\n\t\t\txToRange(x, p);\n\t\t\trangeToX(p, other(x));\n\t\t\taddIn(p, other(x));\n\t\t\taddOut(p, x);\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tArrays.sort(vi, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\tint x = vi[i][0];\n\t\t\tint a = vi[i][1];\n\t\t\tint b = vi[i + 1][1];\n\t\t\tint c = vi[i + 2][1];\n\t\t\tint d = vi[i + 3][1];\n\t\t\taddGroup(a, c, x);\n\t\t\taddGroup(b, d, x);\n\t\t\taddGroup(a, b, x + v);\n\t\t\taddGroup(c, d, x + v);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= v << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tif (belong[i] == belong[i + v]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_Meow_II_java_2.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，主席树优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_2 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 10000001;\n\tpublic static int MAXE = 50000001;\n\tpublic static int v, n, cntt;\n\n\tpublic static int[][] vi = new int[MAXN][2];\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 主席树\n\tpublic static int[] rootOut = new int[MAXN];\n\tpublic static int[] rootIn = new int[MAXN];\n\tpublic static int[] ls = new int[MAXT];\n\tpublic static int[] rs = new int[MAXT];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int buildOut(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildOut(l, mid);\n\t\t\trs[rt] = buildOut(mid + 1, r);\n\t\t\taddEdge(ls[rt], rt);\n\t\t\taddEdge(rs[rt], rt);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int buildIn(int l, int r) {\n\t\tint rt = ++cntt;\n\t\tif (l < r) {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tls[rt] = buildIn(l, mid);\n\t\t\trs[rt] = buildIn(mid + 1, r);\n\t\t\taddEdge(rt, ls[rt]);\n\t\t\taddEdge(rt, rs[rt]);\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addOut(int jobi, int jobx, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(i, rt);\n\t\tif (l == r) {\n\t\t\taddEdge(jobx, rt);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = addOut(jobi, jobx, l, mid, ls[rt]);\n\t\t\t\taddEdge(ls[rt], rt);\n\t\t\t} else {\n\t\t\t\trs[rt] = addOut(jobi, jobx, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rs[rt], rt);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static int addIn(int jobi, int jobx, int l, int r, int i) {\n\t\tint rt = ++cntt;\n\t\tls[rt] = ls[i];\n\t\trs[rt] = rs[i];\n\t\taddEdge(rt, i);\n\t\tif (l == r) {\n\t\t\taddEdge(rt, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tls[rt] = addIn(jobi, jobx, l, mid, ls[rt]);\n\t\t\t\taddEdge(rt, ls[rt]);\n\t\t\t} else {\n\t\t\t\trs[rt] = addIn(jobi, jobx, mid + 1, r, rs[rt]);\n\t\t\t\taddEdge(rt, rs[rt]);\n\t\t\t}\n\t\t}\n\t\treturn rt;\n\t}\n\n\tpublic static void xToRange(int jobx, int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(jobx, i);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\txToRange(jobx, jobl, jobr, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void rangeToX(int jobl, int jobr, int jobx, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\taddEdge(i, jobx);\n\t\t} else {\n\t\t\tint mid = (l + r) >> 1;\n\t\t\tif (jobl <= mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, l, mid, ls[i]);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\trangeToX(jobl, jobr, jobx, mid + 1, r, rs[i]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(group, 1, cntp + 1, (a, b) -> a[1] - b[1]);\n\t\tcntt = v << 1;\n\t\trootOut[0] = buildOut(1, n);\n\t\trootIn[0] = buildIn(1, n);\n\t\tfor (int i = 1; i <= cntp; i++) {\n\t\t\tint l = group[i][0];\n\t\t\tint r = group[i][1];\n\t\t\tint x = group[i][2];\n\t\t\txToRange(x, l, r, 1, n, rootIn[i - 1]);\n\t\t\trangeToX(l, r, other(x), 1, n, rootOut[i - 1]);\n\t\t\trootIn[i] = addIn(l, other(x), 1, n, rootIn[i - 1]);\n\t\t\trootOut[i] = addOut(l, x, 1, n, rootOut[i - 1]);\n\t\t}\n\t}\n\n\tpublic static boolean compute() {\n\t\tArrays.sort(vi, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\tint x = vi[i][0];\n\t\t\tint a = vi[i][1];\n\t\t\tint b = vi[i + 1][1];\n\t\t\tint c = vi[i + 2][1];\n\t\t\tint d = vi[i + 3][1];\n\t\t\taddGroup(a, c, x);\n\t\t\taddGroup(b, d, x);\n\t\t\taddGroup(a, b, x + v);\n\t\t\taddGroup(c, d, x + v);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= v << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tif (belong[i] == belong[i + v]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_Meow_II_java_3.java`\n\n```java\npackage class198;\n\n// 喵了个喵 II，cdq优化建图，java版\n// 给定一个长度为4n的数组arr，1~n每种数字都出现4次\n// 从左到右把每个数字划分进序列0或序列1，要求划分出的两个序列完全相等\n// 如果能做到，先打印"Yes"，然后从左到右打印每个位置划分进了什么序列\n// 如果不能做到，打印"No"\n// 1 <= n <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P9139\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code06_Meow_II_java_3 {\n\n\tpublic static int MAXV = 50001;\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXT = 5000001;\n\tpublic static int MAXE = 20000001;\n\tpublic static int v, n, cntt;\n\n\tpublic static int[][] vi = new int[MAXN][2];\n\tpublic static int[][] group = new int[MAXN][3];\n\tpublic static int cntp;\n\n\tpublic static int[] head = new int[MAXT];\n\tpublic static int[] nxt = new int[MAXE];\n\tpublic static int[] to = new int[MAXE];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// cdq\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] tmp = new int[MAXN];\n\n\tpublic static int[] ans = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addGroup(int l, int r, int x) {\n\t\tgroup[++cntp][0] = l;\n\t\tgroup[cntp][1] = r;\n\t\tgroup[cntp][2] = x;\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= v ? x + v : x - v;\n\t}\n\n\tpublic static void merge(int l, int mid, int r) {\n\t\tint preOut = 0, curOut = 0, preIn = 0, curIn = 0;\n\t\tfor (int p1 = mid + 1, p2 = r; p2 >= mid + 1; p2--) {\n\t\t\tcurOut = ++cntt;\n\t\t\tcurIn = ++cntt;\n\t\t\twhile (p1 - 1 >= l && group[arr[p1 - 1]][0] >= group[arr[p2]][0]) {\n\t\t\t\tp1--;\n\t\t\t\taddEdge(group[arr[p1]][2], curOut);\n\t\t\t\taddEdge(curIn, other(group[arr[p1]][2]));\n\t\t\t}\n\t\t\tif (preOut > 0) {\n\t\t\t\taddEdge(preOut, curOut);\n\t\t\t\taddEdge(curIn, preIn);\n\t\t\t}\n\t\t\taddEdge(curOut, other(group[arr[p2]][2]));\n\t\t\taddEdge(group[arr[p2]][2], curIn);\n\t\t\tpreOut = curOut;\n\t\t\tpreIn = curIn;\n\t\t}\n\t\tint p1 = l, p2 = mid + 1, ti = 0;\n\t\twhile (p1 <= mid && p2 <= r) {\n\t\t\tif (group[arr[p1]][0] <= group[arr[p2]][0]) {\n\t\t\t\ttmp[++ti] = arr[p1++];\n\t\t\t} else {\n\t\t\t\ttmp[++ti] = arr[p2++];\n\t\t\t}\n\t\t}\n\t\twhile (p1 <= mid) {\n\t\t\ttmp[++ti] = arr[p1++];\n\t\t}\n\t\twhile (p2 <= r) {\n\t\t\ttmp[++ti] = arr[p2++];\n\t\t}\n\t\tfor (int i = l, j = 1; i <= r; i++, j++) {\n\t\t\tarr[i] = tmp[j];\n\t\t}\n\t}\n\n\tpublic static void cdq(int l, int r) {\n\t\tif (l == r) {\n\t\t\treturn;\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tcdq(l, mid);\n\t\tcdq(mid + 1, r);\n\t\tmerge(l, mid, r);\n\t}\n\n\tpublic static void buildGraph() {\n\t\tArrays.sort(group, 1, cntp + 1, (a, b) -> a[1] - b[1]);\n\t\tcntt = v << 1;\n\t\tfor (int i = 1; i <= cntp; i++) {\n\t\t\tarr[i] = i;\n\t\t}\n\t\tcdq(1, cntp);\n\t}\n\n\tpublic static boolean compute() {\n\t\tArrays.sort(vi, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\tint x = vi[i][0];\n\t\t\tint a = vi[i][1];\n\t\t\tint b = vi[i + 1][1];\n\t\t\tint c = vi[i + 2][1];\n\t\t\tint d = vi[i + 3][1];\n\t\t\taddGroup(a, c, x);\n\t\t\taddGroup(b, d, x);\n\t\t\taddGroup(a, b, x + v);\n\t\t\taddGroup(c, d, x + v);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= v << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= v; i++) {\n\t\t\tif (belong[i] == belong[i + v]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i += 4) {\n\t\t\t\tint x = vi[i][0];\n\t\t\t\tint a = vi[i][1];\n\t\t\t\tint b = vi[i + 1][1];\n\t\t\t\tint c = vi[i + 2][1];\n\t\t\t\tint d = vi[i + 3][1];\n\t\t\t\tif (belong[x] < belong[x + v]) {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 0;\n\t\t\t\t\tans[c] = 1;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t} else {\n\t\t\t\t\tans[a] = 0;\n\t\t\t\t\tans[b] = 1;\n\t\t\t\t\tans[c] = 0;\n\t\t\t\t\tans[d] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn check;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tv = in.nextInt();\n\t\tn = v << 2;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tvi[i][0] = in.nextInt();\n\t\t\tvi[i][1] = i;\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tout.println("Yes");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
b85fd65b-dd8d-4eef-aedf-e7694b9886b4	5ccd659e-45b0-4701-a259-47c5a7b338e9	deep	块状数组	## 建立块状数组\n\n块状数组，即把一个数组分为几个块，块内信息整体保存，若查询时遇到两边不完整的块直接暴力查询．一般情况下，块的长度为 $O(\\sqrt{n})$．详细分析可以阅读 2017 年国家集训队论文中徐明宽的《非常规大小分块算法初探》．\n\n下面直接给出一种建立块状数组的代码．\n\n???+ note "实现"\n    ```cpp\n    num = sqrt(n);\n    for (int i = 1; i <= num; i++)\n      st[i] = n / num * (i - 1) + 1, ed[i] = n / num * i;\n    ed[num] = n;\n    for (int i = 1; i <= num; i++) {\n      for (int j = st[i]; j <= ed[i]; j++) {\n        belong[j] = i;\n      }\n      size[i] = ed[i] - st[i] + 1;\n    }\n    ```\n\n其中 `st[i]` 和 `ed[i]` 为块的起点和终点，`size[i]` 为块的大小．\n\n## 保存与修改块内信息\n\n### 例题 1：[教主的魔法](https://www.luogu.com.cn/problem/P2801)\n\n两种操作：\n\n1.  区间 $[x,y]$ 每个数都加上 $z$；\n2.  查询区间 $[x,y]$ 内大于等于 $z$ 的数的个数．\n\n我们要询问一个块内大于等于一个数的数的个数，所以需要一个 `t` 数组对块内排序，`a` 为原来的（未被排序的）数组．对于整块的修改，使用类似于标记永久化的方式，用 `delta` 数组记录现在块内整体加上的值．设 $q$ 为查询和修改的操作次数总和，则时间复杂度 $O(q\\sqrt{n}\\log n)$．\n\n用 `delta` 数组记录每个块的整体赋值情况．\n\n???+ note "实现"\n    ```cpp\n    void Sort(int k) {\n      for (int i = st[k]; i <= ed[k]; i++) t[i] = a[i];\n      sort(t + st[k], t + ed[k] + 1);\n    }\n    \n    void Modify(int l, int r, int c) {\n      int x = belong[l], y = belong[r];\n      if (x == y)  // 区间在一个块内就直接修改\n      {\n        for (int i = l; i <= r; i++) a[i] += c;\n        Sort(x);\n        return;\n      }\n      for (int i = l; i <= ed[x]; i++) a[i] += c;     // 直接修改起始段\n      for (int i = st[y]; i <= r; i++) a[i] += c;     // 直接修改结束段\n      for (int i = x + 1; i < y; i++) delta[i] += c;  // 中间的块整体打上标记\n      Sort(x);\n      Sort(y);\n    }\n    \n    int Answer(int l, int r, int c) {\n      int ans = 0, x = belong[l], y = belong[r];\n      if (x == y) {\n        for (int i = l; i <= r; i++)\n          if (a[i] + delta[x] >= c) ans++;\n        return ans;\n      }\n      for (int i = l; i <= ed[x]; i++)\n        if (a[i] + delta[x] >= c) ans++;\n      for (int i = st[y]; i <= r; i++)\n        if (a[i] + delta[y] >= c) ans++;\n      for (int i = x + 1; i <= y - 1; i++)\n        ans +=\n            ed[i] - (lower_bound(t + st[i], t + ed[i] + 1, c - delta[i]) - t) + 1;\n      // 用 lower_bound 找出中间每一个整块中第一个大于等于 c 的数的位置\n      return ans;\n    }\n    ```\n\n### 例题 2：寒夜方舟\n\n两种操作：\n\n1.  区间 $[x,y]$ 每个数都变成 $z$；\n2.  查询区间 $[x,y]$ 内小于等于 $z$ 的数的个数．\n\n用 `delta` 数组记录现在块内被整体赋值为何值．当该块未被整体赋值时，用一个特殊值（如 `0x3f3f3f3f3f3f3f3fll`）加以表示．对于边角块，查询前要 `pushdown`，把块内存的信息下放到每一个数上．赋值之后记得重新 `sort` 一遍．其他方面同上题．\n\n???+ note "实现"\n    ```cpp\n    void Sort(int k) {\n      for (int i = st[k]; i <= ed[k]; i++) t[i] = a[i];\n      sort(t + st[k], t + ed[k] + 1);\n    }\n    \n    void PushDown(int x) {\n      if (delta[x] != 0x3f3f3f3f3f3f3f3fll)  // 用该值标记块内没有被整体赋值\n        for (int i = st[x]; i <= ed[x]; i++) a[i] = t[i] = delta[x];\n      delta[x] = 0x3f3f3f3f3f3f3f3fll;\n    }\n    \n    void Modify(int l, int r, int c) {\n      int x = belong[l], y = belong[r];\n      PushDown(x);\n      if (x == y) {\n        for (int i = l; i <= r; i++) a[i] = c;\n        Sort(x);\n        return;\n      }\n      PushDown(y);\n      for (int i = l; i <= ed[x]; i++) a[i] = c;\n      for (int i = st[y]; i <= r; i++) a[i] = c;\n      Sort(x);\n      Sort(y);\n      for (int i = x + 1; i < y; i++) delta[i] = c;\n    }\n    \n    int Binary_Search(int l, int r, int c) {\n      int ans = l - 1, mid;\n      while (l <= r) {\n        mid = (l + r) / 2;\n        if (t[mid] <= c)\n          ans = mid, l = mid + 1;\n        else\n          r = mid - 1;\n      }\n      return ans;\n    }\n    \n    int Answer(int l, int r, int c) {\n      int ans = 0, x = belong[l], y = belong[r];\n      PushDown(x);\n      if (x == y) {\n        for (int i = l; i <= r; i++)\n          if (a[i] <= c) ans++;\n        return ans;\n      }\n      PushDown(y);\n      for (int i = l; i <= ed[x]; i++)\n        if (a[i] <= c) ans++;\n      for (int i = st[y]; i <= r; i++)\n        if (a[i] <= c) ans++;\n      for (int i = x + 1; i <= y - 1; i++) {\n        if (0x3f3f3f3f3f3f3f3fll == delta[i])\n          ans += Binary_Search(st[i], ed[i], c) - st[i] + 1;\n        else if (delta[i] <= c)\n          ans += size[i];\n      }\n      return ans;\n    }\n    ```\n\n## 练习\n\n1.  [单点修改，区间查询](https://loj.ac/problem/130)\n2.  [区间修改，区间查询](https://loj.ac/problem/132)\n3.  [【模板】线段树 2](https://www.luogu.com.cn/problem/P3373)\n4.  [「Ynoi2019 模拟赛」Yuno loves sqrt technology III](https://www.luogu.com.cn/problem/P5048)\n5.  [「Violet」蒲公英](https://www.luogu.com.cn/problem/P4168)\n6.  [作诗](https://www.luogu.com.cn/problem/P4135)\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
de0cb345-4bbb-4207-b2c1-665a194944c9	b66ea86d-bcb6-43c6-83ff-f845ffd93a3e	deep	块状链表	author: HeRaNO, konnyakuxzy, littlefrog\n\n![./images/kuaizhuanglianbiao.png](./images/kuaizhuanglianbiao.png "./images/kuaizhuanglianbiao.png")\n\n块状链表大概就长这样……\n\n不难发现块状链表就是一个链表，每个节点指向一个数组．\n我们把原来长度为 n 的数组分为 $\\sqrt{n}$ 个节点，每个节点对应的数组大小为 $\\sqrt{n}$．\n所以我们这么定义结构体，代码见下．\n其中 `sqn` 表示 `sqrt(n)` 即 $\\sqrt{n}$，`pb` 表示 `push_back`，即在这个 `node` 中加入一个元素．\n\n???+ note "实现"\n    ```cpp\n    struct node {\n      node* nxt;\n      int size;\n      char d[(sqn << 1) + 5];\n    \n      node() { size = 0, nxt = NULL, memset(d, 0, sizeof(d)); }\n    \n      void pb(char c) { d[size++] = c; }\n    };\n    ```\n\n块状链表应该至少支持：分裂、插入、查找．\n什么是分裂？分裂就是分裂一个 `node`，变成两个小的 `node`，以保证每个 `node` 的大小都接近 $\\sqrt{n}$（否则可能退化成普通数组）．当一个 `node` 的大小超过 $2\\times \\sqrt{n}$ 时执行分裂操作．\n\n分裂操作怎么做呢？先新建一个节点，再把被分裂的节点的后 $\\sqrt{n}$ 个值 `copy` 到新节点，然后把被分裂的节点的后 $\\sqrt{n}$ 个值删掉（`size--`），最后把新节点插入到被分裂节点的后面即可．\n\n块状链表的所有操作的复杂度都是 $\\sqrt{n}$ 的．\n\n还有一个要说的．\n随着元素的插入（或删除），$n$ 会变，$\\sqrt{n}$ 也会变．这样块的大小就会变化，我们难道还要每次维护块的大小？\n\n其实不然，把 $\\sqrt{n}$ 设置为一个定值即可．比如题目给的范围是 $10^6$，那么 $\\sqrt{n}$ 就设置为大小为 $10^3$ 的常量，不用更改它．\n\n```cpp\nlist<vector<char>> orz_list;\n```\n\n## libstdc++ 中的 `rope`\n\n### 导入\n\nlibstdc++ 中的 `rope` 也起到块状链表的作用，它采用可持久化平衡树实现，可完成随机访问和插入、删除元素的操作．\n\n由于 `rope` 并不是真正的用块状链表来实现，所以它的时间复杂度并不等同于块状链表，而是相当于可持久化平衡树的复杂度（即 $O(\\log n)$）．\n\n可以使用如下方法来引入：\n\n```cpp\n#include <ext/rope>\nusing namespace __gnu_cxx;\n```\n\n???+ warning "关于双下划线开头的库函数"\n    OI 中，关于能否使用双下划线开头的库函数曾经一直不确定，2021 年 CCF 发布的 [关于 NOI 系列活动中编程语言使用限制的补充说明](https://www.noi.cn/xw/2021-09-01/735729.shtml) 中提到「允许使用以下划线开头的库函数或宏，但具有明确禁止操作的库函数和宏除外」．故 `rope` 目前可以在 OI 中正常使用．\n\n### 基本操作\n\n|             操作            |               作用              |\n| :-----------------------: | :---------------------------: |\n|       `rope<int> a`       | 初始化 `rope`（与 `vector` 等容器很相似） |\n|      `a.push_back(x)`     |       在 `a` 的末尾添加元素 `x`       |\n|     `a.insert(pos, x)`    |   在 `a` 的 `pos` 个位置添加元素 `x`   |\n|     `a.erase(pos, x)`     |  在 `a` 的 `pos` 个位置删除 `x` 个元素  |\n|     `a.at(x)` 或 `a[x]`    |       访问 `a` 的第 `x` 个元素       |\n| `a.length()` 或 `a.size()` |           获取 `a` 的大小          |\n\n## 例题\n\n[POJ2887 Big String](http://poj.org/problem?id=2887)\n\n题解：\n很简单的模板题．代码如下：\n\n```cpp\n--8<-- "docs/ds/code/block-list/block-list_1.cpp"\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
985f1e7f-a152-4e25-b5cf-c94195c02ddc	8d808ca8-9b07-4d83-86ee-2836da66aa01	deep	二叉搜索树 & 平衡树	author: 2323122, aofall, AtomAlpaca, Bocity, CoelacanthusHex, countercurrent-time, Early0v0, Enter-tainer, fearlessxjdx, Great-designer, H-J-Granger, hsfzLZH1, iamtwz, Ir1d, ksyx, Marcythm, NachtgeistW, ouuan, Persdre, shuzhouliu, StudyingFather, SukkaW, Tiphereth-A, wsyhb, Yesphet, yuhuoji, lingkerio, bililateral, q-wind\n\n## 定义\n\n二叉搜索树是一种二叉树的树形数据结构，其定义如下：\n\n1.  空树是二叉搜索树．\n\n2.  若二叉搜索树的左子树不为空，则其左子树上所有点的附加权值均小于其根节点的值．\n\n3.  若二叉搜索树的右子树不为空，则其右子树上所有点的附加权值均大于其根节点的值．\n\n4.  二叉搜索树的左右子树均为二叉搜索树．\n\n二叉搜索树上的基本操作所花费的时间与这棵树的高度成正比．对于一个有 $n$ 个结点的二叉搜索树中，这些操作的最优时间复杂度为 $O(\\log n)$，最坏为 $O(n)$．随机构造这样一棵二叉搜索树的期望高度为 $O(\\log n)$．\n\n## 过程\n\n### 二叉搜索树节点的定义\n\n???+ note "实现"\n    ```cpp\n    struct TreeNode {\n      int key;\n      TreeNode* left;\n      TreeNode* right;\n      // 维护其他信息，如高度，节点数量等\n      int size;   // 当前节点为根的子树大小\n      int count;  // 当前节点的重复数量\n    \n      TreeNode(int value)\n          : key(value), size(1), count(1), left(nullptr), right(nullptr) {}\n    };\n    ```\n\n### 遍历二叉搜索树\n\n由二叉搜索树的递归定义可得，二叉搜索树的中序遍历权值的序列为非降的序列．时间复杂度为 $O(n)$．\n\n遍历一棵二叉搜索树的代码如下：\n\n???+ note "实现"\n    ```cpp\n    void inorderTraversal(TreeNode* root) {\n      if (root == nullptr) {\n        return;\n      }\n      inorderTraversal(root->left);\n      std::cout << root->key << " ";\n      inorderTraversal(root->right);\n    }\n    ```\n\n### 查找最小/最大值\n\n由二叉搜索树的性质可得，二叉搜索树上的最小值为二叉搜索树左链的顶点，最大值为二叉搜索树右链的顶点．时间复杂度为 $O(h)$．\n\n???+ note "实现"\n    ```cpp\n    int findMin(TreeNode* root) {\n      if (root == nullptr) {\n        return -1;\n      }\n      while (root->left != nullptr) {\n        root = root->left;\n      }\n      return root->key;\n    }\n    \n    int findMax(TreeNode* root) {\n      if (root == nullptr) {\n        return -1;\n      }\n      while (root->right != nullptr) {\n        root = root->right;\n      }\n      return root->key;\n    }\n    ```\n\n### 搜索元素\n\n在以 `root` 为根节点的二叉搜索树中搜索一个值为 `value` 的节点．\n\n分类讨论如下：\n\n-   若 `root` 为空，返回 `false`．\n-   若 `root` 的权值等于 `value`，返回 `true`．\n-   若 `root` 的权值大于 `value`，在 `root` 的左子树中继续搜索．\n-   若 `root` 的权值小于 `value`，在 `root` 的右子树中继续搜索．\n\n时间复杂度为 $O(h)$．\n\n???+ note "实现"\n    ```cpp\n    bool search(TreeNode* root, int target) {\n      if (root == nullptr) {\n        return false;\n      }\n      if (root->key == target) {\n        return true;\n      } else if (target < root->key) {\n        return search(root->left, target);\n      } else {\n        return search(root->right, target);\n      }\n    }\n    ```\n\n插入，删除，修改都需要先在二叉搜索树中进行搜索．\n\n### 插入一个元素\n\n在以 `root` 为根节点的二叉搜索树中插入一个值为 `value` 的节点．\n\n分类讨论如下：\n\n-   若 `root` 为空，直接返回一个值为 `value` 的新节点．\n\n-   若 `root` 的权值等于 `value`，该节点的附加域该值出现的次数自增 $1$．\n\n-   若 `root` 的权值大于 `value`，在 `root` 的左子树中插入权值为 `value` 的节点．\n\n-   若 `root` 的权值小于 `value`，在 `root` 的右子树中插入权值为 `value` 的节点．\n\n时间复杂度为 $O(h)$．\n\n???+ note "实现"\n    ```cpp\n    TreeNode* insert(TreeNode* root, int value) {\n      if (root == nullptr) {\n        return new TreeNode(value);\n      }\n      if (value < root->key) {\n        root->left = insert(root->left, value);\n      } else if (value > root->key) {\n        root->right = insert(root->right, value);\n      } else {\n        root->count++;  // 节点值相等，增加重复数量\n      }\n      root->size = root->count + (root->left ? root->left->size : 0) +\n                   (root->right ? root->right->size : 0);  // 更新节点的子树大小\n      return root;\n    }\n    ```\n\n### 删除一个元素\n\n在以 `root` 为根节点的二叉搜索树中删除一个值为 `value` 的节点．\n\n先在二叉搜索树中搜索权值为 `value` 的节点，分类讨论如下：\n\n-   若该节点的附加 `count` 大于 $1$，只需要减少 `count`．\n\n-   若该节点的附加 `count` 为 $1$：\n\n    -   若 `root` 为叶子节点，直接删除该节点即可．\n\n    -   若 `root` 为链节点，即只有一个儿子的节点，返回这个儿子．\n\n    -   若 `root` 有两个非空子节点，一般是用它左子树的最大值（左子树最右的节点）或右子树的最小值（右子树最左的节点）代替它，然后将它删除．\n\n时间复杂度 $O(h)$．\n\n???+ note "实现"\n    方法使用 `root = remove(root, 1)` 表示删除根节点为 `root` 树中值为 1 的节点，并返回新的根节点．\n    \n    ```cpp\n    // 此处返回值为删除 value 后的新 root\n    TreeNode* remove(TreeNode* root, int value) {\n      if (root == nullptr) {\n        return root;\n      }\n      if (value < root->key) {\n        root->left = remove(root->left, value);\n      } else if (value > root->key) {\n        root->right = remove(root->right, value);\n      } else {\n        if (root->count > 1) {\n          root->count--;  // 节点重复数量大于1，减少重复数量\n        } else {\n          if (root->left == nullptr) {\n            TreeNode* temp = root->right;\n            delete root;\n            return temp;\n          } else if (root->right == nullptr) {\n            TreeNode* temp = root->left;\n            delete root;\n            return temp;\n          } else {\n            TreeNode* successor = findMinNode(root->right);\n            root->key = successor->key;\n            root->count = successor->count;  // 更新重复数量\n            // 当 successor->count > 1时，也应该删除该节点，否则\n            // 后续的删除只会减少重复数量\n            successor->count = 1;\n            root->right = remove(root->right, successor->key);\n          }\n        }\n      }\n      // 继续维护size，不写成 --root->size;\n      // 是因为value可能不在树中，从而可能未发生删除\n      root->size = root->count + (root->left ? root->left->size : 0) +\n                   (root->right ? root->right->size : 0);\n      return root;\n    }\n    \n    // 此处以右子树的最小值为例\n    TreeNode* findMinNode(TreeNode* root) {\n      while (root->left != nullptr) {\n        root = root->left;\n      }\n      return root;\n    }\n    ```\n\n### 求元素的排名\n\n排名定义为将数组元素升序排序后第一个相同元素之前的数的个数加一．\n\n查找一个元素的排名，首先从根节点跳到这个元素，若向右跳，答案加上左儿子节点个数加当前节点重复的数个数，最后答案加上终点的左儿子子树大小加一．\n\n时间复杂度 $O(h)$．\n\n???+ note "实现"\n    ```cpp\n    int queryRank(TreeNode* root, int v) {\n      if (root == nullptr) return 0;\n      if (root->key == v) return (root->left ? root->left->size : 0) + 1;\n      if (root->key > v) return queryRank(root->left, v);\n      return queryRank(root->right, v) + (root->left ? root->left->size : 0) +\n             root->count;\n    }\n    ```\n\n### 查找排名为 k 的元素\n\n在一棵子树中，根节点的排名取决于其左子树的大小．\n\n-   若其左子树的大小大于等于 $k$，则该元素在左子树中；\n\n-   若其左子树的大小在区间 $[k-\\textit{count},k-1]$（`count` 为当前结点的值的出现次数）中，则该元素为子树的根节点；\n\n-   若其左子树的大小小于 $k-\\textit{count}$，则该元素在右子树中．\n\n时间复杂度 $O(h)$．\n\n???+ note "实现"\n    ```cpp\n    int querykth(TreeNode* root, int k) {\n      if (root == nullptr) return -1;  // 或者根据需求返回其他合适的值\n      if (root->left) {\n        if (root->left->size >= k) return querykth(root->left, k);\n        if (root->left->size + root->count >= k) return root->key;\n      } else {\n        if (k <= root->count) return root->key;\n      }\n      return querykth(root->right,\n                      k - (root->left ? root->left->size : 0) - root->count);\n    }\n    ```\n\n## 平衡树简介\n\n使用搜索树的目的之一是缩短插入、删除、修改和查找（插入、删除、修改都包括查找操作）节点的时间．\n\n关于查找效率，如果一棵树的高度为 $h$，在最坏的情况，查找一个关键字需要对比 $h$ 次，查找时间复杂度（也为平均查找长度 ASL，Average Search Length）不超过 $O(h)$．一棵理想的二叉搜索树所有操作的时间可以缩短到 $O(\\log n)$（n 是节点总数）．\n\n然而 $O(\\log n)$ 的时间复杂度仅为理想情况．在最坏情况下，搜索树有可能退化为链表．想象一棵每个结点只有右孩子的二叉搜索树，那么它的性质就和链表一样，所有操作（增删改查）的时间是 $O(n)$．\n\n可以发现操作的复杂度与树的高度 $h$ 有关．由此引出了平衡树，通过一定操作维持树的高度（平衡性）来降低操作的复杂度．\n\n### 平衡性的定义\n\n关于一棵搜索树是否「**平衡**」，不同的平衡树中对「**平衡**」有着不同的定义．比如以 T 为根节点的二叉搜索树，左子树和右子树的高度相差很大，或者左子树的节点个数远大于右子树的节点个数，这棵树显然不具有平衡性．\n\n对于二叉搜索树来说，常见的平衡性的定义是指：以 T 为根节点的树，每一个结点的左子树和右子树高度差最多为 1．\n\n-   [Splay 树](splay.md) 中，对于任意节点的访问操作（搜索、插入还是删除），都会将被访问的节点移动到树的根节点位置．\n\n-   [AVL 树](avl.md) 每个节点 N 维护以 N 为根节点的树的高度信息．AVL 树对平衡性的定义：如果 T 是一棵 AVL 树，当且仅当左右子树也是 AVL 树，且 $|height(T->left) - height(T->right)| \\leq 1$．\n\n-   [Size Balanced Tree](sbt.md) 每个节点 N 维护以 N 为根节点的树中节点个数 `size`．对平衡性的定义：任意节点的 `size` 不小于其兄弟节点（Sibling）的所有子节点（Nephew）的 `size`．\n\n此外，对于拥有同样元素值集合的搜索树，平衡状态可能是不唯一的．也就是说，可能两棵不同的搜索树，含有的元素值集合相同，并且都是平衡的．\n\n### 平衡的调整过程\n\n对不满足平衡条件的搜索树进行调整操作，可以使不平衡的搜索树重新具有平衡性．\n\n关于二叉平衡树，平衡的调整操作分为包括 **左旋（Left Rotate 或者 zag）** 和 **右旋（Right Rotate 或者 zig）** 两种．由于二叉平衡树在调整时需要保证中序遍历序列不变．这两种操作均不改变中序遍历序列．\n\n在这里先介绍右旋，右旋也称为「右单旋转」或「LL 平衡旋转」．对于结点 $A$ 的右旋操作是指：将 $A$ 的左孩子 $B$ 向右上旋转，代替 $A$ 成为根节点，将 $A$ 结点向右下旋转成为 $B$ 的右子树的根结点，$B$ 的原来的右子树变为 $A$ 的左子树．\n\n![bst-rotate](images/bst-rotate.svg)\n\n右旋操作只改变了三组结点关联，相当于对三组边进行循环置换一下，因此需要暂存一个结点再进行轮换更新．\n\n对于右旋操作一般的更新顺序是：暂存 $B$ 结点（新的根节点），让 $A$ 的左孩子指向 $B$ 的右子树 $T2$，再让 $B$ 的右孩子指针指向 $A$，最后让 $A$ 的父结点指向暂存的 $B$．\n\n完全同理，有对应的左旋操作，也称为「左单旋转」或「RR 平衡旋转」．左旋操作与右旋操作互为镜像．\n\n下面给出左旋和右旋的代码．\n\n???+ note "实现"\n    ```cpp\n    TreeNode* rotateLeft(TreeNode* root) {\n      TreeNode* newRoot = root->right;\n      root->right = newRoot->left;\n      newRoot->left = root;\n      // 更新相关节点的信息\n      updateHeight(root);\n      updateHeight(newRoot);\n      return newRoot;  // 返回新的根节点\n    }\n    \n    TreeNode* rotateRight(TreeNode* root) {\n      TreeNode* newRoot = root->left;\n      root->left = newRoot->right;\n      newRoot->right = root;\n      updateHeight(root);\n      updateHeight(newRoot);\n      return newRoot;\n    }\n    ```\n\n对于这段示例代码，在调用时需要保存 `root` 的父节点 `pre`．方法返回指向新的根节点的指针，只需要将 `pre` 指向新的根节点即可．\n\n#### 四种平衡性破坏的情况\n\n虽然不同的二叉平衡树的定义有所区别，不同二叉平衡树区别只在于节点维护的信息不同，以及旋转调整后节点更新的信息不同．二叉平衡树平衡性被破坏的情况只有以下四种．进行平衡性调整的操作只包括左旋和右旋．以下先介绍四种情况，再对不同的二叉平衡树进行对比．\n\nLL 型：T 的左孩子的左子树过长导致平衡性破坏．\n\n调整方式：右旋节点 T．\n\n![bst-LL](images/bst-LL.svg)\n\nRR 型：与 LL 型类似，T 的右孩子的右子树过长导致平衡性破坏．\n\n调整方式：左旋节点 T．\n\n![bst-RR](images/bst-RR.svg)\n\nLR 型：T 的左孩子的右子树过长导致平衡性破坏．\n\n调整方式：先左旋节点 L，成为 LL 型，再右旋节点 T．\n\n![bst-LR](images/bst-LR.svg)\n\nRL 型：与 LR 型类似，T 的右孩子的左子树过长导致平衡性破坏．\n\n调整方式：先右旋节点 R，成为 RR 型，再左旋节点 T．\n\n![bst-RL](images/bst-RL.svg)\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
23eb54ad-8162-4644-943e-52602f4a6f88	146df4da-12da-4e1a-a0a1-bee1f94fb1db	deep	笛卡尔树	author: sshwy, zhouyuyang2002, StudyingFather, Ir1d, ouuan, Enter-tainer\n\n## 引入\n\n笛卡尔树是一种二叉树，每一个节点由一个键值二元组 $(k,w)$ 构成．要求 $k$ 满足二叉搜索树（BST）的性质，而 $w$ 满足堆的性质．如果笛卡尔树的 $k,w$ 键值确定，且 $k$ 互不相同，$w$ 也互不相同，那么这棵笛卡尔树的结构是唯一的．如下图：\n\n![eg](./images/cartesian-tree1.png)\n\n（图源自维基百科）\n\n上面这棵笛卡尔树相当于把数组元素值当作键值 $w$，而把数组下标当作键值 $k$．可以发现，这棵树的键值 $k$ 满足 BST 的性质，而键值 $w$ 满足小根堆的性质．同时根据二叉搜索树的性质，可以发现这种特殊的笛卡尔树满足一棵子树内的下标是一个连续区间．\n\n竞赛中使用笛卡尔树时，常用数组下标作为二元组的键值 $k$，数组下标 $k$ 满足 BST 性质．\n\n下文使用 $k,w$ 时，默认 $k$ 满足 BST 性质，$w$ 满足堆的性质．\n\n## 单调栈构建笛卡尔树\n\n### 过程\n\n我们考虑将元素按 $k$ 升序依次插入到当前的笛卡尔树中．\n\n对于一棵笛卡尔树，定义「右链」为从根节点开始一直走右儿子，走到叶节点形成的链．则插入节点后，这个节点一定在右链上．因为是按照满足 BST 性质的 $k$ 升序插入，那么这个新插入的节点必然在树的 **最右端**．这个节点不可能是一个左儿子，也没有右儿子．\n\n于是我们执行这样一个过程，从下往上比较右链节点与当前节点 $u$ 的 $w$，如果找到了一个右链上的节点 $x$ 满足 $w_x<w_u$，就把 $u$ 接到 $x$ 的右儿子上，而 $x$ 原本的右子树就变成 $u$ 的左子树．\n\n图中红框部分就是我们始终维护的右链：\n\n![build](./images/cartesian-tree2.png)\n\n显然每个数最多进出右链一次（或者说每个点在右链中存在的是一段连续的时间）．这个过程可以用单调栈维护，栈中维护当前笛卡尔树的右链上的节点．一个点不在右链上了就把它弹掉．这样每个点最多进出一次，复杂度 $O(n)$．\n\n???+ note "笛卡尔树与 Treap"\n    实际上，Treap 是笛卡尔树的一种，只不过 Treap 中 $w$ 的值完全随机．Treap 有线性的构建算法，如果提前将键值 $k$ 排好序，是可以使用上述单调栈算法完成构建过程的，只不过很少会这么用．\n\n### C++ 实现\n\n```cpp\n// stk 维护笛卡尔树中节点对应到序列中的下标\nfor (int i = 1; i <= n; i++) {\n  int k = top;  // top 表示操作前的栈顶，k 表示当前栈顶\n  while (k > 0 && w[stk[k]] > w[i]) k--;  // 维护右链上的节点\n  if (k) rs[stk[k]] = i;  // 栈顶元素.右儿子 := 当前元素\n  if (k < top) ls[i] = stk[k + 1];  // 当前元素.左儿子 := 上一个被弹出的元素\n  stk[++k] = i;                     // 当前元素入栈\n  top = k;\n}\n```\n\n## 例题\n\n???+ note "[HDU 1506. Largest Rectangle in a Histogram](https://acm.hdu.edu.cn/showproblem.php?pid=1506)"\n    $n$ 个位置，每个位置上的高度是 $h_i$，求最大子矩形．如下图：\n    \n    ![eg](./images/cartesian-tree3.png)\n    \n    阴影部分就是图中的最大子矩阵．\n\n??? note "解题思路"\n    具体地，我们把下标作为键值 $k$，$h_i$ 作为键值 $w$ 满足小根堆性质，构建一棵 $(i,h_i)$ 的笛卡尔树．\n    \n    这样我们枚举每个节点 $u$，把 $w_u$（即节点 $u$ 的高度 $h$）作为最大子矩阵的高度．由于我们建立的笛卡尔树满足小根堆性质，因此 $u$ 的子树内的节点的高度都大于等于 $u$．而我们又知道 $u$ 子树内的下标是一段连续的区间．于是我们只需要知道子树的大小，然后就可以算这个区间的最大子矩阵的面积了．用每一个点计算出来的值更新答案即可．显然这个可以一次 DFS 完成，因此复杂度是 $O(n)$ 的．\n\n??? note "参考实现"\n    ```cpp\n    --8<-- "docs/ds/code/cartesian-tree/cartesian-tree_1.cpp"\n    ```\n\n## 参考资料\n\n[笛卡尔树 - 维基百科](https://zh.wikipedia.org/wiki/%E7%AC%9B%E5%8D%A1%E5%B0%94%E6%A0%91)\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
fa857108-a48b-4c39-8db4-d641ad29aec3	e6174b0e-8e26-4615-94fd-00a7b02a468a	deep	猫树	author: ChungZH, billchenchina, Chrogeek, Early0v0, ethan-enhe, HeRaNO, hsfzLZH1, iamtwz, Ir1d, konnyakuxzy, luoguojie, Marcythm, orzAtalod, StudyingFather, wy-luke, Xeonacid, CCXXXI, chenryang, chenzheAya, CJSoft, cjsoft, countercurrent-time, DawnMagnet, Enter-tainer, GavinZhengOI, Haohu Shen, Henry-ZHR, hjsjhn, hly1204, jaxvanyang, Jebearssica, kenlig, ksyx, megakite, Menci, moon-dim, NachtgeistW, onelittlechildawa, ouuan, shadowice1984, shawlleyw, shuzhouliu, SukkaW, Tiphereth-A, x2e6, Ycrpro, yifan0305, zeningc, hcx2012Git\n\n## 引入\n\n众所周知线段树可以支持高速查询某一段区间的信息和，比如区间最大子段和，区间和，区间矩阵的连乘积等等．\n\n但是有一个问题在于普通线段树的区间询问在某些毒瘤的眼里可能还是有些慢了．\n\n简单来说就是线段树建树的时候需要做 $O(n)$ 次合并操作，而每一次区间询问需要做 $O(\\log{n})$ 次合并操作，询问区间和这种东西的时候还可以忍受，但是当我们需要询问区间线性基这种合并复杂度高达 $O(\\log^2{w})$ 的信息的话，此时就算是做 $O(\\log{n})$ 次合并有些时候在时间上也是不可接受的．\n\n而所谓「猫树」就是一种不支持修改，仅仅支持快速区间询问的一种静态线段树．\n\n构造一棵这样的静态线段树需要 $O(n\\log{n})$ 次合并操作，但是此时的查询复杂度被加速至 $O(1)$ 次合并操作．\n\n在处理线性基这样特殊的信息的时候甚至可以将复杂度降至 $O(n\\log^2{w})$．\n\n## 原理\n\n在查询 $[l,r]$ 这段区间的信息和的时候，将线段树树上代表 $[l,l]$ 的节点和代表 $[r,r]$ 这段区间的节点在线段树上的 LCA 求出来，设这个节点 $p$ 代表的区间为 $[L,R]$，我们会发现一些非常有趣的性质：\n\n1.  $[L,R]$ 这个区间一定包含 $[l,r]$．显然，因为它既是 $l$ 的祖先又是 $r$ 的祖先．\n\n2.  $[l,r]$ 这个区间一定跨越 $[L,R]$ 的中点．由于 $p$ 是 $l$ 和 $r$ 的 LCA，这意味着 $p$ 的左儿子是 $l$ 的祖先而不是 $r$ 的祖先，$p$ 的右儿子是 $r$ 的祖先而不是 $l$ 的祖先．因此，$l$ 一定在 $[L,\\mathit{mid}]$ 这个区间内，$r$ 一定在 $(\\mathit{mid},R]$ 这个区间内．\n\n有了这两个性质，我们就可以将询问的复杂度降至 $O(1)$ 了．\n\n## 实现\n\n具体来讲我们建树的时候对于线段树树上的一个节点，设它代表的区间为 $(l,r]$．\n\n不同于传统线段树在这个节点里只保留 $[l,r]$ 的和，我们在这个节点里面额外保存 $(l,\\mathit{mid}]$ 的后缀和数组和 $(\\mathit{mid},r]$ 的前缀和数组．\n\n这样的话建树的复杂度为 $T(n)=2T(n/2)+O(n)=O(n\\log{n})$ 同理空间复杂度也从原来的 $O(n)$ 变成了 $O(n\\log{n})$．\n\n下面是最关键的询问了．\n\n如果我们询问的区间是 $[l,r]$ 那么我们把代表 $[l,l]$ 的节点和代表 $[r,r]$ 的节点的 LCA 求出来，记为 $p$．\n\n根据刚才的两个性质，$l,r$ 在 $p$ 所包含的区间之内并且一定跨越了 $p$ 的中点．\n\n这意味这一个非常关键的事实是我们可以使用 $p$ 里面的前缀和数组和后缀和数组，将 $[l,r]$ 拆成 $[l,\\mathit{mid}]+(\\mathit{mid},r]$ 从而拼出来 $[l,r]$ 这个区间．\n\n而这个过程仅仅需要 $O(1)$ 次合并操作！\n\n不过我们好像忽略了点什么？\n\n似乎求 LCA 的复杂度似乎还不是 $O(1)$，暴力求是 $O(\\log{n})$ 的，倍增法则是 $O(\\log{\\log{n}})$ 的，转 ST 表的代价又太大……\n\n## 堆式建树\n\n具体来将我们将这个序列补成 $2$ 的整次幂，然后建线段树．\n\n此时我们发现线段树上两个节点的 LCA 编号，就是两个节点二进制编号的最长公共前缀 LCP．\n\n稍作思考即可发现在 $x$ 和 $y$ 的二进制下 `lcp(x,y)=x>>digits[x^y]`．（其中 `digits[x]` 表示二进制下 $x$ 的位数，即 $\\lfloor \\log_2 x \\rfloor+1$）\n\n所以我们预处理一个 `digits` 数组即可轻松完成求 LCA 的工作．\n\n这样我们就构建了一个猫树．\n\n由于建树的时候涉及到求前缀和和求后缀和，所以对于线性基这种虽然合并是 $O(\\log^2{w})$ 但是求前缀和却是 $O(n\\log{n})$ 的信息，使用猫树可以将静态区间线性基从 $O(n\\log^2{w}+m\\log^2{w}\\log{n})$ 优化至 $O(n\\log{n}\\log{w}+m\\log^2{w})$ 的复杂度．\n\n### 参考\n\n-   [immortalCO 的博客](https://immortalco.blog.uoj.ac/blog/2102)\n-   [\\[Kle77\\]](http://ieeexplore.ieee.org/document/1675628/) V. Klee, "Can the Measure of be Computed in Less than O (n log n) Steps?," Am. Math. Mon., vol. 84, no. 4, pp. 284–285, Apr. 1977.\n-   [\\[BeW80\\]](https://www.tandfonline.com/doi/full/10.1080/00029890.1977.11994336) Bentley and Wood, "An Optimal Worst Case Algorithm for Reporting Intersections of Rectangles," IEEE Trans. Comput., vol. C–29, no. 7, pp. 571–577, Jul. 1980.\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
45bbc569-75f8-437b-b93a-416b8fa8ea57	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	deep	分块思想	author: Ir1d, HeRaNO, Xeonacid\n\n## 简介\n\n其实，分块是一种思想，而不是一种数据结构．\n\n从 NOIP 到 NOI 到 IOI，各种难度的分块思想都有出现．\n\n分块的基本思想是，通过对原数据的适当划分，并在划分后的每一个块上预处理部分信息，从而较一般的暴力算法取得更优的时间复杂度．\n\n分块的时间复杂度主要取决于分块的块长，一般可以通过均值不等式求出某个问题下的最优块长，以及相应的时间复杂度．\n\n分块是一种很灵活的思想，相较于树状数组和线段树，分块的优点是通用性更好，可以维护很多树状数组和线段树无法维护的信息．\n\n当然，分块的缺点是渐近意义的复杂度，相较于线段树和树状数组不够好．\n\n不过在大多数问题上，分块仍然是解决这些问题的一个不错选择．\n\n下面是几个例子．\n\n## 区间和\n\n??? note "例题 [LibreOJ 6280 数列分块入门 4](https://loj.ac/problem/6280)"\n    给定一个长度为 $n$ 的序列 $\\{a_i\\}$，需要执行 $n$ 次操作．操作分为两种：\n    \n    1.  给 $a_l \\sim a_r$ 之间的所有数加上 $x$；\n    2.  求 $\\sum_{i=l}^r a_i$．\n    \n        $1 \\leq n \\leq 5 \\times 10^4$\n\n我们将序列按每 $s$ 个元素一块进行分块，并记录每块的区间和 $b_i$．\n\n$$\n\\underbrace{a_1, a_2, \\ldots, a_s}_{b_1}, \\underbrace{a_{s+1}, \\ldots, a_{2s}}_{b_2}, \\dots, \\underbrace{a_{(s-1) \\times s+1}, \\dots, a_n}_{b_{\\frac{n}{s}}}\n$$\n\n最后一个块可能是不完整的（因为 $n$ 很可能不是 $s$ 的倍数），但是这对于我们的讨论来说并没有太大影响．\n\n首先看查询操作：\n\n-   若 $l$ 和 $r$ 在同一个块内，直接暴力求和即可，因为块长为 $s$，因此最坏复杂度为 $O(s)$．\n-   若 $l$ 和 $r$ 不在同一个块内，则答案由三部分组成：以 $l$ 开头的不完整块，中间几个完整块，以 $r$ 结尾的不完整块．对于不完整的块，仍然采用上面暴力计算的方法，对于完整块，则直接利用已经求出的 $b_i$ 求和即可．这种情况下，最坏复杂度为 $O(\\dfrac{n}{s}+s)$．\n\n接下来是修改操作：\n\n-   若 $l$ 和 $r$ 在同一个块内，直接暴力修改即可，因为块长为 $s$，因此最坏复杂度为 $O(s)$．\n-   若 $l$ 和 $r$ 不在同一个块内，则需要修改三部分：以 $l$ 开头的不完整块，中间几个完整块，以 $r$ 结尾的不完整块．对于不完整的块，仍然是暴力修改每个元素的值（别忘了更新区间和 $b_i$），对于完整块，则直接修改 $b_i$ 即可．这种情况下，最坏复杂度和仍然为 $O(\\dfrac{n}{s}+s)$．\n\n利用均值不等式可知，当 $\\dfrac{n}{s}=s$，即 $s=\\sqrt n$ 时，单次操作的时间复杂度最优，为 $O(\\sqrt n)$．\n\n??? note "参考代码"\n    ```cpp\n    --8<-- "docs/ds/code/decompose/decompose_1.cpp"\n    ```\n\n## 区间和 2\n\n上一个做法的复杂度是 $\\Omega(1) , O(\\sqrt{n})$．\n\n我们在这里介绍一种 $O(\\sqrt{n}) - O(1)$ 的算法．\n\n为了 $O(1)$ 询问，我们可以维护各种前缀和．\n\n然而在有修改的情况下，不方便维护，只能维护单个块内的前缀和．\n\n以及整块作为一个单位的前缀和．\n\n每次修改 $O(T+\\frac{n}{T})$．\n\n询问：涉及三部分，每部分都可以直接通过前缀和得到，时间复杂度 $O(1)$．\n\n## 对询问分块\n\n同样的问题，现在序列长度为 $n$，有 $m$ 个操作．\n\n如果操作数量比较少，我们可以把操作记下来，在询问的时候加上这些操作的影响．\n\n假设最多记录 $T$ 个操作，则修改 $O(1)$，询问 $O(T)$．\n\n$T$ 个操作之后，重新计算前缀和，$O(n)$．\n\n总复杂度：$O(mT+n\\frac{m}{T})$．\n\n$T=\\sqrt{n}$ 时，总复杂度 $O(m \\sqrt{n})$．\n\n### 其他问题\n\n分块思想也可以应用于其他整数相关问题：寻找零元素的数量、寻找第一个非零元素、计算满足某个性质的元素个数等等．\n\n还有一些问题可以通过分块来解决，例如维护一组允许添加或删除数字的集合，检查一个数是否属于这个集合，以及查找第 $k$ 大的数．要解决这个问题，必须将数字按递增顺序存储，并分割成多个块，每个块中包含 $\\sqrt{n}$ 个数字．每次添加或删除一个数字时，必须通过在相邻块的边界移动数字来重新分块．\n\n一种很有名的离线算法 [莫队算法](../misc/mo-algo.md)，也是基于分块思想实现的．\n\n## 练习题\n\n-   [UVa - 12003 - Array Transformer](https://uva.onlinejudge.org/index.php?option=com_onlinejudge&Itemid=8&page=show_problem&problem=3154)\n-   [UVa - 11990 Dynamic Inversion](https://uva.onlinejudge.org/index.php?option=com_onlinejudge&Itemid=8&page=show_problem&problem=3141)\n-   [SPOJ - Give Away](http://www.spoj.com/problems/GIVEAWAY/)\n-   [Codeforces - Till I Collapse](http://codeforces.com/contest/786/problem/C)\n-   [Codeforces - Destiny](http://codeforces.com/contest/840/problem/D)\n-   [Codeforces - Holes](http://codeforces.com/contest/13/problem/E)\n-   [Codeforces - XOR and Favorite Number](https://codeforces.com/problemset/problem/617/E)\n-   [Codeforces - Powerful array](http://codeforces.com/problemset/problem/86/D)\n-   [SPOJ - DQUERY](https://www.spoj.com/problems/DQUERY)\n\n    **本页面主要译自博文 [Sqrt-декомпозиция](http://e-maxx.ru/algo/sqrt_decomposition) 与其英文翻译版 [Sqrt Decomposition](https://cp-algorithms.com/data_structures/sqrt_decomposition.html)．其中俄文版版权协议为 Public Domain + Leave a Link；英文版版权协议为 CC-BY-SA 4.0．**\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
c85667cf-dac2-40e0-8b3a-e1ea06b264ef	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	deep	树分块	author: ouuan, Ir1d, Marcythm, Xeonacid\n\n## 树分块的方式\n\n可以参考 [真 - 树上莫队](../misc/mo-algo-on-tree.md)．\n\n也可以参考 [ouuan 的博客/莫队、带修莫队、树上莫队详解/树上莫队](https://ouuan.github.io/莫队、带修莫队、树上莫队详解/#树上莫队)．\n\n树上莫队同样可以参考以上两篇文章．\n\n## 树分块的应用\n\n树分块除了应用于莫队，还可以灵活地运用到某些树上问题中．但可以用树分块解决的题目往往都有更优秀的做法，所以相关的题目较少．\n\n顺带提一句，「gty 的妹子树」的树分块做法可以被菊花图卡掉．\n\n### [BZOJ4763 雪辉](https://hydro.ac/p/bzoj-P4763)\n\n先进行树分块，然后对每个块的关键点，预处理出它到祖先中每个关键点的路径上颜色的 bitset，以及每个关键点的最近关键点祖先，复杂度是 $O(n\\sqrt n+\\frac{nc}{32})$，其中 $n\\sqrt n$ 是暴力从每个关键点向上跳的复杂度，$\\frac{nc}{32}$ 是把 $O(n)$ 个 `bitset` 存下来的复杂度．\n\n回答询问的时候，先从路径的端点暴力跳到所在块的关键点，再从所在块的关键点一块一块地向上跳，直到 $lca$ 所在块，然后再暴力跳到 $lca$．关键点之间的 `bitset` 已经预处理了，剩下的在暴力跳的过程中计算．单次询问复杂度是 $O(\\sqrt n+\\frac c{32})$，其中 $\\sqrt n$ 是块内暴力跳以及块直接向上跳的复杂度，$O(\\frac c{32})$ 是将预处理的结果与暴力跳的结果合并的复杂度．数颜色个数可以用 `bitset` 的 `count()`，求 $\\operatorname{mex}$ 可以用 `bitset` 的 `_Find_first()`．\n\n所以，总复杂度为 $O((n+m)(\\sqrt n+\\frac c{32}))$．\n\n??? note "参考代码"\n    ```cpp\n    --8<-- "docs/ds/code/tree-decompose/tree-decompose_1.cpp"\n    ```\n\n### [BZOJ4812 由乃打扑克](https://hydro.ac/p/bzoj-P4812)\n\n这题和上一题基本一样，唯一的区别是得到 `bitset` 后如何计算答案．\n\n~~由于 BZOJ 是计算所有测试点总时限，不好卡，所以可以用 `_Find_next()` 水过去．~~\n\n正解是每 $16$ 位一起算，先预处理出 $2^{16}$ 种可能的情况高位连续 $1$ 的个数、低位连续 $1$ 的个数以及中间的贡献．只不过这样要手写 `bitset`，因为标准库的 `bitset` 不能取某 $16$ 位……\n\n代码可以参考 [这篇博客](https://www.cnblogs.com/FallDream/p/bzoj4763.html)．\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
7aac040b-73ff-468d-a83d-f6bdd97af9ca	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	deep	数论分块	数论分块可以快速计算一些形如\n\n$$\n\\sum_{i=1}^nf(i)g\\left(\\left\\lfloor\\dfrac ni\\right\\rfloor\\right)\n$$\n\n的和式．如果可以在 $O(1)$ 时间内计算出 $\\sum_{i=l}^{r}f(i)$ 或已经预处理出 $f$ 的前缀和时，数论分块就可以在 $O(\\sqrt{n})$ 时间内计算出上述和式的值．\n\n数论分块常与 [莫比乌斯反演](./mobius.md) 等技巧结合使用．\n\n## 思路\n\n首先，本文通过一个简单的例子来说明数论分块的思路．假设要计算如图所示的双曲线下的整点个数：\n\n![双曲线下整点](./images/sqrt-decomposition.svg)\n\n这相当于在计算和式：\n\n$$\n\\sum_{i=1}^{11}\\left\\lfloor\\dfrac{11}{i}\\right\\rfloor.\n$$\n\n这是前文所示和式在 $f(k)=1,~g(k)=k$ 时的特殊情况．\n\n最简单的做法当然是逐列计算然后求和，但是这样需要计算第 $i=1,2,\\cdots,11$ 列中每列整点的个数．观察图示可以发现，这些整点列的可以分成 $5$ 块，每块内点列的高度是一致的，形成一个矩形点阵．所以，只要能够知道这些块的宽度，就能够通过计算这些矩形块的大小快速完成统计．\n\n这就是整除分块的基本思路．\n\n## 性质\n\n本节讨论关于双曲线 $y = \\dfrac{n}{x}$ 下整点分块的若干结论．具体地，需要将 $1\\sim n$ 之间的整数按照 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 的取值分为若干块．设\n\n$$\nD(n) = \\left\\{\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor : 1 \\le i \\le n,~i\\in\\mathbf N_+\\right\\}.\n$$\n\n这就是 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 所有可能的取值集合．\n\n首先，这样的不同取值只有 $O(\\sqrt{n})$ 个．所以，数论分块得到的块的数目只有 $O(\\sqrt{n})$ 个．\n\n???+ note "性质 1"\n    $|D(n)|\\le 2\\sqrt{n}$．\n\n??? note "证明"\n    分两种情况讨论：\n    \n    -   当 $i\\le\\sqrt{n}$ 时，$i$ 的取值至多 $\\sqrt{n}$ 个，所以 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 的取值也至多只有 $\\sqrt{n}$ 个．\n    -   当 $i>\\sqrt{n}$ 时，$\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor \\le\\dfrac{n}{i} < \\sqrt{n}$ 也至多只有 $\\sqrt{n}$ 个取值．\n    \n    因此，所有可能取值的总数 $|D(n)|\\le 2\\sqrt{n}$．\n\n通过更细致的分析，实际上可以精确地描述集合 $D(n)$ 及其大小．\n\n???+ note "性质 2"\n    设 $s = \\lfloor\\sqrt{n}\\rfloor$．集合 $D(n)$ 中的元素从小到大依次是\n    \n    $$\n    1 < 2 < \\cdots < s-1 < s \\le \\left\\lfloor\\dfrac{n}{s}\\right\\rfloor < \\left\\lfloor\\dfrac{n}{s-1}\\right\\rfloor < \\cdots < \\left\\lfloor\\dfrac{n}{2}\\right\\rfloor < \\left\\lfloor\\dfrac{n}{1}\\right\\rfloor = n.\n    $$\n    \n    进而，$|D(n)| = \\lfloor \\sqrt{4n+1}\\rfloor - 1$．\n\n??? note "证明"\n    首先，对于 $1 \\le i \\le s$，可以证明 $\\left\\lfloor\\dfrac{n}{\\lfloor n/i\\rfloor}\\right\\rfloor = i$．令 $d = \\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$，需要证明 $\\left\\lfloor\\dfrac{n}{d}\\right\\rfloor = i$．写成不等式，这相当于已知 $d \\le \\dfrac{n}{i} < d + 1$，需要证明 $i \\le \\dfrac{n}{d} < i + 1$．已知条件可以写作 $i\\le\\dfrac{n}{d} < i + \\dfrac{i}{d}$，因此，只需要证明 $\\dfrac{i}{d} \\le 1$，亦即 $i \\le d = \\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$．这等价于 $i \\le \\dfrac{n}{i}$，这对于所有 $1 \\le i \\le s \\le \\sqrt{n}$ 都成立．\n    \n    这一结果实际上说明，映射 $i \\mapsto \\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 构成集合 $\\{i:1\\le i \\le s\\}$ 和集合 $\\left\\{\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor: 1\\le i\\le s\\right\\}$ 之间的双射．由于 $i$ 各不相同，$\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 也各不相同．两个集合唯一有可能相同的元素就是 $s$ 与 $\\left\\lfloor\\dfrac{n}{s}\\right\\rfloor$．所以，$|D(n)|=2s - \\left[s = \\lfloor n/s\\rfloor\\right]$．\n    \n    要得到 $|D(n)|$ 最终的表达式，需要考察何时 $s = \\left\\lfloor\\dfrac{n}{s}\\right\\rfloor$ 成立．\n    \n    -   当 $s = \\left\\lfloor\\dfrac{n}{s}\\right\\rfloor$ 时，总有 $s \\le \\dfrac{n}{s} < s + 1$，亦即 $s^2 \\le n < s^2+s$．此时，有 $4s^2 + 1 \\le 4n + 1 < 4s^2+4s+1 = (2s+1)^2$．又因为 $4n+1$ 一定是奇数，左侧可以等价地松弛到 $4s^2$，所以该条件就等价于 $2s \\le \\sqrt{4n+1} < 2s+1$，亦即 $\\lfloor \\sqrt{4n+1}\\rfloor = 2s$．\n    -   当 $s < \\left\\lfloor\\dfrac{n}{s}\\right\\rfloor$ 时，总有 $s + 1 \\le \\dfrac{n}{s}$，亦即 $s^2 + s\\le n$．又因为 $n < (s+1)^2$，就有 $s^2 + s\\le n < (s+1)^2$．这就等价于 $(2s+1)^2\\le 4n+1 < 4(s+1)^2+1$．再次利用 $4n+1$ 是奇数这一点，右侧可以等价地收紧到 $4(s+1)^2$，所以该条件就等价于 $2s+1\\le\\sqrt{4n+1} < 2s+2$，亦即 $\\lfloor \\sqrt{4n+1}\\rfloor = 2s+1$．\n    \n    总结这两种情形，就得到 $|D(n)| = \\lfloor \\sqrt{4n+1}\\rfloor - 1$ 成立．\n\n然后，单个块的左右端点都很容易确定．\n\n???+ note "性质 3"\n    对于 $d\\in D(n)$，所有满足 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor=d$ 的整数 $i$ 的取值范围为\n    \n    $$\n    \\left\\lfloor\\dfrac{n}{d+1}\\right\\rfloor + 1\\le i \\le \\left\\lfloor\\dfrac{n}{d}\\right\\rfloor.\n    $$\n\n??? note "证明"\n    因为 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor=d$ 相当于不等式\n    \n    $$\n    d\\le \\dfrac{n}{i} < d+1.\n    $$\n    \n    这进一步等价于\n    \n    $$\n    \\dfrac{n}{d+1} < i\\le \\dfrac{n}{d}.\n    $$\n    \n    利用 $i\\in\\mathbf N_+$ 这一点，可以对该不等式取整，它就等价于\n    \n    $$\n    \\left\\lfloor\\dfrac{n}{d+1}\\right\\rfloor + 1 \\le i\\le \\left\\lfloor\\dfrac{n}{d}\\right\\rfloor.\n    $$\n\n这一性质还体现了图像的对称性：每个块的右端点（前文图中的绿点）的集合恰为 $D(n)$．这很容易理解，因为整个图像关于直线 $y=x$ 是对称的．\n\n除了这些性质外，集合 $D(n)$ 还具有良好的递归性质：\n\n???+ note "性质 4"\n    对于 $m\\in D(n)$，有 $D(m)\\subseteq D(n)$．\n\n??? note "证明"\n    设 $m = \\left\\lfloor\\dfrac{n}{k}\\right\\rfloor$，那么，因为对于所有 $i\\in\\mathbf N_+$，都有\n    \n    $$\n    \\left\\lfloor\\dfrac{m}{i}\\right\\rfloor = \\left\\lfloor\\dfrac{\\lfloor n/k\\rfloor}{i}\\right\\rfloor = \\left\\lfloor\\dfrac{n}{ki}\\right\\rfloor \\in D(n),\n    $$\n    \n    所以，$D(m)\\subseteq D(n)$．其中，第二个等号用到了 [取整函数](./basic.md#取整函数) 关于嵌套分式的性质．\n\n前文已经提到，$D(n)$ 既是每块中 $\\left\\lfloor\\dfrac{n}{i}\\right\\rfloor$ 的取值集合，也是每块的右端点集合．这意味着，如果要递归地应用数论分块（即函数在 $n$ 处的值依赖于它在 $m\\in D(n)\\setminus\\{n\\}$ 处的值），那么在整个计算过程中所涉及的取值集合和右端点集合，其实都是 $D(n)$．一个典型的例子是 [杜教筛](./du.md)．\n\n## 过程\n\n利用上一节叙述的结论，就得到数论分块的具体过程．\n\n为计算和式\n\n$$\n\\sum_{i=1}^nf(i)g\\left(\\left\\lfloor\\dfrac ni\\right\\rfloor\\right)\n$$\n\n的取值，可以依据 $\\left\\lfloor\\dfrac ni\\right\\rfloor$ 的取值将标号 $i=1,2,\\cdots,n$ 分块．因为 $\\left\\lfloor\\dfrac ni\\right\\rfloor$ 取值相同的标号是一段连续整数 $[l,r]$，所以该块中和式的取值为\n\n$$\n\\left(\\sum_{i=l}^rf(i)\\right)\\cdot g\\left(\\left\\lfloor\\dfrac nl\\right\\rfloor\\right).\n$$\n\n为了快速计算该和式，通常需要能够快速计算左侧关于 $f$ 的和式．有些时候，该和式的表达式是已知的，可以在 $O(1)$ 时间内完成单次计算；有些时候，可以预处理出它的前缀和，仍然可以在 $O(1)$ 时间内完成单次查询．\n\n在顺次计算每块左右端点时，当前块的左端点 $l$ 就等于前一块的右端点再加 $1$，而当前块的右端点就等于 $\\left\\lfloor\\dfrac n{\\lfloor n/l\\rfloor}\\right\\rfloor$．由此，可以得到如下伪代码：\n\n$$\n\\begin{array}{l}\n\\textbf{Algorithm }\\text{Sum}(f,g,n):\\\\\n\\textbf{Input. }n,~s(k)=\\sum_{i=1}^kf(k),~g(k).\\\\\n\\textbf{Output. }S(n) = \\sum_{i=1}^nf(i)g(\\lfloor n/i\\rfloor).\\\\\n\\textbf{Method.}\\\\\n\\begin{array}{ll}\n1 & l \\gets 1\\\\\n2 & \\textit{result} \\gets 0 \\\\\n3 & \\textbf{while } l \\leq n \\textbf{ do}\\\\\n4 & \\qquad r \\gets \\left\\lfloor \\dfrac{n}{\\lfloor n/l \\rfloor} \\right\\rfloor\\\\\n5 & \\qquad \\textit{result} \\gets \\textit{result} + (s(r)-s(l-1))\\cdot g\\left(\\left\\lfloor \\dfrac{n}{l} \\right\\rfloor\\right)\\\\\n6 & \\qquad l \\gets r+1\\\\\n7 & \\textbf{end while}\\\\\n8 & \\textbf{return }\\textit{result}\n\\end{array}\n\\end{array}\n$$\n\n假设单次计算 $s(\\cdot)$ 的时间复杂度为 $O(1)$，则整个过程的时间复杂度为 $O(\\sqrt{n})$．\n\n## 扩展\n\n前文讨论的是数论分块的最常见也最基本的形式．本节进一步讨论数论分块的扩展形式．\n\n### 向上取整的数论分块\n\n数论分块可以用于计算含有向上取整的和式：\n\n$$\n\\sum_{i=1}^nf(i)g\\left(\\left\\lceil\\dfrac ni\\right\\rceil\\right).\n$$\n\n因为 $\\left\\lceil\\dfrac ni\\right\\rceil = \\left\\lfloor\\dfrac {n-1}i\\right\\rfloor + 1$，该和式可以转化为向下取整的情形：\n\n$$\nf(n)g(1) + \\sum_{i=1}^{n-1}f(i)g\\left(\\left\\lfloor\\dfrac {n-1}i\\right\\rfloor + 1\\right).\n$$\n\n注意到求和的上限发生了变化，以及 $i=n$ 时单独的一项．\n\n### 多维数论分块\n\n数论分块还可以用于处理包含不只有一个取整式的和式：\n\n$$\n\\sum_{i=1}^{n}f(i)g\\left(\\left\\lfloor\\dfrac {n_1}i\\right\\rfloor,\\left\\lfloor\\dfrac {n_2}i\\right\\rfloor,\\cdots,\\left\\lfloor\\dfrac {n_m}i\\right\\rfloor\\right).\n$$\n\n为了应用数论分块的思想，需要保证每块中所有取整式 $\\left\\lfloor\\dfrac {n_1}i\\right\\rfloor,\\left\\lfloor\\dfrac {n_2}i\\right\\rfloor,\\cdots,\\left\\lfloor\\dfrac {n_m}i\\right\\rfloor$ 的取值都不发生变化，也就是说，多维的块应当是所有一维的块的交集．为此，对于已知的左端点 $l$，相应的右端点为\n\n$$\n\\min\\left\\{\\left\\lfloor\\dfrac {n_1}{\\lfloor n_1/l\\rfloor}\\right\\rfloor,\\left\\lfloor\\dfrac {n_2}{\\lfloor n_2/l\\rfloor}\\right\\rfloor,\\cdots,\\left\\lfloor\\dfrac {n_m}{\\lfloor n_m/l\\rfloor}\\right\\rfloor\\right\\}.\n$$\n\n也就是说，对于所有一维分块的右端点取最小值，作为多维分块的右端点．可以借助下图理解：\n\n![多维数论分块图解](./images/n-dimension-sqrt-decomposition.svg)\n\n较为常见的是二维形式，此时可将前述伪代码中 $r \\gets \\left\\lfloor \\dfrac{n}{\\lfloor n/l \\rfloor}\\right\\rfloor$ 替换成\n\n$$\nr \\gets \\min\\left\\{\\left\\lfloor \\dfrac{n_1}{\\lfloor n_1/l \\rfloor}\\right\\rfloor,\\left\\lfloor \\dfrac{n_2}{\\lfloor n_2/l \\rfloor}\\right\\rfloor\\right\\}.\n$$\n\n### 任意指数数论分块\n\n数论分块可以用于含有任意指数的取整式的和式计算：\n\n$$\n\\sum_{i=1}^{\\lfloor n^{\\alpha/\\beta}\\rfloor}f(i)g\\left(\\left\\lfloor\\dfrac {n^\\alpha}{i^\\beta}\\right\\rfloor\\right).\n$$\n\n其中，$\\alpha,\\beta$ 为正实数．本文讨论的基本形式中，$\\alpha=\\beta=1$．\n\n???+ note "性质"\n    对于正整数 $n$ 和正实数 $\\alpha, \\beta$，设\n    \n    $$\n    D(n,\\alpha,\\beta) = \\left\\{\\left\\lfloor\\dfrac{n^\\alpha}{i^\\beta}\\right\\rfloor: i=1,2,\\cdots,\\lfloor n^{\\alpha/\\beta}\\rfloor\\right\\}.\n    $$\n    \n    那么，有\n    \n    1.  $|D(n,\\alpha,\\beta)|\\le 2n^{\\alpha/(1+\\beta)}$．\n    2.  对于 $d\\in D(n,\\alpha,\\beta)$，使得 $\\left\\lfloor\\dfrac{n^\\alpha}{i^\\beta}\\right\\rfloor=d$ 成立的 $i$ 的取值范围为\n    \n        $$\n        \\left\\lfloor\\dfrac{n^{\\alpha/\\beta}}{(d+1)^{1/\\beta}}\\right\\rfloor + 1\\le i \\le \\left\\lfloor\\dfrac{n^{\\alpha/\\beta}}{d^{1/\\beta}}\\right\\rfloor.\n        $$\n\n??? note "证明"\n    对于第一点，分两种情况：\n    \n    -   当 $i\\le \\dfrac{n^\\alpha}{i^\\beta}$ 时，有 $i\\le n^{\\alpha/(1+\\beta)}$，所以 $\\left\\lfloor\\dfrac{n^\\alpha}{i^\\beta}\\right\\rfloor$ 至多有 $n^{\\alpha/(1+\\beta)}$ 种取值．\n    -   当 $i > \\dfrac{n^\\alpha}{i^\\beta}$ 时，有 $i> n^{\\alpha/(1+\\beta)}$，进而有 $\\dfrac{n^\\alpha}{i^\\beta} < n^{\\alpha/(1+\\beta)}$，所以 $\\left\\lfloor\\dfrac{n^\\alpha}{i^\\beta}\\right\\rfloor$ 也至多只有 $n^{\\alpha/(1+\\beta)}$ 种取值．\n    \n    综合两种情形，就有 $|D(n,\\alpha,\\beta)|\\le 2n^{\\alpha/(1+\\beta)}$．\n    \n    对于第二点，$\\left\\lfloor\\dfrac{n^\\alpha}{i^\\beta}\\right\\rfloor=d$ 就等价于\n    \n    $$\n    d \\le \\dfrac{n^\\alpha}{i^\\beta} < d+1 \\iff \\dfrac{n^{\\alpha/\\beta}}{(d+1)^{1/\\beta}} < i \\le \\dfrac{n^{\\alpha/\\beta}}{d^{1/\\beta}}.\n    $$\n    \n    对该不等式取整，就得到第二个命题．\n\n利用这些性质，就可以在 $O(n^{\\alpha/(1+\\beta)})$ 的时间复杂度下实现对任意指数的数论分块．\n\n???+ example "例子"\n    例如，对于 $\\alpha=\\beta=1/2$ 时的如下和式\n    \n    $$\n    \\sum_{i=1}^nf(i)g\\left(\\left\\lfloor\\sqrt{\\dfrac {n}{i}}\\right\\rfloor\\right),\n    $$\n    \n    可以通过数论分块在 $O(n^{1/3})$ 时间内解决．已知块的左端点为 $l$ 时，可以计算右端点为 $r=\\left\\lfloor\\dfrac{n}{\\lfloor\\sqrt{n/l}\\rfloor^2}\\right\\rfloor$．\n\n## 例题\n\n???+ example "[UVa11526 H(n)](https://onlinejudge.org/index.php?option=com_onlinejudge&Itemid=8&category=27&page=show_problem&problem=2521)"\n    $T$ 组数据，每组一个整数 $n$．对于每组数据，输出 $\\sum_{i=1}^n\\left\\lfloor\\dfrac ni\\right\\rfloor$．\n\n??? note "解答"\n    根据前文分析，可以对于每一块相同的 $\\left\\lfloor\\dfrac ni\\right\\rfloor$ 一起计算．时间复杂度为 $O(T\\sqrt n)$．\n\n??? note "实现"\n    ```cpp\n    --8<-- "docs/math/code/sqrt-decomposition/sqrt-decomposition_1.cpp"\n    ```\n\n???+ example "[Codeforces 1954E Chain Reaction](https://codeforces.com/contest/1954/problem/E)"\n    有一排 $n$ 只怪兽，每只怪兽初始血量为 $a_i$．一次攻击会使一段连续的存活的怪兽血量减 $k$，血量不大于 $0$ 视作死亡．对于所有 $k$ 求出击杀所有怪兽所需攻击次数．其中，$n,a_i\\leq 10^5$．\n\n??? note "解答"\n    令 $a_0=0$．假设击杀所有前 $(i-1)$ 只怪兽需要 $T(k,i-1)$ 次攻击，第 $i$ 只怪兽的血量为 $a_i$．由于击杀第 $(i-1)$ 只怪兽时，需要攻击它 $\\lceil a_{i-1}/k\\rceil$ 次，这些攻击都可以延伸到第 $i$ 只怪兽．因此，要击杀第 $i$ 只怪兽，只需要再攻击 $\\max\\{0,\\lceil a_i/k\\rceil-\\lceil a_{i-1}/k\\rceil\\}$ 次．由此，总的攻击次数为\n    \n    $$\n    T(k,n)=\\sum_{i=1}^n\\max\\left(0,\\left\\lceil\\dfrac{a_i}{k}\\right\\rceil-\\left\\lceil\\dfrac{a_{i-1}}{k}\\right\\rceil\\right).\n    $$\n    \n    由于题目涉及的 $n,k$ 都比较大，对每个 $k$ 分别计算该和式并不可行．可以考虑对每个 $i=1,2,\\cdots,n$，都维护数列 $\\{T(k,i)\\}_k$．初始时，设 $T(k,0)\\equiv 0$．假设数列 $\\{T(k,i-1)\\}_k$ 已知，考虑如何对它进行修改才能得到数列 $\\{T(k,i)\\}_k$．根据前文分析，只需要对数列的第 $k$ 项增加 $\\max\\left(0,\\left\\lceil\\dfrac{a_i}{k}\\right\\rceil-\\left\\lceil\\dfrac{a_{i-1}}{k}\\right\\rceil\\right)$ 即可．利用二维数论分块，可以将这一修改操作拆分成 $O(\\sqrt{a_{i-1}}+\\sqrt{a_i})$ 段区间修改操作，且每段区间上增加的值是固定的．最后得到的数列 $\\{T(k,n)\\}_k$ 就是答案．\n    \n    由于题目涉及一系列区间加操作，且查询只发生所有修改完成后．所以，可以通过维护差分序列进行区间加修改，最后通过求前缀和得到所求数列．总的时间复杂度为 $O(\\sum\\sqrt{a_i})$．本题也存在其他解法．\n\n??? note "实现"\n    ```cpp\n    --8<-- "docs/math/code/sqrt-decomposition/sqrt-decomposition_2.cpp"\n    ```\n\n## 习题\n\n-   [UVa11526 H(n)](https://onlinejudge.org/index.php?option=com_onlinejudge&Itemid=8&category=27&page=show_problem&problem=2521)\n-   [Luogu P2261 CQOI2007 余数求和](https://www.luogu.com.cn/problem/P2261)\n-   [Luogu P3455 POI2007 ZAP-Queries](https://www.luogu.com.cn/problem/P3455)\n\n## 参考资料与注释\n\n-   [杜教筛的时空复杂度分析 by riteme](https://riteme.site/blog/2018-9-11/time-space-complexity-dyh-algo.html)\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
90667b89-b11a-49bb-a94d-24e00074d5cd	2408d6bc-f1a0-4590-85c8-873ddaa17d8f	deep	块状数组、块状链表	# 172. 分块专题1-块状数组、块状链表\n\n> 难度标签：**进阶** ｜ 主题：**数据结构** ｜ 来源：左程云《算法讲解》第 172 讲\n\n## 第 1 页：块状数组、块状链表\n\n左程云\n分块专题的安排\n专题1：块状数组、块状链表，讲解172，本节\n专题2：分块的几道好题、树上分块，讲解173\n专题3：双层分块、分块结合并查集，讲解174\n专题4：根号分治，讲解175\n分块专题结束后，开始讲述莫队专题\n\n## 第 2 页：块状数组、块状链表\n\n左程云\n前置知识\n讲解108 - 树状数组    讲解110 - 线段树    讲解152 - FHQ Treap\n讲解153 - Splay树    讲解157 - 主席树    讲解159 - 可持久化前缀树\n讲解160 - 树套树\n理解分块其实不需要前置知识，但分块和这些结构进行比较学习非常重要\n本节课讲述\n分块的原理和适用场景\n块状数组的原理和模版题目    题目1、题目2\n块状数组的经典题目         题目3、题目4、题目5\n块状链表的原理和模版题目    题目6\n\n## 第 3 页：块状数组、块状链表\n\n左程云\n分块的原理\n1，假设数据规模为n，让划分出来的 块内大小 和 块的数量 几乎相同，比如都是 √n 规模\n2，分块结构维护信息时，块内的信息暴力维护，整块的信息修改标签即可\n3，处理 区间修改 或者 区间查询 时，最多处理 左散块 + 右散块 + 中间若干整块 即可\n4，块内遍历时间复杂度O(√n)，块间遍历时间复杂度O(√n)\n分块的适用场景\n1，区间不可合并的信息，线段树等结构难维护，分块往往容易，因为块内信息是暴力维护的\n2，数据量允许的情况下，分块优于暴力，又比高级结构的实现更容易分析\n3，分块维护信息很容易，会衍生出很多强大变体，专题后续的课大量涉及\n4，正式比赛中很少出现 以分块作为最优解 的题目，分块优势是好想、好写、常数小\n5，题目思维难度较大时，如果分块的做法已经很难，那么更优结构的做法只会更难\n6，分块的地位，非必需但收益高\n\n## 第 4 页：块状数组、块状链表\n\n左程云\n题目1\nGive Away\n给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n操作 0 a b c : 打印arr[a..b]范围上>=c的数字个数\n操作 1 a b   : 把arr[a]的值改成b\n1 <= n <= 5 * 10^5\n1 <= m <= 10^5\n1 <= 数组中的值 <= 10^9\n测试链接 : https://www.luogu.com.cn/problem/SP18185\n测试链接 : https://www.spoj.com/problems/GIVEAWAY\n时间复杂度O(m * √n * log √n)，相当极限，但是分块常数小，可以通过\n\n## 第 5 页：块状数组、块状链表\n\n左程云\n题目2\n教主的魔法\n给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n操作 A l r v : 打印arr[l..r]范围上>=v的数字个数\n操作 M l r v : 把arr[l..r]范围上每个值都加上v\n1 <= n <= 10^6\n1 <= m <= 3000\n1 <= 数组中的值 <= 10^9\n测试链接 : https://www.luogu.com.cn/problem/P2801\n时间复杂度O(m * √n * log √n)，可以通过\n\n## 第 6 页：块状数组、块状链表\n\n左程云\n题目3\n蒲公英\n给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n操作 l r : 打印arr[l..r]范围上的众数，如果有多个众数，打印值最小的\n1 <= n <= 4 * 10^4\n1 <= m <= 5 * 10^4\n1 <= 数组中的值 <= 10^9\n题目要求强制在线，具体规则可以打开测试链接查看\n测试链接 : https://www.luogu.com.cn/problem/P4168\nfreq[i][j]表示前i块中j出现的次数\nmode[i][j]表示从i块到j块中的众数\n讨论左右散块中的数字，能否成为众数\n\n## 第 7 页：块状数组、块状链表\n\n左程云\n题目4\n空间少求众数的次数\n给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n操作 l r : 打印arr[l..r]范围上，众数到底出现了几次\n1 <= 所有数据 <= 5 * 10^5\n内存空间只有64MB，题目要求强制在线，具体规则可以打开测试链接查看\n测试链接 : https://www.luogu.com.cn/problem/P5048\n神仙题\nfreq[i][j]表示前i块中j出现的次数，这个结构不能用了，因为空间不允许\nsortList用来收集同一种数的下标列表\nlistIdx[i] = j，表示arr[i]这个元素在sortList里的j位置\nmodeCnt[i][j]表示从i块到j块中众数的出现次数\n讨论左右散块中的数字，能否让众数的次数变得更大\n\n## 第 8 页：块状数组、块状链表\n\n左程云\n题目5\n作诗\n给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n操作 l r : 打印arr[l..r]范围上，有多少个数出现正偶数次\n1 <= 所有数据 <= 10^5\n题目要求强制在线，具体规则可以打开测试链接查看\n测试链接 : https://www.luogu.com.cn/problem/P4135\nfreq[i][j]表示前i块中j出现的次数\neven[i][j]表示从第i块到第j块，有多少个数出现正偶数次\n讨论左右散块中的数字，如何更新 出现正偶数次的数的个数\n\n## 第 9 页：块状数组、块状链表\n\n左程云\n块状链表的原理和实现\n1，概念上，每一块都是数组，块之间连接起来，根据具体需求，选择 单链表 或者 双链表\n2，实现上，不用动态链表实现，利用pool数组进行块编号的分配和回收，纯粹静态数组的方式\n3，保证 块内容量 和 块的数量 同等规模，块内容量 2 * √n，块的内容大小不能超过这个容量\n4，插入时，先分裂成左右两块，然后在中间插入若干新块，填写上内容\n5，删除时，最左块分裂，最右块分裂，左右两块该删的内容 + 中间若干块的内容 都删掉\n6，插入或者删除后，遍历检查相邻块的内容大小，如果 内容大小的累加和 <= 块内容量，就合并\n区间增删、区间移动的题目，最优解大概率是其他结构，这些结构学习门槛往往较高\n因为存在类似链表调整的逻辑，块状链表也未必好写，但是绝对好想\n\n## 第 10 页：块状数组、块状链表\n\n左程云\n题目6\n文本编辑器\n一开始文本为空，光标在文本开头，也就是1位置，请实现如下6种操作\nMove k     : 将光标移动到第k个字符之后，操作保证光标不会到非法位置\nInsert n s : 在光标处插入长度为n的字符串s，光标位置不变\nDelete n   : 删除光标后的n个字符，光标位置不变，操作保证有足够字符\nGet n      : 输出光标后的n个字符，光标位置不变，操作保证有足够字符\nPrev       : 光标前移一个字符，操作保证光标不会到非法位置\nNext       : 光标后移一个字符，操作保证光标不会到非法位置\nInsert操作时，字符串s中ASCII码在[32,126]范围上的字符一定有n个，其他字符请过滤掉\n测试链接 : https://www.luogu.com.cn/problem/P4008\n这道题就是，讲解152 - FHQ Treap，题目3，本节课用块状链表再实现一次\n\n## 模板代码\n\n### `Code01_GiveAway1.java`\n\n```java\npackage class172;\n\n// Give Away，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 0 a b c : 打印arr[a..b]范围上>=c的数字个数\n// 操作 1 a b   : 把arr[a]的值改成b\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^5\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/SP18185\n// 测试链接 : https://www.spoj.com/problems/GIVEAWAY\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code01_GiveAway1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXB = 1001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\tpublic static void build() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tArrays.sort(sortv, bl[i], br[i] + 1);\n\t\t}\n\t}\n\n\tpublic static int getCnt(int i, int v) {\n\t\tint l = bl[i], r = br[i], m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (sortv[m] >= v) {\n\t\t\t\tans += r - m + 1;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int query(int l, int r, int v) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tif (arr[i] >= v) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tans += getCnt(i, v);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void update(int i, int v) {\n\t\tint l = bl[bi[i]];\n\t\tint r = br[bi[i]];\n\t\tarr[i] = v;\n\t\tfor (int j = l; j <= r; j++) {\n\t\t\tsortv[j] = arr[j];\n\t\t}\n\t\tArrays.sort(sortv, l, r + 1);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, op, a, b, c; i <= m; i++) {\n\t\t\top = in.nextInt();\n\t\t\ta = in.nextInt();\n\t\t\tb = in.nextInt();\n\t\t\tif (op == 0) {\n\t\t\t\tc = in.nextInt();\n\t\t\t\tout.println(query(a, b, c));\n\t\t\t} else {\n\t\t\t\tupdate(a, b);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code01_GiveAway2.java`\n\n```java\npackage class172;\n\n// Give Away，C++版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 0 a b c : 打印arr[a..b]范围上>=c的数字个数\n// 操作 1 a b   : 把arr[a]的值改成b\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 10^5\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/SP18185\n// 测试链接 : https://www.spoj.com/problems/GIVEAWAY\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXB = 1001;\n//int n, m;\n//int arr[MAXN];\n//int sortv[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//int bl[MAXB];\n//int br[MAXB];\n//\n//void build() {\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        bl[i] = (i - 1) * blen + 1;\n//        br[i] = min(i * blen, n);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        sortv[i] = arr[i];\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        sort(sortv + bl[i], sortv + br[i] + 1);\n//    }\n//}\n//\n//int getCnt(int i, int v) {\n//    int l = bl[i], r = br[i], m, ans = 0;\n//    while (l <= r) {\n//        m = (l + r) >> 1;\n//        if (sortv[m] >= v) {\n//            ans += r - m + 1;\n//            r = m - 1;\n//        } else {\n//            l = m + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int query(int l, int r, int v) {\n//    int ans = 0;\n//    if (bi[l] == bi[r]) {\n//        for (int i = l; i <= r; i++) {\n//            if (arr[i] >= v) {\n//                ans++;\n//            }\n//        }\n//    } else {\n//        for (int i = l; i <= br[bi[l]]; i++) {\n//            if (arr[i] >= v) {\n//                ans++;\n//            }\n//        }\n//        for (int i = bl[bi[r]]; i <= r; i++) {\n//            if (arr[i] >= v) {\n//                ans++;\n//            }\n//        }\n//        for (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n//            ans += getCnt(i, v);\n//        }\n//    }\n//    return ans;\n//}\n//\n//void update(int i, int v) {\n//    int l = bl[bi[i]];\n//    int r = br[bi[i]];\n//    arr[i] = v;\n//    for (int j = l; j <= r; j++) {\n//        sortv[j] = arr[j];\n//    }\n//    sort(sortv + l, sortv + r + 1);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    build();\n//    cin >> m;\n//    int op, a, b, c;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op >> a >> b;\n//        if (op == 0) {\n//            cin >> c;\n//            cout << query(a, b, c) << '\\n';\n//        } else {\n//            update(a, b);\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_Magic1.java`\n\n```java\npackage class172;\n\n// 教主的魔法，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 A l r v : 打印arr[l..r]范围上>=v的数字个数\n// 操作 M l r v : 把arr[l..r]范围上每个值都加上v\n// 1 <= n <= 10^6\n// 1 <= m <= 3000\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2801\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code02_Magic1 {\n\n\tpublic static int MAXN = 1000001;\n\tpublic static int MAXB = 1001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\tpublic static int[] lazy = new int[MAXB];\n\n\tpublic static void build() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tArrays.sort(sortv, bl[i], br[i] + 1);\n\t\t}\n\t}\n\n\tpublic static int getCnt(int i, int v) {\n\t\tv -= lazy[i];\n\t\tint l = bl[i], r = br[i], m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (sortv[m] >= v) {\n\t\t\t\tans += r - m + 1;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int innerQuery(int l, int r, int v) {\n\t\tv -= lazy[bi[l]];\n\t\tint ans = 0;\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tif (arr[i] >= v) {\n\t\t\t\tans++;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int query(int l, int r, int v) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tans = innerQuery(l, r, v);\n\t\t} else {\n\t\t\tans += innerQuery(l, br[bi[l]], v);\n\t\t\tans += innerQuery(bl[bi[r]], r, v);\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tans += getCnt(i, v);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void innerAdd(int l, int r, int v) {\n\t\tfor (int i = l; i <= r; i++) {\n\t\t\tarr[i] += v;\n\t\t}\n\t\tfor (int i = bl[bi[l]]; i <= br[bi[l]]; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sortv, bl[bi[l]], br[bi[l]] + 1);\n\t}\n\n\tpublic static void add(int l, int r, int v) {\n\t\tif (bi[l] == bi[r]) {\n\t\t\tinnerAdd(l, r, v);\n\t\t} else {\n\t\t\tinnerAdd(l, br[bi[l]], v);\n\t\t\tinnerAdd(bl[bi[r]], r, v);\n\t\t\tfor (int i = bi[l] + 1; i <= bi[r] - 1; i++) {\n\t\t\t\tlazy[i] += v;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tbuild();\n\t\tchar op;\n\t\tint l, r, v;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = in.nextChar();\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tif (op == 'A') {\n\t\t\t\tout.println(query(l, r, v));\n\t\t\t} else {\n\t\t\t\tadd(l, r, v);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic char nextChar() throws IOException {\n\t\t\tbyte c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (c <= ' ');\n\t\t\tchar ans = 0;\n\t\t\twhile (c > ' ') {\n\t\t\t\tans = (char) c;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_Magic2.java`\n\n```java\npackage class172;\n\n// 教主的魔法，C++版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作是如下两种类型中的一种\n// 操作 A l r v : 打印arr[l..r]范围上>=v的数字个数\n// 操作 M l r v : 把arr[l..r]范围上每个值都加上v\n// 1 <= n <= 10^6\n// 1 <= m <= 3000\n// 1 <= 数组中的值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2801\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 1000001;\n//const int MAXB = 1001;\n//int n, m;\n//int arr[MAXN];\n//int sortv[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//int bl[MAXB];\n//int br[MAXB];\n//\n//int lazy[MAXB];\n//\n//void build() {\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\