   }\n//    build();\n//    char op;\n//    int l, r, v;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op >> l >> r >> v;\n//        if (op == 'A') {\n//            cout << query(l, r, v) << '\\n';\n//        } else {\n//            add(l, r, v);\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_Violet1.java`\n\n```java\npackage class172;\n\n// 蒲公英，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上的众数，如果有多个众数，打印值最小的\n// 1 <= n <= 4 * 10^4\n// 1 <= m <= 5 * 10^4\n// 1 <= 数组中的值 <= 10^9\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P4168\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code03_Violet1 {\n\n\tpublic static int MAXN = 40001;\n\tpublic static int MAXB = 201;\n\tpublic static int n, m, s;\n\tpublic static int[] arr = new int[MAXN];\n\n\t// 数字做离散化\n\tpublic static int[] sortv = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\t// freq[i][j]表示前i块中j出现的次数\n\tpublic static int[][] freq = new int[MAXB][MAXN];\n\t// mode[i][j]表示从i块到j块中的众数(最小)\n\tpublic static int[][] mode = new int[MAXB][MAXB];\n\t// 数字的词频统计\n\tpublic static int[] numCnt = new int[MAXN];\n\n\tpublic static int lower(int num) {\n\t\tint l = 1, r = s, m, ans = 0;\n\t\twhile (l <= r) {\n\t\t\tm = (l + r) >> 1;\n\t\t\tif (sortv[m] >= num) {\n\t\t\t\tans = m;\n\t\t\t\tr = m - 1;\n\t\t\t} else {\n\t\t\t\tl = m + 1;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int getCnt(int l, int r, int v) {\n\t\treturn freq[r][v] - freq[l - 1][v];\n\t}\n\n\tpublic static void prepare() {\n\t\t// 建块\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\t// 离散化\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortv[i] = arr[i];\n\t\t}\n\t\tArrays.sort(sortv, 1, n + 1);\n\t\ts = 1;\n\t\tfor (int i = 2; i <= n; i++) {\n\t\t\tif (sortv[s] != sortv[i]) {\n\t\t\t\tsortv[++s] = sortv[i];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = lower(arr[i]);\n\t\t}\n\t\t// 填好freq\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = bl[i]; j <= br[i]; j++) {\n\t\t\t\tfreq[i][arr[j]]++;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= s; j++) {\n\t\t\t\tfreq[i][j] += freq[i - 1][j];\n\t\t\t}\n\t\t}\n\t\t// 填好mode\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = i; j <= bnum; j++) {\n\t\t\t\tint most = mode[i][j - 1];\n\t\t\t\tint mostCnt = getCnt(i, j, most);\n\t\t\t\tfor (int k = bl[j]; k <= br[j]; k++) {\n\t\t\t\t\tint cur = arr[k];\n\t\t\t\t\tint curCnt = getCnt(i, j, cur);\n\t\t\t\t\tif (curCnt > mostCnt || (curCnt == mostCnt && cur < most)) {\n\t\t\t\t\t\tmost = cur;\n\t\t\t\t\t\tmostCnt = curCnt;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tmode[i][j] = most;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint most = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tif (numCnt[arr[i]] > numCnt[most] || (numCnt[arr[i]] == numCnt[most] && arr[i] < most)) {\n\t\t\t\t\tmost = arr[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t} else {\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tmost = mode[bi[l] + 1][bi[r] - 1];\n\t\t\tint mostCnt = getCnt(bi[l] + 1, bi[r] - 1, most) + numCnt[most];\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tint cur = arr[i];\n\t\t\t\tint curCnt = getCnt(bi[l] + 1, bi[r] - 1, cur) + numCnt[cur];\n\t\t\t\tif (curCnt > mostCnt || (curCnt == mostCnt && cur < most)) {\n\t\t\t\t\tmost = cur;\n\t\t\t\t\tmostCnt = curCnt;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tint cur = arr[i];\n\t\t\t\tint curCnt = getCnt(bi[l] + 1, bi[r] - 1, cur) + numCnt[cur];\n\t\t\t\tif (curCnt > mostCnt || (curCnt == mostCnt && cur < most)) {\n\t\t\t\t\tmost = cur;\n\t\t\t\t\tmostCnt = curCnt;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t}\n\t\treturn sortv[most];\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, a, b, l, r, lastAns = 0; i <= m; i++) {\n\t\t\ta = (in.nextInt() + lastAns - 1) % n + 1;\n\t\t\tb = (in.nextInt() + lastAns - 1) % n + 1;\n\t\t\tl = Math.min(a, b);\n\t\t\tr = Math.max(a, b);\n\t\t\tlastAns = query(l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_Violet2.java`\n\n```java\npackage class172;\n\n// 蒲公英，C++版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上的众数，如果有多个众数，打印值最小的\n// 1 <= n <= 4 * 10^4\n// 1 <= m <= 5 * 10^4\n// 1 <= 数组中的值 <= 10^9\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P4168\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 40001;\n//const int MAXB = 201;\n//int n, m, s;\n//int arr[MAXN];\n//int sortv[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//int bl[MAXB];\n//int br[MAXB];\n//\n//int freq[MAXB][MAXN];\n//int mode[MAXB][MAXB];\n//int numCnt[MAXN];\n//\n//int lower(int num) {\n//    int l = 1, r = s, m, ans = 0;\n//    while (l <= r) {\n//        m = (l + r) >> 1;\n//        if (sortv[m] >= num) {\n//            ans = m;\n//            r = m - 1;\n//        } else {\n//            l = m + 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int getCnt(int l, int r, int v) {\n//    return freq[r][v] - freq[l - 1][v];\n//}\n//\n//void prepare() {\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        bl[i] = (i - 1) * blen + 1;\n//        br[i] = min(i * blen, n);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        sortv[i] = arr[i];\n//    }\n//    sort(sortv + 1, sortv + n + 1);\n//    s = 1;\n//    for (int i = 2; i <= n; i++) {\n//        if (sortv[s] != sortv[i]) {\n//            sortv[++s] = sortv[i];\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        arr[i] = lower(arr[i]);\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        for (int j = bl[i]; j <= br[i]; j++) {\n//            freq[i][arr[j]]++;\n// 