   if (curCnt > mostCnt || (curCnt == mostCnt && cur < most)) {\n//                most = cur;\n//                mostCnt = curCnt;\n//            }\n//        }\n//        for (int i = l; i <= br[bi[l]]; i++) {\n//            numCnt[arr[i]] = 0;\n//        }\n//        for (int i = bl[bi[r]]; i <= r; i++) {\n//            numCnt[arr[i]] = 0;\n//        }\n//    }\n//    return sortv[most];\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    prepare();\n//    int lastAns = 0, a, b, l, r;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a >> b;\n//        a = (a + lastAns - 1) % n + 1;\n//        b = (b + lastAns - 1) % n + 1;\n//        l = min(a, b);\n//        r = max(a, b);\n//        lastAns = query(l, r);\n//        cout << lastAns << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_ModeCnt1.java`\n\n```java\npackage class172;\n\n// 空间少求众数的次数，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上，众数到底出现了几次\n// 1 <= 所有数值 <= 5 * 10^5\n// 内存空间只有64MB，题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P5048\n// 提交以下的code，提交时请把类名改成"Main"\n// java实现的逻辑一定是正确的，但是内存占用过大，无法通过测试用例\n// 因为这道题只考虑C++能通过的空间标准，根本没考虑java的用户\n// 想通过用C++实现，本节课Code04_ModeCnt2文件就是C++的实现\n// 两个版本的逻辑完全一样，C++版本可以通过所有测试\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code04_ModeCnt1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXB = 801;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\t// (值、下标)，用来收集同一种数的下标列表\n\tpublic static int[][] sortList = new int[MAXN][2];\n\t// listIdx[i] = j，表示arr[i]这个元素在sortList里的j位置\n\tpublic static int[] listIdx = new int[MAXN];\n\t// modeCnt[i][j]表示从i块到j块中众数的出现次数\n\tpublic static int[][] modeCnt = new int[MAXB][MAXB];\n\t// 数字词频统计\n\tpublic static int[] numCnt = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tsortList[i][0] = arr[i];\n\t\t\tsortList[i][1] = i;\n\t\t}\n\t\tArrays.sort(sortList, 1, n + 1, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tlistIdx[sortList[i][1]] = i;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = i; j <= bnum; j++) {\n\t\t\t\tint cnt = modeCnt[i][j - 1];\n\t\t\t\tfor (int k = bl[j]; k <= br[j]; k++) {\n\t\t\t\t\tcnt = Math.max(cnt, ++numCnt[arr[k]]);\n\t\t\t\t}\n\t\t\t\tmodeCnt[i][j] = cnt;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\tnumCnt[j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans = Math.max(ans, ++numCnt[arr[i]]);\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t} else {\n\t\t\tans = modeCnt[bi[l] + 1][bi[r] - 1];\n\t\t\tfor (int i = l, idx; i <= br[bi[l]]; i++) {\n\t\t\t\tidx = listIdx[i];\n\t\t\t\twhile (idx + ans <= n && sortList[idx + ans][0] == arr[i] && sortList[idx + ans][1] <= r) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]], idx; i <= r; i++) {\n\t\t\t\tidx = listIdx[i];\n\t\t\t\twhile (idx - ans >= 1 && sortList[idx - ans][0] == arr[i] && sortList[idx - ans][1] >= l) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, l, r, lastAns = 0; i <= m; i++) {\n\t\t\tl = in.nextInt() ^ lastAns;\n\t\t\tr = in.nextInt() ^ lastAns;\n\t\t\tlastAns = query(l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_ModeCnt2.java`\n\n```java\npackage class172;\n\n// 空间少求众数的次数，C++版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上，众数到底出现了几次\n// 1 <= 所有数值 <= 5 * 10^5\n// 内存空间只有64MB，题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P5048\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//struct Node {\n//    int v, i;\n//};\n//\n//bool NodeCmp(Node a, Node b) {\n//    if (a.v != b.v) {\n//        return a.v < b.v;\n//    }\n//    return a.i < b.i;\n//}\n//\n//const int MAXN = 500001;\n//const int MAXB = 801;\n//int n, m;\n//int arr[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//int bl[MAXB];\n//int br[MAXB];\n//\n//Node sortList[MAXN];\n//int listIdx[MAXN];\n//\n//int modeCnt[MAXB][MAXB];\n//int numCnt[MAXN];\n//\n//void prepare() {\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        bl[i] = (i - 1) * blen + 1;\n//        br[i] = min(i * blen, n);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        sortList[i].v = arr[i];\n//        sortList[i].i = i;\n//    }\n//    sort(sortList + 1, sortList + n + 1, NodeCmp);\n//    for (int i = 1; i <= n; i++) {\n//        listIdx[sortList[i].i] = i;\n//    }\n//    for (int i = 1; i <= bnum; i++) {\n//        for (int j = i; j <= bnum; j++) {\n//            int cnt = modeCnt[i][j - 1];\n//            for (int k = bl[j]; k <= br[j]; k++) {\n//                cnt = max(cnt, ++numCnt[arr[k]]);\n//            }\n//            modeCnt[i][j] = cnt;\n//        }\n//        for (int j = 1; j <= n; j++) {\n//            numCnt[j] = 0;\n//        }\n//    }\n//}\n//\n//int query(int l, int r) {\n//    int ans = 0;\n//    if (bi[l] == bi[r]) {\n//        for (int i = l; i <= r; i++) {\n//            ans = max(ans, ++numCnt[arr[i]]);\n//        }\n//        for (int i = l; i <= r; i++) {\n//            numCnt[arr[i]] = 0;\n//        }\n//    } else {\n//        ans = modeCnt[bi[l] + 1][bi[r] - 1];\n//        for (int i = l, idx; i <= br[bi[l]]; i++) {\n//            idx = listIdx[i];\n//            while (idx + ans <= n && sortList[idx + ans].v == arr[i] && sortList[idx + ans].i <= r) {\n//                ans++;\n//            }\n//        }\n//        for (int i = bl[bi[r]], idx; i <= r; i++) {\n//            idx = listIdx[i];\n//            while (idx - ans >= 1 && sortList[idx - ans].v == arr[i] && sortList[idx - ans].i >= l) {\n//                ans++;\n//            }\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    prepare();\n//    for (int i = 1, l, r, lastAns = 0; i <= m; i++) {\n//        cin >> l >> r;\n//        l ^= lastAns;\n//        r ^= lastAns;\n//        lastAns = query(l, r);\n//        cout << lastAns << '\\n';\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Poem1.java`\n\n```java\npackage class172;\n\n// 作诗，java版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上，有多少个数出现正偶数次\n// 1 <= 所有数值 <= 10^5\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P4135\n// 提交交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Poem1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXB = 401;\n\tpublic static int n, c, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int blen, bnum;\n\tpublic static int[] bi = new int[MAXN];\n\tpublic static int[] bl = new int[MAXB];\n\tpublic static int[] br = new int[MAXB];\n\n\t// freq[i][j]表示前i块中j出现的次数\n\tpublic static int[][] freq = new int[MAXB][MAXN];\n\t// even[i][j]表示从第i块到第j块，有多少个数出现正偶数次\n\tpublic static int[][] even = new int[MAXB][MAXB];\n\t// 数字词频统计\n\tpublic static int[] numCnt = new int[MAXN];\n\n\t// 返回从l块到r块，数字v的次数\n\tpublic static int getCnt(int l, int r, int v) {\n\t\treturn freq[r][v] - freq[l - 1][v];\n\t}\n\n\t// 某种数的之前词频是pre，现在如果词频加1\n\t// 返回 出现正偶数次的数字个数 的变化量\n\tpublic static int delta(int pre) {\n\t\tif (pre == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif ((pre & 1) == 0) {\n\t\t\treturn -1;\n\t\t}\n\t\treturn 1;\n\t}\n\n\tpublic static void prepare() {\n\t\tblen = (int) Math.sqrt(n);\n\t\tbnum = (n + blen - 1) / blen;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tbi[i] = (i - 1) / blen + 1;\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tbl[i] = (i - 1) * blen + 1;\n\t\t\tbr[i] = Math.min(i * blen, n);\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = bl[i]; j <= br[i]; j++) {\n\t\t\t\tfreq[i][arr[j]]++;\n\t\t\t}\n\t\t\tfor (int j = 1; j <= c; j++) {\n\t\t\t\tfreq[i][j] += freq[i - 1][j];\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= bnum; i++) {\n\t\t\tfor (int j = i; j <= bnum; j++) {\n\t\t\t\teven[i][j] = even[i][j - 1];\n\t\t\t\tfor (int k = bl[j]; k <= br[j]; k++) {\n\t\t\t\t\teven[i][j] += delta(numCnt[arr[k]]);\n\t\t\t\t\tnumCnt[arr[k]]++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int j = 1; j <= c; j++) {\n\t\t\t\tnumCnt[j] = 0;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int query(int l, int r) {\n\t\tint ans = 0;\n\t\tif (bi[l] == bi[r]) {\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tans += delta(numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t} else {\n\t\t\tans = even[bi[l] + 1][bi[r] - 1];\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tans += delta(getCnt(bi[l] + 1, bi[r] - 1, arr[i]) + numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tans += delta(getCnt(bi[l] + 1, bi[r] - 1, arr[i]) + numCnt[arr[i]]);\n\t\t\t\tnumCnt[arr[i]]++;\n\t\t\t}\n\t\t\tfor (int i = l; i <= br[bi[l]]; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t\tfor (int i = bl[bi[r]]; i <= r; i++) {\n\t\t\t\tnumCnt[arr[i]] = 0;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tc = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tprepare();\n\t\tfor (int i = 1, a, b, l, r, lastAns = 0; i <= m; i++) {\n\t\t\ta = (in.nextInt() + lastAns) % n + 1;\n\t\t\tb = (in.nextInt() + lastAns) % n + 1;\n\t\t\tl = Math.min(a, b);\n\t\t\tr = Math.max(a, b);\n\t\t\tlastAns = query(l, r);\n\t\t\tout.println(lastAns);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 20];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Poem2.java`\n\n```java\npackage class172;\n\n// 作诗，C++版\n// 给定一个长度为n的数组arr，接下来有m条操作，每条操作格式如下\n// 操作 l r : 打印arr[l..r]范围上，有多少个数出现正偶数次\n// 1 <= 所有数值 <= 10^5\n// 题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P4135\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXB = 401;\n//int n, c, m;\n//int arr[MAXN];\n//\n//int blen, bnum;\n//int bi[MAXN];\n//int bl[MAXB];\n//int br[MAXB];\n//\n//int freq[MAXB][MAXN];\n//int even[MAXB][MAXB];\n//int numCnt[MAXN];\n//\n//int getCnt(int l, int r, int v) {\n//    return freq[r][v] - freq[l - 1][v];\n//}\n//\n//int delta(int pre) {\n//    if (pre == 0) {\n//        return 0;\n//    }\n//    if ((pre & 1) == 0) {\n//        return -1;\n//    }\n//    return 1;\n//}\n//\n//void prepare() {\n//    blen = (int)sqrt(n);\n//    bnum = (n + blen - 1) / blen;\n//    for (int i = 1; i <= n; i++) {\n//        bi[i] = (i - 1) / blen + 1