0) {\n//        siz[l] = siz[h] - 1;\n//        add[l] = add[h];\n//        addHead(l);\n//    }\n//    num[i] = num[i] + add[h] + v;\n//    fa[i] = i;\n//    siz[i] = 1;\n//    add[i] = 0;\n//    addHead(i);\n//    u(l, i);\n//}\n//\n//void a2(int i, int v) {\n//    int h = find(i);\n//    minusHead(h);\n//    add[h] += v;\n//    addHead(h);\n//}\n//\n//void a3(int v) {\n//    addAll += v;\n//}\n//\n//int f1(int i) {\n//    return num[i] + add[find(i)] + addAll;\n//}\n//\n//int f2(int i) {\n//    int h = find(i);\n//    return num[h] + add[h] + addAll;\n//}\n//\n//int f3() {\n//    return (*heads.rbegin()) + addAll;\n//}\n//\n//int main(){\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) cin >> num[i];\n//    prepare();\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        string op; \n//        cin >> op;\n//        if (op == "F3") {\n//            cout << f3() << "\\n";\n//        } else {\n//            int x; cin >> x;\n//            if (op == "U") {\n//                int y; cin >> y;\n//                u(x, y);\n//            } else if (op == "A1") {\n//                int y; cin >> y;\n//                a1(x, y);\n//            } else if (op == "A2") {\n//                int y; cin >> y;\n//                a2(x, y);\n//            } else if (op == "A3") {\n//                a3(x);\n//            } else if (op == "F1") {\n//                cout << f1(x) << "\\n";\n//            } else {\n//                cout << f2(x) << "\\n";\n//            }\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_PersistentLeftistTree1.java`\n\n```java\npackage class155;\n\n// 可持久化左偏树的实现，利用对数器验证正确性，java版\n\nimport java.util.ArrayList;\nimport java.util.PriorityQueue;\n\npublic class Code03_PersistentLeftistTree1 {\n\n\tpublic static int MAXN = 10000;\n\tpublic static int MAXV = 100000;\n\tpublic static int MAXT = 2000001;\n\n\tpublic static int[] rt = new int[MAXN];\n\tpublic static int[] num = new int[MAXT];\n\tpublic static int[] left = new int[MAXT];\n\tpublic static int[] right = new int[MAXT];\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static int[] size = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\tpublic static int init(int v) {\n\t\tnum[++cnt] = v;\n\t\tleft[cnt] = right[cnt] = dist[cnt] = 0;\n\t\treturn cnt;\n\t}\n\n\tpublic static int clone(int i) {\n\t\tnum[++cnt] = num[i];\n\t\tleft[cnt] = left[i];\n\t\tright[cnt] = right[i];\n\t\tdist[cnt] = dist[i];\n\t\treturn cnt;\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (num[i] > num[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tint h = clone(i);\n\t\tright[h] = merge(right[h], j);\n\t\tif (dist[left[h]] < dist[right[h]]) {\n\t\t\ttmp = left[h];\n\t\t\tleft[h] = right[h];\n\t\t\tright[h] = tmp;\n\t\t}\n\t\tdist[h] = dist[right[h]] + 1;\n\t\treturn h;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tif (left[i] == 0 && right[i] == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (left[i] == 0 || right[i] == 0) {\n\t\t\treturn clone(left[i] + right[i]);\n\t\t}\n\t\treturn merge(left[i], right[i]);\n\t}\n\n\t// 可持久化左偏树，x版本加入数字y，生成最新的i版本\n\tpublic static void treeAdd(int x, int y, int i) {\n\t\trt[i] = merge(rt[x], init(y));\n\t\tsize[rt[i]] = size[rt[x]] + 1;\n\t}\n\n\t// 可持久化左偏树，x版本与y版本合并，生成最新的i版本\n\tpublic static void treeMerge(int x, int y, int i) {\n\t\tif (rt[x] == 0 && rt[y] == 0) {\n\t\t\trt[i] = 0;\n\t\t} else if (rt[x] == 0 || rt[y] == 0) {\n\t\t\trt[i] = clone(rt[x] + rt[y]);\n\t\t} else {\n\t\t\trt[i] = merge(rt[x], rt[y]);\n\t\t}\n\t\tsize[rt[i]] = size[rt[x]] + size[rt[y]];\n\t}\n\n\t// 可持久化左偏树，x版本弹出顶部，生成最新的i版本\n\tpublic static void treePop(int x, int i) {\n\t\tif (size[rt[x]] == 0) {\n\t\t\trt[i] = 0;\n\t\t} else {\n\t\t\trt[i] = pop(rt[x]);\n\t\t\tsize[rt[i]] = size[rt[x]] - 1;\n\t\t}\n\t}\n\n\t// 验证结构\n\tpublic static ArrayList<PriorityQueue<Integer>> verify = new ArrayList<>();\n\n\t// 验证结构，x版本加入数字y，生成最新版本\n\tpublic static void verifyAdd(int x, int y) {\n\t\tPriorityQueue<Integer> pre = verify.get(x);\n\t\tArrayList<Integer> tmp = new ArrayList<>();\n\t\twhile (!pre.isEmpty()) {\n\t\t\ttmp.add(pre.poll());\n\t\t}\n\t\tPriorityQueue<Integer> cur = new PriorityQueue<>();\n\t\tfor (int number : tmp) {\n\t\t\tpre.add(number);\n\t\t\tcur.add(number);\n\t\t}\n\t\tcur.add(y);\n\t\tverify.add(cur);\n\t}\n\n\t// 验证结构，x版本与y版本合并，生成最新版本\n\tpublic static void verifyMerge(int x, int y) {\n\t\tPriorityQueue<Integer> h1 = verify.get(x);\n\t\tPriorityQueue<Integer> h2 = verify.get(y);\n\t\tArrayList<Integer> tmp = new ArrayList<>();\n\t\tPriorityQueue<Integer> cur = new PriorityQueue<>();\n\t\twhile (!h1.isEmpty()) {\n\t\t\tint number = h1.poll();\n\t\t\ttmp.add(number);\n\t\t\tcur.add(number);\n\t\t}\n\t\tfor (int number : tmp) {\n\t\t\th1.add(number);\n\t\t}\n\t\ttmp.clear();\n\t\twhile (!h2.isEmpty()) {\n\t\t\tint number = h2.poll();\n\t\t\ttmp.add(number);\n\t\t\tcur.add(number);\n\t\t}\n\t\tfor (int number : tmp) {\n\t\t\th2.add(number);\n\t\t}\n\t\tverify.add(cur);\n\t}\n\n\t// 验证结构，x版本弹出顶部，生成最新版本\n\tpublic static void verifyPop(int x) {\n\t\tPriorityQueue<Integer> pre = verify.get(x);\n\t\tPriorityQueue<Integer> cur = new PriorityQueue<>();\n\t\tif (pre.size() == 0) {\n\t\t\tverify.add(cur);\n\t\t} else {\n\t\t\tint top = pre.poll();\n\t\t\tArrayList<Integer> tmp = new ArrayList<>();\n\t\t\twhile (!pre.isEmpty()) {\n\t\t\t\ttmp.add(pre.poll());\n\t\t\t}\n\t\t\tfor (int number : tmp) {\n\t\t\t\tpre.add(number);\n\t\t\t\tcur.add(number);\n\t\t\t}\n\t\t\tpre.add(top);\n\t\t\tverify.add(cur);\n\t\t}\n\t}\n\n\t// 可持久化左偏树i版本的堆\n\t// 是否等于\n\t// 验证结构i版本的堆\n\tpublic static boolean check(int i) {\n\t\tint h1 = rt[i];\n\t\tPriorityQueue<Integer> h2 = verify.get(i);\n\t\tif (size[h1] != h2.size()) {\n\t\t\treturn false;\n\t\t}\n\t\tboolean ans = true;\n\t\tArrayList<Integer> tmp = new ArrayList<>();\n\t\twhile (!h2.isEmpty()) {\n\t\t\tint o1 = num[h1];\n\t\t\th1 = pop(h1);\n\t\t\tint o2 = h2.poll();\n\t\t\ttmp.add(o2);\n\t\t\tif (o1 != o2) {\n\t\t\t\tans = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tfor (int v : tmp) {\n\t\t\th2.add(v);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tSystem.out.println("测试开始");\n\t\tdist[0] = -1;\n\t\trt[0] = size[0] = 0; // 可持久化左偏树生成0版本的堆\n\t\tverify.add(new PriorityQueue<>()); // 验证结构生成0版本的堆\n\t\tfor (int i = 1, op, x, y; i < MAXN; i++) {\n\t\t\t// op == 1，x版本的堆里加入数字y，形成i号版本的堆\n\t\t\t// op == 2，x版本的堆和y版本的堆合并，形成i号版本的堆\n\t\t\t// op == 3，x版本的堆弹出堆顶，形成i号版本的堆\n\t\t\top = i == 1 ? 1 : ((int) (Math.random() * 3) + 1);\n\t\t\tx = (int) (Math.random() * i);\n\t\t\tif (op == 1) {\n\t\t\t\ty = (int) (Math.random() * MAXV);\n\t\t\t\ttreeAdd(x, y, i);\n\t\t\t\tverifyAdd(x, y);\n\t\t\t} else if (op == 2) {\n\t\t\t\ty = x;\n\t\t\t\tdo {\n\t\t\t\t\ty = (int) (Math.random() * i);\n\t\t\t\t} while (y == x);\n\t\t\t\t// 保证x != y\n\t\t\t\ttreeMerge(x, y, i);\n\t\t\t\tverifyMerge(x, y);\n\t\t\t} else {\n\t\t\t\ttreePop(x, i);\n\t\t\t\tverifyPop(x);\n\t\t\t}\n\t\t\t// 检查最新版本的堆是否一样\n\t\t\tif (!check(i)) {\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t}\n\t\t// 最后验证是否所有版本的堆都一样\n\t\tfor (int i = 1; i < MAXN; i++) {\n\t\t\tif (!check(i)) {\n\t\t\t\tSystem.out.println("出错了！");\n\t\t\t}\n\t\t}\n\t\tSystem.out.println("测试结束");\n\t}\n\n}\n\n```\n\n### `Code03_PersistentLeftistTree2.java`\n\n```java\npackage class155;\n\n// 可持久化左偏树的实现，利用对数器验证正确性，C++版\n\n//#include <iostream>\n//#include <vector>\n//#include <queue>\n//#include <algorithm>\n//#include <cstdlib>\n//#include <ctime>\n//\n//using namespace std;\n//\n//const int MAXN = 10000;\n//const int MAXV = 100000;\n//const int MAXT = 2000001;\n//\n//int rt[MAXN];\n//int num[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int dist[MAXT];\n//int siz[MAXT];\n//int cnt = 0;\n//\n//int init(int v) {\n//    num[++cnt] = v;\n//    ls[cnt] = rs[cnt] = dist[cnt] = 0;\n//    return cnt;\n//}\n//\n//int clone(int i) {\n//    num[++cnt] = num[i];\