MAXN; i++) {\n//        op = i == 1 ? 1 : (rand() % 3 + 1);\n//        x = rand() % i;\n//        if (op == 1) {\n//            y = rand() % MAXV;\n//            treeAdd(x, y, i);\n//            verifyAdd(x, y);\n//        } else if (op == 2) {\n//            do {\n//                y = rand() % i;\n//            } while (y == x);\n//            treeMerge(x, y, i);\n//            verifyMerge(x, y);\n//        } else {\n//            treePop(x, i);\n//            verifyPop(x);\n//        }\n//        if (!check(i)) {\n//            cout << "err!" << endl;\n//        }\n//    }\n//    for (int i = 1; i < MAXN; i++) {\n//        if (!check(i)) {\n//            cout << "err!" << endl;\n//        }\n//    }\n//    cout << "test finish" << endl;\n//    return 0;\n//}\n```\n\n### `Code04_Blocks1.java`\n\n```java\npackage class155;\n\n// Y的积木，可持久化左偏树实现最优解，java版\n// 一共有n个正数数组，给定每个数组的大小mi，以及每个数组的数字\n// 每个数组必须选且只能选一个数字，就可以形成n个数字的挑选方案\n// 所有这些方案中，有数字累加和第1小的方案、第2小的方案、第3小的方案...\n// 打印，累加和前k小的方案，各自的累加和，要求实现O(k * log k)的解\n// 1 <= n、mi <= 100\n// 1 <= k <= 10^4\n// 1 <= 数字 <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P2409\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\nimport java.util.Arrays;\n\npublic class Code04_Blocks1 {\n\n\tpublic static int MAXN = 101;\n\tpublic static int MAXM = 10001;\n\tpublic static int MAXK = 10001;\n\tpublic static int MAXT = 1000001;\n\tpublic static int INF = 10000001;\n\n\tpublic static int n, k;\n\n\t// 所有数组的所有数字放在arr中\n\tpublic static int[] arr = new int[MAXM];\n\t// start[i] : 第i个数组的第一个数字在arr中的什么位置\n\tpublic static int[] start = new int[MAXN];\n\t// boundary[i] : 第i个数组的越界位置在arr中的什么位置\n\tpublic static int[] boundary = new int[MAXN];\n\n\t// 左偏树代表基于之前的某个方案，做出行动的可能性\n\t// 左偏树的头就代表这个最优行动，假设编号为h的节点是头\n\t// idx[h] : 最优行动来自哪个数组\n\tpublic static int[] idx = new int[MAXT];\n\t// jdx[h] : 最优行动要替换掉idx[h]数组中什么位置的数\n\tpublic static int[] jdx = new int[MAXT];\n\t// cost[h] : 基于之前的某个方案，最优行动会让累加和增加多少\n\tpublic static int[] cost = new int[MAXT];\n\tpublic static int[] left = new int[MAXT];\n\tpublic static int[] right = new int[MAXT];\n\tpublic static int[] dist = new int[MAXT];\n\t// pre[h] : 基于之前的某个方案，这个方案的累加和，标签信息\n\tpublic static int[] pre = new int[MAXT];\n\tpublic static int cnt = 0;\n\n\t// heap是经典的小根堆，放着所有版本左偏树的头\n\t// 哪个左偏树的头节点，所代表方案的累加和最小，谁就放在heap的顶部\n\tpublic static int[] heap = new int[MAXK];\n\tpublic static int heapSize = 0;\n\n\t// 收集答案\n\tpublic static int[] ans = new int[MAXK];\n\n\tpublic static int init(int i, int j) {\n\t\tidx[++cnt] = i;\n\t\tjdx[cnt] = j;\n\t\tcost[cnt] = j + 1 < boundary[i] ? (arr[j + 1] - arr[j]) : INF;\n\t\tleft[cnt] = right[cnt] = dist[cnt] = 0;\n\t\treturn cnt;\n\t}\n\n\tpublic static int clone(int i) {\n\t\tidx[++cnt] = idx[i];\n\t\tjdx[cnt] = jdx[i];\n\t\tcost[cnt] = cost[i];\n\t\tleft[cnt] = left[i];\n\t\tright[cnt] = right[i];\n\t\tdist[cnt] = dist[i];\n\t\treturn cnt;\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (cost[i] > cost[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tint h = clone(i);\n\t\tright[h] = merge(right[h], j);\n\t\tif (dist[left[h]] < dist[right[h]]) {\n\t\t\ttmp = left[h];\n\t\t\tleft[h] = right[h];\n\t\t\tright[h] = tmp;\n\t\t}\n\t\tdist[h] = dist[right[h]] + 1;\n\t\treturn h;\n\t}\n\n\tpublic static int pop(int i) {\n\t\tif (left[i] == 0 && right[i] == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tif (left[i] == 0 || right[i] == 0) {\n\t\t\treturn clone(left[i] + right[i]);\n\t\t}\n\t\treturn merge(left[i], right[i]);\n\t}\n\n\tpublic static boolean compare(int i, int j) {\n\t\treturn pre[i] + cost[i] < pre[j] + cost[j];\n\t}\n\n\tpublic static void heapAdd(int i) {\n\t\theap[++heapSize] = i;\n\t\tint cur = heapSize, up = cur / 2, tmp;\n\t\twhile (cur > 1 && compare(heap[cur], heap[up])) {\n\t\t\ttmp = heap[up];\n\t\t\theap[up] = heap[cur];\n\t\t\theap[cur] = tmp;\n\t\t\tcur = up;\n\t\t\tup = cur / 2;\n\t\t}\n\t}\n\n\tpublic static int heapPop() {\n\t\tint ans = heap[1];\n\t\theap[1] = heap[heapSize--];\n\t\tint cur = 1, l = cur * 2, r = l + 1, best, tmp;\n\t\twhile (l <= heapSize) {\n\t\t\tbest = (r <= heapSize && compare(heap[r], heap[l])) ? r : l;\n\t\t\tbest = compare(heap[best], heap[cur]) ? best : cur;\n\t\t\tif (best == cur) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\ttmp = heap[best];\n\t\t\theap[best] = heap[cur];\n\t\t\theap[cur] = tmp;\n\t\t\tcur = best;\n\t\t\tl = cur * 2;\n\t\t\tr = l + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void compute() {\n\t\tint first = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tArrays.sort(arr, start[i], boundary[i]);\n\t\t\tfirst += arr[start[i]];\n\t\t}\n\t\tdist[0] = -1;\n\t\tint head = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead = merge(head, init(i, start[i]));\n\t\t}\n\t\tpre[head] = first;\n\t\tans[1] = first;\n\t\theapAdd(head);\n\t\tfor (int ansi = 2, h1, h2; ansi <= k; ansi++) {\n\t\t\thead = heapPop();\n\t\t\tans[ansi] = pre[head] + cost[head];\n\t\t\th1 = pop(head);\n\t\t\tif (h1 != 0) {\n\t\t\t\tpre[h1] = pre[head];\n\t\t\t\theapAdd(h1);\n\t\t\t}\n\t\t\tif (jdx[head] + 1 < boundary[idx[head]]) {\n\t\t\t\th2 = merge(h1, init(idx[head], jdx[head] + 1));\n\t\t\t\tpre[h2] = ans[ansi];\n\t\t\t\theapAdd(h2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tk = (int) in.nval;\n\t\tfor (int i = 1, m, ai = 0; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tm = (int) in.nval;\n\t\t\tstart[i] = ai + 1;\n\t\t\tfor (int j = 1; j <= m; j++) {\n\t\t\t\tin.nextToken();\n\t\t\t\tarr[++ai] = (int) in.nval;\n\t\t\t}\n\t\t\tboundary[i] = start[i] + m;\n\t\t}\n\t\tcompute();\n\t\tfor (int i = 1; i <= k; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code04_Blocks2.java`\n\n```java\npackage class155;\n\n// Y的积木，可持久化左偏树实现最优解，C++版\n// 一共有n个正数数组，给定每个数组的大小mi，以及每个数组的数字\n// 每个数组必须选且只能选一个数字，就可以形成n个数字的挑选方案\n// 所有这些方案中，有数字累加和第1小的方案、第2小的方案、第3小的方案...\n// 打印，累加和前k小的方案，各自的累加和，要求实现O(k * log k)的解\n// 1 <= n、mi <= 100\n// 1 <= k <= 10^4\n// 1 <= 数字 <= 100\n// 测试链接 : https://www.luogu.com.cn/problem/P2409\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <algorithm>\n//\n//using namespace std;\n//\n//const int MAXN = 101;\n//const int MAXM = 10001;\n//const int MAXK = 10001;\n//const int MAXT = 1000001;\n//const int INF = 10000001;\n//\n//int n, k;\n//\n//int arr[MAXM];\n//int start[MAXN];\n//int boundary[MAXN];\n//\n//int idx[MAXT];\n//int jdx[MAXT];\n//int cost[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int dist[MAXT];\n//int pre[MAXT];\n//int cnt = 0;\n//\n//int heap[MAXK];\n//int heapSize = 0;\n//\n//int ans[MAXK];\n//\n//int init(int i, int j) {\n//    idx[++cnt] = i;\n//    jdx[cnt] = j;\n//    cost[cnt] = (j + 1 < boundary[i]) ? (arr[j + 1] - arr[j]) : INF;\n//    ls[cnt] = rs[cnt] = dist[cnt] = 0;\n//    return cnt;\n//}\n//\n//int clone(int i) {\n//    idx[++cnt] = idx[i];\n//    jdx[cnt] = jdx[i];\n//    cost[cnt] = cost[i];\n//    ls[cnt] = ls[i];\n//    rs[cnt] = rs[i];\n//    dist[cnt] = dist[i];\n//    return cnt;\n//}\n//\n//int merge(int i, int j) {\n//    if (i == 0 || j == 0) return i + j;\n//    if (cost[i] > cost[j]) {\n//        swap(i, j);\n//    }\n//    int h = clone(i);\n//    rs[h] = merge(rs[h], j);\n//    if (dist[ls[h]] < dist[rs[h]]) {\n//        swap(ls[h], rs[h]);\n//    }\n//    dist[h] = dist[rs[h]] + 1;\n//    return h;\n//}\n//\n//int pop(int i) {\n//    if (ls[i] == 0 && rs[i] == 0) return 0;\n