 + 1;\n//        for (int j = 1; j <= m; j++) {\n//            cin >> arr[++ai];\n//        }\n//        boundary[i] = start[i] + m;\n//    }\n//    compute();\n//    for (int i = 1; i <= k; i++) {\n//        cout << ans[i] << " ";\n//    }\n//    cout << endl;\n//    return 0;\n//}\n```\n\n### `Code05_KShortestPath1.java`\n\n```java\npackage class155;\n\n// k短路问题，可持久化左偏树实现最优解，java版\n// 有n个点编号1~n，有m条边，每条边都是正数边权，组成有向带权图\n// 从1号点走到n号点，就认为是一次旅行\n// 一次旅行中，边不能重复选，点可以重复经过，如果到达了n号点，那么旅行立刻停止\n// 从1号点走到n号点，会有很多通路方案，通路方案的路费为选择边的边权累加和\n// 虽然每次旅行都是从1号点到n号点，但是你希望每次旅行的通路方案都是不同的\n// 任何两次旅行，只要选择的边稍有不同，就认为是不同的通路方案\n// 你的钱数为money，用来支付路费，打印你一共能进行几次旅行\n// 测试链接 : https://www.luogu.com.cn/problem/P2483\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.Arrays;\n\npublic class Code05_KShortestPath1 {\n\n\tpublic static int MAXN = 5001;\n\tpublic static int MAXM = 200001;\n\tpublic static int MAXT = 1000001;\n\tpublic static int MAXH = 4200001;\n\tpublic static double INF = 1e18;\n\n\tpublic static int n, m;\n\tpublic static double money;\n\n\t// 关于正反图有一个非常值得注意的地方\n\t// 如果正图中，a到b的边，编号为x\n\t// 那么反图中，b到a的边，编号也是x\n\t// 因为每一条边，正图建立的同时，反图也同步建立\n\t// 所以正反图中这条边分配的编号也是一样的\n\t// 正图\n\tpublic static int[] headg = new int[MAXN];\n\tpublic static int[] tog = new int[MAXM];\n\tpublic static int[] nextg = new int[MAXM];\n\tpublic static double[] weightg = new double[MAXM];\n\tpublic static int cntg = 0;\n\n\t// 反图\n\tpublic static int[] headr = new int[MAXN];\n\tpublic static int[] tor = new int[MAXM];\n\tpublic static int[] nextr = new int[MAXM];\n\tpublic static double[] weightr = new double[MAXM];\n\tpublic static int cntr = 0;\n\n\t// 左偏树代表基于之前的通路方案，选择非树边的可能性\n\t// 左偏树的头就代表最优的选择，假设编号为h的节点是头\n\t// to[h] : 选择最优非树边，这个非树边在正图里指向哪个节点\n\tpublic static int[] to = new int[MAXT];\n\t// cost[h] : 基于之前的通路方案，最优选择会让路费增加多少\n\tpublic static double[] cost = new double[MAXT];\n\tpublic static int[] left = new int[MAXT];\n\tpublic static int[] right = new int[MAXT];\n\tpublic static int[] dist = new int[MAXT];\n\tpublic static int cntt = 0;\n\n\t// rt[u] : 在最短路树上，节点u及其所有祖先节点，所拥有的全部非树边，组成的左偏树\n\tpublic static int[] rt = new int[MAXN];\n\n\t// heap是经典的小根堆，放着很多(key, val)数据，根据val来组织小根堆\n\tpublic static int[] key = new int[MAXH];\n\tpublic static double[] val = new double[MAXH];\n\tpublic static int[] heap = new int[MAXH];\n\tpublic static int cntd, cnth;\n\n\t// dijkstra算法需要，根据反图跑dijkstra，生成从节点n开始的最短路树\n\t// vis[u] : 节点u到节点n的最短距离，是否已经计算过了\n\tpublic static boolean[] vis = new boolean[MAXN];\n\t// path[u] : 最短路树上，到达节点u的树边，编号是什么，也代表正图上，所对应的边\n\tpublic static int[] path = new int[MAXN];\n\t// dis[u] : 最短路树上，节点n到节点u的最短距离\n\tpublic static double[] dis = new double[MAXN];\n\n\tpublic static void addEdgeG(int u, int v, double w) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\tweightg[cntg] = w;\n\t\theadg[u] = cntg;\n\t}\n\n\tpublic static void addEdgeR(int u, int v, double w) {\n\t\tnextr[++cntr] = headr[u];\n\t\ttor[cntr] = v;\n\t\tweightr[cntr] = w;\n\t\theadr[u] = cntr;\n\t}\n\n\tpublic static int init(int t, double c) {\n\t\tto[++cntt] = t;\n\t\tcost[cntt] = c;\n\t\tleft[cntt] = right[cntt] = dist[cntt] = 0;\n\t\treturn cntt;\n\t}\n\n\tpublic static int clone(int i) {\n\t\tto[++cntt] = to[i];\n\t\tcost[cntt] = cost[i];\n\t\tleft[cntt] = left[i];\n\t\tright[cntt] = right[i];\n\t\tdist[cntt] = dist[i];\n\t\treturn cntt;\n\t}\n\n\tpublic static int merge(int i, int j) {\n\t\tif (i == 0 || j == 0) {\n\t\t\treturn i + j;\n\t\t}\n\t\tint tmp;\n\t\tif (cost[i] > cost[j]) {\n\t\t\ttmp = i;\n\t\t\ti = j;\n\t\t\tj = tmp;\n\t\t}\n\t\tint h = clone(i);\n\t\tright[h] = merge(right[h], j);\n\t\tif (dist[left[h]] < dist[right[h]]) {\n\t\t\ttmp = left[h];\n\t\t\tleft[h] = right[h];\n\t\t\tright[h] = tmp;\n\t\t}\n\t\tdist[h] = dist[right[h]] + 1;\n\t\treturn h;\n\t}\n\n\t// (k, v)组成一个数据，放到堆上，根据v来组织小根堆\n\tpublic static void heapAdd(int k, double v) {\n\t\tkey[++cntd] = k;\n\t\tval[cntd] = v;\n\t\theap[++cnth] = cntd;\n\t\tint cur = cnth, father = cur / 2, tmp;\n\t\twhile (cur > 1 && val[heap[father]] > val[heap[cur]]) {\n\t\t\ttmp = heap[father];\n\t\t\theap[father] = heap[cur];\n\t\t\theap[cur] = tmp;\n\t\t\tcur = father;\n\t\t\tfather = cur / 2;\n\t\t}\n\t}\n\n\t// 小根堆上，堆顶的数据(k, v)弹出，并返回数据所在的下标ans\n\t// 根据返回值ans，key[ans]得到k，val[ans]得到v\n\tpublic static int heapPop() {\n\t\tint ans = heap[1];\n\t\theap[1] = heap[cnth--];\n\t\tint cur = 1, l = cur * 2, r = l + 1, best, tmp;\n\t\twhile (l <= cnth) {\n\t\t\tbest = r <= cnth && val[heap[r]] < val[heap[l]] ? r : l;\n\t\t\tbest = val[heap[best]] < val[heap[cur]] ? best : cur;\n\t\t\tif (best == cur) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\ttmp = heap[best];\n\t\t\theap[best] = heap[cur];\n\t\t\theap[cur] = tmp;\n\t\t\tcur = best;\n\t\t\tl = cur * 2;\n\t\t\tr = l + 1;\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static boolean heapEmpty() {\n\t\treturn cnth == 0;\n\t}\n\n\t// 根据反图跑dijkstra算法\n\t// 得到从节点n出发的最短路树、每个节点到节点n的最短距离信息\n\t// 最短路树如果有多个，找到任何一个即可\n\tpublic static void dijkstra() {\n\t\tdis[n] = 0;\n\t\tArrays.fill(dis, 1, n, INF);\n\t\tcntd = cnth = 0;\n\t\theapAdd(n, 0);\n\t\twhile (!heapEmpty()) {\n\t\t\tint top = heapPop();\n\t\t\tint u = key[top];\n\t\t\tdouble w = val[top];\n\t\t\tif (!vis[u]) {\n\t\t\t\tvis[u] = true;\n\t\t\t\tfor (int e = headr[u], v; e > 0; e = nextr[e]) {\n\t\t\t\t\tv = tor[e];\n\t\t\t\t\tif (dis[v] > w + weightr[e]) {\n\t\t\t\t\t\tdis[v] = w + weightr[e];\n\t\t\t\t\t\tpath[v] = e;\n\t\t\t\t\t\theapAdd(v, dis[v]);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 在最短路树上的每个节点，生成自己的左偏树\n\t// 节点u的左偏树 = 节点u自己的非树边左偏树 + 节点u在最短路树上的父亲的左偏树\n\t// 课上重点解释了这么做的意义\n\tpublic static void mergeRoad() {\n\t\tcntd = cnth = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\theapAdd(i, dis[i]);\n\t\t}\n\t\tdist[0] = -1;\n\t\twhile (!heapEmpty()) {\n\t\t\tint top = heapPop();\n\t\t\tint u = key[top];\n\t\t\tfor (int e = headg[u], v; e > 0; e = nextg[e]) {\n\t\t\t\tv = tog[e];\n\t\t\t\t// path[u]既是边在反图中的编号，也是边在正图中的编号\n\t\t\t\t// 因为正反图同步建立，边的正图编号 == 边的反图编号\n\t\t\t\tif (e != path[u]) {\n\t\t\t\t\trt[u] = merge(rt[u], init(v, weightg[e] + dis[v] - dis[u]));\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (path[u] != 0) {\n\t\t\t\trt[u] = merge(rt[u], rt[tog[path[u]]]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 从路费第1小的方案开始，逐渐找到第2小、第3小...\n\t// 看看money能够覆盖几次旅行，返回旅行的次数\n\tpublic static int expand() {\n\t\tint ans = 0;\n\t\tmoney -= dis[1];\n\t\tif (money >= 0) {\n\t\t\tans++;\n\t\t\tcntd = cnth = 0;\n\t\t\tif (rt[1] != 0) {\n\t\t\t\t// 开始阶段\n\t\t\t\t// 1号节点左偏树的堆顶，代表增加代价最小的非树边，放入决策堆\n\t\t\t\t// 目前路通方案的路费，同步放入\n\t\t\t\theapAdd(rt[1], dis[1] + cost[rt[1]]);\n\t\t\t}\n\t\t\twhile (!heapEmpty()) {\n\t\t\t\tint top = heapPop();\n\t\t\t\tint h = key[top];\n\t\t\t\tdouble w = val[top];\n\t\t\t\tmoney -= w;\n\t\t\t\tif (money < 0) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tans++;\n\t\t\t\t// 当前选择的非树边，被左偏树上的左儿子替换\n\t\t\t\tif (left[h] != 0) {\n\t\t\t\t\theapAdd(left[h], w - cost[h] + cost[left[h]]);\n\t\t\t\t}\n\t\t\t\t// 当前选择的非树边，被左偏树上的右儿子替换\n\t\t\t\tif (right[h] != 0) {\n\t\t\t\t\theapAdd(right[h], w - cost[h] + cost[right[h]]);\n\t\t\t\t}\n\t\t\t\t// 当前选择的非树边，指向节点to[h]，那么从to[h]的左偏树里，新增一个最优的非树边\n\t\t\t\tif (to[h] != 0 && rt[to[h]] != 0) {\n\t\t\t\t\theapAdd(rt[to[h]], w + cost[rt[to[h]]]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tFastReader in = new FastReader();\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tmoney = in.nextDouble();\n\t\tint u, v;\n\t\tdouble w;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\tw = in.nextDouble();\n\t\t\t// 题目说了，一旦到达节点n，旅行立刻停止\n\t\t\t// 所以从节点n出发的边，一律忽略\n\t\t\tif (u != n) {\n\t\t\t\taddEdgeG(u, v, w); // 建立正图\n\t\t\t\taddEdgeR(v, u, w); // 建立反图\n\t\t\t}\n\t\t}\n\t\tdijkstra();\n\t\tmergeRoad();\n\t\tint ans = expand();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tfinal private int BUFFER_SIZE = 1 << 16;\n\t\tprivate final InputStream in;\n\t\tprivate final byte[] buffer;\n\t\tprivate int ptr, len;\n\n\t\tpublic FastReader() {\n\t\t\tin = System.in;\n\t\t\tbuffer = new byte[BUFFER_SIZE];\n\t\t\tptr = len = 0;\n\t\t}\n\n\t\tprivate boolean hasNextByte() throws IOException {\n\t\t\tif (ptr < len)\n\t\t\t\treturn true;\n\t\t\tptr = 0;\n\t\t\tlen = in.read(buffer);\n\t\t\treturn len > 0;\n\t\t}\n\n\t\tprivate byte readByte() throws IOException {\n\t\t\tif (!hasNextByte())\n\t\t\t\treturn -1;\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tpublic boolean hasNext() throws IOException {\n\t\t\twhile (hasNextByte()) {\n\t\t\t\tbyte b = buffer[ptr];\n\t\t\t\tif (!isWhitespace(b))\n\t\t\t\t\treturn true;\n\t\t\t\tptr++;\n\t\t\t}\n\t\t\treturn false;\n\t\t}\n\n\t\tpublic int nextInt() throws IOException {\n\t\t\tint num = 0;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tpublic double nextDouble() throws IOException {\n\t\t\tdouble num = 0, div = 1;\n\t\t\tbyte b = readByte();\n\t\t\twhile (isWhitespace(b))\n\t\t\t\tb = readByte();\n\t\t\tboolean minus = false;\n\t\t\tif (b == '-') {\n\t\t\t\tminus = true;\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\twhile (!isWhitespace(b) && b != '.' && b != -1) {\n\t\t\t\tnum = num * 10 + (b - '0');\n\t\t\t\tb = readByte();\n\t\t\t}\n\t\t\tif (b == '.') {\n\t\t\t\tb = readByte();\n\t\t\t\twhile (!isWhitespace(b) && b != -1) {\n\t\t\t\t\tnum += (b - '0') / (div *= 10);\n\t\t\t\t\tb = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn minus ? -num : num;\n\t\t}\n\n\t\tprivate boolean isWhitespace(byte b) {\n\t\t\treturn b == ' ' || b == '\\n' || b == '\\r' || b == '\\t';\n\t\t}\n\t}\n\n}\n```\n\n### `Code05_KShortestPath2.java`\n\n```java\npackage class155;\n\n// k短路问题，可持久化左偏树实现最优解，C++版\n// 有n个点编号1~n，有m条边，每条边都是正数边权，组成有向带权图\n// 从1号点走到n号点，就认为是一次旅行\n// 一次旅行中，边不能重复选，点可以重复经过，如果到达了n号点，那么旅行立刻停止\n// 从1号点走到n号点，会有很多通路方案，通路方案的路费为选择边的边权累加和\n// 虽然每次旅行都是从1号点到n号点，但是你希望每次旅行的通路方案都是不同的\n// 任何两次旅行，只要选择的边稍有不同，就认为是不同的通路方案\n// 你的钱数为money，用来支付路费，打印你一共能进行几次旅行\n// 测试链接 : https://www.luogu.com.cn/problem/P2483\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 5001;\n//const int MAXM = 200001;\n//const int MAXT = 1000001;\n//const int MAXH = 4200001;\n//const double INF = 1e18;\n//\n//int n, m;\n//double money;\n//\n//int headg[MAXN];\n//int tog[MAXM];\n//int nextg[MAXM];\n//double weightg[MAXM];\n//int cntg = 0;\n//\n//int headr[MAXN];\n//int tor[MAXM];\n//int nextr[MAXM];\n//double weightr[MAXM];\n//int cntr = 0;\n//\n//int to[MAXT];\n//double cost[MAXT];\n//int ls[MAXT];\n//int rs[MAXT];\n//int dist[MAXT];\n//int cntt = 0;\n//\n//int rt[MAXN];\n//\n//int key[MAXH];\n//double val[MAXH];\n//int heap[MAXH];\n//int cntd, cnth;\n//\n//bool vis[MAXN];\n//int path[MAXN];\n//double dis[MAXN];\n//\n//void addEdgeG(int u, int v, double w){\n//    nextg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    weightg[cntg] = w;\n//    headg[u] = cntg;\n//}\n//\n//void addEdgeR(int u, int v, double w){\n//    nextr[++cntr] = headr[u];\n//    tor[cntr] = v;\n//    weightr[cntr] = w;\n//    headr[u] = cntr;\n//}\n//\n//int init(int t, double v){\n//    to[++cntt] = t;\n//    cost[cntt] = v;\n//    ls[cntt] = rs[cntt] = dist[cntt] = 0;\n//    return cntt;\n//}\n//\n//int clone(int i){\n//    to[++cntt] = to[i];\n//    cost[cntt] = cost[i];\n//    ls[cntt] = ls[i];\n//    rs[cntt] = rs[i];\n//    dist[cntt] = dist[i];\n//    return cntt;\n//}\n//\n//int merge(int i, int j){\n//    if(i == 0 || j == 0){\n//        return i + j;\n//    }\n//    if(cost[i] > cost[j])