i) {\n\t\treturn right[father[i]] == i ? 1 : 0;\n\t}\n\n\tpublic static void rotate(int i) {\n\t\tint f = father[i], g = father[f], soni = lr(i), sonf = lr(f);\n\t\tif (soni == 1) {\n\t\t\tright[f] = left[i];\n\t\t\tif (right[f] != 0) {\n\t\t\t\tfather[right[f]] = f;\n\t\t\t}\n\t\t\tleft[i] = f;\n\t\t} else {\n\t\t\tleft[f] = right[i];\n\t\t\tif (left[f] != 0) {\n\t\t\t\tfather[left[f]] = f;\n\t\t\t}\n\t\t\tright[i] = f;\n\t\t}\n\t\tif (g != 0) {\n\t\t\tif (sonf == 1) {\n\t\t\t\tright[g] = i;\n\t\t\t} else {\n\t\t\t\tleft[g] = i;\n\t\t\t}\n\t\t}\n\t\tfather[f] = i;\n\t\tfather[i] = g;\n\t\tup(f);\n\t\tup(i);\n\t}\n\n\tpublic static void splay(int i, int goal) {\n\t\tint f = father[i], g = father[f];\n\t\twhile (f != goal) {\n\t\t\tif (g != goal) {\n\t\t\t\tif (lr(i) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(i);\n\t\t\tf = father[i];\n\t\t\tg = father[f];\n\t\t}\n\t\tif (goal == 0) {\n\t\t\thead = i;\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tkey[++cnt] = num;\n\t\tsize[cnt] = 1;\n\t\tif (head == 0) {\n\t\t\thead = cnt;\n\t\t} else {\n\t\t\tint f = 0, i = head, son = 0;\n\t\t\twhile (i != 0) {\n\t\t\t\tf = i;\n\t\t\t\tif (key[i] <= num) {\n\t\t\t\t\tson = 1;\n\t\t\t\t\ti = right[i];\n\t\t\t\t} else {\n\t\t\t\t\tson = 0;\n\t\t\t\t\ti = left[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (son == 1) {\n\t\t\t\tright[f] = cnt;\n\t\t\t} else {\n\t\t\t\tleft[f] = cnt;\n\t\t\t}\n\t\t\tfather[cnt] = f;\n\t\t\tsplay(cnt, 0);\n\t\t}\n\t}\n\n\tpublic static int index(int x) {\n\t\tint i = head, last = head;\n\t\twhile (i != 0) {\n\t\t\tlast = i;\n\t\t\tif (size[left[i]] >= x) {\n\t\t\t\ti = left[i];\n\t\t\t} else if (size[left[i]] + 1 < x) {\n\t\t\t\tx -= size[left[i]] + 1;\n\t\t\t\ti = right[i];\n\t\t\t} else {\n\t\t\t\ti = 0;\n\t\t\t}\n\t\t}\n\t\tsplay(last, 0);\n\t\treturn key[last];\n\t}\n\n\tpublic static void departure() {\n\t\tint num = limit - change - 1;\n\t\tint i = head, ans = 0;\n\t\twhile (i != 0) {\n\t\t\tif (key[i] > num) {\n\t\t\t\tans = i;\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\tif (ans == 0) {\n\t\t\thead = 0;\n\t\t} else {\n\t\t\tsplay(ans, 0);\n\t\t\tleft[head] = 0;\n\t\t\tup(head);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tint n = io.nextInt();\n\t\tlimit = io.nextInt();\n\t\tString op;\n\t\tint x;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt();\n\t\t\tif (op.equals("I")) {\n\t\t\t\tif (x >= limit) {\n\t\t\t\t\tenter++;\n\t\t\t\t\tadd(x - change);\n\t\t\t\t}\n\t\t\t} else if (op.equals("A")) {\n\t\t\t\tchange += x;\n\t\t\t} else if (op.equals("S")) {\n\t\t\t\tchange -= x;\n\t\t\t\tdeparture();\n\t\t\t} else {\n\t\t\t\tif (x > size[head]) {\n\t\t\t\t\tio.println(-1);\n\t\t\t\t} else {\n\t\t\t\t\tio.println(index(size[head] - x + 1) + change);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tio.println(enter - size[head]);\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// Kattio类IO效率很好，但还是不如StreamTokenizer\n\t// 只有StreamTokenizer无法正确处理时，才考虑使用这个类\n\t// 参考链接 : https://oi-wiki.org/lang/java-pro/\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_FrustratedCashier2.java`\n\n```java\npackage class153;\n\n// 郁闷的出纳员(C++版)\n// 最低薪水为limit，一旦员工薪水低于limit，员工会离职，实现如下四种操作\n// I x : 新来员工初始薪水是x，如果x低于limit，该员工不会入职当然也不算离职\n// A x : 所有员工的薪水都加上x\n// S x : 所有员工的薪水都减去x，一旦有员工低于limit那么就会离职\n// F x : 查询第x多的工资，如果x大于当前员工数量，打印-1\n// 所有操作完成后，打印有多少员工在操作期间离开了公司\n// 测试链接 : https://www.luogu.com.cn/problem/P1486\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <cstring>\n//#include <algorithm>\n//using namespace std;\n//\n//const int MAXN = 300001;\n//\n//int head = 0;\n//int cnt = 0;\n//int key[MAXN];\n//int fa[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int siz[MAXN];\n//int limit;\n//int change = 0;\n//int enter = 0;\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]] + 1;\n//}\n//\n//int lr(int i) {\n//    return rs[fa[i]] == i ? 1 : 0;\n//}\n//\n//void rotate(int i) {\n//    int f = fa[i], g = fa[f], soni = lr(i), sonf = lr(f);\n//    if (soni == 1) {\n//        rs[f] = ls[i];\n//        if (rs[f] != 0) {\n//            fa[rs[f]] = f;\n//        }\n//        ls[i] = f;\n//    } else {\n//        ls[f] = rs[i];\n//        if (ls[f] != 0) {\n//            fa[ls[f]] = f;\n//        }\n//        rs[i] = f;\n//    }\n//    if (g != 0) {\n//        if (sonf == 1) {\n//            rs[g] = i;\n//        } else {\n//            ls[g] = i;\n//        }\n//    }\n//    fa[f] = i;\n//    fa[i] = g;\n//    up(f);\n//    up(i);\n//}\n//\n//void splay(int i, int goal) {\n//    int f = fa[i], g = fa[f];\n//    while (f != goal) {\n//        if (g != goal) {\n//            if (lr(i) == lr(f)) {\n//                rotate(f);\n//            } else {\n//                rotate(i);\n//            }\n//        }\n//        rotate(i);\n//        f = fa[i];\n//        g = fa[f];\n//    }\n//    if (goal == 0) {\n//        head = i;\n//    }\n//}\n//\n//void add(int num) {\n//    key[++cnt] = num;\n//    siz[cnt] = 1;\n//    if (head == 0) {\n//        head = cnt;\n//    } else {\n//        int f = 0, i = head, son = 0;\n//        while (i != 0) {\n//            f = i;\n//            if (key[i] <= num) {\n//                son = 1;\n//                i = rs[i];\n//            } else {\n//                son = 0;\n//                i = ls[i];\n//            }\n//        }\n//        if (son == 1) {\n//            rs[f] = cnt;\n//        } else {\n//            ls[f] = cnt;\n//        }\n//        fa[cnt] = f;\n//        splay(cnt, 0);\n//    }\n//}\n//\n//int index(int x) {\n//    int i = head, last = head;\n//    while (i != 0) {\n//        last = i;\n//        if (siz[ls[i]] >= x) {\n//            i = ls[i];\n//        } else if (siz[ls[i]] + 1 < x) {\n//            x -= siz[ls[i]] + 1;\n//            i = rs[i];\n//        } else {\n//            i = 0;\n//        }\n//    }\n//    splay(last, 0);\n//    return key[last];\n//}\n//\n//void departure() {\n//    int num = limit - change - 1;\n//    int i = head, ans = 0;\n//    while (i != 0) {\n//        if (key[i] > num) {\n//            ans = i;\n//            i = ls[i];\n//        } else {\n//            i = rs[i];\n//        }\n//    }\n//    if (ans == 0) {\n//        head = 0;\n//    } else {\n//        splay(ans, 0);\n//        ls[head] = 0;\n//        up(head);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    int n, x;\n//    char op;\n//    cin >> n >> limit;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> op >> x;\n//        if (op == 'I') {\n//            if (x >= limit) {\n//                enter++;\n//                add(x - change);\n//            }\n//        } else if (op == 'A') {\n//            change += x;\n//        } else if (op == 'S') {\n//            change -= x;\n//            departure();\n//        } else if (op == 'F') {\n//            if (x > siz[head]) {\n//                cout << -1 << endl;\n//            } else {\n//                cout << index(siz[head] - x + 1) + change << endl;\n//            }\n//        }\n//    }\n//    cout << enter - siz[head] << endl;\n//    return 0;\n//}\n```\n\n### `Code03_LiteraryTree1.java`\n\n```java\npackage class153;\n\n// 文艺平衡树，Splay实现范围翻转，java版本\n// 长度为n的序列，下标从1开始，一开始序列为1, 2, ..., n\n// 接下来会有k个操作，每个操作给定l，r，表示从l到r范围上的所有数字翻转\n// 做完k次操作后，从左到右打印所有数字\n// 1 <= n, k <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3391\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code03_LiteraryTree1 {\n\n\tpublic static int MAXN = 100005;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] num = new int[MAXN];\n\n\tpublic static int[] father = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static boolean[] reverse = new boolean[MAXN];\n\n\tpublic static int[] stack = new int[MAXN];\n\n\tpublic static int si;\n\n\tpublic static int[] ans = new int[MAXN];\n\n\tpublic static int ai;\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\tpublic static int lr(int i) {\n\t\treturn right[father[i]] == i ? 1 : 0;\n\t}\n\n\tpublic static void rotate(int i) {\n\t\tint f = father[i], g = father[f], soni = lr(i), sonf = lr(f);\n\t\tif (soni == 1) {\n\t\t\tright[f] = left[i];\n\t\t\tif (right[f] != 0) {\n\t\t\t\tfather[right[f]] = f;\n\t\t\t}\n\t\t\tleft[i] = f;\n\t\t} else {\n\t\t\tleft[f] = right[i];\n\t\t\tif (left[f] != 0) {\n\t\t\t\tfather[left[f]] = f;\n\t\t\t}\n\t\t\tright[i] = f;\n\t\t}\n\t\tif (g != 0) {\n\t\t\tif (sonf == 1) {\n\t\t\t\tright[g] = i;\n\t\t\t} else {\n\t\t\t\tleft[g] = i;\n\t\t\t}\n\t\t}\n\t\tfather[f] = i;\n\t\tfather[i] = g;\n\t\tup(f);\n\t\tup(i);\n\t}\n\n\tpublic static void splay(int i, int goal) {\n\t\tint f = father[i], g = father[f];\n\t\twhile (f != goal) {\n\t\t\tif (g != goal) {\n\t\t\t\tif (lr(i) == lr(f)) {\n\t\t\t\t\trotate(f);\n\t\t\t\t} else {\n\t\t\t\t\trotate(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\trotate(i);\n\t\t\tf = father[i];\n\t\t\tg = father[f];\n\t\t}\n\t\tif (goal == 0) {\n\t\t\thead = i;\n\t\t}\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (reverse[i]) {\n\t\t\treverse[left[i]] = !reverse[left[i]];\n\t\t\treverse[right[i]] = !reverse[right[i]];\n\t\t\tint tmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t\treverse[i] = false;\n\t\t}\n\t}\n\n\tpublic static int find(int rank) {\n\t\tint i = head;\n\t\twhile (i != 0) {\n\t\t\tdown(i);\n\t\t\tif (size[left[i]] + 1 == rank) {\n\t\t\t\treturn i;\n\t\t\t} else if (size[left[i]] >= rank) {\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\trank -= size[left[i]] + 1;\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t\treturn 0;\n\t}\n\n\tpublic static void add(int x) {\n\t\tnum[++cnt] = x;\n\t\tsize[cnt] = 1;\n\t\tfather[cnt] = head;\n\t\tright[head] = cnt;\n\t\tsplay(cnt, 0);\n\t}\n\n\t// 注意l永远不会是最左位置，r永远不会是最右位置\n\t// 因为最左和最右位置提前加入了预备值，永远不会修改\n\tpublic static void reverse(int l, int r) {\n\t\tint i = find(l - 1);\n\t\tint j = find(r + 1);\n\t\tsplay(i, 0);\n\t\tsplay(j, i);\n\t\treverse[left[right[head]]] = !reverse[left[right[head]]];\n\t}\n\n\t// 递归方式实现二叉树中序遍历\n\t// 对本题来说，递归不会爆栈，但其实是有风险的\n\tpublic static void inorder(int i) {\n\t\tif (i != 0) {\n\t\t\tdown(i);\n\t\t\tinorder(left[i]);\n\t\t\tans[++ai] = num[i];\n\t\t\tinorder(right[i]);\n\t\t}\n\t}\n\n\t// 迭代方式实现二叉树中序遍历，防止递归爆栈\n\t// 不懂的话，看讲解018，迭代方式实现二叉树中序遍历\n\t// 遍历时候懒更新任务也要下发\n\tpublic static void inorder() {\n\t\tsi = 0;\n\t\tint i = head;\n\t\twhile (si != 0 || i != 0) {\n\t\t\tif (i != 0) {\n\t\t\t\tdown(i);\n\t\t\t\tstack[++si] = i;\n\t\t\t\ti = left[i];\n\t\t\t} else {\n\t\t\t\ti = stack[si--];\n\t\t\t\tans[++ai] = num[i];\n\t\t\t\ti = right[i];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tadd(0);\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tadd(i);\n\t\t}\n\t\tadd(0);\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\ty = (int) in.nval;\n\t\t\treverse(x + 1, y + 1);\n\t\t}\n\t\tai = 0;\n//\t\tinorder(head);\n\t\tinorder();\n\t\tfor (int i = 2; i < ai; i++) {\n\t\t\tout.print(ans[i] + " ");\n\t\t}\n\t\tout.println();\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code03_LiteraryTree2.java`\n\n```java\npackage class153;\n\n// 文艺平衡树，Splay实现范围翻转，C++版本\n// 长度为n的序列，下标从1开始，一开始序列为1, 2, ..., n\n// 接下来会有k个操作，每个操作给定l，r，表示从l到r范围上的所有数字翻转\n// 做完k次操作后，从左到右打印所有数字\n// 1 <= n, k <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3391\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//\n//using namespace std;\n//\n//const int MAXN = 100005;\n//\n//int head = 0;\n//int cnt = 0;\n//int num[MAXN];\n//int fa[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int siz[MAXN];\n//bool rev[MAXN];\n//int sta[MAXN];\n//int si;\n//int ans[MAXN];\n//int ai;\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]] + 1;\n//}\n//\n//int lr(int i) {\n//    return rs[fa[i]] == i ? 1 : 0;\n//}\n//\n//void rotate(int i) {\n//    int f = fa[i], g = fa[f], soni = lr(i), sonf = lr(f);\n//    if (soni == 1) {\n//        rs[f] = ls[i];\n//        if (rs[f] != 0) {\n//            fa[rs[f]] = f;\n//        }\n//        ls[i] = f;\n//    } else {\n//        ls[f] = rs[i];\n//        if (ls[f] != 0) {\n//            fa[ls[f]] = f;\n//        }\n//        rs[i] = f;\n//    }\n//    if (g != 0)