n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand(time(0));\n//    int n;\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        int version, op, x;\n//        cin >> version >> op >> x;\n//        if (op == 1) {\n//            add(i, head[version], x);\n//        } else if (op == 2) {\n//            remove(i, head[version], x);\n//        } else {\n//            head[i] = head[version];\n//            if (op == 3) {\n//                cout << small(head[i], x) + 1 << "\\n";\n//            } else if (op == 4) {\n//                cout << index(head[i], x) << "\\n";\n//            } else if (op == 5) {\n//                cout << pre(head[i], x) << "\\n";\n//            } else {\n//                cout << post(head[i], x) << "\\n";\n//            }\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_PersistentLiteraryTree1.java`\n\n```java\npackage class152;\n\n// 可持久化文艺平衡树，FHQ-Treap实现，java版\n// 一开始序列为空，实现如下操作，操作一共发生n次\n// v 1 x y : 基于v版本的序列，在第x个数后插入y，生成新版本的序列\n// v 2 x   : 基于v版本的序列，删除第x个数，生成新版本的序列\n// v 3 x y : 基于v版本的序列，范围[x,y]所有数字翻转，生成新版本的序列\n// v 4 x y : 基于v版本的序列，查询范围[x,y]所有数字的和，生成新版本的序列状况=v版本状况\n// 不管什么操作，都基于某个v版本，操作完成后得到新版本的序列，但v版本不会变化\n// 每种操作给定的参数都是有效的，插入数字的范围[-10^6, +10^6]\n// 1 <= n <= 2 * 10^5\n// 本题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P5055\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code06_PersistentLiteraryTree1 {\n\n\tpublic static int MAXN = 200001;\n\n\tpublic static int MAXM = MAXN * 100;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] head = new int[MAXN];\n\n\tpublic static int[] key = new int[MAXM];\n\n\tpublic static int[] left = new int[MAXM];\n\n\tpublic static int[] right = new int[MAXM];\n\n\tpublic static int[] size = new int[MAXM];\n\n\tpublic static boolean[] reverse = new boolean[MAXM];\n\n\tpublic static long[] sum = new long[MAXM];\n\n\tpublic static double[] priority = new double[MAXM];\n\n\tpublic static int copy(int i) {\n\t\tkey[++cnt] = key[i];\n\t\tleft[cnt] = left[i];\n\t\tright[cnt] = right[i];\n\t\tsize[cnt] = size[i];\n\t\treverse[cnt] = reverse[i];\n\t\tsum[cnt] = sum[i];\n\t\tpriority[cnt] = priority[i];\n\t\treturn cnt;\n\t}\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t\tsum[i] = sum[left[i]] + sum[right[i]] + key[i];\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (reverse[i]) {\n\t\t\tif (left[i] != 0) {\n\t\t\t\tleft[i] = copy(left[i]);\n\t\t\t\treverse[left[i]] = !reverse[left[i]];\n\t\t\t}\n\t\t\tif (right[i] != 0) {\n\t\t\t\tright[i] = copy(right[i]);\n\t\t\t\treverse[right[i]] = !reverse[right[i]];\n\t\t\t}\n\t\t\tint tmp = left[i];\n\t\t\tleft[i] = right[i];\n\t\t\tright[i] = tmp;\n\t\t\treverse[i] = false;\n\t\t}\n\t}\n\n\tpublic static void split(int l, int r, int i, int rank) {\n\t\tif (i == 0) {\n\t\t\tright[l] = left[r] = 0;\n\t\t} else {\n\t\t\ti = copy(i);\n\t\t\tdown(i);\n\t\t\tif (size[left[i]] + 1 <= rank) {\n\t\t\t\tright[l] = i;\n\t\t\t\tsplit(i, r, right[i], rank - size[left[i]] - 1);\n\t\t\t} else {\n\t\t\t\tleft[r] = i;\n\t\t\t\tsplit(l, i, left[i], rank);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int merge(int l, int r) {\n\t\tif (l == 0 || r == 0) {\n\t\t\treturn l + r;\n\t\t}\n\t\tif (priority[l] >= priority[r]) {\n\t\t\tl = copy(l);\n\t\t\tdown(l);\n\t\t\tright[l] = merge(right[l], r);\n\t\t\tup(l);\n\t\t\treturn l;\n\t\t} else {\n\t\t\tr = copy(r);\n\t\t\tdown(r);\n\t\t\tleft[r] = merge(l, left[r]);\n\t\t\tup(r);\n\t\t\treturn r;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tlong lastAns = 0;\n\t\tfor (int i = 1, version, op, x = 0, y = 0, l, m, lm, r; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tversion = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) ((long) in.nval ^ lastAns); // 强制在线的规则\n\t\t\tif (op != 2) {\n\t\t\t\tin.nextToken();\n\t\t\t\ty = (int) ((long) in.nval ^ lastAns); // 强制在线的规则\n\t\t\t}\n\t\t\tif (op == 1) {\n\t\t\t\tsplit(0, 0, head[version], x);\n\t\t\t\tl = right[0];\n\t\t\t\tr = left[0];\n\t\t\t\tleft[0] = right[0] = 0; // 保证0版本始终是空树\n\t\t\t\tkey[++cnt] = (int) y;\n\t\t\t\tsize[cnt] = 1;\n\t\t\t\tsum[cnt] = y;\n\t\t\t\tpriority[cnt] = Math.random();\n\t\t\t\thead[i] = merge(merge(l, cnt), r);\n\t\t\t} else if (op == 2) {\n\t\t\t\tsplit(0, 0, head[version], x);\n\t\t\t\tlm = right[0];\n\t\t\t\tr = left[0];\n\t\t\t\tsplit(0, 0, lm, x - 1);\n\t\t\t\tl = right[0];\n\t\t\t\tm = left[0];\n\t\t\t\tleft[0] = right[0] = 0; // 保证0版本始终是空树\n\t\t\t\thead[i] = merge(l, r);\n\t\t\t} else if (op == 3) {\n\t\t\t\tsplit(0, 0, head[version], y);\n\t\t\t\tlm = right[0];\n\t\t\t\tr = left[0];\n\t\t\t\tsplit(0, 0, lm, x - 1);\n\t\t\t\tl = right[0];\n\t\t\t\tm = left[0];\n\t\t\t\tleft[0] = right[0] = 0; // 保证0版本始终是空树\n\t\t\t\treverse[m] = !reverse[m];\n\t\t\t\thead[i] = merge(merge(l, m), r);\n\t\t\t} else {\n\t\t\t\tsplit(0, 0, head[version], y);\n\t\t\t\tlm = right[0];\n\t\t\t\tr = left[0];\n\t\t\t\tsplit(0, 0, lm, x - 1);\n\t\t\t\tl = right[0];\n\t\t\t\tm = left[0];\n\t\t\t\tleft[0] = right[0] = 0; // 保证0版本始终是空树\n\t\t\t\tlastAns = sum[m];\n\t\t\t\tout.println(lastAns);\n\t\t\t\thead[i] = merge(merge(l, m), r);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code06_PersistentLiteraryTree2.java`\n\n```java\npackage class152;\n\n// 可持久化文艺平衡树，FHQ-Treap实现，C++版\n// 一开始序列为空，实现如下操作，操作一共发生n次\n// v 1 x y : 基于v版本的序列，在第x个数后插入y，生成新版本的序列\n// v 2 x   : 基于v版本的序列，删除第x个数，生成新版本的序列\n// v 3 x y : 基于v版本的序列，范围[x,y]所有数字翻转，生成新版本的序列\n// v 4 x y : 基于v版本的序列，查询范围[x,y]所有数字的和，生成新版本的序列状况=v版本状况\n// 不管什么操作，都基于某个v版本，操作完成后得到新版本的序列，但v版本不会变化\n// 每种操作给定的参数都是有效的，插入数字的范围[-10^6, +10^6]\n// 1 <= n <= 2 * 10^5\n// 本题目要求强制在线，具体规则可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P5055\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <vector>\n//#include <cstdlib>\n//#include <ctime>\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXM = MAXN * 100;\n//\n//int cnt = 0;\n//int head[MAXN];\n//int key[MAXM];\n//int ls[MAXM];\n//int rs[MAXM];\n//int siz[MAXM];\n//bool rev[MAXM];\n//long long sum[MAXM];\n//double priority[MAXM];\n//\n//int copy(int i) {\n//    key[++cnt] = key[i];\n//    ls[cnt] = ls[i];\n//    rs[cnt] = rs[i];\n//    siz[cnt] = siz[i];\n//    rev[cnt] = rev[i];\n//    sum[cnt] = sum[i];\n//    priority[cnt] = priority[i];\n//    return cnt;\n//}\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]] + 1;\n//    sum[i] = sum[ls[i]] + sum[rs[i]] + key[i];\n//}\n//\n//void down(int i) {\n//    if (rev[i]) {\n//        if (ls[i] != 0) {\n//            ls[i] = copy(ls[i]);\n//            rev[ls[i]] ^= 1;\n//        }\n//        if (rs[i] != 0) {\n//            rs[i] = copy(rs[i]);\n//            rev[rs[i]] ^= 1;\n//        }\n//        swap(ls[i], rs[i]);\n//        rev[i] = false;\n//    }\n//}\n//\n//void split(int l, int r, int i, int rank) {\n//    if (i == 0) {\n//        rs[l] = ls[r] = 0;\n//    } else {\n//        i = copy(i);\n//        down(i);\n//        if (siz[ls[i]] + 1 <= rank) {\n//            rs[l] = i;\n//            split(i, r, rs[i], rank - siz[ls[i]] - 1);\n//        } else {\n//            ls[r] = i;\n//            split(l, i, ls[i], rank);\n//        }\n//        up(i);\n//    }\n//}\n//\n//int merge(int l, int r) {\n//    if (l == 0 || r == 0) {\n//        return l + r;\n//    }\n//    if (priority[l] >= priority[r]) {\n//        l = copy(l);\n//        down(l);\n//        rs[l] = merge(rs[l], r);\n//        up(l);\n//        return l;\n//    } else {\n//        r = copy(r);\n//        down(r);\n//        ls[r] = merge(l, ls[r]);\n//        up(r);\n//        return r;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    srand(time(0));\n//    int n;\n//    cin >> n;\n//    long long lastAns = 0;\n//    for (int i = 1; i <= n; i++) {\n//        int version, op;\n//        long long x, y = 0;\n//        cin >> version >> op >> x;\n//        x ^= lastAns;\n//        if (op != 2) {\n//            cin >> y;\n//            y ^= lastAns;\n//        }\n//        int l, m, lm, r;\n//        if (op == 1) {\n//            split(0, 0, head[version], x);\n//            l = rs[0];\n//            r = ls[0];\n//            ls[0] = rs[0] = 0;\n//            key[++cnt] = y;\n//            siz[cnt] = 1;\n//            sum[cnt] = y;\n//            priority[cnt] = (double)rand() / RAND_MAX;\n//            head[i] = merge(merge(l, cnt), r);\n//        } else if (op == 2) {\n//            split(0, 0, head[version], x);\n//            lm = rs[0];\n//            r = ls[0];\n//            split(0, 0, lm, x - 1);\n//            l = rs[0];\n//            m = ls[0];\n//            ls[0] = rs[0] = 0;\n//            head[i] = merge(l, r);\n//        } else if (op == 3) {\n//            split(0, 0, head[version], y);\n//            lm = rs[0];\n//            r = ls[0];\n//            split(0, 0, lm, x - 1);\n//            l = rs[0];\n//            m = ls[0];\n//            ls[0] = rs[0] = 0;\n//            rev[m] ^= 1;\n//            head[i] = merge(merge(l, m), r);\n//        } else {\n//            split(0, 0, head[version], y);\n//            lm = rs[0];\n//            r = ls[0];\n//            split(0, 0, lm, x - 1);\n//            l = rs[0];\n//            m = ls[0];\n//            ls[0] = rs[0] = 0;\n//            lastAns = sum[m];\n//            cout << lastAns << endl;\n//            head[i] = merge(merge(l, m), r);\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `FollowUp1.java`\n\n```java\npackage class152;\n\n// FHQ-Treap实现普通有序表，不用词频压缩，数据加强的测试，java版\n// 这个文件课上没有讲，测试数据加强了，而且有强制在线的要求\n// 基本功能要求都是不变的，可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P6136\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class FollowUp1 {\n\n\tpublic static int MAXN = 2000001;\n\n\tpublic static int head = 0;\n\n\tpublic static int cnt = 0;\n\n\tpublic static int[] key = new int[MAXN];\n\n\tpublic static int[] left = new int[MAXN];\n\n\tpublic static int[] right = new int[MAXN];\n\n\tpublic static int[] size = new int[MAXN];\n\n\tpublic static double[] priority = new double[MAXN];\n\n\tpublic static void up(int i) {\n\t\tsize[i] = size[left[i]] + size[right[i]] + 1;\n\t}\n\n\tpublic static void split(int l, int r, int i, int num) {\n\t\tif (i == 0) {\n\t\t\tright[l] = left[r] = 0;\n\t\t} else {\n\t\t\tif (key[i] <= num) {\n\t\t\t\tright[l] = i;\n\t\t\t\tsplit(i, r, right[i], num);\n\t\t\t} else {\n\t\t\t\tleft[r] = i;\n\t\t\t\tsplit(l, i, left[i], num);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int merge(int l, int r) {\n\t\tif (l == 0 || r == 0) {\n\t\t\treturn l + r;\n\t\t}\n\t\tif (priority[l] >= priority[r]) {\n\t\t\tright[l] = merge(right[l], r);\n\t\t\tup(l);\n\t\t\treturn l;\n\t\t} else {\n\t\t\tleft[r] = merge(l, left[r]);\n\t\t\tup(r);\n\t\t\treturn r;\n\t\t}\n\t}\n\n\tpublic static void add(int num) {\n\t\tsplit(0, 0, head, num);\n\t\tkey[++cnt] = num;\n\t\tsize[cnt] = 1;\n\t\tpriority[cnt] = Math.random();\n\t\thead = merge(merge(right[0], cnt), left[0]);\n\t}\n\n\tpublic static void remove(int num) {\n\t\tsplit(0, 0, head, num);\n\t\tint lm = right[0];\n\t\tint r = left[0];\n\t\tsplit(0, 0, lm, num - 1);\n\t\tint l = right[0];\n\t\tint m = left[0];\n\t\thead = merge(merge(l, merge(left[m], right[m])), r);\n\t}\n\n\tpublic static int rank(int num) {\n\t\tsplit(0, 0, head, num - 1);\n\t\tint ans = size[right[0]] + 1;\n\t\thead = merge(right[0], left[0]);\n\t\treturn ans;\n\t}\n\n\tpublic static int index(int i, int x) {\n\t\tif (size[left[i]] >= x) {\n\t\t\treturn index(left[i], x);\n\t\t} else if (size[left[i]] + 1 < x) {\n\t\t\treturn index(right[i], x - size[left[i]] - 1);\n\t\t} else {\n\t\t\treturn key[i];\n\t\t}\n\t}\n\n\tpublic static int index(int x) {\n\t\treturn index(head, x);\n\t}\n\n\tpublic static int pre(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MIN_VALUE;\n\t\t}\n\t\tif (key[i] >= num) {\n\t\t\treturn pre(left[i], num);\n\t\t} else {\n\t\t\treturn Math.max(key[i], pre(right[i], num));\n\t\t}\n\t}\n\n\tpublic static int pre(int num) {\n\t\treturn pre(head, num);\n\t}\n\n\tpublic static int post(int i, int num) {\n\t\tif (i == 0) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t}\n\t\tif (key[i] <= num) {\n\t\t\treturn post(right[i], num);\n\t\t} else {\n\t\t\treturn Math.min(key[i], post(left[i], num));\n\t\t}\n\t}\n\n\tpublic static int post(int num) {\n\t\treturn post(head, num);\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tint n = (int) in.nval;\n\t\tin.nextToken();\n\t\tint m = (int) in.nval;\n\t\tfor (int i = 1, num; i <= n; i++) {\n\t\t\tin.nextToken();\n\t\t\tnum = (int) in.nval;\n\t\t\tadd(num);\n\t\t}\n\t\tint lastAns = 0;\n\t\tint ans = 0;\n\t\tfor (int i = 1, op, x; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\top = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tx = (int) in.nval ^ lastAns;\n\t\t\tif (op == 1) {\n\t\t\t\tadd(x);\n\t\t\t} else if (op == 2) {\n\t\t\t\tremove(x);\n\t\t\t} else if (op == 3) {\n\t\t\t\tlastAns = rank(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 4) {\n\t\t\t\tlastAns = index(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else if (op == 5) {\n\t\t\t\tlastAns = pre(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t} else {\n\t\t\t\tlastAns = post(x);\n\t\t\t\tans ^= lastAns;\n\t\t\t}\n\t\t}\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `FollowUp2.java`\n\n```java\npackage class152;\n\n// FHQ-Treap实现普通有序表，不用词频压缩，数据加强的测试，C++版\n// 这个文件课上没有讲，测试数据加强了，而且有强制在线的要求\n// 基本功能要求都是不变的，可以打开测试链接查看\n// 测试链接 : https://www.luogu.com.cn/problem/P6136\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <cstdio>\n//#include <cstdlib>\n//#include <cstring>\n//#include <algorithm>\n//#include <climits>\n//using namespace std;\n//\n//const int MAXN = 2000001;\n//int head = 0;\n//int cnt = 0;\n//int key[MAXN];\n//int ls[MAXN];\n//int rs[MAXN];\n//int siz[MAXN];\n//double priority[MAXN];\n//\n//void up(int i) {\n//    siz[i] = siz[ls[i]] + siz[rs[i]] + 1;\n//}\n//\n//void split(int l, int r, int i, int num) {\n//    if (i == 0) {\n//        rs[l] = ls[r] = 0;\n//    } else {\n//        if (key[i] <= num) {\n//            rs[l] = i;\n//            split(i, r, rs[i], num);\n//        } else {\n//            ls[r] = i;\n//            split(l, i, ls[i], num);\n//        }\n//        up(i);\n//    }\n//}\n//\n//int merge(int l, int r) {\n//    if (l == 0 || r == 0) {\n//        return l + r;\n//    }\n//    if (priority[l] >= priority[r]) {\n//        rs[l] = merge(rs[l], r);\n//        up(l);\n//        return l;\n//    } else {\n//        ls[r] = merge(l, ls[r]);\n//        up(r);\n//        return r;\n//    }\n//}\n//\n//void add(int num) {\n//    split(0, 0, head, num);\n//    key[++cnt] = num;\n//    siz[cnt] = 1;\n//    priority[cnt] = (double)rand() / RAND_MAX;\n//    head = merge(merge(rs[0], cnt), ls[0]);\n//}\n//\n//void remove(int num) {\n//    split(0, 0, head, num);\n//    int lm = rs[