   }\n//}\n//\n//void clear() {\n//    for (int i = 1; i <= cntt; i++) {\n//        head[i] = dfn[i] = belong[i] = 0;\n//    }\n//    cntt = cntg = cntd = top = sccCnt = 0;\n//}\n//\n//bool check(int d) {\n//    buildGraph(d);\n//    for (int i = 1; i <= (n << 1); i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == belong[i + n]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    clear();\n//    return check;\n//}\n//\n//int compute() {\n//    for (int i = 1; i <= n; i++) {\n//        arr[i].pos = a[i];\n//        arr[i].xid = i;\n//        arr[i + n].pos = b[i];\n//        arr[i + n].xid = i + n;\n//    }\n//    k = n << 1;\n//    sort(arr + 1, arr + k + 1, NodeCmp);\n//    int l = 0, r = arr[k].pos, d, ans = 0;\n//    while (l <= r) {\n//        d = (l + r) >> 1;\n//        if (check(d)) {\n//            ans = d;\n//            l = d + 1;\n//        } else {\n//            r = d - 1;\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> a[i] >> b[i];\n//    }\n//    int ans = compute();\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code03_BinaryCode1.java`\n\n```java\npackage class197;\n\n// 编码，java版\n// 一共有n个字符串，都由字符 '0'、'1'、'?' 组成\n// 每个字符串最多含有一个'?'，如果不含有，说明该字符串已经确定了\n// 如果字符串含有'?'，那么这个'?'必须变成'0'或'1'中的一个\n// 请把所有字符串都确定下来，要求任意一个字符串不是其它字符串的前缀\n// 存在方案打印"YES"，然后打印每个确定后的字符串，不存在方案打印"NO"\n// 1 <= n、字符总数 <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6965\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_BinaryCode1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXP = 1000002;\n\tpublic static int MAXT = 5000001;\n\tpublic static int MAXE = 10000001;\n\tpublic static int n, cntt;\n\n\t// 每个字符串，有两个决定，所以得到两个决定串\n\tpublic static String[] arr = new String[MAXN << 1];\n\n\t// 2-SAT建图\n\tpublic static int[] headg = new int[MAXT];\n\tpublic static int[] nextg = new int[MAXE];\n\tpublic static int[] tog = new int[MAXE];\n\tpublic static int cntg;\n\n\t// 前缀树优化建图\n\tpublic static int[][] tree = new int[MAXP][2];\n\tpublic static int[] fa = new int[MAXP];\n\tpublic static int[] up = new int[MAXP];\n\tpublic static int[] down = new int[MAXP];\n\tpublic static int cntp;\n\n\t// 前缀树的节点x，拥有哪些决定串，用链式前向星实现\n\tpublic static int[] headx = new int[MAXP];\n\tpublic static int[] nextx = new int[MAXP];\n\tpublic static int[] tox = new int[MAXP];\n\tpublic static int cntx;\n\n\t// 相同的决定串构成一组，进行前后缀优化建图\n\tpublic static int[] group = new int[MAXN];\n\tpublic static int gsiz;\n\n\tpublic static int[] dfn = new int[MAXT];\n\tpublic static int[] low = new int[MAXT];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXT];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXT];\n\tpublic static int sccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXT];\n\tpublic static int[] stas = new int[MAXT];\n\tpublic static int[] stae = new int[MAXT];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnextg[++cntg] = headg[u];\n\t\ttog[cntg] = v;\n\t\theadg[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = headg[u]; e > 0; e = nextg[e]) {\n\t\t\tint v = tog[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = headg[u];\n\t\t\t} else {\n\t\t\t\tv = tog[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nextg[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = tog[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static void addGroup(int u, int x) {\n\t\tnextx[++cntx] = headx[u];\n\t\ttox[cntx] = x;\n\t\theadx[u] = cntx;\n\t}\n\n\tpublic static void insert(int x) {\n\t\tString str = arr[x];\n\t\tint cur = 1;\n\t\tfor (int si = 0; si < str.length(); si++) {\n\t\t\tint path = str.charAt(si) == '0' ? 0 : 1;\n\t\t\tif (tree[cur][path] == 0) {\n\t\t\t\ttree[cur][path] = ++cntp;\n\t\t\t\tfa[cntp] = cur;\n\t\t\t\tup[cntp] = ++cntt;\n\t\t\t\tdown[cntp] = ++cntt;\n\t\t\t\taddEdge(up[cntp], up[cur]);\n\t\t\t\taddEdge(down[cur], down[cntp]);\n\t\t\t}\n\t\t\tcur = tree[cur][path];\n\t\t}\n\t\taddEdge(x, up[fa[cur]]);\n\t\taddEdge(up[cur], other(x));\n\t\taddEdge(x, down[cur]);\n\t\taddEdge(down[fa[cur]], other(x));\n\t\taddGroup(cur, x);\n\t}\n\n\tpublic static void groupLink() {\n\t\tif (gsiz > 1) {\n\t\t\tcntt++;\n\t\t\taddEdge(cntt, other(group[1]));\n\t\t\tfor (int i = 2; i <= gsiz; i++) {\n\t\t\t\tcntt++;\n\t\t\t\taddEdge(cntt, other(group[i]));\n\t\t\t\taddEdge(group[i], cntt - 1);\n\t\t\t\taddEdge(cntt, cntt - 1);\n\t\t\t}\n\t\t\tcntt++;\n\t\t\taddEdge(cntt, other(group[gsiz]));\n\t\t\tfor (int i = gsiz - 1; i >= 1; i--) {\n\t\t\t\tcntt++;\n\t\t\t\taddEdge(cntt, other(group[i]));\n\t\t\t\taddEdge(group[i], cntt - 1);\n\t\t\t\taddEdge(cntt, cntt - 1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void buildGraph() {\n\t\tcntt = n << 1;\n\t\tcntp = 1;\n\t\tup[1] = ++cntt;\n\t\tdown[1] = ++cntt;\n\t\tfor (int x = 1; x <= n << 1; x++) {\n\t\t\tinsert(x);\n\t\t}\n\t\tfor (int u = 1; u <= cntp; u++) {\n\t\t\tgsiz = 0;\n\t\t\tfor (int e = headx[u]; e > 0; e = nextx[e]) {\n\t\t\t\tgroup[++gsiz] = tox[e];\n\t\t\t}\n\t\t\tgroupLink();\n\t\t}\n\t}\n\n\tpublic static void addString(int i, String s) {\n\t\tint mark = -1;\n\t\tchar[] str = s.toCharArray();\n\t\tfor (int si = 0; si < str.length; si++) {\n\t\t\tif (str[si] == '?') {\n\t\t\t\tmark = si;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (mark == -1) {\n\t\t\tif (str[0] == '0') {\n\t\t\t\taddEdge(i + n, i);\n\t\t\t} else {\n\t\t\t\taddEdge(i, i + n);\n\t\t\t}\n\t\t\tmark = 0;\n\t\t}\n\t\tstr[mark] = '0';\n\t\tarr[i] = String.valueOf(str);\n\t\tstr[mark] = '1';\n\t\tarr[i + n] = String.valueOf(str);\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tString s;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\ts = in.nextString();\n\t\t\taddString(i, s);\n\t\t}\n\t\tbuildGraph();\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i);\n\t\t\t\ttarjan2(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\tcheck = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (check) {\n\t\t\tout.println("YES");\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (belong[i] < belong[i + n]) {\n\t\t\t\t\tout.println(arr[i]);\n\t\t\t\t} else {\n\t\t\t\t\tout.println(arr[i + n]);\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tout.println("NO");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tString nextString() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tif (c == -1) {\n\t\t\t\treturn null;\n\t\t\t}\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_BinaryCode2.java`\n\n```java\npackage class197;\n\n// 编码，C++版\n// 一共有n个字符串，都由字符 '0'、'1'、'?' 组成\n// 每个字符串最多含有一个'?'，如果不含有，说明该字符串已经确定了\n// 如果字符串含有'?'，那么这个'?'必须变成'0'或'1'中的一个\n// 请把所有字符串都确定下来，要求任意一个字符串不是其它字符串的前缀\n// 存在方案打印"YES"，然后打印每个确定后的字符串，不存在方案打印"NO"\n// 1 <= n、字符总数 <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P6965\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXP = 1000002;\n//const int MAXT = 5000001;\n//const int MAXE = 10000001;\n//int n, cntt;\n//\n//string arr[MAXN << 1];\n//\n//int headg[MAXT];\n//int nextg[MAXE];\n//int tog[MAXE];\n//int cntg;\n//\n//int tree[MAXP][2];\n//int fa[MAXP];\n//int up[MAXP];\n//int down[MAXP];\n//int cntp;\n//\n//int headx[MAXP];\n//int nextx[MAXP];\n//int tox[MAXP];\n//int cntx;\n//\n//int group[MAXN];\n//int gsiz;\n//\n//int dfn[MAXT];\n//int low[MAXT];\n//int cntd;\n//\n//int sta[MAXT];\n//int top;\n//\n//int belong[MAXT];\n//int sccCnt;\n//\n//void addEdge(int u, int v) {\n//    nextg[++cntg] = headg[u];\n//    tog[cntg] = v;\n//    headg[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = headg[u]; e > 0; e = nextg[e]) {\n//        int v = tog[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int other(int x) {\n//    return x <= n ? x + n : x - n;\n//}\n//\n//void addGroup(int u, int x) {\n//    nextx[++cntx] = headx[u];\n//    tox[cntx] = x;\n//    headx[u] = cntx;\n//}\n//\n//void insert(int x) {\n//    string str = arr[x];\n//    int cur = 1;\n//    for (int si = 0; si < (int)str.length(); si++) {\n//        int path = str[si] == '0' ? 0 : 1;\n//        if (tree[cur][path] == 0) {\n//            tree[cur][path] = ++cntp;\n//            fa[cntp] = cur;\n//            up[cntp] = ++cntt;\n//            down[cntp] = ++cntt;\n//            addEdge(up[cntp], up[cur]);\n//            addEdge(down[cur], down[cntp]);\n//        }\n//        cur = tree[cur][path];\n//    }\n//    addEdge(x, up[fa[cur]]);\n//    addEdge(up[cur], other(x));\n//    addEdge(x, down[cur]);\n//    addEdge(down[fa[cur]], other(x));\n//    addGroup(cur, x);\n//}\n//\n//void groupLink() {\n//    if (gsiz > 1) {\n//        cntt++;\n//        addEdge(cntt, other(group[1]));\n//        for (int i = 2; i <= gsiz; i++) {\n//            cntt++;\n//            addEdge(cntt, other(group[i]));\n//            addEdge(group[i], cntt - 1);\n//            addEdge(cntt, cntt - 1);\n//        }\n//        cntt++;\n//        addEdge(cntt, other(group[gsiz]));\n//        for (int i = gsiz - 1; i >= 1; i--) {\n//            cntt++;\n//            addEdge(cntt, other(group[i]));\n//            addEdge(group[i], cntt - 1);\n//            addEdge(cntt, cntt - 1);\n//        }\n//    }\n//}\n//\n//void buildGraph() {\n//    cntt = n << 1;\n//    cntp = 1;\n//    up[1] = ++cntt;\n//    down[1] = ++cntt;\n//    for (int x = 1; x <= (n << 1); x++) {\n//        insert(x);\n//    }\n//    for (int u = 1; u <= cntp; u++) {\n//        gsiz = 0;\n//        for (int e = headx[u]; e > 0; e = nextx[e]) {\n//            group[++gsiz] = tox[e];\n//        }\n//        groupLink();\n//    }\n//}\n//\n//void addString(int i, string s) {\n//    int mark = -1;\n//    for (int si = 0; si < (int)s.length(); si++) {\n//        if (s[si] == '?') {\n//            mark = si;\n//            break;\n//        }\n//    }\n//    if (mark == -1) {\n//        if (s[0] == '0') {\n//            addEdge(i + n, i);\n//        } else {\n//            addEdge(i, i + n);\n//        }\n//        mark = 0;\n//    }\n//    s[mark] = '0';\n//    arr[i] = s;\n//    s[mark] = '1';\n//    arr[i + n] = s;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    string s;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> s;\n//        addString(i, s);\n//    }\n//    buildGraph();\n//    for (int i = 1; i <= (n << 1); i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == belong[i + n]) {\n//            check = false;\n//            break;\n//        }\n//    }\n//    if (check) {\n//        cout << "YES" << "\\n";\n//        for (int i = 1; i <= n; i++) {\n//            if (belong[i] < belong[i + n]) {\n//                cout << arr[i] << "\\n";\n//            } else {\n//                cout << arr[i + n] << "\\n";\n//            }\n//        }\n//    } else {\n//        cout << "NO" << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_Game1.java`\n\n```java\npackage class197;\n\n// 游戏，java版\n// 地面有x、a、b、c四种类型，赛车有A、B、C三辆\n// 类型a不能跑车A，类型b不能跑车B、类型c不能跑车C，类型x没有限制\n// 一共有n个地点，给定每个地点的地面类型，其中x类型的地面有d个\n// 一共有m个限制，格式 pos1 car1 pos2 car2，含义如下\n// 如果pos1号地点使用car1赛车，那么pos2号地点一定要使用car2赛车\n// 每辆赛车可以使用无限次，需要满足以上的规则和限制来安排比赛\n// 如果有方案，找到任意一种方案，打印每个地点用什么车，无方案打印-1\n// 1 <= n <= 5 * 10^4    1 <= m <= 10^5    0 <= d <= 8\n// 测试链接 : https://www.luogu.com.cn/problem/P3825\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_Game1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int n, d, m;\n\n\tpublic static char[] ban = new char[128];\n\tpublic static char[] first = new char[128];\n\tpublic static char[] second = new char[128];\n\n\tpublic static char[] groundType = new char[MAXN];\n\tpublic static int[] pos1 = new int[MAXN];\n\tpublic static char[] car1 = new char[MAXN];\n\tpublic static int[] pos2 = new int[MAXN];\n\tpublic static char[] car2 = new char[MAXN];\n\n\tpublic static int[] posx = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXN];\n\tpublic static int[] to = new int[MAXN];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static char[] ans = new char[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstau[stacksize] = u;\n\t\tstas[stacksize] = status;\n\t\tstae[stacksize] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stau[stacksize];\n\t\tstatus = stas[stacksize];\n\t\te = stae[stacksize];\n\t}\n\n\tpublic static void prepare() {\n\t\tban['a'] = 'A';\n\t\tban['b'] = 'B';\n\t\tban['c'] = 'C';\n\t\tfirst['a'] = 'B';\n\t\tfirst['b'] = 'A';\n\t\tfirst['c'] = 'A';\n\t\tsecond['a'] = 'C';\n\t\tsecond['b'] = 'C';\n\t\tsecond['c'] = 'B';\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int other(int i) {\n\t\treturn i <= n ? i + n : i - n;\n\t}\n\n\tpublic static void buildGraph(int stax) {\n\t\tfor (int bit = 0, idx = 1; bit < d; bit++, idx++) {\n\t\t\tif ((stax >> bit & 1) == 1) {\n\t\t\t\tgroundType[posx[idx]] = 'a';\n\t\t\t} else {\n\t\t\t\tgroundType[posx[idx]] = 'b';\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint p1 = pos1[i];\n\t\t\tchar g1 = groundType[p1];\n\t\t\tchar c1 = car1[i];\n\t\t\tif (ban[g1] == c1) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint id1 = c1 == first[g1] ? p1 : p1 + n;\n\t\t\tint p2 = pos2[i];\n\t\t\tchar g2 = groundType[p2];\n\t\t\tchar c2 = car2[i];\n\t\t\tif (ban[g2] == c2) {\n\t\t\t\taddEdge(id1, other(id1));\n\t\t\t} else {\n\t\t\t\tint id2 = c2 == first[g2] ? p2 : p2 + n;\n\t\t\t\taddEdge(id1, id2);\n\t\t\t\taddEdge(other(id2), other(id1));\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void clear() {\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\thead[i] = dfn[i] = belong[i] = 0;\n\t\t}\n\t\tcntg = cntd = top = sccCnt = 0;\n\t}\n\n\tpublic static boolean compute() {\n\t\tfor (int i = 1, sizx = 0; i <= n; i++) {\n\t\t\tif (groundType[i] == 'x') {\n\t\t\t\tposx[++sizx] = i;\n\t\t\t}\n\t\t}\n\t\tfor (int stax = 0; stax < 1 << d; stax++) {\n\t\t\tbuildGraph(stax);\n\t\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\tif (head[i] == 0) {\n\t\t\t\t\t\t// 孤立点直接分配强联通分量\n\t\t\t\t\t\t// 优化一下常数，java需要，c++不需要\n\t\t\t\t\t\tdfn[i] = low[i] = ++cntd;\n\t\t\t\t\t\tbelong[i] = ++sccCnt;\n\t\t\t\t\t} else {\n\t\t\t\t\t\t// tarjan1(i);\n\t\t\t\t\t\ttarjan2(i);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tboolean check = true;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (belong[i] == belong[i + n]) {\n\t\t\t\t\tcheck = false;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (check) {\n\t\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\t\tchar ground = groundType[i];\n\t\t\t\t\tif (belong[i] < belong[i + n]) {\n\t\t\t\t\t\tans[i] = first[ground];\n\t\t\t\t\t} else {\n\t\t\t\t\t\tans[i] = second[ground];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\treturn true;\n\t\t\t}\n\t\t\tclear();\n\t\t}\n\t\treturn false;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tprepare();\n\t\tn = in.nextInt();\n\t\td = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tgroundType[i] = in.nextChar();\n\t\t}\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tpos1[i] = in.nextInt();\n\t\t\tcar1[i] = in.nextChar();\n\t\t\tpos2[i] = in.nextInt();\n\t\t\tcar2[i] = in.nextChar();\n\t\t}\n\t\tboolean check = compute();\n\t\tif (check) {\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tout.print(ans[i]);\n\t\t\t}\n\t\t} else {\n\t\t\tout.println(-1);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tchar nextChar() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn 0;\n\t\t\t} while (!(c > ' ' && c != -1));\n\t\t\treturn (char) c;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_Game2.java`\n\n```java\npackage class197;\n\n// 游戏，C++版\n// 地面有x、a、b、c四种类型，赛车有A、B、C三辆\n// 类型a不能跑车A，类型b不能跑车B、类型c不能跑车C，类型x没有限制\n// 一共有n个地点，给定每个地点的地面类型，其中x类型的地面有d个\n// 一共有m个限制，格式 pos1 car1 pos2 car2，含义如下\n// 如果pos1号地点使用car1赛车，那么pos2号地点一定要使用car2赛车\n// 每辆赛车可以使用无限次，需要满足以上的规则和限制来安排比赛\n// 如果有方案，找到任意一种方案，打印每个地点用什么车，无方案打印-1\n// 1 <= n <= 5 * 10^4    1 <= m <= 10^5    0 <= d <= 8\n// 测试链接 : https://www.luogu.com.cn/problem/P3825\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//int n, d, m;\n//\n//char ban[128];\n//char first[128];\n//char second[128];\n//\n//char groundType[MAXN];\n//int pos1[MAXN];\n//char car1[MAXN];\n//int pos2[MAXN];\n//char car2[MAXN];\n//\n//int posx[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN];\n//int to[MAXN];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sccCnt;\n//\n//char ans[MAXN];\n//\n//void prepare() {\n//    ban['a'] = 'A';\n//    ban['b'] = 'B';\n//    ban['c'] = 'C';\n//    first['a'] = 'B';\n//    first['b'] = 'A';\n//    first['c'] = 'A';\n//    second['a'] = 'C';\n//    second['b'] = 'C';\n//    second['c'] = 'B';\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int other(int i) {\n//    return i <= n ? i + n : i - n;\n//}\n//\n//void buildGraph(int stax) {\n//    for (int bit = 0, idx = 1; bit < d; bit++, idx++) {\n//        if (((stax >> bit) & 1) == 1) {\n//            groundType[posx[idx]] = 'a';\n//        } else {\n//            groundType[posx[idx]] = 'b';\n//        }\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        int p1 = pos1[i];\n//        char g1 = groundType[p1];\n//        char c1 = car1[i];\n//        if (ban[g1] == c1) {\n//            continue;\n//        }\n//        int id1 = c1 == first[g1] ? p1 : p1 + n;\n//        int p2 = pos2[i];\n//        char g2 = groundType[p2];\n//        char c2 = car2[i];\n//        if (ban[g2] == c2) {\n//            addEdge(id1, other(id1));\n//        } else {\n//            int id2 = c2 == first[g2] ? p2 : p2 + n;\n//            addEdge(id1, id2);\n//            addEdge(other(id2), other(id1));\n//        }\n//    }\n//}\n//\n//void clear() {\n//    for (int i = 1; i <= n << 1; i++) {\n//        head[i] = dfn[i] = belong[i] = 0;\n//    }\n//    cntg = cntd = top = sccCnt = 0;\n//}\n//\n//bool compute() {\n//    for (int i = 1, sizx = 0; i <= n; i++) {\n//        if (groundType[i] == 'x') {\n//            posx[++sizx] = i;\n//        }\n//    }\n//    for (int stax = 0; stax < 1 << d; stax++) {\n//        buildGraph(stax);\n//        for (int i = 1; i <= n << 1; i++) {\n//            if (dfn[i] == 0) {\n//                tarjan(i);\n//            }\n//        }\n//        bool check = true;\n//        for (int i = 1; i <= n; i++) {\n//            if (belong[i] == belong[i + n]) {\n//                check = false;\n//                break;\n//            }\n//        }\n//        if (check) {\n//            for (int i = 1; i <= n; i++) {\n//                char ground = groundType[i];\n//                if (belong[i] < belong[i + n]) {\n//                    ans[i] = first[ground];\n//                } else {\n//                    ans[i] = second[ground];\n//                }\n//            }\n//            return true;\n//        }\n//        clear();\n//    }\n//    return false;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    prepare();\n//    cin >> n >> d;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> groundType[i];\n//    }\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> pos1[i] >> car1[i] >> pos2[i] >> car2[i];\n//    }\n//    bool check = compute();\n//    if (check) {\n//        for (int i = 1; i <= n; i++) {\n//            cout << ans[i];\n//        }\n//    } else {\n//        cout << -1 << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Boolean1.java`\n\n```java\npackage class197;\n\n// 布尔，java版\n// 一共n个变量，取值为0或1，一共m条限制，格式 u x v y，含义如下\n// 如果u的取值为x，则v的取值为y，同时如果v的取值为y，则u的取值为x\n// 限制的编号范围1~m，限制区间[a, b]如果满足如下条件，就认为是合法的\n// 区间[a, b]内的所有限制，存在一种变量赋值方案，能让它们全部成立\n// 一共有q条查询，格式 l r，含义如下\n// 整个限制区间[l, r]，最少划分成多少段连续区间，使得每个连续区间都合法\n// 打印划分的连续区间数量，如果怎么划分都做不到上述要求，打印-1\n// 1 <= n <= 10^5\n// 1 <= m <= 6 * 10^5\n// 1 <= q <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P7843\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_Boolean1 {\n\n\tpublic static int MAXN = 200001;\n\tpublic static int MAXM = 600001;\n\tpublic static int MAXQ = 1000001;\n\tpublic static int MAXP = 20;\n\tpublic static int n, m, q;\n\n\t// 错误计数\n\tpublic static int[] error = new int[MAXM];\n\n\t// 决定编号\n\tpublic static int[] u = new int[MAXM];\n\tpublic static int[] v = new int[MAXM];\n\n\t// 可撤销并查集\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[][] rollback = new int[MAXN][2];\n\tpublic static int opsize;\n\n\t// first[i] = 从i位置开始，向右不停添加限制，首次违规的位置\n\tpublic static int[] first = new int[MAXM];\n\n\t// st[i][p] = 从i位置开始，允许拆成2的p次个连续区间，每个都合法，往右能到什么位置\n\tpublic static int[][] st = new int[MAXM + 1][MAXP];\n\n\tpublic static int find(int i) {\n\t\twhile (i != fa[i]) {\n\t\t\ti = fa[i];\n\t\t}\n\t\treturn i;\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tint fx = find(x);\n\t\tint fy = find(y);\n\t\tif (fx != fy) {\n\t\t\tif (siz[fx] < siz[fy]) {\n\t\t\t\tint tmp = fx;\n\t\t\t\tfx = fy;\n\t\t\t\tfy = tmp;\n\t\t\t}\n\t\t\tfa[fy] = fx;\n\t\t\tsiz[fx] += siz[fy];\n\t\t\trollback[++opsize][0] = fx;\n\t\t\trollback[opsize][1] = fy;\n\t\t}\n\t}\n\n\tpublic static void undo(int oldsiz) {\n\t\twhile (opsize > oldsiz) {\n\t\t\tint fx = rollback[opsize][0];\n\t\t\tint fy = rollback[opsize--][1];\n\t\t\tfa[fy] = fy;\n\t\t\tsiz[fx] -= siz[fy];\n\t\t}\n\t}\n\n\tpublic static int other(int x) {\n\t\treturn x <= n ? x + n : x - n;\n\t}\n\n\tpublic static boolean conflict(int x) {\n\t\treturn find(x) == find(other(x));\n\t}\n\n\t// 整体二分，计算每个位置i的first[i]信息\n\tpublic static void compute(int ql, int qr, int vl, int vr) {\n\t\tif (ql > qr) {\n\t\t\treturn;\n\t\t}\n\t\tif (vl == vr) {\n\t\t\tfor (int i = ql; i <= qr; i++) {\n\t\t\t\tfirst[i] = vl;\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\tint mid = (vl + vr) >> 1;\n\t\tint backup1 = opsize;\n\t\tboolean bad = false;\n\t\tfor (int i = Math.max(qr + 1, vl); i <= mid; i++) {\n\t\t\tunion(u[i], v[i]);\n\t\t\tunion(other(u[i]), other(v[i]));\n\t\t\tif (conflict(u[i])) {\n\t\t\t\tbad = true;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (bad) {\n\t\t\tundo(backup1);\n\t\t\tcompute(ql, qr, vl, mid);\n\t\t} else {\n\t\t\tint backup2 = opsize;\n\t\t\tint split = Math.min(qr, mid);\n\t\t\tfor (; split >= ql; split--) {\n\t\t\t\tunion(u[split], v[split]);\n\t\t\t\tunion(other(u[split]), other(v[split]));\n\t\t\t\tif (conflict(u[split])) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tundo(backup2);\n\t\t\tcompute(split + 1, qr, mid + 1, vr);\n\t\t\tundo(backup1);\n\t\t\tfor (int i = split + 1; i <= qr && i < vl; i++) {\n\t\t\t\tunion(u[i], v[i]);\n\t\t\t\tunion(other(u[i]), other(v[i]));\n\t\t\t}\n\t\t\tcompute(ql, split, vl, mid);\n\t\t}\n\t}\n\n\tpublic static void buildst() {\n\t\topsize = 0;\n\t\tfor (int i = 1; i <= n << 1; i++) {\n\t\t\tfa[i] = i;\n\t\t\tsiz[i] = 1;\n\t\t}\n\t\tcompute(1, m, 1, m + 1);\n\t\tfor (int p = 0; p < MAXP; p++) {\n\t\t\tst[m + 1][p] = m + 1;\n\t\t}\n\t\tfor (int i = m; i >= 1; i--) {\n\t\t\tst[i][0] = first[i];\n\t\t\tfor (int p = 1; p < MAXP; p++) {\n\t\t\t\tst[i][p] = st[st[i][p - 1]][p - 1];\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tq = in.nextInt();\n\t\tfor (int i = 1, x, y; i <= m; i++) {\n\t\t\tu[i] = in.nextInt();\n\t\t\tx = in.nextInt();\n\t\t\tv[i] = in.nextInt();\n\t\t\ty = in.nextInt();\n\t\t\terror[i] = u[i] == v[i] && x != y ? 1 : 0;\n\t\t\tu[i] = x == 0 ? u[i] : (u[i] + n);\n\t\t\tv[i] = y == 0 ? v[i] : (v[i] + n);\n\t\t}\n\t\tbuildst();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\terror[i] += error[i - 1];\n\t\t}\n\t\tfor (int i = 1, l, r; i <= q; i++) {\n\t\t\tl = in.nextInt();\n\t\t\tr = in.nextInt();\n\t\t\tif (error[r] - error[l - 1] > 0) {\n\t\t\t\tout.println(-1);\n\t\t\t} else {\n\t\t\t\tint ans = 0;\n\t\t\t\tfor (int p = MAXP - 1; p >= 0; p--) {\n\t\t\t\t\tif (st[l][p] <= r) {\n\t\t\t\t\t\tl = st[l][p];\n\t\t\t\t\t\tans += 1 << p;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tans++;\n\t\t\t\tout.println(ans);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Boolean2.java`\n\n```java\npackage class197;\n\n// 布尔，C++版\n// 一共n个变量，取值为0或1，一共m条限制，格式 u x v y，含义如下\n// 如果u的取值为x，则v的取值为y，同时如果v的取值为y，则u的取值为x\n// 限制的编号范围1~m，限制区间[a, b]如果满足如下条件，就认为是合法的\n// 区间[a, b]内的所有限制，存在一种变量赋值方案，能让它们全部成立\n// 一共有q条查询，格式 l r，含义如下\n// 整个限制区间[l, r]，最少划分成多少段连续区间，使得每个连续区间都合法\n// 打印划分的连续区间数量，如果怎么划分都做不到上述要求，打印-1\n// 1 <= n <= 10^5\n// 1 <= m <= 6 * 10^5\n// 1 <= q <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P7843\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 200001;\n//const int MAXM = 600001;\n//const int MAXQ = 1000001;\n//const int MAXP = 20;\n//int n, m, q;\n//\n//int error[MAXM];\n//\n//int u[MAXM];\n//int v[MAXM];\n//\n//int fa[MAXN];\n//int siz[MAXN];\n//int rollback[MAXN][2];\n//int opsize;\n//\n//int first[MAXM];\n//\n//int st[MAXM + 1][MAXP];\n//\