\n//        } else {\n//            add(dfn[top[x]], dfn[x], v, 1, n, 1);\n//            x = fa[top[x]];\n//        }\n//    }\n//    add(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), v, 1, n, 1);\n//}\n//\n//void subtreeAdd(int x, int v) {\n//    add(dfn[x], dfn[x] + siz[x] - 1, v, 1, n, 1);\n//}\n//\n//long long pathSum(int x, int y) {\n//    long long ans = 0;\n//    while (top[x] != top[y]) {\n//        if (dep[top[x]] <= dep[top[y]]) {\n//            ans = (ans + query(dfn[top[y]], dfn[y], 1, n, 1)) % MOD;\n//            y = fa[top[y]];\n//        } else {\n//            ans = (ans + query(dfn[top[x]], dfn[x], 1, n, 1)) % MOD;\n//            x = fa[top[x]];\n//        }\n//    }\n//    ans = (ans + query(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), 1, n, 1)) % MOD;\n//    return ans;\n//}\n//\n//long long subtreeSum(int x) {\n//    return query(dfn[x], dfn[x] + siz[x] - 1, 1, n, 1);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> root >> MOD;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(root, 0);\n//    dfs2(root, root);\n//    build(1, n, 1);\n//    for (int i = 1, op, x, y, v; i <= m; i++) {\n//        cin >> op;\n//        if (op == 1) {\n//            cin >> x >> y >> v;\n//            pathAdd(x, y, v);\n//        } else if (op == 2) {\n//            cin >> x >> y;\n//            cout << pathSum(x, y) << "\\n";\n//        } else if (op == 3) {\n//            cin >> x >> v;\n//            subtreeAdd(x, v);\n//        } else {\n//            cin >> x;\n//            cout << subtreeSum(x) << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code02_LCA1.java`\n\n```java\npackage class161;\n\n// 重链剖分解决LCA查询，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，给定头节点编号root\n// 一共有m条查询，每条查询给定a和b，打印a和b的最低公共祖先\n// 请用树链剖分的方式实现\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3379\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.io.StreamTokenizer;\n\npublic class Code02_LCA1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int n, m, root;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cnt = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cnt] = head[u];\n\t\tto[cnt] = v;\n\t\thead[u] = cnt;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(root, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(root, root, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int lca(int a, int b) {\n\t\twhile (top[a] != top[b]) {\n\t\t\tif (dep[top[a]] <= dep[top[b]]) {\n\t\t\t\tb = fa[top[b]];\n\t\t\t} else {\n\t\t\t\ta = fa[top[a]];\n\t\t\t}\n\t\t}\n\t\treturn dep[a] <= dep[b] ? a : b;\n\t}\n\n\tpublic static void main(String[] args) throws IOException {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStreamTokenizer in = new StreamTokenizer(br);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tin.nextToken();\n\t\tn = (int) in.nval;\n\t\tin.nextToken();\n\t\tm = (int) in.nval;\n\t\tin.nextToken();\n\t\troot = (int) in.nval;\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tin.nextToken();\n\t\t\tu = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tv = (int) in.nval;\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(root, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(root, root)，调用迭代版防止爆栈\n\t\tfor (int i = 1, a, b; i <= m; i++) {\n\t\t\tin.nextToken();\n\t\t\ta = (int) in.nval;\n\t\t\tin.nextToken();\n\t\t\tb = (int) in.nval;\n\t\t\tout.println(lca(a, b));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t\tbr.close();\n\t}\n\n}\n\n```\n\n### `Code02_LCA2.java`\n\n```java\npackage class161;\n\n// 重链剖分解决LCA查询，C++版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，给定头节点编号root\n// 一共有m条查询，每条查询给定a和b，打印a和b的最低公共祖先\n// 请用树链剖分的方式实现\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3379\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//int n, m, root;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cnt = 0;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cnt] = head[u];\n//    to[cnt] = v;\n//    head[u] = cnt;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//        }\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    if(son[u] == 0) {\n//        return;\n//    }\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//int lca(int a, int b) {\n//    while (top[a] != top[b]) {\n//        if (dep[top[a]] <= dep[top[b]]) {\n//            b = fa[top[b]];\n//        } else {\n//            a = fa[top[a]];\n//        }\n//    }\n//    return dep[a] <= dep[b] ? a : b;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m >> root;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    dfs1(root, 0);\n//    dfs2(root, root);\n//    for (int i = 1, a, b; i <= m; i++) {\n//        cin >> a >> b;\n//        cout << lca(a, b) << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code03_PathMaxAndSum1.java`\n\n```java\npackage class161;\n\n// 路径最大值与累加和，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定权值\n// 一共有m条操作，每种操作是如下3种类型中的一种\n// 操作 CHANGE x y : x的权值修改为y\n// 操作 QMAX x y   : x到y的路径上，打印节点值的最大值\n// 操作 QSUM x y   : x到y的路径上，打印节点值的累加和\n// 1 <= n <= 3 * 10^4\n// 0 <= m <= 2 * 10^5\n// -30000 <= 节点权值 <= +30000\n// 测试链接 : https://www.luogu.com.cn/problem/P2590\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code03_PathMaxAndSum1 {\n\n\tpublic static int MAXN = 30001;\n\tpublic static int INF = 10000001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static int[] max = new int[MAXN << 2];\n\tpublic static int[] sum = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tseg[cntd] = first;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\tmax[i] = Math.max(max[i << 1], max[i << 1 | 1]);\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = arr[seg[l]];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobi, int jobv, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = max[i] = jobv;\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobi <= mid) {\n\t\t\t\tupdate(jobi, jobv, l, mid, i << 1);\n\t\t\t} else {\n\t\t\t\tupdate(jobi, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int queryMax(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn max[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = -INF;\n\t\tif (jobl <= mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans = Math.max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static int querySum(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tint ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += querySum(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void pointUpdate(int u, int v) {\n\t\tupdate(dfn[u], v, 1, n, 1);\n\t}\n\n\tpublic static int pathMax(int x, int y) {\n\t\tint ans = -INF;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans = Math.max(ans, queryMax(dfn[top[y]], dfn[y], 1, n, 1));\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans = Math.max(ans, queryMax(dfn[top[x]], dfn[x], 1, n, 1));\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans = Math.max(ans, queryMax(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1));\n\t\treturn ans;\n\t}\n\n\tpublic static int pathSum(int x, int y) {\n\t\tint ans = 0;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans += querySum(dfn[top[y]], dfn[y], 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += querySum(dfn[top[x]], dfn[x], 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tans += querySum(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextInt();\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(1, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(1, 1)，调用迭代版防止爆栈\n\t\tbuild(1, n, 1);\n\t\tm = io.nextInt();\n\t\tString op;\n\t\tint x, y;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tif (op.equals("CHANGE")) {\n\t\t\t\tpointUpdate(x, y);\n\t\t\t} else if (op.equals("QMAX")) {\n\t\t\t\tio.println(pathMax(x, y));\n\t\t\t} else {\n\t\t\t\tio.println(pathSum(x, y));\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_PathMaxAndSum2.java`\n\n```java\npackage class161;\n\n// 路径最大值与累加和，C++版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定权值\n// 一共有m条操作，每种操作是如下3种类型中的一种\n// 操作 CHANGE x y : x的权值修改为y\n// 操作 QMAX x y   : x到y的路径上，打印节点值的最大值\n// 操作 QSUM x y   : x到y的路径上，打印节点值的累加和\n// 1 <= n <= 3 * 10^4\n// 0 <= m <= 2 * 10^5\n// -30000 <= 节点权值 <= +30000\n// 测试链接 : https://www.luogu.com.cn/problem/P2590\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 30001;\n//const int INF = 10000001;\n//int n, m;\n//int arr[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg = 0;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dfn[MAXN];\n//int seg[MAXN];\n//int cntd = 0;\n//\n//int maxv[MAXN << 2];\n//int sumv[MAXN << 2];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            dfs1(v, u);\n//        }\n//    }\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (!son[u] || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    dfn[u] = ++cntd;\n//    seg[cntd] = u;\n//    if (!son[u]) return;\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//void up(int i) {\n//    sumv[i] = sumv[i << 1] + sumv[i << 1 | 1];\n//    maxv[i] = max(maxv[i << 1], maxv[i << 1 | 1]);\n//}\n//\n//void build(int l, int r, int i) {\n//    if (l == r) {\n//        sumv[i] = maxv[i] = arr[seg[l]];\n//    } else {\n//        int mid = (l + r) / 2;\n//        build(l, mid, i << 1);\n//        build(mid + 1, r, i << 1 | 1);\n//        up(i);\n//    }\n//}\n//\n//void update(int jobi, int jobv, int l, int r, int i) {\n//    if (l == r) {\n//        sumv[i] = maxv[i] = jobv;\n//    } else {\n//        int mid = (l + r) / 2;\n//        if (jobi <= mid) {\n//            update(jobi, jobv, l, mid, i << 1);\n//        } else {\n//            update(jobi, jobv, mid + 1, r, i << 1 | 1);\n//        }\n//        up(i);\n//    }\n//}\n//\n//int queryMax(int jobl, int jobr, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        return maxv[i];\n//    }\n//    int mid = (l + r) / 2, ans = -INF;\n//    if (jobl <= mid) {\n//        ans = max(ans, queryMax(jobl, jobr, l, mid, i << 1));\n//    }\n//    if (jobr > mid) {\n//        ans = max(ans, queryMax(jobl, jobr, mid + 1, r, i << 1 | 1));\n//    }\n//    return ans;\n//}\n//\n//int querySum(int jobl, int jobr, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        return sumv[i];\n//    }\n//    int mid = (l + r) / 2, ans = 0;\n//    if (jobl <= mid) {\n//        ans += querySum(jobl, jobr, l, mid, i << 1);\n//    }\n//    if (jobr > mid) {\n//        ans += querySum(jobl, jobr, mid + 1, r, i << 1 | 1);\n//    }\n//    return ans;\n//}\n//\n//void pointUpdate(int u, int v) {\n//    update(dfn[u], v, 1, n, 1);\n//}\n//\n//int pathMax(int x, int y) {\n//    int ans = -INF;\n//    while (top[x] != top[y]) {\n//        if (dep[top[x]] <= dep[top[y]]) {\n//            ans = max(ans, queryMax(dfn[top[y]], dfn[y], 1, n, 1));\n//            y = fa[top[y]];\n//        } else {\n//            ans = max(ans, queryMax(dfn[top[x]], dfn[x], 1, n, 1));\n//            x = fa[top[x]];\n//        }\n//    }\n//    return max(ans, queryMax(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), 1, n, 1));\n//}\n//\n//int pathSum(int x, int y) {\n//    int ans = 0;\n//    while (top[x] != top[y]) {\n//        if (dep[top[x]] <= dep[top[y]]) {\n//            ans += querySum(dfn[top[y]], dfn[y], 1, n, 1);\n//            y = fa[top[y]];\n//        } else {\n//            ans += querySum(dfn[top[x]], dfn[x], 1, n, 1);\n//            x = fa[top[x]];\n//        }\n//    }\n//    return ans + querySum(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), 1, n, 1);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1, u, v; i < n; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    build(1, n, 1);\n//    cin >> m;\n//    string op;\n//    int x, y;\n//    while (m--) {\n//        cin >> op >> x >> y;\n//        if (op == "CHANGE") {\n//            pointUpdate(x, y);\n//        } else if(op == "QMAX") {\n//            cout << pathMax(x, y) << '\\n';\n//        } else {\n//            cout << pathSum(x, y) << '\\n';\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_PackageManager1.java`\n\n```java\npackage class161;\n\n// 软件包管理器，java版\n// 一共有n个软件，编号0~n-1，0号软件不依赖任何软件，其他每个软件都仅依赖一个软件\n// 依赖关系由数组形式给出，题目保证不会出现循环依赖\n// 一开始所有软件都是没有安装的，如果a依赖b，那么安装a需要安装b，同时卸载b需要卸载a\n// 一共有m条操作，每种操作是如下2种类型中的一种\n// 操作 install x    : 安装x，如果x已经安装打印0，否则打印有多少个软件的状态需要改变\n// 操作 uninstall x  : 卸载x，如果x没有安装打印0，否则打印有多少个软件的状态需要改变\n// 1 <= n、m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P2146\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code04_PackageManager1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static int[] sum = new int[MAXN << 2];\n\tpublic static boolean[] update = new boolean[MAXN << 2];\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t}\n\n\t// 线段树重置操作的懒更新\n\tpublic static void lazy(int i, int v, int n) {\n\t\tsum[i] = v * n;\n\t\tupdate[i] = true;\n\t\tchange[i] = v;\n\t}\n\n\tpublic static void down(int i, int ln, int rn) {\n\t\tif (update[i]) {\n\t\t\tlazy(i << 1, change[i], ln);\n\t\t\tlazy(i << 1 | 1, change[i], rn);\n\t\t\tupdate[i] = false;\n\t\t}\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv, r - l + 1);\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tdown(i, mid - l + 1, r - mid);\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static long query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tint mid = (l + r) / 2;\n\t\tdown(i, mid - l + 1, r - mid);\n\t\tlong ans = 0;\n\t\tif (jobl <= mid) {\n\t\t\tans += query(jobl, jobr, l, mid, i << 1);\n\t\t}\n\t\tif (jobr > mid) {\n\t\t\tans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 从1到x的路径上，所有节点值改成v\n\tpublic static void pathUpdate(int x, int v) {\n\t\tint y = 1;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tupdate(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tupdate(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tupdate(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\tpublic static int install(int x) {\n\t\tint pre = sum[1];\n\t\tpathUpdate(x, 1);\n\t\tint post = sum[1];\n\t\treturn Math.abs(post - pre);\n\t}\n\n\tpublic static int uninstall(int x) {\n\t\tint pre = sum[1];\n\t\tupdate(dfn[x], dfn[x] + siz[x] - 1, 0, 1, n, 1);\n\t\tint post = sum[1];\n\t\treturn Math.abs(post - pre);\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tfor (int u = 2, v; u <= n; u++) {\n\t\t\tv = io.nextInt() + 1;\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs3(); // dfs3() 等同于 dfs1(1, 0)，调用迭代版防止爆栈\n\t\tdfs4(); // dfs4() 等同于 dfs2(1, 1)，调用迭代版防止爆栈\n\t\tm = io.nextInt();\n\t\tString op;\n\t\tint x;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt() + 1;\n\t\t\tif (op.equals("install")) {\n\t\t\t\tio.println(install(x));\n\t\t\t} else {\n\t\t\t\tio.println(uninstall(x));\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_PackageManager2.java`\n\n```java\npackage class161;\n\n// 软件包管理器，C++版\n// 一共有n个软件，编号0~n-1，0号软件不依赖任何软件，其他每个软件都仅依赖一个软件\n// 依赖关系由数组形式给出，题目保证不会出现循环依赖\n// 一开始所有软件都是没有安装的，如果a依赖b，那么安装a需要安装b，同时卸载b需要卸载a\n// 一共有m条操作，每种操作是如下2种类型中的一种\n// 操作 install x    : 安装x，如果x已经安装打印0，否则打印有多少个软件的状态需要改变\n// 操作 uninstall x  : 卸载x，如果x没有安装打印0，否则打印有多少个软件的状态需要改变\n// 1 <= n、m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P2146\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg = 0;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dfn[MAXN];\n//int cntd = 0;\n//\n//int sum[MAXN << 2];\n//bool update[MAXN << 2];\n//int change[MAXN << 2];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f) {\n//    fa[u] = f;\n//    dep[u] = dep[f] + 1;\n//    siz[u] = 1;\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) dfs1(v, u);\n//    }\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != f) {\n//            siz[u] += siz[v];\n//            if (son[u] == 0 || siz[son[u]] < siz[v]) {\n//                son[u] = v;\n//            }\n//        }\n//    }\n//}\n//\n//void dfs2(int u, int t) {\n//    top[u] = t;\n//    dfn[u] = ++cntd;\n//    if (son[u] == 0) return;\n//    dfs2(son[u], t);\n//    for (int e = head[u], v; e > 0; e = nxt[e]) {\n//        v = to[e];\n//        if (v != fa[u] && v != son[u]) {\n//            dfs2(v, v);\n//        }\n//    }\n//}\n//\n//void up(int i) {\n//    sum[i] = sum[i << 1] + sum[i << 1 | 1];\n//}\n//\n//void lazy(int i, int v, int n) {\n//    sum[i] = v * n;\n//    update[i] = true;\n//    change[i] = v;\n//}\n//\n//void down(int i, int ln, int rn) {\n//    if (update[i]) {\n//        lazy(i << 1, change[i], ln);\n//        lazy(i << 1 | 1, change[i], rn);\n//        update[i] = false;\n//    }\n//}\n//\n//void updateRange(int jobl, int jobr, int jobv, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) {\n//        lazy(i, jobv, r - l + 1);\n//    } else {\n//        int mid = (l + r) / 2;\n//        down(i, mid - l + 1, r - mid);\n//        if (jobl <= mid) updateRange(jobl, jobr, jobv, l, mid, i << 1);\n//        if (jobr > mid) updateRange(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n//        up(i);\n//    }\n//}\n//\n//long long query(int jobl, int jobr, int l, int r, int i) {\n//    if (jobl <= l && r <= jobr) return sum[i];\n//    int mid = (l + r) / 2;\n//    down(i, mid - l + 1, r - mid);\n//    long long ans = 0;\n//    if (jobl <= mid) ans += query(jobl, jobr, l, mid, i << 1);\n//    if (jobr > mid) ans += query(jobl, jobr, mid + 1, r, i << 1 | 1);\n//    return ans;\n//}\n//\n//void pathUpdate(int x, int v) {\n//    int y = 1;\n//    while (top[x] != top[y]) {\n//        if (dep[top[x]] <= dep[top[y]]) {\n//            updateRange(dfn[top[y]], dfn[y], v, 1, n, 1);\n//            y = fa[top[y]];\n//        } else {\n//            updateRange(dfn[top[x]], dfn[x], v, 1, n, 1);\n//            x = fa[top[x]];\n//        }\n//    }\n//    updateRange(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), v, 1, n, 1);\n//}\n//\n//int install(int x) {\n//    int pre = sum[1];\n//    pathUpdate(x, 1);\n//    int post = sum[1];\n//    return abs(post - pre);\n//}\n//\n//int uninstall(int x) {\n//    int pre = sum[1];\n//    updateRange(dfn[x], dfn[x] + siz[x] - 1, 0, 1, n, 1);\n//    int post = sum[1];\n//    return abs(post - pre);\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int u = 2, v; u <= n; u++) {\n//        cin >> v;\n//        v++;\n//        addEdge(v, u);\n//    }\n//    dfs1(1, 0);\n//    dfs2(1, 1);\n//    cin >> m;\n//    string op;\n//    int x;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> op >> x;\n//        x++;\n//        if (op == "install") {\n//            cout << install(x) << '\\n';\n//        } else {\n//            cout << uninstall(x) << '\\n';\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_Coloring1.java`\n\n```java\npackage class161;\n\n// 染色，java版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定初始颜色值\n// 连续相同颜色被认为是一段，变化了就认为是另一段\n// 比如，112221，有三个颜色段，分别为 11、222、1\n// 一共有m条操作，每种操作是如下2种类型中的一种\n// 操作 C x y z : x到y的路径上，每个节点的颜色都改为z\n// 操作 Q x y   : x到y的路径上，打印有几个颜色段\n// 1 <= n、m <= 10^5\n// 1 <= 任何时候的颜色值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2486\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.BufferedReader;\nimport java.io.FileReader;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.InputStreamReader;\nimport java.io.OutputStream;\nimport java.io.PrintWriter;\nimport java.util.StringTokenizer;\n\npublic class Code05_Coloring1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int n, m;\n\tpublic static int[] arr = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] next = new int[MAXN << 1];\n\tpublic static int[] to = new int[MAXN << 1];\n\tpublic static int cntg = 0;\n\n\tpublic static int[] fa = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] siz = new int[MAXN];\n\tpublic static int[] son = new int[MAXN];\n\tpublic static int[] top = new int[MAXN];\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] seg = new int[MAXN];\n\tpublic static int cntd = 0;\n\n\tpublic static int[] sum = new int[MAXN << 2];\n\tpublic static int[] lcolor = new int[MAXN << 2];\n\tpublic static int[] rcolor = new int[MAXN << 2];\n\t// change是线段树的懒更新信息\n\t// change[i] == 0 代表没有懒更新信息\n\t// change[i] != 0 代表颜色重置为change[i]\n\tpublic static int[] change = new int[MAXN << 2];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnext[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs1(int u, int f) {\n\t\tfa[u] = f;\n\t\tdep[u] = dep[f] + 1;\n\t\tsiz[u] = 1;\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs1(v, u);\n\t\t\t}\n\t\t}\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tsiz[u] += siz[v];\n\t\t\t\tif (son[u] == 0 || siz[son[u]] < siz[v]) {\n\t\t\t\t\tson[u] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 递归版，C++可以通过，java会爆栈\n\tpublic static void dfs2(int u, int t) {\n\t\ttop[u] = t;\n\t\tdfn[u] = ++cntd;\n\t\tseg[cntd] = u;\n\t\tif (son[u] == 0) {\n\t\t\treturn;\n\t\t}\n\t\tdfs2(son[u], t);\n\t\tfor (int e = head[u], v; e > 0; e = next[e]) {\n\t\t\tv = to[e];\n\t\t\tif (v != fa[u] && v != son[u]) {\n\t\t\t\tdfs2(v, v);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 不会改迭代版，去看讲解118，详解了从递归版改迭代版\n\tpublic static int[][] fse = new int[MAXN][3];\n\n\tpublic static int stacksize, first, second, edge;\n\n\tpublic static void push(int fir, int sec, int edg) {\n\t\tfse[stacksize][0] = fir;\n\t\tfse[stacksize][1] = sec;\n\t\tfse[stacksize][2] = edg;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\t--stacksize;\n\t\tfirst = fse[stacksize][0];\n\t\tsecond = fse[stacksize][1];\n\t\tedge = fse[stacksize][2];\n\t}\n\n\t// dfs1的迭代版\n\tpublic static void dfs3() {\n\t\tstacksize = 0;\n\t\tpush(1, 0, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) {\n\t\t\t\tfa[first] = second;\n\t\t\t\tdep[first] = dep[second] + 1;\n\t\t\t\tsiz[first] = 1;\n\t\t\t\tedge = head[first];\n\t\t\t} else {\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != second) {\n\t\t\t\t\tpush(to[edge], first, -1);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tfor (int e = head[first], v; e > 0; e = next[e]) {\n\t\t\t\t\tv = to[e];\n\t\t\t\t\tif (v != second) {\n\t\t\t\t\t\tsiz[first] += siz[v];\n\t\t\t\t\t\tif (son[first] == 0 || siz[son[first]] < siz[v]) {\n\t\t\t\t\t\t\tson[first] = v;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// dfs2的迭代版\n\tpublic static void dfs4() {\n\t\tstacksize = 0;\n\t\tpush(1, 1, -1);\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (edge == -1) { // edge == -1，表示第一次来到当前节点，并且先处理重儿子\n\t\t\t\ttop[first] = second;\n\t\t\t\tdfn[first] = ++cntd;\n\t\t\t\tseg[cntd] = first;\n\t\t\t\tif (son[first] == 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tpush(first, second, -2);\n\t\t\t\tpush(son[first], second, -1);\n\t\t\t\tcontinue;\n\t\t\t} else if (edge == -2) { // edge == -2，表示处理完当前节点的重儿子，回到了当前节点\n\t\t\t\tedge = head[first];\n\t\t\t} else { // edge >= 0, 继续处理其他的边\n\t\t\t\tedge = next[edge];\n\t\t\t}\n\t\t\tif (edge != 0) {\n\t\t\t\tpush(first, second, edge);\n\t\t\t\tif (to[edge] != fa[first] && to[edge] != son[first]) {\n\t\t\t\t\tpush(to[edge], to[edge], -1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void up(int i) {\n\t\tsum[i] = sum[i << 1] + sum[i << 1 | 1];\n\t\tif (rcolor[i << 1] == lcolor[i << 1 | 1]) {\n\t\t\tsum[i]--;\n\t\t}\n\t\tlcolor[i] = lcolor[i << 1];\n\t\trcolor[i] = rcolor[i << 1 | 1];\n\t}\n\n\tpublic static void lazy(int i, int v) {\n\t\tsum[i] = 1;\n\t\tlcolor[i] = v;\n\t\trcolor[i] = v;\n\t\tchange[i] = v;\n\t}\n\n\tpublic static void down(int i) {\n\t\tif (change[i] != 0) {\n\t\t\tlazy(i << 1, change[i]);\n\t\t\tlazy(i << 1 | 1, change[i]);\n\t\t\tchange[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void build(int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\tsum[i] = 1;\n\t\t\tlcolor[i] = arr[seg[l]];\n\t\t\trcolor[i] = arr[seg[l]];\n\t\t} else {\n\t\t\tint mid = (l + r) / 2;\n\t\t\tbuild(l, mid, i << 1);\n\t\t\tbuild(mid + 1, r, i << 1 | 1);\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static void update(int jobl, int jobr, int jobv, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\tlazy(i, jobv);\n\t\t} else {\n\t\t\tdown(i);\n\t\t\tint mid = (l + r) / 2;\n\t\t\tif (jobl <= mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, l, mid, i << 1);\n\t\t\t}\n\t\t\tif (jobr > mid) {\n\t\t\t\tupdate(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);\n\t\t\t}\n\t\t\tup(i);\n\t\t}\n\t}\n\n\tpublic static int query(int jobl, int jobr, int l, int r, int i) {\n\t\tif (jobl <= l && r <= jobr) {\n\t\t\treturn sum[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) / 2;\n\t\tif (jobr <= mid) {\n\t\t\treturn query(jobl, jobr, l, mid, i << 1);\n\t\t} else if (jobl > mid) {\n\t\t\treturn query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t} else {\n\t\t\tint ans = query(jobl, jobr, l, mid, i << 1) + query(jobl, jobr, mid + 1, r, i << 1 | 1);\n\t\t\tif (rcolor[i << 1] == lcolor[i << 1 | 1]) {\n\t\t\t\tans--;\n\t\t\t}\n\t\t\treturn ans;\n\t\t}\n\t}\n\n\t// 查询单点颜色，jobi为节点的dfn序号\n\tpublic static int pointColor(int jobi, int l, int r, int i) {\n\t\tif (l == r) {\n\t\t\treturn lcolor[i];\n\t\t}\n\t\tdown(i);\n\t\tint mid = (l + r) / 2;\n\t\tif (jobi <= mid) {\n\t\t\treturn pointColor(jobi, l, mid, i << 1);\n\t\t} else {\n\t\t\treturn pointColor(jobi, mid + 1, r, i << 1 | 1);\n\t\t}\n\t}\n\n\tpublic static void pathUpdate(int x, int y, int v) {\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tupdate(dfn[top[y]], dfn[y], v, 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tupdate(dfn[top[x]], dfn[x], v, 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t}\n\t\tupdate(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), v, 1, n, 1);\n\t}\n\n\tpublic static int pathColors(int x, int y) {\n\t\tint ans = 0, sonc, fac;\n\t\twhile (top[x] != top[y]) {\n\t\t\tif (dep[top[x]] <= dep[top[y]]) {\n\t\t\t\tans += query(dfn[top[y]], dfn[y], 1, n, 1);\n\t\t\t\tsonc = pointColor(dfn[top[y]], 1, n, 1);\n\t\t\t\tfac = pointColor(dfn[fa[top[y]]], 1, n, 1);\n\t\t\t\ty = fa[top[y]];\n\t\t\t} else {\n\t\t\t\tans += query(dfn[top[x]], dfn[x], 1, n, 1);\n\t\t\t\tsonc = pointColor(dfn[top[x]], 1, n, 1);\n\t\t\t\tfac = pointColor(dfn[fa[top[x]]], 1, n, 1);\n\t\t\t\tx = fa[top[x]];\n\t\t\t}\n\t\t\tif (sonc == fac) {\n\t\t\t\tans--;\n\t\t\t}\n\t\t}\n\t\tans += query(Math.min(dfn[x], dfn[y]), Math.max(dfn[x], dfn[y]), 1, n, 1);\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) {\n\t\tKattio io = new Kattio();\n\t\tn = io.nextInt();\n\t\tm = io.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = io.nextInt();\n\t\t}\n\t\tfor (int i = 1, u, v; i < n; i++) {\n\t\t\tu = io.nextInt();\n\t\t\tv = io.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tdfs3();\n\t\tdfs4();\n\t\tbuild(1, n, 1);\n\t\tString op;\n\t\tint x, y, z;\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\top = io.next();\n\t\t\tx = io.nextInt();\n\t\t\ty = io.nextInt();\n\t\t\tif (op.equals("C")) {\n\t\t\t\tz = io.nextInt();\n\t\t\t\tpathUpdate(x, y, z);\n\t\t\t} else {\n\t\t\t\tio.println(pathColors(x, y));\n\t\t\t}\n\t\t}\n\t\tio.flush();\n\t\tio.close();\n\t}\n\n\t// 读写工具类\n\tpublic static class Kattio extends PrintWriter {\n\t\tprivate BufferedReader r;\n\t\tprivate StringTokenizer st;\n\n\t\tpublic Kattio() {\n\t\t\tthis(System.in, System.out);\n\t\t}\n\n\t\tpublic Kattio(InputStream i, OutputStream o) {\n\t\t\tsuper(o);\n\t\t\tr = new BufferedReader(new InputStreamReader(i));\n\t\t}\n\n\t\tpublic Kattio(String intput, String output) throws IOException {\n\t\t\tsuper(output);\n\t\t\tr = new BufferedReader(new FileReader(intput));\n\t\t}\n\n\t\tpublic String next() {\n\t\t\ttry {\n\t\t\t\twhile (st == null || !st.hasMoreTokens())\n\t\t\t\t\tst = new StringTokenizer(r.readLine());\n\t\t\t\treturn st.nextToken();\n\t\t\t} catch (Exception e) {\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic int nextInt() {\n\t\t\treturn Integer.parseInt(next());\n\t\t}\n\n\t\tpublic double nextDouble() {\n\t\t\treturn Double.parseDouble(next());\n\t\t}\n\n\t\tpublic long nextLong() {\n\t\t\treturn Long.parseLong(next());\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_Coloring2.java`\n\n```java\npackage class161;\n\n// 染色，C++版\n// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定初始颜色值\n// 连续相同颜色被认为是一段，变化了就认为是另一段\n// 比如，112221，有三个颜色段，分别为 11、222、1\n// 一共有m条操作，每种操作是如下2种类型中的一种\n// 操作 C x y z : x到y的路径上，每个节点的颜色都改为z\n// 操作 Q x y   : x到y的路径上，打印有几个颜色段\n// 1 <= n、m <= 10^5\n// 1 <= 任何时候的颜色值 <= 10^9\n// 测试链接 : https://www.luogu.com.cn/problem/P2486\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//int n, m;\n//int arr[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXN << 1];\n//int to[MAXN << 1];\n//int cntg = 0;\n//\n//int fa[MAXN];\n//int dep[MAXN];\n//int siz[MAXN];\n//int son[MAXN];\n//int top[MAXN];\n//int dfn[MAXN];\n//int seg[MAXN];\n//int cntd = 0;\n//\n//int sum[MAXN << 2];\n//int lcolor[MAXN << 2];\n//int rcolor[MAXN << 2];\n//int change[MAXN << 2];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void dfs1(int u, int f) {\n//   