cCnt;\n\n\tpublic static int[] outdegree = new int[MAXN];\n\tpublic static int[] indegree = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = 0;\n\t\tfor (int i = 1, x; i <= n; i++) {\n\t\t\tx = in.nextInt();\n\t\t\twhile (x != 0) {\n\t\t\t\tm++;\n\t\t\t\ta[m] = i;\n\t\t\t\tb[m] = x;\n\t\t\t\taddEdge(a[m], b[m]);\n\t\t\t\tx = in.nextInt();\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tif (sccCnt == 1) {\n\t\t\tout.println("1");\n\t\t\tout.println("0");\n\t\t} else {\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint scc1 = belong[a[i]];\n\t\t\t\tint scc2 = belong[b[i]];\n\t\t\t\tif (scc1 != scc2) {\n\t\t\t\t\toutdegree[scc1]++;\n\t\t\t\t\tindegree[scc2]++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tint outZero = 0;\n\t\t\tint inZero = 0;\n\t\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\t\tif (outdegree[i] == 0) {\n\t\t\t\t\toutZero++;\n\t\t\t\t}\n\t\t\t\tif (indegree[i] == 0) {\n\t\t\t\t\tinZero++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println(inZero);\n\t\t\tout.println(Math.max(outZero, inZero));\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_NetworkOfSchools2.java`\n\n```java\npackage class189;\n\n// 校园网络，C++版\n// 一共有n个节点，m条有向边，消息只能顺着有向边传递\n// 打印至少需要在几个节点投放消息，才能让所有节点，都能收到消息\n// 打印至少需要添加几条边，才能让任意两个节点之间，都能传递消息\n// 1 <= n <= 10^4\n// 1 <= m <= 5 * 10^4\n// 测试链接 : https://www.luogu.com.cn/problem/P2812\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 500001;\n//int n, m;\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sccCnt;\n//\n//int outdegree[MAXN];\n//int indegree[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] ==