nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code07_Spy1 {\n\n\tpublic static int MAXN = 3001;\n\tpublic static int MAXM = 8001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, p, m;\n\n\tpublic static int[] cost = new int[MAXN];\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] minVal = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] indegree = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tminVal[sccCnt] = INF;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tminVal[sccCnt] = Math.min(minVal[sccCnt], cost[pop]);\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tp = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tcost[i] = INF;\n\t\t}\n\t\tfor (int i = 1, u, c; i <= p; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tc = in.nextInt();\n\t\t\tcost[u] = c;\n\t\t}\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (cost[i] != INF && dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tboolean check = true;\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[i] == 0) {\n\t\t\t\tcheck = false;\n\t\t\t\tans = i;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (!check) {\n\t\t\tout.println("NO");\n\t\t\tout.println(ans);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tint scc1 = belong[a[i]];\n\t\t\t\tint scc2 = belong[b[i]];\n\t\t\t\tif (scc1 != scc2) {\n\t\t\t\t\tindegree[scc2]++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\t\tif (indegree[i] == 0) {\n\t\t\t\t\tans += minVal[i];\n\t\t\t\t}\n\t\t\t}\n\t\t\tout.println("YES");\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_Spy2.java`\n\n```java\npackage class189;\n\n// 间谍网络，C++版\n// 一共有n个间谍，其中有p个间谍可以贿赂，给定各自的价格，剩下的间谍不能贿赂\n// 然后给定m个控制关系，控制关系是单向的，也是可传递的\n// 如果间谍a能控制间谍b，间谍b能控制间谍c，那么间谍a就能控制间谍c\n// 当你贿赂了某个间谍，该间谍连同他能控制的所有人，都能被你控制\n// 如果你不能控制所有间谍，打印"NO"，然后打印不能控制的间谍中，最小的编号\n// 如果你可以控制所有间谍，打印"YES"，然后打印需要花费的最少钱数\n// 1 <= n <= 3000    0 <= 各自的价格 <= 20000    1 <= m <= 8000\n// 测试链接 : https://www.luogu.com.cn/problem/P1262\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 3001;\n//const int MAXM = 8001;\n//const int INF = 1000000001;\n//int n, p, m;\n//\n//int cost[MAXN];\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int minVal[MAXN];\n//int sccCnt;\n//\n//int indegree[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        minVal[sccCnt] = INF;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//            minVal[sccCnt] = min(minVal[sccCnt], cost[pop]);\n//        } while (pop != u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> p;\n//    for (int i = 1; i <= n; i++) {\n//        cost[i] = INF;\n//    }\n//    for (int i = 1, u, c; i <= p; i++) {\n//        cin >> u >> c;\n//        cost[u] = c;\n//    }\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//        addEdge(a[i], b[i]);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (cost[i] != INF && dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    bool check = true;\n//    int ans = 0;\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[i] == 0) {\n//            check = false;\n//            ans = i;\n//            break;\n//        }\n//    }\n//    if (!check) {\n//        cout << "NO" << "\\n";\n//        cout << ans << "\\n";\n//    } else {\n//        for (int i = 1; i <= m; i++) {\n//            int scc1 = belong[a[i]];\n//            int scc2 = belong[b[i]];\n//            if (scc1 != scc2) {\n//                indegree[scc2]++;\n//            }\n//        }\n//        for (int i = 1; i <= sccCnt; i++) {\n//            if (indegree[i] == 0) {\n//                ans += minVal[i];\n//            }\n//        }\n//        cout << "YES" << "\\n";\n//        cout << ans << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code08_Checkposts1.java`\n\n```java\npackage class189;\n\n// 检查站，java版\n// 给定一张n个点，m条边的有向图，每个点有点权\n// 一个强连通分量内部，选点权最小的点，就能控制该连通分量里的所有点\n// 你的目的是选择若干点之后，图上所有的点都能控制，打印最小点权和\n// 打印选择点的方案数，方案数可能较大，对 1000000007 取余\n// 1 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF427C\n// 测试链接 : https://codeforces.com/problemset/problem/427/C\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code08_Checkposts1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 300001;\n\tpublic static int MOD = 1000000007;\n\tpublic static int n, m;\n\tpublic static int[] val = new int[MAXN];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] minVal = new int[MAXN];\n\tpublic static int[] minCnt = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tminVal[sccCnt] = 1000000001;\n\t\t\tminCnt[sccCnt] = 0;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tif (minVal[sccCnt] > val[pop]) {\n\t\t\t\t\tminVal[sccCnt] = val[pop];\n\t\t\t\t\tminCnt[sccCnt] = 1;\n\t\t\t\t} else if (minVal[sccCnt] == val[pop]) {\n\t\t\t\t\tminCnt[sccCnt]++;\n\t\t\t\t}\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tval[i] = in.nextInt();\n\t\t}\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tlong ans1 = 0, ans2 = 1;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tans1 += minVal[i];\n\t\t\tans2 = (ans2 * minCnt[i]) % MOD;\n\t\t}\n\t\tout.println(ans1 + " " + ans2);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code08_Checkposts2.java`\n\n```java\npackage class189;\n\n// 检查站，C++版\n// 给定一张n个点，m条边的有向图，每个点有点权\n// 一个强连通分量内部，选点权最小的点，就能控制该连通分量里的所有点\n// 你的目的是选择若干点之后，图上所有的点都能控制，打印最小点权和\n// 打印选择点的方案数，方案数可能较大，对 1000000007 取余\n// 1 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF427C\n// 测试链接 : https://codeforces.com/problemset/problem/427/C\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 300001;\n//const int MOD = 1000000007;\n//int n, m;\n//int val[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int minVal[MAXN];\n//int minCnt[MAXN];\n//int sccCnt;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        minVal[sccCnt] = 1000000001;\n//        minCnt[sccCnt] = 0;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//            if (minVal[sccCnt] > val[pop]) {\n//                minVal[sccCnt] = val[pop];\n//                minCnt[sccCnt] = 1;\n//            } else if (minVal[sccCnt] == val[pop]) {\n//                minCnt[sccCnt]++;\n//            }\n//        } while (pop != u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> val[i];\n//    }\n//    cin >> m;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    long long ans1 = 0, ans2 = 1;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        ans1 += minVal[i];\n//        ans2 = (ans2 * minCnt[i]) % MOD;\n//    }\n//    cout << ans1 << " " << ans2 << "\\n";\n//    return 0;\n//}\n```\n\n### `Code09_HasPath1.java`\n\n```java\npackage class189;\n\n// 任意两点都有路，java版\n// 给定一张n个点，m条边的有向图\n// 两点u、v，不管是从u出发能到达v，还是从v出发能到达u，都叫两点间有路\n// 判断这个有向图是否能做到，任意两点都有路，能打印"Yes"，不能打印"No"\n// 1 <= n <= 1000\n// 1 <= m <= 6000\n// 测试链接 : https://www.luogu.com.cn/problem/P10944\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code09_HasPath1 {\n\n\tpublic static int MAXN = 1001;\n\tpublic static int MAXM = 6001;\n\tpublic static int t, n, m;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] indegree = new int[MAXN];\n\tpublic static int[] que = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static boolean topo() {\n\t\tint l = 1, r = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tque[++r] = i;\n\t\t\t}\n\t\t}\n\t\twhile (l <= r) {\n\t\t\tint siz = r - l + 1;\n\t\t\tif (siz > 1) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tint u = que[l++];\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++r] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = in.nextInt();\n\t\tfor (int c = 1; c <= t; c++) {\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t\tcntg = cntd = sccCnt = 0;\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\thead[i] = dfn[i] = belong[i] = indegree[i] = 0;\n\t\t\t}\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\ta[i] = in.nextInt();\n\t\t\t\tb[i] = in.nextInt();\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t}\n\t\t\tfor (int i = 1; i <= n; i++) {\n\t\t\t\tif (dfn[i] == 0) {\n\t\t\t\t\ttarjan(i);\n\t\t\t\t}\n\t\t\t}\n\t\t\tcondense();\n\t\t\tboolean ans = topo();\n\t\t\tout.println(ans ? "Yes" : "No");\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n```\n\n### `Code09_HasPath2.java`\n\n```java\npackage class189;\n\n// 任意两点都有路，C++版\n// 给定一张n个点，m条边的有向图\n// 两点u、v，不管是从u出发能到达v，还是从v出发能到达u，都叫两点间有路\n// 判断这个有向图是否能做到，任意两点都有路，能打印"Yes"，不能打印"No"\n// 1 <= n <= 1000\n// 1 <= m <= 6000\n// 测试链接 : https://www.luogu.com.cn/problem/P10944\n// 如下实现是C++的版本，C++版本和java版本