//            }\n//        }\n//    }\n//    return true;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> t;\n//    for (int c = 1; c <= t; c++) {\n//        cin >> n >> m;\n//        cntg = cntd = sccCnt = 0;\n//        top = 0;\n//        for (int i = 1; i <= n; i++) {\n//            head[i] = dfn[i] = belong[i] = indegree[i] = 0;\n//        }\n//        for (int i = 1; i <= m; i++) {\n//            cin >> a[i] >> b[i];\n//            addEdge(a[i], b[i]);\n//        }\n//        for (int i = 1; i <= n; i++) {\n//            if (dfn[i] == 0) {\n//                tarjan(i);\n//            }\n//        }\n//        condense();\n//        bool ans = topo();\n//        cout << (ans ? "Yes" : "No") << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code10_SafeMarriage1.java`\n\n```java\npackage class189;\n\n// 稳定婚姻，java版\n// 一共有n对婚姻关系，每对婚姻关系给定(女方名, 男方名)，一共2n个名字\n// 一共有m对暧昧关系，每对暧昧关系给定(女方名, 男方名)，不会出现新名字\n// 如果一对婚姻关系破裂，那么女方或者男方，可能会找暧昧关系的对象私奔\n// 私奔会制造更多的婚姻破裂，并且产生进一步的私奔，事情好像多米诺骨牌一样展开\n// 如果所有涉事男女都能重新搭配，只要存在这种可能性，那么这对婚姻关系就是不稳定的\n// 比如A为女，B为男，婚姻关系(A1, B1)、(A2, B2)，同时暧昧关系(A1, B2)、(A2, B1)\n// A1和B1婚姻破裂，导致B1和A2私奔了，导致A2和B2婚姻破裂，导致B2和A1私奔了，这就是重新搭配\n// 检查每对婚姻关系，如果不稳定打印"Unsafe"，如果稳定打印"Safe"\n// 1 <= n <= 4000    0 <= m <= 20000\n// 测试链接 : https://www.luogu.com.cn/problem/P1407\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\nimport java.util.HashMap;\n\npublic class Code10_SafeMarriage1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 30001;\n\tpublic static int n, m;\n\n\tpublic static int[] a = new int[MAXN];\n\tpublic static int[] b = new int[MAXN];\n\tpublic static int cntn;\n\tpublic static HashMap<String, Integer> nameId = new HashMap<>();\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tString girl, boy;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tgirl = in.nextString();\n\t\t\tboy = in.nextString();\n\t\t\ta[i] = ++cntn;\n\t\t\tb[i] = ++cntn;\n\t\t\tnameId.put(girl, a[i]);\n\t\t\tnameId.put(boy, b[i]);\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tgirl = in.nextString();\n\t\t\tboy = in.nextString();\n\t\t\taddEdge(nameId.get(boy), nameId.get(girl));\n\t\t}\n\t\tfor (int i = 1; i <= cntn; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (belong[a[i]] == belong[b[i]]) {\n\t\t\t\tout.println("Unsafe");\n\t\t\t} else {\n\t\t\t\tout.println("Safe");\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tboolean isLetter(int c) {\n\t\t\treturn (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');\n\t\t}\n\n\t\tString nextString() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\treturn null;\n\t\t\t} while (!isLetter(c));\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\twhile (isLetter(c)) {\n\t\t\t\tsb.append((char) c);\n\t\t\t\tc = readByte();\n\t\t\t\tif (c == -1)\n\t\t\t\t\tbreak;\n\t\t\t}\n\t\t\treturn sb.toString();\n\t\t}\n\n\t}\n\n}\n\n```\n\n### `Code10_SafeMarriage2.java`\n\n```java\npackage class189;\n\n// 稳定婚姻，C++版\n// 一共有n对婚姻关系，每对婚姻关系给定(女方名, 男方名)，一共2n个名字\n// 一共有m对暧昧关系，每对暧昧关系给定(女方名, 男方名)，不会出现新名字\n// 如果一对婚姻关系破裂，那么女方或者男方，可能会找暧昧关系的对象私奔\n// 私奔会制造更多的婚姻破裂，并且产生进一步的私奔，事情好像多米诺骨牌一样展开\n// 如果所有涉事男女都能重新搭配，只要存在这种可能性，那么这对婚姻关系就是不稳定的\n// 比如A为女，B为男，婚姻关系(A1, B1)、(A2, B2)，同时暧昧关系(A1, B2)、(A2, B1)\n// A1和B1婚姻破裂，导致B1和A2私奔了，导致A2和B2婚姻破裂，导致B2和A1私奔了，这就是重新搭配\n// 检查每对婚姻关系，如果不稳定打印"Unsafe"，如果稳定打印"Safe"\n// 1 <= n <= 4000    0 <= m <= 20000\n// 测试链接 : https://www.luogu.com.cn/problem/P1407\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 10001;\n//const int MAXM = 30001;\n//int n, m;\n//\n//int a[MAXN];\n//int b[MAXN];\n//int cntn;\n//unordered_map<string, int> nameId;\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sccCnt;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n;\n//    string girl, boy;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> girl >> boy;\n//        a[i] = ++cntn;\n//        b[i] = ++cntn;\n//        nameId[girl] = a[i];\n//        nameId[boy] = b[i];\n//        addEdge(a[i], b[i]);\n//    }\n//    cin >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> girl >> boy;\n//        addEdge(nameId[boy], nameId[girl]);\n//    }\n//    for (int i = 1; i <= cntn; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (belong[a[i]] == belong[b[i]]) {\n//            cout << "Unsafe" << "\\n";\n//        } else {\n//            cout << "Safe" << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n	2026-07-25 03:11:31.715949+00	2026-07-25 03:11:31.715949+00	\N
b7eb3a3e-f437-4e0d-b3d2-f75cc4725a13	e4b5422d-916b-402f-b657-9735ea671cc9	deep	下	# 190. 强连通分量和缩点-下\n\n> 难度标签：**进阶** ｜ 主题：**图论** ｜ 来源：左程云《算法讲解》第 190 讲\n\n## 第 1 页：强连通分量和缩点-下\n\n左程云\n前置知识\n讲解060 - 利用拓扑排序完成DAG的动态规划\n讲解064 - dijkstra算法\n讲解079 - 题目5，树上背包的最优解\n讲解142 - 差分约束\n讲解189 - 强连通分量和缩点-上\n上节课讲述\nTarjan算法求解强连通分量和常见题目\n本节课讲述\n缩点DAG + 动态规划（拓扑排序）             题目1、题目2、题目3、题目4、题目5\n缩点DAG + 最短路、树上背包、差分约束        题目6、题目7、题目8\n缩点DAG + 研究出度入度的分析题             题目9\n\n## 第 2 页：强连通分量和缩点-下\n\n左程云\n题目1\n缩点结合动态规划模版题\n给定一张n个点，m条边的有向图，每个点给定非负点权\n如果重复经过一个点，点权只获得一次\n找到一条路径，使得点权累加和最大，打印这个值\n1 <= n <= 10^4\n1 <= m <= 10^5\n测试链接 : https://www.luogu.com.cn/problem/P3387\n缩点DAG的动态规划\n1，拓扑排序的写法\n2，直接转移的写法\n\n## 第 3 页：强连通分量和缩点-下\n\n左程云\n题目2\n采蘑菇\n给定一张n个点，m条边的有向图，每条边有初始收益、恢复系数两种边权\n初始收益为非负整数，恢复系数范围[0, 0.8]，并且最多有一位小数\n比如，如果重复走过一条边，该边的初始收益为10，恢复系数为0.6\n那么依次获得的收益为，10、6、3、1、0，随后重复经过就没有收益了\n给定起点s，找到一条必须从s出发的路径，打印收益累加和的最大值\n1 <= n <= 8 * 10^4\n1 <= m <= 2 * 10^5\n测试链接 : https://www.luogu.com.cn/problem/P2656\n缩点DAG的动态规划 + 缩点点权的处理 + 限制起点或终点\n\n## 第 4 页：强连通分量和缩点-下\n\n左程云\n题目3\n劫掠计划\n一共有n个城市，给定m条有向道路，每个城市给定拥有的钱数\n给定起点城市s，给定p个有酒吧的城市，有酒吧的城市才能作为终点\n路线必须从s出发到任意终点停止，重复经过城市的话，钱仅获得一次\n题目保证一定存在这样的路线，打印能获得的最大钱数\n1 <= n、m <= 5 * 10^5\n测试链接 : https://www.luogu.com.cn/problem/P3627\n缩点DAG的动态规划 + 缩点之后增加点的属性 + 限制起点或终点\n\n## 第 5 页：强连通分量和缩点-下\n\n左程云\n题目4\n最优贸易\n一共有n个城市，每个城市给定水晶球的销售价格，给定m条道路\n格式 a b op : op为1代表a到b的单向路，否则表示双向路\n你要从1号城市出发，可以任选道路，最终来到n号城市，沿途可以买卖一次水晶球\n在途中你可以任选一座城市买入，可以立即卖出，或者在之后的任何城市卖出\n如果从1号城市能到达n号城市，打印挣到的最大钱数，如果不能到达打印0\n1 <= n <= 10^5\n1 <= m <= 5 * 10^5\n测试链接 : https://www.luogu.com.cn/problem/P1073\n缩点DAG的动态规划 + 限制起点或终点\n\n## 第 6 页：强连通分量和缩点-下\n\n左程云\n题目5\n最大半连通子图\n有向图中节点u和v，只要其中一点能到达另一点，就说两点是半连通的\n如果一个有向图，任意两点都是半连通的，这样的有向图就是半连通图\n有向图中的一个点集，该点集中只要某两点在原图中有边，那么这条边就保留，则可以得到一个子图\n如果该子图既是半连通图，又有节点数量最多，那么这个子图就是原图的最大半连通子图\n给定一张n个点，m条边的有向图，打印最大半连通子图的大小\n可能存在多个最大半连通子图，打印这个数量，数量对给定的数字x取余\n1 <= n <= 10^5\n1 <= m <= 10^6\n测试链接 : https://www.luogu.com.cn/problem/P2272\n缩点DAG的动态规划 + 关于重边的分析 + 判断重边省空间的写法\n\n## 第 7 页：强连通分量和缩点-下\n\n左程云\n题目6\n缩点最短路\n给定一张n个点，m条边的有向图，每条边有非负边权\n如果两点属同一个强连通分量，认为彼此到达的代价为0\n找到从1号点到n号点的路径，打印最小的边权累加和，如果不能到达打印-1\n1 <= n <= 2 * 10^5\n1 <= m <= 10^6\n测试链接 : https://www.luogu.com.cn/problem/P2169\n缩点DAG + 最短路\n讲解064，dijkstra算法\n\n## 第 8 页：强连通分量和缩点-下\n\n左程云\n题目7\n软件安装\n一共有n个物品，你的背包能容纳的总重量为m\n选择某个物品时，重量消耗为当前物品的w，获得收益为当前物品的v\n给定每个物品最多一件依赖物品，不拿依赖物品无法选择当前物品\n如果一批物品循环依赖，想选的话就只能都选，有的物品不存在依赖物品\n打印你能获得的最大收益\n0 <= n <= 100\n0 <= m <= 500\n测试链接 : https://www.luogu.com.cn/problem/P2515\n缩点DAG + 树上背包\n讲解079，题目5，树上背包的最优解，时间复杂度O(n * m)\n\n## 第 9 页：强连通分量和缩点-下\n\n左程云\n题目8\n糖果\n一共n个人，每人至少得到一个糖果，一共k条要求，要求有5种类型\n1 u v : u的糖果 == v的糖果    2 u v : u的糖果 < v的糖果\n3 u v : u的糖果 >= v的糖果    4 u v : u的糖果 > v的糖果\n5 u v : u的糖果 <= v的糖果\n如果无法满足所有要求打印-1，否则打印需要的最少糖果数\n1 <= n、k <= 10^5\n测试链接 : https://www.luogu.com.cn/problem/P3275\n差分约束建图 + 简单判断 + 缩点DAG的动态规划\n讲解142，差分约束，本题只用了差分约束的建图方式，进行简单的分析而已\n\n## 第 10 页：强连通分量和缩点-下\n\n左程云\n题目9\n杀人游戏\n一共n个人，只有一个杀手，每个人是杀手的概率均等，其他人都是平民\n给定m个知晓关系，如果x知晓y，那么y是不是杀手，x就知道情况了\n知晓关系是单向且可传递的，比如a知晓b，b知晓c，那么a知晓c\n你可以盘问任何人，不仅能知道对方身份，并且对方知晓的所有情况都能获得\n但是如果你直接盘问到杀手的话，杀手会原地爆炸，炸死所有人\n你一定要确定所有人的身份，而且你充分了解知晓关系网，会用最优的盘问策略\n返回最优盘问策略下，杀手不爆炸还能被揪出来的概率，保留小数点后面6位\n1 <= n <= 10^5\n0 <= m <= 3 * 10^5\n测试链接 : https://www.luogu.com.cn/problem/P4819\n研究出度入度的分析题， 缩点DAG + 源头孤立情况的分析 + 判断重边省空间的写法\n\n## 模板代码\n\n### `Code01_CondenseTopo1.java`\n\n```java\npackage class190;\n\n// 缩点结合动态规划模版题，java版\n// 给定一张n个点，m条边的有向图，每个点给定非负点权\n// 如果重复经过一个点，点权只获得一次\n// 找到一条路径，使得点权累加和最大，打印这个值\n// 1 <= n <= 10^4\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3387\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code01_CondenseTopo1 {\n\n\tpublic static int MAXN = 10001;\n\tpublic static int MAXM = 100001;\n\tpublic static int n, m;\n\n\tpublic static int[] arr = new int[MAXN];\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sum = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] indegree = new int[MAXN];\n\tpublic static int[] que = new int[MAXN];\n\tpublic static int[] dp = new int[MAXN];\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsum[sccCnt] += arr[pop];\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 != scc2) {\n\t\t\t\tindegree[scc2]++;\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 拓扑排序的写法\n\tpublic static int topo() {\n\t\tint l = 1, r = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tif (indegree[i] == 0) {\n\t\t\t\tdp[i] = sum[i];\n\t\t\t\tque[++r] = i;\n\t\t\t}\n\t\t}\n\t\twhile (l <= r) {\n\t\t\tint u = que[l++];\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdp[v] = Math.max(dp[v], dp[u] + sum[v]);\n\t\t\t\tif (--indegree[v] == 0) {\n\t\t\t\t\tque[++r] = v;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\tans = Math.max(ans, dp[i]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\t// 直接转移的写法\n\tpublic static int dpOnDAG() {\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tif (indegree[u] == 0) {\n\t\t\t\tdp[u] = sum[u];\n\t\t\t}\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdp[v] = Math.max(dp[v], dp[u] + sum[v]);\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tans = Math.max(ans, dp[u]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tarr[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\ttarjan(i);\n\t\t\t}\n\t\t}\n\t\tcondense();\n\t\t// int ans = topo();\n\t\tint ans = dpOnDAG();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code01_CondenseTopo2.java`\n\n```java\npackage class190;\n\n// 缩点结合动态规划模版题，C++版\n// 给定一张n个点，m条边的有向图，每个点给定非负点权\n// 如果重复经过一个点，点权只获得一次\n// 找到一条路径，使得点权累加和最大，打印这个值\n// 1 <= n <= 10^4\n// 1 <= m <= 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3387\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 10001;\n//const int MAXM = 100001;\n//int n, m;\n//\n//int arr[MAXN];\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sum[MAXN];\n//int sccCnt;\n//\n//int indegree[MAXN];\n//int que[MAXN];\n//int dp[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//            sum[sccCnt] += arr[pop];\n//        } while (pop != u);\n//    }\n//}\n//\n//void condense() {\n//    cntg = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        head[i] = 0;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        int scc1 = belong[a[i]];\n//        int scc2 = belong[b[i]];\n//        if (scc1 != scc2) {\n//            indegree[scc2]++;\n//            addEdge(scc1, scc2);\n//        }\n//    }\n//}\n//\n//int topo() {\n//    int l = 1, r = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        if (indegree[i] == 0) {\n//            dp[i] = sum[i];\n//            que[++r] = i;\n//        }\n//    }\n//    while (l <= r) {\n//        int u = que[l++];\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            dp[v] = max(dp[v], dp[u] + sum[v]);\n//            if (--indegree[v] == 0) {\n//                que[++r] = v;\n//            }\n//        }\n//    }\n//    int ans = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        ans = max(ans, dp[i]);\n//    }\n//    return ans;\n//}\n//\n//int dpOnDAG() {\n//    for (int u = sccCnt; u > 0; u--) {\n//        if (indegree[u] == 0) {\n//            dp[u] = sum[u];\n//        }\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            dp[v] = max(dp[v], dp[u] + sum[v]);\n//        }\n//    }\n//    int ans = 0;\n//    for (int u = 1; u <= sccCnt; u++) {\n//        ans = max(ans, dp[u]);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= n; i++) {\n//        cin >> arr[i];\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//        addEdge(a[i], b[i]);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i);\n//        }\n//    }\n//    condense();\n//    // int ans = topo();\n//    int ans = dpOnDAG();\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code02_PickMushroom1.java`\n\n```java\npackage class190;\n\n// 采蘑菇，java版\n// 给定一张n个点，m条边的有向图，每条边有初始收益、恢复系数两种边权\n// 初始收益为非负整数，恢复系数范围[0, 0.8]，并且最多有一位小数\n// 比如，如果重复走过一条边，该边的初始收益为10，恢复系数为0.6\n// 那么依次获得的收益为，10、6、3、1、0，随后重复经过就没有收益了\n// 给定起点s，找到一条必须从s出发的路径，打印收益累加和的最大值\n// 1 <= n <= 8 * 10^4\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2656\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code02_PickMushroom1 {\n\n\tpublic static int MAXN = 80001;\n\tpublic static int MAXM = 200001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m, s;\n\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\tpublic static int[] init = new int[MAXM];\n\tpublic static int[] recover = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int[] weight = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] sum = new int[MAXN];\n\tpublic static int[] dp = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v, int w) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\tweight[cntg] = w;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 > 0 && scc2 > 0) {\n\t\t\t\tint val = init[i];\n\t\t\t\tint rec = recover[i];\n\t\t\t\tif (scc1 == scc2) {\n\t\t\t\t\twhile (val > 0) {\n\t\t\t\t\t\tsum[scc1] += val;\n\t\t\t\t\t\tval = val * rec / 10;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\taddEdge(scc1, scc2, val);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int dpOnDAG() {\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tdp[u] = -INF;\n\t\t}\n\t\tdp[belong[s]] = sum[belong[s]];\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tint w = weight[e];\n\t\t\t\tdp[v] = Math.max(dp[v], dp[u] + w + sum[v]);\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tans = Math.max(ans, dp[u]);\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\tinit[i] = in.nextInt();\n\t\t\tdouble rec = in.nextDouble();\n\t\t\trecover[i] = (int) (rec * 10);\n\t\t\taddEdge(a[i], b[i], 0);\n\t\t}\n\t\ts = in.nextInt();\n\t\t// tarjan1(s);\n\t\ttarjan2(s);\n\t\tcondense();\n\t\tint ans = dpOnDAG();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\n\t\tdouble nextDouble() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tlong intPart = 0;\n\t\t\twhile (c > ' ' && c != -1 && c != '.') {\n\t\t\t\tintPart = intPart * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tdouble val = (double) intPart;\n\t\t\tif (c == '.') {\n\t\t\t\tc = readByte();\n\t\t\t\tdouble base = 0.1;\n\t\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\t\tval += (c - '0') * base;\n\t\t\t\t\tbase *= 0.1;\n\t\t\t\t\tc = readByte();\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code02_PickMushroom2.java`\n\n```java\npackage class190;\n\n// 采蘑菇，C++版\n// 给定一张n个点，m条边的有向图，每条边有初始收益、恢复系数两种边权\n// 初始收益为非负整数，恢复系数范围[0, 0.8]，并且最多有一位小数\n// 比如，如果重复走过一条边，该边的初始收益为10，恢复系数为0.6\n// 那么依次获得的收益为，10、6、3、1、0，随后重复经过就没有收益了\n// 给定起点s，找到一条必须从s出发的路径，打印收益累加和的最大值\n// 1 <= n <= 8 * 10^4\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P2656\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 80001;\n//const int MAXM = 200001;\n//const int INF = 1000000001;\n//int n, m, s;\n//\n//int a[MAXM];\n//int b[MAXM];\n//int init[MAXM];\n//int recover[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int weight[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sum[MAXN];\n//int sccCnt;\n//\n//int dp[MAXN];\n//\n//void addEdge(int u, int v, int w) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    weight[cntg] = w;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        int popv;\n//        do {\n//            popv = sta[top--];\n//            belong[popv] = sccCnt;\n//        } while (popv != u);\n//    }\n//}\n//\n//void condense() {\n//    cntg = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        head[i] = 0;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        int scc1 = belong[a[i]];\n//        int scc2 = belong[b[i]];\n//        if (scc1 > 0 && scc2 > 0) {\n//            int val = init[i];\n//            int rec = recover[i];\n//            if (scc1 == scc2) {\n//                while (val > 0) {\n//                    sum[scc1] += val;\n//                    val = val * rec / 10;\n//                }\n//            } else {\n//                addEdge(scc1, scc2, val);\n//            }\n//        }\n//    }\n//}\n//\n//int dpOnDAG() {\n//    for (int u = 1; u <= sccCnt; u++) {\n//        dp[u] = -INF;\n//    }\n//    dp[belong[s]] = sum[belong[s]];\n//    for (int u = sccCnt; u > 0; u--) {\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            int w = weight[e];\n//            dp[v] = max(dp[v], dp[u] + w + sum[v]);\n//        }\n//    }\n//    int ans = 0;\n//    for (int u = 1; u <= sccCnt; u++) {\n//        ans = max(ans, dp[u]);\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    double rec;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i] >> init[i];\n//        cin >> rec;\n//        recover[i] = (int)(rec * 10);\n//        addEdge(a[i], b[i], 0);\n//    }\n//    cin >> s;\n//    tarjan(s);\n//    condense();\n//    int ans = dpOnDAG();\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code03_RobberyPlan1.java`\n\n```java\npackage class190;\n\n// 劫掠计划，java版\n// 一共有n个城市，给定m条有向道路，每个城市给定拥有的钱数\n// 给定起点城市s，给定p个有酒吧的城市，有酒吧的城市才能作为终点\n// 路线必须从s出发到任意终点停止，重复经过城市的话，钱仅获得一次\n// 题目保证一定存在这样的路线，打印能获得的最大钱数\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3627\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code03_RobberyPlan1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 500001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m, s, p;\n\n\tpublic static int[] money = new int[MAXN];\n\tpublic static boolean[] isBar = new boolean[MAXN];\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM];\n\tpublic static int[] to = new int[MAXM];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sum = new int[MAXN];\n\tpublic static boolean[] hasBar = new boolean[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] dp = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsum[sccCnt] = 0;\n\t\t\thasBar[sccCnt] = false;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsum[sccCnt] += money[pop];\n\t\t\t\thasBar[sccCnt] |= isBar[pop];\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsum[sccCnt] = 0;\n\t\t\t\t\thasBar[sccCnt] = false;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsum[sccCnt] += money[pop];\n\t\t\t\t\t\thasBar[sccCnt] |= isBar[pop];\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 > 0 && scc2 > 0 && scc1 != scc2) {\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int dpOnDAG() {\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tdp[u] = -INF;\n\t\t}\n\t\tdp[belong[s]] = sum[belong[s]];\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tdp[v] = Math.max(dp[v], dp[u] + sum[v]);\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tif (hasBar[u]) {\n\t\t\t\tans = Math.max(ans, dp[u]);\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tmoney[i] = in.nextInt();\n\t\t}\n\t\ts = in.nextInt();\n\t\tp = in.nextInt();\n\t\tfor (int i = 1, x; i <= p; i++) {\n\t\t\tx = in.nextInt();\n\t\t\tisBar[x] = true;\n\t\t}\n\t\t// tarjan1(s);\n\t\ttarjan2(s);\n\t\tcondense();\n\t\tint ans = dpOnDAG();\n\t\tout.println(ans);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_RobberyPlan2.java`\n\n```java\npackage class190;\n\n// 劫掠计划，C++版\n// 一共有n个城市，给定m条有向道路，每个城市给定拥有的钱数\n// 给定起点城市s，给定p个有酒吧的城市，有酒吧的城市才能作为终点\n// 路线必须从s出发到任意终点停止，重复经过城市的话，钱仅获得一次\n// 题目保证一定存在这样的路线，打印能获得的最大钱数\n// 1 <= n、m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P3627\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXM = 500001;\n//const int INF = 1000000001;\n//int n, m, s, p;\n//\n//int money[MAXN];\n//bool isBar[MAXN];\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM];\n//int to[MAXM];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int sum[MAXN];\n//bool hasBar[MAXN];\n//int sccCnt;\n//\n//int dp[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            if (belong[v] == 0) {\n//                low[u] = min(low[u], dfn[v]);\n//            }\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        sccCnt++;\n//        sum[sccCnt] = 0;\n//        hasBar[sccCnt] = false;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = sccCnt;\n//            sum[sccCnt] += money[pop];\n//            hasBar[sccCnt] |= isBar[pop];\n//        } while (pop != u);\n//    }\n//}\n//\n//void condense() {\n//    cntg = 0;\n//    for (int i = 1; i <= sccCnt; i++) {\n//        head[i] = 0;\n//    }\n//    for (int i = 1; i <= m; i++) {\n//        int scc1 = belong[a[i]];\n//        int scc2 = belong[b[i]];\n//        if (scc1 > 0 && scc2 > 0 && scc1 != scc2) {\n//            addEdge(scc1, scc2);\n//        }\n//    }\n//}\n//\n//int dpOnDAG() {\n//    for (int u = 1; u <= sccCnt; u++) {\n//        dp[u] = -INF;\n//    }\n//    dp[belong[s]] = sum[belong[s]];\n//    for (int u = sccCnt; u > 0; u--) {\n//        for (int e = head[u]; e > 0; e = nxt[e]) {\n//            int v = to[e];\n//            dp[v] = max(dp[v], dp[u] + sum[v]);\n//        }\n//    }\n//    int ans = 0;\n//    for (int u = 1; u <= sccCnt; u++) {\n//        if (hasBar[u]) {\n//            ans = max(ans, dp[u]);\n//        }\n//    }\n//    return ans;\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cin >> n >> m;\n//    for (int i = 1; i <= m; i++) {\n//        cin >> a[i] >> b[i];\n//        addEdge(a[i], b[i]);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        cin >> money[i];\n//    }\n//    cin >> s >> p;\n//    for (int i = 1, x; i <= p; i++) {\n//        cin >> x;\n//        isBar[x] = true;\n//    }\n//    tarjan(s);\n//    condense();\n//    int ans = dpOnDAG();\n//    cout << ans << "\\n";\n//    return 0;\n//}\n```\n\n### `Code04_OptimalTrade1.java`\n\n```java\npackage class190;\n\n// 最优贸易，java版\n// 一共有n个城市，每个城市给定水晶球的销售价格，给定m条道路\n// 格式 a b op : op为1代表a到b的单向路，否则表示双向路\n// 你要从1号城市出发，可以任选道路，最终来到n号城市，沿途可以买卖一次水晶球\n// 在途中你可以任选一座城市买入，可以立即卖出，或者在之后的任何城市卖出\n// 如果从1号城市能到达n号城市，打印挣到的最大钱数，如果不能到达打印0\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1073\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_OptimalTrade1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 500001;\n\tpublic static int INF = 1000000001;\n\tpublic static int n, m;\n\n\tpublic static int[] val = new int[MAXN];\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int[] sccMin = new int[MAXN];\n\tpublic static int[] sccMax = new int[MAXN];\n\tpublic static int sccCnt;\n\n\tpublic static int[] premin = new int[MAXN];\n\tpublic static int[] dp = new int[MAXN];\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][3];\n\tpublic static int u, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = status;\n\t\tstack[stacksize][2] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tstatus = stack[stacksize][1];\n\t\te = stack[stacksize][2];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版，java会爆栈，C++可以通过\n\tpublic static void tarjan1(int u) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tif (belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tsccCnt++;\n\t\t\tsccMin[sccCnt] = INF;\n\t\t\tsccMax[sccCnt] = -INF;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\tsccMin[sccCnt] = Math.min(sccMin[sccCnt], val[pop]);\n\t\t\t\tsccMax[sccCnt] = Math.max(sccMax[sccCnt], val[pop]);\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node) {\n\t\tstacksize = 0;\n\t\tpush(node, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t}\n\t\t\t\tif (status == 1 && belong[v] == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, 0, e);\n\t\t\t\t\tpush(v, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tsccCnt++;\n\t\t\t\t\tsccMin[sccCnt] = INF;\n\t\t\t\t\tsccMax[sccCnt] = -INF;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tbelong[pop] = sccCnt;\n\t\t\t\t\t\tsccMin[sccCnt] = Math.min(sccMin[sccCnt], val[pop]);\n\t\t\t\t\t\tsccMax[sccCnt] = Math.max(sccMax[sccCnt], val[pop]);\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= sccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint scc1 = belong[a[i]];\n\t\t\tint scc2 = belong[b[i]];\n\t\t\tif (scc1 > 0 && scc2 > 0 && scc1 != scc2) {\n\t\t\t\taddEdge(scc1, scc2);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int dpOnDAG() {\n\t\tfor (int u = 1; u <= sccCnt; u++) {\n\t\t\tpremin[u] = INF;\n\t\t\tdp[u] = -INF;\n\t\t}\n\t\tint s = belong[1];\n\t\tpremin[s] = sccMin[s];\n\t\tdp[s] = sccMax[s] - sccMin[s];\n\t\tfor (int u = sccCnt; u > 0; u--) {\n\t\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\t\tint v = to[e];\n\t\t\t\tpremin[v] = Math.min(premin[v], Math.min(premin[u], sccMin[v]));\n\t\t\t\tdp[v] = Math.max(dp[v], Math.max(dp[u], sccMax[v] - premin[v]));\n\t\t\t}\n\t\t}\n\t\treturn dp[belong[n]];\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tval[i] = in.nextInt();\n\t\t}\n\t\tfor (int i = 1, op; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\top = in.nextInt();\n\t\t\tif (op == 1) {\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t} else {\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t\taddEdge(b[i], a[i]);\n\t\t\t}\n\t\t}\n\t\t// tarjan1(1);\n\t\ttarjan2(1);\n\t\tif (belong[n] == 0) {\n\t\t\tout.println(0);\n\t\t} else {\n\t\t\tcondense();\n\t\t\tint ans = dpOnDAG();\n\t\t\tout.println(ans);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_OptimalTrade2.java`\n\n```java\npackage class190;\n\n// 最优贸易，C++版\n// 一共有n个城市，每个城市给定水晶球的销售价格，给定m条道路\n// 格式 a b op : op为1代表a到b的单向路，否则表示双向路\n// 你要从1号城市出发，可以任选道路，最终来到n号城市，沿途可以买卖一次水晶球\n// 在途中你可以任选一座城市买入，可以立即卖出，或者在之后的任何城市卖出\n// 如果从1号城市能到达n号城市，打印挣到的最大钱数，如果不能到达打印0\n// 1 <= n <= 10^5\n// 1 <= m <= 5 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/P1073\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 500001;\n//const int INF = 1000000001;\