ublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] ans1 = new int[MAXN];\n\tpublic static int[] ans2 = new int[MAXN];\n\tpublic static int cnta;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[] stau = new int[MAXN];\n\tpublic static int[] stap = new int[MAXN];\n\tpublic static int[] stas = new int[MAXN];\n\tpublic static int[] stae = new int[MAXN];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stasiz;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstau[stasiz] = u;\n\t\tstap[stasiz] = preEdge;\n\t\tstas[stasiz] = status;\n\t\tstae[stasiz] = e;\n\t\tstasiz++;\n\t}\n\n\tpublic static void pop() {\n\t\tstasiz--;\n\t\tu = stau[stasiz];\n\t\tpreEdge = stap[stasiz];\n\t\tstatus = stas[stasiz];\n\t\te = stae[stasiz];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\tif (acnt[v] == 0 || acnt[v] == k || bcnt[v] == 0 || bcnt[v] == l) {\n\t\t\t\t\t\tcnta++;\n\t\t\t\t\t\tans1[cnta] = v;\n\t\t\t\t\t\tans2[cnta] = u;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tacnt[u] += acnt[v];\n\t\t\t\tbcnt[u] += bcnt[v];\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstasiz = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stasiz > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\t\tif (acnt[v] == 0 || acnt[v] == k || bcnt[v] == 0 || bcnt[v] == l) {\n\t\t\t\t\t\t\tcnta++;\n\t\t\t\t\t\t\tans1[cnta] = v;\n\t\t\t\t\t\t\tans2[cnta] = u;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tacnt[u] += acnt[v];\n\t\t\t\t\tbcnt[u] += bcnt[v];\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tk = in.nextInt();\n\t\tl = in.nextInt();\n\t\tfor (int i = 1, x; i <= k; i++) {\n\t\t\tx = in.nextInt();\n\t\t\tacnt[x] = 1;\n\t\t}\n\t\tfor (int i = 1, x; i <= l; i++) {\n\t\t\tx = in.nextInt();\n\t\t\tbcnt[x] = 1;\n\t\t}\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\t// tarjan1(1, 0);\n\t\ttarjan2(1, 0);\n\t\tout.println(cnta);\n\t\tfor (int i = 1; i <= cnta; i++) {\n\t\t\tout.println(ans1[i] + " " + ans2[i]);\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code03_CriticalNetworkLines2.java`\n\n```java\npackage class191;\n\n// 关键网络线路，C++版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 给定k个提供A服务的节点，给定l个提供B服务的节点，保证k和l都是正数\n// 一个节点可能不提供服务，也可能提供A服务或者B服务或者两种都有\n// 每个节点可以通过边，获得任何节点提供的服务，但是必须同时获得两种服务\n// 如果断开某一条边，使得某些节点无法同时获得两种服务，这样的边叫关键边\n// 打印关键边的数量，打印每条关键边的两个端点\n// 1 <= n <= 10^5\n// 1 <= m <= 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P7687\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 1000001;\n//int n, m, k, l;\n//int acnt[MAXN];\n//int bcnt[MAXN];\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int ans1[MAXN];\n//int ans2[MAXN];\n//int cnta;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] > dfn[u]) {\n//                if (acnt[v] == 0 || acnt[v] == k || bcnt[v] == 0 || bcnt[v] == l) {\n//                    cnta++;\n//                    ans1[cnta] = v;\n//                    ans2[cnta] = u;\n//                }\n//            }\n//            acnt[u] += acnt[v];\n//            bcnt[u] += bcnt[v];\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cntg = 1;\n//    cin >> n >> m >> k >> l;\n//    for (int i = 1, x; i <= k; i++) {\n//        cin >> x;\n//        acnt[x] = 1;\n//    }\n//    for (int i = 1, x; i <= l; i++) {\n//        cin >> x;\n//        bcnt[x] = 1;\n//    }\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    tarjan(1, 0);\n//    cout << cnta << "\\n";\n//    for (int i = 1; i <= cnta; i++) {\n//        cout << ans1[i] << " " << ans2[i] << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code04_BertownRoads1.java`\n\n```java\npackage class191;\n\n// 贝尔敦道路，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 每条无向边需要指定一个方向，变成有向边，还要保证任意两点互相可达\n// 如果不存在方案打印0，如果存在方案，打印m条有向边\n// 可以任意次序打印有向边，如果方案不只一种，打印其中一种即可\n// 1 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF118E\n// 测试链接 : https://codeforces.com/problemset/problem/118/E\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code04_BertownRoads1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 300001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static boolean check;\n\tpublic static int[] ans1 = new int[MAXM];\n\tpublic static int[] ans2 = new int[MAXM];\n\tpublic static int cnta;\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\t// 树边和回边需要处理，弃边不要处理\n\t\t\tif (dfn[v] == 0 || dfn[v] < dfn[u]) {\n\t\t\t\tcnta++;\n\t\t\t\tans1[cnta] = u;\n\t\t\t\tans2[cnta] = v;\n\t\t\t}\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\tif (low[v] > dfn[u]) {\n\t\t\t\t\tcheck = false;\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tcheck = true;\n\t\ttarjan(1, 0);\n\t\tif (!check) {\n\t\t\tout.println(0);\n\t\t} else {\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\tout.println(ans1[i] + " " + ans2[i]);\n\t\t\t}\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code04_BertownRoads2.java`\n\n```java\npackage class191;\n\n// 贝尔敦道路，C++版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 每条无向边需要指定一个方向，变成有向边，还要保证任意两点互相可达\n// 如果不存在方案打印0，如果存在方案，打印m条有向边\n// 可以任意次序打印有向边，如果方案不只一种，打印其中一种即可\n// 1 <= n <= 10^5\n// 1 <= m <= 3 * 10^5\n// 测试链接 : https://www.luogu.com.cn/problem/CF118E\n// 测试链接 : https://codeforces.com/problemset/problem/118/E\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 300001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//bool check;\n//int ans1[MAXM];\n//int ans2[MAXM];\n//int cnta;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0 || dfn[v] < dfn[u]) {\n//            cnta++;\n//            ans1[cnta] = u;\n//            ans2[cnta] = v;\n//        }\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//            if (low[v] > dfn[u]) {\n//                check = false;\n//            }\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cntg = 1;\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    check = true;\n//    tarjan(1, 0);\n//    if (!check) {\n//        cout << 0 << "\\n";\n//    } else {\n//        for (int i = 1; i <= m; i++) {\n//            cout << ans1[i] << " " << ans2[i] << "\\n";\n//        }\n//    }\n//    return 0;\n//}\n```\n\n### `Code05_EBCC1.java`\n\n```java\npackage class191;\n\n// 边双连通分量模版题，java版\n// 给定一张无向图，一共n个点、m条边\n// 图中可能存在多个连通区，对每个连通区求边双连通分量\n// 先打印边双连通分量的总数量，然后对每个边双连通分量\n// 打印节点个数，然后任意顺序打印该边双连通分量的节点\n// 请保证原图即使有重边和自环，答案依然正确\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8436\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code05_EBCC1 {\n\n\tpublic static int MAXN = 500001;\n\tpublic static int MAXM = 2000001;\n\tpublic static int n, m;\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] ebccSiz = new int[MAXN];\n\tpublic static int[] ebccArr = new int[MAXN];\n\tpublic static int[] ebccl = new int[MAXN];\n\tpublic static int[] ebccr = new int[MAXN];\n\tpublic static int idx;\n\tpublic static int ebccCnt;\n\n\t// 迭代版需要的栈，讲解118讲了递归改迭代的技巧\n\tpublic static int[][] stack = new int[MAXN][4];\n\tpublic static int u, preEdge, status, e;\n\tpublic static int stacksize;\n\n\tpublic static void push(int u, int preEdge, int status, int e) {\n\t\tstack[stacksize][0] = u;\n\t\tstack[stacksize][1] = preEdge;\n\t\tstack[stacksize][2] = status;\n\t\tstack[stacksize][3] = e;\n\t\tstacksize++;\n\t}\n\n\tpublic static void pop() {\n\t\tstacksize--;\n\t\tu = stack[stacksize][0];\n\t\tpreEdge = stack[stacksize][1];\n\t\tstatus = stack[stacksize][2];\n\t\te = stack[stacksize][3];\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\t// 递归版\n\tpublic static void tarjan1(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan1(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\tebccl[ebccCnt] = idx + 1;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t\tebccArr[++idx] = pop;\n\t\t\t} while (pop != u);\n\t\t\tebccr[ebccCnt] = idx;\n\t\t}\n\t}\n\n\t// 迭代版\n\tpublic static void tarjan2(int node, int pree) {\n\t\tstacksize = 0;\n\t\tpush(node, pree, -1, -1);\n\t\tint v;\n\t\twhile (stacksize > 0) {\n\t\t\tpop();\n\t\t\tif (status == -1) {\n\t\t\t\tdfn[u] = low[u] = ++cntd;\n\t\t\t\tsta[++top] = u;\n\t\t\t\te = head[u];\n\t\t\t} else {\n\t\t\t\tv = to[e];\n\t\t\t\tif (status == 0) {\n\t\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t\t} else {\n\t\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t\t}\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\te = nxt[e];\n\t\t\t}\n\t\t\tif (e != 0) {\n\t\t\t\tv = to[e];\n\t\t\t\tif (dfn[v] == 0) {\n\t\t\t\t\tpush(u, preEdge, 0, e);\n\t\t\t\t\tpush(v, e, -1, -1);\n\t\t\t\t} else {\n\t\t\t\t\tpush(u, preEdge, 1, e);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (dfn[u] == low[u]) {\n\t\t\t\t\tebccCnt++;\n\t\t\t\t\tebccSiz[ebccCnt] = 0;\n\t\t\t\t\tebccl[ebccCnt] = idx + 1;\n\t\t\t\t\tint pop;\n\t\t\t\t\tdo {\n\t\t\t\t\t\tpop = sta[top--];\n\t\t\t\t\t\tebccSiz[ebccCnt]++;\n\t\t\t\t\t\tebccArr[++idx] = pop;\n\t\t\t\t\t} while (pop != u);\n\t\t\t\t\tebccr[ebccCnt] = idx;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1, u, v; i <= m; i++) {\n\t\t\tu = in.nextInt();\n\t\t\tv = in.nextInt();\n\t\t\taddEdge(u, v);\n\t\t\taddEdge(v, u);\n\t\t}\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tif (dfn[i] == 0) {\n\t\t\t\t// tarjan1(i, 0);\n\t\t\t\ttarjan2(i, 0);\n\t\t\t}\n\t\t}\n\t\tout.println(ebccCnt);\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\tout.println(ebccSiz[i]);\n\t\t\tfor (int j = ebccl[i]; j <= ebccr[i]; j++) {\n\t\t\t\tout.print(ebccArr[j] + " ");\n\t\t\t}\n\t\t\tout.println();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code05_EBCC2.java`\n\n```java\npackage class191;\n\n// 边双连通分量模版题，C++版\n// 给定一张无向图，一共n个点、m条边\n// 图中可能存在多个连通区，对每个连通区求边双连通分量\n// 先打印边双连通分量的总数量，然后对每个边双连通分量\n// 打印节点个数，然后任意顺序打印该边双连通分量的节点\n// 请保证原图即使有重边和自环，答案依然正确\n// 1 <= n <= 5 * 10^5\n// 1 <= m <= 2 * 10^6\n// 测试链接 : https://www.luogu.com.cn/problem/P8436\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 500001;\n//const int MAXM = 2000001;\n//int n, m;\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int ebccSiz[MAXN];\n//int ebccArr[MAXN];\n//int ebccl[MAXN];\n//int ebccr[MAXN];\n//int idx;\n//int ebccCnt;\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        ebccCnt++;\n//        ebccSiz[ebccCnt] = 0;\n//        ebccl[ebccCnt] = idx + 1;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            ebccSiz[ebccCnt]++;\n//            ebccArr[++idx] = pop;\n//        } while (pop != u);\n//        ebccr[ebccCnt] = idx;\n//    }\n//}\n//\n//int main() {\n//    ios::sync_with_stdio(false);\n//    cin.tie(nullptr);\n//    cntg = 1;\n//    cin >> n >> m;\n//    for (int i = 1, u, v; i <= m; i++) {\n//        cin >> u >> v;\n//        addEdge(u, v);\n//        addEdge(v, u);\n//    }\n//    for (int i = 1; i <= n; i++) {\n//        if (dfn[i] == 0) {\n//            tarjan(i, 0);\n//        }\n//    }\n//    cout << ebccCnt << "\\n";\n//    for (int i = 1; i <= ebccCnt; i++) {\n//        cout << ebccSiz[i] << "\\n";\n//        for (int j = ebccl[i]; j <= ebccr[i]; j++) {\n//            cout << ebccArr[j] << " ";\n//        }\n//        cout << "\\n";\n//    }\n//    return 0;\n//}\n```\n\n### `Code06_Network1.java`\n\n```java\npackage class191;\n\n// 网络，java版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 一共q条操作，格式 x y : 点x和点y之间新增一条边，打印此时割边的数量\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=2460\n// 测试链接 : http://poj.org/problem?id=3694\n// 提交以下的code，提交时请把类名改成"Main"，可以通过所有测试用例\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStreamWriter;\nimport java.io.PrintWriter;\n\npublic class Code06_Network1 {\n\n\tpublic static int MAXN = 100001;\n\tpublic static int MAXM = 200001;\n\tpublic static int t, n, m, q;\n\tpublic static int[] a = new int[MAXM];\n\tpublic static int[] b = new int[MAXM];\n\n\tpublic static int[] head = new int[MAXN];\n\tpublic static int[] nxt = new int[MAXM << 1];\n\tpublic static int[] to = new int[MAXM << 1];\n\tpublic static int cntg;\n\n\tpublic static int[] dfn = new int[MAXN];\n\tpublic static int[] low = new int[MAXN];\n\tpublic static int cntd;\n\n\tpublic static int[] sta = new int[MAXN];\n\tpublic static int top;\n\n\tpublic static int[] belong = new int[MAXN];\n\tpublic static int ebccCnt;\n\n\tpublic static int[] up = new int[MAXN];\n\tpublic static int[] dep = new int[MAXN];\n\tpublic static int[] fa = new int[MAXN];\n\n\tpublic static void prepare() {\n\t\tcntg = 1;\n\t\tcntd = top = ebccCnt = 0;\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\thead[i] = dfn[i] = low[i] = 0;\n\t\t}\n\t}\n\n\tpublic static void addEdge(int u, int v) {\n\t\tnxt[++cntg] = head[u];\n\t\tto[cntg] = v;\n\t\thead[u] = cntg;\n\t}\n\n\tpublic static void tarjan(int u, int preEdge) {\n\t\tdfn[u] = low[u] = ++cntd;\n\t\tsta[++top] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static void condense() {\n\t\tcntg = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\thead[i] = 0;\n\t\t}\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\taddEdge(ebcc1, ebcc2);\n\t\t\t\taddEdge(ebcc2, ebcc1);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void dfs(int u, int f) {\n\t\tdep[u] = dep[f] + 1;\n\t\tup[u] = f;\n\t\tfa[u] = u;\n\t\tfor (int e = head[u]; e > 0; e = nxt[e]) {\n\t\t\tint v = to[e];\n\t\t\tif (v != f) {\n\t\t\t\tdfs(v, u);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static int find(int i) {\n\t\tif (i != fa[i]) {\n\t\t\tfa[i] = find(fa[i]);\n\t\t}\n\t\treturn fa[i];\n\t}\n\n\tpublic static void union(int x, int y) {\n\t\tx = find(x);\n\t\ty = find(y);\n\t\tif (x != y) {\n\t\t\tif (dep[x] < dep[y]) {\n\t\t\t\tfa[y] = x;\n\t\t\t} else {\n\t\t\t\tfa[x] = y;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic static void link(int x, int y) {\n\t\tx = find(belong[x]);\n\t\ty = find(belong[y]);\n\t\twhile (x != y) {\n\t\t\tif (dep[x] >= dep[y]) {\n\t\t\t\tunion(x, up[x]);\n\t\t\t\tx = find(x);\n\t\t\t} else {\n\t\t\t\tunion(y, up[y]);\n\t\t\t\ty = find(y);\n\t\t\t}\n\t\t\tebccCnt--;\n\t\t}\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tt = 0;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\twhile (n != 0 || m != 0) {\n\t\t\tprepare();\n\t\t\tfor (int i = 1; i <= m; i++) {\n\t\t\t\ta[i] = in.nextInt();\n\t\t\t\tb[i] = in.nextInt();\n\t\t\t\taddEdge(a[i], b[i]);\n\t\t\t\taddEdge(b[i], a[i]);\n\t\t\t}\n\t\t\ttarjan(1, 0);\n\t\t\tcondense();\n\t\t\tdfs(1, 0);\n\t\t\tout.println("Case " + (++t) + ":");\n\t\t\tq = in.nextInt();\n\t\t\tfor (int i = 1, x, y; i <= q; i++) {\n\t\t\t\tx = in.nextInt();\n\t\t\t\ty = in.nextInt();\n\t\t\t\tlink(x, y);\n\t\t\t\tout.println(ebccCnt - 1);\n\t\t\t}\n\t\t\tout.println();\n\t\t\tn = in.nextInt();\n\t\t\tm = in.nextInt();\n\t\t}\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code06_Network2.java`\n\n```java\npackage class191;\n\n// 网络，C++版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 一共q条操作，格式 x y : 点x和点y之间新增一条边，打印此时割边的数量\n// 1 <= n <= 10^5\n// 1 <= m <= 2 * 10^5\n// 测试链接 : https://acm.hdu.edu.cn/showproblem.php?pid=2460\n// 测试链接 : http://poj.org/problem?id=3694\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <iostream>\n//#include <algorithm>\n//\n//using namespace std;\n//\n//const int MAXN = 100001;\n//const int MAXM = 200001;\n//int t, n, m, q;\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int ebccCnt;\n//\n//int up[MAXN];\n//int dep[MAXN];\n//int fa[MAXN];\n//\n//void prepare() {\n//    cntg = 1;\n//    cntd = top = ebccCnt = 0;\n//    for (int i = 1; i <= n; i++) {\n//        head[i] = dfn[i] = low[i] = 0;\n//    }\n//}\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//  