n\t\t\tif ((e ^ 1) == preEdge) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint v = to[e];\n\t\t\tif (dfn[v] == 0) {\n\t\t\t\ttarjan(v, e);\n\t\t\t\tlow[u] = Math.min(low[u], low[v]);\n\t\t\t} else {\n\t\t\t\tlow[u] = Math.min(low[u], dfn[v]);\n\t\t\t}\n\t\t}\n\t\tif (dfn[u] == low[u]) {\n\t\t\tebccCnt++;\n\t\t\tint pop;\n\t\t\tdo {\n\t\t\t\tpop = sta[top--];\n\t\t\t\tbelong[pop] = ebccCnt;\n\t\t\t} while (pop != u);\n\t\t}\n\t}\n\n\tpublic static int getLeaf() {\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\tint ebcc1 = belong[a[i]];\n\t\t\tint ebcc2 = belong[b[i]];\n\t\t\tif (ebcc1 != ebcc2) {\n\t\t\t\tdegree[ebcc1]++;\n\t\t\t\tdegree[ebcc2]++;\n\t\t\t}\n\t\t}\n\t\tint ans = 0;\n\t\tfor (int i = 1; i <= ebccCnt; i++) {\n\t\t\tif (degree[i] == 1) {\n\t\t\t\tans++;\n\t\t\t}\n\t\t}\n\t\treturn ans;\n\t}\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tFastReader in = new FastReader(System.in);\n\t\tPrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));\n\t\tcntg = 1;\n\t\tn = in.nextInt();\n\t\tm = in.nextInt();\n\t\tfor (int i = 1; i <= m; i++) {\n\t\t\ta[i] = in.nextInt();\n\t\t\tb[i] = in.nextInt();\n\t\t\taddEdge(a[i], b[i]);\n\t\t\taddEdge(b[i], a[i]);\n\t\t}\n\t\ttarjan(1, 0);\n\t\tint leafCnt = getLeaf();\n\t\tout.println((leafCnt + 1) / 2);\n\t\tout.flush();\n\t\tout.close();\n\t}\n\n\t// 读写工具类\n\tstatic class FastReader {\n\t\tprivate final byte[] buffer = new byte[1 << 16];\n\t\tprivate int ptr = 0, len = 0;\n\t\tprivate final InputStream in;\n\n\t\tFastReader(InputStream in) {\n\t\t\tthis.in = in;\n\t\t}\n\n\t\tprivate int readByte() throws IOException {\n\t\t\tif (ptr >= len) {\n\t\t\t\tlen = in.read(buffer);\n\t\t\t\tptr = 0;\n\t\t\t\tif (len <= 0)\n\t\t\t\t\treturn -1;\n\t\t\t}\n\t\t\treturn buffer[ptr++];\n\t\t}\n\n\t\tint nextInt() throws IOException {\n\t\t\tint c;\n\t\t\tdo {\n\t\t\t\tc = readByte();\n\t\t\t} while (c <= ' ' && c != -1);\n\t\t\tboolean neg = false;\n\t\t\tif (c == '-') {\n\t\t\t\tneg = true;\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\tint val = 0;\n\t\t\twhile (c > ' ' && c != -1) {\n\t\t\t\tval = val * 10 + (c - '0');\n\t\t\t\tc = readByte();\n\t\t\t}\n\t\t\treturn neg ? -val : val;\n\t\t}\n\t}\n\n}\n\n```\n\n### `Code07_RedundantPaths2.java`\n\n```java\npackage class191;\n\n// 冗余路径，C++版\n// 给定一张无向图，一共n个点、m条边，保证所有点连通\n// 打印至少添加几条边可以让整张图变成一个边双连通分量\n// 1 <= n <= 5000\n// 1 <= m <= 10000\n// 测试链接 : https://www.luogu.com.cn/problem/P2860\n// 如下实现是C++的版本，C++版本和java版本逻辑完全一样\n// 提交如下代码，可以通过所有测试用例\n\n//#include <bits/stdc++.h>\n//\n//using namespace std;\n//\n//const int MAXN = 5001;\n//const int MAXM = 10001;\n//int n, m;\n//int a[MAXM];\n//int b[MAXM];\n//\n//int head[MAXN];\n//int nxt[MAXM << 1];\n//int to[MAXM << 1];\n//int cntg;\n//\n//int dfn[MAXN];\n//int low[MAXN];\n//int cntd;\n//\n//int sta[MAXN];\n//int top;\n//\n//int belong[MAXN];\n//int ebccCnt;\n//\n//int degree[MAXN];\n//\n//void addEdge(int u, int v) {\n//    nxt[++cntg] = head[u];\n//    to[cntg] = v;\n//    head[u] = cntg;\n//}\n//\n//void tarjan(int u, int preEdge) {\n//    dfn[u] = low[u] = ++cntd;\n//    sta[++top] = u;\n//    for (int e = head[u]; e > 0; e = nxt[e]) {\n//        if ((e ^ 1) == preEdge) {\n//            continue;\n//        }\n//        int v = to[e];\n//        if (dfn[v] == 0) {\n//            tarjan(v, e);\n//            low[u] = min(low[u], low[v]);\n//        } else {\n//            low[u] = min(low[u], dfn[v]);\n//        }\n//    }\n//    if (dfn[u] == low[u]) {\n//        ebccCnt++;\n//        int pop;\n//        do {\n//            pop = sta[top--];\n//            belong[pop] = ebccCnt;\n//        } while (pop != u);\n//    }\n//}\n//\n//int getLeaf() {\n//    for (int i = 1; i <= m; i++) {\n//        int ebcc1 = belong[a[i]];\n//        int ebcc2 = belong[b[i]];\n//        if (ebcc1 != ebcc2) {\n//            degree[ebcc1]++;\n//            degree[ebcc2]++;\n//        }\n//    }\n//    int ans = 0;\n//    for (int i = 1; i <= ebccCnt; i++) {\n//        if (degree[i] == 1) {\n//     